    def run_command(cmd,cwd):
        if run_proc[0] and run_proc[0].poll() is None:messagebox.showinfo("Already running","Stop the active process first.",parent=root);return
        out("\n> "+subprocess.list2cmdline([str(x) for x in cmd])+"\n");status.set("Running…")
