def _arena_restore_worker_stream(name,fd):
    """Restore redirected stdout/stderr inside a windowed PyInstaller child."""
    if getattr(sys,name,None) is not None:return
    try:setattr(sys,name,open(fd,"w",encoding="utf-8",errors="replace",buffering=1,closefd=False))
    except Exception:
        try:setattr(sys,name,open(os.devnull,"w",encoding="utf-8"))
        except Exception:pass


if _ARENA_REC_WORKER_BOOT:
    # The recorder/compiler is embedded as a Python module in box_game.exe.
    # Re-launching this same EXE with the private marker gives both the recorder
    # GUI and APU CLI compiler without shipping a second Python interpreter or
    # requiring an external rec.py/rec.exe.
    try:
        _rec_marker=sys.argv.index("--arena-rec-worker")
        sys.argv=[sys.argv[0]]+sys.argv[_rec_marker+1:]
        os.environ.setdefault("BOX_GAME_DIR",_ARENA_INSTALL_DIR)
        os.environ.setdefault("BOX_GAME_RECORDINGS",os.path.join(_ARENA_INSTALL_DIR,"recordings"))
        _arena_restore_worker_stream("stdout",1);_arena_restore_worker_stream("stderr",2)
        import rec as _arena_bundled_recorder
        _rec_real_args=[arg for arg in sys.argv[1:] if str(arg).strip()]
        if _rec_real_args:_arena_bundled_recorder.main_cli()
        else:_arena_bundled_recorder.main_gui()
        raise SystemExit(0)
    except SystemExit:
        raise
    except Exception:
        _early_boot_crash_report(*sys.exc_info())
        raise SystemExit(1)

