def _ns_ease(t, kind="linear"):
    """Shared 0->1 easing curve evaluator used by the engine's own flex_alter
    and weapon motion (swing/jab/etc) interpolation. Kept in sync with the
    identical copy inside NS_RUNTIME_HELPERS, which is what generated
    character scripts get - this one is for the engine's own runtime code."""
    x = max(0.0, min(1.0, float(t)))
    k = str(kind)
    _cv = _curve_eval_named(x, k)
    if _cv is not None:
        return _cv
    if k == "linear":        return x
    if k == "ease_in":       return x * x
    if k == "ease_out":      return x * (2 - x)
    if k == "ease_in_out":   return (2 * x * x if x < .5 else -1 + (4 - 2 * x) * x)
    if k == "smoothstep":    return x * x * (3 - 2 * x)
    if k == "smootherstep":  return x * x * x * (x * (x * 6 - 15) + 10)
    if k == "bounce":        return 1 - abs(math.cos(x * math.pi * 3)) * (1 - x)
    if k == "expo_in":       return 0.0 if x <= 0 else 2 ** (10 * (x - 1))
    if k == "expo_out":      return 1.0 if x >= 1 else 1 - 2 ** (-10 * x)
    if k == "expo_in_out":
        if x <= 0: return 0.0
        if x >= 1: return 1.0
        if x < 0.5: return (2 ** (20 * x - 10)) / 2
        return (2 - 2 ** (-20 * x + 10)) / 2
    return x

def _weapon_ease(t, kind="smoothstep"):
    """Curve evaluator for weapon swing/jab/thrust motion that understands
    BOTH the engine's short-hand names (smoothstep, ease_out, ...) AND the
    exact curve vocabulary used by the Ease / Interpolate math nodes
    (sine_inout, back_out, elastic_out, bounce_out, quad_in, ...), so a
    curve name typed/wired into a weapon's Easing pin behaves the same
    as picking it in the Interpolate node's Curve dropdown."""
    u = max(0.0, min(1.0, float(t)))
    k = str(kind)
    _cv = _curve_eval_named(u, k)
    if _cv is not None:
        return _cv
    if k in ("linear","quad_in","quad_out","quad_inout","cubic_in","cubic_out","cubic_inout",
             "quart_in","quart_out","quart_inout","quint_in","quint_out","quint_inout",
             "sine_in","sine_out","sine_inout","expo_in","expo_out","expo_inout",
             "circ_in","circ_out","circ_inout","back_in","back_out","back_inout",
             "elastic_in","elastic_out","elastic_inout","bounce_in","bounce_out",
             "bounce_inout","discrete"):
        _t = u
        def _bnc(v):
            if v < 1/2.75: return 7.5625*v*v
            if v < 2/2.75: return 7.5625*(v-1.5/2.75)**2+.75
            if v < 2.5/2.75: return 7.5625*(v-2.25/2.75)**2+.9375
            return 7.5625*(v-2.625/2.75)**2+.984375
        if k=="linear": return _t
        if k=="quad_in": return _t*_t
        if k=="quad_out": return _t*(2-_t)
        if k=="quad_inout": return 2*_t*_t if _t<.5 else -1+(4-2*_t)*_t
        if k=="cubic_in": return _t*_t*_t
        if k=="cubic_out": return (_t-1)**3+1
        if k=="cubic_inout": return 4*_t**3 if _t<.5 else (_t-1)*(2*_t-2)**2+1
        if k=="quart_in": return _t**4
        if k=="quart_out": return 1-(_t-1)**4
        if k=="quart_inout": return 8*_t**4 if _t<.5 else 1-8*(_t-1)**4
        if k=="quint_in": return _t**5
        if k=="quint_out": return 1-(_t-1)**5
        if k=="quint_inout": return 16*_t**5 if _t<.5 else 1+16*(_t-1)**5
        if k=="sine_in": return 1-math.cos(_t*math.pi/2)
        if k=="sine_out": return math.sin(_t*math.pi/2)
        if k=="sine_inout": return -(math.cos(math.pi*_t)-1)/2
        if k=="expo_in": return 0.0 if _t==0 else 2**(10*_t-10)
        if k=="expo_out": return 1.0 if _t==1 else 1-2**(-10*_t)
        if k=="expo_inout":
            if _t==0: return 0.0
            if _t==1: return 1.0
            return (2**(20*_t-10)/2) if _t<.5 else (2-2**(10-20*_t))/2
        if k=="circ_in": return 1-math.sqrt(max(0.0,1-_t*_t))
        if k=="circ_out": return math.sqrt(max(0.0,1-((_t-1)**2)))
        if k=="circ_inout":
            return (1-math.sqrt(max(0.0,1-4*_t*_t)))/2 if _t<.5 else (math.sqrt(max(0.0,1-(2*_t-2)**2))+1)/2
        if k=="back_in": return 2.70158*_t**3-1.70158*_t*_t
        if k=="back_out": return 1+2.70158*(_t-1)**3+1.70158*(_t-1)**2
        if k=="back_inout":
            return ((_t*2)**2*(3.59491*(_t*2)-2.59491)/2 if _t<.5
                    else ((_t*2-2)**2*(3.59491*(_t*2-2)+2.59491)+2)/2)
        if k=="elastic_in":
            return 0 if _t==0 else 1 if _t==1 else -(2**(10*_t-10))*math.sin((_t*10-10.75)*(2*math.pi)/3)
        if k=="elastic_out":
            return 0 if _t==0 else 1 if _t==1 else 2**(-10*_t)*math.sin((_t*10-.75)*(2*math.pi)/3)+1
        if k=="elastic_inout":
            if _t==0: return 0.0
            if _t==1: return 1.0
            return ((-(2**(20*_t-10)*math.sin((20*_t-11.125)*(2*math.pi)/4.5))/2) if _t<.5
                    else (2**(-20*_t+10)*math.sin((20*_t-11.125)*(2*math.pi)/4.5))/2+1)
        if k=="bounce_in": return 1-_bnc(1-_t)
        if k=="bounce_out": return _bnc(_t)
        if k=="bounce_inout":
            return (1-_bnc(1-2*_t))/2 if _t<.5 else (1+_bnc(2*_t-1))/2
        if k=="discrete": return float(int(_t*10)/10)
    # fall back to the engine's original short-hand names
    return _ns_ease(u, k)
# ============================================================
# CUSTOM EASING CURVES  (drag-your-own curve editor -- press F8)
# A custom curve is a sorted list of [t, v] points you shape by hand.
# Any engine easing slot (Jab/Thrust/Swing Easing pin, flex easing, ...)
# accepts "curve:<name>" (or just <name>) to use one of these. They are
# saved to easing_curves.json next to this file.
# ============================================================
CUSTOM_EASE_CURVES = {}
CUSTOM_EASE_LOADED = False
# Bumps on every load/save so cached views (dropdown option lists, name lookup
# memos) rebuild ONLY when the curve set actually changes - never per frame.
CUSTOM_EASE_VERSION = 0
_EASING_CURVES_PATH = None

def _easing_curves_path():
    global _EASING_CURVES_PATH
    if _EASING_CURVES_PATH is None:
        try:
            _EASING_CURVES_PATH = _cfg_path("animations", "easing_curves.json")
        except Exception:
            _EASING_CURVES_PATH = "easing_curves.json"
    return _EASING_CURVES_PATH

def _curve_normalize(points_or_entry):
    """Normalize a curve into {"points": [[t, v], ...], "mode": shape}.
    Accepts the old v1 format (a bare point list) too. mode: smooth|linear|step."""
    if isinstance(points_or_entry, dict):
        mode = str(points_or_entry.get("mode", "smooth"))
        raw = points_or_entry.get("points", [])
    else:
        mode = "smooth"
        raw = points_or_entry
    pts = []
    for p in raw or []:
        try:
            t = max(0.0, min(1.0, float(p[0])))
            v = max(-0.5, min(1.75, float(p[1])))
            pts.append([t, v])
        except Exception:
            pass
    pts.sort(key=lambda p: p[0])
    if len(pts) < 2:
        pts = [[0.0, 0.0], [1.0, 1.0]]
    pts[0][0] = 0.0
    pts[-1][0] = 1.0
    if mode not in ("smooth", "linear", "step"):
        mode = "smooth"
    out = {"points": pts, "mode": mode}
    # user-assignable timeline icon (Round 13): riding along on the curve so a
    # motion-clip key using this easing can swap its diamond for the icon.
    try:
        if isinstance(points_or_entry, dict):
            _icn = str(points_or_entry.get("icon", "") or "").strip()[:48]
            if _icn:
                out["icon"] = _icn
    except Exception:
        pass
    # user-assignable easing color (Round 15): keyframes + picker cards that
    # use this curve are painted this color.
    try:
        if isinstance(points_or_entry, dict):
            _cc = points_or_entry.get("color")
            if isinstance(_cc, (list, tuple)) and len(_cc) >= 3:
                out["color"] = [max(0, min(255, int(v))) for v in list(_cc)[:3]]
    except Exception:
        pass
    return out

_CUSTOM_EASE_LOAD_BLOCKED = False

# Character-editor stat fields that are controlled by visual logic should not
# also be directly typed in the character editor.  The graph data stores its
# node id under "type" (older/imported data may use "key"), so keep the
# detection centralized and format-tolerant instead of sprinkling one-off checks
# through the editor drawing code.
def _node_type_key(node):
    if not isinstance(node, dict):
        return ""
    for _k in ("type", "key", "node_type"):
        _v = node.get(_k)
        if _v:
            return str(_v).strip().lower()
    return ""

def _node_prop_value(node, name, default=None):
    """Read a node property from any schema version used by saved graphs."""
    if not isinstance(node, dict):
        return default
    for _bag_name in ("props", "properties", "fields"):
        _bag = node.get(_bag_name, {})
        if isinstance(_bag, dict) and name in _bag:
            _v = _bag.get(name)
            if isinstance(_v, dict):
                return _v.get("value", _v.get("default", default))
            return _v
    return default

def _stat_name_to_editor_fields(stat_name, unknown_means_all=False):
    """Map script stat names to the visible character-editor fields.

    `combat_set_stat` can receive its Stat through a wire.  In that case there
    is no safe single field to leave editable, so unknown_means_all locks every
    core stat that the node could touch.
    """
    if stat_name is None:
        return {"Max HP", "Min Damage", "Max Damage", "Crit Chance %", "Crit Multiplier", "Speed"} if unknown_means_all else set()
    s = str(stat_name).strip().lower().replace(" ", "_").replace("-", "_")
    if not s:
        return {"Max HP", "Min Damage", "Max Damage", "Crit Chance %", "Crit Multiplier", "Speed"} if unknown_means_all else set()
    if s in ("hp", "health", "max_hp", "maxhealth", "max_health", "hit_points", "max_hit_points"):
        return {"Max HP"}
    if s in ("attack", "atk", "damage", "dmg", "base_damage", "dmg_min", "damage_min", "min_damage",
             "dmg_max", "damage_max", "max_damage", "power"):
        return {"Min Damage", "Max Damage"}
    if s in ("crit", "crit_chance", "critical_chance", "critical_hit_chance"):
        return {"Crit Chance %"}
    if s in ("crit_mult", "crit_multiplier", "critical_multiplier", "crit_damage", "critical_damage"):
        return {"Crit Multiplier"}
    if s in ("speed", "move_speed", "movement_speed", "max_speed", "min_speed", "walk_speed", "run_speed"):
        return {"Speed"}
    if s in ("scale", "world_scale", "size"):
        return {"Scale"}
    return set()

# Explicit known mutators.  These are intentionally about the base character
# stats shown in the editor, not one-shot combat effects such as Deal Damage,
# Heal, HP Bar visibility, particles, camera speed, motion-clip speed, etc.
_LOGIC_LOCK_NODE_FIELDS = {
    # HP / max health
    "lifecycle_set_max_hp": {"Max HP"},
    "stat_add_max_hp": {"Max HP"},

    # Damage / attack stats
    "gameplay_increase_attack": {"Min Damage", "Max Damage"},

    # Crit stats
    "combat_reset_crit_stats": {"Crit Chance %", "Crit Multiplier"},
    "combat_set_crit_chance": {"Crit Chance %"},
    "combat_modify_crit_chance": {"Crit Chance %"},
    "combat_set_crit_multiplier": {"Crit Multiplier"},
    "combat_modify_crit_multiplier": {"Crit Multiplier"},
    "gameplay_set_crit_chance": {"Crit Chance %"},
    "gameplay_increase_crit_chance": {"Crit Chance %"},
    "gameplay_set_crit_mult": {"Crit Multiplier"},

    # Character movement speed and speed caps.  This includes the speed-limit
    # nodes the user expects to make the editor Speed value read-only.
    "gameplay_set_speed": {"Speed"},
    "gameplay_increase_speed": {"Speed"},
    "gameplay_decrease_speed": {"Speed"},
    "phys_set_max_speed": {"Speed"},
    "movement_set_speed_limits": {"Speed"},
    "physics_body_limit_speed": {"Speed"},
    "unreal_set_max_walk_speed": {"Speed"},
    "physics_character_body": {"Speed"},
}

_LOGIC_LOCK_ACTION_WORDS = ("set", "add", "increase", "decrease", "modify", "change", "reset", "limit", "cap", "preset",
                            "deal", "deals", "damage", "trigger", "apply", "assign", "scale", "spawn", "fire", "launch", "shoot", "create")
_LOGIC_LOCK_READONLY_WORDS = ("get", "is", "has", "read", "calculate", "check", "count", "list", "find", "filter", "select")
_LOGIC_LOCK_NON_CHARACTER_SPEED_CONTEXTS = (
    "motion", "scene_timer", "timer", "camera", "particle", "emitter", "projectile",
    "animation", "keyframe", "bar_smooth", "blink", "audio", "sound", "ui", "external",
)
# Only exclude UI/metadata wording from broad damage-field locks. Actual
# gameplay damage nodes (projectile damage, motion-event damage, deal damage,
# damage radius/cone/line, multipliers, etc.) intentionally lock the editor's
# Min/Max Damage fields because the script is now the authority for damage.
_LOGIC_LOCK_DAMAGE_EXCLUDES = ("damage_color", "damage font", "damage popup")

def _logic_lock_fields_for_node(node, linked_inputs=None):
    """Return the editor fields made read-only by one visual-script node."""
    if not isinstance(node, dict):
        return set()
    linked_inputs = linked_inputs or set()
    key = _node_type_key(node)
    if not key:
        return set()

    out = set(_LOGIC_LOCK_NODE_FIELDS.get(key, set()))

    # Generic Set Stat / Modify Stat nodes: map the selected stat to the exact
    # editor field(s).  If the Stat pin is wired, lock all core stat fields
    # because the target stat is dynamic at runtime.
    if key in ("combat_set_stat", "combat_modify_stat"):
        node_id = str(node.get("id", ""))
        stat_is_wired = (node_id, "stat") in linked_inputs
        out.update(_stat_name_to_editor_fields(None if stat_is_wired else _node_prop_value(node, "stat", ""),
                                               unknown_means_all=stat_is_wired))

    # A few generic stat-style nodes encode the stat in a dropdown/property.
    if key in ("combat_set_stat_stage", "combat_modify_stat_stage"):
        # Stage modifiers affect temporary/effective stats, not the base editor
        # numbers, so they deliberately do not lock the fields.
        return out

    # Safer fallback for newly-added nodes: only action nodes in character-ish
    # categories can lock, and read-only/pure nodes never do.  This prevents
    # old false positives like "Get Crit Chance" while still catching future
    # "Set Max HP"/"Set Speed Limit" nodes.
    cls = globals().get("NODE_DEFS", {}).get(key) if isinstance(globals().get("NODE_DEFS", {}), dict) else None
    title = str(getattr(cls, "title", "") or node.get("title", ""))
    desc = str(getattr(cls, "description", "") or node.get("description", ""))
    cat = str(getattr(cls, "category", "") or node.get("category", "")).lower()
    text = f"{key} {title} {desc}".lower()
    words = set(re.findall(r"[a-z0-9]+", text))
    # Read-only check must look at the node's *identity*, not any incidental
    # word in its description.  Descriptions like "default is zero" used to
    # trip the old broad `is` check and let Set Projectile Damage stay editable.
    title_words = re.findall(r"[a-z0-9]+", title.lower())
    first_title_word = title_words[0] if title_words else ""
    key_readonly = key.startswith(("get_", "is_", "has_", "read_", "calculate_", "check_", "count_", "list_", "find_", "filter_"))
    if getattr(cls, "pure", False) or first_title_word in _LOGIC_LOCK_READONLY_WORDS or key_readonly:
        return out
    if not any(w in words for w in _LOGIC_LOCK_ACTION_WORDS):
        return out

    characterish = cat in ("gameplay", "combat", "stats", "movement", "physics", "input", "unreal physics",
                            "projectiles", "weapons", "weapon events", "motion events", "clips", "weapon visuals",
                            "position rig", "rig collisions", "area damage", "explosives", "direction", "scene actions", "")
    # Damage/HP nodes live in lots of categories (Projectiles, Rig Collisions,
    # Area Damage, Explosives, Scene Actions, etc.).  Do not drop them just
    # because their category is not one of the classic character stat groups.
    broad_damage_or_hp = any(x in key or x in text for x in ("damage", "dmg", "attack", "hit damage", "contact damage",
                                                            "max_hp", "max hp", "health", "heal", "revive", "lifesteal"))
    if not characterish and not broad_damage_or_hp:
        return out

    if not ("hp_bar" in key or "hp bar" in text):
        if any(x in key or x in text for x in ("max_hp", "max hp", "max health", "hp ceiling", "health ceiling",
                                              "health", "heal", "healing", "revive", "lifesteal", "life steal")):
            out.add("Max HP")

    if not any(x in key or x in text for x in _LOGIC_LOCK_DAMAGE_EXCLUDES):
        # Broad by design: if the graph sets/spawns/applies/scales/deals ANY
        # gameplay damage (projectile rigs, weapon contact, motion events,
        # damage radius/cone/line, typed damage multipliers, etc.), the base
        # Min/Max Damage fields are read-only so users do not fight two sources
        # of truth.
        if any(x in key or x in text for x in ("damage", "dmg", "attack", "hit damage", "contact damage",
                                              "event damage", "projectile damage", "weapon damage")):
            out.update(("Min Damage", "Max Damage"))

    if "crit_chance" in key or "crit chance" in text or "critical chance" in text:
        out.add("Crit Chance %")
    if "crit_mult" in key or "crit multiplier" in text or "critical multiplier" in text:
        out.add("Crit Multiplier")
    if "reset crit" in text:
        out.update(("Crit Chance %", "Crit Multiplier"))

    if not any(ctx in key or ctx in text for ctx in _LOGIC_LOCK_NON_CHARACTER_SPEED_CONTEXTS):
        if ("speed" in words or "velocity" in words or "walk_speed" in key or "max_walk_speed" in key) and \
                ({"set", "increase", "decrease", "limit", "cap", "preset"} & words or "limit_speed" in key or "speed_limits" in key):
            out.add("Speed")

    # Scale is locked only by an explicit CHARACTER-scale mutator. Incidental
    # wording such as Set Max HP's "scale current HP" must never lock World Scale.
    _scale_identity=(key+" "+title.lower()).replace("-","_")
    if key in {"gameplay_set_scale","character_set_scale","set_character_scale","physics_set_world_scale"} or "set character scale" in _scale_identity or "set world scale" in _scale_identity:
        out.add("Scale")

    return out

def _logic_lock_node_label(node):
    """Human-readable node name for lock-tooltips."""
    key = _node_type_key(node)
    cls = globals().get("NODE_DEFS", {}).get(key) if isinstance(globals().get("NODE_DEFS", {}), dict) else None
    title = str(getattr(cls, "title", "") or node.get("title", "") or key or "Logic Node")
    custom = str(node.get("custom_name", "") or node.get("name", "") or "").strip()
    nid = node.get("id", "?")
    if custom:
        return f"{custom} ({title} #{nid})"
    return f"{title} #{nid}"

def _logic_lock_tooltip(field_name):
    sources = []
    try:
        sources = list((modal.get("_logic_lock_sources", {}) or {}).get(field_name, []) or [])
    except Exception:
        sources = []
    if not sources:
        return "Locked by visual script logic."
    shown = sources[:6]
    more = len(sources) - len(shown)
    txt = "Locked by logic node(s):\n" + "\n".join(f"• {s}" for s in shown)
    if more > 0:
        txt += f"\n• +{more} more"
    return txt

def _collect_logic_lock_nodes_and_links():
    """Collect graph nodes from memory and the selected script's sidecar."""
    all_nodes = []
    all_links = []
    have_modal = isinstance(globals().get("modal", None), dict)
    sf = modal.get("script_file") if have_modal else None

    # Only trust in-memory graph nodes when they are actually the selected
    # script's graph.  Otherwise the character editor can inherit stale locks
    # from whatever blueprint happened to be opened last.
    ns_loaded = modal.get("ns_loaded_script") if have_modal else None
    use_memory_graph = have_modal and (not sf or not ns_loaded or ns_loaded == sf or modal.get("type") == "visual_scripter")
    if use_memory_graph:
        ns_nodes = modal.get("ns_nodes", {})
        if isinstance(ns_nodes, dict):
            all_nodes.extend(ns_nodes.values())
        elif isinstance(ns_nodes, list):
            all_nodes.extend(ns_nodes)
        ns_links = modal.get("ns_links", [])
        if isinstance(ns_links, list):
            all_links.extend(ns_links)

    try:
        if globals().get("external_nodes"):
            all_nodes.extend(globals().get("external_nodes") or [])
    except Exception:
        pass
    if sf:
        try:
            path_sc = script_sidecar_path(sf)
            if os.path.isfile(path_sc):
                with open(path_sc, "r", encoding="utf-8") as f_sc:
                    data = json.load(f_sc)
                file_nodes = data.get("nodes", [])
                if isinstance(file_nodes, dict):
                    all_nodes.extend(file_nodes.values())
                elif isinstance(file_nodes, list):
                    all_nodes.extend(file_nodes)
                file_links = data.get("links", [])
                if isinstance(file_links, list):
                    all_links.extend(file_links)
        except Exception:
            pass
    return all_nodes, all_links

def _get_script_overridden_fields():
    overridden = set()
    sources = {}
    all_nodes, all_links = _collect_logic_lock_nodes_and_links()
    linked_inputs = set()
    for link in all_links:
        if not isinstance(link, dict):
            continue
        try:
            linked_inputs.add((str(link.get("to", "")), str(link.get("to_pin", "")).strip().lower()))
        except Exception:
            pass

    for node in all_nodes:
        fields = _logic_lock_fields_for_node(node, linked_inputs)
        if not fields:
            continue
        label = _logic_lock_node_label(node)
        for field in fields:
            overridden.add(field)
            lst = sources.setdefault(field, [])
            if label not in lst:
                lst.append(label)

    # Store it for the click/text handlers and clear focus immediately if a
    # field became logic-locked while it was focused.  This closes the loophole
    # where a stale focused Speed/HP field could still accept typing for a frame.
    try:
        modal["_logic_locked_fields"] = set(overridden)
        modal["_logic_lock_sources"] = {k: list(v) for k, v in sources.items()}
        if modal.get("focus") in overridden:
            modal["focus"] = None
            modal["_text_anchor"] = None
            modal["_text_cursor"] = 0
    except Exception:
        pass
    return overridden

def load_easing_curves():
    global CUSTOM_EASE_CURVES, CUSTOM_EASE_LOADED, CUSTOM_EASE_VERSION, _CUSTOM_EASE_LOAD_BLOCKED
    CUSTOM_EASE_LOADED = True
    CUSTOM_EASE_VERSION += 1
    data, source = _data_store_read_safe(_easing_curves_path(), "Easing Curves", "dict")
    if source == "blocked":
        # Corrupt + no usable backup: keep memory, refuse saves, leave the
        # bad file stashed by _data_store_read_safe for manual recovery.
        _CUSTOM_EASE_LOAD_BLOCKED = True
        return
    _CUSTOM_EASE_LOAD_BLOCKED = False
    if data is not None:
        CUSTOM_EASE_CURVES = {str(k): _curve_normalize(v)
                              for k, v in data.items()
                              if isinstance(v, (list, dict))}
    if not CUSTOM_EASE_CURVES:
        # Starter curve shaped like a snappy jab: fast out, settle, hold.
        CUSTOM_EASE_CURVES = {"jab": {"points": [[0.0, 0.0], [0.20, 0.85], [0.32, 1.0], [1.0, 1.0]],
                                      "mode": "smooth"}}
def save_easing_curves():
    global CUSTOM_EASE_VERSION, CUSTOM_EASE_CURVES, CUSTOM_EASE_LOADED, _CUSTOM_EASE_LOAD_BLOCKED
    CUSTOM_EASE_VERSION += 1
    if _CUSTOM_EASE_LOAD_BLOCKED:
        print("!! Refusing to save easing curves: last load failed and no backup was usable.")
        try:
            push_toast("Easing-curve save skipped - restore a backup first (see console).", "warning", 5.0)
        except Exception:
            pass
        return
    _data_store_write_safe(_easing_curves_path(), CUSTOM_EASE_CURVES, "Easing Curves", CUSTOM_EASE_LOADED)
def _curve_eval_custom(entry, t):
    """Evaluate a hand-drawn curve. `entry` may be the v2 dict
    ({"points": [...], "mode": smooth|linear|step}) or a v1 bare point list
    (treated as smooth). Smooth mode = Catmull-Rom through the points."""
    if isinstance(entry, dict):
        mode = entry.get("mode", "smooth")
        pts = entry.get("points", [])
    else:
        mode = "smooth"
        pts = entry
    if len(pts) < 2:
        return max(0.0, min(1.0, float(t)))
    t = float(t)
    if t <= pts[0][0]:
        return pts[0][1]
    if t >= pts[-1][0]:
        return pts[-1][1]
    seg = 0
    for i in range(len(pts) - 1):
        if pts[i][0] <= t <= pts[i + 1][0]:
            seg = i
            break
    p1 = pts[seg]
    p2 = pts[seg + 1]
    span = max(1e-6, p2[0] - p1[0])
    s = max(0.0, min(1.0, (t - p1[0]) / span))
    if mode == "step":
        return p1[1]
    if mode == "linear":
        v = p1[1] + (p2[1] - p1[1]) * s
        return max(-1.0, min(2.0, v))
    p0 = pts[seg - 1] if seg > 0 else p1
    p3 = pts[seg + 2] if seg + 2 < len(pts) else p2
    v = 0.5 * ((2.0 * p1[1])
               + (-p0[1] + p2[1]) * s
               + (2.0 * p0[1] - 5.0 * p1[1] + 4.0 * p2[1] - p3[1]) * s * s
               + (-p0[1] + 3.0 * p1[1] - 3.0 * p2[1] + p3[1]) * s * s * s)
    return max(-1.0, min(2.0, v))

# PERF (Arena): curve-name resolution is memoized per curve-set version, so hot
# paths (weapon strokes / Interpolate nodes ticking every frame) do one dict hit
# instead of repeating strip/lower/prefix string work for the same easing name.
_CURVE_LOOKUP_VER = [-1]
_CURVE_LOOKUP = {}

def _curve_eval_named(t, kind):
    """Custom-curve value for t, or None if `kind` isn't one of the user's curves."""
    try:
        if not CUSTOM_EASE_LOADED:
            load_easing_curves()
        if not CUSTOM_EASE_CURVES:
            return None
        if _CURVE_LOOKUP_VER[0] != CUSTOM_EASE_VERSION:
            _CURVE_LOOKUP.clear()
            _CURVE_LOOKUP_VER[0] = CUSTOM_EASE_VERSION
        if kind in _CURVE_LOOKUP:
            entry = _CURVE_LOOKUP[kind]
        else:
            entry = CUSTOM_EASE_CURVES.get(kind)
            if entry is None:
                k = str(kind).strip()
                if k.lower().startswith("curve:"):
                    entry = CUSTOM_EASE_CURVES.get(k[6:].strip())
                elif k != kind:
                    entry = CUSTOM_EASE_CURVES.get(k)
            _CURVE_LOOKUP[kind] = entry
        if entry is not None:
            return _curve_eval_custom(entry, float(t))
    except Exception:
        pass
    return None

def _is_custom_curve_name(kind):
    """True if `kind` refers to one of the user's F8-drawn curves."""
    try:
        if not CUSTOM_EASE_LOADED:
            load_easing_curves()
        k = str(kind).strip()
        return k.lower().startswith("curve:") or k in CUSTOM_EASE_CURVES
    except Exception:
        return False

class _EaseCurveOptions:
    """Dropdown contents that always include the user's custom F8 curves.
    Behaves like a read-only list so the inspector/dropdown code never notices."""
    _LONG = ("linear", "quad_in", "quad_out", "quad_inout", "cubic_in", "cubic_out", "cubic_inout",
             "quart_in", "quart_out", "quart_inout", "quint_in", "quint_out", "quint_inout",
             "sine_in", "sine_out", "sine_inout", "expo_in", "expo_out", "expo_inout",
             "circ_in", "circ_out", "circ_inout", "back_in", "back_out", "back_inout",
             "elastic_in", "elastic_out", "elastic_inout", "bounce_in", "bounce_out", "bounce_inout",
             "discrete", "ease_in", "ease_out", "ease_in_out", "smoothstep", "smootherstep", "bounce")
    _SHORT = ("linear", "ease_in", "ease_out", "ease_in_out", "smoothstep", "smootherstep", "bounce")

    def __init__(self, short=False):
        self.short = bool(short)

    # PERF (Arena): the inspector runs len()/contains()/getitem() on this object
    # EVERY FRAME for every visible easing dropdown. Materialize the list once per
    # curve-set version instead of rebuilding+sorting it per call, so the easing
    # system costs nothing while the F8 editor is closed.
    _CACHE = {}

    @classmethod
    def _materialized(cls, short):
        key = (CUSTOM_EASE_VERSION, bool(short))
        hit = cls._CACHE.get(key)
        if hit is None:
            base = list(cls._SHORT if short else cls._LONG)
            try:
                if not CUSTOM_EASE_LOADED:
                    load_easing_curves()
                base += ["curve:" + n for n in sorted(CUSTOM_EASE_CURVES.keys())]
            except Exception:
                pass
            hit = tuple(base)
            if len(cls._CACHE) > 8:
                cls._CACHE.clear()
            cls._CACHE[key] = hit
        return hit

    def _items(self):
        return list(self._materialized(self.short))

    def __iter__(self):
        return iter(self._materialized(self.short))

    def __len__(self):
        return len(self._materialized(self.short))

    def __getitem__(self, i):
        return self._materialized(self.short)[i]

    def __contains__(self, v):
        return v in self._materialized(self.short)

    def __repr__(self):
        return repr(list(self._materialized(self.short)))

    def index(self, v):
        return self._materialized(self.short).index(v)

    def count(self, v):
        return self._materialized(self.short).count(v)

def _ec_points_from_builtin(kind, steps=12):
    return [[i / steps, _weapon_ease(i / steps, kind)] for i in range(steps + 1)]

def open_easing_curve_editor():
    if not CUSTOM_EASE_LOADED:
        load_easing_curves()
    modal["focus"] = None
    if modal.get("_ec_cur") not in CUSTOM_EASE_CURVES:
        modal["_ec_cur"] = sorted(CUSTOM_EASE_CURVES.keys())[0]
    modal["_ec_drag"] = None
    modal["_ec_sel"] = None
    modal["_ec_dirty"] = False
    modal["_ec_snap"] = True
    modal["_ec_undo"] = []
    modal["_ec_redo"] = []
    modal["_ec_list_scroll"] = 0
    modal["_ec_kprev"] = {pygame.K_F8: True, pygame.K_ESCAPE: True}
    modal["_ec_prev_click"] = True
    modal["ec_rename"] = ""
    modal["ec_point_t"] = ""
    modal["ec_point_v"] = ""
    modal["type"] = "easing_curve_editor"

_EC_PRESETS = ["linear", "smoothstep", "expo_out", "back_out", "elastic_out", "bounce_out"]

def draw_easing_curve_editor(mouse_pos):
    """Professional easing curve editor (F8): named curves, drag/add/delete
    points, point selection + numeric fields, undo/redo, snap, shape modes
    (smooth/linear/step), flip tools, curve browser, live jab preview."""
    global left_click_this_frame
    if modal.get("type") != "easing_curve_editor":
        return  # hard gate: the editor never runs in the background
    if not CUSTOM_EASE_LOADED:
        load_easing_curves()
    # Reset any stale clip so the editor always renders above the scene.
    screen.set_clip(None)

    # ---------- state ----------
    def _snapshot():
        return {n: {**({"icon": e["icon"]} if e.get("icon") else {}),
                    **({"color": list(e["color"])} if e.get("color") else {}),
                    "points": [list(p) for p in e["points"]], "mode": e.get("mode", "smooth")}
                for n, e in CUSTOM_EASE_CURVES.items()}

    def _restore(snap):
        CUSTOM_EASE_CURVES.clear()
        for n, e in snap.items():
            CUSTOM_EASE_CURVES[n] = {**({"icon": e["icon"]} if e.get("icon") else {}),
                                     **({"color": list(e["color"])} if e.get("color") else {}),
                                     "points": [list(p) for p in e["points"]],
                                     "mode": e.get("mode", "smooth")}
        save_easing_curves()
        if modal.get("_ec_cur") not in CUSTOM_EASE_CURVES:
            modal["_ec_cur"] = sorted(CUSTOM_EASE_CURVES.keys())[0] if CUSTOM_EASE_CURVES else "jab"
        modal["_ec_drag"] = None
        modal["_ec_sel"] = None

    def _push_undo():
        undo = modal.setdefault("_ec_undo", [])
        undo.append(_snapshot())
        del undo[:-80]
        modal["_ec_redo"] = []

    def _free_name(base):
        base = (base or "curve").strip() or "curve"
        name, i = base, 2
        while name in CUSTOM_EASE_CURVES:
            name = f"{base}_{i}"
            i += 1
        return name

    def _commit_rename():
        cur = modal.get("_ec_cur")
        raw = " ".join(str(modal.get("ec_rename", "")).split())[:32]
        modal["focus"] = None
        if not raw or raw == cur or cur not in CUSTOM_EASE_CURVES:
            return
        _push_undo()
        new = _free_name(raw) if raw in CUSTOM_EASE_CURVES else raw
        rebuilt = {}
        for k, v in CUSTOM_EASE_CURVES.items():
            rebuilt[new if k == cur else k] = v
        CUSTOM_EASE_CURVES.clear()
        CUSTOM_EASE_CURVES.update(rebuilt)
        modal["_ec_cur"] = new
        save_easing_curves()

    def _commit_point_fields():
        sel = modal.get("_ec_sel")
        cur = modal.get("_ec_cur")
        modal["focus"] = None
        if sel is None or cur not in CUSTOM_EASE_CURVES:
            return
        pts = CUSTOM_EASE_CURVES[cur]["points"]
        if not (0 <= sel < len(pts)):
            return
        try:
            nt = float(str(modal.get("ec_point_t", "")).strip())
            nv = float(str(modal.get("ec_point_v", "")).strip())
        except (TypeError, ValueError):
            return
        nt = max(0.0, min(1.0, nt))
        nv = max(-0.5, min(1.75, nv))
        if sel == 0:
            nt = 0.0
        elif sel == len(pts) - 1:
            nt = 1.0
        else:
            nt = max(pts[sel - 1][0] + 0.005, min(pts[sel + 1][0] - 0.005, nt))
        if [nt, nv] != pts[sel]:
            _push_undo()
            pts[sel] = [nt, nv]
            save_easing_curves()

    # ---------- input ----------
    keys = pygame.key.get_pressed()
    mods = pygame.key.get_mods()
    _kprev = modal.setdefault("_ec_kprev", {})

    def _edge(kc):
        now = bool(keys[kc])
        was = _kprev.get(kc, False)
        _kprev[kc] = now
        return now and not was

    _btn_down = pygame.mouse.get_pressed()[0]
    clicked = bool(left_click_this_frame) or (_btn_down and not modal.get("_ec_prev_click"))
    modal["_ec_prev_click"] = _btn_down

    focus = modal.get("focus")
    text_focus = focus in ("ec_rename", "ec_point_t", "ec_point_v")

    # ---------- layout ----------
    panel_w, panel_h = WIDTH, HEIGHT
    panel_rect = pygame.Rect(0, 0, WIDTH, HEIGHT)
    draw_panel(panel_rect, alpha=252, radius=12, shadow=False)
    px = panel_rect.x + 16
    py = panel_rect.y + 12
    sb_w = 172
    mx0 = px + sb_w + 14
    mw = panel_rect.right - 16 - mx0

    names = sorted(CUSTOM_EASE_CURVES.keys())
    cur = modal.get("_ec_cur")
    if cur not in CUSTOM_EASE_CURVES:
        cur = names[0] if names else "jab"
        if cur not in CUSTOM_EASE_CURVES:
            CUSTOM_EASE_CURVES[cur] = {"points": [[0.0, 0.0], [1.0, 1.0]], "mode": "smooth"}
        modal["_ec_cur"] = cur
    entry = CUSTOM_EASE_CURVES[cur]
    pts = entry["points"]
    sel = modal.get("_ec_sel")
    if sel is not None and not (0 <= sel < len(pts)):
        sel = None
        modal["_ec_sel"] = None

    def _btn(rect, label, active=False, danger=False, disabled=False):
        col_hover = rect.collidepoint(mouse_pos) and not disabled
        draw_button(rect, label, col_hover, small=True, danger=danger,
                    muted=(not active and not danger))
        if disabled:
            dim = pygame.Surface((rect.width, rect.height), pygame.SRCALPHA)
            dim.fill((10, 10, 13, 150))
            screen.blit(dim, rect.topleft)
            return False
        return rect.collidepoint(mouse_pos) and clicked

    # ---------- keyboard command routing ----------
    if _edge(pygame.K_ESCAPE):
        if focus == "ec_rename":
            modal["focus"] = None
        elif focus in ("ec_point_t", "ec_point_v"):
            modal["focus"] = None
        else:
            modal["focus"] = None
            modal["type"] = None
            return
    if False and _edge(pygame.K_F8) and not text_focus:
        modal["focus"] = None
        modal["type"] = None
        return
    if _edge(pygame.K_RETURN) or _edge(pygame.K_KP_ENTER):
        if focus == "ec_rename":
            _commit_rename()
        elif focus in ("ec_point_t", "ec_point_v"):
            _commit_point_fields()
    if not text_focus:
        if _edge(pygame.K_z) and (mods & pygame.KMOD_CTRL):
            if modal.get("_ec_undo"):
                modal.setdefault("_ec_redo", []).append(_snapshot())
                _restore(modal["_ec_undo"].pop())
        elif (_edge(pygame.K_y) and (mods & pygame.KMOD_CTRL)) or (_edge(pygame.K_z) and (mods & pygame.KMOD_CTRL) and (mods & pygame.KMOD_SHIFT)):
            if modal.get("_ec_redo"):
                modal.setdefault("_ec_undo", []).append(_snapshot())
                _restore(modal["_ec_redo"].pop())
        elif _edge(pygame.K_DELETE) or _edge(pygame.K_BACKSPACE):
            s = modal.get("_ec_sel")
            if s is not None and 0 < s < len(pts) - 1 and len(pts) > 2:
                _push_undo()
                pts.pop(s)
                modal["_ec_sel"] = None
                save_easing_curves()
        else:
            s = modal.get("_ec_sel")
            if s is not None and 0 <= s < len(pts):
                step = 5.0 if (mods & pygame.KMOD_SHIFT) else 1.0
                moved = False
                if _edge(pygame.K_UP):
                    pts[s][1] = min(1.75, pts[s][1] + 0.01 * step)
                    moved = True
                elif _edge(pygame.K_DOWN):
                    pts[s][1] = max(-0.5, pts[s][1] - 0.01 * step)
                    moved = True
                elif _edge(pygame.K_LEFT) and 0 < s < len(pts) - 1:
                    pts[s][0] = max(pts[s - 1][0] + 0.005, pts[s][0] - 0.005 * step)
                    moved = True
                elif _edge(pygame.K_RIGHT) and 0 < s < len(pts) - 1:
                    pts[s][0] = min(pts[s + 1][0] - 0.005, pts[s][0] + 0.005 * step)
                    moved = True
                if moved:
                    save_easing_curves()

    # Key routing above (rename commit, undo/redo) can REBUILD the curve dict
    # mid-frame. Refresh this frame's cached view so nothing below touches a
    # stale name or entry -- this was the rename+Enter crash: the sidebar still
    # looped over the pre-rename name list and hit a KeyError.
    names = sorted(CUSTOM_EASE_CURVES.keys())
    cur = modal.get("_ec_cur")
    if cur not in CUSTOM_EASE_CURVES:
        cur = names[0] if names else "jab"
        if cur not in CUSTOM_EASE_CURVES:
            CUSTOM_EASE_CURVES[cur] = {"points": [[0.0, 0.0], [1.0, 1.0]], "mode": "smooth"}
        modal["_ec_cur"] = cur
    entry = CUSTOM_EASE_CURVES[cur]
    pts = entry["points"]
    sel = modal.get("_ec_sel")
    if sel is not None and not (0 <= sel < len(pts)):
        sel = None
        modal["_ec_sel"] = None

    # ---------- header ----------
    title = font_lg.render("Easing Curve Editor", True, TEXT_MAIN)
    screen.blit(title, (px, py))
    close_btn = pygame.Rect(panel_rect.right - 38, py - 2, 26, 26)
    ui_draw_rect(screen, DANGER_HOVER if close_btn.collidepoint(mouse_pos) else (60, 44, 48), close_btn, border_radius=7)
    _xl = font_sm.render("x", True, (255, 255, 255))
    screen.blit(_xl, (close_btn.centerx - _xl.get_width() // 2, close_btn.centery - _xl.get_height() // 2))
    if close_btn.collidepoint(mouse_pos) and clicked:
        modal["focus"] = None
        modal["type"] = None
        return

    # ---------- sidebar: curve browser ----------
    sb_x = px
    sb_y = py + 40
    screen.blit(font_tiny.render(f"CURVES ({len(names)})", True, TEXT_FAINT), (sb_x, sb_y))
    list_y = sb_y + 16
    row_h = 24
    max_rows = max(4, (panel_h - 40 - 16 - 96 - 72) // row_h)
    lscroll = max(0, min(int(modal.get("_ec_list_scroll", 0)), max(0, len(names) - max_rows)))
    modal["_ec_list_scroll"] = lscroll
    if cur in names and names.index(cur) < lscroll:
        lscroll = names.index(cur)
        modal["_ec_list_scroll"] = lscroll
    visible = names[lscroll:lscroll + max_rows]
    for r, nm in enumerate(visible):
        rrect = pygame.Rect(sb_x, list_y + r * row_h, sb_w, row_h - 3)
        is_cur = (nm == cur)
        hov = rrect.collidepoint(mouse_pos)
        ui_draw_rect(screen, ACCENT if is_cur else (FIELD_FOCUS if hov else FIELD_BG), rrect, border_radius=6)
        ui_draw_rect(screen, ACCENT if is_cur else PANEL_BORDER, rrect, width=1, border_radius=6)
        mode_letter = {"smooth": "S", "linear": "L", "step": "T"}.get((CUSTOM_EASE_CURVES.get(nm) or {}).get("mode", "smooth"), "S")
        lbl = font_sm.render(nm[:18], True, (10, 10, 14) if is_cur else TEXT_MAIN)
        screen.blit(lbl, (rrect.x + 8, rrect.centery - lbl.get_height() // 2))
        bl = font_tiny.render(mode_letter, True, (10, 10, 14) if is_cur else TEXT_FAINT)
        screen.blit(bl, (rrect.right - bl.get_width() - 7, rrect.centery - bl.get_height() // 2))
        if hov and clicked:
            modal["_ec_cur"] = nm
            modal["_ec_sel"] = None
            modal["_ec_drag"] = None
            modal["focus"] = None
    if len(names) > max_rows:
        up_r = pygame.Rect(sb_x + sb_w - 50, list_y - 14, 22, 14)
        dn_r = pygame.Rect(sb_x + sb_w - 26, list_y - 14, 22, 14)
        draw_button(up_r, "^", up_r.collidepoint(mouse_pos), small=True, muted=True)
        draw_button(dn_r, "v", dn_r.collidepoint(mouse_pos), small=True, muted=True)
        if up_r.collidepoint(mouse_pos) and clicked:
            modal["_ec_list_scroll"] = max(0, lscroll - 1)
        if dn_r.collidepoint(mouse_pos) and clicked:
            modal["_ec_list_scroll"] = min(len(names) - max_rows, lscroll + 1)

    # sidebar management buttons (2x2 grid at bottom of sidebar)
    btn_by = panel_rect.bottom - 86
    bw = (sb_w - 6) // 2
    new_r  = pygame.Rect(sb_x, btn_by, bw, 26)
    dup_r  = pygame.Rect(sb_x + bw + 6, btn_by, bw, 26)
    ren_r  = pygame.Rect(sb_x, btn_by + 32, bw, 26)
    del_r  = pygame.Rect(sb_x + bw + 6, btn_by + 32, bw, 26)
    if _btn(new_r, "New"):
        _push_undo()
        nm = _free_name("curve")
        CUSTOM_EASE_CURVES[nm] = {"points": [[0.0, 0.0], [1.0, 1.0]], "mode": "smooth"}
        modal["_ec_cur"] = nm
        modal["_ec_sel"] = None
        modal["ec_rename"] = nm
        modal["focus"] = "ec_rename"      # name it immediately, like a DAW
        save_easing_curves()
    if _btn(dup_r, "Duplicate"):
        _push_undo()
        nm = _free_name(cur + "_copy")
        CUSTOM_EASE_CURVES[nm] = {"points": [list(p) for p in pts], "mode": entry.get("mode", "smooth")}
        modal["_ec_cur"] = nm
        modal["_ec_sel"] = None
        save_easing_curves()
    if _btn(ren_r, "Rename"):
        modal["ec_rename"] = cur
        modal["focus"] = "ec_rename"
    if _btn(del_r, "Delete", danger=True, disabled=len(names) <= 1):
        _push_undo()
        CUSTOM_EASE_CURVES.pop(cur, None)
        modal["_ec_cur"] = sorted(CUSTOM_EASE_CURVES.keys())[0]
        modal["_ec_sel"] = None
        modal["_ec_drag"] = None
        save_easing_curves()
    draw_button(new_r, "New", new_r.collidepoint(mouse_pos), small=True)
    draw_button(dup_r, "Duplicate", dup_r.collidepoint(mouse_pos), small=True)
    draw_button(ren_r, "Rename", ren_r.collidepoint(mouse_pos), small=True)
    draw_button(del_r, "Delete", del_r.collidepoint(mouse_pos), small=True, danger=True)

    # ---------- main column rows ----------
    row0 = pygame.Rect(mx0, py + 40, mw, 30)
    if focus == "ec_rename":
        draw_text_field(pygame.Rect(row0.x, row0.y - 3, 320, 30), modal.get("ec_rename", ""), "CURVE NAME", True)
        r_hint = font_tiny.render("ENTER apply | ESC cancel", True, TEXT_FAINT)
        screen.blit(r_hint, (row0.x + 330, row0.y + 6))
    else:
        nm_lbl = font_md.render(str(cur), True, TEXT_MAIN)
        screen.blit(nm_lbl, (row0.x, row0.y + 4))
        use_lbl = font_tiny.render(f"type this in any Easing pin:   curve:{cur}", True, GOLD)
        screen.blit(use_lbl, (row0.x + nm_lbl.get_width() + 14, row0.y + 9))
        if row0.inflate(-4, 0).collidepoint(mouse_pos) and clicked and not pygame.key.get_pressed()[pygame.K_F8]:
            modal["ec_rename"] = cur
            modal["focus"] = "ec_rename"

    row1y = py + 78
    screen.blit(font_tiny.render("SHAPE", True, TEXT_FAINT), (mx0, row1y + 8))
    mx = mx0 + 52
    mode_btns = []
    for mode_key, mode_lab in (("smooth", "Smooth"), ("linear", "Linear"), ("step", "Step")):
        r = pygame.Rect(mx, row1y, 84, 28)
        mode_btns.append((mode_key, r))
        draw_button(r, mode_lab, r.collidepoint(mouse_pos), small=True,
                    muted=(entry.get("mode", "smooth") != mode_key))
        mx += 92
    for mode_key, r in mode_btns:
        if r.collidepoint(mouse_pos) and clicked and entry.get("mode", "smooth") != mode_key:
            _push_undo()
            entry["mode"] = mode_key
            save_easing_curves()

    # ICON grid (Round 15): click-to-pick chips, no more < > cycling. The
    # empty chip restores the plain diamond key. COLOR swatches below paint
    # every keyframe + picker card that uses this curve.
    row1iy = row1y + 34
    screen.blit(font_tiny.render("ICON", True, TEXT_FAINT), (mx0, row1iy + 8))
    _eic_name = str(entry.get("icon", "") or "")
    _eic_chip = 24
    _eic_cols = 12
    _egy = row1iy
    for _egi, _egn in enumerate(_EC_ICON_CHOICES):
        _egx = mx0 + 52 + (_egi % _eic_cols) * (_eic_chip + 3)
        _egy = row1iy + (_egi // _eic_cols) * (_eic_chip + 3)
        _echip = pygame.Rect(_egx, _egy, _eic_chip, _eic_chip)
        _eon2 = _eic_name == _egn
        _ehov3 = _echip.collidepoint(mouse_pos)
        ui_draw_rect(screen, ACCENT if _eon2 else ((52, 54, 72) if _ehov3 else FIELD_BG),
                         _echip, border_radius=5)
        ui_draw_rect(screen, ACCENT if _eon2 else PANEL_BORDER, _echip, width=1, border_radius=5)
        if _egn:
            _egs = get_icon_fs(_egn, 13, (10, 10, 14) if _eon2 else (255, 224, 130))
            if _egs is not None:
                screen.blit(_egs, (_echip.centerx - 6, _echip.centery - 6))
        else:
            _dc2 = (10, 10, 14) if _eon2 else (160, 160, 180)
            pygame.draw.polygon(screen, _dc2, [(_echip.centerx, _echip.centery - 5),
                                               (_echip.centerx + 4, _echip.centery),
                                               (_echip.centerx, _echip.centery + 5),
                                               (_echip.centerx - 4, _echip.centery)], 1)
        if _ehov3 and clicked:
            _push_undo()
            if _egn:
                entry["icon"] = _egn
            else:
                entry.pop("icon", None)
            save_easing_curves()
    _eic_lbl = font_tiny.render(_eic_name if _eic_name else "none - motion-clip keys keep the plain diamond",
                                True, GOLD if _eic_name else TEXT_FAINT)
    screen.blit(_eic_lbl, (mx0 + 52 + _eic_cols * (_eic_chip + 3) + 8, row1iy + 6))
    # COLOR swatch grid: key diamond/icon + picker card tint for this curve
    _ecrow_y = _egy + _eic_chip + 8
    screen.blit(font_tiny.render("COLOR", True, TEXT_FAINT), (mx0, _ecrow_y + 8))
    _ecc_raw = entry.get("color")
    _ecc_cur = (tuple(int(v) for v in list(_ecc_raw)[:3])
                if isinstance(_ecc_raw, (list, tuple)) and len(_ecc_raw) >= 3 else None)
    for _eci2, _ecv2 in enumerate(_EASE_COLOR_PRESETS):
        _ecx2 = mx0 + 52 + _eci2 * (24 + 3)
        _ecchip = pygame.Rect(_ecx2, _ecrow_y, 24, 24)
        _econ = (_ecv2 is None and _ecc_cur is None) or (_ecv2 is not None and _ecc_cur == tuple(_ecv2))
        _echov2 = _ecchip.collidepoint(mouse_pos)
        if _ecv2 is None:
            ui_draw_rect(screen, ACCENT if _econ else FIELD_BG, _ecchip, border_radius=5)
            pygame.draw.line(screen, (10, 10, 14) if _econ else (255, 224, 130),
                             (_ecchip.x + 5, _ecchip.bottom - 6), (_ecchip.right - 6, _ecchip.y + 5), 2)
        else:
            ui_draw_rect(screen, tuple(_ecv2), _ecchip, border_radius=5)
        ui_draw_rect(screen, (240, 240, 250) if _econ else PANEL_BORDER, _ecchip,
                         width=2 if _econ else 1, border_radius=5)
        if _echov2 and clicked:
            _push_undo()
            if _ecv2 is None:
                entry.pop("color", None)
            else:
                entry["color"] = [int(_ecv2[0]), int(_ecv2[1]), int(_ecv2[2])]
            save_easing_curves()
    _ecol_lbl = font_tiny.render("keys + picker cards take this color" if _ecc_cur else "default key gold - click a swatch",
                                 True, tuple(_ecc_cur) if _ecc_cur else TEXT_FAINT)
    screen.blit(_ecol_lbl, (mx0 + 52 + len(_EASE_COLOR_PRESETS) * 27 + 8, _ecrow_y + 8))

    row2y = _ecrow_y + 34
    screen.blit(font_tiny.render("EDIT", True, TEXT_FAINT), (mx0, row2y + 8))
    ex = mx0 + 52
    undo_r = pygame.Rect(ex, row2y, 66, 28); ex += 74
    redo_r = pygame.Rect(ex, row2y, 66, 28); ex += 74
    fliph_r = pygame.Rect(ex, row2y, 74, 28); ex += 82
    flipv_r = pygame.Rect(ex, row2y, 74, 28); ex += 82
    snap_r = pygame.Rect(ex, row2y, 96, 28)
    if _btn(undo_r, "Undo", disabled=not modal.get("_ec_undo")):
        modal.setdefault("_ec_redo", []).append(_snapshot())
        _restore(modal["_ec_undo"].pop())
    if _btn(redo_r, "Redo", disabled=not modal.get("_ec_redo")):
        modal.setdefault("_ec_undo", []).append(_snapshot())
        _restore(modal["_ec_redo"].pop())
    if _btn(fliph_r, "Flip H"):
        if len(pts) >= 2:
            _push_undo()
            new_pts = _curve_normalize([ [1.0 - p[0], p[1]] for p in reversed(pts)[:]])["points"]
            entry["points"] = new_pts
            pts = new_pts
            modal["_ec_sel"] = None
            save_easing_curves()
    if _btn(flipv_r, "Flip V"):
        _push_undo()
        for p in pts:
            p[1] = 1.0 - p[1]
        save_easing_curves()
    draw_button(snap_r, "Snap: ON" if modal.get("_ec_snap", True) else "Snap: OFF",
                snap_r.collidepoint(mouse_pos), small=True)
    if snap_r.collidepoint(mouse_pos) and clicked:
        modal["_ec_snap"] = not modal.get("_ec_snap", True)
    draw_button(undo_r, "Undo", undo_r.collidepoint(mouse_pos) and modal.get("_ec_undo"), small=True, muted=True)
    draw_button(redo_r, "Redo", redo_r.collidepoint(mouse_pos) and modal.get("_ec_redo"), small=True, muted=True)
    draw_button(fliph_r, "Flip H", fliph_r.collidepoint(mouse_pos), small=True, muted=True)
    draw_button(flipv_r, "Flip V", flipv_r.collidepoint(mouse_pos), small=True, muted=True)

    row3y = row2y + 36
    screen.blit(font_tiny.render("START FROM", True, TEXT_FAINT), (mx0, row3y + 8))
    bx = mx0 + 92
    for preset in _EC_PRESETS:
        r = pygame.Rect(bx, row3y, 102, 28)
        draw_button(r, preset, r.collidepoint(mouse_pos), small=True, muted=True)
        if r.collidepoint(mouse_pos) and clicked:
            _push_undo()
            entry["points"] = _ec_points_from_builtin(preset)
            pts = entry["points"]
            modal["_ec_sel"] = None
            modal["_ec_drag"] = None
            save_easing_curves()
        bx += 110

    # ---------- graph ----------
    gy = row3y + 38
    gh = panel_rect.bottom - 18 - 108 - gy
    grect = pygame.Rect(mx0, gy, mw, gh)
    ui_draw_rect(screen, (8, 8, 11), grect, border_radius=10)
    ui_draw_rect(screen, PANEL_BORDER, grect, width=1, border_radius=10)
    VMIN, VMAX = -0.25, 1.25

    def tx(t):
        return grect.x + 12 + (grect.width - 24) * t

    def ty(v):
        return grect.bottom - 12 - (grect.height - 24) * ((v - VMIN) / (VMAX - VMIN))

    def un_t(xpos):
        return max(0.0, min(1.0, (xpos - (grect.x + 12)) / max(1, grect.width - 24)))

    def un_v(ypos):
        frac = ((grect.bottom - 12) - ypos) / max(1, grect.height - 24)
        return max(-0.24, min(1.49, VMIN + frac * (VMAX - VMIN)))

    def _snapped(t, v):
        if modal.get("_ec_snap", True) and not (mods & pygame.KMOD_ALT):
            t = max(0.0, min(1.0, round(t * 16.0) / 16.0))
            v = max(-0.5, min(1.75, round(v * 20.0) / 20.0))
        return t, v

    # grid + overshoot bands + guides
    shade = pygame.Surface((grect.width - 4, grect.height - 4), pygame.SRCALPHA)
    for i in range(11):
        tcol = (255, 255, 255, 16) if i % 5 == 0 else (255, 255, 255, 7)
        pygame.draw.line(shade, tcol, (2 + (grect.width - 24) * i / 10, 2), (2 + (grect.width - 24) * i / 10, grect.height - 6))
        pygame.draw.line(shade, tcol, (2, 2 + (grect.height - 24) * i / 10), (grect.width - 4, 2 + (grect.height - 24) * i / 10))
    screen.blit(shade, (grect.x + 2, grect.y + 2))
    over_top_h = max(1, int(ty(1.0) - grect.y - 2))
    band = pygame.Surface((grect.width, over_top_h), pygame.SRCALPHA)
    band.fill((255, 200, 70, 16))
    screen.blit(band, (grect.x, grect.y + 2))
    over_bot_h = max(1, int(grect.bottom - 2 - ty(0.0)))
    band2 = pygame.Surface((grect.width, over_bot_h), pygame.SRCALPHA)
    band2.fill((255, 200, 70, 10))
    screen.blit(band2, (grect.x, ty(0.0)))
    pygame.draw.line(screen, (90, 220, 140, 90), (grect.x, ty(1.0)), (grect.right, ty(1.0)), 1)
    pygame.draw.line(screen, (90, 220, 140, 60), (grect.x, ty(0.0)), (grect.right, ty(0.0)), 1)
    screen.blit(font_tiny.render("1.0 full reach", True, (90, 200, 140)), (grect.x + 6, ty(1.0) - 14))
    screen.blit(font_tiny.render("0.0 rest", True, (90, 200, 140)), (grect.x + 6, ty(0.0) + 2))
    lblT = font_tiny.render("stroke time ->", True, TEXT_FAINT)
    screen.blit(lblT, (grect.right - lblT.get_width() - 6, grect.bottom - 16))

    # the curve
    seg_mode = entry.get("mode", "smooth")
    samples = []
    if seg_mode == "step":
        prev = None
        for i in range(121):
            tt = i / 120.0
            vv = _curve_eval_custom(entry, tt)
            x_i, y_i = int(tx(tt)), int(ty(vv))
            if prev is not None:
                pygame.draw.line(screen, ACCENT_HOVER, (prev[0], prev[1]), (x_i, prev[1]), 3)
                pygame.draw.line(screen, ACCENT_HOVER, (x_i, prev[1]), (x_i, y_i), 3)
            prev = (x_i, y_i)
    else:
        for i in range(121):
            tt = i / 120.0
            samples.append((int(tx(tt)), int(ty(_curve_eval_custom(entry, tt)))))
        if len(samples) >= 2:
            pygame.draw.lines(screen, ACCENT_HOVER, False, samples, 3)

    # animated playhead + readout dot
    phase = (time.time() % 1.4) / 1.4
    eased_now = _curve_eval_custom(entry, phase)
    phx = int(tx(phase))
    pygame.draw.line(screen, (255, 255, 255), (phx, grect.y + 4), (phx, grect.bottom - 4), 1)
    pygame.draw.circle(screen, (255, 255, 255), (phx, int(ty(eased_now))), 5)

    # ---------- point interaction (fixed: drag state survives the frame) ----------
    shift_held = keys[pygame.K_LSHIFT] or keys[pygame.K_RSHIFT]
    drag = modal.get("_ec_drag")
    HANDLE = 11

    if clicked and grect.collidepoint(mouse_pos) and focus is None:
        best_i, best_d = -1, 99999
        for i, p in enumerate(pts):
            d = math.hypot(tx(p[0]) - mouse_pos[0], ty(p[1]) - mouse_pos[1])
            if d < best_d:
                best_i, best_d = i, d
        if 0 <= best_i and best_d <= HANDLE + 6:
            if shift_held and 0 < best_i < len(pts) - 1 and len(pts) > 2:
                _push_undo()
                pts.pop(best_i)
                modal["_ec_sel"] = None
                modal["_ec_drag"] = None
                save_easing_curves()
            else:
                # begin drag: snapshot ONCE at grab time for clean undo
                _push_undo()
                modal["_ec_drag"] = best_i
                modal["_ec_sel"] = best_i
                modal["ec_point_t"] = f"{pts[best_i][0]:.3f}"
                modal["ec_point_v"] = f"{pts[best_i][1]:.3f}"
                drag = best_i
        else:
            # click empty graph -> insert a key exactly ON the curve at that time
            _push_undo()
            nt = un_t(mouse_pos[0])
            nv = _curve_eval_custom(entry, nt)
            nt, nv = _snapped(nt, nv)
            new_p = [nt, nv]
            pts.append(new_p)
            pts.sort(key=lambda p: p[0])
            ni = pts.index(new_p)
            modal["_ec_drag"] = ni
            modal["_ec_sel"] = ni
            modal["ec_point_t"] = f"{nt:.3f}"
            modal["ec_point_v"] = f"{nv:.3f}"
            drag = ni
            save_easing_curves()

    if _btn_down and drag is not None and 0 <= drag < len(pts) and focus is None:
        nt = un_t(mouse_pos[0])
        nv = un_v(mouse_pos[1])
        nt, nv = _snapped(nt, nv)
        if drag == 0:
            nt = 0.0
        elif drag == len(pts) - 1:
            nt = 1.0
        else:
            lo_t = pts[drag - 1][0] + 0.005
            hi_t = pts[drag + 1][0] - 0.005
            nt = max(lo_t, min(hi_t, nt))
        if [nt, nv] != pts[drag]:
            pts[drag] = [nt, nv]
            modal["_ec_dirty"] = True
            modal["ec_point_t"] = f"{nt:.3f}"
            modal["ec_point_v"] = f"{nv:.3f}"
    else:
        if modal.get("_ec_dirty"):
            save_easing_curves()
            modal["_ec_dirty"] = False
        modal["_ec_drag"] = None

    # handles
    for i, p in enumerate(pts):
        hx, hy = int(tx(p[0])), int(ty(p[1]))
        hov = math.hypot(hx - mouse_pos[0], hy - mouse_pos[1]) <= HANDLE + 4
        is_sel = (i == modal.get("_ec_sel"))
        col = GOLD if (drag == i or is_sel) else (GOOD if hov else (235, 235, 242))
        big = 9 if (hov or drag == i or is_sel) else 7
        pygame.draw.circle(screen, (10, 10, 14), (hx, hy), big + 1)
        pygame.draw.circle(screen, col, (hx, hy), big)
        pygame.draw.circle(screen, (10, 10, 14), (hx, hy), 3)
        if is_sel:
            pygame.draw.circle(screen, GOLD, (hx, hy), big + 3, 1)
        if hov or is_sel:
            tip = font_tiny.render(f"{p[0]:.3f}, {p[1]:.3f}", True, TEXT_MAIN)
            screen.blit(tip, (min(hx + 12, grect.right - tip.get_width() - 4), max(hy - 24, grect.y + 4)))

    # ---------- bottom strip: point editor + live jab preview ----------
    bot_y = grect.bottom + 10
    sel2 = modal.get("_ec_sel")
    has_sel = sel2 is not None and 0 <= sel2 < len(pts)
    screen.blit(font_tiny.render("POINT", True, TEXT_FAINT), (mx0, bot_y + 6))
    if has_sel and focus is None:
        modal["ec_point_t"] = f"{pts[sel2][0]:.3f}"
        modal["ec_point_v"] = f"{pts[sel2][1]:.3f}"
    pt_t_r = pygame.Rect(mx0 + 46, bot_y - 2, 74, 26)
    pt_v_r = pygame.Rect(mx0 + 130, bot_y - 2, 74, 26)
    if has_sel:
        draw_text_field(pt_t_r, modal.get("ec_point_t", ""), "T", focus == "ec_point_t")
        draw_text_field(pt_v_r, modal.get("ec_point_v", ""), "V", focus == "ec_point_v")
    else:
        ui_draw_rect(screen, FIELD_BG, pt_t_r, border_radius=6)
        ui_draw_rect(screen, FIELD_BG, pt_v_r, border_radius=6)
        screen.blit(font_tiny.render("select a point", True, TEXT_FAINT), (pt_t_r.x, pt_t_r.y + 7))
    if has_sel:
        if pt_t_r.collidepoint(mouse_pos) and clicked:
            modal["ec_point_t"] = f"{pts[sel2][0]:.3f}"
            modal["focus"] = "ec_point_t"
        if pt_v_r.collidepoint(mouse_pos) and clicked:
            modal["ec_point_v"] = f"{pts[sel2][1]:.3f}"
            modal["focus"] = "ec_point_v"
    delpt_r = pygame.Rect(mx0 + 212, bot_y - 2, 78, 26)
    can_del = has_sel and 0 < sel2 < len(pts) - 1 and len(pts) > 2
    draw_button(delpt_r, "Del Pt", delpt_r.collidepoint(mouse_pos) and can_del, small=True, danger=True)
    if can_del and delpt_r.collidepoint(mouse_pos) and clicked:
        _push_undo()
        pts.pop(sel2)
        modal["_ec_sel"] = None
        modal["focus"] = None
        save_easing_curves()

    pv_x = mx0 + 310
    screen.blit(font_tiny.render(f"JAB PREVIEW (44px) · mode {seg_mode}", True, TEXT_FAINT), (pv_x, bot_y + 6))
    bar = pygame.Rect(pv_x, bot_y + 20, 200, 20)
    ui_draw_rect(screen, FIELD_BG, bar, border_radius=8)
    ui_draw_rect(screen, PANEL_BORDER, bar, width=1, border_radius=8)
    fist_x = int(bar.x + 6 + max(0.0, min(1.25, eased_now)) / 1.25 * (bar.width - 30))
    ui_draw_rect(screen, ACCENT, (fist_x, bar.y + 3, 16, 14), border_radius=4)
    ui_draw_rect(screen, ACCENT_HOVER, (fist_x, bar.y + 3, 16, 14), width=2, border_radius=4)
    screen.blit(font_sm.render(f"t={phase:.2f} v={eased_now:.2f}", True, TEXT_DIM), (bar.right + 10, bar.y + 3))

    undo_txt = font_tiny.render(f"undo {len(modal.get('_ec_undo', []))} | redo {len(modal.get('_ec_redo', []))} | {len(pts)} pts", True, TEXT_FAINT)
    screen.blit(undo_txt, (panel_rect.right - 16 - undo_txt.get_width(), bot_y + 6))

    # click-away commits text fields, like professional editors do
    if clicked and focus is not None:
        if focus == "ec_rename":
            if not pygame.Rect(row0.x, row0.y - 3, 320, 30).collidepoint(mouse_pos):
                _commit_rename()
        elif focus in ("ec_point_t", "ec_point_v"):
            if not (pt_t_r.collidepoint(mouse_pos) or pt_v_r.collidepoint(mouse_pos)):
                _commit_point_fields()

    footer = font_tiny.render(f"click curve adds key | drag moves (Alt = free, no snap) | Shift+click/Del removes | arrows nudge | Ctrl+Z/Y undo/redo | name field: Enter apply | {_scene_shortcut_label('easing_editor')}/ESC close", True, TEXT_FAINT)
    screen.blit(footer, (px, panel_rect.bottom - 20))

    # swallow clicks that land on this panel so nothing underneath reacts
    if left_click_this_frame and panel_rect.collidepoint(mouse_pos):
        left_click_this_frame = False

# ============================================================================
# ASSET LIBRARY (F10) - folder organization for Motion Clips + sprite assets
# ============================================================================
SPRITE_FOLDERS = {}           # rel_path -> virtual folder name
SPRITE_FOLDERS_LOADED = False
_AL_THUMBS = {}
_AL_PIXELART = {}   # rel -> bool, cached so the library grid/preview pick the right scaler
_AL_THUMB_CACHE_SCALED = {}
_AL_META_CACHE = {}

def _sprite_folders_path():
    return _cfg_path("settings", "sprite_folders.json")

def load_sprite_folders():
    global SPRITE_FOLDERS_LOADED
    SPRITE_FOLDERS.clear()
    try:
        if os.path.isfile(_sprite_folders_path()):
            with open(_sprite_folders_path(), "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                for k, v in data.items():
                    # 160 chars: folder names are now nested paths, and 48
                    # would silently truncate a few levels of nesting.
                    SPRITE_FOLDERS[str(k)] = str(v)[:160]
    except Exception as e:
        push_toast(f"Could not load sprite folders: {e}", "warning")
    SPRITE_FOLDERS_LOADED = True

def save_sprite_folders():
    try:
        if "asset_library_view_invalidate" in globals():asset_library_view_invalidate()
        with open(_sprite_folders_path(), "w", encoding="utf-8") as f:
            json.dump(SPRITE_FOLDERS, f, indent=1)
    except Exception as e:
        push_toast(f"Could not save sprite folders: {e}", "warning")

def sprite_folder_of(rel):
    """Virtual folder override wins; otherwise the real subfolder path."""
    rel = str(rel)
    if rel in SPRITE_FOLDERS:
        return SPRITE_FOLDERS[rel]
    d = os.path.dirname(rel).replace(os.sep, "/")
    return d if d != "_imported" else "imported"

# ══════════════════════════════════════════════════════════════════════════
# NESTED FOLDER HIERARCHY
# ══════════════════════════════════════════════════════════════════════════
# Folders were a flat list: every folder rendered as one row, so a library
# with 40 folders meant scrolling past all 40 to reach anything. Folder names
# are now PATHS ("characters/enemies/boss"), which the sidebar renders as a
# collapsible tree -- same idea as Godot's FileSystem dock. Existing flat
# names keep working unchanged; they're simply depth-1 paths.

def folder_path_parts(path):
    return [p for p in str(path or "").replace("\\", "/").split("/") if p]

def folder_path_norm(path):
    return "/".join(folder_path_parts(path))[:160]

def folder_path_parent(path):
    parts = folder_path_parts(path)
    return "/".join(parts[:-1]) if len(parts) > 1 else ""

def folder_path_leaf(path):
    parts = folder_path_parts(path)
    return parts[-1] if parts else ""

def folder_tree_rows(all_paths, collapsed, extra=()):
    """Flatten a set of folder paths into visible tree rows.

    Returns [(path, depth, leaf_label, has_children, is_collapsed, own_count_key)].
    Intermediate folders are synthesised even when nothing is filed directly
    under them, so "a/b/c" always shows a, then b, then c -- you can never end
    up with an orphaned leaf whose parents don't exist.
    """
    nodes = set()
    for p in list(all_paths) + list(extra):
        p = folder_path_norm(p)
        if not p:
            continue
        parts = folder_path_parts(p)
        for i in range(1, len(parts) + 1):
            nodes.add("/".join(parts[:i]))
    kids = {}
    for p in nodes:
        kids.setdefault(folder_path_parent(p), []).append(p)
    for k in kids:
        kids[k].sort(key=lambda s: folder_path_leaf(s).lower())

    rows = []

    def walk(parent, depth):
        for p in kids.get(parent, []):
            has_kids = bool(kids.get(p))
            is_col = p in collapsed
            rows.append((p, depth, folder_path_leaf(p), has_kids, is_col))
            if has_kids and not is_col:
                walk(p, depth + 1)

    walk("", 0)
    return rows

def folder_matches(item_folder, sel_folder):
    """True when an item belongs to sel_folder or any folder beneath it.

    Selecting a parent shows everything in the whole subtree, which is what
    makes the hierarchy useful rather than just decorative.
    """
    if not sel_folder:
        return True
    a = folder_path_norm(item_folder)
    b = folder_path_norm(sel_folder)
    return a == b or a.startswith(b + "/")

def set_sprite_folder(rel, folder):
    rel = str(rel)
    folder = folder_path_norm(folder)
    # ── REAL filesystem move ───────────────────────────────────────────────────
    # Dragging an asset onto a folder physically moves the file into that
    # real directory so the library matches the file explorer. On collision
    # (or when the file has no on-disk location) it falls back to the
    # virtual-only filing.
    try:
        _src_file = os.path.join(SPRITES_DIR, rel.replace("/", os.sep))
        if os.path.isfile(_src_file):
            _dst_dir = _sprite_fs_path(folder)
            _dst_file = os.path.join(_dst_dir, os.path.basename(rel))
            if os.path.abspath(_src_file) != os.path.abspath(_dst_file):
                if os.path.exists(_dst_file):
                    push_toast(f"A file named '{os.path.basename(rel)}' already exists there; filed in the library only.", "warning", 4.0)
                else:
                    os.makedirs(_dst_dir, exist_ok=True)
                    shutil.move(_src_file, _dst_file)
                    _new_rel = os.path.relpath(_dst_file, SPRITES_DIR).replace(os.sep, "/")
                    _sprite_disk_move_cleanup(rel)
                    # The physical path now speaks for itself.
                    SPRITE_FOLDERS.pop(rel, None)
                    SPRITE_FOLDERS.pop(_new_rel, None)
                    save_sprite_folders()
                    return
    except Exception as _e:
        try:
            push_toast(f"Disk move failed, filed in the library only: {_e}", "warning", 3.0)
        except Exception:
            pass
    if folder:
        SPRITE_FOLDERS[rel] = folder
    else:
        SPRITE_FOLDERS.pop(rel, None)
    save_sprite_folders()

def _sprite_fs_path(folder):
    """Real on-disk path for a library folder ('' = SPRITES_DIR root)."""
    return os.path.join(SPRITES_DIR, *folder_path_parts(folder)) if folder_path_norm(folder) else SPRITES_DIR


def _sprite_disk_move_cleanup(old_path):
    """After physically moving sprites on disk, drop every cache entry that
    still references the old location so thumbnails, previews and loaded
    images re-resolve from the new path."""
    try:
        old_path = str(old_path).replace("\\", "/")
        for _k in list(_asset_cache.keys()):
            _k2 = str(_k).replace("\\", "/")
            if _k2 == old_path or _k2.startswith(old_path + "/"):
                _asset_cache.pop(_k, None)
        try:
            _SPRITE_ASSET_CACHE["list"] = None
            _SPRITE_ASSET_CACHE["time"] = 0.0
        except Exception:
            pass
        invalidate_sprite_asset_cache()
    except Exception:
        pass


def rename_sprite_folder(old, new_path, absolute=False):
    """Rename a folder (and re-key every sprite filed under it or its
    sub-folders). new_path may be a bare leaf (kept at the same depth) or a
    full path; absolute=True forces bare leaves to mean a ROOT-level path
    (needed when dragging a nested folder onto the root/'All Assets' row)."""
    old = folder_path_norm(old)
    if absolute or "/" in str(new_path):
        new_path = folder_path_norm(new_path)
    else:
        new_path = folder_path_norm((folder_path_parent(old) + "/" + str(new_path)) if folder_path_parent(old) else str(new_path))
    if not old or old == new_path:
        return False
    # Moving a folder inside itself would orbit forever ("a" -> "a/b/a").
    if new_path == old or new_path.startswith(old + "/"):
        return False
    # ── REAL filesystem move ──────────────────────────────────────────────────
    # The library is not just a visual layer: moving a folder into another
    # folder also moves the actual directory in the file explorer.
    _src_disk = _sprite_fs_path(old)
    _dst_disk = _sprite_fs_path(new_path)
    _moved_phys = False

    def _merge_dir_into(src_dir, dst_dir):
        """Recursively merge src_dir into dst_dir, then remove the emptied
        source tree. Name collisions rename with a _moved suffix instead of
        aborting mid-way — a partial move was exactly the 'empty shell
        folder left behind' bug: shutil.move raised on the first collision,
        the loop stopped, and the half-emptied source directory stayed on
        disk AND in the folder tree."""
        os.makedirs(dst_dir, exist_ok=True)
        for _name in os.listdir(src_dir):
            _s_item = os.path.join(src_dir, _name)
            _d_item = os.path.join(dst_dir, _name)
            if os.path.isdir(_s_item) and os.path.isdir(_d_item):
                _merge_dir_into(_s_item, _d_item)
            else:
                if os.path.exists(_d_item):
                    _b2, _x2 = os.path.splitext(_name)
                    _n2 = 1
                    while os.path.exists(os.path.join(dst_dir, f"{_b2}_moved{_n2 if _n2 > 1 else ''}{_x2}")):
                        _n2 += 1
                    _d_item = os.path.join(dst_dir, f"{_b2}_moved{_n2 if _n2 > 1 else ''}{_x2}")
                shutil.move(_s_item, _d_item)
        # Source should be empty now — take the whole (possibly nested) shell away.
        try:
            os.rmdir(src_dir)
        except OSError:
            # Something undeletable is still inside; leave it, never crash.
            pass

    try:
        if os.path.isdir(_src_disk) and os.path.abspath(_src_disk) != os.path.abspath(_dst_disk):
            if os.path.isdir(_dst_disk):
                # Target folder already exists: merge the contents in and
                # remove the emptied source folder (recursively).
                _merge_dir_into(_src_disk, _dst_disk)
                _moved_phys = True
            elif os.path.exists(_dst_disk):
                raise OSError("a file with that name already exists there")
            else:
                os.makedirs(os.path.dirname(_dst_disk), exist_ok=True)
                shutil.move(_src_disk, _dst_disk)
                _moved_phys = True
    except Exception as _e:
        try:
            push_toast(f"Folder renamed in the library, but the disk folder could not be moved: {_e}", "warning", 4.0)
        except Exception:
            pass
    if _moved_phys:
        _sprite_disk_move_cleanup(old)
    changed = False
    for rel, fld in list(SPRITE_FOLDERS.items()):
        f = folder_path_norm(fld)
        rel_n = folder_path_norm(rel)
        is_self_entry = (rel_n == f)   # folder placeholder made by "New Folder"
        # 1) SELF-ENTRIES keyed at/under the moved path re-key to the new path.
        #    Leaving them at the old key was the "empty shell folder stays in
        #    the tree" bug: the placeholder kept regenerating the old branch.
        if is_self_entry and (rel_n == old or rel_n.startswith(old + "/")):
            new_key = new_path if rel_n == old else folder_path_norm(new_path + rel_n[len(old):])
            SPRITE_FOLDERS.pop(rel, None)
            SPRITE_FOLDERS[new_key] = new_key
            changed = True
            continue
        # 2) ASSET filings whose VALUE points into the moved subtree follow it.
        if f == old:
            SPRITE_FOLDERS[rel] = new_path
            changed = True
        elif f.startswith(old + "/"):
            SPRITE_FOLDERS[rel] = folder_path_norm(new_path + f[len(old):])
            changed = True
        # 3) ASSET keys whose FILE physically travelled with the directory are
        #    dangling: their rel path no longer exists on disk. Drop them, the
        #    new physical location speaks for itself. Keeping them resurrected
        #    the old folder branch through sprite_folder_of()'s dirname logic.
        if _moved_phys and not is_self_entry and rel_n.startswith(old + "/"):
            if not os.path.isfile(os.path.join(SPRITES_DIR, rel.replace("/", os.sep))):
                SPRITE_FOLDERS.pop(rel, None)
                changed = True
    if changed or _moved_phys:
        save_sprite_folders()
        # Re-scan the sprite index NOW: the async TTL cache kept serving the
        # pre-move paths, so the old folder looked like it survived (an empty
        # shell) until some later background rescan.
        try:
            list_sprite_assets(force=True)
        except Exception:
            pass
    return bool(changed or _moved_phys)

def delete_sprite_folder(path):
    """Delete a virtual folder: its sprites (and sub-folders' sprites) are
    re-filed to the parent folder so nothing is orphaned."""
    path = folder_path_norm(path)
    if not path:
        return False
    parent = folder_path_parent(path)
    # ── REAL filesystem refile ──────────────────────────────────────────────────
    # Deleting a folder never deletes artwork: like the virtual filing, its
    # real files and sub-folders move up to the parent directory on disk.
    try:
        _src_disk = _sprite_fs_path(path)
        if os.path.isdir(_src_disk):
            _dst_dir = _sprite_fs_path(parent)
            os.makedirs(_dst_dir, exist_ok=True)
            for _name in os.listdir(_src_disk):
                _s_item = os.path.join(_src_disk, _name)
                _d_item = os.path.join(_dst_dir, _name)
                try:
                    if os.path.isdir(_d_item):
                        # merge sub-folder contents (never overwrite files)
                        for _sub in os.listdir(_s_item):
                            _s_sub = os.path.join(_s_item, _sub)
                            if not os.path.exists(os.path.join(_d_item, _sub)):
                                shutil.move(_s_sub, _d_item)
                        try:
                            os.rmdir(_s_item)
                        except OSError:
                            pass
                    elif os.path.exists(_d_item):
                        pass
                    else:
                        shutil.move(_s_item, _d_item)
                except Exception:
                    pass
            try:
                os.rmdir(_src_disk)
            except OSError:
                pass
            _sprite_disk_move_cleanup(path)
    except Exception:
        pass
    for rel, fld in list(SPRITE_FOLDERS.items()):
        f = folder_path_norm(fld)
        if f == path:
            if rel == path:
                SPRITE_FOLDERS.pop(rel, None)
            else:
                SPRITE_FOLDERS[rel] = parent
        elif f.startswith(path + "/"):
            sub = folder_path_norm((parent + f[len(path):]) if parent else f[len(path)+1:])
            if rel == f:
                SPRITE_FOLDERS.pop(rel, None)
                if sub: SPRITE_FOLDERS[sub] = sub
            else:
                SPRITE_FOLDERS[rel] = parent
    save_sprite_folders()
    return True

def rename_folder(tab, old, new_path, absolute=False):
    """Tab-aware folder rename. Sprites live in SPRITE_FOLDERS; motion clips
    store their folder directly on each clip, so the rename must touch both
    kinds of storage depending on the active tab.

    absolute=True treats a bare-leaf new_path as a FULL path from the root
    (used by drag-to-move). Without it a slash-less name means "rename in
    place at the same depth", which silently no-opped every drag of a nested
    folder onto the root row."""
    tab = str(tab)
    old = folder_path_norm(old)
    if absolute or "/" in str(new_path):
        new_path = folder_path_norm(new_path)
    else:
        new_path = folder_path_norm((folder_path_parent(old) + "/" + str(new_path)) if folder_path_parent(old) else str(new_path))
    if not old or old == new_path:
        return False
    if tab == "motion":
        changed = False
        for c in MOTION_CLIPS.values():
            f = folder_path_norm(c.get("folder", "") or "")
            if f == old:
                c["folder"] = new_path; changed = True
            elif f.startswith(old + "/"):
                c["folder"] = folder_path_norm(new_path + f[len(old):]); changed = True
        if changed:
            save_motion_clips()
        return changed
    # new_path is already fully normalized here; always absolute downstream
    # (a bare leaf like "kid" must mean the ROOT, not same-depth rename).
    return rename_sprite_folder(old, new_path, absolute=True)

def delete_folder(tab, path):
    """Tab-aware folder delete: re-file contents (and sub-folders) to parent."""
    tab = str(tab)
    path = folder_path_norm(path)
    if not path:
        return False
    if tab == "motion":
        parent = folder_path_parent(path)
        for c in MOTION_CLIPS.values():
            f = folder_path_norm(c.get("folder", "") or "")
            if f == path or f.startswith(path + "/"):
                c["folder"] = parent
        save_motion_clips()
        return True
    return delete_sprite_folder(path)

def _al_get_thumb_cached(rel, tw, th):
    key = (str(rel), int(tw), int(th))
    surf = _AL_THUMB_CACHE_SCALED.get(key)
    if surf is None:
        # Inside the Asset Library only, misses spend from the per-frame
        # streaming budget (reset by draw_asset_library): cards whose budget
        # is gone draw their placeholder this frame and fill in next frame.
        if modal.get("type") == "asset_library":
            _bud = modal.get("_al_thumb_budget")
            if _bud is not None:
                _thumb_now=time.perf_counter();_deadline=modal.get("_al_thumb_deadline")
                if _deadline is None:
                    _deadline=_thumb_now+.010;modal["_al_thumb_deadline"]=_deadline
                if _bud[0]<=0 or _thumb_now>float(_deadline):
                    modal["_al_had_thumb_miss"]=True;_ASSET_LIBRARY_FRAME_CACHE["pending"]=True;return None
                _bud[0]-=1
        img = load_sprite_asset(rel)
        if img is not None:
            w2, h2 = img.get_width(), img.get_height()
            sc = min(float(tw) / max(1, w2), float(th) / max(1, h2), 4.0)
            nw, nh = max(1, int(round(w2 * sc))), max(1, int(round(h2 * sc)))
            upscale = (nw > w2 or nh > h2)
            method = (pygame.transform.scale if (upscale or _al_is_pixelart(rel))
                      else pygame.transform.smoothscale)
            try:
                surf = method(img, (nw, nh))
            except Exception:
                surf = False
        else:
            surf = False
        _AL_THUMB_CACHE_SCALED[key] = surf
        if len(_AL_THUMB_CACHE_SCALED) > 1024:
            _AL_THUMB_CACHE_SCALED.pop(next(iter(_AL_THUMB_CACHE_SCALED)))
    return surf if surf is not False else None

def _al_get_file_size_cached(rel):
    key=str(rel);meta=_AL_META_CACHE.get(key)
    if meta is None:
        try:
            fullp=os.path.join(SPRITES_DIR,key.replace("/",os.sep));fz=os.path.getsize(fullp);mtime=os.path.getmtime(fullp);fzs=f"{fz//1024} KB" if fz<1024*1024 else f"{fz//1048576} MB"
        except Exception:fz=0;fzs="";mtime=0.0
        meta={"size_bytes":fz,"size_str":fzs,"modified_time":mtime,"modified_str":time.strftime("%Y-%m-%d  %H:%M",time.localtime(mtime)) if mtime else "","w":0,"h":0,"dim_str":"","type_str":"","_dimensions_ready":False}
        _AL_META_CACHE[key]=meta
        if len(_AL_META_CACHE)>1024:_AL_META_CACHE.pop(next(iter(_AL_META_CACHE)))
    return meta


def _al_get_file_meta_cached(rel):
    key=str(rel);meta=_al_get_file_size_cached(key)
    if not meta.get("_dimensions_ready",False):
        img=load_sprite_asset(key)
        if img:
            w,h=img.get_width(),img.get_height();meta.update({"w":w,"h":h,"dim_str":f"{w} × {h} px","type_str":"Pixel Art (Sharp)" if _al_is_pixelart(key) else "Smooth HD Art","_dimensions_ready":True})
        else:
            meta.update({"w":0,"h":0,"dim_str":"Unknown","type_str":"Could not decode","_dimensions_ready":True})
    return meta

def _draw_filled_star(surf, cx, cy, rad, col):
    """Draw a crisp, filled 10-point polygon star at screen coordinates (cx, cy)."""
    pts = []
    for i in range(10):
        a = math.radians(-90 + i * 36)
        r = rad if (i % 2 == 0) else (rad * 0.45)
        pts.append((cx + math.cos(a) * r, cy + math.sin(a) * r))
    pygame.draw.polygon(surf, col, pts)

def _al_thumb(rel):
    return _al_get_thumb_cached(rel, 52, 52)

def _al_is_pixelart(rel):
    """Cached pixel-art flag for a library sprite."""
    rel = str(rel)
    v = _AL_PIXELART.get(rel)
    if v is None:
        v = _sprite_is_pixelart(load_sprite_asset(rel))
        _AL_PIXELART[rel] = v
        if len(_AL_PIXELART) > 512:
            _AL_PIXELART.pop(next(iter(_AL_PIXELART)))
    return v

def _al_scale_sprite(src, tw, th, rel=None):
    """Scale a sprite to (tw,th), picking nearest-neighbour for pixel art / upscaling."""
    if src is None:
        return None
    if rel:
        res = _al_get_thumb_cached(rel, tw, th)
        if res: return res
    upscale = (tw > src.get_width() or th > src.get_height())
    pixelart = _al_is_pixelart(rel) if rel else _sprite_is_pixelart(src)
    method = pygame.transform.scale if (upscale or pixelart) else pygame.transform.smoothscale
    try:
        return method(src, (max(1, int(tw)), max(1, int(th))))
    except Exception:
        return None

