def _al_audio_folder_of(asset):
    # Pure string operation: never call commonpath/stat from the draw loop.
    path=str(asset.get("path","") or "").replace("\\","/").strip("/")
    marker="audio/_imported/"
    low=path.lower();idx=low.find(marker)
    if idx>=0:
        tail=path[idx+len(marker):];folder=tail.rsplit("/",1)[0] if "/" in tail else ""
        return folder_path_norm(folder)
    return folder_path_norm(asset.get("folder","") or "")

def _al_audio_index():
    key=(_AL_AUDIO_INDEX_GEN[0],len(AUDIO_LIBRARY))
    if _AL_AUDIO_INDEX_CACHE.get("key")==key:return _AL_AUDIO_INDEX_CACHE
    byid={};folders=set();counts={"":len(AUDIO_LIBRARY)}
    for asset in AUDIO_LIBRARY:
        folder=_al_audio_folder_of(asset);byid[asset.get("id")]=folder
        if folder:
            parts=folder_path_parts(folder)
            for i in range(1,len(parts)+1):
                parent="/".join(parts[:i]);folders.add(parent);counts[parent]=counts.get(parent,0)+1
    _AL_AUDIO_INDEX_CACHE.update({"key":key,"folder_by_id":byid,"folders":sorted(folders,key=lambda x:(x.count("/"),x.lower())),"counts":counts})
    return _AL_AUDIO_INDEX_CACHE


def _al_audio_wave(asset, count=64):
    """Zero-I/O card waveform. Audio decoding is allowed only after Preview is
    clicked; modal drawing itself must stay under the frame budget."""
    key=(str(asset.get("path","")),int(count));cached=_AL_AUDIO_WAVE_CACHE.get(key)
    if cached is not None:return cached
    seed=int(hashlib.sha1(key[0].encode()).hexdigest()[:8],16)
    peaks=[]
    for i in range(count):
        envelope=.45+.45*math.sin(math.pi*i/max(1,count-1))
        v=.12+abs(math.sin(seed*.00013+i*.73)+.45*math.sin(seed*.00031+i*2.17))*.32*envelope
        peaks.append(min(1.,v))
    _AL_AUDIO_WAVE_CACHE[key]=peaks
    if len(_AL_AUDIO_WAVE_CACHE)>512:_AL_AUDIO_WAVE_CACHE.pop(next(iter(_AL_AUDIO_WAVE_CACHE)))
    return peaks


def _al_audio_file_meta(asset):
    path=str(asset.get("path","") or "");full=abs_from_base(path)
    try:stamp=(os.path.getmtime(full),os.path.getsize(full)) if full and os.path.isfile(full) else (0,0)
    except Exception:stamp=(0,0)
    key=(path,stamp);hit=_AL_AUDIO_META_CACHE.get(key)
    if hit is not None:return hit
    # No audio decode here. Duration is filled lazily only when previewed;
    # listing/scrolling remains filesystem-metadata-only.
    hit={"size":stamp[1],"duration":asset.get("duration",None)};_AL_AUDIO_META_CACHE[key]=hit
    if len(_AL_AUDIO_META_CACHE)>512:_AL_AUDIO_META_CACHE.pop(next(iter(_AL_AUDIO_META_CACHE)))
    return hit


