    modal["_al_thumb_budget"]=[8 if int(modal.get("_al_grid_sz",130))<=80 else 4]
    modal["_al_thumb_deadline"]=None

    keys = pygame.key.get_pressed()
    _kp = modal.setdefault("_al_kprev", {})
    def _edge(kc):
        n = bool(keys[kc]); w = _kp.get(kc, False); _kp[kc] = n; return n and not w

    _mb = pygame.mouse.get_pressed()
    _lmb = _mb[0]; _rmb = _mb[2]
    clicked = bool(left_click_this_frame) or (_lmb and not modal.get("_al_prev_lmb"))
    rclicked = _rmb and not modal.get("_al_prev_rmb")
    _rename_clicked=clicked;_ctx_clicked=clicked
    # Floating context/docker menus own the click BEFORE folder/cards behind
