        _parts = max(2, min(128, int(modal.get("_ms_split_count", 3) or 3)))
        _set_show("ms_ev_split_count", str(_parts))
        _field(pygame.Rect(rx + 10, ly2, 42, 22), "ms_ev_split_count", "3")
        screen.blit(font_tiny.render("parts", True, TEXT_DIM), (rx + 55, ly2+5))
        _split_r = pygame.Rect(rx + 91, ly2, 92, 22)
        if _btn(_split_r, f"Split ×{_parts}"):
            _duration = max(0.0, float(ev.get("dur", 0.0)))
            if _duration > 0.0:
                _push_undo(); _piece = _duration / _parts
                _pos = clip["events"].index(ev)
                _new_events = []
                for _si in range(_parts):
                    _dup = copy.deepcopy(ev); _dup["frame"] = float(ev.get("frame",0)) + _piece*_si; _dup["dur"] = _piece
                    _dup["name"] = f"{str(ev.get('name','hit'))}_{_si+1}"; _dup["hit_mode"] = "once"; _new_events.append(_dup)
                clip["events"][_pos:_pos+1] = _new_events; modal["_ms_sel_e"] = _pos; save_motion_clips()
            else: push_toast("Set an event duration above 0 before splitting.", "warning", 2.0)
        _mode = str(ev.get("hit_mode", "once")); _mode_r = pygame.Rect(rx+188, ly2, 98, 22)
        if _btn(_mode_r, "Hits: " + _mode.replace("_", " ")):
            _order=("once","interval","every_frame"); _push_undo(); ev["hit_mode"]=_order[(_order.index(_mode)+1)%len(_order)] if _mode in _order else "once"; save_motion_clips()
        ly2 += 26
        if str(ev.get("hit_mode", "once")) == "interval":
            _set_show("ms_ev_hit_interval", f"{float(ev.get('hit_interval_frames',1)):g}")
            _field(pygame.Rect(rx + 126, ly2, 64, 22), "ms_ev_hit_interval", "")
            screen.blit(font_tiny.render("re-hit every", True, TEXT_DIM), (rx+10, ly2+5))
            screen.blit(font_tiny.render("frames", True, TEXT_FAINT), (rx+194, ly2+5))
            ly2 += 26
        screen.blit(font_tiny.render("Type any split count (2–128) · split = separate one-hit beats.", True, TEXT_FAINT), (rx+10,ly2)); ly2 += 16
        screen.blit(font_tiny.render("damage · knockback · team · lifesteal · lunge", True, TEXT_FAINT), (rx + 10, ly2)); ly2 += 12
        screen.blit(font_tiny.render("repeat · tag · sound · impact VFX = Motion Events nodes", True, TEXT_FAINT), (rx + 10, ly2)); ly2 += 18
        if _btn(pygame.Rect(rx + 184, ly2, 102, 22), "Duplicate Event"):
            _push_undo()
            _copy_ev = copy.deepcopy(ev); _copy_ev["frame"] = float(ev.get("frame", 0)) + max(1.0, float(ev.get("dur", 0)))
            _copy_ev["name"] = str(ev.get("name", "event")) + "_copy"
            clip.setdefault("events", []).append(_copy_ev); clip["events"].sort(key=lambda e: float(e.get("frame", 0))); modal["_ms_sel_e"] = clip["events"].index(_copy_ev); save_motion_clips()
        if _btn(pygame.Rect(rx + 10, ly2, 170, 22), "Delete Event (Del)", danger=True):
            _push_undo()
