def _vi_curve(surf, s, c):
    # axes + smooth S-curve with endpoint dots (easing editor)
    w = max(1, int(s*.08))
    pygame.draw.line(surf, c, (s*.16, s*.86), (s*.16, s*.14), w)
    pygame.draw.line(surf, c, (s*.16, s*.86), (s*.88, s*.86), w)
    pts = []
    for i in range(25):
        t = i / 24.0
        e = t * t * (3.0 - 2.0 * t)
        pts.append((s*.16 + t * s*.66, s*.86 - e * s*.66))
    pygame.draw.lines(surf, c, False, pts, max(1, int(s*.07)))
    pygame.draw.circle(surf, c, (int(s*.16), int(s*.86)), max(1, int(s*.05)))
    pygame.draw.circle(surf, c, (int(s*.82), int(s*.20)), max(1, int(s*.05)))

