def _vector_icon_surface(name, size, color):
    """Cached hand-drawn icon surface, or a generic fallback glyph for any
    name we don't have a dedicated draw function for -- so missing icons no
    longer render as empty rectangles."""
    key = (str(name), int(size), tuple(color[:3]))
    hit = _VECTOR_ICON_CACHE.get(key, -1)
    if hit != -1:
        return hit
    surf = None
    fn = _VECTOR_ICON_DRAW.get(str(name))
    try:
        sz = max(12, int(size))
        surf = pygame.Surface((sz, sz), pygame.SRCALPHA)
        if fn is not None:
            try:
                fn(surf, float(size), tuple(color[:3]))
            except Exception:
                fn = None  # fall through to generic
        if fn is None:
            # Generic fallback: rounded square with first letter, so every
            # icon slot always has *something* visible instead of a gap/rect.
            col = tuple(color[:3])
            # subtle background disc
            r = sz//2 - 1
            pygame.draw.circle(surf, (*col, 55 if len(col)==3 else col[3] if len(col)==4 else 55),
                               (sz//2, sz//2), r)
            pygame.draw.circle(surf, col, (sz//2, sz//2), r, width=1)
            # letter glyph
            letter = (str(name)[0] if name else "?").upper()
            try:
                lf = pygame.font.SysFont("segoeui,arial,helvetica,sans", max(8, int(sz*0.55)), bold=True)
            except Exception:
                lf = pygame.font.Font(None, max(10, int(sz*0.6)))
            ls = lf.render(letter, True, col)
            surf.blit(ls, (sz//2 - ls.get_width()//2, sz//2 - ls.get_height()//2))
    except Exception:
        surf = None
    _VECTOR_ICON_CACHE[key] = surf
    return surf

def _lucide_path_points(data):
    """Small pure-Python SVG path flattener for Lucide's 24px stroke icons."""
    toks=re.findall(r"[A-Za-z]|[-+]?(?:\d*\.\d+|\d+\.?)(?:[eE][-+]?\d+)?",str(data or ""));i=0;cmd=None;x=y=0.0;sx=sy=0.0;paths=[];pts=[];last_c=None
    def num():
        nonlocal i
        v=float(toks[i]);i+=1;return v
    def flush():
        nonlocal pts
        if len(pts)>1:paths.append(pts)
        pts=[]
    try:
        while i<len(toks):
            if toks[i].isalpha():cmd=toks[i];i+=1
            if not cmd:break
            rel=cmd.islower();op=cmd.upper()
            if op=="Z":
                if pts:pts.append((sx,sy));flush()
                x,y=sx,sy;cmd=None;last_c=None;continue
            if op=="M":
                nx,ny=num(),num();nx=nx+x if rel else nx;ny=ny+y if rel else ny
                if pts:flush()
                x,y=nx,ny;sx,sy=x,y;pts=[(x,y)];cmd="l" if rel else "L";last_c=None;continue
            if not pts:pts=[(x,y)];sx,sy=x,y
            if op=="L":
                nx,ny=num(),num();x=(x+nx if rel else nx);y=(y+ny if rel else ny);pts.append((x,y));last_c=None
            elif op=="H":
                nx=num();x=x+nx if rel else nx;pts.append((x,y));last_c=None
            elif op=="V":
                ny=num();y=y+ny if rel else ny;pts.append((x,y));last_c=None
            elif op=="C":
                x0,y0=x,y;c1x,c1y=num(),num();c2x,c2y=num(),num();nx,ny=num(),num()
                if rel:c1x+=x0;c1y+=y0;c2x+=x0;c2y+=y0;nx+=x0;ny+=y0
                for k in range(1,9):
                    t=k/8;u=1-t;pts.append((u**3*x0+3*u*u*t*c1x+3*u*t*t*c2x+t**3*nx,u**3*y0+3*u*u*t*c1y+3*u*t*t*c2y+t**3*ny))
                x,y=nx,ny;last_c=(c2x,c2y)
            elif op=="S":
                x0,y0=x,y;c1x,c1y=(2*x-(last_c[0] if last_c else x),2*y-(last_c[1] if last_c else y));c2x,c2y=num(),num();nx,ny=num(),num()
                if rel:c2x+=x0;c2y+=y0;nx+=x0;ny+=y0
                for k in range(1,9):
                    t=k/8;u=1-t;pts.append((u**3*x0+3*u*u*t*c1x+3*u*t*t*c2x+t**3*nx,u**3*y0+3*u*u*t*c1y+3*u*t*t*c2y+t**3*ny))
                x,y=nx,ny;last_c=(c2x,c2y)
            elif op=="Q":
                x0,y0=x,y;cx,cy=num(),num();nx,ny=num(),num()
                if rel:cx+=x0;cy+=y0;nx+=x0;ny+=y0
                for k in range(1,9):
                    t=k/8;u=1-t;pts.append((u*u*x0+2*u*t*cx+t*t*nx,u*u*y0+2*u*t*cy+t*t*ny))
                x,y=nx,ny;last_c=(cx,cy)
            elif op=="T":
                x0,y0=x,y;cx,cy=(2*x-(last_c[0] if last_c else x),2*y-(last_c[1] if last_c else y));nx,ny=num(),num()
                if rel:nx+=x0;ny+=y0
                for k in range(1,9):
                    t=k/8;u=1-t;pts.append((u*u*x0+2*u*t*cx+t*t*nx,u*u*y0+2*u*t*cy+t*t*ny))
                x,y=nx,ny;last_c=(cx,cy)
            elif op=="A":
                # Lucide arcs are decorative portions of stroked outlines. The
                # endpoint segment remains recognizable without a native SVG DLL.
                _rx,_ry,_rot,_large,_sweep,nx,ny=num(),num(),num(),num(),num(),num(),num()
                if rel:nx+=x;ny+=y
                x,y=nx,ny;pts.append((x,y));last_c=None
            else:break
    except (ValueError,IndexError,TypeError):pass
    if len(pts)>1:paths.append(pts)
    return paths


def _lucide_icon_surface(name,size,color,stroke=1.8):
    if not _LUCIDE_AVAILABLE or not isinstance(name,str):return None
    lname=_LUCIDE_NAME_MAP.get(name,name.lower().replace("_","-"));key=(lname,int(size),tuple(color[:3]),round(float(stroke),2));hit=_LUCIDE_ICON_CACHE.get(key,-1)
    if hit!=-1:return hit
    # Disk cache: Lucide had none, so a phone (or any machine without
    # pytablericons) could never build a harvestable icon cache.
    surf=icon_lucide_cached(lname,int(size),color,stroke,lambda:_lucide_render(lname,size,color,stroke))
    _LUCIDE_ICON_CACHE[key]=surf;return surf


def _lucide_render(lname,size,color,stroke=1.8):
    surf=None
    try:
        root=_lucide_load_icon(lname);aa=3;sz=max(12,int(size));work=pygame.Surface((sz*aa,sz*aa),pygame.SRCALPHA);scale=sz*aa/24.0;col=tuple(color[:3]);width=max(1,round(float(stroke)*scale))
        def pt(x,y):return (round(float(x)*scale),round(float(y)*scale))
        for node in root.iter():
            tag=str(node.tag).split("}")[-1];a=node.attrib
            if tag=="line":pygame.draw.line(work,col,pt(a.get("x1",0),a.get("y1",0)),pt(a.get("x2",0),a.get("y2",0)),width)
            elif tag in ("polyline","polygon"):
                vals=[float(v) for v in re.findall(r"[-+]?\d*\.?\d+",a.get("points",""))];points=[pt(vals[j],vals[j+1]) for j in range(0,len(vals)-1,2)]
                if len(points)>1:pygame.draw.lines(work,col,tag=="polygon",points,width)
            elif tag=="rect":
                r=pygame.Rect(round(float(a.get("x",0))*scale),round(float(a.get("y",0))*scale),max(1,round(float(a.get("width",0))*scale)),max(1,round(float(a.get("height",0))*scale)));pygame.draw.rect(work,col,r,width,border_radius=max(0,round(float(a.get("rx",0))*scale)))
            elif tag=="circle":pygame.draw.circle(work,col,pt(a.get("cx",0),a.get("cy",0)),max(1,round(float(a.get("r",0))*scale)),width)
            elif tag=="ellipse":
                cx,cy=float(a.get("cx",0)),float(a.get("cy",0));rx,ry=float(a.get("rx",0)),float(a.get("ry",0));pygame.draw.ellipse(work,col,pygame.Rect(round((cx-rx)*scale),round((cy-ry)*scale),max(1,round(rx*2*scale)),max(1,round(ry*2*scale))),width)
            elif tag=="path":
                for path in _lucide_path_points(a.get("d","")):
                    points=[pt(x,y) for x,y in path]
                    if len(points)>1:pygame.draw.lines(work,col,points[-1]==points[0],points,width)
        surf=pygame.transform.smoothscale(work,(sz,sz)) if aa>1 else work
    except Exception:surf=None
    return surf

def get_icon_fs(name, size=18, color=(240, 240, 246), stroke=1.8):
    """Icon lookup that ALWAYS renders: Tabler PNG first, vector fallback next.

    `name` may be a semantic IC key ("play", "save", ...) or a raw enum; either
    way the caller never has to guard against the icon library being absent.
    """
    if name is None:
        return None
    surf = None
    try:
        enum = (IC or {}).get(str(name)) if isinstance(name, str) else name
        if enum is None and isinstance(name,str) and _TABLER_AVAILABLE and OutlineIcon is not None:
            enum = getattr(OutlineIcon,str(name).upper().replace("-","_").replace(" ","_"),None)
        if enum is not None and _svg_icons_on():
            surf = get_icon(enum, size, color, stroke)
    except Exception:
        surf = None
    if surf is None and isinstance(name,str):surf=_lucide_icon_surface(name,size,color,stroke)
    if surf is None and isinstance(name, str):
        try:surf = icon_semantic_cached(name, size, color, stroke)
        except Exception:surf = None
    if surf is None and isinstance(name, str):
        surf = _vector_icon_surface(name, size, color)
    return surf

def blit_icon_fs(surface, name, cx, cy, size=18, color=(240, 240, 246), stroke=1.8, anchor='center'):
    """Draw and expose an icon as a selectable UI-Studio element."""
    if anchor == 'topleft': rect=pygame.Rect(cx,cy,size,size)
    elif anchor == 'midleft': rect=pygame.Rect(cx,cy-size//2,size,size)
    else: rect=pygame.Rect(cx-size//2,cy-size//2,size,size)
    if "_ui_rect_visible" in globals() and not _ui_rect_visible(rect):return
    key=_modify_register_element("icon",rect,str(name),key=f"icon:{name}") if '_modify_register_element' in globals() else None
    style=_modify_style_by_key(key) if key else {}
    actual=str(style.get("icon",name));actual_size=max(6,min(64,int(style.get("icon_size",size))));actual_color=_style_color(style,"icon_color",color) if style else color
    surf=get_icon_fs(actual,actual_size,actual_color,stroke)
    if surf is None:return
    if style and int(style.get("opacity",255))<255:surf=surf.copy();surf.set_alpha(max(0,min(255,int(style.get("opacity",255)))))
    if anchor=='topleft':surface.blit(surf,(cx,cy))
    elif anchor=='midleft':surface.blit(surf,(cx,cy-actual_size//2))
    else:surface.blit(surf,(cx-actual_size//2,cy-actual_size//2))

