_FULLSCREEN_TRANSITION_UNTIL=0.0

def _display_set_mode(width, height, flags):
    """Wrapper around pygame.display.set_mode that applies the current
    $vsync setting. Falls back to no vsync kwarg if the driver/flag combo
    doesn't support it (some backends only honor vsync with pygame.SCALED
    or a GPU-backed flag set), so this never crashes the window open."""
    want_vsync = 1 if globals().get("SETTINGS", {}).get("vsync", 0) else 0
    try:
        return pygame.display.set_mode((width, height), flags, vsync=want_vsync)
    except Exception:
        return pygame.display.set_mode((width, height), flags)

screen = _display_set_mode(WIDTH, HEIGHT, pygame.RESIZABLE)
# Some Windows/DPI setups hand back an actual client surface that differs
# slightly from the (width, height) just requested -- and don't fire a
# VIDEORESIZE event for that initial adjustment, only for later manual
# drags. If WIDTH/HEIGHT are left holding the requested-not-actual size,
# every layout that positions things off the right/bottom edge (the right
# sidebar included) is computed against the wrong canvas size until some
# later resize event happens to correct it. Resync immediately so this
# never depends on luck/timing.
WIDTH, HEIGHT = screen.get_size()
_WINDOWED_SIZE[:] = [WIDTH, HEIGHT]
pygame.display.set_caption(f"Arena Sim  ·  v{APP_VERSION}")
# Paint solid black immediately so the user never sees a single garbage
# frame (uninitialized backbuffer / previous app's pixels) while we finish
# booting. This is the "fade in from black" the user asked for.
try:
    screen.fill((0, 0, 0))
    pygame.display.flip()
except Exception:
    pass
# ── Image loading helper (handles .ico, which pygame can't load directly) ──
def _load_image_surface(path):
    """Load an image file into a pygame Surface. PNG/JPG/... go through
    pygame.image.load; .ico files are parsed manually (SDL_image has no ICO
    support - that's the old 'Unsupported ICO bitmap format' error). Returns
    None if the file can't be decoded."""
    try:
        ext = os.path.splitext(str(path))[1].lower()
        if ext == ".ico":
            return _load_ico_surface(path)
        return pygame.image.load(path)
    except Exception:
        return None

def _load_ico_surface(path):
    """Parse a Windows .ico file and return the best (largest) image as a
    Surface with per-pixel alpha, or None. Handles both embedded PNG payloads
    (Vista+) and classic DIB (BMP-style) payloads with AND masks."""
    try:
        with open(path, "rb") as f:
            data = f.read()
        if len(data) < 6:
            return None
        count = int.from_bytes(data[4:6], "little")
        if count <= 0:
            return None
        entries = []
        for i in range(count):
            off = 6 + i * 16
            if off + 16 > len(data):
                break
            w = data[off] or 256          # 0 byte means 256px
            h = data[off + 1] or 256
            bpp = int.from_bytes(data[off + 6:off + 8], "little")
            size = int.from_bytes(data[off + 8:off + 12], "little")
            img_off = int.from_bytes(data[off + 12:off + 16], "little")
            if img_off + size <= len(data):
                entries.append((w, h, bpp, size, img_off))
        if not entries:
            return None
        # Prefer the largest image (then highest bit depth).
        entries.sort(key=lambda e: (e[0] * e[1], e[2]), reverse=True)
        for w, h, bpp, size, img_off in entries:
            chunk = data[img_off:img_off + size]
            # PNG-embedded icon (Vista+): just let pygame decode it.
            if chunk[:8] == b"\x89PNG\r\n\x1a\n":
                try:
                    return pygame.image.load(io.BytesIO(chunk))
                except Exception:
                    continue
            try:
                surf = _dib_to_surface(chunk, w, h)
                if surf is not None:
                    return surf
            except Exception:
                continue
    except Exception:
        pass
    return None

def _dib_to_surface(chunk, fallback_w, fallback_h):
    """Convert one classic ICO image entry (BITMAPINFOHEADER + pixels [+ AND
    mask]) into an RGBA Surface. Returns None if the payload isn't a DIB."""
    if len(chunk) < 40:
        return None
    bi_size = int.from_bytes(chunk[0:4], "little")
    if bi_size < 40:
        return None
    width = abs(int.from_bytes(chunk[4:8], "little", signed=True))
    hraw = abs(int.from_bytes(chunk[8:12], "little", signed=True))
    bpp = int.from_bytes(chunk[14:16], "little")
    comp = int.from_bytes(chunk[16:20], "little")
    if width == 0 or hraw == 0:
        # Directory sizes are a fallback if the header is empty.
        width, hraw = fallback_w, fallback_h * 2   # DIB height includes AND mask
    height = hraw // 2 if hraw % 2 == 0 else hraw
    if width <= 0 or height <= 0 or bpp not in (1, 4, 8, 16, 24, 32) or comp != 0:
        return None
    # Palette for indexed bit depths.
    header = bi_size
    palette = []
    if bpp <= 8:
        ncolors = int.from_bytes(chunk[32:36], "little") if len(chunk) >= 36 else 0
        if ncolors == 0:
            ncolors = 1 << bpp
        pal_start = header
        for _i in range(ncolors):
            if pal_start + _i * 4 + 4 > len(chunk):
                break
            b_, g_, r_, _ = chunk[pal_start + _i * 4: pal_start + _i * 4 + 4]
            palette.append((r_, g_, b_))
        header = pal_start + min(ncolors, (len(chunk) - pal_start) // 4) * 4
    row_bytes = ((width * bpp + 31) // 32) * 4
    xor_start = header
    and_start = xor_start + row_bytes * height
    and_row_bytes = ((width + 31) // 32) * 4
    and_avail = and_start + and_row_bytes * height <= len(chunk)

    def _mask_bit(y, x):
        if not and_avail:
            return 0
        off = and_start + (height - 1 - y) * and_row_bytes
        if off + (x // 8) >= len(chunk):
            return 0
        return (chunk[off + x // 8] >> (7 - (x % 8))) & 1

    out = bytearray(width * height * 4)
    p = 0
    any_alpha = False
    for y in range(height):
        src = xor_start + (height - 1 - y) * row_bytes   # DIB rows are bottom-up
        for x in range(width):
            if bpp == 32:
                b_, g_, r_, a_ = chunk[src + x * 4: src + x * 4 + 4]
                if a_:
                    any_alpha = True
                out[p] = r_; out[p + 1] = g_; out[p + 2] = b_; out[p + 3] = a_
            elif bpp == 24:
                b_, g_, r_ = chunk[src + x * 3: src + x * 3 + 3]
                out[p] = r_; out[p + 1] = g_; out[p + 2] = b_; out[p + 3] = 255
            elif bpp == 16:
                v = int.from_bytes(chunk[src + x * 2: src + x * 2 + 2], "little")
                out[p]     = ((v >> 10) & 31) * 255 // 31
                out[p + 1] = ((v >> 5) & 31) * 255 // 31
                out[p + 2] = (v & 31) * 255 // 31
                out[p + 3] = 255
            else:
                bit = x * bpp
                byte = src + bit // 8
                if byte >= len(chunk):
                    out[p + 3] = 255; p += 4; continue
                val = chunk[byte]
                if bpp == 8:
                    idx = val
                elif bpp == 4:
                    idx = (val >> 4) if (bit % 8 == 0) else (val & 15)
                else:  # 1 bpp
                    idx = (val >> (7 - (bit % 8))) & 1
                if idx < len(palette):
                    r_, g_, b_ = palette[idx]
                else:
                    r_ = g_ = b_ = 0
                out[p] = r_; out[p + 1] = g_; out[p + 2] = b_; out[p + 3] = 255
            p += 4
    # Classic icons use the AND mask for transparency; 32bpp uses its alpha
    # channel only when that channel actually carries data.
    use_mask = (bpp < 32) or not any_alpha
    if use_mask:
        p = 0
        for y in range(height):
            for x in range(width):
                if _mask_bit(y, x):
                    out[p + 3] = 0
                p += 4
    try:
        surf = pygame.image.frombuffer(bytes(out), (width, height), "RGBA")
        try:
            return surf.convert_alpha()
        except Exception:
            return surf.copy()
    except Exception:
        return None

# Load the application icon early for the OS window/taskbar only. It is never
# drawn inside Arena's loading screens or beside the Arena Studio text. A
# separate logo.* file remains the explicit opt-in for in-product branding.
_EARLY_APP_ICON_SURF=None
_EARLY_APP_ICON_PATH=None
try:
    _icon_roots=tuple(dict.fromkeys((_ARENA_RESOURCE_DIR,_ARENA_INSTALL_DIR)))
    for _iname in ("icon.ico","icon.png","logo.ico","logo.png","Logo.ico","Logo.png"):
        for _iroot in _icon_roots:
            _ip=os.path.join(_iroot,_iname)
            if not os.path.isfile(_ip):continue
            _isurf=_load_image_surface(_ip)
            if _isurf is None:continue
            _EARLY_APP_ICON_SURF=_isurf;_EARLY_APP_ICON_PATH=_ip
            try:pygame.display.set_icon(_isurf)
            except Exception:pass
            break
        if _EARLY_APP_ICON_SURF is not None:break
except Exception:pass
