font_lg   = CachedFont(pygame.font.SysFont("segoeui", 22, bold=True))
font_md   = CachedFont(pygame.font.SysFont("segoeui", 17))
font_sm   = CachedFont(pygame.font.SysFont("segoeui", 14))
font_tiny = CachedFont(pygame.font.SysFont("segoeui", 11))
font_mono = CachedFont(pygame.font.SysFont("consolas", 13))
SIDEBAR_W = 352  # default; recomputed by build_ui_fonts() from UI_FONT_SCALE

