# Professional neutral product themes. Legacy colorful themes remain readable
# for old project files but are migrated/hidden from the selector.
def _matte_black_theme(accent,hover,dim):
    accent=tuple(accent);hover=tuple(hover);dim=tuple(dim)
    focus=tuple(max(8,min(52,int(8+c*.14))) for c in accent)
    scroll_hover=tuple(max(62,min(128,int(48+c*.24))) for c in accent)
    return {
        "ACCENT":accent,"ACCENT_HOVER":hover,"ACCENT_DIM":dim,"ACCENT_SOFT":accent,
        "APP_BG":(0,0,0),"PANEL_BG":(5,5,6),"PANEL_BG_ALT":(13,13,15),
        "PANEL_BORDER":(40,40,46),"DIVIDER":(25,25,29),
        "FIELD_BG":(8,8,10),"FIELD_FOCUS":focus,
        "TEXT_MAIN":(244,244,247),"TEXT_DIM":(165,165,173),"TEXT_FAINT":(96,96,106),
        "DANGER":(224,62,72),"DANGER_HOVER":(248,88,97),
        "GOOD":(65,192,128),"GOLD":(238,185,57),"INFO":(67,151,244),
        "SCROLLBAR_COLOR":(48,48,55),"SCROLLBAR_HOVER":scroll_hover,
        "SIDEBAR_BG":(3,3,4),"BTN_HOVER_GLOW":(*accent,58),
    }


