def _palette_rgb(h,s,v):
    r,g,b=colorsys.hsv_to_rgb(h%1.0,max(0,min(1,s)),max(0,min(1,v)))
    return (int(round(r*255)),int(round(g*255)),int(round(b*255)))


def _palette_mix(a,b,t):
    return tuple(int(round(a[i]+(b[i]-a[i])*max(0,min(1,t)))) for i in range(3))


def _palette_luma(c):
    return .2126*c[0]+.7152*c[1]+.0722*c[2]


def generate_harmony_palettes(seed):
    """Generate coordinated palette families from one selected main color."""
    try:r,g,b=[max(0,min(255,int(v))) for v in list(seed)[:3]]
    except Exception:r,g,b=82,118,168
    h,s,v=colorsys.rgb_to_hsv(r/255,g/255,b/255);source_s=s;s=max(.62,s);base=_palette_rgb(h,s,max(.72,v))
    hue=lambda d,ss=s,vv=v:_palette_rgb(h+d,ss,vv)
    neutral_dark=_palette_mix(base,(8,12,17),.80);neutral_mid=_palette_mix(base,(90,98,108),.68);neutral_light=_palette_mix(base,(244,246,247),.88)
    families={
      "Generic Gradient":[_palette_rgb(h,s,x) for x in (.16,.25,.36,.48,.60,.72,.84,.96)],
      "Matching Gradient":[_palette_rgb(h+d,s*.82,.30+i*.085) for i,d in enumerate((-.10,-.07,-.04,-.01,.02,.05,.08,.11))],
      "Spot Palette":[neutral_dark,_palette_mix(base,(255,255,255),.75),base,hue(.5,s,.82),hue(.08,s*.75,.88),hue(-.08,s*.75,.70),neutral_mid,neutral_light],
      "Twisted Spot":[neutral_dark,base,hue(.42,s,.82),hue(.58,s,.86),hue(.16,s*.82,.76),hue(-.16,s*.82,.76),neutral_light,_palette_mix(base,(235,190,95),.55)],
      "Classy Palette":[_palette_mix(base,(13,16,20),.84),_palette_mix(base,(35,39,45),.76),_palette_mix(base,(83,88,96),.70),_palette_mix(base,(218,213,202),.78),_palette_mix(base,(248,246,240),.90),_palette_mix(base,(173,139,77),.58),_palette_mix(base,(71,126,112),.62),base],
      # Adaptive product families deliberately combine neutral surfaces with
      # separate semantic hues. They are not brightness ramps of the seed.
      "Neutral + Complement":[(5,6,8),(15,17,20),(35,38,44),(108,113,122),(239,241,244),base,hue(.5,min(1,s*.95),.90),(235,181,58)],
      "Studio Contrast":[(3,4,6),(14,16,19),(43,47,54),(241,243,246),base,(47,167,232),(238,183,56),(66,190,130)],
      "Matte Signal":[(0,0,0),(8,8,10),(28,28,33),(244,244,247),base,(225,57,70),(65,192,128),(239,184,52)],
      "Dual Accent":[(5,6,8),(17,19,23),(48,52,60),(239,242,245),base,hue(.5,min(1,s),.92),hue(.42,min(1,s*.88),.84),hue(.58,min(1,s*.88),.84)],
      "Balanced Product":[(7,8,10),(16,18,21),(39,43,49),(238,241,244),base,(62,181,124),(233,181,62),(62,145,235)],
      "Cube Palette":[hue(0,s,.78),hue(.25,s*.9,.78),hue(.5,s*.9,.78),hue(.75,s*.9,.78),hue(.125,s*.72,.90),hue(.375,s*.72,.90),hue(.625,s*.72,.90),hue(.875,s*.72,.90)],
      "Highlight Palette":[(12,15,19),(28,32,38),(62,68,76),(126,133,142),(224,228,231),base,hue(.5,min(1,s*1.1),.95),hue(.12,min(1,s*1.1),.98)],
      "Monochrome":[_palette_rgb(h,s*.35+i*.08,.18+i*.105) for i in range(8)],
      "Analogous":[hue(d,min(1,s*.9),.78 if i%2==0 else .92) for i,d in enumerate((-.14,-.10,-.06,-.02,.02,.06,.10,.14))],
      "Complementary":[_palette_rgb(h,s,.35),_palette_rgb(h,s,.55),base,_palette_rgb(h,s,.92),_palette_rgb(h+.5,s,.35),_palette_rgb(h+.5,s,.55),_palette_rgb(h+.5,s,.76),_palette_rgb(h+.5,s,.94)],
      "Split Complement":[base,hue(.42,s,.82),hue(.58,s,.82),hue(.08,s*.7,.92),hue(-.08,s*.7,.92),neutral_dark,neutral_mid,neutral_light],
      "Triadic":[hue(0,s,.78),hue(1/3,s,.78),hue(2/3,s,.78),hue(0,s*.55,.95),hue(1/3,s*.55,.95),hue(2/3,s*.55,.95),neutral_dark,neutral_light],
      "Tetradic":[hue(0,s,.78),hue(.25,s,.78),hue(.5,s,.78),hue(.75,s,.78),hue(0,s*.5,.95),hue(.25,s*.5,.95),hue(.5,s*.5,.95),hue(.75,s*.5,.95)],
      "Pastel":[_palette_rgb(h+d,max(.28,s*.42),vv) for d,vv in zip((-.18,-.12,-.06,0,.06,.12,.18,.50),(.88,.93,.86,.96,.90,.84,.94,.89))],
      "Jewel":[hue(d,min(1,s*1.12),vv) for d,vv in ((0,.58),(.12,.68),(.25,.60),(.38,.66),(.50,.58),(.62,.66),(.75,.58),(.88,.65))],
      "Earth Palette":[_palette_mix(base,c,.66) for c in ((47,55,43),(85,75,52),(127,91,60),(166,126,82),(197,161,109),(90,119,91),(67,93,92),(226,214,184))],
      "Night Accent":[(7,11,17),(14,21,31),(24,34,47),(43,56,72),base,hue(.5,s,.86),hue(.10,s,.92),(230,235,239)],
      "ThreeDom Palette":[_palette_mix(base,c,.48) for c in ((11,19,43),(28,37,65),(58,80,107),(91,192,190),(244,241,222),(201,166,91),(102,134,153),(45,57,82))],
      "Dust Palette":[_palette_mix(base,c,.70) for c in ((37,34,35),(50,46,47),(78,70,68),(112,99,92),(155,125,110),(184,160,140),(215,204,186),(231,226,214))],
      "Red White Black":[(7,9,12),(82,12,18),(166,20,30),(232,35,45),(255,255,255),(220,224,228),(128,132,138),(25,28,32)],
      "Blue Red White":[(8,16,35),(24,76,170),(46,126,232),(225,35,52),(255,255,255),(220,225,235),(120,18,35),(12,12,16)],
      "Punchy Contrast":[(7,10,14),base,hue(.5,1,.96),hue(.12,1,1.0),(255,255,255),(235,38,70),(18,114,235),(250,205,20)],
      "Primary Pop":[(5,8,12),(237,28,36),(35,87,137),(241,211,2),(253,255,252),base,hue(.5,1,.9),(80,220,170)],
      "Sports Contrast":[(8,12,20),base,hue(.5,1,.94),(255,255,255),(245,175,20),(220,35,55),(35,115,230),(30,35,42)],
      "Candy Pop":[hue(d,.88,.98) for d in (0,.08,.16,.33,.50,.62,.75,.88)],
    }
    # Stable integer RGB and no accidental duplicate slots within a family.
    return {name:[tuple(max(0,min(255,int(x))) for x in c[:3]) for c in colors] for name,colors in families.items()}


def generated_palette_to_ui(colors,seed=None):
    """Map a generated harmony to a restrained, multicolor product UI.

    The selected seed owns interaction emphasis—not every background. Panels,
    fields and typography use neutral graphite ramps; success, warning, danger
    and info each choose their own semantic hue. This prevents the old adaptive
    themes from becoming one giant red/blue/purple color wash.
    """
    colors=[tuple(max(0,min(255,int(v))) for v in c[:3]) for c in list(colors or [])]
    try:seed=tuple(max(0,min(255,int(v))) for v in list(seed or (82,118,168))[:3])
    except Exception:seed=(82,118,168)
    if not colors:colors=[seed]

    def saturation(c):
        return colorsys.rgb_to_hsv(c[0]/255.0,c[1]/255.0,c[2]/255.0)[1]
    vivid=[c for c in colors if saturation(c)>=.30 and 38<=_palette_luma(c)<=242]
    accent=min(vivid or colors,key=lambda c:sum((c[i]-seed[i])**2 for i in range(3)))
    ah,asat,aval=colorsys.rgb_to_hsv(accent[0]/255.0,accent[1]/255.0,accent[2]/255.0)
    accent=_palette_rgb(ah,max(.58,asat),max(.72,min(.96,aval)))

    # Near-black/graphite surfaces carry almost no seed hue.
    background=(6,7,9)
    panel=(15,17,20)
    panel_alt=(24,27,31)
    panel_border=(48,52,59)
    divider=(34,37,43)
    field=(10,12,15)
    field_focus=_palette_mix((25,29,35),accent,.16)
    text=(241,243,246);dim=(163,170,178);faint=(99,107,116)

    def semantic(target,standard):
        near=min(colors,key=lambda c:sum((c[i]-target[i])**2 for i in range(3)))
        # Family character remains visible, but the semantic identity stays
        # unambiguous even if the source family lacks that hue entirely.
        return _palette_mix(near,standard,.64)
    success=semantic((55,190,120),(66,190,128))
    highlight=semantic((240,185,55),(238,184,58))
    danger=semantic((225,55,70),(224,61,73))
    info=semantic((55,145,235),(61,148,238))

    return {
        "accent":list(accent),"accent_hover":list(_palette_mix(accent,(255,255,255),.23)),
        "accent_dim":list(_palette_mix(accent,background,.57)),
        "background":list(background),"panel":list(panel),"panel_alt":list(panel_alt),
        "panel_border":list(panel_border),"divider":list(divider),
        "field":list(field),"field_focus":list(field_focus),
        "text":list(text),"text_dim":list(dim),"text_faint":list(faint),
        "success":list(success),"highlight":list(highlight),"danger":list(danger),
        "danger_hover":list(_palette_mix(danger,(255,255,255),.20)),"info":list(info),
        "sidebar":[9,10,13],
        "scrollbar":[55,60,68],
    }

def save_named_generated_theme(theme_name,family=None,seed=None):
    name=" ".join(str(theme_name or "").strip().split())[:48]
    if not name:return False
    seed=tuple(seed or _editor_config.get("auto_palette_seed",[82,118,168]))
    family=str(family or _editor_config.get("auto_palette_family","Classy Palette"))
    families=generate_harmony_palettes(seed)
    if family not in families:return False
    generated=generated_palette_to_ui(families[family],seed)
    # custom_ui_palette is the live edited generated tone. Overlay it onto a
    # complete generated schema so old seven-token palettes migrate cleanly.
    tokens=dict(generated);tokens.update(copy.deepcopy(_editor_config.get("custom_ui_palette",{}) or {}))
    entry={"seed":list(seed),"family":family,"tokens":tokens,"schema":2,"saved_at":time.time()}
    _editor_config.setdefault("user_palette_themes",{})[name]=entry
    save_editor_config(_editor_config);apply_theme("user::"+name);return True


def update_named_generated_theme(theme_name):
    name=str(theme_name or "").strip();store=_editor_config.setdefault("user_palette_themes",{})
    if name not in store:return False
    entry=dict(store[name]);tokens=dict(entry.get("tokens",{}) or {})
    tokens.update(copy.deepcopy(_editor_config.get("custom_ui_palette",{}) or {}))
    entry.update({"tokens":tokens,"schema":2,"saved_at":time.time()});store[name]=entry
    save_editor_config(_editor_config);apply_theme("user::"+name);return True


def delete_named_generated_theme(theme_name):
    name=str(theme_name or "");store=_editor_config.setdefault("user_palette_themes",{})
    if name not in store:return False
    store.pop(name,None);save_editor_config(_editor_config)
    if _CURRENT_THEME=="user::"+name:apply_theme("graphite")
    return True


def apply_generated_ui_palette(name,seed=None):
    seed=tuple(seed or globals().get("_editor_config",{}).get("auto_palette_seed",[82,118,168]))
    families=generate_harmony_palettes(seed)
    if name not in families:return False
    _editor_config["auto_palette_seed"]=list(seed);_editor_config["auto_palette_family"]=name
    _editor_config["custom_ui_palette"]=generated_palette_to_ui(families[name],seed)
    save_editor_config(_editor_config);apply_theme("custom");return True


def save_generated_palette_swatches(name,seed=None):
    families=generate_harmony_palettes(seed or _editor_config.get("auto_palette_seed",[82,118,168]))
    if name not in families:return False
    load_color_swatches()
    for color in families[name]:add_color_swatch(color)
    return True


