def _ui_theme_from_tokens(raw):
    def col(key,default):
        try:return tuple(max(0,min(255,int(v))) for v in list(raw.get(key,default))[:3])
        except Exception:return tuple(default)
    accent=col("accent",(82,118,168));bg=col("background",(15,17,20));panel=col("panel",(22,25,29));text=col("text",(232,235,238));dim=col("text_dim",(157,165,174));good=col("success",(75,145,119));gold=col("highlight",(177,145,80))
    def blend(a,b,t):return tuple(int(a[i]+(b[i]-a[i])*t) for i in range(3))
    return {
      "ACCENT":accent,"ACCENT_HOVER":col("accent_hover",blend(accent,(255,255,255),.22)),
      "ACCENT_DIM":col("accent_dim",blend(accent,bg,.52)),"ACCENT_SOFT":accent,"APP_BG":bg,"PANEL_BG":panel,
      "PANEL_BG_ALT":col("panel_alt",blend(panel,text,.10)),"PANEL_BORDER":col("panel_border",blend(panel,text,.23)),
      "DIVIDER":col("divider",blend(panel,text,.14)),"FIELD_BG":col("field",blend(bg,panel,.45)),
      "FIELD_FOCUS":col("field_focus",blend(panel,accent,.30)),"TEXT_MAIN":text,"TEXT_DIM":dim,
      "TEXT_FAINT":col("text_faint",blend(dim,bg,.45)),"DANGER":col("danger",(180,74,79)),
      "DANGER_HOVER":col("danger_hover",(204,94,99)),"GOOD":good,"GOLD":gold,"INFO":col("info",(67,151,244)),
      "SCROLLBAR_COLOR":col("scrollbar",blend(panel,text,.18)),"SCROLLBAR_HOVER":blend(col("scrollbar",blend(panel,text,.18)),text,.24),
      "SIDEBAR_BG":col("sidebar",blend(bg,panel,.24)),"BTN_HOVER_GLOW":(*accent,50)}


def _custom_ui_theme():
    raw = dict(_CUSTOM_UI_PALETTE_DEFAULT)
    # Theme tables are created before editor_config is loaded during startup.
    # Use defaults at that stage; apply_theme("custom") rebuilds from the real
    # config later. Direct _editor_config access here caused the pre-splash
    # NameError that prevented the old crash window from even existing.
    config = globals().get("_editor_config", {})
    raw.update(config.get("custom_ui_palette", {}) or {})
    def col(key):
        value=raw.get(key,_CUSTOM_UI_PALETTE_DEFAULT[key])
        try:return tuple(max(0,min(255,int(v))) for v in list(value)[:3])
        except Exception:return tuple(_CUSTOM_UI_PALETTE_DEFAULT[key])
    theme=_ui_theme_from_tokens(raw)
    if bool(config.get("ui_auto_text_contrast",True)):
        panel=theme["PANEL_BG"];brightness=.2126*panel[0]+.7152*panel[1]+.0722*panel[2]
        main=(18,20,23) if brightness>145 else (246,248,249)
        theme["TEXT_MAIN"]=main;theme["TEXT_DIM"]=_palette_mix(main,panel,.35);theme["TEXT_FAINT"]=_palette_mix(main,panel,.58)
    return theme


_THEMES["custom"] = _custom_ui_theme()

def apply_theme(name=None):
    """Apply a named theme, writing values into module globals."""
    global ACCENT, ACCENT_HOVER, ACCENT_DIM, ACCENT_SOFT
    global APP_BG, PANEL_BG, PANEL_BG_ALT, PANEL_BORDER, DIVIDER
    global FIELD_BG, FIELD_FOCUS, TEXT_MAIN, TEXT_DIM, TEXT_FAINT
    global DANGER, DANGER_HOVER, GOOD, GOLD, INFO
    global SCROLLBAR_COLOR, SCROLLBAR_HOVER, SIDEBAR_BG, BTN_HOVER_GLOW, _CURRENT_THEME
    if _ui_90s_active():
        # 90s UI Mode owns the palette while it is on. The user's chosen
        # theme is remembered in config and restored when the mode is off.
        name = "win95"
    elif name is None:
        name=str(_editor_config.get("ui_theme","graphite"))
    name=_LEGACY_THEME_MAP.get(str(name),str(name))
    is_user_theme=str(name).startswith("user::")
    if is_user_theme:
        uname=str(name).split("::",1)[1]
        entry=globals().get("_editor_config",{}).get("user_palette_themes",{}).get(uname)
        tokens=entry.get("tokens") if isinstance(entry,dict) else None
        if isinstance(tokens,dict) and tokens:
            _THEMES[name]=_ui_theme_from_tokens(tokens)
        else:
            _THEMES.pop(name,None);name="graphite";is_user_theme=False
    if name in _AUTO_THEME_FAMILIES:
        seed=globals().get("_editor_config",{}).get("auto_palette_seed",[82,118,168]);families=generate_harmony_palettes(seed);tokens=generated_palette_to_ui(families[_AUTO_THEME_FAMILIES[name]],seed);_THEMES[name]=_ui_theme_from_tokens(tokens)
    if name == "custom":
        _THEMES["custom"] = _custom_ui_theme()
    if name not in _THEMES or (name not in _PRO_THEME_KEYS and not is_user_theme):name="graphite"
    _CURRENT_THEME = name
    t = _THEMES[name]
    ACCENT = t["ACCENT"]; ACCENT_HOVER = t["ACCENT_HOVER"]; ACCENT_DIM = t["ACCENT_DIM"]
    ACCENT_SOFT = t["ACCENT_SOFT"]
    APP_BG = t["APP_BG"]; PANEL_BG = t["PANEL_BG"]; PANEL_BG_ALT = t["PANEL_BG_ALT"]
    PANEL_BORDER = t["PANEL_BORDER"]; DIVIDER = t["DIVIDER"]
    FIELD_BG = t["FIELD_BG"]; FIELD_FOCUS = t["FIELD_FOCUS"]
    TEXT_MAIN = t["TEXT_MAIN"]; TEXT_DIM = t["TEXT_DIM"]; TEXT_FAINT = t["TEXT_FAINT"]
    DANGER = t["DANGER"]; DANGER_HOVER = t["DANGER_HOVER"]
    GOOD = t["GOOD"]; GOLD = t["GOLD"]; INFO = t.get("INFO",(67,151,244))
    SCROLLBAR_COLOR = t["SCROLLBAR_COLOR"]; SCROLLBAR_HOVER = t["SCROLLBAR_HOVER"]
    SIDEBAR_BG = t["SIDEBAR_BG"]; BTN_HOVER_GLOW = t["BTN_HOVER_GLOW"]
    try:
        if not _ui_90s_active():
            _editor_config["ui_theme"] = name
            save_editor_config(_editor_config)
    except Exception:
        pass
    try:
        _UI_GLYPH_CACHE.clear();_PANEL_SURF_CACHE.clear()
        for _cache_name in ("_DOCK_BACKDROP_CACHE","_SIDEBAR_BACKDROP_CACHE","_SIDEBAR_CHROME_CACHE","_UI_SLICED_CACHE","_GRAD_CACHE","_DIM_SURF_CACHE","_FONT_ROW_LABEL_CACHE","_NS_TEXT_CACHE","_VECTOR_ICON_CACHE","_ADAPTIVE_THEME_PREVIEW_CACHE"):
            _cache=globals().get(_cache_name)
            if hasattr(_cache,"clear"):_cache.clear()
        globals()["_ui_sidebar_cache"]=None
        globals()["_SPLASH_CACHE"]=None
    except Exception:pass

def _ui_relative_luma(color):
    vals=[]
    for component in color[:3]:
        c=max(0,min(255,float(component)))/255.0;vals.append(c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4)
    return .2126*vals[0]+.7152*vals[1]+.0722*vals[2]


def _ui_contrast_ratio(a,b):
    la,lb=_ui_relative_luma(a),_ui_relative_luma(b);return (max(la,lb)+.05)/(min(la,lb)+.05)


def ui_contrast_text(background,preferred=None,minimum=4.5):
    preferred=tuple(preferred or TEXT_MAIN if "TEXT_MAIN" in globals() else preferred or (240,240,244))
    try:auto=bool(globals().get("_editor_config",{}).get("ui_auto_text_contrast",True))
    except Exception:auto=True
    if not auto or _ui_contrast_ratio(background,preferred)>=minimum:return preferred
    dark=(12,14,17);light=(248,249,250)
    return light if _ui_contrast_ratio(background,light)>=_ui_contrast_ratio(background,dark) else dark


