_ADAPTIVE_THEME_PREVIEW_CACHE={}


def _adaptive_theme_preview(key):
    seed=tuple(globals().get("_editor_config",{}).get("auto_palette_seed",[82,118,168]))
    cache_key=(str(key),seed)
    hit=_ADAPTIVE_THEME_PREVIEW_CACHE.get(cache_key)
    if hit is not None:return hit
    family=_AUTO_THEME_FAMILIES.get(str(key))
    families=generate_harmony_palettes(seed)
    hit=_ui_theme_from_tokens(generated_palette_to_ui(families.get(family,[]),seed)) if family else _THEMES.get("graphite",{})
    if len(_ADAPTIVE_THEME_PREVIEW_CACHE)>24:_ADAPTIVE_THEME_PREVIEW_CACHE.clear()
    _ADAPTIVE_THEME_PREVIEW_CACHE[cache_key]=hit
    return hit
