def _ui_custom_live_palette():
    seed=tuple(_editor_config.get("auto_palette_seed",[82,118,168]))
    family=str(_editor_config.get("auto_palette_family","Classy Palette"))
    families=generate_harmony_palettes(seed)
    base=generated_palette_to_ui(families.get(family,next(iter(families.values()))),seed)
    base.update(copy.deepcopy(_editor_config.get("custom_ui_palette",{}) or {}))
    return base


