def _uct_register(rect,callback,tag="action"):
    hit=rect.copy();tag=str(tag)
    # Scroll-content controls only own their visible intersection. This prevents
    # offscreen rows from stealing clicks from the fixed preview/navigation.
    body=modal.get("_uct_body_rect")
    if body is not None and not (tag=="close" or tag.startswith("tab:") or tag.startswith("rail:")):
        hit=hit.clip(body)
        if hit.width<=0 or hit.height<=0:return rect
    modal.setdefault("_uct_actions",[]).append((hit,callback,tag))
    return rect


def _uct_set_scroll(value):
    value=max(0.0,min(float(modal.get("_uct_max_scroll",0.0)),float(value)))
    modal["_uct_scroll"]=value;modal.setdefault("_uct_scroll_by_tab",{})[modal.get("_uct_tab","themes")]=value


def _uct_scroll_from_pointer(y,grab_offset=None):
    track=modal.get("_uct_scroll_track");thumb=modal.get("_uct_scroll_thumb");maximum=float(modal.get("_uct_max_scroll",0.0))
    if not track or not thumb or maximum<=0:return False
    offset=thumb.height/2 if grab_offset is None else float(grab_offset)
    top=float(y)-offset;span=max(1.0,float(track.height-thumb.height));frac=max(0.0,min(1.0,(top-track.y)/span));_uct_set_scroll(frac*maximum);return True


def handle_ui_customization_click(pos):
    """Event-driven hit routing with a real draggable/pageable scrollbar."""
    if modal.get("type")!="ui_customization_tool":return False
    track=modal.get("_uct_scroll_track");thumb=modal.get("_uct_scroll_thumb")
    if thumb and thumb.inflate(8,4).collidepoint(pos):
        modal["_uct_scroll_drag"]=True;modal["_uct_scroll_grab"]=pos[1]-thumb.y;return True
    if track and track.inflate(8,0).collidepoint(pos):
        return _uct_scroll_from_pointer(pos[1])
    for rect,callback,tag in reversed(modal.get("_uct_actions",[])):
        if rect.collidepoint(pos):
            try:callback()
            except Exception as exc:push_toast(f"Customization action failed: {exc}","error",4.0)
            return True
    return False


def handle_ui_customization_scroll_motion(pos):
    if modal.get("type")=="ui_customization_tool" and modal.get("_uct_scroll_drag"):
        return _uct_scroll_from_pointer(pos[1],modal.get("_uct_scroll_grab",0))
    return False


