def _uct_reset_section(tab=None,quiet=False):
    tab=str(tab or modal.get("_uct_tab","themes"))
    if tab=="themes":apply_theme("graphite")
    elif tab=="palette":
        _editor_config["auto_palette_seed"]=[82,118,168];_editor_config["auto_palette_family"]="Classy Palette"
