def _e3d_overlay_prefs():
    """Item silhouette / Form silhouette / verts / edges / face tint colors."""
    cfg = _editor_config if isinstance(globals().get("_editor_config"), dict) else {}
    def rgb(key):
        default = _E3D_OVERLAY_DEFAULTS[key]
        raw = cfg.get(key, default)
        try:
            return tuple(max(0, min(255, int(v))) for v in list(raw)[:3])
        except Exception:
            return tuple(default)
    def opa(key):
        default = float(_E3D_OVERLAY_DEFAULTS[key])
        try:
            return max(0.08, min(1.0, float(cfg.get(key, default))))
        except Exception:
            return default
    sel_a = opa("e3d_sel_opacity")
    line_a = opa("e3d_line_opacity")
    face_a = opa("e3d_face_opacity")
    def rgba(key, a):
        r, g, b = rgb(key)
        return (r / 255.0, g / 255.0, b / 255.0, float(a))
    return {
        "sel": rgba("e3d_sel_color", sel_a),
        "form_sel": rgba("e3d_form_sel_color", sel_a),
        "edge": rgba("e3d_edge_color", line_a),
        "vert": rgba("e3d_vert_color", min(1.0, line_a + 0.12)),
        "face": rgba("e3d_face_tint", face_a),
        "sel_rgb": rgb("e3d_sel_color"),
        "form_sel_rgb": rgb("e3d_form_sel_color"),
        "edge_rgb": rgb("e3d_edge_color"),
        "vert_rgb": rgb("e3d_vert_color"),
        "face_rgb": rgb("e3d_face_tint"),
        "sel_opacity": sel_a,
        "line_opacity": line_a,
        "face_opacity": face_a,
    }


