def _convex_hull_2d(pts):
    pts = sorted(set((round(float(x), 2), round(float(y), 2)) for x, y in pts))
    if len(pts) <= 2:
        return pts
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]


_E3D_CUBE_CORNERS = (
    (-0.5, -0.5, -0.5), (0.5, -0.5, -0.5), (0.5, 0.5, -0.5), (-0.5, 0.5, -0.5),
    (-0.5, -0.5,  0.5), (0.5, -0.5,  0.5), (0.5, 0.5,  0.5), (-0.5, 0.5,  0.5),
)
_E3D_CUBE_FACES = (
    (0, 1, 2, 3), (4, 5, 6, 7), (0, 1, 5, 4), (3, 2, 6, 7), (0, 3, 7, 4), (1, 2, 6, 5),
)
_E3D_CUBE_EDGES = (
    (0, 1), (1, 2), (2, 3), (3, 0), (4, 5), (5, 6), (6, 7), (7, 4), (0, 4), (1, 5), (2, 6), (3, 7),
)


def _e3d_draw_overlay_cube(dest, rect, mode, yaw):
    """Spinning cube preview for one overlay mode. CPU, no GPU."""
    s = pygame.Surface((max(8, rect.w), max(8, rect.h)), pygame.SRCALPHA)
    cx, cy = rect.w * 0.5, rect.h * 0.52
    scale = min(rect.w, rect.h) * 0.34
    cyw, syw = math.cos(yaw), math.sin(yaw)
    pitch = 0.48
    cp, sp = math.cos(pitch), math.sin(pitch)
    pts3 = []
    for x, y, z in _E3D_CUBE_CORNERS:
        xz, zz = x * cyw + z * syw, -x * syw + z * cyw
        y2, z2 = y * cp - zz * sp, y * sp + zz * cp
        pts3.append((xz, y2, z2))
    pts2 = []
    for x, y, z in pts3:
        d = 2.5 / (2.5 + z)
        pts2.append((cx + x * scale * d, cy - y * scale * d))
    # shaded faces, back to front
    faces = []
    for idx in _E3D_CUBE_FACES:
        zs = sum(pts3[i][2] for i in idx) / 4.0
        a, b, c = pts3[idx[0]], pts3[idx[1]], pts3[idx[2]]
        nx = (b[1] - a[1]) * (c[2] - a[2]) - (b[2] - a[2]) * (c[1] - a[1])
        ny = (b[2] - a[2]) * (c[0] - a[0]) - (b[0] - a[0]) * (c[2] - a[2])
        nz = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        ln = math.sqrt(nx * nx + ny * ny + nz * nz) or 1.0
        diff = max(0.0, (nx * 0.35 + ny * 0.8 + nz * 0.45) / ln)
        shade = 0.32 + 0.68 * diff
        col = (int(78 * shade + 30), int(86 * shade + 34), int(102 * shade + 40))
        faces.append((zs, idx, col))
    faces.sort()
    for _z, idx, col in faces:
        pygame.draw.polygon(s, col, [pts2[i] for i in idx])
    prefs = _e3d_overlay_prefs()
    if mode == "faces":
        r, g, b = prefs["face_rgb"]
        a = int(255 * prefs["face_opacity"])
        tint = (r, g, b, a)
        for _z, idx, _c in faces:
            pygame.draw.polygon(s, tint, [pts2[i] for i in idx])
    if mode in ("sel", "form_sel"):
        hull = _convex_hull_2d(pts2)
        rgb = prefs["sel_rgb"] if mode == "sel" else prefs["form_sel_rgb"]
        a = prefs["sel_opacity"]
        if len(hull) >= 2:
            pygame.draw.lines(s, (*rgb, int(70 * a + 20)), True, hull, 5)
            pygame.draw.lines(s, (*rgb, int(200 * a + 40)), True, hull, 2)
    if mode == "edges":
        r, g, b = prefs["edge_rgb"]
        a = int(255 * prefs["line_opacity"])
