    # Perspective floor immediately reads as 3D rather than a flat icon.
    for i in range(-3,4):
        a=project((i*.28,-.78,-.85));b=project((i*.28,-.78,.85));c=project((-.85,-.78,i*.28));d=project((.85,-.78,i*.28));pygame.draw.line(screen,(27,34,44),(a[0],a[1]),(b[0],b[1]),1);pygame.draw.line(screen,(27,34,44),(c[0],c[1]),(d[0],d[1]),1)
    joints=[np.array((-.18,-.68,0.0)),np.array((0.0,-.05,.10)),np.array((.20,.62,-.03))];body=prefs["body_rgb"];start=prefs["start_rgb"];end=prefs["end_rgb"];faces=int(prefs["faces"])
    for bi,(head,tail) in enumerate(zip(joints,joints[1:]),1):
        axis=tail-head;n=axis/(float(np.linalg.norm(axis)) or 1.0);helper=np.array((0,1,0) if abs(n[1])<.9 else (1,0,0),dtype=np.float64);u=np.cross(n,helper);u/=float(np.linalg.norm(u)) or 1.;v=np.cross(n,u);v/=float(np.linalg.norm(v)) or 1.;radius=float(np.linalg.norm(axis))*prefs["body_radius"]
        ring=[head+(u*math.cos(2*math.pi*i/faces)+v*math.sin(2*math.pi*i/faces))*radius for i in range(faces)];rp=[project(q) for q in ring];tp=project(tail)
        if prefs["wireframe"]:
            pygame.draw.lines(screen,body,True,[(q[0],q[1]) for q in rp],max(1,int(round(prefs["line_width"]))))
            for q in rp:pygame.draw.line(screen,body,(q[0],q[1]),(tp[0],tp[1]),max(1,int(round(prefs["line_width"]))))
        else:
            tris=sorted([((rp[i][2]+rp[(i+1)%faces][2]+tp[2])/3,i) for i in range(faces)],reverse=True)
            for _z,i in tris:pygame.draw.polygon(screen,body,[(rp[i][0],rp[i][1]),(rp[(i+1)%faces][0],rp[(i+1)%faces][1]),(tp[0],tp[1])])
        for q,col in ((head,start),(tail,end)):
            qp=project(q);rr=max(4,int(rect.width*prefs["joint_size"]*qp[3]));pygame.draw.circle(screen,_palette_mix(col,(255,255,255),.22),(int(qp[0]),int(qp[1])),rr);pygame.draw.circle(screen,col,(int(qp[0]),int(qp[1])),rr,1)
        mid=project((head+tail)*.5);nm=font_tiny.render(_e3d_armature_bone_name(bi),True,TEXT_MAIN);screen.blit(nm,(int(mid[0]-nm.get_width()/2),int(mid[1]-nm.get_height()-4)))
    meta=font_tiny.render(f"LIVE 3D · {prefs['faces']} faces · {'wire' if prefs['wireframe'] else 'solid'}",True,TEXT_FAINT);screen.blit(meta,(rect.x+7,rect.y+6))


