_NS_CUSTOM_THEME_SETTING_KEYS=("ns_node_theme","ns_node_body_color","ns_node_border_color","ns_node_text_color","ns_node_header_text_color","ns_node_corner_radius","ns_node_border_width","ns_pin_style","ns_pin_scale","ns_pin_glow","ns_wire_width_scale")


def _ns_custom_theme_snapshot():
    data={key:copy.deepcopy(_editor_config.get(key)) for key in _NS_CUSTOM_THEME_SETTING_KEYS if key in _editor_config}
    data["ns_node_theme"]=str(_editor_config.get("ns_node_theme",NS_NODE_THEME))
    data["ns_pin_colors"]=copy.deepcopy(_editor_config.get("ns_pin_colors",{}) or {})
    data["ns_category_colors"]=copy.deepcopy(_editor_config.get("ns_category_colors",{}) or {})
    return data


def save_named_node_theme(name):
    name=" ".join(str(name or "").strip().split())[:48]
    if not name:return False
    _editor_config.setdefault("ns_custom_themes",{})[name]={"settings":_ns_custom_theme_snapshot(),"saved_at":time.time()}
    _editor_config["ns_active_custom_theme"]=name;save_editor_config(_editor_config);push_toast(f"Node theme saved: {name}","success",2.4);return True


def apply_named_node_theme(name):
    global NS_NODE_THEME
    entry=(_editor_config.get("ns_custom_themes",{}) or {}).get(name);settings=entry.get("settings") if isinstance(entry,dict) else None
    if not isinstance(settings,dict):return False
    for key in _NS_CUSTOM_THEME_SETTING_KEYS:
        if key in settings and settings[key] is not None:_editor_config[key]=copy.deepcopy(settings[key])
        elif key!="ns_node_theme":_editor_config.pop(key,None)
    _editor_config["ns_pin_colors"]=copy.deepcopy(settings.get("ns_pin_colors",{}));_editor_config["ns_category_colors"]=copy.deepcopy(settings.get("ns_category_colors",{}))
    NS_NODE_THEME=str(_editor_config.get("ns_node_theme","current"));_editor_config["ns_active_custom_theme"]=name;save_editor_config(_editor_config)
    apply_pin_color_customization();apply_category_color_customization();push_toast(f"Node theme applied: {name}","success",2.2);return True


def delete_named_node_theme(name):
    store=_editor_config.setdefault("ns_custom_themes",{})
    if name not in store:return False
    store.pop(name,None)
    if _editor_config.get("ns_active_custom_theme")==name:_editor_config.pop("ns_active_custom_theme",None)
    save_editor_config(_editor_config);return True


def _uct_node_working_base(base):
    global NS_NODE_THEME
    if base not in NS_NODE_THEMES:return
    NS_NODE_THEME=base;_editor_config["ns_node_theme"]=base;_editor_config.pop("ns_active_custom_theme",None);save_editor_config(_editor_config)
    push_toast(f"Working copy base: {NS_NODE_THEMES[base][0]} · save as a new Node Theme when ready","info",2.6)


