def _ui_anim_pulse(rect,key,strength=2):
    """Small local click/release ring; does not wake unrelated UI animation."""
    now=time.time();stable=key if isinstance(key,(str,tuple,int)) else str(key);mouse_down=bool(pygame.mouse.get_pressed()[0])
    state=_ui_press_btns.get(stable)
    if mouse_down and rect.collidepoint(pygame.mouse.get_pos()):
        if not state or not state.get("down"):_ui_press_btns[stable]=state={"start":now,"until":now+.18,"down":True}
        else:state["until"]=max(float(state.get("until",0)),now+.08)
    elif state:state["down"]=False
    if not state or now>=float(state.get("until",0)):
        if state:_ui_press_btns.pop(stable,None)
        return False
    t=max(0.0,min(1.0,(now-float(state.get("start",now)))/max(.001,float(state.get("until",now))-float(state.get("start",now)))));pulse=math.sin(t*math.pi);pad=max(1,int(float(strength)*(1.0+pulse*2.0)));alpha=max(0,min(150,int(145*(1.0-t))));ring=pygame.Surface((rect.width+pad*2,rect.height+pad*2),pygame.SRCALPHA);pygame.draw.rect(ring,(*ACCENT_HOVER,alpha),ring.get_rect(),width=max(1,int(strength)),border_radius=_button_radius()+pad);screen.blit(ring,(rect.x-pad,rect.y-pad));return True

