    now=time.time();key=key_id if key_id is not None else ((key_rect.x,key_rect.y,key_rect.w,key_rect.h) if isinstance(key_rect,pygame.Rect) else str(key_rect));_ui_press_btns[key]={"start":now,"until":now+.18,"down":False};return True
