def _active_save_base():
    """Returns the persistent save base directory. If SETTINGS["save_dir"] is set,
    use it; otherwise fall back to BASE_DIR (persistent when frozen)."""
    try:
        sd = SETTINGS.get("save_dir", "")
        if sd and str(sd).strip():
            sd = str(sd).strip()
            if not os.path.isabs(sd):
                sd = os.path.join(BASE_DIR, sd)
            return os.path.abspath(sd)
    except Exception:
        pass
    return BASE_DIR

