def _install_packaged_defaults(destination_base=None):
    """Install only the small editable defaults that cannot stay read-only.

    rec.py and node_dictionary.py are Python modules inside the EXE. Font, icon,
    and FFmpeg stay in _internal. The blueprint-example JSON is editable, so a
    missing copy is created in config/scene beside the EXE. Existing files are
    never overwritten.
    """
    base=os.path.abspath(destination_base or _active_save_base());target=os.path.join(base,"config","scene","example_blueprints.json")
    if os.path.isfile(target) or not os.path.isfile(BUNDLED_EXAMPLE_BLUEPRINTS):return False
    try:
        os.makedirs(os.path.dirname(target),exist_ok=True);shutil.copy2(BUNDLED_EXAMPLE_BLUEPRINTS,target);print("[package] installed bundled example_blueprints.json");return True
    except Exception as exc:print("[package] could not install blueprint examples:",exc);return False


def _seed_bundled_content(destination_base=None):
    """Compatibility alias for the pre-v12 packaging hook."""
    return int(bool(_install_packaged_defaults(destination_base)))


# ════════════════════════════════════════════════════════════════════════
# BASE CONFIG FOLDER — every persistent data store and its backups live in
# one organized tree under the save base:
#   config/characters/   character_library.json · character_vault.json · character_rigs.json
#   config/animations/   animation_library.json · motion_clips.json · easing_curves.json
#   config/emitters/     particle_presets.json
#   config/gear/         gear_sets.json
#   config/audio/        audio_library.json
#   config/assets/       asset_creations.json
#   config/scene/        scene_groups.json · node_cluster_library.json · node_cluster_lessons.json · node_terminology.json · scene_blocks.json
#   config/settings/     editor_config.json · color_swatches.json
#   config/backups/<cat>/    automatic timestamped backups for each store
#   config/backups/scripts/  script + graph backups (from scripts/_backups)
# Any file still found in the old flat locations (next to the game file or
# the save-dir root) is MOVED into this tree at startup — never copied over
# or deleted — so existing work is never lost.
# ════════════════════════════════════════════════════════════════════════
def _cfg_path(category, filename):
    """Resolve one store file inside the base config folder tree."""
    return os.path.join(_active_save_base(), "config", str(category), str(filename))

# Every persistent data store the game owns, mapped into the config tree.
