def _migrate_legacy_data_files():
    """One-time (idempotent) move of any data files that still live in the
    old flat locations — next to the game file or in the save-dir root —
    into the config/ folder tree. Files are MOVED, never copied over or
    deleted, so nothing that exists on disk is lost. If the target already
    exists (already migrated), the old copy is parked into the store's
    backup folder instead of being overwritten. Backup files (timestamped
    .backup_*, .bak, .unreadable_* stashes, parked .legacy_* copies) are
    moved into config/backups/<category>/ alongside."""
    try:
        cfg = os.path.abspath(CONFIG_DIR)
        bdir = os.path.abspath(CONFIG_BACKUPS_DIR)
        roots = [os.path.abspath(BASE_DIR)]
        cur = os.path.abspath(_active_save_base())
        if cur not in roots:
            roots.append(cur)
        for cat, fn in _DATA_STORE_SPECS:
            new_path = _cfg_path(cat, fn)
            bk_dir = os.path.join(bdir, cat)
            try:
                os.makedirs(os.path.dirname(new_path), exist_ok=True)
                os.makedirs(bk_dir, exist_ok=True)
            except Exception:
                pass
            for root in roots:
                old = os.path.join(root, fn)
                if os.path.isfile(old):
                    try:
                        if not os.path.exists(new_path):
                            shutil.move(old, new_path)
                            print(f"   [config] moved {fn} -> config/{cat}/")
                        else:
                            _stamp = time.strftime("%Y%m%d-%H%M%S")
                            _dst = os.path.join(bk_dir, f"{fn}.legacy_{_stamp}.json")
                            _i = 1
                            while os.path.exists(_dst) and _i < 100:
                                _dst = os.path.join(bk_dir, f"{fn}.legacy_{_stamp}_{_i}.json")
                                _i += 1
                            shutil.move(old, _dst)
                            print(f"   [config] parked duplicate {fn} -> config/backups/{cat}/")
                    except Exception as e:
                        print("   [config] skip:", fn, e)
                # move any backups of this store sitting beside the old file
                if os.path.isdir(root):
                    try:
                        for bname in os.listdir(root):
                            if (bname.startswith(fn + ".backup_") or bname.startswith(fn + ".unreadable_")
                                    or bname.startswith(fn + ".legacy_") or bname == fn + ".bak"):
                                full = os.path.join(root, bname)
                                if os.path.isfile(full):
                                    try:
                                        shutil.move(full, os.path.join(bk_dir, bname))
                                    except Exception:
                                        pass
                    except Exception:
                        pass
        # legacy script backups -> config/backups/scripts
        try:
            old_sb = os.path.join(SCRIPTS_DIR, "_backups")
            if os.path.isdir(old_sb) and os.path.abspath(old_sb) != os.path.abspath(BACKUPS_DIR):
                os.makedirs(BACKUPS_DIR, exist_ok=True)
                for bname in os.listdir(old_sb):
                    full = os.path.join(old_sb, bname)
                    if os.path.isfile(full):
                        try:
                            shutil.move(full, os.path.join(BACKUPS_DIR, bname))
                        except Exception:
                            pass
                try:
                    os.rmdir(old_sb)
                except Exception:
                    pass
        except Exception:
            pass
    except Exception as e:
        print("[config] migration issue:", e)


def _refresh_save_paths():
    """Recompute all persistent file paths from current SETTINGS["save_dir"].
    Called once after settings load and whenever the user changes save_dir."""
    global RECORDINGS_DIR, SPRITES_DIR, AUDIO_DIR, IMPORTED_AUDIO_DIR
    global SCRIPTS_DIR, BACKUPS_DIR, LIBRARY_PATH
    global CHAR_VAULT_PATH, ANIMATION_LIBRARY_PATH
    global NODE_CLUSTER_LIBRARY_PATH, NODE_CLUSTER_LESSONS_PATH
    global NODE_TERMINOLOGY_PATH, EDITOR_CONFIG_PATH, _EASING_CURVES_PATH
    global SCENE_GROUP_LIBRARY_PATH, CHARACTER_RIG_LIBRARY_PATH, GEAR_SET_LIBRARY_PATH
    global AUDIO_LIBRARY_PATH, COLOR_SWATCHES_PATH, SCENE_BLOCKS_PATH
    global _PE_CUSTOM_PRESETS_PATH, _MOTION_CLIPS_PATH
    global CONFIG_DIR, CONFIG_BACKUPS_DIR, _ICON_DISK_DIR, _sprite_folders_path
    base = _active_save_base()
    # Base config tree
    CONFIG_DIR = os.path.join(base, "config")
    CONFIG_BACKUPS_DIR = os.path.join(CONFIG_DIR, "backups")
    RECORDINGS_DIR = os.path.join(base, "recordings")
    SPRITES_DIR = os.path.join(base, "sprites")
    AUDIO_DIR = os.path.join(base, "audio")
    IMPORTED_AUDIO_DIR = os.path.join(AUDIO_DIR, "_imported")
    SCRIPTS_DIR = os.path.join(base, "scripts")
    BACKUPS_DIR = os.path.join(CONFIG_BACKUPS_DIR, "scripts")
    LIBRARY_PATH = _cfg_path("characters", "character_library.json")
    CHAR_VAULT_PATH = _cfg_path("characters", "character_vault.json")
    CHARACTER_RIG_LIBRARY_PATH = _cfg_path("characters", "character_rigs.json")
    ANIMATION_LIBRARY_PATH = _cfg_path("animations", "animation_library.json")
    _MOTION_CLIPS_PATH = _cfg_path("animations", "motion_clips.json")
    _EASING_CURVES_PATH = _cfg_path("animations", "easing_curves.json")
    _PE_CUSTOM_PRESETS_PATH = _cfg_path("emitters", "particle_presets.json")
    GEAR_SET_LIBRARY_PATH = _cfg_path("gear", "gear_sets.json")
    AUDIO_LIBRARY_PATH = _cfg_path("audio", "audio_library.json")
    SCENE_GROUP_LIBRARY_PATH = _cfg_path("scene", "scene_groups.json")
    NODE_CLUSTER_LIBRARY_PATH = _cfg_path("scene", "node_cluster_library.json")
    NODE_CLUSTER_LESSONS_PATH = _cfg_path("scene", "node_cluster_lessons.json")
    NODE_TERMINOLOGY_PATH = _cfg_path("scene", "node_terminology.json")
    SCENE_BLOCKS_PATH = _cfg_path("scene", "scene_blocks.json")
    EDITOR_CONFIG_PATH = _cfg_path("settings", "editor_config.json")
    COLOR_SWATCHES_PATH = _cfg_path("settings", "color_swatches.json")
    _ICON_DISK_DIR = os.path.join(base, "_icon_cache")
    # Ensure directories exist
    for d in (base, RECORDINGS_DIR, SPRITES_DIR, AUDIO_DIR, IMPORTED_AUDIO_DIR,
              SCRIPTS_DIR, BACKUPS_DIR, CONFIG_DIR, CONFIG_BACKUPS_DIR,
              os.path.join(CONFIG_DIR, "characters"), os.path.join(CONFIG_DIR, "animations"),
              os.path.join(CONFIG_DIR, "emitters"), os.path.join(CONFIG_DIR, "gear"),
              os.path.join(CONFIG_DIR, "audio"), os.path.join(CONFIG_DIR, "assets"),
              os.path.join(CONFIG_DIR, "scene"), os.path.join(CONFIG_DIR, "settings")):
        if d and not os.path.isdir(d):
            try:
                os.makedirs(d, exist_ok=True)
            except Exception:
                pass
    # Bring files from old loose layouts into the writable config tree first.
    try:
        _migrate_legacy_data_files()
    except Exception as _mig_err:
        print("[config] migration error:", _mig_err)
    # Then install the packaged example library only when no legacy/user copy
    # already exists. Other support files stay built into the EXE/_internal.
    try:_install_packaged_defaults(base)
    except Exception as _default_err:print("[package] default install error:",_default_err)

def change_save_dir(new_path):
    """Move all saved folders/files to new_path and update settings."""
    import shutil
    old_base = _active_save_base() if not SETTINGS.get("save_dir", "").strip() else _active_save_base()
    # Re-evaluate old base properly from current settings before changing
    current_sd = str(SETTINGS.get("save_dir", "")).strip()
    if current_sd:
        old_base = os.path.abspath(current_sd) if os.path.isabs(current_sd) else os.path.abspath(os.path.join(BASE_DIR, current_sd))
    else:
        old_base = BASE_DIR
    new_path = str(new_path).strip() if new_path else ""
    if new_path and not os.path.isabs(new_path):
        new_path = os.path.abspath(os.path.join(BASE_DIR, new_path))
    SETTINGS["save_dir"] = new_path
    # Create new directories first
    new_dir = new_path or BASE_DIR
    for d in ("recordings", "sprites", "audio", "scripts", "config"):
        tgt = os.path.join(new_dir, d)
        if not os.path.isdir(tgt):
            try:
                os.makedirs(tgt, exist_ok=True)
            except Exception:
                pass
    # Move contents from old folders to new if different
    if os.path.abspath(old_base) != os.path.abspath(new_dir):
        for sub in ("recordings", "sprites", "audio", "scripts", "config"):
            src = os.path.join(old_base, sub)
            dst = os.path.join(new_dir, sub)
            if src != dst and os.path.isdir(src):
                for item in os.listdir(src):
                    s_path = os.path.join(src, item)
                    d_path = os.path.join(dst, item)
                    try:
                        if os.path.isfile(s_path):
                            shutil.move(s_path, d_path)
                        elif os.path.isdir(s_path):
                            if not os.path.isdir(d_path):
                                shutil.move(s_path, d_path)
                            else:
                                for inner in os.listdir(s_path):
                                    shutil.move(os.path.join(s_path, inner), os.path.join(d_path, inner))
                    except Exception:
                        pass
    _refresh_save_paths()
    # Point every store at the new save dir and reload it from disk.
    try:
        _load_all_data_stores()
    except Exception:
        pass

# Initialize paths once at startup
_refresh_save_paths()

_dmg_font_cache = {}
def get_dmg_font(size, font_name=None, bold=True):
    """Cached font loader. `font_name` can be a pygame system font name or a .ttf path."""
    size = max(6, int(size))
    font_name = font_name or SETTINGS.get("damage_font_name", "segoeui") if "SETTINGS" in globals() else (font_name or "segoeui")
    key = (str(font_name), size, bool(bold))
    f = _dmg_font_cache.get(key)
    if f is None:
        try:
            if isinstance(font_name, str) and font_name.lower().endswith((".ttf", ".otf")) and os.path.isfile(font_name):
                f = pygame.font.Font(font_name, size)
                f.set_bold(bool(bold))
            else:
                f = pygame.font.SysFont(font_name, size, bold=bold)
        except Exception:
            f = pygame.font.SysFont("segoeui", size, bold=bold)
        _dmg_font_cache[key] = f
    return f

def render_outlined_text(font,text,color,outline_color,outline_width):
    """Render a whole-pixel outline; tolerate fractional callers safely."""
    try:outline_width=max(0,int(round(float(outline_width))))
    except (TypeError,ValueError):outline_width=0
    base = font.render(text, True, color)
    if outline_width <= 0:
        return base
    w, h = base.get_size()
    surf = pygame.Surface((w + outline_width * 2, h + outline_width * 2), pygame.SRCALPHA)
    outline_surf = font.render(text, True, outline_color)
    for ox in range(-outline_width, outline_width + 1):
        for oy in range(-outline_width, outline_width + 1):
            if ox == 0 and oy == 0:
                continue
            if ox * ox + oy * oy > outline_width * outline_width + 1:
                continue
            surf.blit(outline_surf, (outline_width + ox, outline_width + oy))
    surf.blit(base, (outline_width, outline_width))
    return surf

_DAMAGE_OUTLINE_CACHE={}
_DAMAGE_OUTLINE_ORDER=[]
_DAMAGE_OUTLINE_LIMIT=768


def render_damage_text_fractional(font,text,color,outline_color,outline_width):
    """Outlined text with real 0.2px logical steps via blended outer rings."""
    width=max(0.0,min(10.0,round(float(outline_width)*5.0)/5.0));key=(id(font),str(text),tuple(color)[:3],tuple(outline_color)[:3],int(round(width*5)));hit=_DAMAGE_OUTLINE_CACHE.get(key)
    if hit is not None:return hit
    low=int(math.floor(width));frac=width-low
    if frac<=1e-6:hit=render_outlined_text(font,str(text),color,outline_color,low)
    else:
        high=low+1;outer=render_outlined_text(font,str(text),color,outline_color,high);outer.set_alpha(max(0,min(255,int(round(frac*255)))));inner=render_outlined_text(font,str(text),color,outline_color,low);hit=pygame.Surface(outer.get_size(),pygame.SRCALPHA);hit.blit(outer,(0,0));hit.blit(inner,((hit.get_width()-inner.get_width())//2,(hit.get_height()-inner.get_height())//2));hit.set_alpha(None)
    _DAMAGE_OUTLINE_CACHE[key]=hit;_DAMAGE_OUTLINE_ORDER.append(key)
    if len(_DAMAGE_OUTLINE_ORDER)>_DAMAGE_OUTLINE_LIMIT:
        stale=_DAMAGE_OUTLINE_ORDER.pop(0);_DAMAGE_OUTLINE_CACHE.pop(stale,None)
    return hit


def toggle_fullscreen():
    global screen,WIDTH,HEIGHT,is_fullscreen,_FULLSCREEN_TRANSITION_UNTIL
    entering=not is_fullscreen
    if entering:_WINDOWED_SIZE[:]=[max(720,int(WIDTH)),max(520,int(HEIGHT))]
    try:
        if entering:
            try:dw,dh=pygame.display.get_desktop_sizes()[0]
            except Exception:
                info=pygame.display.Info();dw,dh=info.current_w,info.current_h
            screen=_display_set_mode(int(dw),int(dh),pygame.FULLSCREEN);is_fullscreen=True
        else:
            ww,wh=_WINDOWED_SIZE;screen=_display_set_mode(max(720,int(ww)),max(520,int(wh)),pygame.RESIZABLE);is_fullscreen=False
        WIDTH,HEIGHT=screen.get_size()
        # Discard resize/mouse events generated by the mode switch itself. They
        # previously reapplied fullscreen dimensions to the restored window and
        # left a black/strobing backbuffer.
        for etype in (getattr(pygame,"VIDEORESIZE",None),getattr(pygame,"WINDOWSIZECHANGED",None),getattr(pygame,"WINDOWRESIZED",None)):
            if etype is not None:
                try:pygame.event.clear(etype)
                except Exception:pass
        for cache_name in ("_ui_sidebar_cache","_ui_toolbar_cache","_SPLASH_CACHE"):
            globals()[cache_name]=None
        for cache_name in ("_PANEL_SURF_CACHE","_SIDEBAR_BACKDROP_CACHE","_DOCK_BACKDROP_CACHE","_GRID_BG_CACHE"):
            cache=globals().get(cache_name)
            if hasattr(cache,"clear"):cache.clear()
        if "_SPARSE_PRESENT_STATE" in globals():_SPARSE_PRESENT_STATE.update({"size":None,"camera":None,"rects":[],"full_next":True})
        if "_IDLE_PRESENT_STATE" in globals():_IDLE_PRESENT_STATE["signature"]=None;_IDLE_PRESENT_STATE["wake_until"]=time.perf_counter()+1.0
        _FULLSCREEN_TRANSITION_UNTIL=time.monotonic()+.35
        screen.fill(APP_BG);pygame.display.flip();pygame.event.pump()
    except Exception as exc:
        is_fullscreen=False;ww,wh=_WINDOWED_SIZE;screen=_display_set_mode(max(720,int(ww)),max(520,int(wh)),pygame.RESIZABLE);WIDTH,HEIGHT=screen.get_size();push_toast(f"Fullscreen switch recovered: {exc}","warning",4)


