# ════════════════════════════════════════════════════════════════════════
# DATA-STORE SAFETY — backups + wipe protection for every persistent JSON
# library (Node Cluster Library, Character Vault, Scene Group Library).
#
#   • Every save is atomic (temp file + os.replace) and first rotates a
#     timestamped backup of whatever was on disk, keeping the newest
#     _DATA_BACKUP_KEEP copies.
#   • A save is REFUSED (file untouched) if the in-memory payload is empty
#     but a non-empty file exists on disk AND the store was never loaded
#     this session — this is what wipes libraries when a second instance is
#     open or a save fires before the first load.
#   • If a save fires before the store was ever loaded, the on-disk entries
#     are MERGED into memory first (new/changed entries win by id + name),
#     so a stray save can never silently drop previously saved work.
#   • A corrupt/unreadable main file falls back to the newest backup, and
#     saves are blocked until the user restores or fixes the file.
#   • Each library UI has a "Restore…" button (open_backup_restore) so any
#     previous version can be recovered by hand.
# ════════════════════════════════════════════════════════════════════════
_DATA_BACKUP_KEEP = 20          # newest timestamped backups kept per store

def _data_store_backup_dir(store_path):
    """Where automatic backups for a store live: config/backups/<category>/
    for stores inside the config tree, otherwise a _backups/ subfolder next
    to the store (foreign/legacy paths)."""
    try:
        cfg = os.path.normpath(CONFIG_DIR)
        sp = os.path.normpath(os.path.abspath(store_path))
        if os.path.commonpath([sp, cfg]) == cfg:
            rel = os.path.relpath(sp, cfg)
            parts = [p for p in rel.split(os.sep) if p and p != "."]
            if len(parts) >= 2:
                return os.path.join(CONFIG_BACKUPS_DIR, parts[0])
    except Exception:
        pass
    return os.path.join(os.path.dirname(store_path) or ".", "_backups")


def list_data_store_backups(path):
    """Newest-first metadata for every backup of a store file.

    Scans both the organized config/backups/<category>/ folder AND the
    folder beside the store (for anything not yet migrated). Recognizes
    timestamped .backup_* copies, legacy .bak files, .unreadable_*
    corruption stashes, and parked .legacy_* duplicates."""
    out = []
    seen = set()
    base_name = os.path.basename(path)
    dirs = []
    bdir = _data_store_backup_dir(path)
    if bdir and os.path.isdir(bdir):
        dirs.append(bdir)
    ldir = os.path.dirname(path) or "."
    if os.path.isdir(ldir) and os.path.abspath(ldir) != os.path.abspath(bdir):
        dirs.append(ldir)
    for d in dirs:
        try:
            for fn in os.listdir(d):
                full = os.path.join(d, fn)
                if not os.path.isfile(full):
                    continue
                if fn.startswith(base_name + ".backup_") and fn.endswith(".json"):
                    stamp = fn[len(base_name) + len(".backup_"):-5]
                    entry = {"path": full, "stamp": stamp, "legacy": False, "kind": "backup"}
                elif fn == base_name + ".bak":
                    entry = {"path": full, "stamp": "legacy", "legacy": True, "kind": "legacy"}
                elif fn.startswith(base_name + ".unreadable_"):
                    stamp = fn[len(base_name) + len(".unreadable_"):-4]
                    entry = {"path": full, "stamp": "stash_" + stamp, "legacy": True, "kind": "stash"}
                elif fn.startswith(base_name + ".legacy_"):
                    stamp = fn[len(base_name) + len(".legacy_"):-5]
                    entry = {"path": full, "stamp": "parked_" + stamp, "legacy": True, "kind": "parked"}
                else:
                    continue
                key = os.path.abspath(full)
                if key not in seen:
                    seen.add(key)
                    out.append(entry)
        except Exception:
            pass
    out.sort(key=lambda b: (0 if b.get("kind") == "backup" else 1, b["stamp"]), reverse=True)
    return out

def _data_store_rotate(path, keep=None):
    """Snapshot the current store file to a timestamped backup inside
    config/backups/<category>/ and prune the oldest beyond `keep` — only
    within that organized folder, so pre-migration legacy files are never
    deleted. Returns the new backup path, or None."""
    if keep is None:
        keep = _DATA_BACKUP_KEEP
    if not path or not os.path.isfile(path):
        return None
    try:
        bdir = _data_store_backup_dir(path)
        os.makedirs(bdir, exist_ok=True)
        stamp = time.strftime("%Y%m%d-%H%M%S")
        bk = os.path.join(bdir, os.path.basename(path) + f".backup_{stamp}.json")
        i = 1
        while os.path.exists(bk) and i < 100:
            bk = os.path.join(bdir, os.path.basename(path) + f".backup_{stamp}_{i}.json")
            i += 1
        shutil.copy2(path, bk)
        # prune only inside the organized backup folder
        try:
            prefix = os.path.basename(path) + ".backup_"
            cands = []
            for fn in os.listdir(bdir):
                if fn.startswith(prefix) and fn.endswith(".json"):
                    cands.append(os.path.join(bdir, fn))
            cands.sort()
            for old in (cands[:-keep] if keep > 0 else cands):
                try:
                    os.remove(old)
                except Exception:
                    pass
        except Exception:
            pass
        return bk
    except Exception:
        return None

def _data_store_merge(path, memory, label, expect="list"):
    """Merge on-disk entries into the in-memory payload right before a save,
    so a save that fires before the store was ever loaded cannot drop
    entries that were already saved.
      expect="list" -> memory wins by entry id or by name (a same-name save
                       is a deliberate replacement).
      expect="dict" -> memory wins by key; on-disk keys are kept."""
    try:
        with open(path, "r", encoding="utf-8") as fh:
            disk = json.load(fh)
        if expect == "dict":
            if not isinstance(disk, dict):
                return memory
            mem = dict(memory) if isinstance(memory, dict) else {}
            merged = dict(disk)
            merged.update(mem)
            if len(disk):
                print(f"!! {label}: merged {len(disk)} on-disk item(s) before saving ({len(merged)} total).")
                try:
                    push_toast(f"{label}: merged {len(disk)} saved item(s) with your new one so nothing was lost.", "info", 5.0)
                except Exception:
                    pass
            return merged
        if not isinstance(disk, list):
            return memory
        # Dedupe only by NON-EMPTY ids/names: entries without either (audio
        # paths, swatch colors, …) can never collide with memory, so they
        # are always kept instead of being dropped for having None/"" keys.
        mem_ids = {e.get("id") for e in memory if isinstance(e, dict) and e.get("id")}
        mem_names = {str(e.get("name", "")).strip().lower()
                     for e in memory if isinstance(e, dict) if str(e.get("name", "")).strip()}
        keep_disk = []
        for e in disk:
            if not isinstance(e, dict):
                keep_disk.append(e)
                continue
            eid = e.get("id")
            ename = str(e.get("name", "")).strip().lower()
            if (eid and eid in mem_ids) or (ename and ename in mem_names):
                continue  # same id or same name in memory -> memory wins
            keep_disk.append(e)
        merged = keep_disk + list(memory)
        if len(keep_disk):
            print(f"!! {label}: merged {len(keep_disk)} on-disk entry(s) before saving ({len(merged)} total).")
            try:
                push_toast(f"{label}: merged {len(keep_disk)} saved item(s) with your new one so nothing was lost.", "info", 5.0)
            except Exception:
                pass
        return merged
    except Exception:
        return memory

def _data_store_write_safe(path, payload, label, loaded, allow_empty=None):
    """Save `payload` to `path` with backup rotation + wipe protection.

    loaded      : True when the in-memory payload was loaded from disk this
                  session (so an empty payload is a legitimate user clear).
    allow_empty : override; if None, uses `loaded`.
    Returns True if the file was written."""
    if allow_empty is None:
        allow_empty = bool(loaded)
    try:
        if not allow_empty and not payload and os.path.isfile(path):
            try:
                with open(path, "r", encoding="utf-8") as fh:
                    _ex = json.load(fh)
                if isinstance(_ex, (list, dict)) and len(_ex) > 0:
                    print(f"!! Refusing to overwrite non-empty {os.path.basename(path)} with empty {label}.")
                    try:
                        push_toast(f"{label} save skipped: on-disk data exists but the library was never loaded. "
                                   "Nothing was overwritten — reopen the library first.", "warning", 6.0)
                    except Exception:
                        pass
                    return False
            except Exception:
                pass
        _data_store_rotate(path)
        _tmp = path + f".tmp{os.getpid()}"
        with open(_tmp, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2)
        os.replace(_tmp, path)
        return True
    except Exception as e:
        print(f"Could not save {label}:", e)
        try:
            push_toast(f"Could not save {label}: {e}", "warning", 5.0)
        except Exception:
            pass
        return False

def _data_store_read_safe(path, label, expect="list"):
    """Read a store file, falling back to the newest backup if the main
    file is missing/corrupt/wrong-shape. Returns (data, source):
        "disk"    — main file parsed fine
        "backup"  — main file was bad; recovered from a backup
        "missing" — no file yet (callers keep their default)
        "blocked" — nothing usable; callers must refuse saves
    """
    if not os.path.isfile(path):
        return None, "missing"
    try:
        with open(path, "r", encoding="utf-8") as fh:
            parsed = json.load(fh)
        if expect == "list":
            if isinstance(parsed, list):
                return parsed, "disk"
            raise ValueError("expected a list")
        if isinstance(parsed, (list, dict)):
            return parsed, "disk"
        raise ValueError("unexpected JSON shape")
    except Exception as e:
        print(f"!! Could not read {label} ({e}) — trying newest backup.")
        for bk in list_data_store_backups(path):
            try:
                with open(bk["path"], "r", encoding="utf-8") as fh:
                    parsed = json.load(fh)
                if expect == "list":
                    ok_shape = isinstance(parsed, list)
                else:
                    ok_shape = isinstance(parsed, (list, dict))
                if ok_shape:
                    print(f"   {label}: recovered from backup {os.path.basename(bk['path'])}")
                    try:
                        push_toast(f"{label}: main file was unreadable — restored from backup "
                                   f"{os.path.basename(bk['path'])}.", "warning", 6.0)
                    except Exception:
                        pass
                    return parsed, "backup"
            except Exception:
                continue
        try:
            _bd = _data_store_backup_dir(path)
            os.makedirs(_bd, exist_ok=True)
            _bad = os.path.join(_bd, os.path.basename(path) + f".unreadable_{int(time.time())}.bak")
            shutil.copy2(path, _bad)
        except Exception:
            pass
        try:
            push_toast(f"{label} file couldn't be read and no backup was found. "
                       "Saves are paused until you restore or fix it.", "warning", 8.0)
        except Exception:
            pass
        return None, "blocked"

_NODE_CLUSTER_LIBRARY_LOADED = False
