_NODE_CLUSTER_LESSONS_LOADED = False
_NODE_CLUSTER_LESSONS_LOAD_BLOCKED = False

def load_node_cluster_lessons():
    """Load previously-taught idea->graph examples from disk."""
    global NODE_CLUSTER_LESSONS, _NODE_CLUSTER_LESSONS_LOADED, _NODE_CLUSTER_LESSONS_LOAD_BLOCKED
    data, source = _data_store_read_safe(NODE_CLUSTER_LESSONS_PATH, "Node Cluster Lessons")
    if source == "blocked":
        _NODE_CLUSTER_LESSONS_LOADED = False
        _NODE_CLUSTER_LESSONS_LOAD_BLOCKED = True
        return
    _NODE_CLUSTER_LESSONS_LOAD_BLOCKED = False
    _NODE_CLUSTER_LESSONS_LOADED = True
    if data is not None:
        NODE_CLUSTER_LESSONS = data if isinstance(data, list) else []
    else:
        NODE_CLUSTER_LESSONS = []
    # Migration: older lessons were keyed only by idea text. Give every
    # lesson a stable id + display name so they can be renamed/deleted
    # individually without disturbing the others.
    used_ids = set()
    dirty = False
    for lesson in NODE_CLUSTER_LESSONS:
        if not lesson.get("id"):
            lesson["id"] = hashlib.sha1(
                (str(lesson.get("idea", "")) + str(lesson.get("ts", time.time()))).encode()
            ).hexdigest()[:12]
            dirty = True
        while lesson["id"] in used_ids:
            lesson["id"] = hashlib.sha1((lesson["id"] + "x").encode()).hexdigest()[:12]
            dirty = True
        used_ids.add(lesson["id"])
        if not lesson.get("name"):
            lesson["name"] = str(lesson.get("idea", "Untitled lesson")).strip()[:60] or "Untitled lesson"
            dirty = True
    if dirty:
        save_node_cluster_lessons()
def save_node_cluster_lessons():
    global NODE_CLUSTER_LESSONS, _NODE_CLUSTER_LESSONS_LOADED, _NODE_CLUSTER_LESSONS_LOAD_BLOCKED
    if _NODE_CLUSTER_LESSONS_LOAD_BLOCKED:
        print("!! Refusing to save cluster lessons: last load failed and no backup was usable.")
        try:
            push_toast("Lesson save skipped - restore a backup first (see console).", "warning", 5.0)
        except Exception:
            pass
        return
    if not _NODE_CLUSTER_LESSONS_LOADED and os.path.isfile(NODE_CLUSTER_LESSONS_PATH):
        NODE_CLUSTER_LESSONS = _data_store_merge(NODE_CLUSTER_LESSONS_PATH, NODE_CLUSTER_LESSONS, "Node Cluster Lessons")
        _NODE_CLUSTER_LESSONS_LOADED = True
    _data_store_write_safe(NODE_CLUSTER_LESSONS_PATH, NODE_CLUSTER_LESSONS, "Node Cluster Lessons", _NODE_CLUSTER_LESSONS_LOADED)
def cluster_lesson_by_id(lesson_id):
    return next((l for l in NODE_CLUSTER_LESSONS if l.get("id") == lesson_id), None)

def rename_cluster_lesson(lesson_id):
    lesson = cluster_lesson_by_id(lesson_id)
    if not lesson:
        return False

    def on_confirm(val):
        val = " ".join(str(val).strip().split())[:60]
        if not val:
            push_toast("Lesson name cannot be empty.", "warning")
            return
        lesson["name"] = val
        save_node_cluster_lessons()
        push_toast("Lesson renamed.", "success", 2.0)
        modal["type"] = "cluster_lesson_manager"
        modal["focus"] = None

    def on_cancel():
        modal["type"] = "cluster_lesson_manager"
        modal["focus"] = None

    modal["type"] = "text_input_modal"
    modal["text_input_title"] = "Rename Lesson"
    modal["text_input_label"] = "Lesson name:"
    modal["text_input_value"] = lesson.get("name", "")
    modal["focus"] = "text_input_value"
    modal["text_input_callback"] = on_confirm
    modal["text_input_cancel_callback"] = on_cancel
    return True

def edit_cluster_lesson_idea(lesson_id):
    """Edit the idea text a taught lesson matches against. Re-tokenizes
    so future idea searches still find it correctly."""
    lesson = cluster_lesson_by_id(lesson_id)
    if not lesson:
        return False

    def on_confirm(val):
        val = " ".join(str(val).strip().split())
        if not val:
            push_toast("Lesson idea cannot be empty.", "warning")
            return
        lesson["idea"] = val
        lesson["tokens"] = sorted(_cluster_idea_tokens(val))
        save_node_cluster_lessons()
        push_toast("Lesson idea updated.", "success", 2.0)
        modal["type"] = "cluster_lesson_manager"
        modal["focus"] = None

    def on_cancel():
        modal["type"] = "cluster_lesson_manager"
        modal["focus"] = None

    modal["type"] = "text_input_modal"
    modal["text_input_title"] = "Edit Lesson Idea"
    modal["text_input_label"] = "Idea text this lesson matches:"
    modal["text_input_value"] = lesson.get("idea", "")
    modal["focus"] = "text_input_value"
    modal["text_input_callback"] = on_confirm
    modal["text_input_cancel_callback"] = on_cancel
    return True

def delete_cluster_lesson(lesson_id):
    global NODE_CLUSTER_LESSONS
    lesson = cluster_lesson_by_id(lesson_id)
    if not lesson:
        return False
    try:
        import tkinter as tk
        root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
        # Bypass lagging confirmation modal completely!
        confirm = True
    except Exception:
        confirm = True
    if not confirm:
        return False

    before = len(NODE_CLUSTER_LESSONS)
    NODE_CLUSTER_LESSONS = [l for l in NODE_CLUSTER_LESSONS if l.get("id") != lesson_id]
    if len(NODE_CLUSTER_LESSONS) != before:
        save_node_cluster_lessons()
        push_toast("Lesson deleted.", "info", 2.0)
        return True
    return False

# ------------------------------------------------------------
# Export script (points at whatever export/recording-compile
# script the user has -- chosen once via a file picker, then
# remembered across launches in editor_config.json).
# ------------------------------------------------------------
EDITOR_CONFIG_PATH = _cfg_path('settings', 'editor_config.json')

_EDITOR_CONFIG_LOADED = False
_EDITOR_CONFIG_LOAD_BLOCKED = False

def load_editor_config():
    global _EDITOR_CONFIG_LOADED, _EDITOR_CONFIG_LOAD_BLOCKED
    data, source = _data_store_read_safe(EDITOR_CONFIG_PATH, "Editor Config", "dict")
    if source == "blocked":
        _EDITOR_CONFIG_LOADED = False
        _EDITOR_CONFIG_LOAD_BLOCKED = True
        return {}
    _EDITOR_CONFIG_LOAD_BLOCKED = False
    _EDITOR_CONFIG_LOADED = True
    return data if isinstance(data, dict) else {}
def save_editor_config(cfg):
    global _EDITOR_CONFIG_LOADED, _EDITOR_CONFIG_LOAD_BLOCKED
    if _EDITOR_CONFIG_LOAD_BLOCKED:
        print("!! Refusing to save editor config: last load failed and no backup was usable.")
        return
    payload = cfg if isinstance(cfg, dict) else {}
    if not _EDITOR_CONFIG_LOADED and os.path.isfile(EDITOR_CONFIG_PATH):
        payload = _data_store_merge(EDITOR_CONFIG_PATH, payload, "Editor Config", "dict")
        _EDITOR_CONFIG_LOADED = True
    _data_store_write_safe(EDITOR_CONFIG_PATH,payload,"Editor Config",_EDITOR_CONFIG_LOADED)
    try:
        exporter=globals().get("_export_shared_ui_theme")
        if callable(exporter) and not globals().get("_SHARED_THEME_EXPORT_BUSY",False):exporter()
    except Exception:pass
_editor_config=load_editor_config()

# ------------------------------------------------------------
# GLOBAL UI STYLE PERSISTENCE
# ------------------------------------------------------------
# Corner style, panel tone/borders/sheen, button gloss/hover/glow etc. are
# meant to be YOUR editor preferences, not something tied to one project --
# the project save/load code above already deliberately skips restoring any
# SETTINGS key that starts with these prefixes for exactly that reason (see
# the "Only UI / theme preferences are global" comment near the settings
# load block). The bug was that nothing ever actually wrote them anywhere
# global -- SETTINGS is just an in-memory dict seeded with hardcoded
# defaults, so the moment the process restarted (or a project without them
# loaded) they silently fell back to defaults. This ties them into
# editor_config.json, which already persists other cross-project editor
# state, so they now survive restarts/reloads and apply to every project.
_GLOBAL_SETTINGS_PREFIXES = ("ui_", "panel_", "button_", "pe_editor_", "pe_max_",
                             "svg_", "arena_outer_")
_GLOBAL_SETTINGS_EXTRA = ("save_dir", "vsync", "fps_cap", "cache_size", "nerd_stats",
                          "nerd_stats_detail", "frame_costs", "spike_logging",
                          "ui_render_fps", "scene_font_scale", "box_color",
                          "pe_show_help", "pe_large_text", "pe_auto_throttle")

def _setting_is_global(key):
    k = str(key)
    return k.startswith(_GLOBAL_SETTINGS_PREFIXES) or k in _GLOBAL_SETTINGS_EXTRA

def _persist_global_setting(key):
    """Call right after SETTINGS[key] = ... for any key covered by
    _setting_is_global -- writes it into editor_config.json immediately so
    it survives a reload/restart and follows you into every project."""
    try:
        if not _setting_is_global(key):
            return
        _editor_config.setdefault("global_settings", {})[str(key)] = SETTINGS.get(key)
        save_editor_config(_editor_config)
    except Exception:
        pass

def _restore_global_settings():
    try:
        _gs = _editor_config.get("global_settings", {})
        if not isinstance(_gs, dict):
            return
        for k, v in _gs.items():
            if k in SETTINGS and _setting_is_global(k):
                SETTINGS[k] = v
    except Exception:
        pass

_restore_global_settings()

# ═════════════════════════════════════════════════════════════════════════
# ARENA PALETTE — global theme that follows you across every project
# Background/box colors, box scale/thickness, shadows and movement smoothing
# used to live INSIDE each project file, so a new project always reset them
# to defaults and loading an old project reverted your choices. They now
# persist globally in editor_config (arena_palette) and are applied at boot,
# on New Project, and whenever you change one of them.
# ═════════════════════════════════════════════════════════════════════════
_ARENA_PALETTE_LAST_SAVE = [0.0]

def _arena_palette_save(force=False):
    """Persist the current arena look into the global editor config.

    Slider drags call this many times per second; writes are throttled to
    one per 0.4 s (force=True bypasses the throttle — used by project save)."""
    try:
        _now = time.time()
        if not force and _now - _ARENA_PALETTE_LAST_SAVE[0] < 0.4:
            _editor_config.setdefault("_arena_palette_dirty", True)
            return
        _ARENA_PALETTE_LAST_SAVE[0] = _now
        _editor_config["arena_palette"] = {
            "bg_color": [int(c) for c in bg_color[:3]],
            "box_color": [int(c) for c in (SETTINGS.get("box_color", [0, 0, 0]) or [0, 0, 0])[:3]],
            "box_scale": int(box_scale),
            "box_thickness": int(box_thickness),
            "show_shadows": bool(show_shadows),
            "movement_smoothing": float(movement_smoothing),
        }
        _editor_config.pop("_arena_palette_dirty", None)
        save_editor_config(_editor_config)
    except Exception:
        pass

def _arena_palette_apply():
    """Apply the persisted global arena look onto the live globals."""
    global bg_color, box_scale, box_thickness, show_shadows, movement_smoothing
    try:
        _pal = _editor_config.get("arena_palette")
        if not isinstance(_pal, dict):
            return
        if isinstance(_pal.get("bg_color"), (list, tuple)) and len(_pal["bg_color"]) >= 3:
            bg_color = [int(c) for c in _pal["bg_color"][:3]]
        if isinstance(_pal.get("box_color"), (list, tuple)) and len(_pal["box_color"]) >= 3:
            SETTINGS["box_color"] = [int(c) for c in _pal["box_color"][:3]]
        try:
            box_scale = int(_pal.get("box_scale", box_scale))
        except Exception:
            pass
        try:
            box_thickness = int(_pal.get("box_thickness", box_thickness))
        except Exception:
            pass
        show_shadows = bool(_pal.get("show_shadows", show_shadows))
        try:
            movement_smoothing = float(_pal.get("movement_smoothing", movement_smoothing))
        except Exception:
            pass
    except Exception:
        pass

# Flush a dirty palette (mid-drag slider change) on the next project save.
try:
    if _editor_config.get("_arena_palette_dirty"):
        _arena_palette_save(force=True)
except Exception:
    pass

# ═════════════════════════════════════════════════════════════════════════
# 90s UI MODE
# One toggle that re-skins the entire app as a flat, chunky, classic-90s
# (Windows-95-era) interface: gray beveled panels, square corners, white
# fields, black text, monospace type, and a retro boot/loading screen.
# Toggling it in Settings > Customize UI plays the loading screen again and
# the app comes back fully re-themed. Switching it off restores the previous
# theme and font. The choice persists across restarts.
# ═════════════════════════════════════════════════════════════════════════
UI_90S_MODE = bool(_editor_config.get("ui_90s_mode", False))
def _ui_90s_pick_font_family():
    """Classic bitmap-era font for 90s mode. Prefers Fixedsys on Windows
    (the authentic Win9x system font) but only if it actually rasterizes;
    otherwise falls back to Courier New."""
    for cand in ("fixedsys", "couriernew"):
        try:
            path = pygame.font.match_font(cand)
            if not path:
                continue
            probe = pygame.font.Font(path, 12)
            surf = probe.render("Test", False, (255, 255, 255))
            if surf is not None and surf.get_width() > 0:
                return cand
        except Exception:
            continue
    return "couriernew"

_UI_90S_FONT_FAMILY = _ui_90s_pick_font_family()

def _ui_90s_active():
    """True while 90s UI Mode is enabled. Chrome drawing helpers query this."""
    return bool(globals().get("UI_90S_MODE", False))

def _ui_90s_set(enabled):
    """Flip 90s UI Mode: persist it, swap theme + fonts, and restore the
    previous look when switching back. Returns True when the state changed."""
    global UI_90S_MODE, UI_FONT_FAMILY
    enabled = bool(enabled)
    if bool(UI_90S_MODE) == enabled:
        return False
    UI_90S_MODE = enabled
    try:
        _UI_90S_TASKBAR["menu_open"] = False
        _UI_90S_SPLASH_BG.clear()
        _UI_90S_TEXT_CACHE.clear()
        _UI_90S_FONT_CACHE.clear()
    except Exception:
        pass
    try:
        if enabled:
            if str(_editor_config.get("ui_theme", "graphite")) != "win95":
                _editor_config.setdefault("ui_theme_before_90s", str(_editor_config.get("ui_theme", "graphite")))
            _editor_config.setdefault("ui_font_before_90s", str(_editor_config.get("ui_font_family", "segoeui")) or "segoeui")
            UI_FONT_FAMILY = _UI_90S_FONT_FAMILY
        else:
            _prev_theme = str(_editor_config.pop("ui_theme_before_90s", "") or "")
            if _prev_theme:
                _editor_config["ui_theme"] = _prev_theme
            UI_FONT_FAMILY = str(_editor_config.pop("ui_font_before_90s", "segoeui") or "segoeui")
        _editor_config["ui_90s_mode"] = bool(enabled)
        save_editor_config(_editor_config)
    except Exception:
        pass
    try:
        apply_theme()
    except Exception:
        pass
    try:
        build_ui_fonts()
    except Exception:
        pass
    try:
        _ui_style_geometry_refresh()
    except Exception:
        pass
    return True

def _ui_90s_toggle_from_ui():
    """Settings-tab hook: toggle the mode, then return to the loading screen
    and re-preload so every cached surface rebuilds in the new style."""
    global UI_90S_MODE
    changed = _ui_90s_set(not bool(UI_90S_MODE))
    try:
        _terminal_log(f"90s UI Mode: {'ON' if UI_90S_MODE else 'OFF'} -- returning to splash", _TC_WARN)
    except Exception:
        pass
    try:
        _soft_reload_to_splash("90s UI Mode: ON" if UI_90S_MODE else "90s UI Mode: OFF")
    except Exception:
        try:
            push_toast("90s UI Mode changed -- reload the app to re-theme every surface", "info", 4.0)
        except Exception:
            pass
    return changed

# ═════════════════════════════════════════════════════════════════════════
# 90s taskbar / splash helpers
# ═════════════════════════════════════════════════════════════════════════
_UI_90S_TASKBAR = {"menu_open": False, "start_rect": None, "menu_rect": None, "menu_rects": []}
_UI_90S_FONT_CACHE = {}
_UI_90S_TEXT_CACHE = {}
_UI_90S_SPLASH_BG = {}
_UI_90S_TASKBAR_H = 32

def _ui_90s_font(size, bold=False):
    try:
        key = (int(size), bool(bold))
        f = _UI_90S_FONT_CACHE.get(key)
        if f is None:
            f = None
            try:
                f = pygame.font.Font(pygame.font.match_font(_UI_90S_FONT_FAMILY), int(size))
            except Exception:
                f = None
            if f is None:
                try:
                    f = pygame.font.SysFont("couriernew", int(size), bold=bold)
                except Exception:
                    f = pygame.font.Font(None, int(size))
            try:
                f.set_bold(bool(bold))
            except Exception:
                pass
            _UI_90S_FONT_CACHE[key] = f
        return f
    except Exception:
        return pygame.font.Font(None, int(size))

def _ui_90s_text(size, text, bold=False, color=(0, 0, 0)):
    """Aliased 90s text with its own render cache."""
    try:
        key = (int(size), bool(bold), str(text), tuple(color))
        surf = _UI_90S_TEXT_CACHE.get(key)
        if surf is None:
            surf = _ui_90s_font(size, bold).render(str(text), False, tuple(color))
            if len(_UI_90S_TEXT_CACHE) > 768:
                _UI_90S_TEXT_CACHE.clear()
            _UI_90S_TEXT_CACHE[key] = surf
        return surf
    except Exception:
        return None

def _ui_90s_bevel_rect(rect, pressed=False, hover=False):
    """Draw a Win95 raised (or sunken when pressed) beveled rectangle."""
    try:
        rr = pygame.Rect(rect)
        face = (208, 208, 208) if hover else (192, 192, 192)
        pygame.draw.rect(screen, face, rr)
        _L = (255, 255, 255); _D = (64, 64, 64)
        if pressed:
            pygame.draw.line(screen, _D, rr.topleft, (rr.right - 1, rr.y))
            pygame.draw.line(screen, _D, rr.topleft, (rr.x, rr.bottom - 1))
            pygame.draw.line(screen, _L, (rr.x + 1, rr.bottom - 1), rr.bottomright)
            pygame.draw.line(screen, _L, (rr.right - 1, rr.y + 1), rr.bottomright)
        else:
            pygame.draw.line(screen, _L, rr.topleft, (rr.right - 1, rr.y))
            pygame.draw.line(screen, _L, rr.topleft, (rr.x, rr.bottom - 1))
            pygame.draw.line(screen, _D, (rr.x + 1, rr.bottom - 1), rr.bottomright)
            pygame.draw.line(screen, _D, (rr.right - 1, rr.y + 1), rr.bottomright)
    except Exception:
        pass

def _ui_90s_gradient_bar(rect, top_col, bottom_col):
    """Classic Win98-style vertical gradient bar."""
    try:
        rr = pygame.Rect(rect)
        top = tuple(top_col); bot = tuple(bottom_col)
        for iy in range(rr.height):
            t = iy / max(1, rr.height - 1)
            c = tuple(int(top[k] + (bot[k] - top[k]) * t) for k in range(3))
            pygame.draw.line(screen, c, (rr.x, rr.y + iy), (rr.right - 1, rr.y + iy), 1)
    except Exception:
        try:
            pygame.draw.rect(screen, top_col, rect)
        except Exception:
            pass

def _ui_90s_splash_bg(sw, sh):
    """Win95 setup-wizard desktop: teal gradient + diagonal stripe pattern."""
    try:
        key = (int(sw), int(sh))
        surf = _UI_90S_SPLASH_BG.get(key)
        if surf is not None:
            return surf
        surf = pygame.Surface((int(sw), int(sh)))
        top = (0, 128, 128); bot = (0, 56, 88)
        for yy in range(int(sh)):
            t = yy / max(1, int(sh) - 1)
            c = tuple(int(top[k] + (bot[k] - top[k]) * t) for k in range(3))
            pygame.draw.line(surf, c, (0, yy), (int(sw), yy), 1)
        stripes = pygame.Surface((int(sw), int(sh)), pygame.SRCALPHA)
        for xx in range(-int(sh), int(sw) + int(sh), 18):
            pygame.draw.line(stripes, (0, 0, 0, 26), (xx, 0), (xx + int(sh), int(sh)), 2)
        surf.blit(stripes, (0, 0))
        _UI_90S_SPLASH_BG.clear()
        _UI_90S_SPLASH_BG[key] = surf
        return surf
    except Exception:
        return None

def _ui_90s_taskbar_draw():
    """Win95 desktop taskbar: Start button with the 4-color flag, an active
    task slot, tray clock, and the pop-up Start menu. Drawn last, on top of
    everything, every frame while 90s UI Mode is active."""
    st = _UI_90S_TASKBAR
    try:
        sw, sh = screen.get_size()
        th = _UI_90S_TASKBAR_H
        bar = pygame.Rect(0, sh - th, sw, th)
        pygame.draw.rect(screen, (192, 192, 192), bar)
        pygame.draw.line(screen, (255, 255, 255), (0, bar.y), (sw, bar.y), 1)
        pygame.draw.line(screen, (128, 128, 128), (0, bar.y + 1), (sw, bar.y + 1), 1)
        mouse = pygame.mouse.get_pos()
        # START button + windows flag
        start = pygame.Rect(4, bar.y + 4, 74, th - 8)
        st["start_rect"] = start
        _ui_90s_bevel_rect(start, pressed=bool(st.get("menu_open")), hover=start.collidepoint(mouse))
        flag = pygame.Rect(start.x + 7, start.centery - 8, 16, 15)
        pygame.draw.rect(screen, (0, 0, 0), flag, 1)
        for (fx, fy), fcol in (((flag.x + 1, flag.y + 1), (255, 40, 40)),
                               ((flag.x + 8, flag.y + 1), (40, 170, 40)),
                               ((flag.x + 1, flag.y + 8), (40, 80, 255)),
                               ((flag.x + 8, flag.y + 8), (255, 220, 40))):
            pygame.draw.rect(screen, fcol, (fx, fy, 6, 6))
        lbl = _ui_90s_text(12, "Start", bold=True)
        if lbl: screen.blit(lbl, (flag.right + 5, start.centery - lbl.get_height() // 2))
        # active task slot (sunken = focused)
        task_w = min(240, max(120, sw - 360))
        task = pygame.Rect(start.right + 6, bar.y + 5, task_w, th - 10)
        _ui_90s_bevel_rect(task, pressed=True)
        tname = _ui_90s_text(11, f" ARENA STUDIO - {(current_project_name or 'UNSAVED')[:16]}", bold=True)
        if tname: screen.blit(tname, (task.x + 6, task.centery - tname.get_height() // 2))
        # tray clock (sunken)
        clock = pygame.Rect(sw - 88, bar.y + 5, 84, th - 10)
        _ui_90s_bevel_rect(clock, pressed=True)
        try:
            _ck = time.strftime("%I:%M %p").lstrip("0")
        except Exception:
            _ck = "--:--"
        csurf = _ui_90s_text(11, " " + _ck + " ")
        if csurf: screen.blit(csurf, (clock.right - csurf.get_width() - 3, clock.centery - csurf.get_height() // 2))
        # START MENU
        if st.get("menu_open"):
            items = [("90s UI Mode: ON" if UI_90S_MODE else "90s UI Mode: OFF", "toggle_90s"),
                     ("Settings...", "settings"),
                     (None, "sep"),
                     ("Shut Down...", "shutdown")]
            mw = 232
            mh = 6 + sum(9 if key == "sep" else 24 for _, key in items) + 6
            menu = pygame.Rect(start.x, max(2, bar.y - mh - 2), mw, mh)
            pygame.draw.rect(screen, (192, 192, 192), menu)
            pygame.draw.line(screen, (255, 255, 255), menu.topleft, (menu.right - 2, menu.y))
            pygame.draw.line(screen, (255, 255, 255), menu.topleft, (menu.x, menu.bottom - 2))
            pygame.draw.line(screen, (64, 64, 64), (menu.x, menu.bottom - 1), menu.bottomright)
            pygame.draw.line(screen, (64, 64, 64), (menu.right - 1, menu.y), menu.bottomright)
            rects = []
            iy = menu.y + 4
            for label, key in items:
                if key == "sep":
                    pygame.draw.line(screen, (128, 128, 128), (menu.x + 4, iy + 4), (menu.right - 4, iy + 4), 1)
                    pygame.draw.line(screen, (255, 255, 255), (menu.x + 4, iy + 5), (menu.right - 4, iy + 5), 1)
                    iy += 10
                    continue
                r = pygame.Rect(menu.x + 4, iy, mw - 8, 22)
                hov = r.collidepoint(mouse)
                if hov:
                    pygame.draw.rect(screen, (0, 0, 128), r)  # classic selection
                    col = (255, 255, 255)
                else:
                    col = (0, 0, 0)
                txt = _ui_90s_text(11, label, bold=hov, color=col)
                if txt: screen.blit(txt, (r.x + 8, r.centery - txt.get_height() // 2))
                rects.append((r, key))
                iy += 23
            st["menu_rect"] = menu
            st["menu_rects"] = rects
        else:
            st["menu_rect"] = None
            st["menu_rects"] = []
    except Exception:
        pass

def _ui_90s_taskbar_click(pos):
    """Route a left click into the taskbar / Start menu. Returns True when
    the click is consumed (nothing underneath receives it)."""
    st = _UI_90S_TASKBAR
    try:
        if not _ui_90s_active():
            return False
        if st.get("menu_open"):
            for r, key in (st.get("menu_rects") or []):
                if r.collidepoint(pos):
                    st["menu_open"] = False
                    try:
                        if key == "toggle_90s":
                            _ui_90s_toggle_from_ui()
                        elif key == "settings":
                            global active_tab
                            active_tab = "style"
                        elif key == "shutdown":
                            pygame.event.post(pygame.event.Event(pygame.QUIT))
                    except Exception:
                        pass
                    return True
            mrect = st.get("menu_rect")
            if mrect is not None and mrect.collidepoint(pos):
                st["menu_open"] = False
                return True
            # Click outside the menu: close it, let the app act normally.
            st["menu_open"] = False
            return False
        sr = st.get("start_rect")
        if sr is not None and sr.collidepoint(pos):
            st["menu_open"] = True
            return True
        sw, sh = screen.get_size()
        if pos[1] >= sh - _UI_90S_TASKBAR_H:
            return True  # the taskbar strip swallows clicks
    except Exception:
        pass
    return False

def _ui_90s_taskbar_event(event):
    """Top-level input gate: the taskbar/Start-menu claims events first."""
    try:
        if not _ui_90s_active():
            return False
        st = _UI_90S_TASKBAR
        if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE and st.get("menu_open"):
            st["menu_open"] = False
            return True
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            return _ui_90s_taskbar_click(event.pos)
    except Exception:
        pass
    return False

