def _ui_feedback_sound(kind):
    try:
        init=pygame.mixer.get_init()
        if not init:return None
        rate,fmt,channels=init;key=(str(kind),rate,fmt,channels);hit=_UI_FEEDBACK_SOUNDS.get(key)
        if hit is not None:return hit
        duration=.055 if kind=="click" else .34;n=max(8,int(rate*duration));t=np.arange(n,dtype=np.float64)/float(rate)
        if kind=="click":
            # A short two-tone rounded tap: no harsh square wave or cheap beep.
            phase=2*math.pi*(760*t-110*t*t);wave=(np.sin(phase)+.28*np.sin(2*math.pi*1180*t))*((1-np.exp(-t*420))*np.exp(-t*58))
        else:
            phase=2*math.pi*(245*t-105*t*t);wave=(np.sin(phase)+.42*np.sin(phase*.51)+.18*np.sin(2*math.pi*92*t))*((1-np.exp(-t*90))*np.exp(-t*5.8))
        peak=.20 if kind=="click" else .34;mono=np.clip(wave*32767*peak,-32767,32767).astype(np.int16)
        arr=np.repeat(mono[:,None],max(1,int(channels)),axis=1) if int(channels)>1 else mono
        hit=pygame.sndarray.make_sound(np.ascontiguousarray(arr));_UI_FEEDBACK_SOUNDS[key]=hit;return hit
    except Exception:return None


def play_ui_feedback(kind="click"):
    try:
        now=time.monotonic()
        if kind=="click" and now-_UI_FEEDBACK_LAST[0]<.025:return
        _UI_FEEDBACK_LAST[0]=now;sound=_ui_feedback_sound(kind)
        if sound is not None:sound.set_volume(max(0.0,min(1.0,UI_FEEDBACK_VOLUME*master_volume_value()*(1.0 if kind=="click" else 1.35))));sound.play()
    except Exception:pass


