# Auto-discovered export tool. Names are tried in this order and the first
# match next to box_game.py wins. The .exe forms are listed first on Windows by
# _export_candidates() so a shipped build is preferred over loose source.
EXPORT_SCRIPT_NAMES = ("rec.py", "rec.exe", "rec.pyw", "rec.bat", "rec.cmd", "rec")

def _export_candidates():
    """Filenames to look for, most-preferred first.

    A frozen rec.exe beats rec.py on Windows because it needs no interpreter and
    is what a packaged copy of the tool ships as; everywhere else .exe is
    meaningless so the script comes first.
    """
    if sys.platform.startswith("win"):
        return ("rec.exe", "rec.py", "rec.pyw", "rec.bat", "rec.cmd")
    # .bat/.cmd/.exe are still listed off-Windows: people do develop on Linux
    # against a Windows build folder, and finding the file to report it beats
    # silently claiming no tool exists.
    return ("rec.py", "rec.pyw", "rec", "rec.exe", "rec.bat", "rec.cmd")

def find_export_script(folder=None):
    """Look for a rec.py / rec.exe sitting next to the game and return its path.

    Searched every time the export panel is opened rather than cached at import,
    so dropping rec.py into the folder while the editor is running is picked up
    without a restart.
    """
    base = folder or BASE_DIR
    try:
        for name in _export_candidates():
            p = os.path.join(base, name)
            if os.path.isfile(p):
                return p
    except Exception:
        pass
    # Frozen Arena Studio embeds rec.py as a module and re-enters this same EXE
    # through --arena-rec-worker. External rec.exe/rec.py still wins when present.
    if _ARENA_FROZEN and os.path.isfile(sys.executable):return os.path.abspath(sys.executable)
    return None

def _export_is_executable(path):
    """True when the file should be run directly instead of through Python."""
    ext = os.path.splitext(str(path))[1].lower()
    if ext in (".exe", ".bat", ".cmd", ".com"):
        return True
    # Extensionless file with the exec bit set (typical Linux/macOS build).
    if not ext and os.name != "nt":
        return os.access(path, os.X_OK)
    return False


def _is_bundled_recorder_path(path):
    if not _ARENA_FROZEN or not path:return False
    try:return os.path.normcase(os.path.abspath(str(path)))==os.path.normcase(os.path.abspath(sys.executable))
    except Exception:return False


def _export_tool_command(path):
    """Return the correct executable prefix for external or embedded recorder."""
    if _is_bundled_recorder_path(path):return [sys.executable,"--arena-rec-worker"]
    return [path] if _export_is_executable(path) else [sys.executable,"-u",path]


def _export_tool_label(path):
    return "Built-in Arena Recorder" if _is_bundled_recorder_path(path) else os.path.basename(str(path or ""))

# An explicit pick from the file dialog always wins over auto-discovery, so a
# user who deliberately pointed at a tool elsewhere is never silently
# overridden by an unrelated rec.py appearing in the folder.
EXPORT_SCRIPT_PATH = _editor_config.get("export_script_path")
EXPORT_SCRIPT_AUTO = False
if EXPORT_SCRIPT_PATH and not os.path.isfile(EXPORT_SCRIPT_PATH):
    EXPORT_SCRIPT_PATH = None  # stale/moved -- fall back to auto-discovery
if not EXPORT_SCRIPT_PATH:
    EXPORT_SCRIPT_PATH = find_export_script()
    EXPORT_SCRIPT_AUTO = EXPORT_SCRIPT_PATH is not None

def refresh_export_script(announce=False):
    """Re-run auto-discovery unless the user pinned a script by hand.

    Returns the resolved path (or None). `announce` toasts when the result
    changes, so hot-dropping rec.py into the folder gives visible feedback.
    """
    global EXPORT_SCRIPT_PATH, EXPORT_SCRIPT_AUTO
    # Any still-valid path is kept: a manual pick because the user chose it, and
    # an auto-detected one because re-scanning must never invalidate a tool that
    # is sitting right there and working.
    if EXPORT_SCRIPT_PATH and os.path.isfile(EXPORT_SCRIPT_PATH):
        return EXPORT_SCRIPT_PATH
    if EXPORT_SCRIPT_PATH:
        EXPORT_SCRIPT_PATH = None  # the file went away
    found = find_export_script()
    if found != EXPORT_SCRIPT_PATH:
        EXPORT_SCRIPT_PATH = found
        EXPORT_SCRIPT_AUTO = found is not None
        if announce and found:
            push_toast(f"Found export tool: {os.path.basename(found)}", kind="success")
    elif found:
        EXPORT_SCRIPT_AUTO = True
    return EXPORT_SCRIPT_PATH

