TOASTS = []  # list of dicts: {"text": str, "kind": "info"/"error"/"success", "expires": float}
SCRIPT_RUNTIME_ERRORS = []
_script_error_last_shown = {}

def push_toast(text, kind="info", seconds=4.0):
    TOASTS.append({"text": text, "kind": kind, "expires": time.time() + seconds})

def choose_export_script():
    """Opens a native file picker for the user to point at their export
    script (e.g. rec.py). Remembers the choice in editor_config.json."""
    global EXPORT_SCRIPT_PATH, EXPORT_SCRIPT_AUTO
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
        path = filedialog.askopenfilename(
            title="Choose export tool (e.g. rec.py or rec.exe)",
            initialdir=BASE_DIR,
            filetypes=[("Export tool", "*.py;*.pyw;*.exe;*.bat;*.cmd"),
                       ("Python script", "*.py;*.pyw"),
                       ("Executable", "*.exe;*.bat;*.cmd"),
                       ("All files", "*.*")],
        )
        root.destroy()
    except Exception as e:
        push_toast(f"Could not open file picker: {e}", kind="error")
        return
    if not path:
        return
    EXPORT_SCRIPT_PATH = path
    EXPORT_SCRIPT_AUTO = False  # explicit pick: stop auto-discovery overriding it
    _editor_config["export_script_path"] = path
    save_editor_config(_editor_config)
    push_toast(f"Export tool set: {os.path.basename(path)}", kind="success")

def clear_export_script():
    """Drop a manual pick and go back to auto-detecting rec.py / rec.exe."""
    global EXPORT_SCRIPT_PATH, EXPORT_SCRIPT_AUTO
    EXPORT_SCRIPT_PATH = None
    EXPORT_SCRIPT_AUTO = False
    _editor_config.pop("export_script_path", None)
    save_editor_config(_editor_config)
    refresh_export_script()
    if EXPORT_SCRIPT_PATH:
        push_toast(f"Back to auto-detect: {os.path.basename(EXPORT_SCRIPT_PATH)}", kind="success")
    else:
        push_toast(f"No rec.py / rec.exe found next to the game ({BASE_DIR}).", kind="warning")

def run_export_script():
    """OPENS the recorder tool you chose (rec.py / rec.exe) as a fully
    detached process. This only opens the recorder -- it never starts an
    export/render pipeline, so the game and your system stay responsive.
    The recorded frames folder is exposed through environment variables
    (BOX_GAME_RECORDINGS / BOX_GAME_LAST_RECORDING) for the recorder to
    use whenever you drive it yourself."""
    global export_process, export_process_started_at
    # Re-check the folder first: the tool may have been dropped in (or replaced
    # with a fresh build) since this panel was last drawn.
    refresh_export_script()
    if not EXPORT_SCRIPT_PATH:
        push_toast("No rec.py or rec.exe found next to the game -- drop one in, "
                   "or click 'Choose...'.", kind="error")
        return
    if not os.path.isfile(EXPORT_SCRIPT_PATH):
        push_toast("Recorder tool no longer exists at that path.", kind="error")
        return
    if export_process is not None and export_process.poll() is None:
        push_toast("Recorder is already open.", kind="error")
        return
    # A frozen .exe/.bat is launched directly; a .py is handed to this same
    # interpreter so it inherits the environment the game is already running in
    # (pygame, numpy and friends) instead of whatever "python" happens to be on
    # PATH -- which is the usual cause of "works for me, ModuleNotFound for you".
    cmd = _export_tool_command(EXPORT_SCRIPT_PATH)
    # The recordings folder is exposed via environment variables only.
    # rec.py/rec.exe stays zero-argument: no auto-export on launch.
    env = dict(os.environ)
    env["BOX_GAME_DIR"] = BASE_DIR
    env["BOX_GAME_RECORDINGS"] = RECORDINGS_DIR
    if record_last_saved_dir:
        # NOTE: the last recording folder is NOT passed as a command-line
        # argument anymore. Handing rec.py a folder on launch is what made it
        # immediately start rendering/encoding the recorded frames and pin
        # the CPU. Opening the recorder should just open it.
        env["BOX_GAME_LAST_RECORDING"] = record_last_saved_dir
    try:
        _launch_kwargs = {"cwd": os.path.dirname(EXPORT_SCRIPT_PATH) or BASE_DIR, "env": env}
        if os.name == "nt":
            # Own console window + own process group so the recorder opens
            # visibly and is never tied to the game's console/job.
            _launch_kwargs["creationflags"] = (
                getattr(subprocess, "CREATE_NEW_CONSOLE", 0)
                | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
            )
        else:
            _launch_kwargs["start_new_session"] = True
        export_process = subprocess.Popen(cmd, **_launch_kwargs)
        export_process_started_at = time.time()
        push_toast(f"Recorder opened: {_export_tool_label(EXPORT_SCRIPT_PATH)}", kind="info")
    except Exception as e:
        export_process = None
        push_toast(f"Failed to open recorder: {e}", kind="error")

