def make_lesson_group_from_selection():
    """Build a brand-new Smart Group of kind='lesson' from whatever
    blueprint nodes are currently selected. The Node Cluster Formation
    node's pin is the only consumer of this group type -- once a Lesson
    Group exists on the canvas, a cluster node can be pinned to it and
    Teach will reuse the group's nodes instead of the transient selection."""
    selected = set(modal.get("ns_multi_selected") or set())
    if modal.get("ns_selected") is not None:
        selected.add(modal["ns_selected"])
    # Don't include the cluster node itself inside its own lesson group --
    # groups describe the supporting graph, not the consumer of it.
    nodes = modal.get("ns_nodes", {})
    for _nid in list(selected):
        _node = nodes.get(_nid)
        if _node and _node.get("type") == "node_cluster_formation":
            selected.discard(_nid)
    selected = {nid for nid in selected if nid in nodes}
    if not selected:
        push_toast("Select the lesson's nodes first, then use the Node Docker to group them.", "warning", 4.0)
        return
    existing_groups = modal.get("ns_smart_groups", [])
    used_ids = {g.get("id") for g in existing_groups}
    gid = int(time.time() * 1000) % 100000000
    while gid in used_ids:
        gid = (gid + 1) % 100000000
    group = {
        "id": gid,
        "name": "Lesson Group",
        "node_ids": sorted(selected),
        "child_group_ids": [],
        "collapsed": False,
        "frozen": False,
        "color": [255, 190, 80],
        "icon": "folder",
        "description": "Made from Node Docker. Pin a Node Cluster Formation node to this group to teach lessons from it.",
        "tags": ["lesson"],
        "padding_scale": 1.0,
        "x": 0, "y": 0, "w": 260, "h": 160,
        "kind": "lesson",
        "lesson_cluster_id": None,  # nothing pinned yet
    }
    existing_groups.append(group)
    _ns_sync_smart_group_bounds(group)
    modal["ns_selected_groups"] = {gid}
    modal["ns_dirty"] = True
    push_toast(f"Lesson Group created · {len(selected)} node(s) ready to teach.", "success", 3.5)

