def draw_gpu_finalize_progress():
    """Small modeless compiling window; the rest of Arena remains usable."""
    global _gpu_finalize_job
    job = _gpu_finalize_job
    if not isinstance(job, dict):
        return
    if job.get("done"):
        linger = 7.0 if job.get("success") else 14.0
        if time.time() - job.get("completed_at", time.time()) > linger:
            _gpu_finalize_job = None
            return
    width = min(520, max(360, WIDTH - 32))
    height = 142
    rect = pygame.Rect(WIDTH - width - 18, 18, width, height)
    shadow = pygame.Surface((width + 16, height + 16), pygame.SRCALPHA)
    pygame.draw.rect(shadow, (0, 0, 0, 105), shadow.get_rect(), border_radius=16)
    screen.blit(shadow, (rect.x - 8, rect.y + 4))
    panel = pygame.Surface(rect.size, pygame.SRCALPHA)
    pygame.draw.rect(panel, (15, 18, 24, 248), panel.get_rect(), border_radius=13)
    border = GOOD if job.get("success") else DANGER if job.get("done") else ACCENT
    pygame.draw.rect(panel, (*border, 235), panel.get_rect(), width=1, border_radius=13)
    screen.blit(panel, rect.topleft)
    running = not job.get("done")
    title = "GPU VIDEO COMPILER" if running else ("GPU VIDEO READY" if job.get("success") else "GPU COMPILE FAILED")
    title_s = font_sm.render(title, True, border)
    screen.blit(title_s, (rect.x + 18, rect.y + 13))
    badge = font_tiny.render("BUILT IN · NO REC.PY", True, TEXT_FAINT)
    screen.blit(badge, (rect.right - badge.get_width() - 18, rect.y + 15))
    phase = font_tiny.render(str(job.get("phase", "Finalizing video"))[:78], True, TEXT_MAIN)
    screen.blit(phase, (rect.x + 18, rect.y + 39))
    progress = max(0.0, min(1.0, float(job.get("progress", 0.0))))
    bar = pygame.Rect(rect.x + 18, rect.y + 65, rect.width - 36, 16)
    ui_draw_rect(screen, FIELD_BG, bar, border_radius=8)
    fill = bar.copy()
    fill.width = max(0, int(bar.width * progress))
    if fill.width:
        ui_draw_rect(screen, border, fill, border_radius=8)
        if running and fill.width > 8:
            sheen_x = fill.x + int((time.time() * 90) % max(1, fill.width))
            pygame.draw.line(screen, (255, 255, 255), (sheen_x, fill.y + 2), (sheen_x, fill.bottom - 3), 2)
    ui_draw_rect(screen, PANEL_BORDER, bar, width=1, border_radius=8)
    pct = font_tiny.render(f"{int(progress * 100):d}%", True, TEXT_MAIN)
    screen.blit(pct, (bar.centerx - pct.get_width() // 2, bar.centery - pct.get_height() // 2))
    status = str(job.get("status", "Compiling in the background"))
    if running:
        speed = max(0.0, float(job.get("speed", 0.0) or 0.0))
        remain = max(0.0, float(job.get("duration", 0.0)) - float(job.get("out_time", 0.0)))
        eta = (remain / speed) if speed > 0.01 else None
        detail = f"{status}  ·  {speed:.2f}×" if speed else status
        if eta is not None:
            detail += f"  ·  about {int(eta // 60):02d}:{int(eta % 60):02d} remaining"
    else:
        detail = status
    detail_s = font_tiny.render(detail[:92], True, TEXT_DIM if running else border)
    screen.blit(detail_s, (rect.x + 18, rect.y + 91))
    folder = os.path.basename(str(job.get("rec_dir", "")))
    foot_text=truncate_text_to_width(font_tiny,f"{folder}  ·  You can keep using Arena Studio while this finishes.",rect.width-36)
    foot = font_tiny.render(foot_text, True, TEXT_FAINT)
    screen.blit(foot, (rect.x + 18, rect.y + 116))


# ---- Experimental Windows-safe multi-process APU renderer -----------------
def _apu_surface_from_rgba(raw,size):
    # Pygame 2 names these frombytes/tobytes; older supported builds expose the
    # identical lossless APIs as fromstring/tostring. Supporting both avoids a
    # worker-only AttributeError on older Windows installations.
    loader=getattr(pygame.image,"frombytes",None) or getattr(pygame.image,"fromstring")
    return loader(raw,tuple(size),"RGBA")


def _apu_register_pickle_reducers():
    import copyreg
    def reduce_surface(surface):
        saver=getattr(pygame.image,"tobytes",None) or getattr(pygame.image,"tostring")
        return _apu_surface_from_rgba,(saver(surface,"RGBA",False),surface.get_size())
    def reduce_vec(value):return pygame.Vector2,((float(value.x),float(value.y)),)
    def reduce_rect(value):return pygame.Rect,((int(value.x),int(value.y),int(value.w),int(value.h)),)
    copyreg.pickle(pygame.Surface,reduce_surface);copyreg.pickle(pygame.Vector2,reduce_vec);copyreg.pickle(pygame.Rect,reduce_rect)


def _apu_pickle_sanitize(value,seen=None):
    """Remove logic/process handles while preserving all render-visible data."""
    if seen is None:seen=set()
    ident=id(value)
    if ident in seen:return
    if isinstance(value,(dict,list,set,tuple)):seen.add(ident)
    if isinstance(value,dict):
        for key in list(value.keys()):
            item=value.get(key)
            if key in ("script_ns","_audio_channel","_channel","channel") or callable(item):value[key]=None
            else:_apu_pickle_sanitize(item,seen)
    elif isinstance(value,list):
        for i,item in enumerate(value):
            if callable(item):value[i]=None
            else:_apu_pickle_sanitize(item,seen)
    elif isinstance(value,set):
        # Runtime sets are normally strings/ids. Callable members are irrelevant.
        for item in list(value):
            if callable(item):value.discard(item)
            else:_apu_pickle_sanitize(item,seen)
    elif isinstance(value,tuple):
        for item in value:_apu_pickle_sanitize(item,seen)


def _apu_worker_command(chunk_path,rec_dir,width,height,encoding,progress_path,error_path):
    args=["--arena-apu-worker",chunk_path,rec_dir,str(int(width)),str(int(height)),str(encoding),progress_path,error_path]
    # Source workers are unbuffered so bootstrap output reaches disk even if a
    # worker dies abruptly. Frozen executables receive only application args.
    return [sys.executable]+args if getattr(sys,"frozen",False) else [sys.executable,"-u",os.path.abspath(__file__)]+args


def _run_apu_worker_cli():
    """Hidden child entry: load one independent state chunk and render it."""
    import pickle
    try:
        marker=sys.argv.index("--arena-apu-worker");chunk_path,rec_dir=sys.argv[marker+1],sys.argv[marker+2];width,height=int(sys.argv[marker+3]),int(sys.argv[marker+4]);encoding=sys.argv[marker+5];progress_path,error_path=sys.argv[marker+6],sys.argv[marker+7]
        _apu_register_pickle_reducers()
        with open(chunk_path,"rb") as handle:
            # One Unpickler retains the cross-record memo produced by the
            # matching Pickler, so shared sprite/font surfaces are loaded once.
            _unpickler=pickle.Unpickler(handle);first=_unpickler.load()
            if isinstance(first,dict) and first.get("apu_stream_chunk"):
                _count=max(0,int(first.get("count",0)));chunk=(_unpickler.load() for _ in range(_count))
            else:chunk=first
            done=0
            for frame_index,state in chunk:
                _render_recording_state_to_png(state,int(frame_index),rec_dir,output_size=(width,height),encoding=encoding,async_save=False);done+=1
                temp=progress_path+".tmp"
                with open(temp,"w",encoding="utf-8") as pf:pf.write(str(done))
                os.replace(temp,progress_path)
        return 0
    except Exception:
        try:
            with open(error_path,"w",encoding="utf-8") as ef:ef.write(traceback.format_exc())
        except Exception:pass
        return 1


def _start_apu_multiprocess_render(rec_dir,states,target_size,encoding="fast",progress_job=None):
    """Serialize render-only chunks once, then launch 2-4 independent workers."""
    import pickle
    total=len(states)
    if total<=1:return None
    # Gradient reconstruction is bounded now, so restore configurable parallel
    # APU workers. Preparation remains asynchronous and worker failure can no
    # longer terminate Arena Studio.
    worker_count=max(2,min(4,int(_editor_config.get("apu_process_workers",2) or 2),total))
    scale=max(.35,min(1.0,float(_editor_config.get("apu_render_scale",.7071) or .7071)));tw,th=target_size;rw=max(2,int(round(tw*scale)));rh=max(2,int(round(th*scale)));rw-=rw%2;rh-=rh%2
    work_dir=os.path.join(rec_dir,"_apu_multiprocess");shutil.rmtree(work_dir,ignore_errors=True);os.makedirs(work_dir,exist_ok=True)
    _apu_register_pickle_reducers();indexed=list(enumerate(states));chunks=[indexed[i::worker_count] for i in range(worker_count)];processes=[];progress_paths=[];error_paths=[];bootstrap_paths=[]
    try:
        for i,chunk in enumerate(chunks):
            chunk_path=os.path.join(work_dir,f"chunk_{i}.pkl");progress=os.path.join(work_dir,f"progress_{i}.txt");error=os.path.join(work_dir,f"error_{i}.log");bootstrap=os.path.join(work_dir,f"bootstrap_{i}.log")
            # Stream one snapshot per pickle record and yield between records.
            # A giant pickle.dump(list_of_every_frame) can hold the GIL long
            # enough for Windows to label Arena Not Responding.
            with open(chunk_path,"wb") as handle:
                _pickler=pickle.Pickler(handle,protocol=pickle.HIGHEST_PROTOCOL);_pickler.dump({"apu_stream_chunk":True,"count":len(chunk)})
                for _entry in chunk:
                    _apu_pickle_sanitize(_entry);_pickler.dump(_entry);handle.flush()
                    if isinstance(progress_job,dict):
                        progress_job["prepared_frames"]=int(progress_job.get("prepared_frames",0))+1;progress_job["status"]=f"Serializing frame states {progress_job['prepared_frames']:,}/{total:,} · deduplicating shared sprites/assets"
                    time.sleep(0)
            cmd=_apu_worker_command(chunk_path,rec_dir,rw,rh,encoding,progress,error);env=dict(os.environ);env["SDL_VIDEODRIVER"]="dummy";env["SDL_AUDIODRIVER"]="dummy";env["ARENA_APU_WORKER"]="1";env["PYTHONUNBUFFERED"]="1"
            # Never discard hidden-child output. A separate bootstrap log catches
            # import/startup tracebacks that occur before error_<n>.log can open.
            _bootstrap_stream=open(bootstrap,"w",encoding="utf-8",errors="replace")
            try:
                kw={"cwd":BASE_DIR,"stdin":subprocess.DEVNULL,"stdout":_bootstrap_stream,"stderr":subprocess.STDOUT,"env":env}
                if os.name=="nt":kw["creationflags"]=getattr(subprocess,"CREATE_NO_WINDOW",0)
                _proc=subprocess.Popen(cmd,**kw)
            finally:
                _bootstrap_stream.close()
            if os.name=="nt":
                try:
                    import ctypes
                    _kh=int(_proc._handle);ctypes.windll.kernel32.SetPriorityClass(_kh,0x00004000)  # BELOW_NORMAL
                    # Reserve logical core 0 for Arena's editor/terminal. Each
                    # single-threaded renderer gets a different remaining core.
                    _cores=max(1,int(os.cpu_count() or 1))
                    if _cores>1:ctypes.windll.kernel32.SetProcessAffinityMask(_kh,(1 << (1+(i%(_cores-1)))))
                except Exception:pass
            processes.append(_proc);progress_paths.append(progress);error_paths.append(error);bootstrap_paths.append(bootstrap)
        return {"apu":True,"apu_mp":True,"rec_dir":rec_dir,"processes":processes,"progress_paths":progress_paths,"error_paths":error_paths,"bootstrap_paths":bootstrap_paths,"work_dir":work_dir,"total":total,"done":0,"cancelled":False,"output_size":(rw,rh),"target_size":tuple(target_size),"render_scale":scale,"encoding":encoding,"worker_count":worker_count,"started":time.time()}
    except Exception:
        _parent_trace=traceback.format_exc()
        for process in processes:
            try:process.terminate()
            except Exception:pass
        # Preserve every artifact. The parent converts this caught failure into
        # a visible yellow problem report instead of silently falling back.
        try:
            with open(os.path.join(work_dir,"parent_startup_error.log"),"w",encoding="utf-8") as handle:handle.write(_parent_trace)
        except Exception:pass
        raise


def _start_apu_multiprocess_async(rec_dir,states,target_size,encoding="fast"):
    """Prepare worker chunks off the UI thread so STOP never blocks the window."""
    placeholder={"apu":True,"apu_preparing":True,"rec_dir":rec_dir,"total":len(states),"done":0,
                 "cancelled":False,"started":time.time(),"status":"Checking frame count · serializing snapshots · gathering assets","stage":"prepare"}
    def prepare():
        try:
            result=_start_apu_multiprocess_render(rec_dir,states,target_size,encoding,placeholder)
            if placeholder.get("cancelled"):
                for proc in (result or {}).get("processes",[]):
                    try:proc.terminate()
                    except Exception:pass
                placeholder.clear();placeholder.update({"apu":True,"rec_dir":rec_dir,"total":len(states),"done":0,"cancelled":True,"states":states})
                return
            if result is None:raise RuntimeError("multiprocess preparation returned no job")
            placeholder.clear();placeholder.update(result)
        except Exception:
            error=traceback.format_exc();problem=os.path.join(rec_dir,"apu_prepare_problem.txt")
            try:Path(problem).write_text(error,encoding="utf-8")
            except Exception:pass
            placeholder.clear();placeholder.update({"apu":True,"apu_prepare_failed":True,"rec_dir":rec_dir,"total":len(states),"done":0,"cancelled":False,"status":"Background worker preparation failed safely","prepare_error":error,"problem_path":problem})
    threading.Thread(target=prepare,name="ArenaAPUPrepare",daemon=True).start()
    return placeholder


def _process_apu_multiprocess_job(job):
    global export_render_job,_apu_compile_job
    if job.get("cancelled"):
        for process in job.get("processes",[]):
            try:
                if process.poll() is None:process.terminate()
            except Exception:pass
        shutil.rmtree(job.get("work_dir",""),ignore_errors=True);export_render_job=None
        if isinstance(_apu_compile_job,dict):_apu_compile_job.update({"done":True,"success":False,"status":"Multi-process rebuild cancelled","completed_at":time.time()})
        return
    done=0
    for path in job.get("progress_paths",[]):
        try:done+=int(Path(path).read_text().strip() or 0)
        except Exception:pass
    _now=time.time();_previous=int(job.get("done",0));job["done"]=min(job["total"],done);elapsed=max(.001,_now-job.get("started",_now));rw,rh=job.get("output_size",(0,0));tw,th=job.get("target_size",(rw,rh))
    if job["done"]>_previous:
        if _previous>0:
            _sample=(_now-float(job.get("throughput_sample_time",_now)))/max(1,job["done"]-_previous);_old=float(job.get("effective_sec_per_frame",_sample));job["effective_sec_per_frame"]=_old*.7+_sample*.3
        job["throughput_sample_time"]=_now
    if not isinstance(_apu_compile_job,dict) or _apu_compile_job.get("kind")!="rebuild-mp":
        _apu_compile_job={"kind":"rebuild-mp","process":None,"rec_dir":job["rec_dir"],"total":job["total"],"frame":job["done"],"fps":record_fps,"width":rw,"height":rh,"target_width":tw,"target_height":th,"progress":0.0,"started":job["started"],"status":"Retrieving frame assets and starting render workers","stage":"rebuild","done":False,"success":None}
    if job["done"]<=0:_mp_status=f"Retrieving assets and loading {job.get('worker_count',0)} renderer(s) · {elapsed:.0f}s elapsed"
    elif "effective_sec_per_frame" not in job:_mp_status=f"Rendering PNG frames {job.get('done',0):,}/{job.get('total',0):,} · first outputs arriving"
    else:_mp_status=f"Rendering PNG frames {job.get('done',0):,}/{job.get('total',0):,} with {job.get('worker_count',0)} workers · {job['effective_sec_per_frame']:.2f}s/frame"
    _apu_compile_job.update({"frame":job["done"],"progress":min(.995,job["done"]/max(1,job["total"])),"status":_mp_status})
    codes=[p.poll() for p in job.get("processes",[])];failed=any(code not in (None,0) for code in codes)
    if failed:
        # Stop sibling workers before presenting the report, but preserve all
        # states, PNGs, and diagnostic files for inspection/recovery.
        for process in job.get("processes",[]):
            try:
                if process.poll() is None:process.terminate()
            except Exception:pass
        details=[]
        diagnostic_paths=list(job.get("error_paths",[]))+list(job.get("bootstrap_paths",[]))
        for path in diagnostic_paths:
            try:
                text=Path(path).read_text(encoding="utf-8",errors="replace").strip()
                if text:details.append(f"===== {os.path.basename(path)} =====\n{text}")
            except Exception as read_exc:
                details.append(f"===== {os.path.basename(path)} =====\nCould not read diagnostic: {read_exc}")
        report=(f"APU MULTI-PROCESS RENDERER FAILURE\n"
                f"Arena Studio: {APP_VERSION}\nRecording: {job.get('rec_dir','')}\n"
                f"Worker exit codes: {codes}\nCompleted frames: {job.get('done',0)} / {job.get('total',0)}\n"
                f"Diagnostic folder: {job.get('work_dir','')}\n\n"
                +("\n\n".join(details) if details else "No child traceback was produced. Bootstrap and worker logs were still preserved."))
        report_path=os.path.join(job.get("work_dir") or job.get("rec_dir") or BASE_DIR,"apu_multiprocess_problem.txt")
        try:Path(report_path).write_text(report,encoding="utf-8")
        except Exception:pass
        try:
            meta_path=os.path.join(job.get("rec_dir",""),"meta.json");meta_data=json.load(open(meta_path,encoding="utf-8"));meta_data["apu_worker_failed"]=True;meta_data["apu_failure_report"]=os.path.relpath(report_path,job.get("rec_dir") or BASE_DIR);json.dump(meta_data,open(meta_path,"w",encoding="utf-8"),indent=2)
        except Exception:pass
        export_render_job=None;_apu_compile_job.update({"done":True,"success":False,"status":"Worker failed · opening detected-problem report","completed_at":time.time()})
