def _apu_compile_reader(job,process):
    """Drain rec.py/FFmpeg output continuously and convert it to popup progress."""
    try:
        with open(job["log_path"],"w",encoding="utf-8",errors="replace") as log:
            for raw in process.stdout:
                line=str(raw).strip()
                if not line:continue
                log.write(line+"\n");log.flush();job["last_line"]=line[-400:]
                match=re.search(r"frame=\s*(\d+)",line)
                if match:
                    frame=int(match.group(1));job["frame"]=max(job.get("frame",0),frame);job["progress"]=min(.995,frame/max(1,int(job.get("total",1))));job["stage"]="encode";job["status"]=f"Encoding H.264 frame {frame:,}/{int(job.get('total',0)):,} at {int(job.get('fps',0))} FPS · mixing {int(job.get('audio_event_count',0))} audio cue(s)"+ (" + BGM" if job.get("has_bgm") else "")
                tmatch=re.search(r"time=\s*(\d+):(\d+):(\d+(?:\.\d+)?)",line)
                if tmatch:
                    sec=int(tmatch.group(1))*3600+int(tmatch.group(2))*60+float(tmatch.group(3));job["out_time"]=sec
                    if job.get("duration",0)>0:job["progress"]=max(job.get("progress",0),min(.995,sec/job["duration"]))
                smatch=re.search(r"speed=\s*([0-9.]+)x",line)
                if smatch:
                    try:job["speed"]=float(smatch.group(1))
                    except Exception:pass
                if line.startswith("Done:"):job["progress"]=.995;job["stage"]="mux";job["status"]="Audio mixed · writing MP4 index and fast-start metadata"
    except Exception:
        job["reader_error"]=traceback.format_exc()
        raise
    finally:job["reader_done"]=True


