    title_s=font_sm.render(title,True,border);screen.blit(title_s,(rect.x+14,rect.y+10));min_r=pygame.Rect(rect.right-62,rect.y+7,24,24);cancel_r=pygame.Rect(rect.right-32,rect.y+7,24,24);draw_button(min_r,"□" if minimized else "_",min_r.collidepoint(pygame.mouse.get_pos()),small=True,muted=True);draw_button(cancel_r,"×",cancel_r.collidepoint(pygame.mouse.get_pos()),small=True,danger=True)
