    progress=max(0.0,min(1.0,float(job.get("progress",0))));pct_text=f"{int(progress*100)}%"
    if minimized:
        ps=font_tiny.render(("PAUSED · " if rebuild and _APU_REBUILD_PAUSED else "")+pct_text,True,TEXT_MAIN);screen.blit(ps,(min_r.x-ps.get_width()-8,rect.y+11));return
    dims=((f"{job.get('width',0)}×{job.get('height',0)} → {job.get('target_width',0)}×{job.get('target_height',0)}" if rebuild and (job.get('target_width'),job.get('target_height'))!=(job.get('width'),job.get('height')) else f"{job.get('width',0)}×{job.get('height',0)}")+f" · {job.get('fps',0)} FPS · {job.get('frame',0):,}/{job.get('total',0):,} frames")
    screen.blit(font_tiny.render(dims,True,TEXT_MAIN),(rect.x+16,rect.y+40));bar=pygame.Rect(rect.x+16,rect.y+64,rect.width-32,17);ui_draw_rect(screen,FIELD_BG,bar,border_radius=8);fill=bar.copy();fill.width=int(bar.width*progress)
