def _sanitize_render_text(s):
    if not isinstance(s, str):
        s = str(s)
    return s.replace("\x00", "").replace("\r", "").strip("\x00")


def _ui_rect_visible(rect,margin=0,use_clip=True):
    """True only for pixels that can actually reach the current screen clip."""
    if not isinstance(rect,pygame.Rect) or rect.width<=0 or rect.height<=0:return False
    try:
        probe=rect.inflate(int(margin)*2,int(margin)*2) if margin else rect
        if not probe.colliderect(screen.get_rect()):return False
        clip=screen.get_clip() if use_clip else None
        return not isinstance(clip,pygame.Rect) or probe.colliderect(clip)
    except Exception:return True


def draw_panel(rect, alpha=248, radius=16, color=None, border=True, shadow=True, opaque=False):
    # Round 16: the glass panel (shadow + body + sheen + border + hairline) is
    # composed ONCE and cached in _panel_composed(), then just blitted each
    # frame - it used to rebuild the shadow blur loop and the per-row sheen
    # every frame for every open panel. 'ui_quality' renders the cached box
    # at a lower internal resolution (same size on screen); 'panel_shadows'
    # can skip the shadow pass entirely.
    if not _ui_rect_visible(rect):return
    if _ui_90s_active():
        # Classic beveled panel: gray slab, light top/left, dark bottom/right.
        # No shadow, no sheen, no glass sampling.
        try:
            body = pygame.Surface(rect.size)
            body.fill(tuple((color or PANEL_BG)[:3]))
            if not opaque:
                body.set_alpha(max(0, min(255, int(alpha))))
            screen.blit(body, rect.topleft)
            _L = (255, 255, 255); _D = (64, 64, 64)
            pygame.draw.line(screen, _L, rect.topleft, (rect.right - 1, rect.y))
            pygame.draw.line(screen, _L, rect.topleft, (rect.x, rect.bottom - 1))
            pygame.draw.line(screen, _D, (rect.x, rect.bottom - 1), rect.bottomright)
            pygame.draw.line(screen, _D, (rect.right - 1, rect.y), rect.bottomright)
        except Exception:
            try:
                pygame.draw.rect(screen, color or PANEL_BG, rect)
            except Exception:
                pass
        if border:
            pygame.draw.rect(screen, PANEL_BORDER, rect, 1)
        return
    if color is None:
        color=PANEL_BG
    if opaque:
        # Scene workspaces opt out of glass entirely: no canvas sampling through
        # the panel, including when a saved $modify style had lower opacity.
        alpha=255
    if shadow and not SETTINGS.get("panel_shadows", True) and not bool(_editor_config.get("ui_global_panel_shadow",False)):
        shadow = False
    if rect.width <= 0 or rect.height <= 0:return
    border=bool(border and SETTINGS.get("panel_borders",True))
    _panel_token="PANEL_BG" if tuple(color[:3])==tuple(PANEL_BG) else "CUSTOM PANEL COLOR"
    _panel_key=_modify_register_element("panel",rect,f"Panel {rect.width}×{rect.height}",meta={"tokens":[_panel_token,"PANEL_BORDER","DIVIDER"]})
    _panel_style=_modify_style_by_key(_panel_key) if _panel_key else {}
    if _panel_style:
        pr=0 if _panel_style.get("square") else _ui_radius(int(_panel_style.get("radius",radius)));bg=_style_color(_panel_style,"bg",color);op=255 if opaque else max(0,min(255,int(_panel_style.get("opacity",alpha))))
        if _panel_style.get("shadow"):
            sr=rect.move(int(_panel_style.get("shadow_x",3)),int(_panel_style.get("shadow_y",4)));ss=pygame.Surface(sr.size,pygame.SRCALPHA);pygame.draw.rect(ss,(0,0,0,int(_panel_style.get("shadow_alpha",100))),ss.get_rect(),border_radius=pr);screen.blit(ss,sr.topleft)
        if _panel_style.get("gradient"):_draw_style_gradient(screen,rect,_style_color(_panel_style,"gradient_a",bg),_style_color(_panel_style,"gradient_b",PANEL_BG_ALT),bool(_panel_style.get("gradient_vertical")),pr,op)
        else:
            ps=pygame.Surface(rect.size,pygame.SRCALPHA);pygame.draw.rect(ps,(*bg,op),ps.get_rect(),border_radius=pr);screen.blit(ps,rect.topleft)
        _ui_panel_sheen(screen,rect,pr,True)
        bw=int(_panel_style.get("border_width",1)) if border else 0
        if bw:ui_draw_rect(screen,_style_color(_panel_style,"border",PANEL_BORDER),rect,bw,pr)
        return
    # Global component effects from Customization Studio. Per-element $modify
    # styles above always win.
    _global_pg=bool(_editor_config.get("ui_global_panel_gradient",False))
    _global_ps=bool(_editor_config.get("ui_global_panel_shadow",False)) and shadow
    if _global_pg or _global_ps:
        pr=_ui_radius(radius)
        if _global_ps:
            sx=int(_editor_config.get("ui_global_panel_shadow_x",4));sy=int(_editor_config.get("ui_global_panel_shadow_y",6));sa=max(0,min(220,int(_editor_config.get("ui_global_panel_shadow_alpha",105))))
            sr=rect.move(sx,sy);ss=pygame.Surface(sr.size,pygame.SRCALPHA);pygame.draw.rect(ss,(0,0,0,sa),ss.get_rect(),border_radius=pr);screen.blit(ss,sr.topleft)
        if _global_pg:
            _draw_style_gradient(screen,rect,_uct_effect_color("ui_global_panel_gradient_a",color),_uct_effect_color("ui_global_panel_gradient_b",PANEL_BG_ALT),bool(_editor_config.get("ui_global_panel_gradient_vertical",True)),pr,alpha)
        else:
            ps=pygame.Surface(rect.size,pygame.SRCALPHA);pygame.draw.rect(ps,(*color,alpha),ps.get_rect(),border_radius=pr);screen.blit(ps,rect.topleft)
        _ui_panel_sheen(screen,rect,pr,True)
        if border:ui_draw_rect(screen,PANEL_BORDER,rect,1,pr)
        return
    # The "Panel Corners" setting (rounded/soft/square) is meant to apply
    # everywhere, but most of the hundreds of draw_panel(...) call sites
    # across the editor pass a fixed literal `radius` and never touch this
    # setting themselves - so with "square" selected (the crisp, cheaper-to-
    # render, no-antialiased-corners look some people call "pixelated"),
    # only the handful of panels that happened to route their radius through
    # _corner_radius_scale() actually went square; everything else stayed
    # rounded. Scaling it right here, once, means every panel drawn through
    # this single shared function respects the setting automatically.
    radius = int(round(radius * _corner_radius_scale()))
    surf, ox, oy = _panel_composed(int(rect.width), int(rect.height), int(alpha),
                                   int(radius), tuple(color), bool(border), bool(shadow))
    screen.blit(surf, (rect.x + ox, rect.y + oy))

