def _modify_button_key(label):
    raw = " ".join(str(label or "button").split()).strip().lower()
    return re.sub(r"[^a-z0-9_+ .:-]+", "", raw)[:96] or "button"


def _modify_element_key(kind, label, rect=None, explicit=None):
    if explicit:
        return str(explicit)
    base = _modify_button_key(label)
    if kind == "button":
        return base
    if kind in ("icon", "section", "field"):
        return f"{kind}:{base}"
    if kind == "panel" and isinstance(rect, pygame.Rect):
        return f"panel:{rect.width}x{rect.height}:{rect.x//40}:{rect.y//40}"
    return f"{kind}:{base}"


def _modify_register_element(kind, rect, label, key=None, meta=None):
    if not isinstance(rect, pygame.Rect) or rect.width <= 0 or rect.height <= 0:
        return None
    ekey = _modify_element_key(kind, label, rect, key)
    # Offscreen and clipped controls do not exist for selection/hit purposes.
    # Returning the key preserves saved style lookup without exposing an outline.
    if not _ui_rect_visible(rect):return ekey
    if _UI_MODIFY_MODE or _UI_MODIFY_IDENTIFY or ekey in _UI_BUTTON_STYLES:
        _UI_MODIFY_ELEMENTS.append({"rect":rect.copy(),"label":str(label),"key":ekey,
                                    "kind":str(kind),"meta":dict(meta or {})})
    return ekey


def _modify_register_button(rect, label, icon=None):
    return _modify_register_element("button", rect, label, meta={"icon":icon} if icon else {})


def _modify_style(label):
    style = _UI_BUTTON_STYLES.get(_modify_button_key(label), {})
    return style if isinstance(style, dict) else {}


def _modify_style_by_key(key):
    style = _UI_BUTTON_STYLES.get(str(key), {})
    return style if isinstance(style, dict) else {}


def _modify_save_styles():
    try:
        _editor_config["ui_button_styles"] = copy.deepcopy(_UI_BUTTON_STYLES)
        _editor_config["ui_element_presets"] = copy.deepcopy(_UI_ELEMENT_PRESETS)
        _editor_config["ui_modify_panel_pos"] = list(_UI_MODIFY_PANEL_POS)
        save_editor_config(_editor_config)
        _PANEL_SURF_CACHE.clear()
    except Exception:
        pass


def _modify_set_mode(enabled):
    global _UI_MODIFY_MODE,_UI_MODIFY_IDENTIFY,_UI_MODIFY_PREV_PAUSED,paused
    was_identify=bool(_UI_MODIFY_IDENTIFY);_UI_MODIFY_MODE=bool(enabled);_UI_MODIFY_IDENTIFY=False
    if _UI_MODIFY_MODE:
        _UI_MODIFY_PREV_PAUSED = bool(paused); paused = True
        modal["type"] = None; modal["focus"] = None; _ns_terminal["open"] = False
        push_toast("UI STUDIO · app frozen · select any panel, icon, label, field or button", "info", 4.5)
    else:
        if not was_identify:paused=bool(_UI_MODIFY_PREV_PAUSED)
        _modify_save_styles();push_toast("UI Studio closed · custom UI saved" if not was_identify else "Modify Identify closed","success" if not was_identify else "info",2.5)


def _modify_set_identify(enabled=True):
    """Live hover-identification mode: no pause, freeze, modal close or fake canvas."""
    global _UI_MODIFY_MODE,_UI_MODIFY_IDENTIFY,paused
    was_full=bool(_UI_MODIFY_MODE and not _UI_MODIFY_IDENTIFY)
    if enabled and was_full:paused=bool(_UI_MODIFY_PREV_PAUSED)
    _UI_MODIFY_MODE=bool(enabled);_UI_MODIFY_IDENTIFY=bool(enabled)
    if enabled:
        _ns_terminal["open"]=False
        push_toast("MODIFY IDENTIFY · hover for type/token help · click to open full UI Studio · Esc exits","info",5.0)
    else:
        _UI_MODIFY_MODE=False;_UI_MODIFY_IDENTIFY=False
        push_toast("Modify Identify closed","info",1.8)


def _modify_identify_candidates(pos):
    viewport=pygame.Rect(0,0,WIDTH,HEIGHT);unique=[];seen=set()
    for item in reversed(_UI_MODIFY_ELEMENTS):
        visible=item.get("rect",pygame.Rect(0,0,0,0)).clip(viewport)
        if visible.width<=0 or visible.height<=0 or not visible.collidepoint(pos):continue
        sig=(item.get("key"),item.get("kind"))
        if sig in seen:continue
        seen.add(sig);copy_item=dict(item);copy_item["rect"]=visible;unique.append(copy_item)
    return sorted(unique,key=_modify_pick_priority)


def _modify_identify_click(pos):
    global _UI_MODIFY_IDENTIFY,_UI_MODIFY_SELECTED,_UI_MODIFY_SELECTED_LABEL,_UI_MODIFY_SELECTED_KIND
    global _UI_MODIFY_PREV_PAUSED,paused
    items=_modify_identify_candidates(pos)
    if not items:return False
    item=items[0];_UI_MODIFY_SELECTED=item["key"];_UI_MODIFY_SELECTED_LABEL=item["label"];_UI_MODIFY_SELECTED_KIND=item["kind"]
    _UI_MODIFY_IDENTIFY=False;_UI_MODIFY_PREV_PAUSED=bool(paused);paused=True
    push_toast(f"Opening UI Studio for {item['kind']} · {item['label']}","success",2.2)
    return True


def _modify_identify_token_hint(item):
    kind=str(item.get("kind","element"));key=str(item.get("key",""))
    hints={
      "panel":"Palette Lab: Panel / Raised Panel · Components: gradients & shadows",
      "button":"Components: semantic colors/energy · $modify Color/States/Effects",
      "field":"Palette Lab: Field / Focused Field · $modify Color/Shape",
      "section":"Palette Lab: Accent + Faint Text · $modify Content/Color",
      "slider":"Palette Lab: Accent/Field · $modify Color/Shape",
      "tab":"Palette Lab: Accent/Panel · $modify States/Color",
      "icon":"Palette Lab: Main/Dim Text · $modify Content/Color",
      "runtime":"Direct-drawn element · use $modify Inspector overrides",
    }
    explicit=", ".join(str(v) for v in (item.get("meta",{}) or {}).get("tokens",[]) if v)
    return (explicit or hints.get(kind,"Use Palette Lab for tokens or full $modify for this exact element")),key


