        if not item:return
        rect=item["rect"].clip(pygame.Rect(0,0,WIDTH,HEIGHT));col={"panel":(92,210,140),"button":(80,165,255),"field":(80,205,190),"section":(205,130,245),"slider":(245,150,95),"tab":(145,155,245),"icon":(240,195,85)}.get(item["kind"],(175,185,195))
