def _modify_selected_style(create=True):
    if not _UI_MODIFY_SELECTED:
        return None
    if create:
        return _UI_BUTTON_STYLES.setdefault(_UI_MODIFY_SELECTED,{})
    return _UI_BUTTON_STYLES.get(_UI_MODIFY_SELECTED,{})


def _modify_open_color_picker(role):
    """Use Arena Studio's existing HSV/HEX/saved-swatch picker in UI Studio."""
    if not _UI_MODIFY_SELECTED:return
    key=str(_UI_MODIFY_SELECTED);field=str(role)
    defaults={"bg":ACCENT,"text":TEXT_MAIN,"border":PANEL_BORDER,"icon_color":TEXT_MAIN,
              "gradient_a":ACCENT,"gradient_b":ACCENT_HOVER,"hover_bg":ACCENT_HOVER,
              "pressed_bg":ACCENT_DIM,"toggle_bg":GOOD,"toggle_text":TEXT_MAIN,
              "glow_color":ACCENT,"shadow_color":(0,0,0)}
    style=_UI_BUTTON_STYLES.setdefault(key,{})
    initial=tuple(style.get(field,defaults.get(field,ACCENT)))
    def apply_color(color,_key=key,_field=field):
        # The shared picker streams live changes while dragging. Keep that
        # preview responsive and save once through Done/$modify instead of
        # rewriting editor_config dozens of times per second.
        target=_UI_BUTTON_STYLES.setdefault(_key,{})
        target[_field]=list(color[:3])
        try: _PANEL_SURF_CACHE.clear()
        except Exception: pass
    open_color_picker(initial_color=initial,callback=apply_color,
                      title=f"UI Studio · {field.replace('_',' ').title()}",
                      allow_alpha=False,return_to=None)


def _modify_begin_text(field,current=""):
    global _UI_MODIFY_TEXT_EDIT,_UI_MODIFY_TEXT_BUFFER
    _UI_MODIFY_TEXT_EDIT=str(field);_UI_MODIFY_TEXT_BUFFER=str(current or "")
    try:pygame.key.start_text_input()
    except Exception:pass


def _modify_commit_text():
    global _UI_MODIFY_TEXT_EDIT, _UI_MODIFY_ICON_SEARCH, _UI_MODIFY_PRESET_NAME
    field=_UI_MODIFY_TEXT_EDIT; text=_UI_MODIFY_TEXT_BUFFER
    if field == "icon_search": _UI_MODIFY_ICON_SEARCH=text
    elif field == "tree_search": globals()["_UI_STUDIO_TREE_SEARCH"]=text
    elif field == "preset_name": _UI_MODIFY_PRESET_NAME=text.strip()[:48] or "Preset"
    elif field and _UI_MODIFY_SELECTED:
        style=_modify_selected_style(True);style[field]=text
        _modify_save_styles()
    _UI_MODIFY_TEXT_EDIT=None
    try:pygame.key.stop_text_input()
    except Exception:pass


def _modify_handle_text(text):
    global _UI_MODIFY_TEXT_BUFFER,_UI_MODIFY_ICON_SEARCH,_UI_STUDIO_TREE_SEARCH
    if _UI_MODIFY_TEXT_EDIT:
        _UI_MODIFY_TEXT_BUFFER+=str(text)[:64]
        if _UI_MODIFY_TEXT_EDIT=="icon_search":_UI_MODIFY_ICON_SEARCH=_UI_MODIFY_TEXT_BUFFER
        elif _UI_MODIFY_TEXT_EDIT=="tree_search":_UI_STUDIO_TREE_SEARCH=_UI_MODIFY_TEXT_BUFFER
        elif _UI_MODIFY_TEXT_EDIT=="preset_name":globals()["_UI_MODIFY_PRESET_NAME"]=_UI_MODIFY_TEXT_BUFFER[:48]
        elif _UI_MODIFY_SELECTED:
            _modify_selected_style(True)[_UI_MODIFY_TEXT_EDIT]=_UI_MODIFY_TEXT_BUFFER
            try:_PANEL_SURF_CACHE.clear()
            except Exception:pass


def _modify_handle_key(event):
    global _UI_MODIFY_TEXT_BUFFER, _UI_MODIFY_TEXT_EDIT
    if not _UI_MODIFY_TEXT_EDIT:return False
    if event.key==pygame.K_a and (pygame.key.get_mods() & (pygame.KMOD_CTRL|pygame.KMOD_META)):
        _UI_MODIFY_TEXT_BUFFER=""
    elif event.key==pygame.K_BACKSPACE:_UI_MODIFY_TEXT_BUFFER=_UI_MODIFY_TEXT_BUFFER[:-1]
    if event.key in (pygame.K_BACKSPACE,pygame.K_a):
        if _UI_MODIFY_TEXT_EDIT=="icon_search":globals()["_UI_MODIFY_ICON_SEARCH"]=_UI_MODIFY_TEXT_BUFFER
        elif _UI_MODIFY_TEXT_EDIT=="tree_search":globals()["_UI_STUDIO_TREE_SEARCH"]=_UI_MODIFY_TEXT_BUFFER
        elif _UI_MODIFY_TEXT_EDIT=="preset_name":globals()["_UI_MODIFY_PRESET_NAME"]=_UI_MODIFY_TEXT_BUFFER[:48]
        elif _UI_MODIFY_SELECTED:_modify_selected_style(True)[_UI_MODIFY_TEXT_EDIT]=_UI_MODIFY_TEXT_BUFFER
    elif event.key in (pygame.K_RETURN,pygame.K_KP_ENTER):_modify_commit_text()
    elif event.key == pygame.K_ESCAPE:_UI_MODIFY_TEXT_EDIT=None
    return True


def _modify_icon_names(query=""):
    names=set(str(k) for k in (IC.keys() if isinstance(IC,dict) else []))
    if _TABLER_AVAILABLE and OutlineIcon is not None:
        try:
            for n in dir(OutlineIcon):
                if n.isupper() and not n.startswith("_"):names.add(n.lower())
        except Exception:pass
    q=str(query).strip().lower().replace(" ","_")
    return sorted(n for n in names if not q or q in n)[:80]


def _ui_style_sound(style):
    sound=str(style.get("click_sound","") or "").strip()
    if not sound:return
    try:
        snd=_UI_STYLE_SOUND_CACHE.get(sound)
        if snd is None:
            path=sound
            if not os.path.isfile(path):
                hit=next((a for a in AUDIO_LIBRARY if sound.lower() in str(a.get("name","")).lower()
                          or sound.lower()==str(a.get("path","")).lower()),None)
                path=abs_from_base(hit.get("path")) if hit else ""
            if path and os.path.isfile(path):snd=pygame.mixer.Sound(path);_UI_STYLE_SOUND_CACHE[sound]=snd
        if snd:snd.play()
    except Exception:pass


def _modify_notify_ui_click(pos):
    now=time.time()
    for item in reversed(_UI_MODIFY_ELEMENTS):
        if item["rect"].collidepoint(pos):
            style=_modify_style_by_key(item["key"])
            _UI_ELEMENT_PRESSED_UNTIL[item["key"]]=now+max(.05,float(style.get("press_duration",.16)))
            if style.get("toggle_visual"):_UI_ELEMENT_TOGGLE_STATE[item["key"]]=not _UI_ELEMENT_TOGGLE_STATE.get(item["key"],False)
            _ui_style_sound(style);return


def _modify_handle_motion(pos):
    global _UI_STUDIO_PAN_LAST
    if _UI_STUDIO_PANNING:
        _UI_STUDIO_PAN[0]+=pos[0]-_UI_STUDIO_PAN_LAST[0];_UI_STUDIO_PAN[1]+=pos[1]-_UI_STUDIO_PAN_LAST[1];_UI_STUDIO_PAN_LAST[:]=pos
    elif _UI_MODIFY_DRAG_OFFSET is not None:
        _UI_MODIFY_PANEL_POS[0]=int(pos[0]-_UI_MODIFY_DRAG_OFFSET[0]);_UI_MODIFY_PANEL_POS[1]=int(pos[1]-_UI_MODIFY_DRAG_OFFSET[1])


def _modify_handle_wheel(delta):
    global _UI_STUDIO_TREE_SCROLL,_UI_STUDIO_ZOOM
    pos=pygame.mouse.get_pos()
    if _UI_STUDIO_CANVAS_RECT and _UI_STUDIO_CANVAS_RECT.collidepoint(pos):_UI_STUDIO_ZOOM=max(.2,min(5.0,_UI_STUDIO_ZOOM*(1.15**int(delta))))
    else:_UI_STUDIO_TREE_SCROLL=max(0,_UI_STUDIO_TREE_SCROLL-int(delta)*5)


def _modify_adjust(style, key, delta, lo, hi):
    style[key]=max(lo,min(hi,float(style.get(key,lo))+delta))


def _modify_pick_priority(item):
    order={"button":0,"tab":1,"field":2,"section":3,"icon":4,"slider":5,"panel":6,"runtime":7}
    rect=item.get("rect");area=(rect.width*rect.height) if isinstance(rect,pygame.Rect) else 10**12
    return (order.get(item.get("kind"),8),area)


def _modify_pick_canvas(pos):
    global _UI_MODIFY_SELECTED,_UI_MODIFY_SELECTED_LABEL,_UI_MODIFY_SELECTED_KIND
    global _UI_STUDIO_LAST_PICK_POS,_UI_STUDIO_PICK_INDEX,_UI_STUDIO_OVERLAP_CHOICES
    global _UI_STUDIO_OVERLAP_MENU,_UI_STUDIO_OVERLAP_MENU_POS
    if not _UI_STUDIO_CANVAS_RECT or not _UI_STUDIO_CANVAS_RECT.collidepoint(pos):return
    scale=max(1e-6,float(_UI_STUDIO_CANVAS_SCALE));ox,oy=_UI_STUDIO_VIEW_ORIGIN
    original=((pos[0]-ox)/scale,(pos[1]-oy)/scale)
    candidates=[it for it in reversed(_UI_MODIFY_ELEMENTS) if it["rect"].collidepoint(original)]
    unique=[];seen=set()
    for it in candidates:
        sig=(it["key"],it["kind"])
        if sig not in seen:seen.add(sig);unique.append(it)
    candidates=sorted(unique,key=_modify_pick_priority)
    _UI_STUDIO_OVERLAP_CHOICES=candidates
    if not candidates:_UI_STUDIO_OVERLAP_MENU=[];return
    if len(candidates)==1:
        item=candidates[0];_UI_MODIFY_SELECTED=item["key"];_UI_MODIFY_SELECTED_LABEL=item["label"];_UI_MODIFY_SELECTED_KIND=item["kind"];_UI_STUDIO_OVERLAP_MENU=[];return
    _UI_STUDIO_OVERLAP_MENU=list(candidates);_UI_STUDIO_OVERLAP_MENU_POS[:]=pos
    push_toast(f"{len(candidates)} overlapping elements · choose the exact layer from the popup","info",1.8)


def _modify_handle_click(pos):
    global _UI_MODIFY_SELECTED,_UI_MODIFY_SELECTED_LABEL,_UI_MODIFY_SELECTED_KIND
    global _UI_MODIFY_TAB,_UI_MODIFY_DRAG_OFFSET,_UI_MODIFY_CLIPBOARD
    for rect,action,value in reversed(_UI_MODIFY_CONTROLS):
        if not rect.collidepoint(pos):continue
        if action=="exit":_modify_set_mode(False);return
        if action=="deselect":
            globals()["_UI_MODIFY_SELECTED"]=None;globals()["_UI_MODIFY_SELECTED_LABEL"]="";globals()["_UI_MODIFY_SELECTED_KIND"]="";return
        if action=="clear_selected":
            if _UI_MODIFY_SELECTED:_UI_BUTTON_STYLES.pop(_UI_MODIFY_SELECTED,None);_modify_save_styles();push_toast("Element overrides cleared · original restored","success",2.0)
            return
        if action=="drag":_UI_MODIFY_DRAG_OFFSET=(pos[0]-rect.x,pos[1]-rect.y);return
        if action in ("select_element","select_overlap"):
            item=value;_UI_MODIFY_SELECTED=item["key"];_UI_MODIFY_SELECTED_LABEL=item["label"];_UI_MODIFY_SELECTED_KIND=item["kind"];globals()["_UI_STUDIO_OVERLAP_MENU"]=[];return
        if action=="canvas_click":_modify_pick_canvas(pos);return
        if action=="canvas_zoom":
            globals()["_UI_STUDIO_ZOOM"]=max(.2,min(5.0,float(_UI_STUDIO_ZOOM)*float(value)));return
        if action=="canvas_fit":
            globals()["_UI_STUDIO_ZOOM"]=1.0;_UI_STUDIO_PAN[:]=[0.0,0.0];return
        if action=="toggle_panel":
            if value=="hierarchy":globals()["_UI_STUDIO_SHOW_HIERARCHY"]=not _UI_STUDIO_SHOW_HIERARCHY
            elif value=="inspector":globals()["_UI_STUDIO_SHOW_INSPECTOR"]=not _UI_STUDIO_SHOW_INSPECTOR
            elif value=="focus":
                globals()["_UI_STUDIO_SHOW_HIERARCHY"]=False;globals()["_UI_STUDIO_SHOW_INSPECTOR"]=False
            return
        if action=="tab":_UI_MODIFY_TAB=str(value);return
        if action=="pick_color":_modify_open_color_picker(value);return
        if action=="edit":
            st=_modify_selected_style(False) or {};_modify_begin_text(value, _UI_MODIFY_ICON_SEARCH if value=="icon_search" else _UI_MODIFY_PRESET_NAME if value=="preset_name" else st.get(value,""));return
        if not _UI_MODIFY_SELECTED:return
        style=_modify_selected_style(True)
        if action=="color":style[str(value[0])]=list(value[1])
        elif action=="set":
            style[str(value[0])]=value[1]
            if value[0] in ("font","icon_position"):push_toast(f"{value[0].replace('_',' ').title()}: {value[1]}","info",1.2)
        elif action=="toggle":style[str(value)]=not bool(style.get(str(value),False))
        elif action=="adjust":_modify_adjust(style,*value)
        elif action=="icon":style["icon"]=str(value);push_toast(f"Icon changed to {value}","info",1.2)
        elif action=="reset":_UI_BUTTON_STYLES.pop(_UI_MODIFY_SELECTED,None)
        elif action=="copy":_UI_MODIFY_CLIPBOARD=copy.deepcopy(style)
        elif action=="paste" and isinstance(_UI_MODIFY_CLIPBOARD,dict):style.clear();style.update(copy.deepcopy(_UI_MODIFY_CLIPBOARD))
        elif action=="save_preset":
            name=_UI_MODIFY_PRESET_NAME.strip() or "Preset";_UI_ELEMENT_PRESETS[name]=copy.deepcopy(style)
        elif action=="load_preset" and value in _UI_ELEMENT_PRESETS:style.clear();style.update(copy.deepcopy(_UI_ELEMENT_PRESETS[value]))
        elif action=="delete_preset":_UI_ELEMENT_PRESETS.pop(str(value),None)
        _modify_save_styles();return
    # Full-screen Studio selection is coordinate-mapped through canvas or
    # hierarchy controls only. Never fall through to original screen-space
    # rectangles (that selected giant panels behind the preview).
    globals()["_UI_STUDIO_OVERLAP_MENU"]=[]


def _modify_font(style, default_font):
    if not style:return default_font
    try:
        family=str(style.get("font","Segoe UI"));size=int(style.get("size",getattr(default_font,"get_height",lambda:14)()))
        return pygame.font.SysFont(family,max(8,min(42,size)),bold=bool(style.get("bold",False)),italic=bool(style.get("italic",False)))
    except Exception:return default_font


def _style_color(style,key,default):
    try:return tuple(int(v) for v in list(style.get(key,default))[:3])
    except Exception:return tuple(default[:3])


def _draw_style_gradient(surface,rect,a,b,vertical=False,radius=0,alpha=255):
    radius=_ui_radius(radius);a=tuple(a[:3]);b=tuple(b[:3]);steps=max(1,rect.height if vertical else rect.width)
    layer=pygame.Surface(rect.size,pygame.SRCALPHA)
    for i in range(steps):
        t=i/max(1,steps-1);c=tuple(int(a[j]+(b[j]-a[j])*t) for j in range(3))+(int(alpha),)
        if vertical:pygame.draw.line(layer,c,(0,i),(rect.width,i))
        else:pygame.draw.line(layer,c,(i,0),(i,rect.height))
    if radius:
        mask=pygame.Surface(rect.size,pygame.SRCALPHA);pygame.draw.rect(mask,(255,255,255,255),mask.get_rect(),border_radius=int(radius));layer.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
    surface.blit(layer,rect.topleft)


