def _window_key_label(event):
    """Stable key string used by Input Key nodes (supports Ctrl/Shift/Alt)."""
    base = pygame.key.name(event.key).lower().replace(" ", "_")
    mods = pygame.key.get_mods()
    prefix = ""
    if mods & pygame.KMOD_CTRL: prefix += "ctrl+"
    if mods & pygame.KMOD_SHIFT: prefix += "shift+"
    if mods & pygame.KMOD_ALT: prefix += "alt+"
    return prefix + base

def _dispatch_window_input(key_label):
    """Send a key/mouse input into every character that has manual input enabled."""
    if modal.get("type") is not None or not simulation_started:
        return
    for _character in list(characters):
        if _character.get("hp", 0) > 0 and _character.get("manual_input_enabled", True):
            call_hook(_character, "on_input", CTX, _character, str(key_label))

