def _quick_nav_rects_for_window():
    """Return quick-nav hit targets from the same geometry used to draw,
    scaled by the current UI_FONT_SCALE so clicks still line up with the
    buttons the user actually sees after changing app font size."""
    _x = 16                                   # content.x (panel at 0 + 16 padding)
    _cw = SIDEBAR_W - 32                      # content width
    _gap = 5                                  # _quick_gap
    _w = (_cw - _gap * 2) // 3
    _sc = UI_FONT_SCALE
    # Mirrors the draw block: dynamic brand height + 12px spacing.
    _title_h = max(20, int(round(22 * _sc)))
    _sub_h   = max(12, int(round(11 * _sc)))
    _brand_h = max(50, _title_h + _sub_h + 20)
    _h = max(38, int(round(44 * _sc)))        # _quick_h
    _y = 16 + _brand_h + 12                   # content.y + brand + spacing
    return tuple(pygame.Rect(_x + (_i % 3) * (_w + _gap),
                             _y + (_i // 3) * (_h + _gap), _w, _h)
                 for _i in range(7))

