# ── Gizmo appearance kit ─────────────────────────────────────────────────────
# ONE shared marker vocabulary for every editor gizmo: weapon-rig anchors,
# identity badges, Motion Studio pivots, and preview handles. The global look
# (style / color mode / scale / thickness / opacity / labels) is configured in
# UI Customization → Gizmos & Markers; per-node color/size/thickness values
# still feed in as the base, so individual rig_position_* settings keep working.
GIZMO_STYLES = ("tech", "classic", "diamond", "brackets", "dot")
_GIZMO_MARKER_CACHE = {}

def _gizmo_prefs():
    cfg = globals().get("_editor_config", {}) or {}
    st = str(cfg.get("gizmo_style", "tech"))
    if st not in GIZMO_STYLES:
        st = "tech"
    try:
        col = tuple(int(v) for v in (cfg.get("gizmo_color") or (80, 220, 255))[:3])
    except Exception:
        col = (80, 220, 255)
    try:
        return {"style": st,
                "color_mode": str(cfg.get("gizmo_color_mode", "per_node")),
                "color": col,
                "scale": max(0.4, min(2.5, float(cfg.get("gizmo_scale", 1.0) or 1.0))),
                "thickness": max(0.5, min(3.0, float(cfg.get("gizmo_thickness", 1.0) or 1.0))),
                "opacity": max(30, min(255, int(cfg.get("gizmo_opacity", 255) or 255))),
                "labels": bool(cfg.get("gizmo_labels", True))}
    except Exception:
        return {"style": "tech", "color_mode": "per_node", "color": (80, 220, 255),
                "scale": 1.0, "thickness": 1.0, "opacity": 255, "labels": True}

def gizmo_pref_color(base):
    """Resolve a gizmo's color against the global preference: per-node colors
    pass through untouched; 'global' mode forces one color everywhere."""
    p = _gizmo_prefs()
    if p["color_mode"] == "global":
        return p["color"]
    try:
        return tuple(int(v) for v in list(base)[:3])
    except Exception:
        return p["color"]

# Per-category gizmo controls (UI Customization → Gizmos & Markers).
# Every debug/authoring overlay family gets: show toggle, color override,
# fill-alpha and outline-width scale. Keys live in editor_config as
# gz_{cat}_{field}; missing keys mean "category default".
GIZMO_CATEGORIES = (
    ("collision",  "Character Collision", (110, 195, 255)),
    ("motion",     "Motion Clip Hitboxes", (255, 90, 90)),
    ("rig",        "Weapon Rig Anchors",  (80, 220, 255)),
    ("collider",   "Rig Colliders",       (80, 255, 150)),
    ("range",      "Node Ranges & Cones", (90, 210, 255)),
    ("identity",   "Identity Badges",     (0, 220, 255)),
    ("emitter",    "Particle Emitters",   (90, 220, 255)),
    ("track",      "NPC Tracking",        (255, 200, 80)),
)

def _gz_cat(cat):
    """Per-category prefs: {'show':bool,'color':tuple|None,'alpha':0..2 fill
    multiplier,'width':0.5..3 outline multiplier}. color None = per-node."""
    cfg = globals().get("_editor_config", {}) or {}
    col = cfg.get(f"gz_{cat}_color")
    try:
        col = tuple(int(v) for v in col[:3]) if col else None
    except Exception:
        col = None
    try:
        return {"show": bool(cfg.get(f"gz_{cat}_show", True)), "color": col,
                "alpha": max(0.0, min(2.0, float(cfg.get(f"gz_{cat}_alpha", 1.0) or 1.0))),
                "width": max(0.5, min(3.0, float(cfg.get(f"gz_{cat}_width", 1.0) or 1.0)))}
    except Exception:
        return {"show": True, "color": None, "alpha": 1.0, "width": 1.0}

def gizmo_cat_visible(cat):
    return _gz_cat(cat)["show"]

def gizmo_cat_color(cat, base):
    """Category override wins, then global color mode, then the per-node base."""
    c = _gz_cat(cat)["color"]
    if c is not None:
        return c
    return gizmo_pref_color(base)

def gizmo_cat_alpha(cat, base_alpha):
    return max(0, min(255, int(round(float(base_alpha) * _gz_cat(cat)["alpha"]))))

def gizmo_cat_width(cat, base_width):
    return max(1, int(round(float(base_width) * _gz_cat(cat)["width"])))

def _gizmo_marker_surf(style, size, color, thick, alpha, hovered):
    """Cached SRCALPHA marker body (no angle arrow / label — those are cheap
    per-call). Dark under-stroke keeps every style readable on any backdrop."""
    key = (str(style), int(size), tuple(color), int(thick), int(alpha), bool(hovered))
    surf = _GIZMO_MARKER_CACHE.get(key)
    if surf is not None:
        return surf
    r = max(3, int(size)); t = max(1, int(thick))
    pad = r + t + 8; d = pad * 2
    s = pygame.Surface((d, d), pygame.SRCALPHA)
    c = pad
    col = tuple(color[:3]); dark = (10, 11, 16)
    hi = tuple(min(255, v + 70) for v in col) if hovered else col
    if style == "classic":
        # The original look: ring + full crosshair.
        pygame.draw.circle(s, dark, (c, c), r, t + 2)
        pygame.draw.circle(s, hi, (c, c), r, t)
        for (x0, y0, x1, y1) in ((c - r - 5, c, c + r + 5, c), (c, c - r - 5, c, c + r + 5)):
            pygame.draw.line(s, dark, (x0, y0), (x1, y1), t + 2)
            pygame.draw.line(s, hi, (x0, y0), (x1, y1), t)
    elif style == "diamond":
        pts = [(c, c - r), (c + r, c), (c, c + r), (c - r, c)]
        pygame.draw.polygon(s, dark, pts, t + 2)
        pygame.draw.polygon(s, hi, pts, t)
        pygame.draw.circle(s, hi, (c, c), max(1, int(r * 0.18)))
    elif style == "brackets":
        L = max(3, int(r * 0.72))
        for sx, sy in ((-1, -1), (1, -1), (1, 1), (-1, 1)):
            cx0, cy0 = c + sx * r, c + sy * r
            for (ex, ey) in ((cx0 - sx * L, cy0), (cx0, cy0 - sy * L)):
                pygame.draw.line(s, dark, (cx0, cy0), (ex, ey), t + 2)
                pygame.draw.line(s, hi, (cx0, cy0), (ex, ey), t)
        pygame.draw.circle(s, dark, (c, c), max(2, int(r * 0.22)) + 1)
        pygame.draw.circle(s, hi, (c, c), max(2, int(r * 0.22)))
    elif style == "dot":
        pygame.draw.circle(s, dark, (c, c), max(2, int(r * 0.62)) + 2)
        pygame.draw.circle(s, hi, (c, c), max(2, int(r * 0.62)))
        pygame.draw.circle(s, hi, (c, c), r, 1)
    else:  # "tech" — segmented ring + outer ticks + center dot
        rect = pygame.Rect(c - r, c - r, r * 2, r * 2)
        for a0 in (20, 110, 200, 290):  # 4 arcs with gaps at N/E/S/W
            a1 = a0 + 50
            try:
                pygame.draw.arc(s, dark, rect.inflate(2, 2), math.radians(a0), math.radians(a1), t + 2)
                pygame.draw.arc(s, hi, rect, math.radians(a0), math.radians(a1), t)
            except Exception:
                pass
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            x0, y0 = c + dx * (r + 1), c + dy * (r + 1)
            x1, y1 = c + dx * (r + 6), c + dy * (r + 6)
            pygame.draw.line(s, dark, (x0, y0), (x1, y1), t + 2)
            pygame.draw.line(s, hi, (x0, y0), (x1, y1), t)
        pygame.draw.circle(s, dark, (c, c), max(2, int(r * 0.24)) + 1)
        pygame.draw.circle(s, hi, (c, c), max(2, int(r * 0.24)))
    if alpha < 255:
        s.set_alpha(alpha)
    if len(_GIZMO_MARKER_CACHE) > 384:
        _GIZMO_MARKER_CACHE.pop(next(iter(_GIZMO_MARKER_CACHE)))
    _GIZMO_MARKER_CACHE[key] = s
    return s

def draw_gizmo_marker(surface, pos, size=10, color=(80, 220, 255), thickness=2,
                      angle=None, label=None, hovered=False, style=None, alpha=None):
    """Draw one standard editor gizmo marker. Respects the UI-Customization
    gizmo prefs (style/scale/thickness/opacity/labels); per-call color/size
    are the node's own base values. angle=degrees draws a direction arrow;
    label draws a name chip (suppressed when labels are globally off)."""
    p = _gizmo_prefs()
    st = style if (style in GIZMO_STYLES) else p["style"]
    col = gizmo_pref_color(color)
    r = max(3, int(round(float(size) * p["scale"])))
    t = max(1, int(round(float(thickness) * p["thickness"])))
    a = p["opacity"] if alpha is None else max(0, min(255, int(alpha)))
    body = _gizmo_marker_surf(st, r, col, t, a, bool(hovered))
    x, y = int(pos[0]), int(pos[1])
    surface.blit(body, (x - body.get_width() // 2, y - body.get_height() // 2))
    if angle is not None:
        try:
            rad = math.radians(float(angle))
            ux, uy = math.cos(rad), math.sin(rad)
            x1, y1 = x + ux * (r + 2), y + uy * (r + 2)
            x2, y2 = x + ux * (r * 2 + 4), y + uy * (r * 2 + 4)
            pygame.draw.line(surface, (10, 11, 16), (x1, y1), (x2, y2), t + 2)
            pygame.draw.line(surface, col, (x1, y1), (x2, y2), t)
            px, py = -uy, ux
            ah = max(3.0, r * 0.42)
            pygame.draw.polygon(surface, col, [
                (x2 + ux * ah, y2 + uy * ah),
                (x2 + px * ah * 0.7, y2 + py * ah * 0.7),
                (x2 - px * ah * 0.7, y2 - py * ah * 0.7)])
        except Exception:
            pass
    if label and p["labels"]:
        try:
            lbl = font_tiny.render(str(label)[:20], True, col)
            chip = pygame.Surface((lbl.get_width() + 8, lbl.get_height() + 4), pygame.SRCALPHA)
            chip.fill((10, 10, 14, min(210, a)))
            cx0, cy0 = x + r + 7, y - r - lbl.get_height() - 4
            surface.blit(chip, (cx0, cy0))
            surface.blit(lbl, (cx0 + 4, cy0 + 2))
        except Exception:
            pass


