def _camera_bounds_rect():
    try:
        r=list(CAMERA_BOUNDS.get("rect",[-600,-340,600,340]));l,t,rr,b=map(float,r[:4])
        return pygame.Rect(min(l,rr),min(t,b),max(1.0,abs(rr-l)),max(1.0,abs(b-t)))
    except Exception:return pygame.Rect(-600,-340,1200,680)

def _camera_bounds_view_half(kind="live"):
    if kind=="virtual":
        aw,ah=virtual_camera_aspect_value();ref_h=max(1.0,float(HEIGHT));ref_w=ref_h*float(aw)/max(1.0,float(ah));z=max(.05,float(virtual_camera.get("zoom",1.0)))
        return pygame.Vector2(ref_w/(2*z),ref_h/(2*z))
    z=max(.05,float(camera.get("zoom",1.0)));return pygame.Vector2(WIDTH/(2*z),HEIGHT/(2*z))

def _camera_bounds_constrain(previous,candidate,kind="live",velocity=None):
    """Hard viewport containment plus adjustable outward-motion easing."""
    if not CAMERA_BOUNDS.get("enabled",False) or _CAMERA_BOUNDS_DRAW.get("active"):return pygame.Vector2(candidate)
    mode=str(CAMERA_BOUNDS.get("mode","both"))
    if mode not in ("both",kind):return pygame.Vector2(candidate)
    box=_camera_bounds_rect();half=_camera_bounds_view_half(kind)
    minx,maxx=box.left+half.x,box.right-half.x;miny,maxy=box.top+half.y,box.bottom-half.y
    if minx>maxx:minx=maxx=box.centerx
    if miny>maxy:miny=maxy=box.centery
    old=pygame.Vector2(previous);old.x=max(minx,min(maxx,old.x));old.y=max(miny,min(maxy,old.y));want=pygame.Vector2(candidate);delta=want-old
    zone=max(0.0,float(CAMERA_BOUNDS.get("ease_distance",180.0)));strength=max(0.0,min(1.0,float(CAMERA_BOUNDS.get("ease_strength",1.0))))
    def axis(value,dv,lo,hi):
        if zone>0 and strength>0 and ((dv<0 and value<lo+zone) or (dv>0 and value>hi-zone)):
            dist=(value-lo) if dv<0 else (hi-value);u=max(0.0,min(1.0,dist/zone));soft=u*u*(3.0-2.0*u);dv*=1.0-strength+strength*soft
        out=max(lo,min(hi,value+dv));return out
    result=pygame.Vector2(axis(old.x,delta.x,minx,maxx),axis(old.y,delta.y,miny,maxy))
    if isinstance(velocity,pygame.Vector2):
        if (result.x<=minx+1e-4 and velocity.x<0) or (result.x>=maxx-1e-4 and velocity.x>0):velocity.x=0
        if (result.y<=miny+1e-4 and velocity.y<0) or (result.y>=maxy-1e-4 and velocity.y>0):velocity.y=0
    return result

def _camera_bounds_screen_rect(w=None,h=None):
    w=WIDTH if w is None else w;h=HEIGHT if h is None else h;box=_camera_bounds_rect();a=world_to_screen_for(pygame.Vector2(box.left,box.top),w,h);b=world_to_screen_for(pygame.Vector2(box.right,box.bottom),w,h)
    return pygame.Rect(round(min(a.x,b.x)),round(min(a.y,b.y)),max(1,round(abs(b.x-a.x))),max(1,round(abs(b.y-a.y))))

def _camera_bounds_handles(r):
    pts={"nw":r.topleft,"n":(r.centerx,r.top),"ne":r.topright,"e":(r.right,r.centery),"se":r.bottomright,"s":(r.centerx,r.bottom),"sw":r.bottomleft,"w":(r.left,r.centery),"move":r.center}
    return {k:pygame.Rect(int(p[0])-9,int(p[1])-9,18,18) for k,p in pts.items()}

def _draw_camera_bounds_gizmo(surface,w,h):
    if surface is not screen or is_recording or _is_export_render:return
    if not (CAMERA_BOUNDS.get("show_gizmo",True) and all_node_gizmos_enabled) and not _CAMERA_BOUNDS_DRAW.get("active"):return
    r=_camera_bounds_screen_rect(w,h);mode=str(CAMERA_BOUNDS.get("mode","both"));col=(255,205,70) if mode=="both" else (80,220,255) if mode=="live" else (175,120,255)
    layer=pygame.Surface((max(1,r.w),max(1,r.h)),pygame.SRCALPHA);pygame.draw.rect(layer,(*col,22),layer.get_rect());pygame.draw.rect(layer,(*col,220),layer.get_rect(),3);surface.blit(layer,r.topleft)
    for key,hr in _camera_bounds_handles(r).items():
        if key=="move":pygame.draw.rect(surface,(15,15,20),hr,border_radius=5);pygame.draw.rect(surface,col,hr,2,5);pygame.draw.line(surface,col,(hr.x+4,hr.centery),(hr.right-4,hr.centery),1);pygame.draw.line(surface,col,(hr.centerx,hr.y+4),(hr.centerx,hr.bottom-4),1)
        else:pygame.draw.circle(surface,col,hr.center,6);pygame.draw.circle(surface,(15,15,20),hr.center,3)
    lab=font_tiny.render(f"CAMERA LIMIT · {mode.upper()} · drag center=move · edges/corners=resize",True,col);surface.blit(lab,(r.x+6,max(54,r.y-18)))

def _handle_camera_bounds_draw_event(event):
    active=bool(_CAMERA_BOUNDS_DRAW.get("active"))
    if event.type==pygame.KEYDOWN and event.key==pygame.K_ESCAPE and active:
        original=_CAMERA_BOUNDS_DRAW.get("original")
        if original is not None:CAMERA_BOUNDS["rect"]=list(original)
        _CAMERA_BOUNDS_DRAW.update({"active":False,"start":None,"current":None,"mode":None,"original":None});push_toast("Camera-boundary edit cancelled.","info",1.5);return True
    # Existing gizmo is directly editable whenever ordinary Arena gizmos show.
    if (not active and event.type==pygame.MOUSEBUTTONDOWN and getattr(event,"button",0)==1
            and modal.get("type") is None and not is_recording and CAMERA_BOUNDS.get("enabled")
            and CAMERA_BOUNDS.get("show_gizmo",True) and all_node_gizmos_enabled):
        r=_camera_bounds_screen_rect();mode=None
        for key,hr in _camera_bounds_handles(r).items():
            if hr.collidepoint(event.pos):mode=key;break
        if mode is None:
            outer=r.inflate(16,16);inner=r.inflate(-16,-16)
            if outer.collidepoint(event.pos) and not inner.collidepoint(event.pos):mode="move"
        if mode:
            p=pygame.Vector2(screen_to_world(event.pos));_CAMERA_BOUNDS_DRAW.update({"active":True,"mode":mode,"start":p,"current":p,"original":list(CAMERA_BOUNDS.get("rect",[]))});return True
    if not active:return False
    mode=_CAMERA_BOUNDS_DRAW.get("mode") or "draw"
    if event.type==pygame.MOUSEBUTTONDOWN and event.button==1 and mode=="draw":
        p=pygame.Vector2(screen_to_world(event.pos));_CAMERA_BOUNDS_DRAW.update({"start":p,"current":p,"original":None});return True
    if event.type==pygame.MOUSEMOTION and _CAMERA_BOUNDS_DRAW.get("start") is not None:
        cur=pygame.Vector2(screen_to_world(event.pos));_CAMERA_BOUNDS_DRAW["current"]=cur;start=pygame.Vector2(_CAMERA_BOUNDS_DRAW["start"])
        if mode=="draw":CAMERA_BOUNDS["rect"]=[start.x,start.y,cur.x,cur.y]
        else:
            o=list(_CAMERA_BOUNDS_DRAW.get("original") or CAMERA_BOUNDS.get("rect",[-600,-340,600,340]));l,t,rr,b=map(float,o[:4]);dx,dy=cur.x-start.x,cur.y-start.y
            if mode=="move":l+=dx;rr+=dx;t+=dy;b+=dy
            else:
                if "w" in mode:l=min(rr-20,l+dx)
                if "e" in mode:rr=max(l+20,rr+dx)
                if "n" in mode:t=min(b-20,t+dy)
                if "s" in mode:b=max(t+20,b+dy)
            CAMERA_BOUNDS["rect"]=[l,t,rr,b]
        return True
    if event.type==pygame.MOUSEBUTTONUP and event.button==1 and _CAMERA_BOUNDS_DRAW.get("start") is not None:
        if mode=="draw":
            s=pygame.Vector2(_CAMERA_BOUNDS_DRAW["start"]);c=pygame.Vector2(screen_to_world(event.pos));CAMERA_BOUNDS["rect"]=[min(s.x,c.x),min(s.y,c.y),max(s.x,c.x),max(s.y,c.y)]
        CAMERA_BOUNDS["enabled"]=True;_CAMERA_BOUNDS_DRAW.update({"active":False,"start":None,"current":None,"mode":None,"original":None});push_toast("Camera boundary updated.","success",1.8);return True
    return event.type in (pygame.MOUSEBUTTONDOWN,pygame.MOUSEBUTTONUP,pygame.MOUSEMOTION)

