_WEAPON_PROJECTILES = []

def clear_weapon_projectiles():
    """Remove every live/lodged projectile and all rig references to them."""
    count = len(_WEAPON_PROJECTILES)
    for projectile in list(_WEAPON_PROJECTILES):
        if isinstance(projectile, dict):
            projectile["alive"] = False
    _WEAPON_PROJECTILES.clear()
    try:
        for owner in characters:
            rig = owner.get("_weapon_rig") if isinstance(owner, dict) else None
            if not isinstance(rig, dict):
                continue
            projectiles = rig.get("projectiles")
            if isinstance(projectiles, dict):
                projectiles.clear()
            last = rig.get("last")
            if isinstance(last, dict):
                last["projectile"] = None
    except Exception:
        pass
    return count

# SIM CLOCK (Arena): single dt-driven clock for all weapon/motion timing. Wall
# clock breaks during recording (dt is locked to 1/record_fps there) and keeps
# running while the match is paused; accumulating dt at the weapon tick keeps
# strokes, ghosts, timed hitboxes and motion clips in lockstep with the sim.
_SIM_CLOCK = [0.0]

def _sim_now():
    return _SIM_CLOCK[0]

def _npc_motion_tick(c, dt):
    """Per-frame runtime for the NPC node family (category 'NPC'). Generated
    scripts only STORE records on the character dict (tilt commands, eased-hop
    commands, cooldown arms); this tick is the single place that interprets
    them against the sim clock, so pause / recording / timescale all behave.
    Runs once per character per frame from the physics step."""
    if not isinstance(c, dict):
        return
    now_s = _sim_now()
    try:
        dt_f = float(dt)
    except (TypeError, ValueError):
        dt_f = 0.0
    # -- hop cooldown: consume arm requests, mirror readiness for pure nodes --
    _arm = c.pop("_hop_cooldown_arm", None)
    if _arm is not None:
        try:
            c["_hop_ready_at"] = now_s + max(0.0, float(_arm))
        except (TypeError, ValueError):
            pass
    c["_hop_ready"] = now_s >= float(c.get("_hop_ready_at", 0.0) or 0.0)
    # -- ground bookkeeping: dt-accumulated seconds grounded / airborne -------
    _g = bool(c.get("gravity_grounded", False))
    if _g:
        c["_ground_t"] = float(c.get("_ground_t", 0.0)) + dt_f
        c["_air_t"] = 0.0
    else:
        c["_air_t"] = float(c.get("_air_t", 0.0)) + dt_f
        c["_ground_t"] = 0.0
    # -- tilt commands -> tween records (angle overlay, visual only) ----------
    _cmd = c.pop("_tilt_cmd", None)
    if isinstance(_cmd, dict):
        try:
            # finish any running tween where it currently stands (no pops)
            _tw0 = c.get("_tilt_tween")
            if isinstance(_tw0, dict):
                dur0 = max(0.0001, float(_tw0.get("dur", 0.0)))
                t0p = max(0.0, min(1.0, (now_s - float(_tw0.get("t0", now_s))) / dur0))
                a00 = float(_tw0.get("from", 0.0)); a01 = float(_tw0.get("to", 0.0))
                c["_tilt_angle"] = a00 + (a01 - a00) * _weapon_ease(t0p, _tw0.get("ease", "linear"))
                c.pop("_tilt_tween", None)
            cur = float(c.get("_tilt_angle", 0.0) or 0.0)
            op = str(_cmd.get("op", "set"))
            if op == "set":
                c["_tilt_angle"] = float(_cmd.get("value", 0.0))
            else:
                dest = (float(_cmd.get("value", 0.0)) if op == "to"
                        else (cur + float(_cmd.get("value", 0.0)) if op == "by" else 0.0))
                dur = max(0.0, float(_cmd.get("dur", 0.25)))
                if dur <= 0.0:
                    c["_tilt_angle"] = dest
                else:
                    c["_tilt_tween"] = {"from": cur, "to": dest, "t0": now_s,
                                        "dur": dur, "ease": str(_cmd.get("ease", "ease_out"))}
        except Exception:
            c.pop("_tilt_tween", None)
    # -- tilt tween evaluation -------------------------------------------------
    _tw = c.get("_tilt_tween")
    if isinstance(_tw, dict):
        try:
            dur = max(0.0001, float(_tw.get("dur", 0.25)))
            t = (now_s - float(_tw.get("t0", now_s))) / dur
            a0 = float(_tw.get("from", 0.0)); a1 = float(_tw.get("to", 0.0))
            if t >= 1.0:
                c["_tilt_angle"] = a1
                c.pop("_tilt_tween", None)
            else:
                c["_tilt_angle"] = a0 + (a1 - a0) * _weapon_ease(max(0.0, t), _tw.get("ease", "linear"))
        except Exception:
            c.pop("_tilt_tween", None)
    c["_tilt_anim"] = isinstance(c.get("_tilt_tween"), dict)
    # -- hop commands ------------------------------------------------------------
    _hc = c.pop("_hop_cmd", None)
    if isinstance(_hc, dict) and str(_hc.get("op", "")) == "ease":
        try:
            c["_hop_ease"] = {"peak": abs(float(_hc.get("peak", 480.0))),
                              "t0": now_s, "dur": max(0.01, float(_hc.get("dur", 0.18))),
                              "ease": str(_hc.get("ease", "ease_out"))}
            c["gravity_grounded"] = False
            c["sleeping"] = False
        except (TypeError, ValueError):
            pass
    # -- eased hop drive: vel.y sweeps 0 -> -peak along the chosen curve --------
    _he = c.get("_hop_ease")
    if isinstance(_he, dict):
        try:
            age = now_s - float(_he.get("t0", now_s))
            dur = max(0.0001, float(_he.get("dur", 0.18)))
            peak = abs(float(_he.get("peak", 480.0)))
            if age >= dur:
                c["vel"].y = -peak
                if "_smooth_vel" in c:
                    c["_smooth_vel"].y = c["vel"].y
                c.pop("_hop_ease", None)
            elif _g and age > 0.05:
                c.pop("_hop_ease", None)   # landed mid-rise: hand control back
            else:
                t = max(0.0, min(1.0, age / dur))
                c["vel"].y = -peak * _weapon_ease(t, _he.get("ease", "ease_out"))
                if "_smooth_vel" in c:
                    c["_smooth_vel"].y = c["vel"].y
        except Exception:
            c.pop("_hop_ease", None)

def _weapon_anchor_world(owner, name, _seen=None):
    if not isinstance(owner,dict): return pygame.Vector2()
    rig=owner.get("_weapon_rig",{}); anchors=rig.get("anchors",{}); a=anchors.get(str(name),{})
    seen=set(_seen or ()); key=str(name)
    if key in seen:return pygame.Vector2(owner.get("pos",(0,0)))
    seen.add(key)
    # origin/parent are Character (object) pins. None means Self; a connected
    # character contributes its world position. Anchor-name parents remain
    # supported for backwards compatibility with older saved graphs.
    # World-position events are temporary scene anchors (impact points,
    # explosions, decals, area checks). Their stored offset IS the world
    # position, so they stay where created instead of following the character.
    if a.get("world_space",False):
        return pygame.Vector2(a.get("offset",(0,0)))
    origin = a.get("origin")
    base = pygame.Vector2(owner.get("pos", (0, 0)))
    if isinstance(origin, dict):
        base = pygame.Vector2(origin.get("pos", base))
    elif isinstance(origin, str) and origin in ("anchor", "position", "sprite") and a.get("parent") in anchors:
        base = _weapon_anchor_world(owner, a.get("parent"), seen)
    parent = a.get("parent")
    parent_angle = 0.0
    if isinstance(parent, dict):
        base = pygame.Vector2(parent.get("pos", base))
        parent_angle = float(parent.get("_flex_facing_angle", parent.get("angle", 0.0)))
    elif parent in anchors:
        parent_angle = float(anchors[parent].get("angle", 0.0))
    local=pygame.Vector2(a.get("offset",(0,0)))
    if a.get("follow_flip_x",False) and owner.get("flip_x",False):local.x*=-1
    if a.get("follow_flip_y",False) and owner.get("flip_y",False):local.y*=-1
    return base+local.rotate(parent_angle)

def _weapon_anchor_world_angle(owner, name, _seen=None):
    """Accumulated world-facing angle of a rig position event: its own angle
    plus every parent contribution _weapon_anchor_world rotates offsets by --
    anchor parents recursively, character parents via their facing. A
    standalone anchor returns its own angle (unchanged); a child at the end
    of an arm chain returns the whole chain's rotation, so attached content
    (motion clips) truly rotates with the rig instead of just translating."""
    if not isinstance(owner, dict):
        return 0.0
    rig = owner.get("_weapon_rig", {})
    anchors = rig.get("anchors", {})
    a = anchors.get(str(name), {})
    seen = set(_seen or ())
    key = str(name)
    if key in seen:  # cyclic parent chain -> stop at this anchor's own angle
        return float(a.get("angle", 0.0))
    seen.add(key)
    try:
        total = float(a.get("angle", 0.0))
    except (TypeError, ValueError):
        total = 0.0
    parent = a.get("parent")
    if isinstance(parent, dict):
        try:
            total += float(parent.get("_flex_facing_angle", parent.get("angle", 0.0)))
        except (TypeError, ValueError):
            pass
    elif parent in anchors:
        total += _weapon_anchor_world_angle(owner, parent, seen)
    if a.get("follow_flip_x",False) and owner.get("flip_x",False):total=180.0-total
    if a.get("follow_flip_y",False) and owner.get("flip_y",False):total=-total
    return total

def _is_combat_character(value, require_alive=True):
    """True only for a fighter that belongs in combat targeting.

    Scene Props and Scene Directors intentionally share the live ``characters``
    list so their graphs can receive lifecycle events.  They are *not* fighters,
    however: never let them enter enemy selection, aiming, hitboxes, damage, or
    generic character queries.  Keeping that rule in one helper prevents a new
    target system from accidentally treating a prop's large sentinel HP as a
    valid combat target.
    """
    if (not isinstance(value, dict) or value.get("is_scene_prop", False)
            or value.get("scene_director", False) or value.get("_is_item", False)):
        return False
    return (not require_alive) or float(value.get("hp", 0) or 0) > 0

def _collision_ignored_for_pair(a, b):
    """True when two characters must pass through each other, per the
    script-set ignore rules (Ignore Collisions nodes):
      * char:      the other's id() sits in my _no_collide_ids (checked both ways)
      * tag_any:   a tag in my _no_collide_tags is carried by the other
      * tag_same:  we BOTH carry a tag listed in either one's _no_collide_shared_tags
      * team:      matching non-empty teams and either has _no_collide_same_team
    Kept identical to the script-side _ns_collision_ignored in
    NS_RUNTIME_HELPERS (same split as _ns_ease)."""
    if not isinstance(a, dict) or not isinstance(b, dict):
        return False
    if ((a.get("_is_item") and not a.get("_item_collide_characters", False))
            or (b.get("_is_item") and not b.get("_item_collide_characters", False))):
        return True
    try:
        if id(b) in a.get("_no_collide_ids", ()) or id(a) in b.get("_no_collide_ids", ()):
            return True
        at, bt = a.get("tags") or (), b.get("tags") or ()
        for t in a.get("_no_collide_tags", ()):
            if t in bt:
                return True
        for t in b.get("_no_collide_tags", ()):
            if t in at:
                return True
        for t in a.get("_no_collide_shared_tags", ()):
            if t in at and t in bt:
                return True
        for t in b.get("_no_collide_shared_tags", ()):
            if t in at and t in bt:
                return True
        if a.get("_no_collide_same_team") or b.get("_no_collide_same_team"):
            ta, tb = str(a.get("team", "")), str(b.get("team", ""))
            if ta and ta == tb:
                return True
    except Exception:
        pass
    return False

def _oriented_box_overlap(a,b):
    """SAT overlap for two true rotated rectangles. Returns hit, normal,
    penetration; unlike the old AABB shortcut this never enlarges a rotated
    box just because its angle changed."""
    ca,cb=a["center"],b["center"];ha,hb=a["half"],b["half"]
    def axes(box):
        ang=math.radians(-float(box.get("angle",0.0)));co,si=math.cos(ang),math.sin(ang)
        return (pygame.Vector2(co,si),pygame.Vector2(-si,co))
    def corners(box):
        c=box["center"];hx,hy=box["half"];aa=axes(box);return [c+aa[0]*sx*hx+aa[1]*sy*hy for sx,sy in ((-1,-1),(1,-1),(1,1),(-1,1))]
    ac,bc=corners(a),corners(b);best=float("inf");best_axis=None
    for axis in axes(a)+axes(b):
        av=[p.dot(axis) for p in ac];bv=[p.dot(axis) for p in bc];overlap=min(max(av),max(bv))-max(min(av),min(bv))
        if overlap<=0:return False,pygame.Vector2(),0.0
        if overlap<best:best=overlap;best_axis=axis
    if best_axis is None:return False,pygame.Vector2(),0.0
    if (ca-cb).dot(best_axis)<0:best_axis=-best_axis
    return True,best_axis,best

def _character_overlap_info(a,b):
    """Sensor/solver overlap; sprite-bound characters test every active layer box."""
    if not _is_combat_character(a) or not _is_combat_character(b):return False,pygame.Vector2(),0.0
    _ause=_character_collision_source(a)=="sprite" or _character_has_manual_animation_collision(a);_buse=_character_collision_source(b)=="sprite" or _character_has_manual_animation_collision(b)
    _ab=_character_active_sprite_boxes(a) if _ause else [];_bb=_character_active_sprite_boxes(b) if _buse else []
    if (_ause and (_character_layered_sprite_state(a) or _character_has_manual_animation_collision(a)) and not _ab) or (_buse and (_character_layered_sprite_state(b) or _character_has_manual_animation_collision(b)) and not _bb):return False,pygame.Vector2(),0.0
    if _ab or _bb:
        if not _ab:
            _ca=_character_collision_center(a);_ha=_character_collision_half_extents(a);_ab=[{"center":_ca,"half":_ha,"angle":0.0}]
        if not _bb:
            _cb=_character_collision_center(b);_hb=_character_collision_half_extents(b);_bb=[{"center":_cb,"half":_hb,"angle":0.0}]
        best=None
        for ba in _ab:
            for bb in _bb:
                hit,normal,penetration=_oriented_box_overlap(ba,bb)
                if not hit:continue
                cand=(penetration,normal)
                if best is None or cand[0]<best[0]:best=cand
        return (True,best[1],best[0]) if best else (False,pygame.Vector2(),0.0)
    ca=_character_collision_center(a);cb=_character_collision_center(b);ax,ay=_character_collision_half_extents(a);bx,by=_character_collision_half_extents(b)
    if abs(ca.x-cb.x)>ax+bx+12 or abs(ca.y-cb.y)>ay+by+12:return False,pygame.Vector2(),0.0
    if a.get("collision_shape","sphere")=="box" and b.get("collision_shape","sphere")=="box":
        ox=ax+bx-abs(ca.x-cb.x);oy=ay+by-abs(ca.y-cb.y)
        if ox<=0 or oy<=0:return False,pygame.Vector2(),0.0
        return (True,pygame.Vector2(1 if ca.x>cb.x else -1,0),ox) if ox<oy else (True,pygame.Vector2(0,1 if ca.y>cb.y else -1),oy)
    reach=max(ax,ay)+max(bx,by);d=ca-cb;dist=d.length()
    if dist>=reach:return False,pygame.Vector2(),0.0
    return True,(d/dist if dist>1e-6 else pygame.Vector2(1,0)),reach-dist


def _phase_touch_pair_is_passthrough(a,b,now=None):
    """Physical response is disabled, but the pair remains a sensor contact."""
    now=time.time() if now is None else now
    pass_modes={"ghost","trigger","passthrough","pass_through","pass-through","sensor","ignore"}
    amode=str(a.get("collision_mode","solid") or "solid").strip().lower()
    bmode=str(b.get("collision_mode","solid") or "solid").strip().lower()
    return (amode in pass_modes or bmode in pass_modes
            or not a.get("has_collision",True) or not b.get("has_collision",True)
            or now<float(a.get("collision_disabled_until",0)) or now<float(b.get("collision_disabled_until",0))
            or _collision_ignored_for_pair(a,b))


def _phase_touch_swept_overlap(a,b,previous_positions):
    """Catch a phase body that crossed another fighter between rendered frames.

    Disabled collision has no physical solver/CCD pass, so a fast ghost can move
    from one side of a character to the other without sharing a sampled frame.
    This relative-motion segment test keeps that crossing damage dependable while
    remaining dormant unless a phase-contact sensor is actually enabled.
    """
    try:
        old_a=pygame.Vector2(previous_positions.get(id(a),a.get("pos",(0,0))))+_character_collision_offset(a)
        old_b=pygame.Vector2(previous_positions.get(id(b),b.get("pos",(0,0))))+_character_collision_offset(b)
        new_rel=_character_collision_center(a)-_character_collision_center(b)
        old_rel=old_a-old_b
        travel=new_rel-old_rel
        travel_sq=travel.length_squared()
        if travel_sq<=1e-9:return False
        closest_t=max(0.0,min(1.0,-old_rel.dot(travel)/travel_sq))
        closest=old_rel+travel*closest_t
        ax,ay=_character_collision_half_extents(a);bx,by=_character_collision_half_extents(b)
        reach=max(ax,ay)+max(bx,by)
        return closest.length_squared()<=reach*reach
    except (TypeError,ValueError,KeyError):
        return False


def _phase_touch_tick(dt):
    """Run collision-independent ghost contact damage and touch events."""
    now=time.time()
    fighters=[c for c in characters if _is_combat_character(c)]
    # Every fighter always retains a lightweight overlap sensor. Pass-through
    # changes only the PHYSICAL response; it must not erase touch registration,
    # on_collision hooks, or normal character contact damage. Explicit Phase &
    # Touch nodes still override timing/tag options for their owner.
    sensors=fighters
    if not sensors:return

    previous_positions={id(c):pygame.Vector2(c.get("_phase_sensor_prev_pos",c.get("pos",(0,0))))
                        for c in fighters}
    try:
        for owner in sensors:
            explicit=owner.get("_phase_contact_sensor")
            explicit=explicit if isinstance(explicit,dict) and explicit.get("enabled",False) else None
            cfg=explicit or {"enabled":True,"deal_contact_damage":True,"mode":"enter","cooldown":.35,
                             "tag":"","only_pass_through":True,"respect_ready":True,"_automatic":True}
            previous=set(owner.get("_phase_touching_ids",set()))
            old_refs=owner.get("_phase_touch_refs",{})
            current=set()
            refs={}
            for other in fighters:
                if other is owner:
                    continue
                hit,normal,overlap=_character_overlap_info(owner,other)
                swept=not hit and _phase_touch_swept_overlap(owner,other,previous_positions)
                if not hit and not swept:
                    continue
                passthrough=_phase_touch_pair_is_passthrough(owner,other,now)
                if cfg.get("only_pass_through",True) and not passthrough:
                    continue
                tag=str(cfg.get("tag","") or "").strip()
                if tag and tag not in set(other.get("tags",set())):
                    continue
                # A sensor contact is still a collision EVENT. It simply skips
                # separation, bounce and impulse response.
                if passthrough:call_hook(owner,"on_collision",CTX,owner,other)

                oid=id(other)
                transient=bool(swept and not hit)
                if not transient:
                    current.add(oid)
                    refs[oid]=other
                entered=oid not in previous
                if entered:
                    call_hook(owner,"on_phase_touch_enter",CTX,owner,other)
                call_hook(owner,"on_phase_touch_stay",CTX,owner,other)

                mode=str(cfg.get("mode","enter")).lower()
                last=owner.setdefault("_phase_touch_last_damage",{})
                cooldown=max(0.0,float(cfg.get("cooldown",.35)))
                if mode in ("enter","once","once_per_touch"):
                    should_damage=entered and now-float(last.get(oid,0))>=cooldown
                elif mode in ("continuous","every_frame"):
                    should_damage=True
                else:
                    should_damage=now-float(last.get(oid,0))>=cooldown
                if should_damage and cfg.get("deal_contact_damage",True) and simulation_started:
                    # Automatic pass-through contacts use the same readiness and
                    # hostile/passive rules as solid character contact. Explicit
                    # sensors retain their authored respect_ready setting.
                    require_ready=(not CTX.has_contact_trait(owner,"hostile")) if cfg.get("_automatic") else bool(cfg.get("respect_ready",False))
                    dealt=CTX.contact_damage(owner,other,require_ready=require_ready)
                    if dealt>0:
                        last[oid]=now
                        call_hook(owner,"on_phase_touch_damage",CTX,owner,other,dealt)
                if transient and entered:
                    call_hook(owner,"on_phase_touch_exit",CTX,owner,other)

            for oid in previous-current:
                other=old_refs.get(oid)
                if isinstance(other,dict):
                    call_hook(owner,"on_phase_touch_exit",CTX,owner,other)
            owner["_phase_touching_ids"]=current
            owner["_phase_touch_refs"]=refs
            owner["_phase_touch_targets"]=list(refs.values())
    finally:
        # Position history powers swept sensor contact, including fast bodies
        # that cross completely between rendered frames.
        for fighter in fighters:
            fighter["_phase_sensor_prev_pos"]=pygame.Vector2(fighter.get("pos",(0,0)))


def predict_character_path(character,seconds=2.0,steps=72,max_bounces=4,gravity_multiplier=1.0):
    """Return sampled future positions and wall-bounce markers without moving the body."""
    if not isinstance(character,dict):return []
    seconds=max(.05,min(10.0,float(seconds)));steps=max(6,min(360,int(steps)));max_bounces=max(0,min(32,int(max_bounces)));dt=seconds/steps;pos=pygame.Vector2(character.get("pos",(0,0)));vel=pygame.Vector2(character.get("vel",(0,0)));gravity=float(character.get("gravity",0))*float(character.get("gravity_scale",1))*float(gravity_multiplier) if character.get("gravity_enabled",False) else 0.0;terminal=abs(float(character.get("terminal_velocity",1200)));damping=max(0.0,float(character.get("linear_damping",0)));bounce=max(0.0,min(1.0,float(character.get("bounce",character.get("restitution",1)))));hx,hy=_character_collision_half_extents(character);offset=_character_collision_offset(character);bounds=get_arena_inner_wall_bounds();out=[{"pos":pygame.Vector2(pos),"time":0.0,"bounce":None,"velocity":pygame.Vector2(vel)}];bounce_count=0
    for index in range(1,steps+1):
        if gravity:vel.y+=gravity*dt
        if terminal>0:vel.y=max(-terminal,min(terminal,vel.y))
        if damping:vel*=max(0.0,1.0-damping*dt)
        pos+=vel*dt;center=pos+offset;marker=[]
        if center.x-hx<bounds.left:
            pos.x+=bounds.left-(center.x-hx);marker.append("left");vel.x=abs(vel.x)*bounce if bounce_count<max_bounces else 0.0;bounce_count+=1
        elif center.x+hx>bounds.right:
            pos.x-=center.x+hx-bounds.right;marker.append("right");vel.x=-abs(vel.x)*bounce if bounce_count<max_bounces else 0.0;bounce_count+=1
        center=pos+offset
        if center.y-hy<bounds.top:
            pos.y+=bounds.top-(center.y-hy);marker.append("top");vel.y=abs(vel.y)*bounce if bounce_count<max_bounces else 0.0;bounce_count+=1
        elif center.y+hy>bounds.bottom:
            pos.y-=center.y+hy-bounds.bottom;marker.append("bottom");vel.y=-abs(vel.y)*bounce if bounce_count<max_bounces else 0.0;bounce_count+=1
        out.append({"pos":pygame.Vector2(pos),"time":index*dt,"bounce":"+".join(marker) if marker else None,"velocity":pygame.Vector2(vel)})
    return out


def draw_character_trajectory_gizmo(surface,w,h,character):
    cfg=character.get("_trajectory_gizmo")
    if not isinstance(cfg,dict) or not cfg.get("enabled",False) or surface is not screen or is_recording or _is_export_render or not all_node_gizmos_enabled:return
    until=float(cfg.get("until",0) or 0)
    if until and time.time()>=until:character.pop("_trajectory_gizmo",None);character.pop("_trajectory_trail",None);return
    mode=str(cfg.get("mode","predict"))
    color=tuple(int(v) for v in cfg.get("color",[80,220,255])[:3]);width=max(1,min(6,int(cfg.get("thickness",2))))
    if mode=="trail":
        # Actual-path mode: draws the character's REAL recorded positions, so
        # any curve produced by AI steering/homing/custom velocity logic shows
        # up correctly (a forward physics prediction can't see that logic).
        trail=list(character.get("_trajectory_trail") or [])
        if len(trail)<2:return
        screen_points=[world_to_screen_for(p,w,h) for p in trail];xy=[(int(p.x),int(p.y)) for p in screen_points]
        pygame.draw.lines(surface,(8,12,18),False,xy,width+3);pygame.draw.lines(surface,color,False,xy,width)
        if cfg.get("show_points",True):
            stride=max(1,len(xy)//16)
            for i in range(0,len(xy),stride):pygame.draw.circle(surface,color,xy[i],2)
        title=font_tiny.render(f"ACTUAL PATH · {float(cfg.get('trail_seconds',2)):.1f}s · {len(xy)-1} samples",True,color);surface.blit(title,(xy[0][0]+10,xy[0][1]-18))
        return
    points=predict_character_path(character,cfg.get("seconds",2),cfg.get("steps",72),cfg.get("bounces",4),cfg.get("gravity_multiplier",1));
    if len(points)<2:return
    screen_points=[world_to_screen_for(entry["pos"],w,h) for entry in points];xy=[(int(p.x),int(p.y)) for p in screen_points];pygame.draw.lines(surface,(8,12,18),False,xy,width+3);pygame.draw.lines(surface,color,False,xy,width)
    if cfg.get("show_points",True):
        stride=max(1,len(points)//16)
        for i in range(0,len(points),stride):pygame.draw.circle(surface,color,xy[i],2)
    for i,entry in enumerate(points):
        if entry.get("bounce"):
            pygame.draw.circle(surface,(8,12,18),xy[i],7);pygame.draw.circle(surface,(255,205,75),xy[i],5,2);lab=font_tiny.render(entry["bounce"].upper(),True,(255,220,110));surface.blit(lab,(xy[i][0]+7,xy[i][1]-lab.get_height()//2))
    end=pygame.Vector2(xy[-1]);prev=pygame.Vector2(xy[-2]);direction=end-prev
    if direction.length_squared()>0:
        d=direction.normalize();perp=pygame.Vector2(-d.y,d.x);pygame.draw.polygon(surface,color,[end,end-d*11+perp*5,end-d*11-perp*5])
    gravity_active=abs(float(character.get("gravity",0)))>1e-6 and character.get("gravity_enabled",False);kind="BOUNCE PATH" if any(p.get("bounce") for p in points) else "ARC PATH" if gravity_active else "STRAIGHT PATH";title=font_tiny.render(f"{kind} · {float(cfg.get('seconds',2)):.1f}s · {len(points)-1} steps",True,color);surface.blit(title,(xy[0][0]+10,xy[0][1]-18))

def _update_character_trajectory_trail(character,dt):
    cfg=character.get("_trajectory_gizmo")
    if not isinstance(cfg,dict) or not cfg.get("enabled",False) or str(cfg.get("mode","predict"))!="trail":
        if "_trajectory_trail" in character:character.pop("_trajectory_trail",None)
        return
    trail=character.get("_trajectory_trail")
    if trail is None:trail=[];character["_trajectory_trail"]=trail
    trail.append(pygame.Vector2(character.get("pos",(0,0))))
    max_len=max(2,int(float(cfg.get("trail_seconds",2))/max(1e-4,dt)))
    while len(trail)>max_len:trail.pop(0)

def _weapon_nearest_enemy(owner,pos,tag=""):
    # PERF (Arena): allocation-free single pass - no candidate list, no per-
    # candidate Vector2 construction. Same winner as the old
    # min(..., distance_squared_to) and the same first-in-list tie behavior.
    best = None
    best_d2 = None
    ox, oy = pos[0], pos[1]
    for c in characters:
        if c is owner or not _is_combat_character(c):
            continue
        if tag and tag not in c.get("tags", set()):
            continue
        cp = c.get("pos", (0, 0))
        dx = cp[0] - ox
        dy = cp[1] - oy
        d2 = dx * dx + dy * dy
        if best is None or d2 < best_d2:
            best = c
            best_d2 = d2
    return best



def _copy_to_system_clipboard(text_str):
    """Copies text string to the OS system clipboard across Windows, Mac, and Linux."""
    text_str = str(text_str)
    # 1. Try tkinter clipboard
    try:
        import tkinter as tk
        r = tk.Tk()
        r.withdraw()
        r.clipboard_clear()
        r.clipboard_append(text_str)
        r.update()
        r.destroy()
        return True
    except Exception:
        pass
    # 2. Try pygame scrap
    try:
        if not pygame.scrap.get_init():
            pygame.scrap.init()
        pygame.scrap.put(pygame.SCRAP_TEXT, text_str.encode("utf-8"))
        return True
    except Exception:
        pass
    # 3. Try subprocess clip / pbcopy / xclip
    try:
        if sys.platform == "win32":
            subprocess.run("clip", input=text_str.encode("utf-8"), check=True, shell=True)
            return True
        elif sys.platform == "darwin":
            subprocess.run("pbcopy", input=text_str.encode("utf-8"), check=True)
            return True
        else:
            subprocess.run(["xclip", "-selection", "clipboard"], input=text_str.encode("utf-8"), check=True)
            return True
    except Exception:
        pass
    return False

def _get_app_root_dir():
    """Get the true root directory where the .exe or .py lives, safe for PyInstaller frozen bundles."""
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()

def _relaunch_app():
    """Spawn a fresh copy of Arena Studio and hand over to it.

    Used by the crash-window 'Reload App' button.  Releases the single-instance
    lock FIRST so the new process can claim it (otherwise it would show the
    'already running' notice), then starts a new process and returns True.  In a
    frozen build this relaunches the same executable; in a source build it
    launches ``python box_game.py``.  Returns False if it could not start.
    """
    try:
        _release_single_instance_lock()
    except Exception:
        pass
    try:
        if getattr(sys, "frozen", False):
            cmd = [sys.executable]
            cwd = os.path.dirname(os.path.abspath(sys.executable))
        else:
            cmd = [sys.executable, os.path.abspath(__file__)]
            cwd = os.path.dirname(os.path.abspath(__file__))
        flags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
        subprocess.Popen(cmd, cwd=cwd, creationflags=flags)
        return True
    except Exception:
        return False


def show_crash_window(error_text, is_manual_kill=False, severity="error", report_title=None):
    try:play_ui_feedback("error")
    except Exception:pass
    """Resilient fatal-error / caught-problem report for source and frozen builds.

    Unhandled failures use red. A failure that Arena caught in a background or
    optional subsystem uses amber/yellow, similar to an IDE problem diagnostic,
    while still stopping the application so no runtime fault is hidden.
    """
    try:_WATCHDOG_STATE["suspended"]=True
    except Exception:pass
    error_text=str(error_text);is_problem=str(severity).lower() in ("warning","problem","caught") and not is_manual_kill
    accent="#B77900" if is_problem else "#D32F2F";text_accent="#8A5A00" if is_problem else "#B71C1C";soft_bg="#FFF9E8" if is_problem else "#FAFAFA"
    window_title=("Arena Studio - Detected Runtime Problem" if is_problem else "Arena Studio - Application Crash Report") if not is_manual_kill else "Arena Studio - Software Kill Warning"
    title_text=(report_title or ("A RUNTIME PROBLEM WAS DETECTED" if is_problem else "AN UNHANDLED ERROR OCCURRED")) if not is_manual_kill else "MANUAL SOFTWARE-KILL TRIGGERED"
    sub_text=(("Arena caught a subsystem failure. It is stopping so the problem is not hidden. Copy the complete report below:"
               if is_problem else "The application encountered an unexpected error. You can select and copy the complete traceback below:")
              if not is_manual_kill else "Manual software-kill was triggered ($software-kill). No unhandled errors were found. This confirms the reporting window works.")

    # Always retain the conventional crash_log.txt. Caught problems also get a
    # dedicated file so they remain easy to distinguish from unhandled crashes.
    try:
        app_dir=_get_app_root_dir();log_path=os.path.join(app_dir,"caught_problem_log.txt" if is_problem else "crash_log.txt")
        for _path in dict.fromkeys((log_path,os.path.join(app_dir,"crash_log.txt"))):
            with open(_path,"w",encoding="utf-8") as f:f.write(error_text)
    except Exception:
        try:
            log_path=os.path.abspath("caught_problem_log.txt" if is_problem else "crash_log.txt")
            with open(log_path,"w",encoding="utf-8") as f:f.write(error_text)
        except Exception:log_path="crash_log.txt"

    exit_code=0 if is_manual_kill else 1
    # Tier 1: Tk gives selectable text and dependable clipboard support.
    try:
        import tkinter as tk
        root=tk.Tk();root.title(window_title);root.geometry("860x640");root.configure(bg="#FFFFFF")
        hdr=tk.Frame(root,bg="#FFFFFF");hdr.pack(fill=tk.X,padx=20,pady=(18,6))
        icon_sym="!" if not is_manual_kill else "X"
        lbl_t=tk.Label(hdr,text=f"[{icon_sym}]  {title_text}",font=("Segoe UI",16,"bold"),fg=accent,bg="#FFFFFF",anchor="w");lbl_t.pack(fill=tk.X)
        lbl_s=tk.Label(hdr,text=sub_text,font=("Segoe UI",10),fg="#333333",bg="#FFFFFF",anchor="w",justify=tk.LEFT,wraplength=810);lbl_s.pack(fill=tk.X,pady=(4,0))
        path_lbl=tk.Label(hdr,text=f"Full report saved to: {log_path}",font=("Consolas",9),fg="#666666",bg="#FFFFFF",anchor="w");path_lbl.pack(fill=tk.X,pady=(5,0))
        txt_frame=tk.Frame(root,bg=accent,bd=1,relief=tk.SOLID);txt_frame.pack(fill=tk.BOTH,expand=True,padx=20,pady=10)
        s_bar=tk.Scrollbar(txt_frame);s_bar.pack(side=tk.RIGHT,fill=tk.Y)
        txt_box=tk.Text(txt_frame,wrap=tk.NONE,yscrollcommand=s_bar.set,font=("Consolas",10),fg=text_accent,bg=soft_bg,padx=12,pady=12,insertbackground=accent)
        x_bar=tk.Scrollbar(txt_frame,orient=tk.HORIZONTAL,command=txt_box.xview);txt_box.configure(xscrollcommand=x_bar.set)
        txt_box.insert(tk.END,error_text);x_bar.pack(side=tk.BOTTOM,fill=tk.X);txt_box.pack(side=tk.LEFT,fill=tk.BOTH,expand=True);s_bar.config(command=txt_box.yview)
        btn_frame=tk.Frame(root,bg="#FFFFFF");btn_frame.pack(fill=tk.X,padx=20,pady=(6,18))
        status_lbl=tk.Label(btn_frame,text="Select text above, or copy the complete report:",font=("Segoe UI",9),fg="#666666",bg="#FFFFFF");status_lbl.pack(side=tk.LEFT)
        _closing={"value":False}
        def _do_copy():
            try:root.clipboard_clear();root.clipboard_append(error_text);root.update();status_lbl.config(text="Complete report copied to clipboard.",fg="#2E7D32")
            except Exception:status_lbl.config(text="Select the report and press Ctrl+C to copy.",fg=accent)
        def _do_close():
            _closing["value"]=True
            try:root.quit();root.destroy()
            except Exception:pass
        def _do_reload():
            if _relaunch_app():
                _closing["value"]=True
                try:root.quit();root.destroy()
                except Exception:pass
            else:
                status_lbl.config(text="Could not relaunch. Close and reopen manually.",fg=accent)
        close_btn=tk.Button(btn_frame,text="Close Application",command=_do_close,font=("Segoe UI",10,"bold"),bg=accent,fg="#FFFFFF",activebackground=accent,activeforeground="#FFFFFF",padx=14,pady=5,relief=tk.FLAT,cursor="hand2");close_btn.pack(side=tk.RIGHT,padx=(10,0))
        reload_btn=tk.Button(btn_frame,text="Reload App",command=_do_reload,font=("Segoe UI",10,"bold"),bg="#2E7D32",fg="#FFFFFF",activebackground="#2E7D32",activeforeground="#FFFFFF",padx=14,pady=5,relief=tk.FLAT,cursor="hand2");reload_btn.pack(side=tk.RIGHT,padx=(10,0))
        copy_btn=tk.Button(btn_frame,text="Copy Report",command=_do_copy,font=("Segoe UI",10,"bold"),bg="#EEEEEE",fg="#222222",padx=14,pady=5,relief=tk.FLAT,cursor="hand2");copy_btn.pack(side=tk.RIGHT)
        root.protocol("WM_DELETE_WINDOW",_do_close);root.lift();root.attributes("-topmost",True);root.mainloop()
        try:pygame.quit()
        except Exception:pass
        raise SystemExit(exit_code)
    except SystemExit:
        raise
    except Exception:
        pass

    # Tier 2: bundled Pygame emergency screen.
    try:
        try:pygame.display.quit()
        except Exception:pass
        pygame.display.init();pygame.font.init();cw,ch=900,650;c_surf=pygame.display.set_mode((cw,ch));pygame.display.set_caption(window_title)
        f_font=pygame.font.SysFont("Consolas",14);h_font=pygame.font.SysFont("Segoe UI",18,bold=True);t_font=pygame.font.SysFont("Segoe UI",12)
        rgb=(183,121,0) if is_problem else (210,40,40);text_rgb=(138,90,0) if is_problem else (180,20,20);box_rgb=(255,249,232) if is_problem else (250,250,250)
        running_c=True;c_clock=pygame.time.Clock();c_lines=error_text.splitlines();scroll_y=0;copied_toast=False
        while running_c:
            for event in pygame.event.get():
                if event.type==pygame.QUIT or (event.type==pygame.KEYDOWN and event.key==pygame.K_ESCAPE):running_c=False
                elif event.type==pygame.MOUSEBUTTONDOWN:
                    if event.button==4:scroll_y=max(0,scroll_y-3)
                    elif event.button==5:scroll_y=min(max(0,len(c_lines)-20),scroll_y+3)
                    elif event.button==1:
                        cp_r=pygame.Rect(cw-250,ch-50,105,36);cl_r=pygame.Rect(cw-135,ch-50,115,36);rl_r=pygame.Rect(cw-365,ch-50,105,36)
                        if rl_r.collidepoint(event.pos):
                            if _relaunch_app():running_c=False
                        elif cp_r.collidepoint(event.pos):_copy_to_system_clipboard(error_text);copied_toast=True
                        elif cl_r.collidepoint(event.pos):running_c=False
                elif event.type==pygame.KEYDOWN and (event.mod&(pygame.KMOD_CTRL|pygame.KMOD_META)) and event.key==pygame.K_c:_copy_to_system_clipboard(error_text);copied_toast=True
            c_surf.fill((255,255,255));c_surf.blit(h_font.render("[!]  "+title_text,True,rgb),(20,16));c_surf.blit(t_font.render(("Caught problem; Arena will stop after this report closes." if is_problem else "Error details are saved to crash_log.txt."),True,(60,60,60)),(20,46))
            box_r=pygame.Rect(20,72,cw-40,ch-136);pygame.draw.rect(c_surf,box_rgb,box_r);pygame.draw.rect(c_surf,rgb,box_r,1)
            max_vis=max(1,(box_r.height-20)//18)
            for i_l,line_str in enumerate(c_lines[scroll_y:scroll_y+max_vis]):c_surf.blit(f_font.render(str(line_str)[:122],True,text_rgb),(box_r.x+10,box_r.y+10+i_l*18))
            cp_btn=pygame.Rect(cw-250,ch-50,105,36);cl_btn=pygame.Rect(cw-135,ch-50,115,36);rl_btn=pygame.Rect(cw-365,ch-50,105,36);pygame.draw.rect(c_surf,(235,235,240),cp_btn,border_radius=6);pygame.draw.rect(c_surf,(190,190,200),cp_btn,1,6);c_surf.blit(t_font.render("Copy",True,(10,10,10)),(cp_btn.x+33,cp_btn.y+9));pygame.draw.rect(c_surf,(46,125,50),rl_btn,border_radius=6);c_surf.blit(t_font.render("Reload",True,(255,255,255)),(rl_btn.x+30,rl_btn.y+9));pygame.draw.rect(c_surf,rgb,cl_btn,border_radius=6);c_surf.blit(t_font.render("Close",True,(255,255,255)),(cl_btn.x+36,cl_btn.y+9))
            if copied_toast:c_surf.blit(t_font.render("Report copied to clipboard.",True,(40,140,60)),(24,ch-40))
            pygame.display.flip();c_clock.tick(30)
        try:pygame.quit()
        except Exception:pass
        raise SystemExit(exit_code)
    except SystemExit:
        raise
    except Exception:
        pass

    # Tier 3: zero-dependency native Windows message.
    try:
        if sys.platform=="win32":
            import ctypes
            flags=(0x30 if is_problem else 0x10)|0x0|0x00010000|0x00040000
            ctypes.windll.user32.MessageBoxW(0,error_text[:4000]+("\n\n[Full report saved to disk]" if len(error_text)>4000 else ""),window_title,flags)
    except Exception:pass
    raise SystemExit(exit_code)


def _show_detected_problem_and_exit(context,error_text,artifact_paths=None):
    """Escalate a caught subsystem failure to the yellow report and stop Arena."""
    artifacts=[os.path.abspath(str(p)) for p in (artifact_paths or []) if p]
    report=(f"CAUGHT RUNTIME PROBLEM\nContext: {context}\nArena Studio: {APP_VERSION}\n"
            f"Time: {time.strftime('%Y-%m-%d %H:%M:%S')}\nPython: {sys.version}\nPlatform: {sys.platform}\n"
            +(f"Diagnostic artifacts:\n  "+"\n  ".join(artifacts)+"\n" if artifacts else "")
            +"\nArena caught this failure before it became an unhandled main-loop crash. The application is stopping so the problem is not hidden.\n\n"+str(error_text))
    try:
        if sys.stderr is not None:print(report,file=sys.stderr)
    except Exception:pass
    try:
        show_crash_window(report,severity="warning",report_title=f"{str(context).upper()} FAILED")
    finally:
        try:pygame.quit()
        except Exception:pass
    raise SystemExit(1)


def _global_exception_handler(exc_type,exc_value,exc_traceback):
    err_msg="".join(traceback.format_exception(exc_type,exc_value,exc_traceback))
    try:
        if sys.stderr is not None:print(err_msg,file=sys.stderr)
    except Exception:pass
    show_crash_window(err_msg,severity="error")


sys.excepthook=_global_exception_handler


_RUNTIME_PROBLEM_QUEUE=queue.Queue()


def _global_thread_exception_handler(args):
    err_msg="".join(traceback.format_exception(args.exc_type,args.exc_value,args.exc_traceback))
    try:
        if sys.stderr is not None:print(err_msg,file=sys.stderr)
    except Exception:pass
    # Tk and Pygame windows must be owned by the main thread. Queue the complete
    # problem and wake the event loop; it presents the amber report next frame.
    try:_RUNTIME_PROBLEM_QUEUE.put_nowait((f"Background Thread: {getattr(args.thread,'name','unknown')}",err_msg,[]))
    except Exception:pass
    try:pygame.event.post(pygame.event.Event(pygame.USEREVENT))
    except Exception:pass


if hasattr(threading,"excepthook"):threading.excepthook=_global_thread_exception_handler


# ══════════════════════════════════════════════════════════════════════════
# MAIN-LOOP TIMEOUT WATCHDOG
# A normal Python exception reaches sys.excepthook. A deadlock/block does not,
# so an independent monitor records the last user actions and main-thread stack
# and opens a dedicated TIMEOUT ERROR window after sixty seconds.
# ══════════════════════════════════════════════════════════════════════════
_WATCHDOG_TIMEOUT_SECONDS=60.0
_WATCHDOG_STATE={"last":time.monotonic(),"stage":"startup","started":False,"suspended":False,"shown":False,"force":None}
_WATCHDOG_ACTIONS=[]
_WATCHDOG_LOCK=threading.Lock()


def _watchdog_note_action(kind,detail=""):
    try:
        entry={"time":time.time(),"kind":str(kind),"detail":str(detail)[:500]}
        with _WATCHDOG_LOCK:
            _WATCHDOG_ACTIONS.append(entry)
            if len(_WATCHDOG_ACTIONS)>24:del _WATCHDOG_ACTIONS[:-24]
    except Exception:pass


def _runtime_watchdog_heartbeat(stage="main loop"):
    try:
        _WATCHDOG_STATE["last"]=time.monotonic();_WATCHDOG_STATE["stage"]=str(stage)
    except Exception:pass


def _watchdog_timeout_report(reason,elapsed,manual=False):
    now=time.time();lines=[
        "TIMEOUT ERROR",
        "Exception: TimeoutError: Arena main-loop heartbeat exceeded the 60-second deadline",
        f"Arena Studio: {APP_VERSION}",
        f"Time: {time.strftime('%Y-%m-%d %H:%M:%S',time.localtime(now))}",
        f"Main-loop heartbeat missing for: {float(elapsed):.1f} seconds",
        f"Last heartbeat stage: {_WATCHDOG_STATE.get('stage','unknown')}",
        f"Trigger: {reason}",
        f"Manual timeout test: {bool(manual)}",
        "",
        "LAST USER / SYSTEM ACTIONS (newest last):",
    ]
    try:
        with _WATCHDOG_LOCK:actions=list(_WATCHDOG_ACTIONS)
        if not actions:lines.append("  (no actions recorded)")
        for action in actions:
            stamp=time.strftime('%H:%M:%S',time.localtime(action.get('time',now)))
            lines.append(f"  {stamp}  {action.get('kind','action')}: {action.get('detail','')}")
    except Exception:lines.append("  (action history unavailable)")
    try:
        lines.extend(["","LIVE STATE:",
            f"  active_tab={globals().get('active_tab','?')}",
            f"  modal={globals().get('modal',{}).get('type') if isinstance(globals().get('modal'),dict) else '?'}",
            f"  recording={globals().get('is_recording',False)} mode={globals().get('record_mode','?')} frame={globals().get('record_frame_idx',0)}",
            f"  export_render_job={bool(globals().get('export_render_job'))}",
            f"  gpu_finalize_job={bool(globals().get('_gpu_finalize_job'))}",
            f"  apu_compile_job={bool(globals().get('_apu_compile_job'))}",
        ])
    except Exception:pass
    try:
        main_id=threading.main_thread().ident;frame=sys._current_frames().get(main_id)
        if frame is not None:lines.extend(["","MAIN THREAD STACK AT TIMEOUT:","".join(traceback.format_stack(frame))])
    except Exception:lines.extend(["","MAIN THREAD STACK: unavailable"])
    lines.extend(["","This report identifies the action immediately before Arena stopped responding.","The full report is saved as timeout_crash_log.txt beside Arena Studio."])
    return "\n".join(lines)


def _watchdog_write_report(report):
    try:
        path=os.path.join(_get_app_root_dir(),"timeout_crash_log.txt");Path(path).write_text(str(report),encoding="utf-8");return path
    except Exception:
        try:path=os.path.abspath("timeout_crash_log.txt");Path(path).write_text(str(report),encoding="utf-8");return path
        except Exception:return "timeout_crash_log.txt"


def _watchdog_show_external(report_path,report,manual=False):
    try:
        import winsound;winsound.MessageBeep(winsound.MB_ICONHAND)
    except Exception:pass
    """Show timeout details outside the potentially blocked Pygame main thread."""
    pid=os.getpid()
    if sys.platform=="win32":
        try:
            ep=str(report_path).replace("'","''")
            title="Arena Studio - Timeout Test" if manual else "Arena Studio - Not Responding"
            ps=f"""Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing;
$form=New-Object System.Windows.Forms.Form; $form.Text='{title}'; $form.Size=New-Object System.Drawing.Size(900,680); $form.StartPosition='CenterScreen'; $form.TopMost=$true;
$head=New-Object System.Windows.Forms.Label; $head.Text='TIMEOUT ERROR  -  ARENA STUDIO STOPPED RESPONDING'; $head.ForeColor=[System.Drawing.Color]::FromArgb(190,75,20); $head.Font=New-Object System.Drawing.Font('Segoe UI',15,[System.Drawing.FontStyle]::Bold); $head.SetBounds(18,16,840,30); $form.Controls.Add($head);
$sub=New-Object System.Windows.Forms.Label; $sub.Text='The main loop produced no heartbeat for more than 60 seconds. Review the last action and captured stack below.'; $sub.SetBounds(20,50,840,38); $form.Controls.Add($sub);
$box=New-Object System.Windows.Forms.TextBox; $box.Multiline=$true; $box.ReadOnly=$true; $box.ScrollBars='Both'; $box.WordWrap=$false; $box.Font=New-Object System.Drawing.Font('Consolas',9); $box.Text=[IO.File]::ReadAllText('{ep}'); $box.SetBounds(20,92,842,500); $form.Controls.Add($box);
$path=New-Object System.Windows.Forms.Label; $path.Text='Saved to: {ep}'; $path.SetBounds(20,600,600,24); $form.Controls.Add($path);
$wait=New-Object System.Windows.Forms.Button; $wait.Text='Keep Waiting'; $wait.SetBounds(626,610,110,32); $wait.Add_Click({{$form.Close()}}); $form.Controls.Add($wait);
$close=New-Object System.Windows.Forms.Button; $close.Text='Close Arena'; $close.BackColor=[System.Drawing.Color]::FromArgb(190,75,20); $close.ForeColor=[System.Drawing.Color]::White; $close.SetBounds(746,610,116,32); $close.Add_Click({{Stop-Process -Id {pid} -Force; $form.Close()}}); $form.Controls.Add($close);
[void]$form.ShowDialog();"""
            flags=getattr(subprocess,"CREATE_NO_WINDOW",0)
            subprocess.Popen(["powershell","-NoProfile","-ExecutionPolicy","Bypass","-Command",ps],creationflags=flags)
            return True
        except Exception:pass
        try:
            import ctypes
            msg=("TIMEOUT ERROR\n\nArena Studio produced no heartbeat for more than 60 seconds.\n\n"
                 f"Last stage: {_WATCHDOG_STATE.get('stage','unknown')}\nReport: {report_path}\n\nYES = close Arena\nNO = keep waiting")
            answer=ctypes.windll.user32.MessageBoxW(None,msg,"Arena Studio - Not Responding",0x34|0x00040000|0x00010000)
            if answer==6:os._exit(1)
            return True
        except Exception:return False
    try:
        import tkinter as tk
        root=tk.Tk();root.title("Arena Studio - Timeout Error");root.geometry("880x650");root.attributes("-topmost",True)
        tk.Label(root,text="TIMEOUT ERROR — ARENA STUDIO STOPPED RESPONDING",font=("Arial",15,"bold"),fg="#B84A14").pack(anchor="w",padx=18,pady=(16,5))
        box=tk.Text(root,wrap="none",font=("Courier",9));box.insert("1.0",report);box.configure(state="disabled");box.pack(fill="both",expand=True,padx=18,pady=8)
        row=tk.Frame(root);row.pack(fill="x",padx=18,pady=(0,16));tk.Button(row,text="Keep Waiting",command=root.destroy).pack(side="right",padx=5);tk.Button(row,text="Close Arena",command=lambda:os._exit(1)).pack(side="right")
        root.mainloop();return True
    except Exception:return False


def _watchdog_loop():
    while True:
        time.sleep(1.0)
        try:
            if _WATCHDOG_STATE.get("suspended"):continue
            force=_WATCHDOG_STATE.get("force");elapsed=time.monotonic()-float(_WATCHDOG_STATE.get("last",time.monotonic()));test_hang=bool(_WATCHDOG_STATE.get("test_hang"))
            manual=bool(force or test_hang)
            if not force and (elapsed<_WATCHDOG_TIMEOUT_SECONDS or (_WATCHDOG_STATE.get("shown") and not test_hang)):continue
            reason=str(force or ("Manual $not-responding main-thread hang test" if test_hang else "No main-loop heartbeat for more than one minute"))
            _WATCHDOG_STATE["force"]=None;_WATCHDOG_STATE["test_hang"]=False
            if not manual:_WATCHDOG_STATE["shown"]=True
            report=_watchdog_timeout_report(reason,max(elapsed,_WATCHDOG_TIMEOUT_SECONDS if manual else elapsed),manual)
            path=_watchdog_write_report(report);_watchdog_show_external(path,report,manual)
        except Exception:pass


def _start_runtime_watchdog():
    if _WATCHDOG_STATE.get("started"):return
    _WATCHDOG_STATE["started"]=True;_WATCHDOG_STATE["last"]=time.monotonic()
    threading.Thread(target=_watchdog_loop,name="ArenaMainLoopWatchdog",daemon=True).start()


def _trigger_not_responding_test(reason="$not-responding manual timeout test",duration=65.0):
    duration=max(61.0,min(180.0,float(duration)))
    _watchdog_note_action("timeout test",f"{reason} · intentional main-thread block {duration:.1f}s")
    _WATCHDOG_STATE.update({"force":None,"test_hang":True,"shown":False,"stage":str(reason),"last":time.monotonic()})
    # Deliberately do not pump Pygame/Windows here. This is an authentic hang
    # test: the OS marks the Arena window Not Responding and the watchdog opens
    # its timeout handler after the real one-minute deadline.
    time.sleep(duration)
    _WATCHDOG_STATE["test_hang"]=False;_runtime_watchdog_heartbeat("main loop recovered after timeout test")
    _terminal_log(f"[timeout-test] Main loop resumed after {duration:.1f}s.",_TC_GOOD)


# ══════════════════════════════════════════════════════════════════════════
# ARENA DATA ARCHIVE (.ARDA) — Full Software Data Export & Import Engine
# ══════════════════════════════════════════════════════════════════════════
ARDA_CATEGORIES = {
    "projects":   {"label": "Projects & Arenas",          "desc": "Saved match projects and layout files"},
    "characters": {"label": "Characters & Vault",         "desc": "Character library templates & character vault"},
    "sprites":    {"label": "Sprites & Images",           "desc": "Sprite artwork and texture files"},
    "audio":      {"label": "Audio & Sound FX",           "desc": "Audio tracks, sound cues, and audio library"},
    "scripts":    {"label": "Scripts & Blueprints",       "desc": "Python trait scripts and visual node graphs"},
    "animations": {"label": "Animations & Motion Clips",  "desc": "Motion clips, frame animations, and easing curves"},
    "settings":   {"label": "Settings & Config",          "desc": "App settings, themes, and editor preferences"},
    "presets":    {"label": "Presets & Scene Groups",     "desc": "Scene node groups, particle presets, and swatches"},
}

def export_arda_package(output_path, selected_categories=None):
    """Export software data into a single .arda (Arena Data Archive) file."""
    import zipfile
    if not output_path.endswith(".arda"):
        output_path += ".arda"
    if selected_categories is None:
        selected_categories = list(ARDA_CATEGORIES.keys())
    selected_set = set(selected_categories)
    
    manifest = {
        "arda_version": "1.0",
        "app_version": APP_VERSION,
        "export_time": time.time(),
        "export_date": time.strftime("%Y-%m-%d %H:%M:%S"),
        "categories": {}
    }
    
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    
    with zipfile.ZipFile(output_path, "w", zipfile.ZIP_DEFLATED) as zf:
        # 1. Projects
        if "projects" in selected_set and os.path.isdir(PROJECTS_DIR):
            p_files = [f for f in os.listdir(PROJECTS_DIR) if f.endswith(".json") and not f.startswith("_")]
            manifest["categories"]["projects"] = {"count": len(p_files), "label": "Projects"}
            for pf in p_files:
                p_path = os.path.join(PROJECTS_DIR, pf)
                zf.write(p_path, f"projects/{pf}")
            if os.path.isdir(PROJ_THUMBS_DIR):
                for tf in os.listdir(PROJ_THUMBS_DIR):
                    zf.write(os.path.join(PROJ_THUMBS_DIR, tf), f"projects/_thumbs/{tf}")
                    
        # 2. Characters & Vault
        if "characters" in selected_set:
            manifest["categories"]["characters"] = {"library_count": len(LIBRARY), "vault_count": len(CHAR_VAULT)}
            zf.writestr("characters/library.json", json.dumps(LIBRARY, indent=2))
            zf.writestr("characters/vault.json", json.dumps(CHAR_VAULT, indent=2))
            
        # 3. Sprites
        if "sprites" in selected_set and os.path.isdir(SPRITES_DIR):
            s_count = 0
            for root_d, _, files in os.walk(SPRITES_DIR):
                for sf in files:
                    full_sp = os.path.join(root_d, sf)
                    rel_sp = os.path.relpath(full_sp, SPRITES_DIR).replace("\\", "/")
                    zf.write(full_sp, f"sprites/{rel_sp}")
                    s_count += 1
            manifest["categories"]["sprites"] = {"count": s_count}
            
        # 4. Audio
        if "audio" in selected_set and os.path.isdir(AUDIO_DIR):
            a_count = 0
            for root_d, _, files in os.walk(AUDIO_DIR):
                for af in files:
                    full_ap = os.path.join(root_d, af)
                    rel_ap = os.path.relpath(full_ap, AUDIO_DIR).replace("\\", "/")
                    zf.write(full_ap, f"audio/{rel_ap}")
                    a_count += 1
            manifest["categories"]["audio"] = {"count": a_count, "library_count": len(AUDIO_LIBRARY)}
            zf.writestr("audio/audio_library.json", json.dumps(AUDIO_LIBRARY, indent=2))
            
        # 5. Scripts & Blueprints
        if "scripts" in selected_set and os.path.isdir(SCRIPTS_DIR):
            sc_count = 0
            for scf in os.listdir(SCRIPTS_DIR):
                full_scp = os.path.join(SCRIPTS_DIR, scf)
                if os.path.isfile(full_scp) and (scf.endswith(".py") or scf.endswith(".json")):
                    zf.write(full_scp, f"scripts/{scf}")
                    sc_count += 1
            manifest["categories"]["scripts"] = {"count": sc_count}
            
        # 6. Animations & Motion Clips
        if "animations" in selected_set:
            manifest["categories"]["animations"] = {
                "animations_count": len(ANIMATION_LIBRARY),
                "motion_clips_count": len(MOTION_CLIPS),
                "curves_count": len(CUSTOM_EASE_CURVES)
            }
            zf.writestr("animations/animation_library.json", json.dumps(ANIMATION_LIBRARY, indent=2))
            zf.writestr("animations/motion_clips.json", json.dumps(MOTION_CLIPS, indent=2))
            zf.writestr("animations/easing_curves.json", json.dumps(CUSTOM_EASE_CURVES, indent=2))
            
        # 7. Settings
        if "settings" in selected_set:
            manifest["categories"]["settings"] = {"count": 3}
            zf.writestr("settings/settings.json", json.dumps(SETTINGS, indent=2))
            zf.writestr("settings/editor_config.json", json.dumps(_editor_config, indent=2))
            zf.writestr("settings/sprite_folders.json", json.dumps(SPRITE_FOLDERS, indent=2))
            
        # 8. Presets & Groups
        if "presets" in selected_set:
            sg_lib = globals().get("SCENE_GROUP_LIBRARY", [])
            pe_presets = globals().get("PE_CUSTOM_PRESETS", {})
            swatches = globals().get("_SAVED_SWATCHES", globals().get("PALETTE_CUSTOM_SWATCHES", []))
            manifest["categories"]["presets"] = {
                "scene_groups": len(sg_lib) if isinstance(sg_lib, list) else 0,
                "particle_presets": len(pe_presets) if isinstance(pe_presets, dict) else 0
            }
            zf.writestr("presets/scene_groups.json", json.dumps(sg_lib if isinstance(sg_lib, list) else [], indent=2))
            zf.writestr("presets/particle_presets.json", json.dumps(pe_presets if isinstance(pe_presets, dict) else {}, indent=2))
            zf.writestr("presets/color_swatches.json", json.dumps(swatches if isinstance(swatches, list) else [], indent=2))

        # Write manifest
        zf.writestr("arda_manifest.json", json.dumps(manifest, indent=2))
        
    return output_path, manifest

def inspect_arda_package(package_path):
    """Read and return manifest metadata of a .arda file without extracting."""
    import zipfile
    if not os.path.isfile(package_path):
        return None
    try:
        with zipfile.ZipFile(package_path, "r") as zf:
            if "arda_manifest.json" in zf.namelist():
                data = json.loads(zf.read("arda_manifest.json").decode("utf-8"))
                return data
    except Exception:
        pass
    return None

def import_arda_package(package_path, mode="append", selected_categories=None):
    """Import software data from a .arda archive.
    Modes:
      'append': Adds onto existing content, renaming colliding files with '_imported'.
      'overwrite': Replaces conflicting items with the archive version.
      'fresh': Clears existing data in selected categories and installs fresh from archive.
    """
    import zipfile
    if not os.path.isfile(package_path):
        return False, "File does not exist"
    
    manifest = inspect_arda_package(package_path) or {}
    mode = str(mode or "append").lower()
    
    with zipfile.ZipFile(package_path, "r") as zf:
        namelist = zf.namelist()
        available_cats = set()
        for name in namelist:
            cat = name.split("/")[0]
            if cat in ARDA_CATEGORIES:
                available_cats.add(cat)
                
        if selected_categories is None:
            import_cats = available_cats
        else:
            import_cats = set(selected_categories) & available_cats
            
        # 1. Projects
        if "projects" in import_cats:
            if mode == "fresh" and os.path.isdir(PROJECTS_DIR):
                for f in os.listdir(PROJECTS_DIR):
                    p = os.path.join(PROJECTS_DIR, f)
                    if os.path.isfile(p): os.remove(p)
            for zname in namelist:
                if zname.startswith("projects/") and not zname.endswith("/"):
                    rel = zname.removeprefix("projects/")
                    dst = os.path.join(PROJECTS_DIR, rel)
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    if mode == "append" and os.path.exists(dst):
                        base, ext = os.path.splitext(rel)
                        dst = os.path.join(PROJECTS_DIR, f"{base}_imported{ext}")
                    with open(dst, "wb") as f_out:
                        f_out.write(zf.read(zname))

        # 2. Characters & Vault
        if "characters" in import_cats:
            if "characters/library.json" in namelist:
                new_lib = json.loads(zf.read("characters/library.json").decode("utf-8"))
                if isinstance(new_lib, list):
                    if mode == "fresh":
                        LIBRARY.clear()
                        LIBRARY.extend(new_lib)
                    elif mode == "overwrite":
                        existing_names = {t.get("name"): idx for idx, t in enumerate(LIBRARY)}
                        for t in new_lib:
                            nm = t.get("name")
                            if nm in existing_names:
                                LIBRARY[existing_names[nm]] = t
                            else:
                                LIBRARY.append(t)
                    else:  # append
                        existing_names = {t.get("name") for t in LIBRARY}
                        for t in new_lib:
                            t_copy = copy.deepcopy(t)
                            orig_nm = t_copy.get("name", "Fighter")
                            cur_nm = orig_nm
                            if cur_nm in existing_names:
                                cur_nm = f"{orig_nm}_imported"
                                i = 2
                                while cur_nm in existing_names:
                                    cur_nm = f"{orig_nm}_imported_{i}"
                                    i += 1
                                t_copy["name"] = cur_nm
                            LIBRARY.append(t_copy)
                            existing_names.add(cur_nm)
                    save_library()

            if "characters/vault.json" in namelist:
                new_vault = json.loads(zf.read("characters/vault.json").decode("utf-8"))
                if isinstance(new_vault, list):
                    if mode == "fresh":
                        CHAR_VAULT.clear()
                        CHAR_VAULT.extend(new_vault)
                    else:
                        v_ids = {v.get("id") for v in CHAR_VAULT}
                        for v in new_vault:
                            if v.get("id") not in v_ids or mode == "overwrite":
                                CHAR_VAULT.append(v)
                    save_character_vault()

        # 3. Sprites
        if "sprites" in import_cats and os.path.isdir(SPRITES_DIR):
            if mode == "fresh":
                for root_d, dirs, files in os.walk(SPRITES_DIR):
                    for sf in files:
                        try: os.remove(os.path.join(root_d, sf))
                        except Exception: pass
            for zname in namelist:
                if zname.startswith("sprites/") and not zname.endswith("/"):
                    rel = zname.removeprefix("sprites/")
                    dst = os.path.join(SPRITES_DIR, rel)
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    if mode == "append" and os.path.exists(dst):
                        base, ext = os.path.splitext(rel)
                        dst = os.path.join(SPRITES_DIR, f"{base}_imported{ext}")
                    with open(dst, "wb") as f_out:
                        f_out.write(zf.read(zname))

        # 4. Audio
        if "audio" in import_cats and os.path.isdir(AUDIO_DIR):
            if mode == "fresh":
                for root_d, dirs, files in os.walk(AUDIO_DIR):
                    for af in files:
                        try: os.remove(os.path.join(root_d, af))
                        except Exception: pass
            for zname in namelist:
                if zname.startswith("audio/") and not zname.endswith("/"):
                    rel = zname.removeprefix("audio/")
                    if rel == "audio_library.json":
                        continue
                    dst = os.path.join(AUDIO_DIR, rel)
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    if mode == "append" and os.path.exists(dst):
                        base, ext = os.path.splitext(rel)
                        dst = os.path.join(AUDIO_DIR, f"{base}_imported{ext}")
                    with open(dst, "wb") as f_out:
                        f_out.write(zf.read(zname))
            if "audio/audio_library.json" in namelist:
                new_al = json.loads(zf.read("audio/audio_library.json").decode("utf-8"))
                if isinstance(new_al, list):
                    if mode == "fresh":
                        AUDIO_LIBRARY.clear()
                        AUDIO_LIBRARY.extend(new_al)
                    else:
                        a_paths = {a.get("path") for a in AUDIO_LIBRARY}
                        for a in new_al:
                            if a.get("path") not in a_paths or mode == "overwrite":
                                AUDIO_LIBRARY.append(a)
                    save_audio_library()

        # 5. Scripts & Blueprints
        if "scripts" in import_cats and os.path.isdir(SCRIPTS_DIR):
            if mode == "fresh":
                for sf in os.listdir(SCRIPTS_DIR):
                    p = os.path.join(SCRIPTS_DIR, sf)
                    if os.path.isfile(p): os.remove(p)
            for zname in namelist:
                if zname.startswith("scripts/") and not zname.endswith("/"):
                    rel = zname.removeprefix("scripts/")
                    dst = os.path.join(SCRIPTS_DIR, rel)
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    if mode == "append" and os.path.exists(dst):
                        base, ext = os.path.splitext(rel)
                        dst = os.path.join(SCRIPTS_DIR, f"{base}_imported{ext}")
                    with open(dst, "wb") as f_out:
                        f_out.write(zf.read(zname))

        # 6. Animations & Motion Clips
        if "animations" in import_cats:
            if "animations/animation_library.json" in namelist:
                new_anim = json.loads(zf.read("animations/animation_library.json").decode("utf-8"))
                if isinstance(new_anim, dict):
                    if mode == "fresh": ANIMATION_LIBRARY.clear()
                    ANIMATION_LIBRARY.update(new_anim)
                    save_animation_library()
            if "animations/motion_clips.json" in namelist:
                new_mc = json.loads(zf.read("animations/motion_clips.json").decode("utf-8"))
                if isinstance(new_mc, dict):
                    if mode == "fresh": MOTION_CLIPS.clear()
                    MOTION_CLIPS.update(new_mc)
                    save_motion_clips()
            if "animations/easing_curves.json" in namelist:
                new_ec = json.loads(zf.read("animations/easing_curves.json").decode("utf-8"))
                if isinstance(new_ec, dict):
                    if mode == "fresh": CUSTOM_EASE_CURVES.clear()
                    CUSTOM_EASE_CURVES.update(new_ec)
                    save_easing_curves()

        # 7. Settings
        if "settings" in import_cats:
            if "settings/settings.json" in namelist:
                new_st = json.loads(zf.read("settings/settings.json").decode("utf-8"))
                if isinstance(new_st, dict): SETTINGS.update(new_st); save_settings()
            if "settings/editor_config.json" in namelist:
                new_ec = json.loads(zf.read("settings/editor_config.json").decode("utf-8"))
                if isinstance(new_ec, dict): _editor_config.update(new_ec); _save_editor_config()
            if "settings/sprite_folders.json" in namelist:
                new_sf = json.loads(zf.read("settings/sprite_folders.json").decode("utf-8"))
                if isinstance(new_sf, dict):
                    if mode == "fresh": SPRITE_FOLDERS.clear()
                    SPRITE_FOLDERS.update(new_sf)
                    save_sprite_folders()

        # 8. Presets & Groups
        if "presets" in import_cats:
            if "presets/scene_groups.json" in namelist:
                try:
                    new_sg = json.loads(zf.read("presets/scene_groups.json").decode("utf-8"))
                    if isinstance(new_sg, list) and "SCENE_GROUP_LIBRARY" in globals():
                        if mode == "fresh": SCENE_GROUP_LIBRARY.clear()
                        SCENE_GROUP_LIBRARY.extend(new_sg)
                        if "save_scene_group_library" in globals(): save_scene_group_library()
                except Exception: pass
            if "presets/particle_presets.json" in namelist:
                try:
                    new_pp = json.loads(zf.read("presets/particle_presets.json").decode("utf-8"))
                    if isinstance(new_pp, dict) and "PE_CUSTOM_PRESETS" in globals():
                        if mode == "fresh": PE_CUSTOM_PRESETS.clear()
                        PE_CUSTOM_PRESETS.update(new_pp)
                        if "_save_particle_presets_file" in globals(): _save_particle_presets_file()
                except Exception: pass

    _load_all_data_stores()
    load_sprite_folders()
    load_motion_clips()
    load_easing_curves()
    return True, f"Successfully imported data from {os.path.basename(package_path)} (mode: {mode})"

def open_export_arda_modal():
    modal.clear()
    modal["type"] = "export_arda_modal"
    modal["_arda_exp_cats"] = set(ARDA_CATEGORIES.keys())
    suggested_fn = f"arena_data_backup_{time.strftime('%Y%m%d_%H%M%S')}.arda"
    modal["_arda_exp_filename"] = suggested_fn
    modal["focus"] = "_arda_exp_filename"

def open_import_arda_modal(file_path=None):
    modal.clear()
    modal["type"] = "import_arda_modal"
    modal["_arda_imp_file"] = file_path or ""
    modal["_arda_imp_mode"] = "append"  # "append" | "overwrite" | "fresh"
    modal["_arda_imp_cats"] = set(ARDA_CATEGORIES.keys())
    if file_path and os.path.isfile(file_path):
        modal["_arda_imp_manifest"] = inspect_arda_package(file_path)
    else:
        modal["_arda_imp_manifest"] = None

def _projectile_critical_roll(projectile):
    """Return (is_critical, multiplier) for one projectile impact.

    Crit Chance is authored as a familiar 0-100 percentage and Crit Damage is
    total damage percentage (150 = 1.5x, 200 = 2x). The old Set Projectile Crit
    Boolean remains compatible: enabled without custom stats means a 100% crit.
    """
    if not isinstance(projectile,dict):
        return False,1.0
    if "crit_chance" in projectile:
        chance=max(0.0,min(100.0,float(projectile.get("crit_chance",0))))
    else:
        chance=100.0 if projectile.get("crit",False) else 0.0
    if chance<=0:
        return False,1.0
    owner=projectile.get("owner")
    fallback_percent=(float(owner.get("crit_mult",owner.get("crit_multiplier",1.5)))*100.0
                      if isinstance(owner,dict) else 150.0)
    percent=max(100.0,float(projectile.get("crit_damage_percent",fallback_percent)))
    critical=chance>=100.0 or random.random()*100.0<chance
    return critical,percent/100.0


def _projectile_lock_lodged_transform(projectile):
    """Hard-lock an embedded projectile's world transform.

    Lodging is a terminal physics state: gravity/weight, drag, homing, later
    velocity nodes, and visual wiggle must not move or rotate the projectile.
    The locked angle is the projectile's travel angle at the exact impact, not
    the wall normal (which caused arrows to snap to a flat 90-degree pose).
    """
    if not isinstance(projectile, dict) or not projectile.get("lodged"):
        return False
    try:
        if "_lodge_pos" not in projectile:
            projectile["_lodge_pos"] = pygame.Vector2(projectile.get("pos", (0, 0)))
        if "_lodge_angle" not in projectile:
            projectile["_lodge_angle"] = float(projectile.get("angle", 0.0))
        projectile["pos"] = pygame.Vector2(projectile["_lodge_pos"])
        projectile["vel"] = pygame.Vector2(0, 0)
        projectile["angle"] = float(projectile["_lodge_angle"])
        projectile["angular_velocity"] = 0.0
        return True
    except Exception:
        return False


# ============================================================
# PROJECTILE TETHER / RETURN SYSTEM  (yoyo / boomerang / grappling line)
# ============================================================
# A tethered projectile keeps a live LINE to its owner (or a rig position
# event on the owner) and obeys a MAX DISTANCE leash. Phases:
#   fly    -> normal flight, leash clamps it at max distance (elastic or hard)
#   lock   -> locked onto a character, following them for a duration
#   return -> homing back to the owner/anchor; catch removes or re-idles it
# All fields live on the projectile dict, so saves/undo/copies keep working.

def _tether_anchor_pos(p):
    """World position the tether line starts from: owner body or a named rig
    position event on the owner (hand, weapon tip, ...)."""
    owner = p.get("owner")
    if not isinstance(owner, dict):
        return pygame.Vector2(p.get("pos", (0, 0)))
    aname = str(p.get("tether_anchor", "") or "")
    if aname:
        try:
            return _weapon_anchor_world(owner, aname)
        except Exception:
            pass
    return pygame.Vector2(owner.get("pos", (0, 0)))

def _tether_start_return(p, reason="scripted"):
    """Begin the return-home phase (boomerang/yoyo comeback)."""
    if not isinstance(p, dict):
        return
    p["_teth_phase"] = "return"
    p["_teth_return_reason"] = str(reason)
    p["_teth_lock_target"] = None
    p["_grounded"] = False; p["_sleeping"] = False
    p["lodged"] = False
    p.pop("_lodge_pos", None); p.pop("_lodge_angle", None)
    # Record return-start geometry so the comeback leg can be EASED (optional).
    # `tether_return_easing` (set via Set Flight: Return Easing) shapes how fast
    # it swings home.  Left unset/linear it keeps the legacy constant reel.
    try:
        _ra = _tether_anchor_pos(p)
        _sp = pygame.Vector2(p.get("pos", _ra))
        p["_teth_return_dist0"] = max(0.0, (_ra - _sp).length())
        p["_teth_return_start"] = _sp
        # Record a fixed perpendicular to the return chord so the optional
        # Return Arc has a stable direction the whole way home (it doesn't
        # rotate with the homing direction, which would spiral instead of bow).
        _ch = _ra - _sp
        _cl = _ch.length()
        if _cl > 1e-6:
            p["_teth_return_normal"] = pygame.Vector2(-_ch.y / _cl, _ch.x / _cl)
        else:
            p["_teth_return_normal"] = pygame.Vector2(1.0, 0.0)
    except Exception:
        p["_teth_return_dist0"] = 0.0
        p["_teth_return_normal"] = pygame.Vector2(1.0, 0.0)

# ── Tether launch gate ───────────────────────────────────────────────────
# Lets a tether be launched only under a gated condition: after the previous
# one returned, once it reaches a chosen phase, within a charge budget, and/or
# after a cooldown.  State is stored per-tether-name on the OWNER (me), so the
# Launch Tethered Projectile node, the Get/Set nodes and per-frame queries all
# agree on the same gate without each node re-deriving it.  Gate off (default)
# and max_charges 0 (unlimited) leave existing launch behaviour unchanged.
_TETHER_PHASES = ("off", "fly", "return", "lock", "held", "caught")


def _tether_live_phase(me, name):
    """The live phase of the named tethered projectile for `me`, or 'off' when
    no such live tether exists in the scene.  The 'still out' phases a 'returned'
    gate treats as blocking are fly / return / lock."""
    name = str(name or "main")
    if not isinstance(me, dict):
        return "off"
    for _p in _WEAPON_PROJECTILES:
        if not isinstance(_p, dict) or not _p.get("alive", True):
            continue
        if not _p.get("tether_enabled"):
            continue
        if _p.get("owner") is not me:
            continue
        if str(_p.get("name", "")) != name:
            continue
        return str(_p.get("_teth_phase", "fly"))
    return "off"


def _tether_gate_store(me, name, create=False):
    """Return (and optionally create) the per-name gate state dict on the owner."""
    name = str(name or "main")
    if not isinstance(me, dict):
        return None
    d = me.setdefault("_tether_gate", {}) if create else me.get("_tether_gate")
    if not isinstance(d, dict):
        return None
    if create:
        return d.setdefault(name, {})
    return d.get(name)


def _tether_gate_status(me, name):
    """Evaluate the launch gate for the named tether.  Returns a dict:
    ready, phase, release, charges_left (-1 = unlimited), max_charges,
    cooldown, cooldown_remaining, gate, require_phase, reason."""
    name = str(name or "main")
    store = _tether_gate_store(me, name, create=False)
    gate = "off"
    require_phase = "caught"
    max_charges = 0
    cooldown = 0.0
    if store:
        gate = str(store.get("gate", "off") or "off")
        require_phase = str(store.get("require_phase", "caught") or "caught")
        max_charges = max(0, int(store.get("max_charges", 0) or 0))
        cooldown = max(0.0, float(store.get("cooldown", 0.0) or 0.0))
    phase = _tether_live_phase(me, name)
    if gate == "returned":
        release = phase in ("caught", "held", "off")
    elif gate == "phase":
        release = (str(phase) == str(require_phase))
    else:
        release = True
    now = _sim_now()
    # Detect the rising edge of "the gate released" (the tether came home /
    # reached the required phase).  We remember WHEN it released so the Launch
    # Cooldown can count from that instant, not from the launch.  This is what
    # gives "must wait 0.5s after the tether comes back before launching again".
    if store is not None:
        prev_release = bool(store.get("_prev_release", True))
        if release and not prev_release:
            store["last_release"] = now
        store["_prev_release"] = release
    charges_left = max_charges
    if store is not None and "charges_left" in store:
        charges_left = max(0, int(store.get("charges_left", max_charges)))
    # Refill the budget the moment a REAL gate releases (the tether came home /
    # reached the chosen phase), so each throw-and-return restores the allowance.
    # A gate of "off" has no release event, so the budget only depletes there
    # (refill via Set Tether Launch Gate / Reset Charges).
    if release and max_charges > 0 and gate != "off":
        charges_left = max_charges
        if store is not None:
            store["charges_left"] = charges_left
    # Cooldown counts from the LATER of the last launch and the last time the
    # gate released (tether returned / reached its phase).  With a 'returned'
    # gate this is exactly "N seconds after it comes back"; on a gate of 'off'
    # (always released) it reduces to "N seconds between launches".  A first
    # launch has nothing to wait out (no last_launch yet).
    if store is not None and "last_launch" in store and cooldown > 0:
        lock_start = float(store["last_launch"])
        if "last_release" in store:
            lock_start = max(lock_start, float(store["last_release"]))
        cd_rem = max(0.0, cooldown - (now - lock_start))
    else:
        cd_rem = 0.0
    ready = bool(release and (max_charges <= 0 or charges_left > 0) and cd_rem <= 0.0)
    reason = ""
    if not ready:
        if cd_rem > 0:
            reason = "cooldown"
        elif max_charges > 0 and charges_left <= 0:
            reason = "charges"
        elif not release:
            reason = "phase"
    return {"ready": ready, "phase": phase, "release": bool(release),
            "charges_left": float(charges_left if max_charges > 0 else -1.0),
            "max_charges": max_charges, "cooldown": cooldown,
            "cooldown_remaining": cd_rem, "gate": gate,
            "require_phase": require_phase, "reason": reason}

def _tether_tick(p, dt):
    """Per-frame tether/return/lock physics for one projectile. Returns True
    when the projectile was caught this frame (handled + possibly removed)."""
    if not isinstance(p, dict) or not p.get("tether_enabled"):
        return False
    owner = p.get("owner")
    anchor = _tether_anchor_pos(p)
    pos = p.get("pos")
    phase = str(p.get("_teth_phase", "fly"))
    now = _sim_now()

    # ---- lock-on / follow a character for a set time ----
    if phase == "lock":
        tgt = p.get("_teth_lock_target")
        if isinstance(tgt, dict) and tgt.get("hp", 1) > 0 and not tgt.get("_despawned"):
            # spring-follow the locked character (offset keeps orbit feel)
            follow = max(0.5, float(p.get("tether_follow_strength", 14.0)))
            want = pygame.Vector2(tgt.get("pos", pos)) + pygame.Vector2(p.get("_teth_lock_offset", (0, 0)))
            blend = 1.0 - math.exp(-follow * dt)
            p["pos"] = pos + (want - pos) * blend
            p["vel"] = (want - pos) * follow * 0.5
            if float(p.get("tether_spin_speed", 0.0)) != 0.0:
                p["angular_velocity"] = float(p.get("tether_spin_speed", 0.0))
            until = p.get("_teth_lock_until")
            if until is not None and now >= float(until):
                if p.get("tether_auto_return", True):
                    _tether_start_return(p, "lock_expired")
                else:
                    p["_teth_phase"] = "fly"
        else:
            # target died/vanished -> come home (or free-fly)
            if p.get("tether_auto_return", True):
                _tether_start_return(p, "target_lost")
            else:
                p["_teth_phase"] = "fly"
        phase = str(p.get("_teth_phase", "fly"))

    # ---- returning home ----
    if phase == "return":
        speed = max(10.0, float(p.get("tether_return_speed", 420.0)))
        accel = max(0.0, float(p.get("tether_return_accel", 0.0)))
        if accel > 0:
            p["_teth_return_speed_now"] = min(speed * 3.0, float(p.get("_teth_return_speed_now", speed)) + accel * dt)
            speed = float(p["_teth_return_speed_now"])
        to_home = anchor - p["pos"]
        dist = to_home.length()
        catch_r = max(4.0, float(p.get("tether_catch_radius", 26.0)))
        # Return Easing shapes the comeback SPEED (optional).  When
        # tether_return_easing is a non-linear curve the reel accelerates /
        # decelerates according to how fast the curve is climbing, so it can
        # snap home instead of always returning at a constant rate.  Default
        # (linear / unset) keeps the legacy constant-speed reel unchanged.
        _te = str(p.get("tether_return_easing", "linear") or "linear")
        if _te not in ("", "linear", "smoothstep"):
            _d0 = max(1e-6, float(p.get("_teth_return_dist0", dist) or dist))
            _prog = max(0.0, min(1.0, 1.0 - dist / _d0))
            _e0 = _weapon_ease(_prog, _te)
            _e1 = _weapon_ease(min(1.0, _prog + 0.02), _te)
            _slope = (_e1 - _e0) / 0.02
            # Same floor as the flight path (0.5): the curve shapes the reel
            # speed so it is clearly VISIBLE, but the 50%-of-base floor keeps a
            # slow-starting curve from creeping so much that it reads as a hold.
            speed = speed * max(0.5, min(3.0, abs(_slope)))
        if dist <= catch_r or dist <= speed * dt:
            # CAUGHT: back at the owner's hand.
            p["_teth_phase"] = "caught"
            if isinstance(owner, dict):
                _ret_pos = pygame.Vector2(p.get("pos", (0, 0)))
                _ret_reason = str(p.get("_teth_return_reason", ""))
                call_hook(owner, "on_projectile_returned", CTX, owner, p, _ret_pos, _ret_reason)
                # Tether-scoped return event: same moment, so an author wiring
                # On Tether Returned gets the catch without also needing the
                # generic projectile-returned event.
                call_hook(owner, "on_tether_returned", CTX, owner, p, _ret_pos, _ret_reason)
            if p.get("tether_destroy_on_return", True):
                p["alive"] = False
                p["_destroy_reason"] = "returned_to_owner"
            else:
                # keep it alive parked at the hand; scripts can relaunch it
                p["pos"] = pygame.Vector2(anchor)
                p["vel"] = pygame.Vector2(0, 0)
                p["_teth_phase"] = "held"
            return True
        # Return Arc bends the comeback into a visible swoop.  `tether_return_arc`
        # (px, signed) bulges the homeward path sideways perpendicular to the
        # chord from where it started returning to the owner; sin(pi*progress)
        # makes the bow zero at both ends so it joins smoothly and the catch is
        # unchanged.  0 (default) = the classic straight reel.  Positive bows to
        # the left of the throw, negative to the right.
        if dist > 1e-9:
            _arc = float(p.get("tether_return_arc", 0.0) or 0.0)
            _norm = p.get("_teth_return_normal")
            if _arc and isinstance(_norm, pygame.Vector2):
                # Progress along the return CHORD (0 at release -> 1 at home),
                # not distance-to-anchor (which is non-monotonic on a curled
                # path and makes the bow fight itself).  sin(pi*t) zeroes the
                # bulge at both ends so it always lands on the owner.
                _st = p.get("_teth_return_start")
                if isinstance(_st, pygame.Vector2):
                    _ch = anchor - _st
                    _cl = _ch.length()
                    if _cl > 1e-6:
                        _cdir = _ch / _cl
                        _along = max(0.0, min(1.0, (p["pos"] - _st).dot(_cdir) / _cl))
                        _bow = math.sin(math.pi * _along) * _arc
                        _target = anchor + _norm * _bow
                        _to_t = _target - p["pos"]
                        if _to_t.length_squared() > 1e-9:
                            p["vel"] = _to_t.normalize() * speed
                        else:
                            p["vel"] = to_home.normalize() * speed
                    else:
                        p["vel"] = to_home.normalize() * speed
                else:
                    p["vel"] = to_home.normalize() * speed
            else:
                p["vel"] = to_home.normalize() * speed
        if float(p.get("tether_spin_speed", 0.0)) != 0.0:
            p["angular_velocity"] = float(p.get("tether_spin_speed", 0.0))
        return False

    if phase == "held":
        # parked at the hand until relaunched
        p["pos"] = pygame.Vector2(anchor)
        p["vel"] = pygame.Vector2(0, 0)
        return False

    # ---- flying: timed return (throw-at-target then boomerang home) ----
    # `tether_return_after` is a flight window in seconds. Once it elapses the
    # projectile launches the return leg even if it never hit anything, so an
    # aimed-but-missed throw still comes home to the thrower. Used by the
    # Lock On (tracking OFF) mode.
    _ra = max(0.0, float(p.get("tether_return_after", 0.0) or 0.0))
    if _ra > 0.0:
        _lt0 = float(p.get("_teth_launch_t0", 0.0) or 0.0)
        if _lt0 <= 0.0:
            p["_teth_launch_t0"] = now
            _lt0 = now
        if now - _lt0 >= _ra:
            _tether_start_return(p, "return_after")
            return False

    # ---- flying: enforce the leash (max distance from owner/anchor) ----
    max_d = float(p.get("tether_max_distance", 0.0) or 0.0)
    if max_d > 0.0:
        delta = p["pos"] - anchor
        dist = delta.length()
        if dist > max_d:
            direction = delta / dist if dist > 1e-9 else pygame.Vector2(1, 0)
            mode = str(p.get("tether_leash_mode", "elastic")).lower()
            was_taut = bool(p.get("_teth_taut"))
            p["_teth_taut"] = True
            if not was_taut and isinstance(owner, dict):
                call_hook(owner, "on_tether_taut", CTX, owner, p,
                          pygame.Vector2(p.get("pos", (0, 0))), float(dist))
            if p.get("tether_return_on_taut", False):
                _tether_start_return(p, "taut")
                return False
            if mode == "hard":
                # rigid rope: clamp position, kill outward velocity
                p["pos"] = anchor + direction * max_d
                out_v = p["vel"].dot(direction)
                if out_v > 0:
                    p["vel"] -= direction * out_v
            else:
                # elastic: spring pull back toward the circle edge.
                # Stiffness scales with elasticity; weight resists the pull.
                stiff = max(0.1, float(p.get("tether_elasticity", 6.0)))
                mass = max(0.05, float(p.get("tether_weight", p.get("weight", 0.0)) or 1.0))
                pull = (dist - max_d) * stiff / mass
                p["vel"] -= direction * pull * dt * 60.0 * 0.16
                # heavy overshoot still gets a soft positional correction
                if dist > max_d * 1.25:
                    p["pos"] = anchor + direction * (max_d * 1.25)
        else:
            p["_teth_taut"] = False
    return False


# ══════════════════════════════════════════════════════════════════════════
# PROJECTILE FLIGHT PATHS  —  eased curves, beziers, waypoints, homing,
# orbit and out-and-back swings.  A projectile whose `flight` config is set
# follows one of these paths every simulation tick instead of falling through
# the normal velocity integrator.  The "easing curve" of a flight is the SAME
# vocabulary every other Interpolate / Ease node uses (`ctx.curve_eval`,
# `_weapon_ease`, and the F8-drawn `curve:` names), so you can build a curved
# dash, a Chlorophyte-style shoot-then-track, or a boomerang swing entirely
# from nodes.
# ══════════════════════════════════════════════════════════════════════════
def _flight_vec(v):
    """Coerce a position/vector into a pygame.Vector2 without throwing."""
    try:
        return pygame.Vector2(v)
    except Exception:
        return pygame.Vector2()


def _flight_resolve_target(p, fl):
    """Resolve the homing/curve target into a dict carrying a 'pos' key.

    Accepts a live character dict, a raw Vector2/(x,y) point, the sentinel
    'nearest', or a tag filter — mirroring how Aim At Target / Aim At Nearest
    resolve their objective so the node behaviour matches muscle memory.
    """
    tgt = fl.get("target")
    if isinstance(tgt, dict) and "pos" in tgt:
        return tgt
    if isinstance(tgt, (pygame.Vector2, tuple, list)):
        return {"pos": pygame.Vector2(tgt)}
    mode = str(fl.get("tracking", "nearest")).lower()
    tag = str(fl.get("tag", "") or "")
    owner = p.get("owner")
    here = p.get("pos", (0, 0))
    if tag and mode in ("nearest", "tag"):
        return _weapon_nearest_enemy(owner, here, tag)
    if tgt in (None, "", "nearest") or mode == "nearest":
        return _weapon_nearest_enemy(owner, here)
    return None


def _flight_center_pos(p, fl, default):
    """World position a flight orbits around (a character, a Vector2, or self)."""
    c = fl.get("center")
    if isinstance(c, dict) and "pos" in c:
        return pygame.Vector2(c.get("pos", default))
    if isinstance(c, (pygame.Vector2, tuple, list)):
        return pygame.Vector2(c)
    if c is None or c == "self":
        owner = p.get("owner")
        if isinstance(owner, dict):
            return pygame.Vector2(owner.get("pos", default))
    return pygame.Vector2(default)


def _flight_bezier2(p0, p1, p2, t):
    """Quadratic Bezier through p0, control p1, end p2 at normalized t."""
    t = max(0.0, min(1.0, float(t)))
    a = 1.0 - t
    return pygame.Vector2(a * a * p0[0] + 2 * a * t * p1[0] + t * t * p2[0],
                          a * a * p0[1] + 2 * a * t * p1[1] + t * t * p2[1])


def _flight_bezier3(p0, p1, p2, p3, t):
    """Cubic Bezier through p0..p3 at normalized t."""
    t = max(0.0, min(1.0, float(t)))
    a = 1.0 - t
    return pygame.Vector2(
        a * a * a * p0[0] + 3 * a * a * t * p1[0] + 3 * a * t * t * p2[0] + t * t * t * p3[0],
        a * a * a * p0[1] + 3 * a * a * t * p1[1] + 3 * a * t * t * p2[1] + t * t * t * p3[1])


def _flight_catmull(points, t):
    """Smooth Catmull-Rom through a polyline of points at normalized t."""
    pts = [_flight_vec(p) for p in points]
    n = len(pts)
    if n <= 0:
        return pygame.Vector2()
    if n == 1:
        return pts[0]
    if n == 2:
        return pts[0] + (pts[1] - pts[0]) * max(0.0, min(1.0, float(t)))
    t = max(0.0, min(1.0, float(t)))
    seg = t * (n - 1)
    i = int(min(n - 2, math.floor(seg)))
    u = seg - i
    p0 = pts[i - 1] if i > 0 else pts[i]
    p1 = pts[i]
    p2 = pts[i + 1]
    p3 = pts[i + 2] if i + 2 < n else pts[i + 1]
    return 0.5 * ((2 * p1) + (-p0 + p2) * u
                  + (2 * p0 - 5 * p1 + 4 * p2 - p3) * u * u
                  + (-p0 + 3 * p1 - 3 * p2 + p3) * u * u * u)


def _flight_sample(q, mode, fl, start):
    """World position on a flight path for path-parameter q in [0, 1]."""
    q = max(0.0, min(1.0, float(q)))
    if mode == "curve":
        end = _flight_vec(fl.get("end", _flight_vec(start) + pygame.Vector2(0, -1)))
        cur = float(fl.get("curvature", 0.0))
        mid = (_flight_vec(start) + end) * 0.5
        d = end - _flight_vec(start)
        n = pygame.Vector2(-d.y, d.x)
        if n.length_squared() > 1e-9:
            n = n.normalize()
        return _flight_bezier2(_flight_vec(start), mid + n * cur, end, q)
    if mode == "bezier":
        s = _flight_vec(start)
        p0 = _flight_vec(fl.get("p0", s))
        p1 = _flight_vec(fl.get("p1", s))
        p2 = _flight_vec(fl.get("p2", s))
        p3 = _flight_vec(fl.get("p3", s))
        return _flight_bezier3(p0, p1, p2, p3, q)
    if mode in ("waypoints", "path"):
        pts = fl.get("points") or []
        if pts:
            return _flight_catmull(pts, q)
        end = _flight_vec(fl.get("end", _flight_vec(start) + pygame.Vector2(0, -1)))
        return _flight_vec(start) + (end - _flight_vec(start)) * q
    # swing == an eased arc out then back to the launcher; reuse curve sampling.
    end = _flight_vec(fl.get("end", _flight_vec(start) + pygame.Vector2(0, -1)))
    cur = float(fl.get("curvature", 0.0))
    mid = (_flight_vec(start) + end) * 0.5
    d = end - _flight_vec(start)
    n = pygame.Vector2(-d.y, d.x)
    if n.length_squared() > 1e-9:
        n = n.normalize()
    return _flight_bezier2(_flight_vec(start), mid + n * cur, end, q)


def _projectile_flight_tick(p, dt):
    """Per-frame flight-path physics for a projectile carrying a `flight` dict.

    Returns True when the projectile's motion was fully driven by the path, so
    the caller skips the normal gravity/drag/homing integrator.  Position is
    produced directly from the path; `vel` is the finite-difference step, so
    wall bounces, knockback direction and travel-angle alignment all keep
    working exactly like a free-flying projectile.
    """
    fl = p.get("flight")
    if not isinstance(fl, dict):
        return False
    mode = str(fl.get("mode") or "straight").lower()
    if mode in ("", "none", "straight", "off"):
        return False
    old = pygame.Vector2(p.get("pos", (0, 0)))
    dt = max(1e-6, float(dt))

    # Keep the visual spin alive on every claimed flight frame.  The tether and
    # plain-physics branches in `_weapon_tick_all` advance rotation, but a
    # flight path (curve/bezier/boomerang/… ) or an on-enemy / apex hold claimed
    # the frame through THIS function, so without this a spinning blade/yoyo
    # would freeze its spin the moment it started flying or holding.
    _ang = float(p.get("angular_velocity", 0.0))
    if _ang != 0.0:
        p["rotation"] = float(p.get("rotation", 0)) + _ang * dt

    # ── GENERIC HOLD (works on ANY flight mode, not just boomerang) ──────
    # `_flight_hold_remaining` (seconds) is a unified hold timer set by the
    # Set Flight: Hold node, by `hold_on_hit` when the projectile tags a
    # character, or by an auto apex hold.  While it is active the path clock
    # is frozen so the projectile lingers in place (or spring-follows a held
    # enemy so it keeps colliding / dealing damage), then resumes exactly where
    # it left off.  A return-capable flight (boomerang/return) swings home right
    # after the hold ends.
    _hold_remain = float(p.get("_flight_hold_remaining", 0.0) or 0.0)
    if _hold_remain > 0:
        new = old
        _htgt = p.get("_flight_hold_target")
        # Tracking toggle.  True = spring-follow the held character (it keeps
        # colliding / dealing repeated damage as it chases them).  False (the
        # "stay where it hit" behaviour) = pin the projectile to the exact point
        # of contact for the whole hold, so it does NOT chase the character even
        # if they move.  `_flight_hold_at` is that contact point, captured when
        # the hold begins.
        _track = bool(p.get("_flight_hold_track", fl.get("hold_track", True)))
        _at = p.get("_flight_hold_at")
        _strength = max(0.5, float(fl.get("hold_follow", 18.0)))
        if isinstance(_htgt, dict) and _htgt.get("hp", 1) > 0 and not _htgt.get("_despawned"):
            want = pygame.Vector2(_htgt.get("pos", old))
            if _track:
                # Follow the moving target; strength = spring stiffness.
                blend = 1.0 - math.exp(-_strength * dt)
                new = old + (want - old) * blend
                p["vel"] = (want - old) * _strength * 0.5
            else:
                # Pinned to the point of contact.  strength = pin rigidity:
                # high (default 18) = frozen dead on the hit spot; low = it
                # creeps a little toward the character, so it still feels like
                # a hard stand-still hold by default.
                base = _at if _at is not None else old
                _k = _strength / 18.0
                _pull = min(1.0, max(0.0, (1.0 - _k)) * 0.05)
                new = base + (want - base) * _pull
                p["vel"] = pygame.Vector2(0, 0)
        else:
            p["vel"] = pygame.Vector2(0, 0)
        p["_flight_hold_remaining"] = _hold_remain - dt
        p["_flight_phase"] = ("on_enemy" if isinstance(p.get("_flight_hold_target"), dict) else "hold")
        if p["_flight_hold_remaining"] <= 0:
            p["_flight_held_done"] = True
        p["pos"] = new
        p["_flight_done"] = False
        p["_grounded"] = False
        p["_sleeping"] = False
        return True
    # A hold just ended: a return-capable flight starts its return leg now.
    if p.pop("_flight_held_done", None) and mode in ("boomerang", "return"):
        p["_flight_phase"] = "back"
        p["_flight_back_t0"] = float(p.get("_flight_t", 0.0))
        p["_flight_phase_t0"] = float(p.get("_flight_t", 0.0))

    if not fl.get("paused"):
        p["_flight_t"] = float(p.get("_flight_t", 0.0)) + dt
    ft = float(p.get("_flight_t", 0.0))
    new = old

    if mode == "custom":
        # Position is driven externally (Set Flight Position / a wired vector
        # from a Bezier/Interpolate chain).  We only keep the derived velocity,
        # angle and alive state; we never move the projectile ourselves, and we
        # claim the frame so the gravity/drag integrator can't override it.
        p["_flight_done"] = False
        return True

    if mode == "homing":
        # Chlorophyte/smart-bullet: fly straight for `delay`, then curve the
        # heading toward the target at a limited turn rate (so it arcs, never
        # snaps); `strength` and the eased `ramp_time` shape how hard it pulls.
        spd = max(0.0, float(fl.get("speed", float(p.get("speed", 260.0)))))
        turn = max(0.0, float(fl.get("turn_rate", 180.0)))
        delay = max(0.0, float(fl.get("delay", 0.0)))
        strength = max(0.0, min(1.0, float(fl.get("strength", 1.0))))
        accel = max(0.0, float(fl.get("accel", 0.0)))
        curve = str(fl.get("easing", "linear"))
        cur = pygame.Vector2(p.get("vel", (0, 0)))
        if cur.length_squared() < 1e-6:
            cur = pygame.Vector2(1, 0).rotate(float(p.get("angle", 0.0))) * spd
        if ft >= delay:
            tgt = _flight_resolve_target(p, fl)
            if tgt is not None:
                desired = pygame.Vector2(tgt.get("pos", (0, 0))) - old
                if desired.length_squared() > 1e-6:
                    desired = desired.normalize()
                    cdir = cur.normalize()
                    diff = ((cdir.angle_to(desired) + 180.0) % 360.0) - 180.0
                    ramp = 1.0
                    rt = max(0.001, float(fl.get("ramp_time", 0.4)))
                    ramp = max(0.0, min(1.0, (ft - delay) / rt))
                    try:
                        ramp = _weapon_ease(ramp, curve)
                    except Exception:
                        pass
                    eff = strength * ramp
                    step = max(-turn * dt, min(turn * dt, diff * eff))
                    cur = cdir.rotate(step).normalize() * spd
                    p["_flight_turn"] = step
        if accel > 0:
            L = cur.length()
            tgt_len = min(spd, L + accel * dt)
            if cur.length_squared() > 1e-6:
                cur = cur.normalize() * max(0.0, tgt_len)
        p["vel"] = cur
        new = old + cur * dt
        p["_flight_done"] = False
    elif mode == "orbit":
        center = _flight_center_pos(p, fl, old)
        radius = max(1.0, float(fl.get("radius", 80.0)))
        aspd = float(fl.get("orbit_speed", float(fl.get("speed", 180.0))))
        cw = bool(fl.get("clockwise", True))
        if not cw:
            aspd = -aspd
        ang = float(fl.get("angle_offset", 0.0)) + ft * aspd
        new = center + pygame.Vector2(radius, 0).rotate(ang)
        tangent = pygame.Vector2(-math.sin(math.radians(ang)), math.cos(math.radians(ang)))
        if not cw:
            tangent = -tangent
        p["vel"] = tangent * (abs(aspd) * math.pi / 180.0 * radius)
        _odur = max(0.0, float(fl.get("duration", 0.0)))
        if _odur > 0 and ft >= _odur:
            p["_flight_done"] = True
            if fl.get("destroy_on_done"):
                p["alive"] = False
                p["_destroy_reason"] = "flight_done"
        else:
            p["_flight_done"] = False
    elif mode in ("boomerang", "return"):
        # ── Boomerang / throw-and-return ─────────────────────────────────────
        # Throw OUT along a fixed (aimed-once) eased curve, linger at the apex
        # (optional Hold Time), then curve BACK to the LIVE owner position.  The
        # out leg NEVER homing/tracks the enemy: its direction is locked in at
        # launch, so it just flies where it was thrown.  The return leg follows
        # the owner (so it comes home to a moving character).  If `hold_on_hit`
        # is set, tagging an enemy switches it into an `on_enemy` hold (for
        # `hit_hold_time` seconds) so lingering deals extra damage, then it
        # swings home.  This is distinct from `homing`, which steers at the
        # target.
        _ph = p.get("_flight_phase", "out")
        out_dur = max(0.05, float(fl.get("out_duration", fl.get("duration", 0.9))))
        hold_time = max(0.0, float(fl.get("hold_time", 0.0)))
        hold_ratio = max(0.0, min(0.6, float(fl.get("hold_ratio", 0.0))))
        back_dur = max(0.05, float(fl.get("return_duration", out_dur)))
        owner_anchor = _tether_anchor_pos(p)
        # The apex hold duration: explicit seconds wins, else out_dur*ratio.
        # A positive value pushes into the GENERIC hold gate (freezes the path
        # clock, then swings home) rather than this phase, keeping hold logic in
        # one place that also serves every other flight mode.
        _hold = hold_time if hold_time > 0 else out_dur * hold_ratio
        anchor = p.get("_flight_start")
        if anchor is None:
            anchor = old
            p["_flight_start"] = old

        if _ph == "out":
            out_ease = str(fl.get("easing", "smoothstep"))
            ph_t0 = float(p.get("_flight_phase_t0", 0.0))
            ph_ft = ft - ph_t0
            if ph_ft < out_dur:
                q = _weapon_ease(max(0.0, min(1.0, ph_ft / out_dur)), out_ease)
                new = _flight_sample(q, "curve", fl, anchor)
            else:
                new = _flight_sample(1.0, "curve", fl, anchor)
            p["vel"] = (new - old) / dt
            _md = max(0.0, float(fl.get("max_distance", 0.0)))
            _out_reached = (_md > 0 and (owner_anchor - new).length() >= _md) or ph_ft >= out_dur
            if _out_reached:
                if _hold > 0 and not p.get("_flight_hold_remaining"):
                    # hand off to the generic hold gate: freeze at the apex for
                    # `_hold` seconds, then the gate flips us onto the back leg.
                    p["_flight_hold_remaining"] = _hold
                    p["_flight_hold_target"] = None
                    p["_flight_phase"] = "hold"
                else:
                    p["_flight_phase"] = "back"
                    p["_flight_back_t0"] = ft
                    p["_flight_phase_t0"] = ft
                p["_flight_done"] = False
            else:
                p["_flight_done"] = False
        else:
            # back leg: turn-limited steer to the live owner + fading curvature
            new = old
            _b0 = float(p.get("_flight_back_t0", 0.0))
            back_prog = max(0.0, min(1.0, (ft - _b0) / back_dur))
            back_ease = str(fl.get("return_easing", "smoothstep"))
            e = _weapon_ease(back_prog, back_ease)
            to_home = owner_anchor - old
            dist = to_home.length()
            catch_r = max(4.0, float(fl.get("catch_radius", 26.0)))
            spd = max(10.0, float(fl.get("return_speed", 420.0)))
            # Return Easing now shapes the SPEED of the comeback (not just the
            # curve bend), so a non-linear curve genuinely changes how fast it
            # swings home instead of reeling at a constant 420 px/s.  The local
            # slope of the curve = how fast progress is advancing right now; a
            # steep curve (e.g. the tail of ease_in / expo_in) snaps home, a
            # flat one eases off.  Clamped so it can't stall or teleport.
            if str(back_ease).strip().lower() not in ("", "linear", "smoothstep"):
                _e2 = _weapon_ease(min(1.0, back_prog + 0.02), back_ease)
                _slope = (_e2 - e) / 0.02
                # The return-easing shapes the comeback SPEED by the local slope
                # of the curve, clamped so it is genuinely VISIBLE yet can never
                # freeze.  A slow-starting curve (ease_in / quad_in / cubic_inout)
                # has a tiny slope right after the point of release: the old
                # 0.05 floor let it crawl at ~5% speed, which read as "the hold
                # is STILL going".  A floor of 1.0 fixed that but flattened every
                # slow-start curve onto the plain return, so they all looked
                # identical.  A 0.5 floor is the balance: the gentle dip to 50%
                # of the return_speed makes the curve clearly distinct (ease_in
                # starts slow, cubic_inout is S-shaped, ease_out shoots off fast)
                # while 50% is still far too quick to ever be mistaken for a hold.
                # The upper clamp keeps a steep curve from teleporting home.
                spd = spd * max(0.5, min(3.0, abs(_slope)))
            if dist <= catch_r or back_prog >= 1.0 or dist <= spd * dt:
                p["_flight_done"] = True
                if fl.get("destroy_on_return", True):
                    p["alive"] = False
                    p["_destroy_reason"] = "returned_to_owner"
                    p["pos"] = new
                else:
                    # arrive but stay alive and parked at the owner (relaunchable)
                    p["pos"] = pygame.Vector2(owner_anchor)
                    p["vel"] = pygame.Vector2(0, 0)
                    p["_flight_phase"] = "held"
                    p["_flight_done"] = False
            else:
                dirv = to_home / dist
                curv = float(fl.get("curvature", 0.0))
                bam = max(-80.0, min(80.0, curv * 0.02))
                bend = bam * (1.0 - e)
                head = dirv.rotate(bend)
                new = old + head * spd * dt
                p["vel"] = head * spd
                p["_flight_done"] = False
    else:
        # Path modes: curve / bezier / waypoints / swing.  Easing is applied to
        # the raw clock, then (for ping-pong) mirrored so the return leg uses
        # the same curve; swing instead splits out / hold / back with a
        # separate return easing.
        dur = max(0.001, float(fl.get("duration", 1.0)))
        raw = ft / dur
        loop = bool(fl.get("loop", False))
        pp = bool(fl.get("pingpong", False))
        curve = str(fl.get("easing", "smoothstep"))
        if loop:
            raw = raw % 1.0
        elif pp:
            cyc = raw % 2.0
            raw = cyc if cyc <= 1.0 else 2.0 - cyc
        else:
            raw = min(1.0, raw)
        if mode == "swing":
            hold = max(0.0, min(0.6, float(fl.get("hold_ratio", 0.14))))
            out = max(0.05, (1.0 - hold) / 2.0)
            rt = out + hold
            raw2 = ft / dur
            back_ease = str(fl.get("return_easing", curve))
            if raw2 <= out:
                q = _weapon_ease(raw2 / out, curve)
            elif raw2 <= rt:
                q = 1.0
            else:
                q = 1.0 - _weapon_ease((raw2 - rt) / out, back_ease)
            q = max(0.0, min(1.0, q))
        else:
            e = raw
            try:
                e = _weapon_ease(raw, curve)
            except Exception:
                pass
            q = max(0.0, min(1.0, e))
        # A path must be anchored to the LAUNCH position, not whatever the
        # projectile drifted to on the previous frame.  Computing the curve
        # against the live position re-shortens the remaining distance each
        # frame, so a curved arc collapses instantly onto its destination
        # instead of arcing outward.  `_flight_start` is captured on the first
        # tick (and reset whenever a new path mode is applied in weapon_op) so
        # the whole journey is sampled against one fixed origin.
        anchor = p.get("_flight_start")
        if anchor is None:
            anchor = old
            p["_flight_start"] = old
        new = _flight_sample(q, mode, fl, anchor)
        p["vel"] = (new - old) / dt
        if ft >= dur and not loop:
            p["_flight_done"] = True
            if fl.get("destroy_on_done"):
                p["alive"] = False
                p["_destroy_reason"] = "flight_done"
        else:
            p["_flight_done"] = bool(p.get("_flight_done", False))

    p["pos"] = new
    if p["vel"].length_squared() > 1e-6:
        p["angle"] = math.degrees(math.atan2(p["vel"].y, p["vel"].x))
    p["_grounded"] = False
    p["_sleeping"] = False
    return True


def _projectile_flight_hold_remaining(p):
    """Seconds left in the current Hold / On-Enemy hold (0 when not holding).
    Reads the unified `_flight_hold_remaining` timer so it works for ANY flight
    mode (curve, bezier, waypoints, swing, homing, orbit, boomerang)."""
    return max(0.0, float(p.get("_flight_hold_remaining", 0.0) or 0.0))


def _projectile_flight_state(p):
    """Live flight readout for getter nodes: progress, eased, speed, heading, etc."""
    fl = p.get("flight")
    ft = float(p.get("_flight_t", 0.0))
    mode = str(fl.get("mode") or "straight") if isinstance(fl, dict) else "straight"
    dur = max(0.001, float(fl.get("duration", 1.0))) if isinstance(fl, dict) else 1.0
    raw = min(1.0, ft / dur) if isinstance(fl, dict) else 0.0
    eased = raw
    if isinstance(fl, dict):
        try:
            eased = _weapon_ease(raw, str(fl.get("easing", "smoothstep")))
        except Exception:
            pass
    return {
        "progress": raw,
        "eased": eased,
        "finished": bool(p.get("_flight_done", False)),
        "remaining": max(0.0, dur - ft),
        "mode": mode,
        # Boomerang flight exposes which leg it is on so scripts can react
        # (e.g. play a "released" sound at the swing-out, a "caught" at home).
        "phase": (str(p.get("_flight_phase", "out")) if mode in ("boomerang", "return") else mode),
        "speed": float(p.get("vel", pygame.Vector2()).length()) if isinstance(p.get("vel"), pygame.Vector2) else float(pygame.Vector2(p.get("vel", (0, 0))).length()),
        "heading": float(p.get("angle", 0.0)),
        "point": pygame.Vector2(p.get("pos", (0, 0))),
    }


def _projectile_hold_gate(p, dt):
    """Advance the unified hold timer for a projectile that has NO active flight
    route (e.g. a plain tethered / launched projectile).  Returns True while the
    projectile is being held so the caller skips normal flight / tether / gravity
    physics for that frame.

    `Set Flight: Hold` (on a character-touch event) and `hold_on_hit` both set
    `_flight_hold_remaining`.  Previously only a projectile WITH a flight mode
    picked that up (inside `_projectile_flight_tick`), so a plain tethered shot
    ignored the hold and just snapped straight home the instant it tagged a
    character.  This gate makes the hold work for those projectiles too: it
    freezes the projectile in place, or spring-follows a held enemy so it keeps
    colliding / dealing repeated damage, then hands off to the normal comeback.
    """
    _hold = float(p.get("_flight_hold_remaining", 0.0) or 0.0)
    if _hold <= 0:
        return False
    old = pygame.Vector2(p.get("pos", (0, 0)))
    new = old
    # Keep spinning while held (a tethered blade/yoyo shouldn't lose its spin
    # just because it froze in place for the hold).
    _ang = float(p.get("angular_velocity", 0.0))
    if _ang != 0.0:
        p["rotation"] = float(p.get("rotation", 0)) + _ang * dt
    _htgt = p.get("_flight_hold_target")
    _track = bool(p.get("_flight_hold_track", True))
    _at = p.get("_flight_hold_at")
    _fcfg = p.get("flight")
    if isinstance(_fcfg, dict):
        _track = bool(p.get("_flight_hold_track", _fcfg.get("hold_track", True)))
    _strength = max(0.5, float(_fcfg.get("hold_follow", 18.0)) if isinstance(_fcfg, dict) else 18.0)
    if isinstance(_htgt, dict) and _htgt.get("hp", 1) > 0 and not _htgt.get("_despawned"):
        want = pygame.Vector2(_htgt.get("pos", old))
        if _track:
            blend = 1.0 - math.exp(-_strength * dt)
            new = old + (want - old) * blend
            p["vel"] = (want - old) * _strength * 0.5
        else:
            base = _at if _at is not None else old
            _k = _strength / 18.0
            _pull = min(1.0, max(0.0, (1.0 - _k)) * 0.05)
            new = base + (want - base) * _pull
            p["vel"] = pygame.Vector2(0, 0)
    else:
        p["vel"] = pygame.Vector2(0, 0)
    p["_flight_hold_remaining"] = _hold - dt
    p["_flight_phase"] = ("on_enemy" if isinstance(p.get("_flight_hold_target"), dict) else "hold")
    if p["_flight_hold_remaining"] <= 0:
        p["_flight_held_done"] = True
    p["pos"] = new
    p["_grounded"] = False
    p["_sleeping"] = False
    return True


def _weapon_tick_all(dt):
    _SIM_CLOCK[0] += max(0.0, float(dt or 0.0))
    now=_sim_now()
    for owner in list(characters):
        rig=owner.get("_weapon_rig",{});anchors=rig.get("anchors",{})
        for a in anchors.values():
            pos=_weapon_anchor_world(owner,a.get("name","main"));mode=a.get("aim_mode")
            target=a.get("aim_target") if mode=="target" else _weapon_nearest_enemy(owner,pos,a.get("aim_tag","")) if mode=="nearest" else None
            if isinstance(target,dict):
                # Store this target for gizmo/debug inspection and turn the
                # anchor in world space every simulation tick.
                a["_aim_live_target"] = target
                d=pygame.Vector2(target.get("pos",pos))-pos
                if d.length_squared()>0:
                    # pygame's Vector2 rotation and the arena's screen-space
                    # gizmo convention both use this signed atan2 directly.
                    # (Negating it mirrors vertical aim: above becomes below.)
                    desired=math.degrees(math.atan2(d.y,d.x))
                    # Angle 0 is a valid facing (east). Do not use `or desired`
                    # here: it made freshly-created 0° anchors believe they were
                    # already at the target and therefore never update.
                    current=float(a.get("angle", desired))
                    delta=(desired-current+180.0)%360.0-180.0
                    dead=max(0.0,float(a.get("aim_deadzone",0.15) or 0.15))
                    if abs(delta) > dead:
                        speed=max(0.01,float(a.get("aim_smooth_speed",12.0) or 12.0))
                        curve=str(a.get("aim_easing","smoothstep") or "smoothstep")
                        if bool(a.get("aim_discrete",False)) or curve == "discrete":
                            # Discrete is a controlled sample-and-hold: it only
                            # changes heading at `speed` updates/sec, keeping an
                            # attached motion clip stable between target swaps.
                            a["_aim_step_clock"]=float(a.get("_aim_step_clock",0.0))+max(0.0,float(dt))
                            if a["_aim_step_clock"] >= 1.0/speed:
                                a["_aim_step_clock"] %= 1.0/speed
                                a["angle"]=desired
                        else:
                            # Exponential response is frame-rate independent;
                            # the chosen easing shapes each small approach step.
                            t=1.0-math.exp(-speed*max(0.0,float(dt)))
                            try: t=_weapon_ease(t,curve)
                            except Exception: pass
                            a["angle"]=current+delta*max(0.0,min(1.0,t))
                    a["aim_target"]=target
                    a["_aim_desired_angle"]=desired
        for name,w in rig.get("weapons",{}).items():
            motion=w.get("motion");v=rig.get("visuals",{}).get(name)
            if motion and v:
                t=(now-motion["start"])/max(.02,motion["duration"])
                if t>=1:
                    w.pop("motion",None)
                    v["motion_offset"]=pygame.Vector2()
                    v["motion_angle"]=0
                    # Auto-disable any timed hitbox when swing finishes
                    hb_name = motion.get("hitbox") or motion.get("collider")
                    if hb_name:
                        hb = rig.get("colliders",{}).get(hb_name)
                        if hb: hb["enabled"] = False
                else:
                    kind=motion["kind"]
                    if kind in ("jab","thrust"):
                        # Extend - brief hold at full extension - retract, instead of a
                        # single raw sine hump. A pure sin(t*pi) reaches full extension
                        # and starts retracting in the same instant, which reads as an
                        # instant snap-out/snap-back no matter how long `duration` is.
                        # This splits the stroke into three phases so there's an actual
                        # felt "punch" with a pause at full reach before it comes back.
                        ease_kind = motion.get("easing","smoothstep")
                        ext_r = float(motion.get("extend_ratio", 0.38))
                        hold_r = float(motion.get("hold_ratio", 0.14))
                        ext_r = max(0.01, min(0.9, ext_r))
                        hold_r = max(0.0, min(0.9 - ext_r, hold_r))
                        if t < ext_r:
                            p = _weapon_ease(t/ext_r, ease_kind)
                            dist_f = p
                        elif t < ext_r+hold_r:
                            dist_f = 1.0
                        else:
                            p = _weapon_ease((t-ext_r-hold_r)/max(0.0001,1.0-ext_r-hold_r), ease_kind)
                            dist_f = 1.0 - p
                        v["motion_offset"]=pygame.Vector2(dist_f*motion["distance"],0)
                    elif kind=="swing":  # easing curve is configurable per-swing (default smoothstep)
                        st = _weapon_ease(t, motion.get("easing","smoothstep"))
                        v["motion_angle"] = (st - 0.5) * motion["arc"]
                    elif kind=="spin":v["motion_angle"]=t*360*motion.get("speed",1)
                    elif kind=="recoil":v["motion_offset"]=pygame.Vector2(-math.sin(t*math.pi)*motion["distance"],0)

                    # === Automatic timed hitbox during swing ===
                    hb_name = motion.get("hitbox") or motion.get("collider")
                    if hb_name:
                        hb = rig.get("colliders",{}).get(hb_name)
                        if hb:
                            hb_start = float(motion.get("hitbox_start", 0.0))
                            hb_dur   = float(motion.get("hitbox_duration", 0.0))
                            if hb_dur <= 0.0:
                                # No explicit window configured -> default to the
                                # extend+hold dwell above (roughly where the limb is
                                # actually out) instead of a near-zero window that
                                # only ever catches frame 1 of the wind-up.
                                hb_start = motion.get("duration",0.25) * 0.30
                                hb_dur   = motion.get("duration",0.25) * 0.40
                            swing_t = t * motion.get("duration", 0.25)
                            should_be_on = (hb_start <= swing_t < (hb_start + max(0.01, hb_dur)))
                            hb["enabled"] = bool(should_be_on)

                if v.get("afterimage") and now-v.get("_last_ghost",0)>.035:
                    v["_last_ghost"]=now
                    v.setdefault("ghosts",[]).append({"pos":pygame.Vector2(_weapon_anchor_world(owner,v.get("anchor","main"))),
                        "angle":float(anchors.get(v.get("anchor","main"),{}).get("angle",0))+float(v.get("motion_angle",0)),"born":now})
            if v and v.get("ghosts"):
                v["ghosts"]=[g for g in v["ghosts"] if now-g["born"]<max(.05,float(v.get("duration",.22)))]
        # Explicit colliders: disabled and zero-damage by default.
        _rig_visuals = rig.get("visuals", {})
        _anchor_vis = None  # anchor->visual hash map, built lazily on first miss
        # Collect all bound collider names from active motion clips of this character
        bound_colliders = set()
        playing = owner.get("_motion_playing")
        if playing:
            for inst in playing.values():
                binds = inst.get("event_colliders")
                if binds:
                    bound_colliders.update(binds.values())

        for col in rig.get("colliders",{}).values():
            if not col.get("enabled"):continue
            if col.get("name") in bound_colliders:
                continue # Skip bound colliders! They are handled by motion events directly!
            anchor_pos = _weapon_anchor_world(owner, col.get("anchor","main"))
            offset = pygame.Vector2(col.get("offset", (0,0)))
            cpos = anchor_pos + offset

            # PUNCH FIX (Arena Arena): jab/thrust moves a rig VISUAL forward via its
            # motion_offset, but colliders never inherited that offset -- the fist
            # sprite lunged while its hitbox stayed parked on the body anchor,
            # which is why damage only ever came from the big static body circle.
            # Any collider that shares an anchor (or a name) with a rig visual now
            # rides that visual's motion offset, so the hitbox travels WITH the fist.
            try:
                _cvis = _rig_visuals.get(col.get("name"))
                if _cvis is None:
                    # Hash visuals by anchor ONCE per rig per tick instead of a
                    # linear scan per collider. dict order preserves the
                    # original first-match-wins behavior exactly.
                    if _anchor_vis is None:
                        _anchor_vis = {}
                        for _vv in _rig_visuals.values():
                            _anchor_vis.setdefault(str(_vv.get("anchor", "")), _vv)
                    _cvis = _anchor_vis.get(str(col.get("anchor", "main")))
                if _cvis is not None:
                    _mo = _cvis.get("motion_offset")
                    if _mo:
                        _cang = float(anchors.get(col.get("anchor", "main"), {}).get("angle", 0))
                        cpos = cpos + pygame.Vector2(_mo).rotate(_cang)
            except Exception:
                pass
            col_scale = float(col.get("scale",1))
            shape = col.get("shape", "circle")

            for target in characters:
                _collider_hits_owner = target is owner
                # Collider self-damage is opt-in, with its own arming delay.
                # This is independent from projectile self-damage/owner-ignore,
                # so a temporary explosion radius can safely be configured on
                # the exact collider that should hurt its creator.
                if _collider_hits_owner:
                    if not col.get("damage_owner",False):
                        continue
                    if now < float(col.get("owner_ignore_until",0.0)):
                        continue
                if not _is_combat_character(target):
                    continue
                required=str(col.get("require_tag",""));ignored=str(col.get("ignore_tag",""));tags=target.get("tags",set())
                if required and required not in tags:continue
                if ignored and ignored in tags:continue

                target_pos = _character_collision_center(target)
                try:
                    _thx, _thy = _character_collision_half_extents(target)
                    target_r = max(float(target.get("radius",20)), float(_thx), float(_thy))
                except Exception:
                    target_r = float(target.get("radius",20))

                hit = False

                if shape == "line":
                    # Proper line (blade) collision - segment vs circle
                    # single-sided: starts at anchor, goes forward (your fix)
                    # double-sided: centered at anchor, extends both ways (old buggy behavior)
                    length = float(col.get("length", 55.0)) * col_scale
                    width = float(col.get("width", 12.0)) * col_scale / 2.0   # half-width
                    double_sided = bool(col.get("double_sided", False))

                    # Direction of the blade (from anchor angle + any motion angle)
                    ang = float(anchors.get(col.get("anchor","main"), {}).get("angle", 0)) + float(col.get("angle", 0))
                    if "motion_angle" in (rig.get("visuals",{}).get(col.get("anchor","main"), {}) or {}):
                        ang += rig["visuals"][col.get("anchor","main")].get("motion_angle", 0)

                    dir_vec = pygame.Vector2(1, 0).rotate(ang)
                    if double_sided:
                        start = cpos - dir_vec * (length * 0.5)
                        end = cpos + dir_vec * (length * 0.5)
                    else:
                        start = cpos
                        end = cpos + dir_vec * length

                    # Closest point on segment to target
                    seg = end - start
                    if seg.length_squared() < 0.0001:
                        closest = start
                    else:
                        t = max(0.0, min(1.0, (target_pos - start).dot(seg) / seg.length_squared()))
                        closest = start + seg * t

                    dist = (target_pos - closest).length()
                    hit = dist <= (width + target_r)

                elif shape == "sprite":
                    # === SPRITE SHAPE COLLIDER: rig sprite IS the collision ===
                    # include_transparent=False -> only opaque pixels count (no damage where its empty)
                    # include_transparent=True  -> whole image rect counts (even transparent)
                    try:
                        # find visual attached to same anchor
                        vis = None
                        _visuals_dict = rig.get("visuals",{})
                        for vv in _visuals_dict.values():
                            if str(vv.get("anchor","")) == str(col.get("anchor","main")):
                                vis = vv
                                break
                        if vis is None:
                            vis = _visuals_dict.get(col.get("name")) or _visuals_dict.get(col.get("anchor","main"))

                        # get image surface for pixel check
                        img_surf = None
                        if vis is not None:
                            try:
                                img_surf = _weapon_visual_surface(vis)
                            except Exception:
                                img_surf = None
                            if img_surf is None:
                                spath = vis.get("sprite","") if isinstance(vis, dict) else ""
                                if spath:
                                    try:
                                        img_surf = load_sprite_asset(spath)
                                    except Exception:
                                        img_surf = None

                        if img_surf is None:
                            # fallback to circle if no sprite
                            cr = float(col.get("radius", 20)) * col_scale
                            hit = cpos.distance_to(target_pos) <= cr + target_r
                        else:
                            ang = float(anchors.get(col.get("anchor","main"), {}).get("angle", 0)) + float(col.get("angle", 0))
                            if vis is not None:
                                ang += float(vis.get("angle",0)) + float(vis.get("motion_angle",0))
                            # combine scales
                            vis_scale = float(vis.get("scale",1.0)) if vis else 1.0
                            tot_scale = max(0.01, vis_scale * col_scale)
                            iw, ih = img_surf.get_width(), img_surf.get_height()
                            # padding extra world units
                            pad = float(col.get("padding", 0.0)) * col_scale
                            # vector from collider center to target in world
                            to_target = target_pos - cpos
                            # rotate into sprite local space (unrotate)
                            local = to_target.rotate(-ang)
                            half_w = (iw * tot_scale) * 0.5 + pad
                            half_h = (ih * tot_scale) * 0.5 + pad

                            # closest point on rect
                            clamped_x = max(-half_w, min(half_w, local.x))
                            clamped_y = max(-half_h, min(half_h, local.y))
                            closest_pt = pygame.Vector2(clamped_x, clamped_y)
                            # distance from closest point on rect to target center (OBB vs circle)
                            dist_to_rect = (local - closest_pt).length()
                            if dist_to_rect > target_r:
                                hit = False
                            else:
                                include_trans = bool(col.get("include_transparent", False))
                                if include_trans:
                                    hit = True
                                else:
                                    # pixel-perfect: check alpha at closest point inside image
                                    # map world local to image pixel
                                    # local is in world units, tot_scale scales pixels to world
                                    # pixel offset from center = local / tot_scale
                                    # If closest point is on edge outside image, we check edge pixel
                                    check_local = local if (abs(local.x) <= half_w and abs(local.y) <= half_h) else closest_pt
                                    # convert to pixel coords
                                    px = int((iw * 0.5) + (check_local.x / tot_scale))
                                    py = int((ih * 0.5) + (check_local.y / tot_scale))
                                    # clamp to image
                                    if 0 <= px < iw and 0 <= py < ih:
                                        try:
                                            alpha = img_surf.get_at((px, py)).a if hasattr(img_surf.get_at((px, py)), 'a') else img_surf.get_at((px, py))[3]
                                            # threshold: 0-255
                                            thresh = float(col.get("threshold", col.get("alpha_threshold", 20.0)))
                                            hit = alpha >= thresh
                                            # if transparent at center but target is big, sample a few points around circle
                                            if not hit and target_r > 4:
                                                # sample 4 points around target circle towards collider center
                                                for ox, oy in [(target_r*0.5,0),(-target_r*0.5,0),(0,target_r*0.5),(0,-target_r*0.5)]:
                                                    samp = pygame.Vector2(check_local.x + ox, check_local.y + oy)
                                                    # must still be inside rect
                                                    if abs(samp.x) > half_w or abs(samp.y) > half_h:
                                                        continue
                                                    spx = int((iw * 0.5) + (samp.x / tot_scale))
                                                    spy = int((ih * 0.5) + (samp.y / tot_scale))
                                                    if 0 <= spx < iw and 0 <= spy < ih:
                                                        try:
                                                            a2 = img_surf.get_at((spx, spy))[3] if len(img_surf.get_at((spx, spy)))>3 else 255
                                                            if a2 >= thresh:
                                                                hit = True
                                                                break
                                                        except Exception:
                                                            pass
                                        except Exception:
                                            # if pixel read fails, fallback to rect hit
                                            hit = True
                                    else:
                                        hit = False
                    except Exception as _e:
                        # on any error, fallback to simple rect check so it doesn't crash game
                        # print("sprite collider error", _e)
                        hit = cpos.distance_to(target_pos) <= float(col.get("length", 40)) * col_scale + target_r

                elif shape == "rect":
                    # Proper oriented-box vs character-circle test.  Motion
                    # event bindings rotate the anchor with the event; the old
                    # axis-aligned fallback ignored that rotation, so a visible
                    # box could touch at its ends/corners but only register near
                    # the center.
                    cw = float(col.get("width", 40)) * col_scale
                    ch = float(col.get("height", 24)) * col_scale
                    _anchor_ang = _weapon_anchor_world_angle(owner, col.get("anchor", "main"))
                    _rect_ang = _anchor_ang + float(col.get("angle", 0.0))
                    _local_target = (target_pos - cpos).rotate(-_rect_ang)
                    _hw, _hh = cw * .5, ch * .5
                    _closest = pygame.Vector2(max(-_hw, min(_hw, _local_target.x)),
                                               max(-_hh, min(_hh, _local_target.y)))
                    hit = (_local_target - _closest).length_squared() <= target_r * target_r

                else:
                    # Default circle (original behavior)
                    cr = float(col.get("radius", max(float(col.get("width",20)), float(col.get("height",20)))*.5)) * col_scale
                    hit = cpos.distance_to(target_pos) <= cr + target_r

                                # === HIT COOLDOWN + ONE-TIME-PER-TOUCH LOGIC (fixed for swarm clones + orbit jitter) ===
                # Use python id so clones with same name get unique tracking
                touching = col.setdefault("_currently_touching", {})
                last_hits = col.setdefault("_last_hits", {})
                try:
                    key = str(id(target))
                except Exception:
                    key = str(target.get("id", target.get("name", "unknown")))
                last = float(last_hits.get(key, 0.0))
                cooldown = float(col.get("hit_cooldown", col.get("cooldown", col.get("interval", 0.55))))
                once_per_touch = bool(col.get("once_per_touch", col.get("single_hit", True)))
                exit_grace = float(col.get("touch_grace", col.get("reentry_delay", 0.28)))
                # spawn immunity - don't hit freshly spawned chars (fixes swarm from library spawning inside blade)
                spawn_immunity = float(col.get("spawn_immunity", 0.35))
                try:
                    # spawn_time is pygame ticks /1000 in original code, compare with current ticks
                    import pygame as _pg_check
                    _now_ticks = _pg_check.time.get_ticks() / 1000.0
                    _spawn_t = float(target.get("spawn_time", _now_ticks))
                    if _now_ticks - _spawn_t < spawn_immunity:
                        continue
                except Exception:
                    pass

                if hit:
                    now_touching = touching.get(key)
                    is_new_touch = now_touching is None
                    if not is_new_touch:
                        if once_per_touch:
                            touching[key] = now
                            continue
                        else:
                            if now - last < cooldown:
                                touching[key] = now
                                continue
                    # new touch - also respect cooldown from last hit even after exit (prevents instant re-hit spam)
                    if not is_new_touch and now - last < cooldown:
                        touching[key] = now
                        continue

                    # global per-target cooldown to prevent swarm burst (10 clones hitting same enemy same frame)
                    _global_hit_cd = float(col.get("global_cooldown", 0.12))
                    _last_global = float(target.get("_last_weapon_hit_time", 0.0))
                    # use time.time() for global check (now is time.time())
                    if now - _last_global < _global_hit_cd:
                        # still update touching to prevent re-trigger spam, but skip damage this time
                        touching[key] = now
                        # don't update last_hits so it can try again after global cd?
                        # we will skip this hit
                        continue

                    touching[key] = now
                    last_hits[key] = now
                    target["_last_weapon_hit_time"] = now
                    if float(col.get("damage",0))>0:
                        _col_crit,_col_crit_mult=_projectile_critical_roll(col);_col_damage=float(col["damage"])*(_col_crit_mult if _col_crit else 1.0);col["_last_crit"]=bool(_col_crit)
                        CTX.deal_script_damage(owner,target,_col_damage,
                                               allow_self=bool(_collider_hits_owner and col.get("damage_owner",False)),
                                               crit=_col_crit,already_rolled_crit=_col_crit,
                                               crit_multiplier_override=_col_crit_mult)
                    if float(col.get("knockback",0))>0:
                        # Push away from the attacker's actual body center instead of the weapon collider's center!
                        # This prevents close targets from being sucked towards the attacker and getting stuck bouncing.
                        d = target_pos - (cpos if _collider_hits_owner else _character_collision_center(owner))
                        if d.length_squared() < 1e-4:
                            d = pygame.Vector2(owner.get("facing", (1, 0)))
                            if d.length_squared() < 1e-4:
                                d = pygame.Vector2(1, 0)
                        if d.length_squared()>0:
                            # Route rig knockback through the external-momentum
                            # channel so a later body touch consumes it instead
                            # of turning it into a momentum chain reaction.
                            CTX.apply_impulse(target, d.normalize().x * float(col["knockback"]),
                                              d.normalize().y * float(col["knockback"]),
                                              duration=col.get("knockback_duration", 0.25),
                                              stack=col.get("knockback_stack", False))
                    rig["events"].setdefault("rig_event_collision",[]).append({"collider":col.get("name"),"target":target,"time":now})
                    call_hook(owner,"on_rig_collision",CTX,owner,target,col)
                else:
                    if key in touching:
                        if now - touching[key] > exit_grace:
                            del touching[key]
                
    for p in list(_WEAPON_PROJECTILES):
        if not p.get("alive",True):continue
        # Per-instance delayed destruction. Each projectile owns this value;
        # simultaneous shots never share or carry over another shot's timer.
        if p.get("_destroy_delay") is not None:
            p["_destroy_delay"]=float(p.get("_destroy_delay",0.0))-dt
            if p["_destroy_delay"]<=0:
                p["alive"]=False;p["_destroy_reason"]="timed_destroy";continue
        p["life"]-=dt
        _was_projectile_sleeping=bool(p.get("_sleeping",False))
        p["owner_ignore"]=max(0.0,float(p.get("owner_ignore",0))-dt)

        # Tether/return/lock phases override plain flight. Runs before the
        # physics integration so leash clamps and homing-return velocities
        # take effect this same frame. A catch may remove the projectile.
        _teth_caught = _tether_tick(p, dt)
        if _teth_caught or not p.get("alive", True):
            continue
        _teth_phase = str(p.get("_teth_phase", "fly")) if p.get("tether_enabled") else "fly"
        _teth_controlled = _teth_phase in ("return", "lock", "held")

        # Once lodged, a projectile is no longer a simulated body.  Previously
        # gravity was added before the lodged check every frame, so it moved a
        # little, rotated toward +Y (90 degrees), then had only velocity zeroed.
        # That repeated forever and looked like sliding/snapping down the wall.
        _is_lodged = _projectile_lock_lodged_transform(p)
        # A projectile WITH an active flight route handles its own hold inside
        # `_projectile_flight_tick`.  For one WITHOUT a flight route (a plain
        # tethered / launched shot), Set Flight: Hold still needs to freeze it —
