                    w = max(2.0, float(c.get("width", 12.0)) * float(c.get("scale", 1.0)))
                    ang = float(anchors.get(c.get("anchor","main"),{}).get("angle", 0)) + float(c.get("angle", 0))
                    dirv = pygame.Vector2(1, 0).rotate(ang)
                    double_sided = bool(c.get("double_sided", False))
                    if double_sided:
                        start_draw = sp - dirv * (length * 0.5 * camera["zoom"])
