def pe_default(name=None, wx=0.0, wy=0.0):
    """A sensible, immediately-visible emitter (soft warm sparks)."""
    pid = _pe_next_id[0]
    _pe_next_id[0] += 1
    _d = {
        "id": pid,
        "name": str(name or f"Emitter {pid}"),
        "enabled": True,
        "visible": True,
        "locked": False,
        "wx": float(wx), "wy": float(wy),
        "preset": "custom",
        # Multiplies every size, speed and distance so an effect authored at
        # one scale can be matched to a scene with much larger or smaller
        # characters without re-tuning a dozen sliders by hand.
        "world_scale": 1.0,
        # Optional persistent binding used by visual-script particle nodes.
        # {"type":"character|anchor|motion_event", "owner":"name", ...}
        # Stored without an underscore so an authored trail/aura survives save/load.
        "binding": None,

        # ── emission ──────────────────────────────────────────────
        "emitting": True,
        "rate": 40.0,             # particles per second
        "one_shot": False,        # emit `burst` once, then stop
        "burst": 24,              # count for one-shot / manual bursts
        "explosiveness": 0.0,     # 0 = steady stream, 1 = all at once
        "max_particles": 400,
        "prewarm": False,         # start already running (no ramp-up)
        "local_space": False,     # particles follow the emitter when it moves
        "duration": 0.0,          # >0 = auto-stop after N seconds
        "_age": 0.0,
        "_accum": 0.0,

        # ── shape ─────────────────────────────────────────────────
        "shape": "point",
        "radius": 40.0,           # circle / ring
        "inner_radius": 24.0,     # ring
        "rect_w": 120.0, "rect_h": 40.0,
        "line_len": 120.0, "line_angle": 0.0,
        "path": [],               # [[x,y], ...] world-relative points
        "path_closed": False,
        "path_smooth": True,      # Catmull-Rom through the points
        "path_follow": False,     # particles travel ALONG the path
        "path_jitter": 0.0,

        # ── initial motion ────────────────────────────────────────
        "direction": -90.0,       # degrees; -90 = up
        "spread": 25.0,           # +/- degrees around direction
        "speed_min": 60.0, "speed_max": 140.0,
        # How much of the emitter's own motion each new particle keeps.
        # 1.0 = fully carried along (sparks off a moving torch), 0 = the
        # emitter slides out from under them (smoke hanging in the air).
        "inherit_velocity": 0.0,
        # Continuous drag on particles ALREADY in flight, as a fraction of
        # the emitter's movement each frame. This is the "the whole plume
        # follows the emitter" look, distinct from inherit_velocity which
        # only affects particles at birth.
        "follow_strength": 0.0,
        "_vx": 0.0, "_vy": 0.0,       # measured emitter velocity
        "_pwx": None, "_pwy": None,   # previous world position
        "align_to_shape": False,  # circle/ring: fire outward from centre

        # ── lifetime ──────────────────────────────────────────────
        "life_min": 0.8, "life_max": 1.6,

        # ── forces ────────────────────────────────────────────────
        "gravity_x": 0.0, "gravity_y": 120.0,
        # Scriptable persistent acceleration. Unlike a one-frame impulse it is
        # applied to every live particle every tick, so hit normals, wind, and
        # gameplay fields can steer an effect after it has spawned.
        "force_x": 0.0, "force_y": 0.0,
        "accel_radial": 0.0,      # away from (+) / toward (-) the emitter
        "accel_tangent": 0.0,     # swirl
        "damping": 0.4,           # velocity decay per second
        "orbit": 0.0,             # degrees/sec rotation around the emitter

        # ── FLOAT & LINGER (item drops) ──────────────────────────────
        # Terraria-style pickups: a sine bob makes a dropped item hover
        # and drift up and down like it's floating on a spring.
        "bob_amp": 0.0,          # vertical bob height in px
        "bob_speed": 1.2,        # bobs per second
        "bob_phase_rnd": 1.0,    # 0 = every particle bobs in sync
        # Zero-g hover: cancels gravity and bleeds off launch speed so
        # the particle hangs in the air where it dropped instead of
        # falling to the floor.
        "linger": False,

        # ── wind + turbulence (what makes fire read as fire) ──────
        "wind_x": 0.0, "wind_y": 0.0,
        "wind_gust": 0.0,         # amplitude of the sway
        "wind_freq": 1.2,         # gusts per second
        "turbulence": 0.0,        # per-particle curl strength
        "turb_scale": 0.01,       # spatial frequency of the noise
        "turb_speed": 1.0,

        # ── appearance ────────────────────────────────────────────
        "render": "circle",
        "blend": "add",
        "size_start": 6.0, "size_end": 0.0,
        "size_curve": "linear",
        "color_start": [255, 200, 90],
        "color_end": [255, 60, 0],
        "color_mid": None,        # optional 3-stop gradient
        "alpha_start": 1.0, "alpha_end": 0.0,
        "alpha_curve": "ease_out",
        "sprite": "",
        # 0 = crisp hard-edged dot, 1 = full soft glow falloff. Only applies
        # to render="circle" (render="circle_hard" always forces a hard edge
        # regardless of this, and "square" is always flat).
        "edge_softness": 0.85,
        # ── ELLIPSE WARP ─────────────────────────────────────────────
        # Circles warp into ellipses: squash/stretch along an axis with
        # lifetime easing and an optional pulsing wobble. Aspect 1 = a
        # plain circle (all of this is free when untouched).
        "ellipse_aspect": 1.0,       # stretch at birth (1 = circle)
        "ellipse_aspect_end": 1.0,   # stretch at death
        "ellipse_osc": 0.0,          # 0..1 warp wobble depth
        "ellipse_osc_freq": 2.0,     # wobbles per second
        "ellipse_axis_mode": "fixed",# fixed | velocity | spin
        "ellipse_axis": 0.0,         # degrees, when mode = fixed
        # ── TEXTURE POOL ──────────────────────────────────────────────
        # A list of per-texture entries so ONE emitter can throw several
        # different images. This is the "character explodes into 3 body
        # parts" case: each entry is its own sprite with its own weight,
        # size multiplier, and optional count-per-burst.
        #   {"sprite": path, "weight": 1.0, "scale": 1.0, "opacity": 1.0,
        #    "tint": None|[r,g,b], "count": 0, "spin": None}
        # weight  -> relative pick chance when mode is "random"
        # count>0 -> in "sequence"/"exact" mode, emit exactly N of this one
        "textures": [],
        "texture_mode": "random",   # random | sequence | exact
        "spin_min": 0.0, "spin_max": 0.0,
        "spin_over_life": False,
        "spin_start": 0.0, "spin_end": 0.0,
        "spin_transition_time": 1.0,  # used by infinite-lifetime particles
        "stretch": 2.0,           # streak length multiplier
        # Ghost copies drawn behind each particle along its recent path.
        # Reads as a motion trail without spawning extra particles.
        "trail": 0,
        "trail_fade": 0.55,       # how quickly ghosts fade back
        "trail_shrink": 0.75,     # size falloff per ghost
        # Fade IN over the first slice of life. Without this, big soft
        # particles (steam, clouds) visibly pop into existence.
        "fade_in": 0.0,           # 0..1 fraction of lifetime
        # A floor the particles collide with, independent of arena walls --
        # this is what lets a waterfall splash at its base.
        "floor_offset": None,     # emitter-relative Y, None = off
        "floor_bounce": 0.3,
        "floor_kill": False,
        "sub_on_floor": "",       # preset spawned where they land
        # ── PHASE CHAINS ──────────────────────────────────────────────
        # Movement stages a particle walks through one after another.
        # Each phase overrides motion while it lasts (gravity, damping,
        # spin, bob, zero-g hover) and blends smoothly into the next one.
        #   {"duration": 0.8, "blend": 0.2, "gravity_y": 560,
        #    "damping": 0.1, "spin": 320, "bob_amp": 0, "bob_speed": 1.2,
        #    "linger": False}
        # duration<=0 = the phase lasts until the particle dies.
        "phases": [],
        # What happens when the last phase finishes:
        #   die            -> the particle just ends
        #   die_and_spawn  -> ends AND spawns sub_on_phase_end here
        #   loop           -> restart the phases until life runs out
        "phase_end_action": "die",
        "sub_on_phase_end": "",   # preset spawned at the phase transition

        # ── collision ─────────────────────────────────────────────
        "collide_walls": False,
        "bounce": 0.4,
        "kill_on_hit": False,
        "floor_y": None,

        # ── ATTRACTORS ────────────────────────────────────────────────
        # Points that pull or push particles. Emitter-relative.
        #   {"x":0,"y":0,"strength":200,"radius":300,"mode":"pull"}
        "attractors": [],

        # ── SUB-EMITTERS ──────────────────────────────────────────────
        # Spawn another preset when a particle dies (or on collision).
        # Smoke puffs trailing sparks, debris leaving dust, etc.
        "sub_on_death": "",        # preset name, "" = off
        "sub_count": 3,
        "sub_chance": 1.0,
        "sub_on_collide": "",

        # ── TARGET SEEK / PICKUP PARTICLES ─────────────────────────────
        # Runtime target is kept in _homing_target; these authored values are
        # plain JSON and can be configured by Particle Interaction nodes.
        "homing_enabled": False,
        "homing_delay": 0.0,
        "homing_speed": 220.0,
        "homing_accel": 900.0,
        "homing_turn_rate": 720.0,
        "homing_touch_radius": 18.0,
        "homing_consume_on_touch": True,
        "homing_touch_once": True,
        "homing_amount": 1.0,
        "homing_touch_preset": "",
        "homing_keep_alive": 4.0,

        # ── ANIMATED SPRITES ──────────────────────────────────────────
        # Play a frame sequence over each particle's lifetime.
        "anim_frames": [],         # list of sprite paths
        "anim_fps": 12.0,
        "anim_over_life": True,    # stretch the sequence across the lifetime

        # ── VELOCITY-ALIGNED ROTATION ─────────────────────────────────
        "align_rotation": False,   # point sprites along their travel
        "rotation_offset": 0.0,

        # ── SOFT / FLICKER ────────────────────────────────────────────
        "flicker": 0.0,            # random per-frame alpha jitter 0..1
        "size_jitter": 0.0,        # per-particle size variance 0..1

        "draw_layer": "front",
        "layer": 0,
        "_particles": [],
    }
    for _group, _key, _default, _lo, _hi in PE_PRO_SPECS:
        _d.setdefault(_key, _default)
    # Frame holds are seconds per frame. A hold of 0 is intentionally infinite:
    # playback stops on that frame and never wraps.
    _d.setdefault("anim_frame_holds", [])
    _d.setdefault("anim_loop", True)
    _d.setdefault("anim_pingpong", False)
    _d.setdefault("anim_random_start", False)
    return _d

