# Project-independent user preset shelf. Saved as ordinary JSON next to the
# application so custom effects are immediately available in every project.
PE_CUSTOM_PRESETS = {}
_PE_CUSTOM_PRESETS_PATH = _cfg_path('emitters', 'particle_presets.json')

_PE_PRESETS_LOADED = False
_PE_PRESETS_LOAD_BLOCKED = False

def load_particle_custom_presets():
    global _PE_PRESETS_LOADED, _PE_PRESETS_LOAD_BLOCKED
    data, source = _data_store_read_safe(_PE_CUSTOM_PRESETS_PATH, "Particle Presets", "dict")
    if source == "blocked":
        _PE_PRESETS_LOADED = False
        _PE_PRESETS_LOAD_BLOCKED = True
        return
    _PE_PRESETS_LOAD_BLOCKED = False
    _PE_PRESETS_LOADED = True
    if data is not None:
        for name, pdata in data.items():
            if isinstance(pdata, dict):
                clean = {str(k): (list(v) if isinstance(v, list) else v)
                         for k, v in pdata.items()}
                key = "custom:" + str(name).strip()[:36]
                if key != "custom:":
                    PE_CUSTOM_PRESETS[key] = clean
                    PE_PRESETS[key] = clean

def _save_particle_presets_file():
    """Persist the user's custom emitter presets with backup rotation +
    wipe protection. Returns True on success."""
    global _PE_PRESETS_LOADED, _PE_PRESETS_LOAD_BLOCKED
    if _PE_PRESETS_LOAD_BLOCKED:
        print("!! Refusing to save particle presets: last load failed and no backup was usable.")
        try:
            push_toast("Particle-preset save skipped - restore a backup first (see console).", "warning", 5.0)
        except Exception:
            pass
        return False
    serial = {k[7:]: v for k, v in PE_CUSTOM_PRESETS.items() if k.startswith("custom:")}
    if not _PE_PRESETS_LOADED and os.path.isfile(_PE_CUSTOM_PRESETS_PATH):
        serial = _data_store_merge(_PE_CUSTOM_PRESETS_PATH, serial, "Particle Presets", "dict")
        _PE_PRESETS_LOADED = True
    return _data_store_write_safe(_PE_CUSTOM_PRESETS_PATH, serial, "Particle Presets", _PE_PRESETS_LOADED)
def save_particle_custom_preset(name, emitter):
    name = " ".join(str(name or "").split())[:36]
    if not name:
        return None
    key = "custom:" + name
    # Texture slots and animation frames are part of the authored preset,
    # not emitter identity. Keep them so node-spawned instances render the
    # same sprites as the Particle Creator preview.
    _preset_identity = set(PE_IDENTITY_KEYS) - {"textures", "texture_mode", "anim_frames",
        "anim_frame_holds", "anim_loop", "anim_pingpong", "anim_random_start",
        "anim_over_life", "anim_fps"}
    data = {k: _pe_safe_clone(v) for k, v in emitter.items()
            if k not in _preset_identity and not str(k).startswith("_")
            and k not in ("preset", "emitting")}
    PE_CUSTOM_PRESETS[key] = data
    PE_PRESETS[key] = data
    if _save_particle_presets_file():
        return key
    return None
def delete_particle_custom_preset(key):
    """Remove one of the user's saved custom presets (built-ins are protected)."""
    key = str(key)
    if not key.startswith("custom:"):
        return False
    PE_CUSTOM_PRESETS.pop(key, None)
    PE_PRESETS.pop(key, None)
    return _save_particle_presets_file()
load_particle_custom_presets()

# Fields that belong to the emitter as an object rather than to the look of
# the effect. Switching preset must never move or rename your emitter.
PE_IDENTITY_KEYS = ("id", "name", "wx", "wy", "enabled", "visible", "locked",
                    "draw_layer", "layer", "world_scale", "binding", "textures",
                    "texture_mode", "anim_frames", "anim_frame_holds", "anim_loop",
                    "anim_pingpong", "anim_random_start", "anim_over_life", "anim_fps")

def pe_apply_preset(em, key, keep_textures=True):
    """Replace an emitter's settings with a preset.

    This used to only overlay the keys a preset happened to define, so any
    field it didn't mention kept the PREVIOUS preset's value. Switching
    fire -> rain left fire's turbulence, gusts and colour ramp behind, and
    the result degraded further with every swap.

    The emitter is now rebuilt from defaults first, so every preset starts
    from a known state. Identity, placement, scale and your own textures
    survive the swap.
    """
    p = PE_PRESETS.get(str(key))
    if not p:
        return False
    keep = {k: em.get(k) for k in PE_IDENTITY_KEYS if k in em}
    # A newly-created emitter starts with empty texture fields. Do not let
    # those empty defaults overwrite the textures/sprite animation authored
    # in the selected Particle Creator preset. Existing non-empty textures
    # are still preserved when explicitly switching an already configured
    # emitter.
    if not keep.get("textures"):
        keep.pop("textures", None)
        keep.pop("texture_mode", None)
    _anim_identity=("anim_frames","anim_frame_holds","anim_loop","anim_pingpong",
                    "anim_random_start","anim_over_life","anim_fps")
    if not keep.get("anim_frames"):
        for _k in _anim_identity:keep.pop(_k,None)
    if not keep_textures:
        for _k in ("textures", "texture_mode")+_anim_identity:
            keep.pop(_k, None)

    fresh = pe_default(name=keep.get("name"), wx=keep.get("wx", 0.0),
                       wy=keep.get("wy", 0.0))
    em.clear()
    em.update(fresh)
    for k, v in p.items():
        em[k] = list(v) if isinstance(v, list) else v
    # The crescent 'slash' render was retired; old project files and custom
    # presets that still reference it fall back to the motion-smear look.
    if em.get("render") == "slash":
        em["render"] = "smear"
    for k, v in keep.items():
        if v is not None:
            em[k] = v
    em["preset"] = str(key)
    # Runtime state must reset too, or the previous cloud lingers.
    em["_particles"] = []
    em["_accum"] = 0.0
    em["_age"] = 0.0
    em["_emit_count"] = 0
    em["_tex_sched"] = None
    em["_pwx"] = None
    em["_pwy"] = None
    em["_vx"] = 0.0
    em["_vy"] = 0.0
    em.pop("_fired", None)
    em["emitting"] = True
    pe_normalize(em)
    return True

def pe_normalize(em):
    """Coerce list-of-dict fields loaded from JSON back into safe shapes."""
    tex = []
    for t in (em.get("textures") or []):
        if isinstance(t, str):
            t = {"sprite": t}
        if not isinstance(t, dict):
            continue
        tex.append({
            "sprite": str(t.get("sprite", "") or ""),
            "weight": max(0.0, float(t.get("weight", 1.0) or 0.0)),
            "scale":  max(0.01, float(t.get("scale", 1.0) or 1.0)),
            "opacity": max(0.0, min(1.0, float(t.get("opacity", 1.0) if t.get("opacity") is not None else 1.0))),
            "tint":   list(t["tint"]) if t.get("tint") else None,
            "count":  max(0, int(t.get("count", 0) or 0)),
            "spin":   None if t.get("spin") is None else float(t["spin"]),
        })
    em["textures"] = tex
    if em.get("texture_mode") not in ("random", "sequence", "exact"):
        em["texture_mode"] = "random"

    atts = []
    for a in (em.get("attractors") or []):
        if not isinstance(a, dict):
            continue
        atts.append({
            "x": float(a.get("x", 0.0)), "y": float(a.get("y", 0.0)),
            "strength": float(a.get("strength", 200.0)),
            "radius": max(1.0, float(a.get("radius", 300.0))),
            "mode": a.get("mode") if a.get("mode") in ("pull", "push", "orbit") else "pull",
            "delay": max(0.0, float(a.get("delay", 0.0) or 0.0)),
            "duration": max(0.0, float(a.get("duration", 0.0) or 0.0)),
            "target_name": str(a.get("target_name", "") or ""),
        })
    em["attractors"] = atts
    em["anim_frames"] = [str(p) for p in (em.get("anim_frames") or []) if p]
    _holds=[]
    for _h in (em.get("anim_frame_holds") or []):
        try: _holds.append(max(0.0,float(_h)))
        except Exception: _holds.append(1.0/max(.01,float(em.get("anim_fps",12))))
    _fallback=1.0/max(.01,float(em.get("anim_fps",12)))
    while len(_holds)<len(em["anim_frames"]): _holds.append(_fallback)
    em["anim_frame_holds"]=_holds[:len(em["anim_frames"])]
    em["anim_loop"]=bool(em.get("anim_loop",True));em["anim_pingpong"]=bool(em.get("anim_pingpong",False))
    # The node system stores bindings as JSON-safe dictionaries. Be strict at
    # load time so a damaged/old scene cannot make the particle tick crash.
    _bind = em.get("binding")
    if not isinstance(_bind, dict):
        em["binding"] = None
    else:
        _bind = dict(_bind)
        _kind = str(_bind.get("type", "") or "").lower()
        if _kind not in ("character", "anchor", "motion_event"):
            em["binding"] = None
        else:
            _bind["type"] = _kind
            _bind["owner"] = str(_bind.get("owner", "") or "")
            _bind["anchor"] = str(_bind.get("anchor", "") or "")
            _bind["clip"] = str(_bind.get("clip", "") or "")
            _bind["event"] = str(_bind.get("event", "") or "")
            try:
                _off = list(_bind.get("offset", [0.0, 0.0]))
                _bind["offset"] = [float(_off[0]), float(_off[1])]
            except Exception:
                _bind["offset"] = [0.0, 0.0]
            _bind["local_offset"] = bool(_bind.get("local_offset", True))
            _bind["rotate"] = bool(_bind.get("rotate", _kind != "character"))
            em["binding"] = _bind
    # Repair old/imported generic labels at load time, so serialized scenes,
    # the editor list, and scene gizmos all agree on the preset name.
    if not str(em.get("name", "")).strip() or re.fullmatch(r"Emitter\s*\d+", str(em.get("name", "")), re.I):
        em["name"] = pe_preset_label(em.get("preset"))
    return em

def pe_pick_texture(em, index):
    """Choose a texture entry for a new particle.

    random   -> weighted pick
    sequence -> round-robin, so 3 body parts come out 1,2,3,1,2,3...
    exact    -> honour each entry's own "count" per burst, then round-robin
    """
    tex = em.get("textures") or []
    if not tex:
        return None
    mode = em.get("texture_mode", "random")
    if mode == "sequence":
        return tex[index % len(tex)]
    if mode == "exact":
        # Build a flat schedule from the per-entry counts once, then cycle.
        # Cache is keyed off the texture list's length so removing/adding a
        # texture in the editor invalidates the stale schedule instead of
        # leaving old indices that point past the end of the (now shorter)
        # texture list.
        sched = em.get("_tex_sched")
        if not sched or em.get("_tex_sched_len") != len(tex):
            sched = []
            for ti, t in enumerate(tex):
                sched.extend([ti] * max(1, int(t.get("count", 0) or 1)))
            em["_tex_sched"] = sched
            em["_tex_sched_len"] = len(tex)
        if not sched:
            return tex[index % len(tex)]
        return tex[sched[index % len(sched)] % len(tex)]
    total = sum(max(0.0, float(t.get("weight", 1.0))) for t in tex)
    if total <= 0:
        return tex[index % len(tex)]
    r = random.random() * total
    acc = 0.0
    for t in tex:
        acc += max(0.0, float(t.get("weight", 1.0)))
        if r <= acc:
            return t
    return tex[-1]

def get_particle_emitter(eid):
    return next((e for e in particle_emitters if e.get("id") == eid), None)



