# ── Built-in procedural textures for sprite presets ──────────────────────
_PE_TEX_MEMO = {}

def _pe_tex_dir():
    d = _cfg_path("emitters", "pe_textures")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    return d

def _pe_tex_painters():
    import math as _m
    painters = {}
    def _pt(name, fn):
        painters[name] = fn
    def petal():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pts = [(24, 4), (34, 16), (44, 26), (30, 44), (24, 38), (18, 44), (4, 26), (14, 16)]
        pygame.draw.polygon(s, (255, 255, 255, 255), pts)
        pygame.draw.aalines(s, (255, 255, 255, 160), True, pts)
        return s
    def feather():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pygame.draw.polygon(s, (255, 255, 255, 255), [(24, 4), (34, 20), (24, 44), (14, 20)])
        pygame.draw.line(s, (0, 0, 0, 0), (24, 8), (24, 40), 1)
        return s
    def leaf():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (255, 255, 255, 255), (12, 8, 24, 34))
        pygame.draw.line(s, (0, 0, 0, 0), (16, 40), (32, 40), 2)
        return s
    def star():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pts = [(24, 4), (28, 20), (44, 24), (28, 28), (24, 44), (20, 28), (4, 24), (20, 20)]
        pygame.draw.polygon(s, (255, 255, 255, 255), pts)
        return s
    def coin():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pygame.draw.circle(s, (255, 255, 255, 255), (24, 24), 20)
        pygame.draw.circle(s, (0, 0, 0, 0), (24, 24), 13)
        return s
    def rune():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pygame.draw.polygon(s, (255, 255, 255, 255), [(24, 6), (42, 24), (24, 42), (6, 24)])
        pygame.draw.polygon(s, (0, 0, 0, 0), [(24, 16), (32, 24), (24, 32), (16, 24)])
        return s
    def shard():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pygame.draw.polygon(s, (255, 255, 255, 255), [(24, 4), (42, 26), (30, 44), (14, 34)])
        return s
    def heart():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        pygame.draw.circle(s, (255, 255, 255, 255), (17, 18), 11)
        pygame.draw.circle(s, (255, 255, 255, 255), (31, 18), 11)
        pygame.draw.polygon(s, (255, 255, 255, 255), [(6, 22), (42, 22), (24, 44)])
        return s
    def puff():
        s = pygame.Surface((48, 48), pygame.SRCALPHA)
        for r, a in ((22, 70), (17, 90), (12, 120), (7, 170), (3, 230)):
            pygame.draw.circle(s, (255, 255, 255, a), (24, 24), r)
        return s
    _pt("petal", petal); _pt("feather", feather); _pt("leaf", leaf); _pt("star", star)
    _pt("coin", coin); _pt("rune", rune); _pt("shard", shard); _pt("heart", heart); _pt("puff", puff)
    return painters

def _pe_tex(name):
    """Absolute path to a built-in procedural texture (written once on disk)."""
    if name in _PE_TEX_MEMO:
        return _PE_TEX_MEMO[name]
    painters = _pe_tex_painters()
    fn = painters.get(name)
    if fn is None:
        return ""
    path = os.path.join(_pe_tex_dir(), name + ".png")
    try:
        if not os.path.isfile(path):
            pygame.image.save(fn(), path)
    except Exception:
        pass
    _PE_TEX_MEMO[name] = path
    return path

