_PE_PACK3_CATS = {}
for _pe_pn, _pe_pb, _pe_pc, _pe_po in _PE_PACK3:
    _base3 = _PE_PACK_TEMPLATES2.get(_pe_pb, _PE_PACK_TEMPLATES3.get(_pe_pb))
    _pe_d = dict(_base3)
    _pe_po = dict(_pe_po)
    if isinstance(_pe_po.get('sprite'), str) and _pe_po['sprite'].startswith('tex:'):
        _pe_po['sprite'] = _pe_tex(_pe_po['sprite'][4:])
    _pe_d.update(_pe_po)
    PE_PRESETS[_pe_pn] = _pe_d
    _PE_PACK3_CATS[_pe_pn] = _pe_pc

# The pack-2 helper templates below are what earlier presets spawn on
# landing / impact (sub_on_floor etc.). Registering them as real presets
# makes those transitions resolve -- and they are handy presets too.
for _ph3_name, _ph3_cat in (("puff_dust", "Effects"), ("sparkle_tw", "Effects"),
                            ("splash_pop", "Effects")):
    if _ph3_name not in PE_PRESETS and _ph3_name in _PE_PACK_TEMPLATES2:
        _ph3_d = dict(_PE_PACK_TEMPLATES2[_ph3_name])
        if isinstance(_ph3_d.get('sprite'), str) and _ph3_d['sprite'].startswith('tex:'):
            _ph3_d['sprite'] = _pe_tex(_ph3_d['sprite'][4:])
        PE_PRESETS[_ph3_name] = _ph3_d
        _PE_PACK3_CATS[_ph3_name] = _ph3_cat

# Register EVERY pack-2 template that any preset references as a spawn
# target (sub_on_floor / sub_on_death / sub_on_collide /
# sub_on_phase_end) as a real preset. Those are the "transition into
# other particles" targets -- if one is missing the spawn silently falls
# back to a default emitter instead of the authored effect.
for _st_key in ("sub_on_floor", "sub_on_death", "sub_on_collide", "sub_on_phase_end"):
    for _st_p in list(PE_PRESETS.values()):
        _st_name = str(_st_p.get(_st_key, "") or "")
        if not _st_name:
            continue
        if _st_name not in PE_PRESETS and _st_name in _PE_PACK_TEMPLATES2:
            _st_d = dict(_PE_PACK_TEMPLATES2[_st_name])
            if isinstance(_st_d.get('sprite'), str) and _st_d['sprite'].startswith('tex:'):
                _st_d['sprite'] = _pe_tex(_st_d['sprite'][4:])
            PE_PRESETS[_st_name] = _st_d
            _PE_PACK3_CATS.setdefault(_st_name, "Effects")


