def pe_preset_label(preset):
    raw = str(preset or "custom")
    if raw.startswith("custom:"):
        raw = raw[7:]
    return " ".join(raw.replace("_", " ").replace("-", " ").split()).title()

def pe_display_name(em):
    name = str(em.get("name", "") or "").strip()
    return pe_preset_label(em.get("preset")) if (not name or re.fullmatch(r"Emitter\s*\d+", name, re.I)) else name

def make_particle_emitter(wx=0.0, wy=0.0, preset=None, name=None):
    # Hard ceiling on live emitters. A blueprint that spawns one per frame
    # would otherwise grow the list without bound; refusing the spawn keeps
    # the scene responsive and surfaces the mistake as a toast.
    _cap = max(1, int(SETTINGS.get("pe_max_emitters", 64)))
    if len(particle_emitters) >= _cap:
        # Reclaim finished one-shots before giving up -- those are almost
        # always the culprit and are safe to drop.
        _dead = [e for e in particle_emitters
                 if e.get("_autokill") and not e.get("_particles")]
        for _d in _dead:
            particle_emitters.remove(_d)
        if len(particle_emitters) >= _cap:
            # Refuse the spawn. Returning an EXISTING emitter here was a bad
            # idea: callers immediately reconfigure what they get back, so a
            # waterfall spawning foam would overwrite itself with foam and
            # the original effect vanished. A detached throwaway satisfies
            # the caller without touching the live scene.
            pe_budget_note()
            _orphan = pe_default(name=name, wx=wx, wy=wy)
            if preset:
                pe_apply_preset(_orphan, preset)
            _orphan["enabled"] = False
            _orphan["emitting"] = False
            return _orphan
    em = pe_default(name=name, wx=wx, wy=wy)
    if preset:
        pe_apply_preset(em, preset)
        if not name:
            em["name"] = pe_preset_label(preset)
    pe_normalize(em)
    particle_emitters.append(em)
    return em

def pe_directional_launch_vector(emitter, direction):
    """Normalize an impact vector and apply optional preset-authored launch bias."""
    try:
        vec=pygame.Vector2(direction)
    except Exception:
        vec=pygame.Vector2(1,0)
    if vec.length_squared()<=1e-8:
        vec=pygame.Vector2(1,0)
    unit=vec.normalize();cfg=emitter if isinstance(emitter,dict) else {}
    forward=max(0.0,float(cfg.get("directional_forward_bias",1.0)))
    upward=max(0.0,float(cfg.get("directional_up_bias",0.0)))
    if upward>0.0:
        unit=pygame.Vector2(unit.x*forward,unit.y*forward-upward)
        # A directional slime/debris preset that promises an arc must always
        # leave the body upward, even when the supplied hit normal points down.
        unit.y=min(unit.y,-upward*.15)
    elif forward!=1.0:
        unit*=forward
    return unit.normalize() if unit.length_squared()>1e-8 else pygame.Vector2(1,0)


def make_particle_preset_instance(wx=0.0, wy=0.0, preset="sparks", scale=1.0):
    """Instantiate a Particle Creator preset verbatim.

    This is intentionally not particle_create(): no burst count, rate, speed,
    spread, renderer, or texture fields are synthesized or overridden. The
    saved preset is copied exactly, like placing that emitter from the
    Particle Creator tool into the scene. Only instance identity/position and
    the requested world scale are changed.
    """
    key = str(preset or "sparks")
    if key not in PE_PRESETS:
        # Accept the display name of a custom preset.
        low = key.lower().replace(" ", "_")
        key = next((k for k in PE_PRESETS if str(k).lower() == low or
                    str(k).lower().replace("custom:", "").replace(" ", "_") == low),
                   "sparks")
    em = pe_default(name=pe_preset_label(key), wx=float(wx), wy=float(wy))
    em.update(copy.deepcopy(PE_PRESETS[key]))
    em["preset"] = key
    em["wx"], em["wy"] = float(wx), float(wy)
    em["world_scale"] = float(scale or 1.0)
    em["_particles"] = []; em["_accum"] = 0.0; em["_age"] = 0.0
    em["_emit_count"] = 0; em["_fired"] = False
    # Runtime state is fresh, but authored lifetime mode is preserved.
    em["emitting"] = not bool(em.get("one_shot",False))
    pe_normalize(em)
    particle_emitters.append(em)
    return em

def remove_particle_emitter(eid):
    particle_emitters[:] = [e for e in particle_emitters if e.get("id") != eid]

# ── Scriptable emitter bindings ────────────────────────────────────────────
# A regular emitter is deliberately world-space by default. A binding only
# moves its SOURCE; local_space/follow_strength decide what already-born
# particles do. That distinction is the important part of a usable trail:
# source follows the hand, old sparks stay behind.
def _pe_binding_owner(ref):
    if isinstance(ref, dict):
        return ref
    name = str(ref or "")
    direct = next((c for c in characters if str(c.get("name", "")) == name), None)
    if direct is not None:
        return direct
    # Weapon-rig projectiles are NOT characters. Trail emitters attached to a
    # projectile resolve their owner here; newest same-named wins so a rapid
    # burst of identical projectiles still follows a real, live projectile.
    for p in reversed(_WEAPON_PROJECTILES):
        if p.get("alive", True) and str(p.get("name", "")) == name:
            return p
    return None

def pe_owner_alive(owner):
    """Is this character / weapon projectile still live in the scene?

    A despawned character (flag already set, list cull happens later) and a
    projectile whose update ended with alive=False must count as dead RIGHT
    AWAY, so emitters marked 'destroy with owner' are removed the same frame
    instead of lingering at their last position for a few more ticks."""
    if not isinstance(owner, dict):
        return False
    if owner.get("_despawned"):
        return False
    if owner.get("alive", True) is False:
        return False
    try:
        if float(owner.get("hp", 1)) <= 0:
            return False
    except (TypeError, ValueError):
        pass
    if any(c is owner for c in characters):
        return True
    return any(p is owner for p in _WEAPON_PROJECTILES)

def pe_binding_transform(binding):
    """Return (world_position, angle) for a persistent particle binding.

    `character` follows the body, `anchor` follows a rig position event, and
    `motion_event` follows the actual currently-playing F9 event geometry.
    Returning None is intentional: a temporarily missing anchor/clip holds
    the emitter at its last valid location rather than snapping to world 0.
    """
    if not isinstance(binding, dict):
        return None
    owner = _pe_binding_owner(binding.get("owner"))
    if not isinstance(owner, dict):
        return None
    kind = str(binding.get("type", "character") or "character").lower()
    try:
        if kind == "anchor":
            an = str(binding.get("anchor", "") or "")
            rig = owner.get("_weapon_rig", {}) or {}
            if not an or an not in (rig.get("anchors", {}) or {}):
                return None
            pos = pygame.Vector2(_weapon_anchor_world(owner, an))
            ang = float(_weapon_anchor_world_angle(owner, an))
        elif kind == "motion_event":
            clip_name = str(binding.get("clip", "") or "")
            event_name = str(binding.get("event", "") or "")
            inst = (owner.get("_motion_playing", {}) or {}).get(clip_name)
            clip = MOTION_CLIPS.get(clip_name) if clip_name else None
            if not isinstance(inst, dict) or not isinstance(clip, dict):
                return None
            ev = next((e for e in (clip.get("events") or [])
                       if str(e.get("name", "")) == event_name), None)
            if not isinstance(ev, dict):
                return None
            pos, ang = _motion_event_world(owner, inst, ev)
            pos = pygame.Vector2(pos)
            ang = float(ang)
        else:
            pos = pygame.Vector2(owner.get("pos", (0, 0)))
            ang = 0.0
    except Exception:
        return None
    try:
        off = binding.get("offset", [0.0, 0.0])
        ov = pygame.Vector2(float(off[0]), float(off[1]))
    except Exception:
        ov = pygame.Vector2()
    if binding.get("local_offset", True):
        ov = ov.rotate(ang)
    return pos + ov, ang

def pe_set_binding(em, kind="character", owner=None, anchor="", clip="", event="",
                   offset=(0.0, 0.0), local_offset=True, rotate=None):
    """Attach an emitter source to a body, rig position event, or motion event.
    Settings are JSON-safe and therefore persist with the authored emitter."""
    if not isinstance(em, dict):
        return None
    _owner_ref = owner if isinstance(owner, dict) else None
    if isinstance(owner, dict):
        owner = owner.get("name", "")
    try:
        ox, oy = float(offset[0]), float(offset[1])
    except Exception:
        ox, oy = 0.0, 0.0
    k = str(kind or "character").lower()
    if k not in ("character", "anchor", "motion_event"):
        return None
    em["binding"] = {
        "type": k, "owner": str(owner or ""), "anchor": str(anchor or ""),
        "clip": str(clip or ""), "event": str(event or ""),
        "offset": [ox, oy], "local_offset": bool(local_offset),
        "rotate": bool(k != "character" if rotate is None else rotate),
    }
    # Runtime-only direct owner reference. The serialized binding keeps just
    # the owner NAME (JSON-safe), but several projectiles/characters can share
    # one name. The live dict pins this emitter to the exact body it was
    # attached to; pe_update_binding prefers it while that owner is alive.
    # (Underscore key: never written to project files.)
    if _owner_ref is not None:
        em["_binding_ref"] = _owner_ref
    else:
        em.pop("_binding_ref", None)
    pe_update_binding(em)
    return em

def pe_clear_binding(em):
    if isinstance(em, dict):
        em["binding"] = None
        em["_binding_rotate"] = False
        em.pop("_binding_ref", None)
        return em
    return None

def pe_update_binding(em):
    """Refresh one emitter's source from its binding. Returns True on update."""
    if not isinstance(em, dict):
        return False
    binding = em.get("binding")
    # Legacy scripts used _follow. Support them as an un-serialized body
    # binding while all new nodes use the persistent public `binding` field.
    if not isinstance(binding, dict) and em.get("_follow"):
        binding = {"type": "character", "owner": em.get("_follow"),
                   "offset": [0.0, 0.0], "local_offset": True, "rotate": False}
    # Prefer the exact runtime owner dict while it is still alive: a
    # name-based lookup can only guess when several projectiles (or several
    # cloned characters) share one name.
    _ref = em.get("_binding_ref")
    if isinstance(_ref, dict) and isinstance(binding, dict):
        binding = dict(binding)
        binding["owner"] = _ref
    result = pe_binding_transform(binding)
    if result is None:
        return False
    pos, angle = result
    em["wx"], em["wy"] = float(pos.x), float(pos.y)
    em["_binding_angle"] = float(angle)
    em["_binding_rotate"] = bool((binding or {}).get("rotate", False))
    return True

def pe_apply_impulse(em, x=0.0, y=0.0):
    """Add a one-time velocity kick to all current particles in an emitter."""
    if not isinstance(em, dict):
        return 0
    try:
        ix, iy = float(x), float(y)
    except Exception:
        return 0
    n = 0
    for part in em.get("_particles", []) or []:
        try:
            part["vx"] = float(part.get("vx", 0.0)) + ix
            part["vy"] = float(part.get("vy", 0.0)) + iy
            n += 1
        except Exception:
            pass
    return n

# ── path helpers ──────────────────────────────────────────────────────────
def pe_path_points(em, samples_per_seg=10):
    """Resolve a path into a dense polyline, smoothing when asked.

    Catmull-Rom keeps the curve passing exactly through the points you drew,
    which is what makes hand-drawing a flame or a river feel predictable --
    a Bezier would pull away from the handles.
    """
    pts = [(float(p[0]), float(p[1])) for p in (em.get("path") or []) if len(p) >= 2]
    if len(pts) < 2:
        return pts
    if not em.get("path_smooth", True):
        return pts
    closed = bool(em.get("path_closed"))
    src = list(pts)
    if closed:
        src = [pts[-1]] + pts + [pts[0], pts[1]]
    else:
        src = [pts[0]] + pts + [pts[-1]]
    out = []
    n = max(2, int(samples_per_seg))
    for i in range(len(src) - 3):
        p0, p1, p2, p3 = src[i], src[i + 1], src[i + 2], src[i + 3]
        for s in range(n):
            t = s / float(n)
            t2, t3 = t * t, t * t * t
            out.append((
                0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t +
                       (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
                       (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
                0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t +
                       (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
                       (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3)))
    out.append(pts[0] if closed else pts[-1])
    return out

def pe_path_sample(em, t):
    """Point + tangent at normalised distance t along the path."""
    pts = pe_path_points(em)
    if len(pts) < 2:
        return (0.0, 0.0), (1.0, 0.0)
    segs = []
    total = 0.0
    for i in range(len(pts) - 1):
        dx, dy = pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]
        d = math.hypot(dx, dy)
        segs.append((d, pts[i], pts[i + 1]))
        total += d
    if total <= 0:
        return pts[0], (1.0, 0.0)
    want = max(0.0, min(1.0, float(t))) * total
    run = 0.0
    for d, a, b in segs:
        if run + d >= want or d <= 0:
            u = 0.0 if d <= 0 else (want - run) / d
            px = a[0] + (b[0] - a[0]) * u
            py = a[1] + (b[1] - a[1]) * u
            ln = max(1e-6, d)
            return (px, py), ((b[0] - a[0]) / ln, (b[1] - a[1]) / ln)
        run += d
    return pts[-1], (1.0, 0.0)

# ── noise (cheap, deterministic, no numpy dependency) ─────────────────────
def _pe_noise(x, y, t):
    """Smooth-ish pseudo noise in -1..1. Sines are plenty for turbulence and
    cost far less than real Perlin at these particle counts."""
    return (math.sin(x * 1.7 + t * 1.3) * math.cos(y * 1.3 - t * 0.7) +
            math.sin((x + y) * 0.9 - t * 1.9) * 0.5) / 1.5

def _pe_curve(t, kind):
    try:
        return _ns_ease(max(0.0, min(1.0, t)), kind or "linear")
    except Exception:
        return max(0.0, min(1.0, t))

def _pe_lerp_color(a, b, t):
    return (int(a[0] + (b[0] - a[0]) * t),
            int(a[1] + (b[1] - a[1]) * t),
            int(a[2] + (b[2] - a[2]) * t))

def pe_color_at(em, t):
    """Colour ramp, 2 or 3 stops."""
    c0 = em.get("color_start", [255, 255, 255])
    c1 = em.get("color_end", [255, 255, 255])
    cm = em.get("color_mid")
    if cm:
        if t < 0.5:
            return _pe_lerp_color(c0, cm, t * 2.0)
        return _pe_lerp_color(cm, c1, (t - 0.5) * 2.0)
    return _pe_lerp_color(c0, c1, t)

def _pe_spawn_origin(em):
    """Pick a spawn point (emitter-relative) and an outward normal."""
    shape = em.get("shape", "point")
    if shape == "circle":
        r = float(em.get("radius", 40)) * math.sqrt(random.random())
        a = random.uniform(0, math.tau)
        return (math.cos(a) * r, math.sin(a) * r), (math.cos(a), math.sin(a))
    if shape == "ring":
        ri = float(em.get("inner_radius", 0))
        ro = max(ri, float(em.get("radius", 40)))
        r = random.uniform(ri, ro)
        a = random.uniform(0, math.tau)
        return (math.cos(a) * r, math.sin(a) * r), (math.cos(a), math.sin(a))
    if shape == "rect":
        w2 = float(em.get("rect_w", 100)) / 2.0
        h2 = float(em.get("rect_h", 40)) / 2.0
        return (random.uniform(-w2, w2), random.uniform(-h2, h2)), (0.0, -1.0)
    if shape == "line":
        ln = float(em.get("line_len", 100))
        ang = math.radians(float(em.get("line_angle", 0.0)))
        u = random.uniform(-0.5, 0.5) * ln
        return (math.cos(ang) * u, math.sin(ang) * u), (-math.sin(ang), math.cos(ang))
    if shape == "arc":
        ro = max(0.0, float(em.get("radius", 40)))
        arc = math.radians(float(em.get("spawn_arc", 180) or 180))
        off = math.radians(float(em.get("spawn_arc_offset", -90)))
        a = off + random.uniform(-arc * .5, arc * .5)
        return (math.cos(a) * ro, math.sin(a) * ro), (math.cos(a), math.sin(a))
    if shape == "cone":
        length = max(1.0, float(em.get("line_len", 120)))
        half = math.radians(max(0.1, abs(float(em.get("spawn_arc", 45) or 45))) * .5)
        u = math.sqrt(random.random()) * length
        a = math.radians(float(em.get("line_angle", -90))) + random.uniform(-half, half)
        return (math.cos(a) * u, math.sin(a) * u), (math.cos(a), math.sin(a))
    if shape == "spiral":
        u = random.random(); turns = float(em.get("spawn_spiral_turns", 2) or 2)
        ro = float(em.get("spawn_spiral_radius", em.get("radius", 80)) or 80)
        a = math.radians(float(em.get("spawn_arc_offset", 0))) + u * math.tau * turns
        r = u * ro
        return (math.cos(a) * r, math.sin(a) * r), (math.cos(a), math.sin(a))
    if shape == "hemisphere":
        ro = max(0.0, float(em.get("radius", 40)))
        a = random.uniform(math.pi, math.tau)
        r = ro * math.sqrt(random.random())
        return (math.cos(a) * r, math.sin(a) * r), (math.cos(a), math.sin(a))
    if shape == "path":
        (px, py), (tx, ty) = pe_path_sample(em, random.random())
        j = float(em.get("path_jitter", 0.0))
        if j:
            px += random.uniform(-j, j)
            py += random.uniform(-j, j)
        return (px, py), (-ty, tx)      # normal = perpendicular to tangent
    return (0.0, 0.0), (0.0, -1.0)

def pe_world_scale(em):
    try:
        return max(0.05, float(em.get("world_scale", 1.0) or 1.0))
    except Exception:
        return 1.0

def pe_emit_one(em, now, index=0):
    """Create one particle in emitter-local terms."""
    (ox, oy), (nx, ny) = _pe_spawn_origin(em)
    # Designer spawn transform. Every term is zero/identity by default.
    _sr = math.radians(float(em.get("spawn_rotation", 0.0)))
    _cs, _ss = math.cos(_sr), math.sin(_sr)
    ox, oy = ox * float(em.get("spawn_scale_x", 1.0)), oy * float(em.get("spawn_scale_y", 1.0))
    ox, oy = ox * _cs - oy * _ss, ox * _ss + oy * _cs
    if em.get("spawn_mirror_x") and random.random() < float(em.get("spawn_mirror_x", 0)): ox = -ox
    if em.get("spawn_mirror_y") and random.random() < float(em.get("spawn_mirror_y", 0)): oy = -oy
    _sn = float(em.get("spawn_noise", 0.0))
    if _sn: ox += random.uniform(-_sn, _sn); oy += random.uniform(-_sn, _sn)
    ox += float(em.get("spawn_bias_x", 0.0)); oy += float(em.get("spawn_bias_y", 0.0))
    _snap = float(em.get("spawn_grid_snap", 0.0))
    if _snap > .01: ox = round(ox/_snap)*_snap; oy = round(oy/_snap)*_snap
    _ws = pe_world_scale(em)
    if _ws != 1.0:
        ox *= _ws
        oy *= _ws
    if em.get("align_to_shape") and (nx or ny):
        base = math.degrees(math.atan2(ny, nx))
    else:
        base = float(em.get("direction", -90.0))
    # Attached emitters can opt into the source anchor/event rotation without
    # mutating their authored direction. This makes a hand/muzzle trail turn
    # with the character while the same preset still works in world space.
    if em.get("_binding_rotate", False):
        base += float(em.get("_binding_angle", 0.0))
    _spread = float(em.get("spread", 0.0)) + float(em.get("launch_fan", 0.0)) * .5
    base += float(em.get("launch_index_spread", 0.0)) * ((index * .61803398875) % 1.0 - .5)
    ang = math.radians(base + random.uniform(-1, 1) * _spread)
    spd = random.uniform(float(em.get("speed_min", 0)),
                         float(em.get("speed_max", 0))) * _ws
    _sw = float(em.get("launch_speed_wave", 0.0))
    if _sw: spd += math.sin(index * float(em.get("launch_speed_wave_freq", 1.0))) * _sw
    if random.random() < float(em.get("launch_reverse_chance", 0.0)): spd = -spd
    _lmin=float(em.get("life_min",1));_lmax=float(em.get("life_max",1));_infinite_life=max(_lmin,_lmax)<=0.0
    life = 1.0 if _infinite_life else max(0.02, random.uniform(min(_lmin,_lmax),max(_lmin,_lmax)))
    p = {
        "x": ox, "y": oy,
        "vx": math.cos(ang) * spd, "vy": math.sin(ang) * spd,
        "life": life, "max_life": life, "age": 0.0, "infinite_life": _infinite_life,
        "seed": random.random() * 1000.0,
        "_bob_ph": random.random() * math.tau * max(0.0, min(1.0, float(em.get("bob_phase_rnd", 1.0)))),
        "_bob_last": 0.0,
        "_ph_idx": 0,              # phase-chain stage
        "_ph_t": 0.0,              # seconds inside the current stage
        "rot": random.uniform(0, 360),
        "spin": random.uniform(float(em.get("spin_min", 0)), float(em.get("spin_max", 0))),
        "t": 0.0,
        "px": ox, "py": oy,          # previous position, for streaks
    }
    p["vx"] += float(em.get("launch_side_bias", 0.0)) + float(em.get("launch_impulse_x", 0.0))
    p["vy"] -= float(em.get("launch_up_bias", 0.0)); p["vy"] += float(em.get("launch_impulse_y", 0.0))
    _vl = float(em.get("launch_velocity_limit", 0.0))
    if _vl > 0:
        _vm = math.hypot(p["vx"], p["vy"])
        if _vm > _vl: p["vx"] *= _vl/_vm; p["vy"] *= _vl/_vm
    if em.get("anim_random_start"):
        p["anim_offset"] = random.random() * max(.001, sum(max(0.0,float(x)) for x in (em.get("anim_frame_holds") or [])))
    # Per-particle texture (the "3 body parts" case) and size variance.
    tx = pe_pick_texture(em, index)
    if tx is not None:
        p["tex"] = tx.get("sprite")
        p["tex_scale"] = float(tx.get("scale", 1.0))
        p["tex_opacity"] = max(0.0,min(1.0,float(tx.get("opacity",1.0))))
        if tx.get("tint"):
            p["tint"] = list(tx["tint"])
        if tx.get("spin") is not None:
            p["spin"] = float(tx["spin"])
    sj = float(em.get("size_jitter", 0.0))
    if sj > 0:
        p["sz_mul"] = max(0.05, 1.0 + random.uniform(-sj, sj))
    # Carry some of the emitter's motion into the particle's launch
    # velocity -- a torch swung sideways throws its sparks sideways.
    iv = float(em.get("inherit_velocity", 0.0))
    if iv:
        p["vx"] += float(em.get("_vx", 0.0)) * iv
        p["vy"] += float(em.get("_vy", 0.0)) * iv
    return p

def pe_burst(em, count=None):
    """Fire a manual burst -- also what one-shot emitters use."""
    if em is None:
        return 0
    n = int(count if count is not None else em.get("burst", 20))
    n = max(0, min(n, int(em.get("max_particles", 400))))
    # Scene-wide budget beats the per-emitter cap. Particle Creator clones are
    # detached and capped separately, so a full live scene cannot blank its UI.
    _room=int(em.get("max_particles",400)) if em.get("_preview_isolated") else pe_budget_room()
    if n > _room:
        n = _room
        pe_budget_note()
    parts = em.setdefault("_particles", [])
    now = time.time()
    base = int(em.get("_emit_count", 0))
    for i in range(n):
        if len(parts) >= int(em.get("max_particles", 400)):
            break
        parts.append(pe_emit_one(em, now, base + i))
    em["_emit_count"] = base + n
    return n

def pe_replay_burst(em, clear_existing=True):
    """Replay a burst even when infinite/live particles occupy the cap."""
    if not isinstance(em,dict):return 0
    if clear_existing:
        em["_particles"]=[];em["_accum"]=0.0
        # Manual UI replay happens between simulation ticks; refresh the cached
        # scene budget immediately so removed infinite particles free capacity.
        pe_budget_refresh()
    em["_age"]=0.0;em.pop("_fired",None)
    n=pe_burst(em,None)
    em["_fired"]=True
    if em.get("one_shot"):em["emitting"]=False
    return n

def pe_restart_emitter(em):
    """Hard restart; infinite particles are explicitly destroyed first."""
    if not isinstance(em,dict):return 0
    em["_particles"]=[];em["_age"]=0.0;em["_accum"]=0.0;em["_emit_count"]=0;em.pop("_fired",None)
    if em.get("one_shot") or float(em.get("rate",0.0))<=0:
        return pe_replay_burst(em,clear_existing=False)
    em["emitting"]=True
    return 0

def _pe_invalidate_preview_runtime():
    modal["_pe_live_preview_em"]=None;modal["_pe_preview_em"]=None;modal["_pe_fit_key"]=None;modal["_pe_fit_bounds"]=None


def pe_tick(em, dt, now):
    """Advance one emitter: spawn, integrate forces, retire dead particles."""
    if not em.get("enabled", True):
        return
    parts = em.setdefault("_particles", [])
    maxp = int(em.get("max_particles", 400))

    # ── Emitter motion ────────────────────────────────────────────────
    # Particle positions are stored RELATIVE to the emitter, so when the
    # emitter moves the whole cloud teleports with it for free. That reads
    # as "glued on" and is almost never what you want, so by default we
    # counter-translate every live particle by the emitter's movement,
    # leaving them behind in world space. local_space=True skips the
    # counter-translation and restores the glued-on behaviour deliberately.
    _wx, _wy = float(em.get("wx", 0.0)), float(em.get("wy", 0.0))
    _pwx, _pwy = em.get("_pwx"), em.get("_pwy")
    if _pwx is None:
        _pwx, _pwy = _wx, _wy
    _mdx, _mdy = _wx - _pwx, _wy - _pwy
    em["_pwx"], em["_pwy"] = _wx, _wy
    _manual_drag = bool(em.get("_manual_dragging", False))
    if dt > 0.0001:
        # Keep the original dynamic drag behaviour: existing particles still
        # counter-translate (or follow by follow_strength) and new particles
        # can inherit motion. Mouse events can arrive in very large bursts,
        # though, so clamp and smooth only the *derived velocity*, never the
        # actual dragged position. That removes the fighting at fast cursor
        # speeds without making the effect feel glued/stiff.
        _nvx, _nvy = _mdx / dt, _mdy / dt
        _vlim = 650.0 if _manual_drag else 4000.0
        _mag = math.hypot(_nvx, _nvy)
        if _mag > _vlim:
            _nvx *= _vlim / _mag
            _nvy *= _vlim / _mag
        _blend = 0.14 if _manual_drag else 0.4
        em["_vx"] = float(em.get("_vx", 0.0)) * (1.0 - _blend) + _nvx * _blend
        em["_vy"] = float(em.get("_vy", 0.0)) * (1.0 - _blend) + _nvy * _blend

    # Keep normal world-space/follow-strength behaviour even during a manual
    # drag. Only the noisy velocity estimate above is stabilized.
    if (_mdx or _mdy) and parts and not em.get("local_space"):
        _fs = max(0.0, min(1.0, float(em.get("follow_strength", 0.0))))
        # A fast hand drag can cross dozens of world pixels in one event. At
        # that speed a full counter-translation makes the whole cloud tear
        # apart in a single frame. Add an adaptive follow only for manual
        # drags: slow/short moves retain the authored follow_strength exactly;
        # rapid moves carry part of the cloud with the handle, preserving a
        # lively trail without the visible break/jitter.
        _adaptive_follow = 0.0
        if _manual_drag and dt > 0.0001:
            _drag_speed = math.hypot(_mdx, _mdy) / dt
            _adaptive_follow = max(0.0, min(0.72, (_drag_speed - 420.0) / 1450.0))
        _effective_follow = _fs + (1.0 - _fs) * _adaptive_follow
        # follow_strength blends between "left behind" (0) and "dragged
        # along" (1) for particles already in flight.
        _keep = 1.0 - _effective_follow
        if _keep > 0.0:
            for _p in parts:
                _p["x"] -= _mdx * _keep
                _p["y"] -= _mdy * _keep
                _p["px"] -= _mdx * _keep
                _p["py"] -= _mdy * _keep

    # -- emission --
    if em.get("emitting", True):
        em["_age"] = float(em.get("_age", 0.0)) + dt
        dur = float(em.get("duration", 0.0))
        if dur > 0 and em["_age"] >= dur:
            em["emitting"] = False
        elif em.get("one_shot"):
            if not em.get("_fired"):
                pe_burst(em)
                em["_fired"] = True
                em["emitting"] = False
        else:
            rate = max(0.0, float(em.get("rate", 0.0))) * _PE_BUDGET["throttle"]
            if rate > 0:
                em["_accum"] = float(em.get("_accum", 0.0)) + rate * dt
                # Explosiveness clumps the same budget into periodic bursts
                # instead of a smooth stream.
                ex = max(0.0, min(1.0, float(em.get("explosiveness", 0.0))))
                thresh = 1.0 + ex * max(1.0, rate * 0.25)
                while (em["_accum"] >= thresh and len(parts) < maxp
                       and (em.get("_preview_isolated") or pe_budget_room()>0)):
                    em["_accum"] -= thresh
                    for _ in range(max(1, int(thresh))):
                        if len(parts) >= maxp:
                            break
                        _ei = int(em.get("_emit_count", 0))
                        parts.append(pe_emit_one(em, now, _ei))
                        em["_emit_count"] = _ei + 1

    if not parts:
        return

    _ws = pe_world_scale(em)
    # `force_x/y` is the visual-scripter's persistent force channel. Keep it
    # separate from gravity in the data so a graph can change one without
    # silently overwriting the other.
    _linger = bool(em.get("linger", False))
    gx = float(em.get("gravity_x", 0)) * _ws
    gy = float(em.get("gravity_y", 0)) * _ws
    fx = float(em.get("force_x", 0)) * _ws
    fy = float(em.get("force_y", 0)) * _ws
    damp = max(0.0, float(em.get("damping", 0.0)))
    _bobA = float(em.get("bob_amp", 0.0)) * _ws
    _bobF = max(0.05, float(em.get("bob_speed", 1.2)))
    ar = float(em.get("accel_radial", 0.0)) * _ws
    at = float(em.get("accel_tangent", 0.0)) * _ws
    orbit = math.radians(float(em.get("orbit", 0.0))) * dt
    turb = float(em.get("turbulence", 0.0)) * _ws
    tsc = float(em.get("turb_scale", 0.01))
    tsp = float(em.get("turb_speed", 1.0))
    wx = float(em.get("wind_x", 0.0)) * _ws
    wy = float(em.get("wind_y", 0.0)) * _ws
    gust = float(em.get("wind_gust", 0.0)) * _ws
    gfreq = float(em.get("wind_freq", 1.0))
