    atts = em.get("attractors") or []
    _trail_n = max(0, int(em.get("trail", 0)))
    follow = em.get("shape") == "path" and em.get("path_follow")
    coll = em.get("collide_walls")
    _pw = em.get("_preview_walls")
    if coll and isinstance(_pw, (list, tuple)) and len(_pw) == 4:
        box = pygame.Rect(int(_pw[0]), int(_pw[1]),
                          max(1, int(_pw[2] - _pw[0])), max(1, int(_pw[3] - _pw[1])))
    else:
        box = get_box_rect_world() if coll else None
    bounce = float(em.get("bounce", 0.4))
    floor_y = em.get("floor_y")

    _subs = []          # (preset, world_x, world_y) queued for after the loop
    _sub_death = str(em.get("sub_on_death", "") or "")
    _sub_coll = str(em.get("sub_on_collide", "") or "")
    _sub_floor = str(em.get("sub_on_floor", "") or "")
    _sub_phase_end = str(em.get("sub_on_phase_end", "") or "")
    _phases = em.get("phases") or []
    _fo = em.get("floor_offset")
    _floor_off = None if _fo is None else float(_fo) * _ws
    _floor_b = float(em.get("floor_bounce", 0.3))
    _sub_ch = max(0.0, min(1.0, float(em.get("sub_chance", 1.0))))

    # Particle pickup/seek behavior. The target may be a live character dict
    # or a fixed world Vector. Touches are aggregated so a 100-particle burst
