def scene_blocks_world_rect(layer, cx, cy):
    ts = max(4, int(layer.get("tile_size", 32)))
    return pygame.Rect(cx * ts, cy * ts, ts, ts)

def scene_blocks_solid_rects():
    out = []
    for layer in scene_blocks:
        if not layer.get("solid", True) or not layer.get("visible", True):
            continue
        ts = max(4, int(layer.get("tile_size", 32)))
        for key in layer.get("tiles", {}):
            try:
                cx, cy = key.split(",")
                cx, cy = int(cx), int(cy)
            except Exception:
                continue
            out.append(pygame.Rect(cx * ts, cy * ts, ts, ts))
    return out

# ── tileset manifests (exported by the sheet extractor's Tileset mode) ──
def _scene_blocks_tilesets(refresh=False):
    global _SCENE_BLOCK_TILESETS
    if _SCENE_BLOCK_TILESETS is None or refresh:
        out = {}
        base = IMPORTED_SPRITES_DIR
        if os.path.isdir(base):
            for root, _dirs, files in os.walk(base):
                for fn in files:
                    if fn.lower().endswith(".json"):
                        try:
                            with open(os.path.join(root, fn), "r", encoding="utf-8") as fh:
                                d = json.load(fh)
                            if (isinstance(d, dict) and d.get("type") == "tileset"
                                    and isinstance(d.get("groups"), dict)):
                                name = str(d.get("name") or os.path.basename(root) or "tileset")
                                d["name"] = name
                                d["folder"] = os.path.relpath(root, SPRITES_DIR).replace(os.sep, "/")
                                out[name] = d
                        except Exception:
                            continue
        _SCENE_BLOCK_TILESETS = out
    return _SCENE_BLOCK_TILESETS

def _scene_blocks_tileset_manifest(name):
    if not name:
        return None
    try:
        return _scene_blocks_tilesets().get(str(name))
    except Exception:
        return None

def _scene_blocks_tile_rel(layer, info):
    g = str(info.get("g", ""))
    if not g:
        return None
    mf = _scene_blocks_tileset_manifest(layer.get("tileset", ""))
    if mf:
        paths = (mf.get("groups") or {}).get(g)
        if paths:
            v = int(info.get("v", 4))
            if 0 <= v < len(paths):
                return paths[v]
    return g

def _scene_blocks_tile_surface(rel, px, alpha=255):
    key = (str(rel), int(px), int(alpha))
    s = _SP_TILE_CACHE.get(key)
    if s is None:
        img = load_sprite_asset(rel)
        if img is None:
            return None
        try:
            if px == img.get_width() and px == img.get_height() and alpha == 255:
                s = img
            else:
                method = (pygame.transform.scale if (px > img.get_width() or px > img.get_height()
                                                     or _sprite_is_pixelart(img))
                          else pygame.transform.smoothscale)
                s = method(img, (px, px))
                if alpha < 255:
                    s = s.copy()
                    s.set_alpha(int(alpha))
        except Exception:
            s = img
        _SP_TILE_CACHE[key] = s
        if len(_SP_TILE_CACHE) > 8192:
            _SP_TILE_CACHE.pop(next(iter(_SP_TILE_CACHE)))
    return s

def _sp_render_layers(surface, to_scr, zoom, show_solid=False):
    """Draw every visible block layer. `to_scr(wx, wy)` maps world -> screen;
    `zoom` is the world-per-pixel scale used to size the tiles."""
    if not scene_blocks:
        return
    sw, sh = surface.get_size()
    for layer in scene_blocks:
        if not layer.get("visible", True):
            continue
        ts = max(4, int(layer.get("tile_size", 32)))
        op = max(0, min(255, int(layer.get("opacity", 255))))
        solid = bool(layer.get("solid", True))
        px = max(1, int(round(ts * zoom)))
        tiles = layer.get("tiles", {})
        for key, info in tiles.items():
            try:
                cx, cy = key.split(",")
                cx, cy = int(cx), int(cy)
            except Exception:
                continue
            wx, wy = cx * ts, cy * ts
            sx, sy = to_scr(wx, wy)
            if sx > sw or sy > sh or sx + px < 0 or sy + px < 0:
                continue
            rel = _scene_blocks_tile_rel(layer, info)
            if not rel:
                continue
            img = _scene_blocks_tile_surface(rel, px, op)
            if img is None:
                continue
            surface.blit(img, (int(sx), int(sy)))
            if show_solid and solid:
                veil = pygame.Surface((img.get_width(), img.get_height()), pygame.SRCALPHA)
                veil.fill((255, 120, 80, 26))
                surface.blit(veil, (int(sx), int(sy)))
                pygame.draw.rect(surface, (255, 140, 100, 90),
                                 pygame.Rect(int(sx), int(sy), img.get_width(), img.get_height()), 1)

