                elapsed = now_time - c.get("bounce_start_time", now_time)
                duration = float(c.get("bounce_duration", 0.5))
                if elapsed >= duration:
                    c["bounce_active"] = False
                else:
                    t = elapsed / duration
                    decay = math.exp(-t * float(c.get("bounce_decay", 5.0)))
                    freq = float(c.get("bounce_frequency", 10.0))
                    osc = math.sin(t * freq * 2.0 * math.pi)
                    bounce_sx = 1.0 + float(c.get("bounce_amp_x", 0.3)) * osc * decay
                    bounce_sy = 1.0 + float(c.get("bounce_amp_y", -0.3)) * osc * decay

