        target = effect.get("target")
        position = target.get("pos") if isinstance(target, dict) else effect.get("pos")
        sp = world_to_screen_for(position, w, h)
        definition = ANIMATION_LIBRARY.get(effect.get("animation"), {})
        paths = animation_frame_paths(definition)
        if not paths:
            # Visible procedural fallback: damage/effects still read clearly
            # even before the user creates an Animation Library clip.
            effect_name = str(effect.get("animation", "effect")).lower()
            if "lightning" in effect_name:
                bolt = [(sp.x, sp.y - 130 * camera["zoom"])]
                segments = 7
                for segment in range(1, segments):
                    progress = segment / segments
                    jitter = math.sin(effect.get("started", 0) * 31 + segment * 4.7) * 18
                    bolt.append((sp.x + jitter * camera["zoom"],
                                 sp.y - (130 * (1-progress)) * camera["zoom"]))
