        durations = animation_frame_durations(definition)
        total = max(.02, sum(durations))
        elapsed = time.time() - effect.get("started", time.time())
        local = elapsed % total if effect.get("loop") else min(elapsed, total-.001)
        acc = 0.0; frame_index = len(paths)-1
