        _fn_bold = bool(en.get("font_bold", True))
        _lbl_col = tuple(en.get("label_color", en.get("text_color", [240,240,246])))
        _val_col = tuple(en.get("value_color", en.get("text_color", [255,255,255])))
        _vfmt    = str(en.get("value_format", "value/max"))  # value/max | percent | value | value/max_percent
        _auto_sz = max(6, _fn_size) if _fn_size > 0 else max(6, _bh - 2)
