        _ch     = max(4, int(en.get("cell_h", 40) * _scl))
        _col    = tuple(en.get("color", [80,80,100]))
        _thk    = max(1, int(en.get("thickness", 1) * _scl))
        _ox     = int(sp.x - (_cols*_cw)//2)
        _oy     = int(sp.y - (_rows*_ch)//2)
        # Filled cells
        for (_c, _r), _fc in en.get("fill_data", {}).items():
            _fr = pygame.Rect(_ox + _c*_cw, _oy + _r*_ch, _cw, _ch)
            pygame.draw.rect(surface, tuple(_fc)[:3], _fr)
