        for col_i in range(_cols+1):
            pygame.draw.line(surface, _col, (_ox+col_i*_cw, _oy), (_ox+col_i*_cw, _oy+_rows*_ch), _thk)
        for row_i in range(_rows+1):
            pygame.draw.line(surface, _col, (_ox, _oy+row_i*_ch), (_ox+_cols*_cw, _oy+row_i*_ch), _thk)
        en["_rect"] = pygame.Rect(_ox, _oy, _cols*_cw, _rows*_ch)

