            _nx, _ny = _dx/_ln, _dy/_ln
            _ar = max(6, _thk*3)
            _perp = (-_ny*_ar*0.5, _nx*_ar*0.5)
            _apt = [(int(sp2.x), int(sp2.y)),
                    (int(sp2.x - _nx*_ar + _perp[0]), int(sp2.y - _ny*_ar + _perp[1])),
                    (int(sp2.x - _nx*_ar - _perp[0]), int(sp2.y - _ny*_ar - _perp[1]))]
            pygame.draw.polygon(surface, _col, _apt)
