def _scene_parallax_pos(item, world_pos, w, h) -> pygame.Vector2:
    """World -> screen for a scene node, honouring parallax_x / parallax_y.

    0.0 = the node holds still on screen (a far background plate),
    1.0 = the node moves with the world exactly like everything else,
    >1.0 = the node moves faster than the world (foreground plate).

    This is the single implementation shared by external nodes, scene text
    and scene images so all three parallax identically.
    """
    try:
        _px, _py = scene_effective_parallax(item)
    except Exception:
        _px = _py = 1.0
    _world_sp = world_to_screen_for(world_pos, w, h)
    if _px == 1.0 and _py == 1.0:
        return _world_sp
    _cam_z = max(0.001, float(camera.get("zoom", 1.0)))
    # Where the point would land if the camera never moved (parallax = 0).
    _fixed_x = w / 2 + world_pos.x * _cam_z
    _fixed_y = h / 2 + world_pos.y * _cam_z
    return pygame.Vector2(
        _fixed_x + (_world_sp.x - _fixed_x) * _px,
        _fixed_y + (_world_sp.y - _fixed_y) * _py,
    )

_EN_COMPOSITE_POOL={"surf":None,"size":None}
_EN_DIRTY_SAFE_KINDS=frozenset(("text_label","rect_box","progress_bar","custom_progress_bar","counter","timer","gradient","grid","circle","line","wall","image_node"))


def _en_composite_surface(w,h):
    """One reusable alpha surface replaces a full-window allocation per node.

    Self-healing: pygame can convert a surface in-place to a non-alpha format
    (for example a special_flags blend blit converts its SOURCE to match the
    destination). If the pooled layer ever loses its SRCALPHA flag, opacity
    blending silently breaks for every node that draws after it (symptoms:
    a node whose opacity slider appears to do nothing). Recreate the layer
    the moment its alpha channel is gone."""
    size=(int(w),int(h));layer=_EN_COMPOSITE_POOL.get("surf")
    if (layer is None or _EN_COMPOSITE_POOL.get("size")!=size
            or not (layer.get_flags() & pygame.SRCALPHA)):
        # Note: never call set_alpha(None) to "reset" this layer. In pygame-ce
        # set_alpha(None) CONVERTS an SRCALPHA surface to a plain RGB surface,
        # permanently destroying its alpha channel -- which silently broke the
        # opacity blend for every node drawn after the first composite frame
        # (e.g. a Timer whose opacity slider appeared to do nothing).
        layer=pygame.Surface(size,pygame.SRCALPHA);_EN_COMPOSITE_POOL.update({"surf":layer,"size":size})
    else:
        layer.set_alpha(255);layer.set_clip(None);layer.fill((0,0,0,0))
    return layer


def _en_seal_bar_alpha(layer, en, w, h, rect=None):
    """Repair the alpha channel of a textured bar drawn onto the SRCALPHA
    composite layer.

    Texture layers (frame/fill sprites) are blitted over the opaque body, and
    a blit writes the SOURCE's per-pixel alpha into the destination. On the
    plain screen surface that is invisible (the screen has no alpha channel),
    but on the SRCALPHA composite layer a transparent frame leaves bar pixels
    with alpha 0 -- so when the layer is blitted with set_alpha (occlusion
    fade, master opacity, blend modes) the whole bar silently vanishes.

    Repair rule (content-aware, so genuinely empty pixels NEVER become black
    boxes): only pixels that still carry visible colour but lost their alpha
    to a transparent texture blit are sealed back to 255. Empty pixels stay
    transparent, and any existing partial alpha (antialiased edges) keeps its
    value.

    Performance: the repair is limited to the bar's own screen rect (a tiny
    subsurface of the composite layer). The previous full-window numpy pass
    cost ~120 ms per fading bar per frame; the rect-sized version is
    sub-millisecond. Solid-color bars (no textures) skip the scan entirely."""
    try:
        r = rect if isinstance(rect, pygame.Rect) else en.get("_rect")
        if not isinstance(r, pygame.Rect) or r.width <= 0 or r.height <= 0:
            return
        r = r.clip(pygame.Rect(0, 0, int(w), int(h)))
        if r.width <= 0 or r.height <= 0:
            return
        # Solid-color bars are drawn with full alpha everywhere; only textured
        # bars can lose alpha to transparent texture blits.
        try:
            _has_tex = bool(en.get("bg_l_path") or en.get("bg_m_path") or en.get("bg_r_path")
                            or en.get("bg_path") or en.get("fill_path") or en.get("fill_m_path")
                            or en.get("frame_path") or en.get("aesthetic_sprites"))
            if not _has_tex:
                return
        except Exception:
            pass
        _sub = layer.subsurface(r)
        try:
            import numpy as _np
            _rgb = pygame.surfarray.array3d(_sub)
            _content = _np.any(_rgb != 0, axis=2)
            _alphas = pygame.surfarray.pixels_alpha(_sub)
            _alphas[_content & (_alphas == 0)] = 255
            del _alphas
        except Exception:
            # numpy-free fallback: scan the bar rect pixel by pixel.
            for _yy in range(r.height):
                for _xx in range(r.width):
                    _c = _sub.get_at((_xx, _yy))
                    if _c.a == 0 and (_c.r or _c.g or _c.b):
                        _sub.set_at((_xx, _yy), (_c.r, _c.g, _c.b, 255))
    except Exception:
        pass


def _en_bar_layer_signature(en, clip=None):
    """Cheap fingerprint of everything that changes how a bar's composited
    layer LOOKS. Runtime fade values are excluded (opacity is applied as
    surface alpha at blit time, not baked into the layer)."""
    try:
        _skip = {"_occlusion_fade_val", "_occlusion_fade_target", "_occl_layer_cache"}
        _d = {k: v for k, v in en.items() if k not in _skip}
        _sig = json.dumps(_d, sort_keys=True, default=str) + "|clip=" + str(clip)
        # Time-driven decorations (aesthetic blink rules) are not in the dict;
        # bucket them coarsely so cached bars re-render only a few times a
        # second instead of every frame.
        if en.get("aesthetic_sprites"):
            _sig += "|t=%d" % int(time.time() * 8)
        return _sig
    except Exception:
        return None


def _en_draw(surface,en,w,h,live):
    """Draw an external node."""
    op=_scene_opacity_255(en)
    try:
        if en.get("occlusion_fade_enabled", False):
            _of = float(en.get("_occlusion_fade_val", 1.0) or 1.0)
            if _of < 0.999:
                op = max(0, min(255, int(round(op * _of))))
    except Exception:
        pass
    # Virtual-camera preview renders offset en["_rect"] to the preview frame's
    # SCREEN position (for gizmo hit-tests). The composite layer math below
    # needs the rect in LAYER coordinates -- un-offset it here.
    _preview_rect_shift = False
    try:
        _preview_rect_shift = bool(virtual_camera.get("preview") and surface is not screen and not _is_export_render)
    except Exception:
        pass
    def _layer_rect():
        try:
            _r = en.get("_rect")
            if _preview_rect_shift and isinstance(_r, pygame.Rect):
                _vf = _virtual_camera_display_frame()
                return _r.move(-_vf.x, -_vf.y)
            return _r
        except Exception:
            return en.get("_rect")
    blend=scene_effective_blend(en)
    if op>=255 and blend=="normal":
        try:
            if en.get("kind") in ("progress_bar", "custom_progress_bar"):
                en.pop("_occl_layer_cache", None)  # fade done; free the layer
        except Exception:
            pass
        return _en_draw_impl(surface,en,w,h,live)
    if op<=0:return
    clip=surface.get_clip()
    layer=None;_from_cache=False;_is_fading_bar=bool(
        op<255 and en.get("kind") in ("progress_bar", "custom_progress_bar")
        and not en.get("custom_draw"))
    if _is_fading_bar:
        # Opacity tweens never change the layer's pixels, only the surface
        # alpha. Rebuild the layer only when the bar's visuals change; the
        # rebuild (textured 3-slice + alpha seal) is by far the most expensive
        # part of the fade.
        _sig=_en_bar_layer_signature(en, clip)
        _cache=en.get("_occl_layer_cache")
        if (isinstance(_cache,dict) and _cache.get("sig")==_sig
                and isinstance(_cache.get("surf"),pygame.Surface)
                and _cache.get("size")==(int(w),int(h))
                and bool(_cache["surf"].get_flags() & pygame.SRCALPHA)):
            layer=_cache["surf"];_from_cache=True
        else:
            layer=pygame.Surface((int(w),int(h)),pygame.SRCALPHA)
            if clip is not None:layer.set_clip(clip)
            _en_draw_impl(layer,en,w,h,live,real_surface=surface);layer.set_clip(None)
            _en_seal_bar_alpha(layer,en,w,h,_layer_rect())
    if layer is None:
        layer=_en_composite_surface(w,h)
        if clip is not None:layer.set_clip(clip)
        _en_draw_impl(layer,en,w,h,live,real_surface=surface);layer.set_clip(None)
        if _is_fading_bar:
            _en_seal_bar_alpha(layer,en,w,h,_layer_rect())
    if op<255:layer.set_alpha(op)
    flag=scene_blend_flag(blend);dirty=None
    if en.get("kind") in _EN_DIRTY_SAFE_KINDS and not en.get("custom_draw"):
        rect=_layer_rect()
        if isinstance(rect,pygame.Rect) and rect.width>0 and rect.height>0:
            pad=96 if en.get("kind") in ("custom_progress_bar","grid","line","wall") else 48;dirty=rect.inflate(pad,pad).clip(pygame.Rect(0,0,int(w),int(h)))
            if clip is not None:dirty=dirty.clip(clip)
            if dirty.width<=0 or dirty.height<=0:return
    if _is_fading_bar and not _from_cache and dirty is not None and _sig is not None:
        try:
            en["_occl_layer_cache"]={"sig":_sig,"surf":layer,"size":(int(w),int(h))}
        except Exception:
            pass
    if dirty is not None:
        if flag:surface.blit(layer,dirty.topleft,dirty,special_flags=flag)
        else:surface.blit(layer,dirty.topleft,dirty)
    elif flag:surface.blit(layer,(0,0),special_flags=flag)
    else:surface.blit(layer,(0,0))

# ============================================================
# ROUND 20 - Scene node proxy rendering ("viewport preview")
# ============================================================
# Scene images and text are re-projected from the source asset every frame so
# they track camera pan/zoom exactly. That is correct, and on a heavy scene it
# is also the entire frame budget: a 1080p background plus a handful of nodes
# measured ~26 ms/frame while zooming.
#
# This works the way a 3D viewport does. The scene-node layer is rendered into
# an offscreen proxy at reduced resolution, and that proxy is re-rendered only
# every N frames; in between, the cached proxy is just upscaled and blitted.
# The result is a deliberately lower-fidelity *preview* -- it is never used for
# recording, export, or the virtual-camera capture, so the finished video is
# always rendered at full quality regardless of these settings.
_SCENE_PROXY = {
    "surf": None,      # cached low-res render of the scene-node layer
    "key": None,       # invalidation key (size/quality/bucket)
    "age": 10 ** 9,    # frames since the last real render; forces a first pass
    "cam": None,       # camera state at last render, for motion detection
    "sig": None,       # legacy/default fingerprint (kept for old cleanup paths)
    # Back and front art are rendered in separate calls. A single proxy made
    # each bucket invalidate the other, so a two-layer scene could silently
    # fall back to a costly full redraw every frame.
    "layers": {},
}

def _scene_proxy_signature(art):
    """Cheap fingerprint of everything that changes how the proxied nodes look.

    Editing a node while the proxy is stale would otherwise show nothing for up
    to a full interval, which reads as a broken editor rather than a quality
    setting. Hooking every mutation site would be fragile across the dozens of
    places scene nodes are edited, so instead the layer is re-rendered whenever
    this signature moves. Animated fields (shake, tweens) are deliberately NOT
    included -- animating them is exactly what the interval is meant to skip.
    """
    out = []
    for _d, kind, o in art:
        out.append((kind, o.get("sid"), _d,
                    o.get("fx"), o.get("fy"), o.get("wx"), o.get("wy"),
                    o.get("scale"), o.get("size"), o.get("rotation"),
                    o.get("alpha"), o.get("opacity"), o.get("text"),
                    o.get("locked"), o.get("blend"),
                    id(o.get("image"))))
    return tuple(out)

def scene_proxy_active(surface, live):
    """True when the scene-node layer should go through the low-res proxy.

    Deliberately narrow: only the live on-screen editor view qualifies. Any
    recording, export, or virtual-camera capture path renders normally, so
    turning the proxy on can never degrade exported footage.
    """
    if not SETTINGS.get("scene_proxy", False):
        return False
    if not live or surface is not screen:
        return False
    # Off during ACTIVE capture only. Disabling whenever recording is merely
    # armed (record_enabled) made the cached preview silently never activate
    # for anyone who keeps recording set up — so the toggle "did nothing".
    if (is_recording and record_mode != "stream") or _is_export_render:
        return False
    if virtual_camera.get("preview"):
        return False
    return True

def scene_proxy_quality():
    try:
        return max(0.1, min(1.0, float(SETTINGS.get("scene_proxy_quality", 0.5))))
    except Exception:
        return 0.5

def scene_proxy_interval():
    try:
        return max(1, min(240, int(SETTINGS.get("scene_proxy_interval", 30))))
    except Exception:
        return 30

def scene_proxy_invalidate():
    """Force every cached scene-art layer to refresh on its next pass."""
    _SCENE_PROXY["age"] = 10 ** 9
    for _proxy_layer in _SCENE_PROXY.get("layers", {}).values():
        _proxy_layer["age"] = 10 ** 9


def _scene_proxy_layer(bucket):
    """Return a persistent proxy for one draw layer (back or front)."""
    layers = _SCENE_PROXY.setdefault("layers", {})
    if bucket not in layers:
        layers[bucket] = {"surf": None, "scratch": None, "key": None,
                          "age": 10 ** 9, "cam": None, "sig": None}
    return layers[bucket]

def _scene_proxy_cam_state():
    try:
        return (round(float(camera.get("zoom", 1.0)), 4),
                round(float(camera["pos"].x), 2),
                round(float(camera["pos"].y), 2))
    except Exception:
        return None

def _scene_proxy_camera_moved(p):
    return p["cam"] is not None and p["cam"] != _scene_proxy_cam_state()

def _scene_proxy_should_render(p, w, h, sig):
    """Decide between a fresh render and reusing the cached proxy."""
    if p["surf"] is None:
        return True
    key = (int(w), int(h), round(scene_proxy_quality(), 3))
    if key != p["key"]:
        return True
    if sig != p["sig"]:
        return True
    return p["age"] >= scene_proxy_interval()

# While a proxy render is in flight the draw functions still record "_rect"
# (hit-testing must keep working) but skip the selection/hover/lock overlays --
# those are redrawn crisply on top of the finished proxy instead of being baked
# into it at reduced resolution.
_SCENE_PROXY_PASS = [False]
# Quality factor of the proxy pass currently being rendered (0..1), or None
# when drawing at full resolution. Image/texture preparation uses this to
# cap upscaling even further so we don't smoothscale a 4K source just to
# immediately downsample it again in the proxy downscale step.
_SCENE_PROXY_Q = [None]

def _scene_proxy_overlays(surface, items):
    """Selection, multi-select, hover and lock chrome for proxied nodes, drawn
    at full resolution over the upscaled proxy."""
    mouse = pygame.mouse.get_pos()
    sel_txt = None
    if modal.get("type") == "add_text":
        _i = modal.get("editing_text_index")
        if _i is not None and 0 <= _i < len(scene_texts):
            sel_txt = scene_texts[_i]
    sel_img = None
    if modal.get("type") == "edit_image":
        _i = modal.get("editing_image_index")
        if _i is not None and 0 <= _i < len(scene_images):
            sel_img = scene_images[_i]
    multi = modal.get("_scene_multi_sel", set())
    for kind, obj in items:
        r = obj.get("_rect")
        if not r:
            continue
        if obj is sel_txt or obj is sel_img:
            pygame.draw.rect(surface, (255, 210, 60), r.inflate(4, 4), width=2, border_radius=4)
        elif (kind, obj.get("sid")) in multi:
            pygame.draw.rect(surface, (90, 220, 255), r.inflate(4, 4), width=2, border_radius=4)
        elif r.collidepoint(mouse) and not obj.get("locked", False):
            pygame.draw.rect(surface, (130, 105, 255), r.inflate(4, 4), width=1, border_radius=4)
        if obj.get("locked", False):
            _lk = get_icon_fs("lock", 14, (255, 210, 60))
            if _lk:
                surface.blit(_lk, (r.right - 16, r.y - (14 if kind == "text" else 0)))

_SCENE_DRAW_INDEX={"epoch":0,"key":None,"buckets":{"back":[],"front":[]}}


def _scene_draw_items(live):
    key=(_SCENE_DRAW_INDEX["epoch"],bool(live))
    if _SCENE_DRAW_INDEX.get("key")==key:return _SCENE_DRAW_INDEX["buckets"]
    all_items=list(external_nodes)+list(scene_texts)+list(scene_images);lookup={scene_hierarchy_key_for(it):it for it in all_items};evaluated={}
    def evaluate(item,trail=None):
        ik=scene_hierarchy_key_for(item)
        if ik in evaluated:return evaluated[ik]
        trail=set(trail or ())
        if not ik or ik in trail:return (scene_hierarchy_local_z(item),"front",False)
        trail.add(ik);parent=lookup.get(item.get("hierarchy_parent"))
        if parent is not None:
            pz,plane,phidden=evaluate(parent,trail);value=(scene_hierarchy_local_z(item)+pz,plane,phidden or not parent.get("visible",True) or bool(parent.get("_group_hidden")))
        else:
            raw=str(item.get("draw_layer","front")) if "kind" in item else str(item.get("layer","front"));plane="back" if raw in ("back","behind") else "front";value=(scene_hierarchy_local_z(item),plane,False)
        evaluated[ik]=value;return value
    buckets={"back":[],"front":[]}
    for item in all_items:
        z,plane,parent_hidden=evaluate(item)
        kind="node" if "kind" in item else "text" if "text" in item else "image"
        hidden=not item.get("visible",True) or item.get("_group_hidden") or parent_hidden
        if hidden:_scene_forget_rect(item);continue
        if live and item.get("vcam_only",False):continue
        buckets[plane].append((z,kind,item))
    buckets["back"].sort(key=lambda row:row[0]);buckets["front"].sort(key=lambda row:row[0]);_SCENE_DRAW_INDEX.update({"key":key,"buckets":buckets});return buckets


def _draw_layer_bucket_merged(surface, w, h, live, bucket, draw_layer):
    # Faux Rec defers the expensive front/HUD layer to rec.py. Behind nodes
    # remain in the core frame because they must stay behind opaque characters.
    if (_faux_capture_core and _is_export_render and bucket == "front"
            and draw_layer == "front"):
        return None
    with frame_cost("scene nodes"):
        return _draw_layer_bucket_merged_impl(surface, w, h, live, bucket, draw_layer)

def _draw_layer_bucket_merged_impl(surface, w, h, live, bucket, draw_layer):
    """Draw scene text, scene images, and external nodes for one layer
    bucket ("back"/"front") in a single depth-sorted pass.

    Previously text, images, and external nodes were drawn in three
    separate back-to-back loops, each independently sorted by "depth"/
    "layer". That meant an external node's depth value only ever
    determined its order *among other external nodes* -- it could never
    actually interleave with (draw above/below) a scene image or text at
    a given depth, no matter what depth you set it to. This merges all
    three into one list so depth values behave consistently across all
    element types, on both the live view and the virtual camera.
    """
    items=list(_scene_draw_items(live).get(bucket,()))

    # "Hide scene nodes" preview: skip images/text entirely but keep external
    # nodes (HUD/logic widgets), which are cheap and usually the thing being
    # worked on when the heavy art is turned off. This works on its own in the
    # live viewport — it must NOT require the "Cached Scene Preview" master
    # toggle, otherwise hiding art appears to do nothing.
    _hide_art = (SETTINGS.get("scene_proxy_hide", False)
                 and live and surface is screen
                 and not is_recording and not _is_export_render)
    if _hide_art:
        for _depth, kind, obj in items:
            if kind in ("text", "image"):
                _scene_forget_rect(obj)
        items = [it for it in items if it[1] == "node"]

    # Arena clip is a gameplay clip, so each scene node picks its own clip
    # rect: the box (opted in) or the full arena viewport (default).
    _clip_live  = bool(_ARENA_CLIP_STATE.get("active"))
    _clip_box   = _ARENA_CLIP_STATE.get("rect")
    _clip_outer = _ARENA_CLIP_STATE.get("outer")
    _entry_clip = surface.get_clip() if _clip_live else None

    _art = [it for it in items if it[1] in ("text", "image")]
    _proxy_on = bool(_art) and not _hide_art and scene_proxy_active(surface, live)
    # Each visual layer owns a cache. This is critical: sharing one cache made
    # the front pass invalidate the back pass (and vice versa) every frame.
    p = _scene_proxy_layer(bucket)
    # "Full quality while moving": a stale proxy visibly lags behind the camera,
    # so during pan/zoom draw normally instead.
    if _proxy_on and SETTINGS.get("scene_proxy_motion", True) and _scene_proxy_camera_moved(p):
        p["cam"] = _scene_proxy_cam_state()
        p["age"] = 10 ** 9
        _proxy_on = False

    def _draw_one(target, kind, obj):
        if kind == "text":
            draw_scene_text(target, obj, w, h, live)
        elif kind == "image":
            draw_scene_image(target, obj, w, h, live)
        else:
            _en_draw(target,obj,w,h,live)

    if not _proxy_on:
        for _depth, kind, obj in items:
            if _clip_live:
                surface.set_clip(_clip_box if _scene_item_arena_clip(obj) else _clip_outer)
            _draw_one(surface, kind, obj)
        if _clip_live:
            surface.set_clip(_entry_clip)
        return

    # --- proxied path -----------------------------------------------------
    # Images and text go through the cached low-res layer; external nodes stay
    # on the full-res pass because they are cheap and often interactive.
    q = scene_proxy_quality()
    pw, ph = max(1, int(w * q)), max(1, int(h * q))
    _sig = _scene_proxy_signature(_art)
    if _scene_proxy_should_render(p, w, h, _sig):
        # Scene nodes size themselves against the real window, so the layer is
        # drawn at full logical size and shrunk once -- rendering straight into
        # (pw, ph) would change layout, not just fidelity. The scratch buffer is
        # reused across refreshes; allocating a full-screen SRCALPHA surface per
        # refresh is exactly the churn this system exists to avoid.
        full = p.get("scratch")
        if full is None or full.get_size() != (int(w), int(h)):
            full = pygame.Surface((int(w), int(h)), pygame.SRCALPHA)
            p["scratch"] = full
        else:
            full.fill((0, 0, 0, 0))
        _SCENE_PROXY_PASS[0] = True
        _SCENE_PROXY_Q[0] = q
        try:
            for _depth, kind, obj in _art:
                if _clip_live:
                    full.set_clip(_clip_box if _scene_item_arena_clip(obj) else _clip_outer)
                _draw_one(full, kind, obj)
            full.set_clip(None)
        finally:
            _SCENE_PROXY_PASS[0] = False
            _SCENE_PROXY_Q[0] = None
        # At full quality the result would otherwise alias the scratch buffer,
        # so the next refresh's clear would wipe the "cached" layer.
        p["surf"] = pygame.transform.smoothscale(full, (pw, ph)) if q < 0.999 else full.copy()
        p["key"] = (int(w), int(h), round(q, 3))
        p["cam"] = _scene_proxy_cam_state()
        p["sig"] = _sig
        p["age"] = 0
    else:
        p["age"] += 1

    _cached = p["surf"]
    if _cached is not None:
        if _clip_live:
            surface.set_clip(_clip_outer)
        if _cached.get_size() != (int(w), int(h)):
            surface.blit(pygame.transform.smoothscale(_cached, (int(w), int(h))), (0, 0))
        else:
            surface.blit(_cached, (0, 0))
        if _clip_live:
            surface.set_clip(_entry_clip)

    if live:
        _scene_proxy_overlays(surface, [(k, o) for _d, k, o in _art])

    for _depth, kind, obj in items:
        if kind != "node":
            continue
        if _clip_live:
            surface.set_clip(_clip_box if _scene_item_arena_clip(obj) else _clip_outer)
        _draw_one(surface, kind, obj)

    if _clip_live:
        surface.set_clip(_entry_clip)

# Static scene text is commonly used for labels/HUD headings. Font rasterising
# (especially outlined text) was happening again every frame for every label.
# Cache only the immutable base glyph surface; animation, placement, rotation,
# opacity, and selection chrome remain live and therefore behave exactly as
# before.
_SCENE_TEXT_CACHE = {}
_SCENE_TEXT_CACHE_ORDER = []

# Per-character glyph cache used by per-letter shake. Without this, shake
# re-rasterised every character (with outline!) on every frame, which for a
# couple of lines of text was the single biggest CPU cost in scene text.
_SCENE_CHAR_CACHE = {}
_SCENE_CHAR_CACHE_ORDER = []

def _scene_text_surface(font, text, color, outline_w):
    key = (id(font), str(text), tuple(color)[:3], int(outline_w))
    hit = _SCENE_TEXT_CACHE.get(key)
    if hit is not None:
        return hit
    out = render_outlined_text(font, text, color, (0, 0, 0), outline_w)
    _SCENE_TEXT_CACHE[key] = out
    _SCENE_TEXT_CACHE_ORDER.append(key)
    if len(_SCENE_TEXT_CACHE_ORDER) > 384:
        stale = _SCENE_TEXT_CACHE_ORDER.pop(0)
        _SCENE_TEXT_CACHE.pop(stale, None)
    return out

def _scene_char_surface(font, ch, color, outline_w):
    """Cached single-glyph rasterisation for per-letter shake."""
    key = (id(font), str(ch), tuple(color)[:3], int(outline_w))
    hit = _SCENE_CHAR_CACHE.get(key)
    if hit is not None:
        return hit
    out = render_outlined_text(font, ch if ch != " " else " ", color, (0, 0, 0), outline_w)
    _SCENE_CHAR_CACHE[key] = out
    _SCENE_CHAR_CACHE_ORDER.append(key)
    if len(_SCENE_CHAR_CACHE_ORDER) > 512:
        stale = _SCENE_CHAR_CACHE_ORDER.pop(0)
        _SCENE_CHAR_CACHE.pop(stale, None)
    return out

def draw_scene_text(surface, t, w, h, live):
    """Draws one user-placed scene label with whole-text or per-letter shake."""
    is_preview = (virtual_camera.get("preview") and surface is not screen and not _is_export_render)
    if is_preview:
        live = True
    font_scale = SETTINGS.get("scene_font_scale", 1.0)
    scale_with_zoom=bool(t.get("world_space") and t.get("scale_with_zoom"));scale_with_frame=bool(t.get("scale_with_frame",False))
    zoom_scale=_scene_frame_relative_scale(w,h) if scale_with_frame else camera.get("zoom",1.0) if scale_with_zoom else 1.0
    # camera["zoom"] already bakes in the output-resolution factor (see
    # virtual_camera_capture_zoom), so only add render_scale on top when
    # zoom_scale *isn't* already carrying that -- otherwise it'd double-scale.
    render_scale=1.0 if (scale_with_zoom or scale_with_frame) else _ui_render_scale(w,h)
    # The glyphs scale by zoom_scale * render_scale (zoom for world-space
    # text, render_scale for fixed-pixel text). Outline and shake must scale
    # by that SAME product or they stay a fixed pixel size while the glyphs
    # grow/shrink -- which is exactly why outlines turned hair-thin and the
    # shake became invisible in the virtual-camera preview and in exported
    # recordings at higher resolutions.
    eff_scale = max(0.01, zoom_scale * render_scale)
    font_size = max(8, int(t.get("size", 28) * font_scale * eff_scale))
    # Scene typography is not damage-number typography: forcing bold and the
    # global thick damage outline made normal UI/cinematic fonts look clogged.
    # Scene text defaults to the font's real weight with a restrained 1px dark
    # keyline only when the user explicitly enables outline.
    font = get_dmg_font(font_size, t.get("font_name", "segoeui"), bold=bool(t.get("bold", False)))
    outline_w = (max(1, int(round(t.get("outline_width", 1) * eff_scale))) if t.get("outline") else 0)
    text = t.get("text", "")

    level = t.get("shake_level", 0) or 0
    freq = t.get("shake_freq", 1.0)
    t_val = pygame.time.get_ticks() / 1000.0

    # Build either a normal text surface or an expanded per-letter shaken surface.
    if t.get("per_letter_shake") and level > 0 and text:
        _shk_color = t.get("color", (255,255,255))
        chars = []
        total_w = 0
        max_h = 0
        pad = int(level * 8 * eff_scale + outline_w + 4)
        for idx, ch in enumerate(text):
            ch_surf = _scene_char_surface(font, ch, _shk_color, outline_w)
            adv = font.size(ch)[0] if ch != " " else max(4, font.size(" ")[0])
            chars.append((ch, ch_surf, adv))
            total_w += adv
            max_h = max(max_h, ch_surf.get_height())
        surf = pygame.Surface((max(1, total_w + pad * 2), max(1, max_h + pad * 2)), pygame.SRCALPHA)
        cx = pad
        for idx, (ch, ch_surf, adv) in enumerate(chars):
            phase = t_val * freq * 6.283 + idx * 1.73
            # Each glyph has its own small orbit, so words shimmer instead of moving as a block.
            # Scaled by eff_scale so the shake stays the same *relative* size
            # as the text itself across editing vs. higher-resolution recordings
            # -- otherwise the shake is a fixed pixel amount while the glyphs
            # grow, and it visibly shrinks in the exported video.
            ox = (math.sin(phase) * level * 3.0 + math.sin(phase * 1.71) * level) * eff_scale
            oy = math.cos(phase * 1.27) * level * 2.6 * eff_scale
            surf.blit(ch_surf, (cx + ox, pad + oy))
            cx += adv
        shake_x = shake_y = 0
    else:
        surf = _scene_text_surface(font, text, t.get("color", (255,255,255)), outline_w)
        shake_x = shake_y = 0
        if level > 0:
            # Scaled by eff_scale -- see the per-letter branch above for why.
            shake_x = math.sin(t_val * freq * 6.28) * level * 3 * eff_scale
            shake_y = math.cos(t_val * freq * 6.28 * 1.3) * level * 2.5 * eff_scale

    # Horizontal alignment offset: the placement point (wx/fx) is treated as
    # the left edge, center, or right edge of the text depending on `align`,
    # so re-typing shorter/longer text doesn't require re-dragging it.
    _align = t.get("align", "center")
    if _align == "left":
        _anchor_frac = 0.0
    elif _align == "right":
        _anchor_frac = 1.0
    else:
        _anchor_frac = 0.5
    _anchor_w = surf.get_width() * _anchor_frac

    if t.get("world_space") and not t.get("camera_locked", False):
        wx = float(t.get("wx") if t.get("wx") is not None else 0.0)
        wy = float(t.get("wy") if t.get("wy") is not None else 0.0)
        # Parallax-aware projection (parallax_x/parallax_y, 1.0 = normal).
        sp = _scene_parallax_pos(t, pygame.Vector2(wx, wy), w, h)
        px_ = sp.x - _anchor_w + shake_x
        py_ = sp.y - surf.get_height() / 2 + shake_y
    else:
        # Camera-attached text is normalized to the virtual export frame. In
        # the live editor, draw it inside the visible frame too, so placement
        # is WYSIWYG before the user starts recording.
        if live and t.get("camera_locked", False) and virtual_camera.get("enabled"):
            _vc_live_frame = _virtual_camera_active_frame()
            if surface is screen:
                px_ = _vc_live_frame.x + t.get("fx", 0.5) * _vc_live_frame.width - _anchor_w + shake_x
                py_ = _vc_live_frame.y + t.get("fy", 0.5) * _vc_live_frame.height - surf.get_height() / 2 + shake_y
            else:
                px_ = t.get("fx", 0.5) * w - _anchor_w + shake_x
                py_ = t.get("fy", 0.5) * h - surf.get_height() / 2 + shake_y
        else:
            px_ = t.get("fx", 0.5) * w - _anchor_w + shake_x
            py_ = t.get("fy", 0.5) * h - surf.get_height() / 2 + shake_y

    pre_w, pre_h = surf.get_width(), surf.get_height()
    rotation = float(t.get("rotation", 0) or 0)
    if rotation % 360 != 0:
        surf = pygame.transform.rotate(surf, -rotation)  # rotate clockwise
        # Center-based placement adjustment
        center = (px_ + pre_w / 2.0, py_ + pre_h / 2.0)
        rot_rect = surf.get_rect(center=center)
        px_, py_ = rot_rect.topleft

    # Universal scene-node opacity (0..255 or 0.0..1.0).
    _t_alpha = _scene_opacity_255(t)
    if _t_alpha < 255:
        surf = surf.copy()
        surf.set_alpha(_t_alpha)

    # PERF: offscreen cull for text just like images. If the text is fully
    # outside the target surface, skip the blit but still record _rect so
    # hit-testing / selection stays correct.
    try:
        _t_draw_rect = pygame.Rect(int(px_) - 4, int(py_) - 4, surf.get_width() + 8, surf.get_height() + 8)
        _t_surf_rect = surface.get_rect() if hasattr(surface, "get_rect") else pygame.Rect(0, 0, w, h)
        _t_visible = (_t_alpha > 0) and _t_draw_rect.colliderect(_t_surf_rect)
    except Exception:
        _t_visible = _t_alpha > 0

    if _t_visible:
        _tb = scene_blend_flag(scene_effective_blend(t))
        if _tb:
            surface.blit(surf, (px_, py_), special_flags=_tb)
        else:
            surface.blit(surf, (px_, py_))
    if live:
        t["_rect"] = pygame.Rect(px_, py_, surf.get_width(), surf.get_height())
        t["_world_space"] = t.get("world_space", False)
        if not _t_visible and not _SCENE_PROXY_PASS[0]:
            return  # skip selection/hover chrome for offscreen text

        # Bounding box for selection / hover. Skipped during a proxy render so
        # the chrome isn't baked in at reduced resolution; it is redrawn sharp
        # over the finished proxy instead.
        _r = t["_rect"]
        _is_hov = _r.collidepoint(pygame.mouse.get_pos())
        _is_sel = (modal.get("type") == "add_text" and modal.get("editing_text_index") is not None and 0 <= modal["editing_text_index"] < len(scene_texts) and scene_texts[modal["editing_text_index"]] is t)
        _is_multi = ("text", t.get("sid")) in modal.get("_scene_multi_sel", set())
        if _SCENE_PROXY_PASS[0] or not all_node_gizmos_enabled:
            pass
        elif _is_sel:
            pygame.draw.rect(surface, (255, 210, 60), _r.inflate(4, 4), width=2, border_radius=4)
        elif _is_multi:
            pygame.draw.rect(surface, (90, 220, 255), _r.inflate(4, 4), width=2, border_radius=4)
        elif _is_hov and not t.get("locked", False):
            pygame.draw.rect(surface, (130, 105, 255), _r.inflate(4, 4), width=1, border_radius=4)

    if is_preview and t.get("_rect"):
        _vf = _virtual_camera_display_frame()
        t["_rect"].x += _vf.x
        t["_rect"].y += _vf.y
    # Draw a small lock badge for locked text items so users know it's protected
    if live and all_node_gizmos_enabled and t.get("locked", False) and not _SCENE_PROXY_PASS[0]:
        _lk_s = get_icon_fs("lock", 14, (255, 210, 60))
        if _lk_s:
            surface.blit(_lk_s, (int(px_) + surf.get_width() - 16, int(py_) - 14))
        else:
            try:
                _lb = get_dmg_font(11, "segoeui", bold=False).render("L", True, GOLD)
                surface.blit(_lb, (int(px_) + surf.get_width() - _lb.get_width(), int(py_) - _lb.get_height()))
            except Exception:
                pass

def _apply_splice_mask(surf, splice):
    """Return a copy of surf with one side of a vertical/horizontal cut
    line made fully transparent. Used for both the main scene image and,
    optionally, its shadow (which can carry its own independent splice)."""
    if not splice or not splice.get("enabled"):
        return surf
    sw, sh = surf.get_width(), surf.get_height()
    pos = max(0.0, min(1.0, float(splice.get("pos", 0.5))))
    keep = splice.get("keep", "start")
    out = surf.copy()
    if splice.get("axis", "v") == "v":
        line_x = int(round(sw * pos))
        hide_rect = pygame.Rect(line_x, 0, sw - line_x, sh) if keep == "start" \
            else pygame.Rect(0, 0, line_x, sh)
    else:
        line_y = int(round(sh * pos))
        hide_rect = pygame.Rect(0, line_y, sw, sh - line_y) if keep == "start" \
            else pygame.Rect(0, 0, sw, line_y)
    if hide_rect.width > 0 and hide_rect.height > 0:
        out.fill((0, 0, 0, 0), hide_rect)
    return out

_SCENE_IMG_CACHE = {}
_SCENE_IMG_GRADE_CACHE = {}
_SCENE_IMG_GRADE_CACHE_BYTES = [0]

# Cache for load_script_ns_from_file: (abspath, mtime, size) -> built namespace.
# Cleared on trait-script reload so edits always take effect immediately.
_SCRIPT_NS_CACHE = {}

def _scene_img_cache_key(img, scale):
    sp = img.get("splice") or {}
    sh = img.get("shadow") or {}
    # Quantise scale to 3 decimal places so smooth-zoom float churn (1.0004
    # vs 1.0007) doesn't thrash the cache every frame.
    return (id(img.get("image")), round(float(scale), 3),
            int(img.get("alpha", 255)), _scene_opacity_255(img),
            round(float(img.get("rotation", 0) or 0), 2),
            bool(img.get("flip_x")), bool(img.get("flip_y")),
            bool(img.get("pixel_perfect")),
            tuple(int(v) for v in list(img.get("tint_color",[255,255,255]))[:3]),
            round(float(img.get("tint_strength",0.0)),3),round(float(img.get("darkness",0.0)),3),
            round(float(img.get("brightness",1.0)),3),round(float(img.get("saturation",1.0)),3),
            round(float(img.get("contrast",1.0)),3),round(float(img.get("hue_shift",0.0)),2),
            bool(sp.get("enabled")), sp.get("axis"),
            round(float(sp.get("pos", 0.5)), 4), sp.get("keep"),
            bool(sh.get("enabled")), tuple(sh.get("color", (0, 0, 0))),
            int(sh.get("alpha", 160)), bool(sh.get("use_main_splice", True)),
            round(float(sh.get("offset_x", 6)), 2), round(float(sh.get("offset_y", 6)), 2),
            bool(img.get("tile_enabled")), int(img.get("tile_cols", 1)), int(img.get("tile_rows", 1)),
            round(float(img.get("tile_gap_x", 0.0)), 4), round(float(img.get("tile_gap_y", 0.0)), 4))

def _scene_image_grade_key(surf,cfg):
    tint=(list(cfg.get("tint_color",[255,255,255]) or [255,255,255])+[255,255,255])[:3]
    return (id(surf),tuple(max(0,min(255,int(v))) for v in tint),
            round(float(cfg.get("tint_strength",0.0)),3),round(float(cfg.get("darkness",0.0)),3),
            round(float(cfg.get("brightness",1.0)),3),round(float(cfg.get("saturation",1.0)),3),
            round(float(cfg.get("contrast",1.0)),3),round(float(cfg.get("hue_shift",0.0)),2))

def _scene_image_color_grade(surf,cfg):
    """Grade the SOURCE image once, before scaling; alpha is preserved."""
    if surf is None:return surf
    key=_scene_image_grade_key(surf,cfg);hit=_SCENE_IMG_GRADE_CACHE.get(key)
    if hit is not None:
        _SCENE_IMG_GRADE_CACHE.pop(key,None);_SCENE_IMG_GRADE_CACHE[key]=hit;return hit
    try:
        hue=max(-180.0,min(180.0,float(cfg.get("hue_shift",0.0))));sat=max(0.0,min(3.0,float(cfg.get("saturation",1.0))));bright=max(0.0,min(3.0,float(cfg.get("brightness",1.0))));dark=max(0.0,min(1.0,float(cfg.get("darkness",0.0))));contrast=max(0.0,min(3.0,float(cfg.get("contrast",1.0))));strength=max(0.0,min(1.0,float(cfg.get("tint_strength",0.0))))
        tint=(list(cfg.get("tint_color",[255,255,255]) or [255,255,255])+[255,255,255])[:3]
        neutral=abs(hue)<1e-6 and abs(sat-1)<1e-6 and abs(bright-1)<1e-6 and dark<=1e-6 and abs(contrast-1)<1e-6 and strength<=1e-6
        if neutral:return surf
        factor=bright*(1.0-dark)
        # Darkness-only/common brightness-down path is an SDL multiply: no
        # NumPy arrays, and crucially no multi-megapixel per-frame conversion.
        if abs(hue)<1e-6 and abs(sat-1)<1e-6 and abs(contrast-1)<1e-6 and strength<=1e-6 and factor<=1.0:
            out=surf.copy();mul=max(0,min(255,int(round(factor*255))));out.fill((mul,mul,mul,255),special_flags=pygame.BLEND_RGBA_MULT)
        else:
            arr=pygame.surfarray.array3d(surf).astype(np.float32);w0,h0=arr.shape[:2];arr=_recolor_rgb_array(arr.reshape(-1,3),hue,sat,1.0).reshape(w0,h0,3);arr=(arr-127.5)*contrast+127.5;arr*=factor
            if strength>0.0:
                tv=np.array([max(0,min(255,float(v))) for v in tint],dtype=np.float32)/255.0;arr=arr*(1.0-strength)+(arr*tv)*strength
            out=pygame.surfarray.make_surface(np.clip(arr,0,255).astype(np.uint8)).convert_alpha()
            try:aa=pygame.surfarray.array_alpha(surf);pa=pygame.surfarray.pixels_alpha(out);pa[:]=aa;del pa
            except Exception:pass
        cost=out.get_width()*out.get_height()*4
        if cost<=32*1024*1024:
            while _SCENE_IMG_GRADE_CACHE and (len(_SCENE_IMG_GRADE_CACHE)>=24 or _SCENE_IMG_GRADE_CACHE_BYTES[0]+cost>96*1024*1024):
                old=_SCENE_IMG_GRADE_CACHE.pop(next(iter(_SCENE_IMG_GRADE_CACHE)));_SCENE_IMG_GRADE_CACHE_BYTES[0]=max(0,_SCENE_IMG_GRADE_CACHE_BYTES[0]-old.get_width()*old.get_height()*4)
            _SCENE_IMG_GRADE_CACHE[key]=out;_SCENE_IMG_GRADE_CACHE_BYTES[0]+=cost
        return out
    except Exception:return surf

def _scene_tile_grid(cell, cols, rows, gap_x, gap_y, max_dim=8192):
    """Compose `cell` into a cols x rows grid surface (gaps as fractions of the
    cell size).  Returns (surface, grid_w, grid_h).  A 1x1 grid returns the
    cell unchanged.  `max_dim` bounds the composed surface so a huge array never
    allocates a multi-hundred-megapixel texture (the caller pre-clamps the cell
    size; this is a final safety net)."""
    cols = max(1, int(cols)); rows = max(1, int(rows))
    if cols == 1 and rows == 1:
        return cell, cell.get_width(), cell.get_height()
    cw = max(1, cell.get_width()); ch = max(1, cell.get_height())
    gx = max(0, int(cw * float(gap_x)))
    gy = max(0, int(ch * float(gap_y)))
    grid_w = cw * cols + gx * (cols - 1)
    grid_h = ch * rows + gy * (rows - 1)
    if grid_w > max_dim or grid_h > max_dim:
        _s = min(max_dim / max(1, grid_w), max_dim / max(1, grid_h))
        cw = max(1, int(cw * _s)); ch = max(1, int(ch * _s))
        gx = max(0, int(cw * float(gap_x))); gy = max(0, int(ch * float(gap_y)))
        grid_w = cw * cols + gx * (cols - 1)
        grid_h = ch * rows + gy * (rows - 1)
        # The cell itself must be rescaled to the clamped size so tiles keep
        # their distinct footprint instead of overlapping.
        try:
            cell = pygame.transform.smoothscale(cell, (cw, ch))
        except Exception:
            try:
                cell = pygame.transform.scale(cell, (cw, ch))
            except Exception:
                pass
    try:
        grid = pygame.Surface((grid_w, grid_h), pygame.SRCALPHA)
    except Exception:
        return cell, cell.get_width(), cell.get_height()
    for r in range(rows):
        for c in range(cols):
            grid.blit(cell, (c * (cw + gx), r * (ch + gy)))
    return grid, grid_w, grid_h

def _scene_img_prepare(img, scale):
    """Do the expensive per-image surface work once; the caller caches it."""

    # Grade at native source size, then scale the cached result. Previously the
    # order was reversed, so darkening one 1000px image after zoom/upscale could
    # allocate/process millions of pixels for every APU frame (multi-second).
    _graded_source=_scene_image_color_grade(img["image"],img)
    src_w, src_h = _graded_source.get_width(), _graded_source.get_height()
    # PERF: cap the rendered size so a tiny source image that's been scaled up
    # 10x+ (e.g. a 128x128 sprite placed at scale=8 filling the screen) never
    # smoothscales to a multi-megapixel surface and tanks framerate. Anything
    # beyond 2x the target surface is wasted -- the extra pixels get
    # downscaled by the blit anyway. The cap can be raised in settings.
    try:
        _cap = max(1.25, float(SETTINGS.get("scene_max_tex_scale", 2.0)))
    except Exception:
        _cap = 2.0
    # Use a hard pixel cap based on the screen size so a world-space bg that
    # zoom has inflated can't blow up either. During a proxy pass we tighten
    # the cap further: the scratch will itself be downscaled to pw x ph, so
    # any pixels above pw/ph are immediately thrown away -- but smoothscaling
    # them is the #1 cost of the proxy refresh.
    _max_dim = max(4096, int(max(WIDTH, HEIGHT) * _cap * 2))
    try:
        _pq = _SCENE_PROXY_Q[0]
        if _pq is not None:
            _max_dim = min(_max_dim, max(256, int(max(WIDTH, HEIGHT) * max(0.1, float(_pq)) * 1.25)))
    except Exception:
        pass
    iw = max(1, int(src_w * scale))
    ih = max(1, int(src_h * scale))
    if iw > _max_dim or ih > _max_dim:
        _s = min(_max_dim / max(1, iw), _max_dim / max(1, ih))
        iw = max(1, int(iw * _s))
        ih = max(1, int(ih * _s))
    # PERF (tiled backdrop): the grid is composed by repeating the cell, so the
    # final surface is ~cols*rows the cell size.  Clamp the cell so the WHOLE
    # grid (cell*count + gaps) stays within a screen-proportional cap --
    # otherwise a 16x16 array of a large texture would allocate a
    # multi-hundred-megapixel surface and crater the framerate/memory.
    _tt_on = bool(img.get("tile_enabled"))
    _tcols = max(1, int(img.get("tile_cols", 1)))
    _trows = max(1, int(img.get("tile_rows", 1)))
    if _tt_on and (_tcols > 1 or _trows > 1):
        _grid_max = int(max(WIDTH, HEIGHT) * 2.0)
        _grid_max = max(2048, min(8192, _grid_max))
        _gcw = iw * _tcols
        _gch = ih * _trows
        if _gcw > _grid_max or _gch > _grid_max:
            _gs = min(_grid_max / max(1, _gcw), _grid_max / max(1, _gch))
            iw = max(1, int(iw * _gs))
            ih = max(1, int(ih * _gs))
    if img.get("pixel_perfect", False):
        base_surf = pygame.transform.scale(_graded_source, (iw, ih))  # nearest-neighbor, keeps hard pixel edges
    else:
        try:
            base_surf = pygame.transform.smoothscale(_graded_source, (iw, ih))
        except Exception:
            base_surf = pygame.transform.scale(_graded_source, (iw, ih))

    flip_x = bool(img.get("flip_x", False))
    flip_y = bool(img.get("flip_y", False))
    if flip_x or flip_y:
        # Flip BEFORE splice so "keep start/end" always refers to the
        # image as it's currently displayed, not the un-flipped source --
        # otherwise flipping would silently swap which side splice keeps.
        base_surf = pygame.transform.flip(base_surf, flip_x, flip_y)

    rotation = float(img.get("rotation", 0) or 0)

    shadow_cfg = img.get("shadow")
    shadow_surf = None
    if shadow_cfg and shadow_cfg.get("enabled"):
        shadow_splice = img.get("splice") if shadow_cfg.get("use_main_splice", True) else shadow_cfg.get("splice")
        shadow_surf = _apply_splice_mask(base_surf, shadow_splice)
        if shadow_surf is base_surf:
            shadow_surf = shadow_surf.copy()
        s_color = tuple(int(c) for c in shadow_cfg.get("color", [0, 0, 0]))[:3]
        shadow_surf.fill((*s_color, 255), special_flags=pygame.BLEND_RGBA_MULT)
        shadow_surf.set_alpha(max(0, min(255, int(shadow_cfg.get("alpha", 160)))))
        # NOTE: shadow rotation is deferred until after tiling so the whole
        # shadow grid is composed first, then rotated with the image grid.

    surf = base_surf
    # "alpha" is the image's own transparency; "opacity" is the universal
    # scene-node fade that every node kind understands. Multiply them so both
    # the image editor slider and blueprint-driven fades work together.
    alpha = int(round(int(img.get("alpha", 255)) * _scene_opacity_255(img) / 255.0))
    if alpha < 255:
        surf = surf.copy()
        surf.set_alpha(max(0, min(255, alpha)))

    splice = img.get("splice")
    surf = _apply_splice_mask(surf, splice)
    if surf is base_surf:
        surf = surf.copy()

    # ── Tiled backdrop: repeat the single prepared cell into a grid ──────
    tile_on = bool(img.get("tile_enabled"))
    tcols = max(1, int(img.get("tile_cols", 1)))
    trows = max(1, int(img.get("tile_rows", 1)))
    if tile_on and (tcols > 1 or trows > 1):
        surf, gw, gh = _scene_tile_grid(surf, tcols, trows,
                                        img.get("tile_gap_x", 0.0), img.get("tile_gap_y", 0.0))
        if shadow_surf is not None:
            shadow_surf, _, _ = _scene_tile_grid(shadow_surf, tcols, trows,
                                                 img.get("tile_gap_x", 0.0), img.get("tile_gap_y", 0.0))

    if rotation % 360 != 0:
        pre_w, pre_h = surf.get_width(), surf.get_height()
        surf = pygame.transform.rotate(surf, rotation)
        if shadow_surf is not None:
            shadow_surf = pygame.transform.rotate(shadow_surf, rotation)
    else:
        pre_w, pre_h = surf.get_width(), surf.get_height()
    return surf, shadow_surf, pre_w, pre_h, rotation, shadow_cfg

def draw_scene_image(surface, img, w, h, live):
    """Draws a user-placed scene image (PNG) with the same rules as scene text."""
    is_preview = (virtual_camera.get("preview") and surface is not screen and not _is_export_render)
    if is_preview:
        live = True
    if not img.get("image"):
        return
    scale_with_zoom = bool(img.get("world_space") and img.get("scale_with_zoom"))
    scale_with_frame = bool(img.get("scale_with_frame", False))
    vcam_zoom = max(0.05, float(virtual_camera.get("zoom", 1.0)))
    live_cam_zoom = max(0.05, float(camera.get("zoom", 1.0)))

    if scale_with_frame:
        zoom_scale=_scene_frame_relative_scale(w,h,live_cam_zoom)
    elif scale_with_zoom:
        zoom_scale = live_cam_zoom
    else:
        zoom_scale = 1.0

    render_scale = 1.0 if (scale_with_zoom or scale_with_frame) else _ui_render_scale(w, h)
    scale = max(0.01, img.get("scale", 1.0) * zoom_scale * render_scale)

    # ── Cached surface prepare ────────────────────────────────────────
    # Scaling, flipping, splicing, tinting and rotating the SOURCE image was
    # happening every single frame. On a 1920x1080 background that alone was
    # ~7 ms -- by far the largest cost in an otherwise empty scene. None of
    # it changes between frames unless the image's settings or the zoom do,
    # so the finished surfaces are memoised per image.
    _ck = _scene_img_cache_key(img, scale)
    _hit = _SCENE_IMG_CACHE.get(id(img))
    if _hit is not None and _hit[0] == _ck:
        surf, shadow_surf, pre_w, pre_h, rotation = _hit[1], _hit[2], _hit[3], _hit[4], _hit[5]
        shadow_cfg = img.get("shadow")
    else:
        surf, shadow_surf, pre_w, pre_h, rotation, shadow_cfg = _scene_img_prepare(img, scale)
        _SCENE_IMG_CACHE[id(img)] = (_ck, surf, shadow_surf, pre_w, pre_h, rotation)
        if len(_SCENE_IMG_CACHE) > 96:
            _SCENE_IMG_CACHE.pop(next(iter(_SCENE_IMG_CACHE)))

    # anchor_x/anchor_y are normalized (0..1) pivot coords ON the image
    # itself: 0.5,0.5 = center (old default), 0,0 = top-left corner sits
    # at the placement point, 0.5,1.0 = bottom-center (image sits "on top
    # of" the point instead of straddling it), etc.
    anchor_x = img.get("anchor_x", 0.5)
    anchor_y = img.get("anchor_y", 0.5)

    if img.get("world_space") and not img.get("camera_locked", False):
        wx = float(img.get("wx") if img.get("wx") is not None else 0.0)
        wy = float(img.get("wy") if img.get("wy") is not None else 0.0)
        # Parallax-aware projection (parallax_x/parallax_y, 1.0 = normal).
        sp = _scene_parallax_pos(img, pygame.Vector2(wx, wy), w, h)
        px_ = sp.x - pre_w * anchor_x
        py_ = sp.y - pre_h * anchor_y
    else:
        if live and img.get("camera_locked", False) and virtual_camera.get("enabled"):
            _vc_live_frame = _virtual_camera_active_frame()
            if surface is screen:
                px_ = _vc_live_frame.x + img.get("fx", 0.5) * _vc_live_frame.width - pre_w * anchor_x
                py_ = _vc_live_frame.y + img.get("fy", 0.5) * _vc_live_frame.height - pre_h * anchor_y
            else:
                px_ = img.get("fx", 0.5) * w - pre_w * anchor_x
                py_ = img.get("fy", 0.5) * h - pre_h * anchor_y
        else:
            px_ = img.get("fx", 0.5) * w - pre_w * anchor_x
            py_ = img.get("fy", 0.5) * h - pre_h * anchor_y

    if rotation % 360 != 0:
        # px_/py_ above describe the top-left of the *unrotated* footprint;
        # rotate around that footprint's center so the anchor point stays
        # visually put, then re-derive the blit position from the rotated
        # surface's (larger) bounding box.
        center = (px_ + pre_w / 2.0, py_ + pre_h / 2.0)
        rot_rect = surf.get_rect(center=center)
        px_, py_ = rot_rect.topleft

    # PERF: offscreen cull. Compute the full post-rotation draw rect, and if it
    # is completely outside the target surface, skip the blit entirely. This is
    # the single biggest win for large world-space backgrounds that are
    # scrolled out of view -- we still pay the cache lookup but avoid the blit.
    try:
        _draw_w = surf.get_width()
        _draw_h = surf.get_height()
        _draw_rect = pygame.Rect(int(px_) - 8, int(py_) - 8, _draw_w + 16, _draw_h + 16)
        _surf_rect = surface.get_rect() if hasattr(surface, "get_rect") else pygame.Rect(0, 0, w, h)
        _visible = _draw_rect.colliderect(_surf_rect)
    except Exception:
        _visible = True

    if not _visible and live and not _SCENE_PROXY_PASS[0]:
        # Still record a zero-size _rect so hit-testing stays consistent but
        # we don't pay the blit cost for offscreen art.
        img["_rect"] = pygame.Rect(int(px_), int(py_), _draw_w if '_draw_w' in dir() else 0, _draw_h if '_draw_h' in dir() else 0)
        img["_world_space"] = img.get("world_space", False)
        return

    if shadow_surf is not None and _visible:
        _sx_off = float(shadow_cfg.get("offset_x", 6)) * render_scale
        _sy_off = float(shadow_cfg.get("offset_y", 6)) * render_scale
        _s_dw = shadow_surf.get_width() - surf.get_width()
        _s_dh = shadow_surf.get_height() - surf.get_height()
        surface.blit(shadow_surf, (px_ - _s_dw / 2.0 + _sx_off, py_ - _s_dh / 2.0 + _sy_off))

    _ib = scene_blend_flag(scene_effective_blend(img))
    if _visible:
        if _ib:
            surface.blit(surf, (px_, py_), special_flags=_ib)
        else:
            surface.blit(surf, (px_, py_))
    if live:
        img["_rect"] = pygame.Rect(px_, py_, surf.get_width(), surf.get_height())
        img["_world_space"] = img.get("world_space", False)
        
        # Bounding box for selection / hover
        _r = img["_rect"]
        _is_hov = _r.collidepoint(pygame.mouse.get_pos())
        _is_sel = (modal.get("type") == "edit_image" and modal.get("editing_image_index") is not None and 0 <= modal["editing_image_index"] < len(scene_images) and scene_images[modal["editing_image_index"]] is img)
        _is_multi = ("image", img.get("sid")) in modal.get("_scene_multi_sel", set())
        if _SCENE_PROXY_PASS[0] or not all_node_gizmos_enabled:
            pass
        elif _is_sel:
            pygame.draw.rect(surface, (255, 210, 60), _r.inflate(4, 4), width=2, border_radius=4)
        elif _is_multi:
            pygame.draw.rect(surface, (90, 220, 255), _r.inflate(4, 4), width=2, border_radius=4)
        elif _is_hov and not img.get("locked", False):
            pygame.draw.rect(surface, (130, 105, 255), _r.inflate(4, 4), width=1, border_radius=4)

    if is_preview and img.get("_rect"):
        _vf = _virtual_camera_display_frame()
        img["_rect"].x += _vf.x
        img["_rect"].y += _vf.y
    # Draw a small lock badge for locked images
    if live and all_node_gizmos_enabled and img.get("locked", False) and not _SCENE_PROXY_PASS[0]:
        _lk_s2 = get_icon_fs("lock", 14, (255, 210, 60))
        if _lk_s2:
            surface.blit(_lk_s2, (int(px_) + surf.get_width() - 16, int(py_)))
        else:
            try:
                _lb2 = get_dmg_font(11, "segoeui", bold=False).render("L", True, GOLD)
                surface.blit(_lb2, (int(px_) + surf.get_width() - _lb2.get_width(), int(py_)))
            except Exception:
                pass

def get_countdown_number():
    if not countdown_active:
        return None
    elapsed = pygame.time.get_ticks() / 1000.0 - countdown_start_time
    # countdown_duration is float, round up for display
    n = int(math.ceil(countdown_duration - elapsed))
    return n if n >= 1 else None

def begin_match_simulation(use_countdown=True):
    """Start a real match (logic / win conditions / on_game_start hooks).

    Play/Pause only freezes physics. This is the actual match start.
    """
    global countdown_active, countdown_start_time, simulation_started, paused
    global game_over, winner, end_fade_alpha, end_fade_complete, end_fade_timer
    global game_start_time

    # Always clear any half-started countdown so the UI can't stick on
    # "Cancel Countdown" with no visible numbers.
    game_over = False
    winner = None
    end_fade_alpha = 0.0
    end_fade_complete = False
    end_fade_timer = 0.0
    scene_death_history.clear()
    paused = False  # countdown + match must not sit paused or they never advance
    _prepare_scene_timers_for_match()

    want_cd = bool(use_countdown) and float(countdown_duration or 0) > 0.05
    if want_cd:
        countdown_active = True
        countdown_start_time = pygame.time.get_ticks() / 1000.0
        simulation_started = False
        if record_enabled and record_countdown_visible and not is_recording:
            try:
                start_recording()
            except Exception:
                pass
        push_toast(f"Match starting in {int(math.ceil(countdown_duration))}…", "info", 2.0)
    else:
        countdown_active = False
        simulation_started = True
        game_start_time = pygame.time.get_ticks() / 1000.0
        if record_enabled and not is_recording:
            try:
                start_recording()
            except Exception:
                pass
        for _c in characters:
            try:
                call_hook(_c, "on_game_start", CTX, _c)
            except Exception:
                pass
        # Start background music when match starts
        try:
            play_background_music()
        except Exception:
            pass
        push_toast("Match simulation started", "success", 2.0)

def open_start_mode_prompt():
    """One clear Run action, then choose physics sandbox or full match."""
    modal["type"] = "start_mode_prompt"
    modal["focus"] = None


def stop_match_simulation(reason="stopped"):
    """Stop match + cancel any countdown. Safe to call anytime."""
    global countdown_active, simulation_started, paused
    global game_over, winner, end_fade_alpha, end_fade_complete, end_fade_timer

    was_cd = countdown_active
    was_sim = simulation_started
    simulation_started = False
    countdown_active = False
    paused = True
    game_over = False
    winner = None
    end_fade_alpha = 0.0
    end_fade_complete = False
    end_fade_timer = 0.0
    # Stop background music when match stops
    try:
        stop_background_music()
    except Exception:
        pass
    if is_recording:
        try:
            stop_recording()
        except Exception:
            pass
    if _OBS_RECORDING_ACTIVE:
        try:stop_obs_recording(False)
        except Exception:pass
    if was_cd and not was_sim:
        push_toast("Countdown cancelled", "info", 2.0)
    elif was_sim:
        push_toast("Match simulation stopped", "info", 2.0)
    elif reason == "stopped":
        push_toast("Simulation idle", "info", 1.5)

def toggle_physics_pause():
    """Play/Pause — freezes movement/physics only. Does not start match logic."""
    global paused, countdown_active
    # If a stuck countdown is active but no numbers remain, clear it instead
    # of leaving the UI on a phantom "Cancel Countdown".
    if countdown_active and get_countdown_number() is None and not simulation_started:
        # Countdown finished visually while paused — either finish start or clear
        if not paused:
            pass
        countdown_active = False
    paused = not paused
    if paused:
        push_toast("Physics paused", "info", 1.2)
    else:
        push_toast("Physics playing", "info", 1.2)

def _ensure_character_motion_after_reset(character,preferred_velocity=None):
    """Wake a revived/reloaded fighter without disturbing planted physics bodies."""
    if not isinstance(character,dict) or character.get("is_scene_prop") or character.get("scene_director"):return False
    character["sleeping"]=False;character.pop("_despawned",None)
    # Collision state is authored runtime state, not disposable death debris.
    # In particular, scripts commonly use collision_disabled_until=inf or a
    # pass-through collision_mode. Reload/revive must not silently turn solid.
    if preferred_velocity is not None:
        try:
            pv=pygame.Vector2(preferred_velocity)
            if pv.length_squared()>1e-6:character["vel"]=pv;character["_smooth_vel"]=pygame.Vector2(pv);return True
        except Exception:pass
    # Legacy arena fighters move by persistent velocity. A zero vector never
    # recovers on its own, so seed it from authored speed after reset/revive.
    if character.get("body_type","dynamic")=="dynamic" and not character.get("gravity_enabled",False) and not character.get("movement_locked",False) and not character.get("input_paused",False):
        vel=pygame.Vector2(character.get("vel",(0,0)))
        if vel.length_squared()<1e-6:
            speed=max(0.0,float(character.get("speed",0.0) or 0.0))
            if speed>0:
                angle=float(character.get("angle",random.uniform(0,360)));vel=pygame.Vector2(speed,0).rotate(angle);character["vel"]=vel;character["_smooth_vel"]=pygame.Vector2(vel);return True
    return False


def reload_characters_in_scene():
    """Reload every live character without stopping or corrupting physics.

    The old implementation called stop_match_simulation() and then replaced
    every character's velocity with (0, 0).  Nothing restored the old paused
    state or velocity, so the Reload button permanently froze the arena.  It
    also left freshly respawned colliders stacked on the same positions, which
    could make the first movement frame tunnel one body through another.

    This version keeps the simulation's running/paused state, carries forward
    each body's velocity, rebuilds scripts/sprites through spawn_instance(),
    re-runs the game-start hook when appropriate, and performs a non-damaging
    overlap separation pass before gameplay resumes.
    """
    global characters
    if not characters:
        push_toast("No characters in scene to reload.", "info", 1.5)
        return

    _was_running = bool(simulation_started)
    _was_paused = bool(paused)
    _old_camera_target = camera.get("target")
    old_state = []

    for c in list(characters):
        try:
            tmpl = {
                "instance_id": str(c.get("instance_id", "") or generate_character_instance_id()),
                "name": c.get("name", "Box"),
                "color": tuple(c.get("color", (100, 100, 200))),
                "radius": float(c.get("radius", 16)),
                "max_hp": int(c.get("max_hp", 100)),
                # Reload remains a respawn/reset action, so HP returns to max.
                "hp": int(c.get("max_hp", 100)),
                "dmg_min": int(c.get("dmg_min", 5)),
                "dmg_max": int(c.get("dmg_max", 10)),
                "speed": float(c.get("speed", 150)),
                "crit_chance": float(c.get("crit_chance", 0.1)),
                "crit_mult": float(c.get("crit_mult", 1.5)),
                "script_file": c.get("script_file"),
                "sprite_folder": c.get("sprite_folder"),
                "sprite_map": dict(c.get("sprite_map", {})),
                "script_params": dict(c.get("script_params", {})),
                "audio_map": dict(c.get("audio_map", {})),
                "audio_volume_map": dict(c.get("audio_volume_map", {})),
                "team": c.get("team", c.get("name", "default")),
                "friendly_fire": c.get("friendly_fire", True),
                "scale": c.get("scale", 1.0),
                "is_scene_prop": c.get("is_scene_prop", False),
                "is_visible": c.get("is_visible", True),
                "has_collision": c.get("has_collision", True),
                "collision_mode": c.get("collision_mode", "solid"),
                "scene_director": c.get("scene_director", False),
                "contact_trait": c.get("contact_trait", "normal"),
                "contact_traits": list(c.get("_contact_traits", [])),
                "collision_shape": c.get("collision_shape", "sphere"),
                "collision_source": c.get("collision_source", "custom"),
                "collision_radius": float(c.get("collision_radius", 16)),
                "collision_radius_x": float(c.get("collision_radius_x", 16)),
                "collision_radius_y": float(c.get("collision_radius_y", 16)),
                "collision_box_w": float(c.get("collision_box_w", 32)),
                "collision_box_h": float(c.get("collision_box_h", 32)),
                "collision_offset_x": float(c.get("collision_offset_x", 0.0)),
                "collision_offset_y": float(c.get("collision_offset_y", 0.0)),
                "collision_debug_color": list(c.get("collision_debug_color", [110, 195, 255])),
                "collision_debug_editor_visible": bool(c.get("collision_debug_editor_visible", True)),
                "collision_debug_play_visible": bool(c.get("collision_debug_play_visible", True)),
                "collision_debug_fill": bool(c.get("collision_debug_fill", True)),
                "max_speed": float(c.get("max_speed", MAX_SPEED)),
                "min_speed": float(c.get("min_speed", 0.0)),
                "mass": float(c.get("mass", 1.0)),
                "bounce": float(c.get("bounce", 1.0)),
                "gravity": float(c.get("gravity", 0.0)),
                "gravity_scale": float(c.get("gravity_scale", 1.0)),
                "gravity_enabled": bool(c.get("gravity_enabled", False)),
                "rig": copy.deepcopy(c.get("rig")),
                "anim_machine": copy.deepcopy(c.get("anim_machine")),
                "animations": dict(c.get("animation_paths", c.get("animation_sources", {}))),
                "animation_sources": dict(c.get("animation_sources", {})),
                "animation_fps": dict(c.get("animation_fps", {})),
                "animation_durations": {
                    k: list(v) for k, v in dict(c.get("animation_durations", {})).items()
                },
                "animation_anchors": dict(c.get("animation_anchors", {})),
                "animation_pivots": copy.deepcopy(c.get("animation_pivots", {})),
                "animation_position_events": copy.deepcopy(c.get("animation_position_events", {})),
                "animation_collision_frames": copy.deepcopy(c.get("animation_collision_frames", {})),
                "animation_layers": copy.deepcopy(c.get("animation_layers", {})),
            }
            runtime = {
                "pos": pygame.Vector2(c.get("pos", (0, 0))),
                "vel": pygame.Vector2(c.get("vel", (0, 0))),
                "smooth_vel": pygame.Vector2(c.get("_smooth_vel", c.get("vel", (0, 0)))),
                "angle": float(c.get("angle", 0.0)),
                "movement_locked": bool(c.get("movement_locked",False)),
                "input_paused": bool(c.get("input_paused",False)),
                "manual_input_enabled": bool(c.get("manual_input_enabled",True)),
                "was_camera_target": c is _old_camera_target,
                "collision_state": {k:copy.deepcopy(c.get(k)) for k in (
                    "has_collision","collision_mode","collision_disabled_until",
                    "_no_collide_ids","_no_collide_tags","_no_collide_shared_tags",
                    "_no_collide_same_team") if k in c},
            }
            old_state.append((tmpl, runtime))
        except Exception as e:
            print(f"Could not snapshot character for reload: {e}")

    # Re-read scripts from disk.  Do not call stop_match_simulation(): this
    # function is synchronous, so physics cannot tick while the list is rebuilt.
    try:
        _SCRIPT_NS_CACHE.clear()
    except Exception:
        pass
    try:
        for _mn in list(sys.modules.keys()):
            if _mn.startswith("script_") or _mn.startswith("user_script_"):
                del sys.modules[_mn]
    except Exception:
        pass

    characters.clear()
    scene_death_history.clear()
    popups.clear()
    camera["target"] = None
    count = 0

    for tmpl, runtime in old_state:
        try:
            inst = spawn_instance(tmpl)  # loads fresh script + calls on_spawn
            inst["pos"] = pygame.Vector2(runtime["pos"])

            # A running match needs its game-start graph setup on the new
            # instance (collision rules, controls, timers, etc.).
            if _was_running:
                try:
                    call_hook(inst, "on_game_start", CTX, inst)
                except Exception:
                    pass

            # Keep actual momentum from immediately before Reload.  The old
            # code forced both values to zero, which was the freeze bug.
            inst["vel"] = pygame.Vector2(runtime["vel"])
            inst["_smooth_vel"] = pygame.Vector2(runtime["smooth_vel"])
            inst["angle"] = runtime["angle"]
            inst["movement_locked"]=runtime.get("movement_locked",False);inst["input_paused"]=runtime.get("input_paused",False);inst["manual_input_enabled"]=runtime.get("manual_input_enabled",True);inst["sleeping"]=False
            inst["_touching_partners"] = set();inst["_phase_touching_ids"]=set();inst["_phase_touch_refs"]={}
            # Preserve the exact pass-through policy that was live immediately
            # before Reload. Fresh on_spawn/on_game_start setup has already run;
            # restoring here prevents reset cleanup/defaults from forcing Solid.
            for _ck,_cv in runtime.get("collision_state",{}).items():inst[_ck]=copy.deepcopy(_cv)
            _ensure_character_motion_after_reset(inst,runtime["vel"])
            characters.append(inst)
            if runtime["was_camera_target"]:
                camera["target"] = inst
            count += 1
        except Exception as e:
            print(f"Failed to reload character: {e}")

    # Resolve initial penetration immediately, even if physics was paused.
    # This pass changes positions only: no damage, hooks, or velocity impulses.
    try:
        for _pass in range(6):
            _moved_any = False
            for _i in range(len(characters)):
                for _j in range(_i + 1, len(characters)):
                    a, b = characters[_i], characters[_j]
                    if a.get("scene_director") or b.get("scene_director"):
                        continue
                    if _phase_touch_pair_is_passthrough(a,b,time.time()):
                        continue
                    ca = _character_collision_center(a)
                    cb = _character_collision_center(b)
                    ax, ay = _character_collision_half_extents(a)
                    bx, by = _character_collision_half_extents(b)
                    if a.get("collision_shape") == "box" and b.get("collision_shape") == "box":
                        ox = ax + bx - abs(ca.x - cb.x)
                        oy = ay + by - abs(ca.y - cb.y)
                        if ox <= 0.0 or oy <= 0.0:
                            continue
                        if ox < oy:
                            normal = pygame.Vector2(1, 0) if ca.x >= cb.x else pygame.Vector2(-1, 0)
                            overlap = ox
                        else:
                            normal = pygame.Vector2(0, 1) if ca.y >= cb.y else pygame.Vector2(0, -1)
                            overlap = oy
                    else:
                        min_dist = max(ax, ay) + max(bx, by)
                        delta = ca - cb
                        dist = delta.length()
                        if dist >= min_dist:
                            continue
                        normal = delta / dist if dist > 1e-5 else pygame.Vector2(1, 0)
                        overlap = min_dist - dist
                    correction = normal * (max(0.0, overlap) + 0.05)
                    move_a = a.get("body_type", "dynamic") != "static"
                    move_b = b.get("body_type", "dynamic") != "static"
                    if move_a and move_b:
                        a["pos"] += correction * 0.5
                        b["pos"] -= correction * 0.5
                    elif move_a:
                        a["pos"] += correction
                    elif move_b:
                        b["pos"] -= correction
                    else:
                        continue
                    _moved_any = True
            if not _moved_any:
                break
        for _c in characters:
            _c["_touching_partners"] = set();_ensure_character_motion_after_reset(_c)
    except Exception as e:
        print(f"Reload overlap repair skipped: {e}")

    try:
        _UI_GLYPH_CACHE.clear()
        _PANEL_SURF_CACHE.clear()
        _ICON_CACHE.clear()
    except Exception:
        pass

    # simulation_started and paused were never modified, so a running arena
    # remains running and a deliberately paused arena remains paused.
    state_text = "running" if _was_running and not _was_paused else ("paused" if _was_paused else "ready")
    push_toast(
        f"Reloaded {count} character(s) — movement/collisions preserved ({state_text}).",
        "success", 3.0
    )
    ui_btn_press(None, "reload_chars")

def draw_countdown_overlay(surface, w, h):
    n = get_countdown_number()
