def sanitize_recording_name(name):
    """Make an optional recording label safe for a folder name."""
    cleaned = []
    for ch in str(name or "").strip():
        cleaned.append(ch if ch.isalnum() or ch in (" ", "-", "_") else "_")
    return "".join(cleaned).strip(" ._")[:80]

def _gpu_capture_view_rect(width=None,height=None,source_profile=None):
    """Safe live-capture rectangle; portrait uses the monitor's long edge."""
    width=int(width or WIDTH);height=int(height or HEIGHT)
    safe=pygame.Rect(14,34,max(2,width-28),max(2,height-34-72))
    profile=_gpu_source_profile(source_profile if source_profile is not None else record_gpu_source_profile)
    aw,ah=(virtual_camera_aspect_value() if virtual_camera.get("enabled") else (16,9))
    if ah>aw and _gpu_portrait_capture_rotated(profile):aw,ah=ah,aw
    aspect=aw/max(1.0,float(ah));avail=safe.width/max(1.0,float(safe.height))
    if avail>aspect:
        h=safe.height-(safe.height%2);w=max(2,int(h*aspect));w-=w%2
    else:
        w=safe.width-(safe.width%2);h=max(2,int(w/aspect));h-=h%2
    cap_w,cap_h=_gpu_source_target_size(profile,aspect)
    if cap_w>0 and w>0 and h>0:
        scale=min(1.0,w/max(1.0,float(cap_w)),h/max(1.0,float(cap_h)))
        w=max(2,int(cap_w*scale));h=max(2,int(cap_h*scale));w-=w%2;h-=h%2
    rect=pygame.Rect(0,0,w,h);rect.center=safe.center;return rect

def _record_window_client_region():
    """Physical desktop coordinates of the Pygame client area (Windows)."""
    if os.name!="nt":
        raise RuntimeError("GPU Recording currently requires Windows")
    import ctypes
    from ctypes import wintypes
    info=pygame.display.get_wm_info();hwnd=info.get("window")
    if not hwnd:raise RuntimeError("Could not obtain the Arena Studio window handle")
    rect=wintypes.RECT()
    if not ctypes.windll.user32.GetClientRect(wintypes.HWND(hwnd),ctypes.byref(rect)):
        raise RuntimeError("GetClientRect failed")
    point=wintypes.POINT(0,0)
    if not ctypes.windll.user32.ClientToScreen(wintypes.HWND(hwnd),ctypes.byref(point)):
        raise RuntimeError("ClientToScreen failed")
    width=max(2,int(rect.right-rect.left));height=max(2,int(rect.bottom-rect.top))
    # yuv420p requires even dimensions. Crop at most one edge pixel.
    width-=width%2;height-=height%2
    return int(point.x),int(point.y),width,height


