    if plan.get("backend")=="ddagrab":
        _dda_source=(f"ddagrab=output_idx=0:draw_mouse=0:framerate={max(1,int(record_fps))}:"
                     f"video_size={plan['w']}x{plan['h']}:offset_x={plan['x']}:offset_y={plan['y']}")
        cmd=[plan["ffmpeg"],"-y","-hide_banner","-loglevel","warning","-f","lavfi","-i",_dda_source]
    else:
        cmd=[plan["ffmpeg"],"-y","-hide_banner","-loglevel","warning",
             "-f","gdigrab","-draw_mouse","0","-framerate",str(max(1,int(record_fps))),
             "-thread_queue_size","1024","-rtbufsize","256M",
             "-offset_x",str(plan["x"]),"-offset_y",str(plan["y"]),
             "-video_size",f"{plan['w']}x{plan['h']}","-i","desktop"]
