    if record_mode!="apu":_flush_png_writer()
    if record_mode!="stream":_restore_cpu_recording_ui()
    if record_mode=="apu" and record_states:
        _apu_scale=max(.35,min(1.0,float(_editor_config.get("apu_render_scale",.7071) or .7071)));_apu_rw=max(2,int(round(_out_w*_apu_scale)));_apu_rh=max(2,int(round(_out_h*_apu_scale)));_apu_rw-=_apu_rw%2;_apu_rh-=_apu_rh%2
        # Restore configurable parallel APU reconstruction. Chunk preparation
