        if bool(_editor_config.get("apu_multiprocess_enabled",True)) and len(record_states)>1:
            export_render_job=_start_apu_multiprocess_async(record_dir,record_states,(_out_w,_out_h),record_png_mode)
            _wc=max(2,min(4,int(_editor_config.get("apu_process_workers",2) or 2),len(record_states)))
            _msg=f"preparing {_wc} background render workers"
