# ══════════════════════════════════════════════════════════════════════════
# HP-REACTIVE AESTHETICS  (custom bar decorations)
# Every aesthetic sprite on a custom bar can react to the bar's HP value:
#   • lock        - pin the sprite always-visible / always-hidden, ignoring rules
#   • show_rule   - only draw while the HP comparison is true
#   • blink_rule  - blink (fade or hard on/off) while the HP comparison is true
#   • states      - swap the texture by HP% (e.g. a heart with 4 states)
# Every rule is optional, so old bars keep working exactly as before.
# ══════════════════════════════════════════════════════════════════════════
_AES_OPS = ("below", "below_eq", "above", "above_eq", "equal", "not_equal", "between", "outside")
_AES_OP_LABELS = {"below": "Below", "below_eq": "Below/=", "above": "Above", "above_eq": "Above/=",
                  "equal": "Equal", "not_equal": "Not=", "between": "Between", "outside": "Outside"}

def _spe_aes_norm(item):
    """Fill default HP-reaction fields on an aesthetic dict (in place)."""
    if not isinstance(item, dict):
        return {}
    item.setdefault("lock", "auto")
    sr = item.setdefault("show_rule", {})
    if not isinstance(sr, dict):
        sr = item["show_rule"] = {}
    sr.setdefault("enabled", False); sr.setdefault("unit", "abs")
    sr.setdefault("op", "below");     sr.setdefault("a", 50.0); sr.setdefault("b", 50.0)
    br = item.setdefault("blink_rule", {})
    if not isinstance(br, dict):
        br = item["blink_rule"] = {}
    br.setdefault("enabled", False); br.setdefault("unit", "abs")
    br.setdefault("op", "below");     br.setdefault("a", 50.0); br.setdefault("b", 50.0)
    br.setdefault("speed", 4.0);      br.setdefault("style", "fade"); br.setdefault("duty", 0.5)
    st = item.setdefault("states", [])
    if not isinstance(st, list):
        item["states"] = []
    return item

def _spe_aes_rule_hit(rule, frac, val, mval):
    """True when `rule` matches the current HP. frac = 0..1, val = current
    absolute HP value, mval = max HP. 'pct' rules compare against frac*100,
    'abs' rules against val. Between/Outside are STRICT (a < x < b), so
    'between 0 and 50' means 0 < hp < 50."""
    if not isinstance(rule, dict) or not rule.get("enabled"):
        return False
    x = (frac * 100.0) if rule.get("unit") == "pct" else float(val)
    op = str(rule.get("op", "below"))
    try:
        a = float(rule.get("a", 0.0)); b = float(rule.get("b", 0.0))
    except Exception:
        a, b = 0.0, 0.0
    if op == "below":      return x < a
    if op == "below_eq":   return x <= a
    if op == "above":      return x > a
    if op == "above_eq":   return x >= a
    if op == "equal":      return abs(x - a) < 0.001
    if op == "not_equal":  return abs(x - a) >= 0.001
    if op == "between":    return a < x < b
    if op == "outside":    return x < a or x > b
    return True

def _spe_aes_state_path(item, frac):
    """Pick the active state texture by HP fraction: the state with the
    LOWEST threshold that still covers the current HP wins; when none does
    (full HP) the aesthetic's own main `path` is used."""
    try:
        best = None
        for st in item.get("states", []) or []:
            if isinstance(st, dict) and st.get("path"):
                try:
                    f = float(st.get("frac", 0.0))
                except Exception:
                    f = 0.0
                if frac <= f and (best is None or f < best[0]):
                    best = (f, str(st["path"]))
        if best is not None:
            return best[1]
    except Exception:
        pass
    return str(item.get("path", ""))

def _spe_aes_react(item, frac, val, mval, now):
    """Returns (visible, alpha) for an aesthetic at the current HP.
    Blink only matters while the sprite is visible, so the classic combo
    'visible below 50' + 'blink above 0' gives: blink only for 0 < hp < 50,
    steady at 0, hidden above 50."""
    item = _spe_aes_norm(item)
    lock = str(item.get("lock", "auto"))
    if lock == "hide":
        return False, 0
    sr = item.get("show_rule", {})
    if isinstance(sr, dict) and sr.get("enabled") and not _spe_aes_rule_hit(sr, frac, val, mval):
        if lock != "show":
            return False, 0
    alpha = 255
    br = item.get("blink_rule", {})
    if isinstance(br, dict) and br.get("enabled") and _spe_aes_rule_hit(br, frac, val, mval):
        try:
            sp = max(0.05, float(br.get("speed", 4.0)))
            ph = float(now) * sp
            t = ph - math.floor(ph)
            if str(br.get("style", "fade")) == "hard":
                duty = max(0.05, min(0.95, float(br.get("duty", 0.5))))
                alpha = 255 if t < duty else 0
            else:
                alpha = int(127.5 * (1.0 + math.sin(2.0 * math.pi * ph)))
        except Exception:
            alpha = 255
    return True, alpha

