def anim_layer_length(state, layer):
    durs = anim_layer_durations(state, layer)
    return float(layer.get("start_delay", 0.0)) + sum(max(0.02, float(d)) for d in durs)

def anim_state_total_length(state):
    """Longest track wins; classic states use their flat frame list."""
    layers = anim_layers(state)
    if not layers:
        durs = modal.setdefault("animation_durations", {}).get(state, []) or []
        if durs:
            return sum(max(0.02, float(d)) for d in durs)
        frames = modal.setdefault("animation_frames", {}).get(state, []) or []
        fps = max(0.1, float(modal.setdefault("animation_fps", {}).get(state, 6.0) or 6.0))
        return len(frames) / fps
    return max([anim_layer_length(state, l) for l in layers] or [0.0])

def anim_layer_frame_at(state, layer, t):
    """Which frame index a layer shows at time t (None when not started
    yet, or when a non-looping track has already finished)."""
    frames = layer.get("frames", [])
    if not frames:
        return None
    delay = float(layer.get("start_delay", 0.0))
    local = float(t) - delay
    if local < 0:
        return None
    durs = anim_layer_durations(state, layer)
    total = sum(max(0.02, float(d)) for d in durs)
    if total <= 0:
        return 0
    if local >= total:
        if not layer.get("loop", True):
            return None
        local = local % total
    acc = 0.0
    for i, d in enumerate(durs):
        acc += max(0.02, float(d))
        if local < acc:
            return i
    return len(frames) - 1

