def _character_has_manual_animation_collision(c,state=None):
    state=str(state or c.get("visual_state","idle"));return bool((c.get("animation_collision_frames",{}) or {}).get(state))
def _character_current_frame_index(c,state):
    frames=(c.get("animations",{}) or {}).get(str(state)) or []
    if not frames:return 0
    elapsed=pygame.time.get_ticks()/1000.0-float(c.get("visual_state_started",c.get("spawn_time",0.0)));durs=(c.get("animation_durations",{}) or {}).get(str(state),[]) or [];fps=max(.1,float((c.get("animation_fps",{}) or {}).get(str(state),6) or 6))
