    scale=max(.001,float(c.get("scale",1.0) or 1.0));pivot=(c.get("animation_pivots",{}) or {}).get(state,[0,0]);px=float(pivot[0] if len(pivot)>0 else 0);py=float(pivot[1] if len(pivot)>1 else 0);flipx=bool(c.get("flip_x",False));flipy=_character_effective_flip_y(c);base=pygame.Vector2(c.get("pos",(0,0)));combo=data.get("combo",());key=(round(base.x,5),round(base.y,5),round(scale,5),flipx,flipy,round(px,4),round(py,4),round(_character_collision_angle(c),3),combo)
    if c.get("_active_sprite_boxes_key")==key:return c.get("_active_sprite_collision_boxes",[])
