        if op == "set_layer": em["draw_layer"] = str(kw.get("draw_layer", "front")); em["layer"] = int(kw.get("layer", 0)); return em
        if op == "set_rate": em["rate"] = max(0.0, float(kw.get("rate", 0))); return em
