        if op == "set_force": em["force_x"] = float(kw.get("x", 0)); em["force_y"] = float(kw.get("y", 0)); return em
        if op == "add_force": em["force_x"] = float(em.get("force_x", 0)) + float(kw.get("x", 0)); em["force_y"] = float(em.get("force_y", 0)) + float(kw.get("y", 0)); return em
        if op == "apply_impulse":
            v = self._particle_vec(kw.get("impulse")); pe_apply_impulse(em, v.x, v.y); return em
        if op == "set_wind": em["wind_x"] = float(kw.get("x", 0)); em["wind_y"] = float(kw.get("y", 0)); em["wind_gust"] = max(0.0, float(kw.get("gust", 0))); return em
