        if op == "set_sprite": em["sprite"] = str(kw.get("sprite", "")); em["render"] = "sprite" if em["sprite"] else em.get("render", "circle"); return em
        if op == "set_collision": em["collide_walls"] = bool(kw.get("enabled", False)); em["bounce"] = max(0.0, float(kw.get("bounce", .4))); em["kill_on_hit"] = bool(kw.get("kill", False)); return em
