        if op == "set_attractor_target":
            _aa=em.setdefault("attractors",[]);_idx=int(kw.get("index",0));_tar=self._particle_owner(kw.get("target"),me) if kw.get("target") is not None else None
            if 0<=_idx<len(_aa):_aa[_idx]["target_name"]=str(_tar.get("name","")) if isinstance(_tar,dict) else ""
            return em
