            if op=="flex_condition_exists":return target is not None
            if op=="flex_condition_any":return bool(source)
            if op=="flex_condition_none":return not source
            if op=="flex_condition_count":return len(source)>=int(kw.get("count",1))
            if op=="flex_condition_all":return bool(source) and all(bool(x) for x in source)
            if op=="flex_condition_between":
                try:return float(kw.get("value",0))>=float(kw.get("a",0)) and float(kw.get("value",0))<=float(kw.get("b",0))
                except (TypeError,ValueError):return False
            if op=="flex_condition_not":return not bool(kw.get("a"))
