    def flex_op(self, operation, me, **kw):
        op=str(operation);targets=self._flex_collection(kw.get("source",kw.get("target",me)),me);now=time.time()
        if not targets and op in ("flex_phase_contact_config","flex_phase_contact_disable","flex_phase_contact_damage_now","flex_path_gizmo","flex_path_gizmo_clear") and isinstance(me,dict):targets=[me]
        if op.startswith("flex_shake_"):
            if op=="flex_shake_tag":targets=[c for c in characters if str(kw.get("tag","")) in c.get("tags",set())]
            elif op=="flex_shake_all":targets=list(characters)
            for target in targets:
                if isinstance(target,dict):target["_flex_shake"]={"until":now+float(kw.get("duration",.3)),"strength":float(kw.get("strength",6)),"frequency":float(kw.get("frequency",24)),"axis":str(kw.get("axis","both"))}
            return targets
        if op.startswith("flex_tint_"):
            if op=="flex_tint_tag":targets=[c for c in characters if str(kw.get("tag","")) in c.get("tags",set())]
            color=kw.get("color",[255,80,80]);duration=float(kw.get("duration",.3));alpha=int(kw.get("opacity",140))
            for target in targets:
                if isinstance(target,dict):target["_ns_tint"]={"color":color,"start_time":now,"end_time":now+duration,"flash":bool(kw.get("flash",False)),"interval":.1,"alpha_override":alpha}
            return targets
        if op=="flex_phase_contact_config":
            for t in targets:
                self.configure_phase_contact_damage(t,enabled=kw.get("enabled",True),
                    mode=kw.get("mode","enter"),cooldown=kw.get("cooldown",.35),
                    tag=kw.get("tag",""),only_pass_through=kw.get("only_when_phasing",True),
                    respect_ready=kw.get("respect_ready",False))
            return targets
        if op=="flex_phase_contact_disable":
            for t in targets:
                if isinstance(t,dict):t.pop("_phase_contact_sensor",None);t.pop("_phase_touching_ids",None);t.pop("_phase_touch_targets",None)
            return targets
        if op=="flex_phase_contact_damage_now":
            for t in targets:
                if isinstance(t,dict):
                    for other in list(t.get("_phase_touch_targets",[])):CTX.contact_damage(t,other,require_ready=bool(kw.get("respect_ready",False)))
            return targets
        if op=="flex_path_gizmo":
            for t in targets:
                if isinstance(t,dict):
                    duration=max(0.0,float(kw.get("duration",0)));t["_trajectory_gizmo"]={"enabled":bool(kw.get("enabled",True)),"mode":str(kw.get("mode","predict")),"trail_seconds":max(.1,float(kw.get("trail_seconds",2))),"seconds":max(.05,float(kw.get("seconds",2))),"steps":max(6,int(kw.get("steps",72))),"bounces":max(0,int(kw.get("bounces",4))),"gravity_multiplier":float(kw.get("gravity_multiplier",1)),"color":list(kw.get("color",[80,220,255]))[:3],"thickness":max(1,int(kw.get("thickness",2))),"show_points":bool(kw.get("show_points",True)),"until":now+duration if duration>0 else 0}
            return targets
        if op=="flex_path_gizmo_clear":
            for t in targets:
                if isinstance(t,dict):t.pop("_trajectory_gizmo",None)
            return targets
        if op=="flex_collision_character":
            for t in targets:
                if isinstance(t,dict):t["collision_disabled_until"]=0 if kw.get("enabled",True) else float("inf")
        elif op=="flex_collision_timed":
            for t in targets:self.remove_collisions(t,float(kw.get("duration",1)))
        elif op=="flex_phase_touch_damage":
            for t in targets:
                if isinstance(t,dict):t["_flex_phase_damage"]={"dps":float(kw.get("damage",0)),"tag":str(kw.get("tag","")),"until":now+float(kw.get("duration",1)),"tick":0.0}
        elif op.startswith("flex_weapon_if_"):
            target=kw.get("target") or self.flex_value("flex_select_nearest",me,source=[c for c in characters if c is not me and _is_combat_character(c)],position=me)
            if not isinstance(target,dict):return False
            d=pygame.Vector2(target["pos"])-pygame.Vector2(me["pos"]);radius=float(kw.get("radius",100));matched=d.length()<=radius
            if op.endswith("left"):matched=matched and d.x<0
            elif op.endswith("right"):matched=matched and d.x>0
            elif op.endswith("above"):matched=matched and d.y<0
            elif op.endswith("below"):matched=matched and d.y>0
            if matched:
                # Don't retrigger while a swing/jab/thrust/etc is still mid-motion.
                # Without this guard, calling this node every tick (e.g. "in
                # range" held true across many frames) kept resetting the
                # motion's start time before it could ever animate, so the
                # weapon appeared to just track the aim anchor instead of
                # visibly swinging.
                _wname=str(kw.get("name","main"))
                _rig=self._weapon_rig(me)
                _weapon=_rig["weapons"].get(_wname)
                _cur_motion=_weapon.get("motion") if _weapon else None
                _mid_motion=bool(_cur_motion) and (_sim_now()-_cur_motion.get("start",0))<_cur_motion.get("duration",0)
                if not _mid_motion:
                    swing_kw = {
                        "name": _wname,
                        "distance": kw.get("distance",35),
                        "angle": kw.get("angle",90),
                        "duration": kw.get("duration",.25),
                        "afterimage": kw.get("afterimage",True),
                        "speed": kw.get("speed",1),
                        "easing": kw.get("easing","smoothstep"),
                    }
                    # Forward new timed hitbox parameters if the user wired them
                    if kw.get("hitbox") or kw.get("collider"):
                        swing_kw["hitbox"] = kw.get("hitbox") or kw.get("collider")
                    if "hitbox_start" in kw: swing_kw["hitbox_start"] = kw.get("hitbox_start")
                    if "hitbox_duration" in kw: swing_kw["hitbox_duration"] = kw.get("hitbox_duration")
                    self.weapon_op(str(kw.get("motion","rig_weapon_swing")), me, **swing_kw)
                else:
                    matched=False
            return matched
        elif op=="flex_apply_tag":
            for t in targets:
                if isinstance(t,dict):t.setdefault("tags",set()).add(str(kw.get("tag","")))
        elif op=="flex_remove_tag":
            for t in targets:
                if isinstance(t,dict):t.setdefault("tags",set()).discard(str(kw.get("tag","")))
        elif op=="flex_damage_collection":
            for t in targets:
                if isinstance(t,dict) and float(kw.get("damage",0))>0:self.deal_script_damage(me,t,float(kw["damage"]))
        elif op.startswith("flex_effect_"):
            for t in targets:
                if not isinstance(t,dict):continue
                if op=="flex_effect_opacity":t["_flex_opacity"]=max(0,min(255,int(kw.get("value",255))))
                elif op=="flex_effect_scale":t["scale"]=max(.01,float(kw.get("value",1)))
                elif op=="flex_effect_speed":t["speed"]=float(kw.get("value",t.get("speed",0)))
                elif op=="flex_effect_rotation":t["_flex_facing_angle"]=float(kw.get("value",0))
                elif op=="flex_effect_sprite":t.setdefault("sprite_map",{})["idle"]=str(kw.get("tag",""))
                elif op=="flex_effect_animation":self.set_state(t,str(kw.get("tag","idle")),float(kw.get("duration",.3)))
                elif op=="flex_effect_flash":t["_ns_tint"]={"color":kw.get("color",[255,255,255]),"start_time":now,"end_time":now+float(kw.get("duration",.2)),"flash":True,"interval":.06,"alpha_override":int(kw.get("opacity",180))}
                elif op=="flex_effect_stop_shake":t.pop("_flex_shake",None)
                elif op=="flex_effect_clear_tags":t["tags"]=set()
            if op=="flex_effect_copy_tags" and targets:
                base=set(targets[0].get("tags",set())) if isinstance(targets[0],dict) else set()
                for t in targets[1:]:
                    if isinstance(t,dict):t.setdefault("tags",set()).update(base)
        return targets

    # ── Open weapon / anchor / projectile rig API ───────────────────────
    def _weapon_rig(self, me):
        if not isinstance(me, dict): return {"anchors":{},"visuals":{},"colliders":{},"weapons":{}}
        return me.setdefault("_weapon_rig", {"anchors":{},"visuals":{},"colliders":{},"weapons":{},"events":{},"ammo":{},"last":{}})

    def weapon_value(self, operation, me, **kw):
        rig=self._weapon_rig(me); name=str(kw.get("name",kw.get("anchor","main")))
        if operation in ("rig_position_world","rig_position_tip_world"):
            return _weapon_anchor_world(me,name)
        if operation == "rig_visual_world":
            _visual = rig.get("visuals", {}).get(name, {})
            return _weapon_anchor_world(me, _visual.get("anchor", "main"))
        if operation=="rig_position_angle": return _weapon_anchor_world_angle(me,name)
        if operation=="rig_position_get": return rig["anchors"].get(name)
        if operation=="rig_position_offset": return pygame.Vector2(rig["anchors"].get(name,{}).get("offset",(0,0)))
        if operation=="rig_position_direction": return pygame.Vector2(1,0).rotate(_weapon_anchor_world_angle(me,name))
        def _find_proj(_n=name):
            _exact=kw.get("projectile")
            if isinstance(_exact,dict) and "pos" in _exact:
                return _exact
            if _n and _n != "main":
                _p_hit = rig.get("projectiles", {}).get(_n)
                if _p_hit and _p_hit.get("alive", True): return _p_hit
                for _p_c in reversed(_WEAPON_PROJECTILES):
                    if _p_c.get("owner") is me and _p_c.get("name") == _n and _p_c.get("alive", True):
                        return _p_c
            return rig["last"].get("projectile")
        if operation in ("rig_projectile_last", "rig_projectile_get"): return _find_proj()
        # ── Tether getters ────────────────────────────────────────────────
        if operation.startswith("rig_tether_get_") or operation in ("rig_tether_is_returning","rig_tether_is_locked","rig_tether_is_taut","rig_tether_is_held"):
            _p = _find_proj()
            if not _p: 
                return (pygame.Vector2() if operation.endswith(("_anchor_position",)) else
                        ("" if operation.endswith(("_phase",)) else
                         (False if operation.startswith("rig_tether_is_") else 0.0)))
            if operation=="rig_tether_get_distance":
                try: return float((_tether_anchor_pos(_p) - _p["pos"]).length())
                except Exception: return 0.0
            if operation=="rig_tether_get_max_distance": return float(_p.get("tether_max_distance",0.0) or 0.0)
            if operation=="rig_tether_get_stretch":
                _md=float(_p.get("tether_max_distance",0.0) or 0.0)
                if _md<=0: return 0.0
                try: return max(0.0,min(2.0,float((_tether_anchor_pos(_p)-_p["pos"]).length())/_md))
                except Exception: return 0.0
            if operation=="rig_tether_get_phase": return str(_p.get("_teth_phase","fly") if _p.get("tether_enabled") else "off")
            if operation=="rig_tether_get_anchor_position": return _tether_anchor_pos(_p)
            if operation=="rig_tether_get_lock_target": return _p.get("_teth_lock_target")
            if operation=="rig_tether_is_returning": return str(_p.get("_teth_phase",""))=="return"
            if operation=="rig_tether_is_locked": return str(_p.get("_teth_phase",""))=="lock"
            if operation=="rig_tether_is_held": return str(_p.get("_teth_phase",""))=="held"
            if operation=="rig_tether_is_taut": return bool(_p.get("_teth_taut",False))
        # "Is Tether Returned" = the tether is HOME / not out (caught, held, or
        # no live tether at all = off).  This is exactly the condition the
        # returned launch gate treats as "ready", so it composes with it.  It is
        # the complement of Is Tether Returning (which is "in transit home").
        if operation == "rig_tether_is_returned":
            return str(_tether_live_phase(me, name)) in ("caught", "held", "off")
        # Tether launch-gate getters (read the per-name gate stored on `me`).
        if operation in ("rig_tether_launch_ready", "rig_tether_launch_charge", "rig_tether_launch_cooldown"):
            _gs = _tether_gate_status(me, name)
            if operation == "rig_tether_launch_ready":
                return _gs["ready"]
            if operation == "rig_tether_launch_charge":
                return float(_gs["charges_left"])
            # cooldown remaining (seconds until a launch is allowed again)
            return float(_gs["cooldown_remaining"])
        if operation=="rig_projectile_get_weight":
            _p = _find_proj()
            return float(_p.get("weight", _p.get("drop", _p.get("gravity", 0.0)))) if _p else 0.0
        if operation=="rig_projectile_get_accuracy":
            _p = _find_proj()
            return float(_p.get("accuracy", 100.0)) if _p else 100.0
        if operation=="rig_projectile_get_angle":
            _p = _find_proj()
            return float(_p.get("angle", 0.0)) if _p else 0.0
        if operation=="rig_projectile_get_speed":
            _p = _find_proj()
            return float(_p.get("vel", pygame.Vector2()).length()) if _p else 0.0
        if operation=="rig_projectile_get_position":
            _p=_find_proj();return pygame.Vector2(_p.get("pos",(0,0))) if _p else pygame.Vector2()
        if operation=="rig_projectile_get_velocity":
            _p=_find_proj();return pygame.Vector2(_p.get("vel",(0,0))) if _p else pygame.Vector2()
        if operation=="rig_projectile_get_lifetime":
            _p=_find_proj();return max(0.0,float(_p.get("life",0.0))) if _p else 0.0
        if operation=="rig_projectile_get_destroy_delay":
            _p=_find_proj();return max(0.0,float(_p.get("_destroy_delay",0.0))) if _p else 0.0
        if operation=="rig_projectile_get_bounces":
            _p=_find_proj();return int(_p.get("bounces",0)) if _p else 0
        if operation=="rig_projectile_is_grounded":
            _p=_find_proj();return bool(_p and _p.get("_grounded",False))
        if operation=="rig_projectile_is_sleeping":
            _p=_find_proj();return bool(_p and _p.get("_sleeping",False))
        if operation=="rig_projectile_is_alive":
            _p=_find_proj();return bool(_p and _p.get("alive",True))
        if operation=="rig_projectile_get_name":
            _p=_find_proj();return str(_p.get("name","")) if _p else ""
        # ── Projectile FLIGHT getters ────────────────────────────────────────
        if operation in ("rig_projectile_flight_get", "rig_projectile_flight_state"):
            _p=_find_proj();return _projectile_flight_state(_p) if _p else {"progress":0.0,"eased":0.0,"finished":False,"remaining":0.0,"mode":"straight","speed":0.0,"heading":0.0,"point":pygame.Vector2()}
        if operation=="rig_projectile_flight_progress":
            _p=_find_proj();return _projectile_flight_state(_p)["progress"] if _p else 0.0
        if operation=="rig_projectile_flight_eased":
            _p=_find_proj();return _projectile_flight_state(_p)["eased"] if _p else 0.0
        if operation=="rig_projectile_flight_finished":
            _p=_find_proj();return _projectile_flight_state(_p)["finished"] if _p else False
        if operation=="rig_projectile_flight_remaining":
            _p=_find_proj();return _projectile_flight_state(_p)["remaining"] if _p else 0.0
        if operation=="rig_projectile_flight_mode":
            _p=_find_proj();return _projectile_flight_state(_p)["mode"] if _p else "straight"
        if operation=="rig_projectile_flight_heading":
            _p=_find_proj();return _projectile_flight_state(_p)["heading"] if _p else 0.0
        if operation in ("rig_projectile_flight_speed","rig_projectile_flight_speed_value"):
            _p=_find_proj();return _projectile_flight_state(_p)["speed"] if _p else 0.0
        if operation=="rig_projectile_flight_point":
            _p=_find_proj();return _projectile_flight_state(_p)["point"] if _p else pygame.Vector2()
        if operation=="rig_projectile_flight_phase":
            _p=_find_proj();return _projectile_flight_state(_p)["phase"] if _p else "straight"
        if operation in ("rig_projectile_flight_hold_remaining","rig_projectile_flight_hold_value"):
            _p=_find_proj();return _projectile_flight_hold_remaining(_p) if _p else 0.0
        if operation=="rig_projectile_flight_active":
            _p=_find_proj();return bool(_p and isinstance(_p.get("flight"), dict) and str(_p["flight"].get("mode")) not in ("","straight","off","none")) if _p else False
        if operation=="rig_collider_last": return rig["last"].get("collider")
        if operation=="rig_weapon_last": return rig["last"].get("weapon")
        if operation=="rig_ammo_get": return float(rig["ammo"].get(name,0))
        if operation=="rig_anchor_exists": return name in rig["anchors"]
        if operation=="rig_visual_exists": return name in rig["visuals"]
        if operation=="rig_projectile_count": return sum(1 for p in _WEAPON_PROJECTILES if p.get("owner") is me)

        # NEW: clean normalized progress (0.0 → 1.0) for current swing/motion
        # Use from Visual Scripter (Variable Get or Flex nodes) to drive interpolation
        if operation in ("rig_weapon_progress", "rig_swing_progress", "weapon_progress", "rig_motion_progress"):
            w = rig.get("weapons", {}).get(name)
            if not w or not w.get("motion"):
                return 0.0
            m = w["motion"]
            dur = max(0.001, float(m.get("duration", 0.25)))
            elapsed = max(0.0, time.time() - float(m.get("start", 0)))
            return max(0.0, min(1.0, elapsed / dur))
        return rig["last"].get(operation)

    def weapon_op(self, operation, me, **kw):
        """Composable weapon-rig operation. Visuals/colliders are harmless by
        default: no collision and zero damage until explicit nodes enable it."""
        if not isinstance(me,dict): return None
        rig=self._weapon_rig(me); anchors=rig["anchors"]; visuals=rig["visuals"]; colliders=rig["colliders"]
        name=str(kw.get("name",kw.get("anchor","main")) or "main")
        now=_sim_now()
        # Position events / origins
        if operation == "rig_position_child_create":
            _parent_name = str(kw.get("parent_anchor", "main") or "main")
            _length = float(kw.get("length", 40.0))
            anchors[name] = {"name": name, "tag": str(kw.get("tag", "")),
                "origin": "anchor", "parent": _parent_name,
                "offset": pygame.Vector2(_length, 0),
                "angle": float(kw.get("angle", 0.0)),
                "layer": str(kw.get("layer", "front")), "scale": 1.0,
                "visible": True, "show_gizmo": bool(kw.get("show_gizmo", True)),
                "play_visible": bool(kw.get("play_visible", False)),
                "color": (80, 220, 255), "gizmo_size": 10.0,
                "gizmo_thickness": 2.0, "aim_mode": "fixed"}
            rig["last"]["anchor"] = name
            return anchors[name]
        if operation == "rig_position_orbit_target":
            # Place an anchor on a circle around center and aim it at target.
            # Both center and target are character/object references; unlike
            # the old string-based origin/parent fields they can be wired to
            # Self, Event Other, Find Opponent, etc.
            center = kw.get("center")
            target = kw.get("target")
            center_pos = pygame.Vector2(center.get("pos", me.get("pos", (0, 0)))) if isinstance(center, dict) else pygame.Vector2(me.get("pos", (0, 0)))
            target_pos = pygame.Vector2(target.get("pos", center_pos)) if isinstance(target, dict) else center_pos
            delta = target_pos - center_pos
            if delta.length_squared() > 1e-8:
                direction = delta.normalize()
                radius = max(0.0, float(kw.get("radius", 80.0)))
                anchor = anchors.setdefault(name, {"name": name, "tag": "", "origin": center,
                    "parent": None, "offset": pygame.Vector2(), "angle": 0.0,
                    "layer": "front", "scale": 1.0, "visible": True,
                    "show_gizmo": True, "play_visible": False,
                    "color": (80, 220, 255), "gizmo_size": 10.0,
                    "gizmo_thickness": 2.0, "aim_mode": "fixed"})
                anchor["origin"] = center if isinstance(center, dict) else me
                anchor["parent"] = None
                _desired_offset = direction * radius
                _desired_angle = math.degrees(math.atan2(direction.y, direction.x)) + float(kw.get("angle_offset", 0.0))
                _smooth_time = max(0.0, float(kw.get("smooth_time", 0.18)))
                _progress = max(0.0, min(1.0, float(kw.get("progress", 1.0))))
                _goal_key = id(target) if isinstance(target, dict) else None
                _now = time.time()
                _last = float(anchor.get("_orbit_last_time", _now))
                _odt = max(0.0, min(0.25, _now - _last))
                _target_changed = anchor.get("_orbit_goal_key") != _goal_key
                if _target_changed or _progress <= 0.001 or not anchor.get("_orbit_initialized"):
                    anchor["_orbit_from_offset"] = pygame.Vector2(anchor.get("offset", _desired_offset))
                    anchor["_orbit_from_angle"] = float(anchor.get("angle", _desired_angle))
                    anchor["_orbit_goal_key"] = _goal_key
                _from_offset = pygame.Vector2(anchor.get("_orbit_from_offset", _desired_offset))
                _from_angle = float(anchor.get("_orbit_from_angle", _desired_angle))
                if _progress < 1.0:
                    # A wired Interpolate/Ease output controls this exact
                    # transition. It overrides the automatic smooth-time
                    # blend so custom cubic/sine/quad curves can be used.
                    _blend = _progress
                elif _smooth_time > 0.0 and anchor.get("_orbit_initialized"):
                    _blend = 1.0 - math.exp(-_odt / _smooth_time) if _odt > 0 else 0.0
                    _from_offset = pygame.Vector2(anchor.get("offset", _desired_offset))
                    _from_angle = float(anchor.get("angle", _desired_angle))
                else:
                    _blend = 1.0
                anchor["offset"] = _from_offset + (_desired_offset - _from_offset) * _blend
                _angle_delta = (_desired_angle - _from_angle + 180.0) % 360.0 - 180.0
                anchor["angle"] = _from_angle + _angle_delta * _blend
                anchor["_orbit_last_time"] = _now
                anchor["_orbit_initialized"] = True
                # Keep the bottle upright instead of letting it appear upside
                # down when its aim passes the left-facing half of the circle.
                # Flip the artwork in local space before its rotation.
                if bool(kw.get("keep_upright", True)):
                    _facing = ((anchor["angle"] + 180.0) % 360.0) - 180.0
                    _flip_y = abs(_facing) > 90.0
                    for _visual in visuals.values():
                        if str(_visual.get("anchor", "")) == name:
                            _visual["flip_y"] = _flip_y
                anchor["_orbit_radius"] = radius
                anchor["_orbit_target"] = target
                rig["last"]["anchor"] = name
            return anchors.get(name)
        if operation == "rig_position_orbit":
            # ONE-NODE ORBIT - continuous orbit around center character
            # center=None means self, radius in pixels, speed in deg/sec
            # face_mode: face_center (hilt to center = fan), tangent (helicopter), fixed (no auto rotation)
            center = kw.get("center")
            is_center_dict = isinstance(center, dict)
            # Fallback to owner position if center not supplied
            radius = max(0.0, float(kw.get("radius", 40.0)))
            speed = float(kw.get("speed", kw.get("orbit_speed", 180.0)))
            angle_offset = float(kw.get("angle_offset", 0.0))
            face_mode_raw = str(kw.get("face_mode", kw.get("rotation_mode", "face_center"))).lower()
            # legacy bools
            if "face_center" in kw and isinstance(kw.get("face_center"), bool):
                if kw.get("face_center"):
                    face_mode_raw = "face_center"
            if bool(kw.get("tangent", False)):
                face_mode_raw = "tangent"
            if face_mode_raw in ("false","fixed","none","0",""):
                face_mode = "fixed"
            elif "tangent" in face_mode_raw or "helicopter" in face_mode_raw or "blade" in face_mode_raw:
                face_mode = "tangent"
            elif "center" in face_mode_raw or "face" in face_mode_raw:
                face_mode = "face_center"
            else:
                face_mode = "fixed"

            anchor = anchors.setdefault(name, {"name": name, "tag": str(kw.get("tag","")), "origin": center if is_center_dict else me, "parent": None, "offset": pygame.Vector2(), "angle": 0.0, "layer": "front", "scale":1.0,"visible":True,"show_gizmo":True,"play_visible":False,"color":(80,220,255),"gizmo_size":10.0,"gizmo_thickness":2.0,"aim_mode":"fixed", "_orbit_angle": angle_offset, "_orbit_initialized": False})

            anchor["origin"] = center if is_center_dict else me
            anchor["parent"] = None
            _now = time.time()
            _last = float(anchor.get("_orbit_last_time", _now))
            _dt = max(0.0, min(0.25, _now - _last))
            if not anchor.get("_orbit_initialized"):
                _orbit_angle = angle_offset
            else:
                _orbit_angle = float(anchor.get("_orbit_angle", angle_offset)) + speed * _dt
            if abs(_orbit_angle) > 100000:
                _orbit_angle %= 360.0
            anchor["_orbit_angle"] = _orbit_angle
            anchor["_orbit_last_time"] = _now
            anchor["_orbit_initialized"] = True

            # position: offset from origin by radius rotated by current orbit angle
            _offset_vec = pygame.Vector2(radius, 0).rotate(_orbit_angle)
            anchor["offset"] = _offset_vec

            # rotation: make hilt look natural
            if face_mode == "face_center":
                # anchor points to center -> hilt to center (fan)
                anchor["angle"] = _orbit_angle + 180.0
            elif face_mode == "tangent":
                # blade tangent to circle (helicopter)
                anchor["angle"] = _orbit_angle + 90.0
            else:
                # fixed - don't overwrite angle after first time
                if not anchor.get("_orbit_fixed_angle_set"):
                    anchor["angle"] = float(kw.get("angle", anchor.get("angle",0.0)))
                    anchor["_orbit_fixed_angle_set"] = True

            anchor["_orbit_radius"] = radius
            anchor["_orbit_center"] = center
            anchor["_orbit_face_mode"] = face_mode
            rig["last"]["anchor"] = name
            return anchor
        if operation in ("rig_position_create","rig_position_create_at_position"):
            _world_create=operation=="rig_position_create_at_position"
            if _world_create:
                try:_create_offset=pygame.Vector2(kw.get("position",(0,0)))
                except Exception:_create_offset=pygame.Vector2()
            else:
                _create_offset=pygame.Vector2(float(kw.get("x",0)),float(kw.get("y",0)))
            anchors[name]={"name":name,"tag":str(kw.get("tag","")),
                "origin":None if _world_create else kw.get("origin"),
                "parent":None if _world_create else kw.get("parent"),"offset":_create_offset,
                "world_space":_world_create,
                "angle":float(kw.get("angle",0)),"layer":str(kw.get("layer","front")),"scale":float(kw.get("scale",1)),
                "visible":bool(kw.get("visible",True)),"show_gizmo":bool(kw.get("show_gizmo",True)),"play_visible":bool(kw.get("play_visible",False)),
                "color":tuple(kw.get("color", (80,220,255))),"gizmo_size":float(kw.get("gizmo_size",10)),"gizmo_thickness":float(kw.get("gizmo_thickness",2)),"follow_flip_x":bool(kw.get("follow_flip_x",False)),"follow_flip_y":bool(kw.get("follow_flip_y",False)),"aim_mode":"fixed"}
            rig["last"]["anchor"]=name; return anchors[name]
        if operation=="rig_position_destroy":
            # Remove the anchor plus anything directly attached to it. Leaving
            # orphan colliders/visuals would make an explosion snap back to the
            # character on the following frame.
            anchors.pop(name,None)
            for _vk in [k for k,v in visuals.items() if str(v.get("anchor",""))==name]:visuals.pop(_vk,None)
            for _ck in [k for k,v in colliders.items() if str(v.get("anchor",""))==name]:colliders.pop(_ck,None)
            _removed={name}
            _again=True
            while _again:
                _again=False
