COLOR_SWATCHES_PATH = _cfg_path('settings', 'color_swatches.json')
COLOR_SWATCHES_DEFAULT = [
    [231, 76, 60], [230, 126, 34], [241, 196, 15], [46, 204, 113],
    [26, 188, 156], [52, 152, 219], [155, 89, 182], [52, 73, 94],
    [236, 64, 122], [255, 138, 101], [129, 199, 132], [77, 208, 225],
    [149, 117, 205], [240, 98, 146], [255, 213, 79], [120, 144, 156],
    [255, 255, 255], [192, 192, 192], [128, 128, 128], [0, 0, 0],
    [100, 200, 255], [255, 100, 150], [255, 200, 100], [120, 240, 120]
]
COLOR_SWATCHES = [list(c) for c in COLOR_SWATCHES_DEFAULT]

_COLOR_SWATCHES_LOADED = False
_COLOR_SWATCHES_LOAD_BLOCKED = False

def load_color_swatches():
    global COLOR_SWATCHES, _COLOR_SWATCHES_LOADED, _COLOR_SWATCHES_LOAD_BLOCKED
    data, source = _data_store_read_safe(COLOR_SWATCHES_PATH, "Color Swatches")
    if source == "blocked":
        _COLOR_SWATCHES_LOADED = False
        _COLOR_SWATCHES_LOAD_BLOCKED = True
        return
    _COLOR_SWATCHES_LOAD_BLOCKED = False
    _COLOR_SWATCHES_LOADED = True
    if data is not None and isinstance(data, list) and len(data) > 0:
        COLOR_SWATCHES = [list(c) for c in data if isinstance(c, (list, tuple)) and len(c) >= 3]
def save_color_swatches():
    global COLOR_SWATCHES, _COLOR_SWATCHES_LOADED, _COLOR_SWATCHES_LOAD_BLOCKED
    if _COLOR_SWATCHES_LOAD_BLOCKED:
        print("!! Refusing to save color swatches: last load failed and no backup was usable.")
        return
    if not _COLOR_SWATCHES_LOADED and os.path.exists(COLOR_SWATCHES_PATH):
        COLOR_SWATCHES = _data_store_merge(COLOR_SWATCHES_PATH, COLOR_SWATCHES, "Color Swatches")
        _COLOR_SWATCHES_LOADED = True
    _data_store_write_safe(COLOR_SWATCHES_PATH, COLOR_SWATCHES, "Color Swatches", _COLOR_SWATCHES_LOADED)
def add_color_swatch(col):
    if not col:
        return
    c = [int(v) for v in col[:3]]
    if not any(c == [int(x) for x in sw[:3]] for sw in COLOR_SWATCHES):
        COLOR_SWATCHES.append(c)
        save_color_swatches()

def remove_color_swatch(index):
    if 0 <= index < len(COLOR_SWATCHES):
        COLOR_SWATCHES.pop(index)
        save_color_swatches()

_cp_wheel_cache = {}

def _get_color_wheel_surface(size=200, outer_r=95, inner_r=70):
    key = (size, outer_r, inner_r)
    if key in _cp_wheel_cache:
        return _cp_wheel_cache[key]
    surf = pygame.Surface((size, size), pygame.SRCALPHA)
    cx, cy = size // 2, size // 2
    for y in range(size):
        dy = y - cy
        for x in range(size):
            dx = x - cx
            dist = math.hypot(dx, dy)
            if inner_r <= dist <= outer_r:
                angle = math.atan2(dy, dx) % (2.0 * math.pi)
                hue = angle / (2.0 * math.pi)
                r, g, b = colorsys.hsv_to_rgb(hue, 1.0, 1.0)
                surf.set_at((x, y), (int(r * 255), int(g * 255), int(b * 255), 255))
    _cp_wheel_cache[key] = surf
    return surf

def _get_sat_val_surface(hue, w=80, h=80):
    key = (round(float(hue), 2), w, h)
    cache = modal.get("_cp_sat_val_cache_surf")
    cache_key = modal.get("_cp_sat_val_cache_key")
    if cache is not None and cache_key == key:
        return cache
    surf = pygame.Surface((w, h), pygame.SRCALPHA)
    for y in range(h):
        v = 1.0 - (y / max(1.0, float(h - 1)))
        for x in range(w):
            s = x / max(1.0, float(w - 1))
            r, g, b = colorsys.hsv_to_rgb(hue, s, v)
            surf.set_at((x, y), (int(r * 255), int(g * 255), int(b * 255), 255))
    modal["_cp_sat_val_cache_surf"] = surf
    modal["_cp_sat_val_cache_key"] = key
    return surf

def open_color_picker(initial_color=(255, 255, 255), callback=None, title="Color Picker", allow_alpha=True, return_to=None):
    if not isinstance(initial_color, (list, tuple)) or len(initial_color) < 3:
        initial_color = (255, 255, 255)
    r = max(0, min(255, int(initial_color[0])))
    g = max(0, min(255, int(initial_color[1])))
    b = max(0, min(255, int(initial_color[2])))
    a = max(0, min(255, int(initial_color[3]))) if (len(initial_color) > 3 and allow_alpha) else 255

    import colorsys
    h, s, v = colorsys.rgb_to_hsv(r / 255.0, g / 255.0, b / 255.0)

    load_color_swatches()

    modal["_cp_color"] = [r, g, b, a]
    modal["_cp_initial"] = [r, g, b, a]
    modal["_cp_callback"] = callback
    modal["_cp_title"] = title
    modal["_cp_allow_alpha"] = allow_alpha
    modal["_cp_return_to"] = return_to or (modal.get("type") if modal.get("type") != "color_picker" else None)
    modal["_cp_hue"] = h
    modal["_cp_sat"] = s
    modal["_cp_val"] = v
    modal["_cp_hex"] = f"#{r:02X}{g:02X}{b:02X}"
    modal["_cp_dragging"] = None
    modal["_cp_sat_val_cache_surf"] = None
    modal["_cp_sat_val_cache_key"] = None
    modal["_cp_delete_mode"] = False
    modal["focus"] = None
    modal["type"] = "color_picker"

def _cp_close(cancel=False):
    if cancel and modal.get("_cp_initial") and callable(modal.get("_cp_callback")):
        try:
            modal["_cp_callback"](modal["_cp_initial"])
        except Exception:
            pass
    ret = modal.get("_cp_return_to")
    modal["focus"] = None
    modal["type"] = None if (ret == "main" or ret is None) else ret

def _cp_set_color_rgb(r, g, b, a=None, trigger_cb=True):
    r = max(0, min(255, int(r)))
    g = max(0, min(255, int(g)))
    b = max(0, min(255, int(b)))
    cur_a = modal["_cp_color"][3] if len(modal["_cp_color"]) > 3 else 255
    a = max(0, min(255, int(a))) if a is not None else cur_a
    modal["_cp_color"] = [r, g, b, a]
    import colorsys
    h, s, v = colorsys.rgb_to_hsv(r / 255.0, g / 255.0, b / 255.0)
    modal["_cp_hue"] = h
    modal["_cp_sat"] = s
    modal["_cp_val"] = v
    modal["_cp_hex"] = f"#{r:02X}{g:02X}{b:02X}"
    if trigger_cb and callable(modal.get("_cp_callback")):
        try:
            modal["_cp_callback"](modal["_cp_color"])
        except Exception:
            pass

def _cp_set_color_hsv(h, s, v, a=None, trigger_cb=True):
    h = h % 1.0
    s = max(0.0, min(1.0, float(s)))
    v = max(0.0, min(1.0, float(v)))
    modal["_cp_hue"] = h
    modal["_cp_sat"] = s
    modal["_cp_val"] = v
    import colorsys
    r_f, g_f, b_f = colorsys.hsv_to_rgb(h, s, v)
    r, g, b = int(round(r_f * 255)), int(round(g_f * 255)), int(round(b_f * 255))
    cur_a = modal["_cp_color"][3] if len(modal["_cp_color"]) > 3 else 255
    a = max(0, min(255, int(a))) if a is not None else cur_a
    modal["_cp_color"] = [r, g, b, a]
    modal["_cp_hex"] = f"#{r:02X}{g:02X}{b:02X}"
    if trigger_cb and callable(modal.get("_cp_callback")):
        try:
            modal["_cp_callback"](modal["_cp_color"])
        except Exception:
            pass

def _cp_set_hex_from_input(val):
    modal["_cp_hex"] = val
    clean = val.lstrip("#").strip()
    rgb = None
    if len(clean) == 3:
        clean = "".join(c * 2 for c in clean)
    if len(clean) == 6 and all(c in "0123456789abcdefABCDEF" for c in clean):
        rgb = (int(clean[0:2], 16), int(clean[2:4], 16), int(clean[4:6], 16))
    elif len(clean) == 8 and all(c in "0123456789abcdefABCDEF" for c in clean):
        rgb = (int(clean[0:2], 16), int(clean[2:4], 16), int(clean[4:6], 16), int(clean[6:8], 16))
    if rgb:
        cur_a = modal["_cp_color"][3] if len(modal["_cp_color"]) > 3 else 255
        a = rgb[3] if len(rgb) > 3 else cur_a
        _cp_set_color_rgb(rgb[0], rgb[1], rgb[2], a, trigger_cb=True)

def _cp_render_parent_modal(mouse_pos):
    parent = modal.get("_cp_return_to")
    if parent and parent != "color_picker":
        old_type = modal.get("type")
        modal["type"] = parent
        try:
            fn_map = {
                "asset_creator": "draw_asset_creator",
                "recolor_sprite": "draw_recolor_modal",
                "particle_editor": "draw_particle_editor",
                "motion_studio": "draw_motion_studio",
                "easing_curve_editor": "draw_easing_curve_editor",
                "scene_painter": "draw_scene_painter",
                "character_vault": "draw_character_vault",
                "anim_state_timeline": "draw_anim_state_timeline",
                "asset_library": "draw_asset_library",
                "ui_customization_tool": "draw_ui_customization_tool",
            }
            fn_name = fn_map.get(parent)
            if fn_name and fn_name in globals() and callable(globals()[fn_name]):
                globals()[fn_name](mouse_pos)
        except Exception:
            pass
        finally:
            modal["type"] = old_type

def draw_color_picker_modal(mouse_pos):
    global left_click_this_frame
    if modal.get("type") != "color_picker":
        return
    screen.set_clip(None)
    _cp_render_parent_modal(mouse_pos)
    dim_fullscreen(120)
    f = _UIFrame("_cp")

    if f.key_edge(pygame.K_ESCAPE):
        _cp_close(cancel=True)
        return

    pw, ph = 640, 510
    panel = pygame.Rect((WIDTH - pw) // 2, (HEIGHT - ph) // 2, pw, ph)
    draw_panel(panel, alpha=252, radius=12, shadow=False)

