def open_recolor_modal(rel):
    if not rel:
        return
    modal["_rec_src"] = str(rel)
    modal["_rec_hue"] = 0.0
    modal["_rec_sat"] = 1.0
    modal["_rec_val"] = 1.0
    modal["_rec_colorize_on"] = True
    modal["_rec_color"] = [90, 140, 235]
    modal["_rec_strength"] = 1.0
    modal["_rec_name"] = "blue"
    modal["_rec_cache_key"] = None
    modal["_rec_preview"] = None
    modal["focus"] = None
    modal["type"] = "recolor_sprite"

def _recolor_current():
    rel = modal.get("_rec_src")
    src = load_sprite_asset(rel) if rel else None
    if src is None:
        return None
    hue = float(modal.get("_rec_hue", 0.0))
    sat = float(modal.get("_rec_sat", 1.0))
    val = float(modal.get("_rec_val", 1.0))
    col_on = bool(modal.get("_rec_colorize_on", False))
    col = tuple(modal.get("_rec_color", [0, 0, 0])) if col_on else None
    st = float(modal.get("_rec_strength", 1.0))
    key = (round(hue, 2), round(sat, 2), round(val, 2), col_on,
           tuple(col) if col else None, round(st, 2))
    if modal.get("_rec_cache_key") != key:
        modal["_rec_cache_key"] = key
        modal["_rec_preview"] = recolor_sprite_surface(src, hue, sat, val, col, st)
    return modal.get("_rec_preview")

