def list_imported_audio():
    """Every audio file under audio/_imported/ and audio/, recursively."""
    out = []
    seen = set()
    for d in [IMPORTED_AUDIO_DIR, AUDIO_DIR]:
        if not os.path.isdir(d):
            continue
        for root, _dirs, files in os.walk(d):
            for fname in files:
                if fname.lower().endswith((".wav", ".ogg", ".mp3", ".flac", ".aiff", ".aif")):
                    rel = os.path.relpath(os.path.join(root, fname), BASE_DIR).replace(os.sep, "/")
                    if rel not in seen:
                        seen.add(rel)
                        out.append(rel)
    return sorted(out)

def _sprite_is_pixelart(surf):
    """Heuristic: a sprite is treated as pixel art (and should render with
    crisp nearest-neighbour scaling instead of blurry smooth interpolation)
    when it is small, or small-ish with a limited palette. Big painted art
    stays smooth. This is why a 12px Terraria sword imports crisp while a
    1024px character portrait stays anti-aliased."""
    if surf is None:
        return False
    try:
        w, h = surf.get_size()
        mx = max(w, h)
        if mx <= 96:
            return True
        if mx <= 256:
            arr = np.asarray(pygame.surfarray.array3d(surf))
            step = max(1, mx // 48)
            sub = arr[::step, ::step].reshape(-1, 3)
            if sub.shape[0] > 6000:
                sub = sub[:: sub.shape[0] // 6000 + 1]
            uniq = int(np.unique(sub, axis=0).shape[0])
            return uniq <= 128
    except Exception:
        pass
    return False

def load_sprite_asset(rel_path):
    """Loads (and caches) a single sprite by its path relative to
    sprites/, e.g. 'ant_queen/sting.png'."""
    if not rel_path:
        return None
    if rel_path in _asset_cache and _asset_cache.get(rel_path) is not None:
        return _asset_cache[rel_path]
    _asset_cache.pop(rel_path,None)
    full = os.path.join(SPRITES_DIR, rel_path.replace("/", os.sep))
    img = None
    if os.path.isfile(full):
        try:
            img = pygame.image.load(full).convert_alpha()
        except Exception as e:
            print(f"Could not load sprite asset '{rel_path}':", e)
    if img is not None:_asset_cache[rel_path]=img
    else:_asset_cache.pop(rel_path,None)
    return img

def import_sprite_from_disk():
    """Opens a native file picker (works even if the PNG lives nowhere
    near this project) and copies the chosen image into
    sprites/exports/, so it becomes a normal library asset. Returns
    the new relative path, or None if the user cancelled / it failed."""
    import shutil
    try:
        import tkinter as tk
        from tkinter import filedialog
    except Exception as e:
        print("Could not open file picker (tkinter unavailable):", e)
        return None
    try:
        root = tk.Tk()
        root.withdraw()
        root.attributes("-topmost", True)
        path = filedialog.askopenfilename(
            title="Choose a sprite PNG",
            filetypes=[("PNG image", "*.png"), ("All files", "*.*")],
        )
        root.destroy()
    except Exception as e:
        print("File picker failed:", e)
        return None
    if not path:
        return None
    os.makedirs(IMPORTED_SPRITES_DIR, exist_ok=True)
    base = os.path.basename(path)
    dest = os.path.join(IMPORTED_SPRITES_DIR, base)
    stem, ext = os.path.splitext(base)
    n = 1
    while os.path.exists(dest) and not os.path.samefile(path, dest) if os.path.exists(dest) else False:
        dest = os.path.join(IMPORTED_SPRITES_DIR, f"{stem}_{n}{ext}")
        n += 1
    try:
        if not os.path.exists(dest):
            shutil.copyfile(path, dest)
        rel = os.path.relpath(dest, SPRITES_DIR).replace(os.sep, "/")
        _asset_cache.pop(rel, None)
        invalidate_sprite_asset_cache()
        return rel
    except Exception as e:
        print("Could not import sprite:", e)
        return None

AUDIO_EVENTS = ["spawn", "attack", "hit", "damage_taken", "death", "wall_bounce"]
GLOBAL_AUDIO_EVENTS = ["game_end", "background_music"]
AUDIO_EXTS = (".wav", ".ogg", ".mp3", ".flac", ".aiff", ".aif")
_sound_cache = {}
# Audio Library: imported files stay project-local; metadata (names, tags and
# reusable FX presets) lives beside the project and is safe to version-control.
AUDIO_LIBRARY_PATH = _cfg_path('audio', 'audio_library.json')
AUDIO_LIBRARY = []

def _prune_audio_library():
    """Drop registry entries whose file no longer exists on disk (e.g. files
    deleted manually in Explorer/Finder). Keeps the library mirroring what is
    actually in the folders. No-op before abs_from_base is defined (import
    order); refresh_audio_library_files() prunes every scan."""
    global AUDIO_LIBRARY
    _abs = globals().get("abs_from_base")
    if _abs is None:
        return 0
    before = len(AUDIO_LIBRARY)
    keep = []
    for x in AUDIO_LIBRARY:
        try:
            p = str(x.get("path", "") or "")
            if not p:
                continue
            full = _abs(p)
            if full and os.path.isfile(full):
                keep.append(x)
        except Exception:
            keep.append(x)
    removed = before - len(keep)
    if removed:
        AUDIO_LIBRARY = keep
        try:
            save_audio_library()
        except Exception:
            pass
        globals()["_last_audio_prune_count"] = removed
    return removed

_AUDIO_LIBRARY_LOADED = False
_AUDIO_LIBRARY_LOAD_BLOCKED = False

def load_audio_library():
    global AUDIO_LIBRARY, _AUDIO_LIBRARY_LOADED, _AUDIO_LIBRARY_LOAD_BLOCKED
    data, source = _data_store_read_safe(AUDIO_LIBRARY_PATH, "Audio Library")
    if source == "blocked":
        _AUDIO_LIBRARY_LOADED = False
        _AUDIO_LIBRARY_LOAD_BLOCKED = True
        return
    _AUDIO_LIBRARY_LOAD_BLOCKED = False
    _AUDIO_LIBRARY_LOADED = True
    if data is not None:
        AUDIO_LIBRARY = data if isinstance(data, list) else []
    else:
        AUDIO_LIBRARY = []
    # Repair historical duplicate cards where one entry used C:/.../project/audio
    # and another used audio/... for the exact same file.
    _dedup=[];_seen=set();_changed=False
    for _entry in AUDIO_LIBRARY:
        if not isinstance(_entry,dict):_changed=True;continue
        _entry=dict(_entry);_old=str(_entry.get("path","") or "");_entry["path"]=_canonical_audio_library_path(_old);_ident=_audio_path_identity(_entry["path"])
        if not _ident or _ident in _seen:_changed=True;continue
        _seen.add(_ident);_changed=_changed or (_entry["path"]!=_old);_dedup.append(_entry)
    AUDIO_LIBRARY=_dedup
    _prune_audio_library()
    if _changed:
        try:save_audio_library()
        except Exception:pass
def save_audio_library():
    global AUDIO_LIBRARY, _AUDIO_LIBRARY_LOADED, _AUDIO_LIBRARY_LOAD_BLOCKED
    if _AUDIO_LIBRARY_LOAD_BLOCKED:
        print("!! Refusing to save audio library: last load failed and no backup was usable.")
        try:
            push_toast("Audio-library save skipped - restore a backup first (see console).", "warning", 5.0)
        except Exception:
            pass
        return
    if not _AUDIO_LIBRARY_LOADED and os.path.isfile(AUDIO_LIBRARY_PATH):
        AUDIO_LIBRARY = _data_store_merge(AUDIO_LIBRARY_PATH, AUDIO_LIBRARY, "Audio Library")
        _AUDIO_LIBRARY_LOADED = True
    _data_store_write_safe(AUDIO_LIBRARY_PATH, AUDIO_LIBRARY, "Audio Library", _AUDIO_LIBRARY_LOADED)
def _canonical_audio_library_path(path):
    """One stable spelling per file. Absolute paths inside the project become
    BASE_DIR-relative, preventing Preview from registering a second card."""
    raw=str(path or "").strip()
    if not raw:return ""
    try:
        if os.path.isabs(raw):
            ap=os.path.abspath(raw);base=os.path.abspath(BASE_DIR)
            if os.path.commonpath((ap,base))==base:raw=os.path.relpath(ap,base)
    except Exception:pass
    return raw.replace("\\","/")

def _audio_path_identity(path):
    pth=_canonical_audio_library_path(path)
    try:return os.path.normcase(os.path.abspath(abs_from_base(pth) if not os.path.isabs(pth) else pth))
    except Exception:return os.path.normcase(pth)

def audio_library_entry(path):
    ident=_audio_path_identity(path)
    return next((x for x in AUDIO_LIBRARY if _audio_path_identity(x.get("path"))==ident),None)

def register_audio_asset(path, name=None):
    """Add an imported sound once, regardless of absolute/relative spelling."""
    path=_canonical_audio_library_path(path)
    if not path:return None
    item=audio_library_entry(path)
    if item:return item
    item = {"id": hashlib.sha1(path.encode("utf-8")).hexdigest()[:12],
            "name": name or os.path.splitext(os.path.basename(path))[0],
            "path": path, "tags": [], "effects": [], "created": time.time()}
    AUDIO_LIBRARY.append(item); save_audio_library()
    return item

def delete_audio_asset(asset_id):
    """Remove metadata only. The source remains safely in audio/_imported."""
    global AUDIO_LIBRARY
    AUDIO_LIBRARY = [x for x in AUDIO_LIBRARY if x.get("id") != asset_id]
    save_audio_library(); return True

def audio_library_folders():
    """Real folder tree entries from audio/_imported; no demo categories."""
    found = [""]
    if os.path.isdir(IMPORTED_AUDIO_DIR):
        for root, dirs, _files in os.walk(IMPORTED_AUDIO_DIR):
            dirs[:] = [d for d in dirs if not d.startswith(".")]
            rel = os.path.relpath(root, IMPORTED_AUDIO_DIR).replace(os.sep, "/")
            if rel != "." and rel not in found: found.append(rel)
    return sorted(found, key=lambda v: (v.count("/"), v.lower()))

def refresh_audio_library_files():
    """Rescan audio/_imported without restarting the editor. Picks up files
    copied in by Explorer/Finder as well as newly imported sounds, and drops
    entries for files deleted outside the app."""
    os.makedirs(IMPORTED_AUDIO_DIR, exist_ok=True)
    added = 0
    globals()["_last_audio_prune_count"] = _prune_audio_library()
    try:
        # Scan audio/_imported recursively *and* the rest of audio/, matching
        # the node dropdown's file discovery. Folder organization is welcome.
        for path in list_imported_audio():
            if audio_library_entry(path) is None:
                register_audio_asset(path); added += 1
    except Exception as e:
        push_toast(f"Could not refresh audio files: {e}", "error")
        return 0
    # Force sound + node/palette UI to consult the filesystem next draw.
    _sound_cache.clear()
    return added

def _audio_safe_folder(folder):
    folder = str(folder or "").strip().replace("\\", "/")
    parts = [re.sub(r"[^A-Za-z0-9 _.-]", "_", x).strip() for x in folder.split("/")]
    parts = [x for x in parts if x not in ("", ".", "..")]
    return "/".join(parts[:4])

def _audio_replace_path_everywhere(old_path, new_path):
    """Keep character cues working after an Audio Library rename/move."""
    for collection in (LIBRARY, characters):
        for item in collection:
            amap = item.get("audio_map", {}) if isinstance(item, dict) else {}
            for cue, path in list(amap.items()):
                if path == old_path: amap[cue] = new_path
    for asset in AUDIO_LIBRARY:
        if asset.get("path") == old_path: asset["path"] = new_path
    _sound_cache.clear()

def audio_library_rename(asset, display_name):
    display_name = re.sub(r"[^A-Za-z0-9 _.-]", "_", str(display_name or "").strip())[:80]
    if not display_name: raise ValueError("Name cannot be empty.")
    old = asset.get("path", ""); ext = os.path.splitext(old)[1]
    full_old = abs_from_base(old)
    if not full_old or not os.path.isfile(full_old): raise ValueError("Audio file is missing on disk.")
    new_file = display_name + ext
    full_new = os.path.join(os.path.dirname(full_old), new_file)
    if os.path.normcase(full_new) != os.path.normcase(full_old) and os.path.exists(full_new):
        raise ValueError("A sound with that filename already exists in this folder.")
    os.rename(full_old, full_new)
    new_path = rel_to_base(full_new)
    _audio_replace_path_everywhere(old, new_path)
    asset["name"] = display_name
    save_audio_library()

def audio_library_move(asset, folder):
    folder = _audio_safe_folder(folder)
    old = asset.get("path", ""); full_old = abs_from_base(old)
    if not full_old or not os.path.isfile(full_old): raise ValueError("Audio file is missing on disk.")
    dest_dir = os.path.join(IMPORTED_AUDIO_DIR, *folder.split("/")) if folder else IMPORTED_AUDIO_DIR
    os.makedirs(dest_dir, exist_ok=True)
    full_new = os.path.join(dest_dir, os.path.basename(full_old))
    if os.path.normcase(full_new) != os.path.normcase(full_old) and os.path.exists(full_new):
        raise ValueError("That folder already contains a file with this name.")
    shutil.move(full_old, full_new)
    _audio_replace_path_everywhere(old, rel_to_base(full_new))
    asset["folder"] = folder
    save_audio_library()

def open_audio_rename_dialog(asset):
    def done(value):
        try: audio_library_rename(asset, value); push_toast("Audio renamed and cue paths updated.", "success")
        except Exception as e: push_toast(str(e), "error")
        modal["type"] = None
    modal.update({"type":"text_input_modal", "text_input_title":"Rename Audio Asset",
                  "text_input_label":"New filename (extension is kept):", "text_input_value":asset.get("name", ""),
                  "focus":"text_input_value", "text_input_callback":done, "text_input_cancel_callback":lambda: modal.update({"type":None, "focus":None})})

def audio_library_rename_folder(folder_key, new_leaf):
    """Rename a folder under audio/_imported and re-point every asset + cue
    path that lived beneath it (files and subfolders move on disk too)."""
    new_leaf = re.sub(r"[^A-Za-z0-9 _.-]", "_", str(new_leaf or "").strip())
    if not new_leaf:
        raise ValueError("Name cannot be empty.")
    folder_key = str(folder_key or "").strip().strip("/")
    if not folder_key:
        raise ValueError("Cannot rename the root folder.")
    parts = folder_key.split("/")
    parent_key = "/".join(parts[:-1]) if len(parts) > 1 else ""
    new_key = (parent_key + "/" + new_leaf) if parent_key else new_leaf
    old_dir = os.path.join(IMPORTED_AUDIO_DIR, *folder_key.split("/"))
    new_dir = os.path.join(IMPORTED_AUDIO_DIR, *new_key.split("/"))
    if not os.path.isdir(old_dir):
        raise ValueError("Folder not found on disk.")
    if os.path.exists(new_dir):
        raise ValueError("A folder with that name already exists here.")
    os.rename(old_dir, new_dir)
    old_rel = "audio/_imported/" + folder_key
    new_rel = "audio/_imported/" + new_key
    for asset in AUDIO_LIBRARY:
        p = str(asset.get("path", ""))
        if p.startswith(old_rel + "/"):
            asset["path"] = new_rel + p[len(old_rel):]
    for collection in (LIBRARY, characters):
        for item in collection:
            amap = item.get("audio_map", {}) if isinstance(item, dict) else {}
            for cue, path in list(amap.items()):
                if str(path).startswith(old_rel + "/"):
                    amap[cue] = new_rel + str(path)[len(old_rel):]
    save_audio_library()
    _sound_cache.clear()

def audio_library_delete_folder(folder_key):
    """Delete a folder under audio/_imported: every file inside is moved up
    to the parent (or root) so no sound is lost, then the empty dirs are
    removed. Cue paths are re-pointed automatically."""
    folder_key = str(folder_key or "").strip().strip("/")
    if not folder_key:
        raise ValueError("Cannot delete the root folder.")
    base = os.path.join(IMPORTED_AUDIO_DIR, *folder_key.split("/"))
    if not os.path.isdir(base):
        raise ValueError("Folder not found on disk.")
    parts = folder_key.split("/")
    parent_key = "/".join(parts[:-1]) if len(parts) > 1 else ""
    parent_dir = os.path.join(IMPORTED_AUDIO_DIR, *parent_key.split("/")) if parent_key else IMPORTED_AUDIO_DIR
    os.makedirs(parent_dir, exist_ok=True)
    renames = []
    moved = 0
    for root, _dirs, files in os.walk(base):
        for fname in files:
            src = os.path.join(root, fname)
            dst = os.path.join(parent_dir, fname)
            if os.path.normcase(src) != os.path.normcase(dst):
                if os.path.exists(dst):
                    stem, ext = os.path.splitext(fname)
                    n = 1
                    while os.path.exists(os.path.join(parent_dir, f"{stem}_{n}{ext}")):
                        n += 1
                    dst = os.path.join(parent_dir, f"{stem}_{n}{ext}")
                shutil.move(src, dst)
                renames.append((rel_to_base(src), rel_to_base(dst)))
                moved += 1
    for old_p, new_p in renames:
        _audio_replace_path_everywhere(old_p, new_p)
    shutil.rmtree(base, ignore_errors=True)
    save_audio_library()
    return moved

