def audio_effect_chain(value):
    """Normalize an effect chain from a node/property/library entry."""
    if isinstance(value, str):
        presets = {
            "clean": [],
            "echo": [{"type":"echo", "delay_ms":180, "feedback":0.38, "mix":0.42}],
            "retro": [{"type":"bitcrush", "bits":6, "rate":8000, "mix":1.0}],
            "lofi": [{"type":"bitcrush", "bits":8, "rate":11025, "mix":0.7}, {"type":"echo", "delay_ms":95, "feedback":0.18, "mix":0.18}],
        }
        return presets.get(value.lower(), [])
    return value if isinstance(value, list) else []

def load_effect_sound(path, effects=None):
    """Offline NumPy FX for playback. Echo and bit-crush are deliberately
    rendered before play, so every Audio node and ordinary cue uses identical
    sound. Pygame has no real-time DSP graph, hence this predictable approach."""
    chain = audio_effect_chain(effects)
    if not chain: return load_sound(path)
    key = ("fx", path, json.dumps(chain, sort_keys=True))
    if key in _sound_cache: return _sound_cache[key]
    source = load_sound(path)
    if source is None: return None
    try:
        arr = pygame.sndarray.array(source)
        dtype = arr.dtype; limit = float(max(abs(np.iinfo(dtype).min), np.iinfo(dtype).max)) if np.issubdtype(dtype, np.integer) else 1.0
        work = arr.astype(np.float32) / limit
        if work.ndim == 1: work = work[:, None]
        sample_rate = max(8000, int(pygame.mixer.get_init()[0] or 44100))
        for fx in chain:
            if not isinstance(fx, dict): continue
            kind = str(fx.get("type", "")).lower(); mix = max(0., min(1., float(fx.get("mix", 1))))
            if kind == "echo":
                delay = max(1, int(sample_rate * float(fx.get("delay_ms", 180)) / 1000))
                feedback = max(0., min(.95, float(fx.get("feedback", .35))))
                wet = work.copy()
                for i in range(delay, len(wet)): wet[i] += wet[i-delay] * feedback
                work = work*(1-mix) + wet*mix
            elif kind in ("bitcrush", "retro"):
                bits = max(2, min(16, int(fx.get("bits", 6))))
                rate = max(1000, min(sample_rate, int(fx.get("rate", 8000))))
                step = max(1, int(sample_rate / rate)); wet = work.copy()
                wet = np.round(wet * (2**(bits-1))) / float(2**(bits-1))
                wet = np.repeat(wet[::step], step, axis=0)[:len(work)]
                if len(wet) < len(work): wet = np.vstack((wet, np.repeat(wet[-1:], len(work)-len(wet), axis=0)))
                work = work*(1-mix) + wet*mix
        out = np.clip(work, -1, 1)
        out = (out * limit).astype(dtype)
        if arr.ndim == 1: out = out[:,0]
        snd = pygame.sndarray.make_sound(np.ascontiguousarray(out))
    except Exception as e:
        print("Audio FX fallback:", e); snd = source
    _sound_cache[key] = snd
    return snd

