def _file_hash(path):
    try:
        h = hashlib.sha1()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return None

def import_audio_from_disk():
    """Import an audio cue into audio/_imported and return a BASE_DIR-relative path.

    UPGRADED: You can now pick from ANYWHERE on your desktop/laptop (Desktop, Downloads, etc).
    The file is automatically cached into audio/_imported so previews and exports keep working.
    Supports multi-select, remembers last folder, and uses a cache JSON to avoid duplicates.

    If a file already sitting in audio/_imported has the same name AND the
    same content, that existing file is reused instead of making a
    numbered duplicate (hit_1.wav, hit_2.wav, ...). A same-named file with
    *different* content still gets a numbered copy, since it's genuinely
    a different sound.
    """
    # === helpers for anywhere import ===
    def _get_desktop():
        # Try common desktop locations
        try:
            home = os.path.expanduser("~")
            for cand in [os.path.join(home, "Desktop"), os.path.join(home, "OneDrive", "Desktop"), os.path.join(home, "Downloads"), home]:
                if os.path.isdir(cand):
                    return cand
        except Exception:
            pass
        return BASE_DIR

    def _get_last_audio_dir():
        try:
            cache_path = EDITOR_CONFIG_PATH
            if os.path.isfile(cache_path):
                with open(cache_path, "r") as f:
                    cfg = json.load(f)
                    ld = cfg.get("last_audio_import_dir")
                    if ld and os.path.isdir(ld):
                        return ld
        except Exception:
            pass
        return _get_desktop()

    def _save_last_audio_dir(d):
        try:
            cfg_path = EDITOR_CONFIG_PATH
            cfg = {}
            if os.path.isfile(cfg_path):
                try:
                    with open(cfg_path, "r") as f:
                        cfg = json.load(f)
                except Exception:
                    cfg = {}
            cfg["last_audio_import_dir"] = d
            with open(cfg_path, "w") as f:
                json.dump(cfg, f, indent=2)
        except Exception:
            pass

    # Use the new central importer that handles caching
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
        initial = _get_last_audio_dir()
        # Allow multi-select so you can import many sounds at once from anywhere
        paths = filedialog.askopenfilenames(
            title="Choose audio cues from anywhere (Desktop, Downloads, etc) - will be cached to audio/_imported",
            initialdir=initial,
            filetypes=[("Audio files", "*.wav *.ogg *.mp3 *.flac *.aiff *.aif *.m4a"), ("All files", "*.*")],
        )
        root.destroy()
        # askopenfilenames returns tuple
        if not paths:
            return None
        # Normalize to list
        if isinstance(paths, str):
            paths = (paths,)
    except Exception as e:
        print("Audio picker failed:", e)
        return None

    imported = []
    for p in paths:
        try:
            rel = import_audio_from_absolute_path(p)
            if rel:
                imported.append(rel)
        except Exception as e:
            print(f"Failed to import {p}:", e)

    # remember last dir
    try:
        if paths:
            _save_last_audio_dir(os.path.dirname(os.path.abspath(paths[0])))
    except Exception:
        pass

    if not imported:
        return None
    # return first for backward compat, but we imported all
    if len(imported) == 1:
        return imported[0]
    return imported[0]  # first, others are still cached and show in library

# === NEW CENTRAL CACHE SYSTEM ===
AUDIO_IMPORT_CACHE_PATH = _cfg_path("audio", "audio_import_cache.json")
_AUDIO_IMPORT_CACHE = None

def _load_audio_import_cache():
    global _AUDIO_IMPORT_CACHE
    if _AUDIO_IMPORT_CACHE is not None:
        return _AUDIO_IMPORT_CACHE
    try:
        if os.path.isfile(AUDIO_IMPORT_CACHE_PATH):
            with open(AUDIO_IMPORT_CACHE_PATH, "r", encoding="utf-8") as f:
                _AUDIO_IMPORT_CACHE = json.load(f)
                if not isinstance(_AUDIO_IMPORT_CACHE, dict):
                    _AUDIO_IMPORT_CACHE = {}
                return _AUDIO_IMPORT_CACHE
    except Exception:
        pass
    _AUDIO_IMPORT_CACHE = {}
    return _AUDIO_IMPORT_CACHE

def _save_audio_import_cache():
    try:
        with open(AUDIO_IMPORT_CACHE_PATH, "w", encoding="utf-8") as f:
            json.dump(_AUDIO_IMPORT_CACHE or {}, f, indent=2)
    except Exception as e:
        print("Could not save audio cache:", e)

_DISK_AUDIO_SEARCH_CACHE = {}
_DISK_AUDIO_LAST_SEARCH = {"query": "", "results": [], "time": 0}

def _get_common_audio_roots():
    roots = []
    try:
        home = os.path.expanduser("~")
        candidates = [
            os.path.join(home, "Desktop"),
            os.path.join(home, "OneDrive", "Desktop"),
            os.path.join(home, "Downloads"),
            os.path.join(home, "Documents"),
            os.path.join(home, "Music"),
            os.path.join(home, "Videos"),
            BASE_DIR,
        ]
        for c in candidates:
            if c and os.path.isdir(c) and c not in roots:
                roots.append(c)
    except Exception:
        pass
    return roots

def search_audio_files_on_disk(query, max_results=40, max_depth=3):
    if not query:
        return []
    q = str(query).lower().strip()
    if len(q) < 2:
        return []
    try:
        now = time.time()
        if _DISK_AUDIO_LAST_SEARCH.get("query") == q and now - _DISK_AUDIO_LAST_SEARCH.get("time", 0) < 5:
            return _DISK_AUDIO_LAST_SEARCH.get("results", [])[:max_results]
    except Exception:
        pass
    results = []
    roots = _get_common_audio_roots()
    for root in roots:
        try:
            for r, dirs, files in os.walk(root):
                rel_depth = r[len(root):].count(os.sep)
                if rel_depth > max_depth:
                    dirs[:] = []
                    continue
                dirs[:] = [d for d in dirs if not d.startswith('.') and d.lower() not in ('node_modules', '__pycache__', '.git', 'appdata', 'application data')]
                for fname in files:
                    if len(results) >= max_results:
                        break
                    low = fname.lower()
                    if not low.endswith(('.wav','.ogg','.mp3','.flac','.aiff','.aif','.m4a')):
                        continue
                    if q in low:
                        full = os.path.join(r, fname)
                        results.append(full)
                if len(results) >= max_results:
                    break
        except Exception:
            continue
        if len(results) >= max_results:
            break
    try:
        _DISK_AUDIO_LAST_SEARCH["query"] = q
        _DISK_AUDIO_LAST_SEARCH["results"] = list(results)
        _DISK_AUDIO_LAST_SEARCH["time"] = time.time()
    except Exception:
        pass
    return results[:max_results]

def import_audio_from_absolute_path(abs_path):
    """Core function: take ANY absolute path on your computer, copy to audio/_imported cache, and return rel path.

    This is what makes 'import from anywhere' work:
    - You pick C:/Users/You/Desktop/my_sound.wav
    - It gets copied to audio/_imported/my_sound.wav (or my_sound_1.wav if duplicate)
    - Cache JSON remembers original -> cached mapping
    - Returns audio/_imported/my_sound.wav so previews work
    - No need to manually copy to import folder ever again
    """
    if not abs_path or not os.path.isfile(abs_path):
        return None
    try:
        os.makedirs(IMPORTED_AUDIO_DIR, exist_ok=True)
        base = os.path.basename(abs_path)
        stem, ext = os.path.splitext(base)
        if ext.lower() not in AUDIO_EXTS:
            ext = ".wav"
        src_hash = _file_hash(abs_path)

        # Check cache first: same abs path + same hash -> reuse
        cache = _load_audio_import_cache()
        cache_key = os.path.abspath(abs_path)
        cached_entry = cache.get(cache_key)
        if cached_entry and isinstance(cached_entry, dict):
            cached_rel = cached_entry.get("cached_path")
            cached_hash = cached_entry.get("hash")
            if cached_rel and src_hash and cached_hash == src_hash:
                full_cached = os.path.join(BASE_DIR, cached_rel.replace("/", os.sep))
                if os.path.isfile(full_cached):
                    # cache hit, reuse
                    try:
                        register_audio_asset(cached_rel)
                    except Exception:
                        pass
                    return cached_rel

        dest = os.path.join(IMPORTED_AUDIO_DIR, stem + ext)
        n = 1
        while os.path.exists(dest):
            if os.path.abspath(dest) == os.path.abspath(abs_path):
                break
            if src_hash is not None and src_hash == _file_hash(dest):
                rel = rel_to_base(dest) if "rel_to_base" in globals() else dest
                # save cache
                try:
                    cache[cache_key] = {"cached_path": rel, "hash": src_hash, "original": abs_path, "timestamp": time.time()}
                    _save_audio_import_cache()
                    register_audio_asset(rel)
                except Exception:
                    pass
                return rel
            dest = os.path.join(IMPORTED_AUDIO_DIR, f"{stem}_{n}{ext}")
            n += 1
        if not os.path.exists(dest):
            shutil.copyfile(abs_path, dest)
        rel = rel_to_base(dest) if "rel_to_base" in globals() else dest
        # save to cache
        try:
            cache[cache_key] = {"cached_path": rel, "hash": src_hash, "original": abs_path, "timestamp": time.time()}
            _save_audio_import_cache()
        except Exception:
            pass
        try:
            register_audio_asset(rel)
        except Exception:
            pass
        return rel
    except Exception as e:
        print("Could not import audio from", abs_path, ":", e)
        return None

def resolve_audio_path(path):
    """If path is absolute and exists, auto-import it to cache and return cached rel path.
    If relative, return as-is. This lets you paste C:/.../sound.wav anywhere and it just works."""
    if not path:
        return path
    try:
        # absolute path on disk?
        if os.path.isabs(path) and os.path.isfile(path):
            cached = import_audio_from_absolute_path(path)
            return cached or path
        # also handle Desktop-style paths that may be typed with forward slashes
        # try expanduser and check existence
        expanded = os.path.expanduser(path)
        if os.path.isfile(expanded) and os.path.isabs(expanded):
            cached = import_audio_from_absolute_path(expanded)
            return cached or path
    except Exception as e:
        print("resolve_audio_path failed:", e)
    return path

def load_sound(path):
    """Loads (and caches) a sound by its path relative to BASE_DIR
    (e.g. 'audio/_imported/hit.wav'), mirroring load_sprite_asset.
    UPGRADED: If you pass an absolute desktop path like C:/Users/You/Desktop/hit.wav,
    it will auto-import to audio/_imported cache and load from there."""
    if not AUDIO_AVAILABLE or not path:
        return None
    # A path already represented by an Audio Library entry must be loaded in
    # place. Auto-importing it during Preview used to create a cloned card.
    try:
        _registered=audio_library_entry(path) if "audio_library_entry" in globals() else None
        if _registered is not None:path=_registered.get("path",path)
        elif os.path.isabs(path) or ("://" in path) or path.startswith("~"):
            path=resolve_audio_path(path)
    except Exception:pass
    full=(path if os.path.isabs(str(path)) else (abs_from_base(path) if "abs_from_base" in globals() else os.path.join(BASE_DIR,str(path).replace("/",os.sep))))
    if full in _sound_cache:
        return _sound_cache[full]
    snd = None
    if os.path.isfile(full):
        try:
            snd = pygame.mixer.Sound(full)
        except Exception as e:
            print(f"Could not load sound '{path}':", e)
    _sound_cache[full] = snd
    return snd

def _record_audio_event(event_name, vol, path, pitch=1.0, extra=None):
    if is_recording:
        _event = {
            "frame": record_frame_idx,
            "time": record_frame_idx / max(1, record_fps),
            "event": event_name, "volume": vol, "pitch": float(pitch or 1.0),
            # Actual sound file used, relative to BASE_DIR (same form load_sound
            # expects). Recorded per-event rather than resolved later, since
            # different characters can map the same event name to different
            # files -- the export step needs to know exactly which file played.
            "path": path,
        }
        if isinstance(extra, dict):
            _event.update(_faux_json_value(extra) if "_faux_json_value" in globals() else extra)
        record_audio_events.append(_event)

def play_audio_cue(character_or_template, event_name, volume=None, pitch=1.0):
    if not AUDIO_AVAILABLE or not isinstance(character_or_template, dict) or not event_name:
        return
    event_name = normalize_sprite_tag(event_name) if "normalize_sprite_tag" in globals() else event_name
    path = character_or_template.get("audio_map", {}).get(event_name)
    if not path:
        return
    
    # Use CTX's pitch cache for proper pitch shifting
    if 'CTX' in globals():
        snd = CTX._get_pitched_sound(path, pitch, character_or_template.get('_audio_effects', []))
    else:
        snd = load_effect_sound(path, character_or_template.get('_audio_effects', []))
    if snd is None:
        return
    vol = volume if volume is not None else character_or_template.get("audio_volume_map", {}).get(event_name, 1.0)
    vol = max(0.0, min(1.0, float(vol))) * master_volume_value()
    try:
        snd.set_volume(vol)
        snd.play()
        _record_audio_event(event_name, vol, path, pitch=pitch)
    except Exception as e:
        print("Could not play sound:", e)

def play_global_audio_cue(event_name, volume=None):
    if not AUDIO_AVAILABLE or not event_name:
        return
    # Background music is handled via dedicated looping channel, not one-shot
    if str(event_name) == "background_music":
        play_background_music(volume=volume)
        return
    path = GLOBAL_AUDIO_MAP.get(event_name)
    if not path:
        return
    snd = load_sound(path)
    if snd is None:
        return
    vol = volume if volume is not None else GLOBAL_AUDIO_VOLUME_MAP.get(event_name, 1.0)
    vol = max(0.0, min(1.0, float(vol))) * master_volume_value()
    try:
        snd.set_volume(vol)
        snd.play()
        _record_audio_event(event_name, vol, path)
    except Exception as e:
        print("Could not play sound:", e)

def _bgm_effective_volume():
    try:
        v = GLOBAL_AUDIO_VOLUME_MAP.get("background_music", 0.7)
        mv = master_volume_value() if 'master_volume_value' in globals() else 1.0
        return max(0.0, min(1.0, float(v))) * float(mv)
    except Exception:
        return 0.7

def play_background_music(volume=None, force_restart=False):
    """Play project background music in loop. Volume from slider or param.
    Uses pygame.mixer.music for streaming (good for large mp3/ogg) with Sound fallback."""
    global _background_music_channel, _background_music_sound, _background_music_path
    global _bgm_fade_active
    # Starting fresh playback cancels any in-progress end-of-match fade and
    # restores the authored volume, so a new match begins at normal level.
    if _bgm_fade_active:
        _bgm_fade_active = False
        GLOBAL_AUDIO_VOLUME_MAP["background_music"] = _bgm_fade_authored_volume
    if not AUDIO_AVAILABLE:
        return None
    path = GLOBAL_AUDIO_MAP.get("background_music")
    if not path:
        return None
    # Resolve absolute path
    try:
        full = abs_from_base(path) if 'abs_from_base' in globals() else path
        if not os.path.isabs(full):
            full = os.path.join(BASE_DIR, path.replace("/", os.sep)) if 'BASE_DIR' in globals() else path
    except Exception:
        full = path

    # If already playing same file and not forced, just update volume
    if not force_restart:
        try:
            if _background_music_channel is not None and _background_music_path == path:
                # Check if music or sound is busy
                busy = False
                try:
                    if _background_music_channel == "music":
                        busy = pygame.mixer.music.get_busy()
                    elif hasattr(_background_music_channel, "get_busy"):
                        busy = _background_music_channel.get_busy()
                except Exception:
                    busy = False
                if busy:
                    if volume is not None:
                        GLOBAL_AUDIO_VOLUME_MAP["background_music"] = max(0.0, min(1.0, float(volume)))
                    set_background_music_volume(GLOBAL_AUDIO_VOLUME_MAP.get("background_music", 0.7))
                    return _background_music_channel
        except Exception:
            pass

    # Stop previous
    stop_background_music()

    eff = _bgm_effective_volume() if volume is None else max(0.0, min(1.0, float(volume))) * (master_volume_value() if 'master_volume_value' in globals() else 1.0)
    if volume is not None:
        GLOBAL_AUDIO_VOLUME_MAP["background_music"] = max(0.0, min(1.0, float(volume)))
        eff = _bgm_effective_volume()

    # Try mixer.music first (streaming, good for large files)
    try:
        if os.path.isfile(full):
            pygame.mixer.music.load(full)
            pygame.mixer.music.set_volume(eff)
            pygame.mixer.music.play(-1)
            _background_music_channel = "music"
            _background_music_sound = None
            _background_music_path = path
            _record_audio_event("background_music", eff, path)
            return _background_music_channel
    except Exception as e:
        # print(f"music.load failed, falling back to Sound: {e}")
        pass

    # Fallback to Sound looping
    snd = load_sound(path)
    if snd is None:
        print(f"Could not load background music: {path}")
        return None
    try:
        snd.set_volume(eff)
        chan = snd.play(loops=-1)
        if chan is not None:
            chan.set_volume(eff)
        _background_music_channel = chan
        _background_music_sound = snd
        _background_music_path = path
        _record_audio_event("background_music", eff, path)
        return chan
    except Exception as e:
        print(f"Could not play background music: {e}")
        return None

def stop_background_music():
    global _background_music_channel, _background_music_sound, _background_music_path
    global _bgm_fade_active
    _stopping_bgm_path = _background_music_path
    _stopping_bgm_active = _background_music_channel is not None
    # Cancelling a fade restores the authored volume so a later play starts
    # at the normal level (e.g. user stops mid-fade or restarts a match).
    if _bgm_fade_active:
        try:
            GLOBAL_AUDIO_VOLUME_MAP["background_music"] = _bgm_fade_authored_volume
        except Exception:
            pass
    _bgm_fade_active = False
    try:
        if _background_music_channel == "music":
            try:
                pygame.mixer.music.stop()
            except Exception:
                pass
        elif _background_music_channel is not None:
            try:
                _background_music_channel.stop()
            except Exception:
                pass
    except Exception:
        pass
    # Always also stop music channel to be safe
    try:
        if pygame.mixer.get_init():
            # Only stop if we were the music player - we check if our path is set
            if _background_music_path is not None:
                # Don't stop other music? But we own BGM, so stop
                pygame.mixer.music.stop()
    except Exception:
        pass
    _background_music_channel = None
    _background_music_sound = None
    _background_music_path = None
    if _stopping_bgm_active and _stopping_bgm_path:
        _record_audio_event("background_music_stop", 0.0, _stopping_bgm_path)

def start_background_music_fade(duration=2.0):
    """Begin a smooth fade-out of the background music over `duration`
    seconds. Wall-clock based, so time scale / slow-mo never distorts it.
    The authored volume is restored once the fade finishes (or is
    interrupted), so the next match starts at the normal level."""
    global _bgm_fade_active, _bgm_fade_duration, _bgm_fade_authored_volume, _bgm_fade_start_time
    if not AUDIO_AVAILABLE:
        return
    if not is_background_music_playing():
        return
    _bgm_fade_active = True
    _bgm_fade_duration = max(0.05, float(duration or 2.0))
    _bgm_fade_authored_volume = float(GLOBAL_AUDIO_VOLUME_MAP.get("background_music", 0.7))
    _bgm_fade_start_time = time.time()
    _record_audio_event("background_music_fade", _bgm_fade_authored_volume,
                        _background_music_path or GLOBAL_AUDIO_MAP.get("background_music", ""),
                        extra={"duration": _bgm_fade_duration})

def _update_background_music_fade():
    """Advance the BGM fade-out. Call every frame; stops the music when the
    fade completes, then restores the authored volume for next time."""
    global _bgm_fade_active
    if not _bgm_fade_active:
        return
    try:
        if not is_background_music_playing():
            _bgm_fade_active = False
            GLOBAL_AUDIO_VOLUME_MAP["background_music"] = _bgm_fade_authored_volume
            return
        elapsed = time.time() - _bgm_fade_start_time
        if elapsed >= _bgm_fade_duration:
            GLOBAL_AUDIO_VOLUME_MAP["background_music"] = _bgm_fade_authored_volume
            stop_background_music()
            _bgm_fade_active = False
            return
        frac = elapsed / _bgm_fade_duration
        set_background_music_volume(_bgm_fade_authored_volume * (1.0 - frac))
    except Exception:
        _bgm_fade_active = False

def set_background_music_volume(volume):
    """Adjust BGM volume live (0.0-1.0) and save to volume map."""
    GLOBAL_AUDIO_VOLUME_MAP["background_music"] = max(0.0, min(1.0, float(volume)))
    eff = _bgm_effective_volume()
    try:
        if _background_music_sound is not None:
            _background_music_sound.set_volume(eff)
        if _background_music_channel is not None and _background_music_channel != "music":
            try:
                _background_music_channel.set_volume(eff)
            except Exception:
                pass
        # Always set music volume too
        try:
            pygame.mixer.music.set_volume(eff)
        except Exception:
            pass
    except Exception:
        pass
    return eff

def is_background_music_playing():
    try:
        if _background_music_channel == "music":
            return pygame.mixer.music.get_busy()
        return _background_music_channel is not None and hasattr(_background_music_channel, "get_busy") and _background_music_channel.get_busy()
    except Exception:
        return False

def get_background_music_path():
    return GLOBAL_AUDIO_MAP.get("background_music", "")

BUILTIN_SPRITE_TAGS = ["idle", "attack", "hit"]  # the engine sets these on its own during combat

_SPRITE_TAG_PEEK_CACHE = {}  # filename -> (mtime, size, tags) so hot paths (live code preview) don't re-exec scripts

def peek_script_sprite_tags(filename):
    """Reads a script's top-level SPRITE_TAGS list (if any), so the
    importer can auto-add a picker row the moment a script declares a
    new tag -- no renaming or foldering needed. Example:
        SPRITE_TAGS = ["sting_sprite"]
        ...
        ctx.set_state(me, "sting_sprite", 0.3)
    Results are cached against the file's (mtime, size) because this is
    now also consulted from the blueprint codegen path, which the Code
    tab re-runs every frame for its live preview.
    """
    if not filename:
        return []
    path = os.path.join(SCRIPTS_DIR, filename)
    try:
        st = os.stat(path)
        cache_key = (st.st_mtime_ns, st.st_size)
    except Exception:
        cache_key = None
    if cache_key is not None:
        cached = _SPRITE_TAG_PEEK_CACHE.get(filename)
        if cached and cached[0] == cache_key:
            return list(cached[1])
    try:
        with open(path, "r") as f:
            text = f.read()
    except Exception as e:
        print(f"Could not read script '{filename}' for sprite tags:", e)
        return []
    ns = build_script_ns(text) or {}
    tags = ns.get("SPRITE_TAGS")
    result = ([str(t) for t in tags if isinstance(t, str) and t]
              if isinstance(tags, (list, tuple)) else [])
    if cache_key is not None:
        _SPRITE_TAG_PEEK_CACHE[filename] = (cache_key, list(result))
    return result

def normalize_sprite_tag(tag):
    """Collapses a custom "<builtin>_sprite" tag (e.g. "attack_sprite",
    declared by a trait script's SPRITE_TAGS) into the matching builtin
    slot ("attack") so it shares one picker row and one sprite instead
    of showing up as a separate, redundant tag."""
    if isinstance(tag, str) and tag.endswith("_sprite"):
        base = tag[: -len("_sprite")]
        if base in BUILTIN_SPRITE_TAGS:
            return base
    return tag

def _delete_custom_sprite_state(tag):
    """Remove a user-added sprite state from every editor structure that holds
    it (called from the trash button on custom Sprite-tab rows). Built-in and
    script-declared states never get the button, so they can't reach here.
    Persists with the character like any other editor change (Confirm/Save)."""
    tag = normalize_sprite_tag(tag)
    if not tag:
        return False
    if isinstance(modal.get("sprite_tags"), list):
        modal["sprite_tags"] = [t for t in modal["sprite_tags"] if normalize_sprite_tag(t) != tag]
    modal["custom_sprite_tags"] = [t for t in (modal.get("custom_sprite_tags") or [])
                                   if normalize_sprite_tag(t) != tag]
    sm = modal.get("sprite_map")
    if isinstance(sm, dict):
        sm.pop(tag, None)
    for key in ("animation_frames", "animation_fps", "animation_durations",
                "animation_frame_offsets", "animation_sources",
                "animation_anchors", "animation_pivots", "animation_position_events", "animation_collision_frames", "animation_layers"):
        d = modal.get(key)
        if isinstance(d, dict):
            d.pop(tag, None)
    try:
        _sync_sprite_image_nodes(modal.get("script_file"), tag, "")
    except Exception:
        pass
    # Also strip the tag from the script's SPRITE_TAGS declaration.
    # Custom states get persisted into the script (so they survive editor
    # sessions), which means an intentional delete must remove it there
    # too — otherwise the next editor open / script regeneration would
    # just resurrect the state the user explicitly trashed.
    try:
        remove_sprite_tag_from_script(modal.get("script_file"), tag)
    except Exception:
        pass
    push_toast(f"Deleted custom state '{tag}'.", "info", 1.8)
    return True

def remove_sprite_tag_from_script(filename, tag):
    """Delete one tag from a script's top-level ``SPRITE_TAGS = [...]``
    declaration (leaving the rest of the list intact). No-op when the
    script has no such line or doesn't declare the tag. The counterpart
    of persist_custom_sprite_tags_to_script for intentional deletes."""
    if not filename or not tag:
        return False
    tag = normalize_sprite_tag(tag)
    existing = peek_script_sprite_tags(filename)
    if tag not in existing:
        return False
    remaining = [t for t in existing if normalize_sprite_tag(t) != tag]
    path = os.path.join(SCRIPTS_DIR, filename)
    try:
        with open(path, "r", encoding="utf-8") as f:
            text = f.read()
    except Exception:
        return False
    import re as _re
    pattern = _re.compile(
        r"^[ \t]*SPRITE_TAGS[ \t]*=[ \t]*\[[^\]]*\][ \t]*(?:#[^\n]*)?$",
        _re.MULTILINE,
    )
    if not pattern.search(text):
        return False
    if remaining:
        new_text = pattern.sub("SPRITE_TAGS = " + repr(remaining), text, count=1)
    else:
        new_text = pattern.sub("", text, count=1)
    if new_text == text:
        return True
    try:
        with open(path, "w", encoding="utf-8") as f:
            f.write(new_text)
        return True
    except Exception:
        return False

def persist_custom_sprite_tags_to_script(filename, custom_tags):
    """Merge a list of custom sprite tags into the script's top-level
    ``SPRITE_TAGS = [...]`` declaration so they survive closing the
    character editor and reappear next session.

    * Existing ``SPRITE_TAGS`` line is replaced (union'd with the union of
      script-declared tags + custom_tags so we never drop anything).
    * If the script has no such line, one is appended at the bottom.
    * Pass an empty / None ``custom_tags`` to leave the script untouched.

    Returns True on success, False on failure (no script / read error /
    write error). Failures are surfaced as a toast so the user knows the
    tag will only live in the character template and not the script.
    """
    if not filename or not custom_tags:
        return False
    # Normalize + dedupe + drop anything that maps to a builtin (so we
    # don't store "attack" as a "custom" tag -- the editor treats builtins
    # as always-present anyway).
    clean = []
    seen = set()
    for t in custom_tags:
        t = normalize_sprite_tag(t)
        if not t or t in BUILTIN_SPRITE_TAGS or t in seen:
            continue
        seen.add(t)
        clean.append(t)
    if not clean:
        return False
    path = os.path.join(SCRIPTS_DIR, filename)
    try:
        with open(path, "r", encoding="utf-8") as f:
            text = f.read()
    except Exception as e:
        push_toast(f"Could not read script for sprite tags: {e}", "warning")
        return False

    # Merge with whatever the script already declared (if anything).
    existing = peek_script_sprite_tags(filename)
    merged = []
    for t in list(existing) + list(clean):
        t = normalize_sprite_tag(t)
        if not t or t in BUILTIN_SPRITE_TAGS or t in merged:
            continue
        merged.append(t)

    import re as _re
    pattern = _re.compile(
        r"^[ \t]*SPRITE_TAGS[ \t]*=[ \t]*\[[^\]]*\][ \t]*(?:#[^\n]*)?$",
        _re.MULTILINE,
    )
    new_line = "SPRITE_TAGS = " + repr(merged)
    if pattern.search(text):
        new_text = pattern.sub(new_line, text, count=1)
    else:
        # Append at the end with a leading blank line so it sits nicely.
        new_text = text.rstrip() + "\n\n" + new_line + "\n"
    if new_text == text:
        return True  # nothing changed
    try:
        with open(path, "w", encoding="utf-8") as f:
            f.write(new_text)
        return True
    except Exception as e:
        push_toast(f"Could not save sprite tags to script: {e}", "warning")
        return False

def get_all_tags_for_script(filename):
    """Built-in tags (always available) + whatever custom tags this
    script declares, in a stable order, deduplicated. Custom tags that
    collapse onto a builtin (see normalize_sprite_tag) are folded in
    rather than shown twice."""
    tags = list(BUILTIN_SPRITE_TAGS)
    for t in peek_script_sprite_tags(filename):
        t = normalize_sprite_tag(t)
        if t not in tags:
            tags.append(t)
    return tags

# ============================================================
# CHARACTERS / COMBAT
# ============================================================
characters = []
