    # GPU/CPU-friendly source, then upscale the finished Surface.
    req_w=max(1,min(4096,int(w)));req_h=max(1,min(4096,int(h)))
    _max_dim=1024;_max_pixels=1024*1024;_scale=min(1.0,_max_dim/max(req_w,req_h),math.sqrt(_max_pixels/max(1,req_w*req_h)))
    w=max(1,int(round(req_w*_scale)));h=max(1,int(round(req_h*_scale)));stops=_gradient_node_stops(en)
    stop_key=tuple((round(stop["pos"],5),tuple(stop["color"]),int(stop["alpha"]),round(stop.get("bias",.5),4)) for stop in stops)
    key=(w,h,str(en.get("gradient_type","linear")),round(float(en.get("gradient_angle",0)),3),round(float(en.get("gradient_distance",1)),4),round(float(en.get("gradient_offset",0)),4),round(float(en.get("gradient_smoothness",1)),4),str(en.get("gradient_interpolation","smoothstep")),str(en.get("gradient_repeat","clamp")),str(en.get("gradient_color_space","rgb")),round(float(en.get("gradient_center_x",.5)),4),round(float(en.get("gradient_center_y",.5)),4),round(float(en.get("gradient_aspect",1)),4),bool(en.get("gradient_reverse",False)),round(float(en.get("gradient_dither",0)),3),int(en.get("border_radius",0)),stop_key)
    hit=_GRADIENT_NODE_CACHE.get(key)
    if hit is not None:
        _GRADIENT_NODE_CACHE.pop(key,None);_GRADIENT_NODE_CACHE[key]=hit
        if (w,h)!=(req_w,req_h):
            method=pygame.transform.scale if en.get("pixel_perfect",False) else pygame.transform.smoothscale
            return method(hit,(req_w,req_h))
        return hit
    yy,xx=np.mgrid[0:h,0:w].astype(np.float32);nx=xx/max(1,w-1);ny=yy/max(1,h-1);cx=float(en.get("gradient_center_x",.5));cy=float(en.get("gradient_center_y",.5));aspect=max(.01,float(en.get("gradient_aspect",1)));distance=max(.001,float(en.get("gradient_distance",1)));angle=math.radians(float(en.get("gradient_angle",0)));kind=str(en.get("gradient_type","linear"))
    dx=(nx-cx)*aspect;dy=ny-cy
    if kind=="radial":t=np.sqrt(dx*dx+dy*dy)*2.0/distance
    elif kind=="diamond":t=(np.abs(dx)+np.abs(dy))*2.0/distance
    elif kind=="conic":t=(np.arctan2(dy,dx)-angle)/(math.pi*2.0)+.5
    else:t=.5+((nx-cx)*math.cos(angle)+(ny-cy)*math.sin(angle))/distance
    t=t+float(en.get("gradient_offset",0));repeat=str(en.get("gradient_repeat","clamp"))
    if repeat=="repeat":t=np.mod(t,1.0)
    elif repeat=="mirror":t=1.0-np.abs(np.mod(t,2.0)-1.0)
    else:t=np.clip(t,stops[0]["pos"],stops[-1]["pos"])
    if en.get("gradient_reverse",False):t=1.0-t
    rgb=np.zeros((h,w,3),dtype=np.float32);alpha=np.zeros((h,w),dtype=np.float32);interp=str(en.get("gradient_interpolation","smoothstep"));space=str(en.get("gradient_color_space","rgb"));smooth=max(.05,float(en.get("gradient_smoothness",1)))
    for i in range(len(stops)-1):
        a,b=stops[i],stops[i+1];lo,hi=float(a["pos"]),float(b["pos"]);mask=(t>=lo)&(t<=hi if i==len(stops)-2 else t<hi);u=np.clip((t-lo)/max(1e-6,hi-lo),0,1);bias=float(a.get("bias",.5))
        if bias<.5:u=np.power(u,1.0+(0.5-bias)*6.0)
        elif bias>.5:u=1.0-np.power(1.0-u,1.0+(bias-.5)*6.0)
        if interp=="constant":u=np.zeros_like(u)
        elif interp=="smoothstep":u=u*u*(3-2*u)
        elif interp=="smootherstep":u=u*u*u*(u*(u*6-15)+10)
        elif interp=="ease_in":u=u*u
        elif interp=="ease_out":u=1-(1-u)*(1-u)
        if smooth!=1.0:u=np.power(np.clip(u,0,1),smooth)
        if space=="hsv":
            ah,as_,av=colorsys.rgb_to_hsv(*(v/255.0 for v in a["color"]));bh,bs,bv=colorsys.rgb_to_hsv(*(v/255.0 for v in b["color"]));dh=((bh-ah+.5)%1.0)-.5;hh=np.mod(ah+dh*u,1.0);ss=as_+(bs-as_)*u;vv=av+(bv-av)*u
            # Vectorized HSV -> RGB.
            sector=np.floor(hh*6).astype(np.int16);f=hh*6-sector;p=vv*(1-ss);q=vv*(1-f*ss);r2=vv*(1-(1-f)*ss);m=sector%6
            rr=np.choose(m,[vv,q,p,p,r2,vv]);gg=np.choose(m,[r2,vv,vv,q,p,p]);bb=np.choose(m,[p,p,r2,vv,vv,q]);seg=np.stack((rr,gg,bb),axis=-1)*255.0
        else:seg=np.array(a["color"],dtype=np.float32)+(np.array(b["color"],dtype=np.float32)-np.array(a["color"],dtype=np.float32))*u[...,None]
        rgb[mask]=seg[mask];alpha[mask]=(float(a["alpha"])+(float(b["alpha"])-float(a["alpha"]))*u)[mask]
    rgb[t<stops[0]["pos"]]=stops[0]["color"];alpha[t<stops[0]["pos"]]=stops[0]["alpha"];rgb[t>stops[-1]["pos"]]=stops[-1]["color"];alpha[t>stops[-1]["pos"]]=stops[-1]["alpha"]
    dither=max(0.0,float(en.get("gradient_dither",0)))
    if dither>0:
        bayer=np.array([[0,8,2,10],[12,4,14,6],[3,11,1,9],[15,7,13,5]],dtype=np.float32)/15.0-.5;rgb+=np.tile(bayer,(math.ceil(h/4),math.ceil(w/4)))[:h,:w,None]*dither
    # Keep fully opaque gradients on a display-format RGB surface. The old
