    surf=pygame.surfarray.make_surface(np.clip(rgb,0,255).astype(np.uint8).transpose(1,0,2))
    if _opaque_gradient:
        surf=surf.convert()
    else:
        surf=surf.convert_alpha();pygame.surfarray.pixels_alpha(surf)[:]=np.clip(alpha,0,255).astype(np.uint8).T
    if radius:
        mask=pygame.Surface((w,h),pygame.SRCALPHA);pygame.draw.rect(mask,(255,255,255,255),mask.get_rect(),border_radius=min(radius,min(w,h)//2));surf.blit(mask,(0,0),special_flags=pygame.BLEND_RGBA_MIN)
    cost=w*h*4
