def _progress_gradient_ends(en, frac, base_col):
    """(start_col, end_col, enabled) for a progress bar's gradient fill.

    The computed percent color (base_col, from color/color_stops/blink) always
    steers the gradient START, so color-by-percent keeps working on gradients.
    gradient_stops (pct -> [startCol, endCol] pairs) additionally interpolates
    BOTH endpoints per stop - gradients for the different percentages."""
    ca = tuple(int(v) for v in tuple(base_col)[:3])
    if not en.get("gradient_enabled", False):
        return ca, ca, False
    cb = tuple(int(v) for v in tuple(en.get("gradient_end", [255, 255, 255]))[:3])
    stops = en.get("gradient_stops")
    try:
        if stops and len(stops) >= 2:
            def _stop_col(which):
                lo_p, lo_c = stops[0][0], stops[0][1][which]
                hi_p, hi_c = stops[-1][0], stops[-1][1][which]
                for si2 in range(len(stops) - 1):
                    if stops[si2][0] <= frac <= stops[si2 + 1][0]:
                        lo_p, lo_c = stops[si2][0], stops[si2][1][which]
                        hi_p, hi_c = stops[si2 + 1][0], stops[si2 + 1][1][which]
                        break
                tt = max(0.0, min(1.0, (frac - lo_p) / max(0.001, hi_p - lo_p)))
                return _blend_rgb(lo_c, hi_c, tt)
            ca, cb = _stop_col(0), _stop_col(1)
    except Exception:
        pass
    return ca, cb, True

# Kinds: "text_label" | "rect_box" | "progress_bar" | "counter" | "grid"
_char_next_instance_id = [1001]

def generate_character_instance_id():
    nid = _char_next_instance_id[0]
    _char_next_instance_id[0] += 1
    return f"inst_{nid}"

def _ensure_char_instance_id(c):
    if not isinstance(c, dict):
        return c
    if not c.get("instance_id"):
        c["instance_id"] = generate_character_instance_id()
    # Loading a saved inst_#### must advance the allocator so a later spawn
    # cannot reuse that identity.
    raw = str(c.get("instance_id", ""))
    tail = raw[5:] if raw.startswith("inst_") else ""
    if tail.isdigit():
        _char_next_instance_id[0] = max(_char_next_instance_id[0], int(tail) + 1)
    return c

