def _gradient_node_surface_interactive(en,w,h):
    """Low-cost live edit proxy; full resolution returns on mouse release."""
    active=bool((globals().get("dragging_slider") is not None and modal.get("_en_selected_id")==en.get("id")) or (modal.get("type")=="gradient_editor" and modal.get("_ge_node_id")==en.get("id") and (modal.get("_ge_slider_drag") is not None or modal.get("_ge_drag") is not None)))
    if not active or max(w,h)<=420:return _gradient_node_surface(en,w,h)
    factor=420.0/max(w,h);rw=max(2,int(w*factor));rh=max(2,int(h*factor));small=_gradient_node_surface(en,rw,rh)
    return pygame.transform.smoothscale(small,(w,h))


def _gradient_live_display_surface(en,w,h,rotation=0.0):
    """Cache a stable source texture, then quantize zoom-scaled display sizes."""
    w=max(2,min(4096,int(w)));h=max(2,min(4096,int(h)));active=bool((modal.get("type")=="gradient_editor" and modal.get("_ge_node_id")==en.get("id") and (modal.get("_ge_slider_drag") or modal.get("_ge_drag"))) or (globals().get("dragging_slider") is not None and modal.get("_en_selected_id")==en.get("id")))
    base_w=max(2,int(float(en.get("w",320))));base_h=max(2,int(float(en.get("h",180))));limit=420 if active else 1024;factor=min(1.0,limit/max(base_w,base_h));base_w=max(2,int(base_w*factor));base_h=max(2,int(base_h*factor));source=_gradient_node_surface(en,base_w,base_h)
    # Eight-pixel buckets eliminate continuous camera-zoom cache churn without visible stepping.
    tw=max(2,min(4096,int(round(w/8.0)*8)));th=max(2,min(4096,int(round(h/8.0)*8)));rot=round(float(rotation)%360,2);key=(id(source),tw,th,rot,bool(en.get("pixel_perfect",False)));hit=_GRADIENT_DISPLAY_CACHE.get(key)
    if hit is not None:_GRADIENT_DISPLAY_CACHE.pop(key,None);_GRADIENT_DISPLAY_CACHE[key]=hit;return hit
    if source.get_size()==(tw,th):out=source
    else:out=(pygame.transform.scale if en.get("pixel_perfect") else pygame.transform.smoothscale)(source,(tw,th))
    if rot:out=pygame.transform.rotate(out,-rot)
    cost=out.get_width()*out.get_height()*4
    if cost<=20*1024*1024:
        while _GRADIENT_DISPLAY_CACHE and (len(_GRADIENT_DISPLAY_CACHE)>=18 or _GRADIENT_DISPLAY_CACHE_BYTES[0]+cost>64*1024*1024):
            old_key=next(iter(_GRADIENT_DISPLAY_CACHE));old=_GRADIENT_DISPLAY_CACHE.pop(old_key);_GRADIENT_DISPLAY_CACHE_BYTES[0]=max(0,_GRADIENT_DISPLAY_CACHE_BYTES[0]-old.get_width()*old.get_height()*4)
        _GRADIENT_DISPLAY_CACHE[key]=out;_GRADIENT_DISPLAY_CACHE_BYTES[0]+=cost
    return out


def _gradient_checker_surface(w,h,tile=10):
    key=(int(w),int(h),int(tile),tuple(FIELD_BG));hit=_GRADIENT_CHECKER_CACHE.get(key)
    if hit is not None:return hit
    if len(_GRADIENT_CHECKER_CACHE)>12:_GRADIENT_CHECKER_CACHE.clear()
    surf=pygame.Surface((max(1,int(w)),max(1,int(h))))
    for y in range(0,h,tile):
        for x in range(0,w,tile):pygame.draw.rect(surf,(38,38,47) if (x//tile+y//tile)%2==0 else (25,25,32),(x,y,min(tile,w-x),min(tile,h-y)))
    _GRADIENT_CHECKER_CACHE[key]=surf;return surf


def _gradient_reveal_in_scene(node):
    node["visible"]=True;node["vcam_only"]=False
    if _scene_raw_opacity_255(node)<=0:node["opacity"]=255
    parent=node.get("hierarchy_parent");seen=set()
    while parent and parent not in seen:
        seen.add(parent);item=scene_hierarchy_item(parent)
        if item is None:break
        item["visible"]=True;item["_group_hidden"]=False;parent=item.get("hierarchy_parent")
    group=_scene_group_layer_of(node)
    if group is not None:group["visible"]=True;group["opacity"]=1.0
    scene_proxy_invalidate();_SPARSE_PRESENT_STATE["full_next"]=True


def open_gradient_editor(node_id):
    node=get_external_node(node_id)
    if node is None or node.get("kind")!="gradient":return
    _scene_set_opacity_byte(node,_scene_raw_opacity_255(node))
    modal.update({"type":"gradient_editor","focus":None,"_ge_node_id":node_id,"_ge_scroll":0.0,"_ge_selected_stop":0,"_ge_actions":[],"_ge_sliders":[],"_ge_drag":None,"_ge_slider_drag":None,"_ge_zoom":1.0,"_ge_pan":[0.0,0.0]})


def close_gradient_editor():
    global _TOOL_MODAL_CLOSE_UNTIL,left_click_this_frame
    modal["_ge_drag"]=None;modal["_ge_slider_drag"]=None;modal["type"]=None;modal["focus"]=None;_TOOL_MODAL_CLOSE_UNTIL=time.monotonic()+.28;left_click_this_frame=False;_GRADIENT_NODE_CACHE.clear();_GRADIENT_NODE_CACHE_BYTES[0]=0;_GRADIENT_DISPLAY_CACHE.clear();_GRADIENT_DISPLAY_CACHE_BYTES[0]=0;scene_proxy_invalidate();_SPARSE_PRESENT_STATE["full_next"]=True;push_toast("Gradient changes applied to the Scene Node","success",2.2)


def _ge_set_slider(slider,x):
    frac=max(0,min(1,(x-slider["x"])/max(1,slider["w"])));slider["set"](slider["min"]+frac*(slider["max"]-slider["min"]))


def handle_gradient_editor_event(event):
    if modal.get("type")!="gradient_editor":return False
    node=get_external_node(modal.get("_ge_node_id"))
    if node is None:close_gradient_editor();return True
    if event.type==pygame.KEYDOWN and event.key==pygame.K_ESCAPE:close_gradient_editor();return True
    if event.type==pygame.MOUSEWHEEL:
        pos=pygame.mouse.get_pos();preview=modal.get("_ge_preview_rect")
        if preview and preview.collidepoint(pos):modal["_ge_zoom"]=max(.25,min(2.0,float(modal.get("_ge_zoom",1))*1.12**event.y))
        else:modal["_ge_scroll"]=max(0,min(float(modal.get("_ge_max_scroll",0)),float(modal.get("_ge_scroll",0))-event.y*52))
        return True
    if event.type==pygame.MOUSEBUTTONDOWN:
        if event.button==1:
            pos=event.pos
            controls=modal.get("_ge_controls_rect")
            for rect,action in reversed(modal.get("_ge_actions",[])):
                inside_controls=bool(controls and rect.x>=controls.x and rect.right<=controls.right)
                if rect.collidepoint(pos) and (not inside_controls or controls.collidepoint(pos)):action();scene_proxy_invalidate();return True
            for slider in reversed(modal.get("_ge_sliders",[])):
                if _slider_track_hit(slider,pos,controls):modal["_ge_slider_drag"]=slider;_ge_set_slider(slider,pos[0]);scene_proxy_invalidate();return True
            for index,rect in modal.get("_ge_stop_handles",[]):
                if rect.collidepoint(pos):modal["_ge_selected_stop"]=index;modal["_ge_drag"]={"kind":"stop","index":index};return True
            center=modal.get("_ge_center_handle");direction=modal.get("_ge_direction_handle")
            if center and center.collidepoint(pos):modal["_ge_drag"]={"kind":"center"};return True
            if direction and direction.collidepoint(pos):modal["_ge_drag"]={"kind":"direction"};return True
            if modal.get("_ge_image_rect") and modal["_ge_image_rect"].collidepoint(pos):modal["_ge_drag"]={"kind":"pan","last":pos};return True
        elif event.button in (2,3) and modal.get("_ge_preview_rect") and modal["_ge_preview_rect"].collidepoint(event.pos):modal["_ge_drag"]={"kind":"pan","last":event.pos};return True
    if event.type==pygame.MOUSEMOTION:
        if modal.get("_ge_slider_drag"):_ge_set_slider(modal["_ge_slider_drag"],event.pos[0]);scene_proxy_invalidate();return True
        drag=modal.get("_ge_drag");image=modal.get("_ge_image_rect")
        if drag and image:
            if drag["kind"]=="center":node["gradient_center_x"]=round(max(-1,min(2,(event.pos[0]-image.x)/max(1,image.width))),4);node["gradient_center_y"]=round(max(-1,min(2,(event.pos[1]-image.y)/max(1,image.height))),4)
            elif drag["kind"]=="direction":
                cx=image.x+float(node.get("gradient_center_x",.5))*image.width;cy=image.y+float(node.get("gradient_center_y",.5))*image.height;dx=event.pos[0]-cx;dy=event.pos[1]-cy;node["gradient_angle"]=round(math.degrees(math.atan2(dy,dx)),2);node["gradient_distance"]=round(max(.05,min(10,math.hypot(dx/max(1,image.width),dy/max(1,image.height))*2)),4)
            elif drag["kind"]=="stop":
                stops=_gradient_node_stops(node);i=max(0,min(len(stops)-1,int(drag.get("index",0))));target=stops[i];lo=float(stops[0]["pos"]);hi=float(stops[-1]["pos"]);target["pos"]=round(lo+max(0,min(1,(event.pos[0]-image.x)/max(1,image.width)))*max(1e-6,hi-lo),4);stops.sort(key=lambda st:st["pos"]);modal["_ge_selected_stop"]=stops.index(target) if target in stops else 0;drag["index"]=modal["_ge_selected_stop"]
            elif drag["kind"]=="pan":
                last=drag.get("last",event.pos);modal["_ge_pan"][0]+=event.pos[0]-last[0];modal["_ge_pan"][1]+=event.pos[1]-last[1];drag["last"]=event.pos
            scene_proxy_invalidate();return True
    if event.type==pygame.MOUSEBUTTONUP:
        if modal.get("_ge_slider_drag") or modal.get("_ge_drag"):modal["_ge_slider_drag"]=None;modal["_ge_drag"]=None;scene_proxy_invalidate();return True
    return event.type in (pygame.MOUSEBUTTONDOWN,pygame.MOUSEBUTTONUP,pygame.MOUSEMOTION)


