def make_external_node(kind, wx=0, wy=0, **props):
    node = {
        "id": _en_new_id(), "kind": kind, "wx": float(wx), "wy": float(wy),
        "locked": False, "visible": True, "vcam_only": False,
        "name": f"{kind}_{len(external_nodes)+1}",
        "world_space": True, "scale_with_zoom": True,
        "fx": 0.5, "fy": 0.5,
        "event_script": None, "linked_char": None, "_rect": None,
    }
    node.update(_EN_DEFAULTS.get(kind, {}))
    node.update(props)
    external_nodes.append(node)
    return node

def get_external_node(node_id):
    try:
        nid = int(node_id)
        return next((n for n in external_nodes if n.get("id") == nid), None)
    except Exception:
        return next((n for n in external_nodes if n.get("id") == node_id), None)

def get_external_node_by_name(name):
    nm = str(name)
    return next((n for n in external_nodes if str(n.get("name", "")) == nm), None)


def clone_external_node(node_or_id, new_tag=None, new_name=None, link_character=None, wx=None, wy=None):
    """Clone any external scene node (custom_progress_bar, progress_bar, text_label, rect_box, counter, timer, etc.).
    Returns the newly cloned node dictionary and assigns it a fresh ID."""
    orig = None
    if isinstance(node_or_id, dict):
        orig = node_or_id
    elif isinstance(node_or_id, (int, float)):
        orig = get_external_node(int(node_or_id))
    elif isinstance(node_or_id, str):
        t = str(node_or_id)
        orig = next((n for n in external_nodes if str(n.get("tag", "")) == t or t in n.get("tags", []) or str(n.get("name", "")) == t), None)
        if not orig and t.isdigit():
            orig = get_external_node(int(t))
        if not orig and "en_find_first_by_tag" in globals():
            orig = en_find_first_by_tag(t, include_hidden=True)
    if not orig:
        return None
    
    import copy
    clone = copy.deepcopy(orig)
    clone["id"] = _en_new_id()
    
    if new_name:
        clone["name"] = str(new_name)
    else:
        clone["name"] = f"{orig.get('name', 'node')}_clone_{clone['id']}"
        
    if new_tag is not None and str(new_tag).strip():
        clone["tag"] = str(new_tag)
        clone["tags"] = [str(new_tag)]
    else:
        clone["tag"] = str(orig.get("tag", ""))
        clone["tags"] = list(orig.get("tags", []))
        
    if link_character:
        cname = str(link_character.get("name", "") if isinstance(link_character, dict) else link_character)
        clone["linked_char"] = cname
        clone["linked_chars"] = [cname]
        if isinstance(link_character, dict):
            _ensure_char_instance_id(link_character)
            clone["linked_instance_id"] = str(link_character.get("instance_id", ""))
            clone["linked_chars"] = [clone["linked_instance_id"]]
            clone["char_follow_enabled"] = True
            clone["char_follow_offset_x"] = float(wx if wx is not None else 0.0)
            clone["char_follow_offset_y"] = float(wy if wy is not None else -30.0)
            if "pos" in link_character:
                cpos = link_character["pos"]
                clone["wx"] = float(cpos.x if hasattr(cpos, "x") else cpos[0]) + float(wx if wx is not None else 0.0)
                clone["wy"] = float(cpos.y if hasattr(cpos, "y") else cpos[1]) + float(wy if wy is not None else -30.0)
    elif wx is not None or wy is not None:
        if wx is not None: clone["wx"] = float(wx)
        if wy is not None: clone["wy"] = float(wy)
        
    external_nodes.append(clone)
    if "en_tag_index_rebuild" in globals():
        en_tag_index_rebuild()
    return clone

def remove_external_node_by_tag(tag):
    """Remove all external nodes with a given tag."""
    t = str(tag)
    before = len(external_nodes)
    external_nodes[:] = [n for n in external_nodes if str(n.get("tag", "")) != t and t not in n.get("tags", [])]
    if "en_tag_index_rebuild" in globals():
        en_tag_index_rebuild()
    return before - len(external_nodes)

def remove_external_node_by_name(name):
    """Remove all external nodes with a given name."""
    nm = str(name)
    before = len(external_nodes)
    external_nodes[:] = [n for n in external_nodes if str(n.get("name", "")) != nm]
    if "en_tag_index_rebuild" in globals():
        en_tag_index_rebuild()
    return before - len(external_nodes)

def remove_external_nodes_linked_to(character_or_name):
    """Remove all external nodes linked to a character by unique instance_id (priority) or name."""
    cname = str(character_or_name.get("name", "") if isinstance(character_or_name, dict) else character_or_name)
    cinst = str(character_or_name.get("instance_id", "") if isinstance(character_or_name, dict) else "")
    before = len(external_nodes)
    def _is_linked(n):
        if cinst:
            return (str(n.get("linked_instance_id", "")) == cinst or cinst in n.get("linked_chars", []))
        if cname:
            return (str(n.get("linked_char", "")) == cname or cname in n.get("linked_chars", []))
        return False
    external_nodes[:] = [n for n in external_nodes if not _is_linked(n)]
    if "en_tag_index_rebuild" in globals():
        en_tag_index_rebuild()
    return before - len(external_nodes)

def set_external_node_tag(node_or_id, new_tag):
    """Set/replace the tag of an external node."""
    n = node_or_id if isinstance(node_or_id, dict) else (get_external_node(int(node_or_id)) if str(node_or_id).isdigit() else (get_external_node_by_name(str(node_or_id)) or en_find_first_by_tag(str(node_or_id))))
    if n:
        n["tag"] = str(new_tag)
        n["tags"] = [str(new_tag)]
        if "en_tag_index_rebuild" in globals():
            en_tag_index_rebuild()
        return True
    return False

def set_external_node_name(node_or_id, new_name):
    """Set/replace the name of an external node."""
    n = node_or_id if isinstance(node_or_id, dict) else (get_external_node(int(node_or_id)) if str(node_or_id).isdigit() else (get_external_node_by_name(str(node_or_id)) or en_find_first_by_tag(str(node_or_id))))
    if n:
        n["name"] = str(new_name)
        return True
    return False

def remove_external_node(node_id):
    # Undo-tracked: deleting a node used to be unrecoverable.
    _doomed = get_external_node(node_id) if "get_external_node" in globals() else None
    if "scene_undo_push" in globals():
        _nm = (_doomed or {}).get("name") or (_doomed or {}).get("kind") or "node"
        scene_undo_push(f"Delete {_nm}")
    external_nodes[:] = [n for n in external_nodes if n["id"] != node_id]

# -- Scene Debug Button Helpers --
def make_scene_debug_button(label="Debug", window_title="Debug Controls", color=None, action_type="custom_event", target_type="all", target_name="", amount=0.0, tag="", enabled=True):
    global scene_debug_next_id
    btn = {
        "id": scene_debug_next_id,
        "label": str(label or "Debug")[:40],
        "window_title": str(window_title or "Debug Controls")[:40],
        "color": list(color or [130,105,255]),
        "action_type": str(action_type or "custom_event"),
        "target_type": str(target_type or "all"),
        "target_name": str(target_name or "")[:40],
        "amount": float(amount or 0.0),
        "tag": str(tag or "")[:40],
        "enabled": bool(enabled),
    }
    scene_debug_next_id += 1
    scene_debug_buttons.append(btn)
    push_toast(f"Debug Button '{btn['label']}' added", "success", 2.0)
    return btn

def remove_scene_debug_button(btn_id):
    global scene_debug_buttons
    before = len(scene_debug_buttons)
    scene_debug_buttons[:] = [b for b in scene_debug_buttons if b.get("id") != btn_id]
    return len(scene_debug_buttons) != before

def get_scene_debug_button(btn_id):
    return next((b for b in scene_debug_buttons if b.get("id")==btn_id), None)

def duplicate_scene_debug_button(btn_id):
    orig = get_scene_debug_button(btn_id)
    if not orig:
        return None
    import copy
    clone = copy.deepcopy(orig)
    global scene_debug_next_id
    clone["id"] = scene_debug_next_id
    scene_debug_next_id += 1
    clone["label"] = (clone.get("label","") + " Copy")[:40]
    scene_debug_buttons.append(clone)
    return clone

def _scene_debug_get_targets(btn):
    ttype = btn.get("target_type","all")
    tname = btn.get("target_name","")
    if ttype == "by_name":
        return [c for c in characters if c.get("name")==tname]
    elif ttype == "fighters":
        return [c for c in characters if not c.get("is_scene_prop")]
    elif ttype == "scene_props":
        return [c for c in characters if c.get("is_scene_prop")]
    elif ttype == "alive":
        return [c for c in characters if c.get("hp",0)>0 and not c.get("is_scene_prop")]
    else:
        return list(characters)

def _scene_debug_archive_death(target,killer=None):
    """Remember one real fighter death for the Revive Last Killed debug action."""
    if not _is_combat_character(target,require_alive=False):
        return False
    # The normal death pass is edge-triggered, but defensive deduplication keeps
    # a plugin/manual hook from inserting the same still-dead object twice.
    scene_death_history[:]=[e for e in scene_death_history if e.get("character") is not target]
    scene_death_history.append({
        "character":target,"killed_at":time.time(),
        "killer_name":killer.get("name","") if isinstance(killer,dict) else "",
        "tags":set(target.get("tags",set())),"team":target.get("team"),
        "position":pygame.Vector2(target.get("pos",(0,0))),
        "velocity":pygame.Vector2(target.get("vel",(0,0))),
        "smooth_velocity":pygame.Vector2(target.get("_smooth_vel",target.get("vel",(0,0)))),
        "movement_locked":bool(target.get("movement_locked",False)),
        "input_paused":bool(target.get("input_paused",False)),
        "manual_input_enabled":bool(target.get("manual_input_enabled",True)),
        "collision_state":{k:copy.deepcopy(target.get(k)) for k in (
            "has_collision","collision_mode","collision_disabled_until",
            "_no_collide_ids","_no_collide_tags","_no_collide_shared_tags",
            "_no_collide_same_team") if k in target},
    })
    if len(scene_death_history)>SCENE_DEBUG_DEATH_HISTORY_MAX:
        del scene_death_history[:-SCENE_DEBUG_DEATH_HISTORY_MAX]
    return True


def _scene_debug_revive_last(count=1):
    """Revive the newest N archived fighters (1..20), preserving authored state."""
    global game_over,winner,end_fade_alpha,end_fade_complete,end_fade_timer
    wanted=max(1,min(SCENE_DEBUG_DEATH_HISTORY_MAX,int(round(float(count or 1)))))
    revived=[];seen=set()
    while scene_death_history and len(revived)<wanted:
        entry=scene_death_history.pop();target=entry.get("character")
        if not isinstance(target,dict) or id(target) in seen:
            continue
        seen.add(id(target))
        if target in characters and target.get("hp",0)>0:
            continue
        # Restore values death hooks are most likely to mutate; every other
        # custom field remains on the original dictionary automatically.
        target["tags"]=set(entry.get("tags",target.get("tags",set())))
        if entry.get("team") is not None:target["team"]=entry.get("team")
        target["pos"]=pygame.Vector2(entry.get("position",target.get("pos",(0,0))))
        target["vel"]=pygame.Vector2(entry.get("velocity",(0,0)));target["_smooth_vel"]=pygame.Vector2(entry.get("smooth_velocity",target["vel"]))
        target["movement_locked"]=bool(entry.get("movement_locked",False));target["input_paused"]=bool(entry.get("input_paused",False));target["manual_input_enabled"]=bool(entry.get("manual_input_enabled",True));target["sleeping"]=False
        target["cooldown"]=0.0;target["visual_state"]="idle";target["visual_timer"]=0.0
        target["_touching_partners"]=set();target["_phase_touching_ids"]=set();target["_phase_touch_refs"]={};target.pop("_despawned",None)
        for _ck,_cv in entry.get("collision_state",{}).items():target[_ck]=copy.deepcopy(_cv)
        CTX.revive(target,100)
        # on_revive may deliberately change the mode; motion recovery no longer
        # removes whichever collision policy is now active.
        _ensure_character_motion_after_reset(target,entry.get("velocity"))
        # on_revive remains free to run setup logic, but this debug action's
        # contract guarantees identity tags/team match the killed target.
        target["tags"]=set(entry.get("tags",target.get("tags",set())))
        if entry.get("team") is not None:target["team"]=entry.get("team")
        if target.get("hp",0)>0:
            revived.append(target)
    if revived:
        game_over=False;winner=None;end_fade_alpha=0.0;end_fade_complete=False;end_fade_timer=0.0
        if camera.get("target") is None:camera["target"]=revived[0]
    return revived


def trigger_scene_debug_button(btn):
    if not btn or not btn.get("enabled",True):
        return
    label = btn.get("label","Debug")
    bid = btn.get("id",0)
    action = btn.get("action_type","custom_event")
    amount = float(btn.get("amount",0) or 0)
    tag = btn.get("tag","")
    targets = _scene_debug_get_targets(btn)
    try:
        if action=="toggle_all_invulnerable":
            state=CTX.toggle_debug_all_invulnerable("toggle",False);btn["_toggle_state"]=state
            push_toast(f"{label}: all characters are now {'INVULNERABLE' if state else 'VULNERABLE'}","warning" if state else "success",2.0)
        elif action=="revive_last_killed":
            count=max(1,min(SCENE_DEBUG_DEATH_HISTORY_MAX,int(round(amount or 1))))
            revived=_scene_debug_revive_last(count)
            if revived:
                push_toast(f"{label}: Revived {len(revived)} of the last {count} killed","success",2.2)
            else:
                push_toast(f"{label}: No killed targets in the revive history","warning",2.2)
        elif action in ("restore_hp_all","restore_hp_target"):
            for c in targets:
                c["hp"] = c.get("max_hp",100)
                try: call_hook(c, "on_heal", CTX, c, c.get("max_hp",100))
                except: pass
                try: call_hook(c, "on_full_heal", CTX, c)
                except: pass
            push_toast(f"{label}: Restored HP ({len(targets)})", "success", 1.6)
        elif action in ("heal_all","heal_target"):
            for c in targets:
                if c.get("hp",0)<=0: continue
                old = c.get("hp",0)
                c["hp"] = min(c.get("max_hp",old), old + amount)
                try: call_hook(c, "on_heal", CTX, c, amount)
                except: pass
            push_toast(f"{label}: Healed {len(targets)} by {amount}", "success", 1.6)
        elif action in ("deal_damage_all","deal_damage_target"):
            for c in targets:
                if c.get("hp",0)<=0 or _DEBUG_ALL_CHARACTERS_INVULNERABLE[0]: continue
                dmg = int(amount) if amount else 10
                c["hp"] = max(0, c["hp"]-dmg)
                try: call_hook(c, "on_damage_taken", CTX, c, None, dmg, False)
                except: pass
                try: spawn_popup(c["pos"], f"-{dmg}", (255,90,90), target=c, amount=dmg)
                except: pass
                if c["hp"]<=0:
                    try: call_hook(c, "on_death", CTX, c, None)
                    except: pass
                    for sd in characters:
                        if sd.get("is_scene_prop"):
                            try: call_hook(sd, "on_scene_death", CTX, c, None)
                            except: pass
            push_toast(f"{label}: Dealt {amount} dmg to {len(targets)}", "info", 1.6)
        elif action in ("set_hp_all","set_hp_target"):
            for c in targets:
                c["hp"] = max(0, min(c.get("max_hp",100), int(amount)))
            push_toast(f"{label}: Set HP to {int(amount)} ({len(targets)})", "info", 1.6)
        elif action in ("kill_all","kill_target"):
            for c in targets:
                if c.get("hp",0)>0:
                    c["hp"]=0
                    try: call_hook(c, "on_death", CTX, c, None)
                    except: pass
                    for sd in characters:
                        if sd.get("is_scene_prop"):
                            try: call_hook(sd, "on_scene_death", CTX, c, None)
                            except: pass
            push_toast(f"{label}: Killed {len(targets)}", "warning", 1.6)
        elif action in ("trigger_damage_taken_all","trigger_damage_taken_target"):
            for c in targets:
                try: call_hook(c, "on_damage_taken", CTX, c, None, amount if amount else 10, False)
                except: pass
            push_toast(f"{label}: Triggered on_damage_taken ({len(targets)})", "info", 1.6)
        elif action in ("trigger_damage_dealt_all","trigger_damage_dealt_target"):
            for c in targets:
                try: call_hook(c, "on_damage_dealt", CTX, c, None, amount if amount else 10, False)
                except: pass
            push_toast(f"{label}: Triggered on_damage_dealt ({len(targets)})", "info", 1.6)
        elif action in ("spawn_duplicate_all","spawn_duplicate_target"):
            cnt=0
            for c in list(targets):
                try:
                    tmpl = {
                        "name": c.get("name"),
                        "max_hp": c.get("max_hp",100),
                        "dmg_min": c.get("dmg_min",5),
                        "dmg_max": c.get("dmg_max",10),
                        "crit_chance": c.get("crit_chance",0.05),
                        "crit_mult": c.get("crit_mult",2.0),
                        "color": tuple(c.get("color",(200,60,60))),
                        "scale": c.get("scale",1.0),
                        "radius": c.get("radius",18),
                        "is_scene_prop": c.get("is_scene_prop",False),
                        "is_visible": c.get("is_visible",True),
                        "tags": set(c.get("tags",set())),
                    }
                    inst = spawn_instance(tmpl, near=c.get("pos"))
                    inst["sprites"] = c.get("sprites",{})
                    inst["animations"] = c.get("animations",{})
                    inst["animation_durations"] = c.get("animation_durations",{})
                    inst["animation_fps"] = c.get("animation_fps",{})
                    inst["script_file"] = c.get("script_file")
                    inst["script_ns"] = None
                    if inst.get("script_file"):
                        try:
                            ns = load_script_ns_from_file(inst.get("script_file"))
                            if ns:
                                apply_script_params(ns, c.get("script_params",{}))
                                inst["script_ns"]=ns
                        except: pass
                    characters.append(inst)
                    cnt+=1
                except Exception as e:
                    print("duplicate failed", e)
            push_toast(f"{label}: Duplicated {cnt}", "success", 1.6)
        elif action in ("reset_cooldowns_all","reset_cooldowns_target"):
            for c in targets:
                c["cooldown"]=0
            push_toast(f"{label}: Reset cooldowns ({len(targets)})", "info", 1.6)
        elif action == "add_tag":
            if not tag:
                push_toast("No tag set for Add Tag action", "warning", 2.0)
            else:
                for c in targets:
                    c.setdefault("tags",set()).add(tag)
                    try: call_hook(c, "on_tag_added", CTX, c, tag)
                    except: pass
                push_toast(f"{label}: Added tag '{tag}' to {len(targets)}", "info", 1.6)
        elif action == "remove_tag":
            if not tag:
                push_toast("No tag set for Remove Tag action", "warning", 2.0)
            else:
                for c in targets:
                    if tag in c.get("tags",set()):
                        c.get("tags",set()).remove(tag)
                        try: call_hook(c, "on_tag_removed", CTX, c, tag)
                        except: pass
                push_toast(f"{label}: Removed tag '{tag}' ({len(targets)})", "info", 1.6)
        for ch in list(characters):
            try:
                call_hook(ch, "on_scene_debug_button", CTX, ch, label, bid)
            except Exception:
                pass
        try:
            if characters:
                avg = pygame.Vector2(0,0)
                for c in characters[:10]:
                    avg += pygame.Vector2(c.get("pos",(0,0)))
                avg /= max(1, min(10, len(characters)))
                spawn_popup(avg, label, tuple(btn.get("color",(130,105,255))), crit=False)
        except: pass
    except Exception as ex:
        push_toast(f"Debug button error: {ex}", "error", 2.5)
        import traceback; traceback.print_exc()

