# NERD STATS  (F3)
# ══════════════════════════════════════════════════════════════════════════
# A Minecraft-style debug overlay: frame timing with a live graph, what the
# scene actually contains, and where the cursor is in world space -- which is
# otherwise guesswork when placing things by hand.
_NERD = {
    "frames": [],        # recent frame times (ms) for the graph
    "fps": 0.0,
    "avg": 0.0,
    "worst": 0.0,
    "last_t": 0.0,
    "mem": 0.0,
    "mem_t": 0.0,
}

# Both performance windows are proper draggable editor overlays. Positions are
# intentionally session-local: defaults adapt to sidebar/window size until the
# user actually moves a panel.
_PERF_OVERLAY_POS={"nerd":None,"frame_costs":None}
_PERF_OVERLAY_RECTS={}
_PERF_OVERLAY_DRAG=None


def _perf_overlay_rect(key,w,h,default_x,default_y):
    pos=_PERF_OVERLAY_POS.get(key)
    x,y=(default_x,default_y) if pos is None else pos
    x=max(4,min(max(4,WIDTH-int(w)-4),int(x)));y=max(4,min(max(4,HEIGHT-int(h)-4),int(y)))
    return pygame.Rect(x,y,int(w),int(h))


def handle_perf_overlay_event(event):
    """Drag Nerd Stats or Frame Cost by their 24px header strip."""
    global _PERF_OVERLAY_DRAG
    if event.type==pygame.MOUSEBUTTONDOWN and event.button==1 and modal.get("type") is None:
        for key in ("frame_costs","nerd"):
            visible=(SETTINGS.get("frame_costs",False) if key=="frame_costs" else SETTINGS.get("nerd_stats",False))
            rect=_PERF_OVERLAY_RECTS.get(key)
            if visible and isinstance(rect,pygame.Rect) and pygame.Rect(rect.x,rect.y,rect.width,min(24,rect.height)).collidepoint(event.pos):
                _PERF_OVERLAY_DRAG={"key":key,"dx":event.pos[0]-rect.x,"dy":event.pos[1]-rect.y};_SPARSE_PRESENT_STATE["full_next"]=True;return True
    if event.type==pygame.MOUSEMOTION and _PERF_OVERLAY_DRAG:
        key=_PERF_OVERLAY_DRAG["key"];rect=_PERF_OVERLAY_RECTS.get(key)
        if isinstance(rect,pygame.Rect):
            nx=event.pos[0]-_PERF_OVERLAY_DRAG["dx"];ny=event.pos[1]-_PERF_OVERLAY_DRAG["dy"]
            _PERF_OVERLAY_POS[key]=(max(4,min(max(4,WIDTH-rect.width-4),nx)),max(4,min(max(4,HEIGHT-rect.height-4),ny)));_SPARSE_PRESENT_STATE["full_next"]=True
        return True
    if event.type==pygame.MOUSEBUTTONUP and event.button==1 and _PERF_OVERLAY_DRAG:
        _PERF_OVERLAY_DRAG=None;_SPARSE_PRESENT_STATE["full_next"]=True;return True
    return False

def _save_reminder_delay(seconds):
    global _save_reminder_next
    modal["_save_reminder_open"]=False;modal["_save_reminder_rects"]={};_save_reminder_next=time.time()+max(30,float(seconds));_SPARSE_PRESENT_STATE["full_next"]=True


def handle_save_reminder_event(event):
    """Persistent Save / Don't Save / timed Snooze decision banner."""
    if not modal.get("_save_reminder_open") or modal.get("type") is not None:return False
    if event.type!=pygame.MOUSEBUTTONDOWN or event.button!=1:return False
    rects=modal.get("_save_reminder_rects",{}) or {};pos=event.pos
    if rects.get("save") and rects["save"].collidepoint(pos):
        if current_project_name:
            if save_project(current_project_name):_save_reminder_delay(int(_editor_config.get("save_reminder_interval",300) or 300))
        else:
            modal["_save_reminder_open"]=False;show_save_as_dialog("My Project")
        return True
    if rects.get("dont") and rects["dont"].collidepoint(pos):_save_reminder_delay(int(_editor_config.get("save_reminder_interval",300) or 300));return True
    options=(5,10,30,60,120);minutes=int(modal.get("_save_reminder_snooze_minutes",10));index=options.index(minutes) if minutes in options else 1
    if rects.get("minus") and rects["minus"].collidepoint(pos):modal["_save_reminder_snooze_minutes"]=options[max(0,index-1)];return True
    if rects.get("plus") and rects["plus"].collidepoint(pos):modal["_save_reminder_snooze_minutes"]=options[min(len(options)-1,index+1)];return True
    if rects.get("snooze") and rects["snooze"].collidepoint(pos):_save_reminder_delay(minutes*60);return True
    return bool(rects.get("panel") and rects["panel"].collidepoint(pos))


# --- Frame cost breakdown (Shift+F4) ----------------------------------------
# "It got slower" is unactionable without knowing WHICH part got slower. This
# times the real subsystems in the live loop and reports the split, so a slow
# frame can be attributed instead of guessed at.
_FCOST_ALWAYS = [True]  # always gather subsystem timings (cheap) so $flood/$wash work without Shift+F4
_FCOST = {}
_FCOST_LAST = {}
_FCOST_T = [0.0]

class frame_cost:
    """Context manager timing one named phase of the frame.

    Deliberately a no-op (two dict lookups) unless the overlay is on, so it can
    stay wrapped around hot paths permanently without costing anything.
    """

    __slots__ = ("name", "t0")

    def __init__(self, name):
        self.name = name
        self.t0 = 0.0

    def __enter__(self):
        # Always collect timing when any tool ($flood/$wash/perf overlay)
        # asks for it -- the check is a dict lookup + a perf_counter() call,
        # roughly 200 nanoseconds of overhead, negligible vs the savings.
        if SETTINGS.get("frame_costs", False) or _FCOST_ALWAYS[0]:
            self.t0 = time.perf_counter()
        return self

    def __exit__(self, *exc):
        if self.t0:
            _FCOST[self.name] = _FCOST.get(self.name, 0.0) + (time.perf_counter() - self.t0) * 1000.0
        return False

def frame_cost_flip():
    """Called once per frame: roll the accumulator into a smoothed snapshot."""
    if not SETTINGS.get("frame_costs", False) and not _FCOST_ALWAYS[0]:
        if _FCOST:
            _FCOST.clear()
        return
    now = time.time()
    for k, v in _FCOST.items():
        # Exponential smoothing: raw per-frame numbers jitter too much to read.
        _FCOST_LAST[k] = v if k not in _FCOST_LAST else _FCOST_LAST[k] * 0.9 + v * 0.1
    for k in list(_FCOST_LAST):
        if k not in _FCOST:
            _FCOST_LAST[k] *= 0.9
            if _FCOST_LAST[k] < 0.005:
                del _FCOST_LAST[k]
    _FCOST.clear()
    _FCOST_T[0] = now

def draw_frame_costs():
    """Frame costs using the same compact shell/layout as Nerd Stats."""
    if not SETTINGS.get("frame_costs",False) or is_recording or _is_export_render:
        _PERF_OVERLAY_RECTS.pop("frame_costs",None);return
    display=dict(_FCOST_LAST)
    if "characters" in display and "collision gizmos" in display:display["characters exclusive"]=max(0.0,display["characters"]-display["collision gizmos"]);display.pop("characters",None)
    if "scene nodes" in display:
        display["scene nodes total"]=display.pop("scene nodes")
    if "scene" in display:
        nested=sum(_FCOST_LAST.get(k,0.0) for k in ("scene nodes","characters","particle emitters","weapons/effects","scene blocks","grid+bg"));display["scene core"]=max(0.0,display["scene"]-nested);display.pop("scene",None)
    rows=sorted(display.items(),key=lambda kv:-kv[1])[:12]
    if not rows:_PERF_OVERLAY_RECTS.pop("frame_costs",None);return
    total=max(.001,sum(v for _k,v in rows))
    notes=[]
    if "scene core" in display:notes.append("Scene phases are exclusive—not double counted")
    if "present/update" in display:notes.append("Present is transfer/wait; frame pacing is excluded")
    notes.append("Percentages use measured active work only · Shift+F4 closes")
    header_h=24;pad=8;line_h=14;wid=306;hei=header_h+pad*2+30+len(rows)*line_h+len(notes)*line_h
    box=_perf_overlay_rect("frame_costs",wid,hei,WIDTH-wid-14,60);_PERF_OVERLAY_RECTS["frame_costs"]=box.copy()
    panel=pygame.Surface(box.size,pygame.SRCALPHA);panel.fill((8,8,12,232));screen.blit(panel,box.topleft);ui_draw_rect(screen,(60,58,78),box,1,5)
    header=pygame.Rect(box.x,box.y,box.width,header_h);ui_draw_rect(screen,PANEL_BG_ALT,header,border_top_left_radius=5,border_top_right_radius=5);pygame.draw.line(screen,DIVIDER,(header.x,header.bottom-1),(header.right,header.bottom-1),1)
    hic=get_icon_fs("activity",13,ACCENT)
    if hic:screen.blit(hic,(header.x+8,header.centery-hic.get_height()//2))
    screen.blit(font_tiny.render("FRAME COSTS  ·  DRAG",True,TEXT_DIM),(header.x+27,header.y+6))
    for di in range(3):pygame.draw.circle(screen,TEXT_FAINT,(header.right-10,header.y+8+di*4),1)
    y=header.bottom+pad;fps_col=(120,240,150) if _NERD["fps"]>=55 else ((250,210,90) if _NERD["fps"]>=30 else (255,110,110))
    screen.blit(font_sm.render(f"{total:5.2f} ms",True,TEXT_MAIN),(box.x+pad,y));fs=font_sm.render(f"{_NERD['fps']:5.1f} fps",True,fps_col);screen.blit(fs,(box.right-pad-fs.get_width(),y));y+=24
    for name,value in rows:
        col=(255,120,120) if value>total*.4 else ((255,210,120) if value>total*.15 else (170,200,255));lab=font_tiny.render(truncate_text_to_width(font_tiny,str(name),184),True,TEXT_DIM);val=font_tiny.render(f"{value:6.2f} ms  {100*value/max(.01,total):3.0f}%",True,col);screen.blit(lab,(box.x+pad,y));screen.blit(val,(box.right-pad-val.get_width(),y));y+=line_h
    pygame.draw.line(screen,DIVIDER,(box.x+pad,y+1),(box.right-pad,y+1),1);y+=7
    for note in notes:screen.blit(font_tiny.render(truncate_text_to_width(font_tiny,note,box.width-pad*2),True,TEXT_FAINT),(box.x+pad,y));y+=line_h

_NERD_RESOURCE_MODULE=[None,False]

def nerd_stats_tick(raw_ms):
    """Feed one frame's timing; slow OS probes are cached and infrequent."""
    f = _NERD["frames"]
    f.append(float(raw_ms))
    if len(f) > 120:
        del f[:len(f) - 120]
    now = time.time()
    # Recompute the summary ~5x/sec so the numbers are readable rather than
    # flickering every frame.
    if now - _NERD["last_t"] >= 0.2:
        _NERD["last_t"] = now
        n = len(f)
        if n:
            avg = sum(f) / n
            _NERD["avg"] = avg
            _NERD["fps"] = 1000.0 / avg if avg > 0.01 else 0.0
            _NERD["worst"] = max(f)
    if now-_NERD["mem_t"]>=8.0:
        _NERD["mem_t"]=now
        if not _NERD_RESOURCE_MODULE[1]:
            _NERD_RESOURCE_MODULE[1]=True
            try:import resource as _res;_NERD_RESOURCE_MODULE[0]=_res
            except Exception:_NERD_RESOURCE_MODULE[0]=None
        try:
            if _NERD_RESOURCE_MODULE[0] is not None:_NERD["mem"]=_NERD_RESOURCE_MODULE[0].getrusage(_NERD_RESOURCE_MODULE[0].RUSAGE_SELF).ru_maxrss/1024.0
        except Exception:pass

def draw_scene_proxy_badge():
    """Small corner badge whenever the viewport is showing a degraded preview.

    Without it a cached or hidden scene layer is indistinguishable from the
    renderer being broken -- especially after a session break. Never drawn into
    recordings or exports.
    """
    if is_recording or _is_export_render:
        return
    hide = bool(SETTINGS.get("scene_proxy_hide", False))
    prox = bool(SETTINGS.get("scene_proxy", False))
    if not (hide or prox):
        return
    if hide:
        label = "SCENE ART HIDDEN"
        col, bg = (255, 140, 140), (46, 16, 16)
    else:
        label = "PREVIEW %d%% / %df" % (int(scene_proxy_quality() * 100), scene_proxy_interval())
        col, bg = (255, 205, 90), (44, 34, 10)
    surf = font_tiny.render(label + "   Shift+P", True, col)
    pad = 7
    rect = pygame.Rect(0, 0, surf.get_width() + pad * 2, surf.get_height() + pad)
    _chrome_right=(dock_reserved_width()+12) if ui_visible else 12
    rect.bottomright = (max(rect.width+4,WIDTH-_chrome_right), HEIGHT - 10)
    box = pygame.Surface(rect.size, pygame.SRCALPHA)
    box.fill((*bg, 225))
    screen.blit(box, rect.topleft)
    ui_draw_rect(screen, col, rect, width=1, border_radius=4)
    screen.blit(surf, (rect.x + pad, rect.y + pad // 2))

def draw_nerd_stats():
    """Draggable live performance panel."""
    if not SETTINGS.get("nerd_stats", False):
        _PERF_OVERLAY_RECTS.pop("nerd",None);return
    if is_recording or _is_export_render:
        _PERF_OVERLAY_RECTS.pop("nerd",None);return          # never bake the overlay into exported footage
    detail = int(SETTINGS.get("nerd_stats_detail", 1))

    fps = _NERD["fps"]
    avg = _NERD["avg"]
    worst = _NERD["worst"]
    fps_col = (120, 240, 150) if fps >= 55 else ((250, 210, 90) if fps >= 30 else (255, 110, 110))

    rows = [(f"{fps:5.1f} fps", fps_col),
            (f"{avg:5.2f} ms  (worst {worst:.0f})", TEXT_DIM)]

    if detail >= 1:
        mx, my = pygame.mouse.get_pos()
        inside = (not ui_visible) or mx > SIDEBAR_W
        if inside:
            wp = screen_to_world((mx, my))
            rows.append((f"cursor  {wp.x:8.1f}, {wp.y:8.1f}", (150, 210, 255)))
        else:
            rows.append(("cursor  (sidebar)", TEXT_FAINT))
        rows.append((f"screen  {mx:5d}, {my:5d}", TEXT_FAINT))
        cam = camera.get("pos", pygame.Vector2(0, 0))
        rows.append((f"camera  {cam.x:8.1f}, {cam.y:8.1f}  x{camera.get('zoom', 1.0):.2f}",
                     TEXT_FAINT))
        rows.append(("", None))
        _alive = sum(1 for c in characters
                     if c.get("hp", 0) > 0 and not c.get("is_scene_prop"))
        rows.append((f"entities {len(characters):4d}   alive {_alive}", TEXT_DIM))
        rows.append((f"nodes    {len(external_nodes):4d}   groups {len(scene_groups)}", TEXT_DIM))
        rows.append((f"text/img {len(scene_texts):4d} / {len(scene_images)}", TEXT_DIM))
        try:
            _pc = pe_total_particles()
            rows.append((f"emitters {len(particle_emitters):4d}   parts {_pc}",
                         (255, 170, 90) if _pc > 1500 else TEXT_DIM))
        except Exception:
            pass
        # Top 3 subsystem costs (always-on sampling, no overlay required)
        try:
            _hot = sorted(_FCOST_LAST.items(), key=lambda kv: -kv[1])[:3]
            if _hot:
                rows.append(("", None))
                for _kn, _kv in _hot:
                    _kc = (255,120,120) if _kv > 6 else ((255,210,120) if _kv > 2 else (170,220,180))
                    rows.append((f"  {_kn[:16]:<16} {_kv:5.1f} ms", _kc))
        except Exception:
            pass
        if False:
            _rs=_RENDERDOC_STATE;_rd_ready=bool(_rs.get("available"));_rd_pending=int(_rs.get("pending") or 0)
            rows.append((f"RenderDoc {'READY' if _rd_ready else 'off'}  cap {_rs.get('captures',0)}  pending {_rd_pending}",GOOD if _rd_ready else TEXT_FAINT))
            for _gk in ("3d viewport render","3d GPU readback","3d surface copy/scale","3d skin palette","3d CPU skin fallback"):
                if _gk in _FCOST_LAST:
                    _gv=float(_FCOST_LAST[_gk]);rows.append((f"  {_gk[3:][:17]:<17} {_gv:5.1f} ms",(255,120,120) if _gv>8 else ((255,210,120) if _gv>3 else (170,220,180))))
            _ws3=_ENV3D.get("workspace") if isinstance(globals().get("_ENV3D"),dict) else None
            if _ws3 is not None:rows.append((f"workers {getattr(_ws3,'_cpu_workers',0)}  queued {len(getattr(_ws3,'_worker_jobs',{}))}  done {getattr(_ws3,'_worker_done',0)}",TEXT_DIM))

    if detail >= 2:
        rows.append(("", None))
        rows.append((f"particles(legacy) {len(particles)}", TEXT_FAINT))
        rows.append((f"vfx {len(world_effects)}  zones {len(area_zones)}  popups {len(popups)}",
                     TEXT_FAINT))
        rows.append((f"undo {len(scene_undo_stack)}  redo {len(scene_redo_stack)}", TEXT_FAINT))
        if _NERD["mem"]:
            rows.append((f"memory {_NERD['mem']:.0f} MB", TEXT_FAINT))
        rows.append((f"project {current_project_name or '(unsaved)'}", TEXT_FAINT))
        rows.append((f"sim {'running' if simulation_started else 'stopped'}"
                     f"  {'paused' if paused else 'live'}", TEXT_FAINT))
        if is_recording:
            rows.append(("RECORDING", (255, 110, 110)))

    pad = 8
    line_h = 14
    graph_h = 34 if detail >= 1 else 0
    header_h=24;w=232;h=header_h+pad*2+len(rows)*line_h+graph_h
    x0=(SIDEBAR_W+10) if ui_visible else 10;default_y=60 if (ui_visible and active_tab=="arena") else 10
    box=_perf_overlay_rect("nerd",w,h,x0,default_y);_PERF_OVERLAY_RECTS["nerd"]=box.copy()

    panel = pygame.Surface((box.width, box.height), pygame.SRCALPHA);panel.fill((8,8,12,232));screen.blit(panel,box.topleft)
    ui_draw_rect(screen,(60,58,78),box,width=1,border_radius=5)
    header=pygame.Rect(box.x,box.y,box.width,header_h);ui_draw_rect(screen,PANEL_BG_ALT,header,border_top_left_radius=5,border_top_right_radius=5);pygame.draw.line(screen,DIVIDER,(header.x,header.bottom-1),(header.right,header.bottom-1),1)
    hic=get_icon_fs("activity",13,ACCENT)
    if hic:screen.blit(hic,(header.x+8,header.centery-hic.get_height()//2))
    screen.blit(font_tiny.render("PERFORMANCE  ·  DRAG",True,TEXT_DIM),(header.x+27,header.y+6))
    for _di in range(3):pygame.draw.circle(screen,TEXT_FAINT,(header.right-10,header.y+8+_di*4),1)

    y = box.y + header_h + pad
    for text, col in rows:
        if text:
            screen.blit(font_tiny.render(text, True, col or TEXT_DIM), (box.x + pad, y))
        y += line_h

    # Frame-time graph: one bar per recent frame, scaled against a 33ms
    # (30fps) ceiling with a 16.7ms reference line for 60fps.
    if graph_h:
        g = pygame.Rect(box.x + pad, y, box.width - pad * 2, graph_h - 8)
        ui_draw_rect(screen, PANEL_BG, g)
        f = _NERD["frames"]
        if f:
            top = max(33.0, max(f))
            n = min(len(f), g.width)
            _target_ms=1000.0/max(1,_fps_cap());_green_limit=max(17.0,_target_ms*1.22);_yellow_limit=max(33.0,_target_ms*2.0)
            for i,ms in enumerate(f[-n:]):
                bh=max(1,int((ms/top)*g.height));bc=(120,240,150) if ms<=_green_limit else ((250,210,90) if ms<=_yellow_limit else (255,110,110))
                pygame.draw.line(screen,bc,(g.x+i,g.bottom-1),(g.x+i,g.bottom-bh))
            ry=g.bottom-int((_target_ms/top)*g.height)
            pygame.draw.line(screen, (70, 90, 120), (g.x, ry), (g.right, ry), 1)
        ui_draw_rect(screen, (60, 58, 78), g, width=1)

def draw_scene_marquee():
    """Translucent box-select rectangle while dragging on empty canvas."""
    mq = modal.get("_scene_marquee")
    if not mq:
        return
    r = pygame.Rect(min(mq["x0"], mq["x1"]), min(mq["y0"], mq["y1"]),
                    abs(mq["x1"] - mq["x0"]), abs(mq["y1"] - mq["y0"]))
    if r.width < 2 or r.height < 2:
        return
    col = (90, 220, 255)
    fill = pygame.Surface((r.width, r.height), pygame.SRCALPHA)
    fill.fill((*col, 38))
    screen.blit(fill, r.topleft)
    ui_draw_rect(screen, col, r, width=1)
    # Live count so you know what you're catching before releasing.
    n = 0
    for coll in (external_nodes, scene_texts, scene_images):
        for it in coll:
            if it.get("locked") or _scene_item_hidden(it):
                continue
            ir = it.get("_rect")
            if ir is not None and r.colliderect(ir):
                n += 1
    if n:
        lbl = font_tiny.render(f"{n} item(s)", True, (10, 10, 14))
        chip = pygame.Rect(r.right - lbl.get_width() - 10, r.bottom + 4,
                           lbl.get_width() + 8, lbl.get_height() + 4)
        ui_draw_rect(screen, col, chip, border_radius=3)
        screen.blit(lbl, (chip.x + 4, chip.y + 2))

def draw_scene_group_outlines():
    """Dashed frame + draggable label strip around each scene node group.

    The label tab above the frame acts as a drag handle — click and drag it
    to move the entire group (all external nodes, texts, and images) at once.
    Hidden during play/recording so it never contaminates exported footage.
    Clipped to the arena canvas so it never bleeds over the sidebar/audio UI.
    """
    if not scene_groups or simulation_started or is_recording:
        modal["_sg_outline_hits"] = []
        return
    # Clip strictly to the arena area so outlines never bleed into the
    # sidebar, audio manager, or any other UI panel.
    _arena_clip = pygame.Rect(SIDEBAR_W, 0, WIDTH - SIDEBAR_W, HEIGHT)
    _old_sg_clip = screen.get_clip()
    screen.set_clip(_arena_clip)
    hit_rects = []  # (group, label_rect, full_rect)
    _dragging_gid = (modal.get("_dragging_scene_group") or {}).get("gid")
    for group in scene_groups:
        if not group.get("visible", True):
            continue
        rect = scene_group_bounds(group)
        if rect is None or rect.width <= 0:
            continue
        col = tuple(int(c) for c in group.get("color", [120, 170, 255])[:3])
        locked = bool(group.get("locked"))
        is_dragging = (group.get("id") == _dragging_gid)
        # Dashed border
        dash, gap = 8, 6
        line_w = 2 if is_dragging else 1
        for x in range(rect.left, rect.right, dash + gap):
            x2 = min(x + dash, rect.right)
            pygame.draw.line(screen, col, (x, rect.top), (x2, rect.top), line_w)
            pygame.draw.line(screen, col, (x, rect.bottom), (x2, rect.bottom), line_w)
        for y in range(rect.top, rect.bottom, dash + gap):
            y2 = min(y + dash, rect.bottom)
            pygame.draw.line(screen, col, (rect.left, y), (rect.left, y2), line_w)
            pygame.draw.line(screen, col, (rect.right, y), (rect.right, y2), line_w)
        # Label strip — this is the drag handle
        label = str(group.get("name", "Group"))
        if locked:
            label += "  🔒"
        tag = font_tiny.render(label, True, col)
        strip_w = max(tag.get_width() + 24, 60)
        strip_h = 18
        bg = pygame.Rect(rect.left, rect.top - strip_h - 2, strip_w, strip_h)
        mx_pos, my_pos = pygame.mouse.get_pos()
        hov = bg.collidepoint(mx_pos, my_pos) and not locked
        chip = pygame.Surface((bg.width, bg.height), pygame.SRCALPHA)
        chip.fill((*col, 220) if (hov or is_dragging) else (10, 10, 14, 210))
        screen.blit(chip, bg.topleft)
        ui_draw_rect(screen, col, bg, width=1, border_radius=3)
        # Grip dots
        for _di in range(3):
            pygame.draw.circle(screen, (*col, 180) if (hov or is_dragging) else (*col, 80),
                               (bg.x + 6, bg.y + 5 + _di * 4), 1)
        label_col = (10, 10, 14) if (hov or is_dragging) else col
        screen.blit(font_tiny.render(label, True, label_col), (bg.x + 14, bg.y + 2))
        if not locked:
            hint = font_tiny.render("drag", True, (10, 10, 14) if (hov or is_dragging) else (*col, 120))
            screen.blit(hint, (bg.right - hint.get_width() - 4, bg.y + 2))
        hit_rects.append((group, bg, rect))
    modal["_sg_outline_hits"] = hit_rects
    screen.set_clip(_old_sg_clip)

def draw_scene_debug_overlay():
    global scene_debug_overlay_rects, scene_debug_window_header_rects
    scene_debug_overlay_rects = []
    scene_debug_window_header_rects = {}
    if not scene_debug_mode:
        return
    if not scene_debug_buttons:
        hint_rect = pygame.Rect(SIDEBAR_W + 20, 80, 320, 70)
        draw_panel(hint_rect, alpha=230, radius=12)
        screen.blit(font_sm.render("Scene Debug Mode ON", True, GOOD), (hint_rect.x+12, hint_rect.y+10))
        screen.blit(font_tiny.render("No debug buttons yet. Add from sidebar.", True, TEXT_DIM), (hint_rect.x+12, hint_rect.y+32))
        return
    from collections import defaultdict
    groups = defaultdict(list)
    for b in scene_debug_buttons:
        if not b.get("enabled",True):
            continue
        groups[b.get("window_title","Debug Controls")].append(b)
    idx=0
    for wtitle, btns in groups.items():
        pos = scene_debug_window_positions.get(wtitle)
        if pos is None:
            bx = SIDEBAR_W + 20 + (idx % 3) * 340
            by = 80 + (idx // 3) * 260
            bx = max(SIDEBAR_W+10, min(WIDTH-330, bx))
            by = max(60, min(HEIGHT-200, by))
        else:
            bx, by = pos
        panel_w = 300
        header_h = 32
        btn_h = 32
        gap = 6
        panel_h = header_h + 12 + len(btns)*(btn_h+gap) + 12
        panel_rect = pygame.Rect(int(bx), int(by), panel_w, panel_h)
        draw_panel(panel_rect, alpha=242, radius=12, color=(18,18,24))
        header_rect = pygame.Rect(panel_rect.x, panel_rect.y, panel_rect.width, header_h)
        ui_draw_rect(screen, FIELD_FOCUS, header_rect, border_top_left_radius=12, border_top_right_radius=12)
        pygame.draw.line(screen, DIVIDER, (header_rect.x, header_rect.bottom-1), (header_rect.right, header_rect.bottom-1), 1)
        title_lbl = font_sm.render(wtitle[:28], True, TEXT_MAIN)
        screen.blit(title_lbl, (header_rect.x+12, header_rect.y+8))
        blit_icon(screen, IC.get('grid') if 'grid' in IC else None, header_rect.right-28, header_rect.centery, 14, TEXT_DIM)
        scene_debug_window_header_rects[wtitle] = header_rect
        by_cursor = panel_rect.y + header_h + 8
        for btn in btns:
            b_rect = pygame.Rect(panel_rect.x+10, by_cursor, panel_w-20, btn_h)
            is_hover = b_rect.collidepoint(pygame.mouse.get_pos())
            col = tuple(btn.get("color",(130,105,255)))
            _inv_btn=btn.get("action_type")=="toggle_all_invulnerable";_inv_on=bool(_DEBUG_ALL_CHARACTERS_INVULNERABLE[0]) if _inv_btn else False
            if _inv_on:col=(255,190,60)
            base = col if is_hover or _inv_on else (col[0]//2+20, col[1]//2+20, col[2]//2+20)
            ui_draw_rect(screen, base, b_rect, border_radius=8)
            ui_draw_rect(screen, col, b_rect, width=2 if _inv_on else 1, border_radius=8)
            lbl = font_sm.render(btn.get("label","Debug")[:22], True, (12,12,16) if _inv_on else TEXT_MAIN)
            screen.blit(lbl, (b_rect.x+12, b_rect.centery - lbl.get_height()//2))
            hint = ("INVULN ON" if _inv_on else "INVULN OFF" if _inv_btn else btn.get("action_type","").replace("_"," ")[:14])
            hint_lbl = font_tiny.render(hint, True, (12,12,16) if _inv_on else TEXT_DIM)
            screen.blit(hint_lbl, (b_rect.right - hint_lbl.get_width() - 10, b_rect.centery - hint_lbl.get_height()//2))
            scene_debug_overlay_rects.append((btn, b_rect))
            by_cursor += btn_h + gap
        idx+=1

def array_external_node(node_id, count=3, step_x=40.0, step_y=0.0,
                        rot_step=0.0, scale_step=0.0, rows=1, row_step_x=0.0,
                        row_step_y=40.0, group_result=True):
    """Repeat a node N times with a per-copy offset -- fences, tick marks,
    background rows, ladders.

    duplicate_external_node() already existed but only ever made ONE copy at a
    fixed +20px, so building a row of 20 posts meant 20 manual duplicate-and-
    drag operations. This is the same idea with a step vector, an optional
    second axis for 2D grids, and per-copy rotation/scale ramps.

    Returns the list of created nodes (the original is not included).
    """
    orig = get_external_node(node_id)
    if not orig:
        return []
    count = max(1, int(count))
    rows = max(1, int(rows))
    total = count * rows
    if total > 512:
        push_toast("Array capped at 512 copies.", "warning", 2.5)
        rows = max(1, 512 // max(1, count))
    made = []
    import copy as _copy
    scene_undo_push(f"Array x{count * rows}")
    for ri in range(rows):
        for ci in range(count):
            if ri == 0 and ci == 0:
                continue    # the original occupies slot (0,0)
            clone = _copy.deepcopy(orig)
            clone["id"] = _en_new_id()
            clone["_rect"] = None
            dx = step_x * ci + row_step_x * ri
            dy = step_y * ci + row_step_y * ri
            if clone.get("camera_locked"):
                # Camera-locked nodes live in fractional screen space, so a
                # pixel step has to be converted or the array collapses.
                clone["fx"] = max(0.0, min(1.0, float(clone.get("fx", 0.5)) + dx / max(1, WIDTH)))
                clone["fy"] = max(0.0, min(1.0, float(clone.get("fy", 0.5)) + dy / max(1, HEIGHT)))
            else:
                clone["wx"] = float(orig.get("wx", 0.0)) + dx
                clone["wy"] = float(orig.get("wy", 0.0)) + dy
                if "wx2" in clone:
                    clone["wx2"] = float(orig.get("wx2", 0.0)) + dx
                if "wy2" in clone:
                    clone["wy2"] = float(orig.get("wy2", 0.0)) + dy
            idx = ri * count + ci
            if rot_step:
                clone["rotation"] = (float(orig.get("rotation", 0.0)) + rot_step * idx) % 360
            if scale_step:
                clone["scale"] = max(0.02, float(orig.get("scale", 1.0)) + scale_step * idx)
            base_name = str(orig.get("name") or orig.get("kind") or "node")
            clone["name"] = f"{base_name}_{idx:02d}"
            external_nodes.append(clone)
            made.append(clone)
    if made and group_result:
        try:
            ids = [orig["id"]] + [m["id"] for m in made]
            group_selected_scene_nodes(ids, name=f"{orig.get('name') or 'array'}_array")
        except Exception:
            pass
    try:
        en_tag_index_rebuild()
    except Exception:
        pass
    return made

def duplicate_external_node(node_id):
    orig = get_external_node(node_id)
    if not orig:
        return None
    if "scene_undo_push" in globals():
        scene_undo_push("Duplicate node")
    import copy
    clone = copy.deepcopy(orig)
    clone["id"] = _en_new_id()
    clone["wx"] = float(orig.get("wx", 0) + 20)
    clone["wy"] = float(orig.get("wy", 0) + 20)
    if "wx2" in clone:
        clone["wx2"] = float(orig.get("wx2", 0) + 20)
    if "wy2" in clone:
        clone["wy2"] = float(orig.get("wy2", 0) + 20)
    clone["name"] = f"{orig.get('name', 'node')}_copy"
    external_nodes.append(clone)
    return clone

def roll_damage(c):
    """Roll ordinary body/contact damage (projectiles/colliders stay separate)."""
    lo=int(round(float(c.get("contact_damage_min",c.get("dmg_min",0)))));hi=int(round(float(c.get("contact_damage_max",c.get("dmg_max",lo)))))
    if hi<lo:lo,hi=hi,lo
    dmg=random.randint(max(0,lo),max(0,hi))
    chance=max(0.0,min(1.0,float(c.get("contact_crit_chance",c.get("crit_chance",0.0)))))
    crit=random.random()<chance
    if crit:
        mult=max(1.0,float(c.get("contact_crit_damage_percent",float(c.get("crit_mult",1.5))*100.0))/100.0);dmg=int(round(dmg*mult))
    return dmg,crit

def spawn_popup(pos, text, color, crit=False, target=None, amount=None, font_name=None, font_size=None, font_bold=None):
    if target is not None and isinstance(target, dict) and target.get("show_damage_numbers") is False:
        return
    combo_key = id(target) if target is not None else None
    if SETTINGS.get("damage_stack") and combo_key is not None and amount is not None:
        for p in reversed(popups):
            if p.get("combo_key") == combo_key and p.get("life", 0) > 0:
                p["combo_total"] = p.get("combo_total", 0) + int(amount)
                p["combo_count"] = p.get("combo_count", 1) + 1
                p["text"] = f"-{p['combo_total']}"
                p["life"] = p.get("total_life", 1.0)
                p["pos"] = pygame.Vector2(pos)
                p["color"] = tuple(SETTINGS.get("combo_damage_color", [130, 220, 255]))
                p["crit"] = p.get("crit", False) or crit
                p["seed"] = random.uniform(0, 1000)
                return
    _dur = max(0.1, float(SETTINGS.get("dmg_duration", 1.0)))
    popups.append({
        "text": text, "pos": pygame.Vector2(pos), "life": _dur, "total_life": _dur,
        "color": color, "crit": crit, "seed": random.uniform(0, 1000),
        "font_name": font_name or SETTINGS.get("damage_font_name", "segoeui"),
        "font_size_override": font_size,
        "font_bold_override": font_bold if font_bold is not None else True,
        "combo_key": combo_key,
        "combo_total": int(amount) if amount is not None else None,
        "combo_count": 1,
    })

_DAMAGE_TEST_LOOP={"enabled":False,"next":0.0,"count":0,"interval":0.32}


def set_damage_test_loop(enabled=None):
    state=(not _DAMAGE_TEST_LOOP.get("enabled",False)) if enabled is None else bool(enabled);_DAMAGE_TEST_LOOP["enabled"]=state;_DAMAGE_TEST_LOOP["next"]=0.0
    push_toast("Damage-number preview loop ON" if state else "Damage-number preview loop OFF","success" if state else "info",2.0);return state


def _damage_test_loop_tick():
    """Continuously preview normal/critical numbers only while Settings is open."""
    if not _DAMAGE_TEST_LOOP.get("enabled",False):return
    if not ui_visible or active_tab!="style" or modal.get("type") is not None:
        _DAMAGE_TEST_LOOP["next"]=time.monotonic();return
    now=time.monotonic()
    if now<float(_DAMAGE_TEST_LOOP.get("next",0)):return
    count=int(_DAMAGE_TEST_LOOP.get("count",0));crit=(count%4)==3;amount=random.randint(55,125) if crit else random.randint(10,68)
    # Spread previews around the arena center so successive values remain legible.
    angle=(count%10)*(math.tau/10.0);radius=35+18*(count%3);pos=pygame.Vector2(math.cos(angle)*radius,math.sin(angle)*radius*.55)
    color=tuple(SETTINGS.get("crit_damage_color" if crit else "damage_color",[255,90,90] if crit else [255,210,90]));spawn_popup(pos,f"-{amount}{'!' if crit else ''}",color,crit=crit)
    _DAMAGE_TEST_LOOP["count"]=count+1;_DAMAGE_TEST_LOOP["next"]=now+max(.12,float(_DAMAGE_TEST_LOOP.get("interval",.32)))


def spawn_instance(template, near=None):
    box = get_box_rect_world()
    inner = box.inflate(-box_thickness * 2 - 40, -box_thickness * 2 - 40)
    if inner.width < 32 or inner.height < 32:
        inner = box.inflate(-10, -10)
    radius = 16
    # Props and Directors share one authoring type. A hidden prop is a pure
    # Director host; a visible prop is a static scene object with the author's
    # visibility/collision choices. Both remain outside the combat target pool.
    is_scene_prop = bool(template.get("is_scene_prop", False))
    prop_visible = bool(template.get("is_visible", True))
    is_scene_director = bool(is_scene_prop and (template.get("scene_director", False) or not prop_visible))
    if near is not None:
        pos = pygame.Vector2(near) + pygame.Vector2(random.uniform(-30, 30), random.uniform(-30, 30))
        pos.x = max(inner.left + radius, min(inner.right - radius, pos.x))
        pos.y = max(inner.top + radius, min(inner.bottom - radius, pos.y))
    else:
        lo_x, hi_x = inner.left + radius, max(inner.left + radius + 1, inner.right - radius)
        lo_y, hi_y = inner.top + radius, max(inner.top + radius + 1, inner.bottom - radius)
        pos = pygame.Vector2(random.randint(int(lo_x), int(hi_x)), random.randint(int(lo_y), int(hi_y)))

    angle = random.uniform(0, 360)
    vel = pygame.Vector2(0, 0) if is_scene_prop else pygame.Vector2(template["speed"], 0).rotate(angle)
    script_file = template.get("script_file")
    sprite_folder = template.get("sprite_folder")
    sprite_map = dict(template.get("sprite_map", {}))
    script_params = dict(template.get("script_params", {}))
    audio_map = dict(template.get("audio_map", {}))
    audio_volume_map = dict(template.get("audio_volume_map", {}))
    # Every saved library animation is available by name to script nodes.
    # Character-authored state animations override names from the library.
    animation_defs = {}
    animation_fps_map = {}
    animation_duration_defs = {}
    # Global animation clips are loaded on demand by Set Animation State.
    # Auto-injecting every global clip (especially a global "idle") made one
    # character render another character's artwork.
    for key, value in dict(template.get("animations", {})).items():
        animation_defs[str(key)] = list(value)
    for key, value in dict(template.get("animation_fps", {})).items():
        animation_fps_map[str(key)] = float(value)
    for key, value in dict(template.get("animation_durations", {})).items():
        animation_duration_defs[str(key)] = [max(0.02, float(x)) for x in value]
    animation_anchor_map = {}
    for key, value in dict(template.get("animation_anchors", {})).items():
        try:
            animation_anchor_map[str(key)] = (float(value[0]), float(value[1]))
        except (TypeError, IndexError, ValueError):
            pass
    script_ns = load_script_ns_from_file(script_file) or {}
    apply_script_params(script_ns, script_params)

    # legacy folder-convention sprites first (back-compat with characters
    # saved before the per-tag picker existed), then the explicit
    # tag -> asset picks on top, since those are always more specific.
    sprites = dict(load_sprites(sprite_folder)) if sprite_folder else {}
    for tag, rel_path in sprite_map.items():
        img = load_sprite_asset(rel_path)
        if img is not None:
            sprites[tag] = img

    animation_surfaces = {}
    for state, paths in animation_defs.items():
        frames = []
        for rel_path in paths:
            img = load_sprite_asset(rel_path)
            if img is not None:
                frames.append(img)
        if frames:
            animation_surfaces[state] = frames

    inst = {
        "instance_id": str(template.get("instance_id") or generate_character_instance_id()),
        "library_source_name": str(template.get("library_source_name",template.get("name","Fighter"))),
        "name": template["name"], "color": tuple(template["color"]),
        "radius": float(template.get("radius", 16)),
        "contact_trait": str(template.get("contact_trait", "normal")),
        "_contact_traits": list(template.get("contact_traits", [])),
        "collision_shape": str(template.get("collision_shape", "sphere")),
        "collision_radius": float(template.get("collision_radius", 16)),
        "collision_radius_x": float(template.get("collision_radius_x", template.get("collision_radius", 16))),
        "collision_radius_y": float(template.get("collision_radius_y", template.get("collision_radius_x", template.get("collision_radius", 16)))),
        "collision_box_w": float(template.get("collision_box_w", 32)),
        "collision_box_h": float(template.get("collision_box_h", 32)),
        "collision_source": str(template.get("collision_source", "custom")),
        "collision_debug_color": list(template.get("collision_debug_color", [110, 195, 255])),
        "collision_debug_editor_visible": bool(template.get("collision_debug_editor_visible", template.get("collision_debug_visible", True))),
        "collision_debug_play_visible": bool(template.get("collision_debug_play_visible", template.get("collision_debug_visible", True))),
        "collision_debug_fill": bool(template.get("collision_debug_fill", True)),
        "collision_offset_x": float(template.get("collision_offset_x", 0.0)),
        "collision_offset_y": float(template.get("collision_offset_y", 0.0)),
        "is_scene_prop": is_scene_prop, "scene_director": is_scene_director,
        # Preserve the authored collider choice even while a prop is hidden as
        # a Director.  Scene Prop Toggle Visibility can later restore it.
        "_prop_has_collision": bool(template.get("has_collision", True)) if is_scene_prop else False,
        # A visible prop honors its authoring flags. A hidden Director remains a
        # non-physical hook host, preserving existing director-only projects.
        "has_collision": bool(template.get("has_collision", True)) if is_scene_prop and not is_scene_director else (False if is_scene_director else bool(template.get("has_collision", True))),
        "is_visible": prop_visible if is_scene_prop and not is_scene_director else (False if is_scene_director else bool(template.get("is_visible", True))),
        "scale": template.get("scale", 1.0),
        "character_center": _character_center_value(template),
        "pos": pos, "vel": vel,
        "max_hp": template["max_hp"], "hp": template.get("hp", template["max_hp"]),
        "dmg_min": template["dmg_min"], "dmg_max": template["dmg_max"],
        "speed": 0.0 if is_scene_prop else template.get("speed", vel.length()),
        "crit_chance": template["crit_chance"], "crit_mult": template["crit_mult"],
        "cooldown": 0.0,
        "script_file": script_file, "script_ns": script_ns, "script_params": script_params,
        "sprite_folder": sprite_folder, "sprite_map": sprite_map, "sprites": sprites,
        "custom_sprite_tags": [str(t) for t in (template.get("custom_sprite_tags") or []) if isinstance(t, str) and t],
        "audio_map": audio_map,
        "audio_volume_map": audio_volume_map,
        "animation_paths": animation_defs,
        "animation_sources": dict(template.get("animation_sources", {})),
        "animations": animation_surfaces,
        "animation_fps": animation_fps_map,
        "animation_durations": animation_duration_defs,
        "animation_anchors": animation_anchor_map,
        "animation_pivots": {str(k):list(v) for k,v in dict(template.get("animation_pivots",{})).items()},
        "animation_position_events": copy.deepcopy(dict(template.get("animation_position_events",{}))),
        "animation_collision_frames": copy.deepcopy(dict(template.get("animation_collision_frames",{}))),
        "animation_layers": copy.deepcopy(dict(template.get("animation_layers",{}))),
        "animation_total_durations": {
            key: sum(values) for key, values in animation_duration_defs.items()
        },
        # Live copies so runtime gear-swaps never mutate the library template.
        "rig": copy.deepcopy(_rig_normalize(template.get("rig"))),
        "anim_machine": copy.deepcopy(_anim_machine_normalize(
            template.get("anim_machine"), known_states=list(dict.fromkeys(list(animation_defs.keys())+list(sprite_map.keys())+list((template.get("animation_layers",{}) or {}).keys()))))),
        "spawn_time": pygame.time.get_ticks() / 1000.0,
        "visual_state_started": pygame.time.get_ticks() / 1000.0,
        "visual_state": "idle", "visual_timer": 0.0,
        "_remove_rect": None, "_row_rect": None,
        "friendly_fire": template.get("friendly_fire", True),
        "team": template.get("team", template.get("name", "default")),
        # Per-character speed limits (enforced every frame in the physics loop)
        # Template can set max_speed/min_speed; otherwise the global cap applies.
        "max_speed": float(template.get("max_speed", MAX_SPEED)),
        "min_speed": float(template.get("min_speed", 0.0)),
        "_smooth_vel": pygame.Vector2(vel),
        "_external_momentum": pygame.Vector2(), # knockback/impulses only
        "_last_bounce_sound": 0.0,
        # Wall-contact state: which arena sides are touched this frame, plus the
        # most recent touch/bounce directions for the query (pure) nodes.
        "_wall_contacts": set(), "_block_contacts": set(), "_tilt_angle": 0.0, "_hop_ready": True,
        "_last_wall_touch_dir": pygame.Vector2(0, 0), "_last_wall_touch_time": -9999.0,
        "_last_bounce_dir": pygame.Vector2(0, 0), "_last_bounce_time": -9999.0,
        "_last_character_touch_time": -9999.0, "_last_character_touch_other": None,
        "_last_character_bounce_time": -9999.0, "_last_character_bounce_other": None,
        "_last_character_bounce_dir": pygame.Vector2(0,0),
        # Manual input / platformer physics state controlled by Input and Physics nodes.
        # Gravity stays opt-in: the original arena is a free-bouncing, horizontal
        # arena unless a Physics Gravity node enables platformer gravity.  Keep
        # restitution at 1.0 here so an ordinary character preserves the old
        # full-speed wall/floor bounce; the Earth/Moon/Rigid Body presets replace
        # this with their configured restitution when they are actually used.
        "gravity": 0.0, "gravity_scale": 1.0, "gravity_enabled": False,
        "gravity_grounded": False, "terminal_velocity": 1200.0,
        "mass": 1.0, "bounce": 1.0, "air_control": 1.0,
        "manual_input_enabled": not is_scene_prop, "_input_vector": pygame.Vector2(0, 0),
        "control_mode": "manual", "collision_mode": "solid",
        "body_type": "static" if is_scene_prop else "dynamic", "restitution": 1.0, "ground_friction": 1.0,
        "show_hp_bar": False if is_scene_prop else None,
        "show_name": True if is_scene_prop else None,
        # Characters still separate when their bodies touch, but they do not
        # exchange velocity by default. Knockback and wall ricochets therefore
        # remain the only sources of momentum unless a script opts into it.
        "character_collision_response": "separate", # separate | reflect | transfer
        # Contact velocity is opt-in. This prevents an unrelated character
        # bump from rewriting a controlled knockback vector.
        "inherit_collision_speed": False,
        "collision_lock_min_speed": False,
        "character_collision_restitution": 1.0,
        "character_contact_recoil": 120.0, # fixed reaction; never copies impact speed
        "character_contact_recoil_duration": 0.12,
        "linear_damping": 0.0, "angular_damping": 0.0, "sleeping": False,
        "freeze_x": False, "freeze_y": False, "collision_layer": 1,
        "collision_mask": 1, "ccd": False, "floor_snap": 0.0,
        "motion_mode": "floating", "up_direction": pygame.Vector2(0, -1),
    }
    call_hook(inst, "on_spawn", CTX, inst)
    return inst

