def set_script_params_ui(filename):
    """Populate modal fields for a script's PARAMS dict (or clear them),
    and refresh the list of sprite tags available for this script (the
    built-in idle/attack/hit plus anything the script's SPRITE_TAGS
    declares)."""
    # Preserve the character's currently typed overrides while refreshing a
    # graph-generated script. Previously Save Blueprint rebuilt these rows
    # from scratch, which made parameters appear to vanish/reset.
    previous_values = {
        k: modal.get("fields", {}).get(f"param:{k}")
        for k in modal.get("param_order", [])
        if f"param:{k}" in modal.get("fields", {})
    }
    for k in modal.get("param_order", []):
        modal["fields"].pop(f"param:{k}", None)
    if not filename:
        modal["param_order"] = []
        modal["param_types"] = {}
        modal["ns_preserved_params"] = {}
    else:
        defaults = peek_script_params(filename)
        # Reset preserved params to match the actual script — no stale leakage
        modal["ns_preserved_params"] = dict(defaults)
        modal["param_order"] = list(defaults.keys())
        rich_types = peek_script_param_types(filename)
        modal["param_types"] = {}
        for k, v in defaults.items():
            inferred = type(v).__name__
            # Imported source-only scripts cannot declare graph metadata, so
            # animation-like names still get a proper library picker.
            if isinstance(v, str) and any(token in k.lower() for token in ("animation", "anim", "effect_clip")):
                inferred = "animation"
            modal["param_types"][k] = rich_types.get(k, inferred)
        for k, v in defaults.items():
            preserved = previous_values.get(k)
            modal["fields"][f"param:{k}"] = preserved if preserved is not None else str(v)
    modal["sprite_tags"] = get_all_tags_for_script(filename)
    # Custom tags the user added in the character editor (and saved onto
    # the character template as `custom_sprite_tags`) must also appear in
    # the resolved tag list, otherwise reopening the editor would make
    # them disappear. Merge them in after the script-derived tags.
    for _ct in modal.get("custom_sprite_tags", []) or []:
        _ct = normalize_sprite_tag(_ct)
        if _ct and _ct not in modal["sprite_tags"]:
            modal["sprite_tags"].append(_ct)
    # drop any assigned sprites for tags this script no longer declares,
    # so stale picks don't linger invisibly
    modal["sprite_map"] = {
        tag: path for tag, path in modal.get("sprite_map", {}).items()
        if tag in modal["sprite_tags"]
    }

def open_add_character_modal(edit_template=None):
    """Open the character modal for a library template OR one live scene instance.
    Live edits apply only to that exact instance and preserve its scene position."""
    global modal_scroll
    modal["type"] = "add_character"
    modal["editing"] = edit_template
    modal["_editing_original_name"] = str((edit_template or {}).get("library_source_name",(edit_template or {}).get("name",""))) if isinstance(edit_template,dict) else ""
    modal["_apply_live_to_library"] = False
    if edit_template is not None:
        modal["fields"] = {
            "Name": edit_template["name"],
            "Max HP": str(edit_template["max_hp"]),
            "Min Damage": str(edit_template["dmg_min"]),
            "Max Damage": str(edit_template["dmg_max"]),
            "Crit Chance %": str(round(edit_template["crit_chance"] * 100, 3)),
            "Crit Multiplier": str(edit_template["crit_mult"]),
            "Speed": str(edit_template["speed"]),
            "Scale": str(edit_template.get("scale", 1.0)),
        }
        modal["is_scene_prop"] = bool(edit_template.get("is_scene_prop", False))
        modal["has_collision"] = bool(edit_template.get("has_collision", True))
        modal["is_visible"] = bool(edit_template.get("is_visible", True))
        modal["color"] = tuple(edit_template["color"])
        modal["script_file"] = edit_template.get("script_file")
        modal["sprite_folder"] = edit_template.get("sprite_folder")
        modal["sprite_map"] = dict(edit_template.get("sprite_map", {}))
        modal["audio_map"] = dict(edit_template.get("audio_map", {}))
        modal["audio_volume_map"] = dict(edit_template.get("audio_volume_map", {}))
        _editing_live = any(edit_template is c for c in characters)
        _editing_anim_source = (edit_template.get("animation_paths", {})
                                if _editing_live else edit_template.get("animations", {}))
        modal["animation_frames"] = {k: list(v) for k, v in dict(_editing_anim_source or {}).items()}
        modal["animation_frame_offsets"] = {k: [list(x) for x in v] for k, v in dict(edit_template.get("animation_frame_offsets", {})).items()}
        modal["animation_fps"] = dict(edit_template.get("animation_fps", {}))
        modal["animation_durations"] = {k: list(v) for k, v in dict(edit_template.get("animation_durations", {})).items()}
        modal["animation_sources"] = dict(edit_template.get("animation_sources", {}))
        # The editor sliders mutate pivot values in place, so anchors must be lists
        # rather than tuples.
        modal["animation_anchors"] = {k: list(v) for k, v in dict(edit_template.get("animation_anchors", {})).items()}
        modal["animation_pivots"] = {k: list(v) for k, v in dict(edit_template.get("animation_pivots", {})).items()}
        modal["animation_position_events"] = copy.deepcopy(dict(edit_template.get("animation_position_events",{})))
        modal["animation_collision_frames"] = copy.deepcopy(dict(edit_template.get("animation_collision_frames",{})))
        modal["animation_state"] = "idle"
        modal["char_rig"] = _rig_normalize(edit_template.get("rig"))
        anim_restore_layers(edit_template.get("animation_layers"))
        modal["anim_machine"] = _anim_machine_normalize(
            edit_template.get("anim_machine"),
            known_states=list(dict(edit_template.get("animations", {})).keys()))
        modal["friendly_fire"] = edit_template.get("friendly_fire", True)
        modal["character_center"] = _character_center_value(edit_template)
        modal["visual_radius"] = float(edit_template.get("radius", edit_template.get("collision_radius", 16)))
        modal["contact_trait"] = str(edit_template.get("contact_trait", "normal"))
        modal["collision_source"] = str(edit_template.get("collision_source", "custom"))
        modal["collision_debug_color"] = list(edit_template.get("collision_debug_color", [110, 195, 255]))
        modal["collision_debug_editor_visible"] = bool(edit_template.get("collision_debug_editor_visible", edit_template.get("collision_debug_visible", True)))
        modal["collision_debug_play_visible"] = bool(edit_template.get("collision_debug_play_visible", edit_template.get("collision_debug_visible", True)))
        modal["collision_debug_fill"] = bool(edit_template.get("collision_debug_fill", True))
        modal["collision_shape"] = edit_template.get("collision_shape", "sphere")
        modal["collision_radius"] = float(edit_template.get("collision_radius", 16))
        modal["collision_radius_x"] = float(edit_template.get("collision_radius_x", edit_template.get("collision_radius", 16)))
        modal["collision_radius_y"] = float(edit_template.get("collision_radius_y", edit_template.get("collision_radius_x", edit_template.get("collision_radius", 16))))
        modal["collision_box_w"] = float(edit_template.get("collision_box_w", 32))
        modal["collision_box_h"] = float(edit_template.get("collision_box_h", 32))
        modal["collision_offset_x"] = float(edit_template.get("collision_offset_x", 0.0))
        modal["collision_offset_y"] = float(edit_template.get("collision_offset_y", 0.0))
        # Restore the custom sprite tags BEFORE set_script_params_ui runs: it
        # merges modal["custom_sprite_tags"] into sprite_tags and then prunes
        # sprite_map picks whose tag isn't declared. Loading them after the
        # call meant the prune saw no custom tags and silently deleted every
        # custom pick on editor reopen (the "my sprite vanished" bug).
        _saved_custom = edit_template.get("custom_sprite_tags") or []
        modal["custom_sprite_tags"] = [
            normalize_sprite_tag(t) for t in _saved_custom
            if isinstance(t, str) and t and normalize_sprite_tag(t) not in BUILTIN_SPRITE_TAGS
        ]
        set_script_params_ui(modal["script_file"])
        for k, v in edit_template.get("script_params", {}).items():
            if f"param:{k}" in modal["fields"] or True:
                modal["fields"][f"param:{k}"] = str(v)
    else:
        modal["fields"] = dict(FIELD_DEFAULTS)
        modal["fields"]["Name"] = f"Fighter{random.randint(1, 99)}"
        modal["color"] = random.choice(PALETTE)
        modal["script_file"] = None
        modal["sprite_folder"] = None
        modal["sprite_map"] = {}
        modal["audio_map"] = {}
        modal["audio_volume_map"] = {}
        set_script_params_ui(None)  # Cleanly reset and clear all parameters for the brand-new character!
        modal["ns_preserved_params"] = {}  # Don't carry old script's PARAMS into new character
        modal["animation_state"] = "idle"
        modal["animation_frames"] = {}
        modal["animation_fps"] = {}
        modal["animation_durations"] = {}
        modal["animation_sources"] = {}
        modal["animation_anchors"] = {}
        modal["animation_pivots"] = {}
        modal["animation_position_events"] = {}
        modal["animation_collision_frames"] = {}
        modal["char_rig"] = _rig_default()
        modal["animation_layers"] = {}
        modal["anim_machine"] = _anim_machine_default()
        modal["param_types"] = {}
        modal["sprite_tags"] = get_all_tags_for_script(None)
        # Brand-new character has no custom sprite tags yet. Saved ones
        # for an EXISTING character are restored a few lines below where
        # the edit_template branch reads them off the template.
        modal["custom_sprite_tags"] = []
        modal["friendly_fire"] = True
        modal["character_center"] = [0.5,0.5]
        # A Director is a prop with its visuals off, not a separate kind --
        # the picker exposes it as a sub-toggle on Prop.
        _ek0 = modal.get("_entity_kind", "character")
        modal["is_scene_prop"] = (_ek0 == "prop")
        modal["scene_director"] = bool(_ek0 == "prop" and modal.get("_entity_director"))
        modal["has_collision"] = True
        modal["is_visible"] = True
        modal["visual_radius"] = 16.0
        modal["contact_trait"] = "normal"
        modal["collision_source"] = "custom"
        modal["collision_debug_color"] = [110, 195, 255]
        modal["collision_debug_editor_visible"] = True
        modal["collision_debug_play_visible"] = True
        modal["collision_debug_fill"] = True
        modal["collision_shape"] = "sphere"
        modal["collision_radius"] = 16.0
        modal["collision_radius_x"] = 16.0
        modal["collision_radius_y"] = 16.0
        modal["collision_box_w"] = 32.0
        modal["collision_box_h"] = 32.0
        modal["collision_offset_x"] = 0.0
        modal["collision_offset_y"] = 0.0
    modal["focus"] = "Name"
    modal_scroll = 0.0

def swap_scene_image(idx):
    """Swap through Arena's Asset Library while preserving every edit field."""
    if not (0<=idx<len(scene_images)):return
    def _pick(rel_path,_idx=idx):
        if not rel_path:return
        full=os.path.join(SPRITES_DIR,str(rel_path).replace("/",os.sep))
        try:new_img=load_sprite_asset(rel_path) or pygame.image.load(full).convert_alpha()
        except Exception as exc:push_toast(f"Failed to load replacement: {exc}","error",4);return
        if "scene_undo_push" in globals():scene_undo_push("Swap scene image")
        img=scene_images[_idx];img["image"]=new_img;img["source_path"]=full;img["image_path"]=None;img["pixel_perfect"]=_sprite_is_pixelart(new_img);modal["editing_image_index"]=_idx;scene_proxy_invalidate();push_toast(f"Swapped image to {os.path.basename(str(rel_path))}","success",2.2)
    open_asset_library(tab="sprites",pick_callback=_pick,return_to="edit_image")


def _add_scene_image_from_rel(rel_path, tile_kwargs=None):
    """Place a sprite from the asset library into the scene as a scene image.

    `tile_kwargs` optionally sets the tiled-backdrop grid on this image
    (dict of e.g. {'tile_enabled': True, 'tile_cols': 3, 'tile_rows': 3}),
    so the same picker drives both a single image and a tiled backdrop."""
    if not rel_path:
        return
    full = os.path.join(SPRITES_DIR, rel_path)
    if not os.path.isfile(full):
        push_toast(f"Image not found: {rel_path}", "error", 3.0)
        return
    try:
        img = pygame.image.load(full).convert_alpha()
    except Exception as e:
        push_toast(f"Failed to load image: {e}", "error", 3.0)
        return
    if "scene_undo_push" in globals():
        scene_undo_push("Add image")
    scene_images.append({
        "image": img,
        "source_path": full,
        "image_path": None,
        # Auto pixel-perfect: a small/palette sprite (e.g. a Terraria sword)
        # renders crisp by default instead of blurring. Big art stays smooth.
        "pixel_perfect": _sprite_is_pixelart(img),
        "fx": 0.5, "fy": 0.5,
        "scale": 1.0,
        "alpha": 255,
        "layer":"front","depth":0,"z_index":0,"hierarchy_parent":None,
        "rotation": 0,
        "flip_x": False,
        "flip_y": False,
        "world_space": False,
        "camera_locked": False,
        "scale_with_zoom": False,
        "vcam_only": False,
        "opacity": 255,        # universal scene-node master opacity
        "blend": "normal",     # normal | add | multiply | screen | subtract
        # Cached non-destructive color grade.
        "tint_color": [255,255,255], "tint_strength": 0.0,
        "darkness": 0.0, "brightness": 1.0, "saturation": 1.0,
        "contrast": 1.0, "hue_shift": 0.0,
        "parallax_x": 1.0,     # 0 = static background, 1 = normal world, >1 = foreground
        "parallax_y": 1.0,
        # Tiled backdrop: repeat this image in a rows x columns grid instead of
        # a single blit.  tile_enabled on + (cols>1 or rows>1) turns it on.  The
        # grid starts at the image's anchor point and extends right/down.
        "tile_enabled": False, "tile_cols": 1, "tile_rows": 1,
        "tile_gap_x": 0.0, "tile_gap_y": 0.0,
        "arena_clip": None,    # None = follow setting, True/False = force
        "splice": {"enabled": False, "axis": "v", "pos": 0.5, "keep": "start"},
        "shadow": {"enabled": False, "offset_x": 6, "offset_y": 6, "color": [0, 0, 0],
                   "alpha": 160, "use_main_splice": True,
                   "splice": {"enabled": False, "axis": "v", "pos": 0.5, "keep": "start"}},
        "_rect": None,
    })
    if tile_kwargs:
        _new_img = scene_images[-1]
        for _k, _v in tile_kwargs.items():
            _new_img[_k] = _v
    ensure_scene_item_ids()
    _new_scene_image = scene_images[-1]
    _root_peers=[it for it in scene_hierarchy_all_items() if it is not _new_scene_image and not it.get("hierarchy_parent")]
    scene_hierarchy_set_local_z(_new_scene_image,max([scene_hierarchy_local_z(it) for it in _root_peers] or [-1])+1)
    modal["_eh_selected"] = scene_hierarchy_key_for(_new_scene_image)
    scene_sel_set_single(_new_scene_image)
    scene_proxy_invalidate()
    push_toast(f"Added '{os.path.basename(rel_path)}' to scene.", "success", 2.0)

def open_add_image_modal(edit_index=None):
    """Open the built-in asset library to pick a scene image, or edit an existing one."""
    if edit_index is None:
        # Open asset library in pick mode — no tkinter, no file manager
        _prev_type = modal.get("type")
        open_asset_library(
            tab="sprites",
            pick_callback=_add_scene_image_from_rel,
            return_to=_prev_type,
        )
        return

    # Editing existing image
    global modal_scroll
    modal["type"] = "edit_image"
    modal["editing_image_index"] = edit_index
    img = scene_images[edit_index]
    modal["image_scale"] = img.get("scale", 1.0)
    modal["image_alpha"] = img.get("alpha", 255)
    modal["image_pixel_perfect"] = img.get("pixel_perfect", False)
    modal["image_layer"] = img.get("layer", "front")
    modal["image_depth"] = img.get("z_index",img.get("depth",0))
    modal["image_rotation"] = img.get("rotation", 0)
    modal["image_world_space"] = img.get("world_space", False)
    modal["image_camera_locked"] = img.get("camera_locked", False)
    modal["image_scale_with_zoom"] = img.get("scale_with_zoom", False)
    modal["image_scale_with_frame"] = img.get("scale_with_frame", False)
    modal["image_vcam_only"] = img.get("vcam_only", False)
    modal["image_anchor_x"] = img.get("anchor_x", 0.5)
    modal["image_anchor_y"] = img.get("anchor_y", 0.5)
    modal["image_flip_x"] = bool(img.get("flip_x", False))
    modal["image_flip_y"] = bool(img.get("flip_y", False))
    modal["image_opacity"] = img.get("opacity", 255)
    modal["image_parallax_x"] = float(img.get("parallax_x", 1.0))
