def _scene_modal_blend_zorder(px, pw, by, off, mkey, item, mouse_pos, click):
    """Blend-mode picker + draw-order nudges for the text/image modals.

    External nodes got these in their inspector, but scene texts and images
    are edited through their own modals, which never received the controls --
    so the fields existed and were honoured at draw time yet were unreachable
    from the UI. This renders both rows and returns the new vertical offset.
    """
    _blend_rects = []
    _z_rects = []
    screen.blit(font_tiny.render("BLEND", True, TEXT_FAINT), (px, by(off)))
    off += 15
    _bw = (pw - 16) // 5
    _cur = str(modal.get(mkey + "_blend", "normal") or "normal")
    for _i, _bm in enumerate(SCENE_BLEND_MODES):
        _r = pygame.Rect(px + _i * (_bw + 4), by(off), _bw, 20)
        _act = (_cur == _bm)
        _hov = _r.collidepoint(mouse_pos)
        ui_draw_rect(screen, ACCENT if _act else (PANEL_BG_ALT if _hov else FIELD_BG),
                         _r, border_radius=4)
        ui_draw_rect(screen, ACCENT if _act else PANEL_BORDER, _r, width=1, border_radius=4)
        _s = font_tiny.render(_bm[:4], True,
                              (10, 10, 14) if _act else (TEXT_MAIN if _hov else TEXT_DIM))
        screen.blit(_s, (_r.centerx - _s.get_width() // 2, _r.centery - _s.get_height() // 2))
        # Clicks are resolved in the MOUSEBUTTONDOWN block, not here: modals
        # are drawn AFTER events are processed, so on the frame of a click
        # these rects don't exist yet and left_click_this_frame is already
        # False. We publish them instead.
        _blend_rects.append((_bm, pygame.Rect(_r)))
    modal[mkey + "_blend_rects"] = _blend_rects
    off += 26

    # Draw-order nudges act on the LIVE item immediately (not on Save), since
    # they're relative operations against the current scene -- deferring them
    # to a modal commit would compare against stale neighbours.
    screen.blit(font_tiny.render("DRAW ORDER", True, TEXT_FAINT), (px, by(off)))
    off += 15
    _zb = (pw - 12) // 4
    for _zi, (_zl, _zmode) in enumerate([("To Back", "back"), ("Back 1", "down"),
                                         ("Fwd 1", "up"), ("To Front", "front")]):
        _r = pygame.Rect(px + _zi * (_zb + 4), by(off), _zb, 20)
        _hov = _r.collidepoint(mouse_pos)
        ui_draw_rect(screen, PANEL_BG_ALT if _hov else FIELD_BG, _r, border_radius=4)
        ui_draw_rect(screen, ACCENT if _hov else PANEL_BORDER, _r, width=1, border_radius=4)
        _s = font_tiny.render(_zl, True, TEXT_MAIN if _hov else TEXT_DIM)
        screen.blit(_s, (_r.centerx - _s.get_width() // 2, _r.centery - _s.get_height() // 2))
        _z_rects.append((_zmode, pygame.Rect(_r)))
    modal[mkey + "_zorder_rects"] = _z_rects
    off += 24
    if item is not None:
        screen.blit(font_tiny.render(f"current depth: {int(item.get('depth', 0))}",
                                     True, TEXT_FAINT), (px, by(off)))
    off += 18
    return off

