def confirm_add_text():
    text = modal["fields"].get("Text", "").strip()
    if not text:
        close_modal()
        return
    scene_undo_push("Edit text" if modal.get("editing_text_index") is not None else "Add text")
    size = max(8, safe_int(modal["fields"].get("Text Size", "28"), 28))
    idx = modal.get("editing_text_index")
    if idx is not None and 0 <= idx < len(scene_texts):
        t = scene_texts[idx]
        old_ws = t.get("world_space", False)
        new_ws = modal.get("text_world_space", False)
        
        t["text"] = text
        t["size"] = size
        t["color"] = tuple(modal["color"])
        t["outline"] = modal.get("text_outline", True)
        t["layer"] = modal.get("text_layer", "front")
        t["depth"]=modal.get("text_depth",0);t["z_index"]=int(t["depth"])
        t["rotation"] = modal.get("text_rotation", 0)
        t["world_space"] = new_ws
        t["camera_locked"] = modal.get("text_camera_locked", False)
        t["shake_level"] = modal.get("text_shake_level", 0.0)
        t["shake_freq"] = modal.get("text_shake_freq", 1.0)
        t["per_letter_shake"] = modal.get("text_per_letter_shake", False)
        t["scale_with_zoom"] = modal.get("text_scale_with_zoom", False)
        t["scale_with_frame"] = modal.get("text_scale_with_frame", False)
        t["font_name"] = modal.get("text_font_name", "segoeui")
        t["vcam_only"] = modal.get("text_vcam_only", False)
        t["outline_width"] = modal.get("text_outline_width", 1)
        t["opacity"] = modal.get("text_opacity", 255)
        t["parallax_x"] = float(modal.get("text_parallax_x", 1.0))
        t["parallax_y"] = float(modal.get("text_parallax_y", 1.0))
        t["arena_clip"] = modal.get("text_arena_clip", None)
        t["blend"] = modal.get("text_blend", "normal")
        t["align"] = modal.get("text_align", "center")
        t.setdefault("bold", False)

        if not old_ws and new_ws:
            # Locking to world position: convert current fx/fy to wx/wy
            sx = t.get("fx", 0.5) * WIDTH
            sy = t.get("fy", 0.5) * HEIGHT
            wpos = screen_to_world((sx, sy))
            t["wx"] = float(wpos.x)
            t["wy"] = float(wpos.y)
        elif old_ws and not new_ws:
            # Unlocking from world position: convert current wx/wy to fx/fy
            sp = world_to_screen_for(pygame.Vector2(t.get("wx", 0), t.get("wy", 0)), WIDTH, HEIGHT)
            t["fx"] = max(0.0, min(1.0, sp.x / max(1, WIDTH)))
            t["fy"] = max(0.0, min(1.0, sp.y / max(1, HEIGHT)))
    else:
        # Always create in screen space first. User can drag it, then
        # toggle "Lock to Scene" in the edit modal to make it world-fixed.
        wcenter = screen_to_world((WIDTH // 2, HEIGHT // 2))
        scene_texts.append({
            "text": text, "size": size, "color": tuple(modal["color"]),
            "outline": modal.get("text_outline", True), "layer": modal.get("text_layer", "front"),
            "depth":modal.get("text_depth",0),"z_index":int(modal.get("text_depth",0)),"hierarchy_parent":None,
            "rotation": modal.get("text_rotation", 0),
            "world_space": False,
            "camera_locked": modal.get("text_camera_locked", False),
            "fx": 0.5, "fy": 0.5,
            "wx": float(wcenter.x), "wy": float(wcenter.y),
            "shake_level": modal.get("text_shake_level", 0.0),
            "shake_freq": modal.get("text_shake_freq", 1.0),
            "per_letter_shake": modal.get("text_per_letter_shake", False),
            "scale_with_zoom": modal.get("text_scale_with_zoom", False),
            "font_name": modal.get("text_font_name", "segoeui"),
            "vcam_only": modal.get("text_vcam_only", False),
            "opacity": modal.get("text_opacity", 255),
            "parallax_x": modal.get("text_parallax_x", 1.0),
            "parallax_y": modal.get("text_parallax_y", 1.0),
            "arena_clip": modal.get("text_arena_clip", None),
            "blend": modal.get("text_blend", "normal"),
            "align": modal.get("text_align", "center"),
            "bold": False, "outline_width": modal.get("text_outline_width", 1),
        })
    close_modal()

