def open_asset_browser(tag):
    """Open the modern F10 Asset Library to pick a character sprite state.

    This replaces the old flat ``browse_asset`` thumbnail wall. The callback
    returns directly to the Character Selector with its in-progress form still
    intact, while the library provides folders, search, previews and import.
    """
    tag = str(tag)
    current = str((modal.get("sprite_map") or {}).get(tag, "") or "")

    def _pick_character_state_sprite(rel_path, _tag=tag):
        modal.setdefault("sprite_map", {})[_tag] = str(rel_path)
        _sync_sprite_image_nodes(modal.get("script_file"), _tag, str(rel_path))
        modal["focus"] = None
        push_toast(f"Assigned {os.path.basename(str(rel_path))} to {_tag.replace('_', ' ').title()}.",
                   "success", 2.0)

    open_asset_library("sprites", pick_callback=_pick_character_state_sprite,
                       return_to="add_character")
    # Preserve context when re-opening a picker: selected sprite and its
    # folder are already focused instead of dumping the user at a giant grid.
    if current:
        modal["_al_sel"] = current
        modal["_al_sel_set"] = {current}
        try:
            modal["_al_folder"] = sprite_folder_of(current)
        except Exception:
            pass

def _scan_user_font_files():
    """Walk the OS's actual font directories for .ttf/.otf/.ttc files.

    pygame.font.get_fonts() only returns whatever pygame's system font cache
    had at import time, which frequently misses fonts installed after the
    process started, per-user-only installs, or fonts that never got
    properly registered with the OS's font-matching system. Scanning the
    real directories catches everything that's actually on disk.
    """
    exts = (".ttf", ".otf", ".ttc")
    home = os.path.expanduser("~")
    dirs = []
    if sys.platform.startswith("win"):
        dirs += [
            os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts"),
            os.path.join(os.environ.get("LOCALAPPDATA", os.path.join(home, "AppData", "Local")), "Microsoft", "Windows", "Fonts"),
        ]
    elif sys.platform == "darwin":
        dirs += ["/Library/Fonts", "/System/Library/Fonts", os.path.join(home, "Library", "Fonts")]
    else:
        dirs += ["/usr/share/fonts", "/usr/local/share/fonts",
                 os.path.join(home, ".fonts"), os.path.join(home, ".local", "share", "fonts")]

    found = []
    seen_names = set()
    for d in dirs:
        if not d or not os.path.isdir(d):
            continue
        try:
            for root, _sub, files in os.walk(d):
                for fn in files:
                    if fn.lower().endswith(exts):
                        key = fn.lower()
                        if key in seen_names:
                            continue
                        seen_names.add(key)
                        found.append(os.path.join(root, fn))
        except Exception:
            continue
    return found

_FONT_FILE_CACHE = None

def _font_display_label(item):
    """Human-friendly label for a font list entry — basename without
    extension for real font files on disk, the raw name otherwise."""
    if isinstance(item, str) and (os.sep in item or item.lower().endswith((".ttf", ".otf", ".ttc"))):
        return os.path.splitext(os.path.basename(item))[0]
    return item

_FONT_CHOICES_MEMO = {"t": 0.0, "items": None}

_FONT_ROW_LABEL_CACHE = {}

def _font_row_label_surface(item):
    """Rendered 16px sample label for one font-browser row. The text never
    changes for a given font, so rasterise it once and reuse - without this,
    the browser re-created + re-rendered a Font for every row on every frame."""
    key = str(item)
    hit = _FONT_ROW_LABEL_CACHE.get(key)
    if hit is None:
        try:
            sample_font = get_dmg_font(16, item, bold=False)
            hit = sample_font.render(_font_display_label(item)[:34], True, TEXT_MAIN)
            if len(_FONT_ROW_LABEL_CACHE) > 900:
                _FONT_ROW_LABEL_CACHE.clear()
            _FONT_ROW_LABEL_CACHE[key] = hit
        except Exception:
            hit = None
    return hit

def list_font_choices(force=False):
    """All pickable fonts: preferred names + pygame system fonts + real font
    files found on disk. The result is memoised for 15s (and the disk scan is
    cached for the whole session), so the font browser / search no longer
    re-walks the OS font directories and re-sorts hundreds of entries on
    every frame or every keystroke."""
    global _FONT_FILE_CACHE
    now = time.time()
    if (not force and _FONT_CHOICES_MEMO["items"] is not None
            and now - _FONT_CHOICES_MEMO["t"] < 15.0):
        return _FONT_CHOICES_MEMO["items"]
    sys_fonts = sorted(set(pygame.font.get_fonts()))
    if _FONT_FILE_CACHE is None:
        try:
            _FONT_FILE_CACHE = sorted(_scan_user_font_files(), key=lambda p: os.path.basename(p).lower())
        except Exception:
            _FONT_FILE_CACHE = []
    preferred = ["segoeui", "arial", "impact", "georgia", "verdana", "timesnewroman", "consolas", "comicsansms"]
    out = []
    for f in preferred + sys_fonts:
        if f and f not in out:
            out.append(f)
    for p in _FONT_FILE_CACHE:
        if p not in out:
            out.append(p)
    _FONT_CHOICES_MEMO["items"] = out[:400]
    _FONT_CHOICES_MEMO["t"] = now
    return _FONT_CHOICES_MEMO["items"]

def _apply_ease_choice(chosen):
    """Write the ease-browser pick back to whatever slot opened it."""
    chosen = str(chosen or "linear")
    if modal.get("_ease_target") == "bar_smooth":
        _bn = get_external_node(int(modal.get("_en_ease_target_id", -1)))
        if _bn is not None:
            _bn["smooth_ease"] = chosen
            _bn["hp_ease"] = chosen
            _bn.pop("_ease_tween", None)  # retween cleanly with the new curve
    else:
        modal["_ease_choice"] = chosen

def open_ease_browser(target, node_id=None):
    """Open the built-in interpolation/curve picker. `target` selects the
    slot the chosen curve name is written back to:

    * "bar_smooth"  external progress/custom bar `smooth_ease`
                    (node_id = the bar's external-node id)

    The list is the engine's FULL easing system (_EaseCurveOptions):
    legacy quick modes, every built-in curve family, and the user's own
    F8 `curve:` customs."""
    modal["_ease_target"] = target
    if node_id is not None:
        modal["_en_ease_target_id"] = int(node_id)
    modal["ease_search"] = ""
    modal["focus"] = "ease_search"
    open_browser("browse_ease")

def open_font_browser(target):
    """Open the in-app font picker. `target` selects which font slot
    the chosen family is written back to:

    * "damage"      SETTINGS["damage_font_name"]    (floating damage popups)
    * "ui"          App-wide UI chrome              (build_ui_fonts rebuilds
                                                    font_lg/md/sm/tiny/mono
                                                    and resizes the sidebar)
    * "scene_text" / "timer" / "custom_bar"  per-node font slots
    """
    modal["_font_target"] = target
    modal["font_search"] = ""
    modal["focus"] = "font_search"
    open_browser("browse_font")

