# ============================================================
# BLUEPRINT VISUAL SCRIPTER -- scalable node-graph editor
# ============================================================
# This section replaces the old hardcoded visual scripter with a
# data-driven, extensible node architecture. New nodes are added by
# defining a class and decorating it with @register_node; the UI,
# serialization, validation and code generation pick it up automatically.

# ══════════════════════════════════════════════════════════════════════════════
# NODE EXTENSION API  — everything below makes external nodes first-class
# citizens with the same capabilities as internal nodes.
# ══════════════════════════════════════════════════════════════════════════════

# ---------- type system ----------
EXEC = "exec"
NUMBER = "number"
STRING = "string"
BOOLEAN = "boolean"
VECTOR = "vector"
COLOR = "color"
OBJECT = "object"
ANY = "any"

DATA_TYPES = {NUMBER, STRING, BOOLEAN, VECTOR, COLOR, OBJECT, ANY}
PIN_COLORS = {
    "clip": (0, 210, 180),
    EXEC: (230, 230, 240), NUMBER: (78, 210, 138), STRING: (250, 200, 70),
    BOOLEAN: (155, 89, 182), VECTOR: (52, 152, 219), COLOR: (236, 64, 122),
    OBJECT: (230, 126, 34), ANY: (140, 140, 158),
}
_PIN_COLOR_DEFAULTS=dict(PIN_COLORS)


def apply_pin_color_customization():
    custom=_editor_config.get("ns_pin_colors",{}) or {}
    for key,default in _PIN_COLOR_DEFAULTS.items():
        raw=custom.get(str(key),default)
        try:PIN_COLORS[key]=tuple(max(0,min(255,int(v))) for v in list(raw)[:3])
        except Exception:PIN_COLORS[key]=default
    if "audio" in PIN_COLORS or "audio" in custom:
        raw=custom.get("audio",(255,120,200))
        try:PIN_COLORS["audio"]=tuple(max(0,min(255,int(v))) for v in list(raw)[:3])
        except Exception:PIN_COLORS["audio"]=(255,120,200)


apply_pin_color_customization()

def _ns_pins_compatible(source_pin, target_pin):
    """Return whether a dragged output can connect to an input."""
    if source_pin is None or target_pin is None:
        return False
    if source_pin.type == EXEC or target_pin.type == EXEC:
        return source_pin.type == target_pin.type
    return (source_pin.type == target_pin.type
            or source_pin.type == ANY
            or target_pin.type == ANY)

def _ns_mark_invalid_wire(from_id, from_pin, pos, to_id=None, to_pin=None):
    """Keep a short red blinking preview after an invalid drop."""
    modal["ns_invalid_wire_flash"] = {
        "from_id": from_id, "from_pin": from_pin,
        "to_id": to_id, "to_pin": to_pin,
        "pos": tuple(pos), "until": time.time() + 1.35,
    }

def _ns_disconnect_pin(node_id, pin_name, side):
    """Disconnect all links on one visible socket, with undo support."""
    links = modal.get("ns_links", [])
    if side == "input":
        kept = [link for link in links
                if not (link.get("to") == node_id and link.get("to_pin") == pin_name)]
    else:
        kept = [link for link in links
                if not (link.get("from") == node_id and link.get("from_pin") == pin_name)]
    if len(kept) == len(links):
        return False
    ns_snapshot()
    modal["ns_links"] = kept
    modal["ns_dirty"] = True
    push_toast(f"Disconnected {side} pin", "info", 1.8)
    return True

class PinSpec:
    def __init__(self, name, pin_type, default=None, options=None, tooltip="", required=False):
        self.name = name
        self.type = pin_type
        self.default = default
        self.options = options or []
        self.tooltip = tooltip
        # Optional by default. Many object pins deliberately use None to mean
        # "Self", so treating every None default as a validation error made
        # perfectly valid graphs impossible to save.
        self.required = required

class PropSpec:
    def __init__(self, name, prop_type, default=None, options=None, min_val=None, max_val=None, tooltip=""):
        self.name = name
        self.type = prop_type  # number|string|boolean|dropdown|color|vector|script_file
        self.default = default
        self.options = options or []
        self.min = min_val
        self.max = max_val
        self.tooltip = tooltip

NODE_DEFS = {}
NODE_CATEGORIES = {}

# ── Tag / Metadata system for external nodes ──────────────────────────────────
# Every external node can carry arbitrary tags and metadata.  Scripts and
# blueprint nodes use these to find and bind objects without hardcoding IDs.

_EN_TAG_INDEX: dict = {}   # tag -> set of external-node IDs  (rebuilt on query)

def en_tag_index_rebuild():
    """Rebuild the inverted tag index from scratch.  O(N) — call lazily."""
    _EN_TAG_INDEX.clear()
    for n in external_nodes:
        for t in n.get("tags", []):
            _EN_TAG_INDEX.setdefault(str(t), set()).add(n["id"])

def en_add_tag(node_or_id, tag: str) -> None:
    n = node_or_id if isinstance(node_or_id, dict) else get_external_node(node_or_id)
    if n is None: return
    tag = str(tag).strip()
    if not tag: return
    tags = n.setdefault("tags", [])
    if tag not in tags:
        tags.append(tag)
        _EN_TAG_INDEX.setdefault(tag, set()).add(n["id"])

def en_remove_tag(node_or_id, tag: str) -> None:
    n = node_or_id if isinstance(node_or_id, dict) else get_external_node(node_or_id)
    if n is None: return
    tag = str(tag)
    n.get("tags", []).remove(tag) if tag in n.get("tags", []) else None
    _EN_TAG_INDEX.get(tag, set()).discard(n["id"])

def en_find_by_tag(tag: str, include_hidden: bool = False) -> list:
    """Return all external nodes that carry `tag`.  O(k) after indexing.
    By default hidden nodes (visible=False) are excluded, matching the
    behavior most scripts rely on for rendering/highlighting logic. Pass
    include_hidden=True for control-flow lookups (e.g. zeroing a bar's
    value on death) where the node may currently be hidden."""
    ids = _EN_TAG_INDEX.get(str(tag))
    if ids is None:
        en_tag_index_rebuild()
        ids = _EN_TAG_INDEX.get(str(tag), set())
    if include_hidden:
        return [n for n in external_nodes if n["id"] in ids]
    return [n for n in external_nodes if n["id"] in ids and n.get("visible", True)]

def en_find_first_by_tag(tag: str, include_hidden: bool = False):
    nodes = en_find_by_tag(tag, include_hidden=include_hidden)
    return nodes[0] if nodes else None

def en_find_by_group(group: str) -> list:
    return [n for n in external_nodes if n.get("group") == str(group)]

def en_set_meta(node_or_id, key: str, value) -> None:
    """Store arbitrary metadata on an external node — survives save/load."""
    n = node_or_id if isinstance(node_or_id, dict) else get_external_node(node_or_id)
    if n is not None:
        n.setdefault("meta", {})[str(key)] = value

def en_get_meta(node_or_id, key: str, default=None):
    n = node_or_id if isinstance(node_or_id, dict) else get_external_node(node_or_id)
    return n.get("meta", {}).get(str(key), default) if n else default

