# ── Custom draw function registry ─────────────────────────────────────────────
# Any external code can register a draw function by name.
# fn signature: fn(surface, en, sp, w, h, live) -> None
_EN_CUSTOM_DRAW_FNS: dict = {}

def register_custom_draw(name: str, fn) -> None:
    """Register a custom draw function for external nodes.
    fn(surface, en, screen_pos, canvas_w, canvas_h, live) -> None
    """
    _EN_CUSTOM_DRAW_FNS[str(name)] = fn

# ── Arena wall system ─────────────────────────────────────────────────────────
# "arena_walls" is a separate list from external_nodes for performance;
# walls participate in the physics loop, not just the draw loop.

arena_walls: list = []   # list of wall dicts, each referencing an external node id

def generate_arena_walls(thickness=8, color=(60,60,80)):
    """Auto-generate four boundary walls around the current arena box.
    Replaces any existing auto-generated walls. Custom walls are untouched."""
    # Remove previously auto-generated nodes
    auto_ids = {w["ext_id"] for w in arena_walls if w.get("auto")}
    external_nodes[:] = [n for n in external_nodes if n["id"] not in auto_ids]
    arena_walls[:] = [w for w in arena_walls if not w.get("auto")]

    half = box_scale / 2
    segments = [
        # (wx1, wy1, wx2, wy2, name)
        (-half, -half,  half, -half, "wall_top"),
        (-half,  half,  half,  half, "wall_bottom"),
        (-half, -half, -half,  half, "wall_left"),
        ( half, -half,  half,  half, "wall_right"),
    ]
    for wx1, wy1, wx2, wy2, name in segments:
        n = make_external_node("wall", wx=wx1, wy=wy1,
                               wx2=wx2, wy2=wy2,
                               name=name, color=list(color),
                               thickness=thickness, collision=True)
        n["tags"] = ["auto_wall", "arena_wall"]
        arena_walls.append({"ext_id": n["id"], "auto": True, "name": name})

# ── Patched make_external_node — inject extended defaults ─────────────────────
# We monkey-patch after definition so the original signature is unchanged.
_orig_make_external_node = make_external_node

def make_external_node(kind, wx=0, wy=0, **props):
    if "scene_undo_push" in globals():
        scene_undo_push(f"Create {kind.replace('_', ' ')}")
    n = _orig_make_external_node(kind, wx, wy, **props)
    # Inject universal extended fields (only the ones not already set)
    for k, v in _EN_EXTENDED_DEFAULTS["_universal"].items():
        n.setdefault(k, v if not isinstance(v, (list, dict)) else type(v)(v))
    # Inject kind-specific extended defaults
    for k, v in _EN_EXTENDED_DEFAULTS.get(kind, {}).items():
        n.setdefault(k, v if not isinstance(v, (list, dict)) else type(v)(v))
    n["created_at"] = time.time()
    return n

# Rebuild tag index whenever a new node is made
_orig_en_append = external_nodes.append  # capture list method

class _TrackedExtList(list):
    """Thin list subclass that keeps the tag index warm on append/pop."""
    def append(self, item):
        super().append(item)
        for t in item.get("tags", []):
            _EN_TAG_INDEX.setdefault(str(t), set()).add(item["id"])
    def remove(self, item):
        for t in item.get("tags", []):
            _EN_TAG_INDEX.get(str(t), set()).discard(item["id"])
        super().remove(item)

# Replace the module-level list with the tracked version
import sys as _sys
_frame_locals = _sys._getframe(0).f_locals   # module globals
# Can't easily swap a list in-place across all references so we use the
# mutation approach instead: clear + extend keeps the same object identity.
external_nodes.clear()

