# every function defined later in this file (register_node, graph_diagnostics, etc.)
try:
    from node_dictionary import NODE_TIPS
except ImportError:
    NODE_TIPS = {}  # graceful fallback if the file is missing

# Only these data-style nodes receive optional white flow-through sockets.
# Most values are intentionally kept data-only so the canvas does not become
# a wall of white pins. Nodes that already declare real EXEC pins are never
# modified or removed by this list.
_UNIVERSAL_FLOW_KEYS = {
    # Basic arithmetic that is commonly used as a step in a control chain.
    "math_add", "math_subtract", "math_multiply", "math_divide",
    "math_clamp", "math_min", "math_max", "math_abs", "math_floor",
    "math_ceil", "math_round", "math_power", "math_sqrt", "math_modulo",
    # Comparisons are useful between a math step and If / Else.
    "condition_compare_number", "condition_compare_text", "condition_compare_boolean",
    "math_is_near",
}

def register_node(key, category, title, description=""):
    def decorator(cls):
        cls.key = key
        cls.category = category
        cls.title = title
        cls.description = description
        cls.inputs = list(getattr(cls, "inputs", []))
        cls.outputs = list(getattr(cls, "outputs", []))
        cls.properties = dict(getattr(cls, "properties", {}))

        # Every non-event, non-clip node gets optional white flow-through
        # sockets.  Pure math/data nodes can now participate in a white
        # execution chain (for example If/Else false -> Subtract -> Set
        # Variable) without changing their colored data pins.  Mark these
        # sockets so diagnostics do not complain that an optional data node
        # is "unreachable" just because its white sockets are unused.
        cls._has_universal_flow = False
        if key in _UNIVERSAL_FLOW_KEYS and category not in ("Events", "Clips"):
            if not any(p.type == EXEC for p in cls.inputs):
                _flow_in = PinSpec("", EXEC, tooltip="Optional execution input")
                _flow_in.universal_flow = True
                cls.inputs.insert(0, _flow_in)
                cls._has_universal_flow = True
            if not any(p.type == EXEC for p in cls.outputs):
                _flow_out = PinSpec("", EXEC, tooltip="Optional execution output")
                _flow_out.universal_flow = True
                cls.outputs.append(_flow_out)
                cls._has_universal_flow = True
        # Automatic systematic locking analyzer
        cls.overrides_hp = getattr(cls, "overrides_hp", False)
        cls.overrides_damage = getattr(cls, "overrides_damage", False)
        cls.overrides_crit = getattr(cls, "overrides_crit", False)
        cls.overrides_speed = getattr(cls, "overrides_speed", False)
        cls.overrides_scale = getattr(cls, "overrides_scale", False)

        text_to_check = f"{key} {title} {description}".lower()
        
        # 1. HP Overrides
        if "hp" in text_to_check or "health" in text_to_check:
            if any(x in text_to_check for x in ("set", "modify", "add", "subtract", "stage", "healing", "heal")):
                cls.overrides_hp = True
                
        # 2. Damage Overrides
        if "damage" in text_to_check or "dmg" in text_to_check or "attack" in text_to_check or "atk" in text_to_check:
            if any(x in text_to_check for x in ("set", "modify", "add", "deal", "change", "recoil", "stage", "impact", "hit")):
                cls.overrides_damage = True
                
        # 3. Crit Overrides
        if "crit" in text_to_check:
            if any(x in text_to_check for x in ("set", "modify", "chance", "multiplier", "mult", "add", "reset", "check")):
                cls.overrides_crit = True
                
        # 4. Speed / Velocity Overrides
        if "speed" in text_to_check or "velocity" in text_to_check or "vel" in text_to_check or "move" in text_to_check:
            if any(x in text_to_check for x in ("set", "modify", "preset", "limit", "physics", "slide", "force", "launch")):
                cls.overrides_speed = True
                
        # 5. Scale Overrides
        if "scale" in text_to_check:
            if any(x in text_to_check for x in ("set", "modify", "change", "world")):
                cls.overrides_scale = True

        NODE_DEFS[key] = cls
        NODE_CATEGORIES.setdefault(category, []).append(key)
        return cls
    return decorator

class DynamicPinSpec:
    """Reusable variable-pin-count system for node classes.

    Declares that N of a node's pins are "slots" that appear/disappear live
    as a number property is adjusted in the inspector, instead of always
    being a fixed count. Any NEW node can opt into this the same way:

        class MyNode(NodeBase):
            properties = {"count": PropSpec("count", "number", 3, min_val=2, max_val=6)}
            inputs = [PinSpec("", EXEC)]
            outputs = [PinSpec("", EXEC)] + DynamicPinSpec.make_slots(
                "out_{i}", "Outcome {i}", EXEC, 6)
            dynamic_pins = DynamicPinSpec("count", 2, 6, side="outputs")

    `count_prop`  -- name of the number PropSpec that controls how many
                     slot pins are currently visible/usable (clamped to
                     [min_n, max_n]).
    `side`        -- "outputs", "inputs", or "both". Pins built via
                     make_slots() and placed in cls.inputs/cls.outputs are
                     tagged so resolve() knows which ones it's allowed to
                     trim; any non-slot pins (e.g. the main exec-in, or
                     always-present data pins) are always kept.
    """
    def __init__(self, count_prop, min_n, max_n, side="outputs"):
        self.count_prop = count_prop
        self.min_n = min_n
        self.max_n = max_n
        self.side = side

    def resolve(self, cls, node, full_list):
        n = cls.prop_value(node, self.count_prop, self.max_n)
        try:
            n = int(n)
        except (TypeError, ValueError):
            n = self.max_n
        n = max(self.min_n, min(self.max_n, n))
        out = []
        slot_seen = 0
        for p in full_list:
            if getattr(p, "_dyn_slot", False):
                slot_seen += 1
                if slot_seen > n:
                    continue
            out.append(p)
        return out

    @staticmethod
    def make_slots(name_fmt, label_fmt, pin_type, count, **pin_kwargs):
        """Build `count` PinSpecs (1-indexed via {i} in the format strings),
        each flagged as a trim-able dynamic slot for use with DynamicPinSpec."""
        pins = []
        for i in range(1, count + 1):
            p = PinSpec(name_fmt.format(i=i), pin_type, tooltip=label_fmt.format(i=i), **pin_kwargs)
            p._dyn_slot = True
            pins.append(p)
        return pins

class NodeBase:
    key = ""
    category = ""
    title = ""
    description = ""
    inputs = []
    outputs = []
    properties = {}
    pure = False  # if True, output expressions have no side effects

    # ── Dynamic pin count system ──────────────────────────────────────────
    # By default a node's inputs/outputs are the fixed lists declared on the
    # class. A node can opt into a variable pin count (grows/shrinks live as
    # a property changes -- e.g. "how many branches") by setting
    # `dynamic_pins = DynamicPinSpec(...)` on the class (see helper below).
    # Every pin-count callsite should read through get_inputs()/get_outputs()
    # rather than the raw cls.inputs/cls.outputs so this works everywhere.
    dynamic_pins = None  # DynamicPinSpec or None

    @classmethod
    def get_inputs(cls, node):
        dp = cls.dynamic_pins
        if dp and dp.side in ("inputs", "both"):
            return dp.resolve(cls, node, cls.inputs)
        return cls.inputs

    @classmethod
    def get_outputs(cls, node):
        dp = cls.dynamic_pins
        if dp and dp.side in ("outputs", "both"):
            return dp.resolve(cls, node, cls.outputs)
        return cls.outputs

    @classmethod
    def get_properties(cls, node):
        """Like cls.properties, but drops entries that belong to a currently
        trimmed-away dynamic pin slot (matched by property name == pin name),
        so the inspector panel doesn't keep showing fields for pins that are
        no longer on the node. Nodes using DynamicPinSpec get this for free
        as long as the slot's PropSpec name matches its PinSpec name."""
        dp = cls.dynamic_pins
        if not dp:
            return cls.properties
        visible_names = {p.name for p in cls.get_inputs(node)} | {p.name for p in cls.get_outputs(node)}
        all_slot_pins = [p for p in (cls.inputs + cls.outputs) if getattr(p, "_dyn_slot", False)]
        hidden_names = {p.name for p in all_slot_pins if p.name not in visible_names}
        if not hidden_names:
            return cls.properties
        return {k: v for k, v in cls.properties.items() if k not in hidden_names}

    @classmethod
    def get_input(cls, node, name):
        for p in cls.get_inputs(node):
            if p.name == name:
                return p
        return None

    @classmethod
    def get_output(cls, node, name):
        for p in cls.get_outputs(node):
            if p.name == name:
                return p
        return None

    @classmethod
    def get_prop(cls, node, name):
        return cls.properties.get(name)

    @classmethod
    def prop_value(cls, node, name, fallback=None):
        props = node.get("props", {})
        spec = cls.properties.get(name)
        if name in props:
            return props[name]
        if spec:
            return spec.default
        return fallback

    @classmethod
    def input_expr(cls, ctx, node, pin_name):
        return ctx.get_input_expr(node["id"], pin_name)

    @classmethod
    def output_expr(cls, ctx, node, pin_name):
        return ctx.get_output_expr(node["id"], pin_name)

    @classmethod
    def object_input_expr(cls, ctx, node, pin_name, fallback="me"):
        """Resolve an optional object pin.

        Unconnected pins use the declared fallback (normally Self). Connected
        pins preserve None so failed searches never silently become Self.
        """
        if not ctx.find_input_link(node["id"], pin_name):
            return fallback
        # A connected selector returning None must remain None. Silently
        # replacing it with Self made every target-based action affect the
        # caster whenever a search failed. Use Find/Validate Target's Found
        # execution branch before dereferencing optional targets - the NPC
        # family (npc_*) is None-safe on its own, no Validate gate needed.
        return cls.input_expr(ctx, node, pin_name)

    def generate_code(self, ctx, node, visited):
        """Emit code for this node and continue through the default exec output."""
        ctx.generate_exec_branch(node["id"], "", visited)

    def generate_output_expr(self, ctx, node, output_name):
        return "None"

# ── NodeBase / PropSpec late-patch ────────────────────────────────────────────
# Applied here so both classes are fully defined before we touch them.

# PropSpec: add optional fmt= kwarg for object_ref display hints
_PropSpec_orig_init = PropSpec.__init__
def _PropSpec_new_init(self, name, prop_type, default=None, options=None,
                       min_val=None, max_val=None, tooltip="", fmt=None):
    _PropSpec_orig_init(self, name, prop_type, default, options, min_val, max_val, tooltip)
    self.fmt = fmt
PropSpec.__init__ = _PropSpec_new_init

# NodeBase: add extension class variables inherited by all node subclasses
NodeBase.version          = (1, 0, 0)
NodeBase.tags             = []
NodeBase.deprecated       = False
NodeBase.experimental     = False
NodeBase.min_inputs       = 0
NodeBase.max_inputs       = 0
NodeBase.resizable        = False
NodeBase.color_override   = None
NodeBase.icon_key         = None
NodeBase.inspector_widget = None

# ---------- validation ----------
def graph_diagnostics(nodes, links):
    """Return actionable errors/warnings for the visual graph.

    Each result includes a node id when possible so the UI can select and
    center that node when the user clicks the diagnostic.
    """
    issues = []
    node_ids = set(nodes.keys())

    def add(severity, message, node_id=None, hint=""):
        issues.append({"severity": severity, "message": message,
                       "node_id": node_id, "hint": hint})

    event_ids = []
    for nid, node in nodes.items():
        cls = NODE_DEFS.get(node.get("type"))
        if cls is None:
            add("error", f"Unknown node type: {node.get('type')}", nid,
                "Delete and recreate this node.")
            continue
        if cls.__name__.startswith("Event") or node.get("type") in globals().get("EVENT_TO_HOOK", {}):
            event_ids.append(nid)
        if _ns_node_muted(node):
            add("info", f"{cls.title} is muted; it blocks execution, data, clamps, and downstream flow.",
                nid, "Unmute it from the node docker to restore this path.")
        elif _ns_node_bypassed(node):
            add("info", f"{cls.title} is bypassed; its action is skipped and primary flow continues.",
                nid, "Disable Bypass to execute the node normally.")
        if node.get("type") in ("direction_cardinal", "direction_cardinal_damage",
                                "direction_cardinal_targets", "direction_cardinal_offset"):
            x, y = _cardinal_components(node, cls)
            if x == 0 and y == 0:
                add("warning", f"{cls.title} has no usable direction.", nid,
                    "Enable one direction, or avoid cancelling North with South / East with West.")
        for pin in cls.inputs:
            # A muted node is intentionally disconnected from execution/data;
            # missing required inputs should not prevent saving that graph.
            if _ns_node_muted(node):
                break
            if pin.type == EXEC or not getattr(pin, "required", False):
                continue
            if not any(l["to"] == nid and l["to_pin"] == pin.name for l in links):
                add("error", f"{cls.title}: connect required input '{pin.name}'.",
                    nid, "Drag a compatible output wire into this pin.")

    if nodes and not event_ids:
        add("error", "No Event node starts this graph.", None,
            "Add On Spawn, On Hit, On Kill, Every Frame, or another Event.")

    input_counts = {}
    exec_edges = {}
    for i, link in enumerate(links):
        src_id, dst_id = link.get("from"), link.get("to")
        if src_id not in node_ids or dst_id not in node_ids:
            add("error", f"Wire {i + 1} references a deleted node.", None,
                "Delete the broken wire and reconnect it.")
            continue
        src_cls = NODE_DEFS.get(nodes[src_id].get("type"))
        dst_cls = NODE_DEFS.get(nodes[dst_id].get("type"))
        if src_cls is None or dst_cls is None:
            continue
        src_pin = next((p for p in src_cls.outputs if p.name == link.get("from_pin")), None)
        dst_pin = next((p for p in dst_cls.inputs if p.name == link.get("to_pin")), None)
        if src_pin is None:
            add("error", f"{src_cls.title}: output pin '{link.get('from_pin')}' no longer exists.",
                src_id, "Reconnect this wire from a valid output.")
            continue
        if dst_pin is None:
            add("error", f"{dst_cls.title}: input pin '{link.get('to_pin')}' no longer exists.",
                dst_id, "Reconnect this wire to a valid input.")
            continue

        key = (dst_id, dst_pin.name)
        input_counts[key] = input_counts.get(key, 0) + 1
        # Only flag multiple incoming wires on DATA pins.
        # Exec (white) input pins can legitimately receive from many sources
        # — e.g. flow_disabled / flow_pass wired from several events.
        if input_counts[key] > 1 and dst_pin.type != EXEC:
            add("error", f"{dst_cls.title}.{dst_pin.name} has more than one wire.",
                dst_id, "Keep only one incoming wire for each input pin.")

        if src_pin.type == EXEC or dst_pin.type == EXEC:
            if src_pin.type != dst_pin.type:
                add("error", "Execution wires can only connect to execution pins.",
                    dst_id, "White pins connect to white pins; colored data pins connect by type.")
            else:
                exec_edges.setdefault(src_id, []).append(dst_id)
        elif (src_pin.type != dst_pin.type
              and src_pin.type != ANY
              and dst_pin.type != ANY
              # STRING <-> NUMBER is implicitly safe — we auto-convert in generated code
              and not {src_pin.type, dst_pin.type} <= {NUMBER, STRING, BOOLEAN, ANY}):
            add("error", f"Type mismatch: {src_pin.type} cannot connect to {dst_pin.type}.",
                dst_id, f"Use a {dst_pin.type} output for '{dst_pin.name}'.")

    # Find execution nodes that can actually be reached from an Event.
    # ── IMPORTANT: flow_pass / flow_disabled / flow_return are intentional
    # "hold" nodes — we still traverse THROUGH them so their downstream nodes
    # are not wrongly flagged as "will never run".  The visual tint system
    # already communicates their suppressed state; the diagnostics panel
    # should stay silent about anything downstream of them.
    FLOW_UTILITY_TYPES = {"flow_pass", "flow_disabled", "flow_return",
                          "flow_gate", "flow_switch_number", "flow_switch_tag",
                          "flow_state_machine", "flow_defer"}

    reachable = set(event_ids)
    stack = list(event_ids)
    while stack:
        current = stack.pop()
        # Muted nodes are deliberate hard stops; their downstream paths are
        # not runtime-reachable until the node is unmuted.
        if _ns_node_muted(nodes.get(current)):
            continue
        for nxt in exec_edges.get(current, []):
            if nxt not in reachable:
                reachable.add(nxt)
                stack.append(nxt)

    # Also flood from every flow-utility node so anything they connect to
    # (even if the utility node itself is downstream of a pass/disabled) is
    # never reported as disconnected.
    for nid, node in nodes.items():
        if node.get("type") in FLOW_UTILITY_TYPES and nid not in reachable:
            reachable.add(nid)
            extra_stack = [nid]
            while extra_stack:
                cur = extra_stack.pop()
                if _ns_node_muted(nodes.get(cur)):
                    continue
                for nxt in exec_edges.get(cur, []):
                    if nxt not in reachable:
                        reachable.add(nxt)
                        extra_stack.append(nxt)

    for nid, node in nodes.items():
        cls = NODE_DEFS.get(node.get("type"))
        if cls is None:
            continue
        # Never warn about flow-utility nodes being unreachable — that's the point.
        if node.get("type") in FLOW_UTILITY_TYPES:
            continue
        has_exec_input  = any(p.type == EXEC and not getattr(p, "universal_flow", False) for p in cls.inputs)
        has_exec_output = any(p.type == EXEC and not getattr(p, "universal_flow", False) for p in cls.outputs)
        if (has_exec_input or has_exec_output) and node.get("type") != "debug_button" and not (cls.__name__.startswith("Event") or node.get("type") in globals().get("EVENT_TO_HOOK", {})) and nid not in reachable:
            add("warning", f"{cls.title} will never run; its execution pin is not connected to an Event.",
                nid, "Connect the white execution wire from an Event or another running node.")
        data_outputs = [p for p in cls.outputs if p.type != EXEC]
        if data_outputs and not (cls.__name__.startswith("Event") or node.get("type") in globals().get("EVENT_TO_HOOK", {})):
            used = any(l.get("from") == nid and l.get("from_pin") in {p.name for p in data_outputs}
                       for l in links)
            # Suppress "unused output" warning when the node is intentionally
            # blocked (downstream of a pass/disabled) — the tints already show this.
            if not used and nid in reachable:
                add("warning", f"{cls.title} produces a value that is not being used.",
                    nid, "Connect its colored output to a matching input, or remove the node.")

    other_node_ids = [nid for nid, n in nodes.items() if n.get("type") == "target_event_other"]
    compatible_other_events = {
        "event_on_hit", "event_on_critical_hit", "event_on_damage_taken",
        "event_on_damage_dealt", "event_on_kill", "event_on_collision",
        "event_on_character_touch",
        "event_on_phase_touch_enter", "event_on_phase_touch_stay", "event_on_phase_touch_exit", "event_on_phase_touch_damage",
    }
    if other_node_ids and not any(nodes[eid].get("type") in compatible_other_events for eid in event_ids):
        for nid in other_node_ids:
            add("warning", "Event Other / Victim is empty for the Events in this graph.",
                nid, "Use it with On Hit, Damage, Kill, or Collision; otherwise use Self or a range target.")

    # Round 20: 'Get Nearest Enemy / Ally' (area_nearest_team) emits the same
    # `(min(...) if hits else None)` pattern, so it belongs to the set -
    # "Nearest Enemy in range" yields NOBODY when nobody is in range.
    unsafe_selectors = {"target_random_in_range", "target_nearest_in_range", "area_nearest_team"}
    warned_targets = set()
    for wire in links:
        if wire.get("to_pin") != "target":
            continue
        source_node = nodes.get(wire.get("from"), {})
        target_node = nodes.get(wire.get("to"), {})
        target_cls = NODE_DEFS.get(target_node.get("type"))
        if (source_node.get("type") in unsafe_selectors and target_cls
                and any(pin.type == EXEC for pin in target_cls.inputs)
                and not str(target_node.get("type", "")).startswith("npc_")
                and wire.get("to") not in warned_targets):
            warned_targets.add(wire.get("to"))
            add("warning", f"{target_cls.title} may receive no target.", wire.get("to"),
                "Use Find Random Opponent or Validate Target and connect the action through its Found/Valid execution branch.")

    # Round 20: the same maybe-empty selectors are just as dangerous feeding a
    # PURE condition node (Health Check & co. have no exec inputs and fall back
    # to SELF when the target is empty - 'enemy in range has hp > 0' quietly
    # becomes 'I am alive', so the branch fires every tick with nobody around,
    # e.g. a jab that 'loops forever alone'). Warn with the right fix.
    for wire in links:
        if wire.get("to_pin") != "target":
            continue
        source_node = nodes.get(wire.get("from"), {})
        target_node = nodes.get(wire.get("to"), {})
        target_cls = NODE_DEFS.get(target_node.get("type"))
        _pure_key = ("pure", wire.get("from"), wire.get("to"))
        if (source_node.get("type") in unsafe_selectors and target_cls
                and not any(pin.type == EXEC for pin in target_cls.inputs)
                and not str(target_node.get("type", "")).startswith("npc_")
                and _pure_key not in warned_targets):
            warned_targets.add(_pure_key)
            add("warning",
                f"{target_cls.title} may receive no target; if the selector finds nobody, most checks quietly read SELF instead.",
                wire.get("to"),
                "Gate the action through a Validate Target node and run it from the Valid branch.")

    # ── Soft usage tips (info) — grey/blue in UI, never block save ───────
    def _has_data_in(nid, pin_name):
        return any(l.get("to") == nid and l.get("to_pin") == pin_name for l in links)

    def _has_data_out_used(nid):
        return any(l.get("from") == nid for l in links)

    for nid, node in nodes.items():
        ntype = node.get("type", "")
        cls = NODE_DEFS.get(ntype)
        if cls is None:
            continue
        props = node.get("props", {})

        # Math binary ops with no wires and default zeros
        if ntype in ("math_subtract", "math_add", "math_multiply", "math_divide"):
            a_w, b_w = _has_data_in(nid, "a"), _has_data_in(nid, "b")
            if not a_w and not b_w:
                add("tip",
                    f"{cls.title}: A and B are unwired — both use pin defaults (often 0/1), so the result may look wrong.",
                    nid,
                    "Wire Constant Number (or any number output) into A and B. Subtract is A − B.")
            elif ntype == "math_subtract" and a_w and not b_w:
                add("tip",
                    f"{cls.title}: B is unwired (defaults to 0) so this is just A − 0.",
                    nid,
                    "Wire a value into B, or leave it only if you really want −0.")
            elif ntype == "math_subtract" and not a_w and b_w:
                add("tip",
                    f"{cls.title}: A is unwired (defaults to 0) so this is 0 − B (negates B).",
                    nid,
                    "Wire the value you want to subtract FROM into A; B is the amount subtracted.")
            if not _has_data_out_used(nid):
                add("tip",
                    f"{cls.title}: result is not connected to anything.",
                    nid,
                    "Drag the result pin into Print, Watcher, Compare, Deal Damage amount, etc.")

        # Constant number set to 0 with no consumers — mild tip
        if ntype == "utility_constant_number":
            try:
                cv = float(props.get("value", 0) or 0)
            except (TypeError, ValueError):
                cv = 0
            if not _has_data_out_used(nid):
                add("tip",
                    "Constant Number is not connected — its value never reaches another node.",
                    nid,
                    "Wire its value pin into a Math / Compare / Gameplay amount input.")
            elif cv == 0:
                add("tip",
                    "Constant Number is 0. If a connected Subtract/Add looks wrong, edit this constant in the inspector.",
                    nid,
                    "Select the Constant Number node and set Value in the inspector.")

        # Compare without A/B
        if ntype == "condition_compare_number":
            if not _has_data_in(nid, "a") and not _has_data_in(nid, "b"):
                add("tip",
                    "Compare Number has no A/B wires — it will compare defaults (0 == 0 → True).",
                    nid,
                    "Wire the value under test into A and the threshold into B (or vice versa).")
            if not any(l.get("from") == nid for l in links):
                add("tip",
                    "Compare Number result is unused — wire it into If/Else condition.",
                    nid,
                    "Connect result → Branch condition so true/false paths can run.")

        # Branch without condition
        if ntype == "condition_branch":
            if not _has_data_in(nid, "condition"):
                add("tip",
                    "If/Else has no condition wire — it always takes the TRUE path in debug/runtime defaults.",
                    nid,
                    "Wire a Compare / boolean node into the condition pin.")

        # Pure data nodes sitting on exec chains without data use
        if getattr(cls, "pure", False) and any(p.type != EXEC for p in cls.outputs):
            if not _has_data_out_used(nid) and ntype not in ("utility_comment",):
                # already covered some; skip duplicates for math/const
                if not ntype.startswith(("math_", "utility_constant", "condition_compare")):
                    add("tip",
                        f"{cls.title}: data output is unused.",
                        nid,
                        "Connect its colored output, or remove the node if you don't need it.")

    return issues

def validate_graph(nodes, links):
    """Blocking errors only; warnings remain visible but do not prevent save."""
    return [issue["message"] for issue in graph_diagnostics(nodes, links)
            if issue["severity"] == "error"]

# ---------- node execution policy ----------
def _ns_node_muted(node):
    return bool(node and node.get("ui_muted", False))

def _ns_node_bypassed(node):
    return bool(node and node.get("ui_bypass", False)) and not _ns_node_muted(node)

def _ns_primary_bypass_pin(node):
    """Choose one predictable continuation when an action node is bypassed."""
    cls = NODE_DEFS.get(node.get("type"), NodeBase) if node else NodeBase
    exec_pins = [p.name for p in getattr(cls, "outputs", []) if p.type == EXEC]
    for preferred in ("", "then", "exec_out", "completed", "next", "true"):
        if preferred in exec_pins:
            return preferred
    return exec_pins[0] if exec_pins else None

def _ns_default_output_value(node, pin_name=None):
    """Safe debug-sim value for a muted data node."""
    cls = NODE_DEFS.get(node.get("type"), NodeBase) if node else NodeBase
    pin = next((p for p in getattr(cls, "outputs", []) if p.name == pin_name), None)
    ptype = getattr(pin, "type", ANY)
    if ptype == BOOLEAN: return False
    if ptype == STRING: return ""
    if ptype == VECTOR: return pygame.Vector2(0, 0)
    if ptype == COLOR: return (255, 255, 255)
    if ptype == NUMBER: return 0.0
    return None

class CodegenContext:
    def __init__(self, nodes, links, event_trigger, event_args):
        self.nodes = nodes
        self.links = links
        self.event_trigger = event_trigger
        self.event_args = event_args  # {pin_name: python_arg_name}
        self.out = []
        self.indent_level = 1
        self.expr_cache = {}
        self.generated_exprs = set()
        self.state_vars = {}
        self.pending_funcs = []
        # --- pure-value temp (_pv_N) scope tracking -------------------------
        # Multi-consumer pure outputs are materialised into `_pv_N` temp vars
        # at the *first consumer's* location.  If that first consumer sits
        # inside an if/else branch, loop body, Smart-Group guard or a nested
        # def (delayed/timer callback), the temp is only visible on that
        # control-flow path -- a later consumer elsewhere then crashes at
        # runtime with `NameError: name '_pv_N' is not defined`.
        # We therefore remember, for every emitted _pv temp, the chain of
        # enclosing codegen regions it was born in, and re-materialise the
        # expression when a consumer is reached that is NOT dominated by the
        # temp's defining region (see get_output_expr / push_indent).
        self._region_stack = []          # ids of enclosing codegen regions
        self._region_next_id = 0
        self._pv_def_region = {}         # `_pv_N` temp -> tuple(region ids)
        self.loop_depth = 0
        self.needs_time = False
        self.var_counter = 0
        self.audio_state_vars = set()
        self.used_helpers = set()
        self._pending_ctxs = []           # sub-contexts collected for subgraph funcs
        self._pending_func_name = None
        self._pending_func_extra_args = ()
        # Per-line node ownership for the code viewer: each emitted line
        # remembers which blueprint node produced it, so clicking the line
        # can jump the canvas to that node.
        self.line_node_ids = []      # parallel to self.out (list of node_ids)
        self._emit_node_stack = []   # node_id stack — top is the "current" node

    def push_node(self, node_id):
        self._emit_node_stack.append(node_id)

    def pop_node(self):
        if self._emit_node_stack:
            self._emit_node_stack.pop()

    def _current_node_id(self):
        return self._emit_node_stack[-1] if self._emit_node_stack else None

    def emit(self, line):
        indented = "    " * self.indent_level + line
        self.out.append(indented)
        self.line_node_ids.append(self._current_node_id())

    def emit_raw(self, line):
        self.out.append(line)
        self.line_node_ids.append(self._current_node_id())

    def annotated_lines(self):
        """Yield (line_text, node_id) for every line currently in out,
        splitting embedded newlines so multi-line strings become one entry
        per source line (node id inherited from the parent emit call)."""
        for i, raw in enumerate(self.out):
            nid = self.line_node_ids[i] if i < len(self.line_node_ids) else None
            for sub in raw.split("\n"):
                yield sub, nid

    def fresh_var(self, prefix="v"):
        self.var_counter += 1
        return f"_{prefix}_{self.var_counter}"

    # --- Audio helper methods for code generation ---

    # --- Audio helper methods for code generation ---
    
    def emit_audio_state_init(self, me_var="me"):
        self.emit(f"{me_var}.setdefault('_audio_channel', None)")
        self.emit(f"{me_var}.setdefault('_audio_cue', None)")
        self.emit(f"{me_var}.setdefault('_audio_loop', False)")
        self.emit(f"{me_var}.setdefault('_audio_state', 'idle')")
        self.emit(f"{me_var}.setdefault('_last_audio_pick', -1)")
        self.emit(f"{me_var}.setdefault('_audio_shuffle_bag', [])")

    def emit_play_audio(self, me_var, cue_expr, vol_expr, pitch_expr, loop_expr="False"):
        chan_var = self.fresh_var("achan")
        self.emit(f"{chan_var} = ctx.play_audio_cue({me_var}, {cue_expr}, {vol_expr}, {pitch_expr}, {loop_expr})")
        self.emit(f"if {chan_var}:")
        self.push_indent()
        self.emit(f"{me_var}['_audio_channel'] = {chan_var}")
        self.emit(f"{me_var}['_audio_cue'] = {cue_expr}")
        self.emit(f"{me_var}['_audio_loop'] = {loop_expr}")
        self.pop_indent()
        return chan_var

    def emit_stop_audio(self, me_var, fade_expr="0.0"):
        self.emit(f"ch = {me_var}.get('_audio_channel')")
        self.emit("if ch:")
        self.push_indent()
        self.emit(f"ctx.stop_audio(ch, {fade_expr})")
        self.emit(f"{me_var}['_audio_channel'] = None")
        self.emit(f"{me_var}['_audio_cue'] = None")
        self.pop_indent()

    def emit_crossfade_logic(self, from_ch, to_ch, from_vol, to_vol, duration, curve="linear"):
        timer = self.fresh_var("xf_timer")
        prog = self.fresh_var("xf_prog")
        active = self.fresh_var("xf_active")
        self.emit(f"{timer} = 0.0")
        self.emit(f"{active} = True")
        return timer, prog, active

    def state_name(self, node_id, suffix):
        name = f"_ns_state_{node_id}_{suffix}"
        self.state_vars[name] = True
        return name

    def emit_nested_def_with_global(self, def_line, body_fn):
        """Emit a nested `def ...:` line (e.g. _evt_cb) and run body_fn to
        generate its body, then retroactively insert a `global` statement
        for any state vars the body references. Nested functions don't
        inherit `global` declarations from their enclosing hook function,
        so any node state var (e.g. _ns_state_162_active) touched inside a
        nested def becomes an UnboundLocalError trap unless it gets its own
        global line here — even if that var was already registered by some
        other node earlier in the same hook (registration order must NOT
        matter, so we scan the actual body text rather than diffing
        ctx.state_vars before/after). body_fn is called with no args after
        push_indent().

        [PATCH] Also makes the module-level `CTX` visible inside every
        generated nested def. Visual-scripter nodes emit calls like
        `CTX.resolve_character(...)` / `CTX.hook(...)`, but the function
        parameter is `_ctx` (not `CTX`) so the body would crash with
        `NameError: name 'CTX' is not defined`. We always register `CTX`
        as a state var and prepend an alias line so the global is
        rebound to whatever `_ctx` was passed in for the lifetime of
        the call. Same trick the existing state-var global injection
        uses, just for an extra fixed name. The state_vars dict's
        sort order means `CTX` lands alphabetically with the other
        `global` names."""
        import re
        # Ensure CTX is treated like a state var so it gets `global CTX`
        # in the injected header below, even on graphs that never touch
        # any node state vars.
        self.state_vars.setdefault("CTX", True)
        self.emit(def_line)
        self.push_indent()
        _insert_idx = len(self.out)
        _body_indent = "    " * self.indent_level
        # Alias `_ctx` -> `CTX` for the duration of this nested def so
        # generated code referencing `CTX.foo(...)` resolves to the same
        # instance the engine just passed in.
        self.out.append(_body_indent + "CTX = _ctx")
        body_fn()
        _body_text = "\n".join(self.out[_insert_idx:])
        _used_vars = [
            name for name in self.state_vars.keys()
            if re.search(r"\b" + re.escape(name) + r"\b", _body_text)
        ]
        if _used_vars:
            self.out.insert(_insert_idx, _body_indent + "global " + ", ".join(sorted(_used_vars)))
            self.line_node_ids.insert(_insert_idx, None)
        self.pop_indent()

    def push_indent(self):
        self.indent_level += 1
        # Entering a nested codegen region (branch / loop body / Smart-Group
        # guard / nested def).  Regions get unique monotonically increasing
        # ids so a sibling region (e.g. the else-branch of the same if) never
        # matches the defining region of a temp born in its sibling.
        self._region_next_id += 1
        self._region_stack.append(self._region_next_id)

    def pop_indent(self):
        self.indent_level = max(0, self.indent_level - 1)
        if self._region_stack:
            self._region_stack.pop()

    def find_input_link(self, node_id, pin_name):
        for l in self.links:
            if l["to"] == node_id and l["to_pin"] == pin_name:
                return l
        return None

    def generate_input(self, node, pin_name, visited=None):
        """Legacy-node compatibility wrapper. Older registered nodes call
        generate_input(node, pin, visited); modern code uses get_input_expr.
        Keeping the adapter here lets mixed-version graphs compile safely.
        """
        node_id = node.get("id") if isinstance(node, dict) else node
        return self.get_input_expr(node_id, pin_name) if node_id in self.nodes else "None"

    def get_input_expr(self, node_id, pin_name):
        cls = NODE_DEFS.get(self.nodes[node_id].get("type"))
        pin = cls.get_input(self.nodes[node_id], pin_name) if cls else None
        link = self.find_input_link(node_id, pin_name)
        if link:
            return self.get_output_expr(link["from"], link["from_pin"])
        if pin:
            return self.default_to_expr(pin.type, pin.default)
        return "None"

    def default_to_expr(self, pin_type, default):
        if default is None:
            if pin_type == NUMBER:
                return "0"
            if pin_type == STRING:
                return '""'
            if pin_type == BOOLEAN:
                return "False"
            if pin_type == VECTOR:
                return "pygame.Vector2(0, 0)"
            if pin_type == COLOR:
                return "(255, 255, 255)"
            return "None"
        if pin_type == VECTOR and isinstance(default, (list, tuple)) and len(default) == 2:
            return f"pygame.Vector2({default[0]}, {default[1]})"
        if pin_type == COLOR and isinstance(default, (list, tuple)):
            return f"({', '.join(str(int(c)) for c in default)})"
        return repr(default)

    def get_output_expr(self, node_id, pin_name):
        key = (node_id, pin_name)
        if key in self.expr_cache:
            cached = self.expr_cache[key]
            # Dominance check for materialised pure temps (_pv_N): a temp
            # emitted inside region R is only valid for consumers whose
            # current region chain *starts with* R's chain (same branch or a
            # nested one).  A consumer on any other control-flow path -- a
            # sibling else-branch, code after the if, an outer function, or
            # outside a Smart-Group guard that may be disabled at runtime --
            # must not reuse the name: it may never have been assigned, which
            # is exactly the `NameError: _pv_N is not defined` crash.  Drop
            # the stale cache entry and fall through to re-materialise the
            # expression at the current location (pure sub-inputs get the
            # same treatment recursively, so the whole tree is born here).
            def_region = self._pv_def_region.get(cached) \
                if isinstance(cached, str) else None
            if def_region is None:
                return cached
            if tuple(self._region_stack)[:len(def_region)] == def_region:
                return cached
            del self.expr_cache[key]
        node = self.nodes.get(node_id)
        if node is None:
            return "None"
        cls = NODE_DEFS.get(node.get("type"))
        if cls is None:
            self.expr_cache[key] = "None"
            return "None"
        # Muted data nodes are electrically quiet. Bypassed data nodes forward
        # the first compatible input instead of evaluating their operation.
        if _ns_node_muted(node):
            out_pin = next((p for p in cls.outputs if p.name == pin_name), None)
            expr = self.default_to_expr(getattr(out_pin, "type", ANY), getattr(out_pin, "default", None))
            self.expr_cache[key] = expr
            return expr
        if _ns_node_bypassed(node):
            out_pin = next((p for p in cls.outputs if p.name == pin_name), None)
            compatible = next((p for p in cls.inputs if p.type != EXEC and
                               (out_pin is None or p.type in (out_pin.type, ANY) or out_pin.type == ANY)), None)
            expr = (self.get_input_expr(node_id, compatible.name) if compatible else
                    self.default_to_expr(getattr(out_pin, "type", ANY),
                                         getattr(out_pin, "default", None)))
            self.expr_cache[key] = expr
            return expr
        # event args map directly
        if cls.__name__.startswith("Event") and pin_name in self.event_args:
            self.expr_cache[key] = self.event_args[pin_name]
            return self.expr_cache[key]
        expr = cls().generate_output_expr(self, self.nodes[node_id], pin_name)
        if cls.pure:
            # If multiple downstream nodes consume this pure output,
            # materialise into a temp variable so the expression is
            # evaluated only once.  Without this, a consumer that mutates
            # state (e.g. set_local_var) causes later inlined reads to
            # see the *changed* state and produce a stale / double-applied
            # result (the classic "double-decrement" bug).
            n_consumers = sum(
                1 for l in self.links
                if l["from"] == node_id and l["from_pin"] == pin_name
            )
            if n_consumers > 1:
                var = self.fresh_var("pv")
                self.emit(f"{var} = {expr}")
                # Record where this temp was born so later consumers on
                # other control-flow paths re-materialise it locally instead
                # of referencing a possibly-unassigned name.
                self._pv_def_region[var] = tuple(self._region_stack)
                self.expr_cache[key] = var
                return var
            self.expr_cache[key] = expr
            return expr
        var = self.fresh_var("v")
        self.emit(f"{var} = {expr}")
        self.expr_cache[key] = var
        return var

    def output_links(self, node_id, pin_name=""):
        return [l for l in self.links if l["from"] == node_id and l["from_pin"] == pin_name]

    def find_output_links(self, node_id, pin_name=""):
        return self.output_links(node_id, pin_name)

    def generate_exec_branch(self, node_id, output_pin, visited):
        links = self.output_links(node_id, output_pin)
        if not links:
            # Empty if/else/loop branches are invalid Python. Emitting pass at
            # every unconnected execution output also makes terminal nodes
            # safe without changing their behavior.
            self.emit("pass")
            return
        for l in links:
            self.generate_exec(l["to"], set(visited))

    def generate_exec(self, node_id, visited=None):
        if visited is None:
            visited = set()
        if node_id in visited:
            self.emit("# cycle detected, stopping execution")
            return
        visited = visited | {node_id}
        node = self.nodes.get(node_id)
        if node is None:
            return
        cls = NODE_DEFS.get(node.get("type"))
        if cls is None:
            self.emit(f"# unknown node type: {node.get('type')}")
            return

        # Execution policy set from the node docker. Mute blocks the path;
        # bypass skips this action but continues through one deterministic pin.
        if _ns_node_muted(node):
            self.push_node(node_id)
            try:
                self.emit(f"pass  # MUTED: blocked {getattr(cls, 'title', node.get('type'))!r}")
            finally:
                self.pop_node()
            return
        if _ns_node_bypassed(node):
            self.push_node(node_id)
            try:
                self.emit(f"pass  # BYPASSED: skipped {getattr(cls, 'title', node.get('type'))!r}")
            finally:
                self.pop_node()
            pin = _ns_primary_bypass_pin(node)
            if pin is not None:
                self.generate_exec_branch(node_id, pin, visited)
            return

        # Audio Clamp attachment: execute attached audio clamp logic as signal flows through host node
        for _other_clamp in list(self.nodes.values()):
            if _other_clamp.get("type") == "debug_audio_clamp" and not _ns_node_muted(_other_clamp):
                if str(_other_clamp.get("props", {}).get("clamped_to", "")) == str(node_id):
                    if _other_clamp["id"] not in visited:
                        visited.add(_other_clamp["id"])
                        _cls_ac = NODE_DEFS.get("debug_audio_clamp")
                        if _cls_ac:
                            _cls_ac().generate_code(self, _other_clamp, visited)

        # Debug-Only Clip: skip live/exported action for the HOST node.
        # Canvas debug Play does NOT use codegen, so it still runs fully.
        debug_only_clip = None
        for _other in self.nodes.values():
            if _other.get("type") != "debug_clamp_debug_only" or _ns_node_muted(_other):
                continue
            if str(_other.get("props", {}).get("clamped_to", "")) == str(node_id):
                debug_only_clip = _other
                break
        if debug_only_clip is None and bool(node.get("props", {}).get("debug_only", False)):
            debug_only_clip = node

        if debug_only_clip is not None and node.get("type") != "debug_clamp_debug_only":
            label = "DEBUG ONLY"
            pass_through = True
            if isinstance(debug_only_clip, dict):
                label = str(debug_only_clip.get("props", {}).get("label", "DEBUG ONLY") or "DEBUG ONLY")
                pass_through = bool(debug_only_clip.get("props", {}).get("pass_through", True))
            title = getattr(cls, "title", node.get("type", "?"))
            self.push_node(node_id)
            try:
                self.emit(f"pass  # [{label}] skipped live action for {title!r} (debug-only clip)")
            finally:
                self.pop_node()
            if pass_through:
                for p in cls.outputs:
                    if p.type == EXEC:
                        self.generate_exec_branch(node_id, p.name, visited)
            return

        # Smart Groups can be enabled/disabled at runtime. Nodes inside nested
        # groups require every containing group flag, while group-control
        # nodes remain exempt so a disabled group can always be re-enabled.
        _group_names=[]
        if not str(node.get("type","")).startswith("graph_group_"):
            for _g in modal.get("ns_smart_groups",[]) or []:
                try:
                    if node_id in _ns_group_all_node_ids(_g):_group_names.append(str(_g.get("name","Smart Group")))
                except Exception:pass
        self.push_node(node_id)
        try:
            if _group_names:
                _guard=" and ".join(f"_ns_group_flags.get({name!r}, True)" for name in _group_names)
                self.emit(f"if {_guard}:");self.push_indent()
                cls().generate_code(self,node,visited)
                self.pop_indent()
            else:
                cls().generate_code(self, node, visited)
        finally:
            self.pop_node()

    def generate_subgraph_function(self, node_id, output_pin, func_name, extra_args):
        """Generate a standalone function that executes the subgraph reachable
        from a given output exec pin. Used by timing nodes for delayed callbacks."""
        sub = CodegenContext(self.nodes, self.links, self.event_trigger, self.event_args)
        sub.indent_level = 1
        sub.var_counter = self.var_counter
        sub.state_vars = self.state_vars
        sub.needs_time = self.needs_time
        sub.used_helpers = self.used_helpers
        # emit state vars used by subgraph
        sub.push_node(node_id)
        try:
            for l in sub.output_links(node_id, output_pin):
                sub.generate_exec(l["to"], set())
        finally:
            sub.pop_node()
        self.var_counter = sub.var_counter
        self.needs_time = sub.needs_time
        self.used_helpers |= sub.used_helpers
        # Remember the sub-context so we can render it with node-id markers
        sub._pending_func_name = func_name
        sub._pending_func_extra_args = tuple(extra_args)
        self._pending_ctxs.append(sub)
        # Bubble up any nested pending sub-contexts (e.g. a timer node
        # reached from *inside* this delayed callback) so their function
        # bodies actually get emitted too, not just the calls to them.
        self._pending_ctxs.extend(getattr(sub, "_pending_ctxs", []))
        # Keep old pending_funcs list populated with plain text for backward
        # compatibility with anything that reads it.  sub.out lines already
        # carry correct indentation (sub.indent_level == 1 → 4 spaces), so
        # we must NOT add another layer of indentation here.  The old code
        # that prefixed every line with "    " caused double-indentation,
        # which produced IndentationError when the fallback path emitted
        # these lines at module scope after the primary pending_ctxs path
        # had already rendered the same function correctly.
        args = ["ctx", "me"] + list(extra_args)
        body = list(sub.out)
        func_lines = [f"def {func_name}({', '.join(args)}):"]
        if not sub.out:
            func_lines.append("    pass")
        else:
            func_lines.extend(body)
        self.pending_funcs.extend(func_lines)
        self.pending_funcs.append("")

def _ns_to_number(value, default=0.0):
    """Editor-side twin of the same-named helper injected into generated
    scripts (see NS_RUNTIME_HELPERS below) — needed here too because the
    canvas Debug Simulator runs inside the editor's own process, not the
    exported script, so it can't reach the injected copy."""
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except (TypeError, ValueError):
            return float(default)
    return float(default)

def _ns_bool(value):
    if isinstance(value, str):
        return value.strip().lower() in ("1", "true", "yes", "on")
    return bool(value)

def _ns_as_vec(v):
    """Normalize a Vector2 / (x,y) tuple / dict-with-pos into a Vector2."""
    try:
        if isinstance(v, dict) and "pos" in v:
            return pygame.Vector2(v["pos"])
        return pygame.Vector2(v)
    except Exception:
        return pygame.Vector2()

def _ns_bezier_point(p0, p1, p2, p3=None, t=0.5):
    """Point on a quadratic (3 points) or cubic (4 points) Bezier at t."""
    t = max(0.0, min(1.0, float(t)))
    a = _ns_as_vec(p0); b = _ns_as_vec(p1); c = _ns_as_vec(p2)
    if p3 is None:
        u = 1.0 - t
        return a * (u * u) + b * (2.0 * u * t) + c * (t * t)
    d = _ns_as_vec(p3); u = 1.0 - t
    return a * (u ** 3) + b * (3.0 * u * u * t) + c * (3.0 * u * t * t) + d * (t ** 3)

def _ns_catmull_point(points, t=0.5):
    """Smooth point through a Catmull-Rom route at normalized t."""
    try:
        pts = [_ns_as_vec(p) for p in points]
    except Exception:
        return pygame.Vector2()
    n = len(pts)
    if n <= 0:
        return pygame.Vector2()
    if n == 1:
        return pts[0]
    if n == 2:
        return pts[0] + (pts[1] - pts[0]) * max(0.0, min(1.0, float(t)))
    t = max(0.0, min(1.0, float(t)))
    seg = t * (n - 1)
    i = int(min(n - 2, math.floor(seg)))
    u = seg - i
    p0 = pts[i - 1] if i > 0 else pts[i]
    p1 = pts[i]; p2 = pts[i + 1]
    p3 = pts[i + 2] if i + 2 < n else pts[i + 1]
    return (p1 * 2 + (-p0 + p2) * u + (2 * p0 - 5 * p1 + 4 * p2 - p3) * (u * u)
            + (-p0 + 3 * p1 - 3 * p2 + p3) * (u * u * u)) * 0.5

def _ns_path_point(points, t=0.5):
    """Alias of _ns_catmull_point for wiring Waypoint routes into math."""
    return _ns_catmull_point(points, t)

# ---------- default runtime helpers injected into generated scripts ----------

def _ns_accuracy_spread(accuracy=100.0):
    """Calculates random angle spread in degrees based on accuracy percentage (default 100 = 100% accuracy, 0 deg error).
    Lower accuracy yields wider random angle spread (0% accuracy = 100 deg spread)."""
    acc = _ns_to_number(accuracy, 100.0)
    if acc >= 100.0:
        return 0.0
    spread_max = max(0.0, 100.0 - acc)
    return random.uniform(-spread_max, spread_max)

def _ns_aim_angle_with_accuracy(from_pos, to_pos, accuracy=100.0):
    """Calculates angle in degrees from from_pos to to_pos with random spread based on accuracy % (default 100 = 100%)."""
    try:
        if isinstance(from_pos, dict):
            fp = from_pos.get("pos", (0, 0))
        else:
            fp = from_pos
        if isinstance(to_pos, dict):
            tp = to_pos.get("pos", (0, 0))
        else:
            tp = to_pos
        fx = float(fp[0] if hasattr(fp, "__getitem__") else getattr(fp, "x", 0))
        fy = float(fp[1] if hasattr(fp, "__getitem__") else getattr(fp, "y", 0))
        tx = float(tp[0] if hasattr(tp, "__getitem__") else getattr(tp, "x", 0))
        ty = float(tp[1] if hasattr(tp, "__getitem__") else getattr(tp, "y", 0))
        dx, dy = tx - fx, ty - fy
        base_angle = math.degrees(math.atan2(dy, dx))
        return (base_angle + _ns_accuracy_spread(accuracy) + 180.0) % 360.0 - 180.0
    except Exception:
        return 0.0

def _ns_calculate_arc_angle(from_pos, to_pos, speed=300.0, weight=200.0, accuracy=100.0):
    """Calculates launch angle taking projectile weight (gravity) into account to hit to_pos, plus accuracy spread (default 100 = 100%)."""
    try:
        if isinstance(from_pos, dict):
            fp = from_pos.get("pos", (0, 0))
        else:
            fp = from_pos
        if isinstance(to_pos, dict):
            tp = to_pos.get("pos", (0, 0))
        else:
            tp = to_pos
        fx = float(fp[0] if hasattr(fp, "__getitem__") else getattr(fp, "x", 0))
        fy = float(fp[1] if hasattr(fp, "__getitem__") else getattr(fp, "y", 0))
        tx = float(tp[0] if hasattr(tp, "__getitem__") else getattr(tp, "x", 0))
        ty = float(tp[1] if hasattr(tp, "__getitem__") else getattr(tp, "y", 0))
        dx, dy = tx - fx, ty - fy
        spd = max(1.0, float(speed))
        g = float(weight)
        base_angle = None
        if abs(dx) > 1e-4 and g > 0:
            v2 = spd * spd
            v4 = v2 * v2
            disc = v4 - g * (g * dx * dx + 2 * dy * v2)
            if disc >= 0:
                root = math.sqrt(disc)
                tan_theta = (v2 - root) / (g * dx)
                theta = math.atan(tan_theta)
                if dx < 0:
                    theta += math.pi
                base_angle = math.degrees(theta)
        if base_angle is None:
            base_angle = math.degrees(math.atan2(dy, dx)) if (dx != 0 or dy != 0) else 0.0
        return (base_angle + _ns_accuracy_spread(accuracy) + 180.0) % 360.0 - 180.0
    except Exception:
        return 0.0

