# ---------- node system runtime helpers ----------
import time

def _ns_vec2(x=0, y=0):
    return pygame.Vector2(x, y)

def _ns_dist(a, b):
    try:
        return a.distance_to(b)
    except Exception:
        try:
            return ((a[0]-b[0])**2 + (a[1]-b[1])**2)**0.5
        except Exception:
            return 999999.0

def _ns_clamp(v, lo, hi):
    return max(lo, min(hi, v))

def _ns_bool(value):
    if isinstance(value, str):
        return value.strip().lower() in ("1", "true", "yes", "on")
    return bool(value)

def _ns_lerp(a, b, t):
    return a + (b - a) * t

def _ns_to_number(value, default=0.0):
    """Safely coerce ANY value (string, bool, number, None, or even a
    variable that was never set) into a float instead of crashing the
    whole hook with 'could not convert string to float'. Non-numeric
    strings and unconvertible values just fall back to `default`."""
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except (TypeError, ValueError):
            return float(default)
    return float(default)

def _ns_parse_vector(text, default=(0.0, 0.0)):
    """Parse strings like '120,40' or '(120, 40)' into a Vector2. Falls
    back to `default` on anything unparsable instead of raising."""
    try:
        cleaned = str(text).strip().strip("()[]")
        parts = [p.strip() for p in cleaned.split(",")]
        if len(parts) != 2:
            raise ValueError("expected 2 components")
        return pygame.Vector2(float(parts[0]), float(parts[1]))
    except Exception:
        return pygame.Vector2(default[0], default[1])

def _ns_as_vec(v):
    """Coerce a Vector2 / (x,y) / character into a pygame.Vector2."""
    try:
        if isinstance(v, dict) and "pos" in v:
            return pygame.Vector2(v["pos"])
        return pygame.Vector2(v)
    except Exception:
        return pygame.Vector2()

def _ns_bezier_point(p0, p1, p2, p3=None, t=0.5):
    """Point on a Bezier. Pass 3 points (p0, ctrl, end) for a quadratic curve,
    or 4 points for a cubic. t is clamped to 0..1. Returns a pygame.Vector2."""
    t = max(0.0, min(1.0, float(t)))
    a = _ns_as_vec(p0); b = _ns_as_vec(p1); c = _ns_as_vec(p2)
    if p3 is None:
        u = 1.0 - t
        return a * (u * u) + b * (2.0 * u * t) + c * (t * t)
    d = _ns_as_vec(p3); u = 1.0 - t
    return a * (u ** 3) + b * (3.0 * u * u * t) + c * (3.0 * u * t * t) + d * (t ** 3)

def _ns_catmull_point(points, t=0.5):
    """Smooth Catmull-Rom point through a list of Vector2/(x,y) route points."""
    try:
        pts = [_ns_as_vec(p) for p in points]
    except Exception:
        return pygame.Vector2()
    n = len(pts)
    if n <= 0:
        return pygame.Vector2()
    if n == 1:
        return pts[0]
    if n == 2:
        return pts[0] + (pts[1] - pts[0]) * max(0.0, min(1.0, float(t)))
    t = max(0.0, min(1.0, float(t)))
    seg = t * (n - 1)
    i = int(min(n - 2, math.floor(seg)))
    u = seg - i
    p0 = pts[i - 1] if i > 0 else pts[i]
    p1 = pts[i]; p2 = pts[i + 1]; p3 = pts[i + 2] if i + 2 < n else pts[i + 1]
    return (p1 * 2 + (-p0 + p2) * u + (2 * p0 - 5 * p1 + 4 * p2 - p3) * (u * u)
            + (-p0 + 3 * p1 - 3 * p2 + p3) * (u * u * u)) * 0.5

def _ns_path_point(points, t=0.5):
    """Alias of _ns_catmull_point for wiring Waypoint routes into math."""
    return _ns_catmull_point(points, t)

def _ns_vector_angle(v):
    """Compass angle of a direction vector in degrees, matching the Play
    Motion Clip Angle field: 0 = up (North), positive clockwise
    (East = 90, South = 180, West = 270). Accepts a Vector2 or (x, y)."""
    try:
        x = float(v.x); y = float(v.y)
    except Exception:
        try:
            x = float(v[0]); y = float(v[1])
        except Exception:
            return 0.0
    return math.degrees(math.atan2(x, -y)) % 360.0

def _ns_ease(t, kind="linear"):
    """Shared 0->1 easing curve evaluator used by flex_alter and by weapon
    motion (swing/jab/etc) interpolation, so both use the exact same set
    of curves. Includes exponential in/out/in-out on top of the classic set.
    Falls through to the engine's full-vocabulary evaluator (sine_inout,
    elastic_out, bounce_out, quad_in, ... plus F8 custom 'curve:' names)
    so Fade Opacity and friends honour EVERY curve the dropdowns offer."""
    x = max(0.0, min(1.0, float(t)))
    k = str(kind)
    if k == "linear":        return x
    if k == "ease_in":       return x * x
    if k == "ease_out":      return x * (2 - x)
    if k == "ease_in_out":   return (2 * x * x if x < .5 else -1 + (4 - 2 * x) * x)
    if k == "smoothstep":    return x * x * (3 - 2 * x)
    if k == "smootherstep":  return x * x * x * (x * (x * 6 - 15) + 10)
    if k == "bounce":        return 1 - abs(math.cos(x * math.pi * 3)) * (1 - x)
    if k == "expo_in":       return 0.0 if x <= 0 else 2 ** (10 * (x - 1))
    if k == "expo_out":      return 1.0 if x >= 1 else 1 - 2 ** (-10 * x)
    if k == "expo_in_out":
        if x <= 0: return 0.0
        if x >= 1: return 1.0
        if x < 0.5: return (2 ** (20 * x - 10)) / 2
        return (2 - 2 ** (-20 * x + 10)) / 2
    try:
        # build_script_ns seeds _ns_host_ease with the engine's full-
        # vocabulary evaluator; guarded so a bare exec of the generated
        # source (unit tests, external tools) still returns linear.
        _we = globals().get("_ns_host_ease")
        if callable(_we):
            return max(0.0, min(1.0, float(_we(x, k))))
    except Exception:
        pass
    return x

# status helpers (statuses stored as dict on character)
def _ns_apply_status(me, status, duration):
    me.setdefault("_ns_statuses", {})[status] = time.time() + duration

def _ns_remove_status(me, status):
    me.get("_ns_statuses", {}).pop(status, None)

def _ns_has_status(me, status):
    statuses = me.get("_ns_statuses", {})
    if status not in statuses:
        return False
    if time.time() > statuses[status]:
        statuses.pop(status, None)
        return False
    return True

# knockback helper

def _ns_knockback(me, direction, force, duration=0.25, stack=False):
    """Bump-based knockback: push velocity toward the hit direction and
    temporarily raise max_speed, like getting physically bumped by another
    character. No separate momentum channel or velocity restore."""
    try:
        if not isinstance(me, dict): return
        d = pygame.Vector2(direction)
        if d.length_squared() <= 1e-9: return
        d = d.normalize()
        force = float(force)
        dur = float(duration)
        if "_kb_base_max_speed" not in me:
            me["_kb_base_max_speed"] = float(me.get("max_speed", 400))
        base_max = me["_kb_base_max_speed"]
        if stack:
            me["vel"] = me["vel"] + d * force
            me["max_speed"] = max(float(me.get("max_speed", base_max)), base_max + force)
        else:
            bumped_speed = max(base_max, force)
            me["vel"] = d * bumped_speed
            me["max_speed"] = bumped_speed
        me["_external_momentum_time"] = max(float(me.get("_external_momentum_time", 0.0)), dur)
        me["_smooth_vel"] = pygame.Vector2(me["vel"])
    except Exception:
        pass

def _ns_teleport(me, pos):
    try:
        me["pos"] = pygame.Vector2(pos)
    except Exception:
        pass

# tint / flash helpers (drawn by the engine as a translucent overlay on the character)
def _ns_set_tint(target, color, duration):
    if target is None:
        return
    target["_ns_tint"] = {"color": tuple(color), "end_time": time.time() + duration, "flash": False}

def _ns_flash_tint(target, color, duration, interval=0.15):
    if target is None:
        return
    target["_ns_tint"] = {
        "color": tuple(color), "end_time": time.time() + duration,
        "flash": True, "interval": max(0.05, interval), "start_time": time.time(),
    }

def _ns_char_ok(t):
    """A usable character target: a dict that is still alive."""
    return isinstance(t, dict) and float(t.get("hp", 1) or 0) > 0

def _ns_pos_of(d):
    """pos Vector2 of a character dict, or None when unavailable."""
    p = d.get("pos") if isinstance(d, dict) else None
    return p if hasattr(p, "x") else None

def _ns_track(me):
    """The character's tracked target (npc_track_* nodes), validated alive."""
    t = me.get("_track_target") if isinstance(me, dict) else None
    return t if _ns_char_ok(t) else None

def _ns_set_track(me, target, group=""):
    """Memorize `target` as me's tracked target, filed under group name
    (free-form string the graph reads back with Tracked Group / Tracked In
    Group?). Stores the raw dict - dead targets keep invalidating on READ via
    _ns_track exactly like raw assignment did. Stamps _track_since only when
    the identity actually changes; the arena gizmo keys its acquire/switch
    burst off that moment."""
    if not isinstance(me, dict):
        return False
    if not isinstance(target, dict):
        target = None
    if target is not me.get("_track_target"):
        me["_track_since"] = time.time()
    me["_track_target"] = target
    me["_track_group"] = str(group or "") if target is not None else ""
    return target is not None

def _ns_track_group(me):
    """Group name the (living) tracked target was filed under, '' otherwise."""
    if not isinstance(me, dict) or _ns_track(me) is None:
        return ""
    return str(me.get("_track_group", ""))

# opacity helpers (Set Opacity / Fade Opacity nodes; draw side honors them)
def _ns_set_opacity(me, value):
    """Instant, persistent opacity: 1.0 solid -> 0.0 invisible."""
    if not isinstance(me, dict):
        return
    me.pop("_opacity_fade", None)
    me.pop("_opacity_flicker", None)
    try:
        me["opacity"] = _ns_clamp(float(value), 0.0, 1.0)
    except (TypeError, ValueError):
        me["opacity"] = 1.0

def _ns_flicker_opacity(me, duration=0.6, rate=8.0, low=0.15, high=1.0, smooth=False):
    """Fire-and-forget opacity flicker: trigger ONCE and the character
    blinks between low and high opacity at `rate` cycles/second for
    `duration` seconds, then restores the opacity it had before the
    flicker started. Wall-clock driven — no per-frame execution needed."""
    if not isinstance(me, dict):
        return
    try:
        d = max(0.05, float(duration))
    except (TypeError, ValueError):
        d = 0.6
    try:
        r = max(0.5, float(rate))
    except (TypeError, ValueError):
        r = 8.0
    try:
        lo = _ns_clamp(float(low), 0.0, 1.0)
    except (TypeError, ValueError):
        lo = 0.15
    try:
        hi = _ns_clamp(float(high), 0.0, 1.0)
    except (TypeError, ValueError):
        hi = 1.0
    if lo > hi:
        lo, hi = hi, lo
    me.pop("_opacity_fade", None)
    prev = me.get("_opacity_flicker")
    # Retriggering mid-flicker keeps the ORIGINAL pre-flicker opacity as the
    # restore value (opacity itself is untouched while flickering, but be
    # explicit so stacked teleports can't capture a half-faded value).
    restore = (prev.get("restore") if isinstance(prev, dict)
               else _ns_clamp(float(me.get("opacity", 1.0)), 0.0, 1.0))
    me["_opacity_flicker"] = {"t0": time.time(), "dur": d, "rate": r,
                              "low": lo, "high": hi, "smooth": bool(smooth),
                              "restore": restore}

def _ns_opacity(me, _settle=True):
    """Current opacity of a character, mid-fade/flicker included (0.0-1.0)."""
    if not isinstance(me, dict):
        return 1.0
    fl = me.get("_opacity_flicker")
    if isinstance(fl, dict):
        try:
            e = time.time() - float(fl.get("t0", 0.0))
            d = max(1e-6, float(fl.get("dur", 0.0)))
            if e >= d:
                me.pop("_opacity_flicker", None)
                me["opacity"] = _ns_clamp(float(fl.get("restore", 1.0)), 0.0, 1.0)
            else:
                lo = float(fl.get("low", 0.0)); hi = float(fl.get("high", 1.0))
                ph = e * float(fl.get("rate", 8.0))
                if fl.get("smooth"):
                    return _ns_clamp(lo + (hi - lo) * (0.5 + 0.5 * math.cos(ph * 2.0 * math.pi)), 0.0, 1.0)
                return _ns_clamp(hi if int(ph * 2.0) % 2 == 0 else lo, 0.0, 1.0)
        except (TypeError, ValueError):
            me.pop("_opacity_flicker", None)
    f = me.get("_opacity_fade")
    if isinstance(f, dict):
        try:
            t0 = float(f.get("t0", 0.0)); dur = max(1e-6, float(f.get("dur", 0.0)))
            k = (time.time() - t0) / dur
            if k >= 1.0:
                me.pop("_opacity_fade", None)
                me["opacity"] = _ns_clamp(float(f.get("to", 1.0)), 0.0, 1.0)
            else:
                e = _ns_ease(max(0.0, k), f.get("ease", "linear"))
                fr = float(f.get("from", 1.0)); to = float(f.get("to", 1.0))
                return _ns_clamp(fr + (to - fr) * e, 0.0, 1.0)
        except (TypeError, ValueError):
            me.pop("_opacity_fade", None)
    try:
        return _ns_clamp(float(me.get("opacity", 1.0)), 0.0, 1.0)
    except (TypeError, ValueError):
        return 1.0

def _ns_fade_opacity(me, value, duration, ease="linear"):
    """Start a wall-clock opacity fade from the CURRENT opacity to `value`."""
    if not isinstance(me, dict):
        return
    try:
        v = _ns_clamp(float(value), 0.0, 1.0)
    except (TypeError, ValueError):
        v = 1.0
    try:
        d = max(0.0, float(duration))
    except (TypeError, ValueError):
        d = 0.0
    cur = _ns_opacity(me)
    me.pop("_opacity_flicker", None)  # a fade takes over from any running flicker
    if d <= 0.0:
        me.pop("_opacity_fade", None)
        me["opacity"] = v
        return
    me["_opacity_fade"] = {"from": cur, "to": v, "t0": time.time(),
                           "dur": d, "ease": str(ease or "linear")}

# collision-ignore rules (read by the engine's body-collision pass,
# _collision_ignored_for_pair; query them from graphs with
# Ignores Collisions With?)
def _ns_no_collide_add(me, kind, value=True):
    """Give a character a pass-through rule.
    kind 'tag_same' - pass through anyone who shares this tag with me
                      (the crowd rule: same-tag walkers never body-block).
    kind 'tag_any'  - pass through ANY character carrying this tag.
    kind 'char'     - pass through this one specific character.
    kind 'team'     - pass through teammates (same non-empty team)."""
    if not isinstance(me, dict):
        return False
    if kind in ("tag_same", "tag_any"):
        tag = str(value or "").strip()
        if not tag:
            return False
        key = "_no_collide_shared_tags" if kind == "tag_same" else "_no_collide_tags"
        me.setdefault(key, set()).add(tag)
        return True
    if kind == "char":
        if not isinstance(value, dict):
            return False
        me.setdefault("_no_collide_ids", set()).add(id(value))
        return True
    if kind == "team":
        me["_no_collide_same_team"] = bool(value)
        return True
    return False

def _ns_no_collide_clear(me, tag=""):
    """Remove pass-through rules: a given tag (all tag sets), or everything
    when tag is ''."""
    if not isinstance(me, dict):
        return False
    t = str(tag or "").strip()
    if t:
        for key in ("_no_collide_tags", "_no_collide_shared_tags"):
            s = me.get(key)
            if isinstance(s, set):
                s.discard(t)
        return True
    for key in ("_no_collide_tags", "_no_collide_shared_tags",
                "_no_collide_ids", "_no_collide_same_team"):
        me.pop(key, None)
    return True

def _ns_collision_ignored(a, b):
    """True when characters a and b pass through each other by any rule
    (mirrors the engine's _collision_ignored_for_pair)."""
    if not isinstance(a, dict) or not isinstance(b, dict):
        return False
    try:
        if id(b) in a.get("_no_collide_ids", ()) or id(a) in b.get("_no_collide_ids", ()):
            return True
        at, bt = a.get("tags") or (), b.get("tags") or ()
        for t in a.get("_no_collide_tags", ()):
            if t in bt:
                return True
        for t in b.get("_no_collide_tags", ()):
            if t in at:
                return True
        for t in a.get("_no_collide_shared_tags", ()):
            if t in at and t in bt:
                return True
        for t in b.get("_no_collide_shared_tags", ()):
            if t in at and t in bt:
                return True
        if a.get("_no_collide_same_team") or b.get("_no_collide_same_team"):
            ta, tb = str(a.get("team", "")), str(b.get("team", ""))
            if ta and ta == tb:
                return True
    except Exception:
        pass
    return False

def _ns_delta_to(me, other):
    """Vector from me's pos to other's pos, or None when either is missing."""
    a, b = _ns_pos_of(other), _ns_pos_of(me)
    if a is None or b is None:
        return None
    try:
        return pygame.Vector2(a) - pygame.Vector2(b)
    except Exception:
        return None

