def _ns_emit_target_event_bindings(ctx, source_node_id, source_output_pin, obj_var, visited):
    """Find all Event Nodes connected to source_node_id's output_pin via their 'target' pin,
    and generate their instance event hook bindings (_d_ns[trigger] = _evt_cb) right here in the stream!"""
    for link in ctx.links:
        if link.get("from") == source_node_id and str(link.get("from_pin", "")) == str(source_output_pin):
            target_node = ctx.nodes.get(link.get("to"))
            if not target_node or _ns_node_muted(target_node):
                continue
            ntype = target_node.get("type", "")
            if ntype in EVENT_TO_HOOK and link.get("to_pin") == "target":
                trigger = EVENT_TO_HOOK[ntype]
                cls_ev = NODE_DEFS.get(ntype)
                if cls_ev and target_node["id"] not in visited:
                    visited.add(target_node["id"])
                    event_args = cls_ev.event_args
                    ctx.emit(f"if isinstance({obj_var}, dict):")
                    ctx.push_indent()
                    ctx.emit(f"if {obj_var}.get('script_ns') is None:")
                    ctx.push_indent()
                    ctx.emit(f"{obj_var}['script_ns'] = {{}}")
                    ctx.pop_indent()
                    ctx.emit(f"_d_ns = {obj_var}['script_ns']")
                    hook_arg_names = ["_ctx", "me"] + [event_args.get(k, k) for k in event_args]
                    ctx.emit_nested_def_with_global(
                        f"def _evt_cb({', '.join(hook_arg_names)}):",
                        lambda: ctx.generate_exec_branch(target_node["id"], "", visited),
                    )
                    ctx.emit(f"_d_ns['{trigger}'] = _evt_cb")
                    ctx.pop_indent()

def make_event_node(trigger, node_title):
    node_args = EVENT_SPECS[trigger]["args"]
    node_desc = EVENT_SPECS[trigger].get("desc", "")
    def _event_pin_type(name):
        if name in ("other", "summoner", "sender", "attacker", "target", "killer", "collector", "item", "projectile"):
            return OBJECT
        if name in ("crit", "met", "enabled"):
            return BOOLEAN
        if name in ("state", "key", "tag", "event_name", "phase", "killer_name", "clip", "event", "reason"):
            return STRING
        if name in ("position", "event_position", "normal", "direction"):
            return VECTOR
        if name in ("emitter", "particle"):
            return ANY
        return NUMBER
    node_inputs = [
        PinSpec("target", OBJECT, default=None, tooltip="Optional target dummy / spawned character. If connected, events bind to this entity instead of host.")
    ]
    node_outputs = [PinSpec("", EXEC, tooltip="Execution flow")] + [
        PinSpec(k, _event_pin_type(k), tooltip=k) for k in node_args
    ]
    if trigger in ("on_death", "on_scene_death"):
        node_outputs.append(PinSpec("killer_name", STRING, tooltip="Killer name as text"))
    _filter_props = tuple(EVENT_SPECS[trigger].get("filter_props", ()))
    _node_properties = ({p: PropSpec(p, "string", "") for p in _filter_props}
                        if _filter_props else {})
    class EventNode(NodeBase):
        key = f"event_{trigger}"
        category = "Events"
        title = node_title
        inputs = node_inputs
        outputs = node_outputs
        properties = _node_properties
        event_trigger = trigger
        event_args = node_args
        def generate_code(self, ctx, node, visited):
            for k, v in self.event_args.items():
                ctx.expr_cache[(node["id"], k)] = v
            # Optional per-trigger filters (Motion Clip events): the node only
            # fires its branch when its clip/event filter props match. Empty
            # filter = match everything. Several filtered nodes of one trigger
            # coexist: top-level nodes share one hook def, each with its own
            # `if` gate - named events in one clip get separate logic chains.
            _conds = []
            for _fp in EVENT_SPECS[trigger].get("filter_props", ()):
                _fv = str(node.get("props", {}).get(_fp, "") or "").strip()
                if _fv:
                    _conds.append(f"(str({_fp} or '') == {_fv!r})")
            def _emit_body():
                if _conds:
                    ctx.emit(f"if {' and '.join(_conds)}:")
                    ctx.push_indent()
                    ctx.generate_exec_branch(node["id"], "", visited)
                    ctx.pop_indent()
                else:
                    ctx.generate_exec_branch(node["id"], "", visited)
            if ctx.find_input_link(node["id"], "target"):
                t_expr = self.input_expr(ctx, node, "target")
                d_obj = ctx.fresh_var("evt_target")
                ctx.emit(f"{d_obj} = {t_expr}")
                ctx.emit(f"if isinstance({d_obj}, dict):")
                ctx.push_indent()
                ctx.emit(f"if {d_obj}.get('script_ns') is None:")
                ctx.push_indent()
                ctx.emit(f"{d_obj}['script_ns'] = {{}}")
                ctx.pop_indent()
                ctx.emit(f"_d_ns = {d_obj}['script_ns']")
                hook_arg_names = ["_ctx", "me"] + [self.event_args.get(k, k) for k in self.event_args]
                ctx.emit_nested_def_with_global(
                    f"def _evt_cb({', '.join(hook_arg_names)}):",
                    _emit_body,
                )
                ctx.emit(f"_d_ns['{trigger}'] = _evt_cb")
                ctx.pop_indent()
            else:
                _emit_body()
        def generate_output_expr(self, ctx, node, output_name):
            if output_name == "killer_name" and trigger in ("on_death", "on_scene_death"):
                return "(killer.get('name', '') if isinstance(killer, dict) else str(killer or ''))"
            return self.event_args.get(output_name, "None")
    register_node(f"event_{trigger}", "Events", node_title, node_desc)(EventNode)
    return EventNode

