for _scene_key, _source_hook, _scene_title in _SCENE_GLOBAL_EVENT_SOURCES:
    _trigger = "scene_any_" + _scene_key
    _base_desc = EVENT_SPECS.get(_source_hook, {}).get("desc", "")
    if _base_desc:
        _scene_desc = "Scene-wide version of '" + EVENT_SPECS[_source_hook]["title"] + "': " + _base_desc[0].lower() + _base_desc[1:] + " Fires for the 'subject' character wherever it happens in the arena, not just this one."
    else:
        _scene_desc = "Scene-wide hook: fires for any character in the arena that triggers this event, passing the character as 'subject'."
    EVENT_SPECS.setdefault(_trigger, {"args": {"subject": "subject"}, "title": _scene_title, "desc": _scene_desc})

_scene_hook_bridge_map = {}
for _key, _source, _title in _SCENE_GLOBAL_EVENT_SOURCES:
    _scene_hook_bridge_map.setdefault(_source, []).append("on_scene_any_" + _key)
_SCENE_HOOK_BRIDGE.update(_scene_hook_bridge_map)

EVENT_SPECS.setdefault("on_motion_event_hit", {"args": {"target": "target", "clip": "clip", "event": "event", "frame": "frame"},
    "title": "On Motion Event Hit", "filter_props": ("clip", "event"),
    "desc": "Fires when a playing Motion Clip's named event overlaps a target - the collider-hit counterpart. Set the clip/event filter props to react to ONE named event (e.g. only 'jab.smash'), then run ANY logic: deal/BUFF damage thresholds, crit rolls (hit count % 5 + random), spawn, lifesteal - the event itself no longer needs any damage. Outputs target, clip, event, frame. Several filtered nodes of this trigger coexist."})
