# ==============================================================================
# NPC MOVEMENT CONTROL NODES (37 NODES)
# Hop / tilt / track toolkit for Terraria-style hopper enemies & NPCs.
# Tilt = visual overlay on the sprite (degrees, + leans clockwise / rightward),
# it never touches c['angle'], so facing, weapon rigs and combat logic are safe.
# Hops set velocity directly (negative y = up) and clear gravity_grounded so
# ground-friction / stop_on_ground cannot eat the first airborne frame.
# ==============================================

@register_node("npc_set_tilt", "NPC", "Set Tilt",
               "Instantly set the sprite's TILT overlay to an angle (degrees, + leans right / clockwise). Visual only - facing/angle logic untouched. Cancels any running tilt tween.")
class NpcSetTiltNode(NodeBase):
    properties = {"angle": PropSpec("angle", "number", 12.0)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None),
              PinSpec("angle", NUMBER, default=12.0)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        a = self.input_expr(ctx, node, "angle") if ctx.find_input_link(node["id"], "angle") else repr(self.prop_value(node, "angle", 12.0))
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.emit(f"    {t}['_tilt_cmd'] = {{'op': 'set', 'value': float({a})}}")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("npc_tilt_to", "NPC", "Tilt To Angle",
               "Eases the sprite's TILT overlay to an angle over a duration with any engine easing curve (your custom F8 curves included). Reaching a running tilt retargets smoothly from where it is now.")
class NpcTiltToNode(NodeBase):
    properties = {"angle": PropSpec("angle", "number", 14.0),
                  "duration": PropSpec("duration", "number", 0.18, min_val=0.0, max_val=10.0),
                  "curve": PropSpec("curve", "dropdown", "ease_out", options=_EaseCurveOptions())}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None),
              PinSpec("angle", NUMBER, default=14.0),
              PinSpec("duration", NUMBER, default=0.18)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        a = self.input_expr(ctx, node, "angle") if ctx.find_input_link(node["id"], "angle") else repr(self.prop_value(node, "angle", 14.0))
        d = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 0.18))
        e = repr(str(self.prop_value(node, "curve", "ease_out")))
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.emit(f"    {t}['_tilt_cmd'] = {{'op': 'to', 'value': float({a}), 'dur': max(0.0, float({d})), 'ease': {e}}}")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("npc_tilt_by", "NPC", "Tilt By Amount",
               "Eases the tilt by a RELATIVE amount (current tilt + delta). Great for winding up further each hop. Positive = further right.")
class NpcTiltByNode(NodeBase):
    properties = {"delta": PropSpec("delta", "number", 8.0),
                  "duration": PropSpec("duration", "number", 0.15, min_val=0.0, max_val=10.0),
                  "curve": PropSpec("curve", "dropdown", "ease_out", options=_EaseCurveOptions())}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None),
              PinSpec("delta", NUMBER, default=8.0),
              PinSpec("duration", NUMBER, default=0.15)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        a = self.input_expr(ctx, node, "delta") if ctx.find_input_link(node["id"], "delta") else repr(self.prop_value(node, "delta", 8.0))
        d = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 0.15))
