@register_node("npc_hop_toward_character", "NPC", "Hop Toward Character",
               "Aimed hop at another character: horizontal speed chases their distance (capped at power), upward speed grows with distance but never dips below min_up x power - so every hop still arcs. 'other' takes ANY character source (Event Other/Victim, Nearest in Range, Choose Library Character, Tracked Target...); left unwired it aims at your Tracked Target automatically, so Track Nearest + this node is all the wiring a hopper needs. No/invalid target = safe straight-up hop at min_up strength - None-safe, no Validate Target gate needed. predict (seconds) leads the target by its own velocity - 0 = aim where they are.")
class NpcHopTowardCharacterNode(NodeBase):
    properties = {"power": PropSpec("power", "number", 520.0, min_val=0.0),
                  "min_up": PropSpec("min_up", "number", 0.35, min_val=0.0, max_val=1.0),
                  "predict": PropSpec("predict", "number", 0.0, min_val=0.0, max_val=2.0)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None, tooltip="Who hops (default: Self)"),
              PinSpec("other", OBJECT, default=None, tooltip="Who to leap AT - any object source; unwired = your Tracked Target"),
              PinSpec("power", NUMBER, default=520.0),
              PinSpec("min_up", NUMBER, default=0.35),
              PinSpec("predict", NUMBER, default=0.0)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        o = self.object_input_expr(ctx, node, "other", f"_ns_track({t})")
        p = self.input_expr(ctx, node, "power") if ctx.find_input_link(node["id"], "power") else repr(self.prop_value(node, "power", 520.0))
        m = self.input_expr(ctx, node, "min_up") if ctx.find_input_link(node["id"], "min_up") else repr(self.prop_value(node, "min_up", 0.35))
        pr = self.input_expr(ctx, node, "predict") if ctx.find_input_link(node["id"], "predict") else repr(self.prop_value(node, "predict", 0.0))
        ctx.emit(f"_npc_ot = {o}")
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.emit(f"    _npc_p = max(0.0, float({p}))")
        ctx.emit(f"    _npc_d = _ns_delta_to({t}, _npc_ot)")
        ctx.emit("    _npc_dx = float(_npc_d.x) if _npc_d is not None else 0.0")
        ctx.emit("    if _npc_d is not None and isinstance(_npc_ot, dict) and hasattr(_npc_ot.get('vel'), 'x'):")
        ctx.emit(f"        _npc_dx += float(_npc_ot['vel'].x) * max(0.0, float({pr}))")
        ctx.emit(f"    _npc_up = max(_ns_clamp(float({m}), 0.0, 1.0) * _npc_p, min(_npc_p, abs(_npc_dx) * 0.55))")
        ctx.emit(f"    {t}['vel'] = pygame.Vector2(_ns_clamp(_npc_dx * 2.0, -_npc_p, _npc_p), -min(_npc_p, _npc_up))")
        ctx.emit(f"    {t}['_smooth_vel'] = pygame.Vector2({t}['vel'])")
        ctx.emit(f"    {t}['gravity_grounded'] = False")
        ctx.emit(f"    {t}['sleeping'] = False")
        ctx.emit(f"    {t}.pop('_hop_ease', None)")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("npc_hop_toward_point", "NPC", "Hop Toward Point",
               "Aimed hop at a fixed world position - same arc rules as Hop Toward Character (distance-scaled upward arc, min_up floor on lift).")
class NpcHopTowardPointNode(NodeBase):
    properties = {"power": PropSpec("power", "number", 520.0, min_val=0.0),
                  "min_up": PropSpec("min_up", "number", 0.35, min_val=0.0, max_val=1.0)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None),
              PinSpec("position", VECTOR, default=None),
              PinSpec("power", NUMBER, default=520.0),
              PinSpec("min_up", NUMBER, default=0.35)]
    outputs = [PinSpec("", EXEC)]
