@register_node("npc_land_stop", "NPC", "Land Stop (Kill Horizontal)",
               "Zeros horizontal speed instantly (vertical speed untouched) and cancels any eased hop. Wire to On Wall Touch south so the hopper plants its landing instead of sliding.")
class NpcLandStopNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.emit(f"    if hasattr({t}.get('vel'), 'x'): {t}['vel'].x = 0.0")
        ctx.emit(f"    if hasattr({t}.get('_smooth_vel'), 'x'): {t}['_smooth_vel'].x = 0.0")
        ctx.emit(f"    {t}.pop('_hop_ease', None)")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("npc_get_up_speed", "NPC", "Get Up Speed",
               "Upward speed RIGHT NOW (positive while rising, negative while falling). The natural feed for tilt-while-airborne graphs.")
class NpcGetUpSpeedNode(NodeBase):
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("speed", NUMBER)]
    pure = True
