        tag = self.input_expr(ctx, node, "tag") if ctx.find_input_link(node["id"], "tag") else repr(self.prop_value(node, "tag", ""))
        kind = "tag_same" if str(self.prop_value(node, "mode", "same_tag")) == "same_tag" else "tag_any"
        ctx.emit(f"_ns_no_collide_add({t}, {kind!r}, {tag})")
        ctx.generate_exec_branch(node["id"], "", visited)

