@register_node("combat_direction_to_string", "Direction", "Direction to String",
               "Converts a direction Vector (blue pin) into a readable string ('south', 'north', 'east', 'west', or 'unknown').")
class DirectionToStringNode(NodeBase):
    inputs = [PinSpec("direction_vector", VECTOR, default=None)]
    outputs = [PinSpec("string", STRING)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        vec = self.input_expr(ctx, node, "direction_vector") if ctx.find_input_link(node["id"], "direction_vector") else "pygame.Vector2(0, 0)"
        return f"('south' if (hasattr({vec}, 'y') and {vec}.y > 0.5 and abs({vec}.x) < 0.5) else 'north' if (hasattr({vec}, 'y') and {vec}.y < -0.5 and abs({vec}.x) < 0.5) else 'east' if (hasattr({vec}, 'x') and {vec}.x > 0.5 and abs({vec}.y) < 0.5) else 'west' if (hasattr({vec}, 'x') and {vec}.x < -0.5 and abs({vec}.y) < 0.5) else 'unknown')"

@register_node("combat_direction_to_vector", "Direction", "Direction to Vector",
               "Converts a direction string ('south', 'north', 'east', 'west') into a normalized direction Vector.")
class DirectionToVectorNode(NodeBase):
    inputs = [PinSpec("direction_string", STRING, default="south")]
    outputs = [PinSpec("vector", VECTOR)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        ds = self.input_expr(ctx, node, "direction_string") if ctx.find_input_link(node["id"], "direction_string") else repr("south")
        return f"(pygame.Vector2(0, 1) if str({ds}).strip().lower() == 'south' else pygame.Vector2(0, -1) if str({ds}).strip().lower() == 'north' else pygame.Vector2(1, 0) if str({ds}).strip().lower() == 'east' else pygame.Vector2(-1, 0) if str({ds}).strip().lower() == 'west' else pygame.Vector2(0, 0))"

@register_node("combat_vector_to_direction", "Direction", "Vector to Direction",
               "Converts any general Vector into the nearest cardinal direction string ('south', 'north', 'east', or 'west').")
class VectorToDirectionNode(NodeBase):
    inputs = [PinSpec("vector", VECTOR, default=None)]
    outputs = [PinSpec("direction_string", STRING)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        vec = self.input_expr(ctx, node, "vector") if ctx.find_input_link(node["id"], "vector") else "pygame.Vector2(0, 0)"
        return f"('east' if (hasattr({vec}, 'x') and abs({vec}.x) >= abs({vec}.y) and {vec}.x >= 0) else 'west' if (hasattr({vec}, 'x') and abs({vec}.x) >= abs({vec}.y) and {vec}.x < 0) else 'south' if (hasattr({vec}, 'y') and abs({vec}.y) > abs({vec}.x) and {vec}.y >= 0) else 'north' if (hasattr({vec}, 'y') and {vec}.y < 0) else 'unknown')"

@register_node("combat_compare_bounce_direction", "Combat", "Is Bounce Direction?",
               "Checks if the given bounce direction Vector (blue pin) matches the specified target direction (North, South, East, or West). Wire the blue direction pin of On Wall Bounce straight here! Leave the pin UNWIRED to check the most recent real bounce the physics layer recorded.")
class CombatCompareBounceDirectionNode(NodeBase):
    properties = {"target_direction": PropSpec("target_direction", "dropdown", "south", options=["north", "south", "east", "west"])}
    inputs = [PinSpec("direction_vector", VECTOR, default=None)]
    outputs = [PinSpec("result", BOOLEAN)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        if ctx.find_input_link(node["id"], "direction_vector"):
            vec = self.input_expr(ctx, node, "direction_vector")
        else:
            # Unwired: fall back to the most recent REAL ricochet recorded
            # by the physics layer (frame-accurate inside event hooks).
            vec = ("((me.get('_last_bounce_dir') if isinstance(me.get('_last_bounce_dir'), pygame.Vector2) "
                   "else pygame.Vector2(0, 0)) if isinstance(me, dict) else pygame.Vector2(0, 0))")
        target = self.prop_value(node, "target_direction", "south")
        if target == "south":
            return f"(hasattr({vec}, 'y') and {vec}.y > 0.5 and abs({vec}.x) < 0.5)"
        elif target == "north":
            return f"(hasattr({vec}, 'y') and {vec}.y < -0.5 and abs({vec}.x) < 0.5)"
        elif target == "east":
            return f"(hasattr({vec}, 'x') and {vec}.x > 0.5 and abs({vec}.y) < 0.5)"
        elif target == "west":
            return f"(hasattr({vec}, 'x') and {vec}.x < -0.5 and abs({vec}.y) < 0.5)"
        return "False"

@register_node("combat_compare_touch_direction", "Combat", "Is Touch Direction?",
               "Checks if the given touch direction Vector (blue pin) matches the specified target direction (North, South, East, or West). Wire the blue direction pin of On Wall Touch straight here! Leave the pin UNWIRED to check the character's LIVE wall contact instead - on an Every Frame branch it answers 'am I currently touching something in that direction?' (south = floor, north = ceiling, east/west = side walls).")
class CombatCompareTouchDirectionNode(NodeBase):
    properties = {"target_direction": PropSpec("target_direction", "dropdown", "south", options=["north", "south", "east", "west"])}
    inputs = [PinSpec("direction_vector", VECTOR, default=None)]
    outputs = [PinSpec("result", BOOLEAN)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        if ctx.find_input_link(node["id"], "direction_vector"):
            vec = self.input_expr(ctx, node, "direction_vector")
        else:
            # Unwired: poll the live per-frame contact set maintained by physics.
            vec = ("(pygame.Vector2(0, 1) if (isinstance(me, dict) and 'south' in (me.get('_wall_contacts') or ())) "
                   "else pygame.Vector2(0, -1) if (isinstance(me, dict) and 'north' in (me.get('_wall_contacts') or ())) "
                   "else pygame.Vector2(1, 0) if (isinstance(me, dict) and 'east' in (me.get('_wall_contacts') or ())) "
                   "else pygame.Vector2(-1, 0) if (isinstance(me, dict) and 'west' in (me.get('_wall_contacts') or ())) "
                   "else pygame.Vector2(0, 0))")
        target = self.prop_value(node, "target_direction", "south")
        if target == "south":
            return f"(hasattr({vec}, 'y') and {vec}.y > 0.5 and abs({vec}.x) < 0.5)"
        elif target == "north":
            return f"(hasattr({vec}, 'y') and {vec}.y < -0.5 and abs({vec}.x) < 0.5)"
        elif target == "east":
            return f"(hasattr({vec}, 'x') and {vec}.x > 0.5 and abs({vec}.y) < 0.5)"
        elif target == "west":
            return f"(hasattr({vec}, 'x') and {vec}.x < -0.5 and abs({vec}.y) < 0.5)"
        return "False"


