@register_node("combat_modify_crit_chance", "Combat", "Modify Crit Chance",
               "Raises, lowers, or multiplies a target's critical strike probability.")
class CombatModifyCritChanceNode(NodeBase):
    properties = {"amount": PropSpec("amount", "number", 5.0), "multiply": PropSpec("multiply", "boolean", False)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("amount", NUMBER, default=5.0), PinSpec("multiply", BOOLEAN, default=False)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        amt = self.input_expr(ctx, node, "amount") if ctx.find_input_link(node["id"], "amount") else repr(self.prop_value(node, "amount", 5.0))
        mult = self.input_expr(ctx, node, "multiply") if ctx.find_input_link(node["id"], "multiply") else repr(self.prop_value(node, "multiply", False))
        ctx.emit(f"if {mult}: {t}['crit_chance'] = min(1.0, max(0.0, float({t}.get('crit_chance', 0.1)) * float({amt})))")
        ctx.emit(f"else: {t}['crit_chance'] = min(1.0, max(0.0, float({t}.get('crit_chance', 0.1)) + float({amt}) / 100.0))")
        ctx.generate_exec_branch(node["id"], "", visited)

