@register_node("combat_accuracy_check", "Combat", "Accuracy Check",
               "Returns whether an action lands after applying accuracy and evasion stages.")
class CombatAccuracyCheckNode(NodeBase):
    properties = {"base_accuracy": PropSpec("base_accuracy", "number", 100)}
    inputs = [PinSpec("attacker", OBJECT, default=None), PinSpec("target", OBJECT, default=None), PinSpec("base_accuracy", NUMBER, default=100)]
    outputs = [PinSpec("result", BOOLEAN), PinSpec("chance", NUMBER)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        attacker = self.object_input_expr(ctx, node, "attacker", "me")
        target = self.object_input_expr(ctx, node, "target", "me")
        acc = self.input_expr(ctx, node, "base_accuracy") if ctx.find_input_link(node["id"], "base_accuracy") else repr(self.prop_value(node, "base_accuracy", 100))
        chance_var = ctx.fresh_var("acc_chance")
        ctx.expr_cache[(node["id"], "chance")] = chance_var
        ctx.emit(f"{chance_var} = ctx.get_accuracy_chance({attacker}, {target}, {acc})")
        if output_name == "chance":
            return chance_var
        return f"(random.random() <= {chance_var})"

