@register_node("combat_calculate_damage", "Combat", "Calculate Damage",
               "Generic damage formula using power, offense, defense, crit, type multiplier, and any bonus multiplier.")
class CombatCalculateDamageNode(NodeBase):
    properties = {"power": PropSpec("power", "number", 40), "category": PropSpec("category", "dropdown", "physical", options=["physical", "special", "true"]), "damage_type": PropSpec("damage_type", "string", "physical"), "crit": PropSpec("crit", "boolean", False), "bonus_mult": PropSpec("bonus_mult", "number", 1.0)}
    inputs = [PinSpec("attacker", OBJECT, default=None), PinSpec("target", OBJECT, default=None), PinSpec("power", NUMBER, default=40), PinSpec("attack_value", NUMBER, default=0), PinSpec("defense_value", NUMBER, default=0), PinSpec("damage_type", STRING, default="physical"), PinSpec("crit", BOOLEAN, default=False), PinSpec("bonus_mult", NUMBER, default=1.0)]
    outputs = [PinSpec("damage", NUMBER)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        attacker = self.object_input_expr(ctx, node, "attacker", "me")
        target = self.object_input_expr(ctx, node, "target", "me")
        power = self.input_expr(ctx, node, "power") if ctx.find_input_link(node["id"], "power") else repr(self.prop_value(node, "power", 40))
        attack_value = self.input_expr(ctx, node, "attack_value") if ctx.find_input_link(node["id"], "attack_value") else "None"
        defense_value = self.input_expr(ctx, node, "defense_value") if ctx.find_input_link(node["id"], "defense_value") else "None"
        damage_type = self.input_expr(ctx, node, "damage_type") if ctx.find_input_link(node["id"], "damage_type") else repr(self.prop_value(node, "damage_type", "physical"))
        crit = self.input_expr(ctx, node, "crit") if ctx.find_input_link(node["id"], "crit") else repr(self.prop_value(node, "crit", False))
        bonus = self.input_expr(ctx, node, "bonus_mult") if ctx.find_input_link(node["id"], "bonus_mult") else repr(self.prop_value(node, "bonus_mult", 1.0))
        category = self.prop_value(node, "category", "physical")
        return f"ctx.calculate_damage({attacker}, {target}, {power}, {attack_value}, {defense_value}, {category!r}, {damage_type}, {crit}, {bonus})"

