    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("name", STRING, default="")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        name = self.input_expr(ctx, node, "name") if ctx.find_input_link(node["id"], "name") else repr(self.prop_value(node, "name", ""))
        ctx.emit(f"ctx.set_name({t}, {name})")
        ctx.generate_exec_branch(node["id"], "", visited)

