@register_node("gameplay_increase_speed", "Gameplay", "Increase Speed",
               "Adds a flat amount to the character's movement speed stat (units/sec). Increase 50 after a Decrease 50 returns the character to normal.")
class IncreaseSpeedNode(NodeBase):
    properties = {"amount": PropSpec("amount", "number", 50, min_val=0, max_val=10000)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("amount", NUMBER, default=50)]
    outputs = [PinSpec("", EXEC)]

    @staticmethod
    def _legacy_amount(node):
        # Older saves stored a decimal "multiplier" (e.g. 1.3). Convert it to
        # an equivalent flat amount against the 150 default speed so old
        # projects keep roughly the same behaviour instead of breaking.
        props = node.get("properties", {}) or {}
        if "amount" not in props and "multiplier" in props:
            try:
                return round((float(props["multiplier"]) - 1.0) * 150.0, 1)
            except Exception:
                return 50
        return None

    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        legacy = self._legacy_amount(node)
        if ctx.find_input_link(node["id"], "amount"):
            amt = self.input_expr(ctx, node, "amount")
        elif ctx.find_input_link(node["id"], "multiplier"):
            # Legacy graph with a wire into the old multiplier pin: convert
            # the incoming ratio to a flat amount at runtime.
            amt = f"(float({self.input_expr(ctx, node, 'multiplier')}) - 1.0) * max(1.0, float({t}.get('speed', 150) or 150))"
        else:
            amt = repr(legacy if legacy is not None else self.prop_value(node, "amount", 50))
        # Flat, symmetric stat change: bump the speed stat, keep max_speed in
        # step so the per-frame velocity clamp doesn't erase the change, and
        # scale current velocity so the effect is visible immediately.
        ctx.emit(f"_ns_spdadj = float({amt})")
        ctx.emit(f"_ns_spd_old = float({t}.get('speed', 150) or 0.0)")
        ctx.emit(f"{t}['speed'] = max(0.0, _ns_spd_old + _ns_spdadj)")
        # Knockback-aware: while a knockback is active the REAL cap lives in
        # _kb_base_max_speed (max_speed is temporarily bumped and gets
        # overwritten by that snapshot when the knockback expires). Adjust the
        # snapshot too, or the expiry restore silently wipes this stat change.
        ctx.emit(f"if '_kb_base_max_speed' in {t}: {t}['_kb_base_max_speed'] = max(0.0, float({t}.get('_kb_base_max_speed') or 0.0) + _ns_spdadj)")
        ctx.emit(f"{t}['max_speed'] = max(0.0, float({t}.get('max_speed', _ns_spd_old) or 0.0) + _ns_spdadj)")
        ctx.emit(f"_ns_spd_v = {t}.get('vel')")
        ctx.emit(f"if hasattr(_ns_spd_v, 'length') and _ns_spd_v.length() > 1e-6:")
        ctx.emit(f"    {t}['_last_dir'] = _ns_spd_v.normalize()  # remember heading in case a later Decrease stops us")
        ctx.emit(f"    _ns_spd_v.scale_to_length(max(0.0, _ns_spd_v.length() + _ns_spdadj))")
        ctx.emit(f"elif _ns_spdadj > 0 and hasattr(_ns_spd_v, 'length'):")
        ctx.emit(f"    # Stopped (a Decrease drove velocity to zero): a zero vector can't be")
        ctx.emit(f"    # rescaled, which used to freeze the character forever. Resume along")
        ctx.emit(f"    # the last known heading at the same magnitude the scale would give.")
        ctx.emit(f"    {t}['vel'] = pygame.Vector2({t}.get('_last_dir') or (1, 0)).normalize() * _ns_spdadj")
        ctx.emit(f"    if '_smooth_vel' in {t}: {t}['_smooth_vel'] = pygame.Vector2({t}['vel'])")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("gameplay_decrease_speed", "Gameplay", "Decrease Speed",
               "Subtracts a flat amount from the character's movement speed stat (units/sec). Decrease 50 then Increase 50 returns the character to normal — safe in every-X-frame loops.")
class DecreaseSpeedNode(NodeBase):
    properties = {"amount": PropSpec("amount", "number", 50, min_val=0, max_val=10000)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("amount", NUMBER, default=50)]
    outputs = [PinSpec("", EXEC)]

    @staticmethod
    def _legacy_amount(node):
        # Older saves stored a decimal "multiplier" (e.g. 0.7 = keep 70%).
        props = node.get("properties", {}) or {}
        if "amount" not in props and "multiplier" in props:
            try:
                return round((1.0 - float(props["multiplier"])) * 150.0, 1)
            except Exception:
                return 50
        return None

    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        legacy = self._legacy_amount(node)
        if ctx.find_input_link(node["id"], "amount"):
            amt = self.input_expr(ctx, node, "amount")
        elif ctx.find_input_link(node["id"], "multiplier"):
            # Legacy graph wired into the old multiplier pin (0.7 = keep 70%):
            # convert the ratio to a flat subtracted amount at runtime.
            amt = f"(1.0 - float({self.input_expr(ctx, node, 'multiplier')})) * max(1.0, float({t}.get('speed', 150) or 150))"
        else:
            amt = repr(legacy if legacy is not None else self.prop_value(node, "amount", 50))
        # Identical math to Increase Speed with a negated amount, so the two
        # nodes are exact inverses of each other.
        ctx.emit(f"_ns_spdadj = -float({amt})")
        ctx.emit(f"_ns_spd_old = float({t}.get('speed', 150) or 0.0)")
        ctx.emit(f"{t}['speed'] = max(0.0, _ns_spd_old + _ns_spdadj)")
        # Knockback-aware: adjust the pre-knockback snapshot when one exists
        # (see Increase Speed). Without this, Decrease during a knockback got
        # reverted on expiry — or worse, the stale snapshot re-raised the cap.
        ctx.emit(f"if '_kb_base_max_speed' in {t}: {t}['_kb_base_max_speed'] = max(0.0, float({t}.get('_kb_base_max_speed') or 0.0) + _ns_spdadj)")
        ctx.emit(f"{t}['max_speed'] = max(0.0, float({t}.get('max_speed', _ns_spd_old) or 0.0) + _ns_spdadj)")
        ctx.emit(f"_ns_spd_v = {t}.get('vel')")
        ctx.emit(f"if hasattr(_ns_spd_v, 'length') and _ns_spd_v.length() > 1e-6:")
        ctx.emit(f"    {t}['_last_dir'] = _ns_spd_v.normalize()  # keep heading so a later Increase can resume")
        ctx.emit(f"    _ns_spd_v.scale_to_length(max(0.0, _ns_spd_v.length() + _ns_spdadj))")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("gameplay_increase_attack", "Gameplay", "Increase Attack",
               "Permanently adds to the character's base damage output.")
class IncreaseAttackNode(NodeBase):
    properties = {"amount": PropSpec("amount", "number", 5)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("amount", NUMBER, default=5)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        amt = self.input_expr(ctx, node, "amount") if ctx.find_input_link(node["id"], "amount") else repr(self.prop_value(node, "amount", 5))
        ctx.emit(f"{t}['dmg_min'] = max(0, {t}['dmg_min'] + {amt})")
        ctx.emit(f"{t}['dmg_max'] = max(0, {t}['dmg_max'] + {amt})")
        ctx.generate_exec_branch(node["id"], "", visited)

