@register_node("gameplay_spawn_library_character", "Gameplay", "Spawn Library Character", "Choose any saved character and spawn it at an exact wired world position.")
class SpawnLibraryCharacterNode(NodeBase):
    properties={"character":PropSpec("character","character","" )}
    inputs=[PinSpec("",EXEC),PinSpec("position",VECTOR,default=None),PinSpec("character",STRING,default="")]
    outputs=[PinSpec("",EXEC),PinSpec("spawned",OBJECT)]
    def generate_code(self,ctx,node,visited):
        position=self.input_expr(ctx,node,"position") if ctx.find_input_link(node["id"],"position") else "me['pos']"
        character=self.input_expr(ctx,node,"character") if ctx.find_input_link(node["id"],"character") else repr(self.prop_value(node,"character",""))
        var=ctx.fresh_var("spawned");ctx.expr_cache[(node["id"],"spawned")]=var
        ctx.emit(f"{var}=ctx.spawn_library_character({character},{position})")
        _ns_emit_target_event_bindings(ctx, node["id"], "spawned", var, visited)
        ctx.generate_exec_branch(node["id"],"",visited)

