@register_node("gameplay_knockback", "Gameplay", "Knockback",
               "Applies a physics impulse in a direction to shove a character.")
class KnockbackNode(NodeBase):
    properties = {"force": PropSpec("force", "number", 300), "duration": PropSpec("duration", "number", 0.25, min_val=0.0), "stack": PropSpec("stack", "bool", False)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("direction", VECTOR, default=None), PinSpec("force", NUMBER, default=300), PinSpec("duration", NUMBER, default=0.25), PinSpec("stack", BOOLEAN, default=False)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        d = self.input_expr(ctx, node, "direction") if ctx.find_input_link(node["id"], "direction") else f"({t}['pos'] - me['pos'])"
        f = self.input_expr(ctx, node, "force") if ctx.find_input_link(node["id"], "force") else repr(self.prop_value(node, "force", 300))
        dur = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 0.25))
        stack = self.input_expr(ctx, node, "stack") if ctx.find_input_link(node["id"], "stack") else repr(bool(self.prop_value(node, "stack", False)))
        ctx.emit(f"_ns_knockback({t}, {d}, {f}, {dur}, {stack})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("gameplay_momentum", "Gameplay", "Get External Momentum",
               "Returns the current knockback/impulse vector. Authored movement speed is deliberately not included.")
class MomentumNode(NodeBase):
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("momentum", VECTOR), PinSpec("amount", NUMBER), PinSpec("active", BOOLEAN)]
    def generate_output_expr(self, ctx, node, output_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        if output_name == "momentum": return f"pygame.Vector2(({t}).get('_external_momentum', (0,0)))"
        if output_name == "amount": return f"pygame.Vector2(({t}).get('_external_momentum', (0,0))).length()"
        return f"pygame.Vector2(({t}).get('_external_momentum', (0,0))).length_squared() > 1e-6"

@register_node("gameplay_has_momentum", "Gameplay", "Has Momentum At Least",
               "True when a character's external knockback/impulse magnitude meets the threshold.")
class HasMomentumNode(NodeBase):
    properties = {"amount": PropSpec("amount", "number", 1.0, min_val=0.0)}
    inputs = [PinSpec("target", OBJECT, default=None), PinSpec("amount", NUMBER, default=1.0)]
    outputs = [PinSpec("has", BOOLEAN)]
    def generate_output_expr(self, ctx, node, output_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        amount = self.input_expr(ctx, node, "amount") if ctx.find_input_link(node["id"], "amount") else repr(self.prop_value(node, "amount", 1.0))
        return f"pygame.Vector2(({t}).get('_external_momentum', (0,0))).length() >= float({amount})"

