@register_node("target_find_random_opponent", "Targets", "Find Random Opponent", "Execution search with Found/Not Found branches, target, position, distance, and candidate count.")
class FindRandomOpponentNode(NodeBase):
    properties = {
        "min_distance": PropSpec("min_distance", "number", 0.0, min_val=0.0, max_val=2000.0),
        "max_distance": PropSpec("max_distance", "number", 0.0, min_val=0.0, max_val=4000.0),
        "identify_by": PropSpec("identify_by", "dropdown", "team", options=["team", "tag", "name"]),
        "team_filter": PropSpec("team_filter", "dropdown", "all", options=["enemy", "ally", "all"]),
        "tag": PropSpec("tag", "string", ""),
        "name": PropSpec("name", "string", ""),
        "fallback_any": PropSpec("fallback_any", "boolean", True),
        "include_self": PropSpec("include_self", "boolean", False),
    }
    inputs = [PinSpec("", EXEC), PinSpec("origin", OBJECT, default=None),
              PinSpec("min_distance", NUMBER, default=0.0),
              PinSpec("max_distance", NUMBER, default=0.0),
              PinSpec("tag", STRING, default=""), PinSpec("name", STRING, default="")]
    outputs = [PinSpec("found", EXEC), PinSpec("not_found", EXEC),
               PinSpec("target", OBJECT), PinSpec("position", VECTOR),
               PinSpec("distance", NUMBER), PinSpec("candidate_count", NUMBER)]
    def generate_code(self, ctx, node, visited):
        origin = self.object_input_expr(ctx, node, "origin", "me")
        lo = self.input_expr(ctx,node,"min_distance") if ctx.find_input_link(node["id"],"min_distance") else repr(self.prop_value(node,"min_distance",0.0))
        hi = self.input_expr(ctx,node,"max_distance") if ctx.find_input_link(node["id"],"max_distance") else repr(self.prop_value(node,"max_distance",0.0))
        identify_by = self.prop_value(node, "identify_by", "team")
        center = ctx.fresh_var("origin")
        candidates = ctx.fresh_var("candidates")
        target = ctx.fresh_var("target")
        distance = ctx.fresh_var("distance")
        ctx.emit(f"ctx.debug_range(me,{origin},{lo},{hi},{(node.get('custom_name') or self.title)!r})")
        ctx.emit(f"{center}=({origin}).get('pos',me['pos']) if isinstance({origin},dict) else pygame.Vector2({origin})")
        if identify_by == "tag":
            tag = self.input_expr(ctx,node,"tag") if ctx.find_input_link(node["id"],"tag") else repr(self.prop_value(node,"tag",""))
            ctx.emit(f"{candidates}=ctx.characters_with_tag(me,{center},float({hi}) if float({hi})>0 else 999999,{tag},{bool(self.prop_value(node,'include_self',False))!r})")
        elif identify_by == "name":
            name = self.input_expr(ctx,node,"name") if ctx.find_input_link(node["id"],"name") else repr(self.prop_value(node,"name",""))
            ctx.emit(f"{candidates}=ctx.characters_with_name(me,{center},float({hi}) if float({hi})>0 else 999999,{name},{bool(self.prop_value(node,'include_self',False))!r})")
        else:
            ctx.emit(f"{candidates}=ctx.characters_in_radius(me,{center},float({hi}) if float({hi})>0 else 999999,{self.prop_value(node,'team_filter','all')!r},{bool(self.prop_value(node,'include_self',False))!r})")
        ctx.emit(f"{candidates}=[_c for _c in {candidates} if {center}.distance_to(_c['pos'])>=float({lo}) and (float({hi})<=0 or {center}.distance_to(_c['pos'])<=float({hi}))]")
        if identify_by == "team" and self.prop_value(node,"fallback_any",True) and self.prop_value(node,"team_filter","all") != "all":
            ctx.emit(f"if not {candidates}:")
            ctx.push_indent();ctx.emit(f"{candidates}=ctx.characters_in_radius(me,{center},float({hi}) if float({hi})>0 else 999999,'all',{bool(self.prop_value(node,'include_self',False))!r})");ctx.emit(f"{candidates}=[_c for _c in {candidates} if {center}.distance_to(_c['pos'])>=float({lo})]");ctx.pop_indent()
        ctx.emit(f"{target}=random.choice({candidates}) if {candidates} else None")
        ctx.emit(f"{distance}={center}.distance_to({target}['pos']) if {target} else -1")
        ctx.expr_cache[(node["id"],"target")]=target
        ctx.expr_cache[(node["id"],"position")]=f"({target}['pos'] if {target} else {center})"
        ctx.expr_cache[(node["id"],"distance")]=distance
        ctx.expr_cache[(node["id"],"candidate_count")]=f"len({candidates})"
        ctx.emit(f"if {target} is not None:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"found",visited);ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"not_found",visited);ctx.pop_indent()

@register_node("target_validate", "Targets", "Validate Target", "Gate any target-based action through Valid/Invalid execution branches.")
class ValidateTargetNode(NodeBase):
    inputs=[PinSpec("",EXEC),PinSpec("target",OBJECT,default=None)]
    outputs=[PinSpec("valid",EXEC),PinSpec("invalid",EXEC),PinSpec("target",OBJECT),PinSpec("position",VECTOR)]
    def generate_code(self,ctx,node,visited):
        target=self.input_expr(ctx,node,"target") if ctx.find_input_link(node["id"],"target") else "None"
        ctx.expr_cache[(node["id"],"target")]=target
        ctx.expr_cache[(node["id"],"position")]=f"({target}['pos'] if {target} else me['pos'])"
        ctx.emit(f"if isinstance({target},dict) and {target}.get('hp',0)>0:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"valid",visited);ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"invalid",visited);ctx.pop_indent()

