        ctx.emit(f"ctx.damage_cone(me,{o},{d},{_angle!r},{_range!r},{amount},{self.prop_value(node,'team_filter','enemy')!r},{bool(self.prop_value(node,'allow_self',False))!r},{_tag})"); ctx.generate_exec_branch(node["id"],"",visited)

