@register_node("weather_lightning", "Weather", "Lightning Strike", "Custom animation + impact damage + optional chain. No collision contact required.")
class LightningStrikeNode(NodeBase):
    properties={"animation":PropSpec("animation","animation","lightning"),"damage":PropSpec("damage","number",35),"radius":PropSpec("radius","number",45),"jumps":PropSpec("jumps","number",0,min_val=0,max_val=20),"jump_range":PropSpec("jump_range","number",100),"decay":PropSpec("decay","number",.8,min_val=0,max_val=1),"team_filter":PropSpec("team_filter","dropdown","all",options=["enemy","ally","all"]),"allow_self":PropSpec("allow_self","boolean",False)}
    inputs=[PinSpec("",EXEC),PinSpec("target",OBJECT,default=None),PinSpec("position",VECTOR,default=None),
            PinSpec("animation",STRING,default="lightning"),PinSpec("damage",NUMBER,default=35),PinSpec("radius",NUMBER,default=45),
            PinSpec("jumps",NUMBER,default=0),PinSpec("jump_range",NUMBER,default=100),PinSpec("decay",NUMBER,default=.8),PinSpec("allow_self",BOOLEAN,default=False)]
    outputs=[PinSpec("",EXEC,tooltip="Successfully struck"),PinSpec("failed",EXEC,tooltip="No target was supplied"),PinSpec("target",OBJECT)]
    def generate_code(self,ctx,node,visited):
        # A connected selector returning None must stay None. Falling back to
        # Self made failed searches silently strike the caster instead.
        t=self.input_expr(ctx,node,"target") if ctx.find_input_link(node["id"],"target") else "me"
        ctx.expr_cache[(node["id"],"target")]=t
        p=self.input_expr(ctx,node,"position") if ctx.find_input_link(node["id"],"position") else f"({t})['pos']"
        def value(name,default): return self.input_expr(ctx,node,name) if ctx.find_input_link(node["id"],name) else repr(self.prop_value(node,name,default))
        anim=value("animation","lightning");damage=value("damage",35);radius=value("radius",45);jumps=value("jumps",0);jump_range=value("jump_range",100);decay=value("decay",.8);allow=value("allow_self",False)
        team_filter = self.prop_value(node, "team_filter", "all")
        ctx.emit(f"if {t} is not None:")
        ctx.push_indent()
        ctx.emit(f"ctx.play_animation_at({anim},{p},target={t},scale=max(.5,({radius})/32))")
        ctx.emit(f"ctx.damage_radius(me,{p},{radius},{damage},{team_filter!r},{allow},0)")
        ctx.emit(f"if int({jumps})>0:")
        ctx.push_indent();ctx.emit(f"ctx.chain_lightning(me,{t},{damage},int({jumps}),{jump_range},{decay},{anim},{allow})");ctx.pop_indent()
        ctx.generate_exec_branch(node["id"],"",visited)
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"failed",visited);ctx.pop_indent()

