# ---------- Cardinal / Directional Combat ----------
def _cardinal_components(node, cls):
    x = int(bool(cls.prop_value(node, "east", False))) - int(bool(cls.prop_value(node, "west", False)))
    y = int(bool(cls.prop_value(node, "south", False))) - int(bool(cls.prop_value(node, "north", False)))
    return x, y

def _cardinal_expr(node, cls):
    x, y = _cardinal_components(node, cls)
    if x == 0 and y == 0:
        return "pygame.Vector2(0,0)"
    length = math.sqrt(x*x + y*y)
    return f"pygame.Vector2({x/length!r},{y/length!r})"

def _cardinal_properties(default="north"):
    return {
        "north": PropSpec("north", "boolean", default in ("north", "north_east", "north_west")),
        "south": PropSpec("south", "boolean", default in ("south", "south_east", "south_west")),
        "east": PropSpec("east", "boolean", default in ("east", "north_east", "south_east")),
        "west": PropSpec("west", "boolean", default in ("west", "north_west", "south_west")),
    }

@register_node("direction_cardinal", "Direction", "Cardinal Direction", "Toggle North/South/East/West. North + East automatically becomes a normalized diagonal.")
class CardinalDirectionNode(NodeBase):
    properties = _cardinal_properties("north")
    outputs = [PinSpec("direction", VECTOR)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        return _cardinal_expr(node, self)

@register_node("direction_preset", "Direction", "Direction Preset",
               "Outputs a common predefined direction vector (Up, Down, Left, Right, Forward).")
class DirectionPresetNode(NodeBase):
    properties = {"direction": PropSpec("direction", "dropdown", "North / Top",
        options=["North / Top","North East","East / Right","South East","South / Bottom","South West","West / Left","North West"])}
    outputs = [PinSpec("direction", VECTOR)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        vectors={"North / Top":(0,-1),"North East":(1,-1),"East / Right":(1,0),"South East":(1,1),"South / Bottom":(0,1),"South West":(-1,1),"West / Left":(-1,0),"North West":(-1,-1)}
        x,y=vectors.get(self.prop_value(node,"direction","North / Top"),(0,-1)); length=math.sqrt(x*x+y*y)
        return f"pygame.Vector2({x/length!r},{y/length!r})"

@register_node("direction_combine", "Direction", "Combine Directions", "Add two vectors and normalize them; North plus East becomes North East.")
class CombineDirectionsNode(NodeBase):
    inputs=[PinSpec("a",VECTOR,default=(0,-1)),PinSpec("b",VECTOR,default=(1,0))]
    outputs=[PinSpec("direction",VECTOR)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        a=self.input_expr(ctx,node,"a");b=self.input_expr(ctx,node,"b");return f"((({a})+({b})).normalize() if (({a})+({b})).length_squared() else pygame.Vector2())"

@register_node("direction_cardinal_offset", "Direction", "Cardinal Position Offset", "Move a world position a chosen distance in a cardinal/diagonal direction.")
class CardinalOffsetNode(NodeBase):
    properties={**_cardinal_properties("north"),"distance":PropSpec("distance","number",100)}
    inputs=[PinSpec("origin",VECTOR,default=None),PinSpec("direction",VECTOR,default=None),PinSpec("distance",NUMBER,default=100)]
    outputs=[PinSpec("position",VECTOR)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        origin=self.input_expr(ctx,node,"origin") if ctx.find_input_link(node["id"],"origin") else "me['pos']"
        direction=self.input_expr(ctx,node,"direction") if ctx.find_input_link(node["id"],"direction") else _cardinal_expr(node,self)
        distance=self.input_expr(ctx,node,"distance") if ctx.find_input_link(node["id"],"distance") else repr(self.prop_value(node,"distance",100))
        return f"(({origin})+({direction})*({distance}))"

@register_node("direction_cardinal_damage", "Area Damage", "Cardinal Direction Damage", "Damage only North/Top, South/Bottom, East/Right, West/Left, or any diagonal combination, between minimum and maximum distance.")
class CardinalDamageNode(NodeBase):
    properties={**_cardinal_properties("north"),
        "shape":PropSpec("shape","dropdown","lane",options=["lane","cone"]),
        "min_distance":PropSpec("min_distance","number",0,min_val=0,max_val=2000),
        "max_distance":PropSpec("max_distance","number",200,min_val=1,max_val=2000),
        "width":PropSpec("width","number",80,min_val=1,max_val=1000),
        "angle":PropSpec("angle","number",45,min_val=1,max_val=360),
        "damage":PropSpec("damage","number",25,min_val=0,max_val=1000),
        "team_filter":PropSpec("team_filter","dropdown","enemy",options=["enemy","ally","all"]),
        "allow_self":PropSpec("allow_self","boolean",False)}
    inputs=[PinSpec("",EXEC),PinSpec("origin",VECTOR,default=None),PinSpec("direction",VECTOR,default=None),PinSpec("damage",NUMBER,default=25)]
    outputs=[PinSpec("",EXEC),PinSpec("hit_characters",OBJECT)]
    def generate_code(self,ctx,node,visited):
        origin=self.input_expr(ctx,node,"origin") if ctx.find_input_link(node["id"],"origin") else "me['pos']"
        direction=self.input_expr(ctx,node,"direction") if ctx.find_input_link(node["id"],"direction") else _cardinal_expr(node,self)
        damage=self.input_expr(ctx,node,"damage") if ctx.find_input_link(node["id"],"damage") else repr(self.prop_value(node,"damage",25))
        _min=self.prop_value(node,"min_distance",0);_max=self.prop_value(node,"max_distance",200)
        _width=self.prop_value(node,"width",80);_angle=self.prop_value(node,"angle",45)
        _shape=self.prop_value(node,"shape","lane");_label=(node.get("custom_name") or self.title)
        # Accurate band gizmo (lane rectangle or cone sector) that mirrors the
        # runtime dot/cross test and follows fused diagonals (North+East).
        ctx.emit(f"ctx.debug_band(me,{origin},{direction},{_min!r},{_max!r},{_width!r},{_angle!r},{_shape!r},(90,210,255),0.25,{_label!r})")
        var=ctx.fresh_var("cardinal_hits");ctx.expr_cache[(node["id"],"hit_characters")]=var
        ctx.emit(f"{var}=ctx.damage_direction_band(me,{origin},{direction},{_min!r},{_max!r},{_width!r},{_angle!r},{_shape!r},{damage},{self.prop_value(node,'team_filter','enemy')!r},{bool(self.prop_value(node,'allow_self',False))!r})")
        ctx.generate_exec_branch(node["id"],"",visited)

@register_node("direction_cardinal_targets", "Area Damage", "Get Characters In Cardinal Range",
               "Returns characters strictly in a North/South/East/West direction from the source.")
class CardinalTargetsNode(NodeBase):
    properties={**_cardinal_properties("north"),"shape":PropSpec("shape","dropdown","lane",options=["lane","cone"]),"min_distance":PropSpec("min_distance","number",0),"max_distance":PropSpec("max_distance","number",200),"width":PropSpec("width","number",80),"angle":PropSpec("angle","number",45),"team_filter":PropSpec("team_filter","dropdown","enemy",options=["enemy","ally","all"]),"include_self":PropSpec("include_self","boolean",False)}
    inputs=[PinSpec("origin",VECTOR,default=None),PinSpec("direction",VECTOR,default=None)]
    outputs=[PinSpec("characters",OBJECT)]
    def generate_output_expr(self,ctx,node,output_name):
        origin=self.input_expr(ctx,node,"origin") if ctx.find_input_link(node["id"],"origin") else "me['pos']";direction=self.input_expr(ctx,node,"direction") if ctx.find_input_link(node["id"],"direction") else _cardinal_expr(node,self)
        _min=self.prop_value(node,"min_distance",0);_max=self.prop_value(node,"max_distance",200)
        _width=self.prop_value(node,"width",80);_angle=self.prop_value(node,"angle",45)
        _shape=self.prop_value(node,"shape","lane");_team=self.prop_value(node,"team_filter","enemy")
        _inc=bool(self.prop_value(node,"include_self",False));_label=(node.get("custom_name") or self.title)
        _actual=(f"ctx.characters_in_direction_band(me,{origin},{direction},{_min!r},{_max!r},{_width!r},{_angle!r},{_shape!r},{_team!r},{_inc!r})")
        # debug_band is falsy, so `or` chains past it into the real call while
        # still firing the accurate gizmo each evaluation.
        return (f"(ctx.debug_band(me,{origin},{direction},{_min!r},{_max!r},{_width!r},{_angle!r},{_shape!r},(90,210,255),0.25,{_label!r}) or {_actual})")

@register_node("direction_cardinal_check", "Area Damage", "Enemy In Cardinal Range?",
               "Returns True/False whether any matching character is in the chosen cardinal direction within range. Pure boolean — wire straight into If / Else or any condition pin.")
class CardinalRangeCheckNode(NodeBase):
    properties={**_cardinal_properties("east"),"min_distance":PropSpec("min_distance","number",0),"max_distance":PropSpec("max_distance","number",200),"width":PropSpec("width","number",80),"angle":PropSpec("angle","number",45),"team_filter":PropSpec("team_filter","dropdown","enemy",options=["enemy","ally","all"]),"include_self":PropSpec("include_self","boolean",False)}
    inputs=[PinSpec("origin",VECTOR,default=None),PinSpec("direction",VECTOR,default=None)]
    outputs=[PinSpec("result",BOOLEAN)]
    pure=True
    def generate_output_expr(self,ctx,node,output_name):
        origin=self.input_expr(ctx,node,"origin") if ctx.find_input_link(node["id"],"origin") else "me['pos']"
        direction=self.input_expr(ctx,node,"direction") if ctx.find_input_link(node["id"],"direction") else _cardinal_expr(node,self)
        _min=self.prop_value(node,"min_distance",0);_max=self.prop_value(node,"max_distance",200)
        _width=self.prop_value(node,"width",80);_team=self.prop_value(node,"team_filter","enemy")
        _inc=bool(self.prop_value(node,"include_self",False));_label=(node.get("custom_name") or self.title)
        _actual=(f"ctx.characters_in_direction_band(me,{origin},{direction},{_min!r},{_max!r},{_width!r},45,'lane',{_team!r},{_inc!r})")
        return (f"bool((ctx.debug_band(me,{origin},{direction},{_min!r},{_max!r},{_width!r},45,'lane',(90,210,255),0.25,{_label!r}) or {_actual}))")

# -----------------------------------------------------------------------------
# ANGLE SECTOR TARGETING
# -----------------------------------------------------------------------------
@register_node("direction_enemy_in_angle_sector", "Direction", "Enemy In Angle Sector?",
               "Checks whether any matching character is inside a configurable degree sector. "
               "0° starts along the supplied Base Direction (default: the character's current left/right facing). "
               "The live cyan cone gizmo is drawn whenever this node evaluates.")
class EnemyInAngleSectorNode(NodeBase):
    properties = {
        "start_degrees": PropSpec("start_degrees", "number", 0.0),
        "end_degrees": PropSpec("end_degrees", "number", 180.0),
        "min_distance": PropSpec("min_distance", "number", 0.0),
        "max_distance": PropSpec("max_distance", "number", 220.0),
        "team_filter": PropSpec("team_filter", "dropdown", "enemy", options=["enemy", "ally", "all"]),
        "include_self": PropSpec("include_self", "boolean", False),
        "gizmo": PropSpec("gizmo", "boolean", True),
    }
    inputs = [PinSpec("origin", VECTOR, default=None), PinSpec("base_direction", VECTOR, default=None),
              PinSpec("start_degrees", NUMBER, default=0.0), PinSpec("end_degrees", NUMBER, default=180.0)]
    outputs = [PinSpec("result", BOOLEAN), PinSpec("targets", OBJECT), PinSpec("center_direction", VECTOR), PinSpec("span", NUMBER)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        origin = self.input_expr(ctx,node,"origin") if ctx.find_input_link(node["id"],"origin") else "me.get('pos', pygame.Vector2())"
        base = self.input_expr(ctx,node,"base_direction") if ctx.find_input_link(node["id"],"base_direction") else "pygame.Vector2(-1 if me.get('flip_x', False) else 1, 0)"
        st = self.input_expr(ctx,node,"start_degrees") if ctx.find_input_link(node["id"],"start_degrees") else repr(self.prop_value(node,"start_degrees",0.0))
        en = self.input_expr(ctx,node,"end_degrees") if ctx.find_input_link(node["id"],"end_degrees") else repr(self.prop_value(node,"end_degrees",180.0))
        mn = repr(self.prop_value(node,"min_distance",0.0)); mx=repr(self.prop_value(node,"max_distance",220.0))
        team=repr(self.prop_value(node,"team_filter","enemy")); inc=repr(bool(self.prop_value(node,"include_self",False)))
        key = ctx.fresh_var("sector")
        ctx.emit(f"{key}_base = pygame.Vector2({base})")
        ctx.emit(f"if {key}_base.length_squared() <= 1e-9: {key}_base = pygame.Vector2(1,0)")
        ctx.emit(f"{key}_base = {key}_base.normalize()")
        ctx.emit(f"{key}_start = float({st}) % 360.0")
        ctx.emit(f"{key}_span = (float({en}) - float({st})) % 360.0")
        ctx.emit(f"if abs(float({en}) - float({st})) > 1e-6 and {key}_span <= 1e-6: {key}_span = 360.0")
        ctx.emit(f"{key}_dir = {key}_base.rotate({key}_start + {key}_span * .5)")
        ctx.emit(f"{key}_targets = ctx.characters_in_direction_band(me, {origin}, {key}_dir, {mn}, {mx}, 0.0, {key}_span, 'cone', {team}, {inc})")
        if bool(self.prop_value(node,"gizmo",True)):
            label = repr(node.get("custom_name") or "Angle Sector")
            ctx.emit(f"ctx.debug_cone(me, {origin}, {key}_dir, {key}_span, {mx}, (90,210,255), .25, {label})")
        if output_name == "targets": return f"{key}_targets"
        if output_name == "center_direction": return f"{key}_dir"
        if output_name == "span": return f"{key}_span"
        return f"bool({key}_targets)"

@register_node("direction_enemy_in_half_sector", "Direction", "Enemy In Left / Right Half?",
               "Simple half-circle sector check. Left = North→South along the character's left side; Right = North→South along its right side. Draws a live cyan half-circle gizmo.")
class EnemyInHalfSectorNode(NodeBase):
    properties={"side":PropSpec("side","dropdown","left",options=["left","right"]),"max_distance":PropSpec("max_distance","number",220.0),"team_filter":PropSpec("team_filter","dropdown","enemy",options=["enemy","ally","all"])}
    inputs=[PinSpec("origin",VECTOR,default=None)]
    outputs=[PinSpec("result",BOOLEAN),PinSpec("targets",OBJECT)]
    pure=True
    def generate_output_expr(self,ctx,node,output_name):
        org=self.input_expr(ctx,node,"origin") if ctx.find_input_link(node["id"],"origin") else "me.get('pos',pygame.Vector2())"
        side=str(self.prop_value(node,"side","left")); direction="pygame.Vector2(-1,0)" if side=="left" else "pygame.Vector2(1,0)"
        mx=repr(self.prop_value(node,"max_distance",220.0)); team=repr(self.prop_value(node,"team_filter","enemy")); key=ctx.fresh_var("half_sector")
        ctx.emit(f"{key}_targets=ctx.characters_in_direction_band(me,{org},{direction},0.0,{mx},0.0,180.0,'cone',{team},False)")
        _half_label = "Left Half" if side == "left" else "Right Half"
        ctx.emit(f"ctx.debug_cone(me,{org},{direction},180.0,{mx},(90,210,255),.25,{_half_label!r})")
        return f"{key}_targets" if output_name=="targets" else f"bool({key}_targets)"

