@register_node("animation_at_position", "Animation", "Play Animation At Position",
               "Plays a VFX animation clip at a specific world position.")
class AnimationAtPositionNode(NodeBase):
    properties={"animation":PropSpec("animation","animation",""),"duration":PropSpec("duration","number",0),"scale":PropSpec("scale","number",1)}
    inputs=[PinSpec("",EXEC),PinSpec("position",VECTOR,default=None),PinSpec("animation",STRING,default=""),PinSpec("duration",NUMBER,default=0),PinSpec("scale",NUMBER,default=1)]
    outputs=[PinSpec("",EXEC),PinSpec("effect",OBJECT)]
    def generate_code(self,ctx,node,visited):
        p=self.input_expr(ctx,node,"position") if ctx.find_input_link(node["id"],"position") else "me['pos']"
        def value(name,default):return self.input_expr(ctx,node,name) if ctx.find_input_link(node["id"],name) else repr(self.prop_value(node,name,default))
        animation=value("animation","");duration=value("duration",0);scale=value("scale",1)
        v=ctx.fresh_var("effect");ctx.expr_cache[(node["id"],"effect")]=v
        ctx.emit(f"{v}=ctx.play_animation_at({animation},{p},{duration},{scale})");ctx.generate_exec_branch(node["id"],"",visited)

