    properties = {"count": PropSpec("count", "number", 5), "radius": PropSpec("radius", "number", 50)}
    inputs = [PinSpec("", EXEC), PinSpec("count", NUMBER, default=5), PinSpec("radius", NUMBER, default=50)]
    outputs = [PinSpec("", EXEC), PinSpec("spawned", ANY)]
    def generate_code(self, ctx, node, visited):
        cnt = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(self.prop_value(node, "count", 5))
        rad = self.input_expr(ctx, node, "radius") if ctx.find_input_link(node["id"], "radius") else repr(self.prop_value(node, "radius", 50))
