def _make_control_status_node(key,title,status):
    class ControlStatusNode(NodeBase):
        properties={"duration":PropSpec("duration","number",1)};inputs=[PinSpec("",EXEC),PinSpec("target",OBJECT,default=None)];outputs=[PinSpec("",EXEC)]
        def generate_code(self,ctx,node,visited):t=self.object_input_expr(ctx,node,"target","me");ctx.emit(f"ctx.set_control_status({t},{status!r},{self.prop_value(node,'duration',1)!r})");ctx.generate_exec_branch(node["id"],"",visited)
    register_node(key,"Status",title)(ControlStatusNode)
_make_control_status_node("status_stun","Stun","stun")
