class ReflectDamageNode(NodeBase):
    properties={"percent":PropSpec("percent","number",50,min_val=0,max_val=500),"allow_self":PropSpec("allow_self","boolean",False)}
    inputs=[PinSpec("",EXEC),PinSpec("attacker",OBJECT,default=None),PinSpec("incoming_damage",NUMBER,default=0)];outputs=[PinSpec("",EXEC)]
