@register_node("combat_directional_damage", "Direction", "Damage If Direction Matches",
               "Deals bonus or reduced damage based on whether the attack came from front or behind.")
class DirectionalDamageNode(NodeBase):
    properties={"side":PropSpec("side","dropdown","behind",options=["front","behind"]),"damage":PropSpec("damage","number",30),"allow_self":PropSpec("allow_self","boolean",False)};inputs=[PinSpec("",EXEC),PinSpec("target",OBJECT,default=None)];outputs=[PinSpec("",EXEC),PinSpec("matched",BOOLEAN)]
    def generate_code(self,ctx,node,visited):
        t=self.object_input_expr(ctx,node,"target","locals().get('other') or me");op='<' if self.prop_value(node,'side','behind')=='behind' else '>';v=ctx.fresh_var('matched');ctx.expr_cache[(node['id'],'matched')]=v;ctx.emit(f"{v}=(me.get('vel',pygame.Vector2(1,0)).dot(({t})['pos']-me['pos']) {op} 0)");ctx.emit(f"if {v}: ctx.deal_script_damage(me,{t},{self.prop_value(node,'damage',30)!r},{bool(self.prop_value(node,'allow_self',False))!r})");ctx.generate_exec_branch(node["id"],"",visited)

@register_node("explosive_chain_reaction", "Explosives", "Chain Reaction",
               "Triggers secondary explosions on targets killed by the primary explosion.")
class ChainReactionNode(SpawnExplosionAdvancedNode):
    properties={"radius":PropSpec("radius","number",130),"damage":PropSpec("damage","number",35),"force":PropSpec("force","number",350),"animation":PropSpec("animation","animation","explosion"),"team_filter":PropSpec("team_filter","dropdown","all",options=["enemy","ally","all"]),"allow_self":PropSpec("allow_self","boolean",False),"falloff":PropSpec("falloff","number",.4)}

@register_node("utility_clamp_damage", "Utility", "Clamp Damage",
               "Caps incoming or outgoing damage to a min/max range.")
class ClampDamageNode(NodeBase):
    inputs=[PinSpec("damage",NUMBER,default=0),PinSpec("min",NUMBER,default=0),PinSpec("max",NUMBER,default=9999)];outputs=[PinSpec("damage",NUMBER)];pure=True
    def generate_output_expr(self,ctx,node,output_name):return f"_ns_clamp({self.input_expr(ctx,node,'damage')},{self.input_expr(ctx,node,'min')},{self.input_expr(ctx,node,'max')})"

@register_node("utility_team_filter", "Utility", "Team Filter",
               "Checks whether a target is an Ally, Enemy, or Neutral relative to the source.")
class TeamFilterNode(NodeBase):
    properties={"filter":PropSpec("filter","dropdown","enemy",options=["enemy","ally","all"])};inputs=[PinSpec("characters",OBJECT,default=None)];outputs=[PinSpec("characters",OBJECT)]
    def generate_output_expr(self,ctx,node,output_name):lst=self.object_input_expr(ctx,node,"characters","[]");return f"[_c for _c in ({lst}) if ctx._team_matches(me,_c,{self.prop_value(node,'filter','enemy')!r})]"

# ---------- Exposed Trait Parameters ----------
# Connect these value nodes to regular data inputs. Their names/defaults are
# emitted into the generated script's PARAMS dict, so the character Traits
# panel can override them without reopening the graph.
@register_node("parameter_number", "Parameters", "Number Parameter",
               "Exposes a numeric slider in the Character Traits panel so you can tune it per-character without editing the script.")
class NumberParameterNode(NodeBase):
    properties={"name":PropSpec("name","string","amount"),"default":PropSpec("default","number",10,min_val=-10000,max_val=10000)}
    outputs=[PinSpec("value",NUMBER)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        name=str(self.prop_value(node,"name","amount"));default=self.prop_value(node,"default",10);return f"float(PARAMS.get({name!r},{default!r}))"

@register_node("parameter_boolean", "Parameters", "Boolean Parameter",
               "Exposes a True/False checkbox in the Character Traits panel.")
class BooleanParameterNode(NodeBase):
    properties={"name":PropSpec("name","string","enabled"),"default":PropSpec("default","boolean",True)}
    outputs=[PinSpec("value",BOOLEAN)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        name=str(self.prop_value(node,"name","enabled"));default=bool(self.prop_value(node,"default",True));return f"_ns_bool(PARAMS.get({name!r},{default!r}))"

@register_node("parameter_text", "Parameters", "Text Parameter",
               "Exposes a text field in the Character Traits panel.")
class TextParameterNode(NodeBase):
    properties={"name":PropSpec("name","string","text"),"default":PropSpec("default","string","")}
    outputs=[PinSpec("value",STRING)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        name=str(self.prop_value(node,"name","text"));default=str(self.prop_value(node,"default",""));return f"PARAMS.get({name!r},{default!r})"

@register_node("parameter_animation", "Parameters", "Animation Parameter", "Exposes an Animation Editor state picker in the character Traits section.")
class AnimationParameterNode(NodeBase):
    properties={"name":PropSpec("name","string","animation"),"default":PropSpec("default","animation","")}
    outputs=[PinSpec("value",STRING)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        name=str(self.prop_value(node,"name","animation"));default=str(self.prop_value(node,"default",""));return f"PARAMS.get({name!r},{default!r})"

@register_node("animation_choose", "Animation", "Choose Animation", "Select a reusable animation and output its name for any animation input.")
class ChooseAnimationNode(NodeBase):
    properties={"animation":PropSpec("animation","animation","")}
    outputs=[PinSpec("animation",STRING)];pure=True
    def generate_output_expr(self,ctx,node,output_name):return repr(self.prop_value(node,"animation",""))

@register_node("parameter_color", "Parameters", "Color Parameter",
               "Exposes a color picker in the Character Traits panel.")
class ColorParameterNode(NodeBase):
    properties={"name":PropSpec("name","string","color"),"color":PropSpec("color","color",[255,255,255])}
    outputs=[PinSpec("value",COLOR)];pure=True
    def generate_output_expr(self,ctx,node,output_name):
        name=str(self.prop_value(node,"name","color"));default=list(self.prop_value(node,"color",[255,255,255]));return f"tuple(PARAMS.get({name!r},{default!r}))"

# ---------- Variables ----------
@register_node("variable_set", "Variables", "Set Variable",
               "Sets a project-wide global variable accessible by every character in the scene.")
class SetVariableNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_var"),
                  "type": PropSpec("type", "dropdown", "number", options=["number", "string", "boolean", "vector", "color", "object"])}
    inputs = [PinSpec("", EXEC), PinSpec("value", ANY, default=None)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        name = self.prop_value(node, "name", "my_var")
        v = self.input_expr(ctx, node, "value") if ctx.find_input_link(node["id"], "value") else ctx.default_to_expr(self.prop_value(node, "type", "number"), None)
        ctx.emit(f"_ns_variables[{repr(name)}] = {v}")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("variable_get", "Variables", "Get Variable",
               "Reads a project-wide global variable.")
class GetVariableNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_var"),
                  "type": PropSpec("type", "dropdown", "number", options=["number", "string", "boolean", "vector", "color", "object"])}
    inputs = []
    outputs = [PinSpec("value", ANY)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        name = self.prop_value(node, "name", "my_var")
        vtype = self.prop_value(node, "type", "number")
        default = ctx.default_to_expr(vtype, None)
        raw = f"_ns_variables.get({repr(name)}, {default})"
        if vtype == "number":
            return f"_ns_to_number({raw}, {default})"
        if vtype == "boolean":
            return f"_ns_bool({raw})"
        return raw

@register_node("variable_increment", "Variables", "Increment",
               "Adds a value to a global variable.")
class IncrementNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_var"), "amount": PropSpec("amount", "number", 1)}
    inputs = [PinSpec("", EXEC), PinSpec("amount", NUMBER, default=1)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        name = self.prop_value(node, "name", "my_var")
        amt = self.input_expr(ctx, node, "amount") if ctx.find_input_link(node["id"], "amount") else repr(self.prop_value(node, "amount", 1))
        ctx.emit(f"_ns_variables[{repr(name)}] = _ns_variables.get({repr(name)}, 0) + ({amt})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("variable_decrement", "Variables", "Decrement",
               "Subtracts a value from a global variable.")
class DecrementNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_var"), "amount": PropSpec("amount", "number", 1)}
    inputs = [PinSpec("", EXEC), PinSpec("amount", NUMBER, default=1)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        name = self.prop_value(node, "name", "my_var")
        amt = self.input_expr(ctx, node, "amount") if ctx.find_input_link(node["id"], "amount") else repr(self.prop_value(node, "amount", 1))
        ctx.emit(f"_ns_variables[{repr(name)}] = _ns_variables.get({repr(name)}, 0) - ({amt})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("variable_toggle", "Variables", "Toggle Boolean",
               "Flips a global Boolean variable between True and False.")
class ToggleBooleanNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_flag")}
    inputs = [PinSpec("", EXEC)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        name = self.prop_value(node, "name", "my_flag")
        ctx.emit(f"_ns_variables[{repr(name)}] = not _ns_variables.get({repr(name)}, False)")
        ctx.generate_exec_branch(node["id"], "", visited)

# ---------- Loops ----------
@register_node("loop_for", "Loops", "For",
               "A standard counted For loop from Start to End, firing its body each iteration.")
class ForNode(NodeBase):
    properties = {"count": PropSpec("count", "number", 3, min_val=1, max_val=1000)}
    inputs = [PinSpec("", EXEC), PinSpec("count", NUMBER, default=3)]
    outputs = [PinSpec("", EXEC, tooltip="Loop body"), PinSpec("index", NUMBER), PinSpec("completed", EXEC)]
    def generate_code(self, ctx, node, visited):
        count = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(int(self.prop_value(node, "count", 3)))
        idx = ctx.fresh_var("i")
        ctx.emit(f"for {idx} in range(int({count})):")
        ctx.push_indent()
        ctx.expr_cache[(node["id"], "index")] = idx
        old_depth = ctx.loop_depth
        ctx.loop_depth += 1
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.loop_depth = old_depth
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "completed", visited)

@register_node("loop_for_each", "Loops", "For Each",
               "Iterates over a list of characters, firing the body once per item in the list.")
class ForEachNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("list", OBJECT, default=None)]
    outputs = [PinSpec("", EXEC, tooltip="Loop body"), PinSpec("item", OBJECT), PinSpec("index", NUMBER), PinSpec("completed", EXEC)]
    def generate_code(self, ctx, node, visited):
        lst = self.object_input_expr(ctx, node, "list", "[]")
        item = ctx.fresh_var("item")
        idx = ctx.fresh_var("idx")
        ctx.emit(f"for {idx}, {item} in enumerate({lst}):")
        ctx.push_indent()
        ctx.expr_cache[(node["id"], "item")] = item
        ctx.expr_cache[(node["id"], "index")] = idx
        old_depth = ctx.loop_depth
        ctx.loop_depth += 1
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.loop_depth = old_depth
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "completed", visited)

@register_node("loop_while", "Loops", "While",
               "A raw While loop -- will crash the game if the condition never becomes False. Use Repeat While instead.")
class WhileNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("condition", BOOLEAN, default=True)]
    outputs = [PinSpec("", EXEC, tooltip="Loop body"), PinSpec("completed", EXEC)]
    def generate_code(self, ctx, node, visited):
        cond = self.input_expr(ctx, node, "condition")
        ctx.emit(f"while {cond}:")
        ctx.push_indent()
        old_depth = ctx.loop_depth
        ctx.loop_depth += 1
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.loop_depth = old_depth
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "completed", visited)

@register_node("loop_break", "Loops", "Break",
               "Immediately aborts the enclosing loop.")
class BreakNode(NodeBase):
    inputs = [PinSpec("", EXEC)]
    outputs = []
    def generate_code(self, ctx, node, visited):
        if ctx.loop_depth > 0:
            ctx.emit("break")
        else:
            ctx.emit("# Break used outside of loop")

@register_node("loop_continue", "Loops", "Continue",
               "Skips the rest of this loop iteration and moves to the next one.")
class ContinueNode(NodeBase):
    inputs = [PinSpec("", EXEC)]
    outputs = []
    def generate_code(self, ctx, node, visited):
        if ctx.loop_depth > 0:
            ctx.emit("continue")
        else:
            ctx.emit("# Continue used outside of loop")

# ---------- Flow Control: Pass / Return / Disabled ----------

@register_node("flow_pass", "Utility", "Pass",
               "Does nothing and lets execution flow through unchanged. "
               "Use it as a placeholder to keep a chain of nodes wired up "
               "while you work on the logic — like a Python 'pass' statement.")
class PassNode(NodeBase):
    category = "Utility"
    inputs  = [PinSpec("", EXEC)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        ctx.emit("pass")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("flow_return", "Utility", "Return",
               "Immediately stops execution of this hook (like Python 'return'). "
               "Anything wired after this node is ignored. "
               "Great for early-exit conditions: 'If not valid -> Return'.")
class ReturnNode(NodeBase):
    category = "Utility"
    inputs  = [PinSpec("", EXEC)]
    outputs = []
    def generate_code(self, ctx, node, visited):
        ctx.emit("return")

@register_node("gameplay_phase_change", "Gameplay", "Set Phase",
               "Sets a numeric phase variable on a character and fires the on_phase_change event hook. "
               "Use to create classic boss phase transitions: Phase 1 → Phase 2 → Phase 3. "
               "Wire On Phase Change event to react to it.")
class PhaseChangeNode(NodeBase):
    properties = {"phase": PropSpec("phase", "number", 2, min_val=1, max_val=99)}
    inputs  = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None),
               PinSpec("phase", NUMBER, default=2)]
    outputs = [PinSpec("", EXEC), PinSpec("phase", NUMBER)]
    def generate_code(self, ctx, node, visited):
        t   = self.object_input_expr(ctx, node, "target", "me")
        ph  = self.input_expr(ctx, node, "phase") if ctx.find_input_link(node["id"], "phase") \
              else repr(int(self.prop_value(node, "phase", 2)))
        pv  = ctx.fresh_var("phase")
        ctx.expr_cache[(node["id"], "phase")] = pv
        ctx.emit(f"{pv} = int({ph})")
        ctx.emit(f"ctx.set_local_var({t}, 'phase', {pv})")
        ctx.emit(f"ctx.hook({t}, 'on_phase_change', ctx, {t}, {pv})")
        ctx.generate_exec_branch(node["id"], "", visited)

