# ── NEW MATH NODES ────────────────────────────────────────────────────────────
@register_node("math_map_range2", "Math", "Map Range", "Remaps a value from one range to another.")
class MathMapRangeNode(NodeBase):
    inputs = [PinSpec("Value", NUMBER), PinSpec("InMin", NUMBER), PinSpec("InMax", NUMBER, 1.0), PinSpec("OutMin", NUMBER), PinSpec("OutMax", NUMBER, 100.0)]
    outputs = [PinSpec("Result", NUMBER)]
    def generate_code(self, ctx, node, visited):
        v = ctx.generate_input(node, "Value", visited) or "0.0"
        imin = ctx.generate_input(node, "InMin", visited) or "0.0"
        imax = ctx.generate_input(node, "InMax", visited) or "1.0"
        omin = ctx.generate_input(node, "OutMin", visited) or "0.0"
        omax = ctx.generate_input(node, "OutMax", visited) or "100.0"
        ctx.set_local(node, "Result", f"({omin} + ({v} - {imin}) * ({omax} - {omin}) / ({imax} - {imin}) if {imax} != {imin} else {omin})")

@register_node("math_vector_length", "Math", "Vector Length", "Returns the magnitude of the vector.")
class MathVectorLengthNode(NodeBase):
    inputs = [PinSpec("Vector", VECTOR)]
    outputs = [PinSpec("Length", NUMBER)]
    def generate_code(self, ctx, node, visited):
        v = ctx.generate_input(node, "Vector", visited) or "(0,0)"
        ctx.set_local(node, "Length", f"pygame.Vector2({v}).length()")

@register_node("math_vector_normalize", "Math", "Normalize Vector", "Returns the vector with length 1.")
class MathVectorNormalizeNode(NodeBase):
    inputs = [PinSpec("Vector", VECTOR)]
    outputs = [PinSpec("Normal", VECTOR)]
    def generate_code(self, ctx, node, visited):
        v = ctx.generate_input(node, "Vector", visited) or "(0,0)"
        ctx.set_local(node, "Normal", f"(pygame.Vector2({v}).normalize() if pygame.Vector2({v}).length_squared() > 0 else pygame.Vector2(1, 0))")

@register_node("math_vector_dot", "Math", "Dot Product", "Returns the dot product of two vectors.")
class MathVectorDotNode(NodeBase):
    inputs = [PinSpec("A", VECTOR), PinSpec("B", VECTOR)]
    outputs = [PinSpec("Dot", NUMBER)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "A", visited) or "(0,0)"
        b = ctx.generate_input(node, "B", visited) or "(0,0)"
        ctx.set_local(node, "Dot", f"pygame.Vector2({a}).dot(pygame.Vector2({b}))")

# ── NEW PHYSICS/STATS NODES ───────────────────────────────────────────────────
@register_node("phys_set_max_speed", "Movement", "Set Max Speed", "Changes the character's base speed stat.")
class PhysSetMaxSpeedNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Character", OBJECT, "self"), PinSpec("Speed", NUMBER, 200.0)]
    outputs = [PinSpec("exec", EXEC)]
    def generate_code(self, ctx, node, visited):
        c = ctx.generate_input(node, "Character", visited) or "self"
        s = ctx.generate_input(node, "Speed", visited) or "200.0"
        ctx.emit(f"_t = ctx.resolve_character({c}, me)")
        ctx.emit(f"if _t: _t['speed'] = max(1, {s})")
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("phys_get_velocity_dir", "Movement", "Get Velocity Direction", "Returns the normalized direction of movement.")
class PhysGetVelocityDirNode(NodeBase):
    inputs = [PinSpec("Character", OBJECT, "self")]
    outputs = [PinSpec("Direction", VECTOR)]
    def generate_code(self, ctx, node, visited):
        c = ctx.generate_input(node, "Character", visited) or "self"
        ctx.emit(f"_t = ctx.resolve_character({c}, me)")
        ctx.emit("_v = _t['vel'] if _t else pygame.Vector2()")
        ctx.set_local(node, "Direction", "(_v.normalize() if _v.length_squared() > 0 else pygame.Vector2())")

@register_node("phys_teleport", "Movement", "Teleport", "Instantly moves a character to a position.")
class PhysTeleportNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Character", OBJECT, "self"), PinSpec("Position", VECTOR)]
    outputs = [PinSpec("exec", EXEC)]
