# ── NEW LIGHT NODES ───────────────────────────────────────────────────────────
@register_node("ext_create_light", "Scene", "Create Light Source", "Spawns an external node that emits light in the darkness.")
class ExtCreateLightNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Position", VECTOR), PinSpec("Color", COLOR, [255,255,255]), PinSpec("Radius", NUMBER, 200.0), PinSpec("Intensity", NUMBER, 1.0)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Light Node", OBJECT)]
    def generate_code(self, ctx, node, visited):
        pos = ctx.generate_input(node, "Position", visited) or "(0,0)"
        col = ctx.generate_input(node, "Color", visited) or "[255,255,255]"
        rad = ctx.generate_input(node, "Radius", visited) or "200.0"
        ins = ctx.generate_input(node, "Intensity", visited) or "1.0"
        ctx.emit(f"_p = pygame.Vector2({pos})")
        ctx.emit("_n = ctx.spawn_external_node('light_source', _p.x, _p.y)")
        ctx.emit(f"_n['color'] = list({col})[:3]")
        ctx.emit(f"_n['radius'] = {rad}")
        ctx.emit(f"_n['intensity'] = {ins}")
        ctx.set_local(node, "Light Node", "_n")
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("ext_set_light_props", "Scene", "Set Light Properties", "Modifies an existing Light Source external node.")
class ExtSetLightPropsNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Node", OBJECT), PinSpec("Radius", NUMBER, 200.0), PinSpec("Intensity", NUMBER, 1.0)]
    outputs = [PinSpec("exec", EXEC)]
    def generate_code(self, ctx, node, visited):
        nd = ctx.generate_input(node, "Node", visited) or "{}"
        rad = ctx.generate_input(node, "Radius", visited) or "200.0"
        ins = ctx.generate_input(node, "Intensity", visited) or "1.0"
        ctx.emit(f"if isinstance({nd}, dict) and {nd}.get('kind') == 'light_source':")
        ctx.emit(f"    {nd}['radius'] = {rad}")
        ctx.emit(f"    {nd}['intensity'] = {ins}")
        ctx.generate_exec_branch(node["id"], "exec", visited)

