# ── ELECTRONIC SYSTEMS: MEMORY & LATCHES ──────────────────────────────────────
@register_node("mem_sr_latch", "Electronics", "SR Latch", "Set-Reset Latch. Stores a boolean state.")
class MemSrLatchNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Set", BOOLEAN, False), PinSpec("Reset", BOOLEAN, False)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Q", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        s = ctx.generate_input(node, "Set", visited) or "False"
        r = ctx.generate_input(node, "Reset", visited) or "False"
        var = f"_ns_sr_latch_{node['id']}"
        ctx.emit_global(f"{var} = False")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {s}: {var} = True")
        ctx.emit(f"elif {r}: {var} = False")
        ctx.set_local(node, "Q", var)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("mem_d_latch", "Electronics", "D Latch", "Data Latch. Stores data when Enable is True.")
class MemDLatchNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Data", ANY, None), PinSpec("Enable", BOOLEAN, True)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Q", ANY)]
    def generate_code(self, ctx, node, visited):
        d = ctx.generate_input(node, "Data", visited) or "None"
        en = ctx.generate_input(node, "Enable", visited) or "True"
        var = f"_ns_d_latch_{node['id']}"
        ctx.emit_global(f"{var} = None")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {en}: {var} = {d}")
        ctx.set_local(node, "Q", var)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("mem_t_flipflop", "Electronics", "T Flip-Flop", "Toggle Flip-Flop. Flips state on execution if T is True.")
class MemTFlipFlopNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("T", BOOLEAN, True)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Q", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        t = ctx.generate_input(node, "T", visited) or "True"
        var = f"_ns_t_ff_{node['id']}"
        ctx.emit_global(f"{var} = False")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {t}: {var} = not {var}")
        ctx.set_local(node, "Q", var)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("mem_jk_flipflop", "Electronics", "JK Flip-Flop", "JK Flip-Flop state machine.")
class MemJkFlipFlopNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("J", BOOLEAN, False), PinSpec("K", BOOLEAN, False)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Q", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        j = ctx.generate_input(node, "J", visited) or "False"
        k = ctx.generate_input(node, "K", visited) or "False"
        var = f"_ns_jk_ff_{node['id']}"
        ctx.emit_global(f"{var} = False")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {j} and not {k}: {var} = True")
        ctx.emit(f"elif not {j} and {k}: {var} = False")
        ctx.emit(f"elif {j} and {k}: {var} = not {var}")
        ctx.set_local(node, "Q", var)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("mem_8bit_reg", "Electronics", "8-Bit Register", "Stores an 8-bit integer.")
class Mem8BitRegNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Data", NUMBER, 0), PinSpec("Load", BOOLEAN, True)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Out", NUMBER)]
    def generate_code(self, ctx, node, visited):
        d = ctx.generate_input(node, "Data", visited) or "0"
        l = ctx.generate_input(node, "Load", visited) or "True"
        var = f"_ns_8reg_{node['id']}"
        ctx.emit_global(f"{var} = 0")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {l}: {var} = int({d}) & 0xFF")
        ctx.set_local(node, "Out", var)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("mem_write", "Electronics", "Memory Write", "Writes a value to a global memory address.")
class MemWriteNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Address", STRING, "0x00"), PinSpec("Value", ANY, None)]
    outputs = [PinSpec("exec", EXEC)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "Address", visited) or "'0x00'"
        v = ctx.generate_input(node, "Value", visited) or "None"
        ctx.emit_global("_ns_global_memory = {}")
        ctx.emit("global _ns_global_memory")
        ctx.emit(f"_ns_global_memory[{a}] = {v}")
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("mem_read", "Electronics", "Memory Read", "Reads a value from a global memory address.")
class MemReadNode(NodeBase):
    inputs = [PinSpec("Address", STRING, "0x00")]
    outputs = [PinSpec("Value", ANY)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "Address", visited) or "'0x00'"
        ctx.emit_global("_ns_global_memory = {}")
        ctx.emit("global _ns_global_memory")
        ctx.set_local(node, "Value", f"_ns_global_memory.get({a})")

@register_node("mem_clear", "Electronics", "Clear Memory", "Wipes the entire global memory dictionary.")
class MemClearNode(NodeBase):
    inputs = [PinSpec("exec", EXEC)]
    outputs = [PinSpec("exec", EXEC)]
    def generate_code(self, ctx, node, visited):
        ctx.emit_global("_ns_global_memory = {}")
        ctx.emit("global _ns_global_memory")
        ctx.emit("_ns_global_memory.clear()")
        ctx.generate_exec_branch(node["id"], "exec", visited)

# ── ELECTRONIC SYSTEMS: CPUS & CLOCKS ─────────────────────────────────────────
@register_node("cpu_clock_gen", "Electronics", "Clock Generator", "Outputs a repeating clock signal boolean over time.")
class CpuClockGenNode(NodeBase):
    inputs = [PinSpec("Frequency", NUMBER, 1.0)]
    outputs = [PinSpec("Tick", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        f = ctx.generate_input(node, "Frequency", visited) or "1.0"
        ctx.set_local(node, "Tick", f"(int((pygame.time.get_ticks()/1000.0) * {f}) % 2 == 0)")

@register_node("cpu_prog_counter", "Electronics", "Program Counter", "Increments a counter on execution, resettable.")
class CpuProgCounterNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Reset", BOOLEAN, False)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Count", NUMBER)]
    def generate_code(self, ctx, node, visited):
        r = ctx.generate_input(node, "Reset", visited) or "False"
        var = f"_ns_pc_{node['id']}"
        ctx.emit_global(f"{var} = 0")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {r}: {var} = 0")
        ctx.emit(f"else: {var} += 1")
        ctx.set_local(node, "Count", var)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("cpu_alu_add", "Electronics", "ALU Add", "Simulates ALU addition with overflow check.")
class CpuAluAddNode(NodeBase):
    inputs = [PinSpec("A", NUMBER, 0), PinSpec("B", NUMBER, 0)]
    outputs = [PinSpec("Sum", NUMBER), PinSpec("Overflow", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "A", visited) or "0"
        b = ctx.generate_input(node, "B", visited) or "0"
        ctx.emit(f"_alu_sum_{node['id']} = int({a}) + int({b})")
        ctx.set_local(node, "Sum", f"(_alu_sum_{node['id']} & 0xFF)")
        ctx.set_local(node, "Overflow", f"(_alu_sum_{node['id']} > 255)")

@register_node("cpu_alu_sub", "Electronics", "ALU Sub", "Simulates ALU subtraction with underflow flag.")
class CpuAluSubNode(NodeBase):
    inputs = [PinSpec("A", NUMBER, 0), PinSpec("B", NUMBER, 0)]
    outputs = [PinSpec("Diff", NUMBER), PinSpec("Underflow", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "A", visited) or "0"
        b = ctx.generate_input(node, "B", visited) or "0"
        ctx.emit(f"_alu_diff_{node['id']} = int({a}) - int({b})")
        ctx.set_local(node, "Diff", f"(_alu_diff_{node['id']} & 0xFF)")
        ctx.set_local(node, "Underflow", f"(_alu_diff_{node['id']} < 0)")

@register_node("cpu_alu_mul", "Electronics", "ALU Multiply", "Simulates ALU multiplication.")
class CpuAluMulNode(NodeBase):
    inputs = [PinSpec("A", NUMBER, 0), PinSpec("B", NUMBER, 0)]
    outputs = [PinSpec("Prod", NUMBER), PinSpec("Overflow", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "A", visited) or "0"
        b = ctx.generate_input(node, "B", visited) or "0"
        ctx.emit(f"_alu_mul_{node['id']} = int({a}) * int({b})")
        ctx.set_local(node, "Prod", f"(_alu_mul_{node['id']} & 0xFFFF)")
        ctx.set_local(node, "Overflow", f"(_alu_mul_{node['id']} > 65535)")

@register_node("cpu_alu_div", "Electronics", "ALU Divide", "Simulates ALU division, handles Div0.")
class CpuAluDivNode(NodeBase):
    inputs = [PinSpec("A", NUMBER, 0), PinSpec("B", NUMBER, 1)]
    outputs = [PinSpec("Quot", NUMBER), PinSpec("DivZero", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "A", visited) or "0"
        b = ctx.generate_input(node, "B", visited) or "1"
        ctx.emit(f"_alu_b_{node['id']} = int({b})")
        ctx.emit(f"_alu_divz_{node['id']} = (_alu_b_{node['id']} == 0)")
        ctx.set_local(node, "Quot", f"(0 if _alu_divz_{node['id']} else int({a}) // _alu_b_{node['id']})")
        ctx.set_local(node, "DivZero", f"_alu_divz_{node['id']}")

@register_node("cpu_inst_dec", "Electronics", "Instruction Decoder", "Decodes an opcode into execution branches.")
class CpuInstDecNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Opcode", NUMBER, 0)]
    outputs = [PinSpec("Op 0", EXEC), PinSpec("Op 1", EXEC), PinSpec("Op 2", EXEC), PinSpec("Op 3", EXEC)]
    def generate_code(self, ctx, node, visited):
        op = ctx.generate_input(node, "Opcode", visited) or "0"
        ctx.emit(f"_op_{node['id']} = int({op}) % 4")
        ctx.emit(f"if _op_{node['id']} == 0:")
        ctx.generate_exec_branch(node["id"], "Op 0", visited)
        ctx.emit(f"elif _op_{node['id']} == 1:")
        ctx.generate_exec_branch(node["id"], "Op 1", visited)
        ctx.emit(f"elif _op_{node['id']} == 2:")
        ctx.generate_exec_branch(node["id"], "Op 2", visited)
        ctx.emit(f"elif _op_{node['id']} == 3:")
        ctx.generate_exec_branch(node["id"], "Op 3", visited)

@register_node("cpu_tick", "Electronics", "CPU Tick", "Fires every X milliseconds exactly.")
class CpuTickNode(NodeBase):
    inputs = []
    outputs = [PinSpec("exec", EXEC)]
    properties = {"ms": PropSpec("ms", "number", 100.0, min_val=1.0, max_val=1000.0)}
    def generate_code(self, ctx, node, visited):
        ms = node.get("properties", {}).get("ms", 100.0)
        var = f"_ns_cputick_{node['id']}"
        ctx.emit_global(f"{var} = 0")
        ctx.emit(f"global {var}")
        ctx.emit("_now = pygame.time.get_ticks()")
        ctx.emit(f"if _now - {var} >= {ms}:")
        ctx.emit(f"    {var} = _now")
        ctx.generate_exec_branch(node["id"], "exec", visited)

