@register_node("sys_watchdog", "Electronics", "Watchdog Timer", "If not fed for 5s, triggers Reset.")
class SysWatchdogNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Feed", BOOLEAN, False)]
    outputs = [PinSpec("Normal", EXEC), PinSpec("Reset", EXEC)]
    def generate_code(self, ctx, node, visited):
        f = ctx.generate_input(node, "Feed", visited) or "False"
        var = f"_ns_wd_{node['id']}"
        ctx.emit_global(f"{var} = 0")
        ctx.emit(f"global {var}")
        ctx.emit(f"if {f}: {var} = pygame.time.get_ticks()")
        ctx.emit(f"if pygame.time.get_ticks() - {var} > 5000:")
        ctx.generate_exec_branch(node["id"], "Reset", visited)
        ctx.emit("else:")
        ctx.generate_exec_branch(node["id"], "Normal", visited)

