# ── ELECTRONIC SYSTEMS: ADVANCED COMPONENTS ───────────────────────────────────
@register_node("adv_pid", "Electronics", "PID Controller", "Classic Proportional-Integral-Derivative controller.")
class AdvPidNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Error", NUMBER, 0.0), PinSpec("P", NUMBER, 1.0), PinSpec("I", NUMBER, 0.1), PinSpec("D", NUMBER, 0.01)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Correction", NUMBER)]
    def generate_code(self, ctx, node, visited):
        e = ctx.generate_input(node, "Error", visited) or "0.0"
        p = ctx.generate_input(node, "P", visited) or "1.0"
        i = ctx.generate_input(node, "I", visited) or "0.1"
        d = ctx.generate_input(node, "D", visited) or "0.01"
        vp = f"_ns_pid_prev_{node['id']}"
        vi = f"_ns_pid_int_{node['id']}"
        ctx.emit_global(f"{vp} = 0.0")
        ctx.emit_global(f"{vi} = 0.0")
        ctx.emit(f"global {vp}, {vi}")
        ctx.emit(f"{vi} += {e}")
        ctx.emit(f"_deriv = {e} - {vp}")
        ctx.emit(f"{vp} = {e}")
        ctx.emit(f"_corr = ({p} * {e}) + ({i} * {vi}) + ({d} * _deriv)")
        ctx.set_local(node, "Correction", "_corr")
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("adv_kalman", "Electronics", "Kalman Filter", "Simplified 1D Kalman filter for noise reduction.")
class AdvKalmanNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Measurement", NUMBER, 0.0), PinSpec("Noise", NUMBER, 1.0)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Estimate", NUMBER)]
    def generate_code(self, ctx, node, visited):
        m = ctx.generate_input(node, "Measurement", visited) or "0.0"
        n = ctx.generate_input(node, "Noise", visited) or "1.0"
        vest = f"_ns_kal_est_{node['id']}"
        verr = f"_ns_kal_err_{node['id']}"
        ctx.emit_global(f"{vest} = 0.0")
        ctx.emit_global(f"{verr} = 1.0")
        ctx.emit(f"global {vest}, {verr}")
        ctx.emit(f"_kg = {verr} / ({verr} + {n})")
        ctx.emit(f"{vest} = {vest} + _kg * ({m} - {vest})")
        ctx.emit(f"{verr} = (1.0 - _kg) * {verr}")
        ctx.set_local(node, "Estimate", vest)
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("adv_gyro", "Electronics", "Gyroscope", "Simulates angular velocity based on rotation changes.")
class AdvGyroNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Angle", NUMBER, 0.0)]
    outputs = [PinSpec("exec", EXEC), PinSpec("Ang Vel", NUMBER)]
    def generate_code(self, ctx, node, visited):
        a = ctx.generate_input(node, "Angle", visited) or "0.0"
        var = f"_ns_gyro_{node['id']}"
        ctx.emit_global(f"{var} = 0.0")
        ctx.emit(f"global {var}")
        ctx.emit(f"_avel = {a} - {var}")
        ctx.emit(f"{var} = {a}")
        ctx.set_local(node, "Ang Vel", "_avel")
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("adv_accel", "Electronics", "Accelerometer", "Simulates acceleration based on velocity changes.")
class AdvAccelNode(NodeBase):
    inputs = [PinSpec("exec", EXEC), PinSpec("Character", OBJECT, "self")]
    outputs = [PinSpec("exec", EXEC), PinSpec("Accel", VECTOR)]
    def generate_code(self, ctx, node, visited):
        c = ctx.generate_input(node, "Character", visited) or "self"
        var = f"_ns_accel_{node['id']}"
        ctx.emit_global(f"{var} = pygame.Vector2()")
        ctx.emit(f"global {var}")
        ctx.emit(f"_t = ctx.resolve_character({c}, me)")
        ctx.emit("if _t:")
        ctx.emit(f"    _ac = _t['vel'] - {var}")
        ctx.emit(f"    {var} = pygame.Vector2(_t['vel'])")
        ctx.emit("else: _ac = pygame.Vector2()")
        ctx.set_local(node, "Accel", "_ac")
        ctx.generate_exec_branch(node["id"], "exec", visited)

@register_node("adv_magneto", "Electronics", "Magnetometer", "Returns a vector pointing to 0,0.")
class AdvMagnetoNode(NodeBase):
    inputs = [PinSpec("Character", OBJECT, "self")]
