@register_node("adv_quat", "Electronics", "Quaternion Rotor", "Simulates complex 2D rotation via matrices.")
class AdvQuatNode(NodeBase):
    inputs = [PinSpec("Vector", VECTOR), PinSpec("CosA", NUMBER, 1.0), PinSpec("SinA", NUMBER, 0.0)]
    outputs = [PinSpec("Rotated", VECTOR)]
    def generate_code(self, ctx, node, visited):
        v = ctx.generate_input(node, "Vector", visited) or "(0,0)"
        c = ctx.generate_input(node, "CosA", visited) or "1.0"
        s = ctx.generate_input(node, "SinA", visited) or "0.0"
        ctx.emit(f"_v = pygame.Vector2({v})")
        ctx.emit(f"_nx = _v.x * {c} - _v.y * {s}")
        ctx.emit(f"_ny = _v.x * {s} + _v.y * {c}")
        ctx.set_local(node, "Rotated", "pygame.Vector2(_nx, _ny)")

@register_node("adv_matrix", "Electronics", "Matrix Multiply", "Simulates 2x2 matrix multiplication with a vector.")
class AdvMatrixNode(NodeBase):
    inputs = [PinSpec("Vector", VECTOR), PinSpec("M00", NUMBER, 1), PinSpec("M01", NUMBER, 0), PinSpec("M10", NUMBER, 0), PinSpec("M11", NUMBER, 1)]
    outputs = [PinSpec("Result", VECTOR)]
    def generate_code(self, ctx, node, visited):
        v = ctx.generate_input(node, "Vector", visited) or "(0,0)"
        m00 = ctx.generate_input(node, "M00", visited) or "1"
        m01 = ctx.generate_input(node, "M01", visited) or "0"
        m10 = ctx.generate_input(node, "M10", visited) or "0"
        m11 = ctx.generate_input(node, "M11", visited) or "1"
        ctx.emit(f"_v = pygame.Vector2({v})")
        ctx.set_local(node, "Result", f"pygame.Vector2(_v.x * {m00} + _v.y * {m01}, _v.x * {m10} + _v.y * {m11})")

@register_node("ext_get_node", "Scene", "Get External Node",
               "Finds an external scene node by its numeric ID or by name. "
               "Returns the node object so other nodes can modify it.")
class ExtGetNodeNode(NodeBase):
    properties = {"node_id": PropSpec("node_id", "number", 1, min_val=1, max_val=9999),
                  "by_name": PropSpec("by_name", "string", "")}
    inputs  = [PinSpec("node_id", NUMBER, default=1), PinSpec("name", STRING, default="")]
    outputs = [PinSpec("node", OBJECT), PinSpec("found", BOOLEAN)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        if output_name == "found":
            if ctx.find_input_link(node["id"], "name"):
                n = self.input_expr(ctx, node, "name")
                return f"(ctx.get_ext_node_by_name({n}) is not None)"
            nid = self.input_expr(ctx, node, "node_id") if ctx.find_input_link(node["id"], "node_id") \
                  else repr(int(self.prop_value(node, "node_id", 1)))
            return f"(ctx.get_ext_node({nid}) is not None)"
        if ctx.find_input_link(node["id"], "name"):
            n = self.input_expr(ctx, node, "name")
            return f"ctx.get_ext_node_by_name({n})"
        nid = self.input_expr(ctx, node, "node_id") if ctx.find_input_link(node["id"], "node_id") \
              else repr(int(self.prop_value(node, "node_id", 1)))
        return f"ctx.get_ext_node({nid})"

@register_node("ext_set_text", "Scene", "Set Node Text",
               "Sets the text of an external Text Label or Counter node. "
               "Wire a Format String or any string value directly in.")
class ExtSetTextNode(NodeBase):
    properties = {"node_id": PropSpec("node_id", "number", 1, min_val=1, max_val=9999)}
    inputs  = [PinSpec("", EXEC), PinSpec("node", OBJECT, default=None),
               PinSpec("text", STRING, default="")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        n = self.object_input_expr(ctx, node, "node", "None")
        t = self.input_expr(ctx, node, "text") if ctx.find_input_link(node["id"], "text") else '""'
        if ctx.find_input_link(node["id"], "node"):
            ctx.emit(f"_snt = {n}")
            ctx.emit(f"if isinstance(_snt, list): _snt = next((x for x in _snt if isinstance(x, dict)), None)")
            ctx.emit(f"if _snt: _snt['text'] = str({t})")
        else:
            nid = repr(int(self.prop_value(node, "node_id", 1)))
            ctx.emit(f"ctx.set_ext_text({nid}, {t})")
        ctx.generate_exec_branch(node["id"], "", visited)

