@register_node("ext_create_node", "Scene", "Create External Node",
               "Dynamically create an external node at runtime from a script. "
               "Kinds: text_label · rect_box · progress_bar · counter · grid")
class ExtCreateNodeNode(NodeBase):
    properties = {"kind": PropSpec("kind", "dropdown", "text_label",
                                   options=["text_label","rect_box","progress_bar","custom_progress_bar","counter","grid"])}
    inputs  = [PinSpec("", EXEC), PinSpec("position", VECTOR, default=None)]
    outputs = [PinSpec("", EXEC), PinSpec("node", OBJECT)]
    def generate_code(self, ctx, node, visited):
        kind = repr(self.prop_value(node, "kind", "text_label"))
        pos  = self.input_expr(ctx, node, "position") if ctx.find_input_link(node["id"], "position") \
               else "pygame.Vector2(0,0)"
        v    = ctx.fresh_var("ext_node")
        ctx.expr_cache[(node["id"], "node")] = v
        ctx.emit(f"_ecpos = pygame.Vector2({pos})")
        ctx.emit(f"{v} = ctx.create_ext_node({kind}, _ecpos.x, _ecpos.y)")
        ctx.generate_exec_branch(node["id"], "", visited)

