@register_node("ext_find_tag", "Scene", "Find By Tag",
               "Return all external nodes that carry a specific tag. "
               "Wire the tag from a Constant String or Format String. "
               "Use Get First for a single result. Enable 'Include Hidden' to "
               "still find nodes that currently have Visible=False — needed if "
               "you're e.g. zeroing out a bar's value after it's been hidden.")
class ExtFindTagNode(NodeBase):
    properties = {"tag": PropSpec("tag", "string", "my_tag"),
                  "include_hidden": PropSpec("include_hidden", "boolean", False)}
    inputs  = [PinSpec("tag", STRING, default="my_tag")]
    outputs = [PinSpec("nodes", ANY, tooltip="List of matching external nodes"),
               PinSpec("first", OBJECT, tooltip="First matching node, or None"),
               PinSpec("count", NUMBER)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        t = self.input_expr(ctx, node, "tag") if ctx.find_input_link(node["id"], "tag") \
            else repr(self.prop_value(node, "tag", "my_tag"))
        ih = repr(bool(self.prop_value(node, "include_hidden", False)))
        if output_name == "nodes":  return f"ctx.en_find_tag({t}, {ih})"
        if output_name == "first":  return f"ctx.en_find_tag_first({t}, {ih})"
        if output_name == "count":  return f"len(ctx.en_find_tag({t}, {ih}))"
        return "None"

@register_node("ext_add_tag", "Scene", "Add Tag",
               "Add a tag to an external node so it can be found by Find By Tag.")
class ExtAddTagNode(NodeBase):
    properties = {"tag": PropSpec("tag", "string", "my_tag"),
                  "node_id": PropSpec("node_id", "number", 1)}
    inputs  = [PinSpec("", EXEC), PinSpec("node", OBJECT, default=None),
               PinSpec("tag", STRING, default="my_tag")]
