@register_node("sprite_queue_state", "Sprite", "Queue Sprite State",
               "Append a sprite/duration pair to a per-character sprite queue for scripts/controllers to consume.")
class QueueSpriteStateNode(NodeBase):
    properties = {"state": PropSpec("state", "string", "idle"),
                  "duration": PropSpec("duration", "number", 0.0, min_val=0.0, max_val=600.0)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None),
              PinSpec("state", STRING, default="idle"), PinSpec("duration", NUMBER, default=0.0)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        target = self.object_input_expr(ctx, node, "target", "me")
