        dur = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 0.0))
        ctx.emit(f"({target}).setdefault('sprite_queue', []).append(({state}, float({dur})))")
