@register_node("animation_random_state", "Animation", "Random Animation State",
               "Pure node: choose one state from a comma-separated list.")
class RandomAnimationStateNode(NodeBase):
    properties = {"states": PropSpec("states", "string", "idle,attack,hit")}
    inputs = [PinSpec("states", STRING, default="")]; outputs = [PinSpec("state", STRING)]; pure = True
    def generate_output_expr(self, ctx, node, output_name):
        states_expr = self.input_expr(ctx,node,"states") if ctx.find_input_link(node["id"],"states") else repr(self.prop_value(node,"states","idle,attack,hit"))
        return f"(random.choice([s.strip() for s in str({states_expr}).split(',') if s.strip()] or ['idle']))"

@register_node("animation_state_equals", "Animation", "Animation State Equals",
               "Pure condition: test the character's current visual_state.")
class AnimationStateEqualsNode(NodeBase):
    properties = {"state": PropSpec("state", "animation", "idle")}
    inputs = [PinSpec("target", OBJECT, default=None), PinSpec("state", STRING, default="idle")]; outputs = [PinSpec("result", BOOLEAN)]; pure = True
    def generate_output_expr(self, ctx, node, output_name):
        target = self.object_input_expr(ctx, node, "target", "me")
        state = self.input_expr(ctx,node,"state") if ctx.find_input_link(node["id"],"state") else repr(self.prop_value(node,"state","idle"))
        return f"(({target}).get('visual_state','idle') == {state})"

@register_node("animation_flip_from_direction", "Animation", "Flip Sprite From Direction",
               "Set flip_x based on a direction vector's X component.")
class FlipSpriteFromDirectionNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("direction", VECTOR, default=None)]; outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        target = self.object_input_expr(ctx, node, "target", "me")
        direction = self.input_expr(ctx,node,"direction") if ctx.find_input_link(node["id"],"direction") else f"({target}).get('vel', pygame.Vector2(1,0))"
        ctx.emit(f"({target})['flip_x'] = (pygame.Vector2({direction}).x < 0)")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("animation_face_target_vertical_flip", "Animation", "Face Target Vertically By Flip",
               "Vertical counterpart to Face Target By Flip. Set the actor's artwork orientation explicitly: choose South if the unflipped sprite faces down, or North if it faces up. Only flip_y changes; horizontal/cardinal direction is ignored.")
class FaceTargetVerticallyByFlipNode(NodeBase):
    properties = {
        "default_facing": PropSpec("default_facing", "dropdown", "south", options=["south", "north"]),
        "deadzone": PropSpec("deadzone", "number", 10, min_val=0),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who flips vertically (default: Self)"),
              PinSpec("target", OBJECT, default=None, tooltip="Who the actor faces")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor=self.object_input_expr(ctx,node,"actor","me")
        target=self.object_input_expr(ctx,node,"target","locals().get('other') or me")
        is_south=str(self.prop_value(node,"default_facing","south")).lower()!="north"
        a=ctx.fresh_var("face_vertical_actor");t=ctx.fresh_var("face_vertical_target");d=ctx.fresh_var("face_vertical_delta");w=ctx.fresh_var("face_vertical_want")
        ctx.emit(f"{a}={actor};{t}={target}")
        ctx.emit(f"if isinstance({a},dict) and isinstance({t},dict) and {a} is not {t}:")
        ctx.push_indent()
        ctx.emit(f"{d}=pygame.Vector2({t}.get('pos',(0,0)))-pygame.Vector2({a}.get('pos',(0,0)));")
        # Dead simple, always live, no deadzone/hysteresis: target above (d.y<0)
        # -> flip; target at/below (d.y>=0) -> back to the default artwork.
        # Re-evaluated and written every single call, so it can never get stuck.
        ctx.emit(f"{w}=(float({d}.y) < 0) == {is_south!r}")
        ctx.emit(f"{a}['flip_y']={w}")
        ctx.emit(f"{a}['_vertical_face_lock']=True; {a}['_vertical_face_flip_y']={w}")
        ctx.pop_indent();ctx.generate_exec_branch(node["id"],"",visited)

@register_node("animation_face_target_by_flip", "Animation", "Face Target By Flip",
               "Flip a sprite so it faces a target based on which side of the actor the target is on. Horizontal flip can use a Cardinal Direction node for the sprite's natural facing.")
class FaceTargetByFlipNode(NodeBase):
    properties = {
        "flip_horizontal": PropSpec("flip_horizontal", "boolean", True),
        "vertical_mode": PropSpec("vertical_mode", "dropdown", "off", options=["off", "north", "south"]),
        "deadzone": PropSpec("deadzone", "number", 0),
        "default_facing": PropSpec("default_facing", "dropdown", "east", options=["east / right", "west / left"]),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("actor", OBJECT, default=None),
        PinSpec("target", OBJECT, default=None),
        PinSpec("default_direction", VECTOR, default=None),
    ]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        # Safe default: locals().get('other') returns None (not NameError) in
        # on_tick where 'other' is never defined. Fall back to me only when
        # the pin is unwired AND no event other is present.
        target = self.object_input_expr(ctx, node, "target", "locals().get('other') or me")
        default_direction = self.input_expr(ctx, node, "default_direction") if ctx.find_input_link(node["id"], "default_direction") else ("pygame.Vector2(-1,0)" if "west" in str(self.prop_value(node,"default_facing","east")).lower() else "pygame.Vector2(1,0)")
        flip_horizontal = bool(self.prop_value(node, "flip_horizontal", True))
        vertical_mode = str(self.prop_value(node, "vertical_mode", "off"))
        deadzone = float(self.prop_value(node, "deadzone", 0) or 0)
        _actor = ctx.fresh_var("face_actor")
        _target = ctx.fresh_var("face_target")
        _default = ctx.fresh_var("face_default")
        _delta = ctx.fresh_var("face_delta")
        _base_x = ctx.fresh_var("face_base_x")
        # Pre-assign all fresh_vars to None so they are always bound even when
        # the isinstance guard is False. Without this, Python raises
        # UnboundLocalError when any downstream node references these names
        # (e.g. in on_tick where 'other' is never in scope).
        ctx.emit(f"{_actor} = None; {_target} = None; {_delta} = None; {_base_x} = None")
        ctx.emit(f"{_actor} = {actor}")
        ctx.emit(f"{_target} = {target}")
        ctx.emit(f"if isinstance({_actor}, dict) and isinstance({_target}, dict):")
        ctx.push_indent()
        ctx.emit(f"{_default} = pygame.Vector2({default_direction})")
        ctx.emit(f"if {_default}.length_squared() == 0: {_default} = pygame.Vector2(1,0)")
        ctx.emit(f"{_delta} = pygame.Vector2({_target}.get('pos', (0,0))) - pygame.Vector2({_actor}.get('pos', (0,0)))")
        if flip_horizontal:
            ctx.emit(f"{_base_x} = (-1.0 if {_default}.x < 0 else 1.0)")
            ctx.emit(f"if abs({_delta}.x) > {deadzone!r}: {_actor}['flip_x'] = ({_delta}.x * {_base_x} < 0)")
        if vertical_mode in ("north", "south"):
            _is_south = (vertical_mode == "south")
            _dz = abs(deadzone)
            _want_y = ctx.fresh_var("face_vertical_want")
            # Same hysteresis fix as Face Target Vertically By Flip: only
            # re-evaluate outside the deadzone band, and only write flip_y
            # when the desired state actually changes, so jitter around
            # delta.y == 0 can't make the sprite flip every frame.
            ctx.emit(f"{_want_y}=None")
            ctx.emit(f"if {_delta}.y > {_dz!r}: {_want_y} = (not {_is_south!r})")
            ctx.emit(f"elif {_delta}.y < -{_dz!r}: {_want_y} = bool({_is_south!r})")
            ctx.emit(f"if {_want_y} is not None and bool({_actor}.get('flip_y',False)) != {_want_y}: {_actor}['flip_y'] = {_want_y}")
            ctx.emit(f"if {_want_y} is not None: {_actor}['_vertical_face_lock']=True; {_actor}['_vertical_face_flip_y']=bool({_actor}.get('flip_y',False))")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("animation_flip_to_direction", "Animation", "Flip Character To Direction",
               "Directly set the actor's flip_x/flip_y to face a chosen cardinal direction (North/South/East/West). Not target-based — you pick the direction outright. Tell it which way the unflipped artwork already faces (default facing), and it works out whether a flip is needed.")
class FlipCharacterToDirectionNode(NodeBase):
    properties = {
        "direction": PropSpec("direction", "dropdown", "north", options=["north", "south", "east", "west"]),
        "default_vertical": PropSpec("default_vertical", "dropdown", "south", options=["south", "north"]),
        "default_horizontal": PropSpec("default_horizontal", "dropdown", "east", options=["east", "west"]),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who to flip (default: Self)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        direction = str(self.prop_value(node, "direction", "north")).lower()
        is_default_south = str(self.prop_value(node, "default_vertical", "south")).lower() != "north"
        is_default_east = str(self.prop_value(node, "default_horizontal", "east")).lower() != "west"
        a = ctx.fresh_var("flip_dir_actor")
        ctx.emit(f"{a}={actor}")
        ctx.emit(f"if isinstance({a},dict):")
        ctx.push_indent()
        if direction in ("north", "south"):
            # Facing north needs a flip only if the unflipped art already faces south, and vice versa.
            want_flip_y = (direction == "north") == is_default_south
            ctx.emit(f"{a}['flip_y']={want_flip_y!r}")
            ctx.emit(f"{a}['_vertical_face_lock']=True; {a}['_vertical_face_flip_y']={want_flip_y!r}")
        else:
            # Facing west needs a flip only if the unflipped art already faces east, and vice versa.
            want_flip_x = (direction == "west") == is_default_east
            ctx.emit(f"{a}['flip_x']={want_flip_x!r}")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_track_target", "AI Movement", "AI: Track Target (Homing)", "Straight homing: velocity always points directly at the target's current position, full speed. Naturally curves while the target moves.")
class AiMv_MoveTrackTarget(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 220, min_val=0),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)"), PinSpec("target", OBJECT, default=None, tooltip="Who/what to react to (default: nearest enemy)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        target = self.object_input_expr(ctx, node, "target", "locals().get('other') or me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        t = ctx.fresh_var('ai_target')
        ctx.emit(f"{t}={target}")
        ctx.emit(f"if isinstance({a},dict) and isinstance({t},dict) and {a} is not {t}:")
        ctx.push_indent()
        ctx.emit(f"_d=pygame.Vector2({t}.get('pos',(0,0)))-pygame.Vector2({a}.get('pos',(0,0)))")
        ctx.emit(f"{a}['vel']=_d.normalize()*{self.prop_value(node,'speed',220)!r} if _d.length_squared()>4 else pygame.Vector2(0,0)")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_curved_homing", "AI Movement", "AI: Curved Homing (Turn-Limited)", "Missile-style pursuit: velocity rotates toward the target at a limited turn rate instead of snapping, producing a smooth curved chase.")
class AiMv_MoveCurvedHoming(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 220, min_val=0),
        "turn_rate": PropSpec("turn_rate", "number", 180, min_val=1, tooltip="Max degrees/second the heading can turn"),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)"), PinSpec("target", OBJECT, default=None, tooltip="Who/what to react to (default: nearest enemy)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        target = self.object_input_expr(ctx, node, "target", "locals().get('other') or me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        t = ctx.fresh_var('ai_target')
        ctx.emit(f"{t}={target}")
        ctx.emit(f"if isinstance({a},dict) and isinstance({t},dict) and {a} is not {t}:")
        ctx.push_indent()
        _spd=self.prop_value(node,"speed",220);_tr=self.prop_value(node,"turn_rate",180)
        ctx.emit(f"_dt=max(0.001,locals().get('dt',1/60))")
        ctx.emit(f"_d=pygame.Vector2({t}.get('pos',(0,0)))-pygame.Vector2({a}.get('pos',(0,0)))")
        ctx.emit(f"if _d.length_squared()>4:")
        ctx.push_indent()
        ctx.emit(f"_desired=_d.normalize()")
        ctx.emit(f"_cur={a}.get('_ai_heading')")
        ctx.emit(f"_cur=_cur if isinstance(_cur,pygame.Vector2) and _cur.length_squared()>1e-6 else pygame.Vector2(_desired)")
        ctx.emit(f"_diff=((_cur.angle_to(_desired)+180)%360)-180")
        ctx.emit(f"_step=max(-{_tr!r}*_dt,min({_tr!r}*_dt,_diff))")
        ctx.emit(f"_nh=_cur.rotate(_step)")
        ctx.emit(f"{a}['_ai_heading']=_nh;{a}['vel']=_nh.normalize()*{_spd!r}")
        ctx.pop_indent()
        ctx.emit(f"else: {a}['vel']=pygame.Vector2(0,0)")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_predictive_intercept", "AI Movement", "AI: Predictive Intercept (Lead Target)", "Aims ahead of a moving target using its current velocity and a lead time, so the actor intercepts rather than chases from behind.")
class AiMv_MovePredictiveIntercept(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 240, min_val=0),
        "lead_time": PropSpec("lead_time", "number", 0.5, min_val=0),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)"), PinSpec("target", OBJECT, default=None, tooltip="Who/what to react to (default: nearest enemy)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        target = self.object_input_expr(ctx, node, "target", "locals().get('other') or me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        t = ctx.fresh_var('ai_target')
        ctx.emit(f"{t}={target}")
        ctx.emit(f"if isinstance({a},dict) and isinstance({t},dict) and {a} is not {t}:")
        ctx.push_indent()
        ctx.emit(f"_lead=pygame.Vector2({t}.get('pos',(0,0)))+pygame.Vector2({t}.get('vel',(0,0)))*"+repr(self.prop_value(node,"lead_time",0.5)))
        ctx.emit(f"_d=_lead-pygame.Vector2({a}.get('pos',(0,0)))")
        ctx.emit(f"{a}['vel']=_d.normalize()*"+repr(self.prop_value(node,"speed",240))+" if _d.length_squared()>4 else pygame.Vector2(0,0)")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_orbit_target", "AI Movement", "AI: Orbit Target (Circle Strafe)", "Circles the target at a set radius, self-correcting distance, for a naturally curved strafing motion.")
class AiMv_MoveOrbitTarget(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 180, min_val=0),
        "radius": PropSpec("radius", "number", 160, min_val=1),
        "clockwise": PropSpec("clockwise", "bool", True),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)"), PinSpec("target", OBJECT, default=None, tooltip="Who/what to react to (default: nearest enemy)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        target = self.object_input_expr(ctx, node, "target", "locals().get('other') or me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        t = ctx.fresh_var('ai_target')
        ctx.emit(f"{t}={target}")
        ctx.emit(f"if isinstance({a},dict) and isinstance({t},dict) and {a} is not {t}:")
        ctx.push_indent()
        _spd=self.prop_value(node,"speed",180);_rad=self.prop_value(node,"radius",160);_cw=bool(self.prop_value(node,"clockwise",True))
        ctx.emit(f"_to=pygame.Vector2({t}.get('pos',(0,0)))-pygame.Vector2({a}.get('pos',(0,0)))")
        ctx.emit(f"_dist=_to.length()")
        ctx.emit(f"if _dist>1:")
        ctx.push_indent()
        ctx.emit(f"_tan=_to.normalize().rotate("+("90" if _cw else "-90")+")")
        ctx.emit(f"_rad_corr=_to.normalize()*(_dist-{_rad!r})*2.0")
        ctx.emit(f"{a}['vel']=_tan*{_spd!r}+_rad_corr")
        ctx.pop_indent()
        ctx.emit(f"else: {a}['vel']=pygame.Vector2(0,0)")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_wander", "AI Movement", "AI: Wander (Random Curved Drift)", "No target needed - drifts in a slowly, randomly curving direction. Good for idle/ambient roaming.")
class AiMv_MoveWander(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 140, min_val=0),
        "turn_jitter": PropSpec("turn_jitter", "number", 60, min_val=0, tooltip="Max random degrees/second of heading drift"),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        ctx.emit(f"if isinstance({a},dict):")
        ctx.push_indent()
        _spd=self.prop_value(node,"speed",140);_tj=self.prop_value(node,"turn_jitter",60)
        ctx.emit(f"_dt=max(0.001,locals().get('dt',1/60))")
        ctx.emit(f"_cur={a}.get('_ai_wander_heading')")
        ctx.emit(f"_cur=_cur if isinstance(_cur,pygame.Vector2) and _cur.length_squared()>1e-6 else pygame.Vector2(1,0).rotate(random.uniform(0,360))")
        ctx.emit(f"_cur=_cur.rotate(random.uniform(-1,1)*{_tj!r}*_dt)")
        ctx.emit(f"{a}['_ai_wander_heading']=_cur;{a}['vel']=_cur.normalize()*{_spd!r}")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_bounce_patrol", "AI Movement", "AI: Bounce Patrol (Straight Wall Bounce)", "Moves in a straight line and reflects off the given rectangular bounds like a classic bouncing-ball patrol. No target needed.")
class AiMv_MoveBouncePatrol(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 200, min_val=0),
        "min_x": PropSpec("min_x", "number", 0),
        "max_x": PropSpec("max_x", "number", 1280),
        "min_y": PropSpec("min_y", "number", 0),
        "max_y": PropSpec("max_y", "number", 720),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        ctx.emit(f"if isinstance({a},dict):")
        ctx.push_indent()
        _spd=self.prop_value(node,"speed",200);_mnx=self.prop_value(node,"min_x",0);_mxx=self.prop_value(node,"max_x",1280);_mny=self.prop_value(node,"min_y",0);_mxy=self.prop_value(node,"max_y",720)
        ctx.emit(f"_cur={a}.get('_ai_bounce_dir')")
        ctx.emit(f"_cur=_cur if isinstance(_cur,pygame.Vector2) and _cur.length_squared()>1e-6 else pygame.Vector2(1,0).rotate(random.uniform(0,360))")
        ctx.emit(f"_p={a}.get('pos',(0,0))")
        ctx.emit(f"if _p[0]<={_mnx!r} and _cur.x<0: _cur.x=-_cur.x")
        ctx.emit(f"if _p[0]>={_mxx!r} and _cur.x>0: _cur.x=-_cur.x")
        ctx.emit(f"if _p[1]<={_mny!r} and _cur.y<0: _cur.y=-_cur.y")
        ctx.emit(f"if _p[1]>={_mxy!r} and _cur.y>0: _cur.y=-_cur.y")
        ctx.emit(f"{a}['_ai_bounce_dir']=_cur;{a}['vel']=_cur.normalize()*{_spd!r}")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_curved_wall_bounce", "AI Movement", "AI: Curved Wall Bounce", "Like Bounce Patrol, but eases into the new direction at a turn rate instead of snapping, so each bounce arcs smoothly. No target needed.")
class AiMv_MoveCurvedWallBounce(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 200, min_val=0),
        "turn_rate": PropSpec("turn_rate", "number", 240, min_val=1),
        "min_x": PropSpec("min_x", "number", 0),
        "max_x": PropSpec("max_x", "number", 1280),
        "min_y": PropSpec("min_y", "number", 0),
        "max_y": PropSpec("max_y", "number", 720),
    }
