@register_node("ai_move_patrol_waypoints", "AI Movement", "AI: Patrol Waypoints", "Cycles through a list of world-space waypoints ('x,y;x,y;x,y'), moving to each in turn and looping (or stopping) at the end.")
class AiMv_MovePatrolWaypoints(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 180, min_val=0),
        "waypoints": PropSpec("waypoints", "string", "0,0;200,0;200,200;0,200", tooltip="Format: x,y;x,y;x,y"),
        "arrive_radius": PropSpec("arrive_radius", "number", 20, min_val=1),
        "loop": PropSpec("loop", "bool", True),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        ctx.emit(f"if isinstance({a},dict):")
        ctx.push_indent()
        _spd=self.prop_value(node,"speed",180);_wp_raw=str(self.prop_value(node,"waypoints","0,0;200,0;200,200;0,200"));_ar=self.prop_value(node,"arrive_radius",20);_loop=bool(self.prop_value(node,"loop",True))
        _wp=[]
        for _seg in _wp_raw.split(";"):
            _seg=_seg.strip()
            if not _seg: continue
            _parts=_seg.split(",")
            if len(_parts)>=2:
                try: _wp.append((float(_parts[0]),float(_parts[1])))
                except ValueError: pass
        if not _wp: _wp=[(0.0,0.0)]
        ctx.emit(f"_wp={_wp!r}")
        ctx.emit(f"_idx=int({a}.get('_ai_patrol_idx',0))%len(_wp)")
        ctx.emit(f"_wpt=pygame.Vector2(_wp[_idx])")
        ctx.emit(f"_d=_wpt-pygame.Vector2({a}.get('pos',(0,0)))")
        ctx.emit(f"if _d.length()<={_ar!r}:")
        ctx.push_indent()
        ctx.emit(f"if {_loop!r} or _idx+1<len(_wp): _idx=(_idx+1)%len(_wp)")
        ctx.emit(f"{a}['_ai_patrol_idx']=_idx")
        ctx.pop_indent()
        ctx.emit(f"{a}['vel']=_d.normalize()*{_spd!r} if _d.length_squared()>4 else pygame.Vector2(0,0)")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("ai_move_dash_toward", "AI Movement", "AI: Dash Toward Target", "Bursts toward the target at high speed for a short duration, then goes idle until the cooldown expires and it dashes again.")
class AiMv_MoveDashToward(NodeBase):
    properties = {
        "dash_speed": PropSpec("dash_speed", "number", 500, min_val=0),
        "dash_duration": PropSpec("dash_duration", "number", 0.25, min_val=0.02),
        "cooldown": PropSpec("cooldown", "number", 1.2, min_val=0),
    }
    inputs = [PinSpec("", EXEC), PinSpec("actor", OBJECT, default=None, tooltip="Who moves (default: Self)"), PinSpec("target", OBJECT, default=None, tooltip="Who/what to react to (default: nearest enemy)")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        actor = self.object_input_expr(ctx, node, "actor", "me")
        target = self.object_input_expr(ctx, node, "target", "locals().get('other') or me")
        a = ctx.fresh_var("ai_actor")
        ctx.emit(f"{a}={actor}")
        t = ctx.fresh_var('ai_target')
        ctx.emit(f"{t}={target}")
        ctx.emit(f"if isinstance({a},dict) and isinstance({t},dict) and {a} is not {t}:")
        ctx.push_indent()
        _ds=self.prop_value(node,"dash_speed",500);_dd=self.prop_value(node,"dash_duration",0.25);_cd0=self.prop_value(node,"cooldown",1.2)
        ctx.emit(f"_dt=max(0.001,locals().get('dt',1/60))")
        ctx.emit(f"_cd=max(0.0,float({a}.get('_ai_dash_cd',0))-_dt)")
        ctx.emit(f"_tm=float({a}.get('_ai_dash_timer',0))")
        ctx.emit(f"if _tm>0:")
        ctx.push_indent()
        ctx.emit(f"_tm=max(0.0,_tm-_dt)")
        ctx.emit(f"_dv={a}.get('_ai_dash_dir')")
        ctx.emit(f"{a}['vel']=pygame.Vector2(_dv)*{_ds!r} if isinstance(_dv,pygame.Vector2) else pygame.Vector2(0,0)")
        ctx.pop_indent()
        ctx.emit(f"elif _cd<=0:")
        ctx.push_indent()
        ctx.emit(f"_d=pygame.Vector2({t}.get('pos',(0,0)))-pygame.Vector2({a}.get('pos',(0,0)))")
        ctx.emit(f"if _d.length_squared()>4:")
        ctx.push_indent()
        ctx.emit(f"_dv=_d.normalize();{a}['_ai_dash_dir']=_dv;_tm={_dd!r};_cd={_cd0!r};{a}['vel']=_dv*{_ds!r}")
        ctx.pop_indent()
        ctx.pop_indent()
        ctx.emit(f"else: {a}['vel']=pygame.Vector2(0,0)")
        ctx.emit(f"{a}['_ai_dash_timer']=_tm;{a}['_ai_dash_cd']=_cd")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

