# ---------- Performance / graph-friendly runtime gates ----------
@register_node("perf_every_n_ticks", "Performance", "Every N Ticks Gate",
               "Performance gate: only continue once every N executions. Great for expensive checks on Tick.")
class PerfEveryNTicksNode(NodeBase):
    properties = {"n": PropSpec("n", "number", 4, min_val=1, max_val=999)}
    inputs = [PinSpec("", EXEC), PinSpec("n", NUMBER, default=4)]; outputs = [PinSpec("run", EXEC), PinSpec("skip", EXEC)]
    def generate_code(self, ctx, node, visited):
        n_expr = self.input_expr(ctx,node,"n") if ctx.find_input_link(node["id"],"n") else repr(self.prop_value(node,"n",4))
        key = f"_ns_perf_tick_{node['id']}"
        ctx.emit(f"me[{key!r}] = me.get({key!r}, 0) + 1")
        ctx.emit(f"if me[{key!r}] % max(1, int({n_expr})) == 0:")
        ctx.indent_level += 1; ctx.generate_exec_branch(node["id"], "run", visited); ctx.indent_level -= 1
        ctx.emit("else:")
        ctx.indent_level += 1; ctx.generate_exec_branch(node["id"], "skip", visited); ctx.indent_level -= 1

@register_node("perf_random_chance_gate", "Performance", "Random Chance Gate",
               "Performance/randomness gate: run a branch only with a percentage chance.")
class PerfRandomChanceGateNode(NodeBase):
    properties = {"chance": PropSpec("chance", "number", 0.25, min_val=0.0, max_val=1.0)}
    inputs = [PinSpec("", EXEC), PinSpec("chance", NUMBER, default=0.25)]; outputs = [PinSpec("run", EXEC), PinSpec("skip", EXEC)]
    def generate_code(self, ctx, node, visited):
        chance = self.input_expr(ctx,node,"chance") if ctx.find_input_link(node["id"],"chance") else repr(self.prop_value(node,"chance",0.25))
        ctx.emit(f"if random.random() <= _ns_clamp(float({chance}), 0, 1):")
        ctx.indent_level += 1; ctx.generate_exec_branch(node["id"], "run", visited); ctx.indent_level -= 1
        ctx.emit("else:")
        ctx.indent_level += 1; ctx.generate_exec_branch(node["id"], "skip", visited); ctx.indent_level -= 1

# ---------- Visual Effects ----------
@register_node("vfx_spawn_particle", "Visual Effects", "Spawn Particle",
               "Generates small visual dot particles at a location. Purely cosmetic, no collision.")
class SpawnParticleNode(NodeBase):
    properties = {"color": PropSpec("color", "color", [255, 200, 70]), "count": PropSpec("count", "number", 5)}
    inputs = [PinSpec("", EXEC), PinSpec("position", VECTOR, default=None), PinSpec("color", COLOR, default=[255,200,70]), PinSpec("count", NUMBER, default=5)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        pos = self.input_expr(ctx, node, "position") if ctx.find_input_link(node["id"], "position") else "me['pos']"
        c = self.input_expr(ctx, node, "color") if ctx.find_input_link(node["id"], "color") else repr(self.prop_value(node, "color", [255,200,70]))
        n = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(int(self.prop_value(node, "count", 5)))
        ctx.emit(f"ctx.spawn_particles({pos}, {c}, {n})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("vfx_spawn_particle_directional", "Visual Effects", "Spawn Directional Particles",
               "Pure directional particle burst: every dot flies along the Direction input (vector — wire "
               "Get Aim Direction, Get Direction To Target, a Position Event's direction, etc.; a plain number "
               "works too and is read as degrees). Spread fans them inside a cone (0 = laser-straight line). "
               "Purely cosmetic, no collision.")
class SpawnParticleDirectionalNode(NodeBase):
    properties = {
        "color": PropSpec("color", "color", [255, 200, 70]),
        "count": PropSpec("count", "number", 8),
        "speed": PropSpec("speed", "number", 180.0, min_val=0.0, max_val=2400.0),
        "spread": PropSpec("spread", "number", 20.0, min_val=0.0, max_val=360.0,
                           tooltip="Total cone width in degrees. 0 = perfectly straight beam."),
        "life": PropSpec("life", "number", 0.6, min_val=0.05, max_val=10.0),
        "size": PropSpec("size", "number", 3.0, min_val=0.5, max_val=24.0),
        "gravity": PropSpec("gravity", "number", 0.0, min_val=-2400.0, max_val=2400.0,
                            tooltip="Downward pull per second. 0 = flies straight forever."),
    }
    inputs = [PinSpec("", EXEC), PinSpec("position", VECTOR, default=None),
              PinSpec("direction", VECTOR, default=None),
              PinSpec("color", COLOR, default=[255, 200, 70]), PinSpec("count", NUMBER, default=8),
              PinSpec("speed", NUMBER, default=180.0), PinSpec("spread", NUMBER, default=20.0),
              PinSpec("life", NUMBER, default=0.6), PinSpec("size", NUMBER, default=3.0),
              PinSpec("gravity", NUMBER, default=0.0)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        pos = self.input_expr(ctx, node, "position") if ctx.find_input_link(node["id"], "position") else "me['pos']"
        # Unwired direction = the character's current facing.
        dr = (self.input_expr(ctx, node, "direction") if ctx.find_input_link(node["id"], "direction")
              else "pygame.Vector2(-1 if me.get('flip_x', False) else 1, 0)")
        c = self.input_expr(ctx, node, "color") if ctx.find_input_link(node["id"], "color") else repr(self.prop_value(node, "color", [255, 200, 70]))
        n = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(int(self.prop_value(node, "count", 8)))
        sp = self.input_expr(ctx, node, "speed") if ctx.find_input_link(node["id"], "speed") else repr(float(self.prop_value(node, "speed", 180.0)))
        sr = self.input_expr(ctx, node, "spread") if ctx.find_input_link(node["id"], "spread") else repr(float(self.prop_value(node, "spread", 20.0)))
        lf = self.input_expr(ctx, node, "life") if ctx.find_input_link(node["id"], "life") else repr(float(self.prop_value(node, "life", 0.6)))
        sz = self.input_expr(ctx, node, "size") if ctx.find_input_link(node["id"], "size") else repr(float(self.prop_value(node, "size", 3.0)))
        gv = self.input_expr(ctx, node, "gravity") if ctx.find_input_link(node["id"], "gravity") else repr(float(self.prop_value(node, "gravity", 0.0)))
        ctx.emit(f"ctx.spawn_particles_directional({pos}, {dr}, {c}, {n}, {sp}, {sr}, {lf}, {sz}, {gv})")
        ctx.generate_exec_branch(node["id"], "", visited)

