@register_node("random_jitter", "Utility", "Random Jitter",
               "Adds a uniformly random offset from -Amount to +Amount to a value.")
class RandomJitterNode(NodeBase):
    inputs = [PinSpec("value", NUMBER, default=0), PinSpec("amount", NUMBER, default=1)]
    outputs = [PinSpec("value", NUMBER)]
    pure = True
