@register_node("event_on_projectile_wall_hit", "Weapon Events", "On Projectile Wall Touch / Hit",
               "Fires when a projectile hits or touches the arena wall. Outputs the projectile, impact side, hit position, and surface normal.")
class EventOnProjectileWallHitNode(NodeBase):
    outputs = [
        PinSpec("", EXEC),
        PinSpec("projectile", OBJECT),
        PinSpec("name", STRING),
        PinSpec("wall_side", STRING),
        PinSpec("hit_pos", VECTOR),
        PinSpec("normal", VECTOR),
    ]
    def generate_output_expr(self, ctx, node, pin_name):
        return ctx.event_args.get(pin_name, "None")
