@register_node("vfx_wiggle_target", "Visual Effects", "Wiggle Target / Sprite",
               "Universally applies an oscillating angle/position wiggle to characters, projectiles, weapons, or scene entities.")
class VfxWiggleTargetNode(NodeBase):
    properties = {
        "frequency": PropSpec("frequency", "number", 12.0, min_val=0.5, max_val=50.0),
        "angle_amplitude": PropSpec("angle_amplitude", "number", 15.0, min_val=0.0, max_val=180.0),
        "offset_amplitude": PropSpec("offset_amplitude", "number", 4.0, min_val=0.0, max_val=50.0),
        "duration": PropSpec("duration", "number", 0.5, min_val=0.0, max_val=60.0, tooltip="0 = continuous until stopped"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("frequency", NUMBER, default=12.0),
        PinSpec("angle_amplitude", NUMBER, default=15.0),
        PinSpec("offset_amplitude", NUMBER, default=4.0),
        PinSpec("duration", NUMBER, default=0.5),
    ]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        freq = self.input_expr(ctx, node, "frequency") if ctx.find_input_link(node["id"], "frequency") else repr(self.prop_value(node, "frequency", 12.0))
        a_amp = self.input_expr(ctx, node, "angle_amplitude") if ctx.find_input_link(node["id"], "angle_amplitude") else repr(self.prop_value(node, "angle_amplitude", 15.0))
        p_amp = self.input_expr(ctx, node, "offset_amplitude") if ctx.find_input_link(node["id"], "offset_amplitude") else repr(self.prop_value(node, "offset_amplitude", 4.0))
        dur = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 0.5))
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.push_indent()
        ctx.emit(f"{t}['wiggle_active'] = True")
        ctx.emit(f"{t}['wiggle_start_time'] = pygame.time.get_ticks() / 1000.0")
        ctx.emit(f"{t}['wiggle_freq'] = float({freq})")
        ctx.emit(f"{t}['wiggle_angle_amp'] = float({a_amp})")
        ctx.emit(f"{t}['wiggle_pos_amp'] = float({p_amp})")
        ctx.emit(f"{t}['wiggle_duration'] = float({dur})")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

