@register_node("character_get_instance_id", "Utility", "Get Character Instance ID",
               "Returns the unique instance ID and numeric ID of this character (or a target character). Useful for creating per-character unique custom bars, tags, and tracking.")
class CharacterGetInstanceIdNode(NodeBase):
    inputs = [PinSpec("character", OBJECT, default=None)]
    outputs = [PinSpec("instance_id", STRING), PinSpec("id_number", NUMBER)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        c = self.object_input_expr(ctx, node, "character", "me")
        if output_name == "id_number":
            return f"(lambda _c: int(str(_c.get('instance_id', '0')).replace('inst_', '')) if str(_c.get('instance_id', '')).replace('inst_', '').isdigit() else 0)({c})"
        return f"str({c}.get('instance_id', {c}.get('name', 'char')))"

