@register_node("utility_format_id_tag", "Utility", "Format Tag With ID",
               "Formats a combined tag string using a prefix, unique ID, and optional suffix (e.g. 'hp_bar_' + 'inst_1001' -> 'hp_bar_inst_1001').")
class UtilityFormatIdTagNode(NodeBase):
    properties = {
        "prefix": PropSpec("prefix", "string", "hp_bar_"),
        "suffix": PropSpec("suffix", "string", ""),
    }
    inputs = [
        PinSpec("prefix", STRING, default="hp_bar_"),
        PinSpec("id", STRING, default=""),
        PinSpec("suffix", STRING, default=""),
    ]
    outputs = [PinSpec("tag", STRING)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        pfx = self.input_expr(ctx, node, "prefix") if ctx.find_input_link(node["id"], "prefix") else repr(self.prop_value(node, "prefix", "hp_bar_"))
        i_val = self.input_expr(ctx, node, "id") if ctx.find_input_link(node["id"], "id") else repr(str(self.prop_value(node, "id", "")))
        sfx = self.input_expr(ctx, node, "suffix") if ctx.find_input_link(node["id"], "suffix") else repr(self.prop_value(node, "suffix", ""))
        # Build normal string concatenation. Embedding repr() expressions
        # inside another generated f-string produced invalid code such as
        # f''hp_bar_''inst_1001'' (the reported export SyntaxError).
        return f"(str({pfx}) + str({i_val}) + str({sfx}))"

@register_node("utility_generate_unique_id", "Utility", "Generate Unique ID",
               "Generates a fresh unique string ID on each execution branch or evaluation.")
class UtilityGenerateUniqueIdNode(NodeBase):
    properties = {"prefix": PropSpec("prefix", "string", "id_")}
    inputs = [PinSpec("prefix", STRING, default="id_")]
    outputs = [PinSpec("unique_id", STRING)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        pfx = self.input_expr(ctx, node, "prefix") if ctx.find_input_link(node["id"], "prefix") else repr(self.prop_value(node, "prefix", "id_"))
        # Engine counter + time_ns is unique even when several characters
        # use the same Random Seed during the same frame.
        return f"ctx.make_unique_id({pfx})"

@register_node("scene_clone_node", "Scene Actions", "Clone Scene Node / Custom Bar",
               "Duplicates any scene node (Custom Bar, HP Bar, Progress Bar, Label, Counter, etc.) by its ID, Tag, Name, or direct Object link. Creates a fresh instance with a new unique ID.")
class SceneCloneNodeNode(NodeBase):
    properties = {
        "node_id": PropSpec("node_id", "number", 1, min_val=1, max_val=9999, tooltip="Numeric ID of template node"),
        "by_tag": PropSpec("by_tag", "string", "", tooltip="Template node tag to clone (e.g. 'hp_bar')"),
        "new_tag": PropSpec("new_tag", "string", "", tooltip="Optional new tag for the cloned node"),
        "new_name": PropSpec("new_name", "string", "", tooltip="Optional new name for the cloned node"),
        "link_self": PropSpec("link_self", "boolean", True, tooltip="Automatically link cloned node to Self"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("node", OBJECT, default=None),
        PinSpec("node_id", NUMBER, default=1),
        PinSpec("tag", STRING, default=""),
        PinSpec("new_tag", STRING, default=""),
        PinSpec("new_name", STRING, default=""),
        PinSpec("link_character", OBJECT, default=None),
    ]
    outputs = [
        PinSpec("", EXEC),
        PinSpec("cloned_node", OBJECT),
        PinSpec("cloned_id", NUMBER),
        PinSpec("cloned_name", STRING),
    ]
    def generate_code(self, ctx, node, visited):
        v_node = ctx.fresh_var("cloned_node")
        ctx.expr_cache[(node["id"], "cloned_node")] = v_node
        ctx.expr_cache[(node["id"], "cloned_id")] = f"({v_node}['id'] if {v_node} else 0)"
        ctx.expr_cache[(node["id"], "cloned_name")] = f"({v_node}.get('name', '') if {v_node} else '')"
        
        if ctx.find_input_link(node["id"], "node"):
            src = self.input_expr(ctx, node, "node")
        elif ctx.find_input_link(node["id"], "tag"):
            t_expr = self.input_expr(ctx, node, "tag")
            src = f"ctx.en_find_tag_first({t_expr})"
        elif self.prop_value(node, "by_tag", ""):
            src = f"ctx.en_find_tag_first({repr(self.prop_value(node, 'by_tag'))})"
        elif ctx.find_input_link(node["id"], "node_id"):
            nid_expr = self.input_expr(ctx, node, "node_id")
            src = f"ctx.get_ext_node({nid_expr})"
        else:
            nid = repr(int(self.prop_value(node, "node_id", 1)))
            src = f"ctx.get_ext_node({nid})"
            
        ntag = self.input_expr(ctx, node, "new_tag") if ctx.find_input_link(node["id"], "new_tag") else repr(self.prop_value(node, "new_tag", "") or None)
        nname = self.input_expr(ctx, node, "new_name") if ctx.find_input_link(node["id"], "new_name") else repr(self.prop_value(node, "new_name", "") or None)
        
        if ctx.find_input_link(node["id"], "link_character"):
            lchar = self.input_expr(ctx, node, "link_character")
        elif self.prop_value(node, "link_self", True):
            lchar = "me"
        else:
            lchar = "None"
            
        ctx.emit(f"{v_node} = ctx.clone_ext_node({src}, new_tag={ntag}, new_name={nname}, link_character={lchar})")
        ctx.generate_exec_branch(node["id"], "", visited)
    def generate_output_expr(self, ctx, node, pin_name):
        v_node = ctx.expr_cache.get((node["id"], "cloned_node"), "None")
        if pin_name == "cloned_id":
            return f"({v_node}['id'] if isinstance({v_node}, dict) else 0)"
        if pin_name == "cloned_name":
            return f"({v_node}.get('name', '') if isinstance({v_node}, dict) else '')"
        return v_node

@register_node("scene_duplicate_bar_for_character", "Scene Actions", "Duplicate Custom Bar For Character",
               "Duplicates a template Custom HP Bar / progress bar on spawn, links it directly to this character, and assigns custom tags/names.")
class SceneDuplicateBarForCharacterNode(NodeBase):
    properties = {
        "template_tag": PropSpec("template_tag", "string", "hp_bar", tooltip="Tag of the template bar to duplicate"),
        "new_tag": PropSpec("new_tag", "string", "", tooltip="Optional unique tag for the new instance (e.g. 'my_hp_bar')"),
        "offset_y": PropSpec("offset_y", "number", -35.0, tooltip="Vertical offset above character"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("character", OBJECT, default=None),
        PinSpec("template_tag", STRING, default="hp_bar"),
        PinSpec("new_tag", STRING, default=""),
        PinSpec("offset_y", NUMBER, default=-35.0),
    ]
    outputs = [
        PinSpec("", EXEC),
        PinSpec("cloned_bar", OBJECT),
        PinSpec("bar_id", NUMBER),
    ]
    def generate_code(self, ctx, node, visited):
        c = self.object_input_expr(ctx, node, "character", "me")
        ttag = self.input_expr(ctx, node, "template_tag") if ctx.find_input_link(node["id"], "template_tag") else repr(self.prop_value(node, "template_tag", "hp_bar"))
        ntag = self.input_expr(ctx, node, "new_tag") if ctx.find_input_link(node["id"], "new_tag") else repr(self.prop_value(node, "new_tag", "") or None)
        off_y = self.input_expr(ctx, node, "offset_y") if ctx.find_input_link(node["id"], "offset_y") else repr(self.prop_value(node, "offset_y", -35.0))
        v_bar = ctx.fresh_var("cloned_bar")
        ctx.expr_cache[(node["id"], "cloned_bar")] = v_bar
        ctx.expr_cache[(node["id"], "bar_id")] = f"({v_bar}['id'] if {v_bar} else 0)"
        ctx.emit(f"_tmpl_src = ctx.en_find_tag_first({ttag}) or ctx.get_ext_node_by_name({ttag})")
        ctx.emit(f"{v_bar} = ctx.clone_ext_node(_tmpl_src, new_tag={ntag}, link_character={c}, wy={off_y})")
        ctx.generate_exec_branch(node["id"], "", visited)
    def generate_output_expr(self, ctx, node, pin_name):
        v_bar = ctx.expr_cache.get((node["id"], "cloned_bar"), "None")
        if pin_name == "bar_id":
            return f"({v_bar}['id'] if isinstance({v_bar}, dict) else 0)"
        return v_bar

