@register_node("random_once_chance", "Utility", "Random Once Chance",
               "Allows a random event through at most once per character. Reset its latch with the Reset input.")
class RandomOnceChanceNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("reset", EXEC), PinSpec("chance", NUMBER, default=50)]
    outputs = [PinSpec("pass", EXEC), PinSpec("fail", EXEC)]
    def generate_code(self, ctx, node, visited):
        chance = self.input_expr(ctx,node,'chance') if ctx.find_input_link(node['id'],'chance') else repr(50)
        store = "me.setdefault('_ns_random_once', {{}})"
        key = repr(node['id'])
        ctx.emit(f"if {key} in {store} and {store}[{key}] == 'reset':")
        ctx.push_indent(); ctx.emit(f"{store}.pop({key}, None)"); ctx.pop_indent()
        ctx.emit(f"if {key} not in {store}:")
        ctx.push_indent()
        ctx.emit(f"{store}[{key}] = 'pass' if random.random() * 100.0 < float({chance}) else 'fail'")
        ctx.pop_indent()
        ctx.emit(f"if {store}.get({key}) == 'pass':")
        ctx.push_indent(); ctx.generate_exec_branch(node['id'],'pass',visited); ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent(); ctx.generate_exec_branch(node['id'],'fail',visited); ctx.pop_indent()

@register_node("random_retrigger_gate", "Utility", "Random Retrigger Gate",
               "Rolls a chance on every trigger and provides explicit Pass/Fail execution paths. Unlike Once Chance it never latches.")
class RandomRetriggerGateNode(RandomProbabilityGateNode):
    pass

@register_node("random_shuffle_index", "Utility", "Random Shuffle Index",
               "Produces a shuffled index from 0 to Count-1. It cycles through every index before repeating.")
class RandomShuffleIndexNode(NodeBase):
    properties = {"count": PropSpec("count", "number", 3, min_val=1, max_val=1000)}
    inputs = [PinSpec("", EXEC), PinSpec("count", NUMBER, default=3)]
    outputs = [PinSpec("", EXEC), PinSpec("index", NUMBER), PinSpec("finished", EXEC)]
    def generate_code(self, ctx, node, visited):
        count = self.input_expr(ctx,node,'count') if ctx.find_input_link(node['id'],'count') else repr(self.prop_value(node,'count',3))
        store = f"me.setdefault('_ns_shuffle', {{}}).setdefault({node['id']!r}, [])"
        bag = ctx.fresh_var('shuffle_bag')
        idx = ctx.fresh_var('shuffle_idx')
        ctx.emit(f"{bag} = {store}")
        ctx.emit(f"if not {bag}:")
        ctx.push_indent()
        ctx.emit(f"{bag}.extend(range(max(1, int({count}))))")
        ctx.emit(f"random.shuffle({bag})")
        ctx.pop_indent()
        ctx.emit(f"{idx} = {bag}.pop(0)")
        ctx.expr_cache[(node['id'],'index')] = idx
        ctx.generate_exec_branch(node['id'],'',visited)
        ctx.emit(f"if not {bag}:")
        ctx.push_indent(); ctx.generate_exec_branch(node['id'],'finished',visited); ctx.pop_indent()
    def generate_output_expr(self,ctx,node,output_name):
        return ctx.expr_cache.get((node['id'],'index'),'0')

# ── Manual Input / Physics / Camera Control pack ──────────────────────────────
# This block intentionally uses explicit node names instead of overloading the
# old arena keyboard shortcuts. Blueprint authors can lock scene controls,
# listen for W/A/S/D, apply gravity, and drive character velocity themselves.
@register_node("input_key", "Input", "Key Input",
               "Matches a key string from On Input. It exposes separate pressed, released, and held execution outputs.")
class InputKeyNode(NodeBase):
    properties = {
        "key": PropSpec("key", "string", "w"),
    }
    inputs = [PinSpec("", EXEC), PinSpec("event_key", STRING, default="")]
    outputs = [PinSpec("pressed", EXEC), PinSpec("released", EXEC), PinSpec("held", EXEC),
               PinSpec("is_down", BOOLEAN), PinSpec("key", STRING)]
    def generate_code(self, ctx, node, visited):
        actual = self.input_expr(ctx, node, "event_key") if ctx.find_input_link(node["id"], "event_key") else "key"
        wanted = str(self.prop_value(node, "key", "w")).lower()
        ctx.expr_cache[(node["id"], "key")] = actual
        ctx.expr_cache[(node["id"], "is_down")] = f"(str({actual}).lower() in ({wanted!r}, {wanted + '_held'!r}))"
        ctx.emit(f"if str({actual}).lower() == {wanted!r}:")
        ctx.push_indent(); ctx.generate_exec_branch(node["id"], "pressed", visited); ctx.pop_indent()
        ctx.emit(f"elif str({actual}).lower() == {wanted + '_released'!r}:")
        ctx.push_indent(); ctx.generate_exec_branch(node["id"], "released", visited); ctx.pop_indent()
        ctx.emit(f"elif str({actual}).lower() == {wanted + '_held'!r}:")
        ctx.push_indent(); ctx.generate_exec_branch(node["id"], "held", visited); ctx.pop_indent()
    def generate_output_expr(self, ctx, node, output_name):
        if output_name == "key": return ctx.expr_cache.get((node["id"], "key"), "key")
        if output_name == "is_down": return ctx.expr_cache.get((node["id"], "is_down"), "False")
        return "None"

@register_node("input_any_key", "Input", "Any Key",
               "Fires for any keyboard key or mouse input. Use the key output to inspect which input arrived.")
class AnyKeyInputNode(InputKeyNode):
    properties = {}
    def generate_code(self, ctx, node, visited):
        actual = self.input_expr(ctx, node, "event_key") if ctx.find_input_link(node["id"], "event_key") else "key"
        ctx.expr_cache[(node["id"], "key")] = actual
        ctx.expr_cache[(node["id"], "is_down")] = f"not str({actual}).lower().endswith('_released')"
        ctx.generate_exec_branch(node["id"], "pressed", visited)
        ctx.generate_exec_branch(node["id"], "held", visited)
        ctx.generate_exec_branch(node["id"], "released", visited)

@register_node("input_mouse_button", "Input", "Mouse Button",
               "Treats mouse_left, mouse_right, or mouse_middle as an input key.")
class MouseButtonInputNode(InputKeyNode):
    properties = {"key": PropSpec("key", "dropdown", "mouse_left", options=["mouse_left", "mouse_right", "mouse_middle"])}

@register_node("input_key_combo", "Input", "Key Combination",
               "Matches modifier combinations such as ctrl+w, shift+space, or alt+mouse_left.")
class KeyComboInputNode(InputKeyNode):
    properties = {"key": PropSpec("key", "string", "ctrl+w")}

def _control_exprs(self, ctx, node, specs):
    values = {}
    for pin in specs:
        if ctx.find_input_link(node["id"], pin.name):
            values[pin.name] = self.input_expr(ctx, node, pin.name)
        else:
            values[pin.name] = ctx.default_to_expr(pin.type, pin.default)
    return values

def _register_control_action_node(key, category, title, description, specs=(), emitter=None, properties=None):
    specs = list(specs)
    node_properties = dict(properties or {})
    class ControlActionNode(NodeBase):
        inputs = [PinSpec("", EXEC)] + specs
        outputs = [PinSpec("", EXEC)]
        properties = node_properties
        def generate_code(self, ctx, node, visited):
            values = _control_exprs(self, ctx, node, specs)
            line = emitter(self, ctx, node, values) if emitter else "pass"
            if line:
                ctx.emit(line)
            ctx.generate_exec_branch(node["id"], "", visited)
    ControlActionNode.__name__ = "Control_" + "".join(part.title() for part in key.split("_"))
    register_node(key, category, title, description)(ControlActionNode)
    return ControlActionNode

def _register_control_value_node(key, category, title, description, specs, output_name, output_type, expression):
    specs = list(specs)
    class ControlValueNode(NodeBase):
        inputs = specs
        outputs = [PinSpec(output_name, output_type)]
        properties = {}
        pure = True
        def generate_output_expr(self, ctx, node, requested_output):
            values = _control_exprs(self, ctx, node, specs)
            return expression(self, ctx, node, values)
    ControlValueNode.__name__ = "Value_" + "".join(part.title() for part in key.split("_"))
    register_node(key, category, title, description)(ControlValueNode)
    return ControlValueNode

# Explicit node catalog: 100+ small, focused controls. The catalog is kept in
# source so the node dictionary generator can document every new registration.
INPUT_CONTROL_NODE_CATALOG = []
def _catalog_action(key, category, title, description, specs=(), emitter=None, properties=None):
    INPUT_CONTROL_NODE_CATALOG.append((key, category, title, description))
    return _register_control_action_node(key, category, title, description, specs, emitter, properties)
def _catalog_value(key, category, title, description, specs, output_name, output_type, expression):
    INPUT_CONTROL_NODE_CATALOG.append((key, category, title, description))
    return _register_control_value_node(key, category, title, description, specs, output_name, output_type, expression)

# Prebuilt physics bodies — ready-to-use presets for platformer tests.
@register_node("physics_earth_gravity", "Physics", "Earth Gravity Body",
               "Prebuilt Earth-like gravity: 980 units/s² downward, terminal velocity, modest restitution, floor friction, and sleeping at rest.")
class EarthGravityNode(NodeBase):
    properties = {
        "gravity": PropSpec("gravity", "number", 980.0),
        "bounce": PropSpec("bounce", "number", 0.15, min_val=0.0, max_val=1.0),
        "floor_friction": PropSpec("floor_friction", "number", 0.82, min_val=0.0, max_val=1.0),
        "terminal_velocity": PropSpec("terminal_velocity", "number", 1600.0),
    }
    inputs = [PinSpec("", EXEC), PinSpec("gravity", NUMBER, default=980.0), PinSpec("bounce", NUMBER, default=0.15)]
    outputs = [PinSpec("", EXEC), PinSpec("grounded", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        g = self.input_expr(ctx,node,"gravity") if ctx.find_input_link(node["id"],"gravity") else repr(self.prop_value(node,"gravity",980.0))
        b = self.input_expr(ctx,node,"bounce") if ctx.find_input_link(node["id"],"bounce") else repr(self.prop_value(node,"bounce",0.15))
        fr = repr(self.prop_value(node,"floor_friction",0.82)); tv = repr(self.prop_value(node,"terminal_velocity",1600.0))
        ctx.emit(f"ctx.set_gravity(me, {g})")
        ctx.emit(f"ctx.set_restitution(me, {b})")
        ctx.emit(f"me['ground_friction'] = max(0.0, min(1.0, float({fr})))")
        ctx.emit(f"ctx.set_terminal_velocity(me, {tv})")
        ctx.expr_cache[(node["id"],"grounded")] = "bool(me.get('gravity_grounded', False))"
        ctx.generate_exec_branch(node["id"],"",visited)
    def generate_output_expr(self,ctx,node,output_name):
        return ctx.expr_cache.get((node["id"],"grounded"), "bool(me.get('gravity_grounded', False))")

@register_node("physics_moon_gravity", "Physics", "Moon Gravity Body", "Prebuilt low-gravity body using approximately 162 units/s².")
class MoonGravityNode(EarthGravityNode):
    properties = {"gravity": PropSpec("gravity", "number", 162.0), "bounce": PropSpec("bounce", "number", 0.25), "floor_friction": PropSpec("floor_friction", "number", 0.82), "terminal_velocity": PropSpec("terminal_velocity", "number", 900.0)}

@register_node("physics_zero_gravity", "Physics", "Zero Gravity Body", "Disables gravity and bounce for a floating body.")
class ZeroGravityNode(NodeBase):
    inputs = [PinSpec("", EXEC)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self,ctx,node,visited):
        ctx.emit("ctx.disable_gravity(me)"); ctx.emit("ctx.set_restitution(me, 0.0)"); ctx.generate_exec_branch(node["id"],"",visited)

@register_node("physics_stop_bounce", "Physics", "Stop Bouncing", "Immediately removes vertical bounce, marks the body grounded, and applies floor friction.")
class StopBounceNode(NodeBase):
    inputs = [PinSpec("", EXEC)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self,ctx,node,visited):
        ctx.emit("ctx.stop_bounce(me)"); ctx.generate_exec_branch(node["id"],"",visited)

@register_node("physics_rigid_body", "Physics", "Rigid Body 2D", "Preset for a dynamic body affected by gravity, forces, impulses, collision bounce, and damping.")
class RigidBodyPresetNode(NodeBase):
    properties = {"gravity": PropSpec("gravity","number",980.0), "mass": PropSpec("mass","number",1.0), "bounce": PropSpec("bounce","number",0.15), "damping": PropSpec("damping","number",0.0)}
    inputs = [PinSpec("",EXEC), PinSpec("gravity",NUMBER,default=980.0)]
    outputs = [PinSpec("",EXEC)]
    def generate_code(self,ctx,node,visited):
        g = self.input_expr(ctx,node,"gravity") if ctx.find_input_link(node["id"],"gravity") else repr(self.prop_value(node,"gravity",980.0))
        ctx.emit("ctx.set_body_type(me, 'dynamic')")
        ctx.emit(f"ctx.set_gravity(me, {g})")
        ctx.emit(f"ctx.set_mass(me, {self.prop_value(node,'mass',1.0)!r})")
        ctx.emit(f"ctx.set_restitution(me, {self.prop_value(node,'bounce',0.15)!r})")
        ctx.emit(f"ctx.set_linear_damping(me, {self.prop_value(node,'damping',0.0)!r})")
        ctx.generate_exec_branch(node["id"],"",visited)

@register_node("physics_character_collision_response", "Physics", "Set Character Collision Response",
               "Choose Separate (default: blocks contact and consumes knockback without speed transfer), Reflect (each body bounces independently), or Transfer (physical momentum exchange; both characters must choose it).")
class CharacterCollisionResponseNode(NodeBase):
    properties = {"response": PropSpec("response", "dropdown", "separate", options=["separate", "reflect", "transfer"]),
                  "restitution": PropSpec("restitution", "number", 1.0, min_val=0.0, max_val=1.0),
                  "contact_recoil": PropSpec("contact_recoil", "number", 120.0, min_val=0.0)}
    inputs = [PinSpec("", EXEC), PinSpec("restitution", NUMBER, default=1.0), PinSpec("contact_recoil", NUMBER, default=120.0)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        r = self.input_expr(ctx, node, "restitution") if ctx.find_input_link(node["id"], "restitution") else repr(self.prop_value(node, "restitution", 1.0))
        recoil = self.input_expr(ctx, node, "contact_recoil") if ctx.find_input_link(node["id"], "contact_recoil") else repr(self.prop_value(node, "contact_recoil", 120.0))
        ctx.emit(f"ctx.set_character_collision_response(me, {self.prop_value(node, 'response', 'separate')!r}, {r}, {recoil})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("physics_set_collision_speed_inheritance", "Physics", "Set Collision Speed Inheritance",
               "Characters always bounce on contact. Inherit Speed OFF reflects using each body’s own speed; ON permits mass/restitution speed transfer. Lock To Min Speed keeps the reflected direction but forces ordinary contacts to that body’s min_speed. Active scripted knockback is never flattened.")
class CollisionSpeedInheritanceNode(NodeBase):
    properties = {"inherit_speed": PropSpec("inherit_speed", "boolean", False),
                  "lock_to_min_speed": PropSpec("lock_to_min_speed", "boolean", True)}
    inputs = [PinSpec("", EXEC), PinSpec("inherit_speed", BOOLEAN, default=False),
              PinSpec("lock_to_min_speed", BOOLEAN, default=True)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        inherit = self.input_expr(ctx, node, "inherit_speed") if ctx.find_input_link(node["id"], "inherit_speed") else repr(bool(self.prop_value(node, "inherit_speed", False)))
        lock = self.input_expr(ctx, node, "lock_to_min_speed") if ctx.find_input_link(node["id"], "lock_to_min_speed") else repr(bool(self.prop_value(node, "lock_to_min_speed", True)))
        ctx.emit(f"ctx.set_collision_speed_inheritance(me, {inherit}, {lock})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("physics_get_collision_speed_inheritance", "Physics", "Is Collision Speed Inherited",
               "True when this character currently allows speed/momentum transfer from character contacts.")
class GetCollisionSpeedInheritanceNode(NodeBase):
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("inheriting", BOOLEAN)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        target = self.object_input_expr(ctx, node, "target", "me")
        return f"ctx.get_collision_speed_inheritance({target})"

@register_node("physics_kinematic_body", "Physics", "Kinematic Body 2D", "Preset for a manually moved character body that is not pushed by gravity unless you enable it.")
class KinematicBodyPresetNode(NodeBase):
    inputs = [PinSpec("",EXEC)]
    outputs = [PinSpec("",EXEC)]
    def generate_code(self,ctx,node,visited):
        ctx.emit("ctx.set_body_type(me, 'kinematic')"); ctx.emit("ctx.disable_gravity(me)"); ctx.generate_exec_branch(node["id"],"",visited)

@register_node("physics_static_body", "Physics", "Static Body 2D", "Preset for an unmoving collision body.")
class StaticBodyPresetNode(NodeBase):
    inputs = [PinSpec("",EXEC)]
    outputs = [PinSpec("",EXEC)]
