@register_node("physics_character_body", "Physics", "Character Body 2D", "Preset for player-like movement: kinematic mode, manual input enabled, and floor-friendly motion.")
class CharacterBodyPresetNode(NodeBase):
    properties = {"gravity": PropSpec("gravity","number",980.0), "speed": PropSpec("speed","number",250.0), "jump": PropSpec("jump","number",400.0)}
    inputs = [PinSpec("",EXEC)]
    outputs = [PinSpec("",EXEC)]
    def generate_code(self,ctx,node,visited):
        ctx.emit("ctx.set_body_type(me, 'kinematic')")
        ctx.emit(f"ctx.set_gravity(me, {self.prop_value(node,'gravity',980.0)!r})")
        ctx.emit(f"me['manual_speed'] = {self.prop_value(node,'speed',250.0)!r}")
        ctx.emit(f"me['jump_force'] = {self.prop_value(node,'jump',400.0)!r}")
        ctx.generate_exec_branch(node["id"],"",visited)

@register_node("physics_kinematic_gravity", "Physics", "Kinematic Gravity Body",
               "Godot-style kinematic body for enemies / props (slime, crates): gravity pulls it down, it PLANTS on the floor with no bounce, and Stop on Ground kills all horizontal speed the instant it lands so it never slides. Falls and stays put.")
class KinematicGravityBodyNode(NodeBase):
    properties = {
        "gravity": PropSpec("gravity", "number", 980.0),
        "stop_on_ground": PropSpec("stop_on_ground", "boolean", True),
        "floor_friction": PropSpec("floor_friction", "number", 0.8, min_val=0.0, max_val=1.0),
    }
    inputs = [PinSpec("", EXEC), PinSpec("gravity", NUMBER, default=980.0)]
    outputs = [PinSpec("", EXEC), PinSpec("grounded", BOOLEAN)]
    def generate_code(self, ctx, node, visited):
        g = self.input_expr(ctx, node, "gravity") if ctx.find_input_link(node["id"], "gravity") else repr(self.prop_value(node, "gravity", 980.0))
        ctx.emit("ctx.set_body_type(me, 'kinematic')")
        ctx.emit(f"ctx.set_gravity(me, {g})")
        ctx.emit("ctx.set_restitution(me, 0.0)")
        ctx.emit(f"me['ground_friction'] = max(0.0, min(1.0, float({self.prop_value(node,'floor_friction',0.8)!r})))")
        ctx.emit(f"me['stop_on_ground'] = bool({self.prop_value(node,'stop_on_ground',True)!r})")
        ctx.expr_cache[(node["id"], "grounded")] = "bool(me.get('gravity_grounded', False))"
        ctx.generate_exec_branch(node["id"], "", visited)
    def generate_output_expr(self, ctx, node, output_name):
        return ctx.expr_cache.get((node["id"], "grounded"), "bool(me.get('gravity_grounded', False))")

@register_node("physics_is_grounded", "Physics", "Is On Ground?",
               "True while the character is touching the floor (a gravity/kinematic body that "
               "has landed). Drop in on_tick, wire into If/Else, and branch grounded vs in-air "
               "animation states. Pairs with Earth/Moon/Character/Kinematic Gravity bodies.")
class IsGroundedNode(NodeBase):
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("grounded", BOOLEAN)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        target = self.object_input_expr(ctx, node, "target", "me")
        return f"bool(({target}).get('gravity_grounded', False))"

