# ══════════════════════════════════════════════════════════════════════════
# VISUAL SCRIPTER — PARTICLE EFFECT NODE FAMILY
# ══════════════════════════════════════════════════════════════════════════
# The original six `pe_*` catalog entries are kept for compatibility. This is
# the full authoring surface: presets can be typed OR selected, emitters can be
# referenced directly, and every node delegates to Ctx.particle_op so runtime
# behavior, saves, budget handling, and the particle editor all agree.

class _ParticlePresetOptions:
    """Live dropdown of built-in and saved `custom:` particle presets."""
    _stamp = [0.0]
    _cache = [["sparks"]]
    @classmethod
    def _items(cls):
        now = time.monotonic()
        if now - cls._stamp[0] > 0.35:
            try:
                cls._cache[0] = Ctx.particle_preset_names() or ["sparks"]
            except Exception:
                cls._cache[0] = sorted(PE_PRESETS) or ["sparks"]
            cls._stamp[0] = now
        return cls._cache[0]
    def __iter__(self): return iter(self._items())
    def __len__(self): return len(self._items())
    def __getitem__(self, i): return self._items()[i]
    def __contains__(self, value): return value in self._items()
    def __repr__(self): return repr(list(self._items()))
    def index(self, value): return self._items().index(value)

class _ParticleEmitterOptions:
    """Direct picker references. `#id` is stable even when names duplicate."""
    _stamp = [0.0]
    _cache = [[""]]
    @classmethod
    def _items(cls):
        now = time.monotonic()
        if now - cls._stamp[0] > 0.25:
            try:
                cls._cache[0] = [""] + [f"#{int(e.get('id', 0))} · {pe_display_name(e)}"
                                       for e in particle_emitters]
            except Exception:
                cls._cache[0] = [""]
            cls._stamp[0] = now
        return cls._cache[0]
    def __iter__(self): return iter(self._items())
    def __len__(self): return len(self._items())
    def __getitem__(self, i): return self._items()[i]
    def __contains__(self, value): return value in self._items()
    def __repr__(self): return repr(list(self._items()))
    def index(self, value): return self._items().index(value)

# Pickers are deliberately tiny pure nodes. They turn selection into ordinary
# values, so every action still accepts a typed string for projects imported
# from text or generated at runtime.
@register_node("particle_preset_picker", "Particle FX", "Particle Preset",
               "Choose an effect directly from the live particle preset shelf. You may instead type any preset name into a Particle node's Preset property/pin.")
class ParticlePresetPickerNode(NodeBase):
    properties = {"preset": PropSpec("preset", "dropdown", "sparks", options=_ParticlePresetOptions())}
    inputs = []
    outputs = [PinSpec("preset", STRING)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        return repr(str(self.prop_value(node, "preset", "sparks")))

@register_node("particle_emitter_picker", "Particle FX", "Particle Emitter Reference",
               "Reference an emitter two ways: wire the grey emitter output of a Spawn/Create "
               "Particle node into this node's emitter INPUT to pass that exact spawned emitter "
               "along (a named handle you can route to Destroy/Modify nodes anywhere in the graph), "
               "or leave the input unwired and choose a live emitter from the dropdown / type a "
               "name or numeric ID. A wired input always wins over the dropdown.")
class ParticleEmitterPickerNode(NodeBase):
    properties = {"emitter": PropSpec("emitter", "dropdown", "", options=_ParticleEmitterOptions())}
    inputs = [PinSpec("emitter", ANY, default=None,
                      tooltip="Optional: wire a Spawn Particle node's grey emitter output here to reference that exact emitter. Overrides the dropdown.")]
    outputs = [PinSpec("emitter", ANY, tooltip="The referenced emitter — wire into Destroy Particle Emitter or any other Particle node's emitter pin.")]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        if ctx.find_input_link(node["id"], "emitter"):
            wired = self.input_expr(ctx, node, "emitter")
            # Fall back to the dropdown if the wired value is empty/None at runtime.
            return f"(({wired}) if ({wired}) not in (None, '') else {str(self.prop_value(node, 'emitter', ''))!r})"
        return repr(str(self.prop_value(node, "emitter", "")))

