_PARTICLE_PIN_TYPES = {"string": STRING, "number": NUMBER, "bool": BOOLEAN,
                       "vector": VECTOR, "object": OBJECT, "color": COLOR,
                       "emitter": ANY, "any": ANY}
_PARTICLE_DROPDOWNS = {
    "preset": _ParticlePresetOptions(), "touch_preset": _ParticlePresetOptions(), "emitter": _ParticleEmitterOptions(),
    "anchor": _RigAnchorOptions(), "clip": _MotionClipOptions(),
    "mode": ["continuous", "burst"], "draw_layer": ["front", "behind"],
    "shape": list(PE_SHAPES), "render": list(PE_RENDERS), "blend": list(PE_BLENDS),
    "motion": ["damping", "orbit", "turbulence", "inherit_velocity", "follow_strength"],
    "attractor_mode": ["pull", "push", "orbit"],
}

def _particle_prop_spec(name, typ, default):
    if typ in ("object", "vector", "emitter", "any"):
        return None
    if typ == "bool":
        return PropSpec(name, "boolean", default)
    if typ == "number":
        return PropSpec(name, "number", default)
    if typ == "color":
        return PropSpec(name, "color", default)
    options = _PARTICLE_DROPDOWNS.get(name)
    if options is not None:
        return PropSpec(name, "dropdown", default, options=options)
    return PropSpec(name, "string", default)

def _register_particle_fx_node(key, category, title, description, op, fields=(), value_type=None, result=False):
    """Register an action/value node around the shared particle operation API.

    `fields` entries are (name, kind, default). Generated classes keep every
    scalar editable in the inspector and every value wireable; a pin wins over
    the property, exactly like the rest of the visual scripter.
    """
    props = {}
    inputs = [] if value_type else [PinSpec("", EXEC)]
    for fname, fkind, default in fields:
        inputs.append(PinSpec(fname, _PARTICLE_PIN_TYPES[fkind], default=default))
        spec = _particle_prop_spec(fname, fkind, default)
        if spec is not None:
            props[fname] = spec
    outputs = [PinSpec("value", _PARTICLE_PIN_TYPES[value_type])] if value_type else [PinSpec("", EXEC)]
    if result:
        outputs.append(PinSpec("emitter", ANY, tooltip="The created/updated emitter; wire directly into another Particle node."))

    def _kwargs(self, ctx, node):
        args = []
        for fname, fkind, default in fields:
            if ctx.find_input_link(node["id"], fname):
                expr = self.input_expr(ctx, node, fname)
            elif fname in props:
                expr = repr(self.prop_value(node, fname, default))
            else:
                expr = repr(default)
            args.append(f"{fname}={expr}")
        return ", ".join(args)

    if value_type:
        def generate_output_expr(self, ctx, node, pin_name):
            return f"ctx.particle_value({op!r}, me, {_kwargs(self, ctx, node)})"
        attrs = {"properties": props, "inputs": inputs, "outputs": outputs, "pure": True,
                 "generate_output_expr": generate_output_expr}
    else:
        def generate_code(self, ctx, node, visited):
            args = _kwargs(self, ctx, node)
            if result:
                var = ctx.fresh_var("particle")
                ctx.emit(f"{var} = ctx.particle_op({op!r}, me{', ' if args else ''}{args})")
                # Persist EVERY emitter id this node creates on the owner —
                # not just the latest. The local variable only exists in THIS
                # hook body, and a Destroy/Modify node reached through a
                # Delay/Fuse callback (its own function) or any later frame
                # could never see it, which made "spawn → timer → destroy"
                # silently do nothing. Storing one id per node ALSO broke any
                # spawn that ran repeatedly (a trail spawned once per
                # projectile): each run overwrote the previous id, so a later
                # Destroy only ever reached the NEWEST trail and every older
                # sibling leaked. The list is read back as a multi-reference
                # by Ctx.get_emitters; destroyed ids are pruned and the list
                # is capped so a rapid spawn stream cannot grow it forever.
                # Defensive normalization: a graph recompiled onto a character
                # that already ran an OLD-version script may find a bare int
                # (or None) stored at this key. Coerce to a list — keeping the
                # old int as the first entry so that emitter stays reachable —
                # before any `in`/append/remove list operations run.
                ctx.emit(f"_ns_pmap_{node['id']} = me.get('_ns_particle_refs')")
                ctx.emit(f"if not isinstance(_ns_pmap_{node['id']}, dict): _ns_pmap_{node['id']} = me['_ns_particle_refs'] = {{}}")
                ctx.emit(f"_ns_refs_{node['id']} = _ns_pmap_{node['id']}.setdefault({node['id']!r}, [])")
                ctx.emit(f"if not isinstance(_ns_refs_{node['id']}, list): _ns_refs_{node['id']} = _ns_pmap_{node['id']}[{node['id']!r}] = ([_ns_refs_{node['id']}] if isinstance(_ns_refs_{node['id']}, int) else [])")
                ctx.emit(f"_ns_eid_{node['id']} = {var}.get('id') if isinstance({var}, dict) else None")
                ctx.emit(f"if _ns_eid_{node['id']} is not None:")
                ctx.push_indent()
                ctx.emit(f"if _ns_eid_{node['id']} in _ns_refs_{node['id']}: _ns_refs_{node['id']}.remove(_ns_eid_{node['id']})")
                ctx.emit(f"_ns_refs_{node['id']}.append(_ns_eid_{node['id']})")
                ctx.emit(f"del _ns_refs_{node['id']}[:-64]")
                ctx.pop_indent()
                ctx.expr_cache[(node["id"], "emitter")] = var
            else:
                ctx.emit(f"ctx.particle_op({op!r}, me{', ' if args else ''}{args})")
            ctx.generate_exec_branch(node["id"], "", visited)
        def generate_output_expr(self, ctx, node, pin_name):
            # Same-scope consumers get the live emitter dict; consumers in a
            # delayed callback / later frame resolve the stored emitter ids.
            # The helper tolerates old-format values (a bare int/None stored
            # by pre-12.69.1 scripts) and always returns a list.
            return ctx.expr_cache.get((node["id"], "emitter"),
                                      f"ctx.stored_particle_refs(me, {node['id']!r})")
        attrs = {"properties": props, "inputs": inputs, "outputs": outputs,
                 "generate_code": generate_code, "generate_output_expr": generate_output_expr}
    cls = type("Particle_" + key.replace("particle_", "").title().replace("_", ""), (NodeBase,), attrs)
    register_node(key, category, title, description)(cls)

# Field shorthand makes this broad surface auditable instead of 60 copy-pasted
