("command_disable", "Disable Command", "Disable a named command.", "disable"),
("command_toggle", "Toggle Command", "Toggle a named command.", "toggle"),
("command_bind_key", "Bind Command Key", "Bind a command name to a key.", "bind"),
("command_unbind", "Unbind Command", "Remove a command binding.", "unbind"),
("command_fire", "Fire Command", "Fire a command immediately.", "fire"),
("command_sequence", "Command Sequence", "Advance a named command sequence.", "sequence"),
("command_repeat", "Command Repeat", "Store a command repeat count.", "repeat"),
("command_hold", "Command Hold", "Mark a command held.", "hold"),
