_catalog_action("command_toggle_value", "Control", "Command Toggle Value", "Toggle a numeric command between zero and one.", [PinSpec("name", STRING, default="action")], lambda s,c,n,v: f"me.setdefault('_command_values', {{}}).__setitem__(str({v['name']}), 0.0 if me.setdefault('_command_values', {{}}).get(str({v['name']}), 0.0) else 1.0)")
