# ---------- Audio Conditionals ----------

@register_node("audio_branch", "Audio", "Audio If / Else",
    "Branch audio execution based on a condition. Connect condition to boolean input, "
    "then different audio nodes to true/false outputs.")
class AudioBranchNode(NodeBase):
    properties = {}
    inputs = [
        PinSpec("", EXEC),
        PinSpec("condition", BOOLEAN, default=True, tooltip="True = play 'then' audio, False = play 'else' audio"),
    ]
    outputs = [
        PinSpec("then", EXEC, tooltip="Executes when condition is true"),
        PinSpec("else", EXEC, tooltip="Executes when condition is false"),
    ]
    
    def generate_code(self, ctx, node, visited):
        cond = self.input_expr(ctx, node, "condition") if ctx.find_input_link(node["id"], "condition") else "True"
        ctx.emit(f"if {cond}:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "then", visited)
        ctx.pop_indent()
        else_links = ctx.output_links(node["id"], "else")
        if else_links:
            ctx.emit("else:")
            ctx.push_indent()
            ctx.generate_exec_branch(node["id"], "else", visited)
            ctx.pop_indent()

@register_node("audio_condition_hp", "Audio", "HP Condition",
    "Check character HP and branch audio. Perfect for 'if HP > 50 play this, else play that'.")
class AudioHPConditionNode(NodeBase):
    properties = {
        "operation": PropSpec("operation", "dropdown", ">",
            options=[">", ">=", "<", "<=", "==", "!="]),
        "threshold": PropSpec("threshold", "number", 50, min_val=0, max_val=100,
            tooltip="HP percentage threshold (0-100)"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None, tooltip="Character to check (None = self)"),
        PinSpec("threshold", NUMBER, default=50, tooltip="Override threshold"),
    ]
    outputs = [
        PinSpec("true", EXEC, tooltip="Condition met"),
        PinSpec("false", EXEC, tooltip="Condition not met"),
        PinSpec("hp", NUMBER, tooltip="Current HP"),
        PinSpec("hp_pct", NUMBER, tooltip="HP percentage (0-100)"),
    ]
    
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        op = self.prop_value(node, "operation", ">")
        thresh = self.input_expr(ctx, node, "threshold") if ctx.find_input_link(node["id"], "threshold") else repr(self.prop_value(node, "threshold", 50))
        
        ctx.emit(f"_hp_pct = {t}[\"hp\"] / max(1, {t}[\"max_hp\"]) * 100")
        ctx.emit(f"_hp = {t}[\"hp\"]")
        ctx.expr_cache[(node["id"], "hp")] = "_hp"
        ctx.expr_cache[(node["id"], "hp_pct")] = "_hp_pct"
        
        ctx.emit(f"if _hp_pct {op} {thresh}:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "true", visited)
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "false", visited)
        ctx.pop_indent()

@register_node("audio_condition_distance", "Audio", "Distance Condition",
    "Check distance between two characters/objects for spatial audio logic.")
class AudioDistanceConditionNode(NodeBase):
    properties = {
        "operation": PropSpec("operation", "dropdown", "<",
            options=[">", ">=", "<", "<=", "=="]),
        "distance": PropSpec("distance", "number", 100, min_val=0, max_val=2000),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("a", OBJECT, default=None, tooltip="First object (None = self)"),
        PinSpec("b", OBJECT, default=None, tooltip="Second object"),
        PinSpec("distance", NUMBER, default=100, tooltip="Override distance"),
    ]
    outputs = [
        PinSpec("true", EXEC),
        PinSpec("false", EXEC),
        PinSpec("distance", NUMBER, tooltip="Actual distance"),
    ]
    
    def generate_code(self, ctx, node, visited):
        a = self.object_input_expr(ctx, node, "a", "me")
        b = self.object_input_expr(ctx, node, "b", "me")
        op = self.prop_value(node, "operation", "<")
        dist = self.input_expr(ctx, node, "distance") if ctx.find_input_link(node["id"], "distance") else repr(self.prop_value(node, "distance", 100))
        
        ctx.emit(f"_dist = {a}[\"pos\"].distance_to({b}[\"pos\"])")
        ctx.expr_cache[(node["id"], "distance")] = "_dist"
        
        ctx.emit(f"if _dist {op} {dist}:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "true", visited)
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "false", visited)
        ctx.pop_indent()

@register_node("audio_condition_status", "Audio", "Status Condition",
    "Check if character has a specific status effect (stun, poison, burn, etc.).")
class AudioStatusConditionNode(NodeBase):
    properties = {
        "status": PropSpec("status", "string", "stun",
            tooltip="Status to check for"),
        "invert": PropSpec("invert", "boolean", False,
            tooltip="True = branch when status is NOT present"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("status", STRING, default="stun"),
    ]
    outputs = [
        PinSpec("true", EXEC),
        PinSpec("false", EXEC),
    ]
    
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        status = self.input_expr(ctx, node, "status") if ctx.find_input_link(node["id"], "status") else repr(self.prop_value(node, "status", "stun"))
        invert = self.prop_value(node, "invert", False)
        
        ctx.emit(f"_has = {t}.get(\"_ns_statuses\", {{}}).get({status}, 0) > time.time()")
