        ctx.generate_exec_branch(node["id"], "success", visited)
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "fail", visited)
        ctx.pop_indent()

