@register_node("audio_sequence", "Audio", "Audio Sequence",
    "Play multiple audio cues in sequence with configurable delays between each. "
    "Great for combo sounds, multi-hit effects, or layered sequences.")
class AudioSequenceNode(NodeBase):
    properties = {
        "count": PropSpec("count", "number", 3, min_val=2, max_val=16,
            tooltip="Number of steps in sequence"),
        "loop": PropSpec("loop", "boolean", False,
            tooltip="Loop the entire sequence"),
        "loop_delay": PropSpec("loop_delay", "number", 0.0, min_val=0.0, max_val=10.0,
            tooltip="Delay before restarting loop"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
    ]
    outputs = [
        PinSpec("", EXEC, tooltip="After sequence completes"),
        PinSpec("step", EXEC, tooltip="Fires for each step (connect to Play Audio)"),
        PinSpec("index", NUMBER, tooltip="Current step index"),
        PinSpec("completed", EXEC, tooltip="When sequence finishes (if not looping)"),
    ]
    
    def generate_code(self, ctx, node, visited):
        count = int(self.prop_value(node, "count", 3))
        loop = self.prop_value(node, "loop", False)
        loop_delay = self.prop_value(node, "loop_delay", 0.0)
        _t = self.object_input_expr(ctx, node, "target", "me")
        
        idx_var = ctx.fresh_var("idx")
        timer_var = ctx.fresh_var("timer")
        active_var = ctx.fresh_var("active")
        step_var = ctx.fresh_var("step_active")
        
        ctx.emit(f"{active_var} = True")
        ctx.emit(f"{timer_var} = 0.0")
        ctx.emit(f"{idx_var} = 0")
        ctx.emit(f"{step_var} = False")
        
        # Generate step data from connected inputs
        steps = []
        for i in range(count):
            cue_pin = f"cue_{i}"
            delay_pin = f"delay_{i}" if i < count - 1 else None
            
            cue_link = ctx.find_input_link(node["id"], cue_pin)
            cue = ctx.get_input_expr(node["id"], cue_pin) if cue_link else repr(f"step_{i}")
            
            delay = 0.2
            if delay_pin:
                delay_link = ctx.find_input_link(node["id"], delay_pin)
                delay = ctx.get_input_expr(node["id"], delay_pin) if delay_link else "0.2"
            
            steps.append((cue, delay))
        
        step_data_var = ctx.fresh_var("seq")
        ctx.emit(f"{step_data_var} = [")
        for cue, delay in steps:
            ctx.emit(f"    ({cue}, {delay}),")
        ctx.emit("]")
        
        ctx.emit("while True:")
        ctx.push_indent()
        ctx.emit(f"if not {active_var}:")
        ctx.emit("    break")
        ctx.emit(f"{timer_var} += dt")
        ctx.emit(f"if {idx_var} < len({step_data_var}):")
        ctx.push_indent()
        ctx.emit(f"cue_name, step_delay = {step_data_var}[{idx_var}]")
        ctx.emit(f"{step_var} = True")
        ctx.expr_cache[(node["id"], "index")] = idx_var
        ctx.generate_exec_branch(node["id"], "step", visited)
        ctx.emit(f"{step_var} = False")
        ctx.emit(f"{timer_var} = 0.0")
        ctx.emit(f"{idx_var} += 1")
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        if loop:
            ctx.emit(f"{idx_var} = 0")
            if loop_delay > 0:
                ctx.emit(f"{timer_var} = -{loop_delay}")
        else:
            ctx.emit(f"{active_var} = False")
            ctx.generate_exec_branch(node["id"], "completed", visited)
        ctx.pop_indent()
        ctx.pop_indent()
        
        ctx.generate_exec_branch(node["id"], "", visited)

# ---------- Audio Randomization ----------

@register_node("audio_random", "Audio", "Audio Random Pick",
    "Randomly select one audio cue from a list. Supports weighted random selection. "
    "Perfect for footstep variations, impact variations, etc.")
class AudioRandomNode(NodeBase):
    properties = {
        "count": PropSpec("count", "number", 4, min_val=2, max_val=16,
            tooltip="Number of audio options"),
        "weighted": PropSpec("weighted", "boolean", False,
            tooltip="Use weights for each option (requires weight inputs)"),
        "no_repeat": PropSpec("no_repeat", "boolean", True,
            tooltip="Don't pick the same option twice in a row"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
    ]
    outputs = [
        PinSpec("", EXEC, tooltip="After picking"),
        PinSpec("cue", STRING, tooltip="Selected cue name"),
        PinSpec("index", NUMBER, tooltip="Selected index"),
        PinSpec("pick", EXEC, tooltip="Fires once with selected cue (connect Play Audio)"),
    ]
    
    def generate_code(self, ctx, node, visited):
        count = int(self.prop_value(node, "count", 4))
        weighted = self.prop_value(node, "weighted", False)
        no_repeat = self.prop_value(node, "no_repeat", True)
        t = self.object_input_expr(ctx, node, "target", "me")
        
        options_var = ctx.fresh_var("opts")
        weights_var = ctx.fresh_var("wts")
        last_var = ctx.fresh_var("last")
        pick_var = ctx.fresh_var("pick")
        idx_var = ctx.fresh_var("idx")
        
        ctx.emit(f"{options_var} = [")
        for i in range(count):
            pin = f"option_{i}"
            link = ctx.find_input_link(node["id"], pin)
            opt = ctx.get_input_expr(node["id"], pin) if link else repr(f"option_{i}")
            ctx.emit(f"    {opt},")
        ctx.emit("]")
        
        if weighted:
            ctx.emit(f"{weights_var} = [")
            for i in range(count):
                pin = f"weight_{i}"
                link = ctx.find_input_link(node["id"], pin)
                wt = ctx.get_input_expr(node["id"], pin) if link else "1.0"
                ctx.emit(f"    {wt},")
            ctx.emit("]")
        else:
            ctx.emit(f"{weights_var} = None")
        
        ctx.emit(f"{last_var} = getattr({t}, '_last_audio_pick', -1)")
        
        if weighted:
            ctx.emit("import random")
            ctx.emit(f"total = sum({weights_var})")
            ctx.emit("r = random.uniform(0, total)")
            ctx.emit("upto = 0")
            ctx.emit(f"{idx_var} = 0")
            ctx.emit(f"for i, w in enumerate({weights_var}):")
            ctx.push_indent()
            if no_repeat:
                ctx.emit(f"if i == {last_var}:")
                ctx.emit("    upto += w")
                ctx.emit("    continue")
            ctx.emit("if upto + w >= r:")
            ctx.emit(f"    {idx_var} = i")
            ctx.emit("    break")
            ctx.emit("upto += w")
            ctx.pop_indent()
        else:
            if no_repeat and count > 1:
                ctx.emit(f"choices = [i for i in range(len({options_var})) if i != {last_var}]")
                ctx.emit(f"{idx_var} = random.choice(choices)")
            else:
                ctx.emit(f"{idx_var} = random.randrange(len({options_var}))")
        
        ctx.emit(f"{pick_var} = {options_var}[{idx_var}]")
        ctx.emit(f"{t}._last_audio_pick = {idx_var}")
        
        ctx.expr_cache[(node["id"], "cue")] = pick_var
        ctx.expr_cache[(node["id"], "index")] = idx_var
        
        ctx.generate_exec_branch(node["id"], "pick", visited)
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("audio_shuffle", "Audio", "Audio Shuffle Bag",
    "Shuffle bag / bag of holding pattern: picks all options before repeating. "
    "Ensures even distribution without immediate repeats.")
class AudioShuffleBagNode(NodeBase):
    properties = {
        "count": PropSpec("count", "number", 4, min_val=2, max_val=16,
            tooltip="Number of audio options"),
        "refill_early": PropSpec("refill_early", "boolean", False,
            tooltip="Refill bag when 1 item left (vs empty)"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
    ]
    outputs = [
        PinSpec("", EXEC),
        PinSpec("cue", STRING),
        PinSpec("index", NUMBER),
        PinSpec("pick", EXEC),
        PinSpec("bag_remaining", NUMBER, tooltip="Items left in current bag"),
    ]
    
    def generate_code(self, ctx, node, visited):
        count = int(self.prop_value(node, "count", 4))
        t = self.object_input_expr(ctx, node, "target", "me")
        
        options_var = ctx.fresh_var("opts")
        bag_var = ctx.fresh_var("bag")
        pick_var = ctx.fresh_var("pick")
        idx_var = ctx.fresh_var("idx")
        remaining_var = ctx.fresh_var("rem")
        
        ctx.emit(f"{options_var} = [")
        for i in range(count):
            pin = f"option_{i}"
            link = ctx.find_input_link(node["id"], pin)
            opt = ctx.get_input_expr(node["id"], pin) if link else repr(f"option_{i}")
            ctx.emit(f"    {opt},")
        ctx.emit("]")
        
        bag_attr = "_audio_shuffle_bag"
        ctx.emit(f"if not hasattr({t}, {bag_attr!r}) or not getattr({t}, {bag_attr!r}):")
        ctx.push_indent()
        ctx.emit("import random")
        ctx.emit(f"bag = list(range(len({options_var})))")
        ctx.emit("random.shuffle(bag)")
        ctx.emit(f"{t}.{bag_attr} = bag")
        ctx.pop_indent()
        
        ctx.emit(f"{bag_var} = {t}.{bag_attr}")
        ctx.emit(f"{remaining_var} = len({bag_var})")
        ctx.expr_cache[(node["id"], "bag_remaining")] = remaining_var
        
        ctx.emit(f"{idx_var} = {bag_var}.pop()")
        ctx.emit(f"{pick_var} = {options_var}[{idx_var}]")
        
        ctx.expr_cache[(node["id"], "cue")] = pick_var
        ctx.expr_cache[(node["id"], "index")] = idx_var
        
        ctx.emit(f"if not {bag_var}:")
        ctx.push_indent()
        ctx.emit("import random")
        ctx.emit(f"bag = list(range(len({options_var})))")
        ctx.emit("random.shuffle(bag)")
        ctx.emit(f"{t}.{bag_attr} = bag")
        ctx.pop_indent()
        
        ctx.generate_exec_branch(node["id"], "pick", visited)
        ctx.generate_exec_branch(node["id"], "", visited)

# ---------- Audio Layering / Mixing ----------

@register_node("audio_layer", "Audio", "Audio Layer",
    "Play multiple audio cues simultaneously. Each layer has independent volume, pitch, "
    "and spatial settings. Great for impact sounds: layer a 'thud' with a 'crack'.")
class AudioLayerNode(NodeBase):
    properties = {
        "count": PropSpec("count", "number", 3, min_val=2, max_val=8,
            tooltip="Number of layers"),
        "stagger": PropSpec("stagger", "number", 0.0, min_val=0.0, max_val=1.0,
            tooltip="Random delay per layer (0-1 seconds) for natural variation"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
    ]
    outputs = [
        PinSpec("", EXEC, tooltip="After all layers start"),
        PinSpec("channels", OBJECT, tooltip="List of channel handles"),
        PinSpec("layer", EXEC, tooltip="Fires per layer (for custom per-layer logic)"),
    ]
    
    def generate_code(self, ctx, node, visited):
        count = int(self.prop_value(node, "count", 3))
        stagger = self.prop_value(node, "stagger", 0.0)
        t = self.object_input_expr(ctx, node, "target", "me")
        
        channels_var = ctx.fresh_var("chans")
        _layer_var = ctx.fresh_var("layer")
        
        ctx.emit(f"{channels_var} = []")
        
        for i in range(count):
            cue_pin = f"cue_{i}"
            vol_pin = f"volume_{i}"
            pitch_pin = f"pitch_{i}"
            rand_pin = f"pitch_random_{i}"
            
            cue_link = ctx.find_input_link(node["id"], cue_pin)
            cue = ctx.get_input_expr(node["id"], cue_pin) if cue_link else repr(f"layer_{i}")
            
            vol = "1.0"
            vol_link = ctx.find_input_link(node["id"], vol_pin)
            if vol_link:
                vol = ctx.get_input_expr(node["id"], vol_pin)
            
            pitch = "1.0"
            pitch_link = ctx.find_input_link(node["id"], pitch_pin)
            if pitch_link:
                pitch = ctx.get_input_expr(node["id"], pitch_pin)
            
            pitch_rand = "0.0"
            rand_link = ctx.find_input_link(node["id"], rand_pin)
            if rand_link:
                pitch_rand = ctx.get_input_expr(node["id"], rand_pin)
            
            ctx.emit(f"_pitch_{i} = {pitch}")
            if pitch_rand != "0.0":
                ctx.emit(f"if {pitch_rand} > 0:")
                ctx.emit(f"    _pitch_{i} *= random.uniform(1 - {pitch_rand}, 1 + {pitch_rand})")
            
            if stagger > 0:
                ctx.emit(f"_delay_{i} = random.uniform(0, {stagger})")
                ctx.emit(f"def _play_layer_{i}():")
                ctx.push_indent()
                ctx.emit(f"ch = ctx.play_audio_cue({t}, {cue}, {vol}, _pitch_{i})")
                ctx.emit(f"{channels_var}.append(ch)")
                ctx.pop_indent()
                ctx.emit(f"ctx.schedule(_delay_{i}, _play_layer_{i})")
            else:
                ctx.emit(f"ch = ctx.play_audio_cue({t}, {cue}, {vol}, _pitch_{i})")
                ctx.emit(f"{channels_var}.append(ch)")
            
            ctx.expr_cache[(node["id"], f"layer_{i}_channel")] = "ch"
            ctx.generate_exec_branch(node["id"], "layer", visited)
        
        ctx.expr_cache[(node["id"], "channels")] = channels_var
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("audio_crossfade", "Audio", "Audio Crossfade",
    "Smoothly crossfade between two audio cues. Useful for music transitions, "
    "or blending between combat states.")
class AudioCrossfadeNode(NodeBase):
    properties = {
        "duration": PropSpec("duration", "number", 1.0, min_val=0.1, max_val=10.0,
            tooltip="Crossfade time in seconds"),
        "curve": PropSpec("curve", "dropdown", "linear",
            options=["linear", "ease_in", "ease_out", "ease_in_out"],
            tooltip="Fade curve shape"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("from_cue", STRING, default="", tooltip="Cue to fade out"),
        PinSpec("to_cue", STRING, default="", tooltip="Cue to fade in"),
        PinSpec("from_volume", NUMBER, default=1.0),
        PinSpec("to_volume", NUMBER, default=1.0),
        PinSpec("duration", NUMBER, default=1.0),
    ]
    outputs = [
        PinSpec("", EXEC, tooltip="After crossfade starts"),
        PinSpec("from_channel", OBJECT),
        PinSpec("to_channel", OBJECT),
        PinSpec("progress", NUMBER, tooltip="Crossfade progress 0-1"),
        PinSpec("completed", EXEC, tooltip="When crossfade finishes"),
    ]
    
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        dur = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 1.0))
        curve = self.prop_value(node, "curve", "linear")
        
        from_cue = self.input_expr(ctx, node, "from_cue") if ctx.find_input_link(node["id"], "from_cue") else '""'
        to_cue = self.input_expr(ctx, node, "to_cue") if ctx.find_input_link(node["id"], "to_cue") else '""'
        from_vol = self.input_expr(ctx, node, "from_volume") if ctx.find_input_link(node["id"], "from_volume") else "1.0"
        to_vol = self.input_expr(ctx, node, "to_volume") if ctx.find_input_link(node["id"], "to_volume") else "1.0"
        
        from_ch = ctx.fresh_var("from_ch")
        to_ch = ctx.fresh_var("to_ch")
        prog_var = ctx.fresh_var("prog")
        timer_var = ctx.fresh_var("timer")
        active_var = ctx.fresh_var("active")
        
        ctx.emit(f"{from_ch} = ctx.play_audio_cue({t}, {from_cue}, {from_vol}) if {from_cue} else None")
        ctx.emit(f"{to_ch} = ctx.play_audio_cue({t}, {to_cue}, 0.0) if {to_cue} else None")
        ctx.emit(f"if {to_ch}: ctx.set_audio_volume({to_ch}, 0.0, 0.0)")
        ctx.emit(f"{timer_var} = 0.0")
        ctx.emit(f"{active_var} = True")
        ctx.emit(f"{prog_var} = 0.0")
        
        ctx.expr_cache[(node["id"], "from_channel")] = from_ch
        ctx.expr_cache[(node["id"], "to_channel")] = to_ch
        ctx.expr_cache[(node["id"], "progress")] = prog_var
        
        ctx.emit("while True:")
        ctx.push_indent()
        ctx.emit(f"if not {active_var}: break")
        ctx.emit(f"{timer_var} += dt")
        ctx.emit(f"{prog_var} = min(1.0, {timer_var} / {dur})")
        
        if curve == "ease_in":
            ctx.emit(f"_eased = {prog_var} * {prog_var}")
        elif curve == "ease_out":
            ctx.emit(f"_eased = 1 - (1 - {prog_var}) ** 2")
        elif curve == "ease_in_out":
            ctx.emit(f"_eased = 3 * {prog_var}**2 - 2 * {prog_var}**3")
        else:
            ctx.emit(f"_eased = {prog_var}")
        
        ctx.emit(f"if {from_ch}: ctx.set_audio_volume({from_ch}, {from_vol} * (1 - _eased), 0.0)")
        ctx.emit(f"if {to_ch}: ctx.set_audio_volume({to_ch}, {to_vol} * _eased, 0.0)")
        
        ctx.emit(f"if {prog_var} >= 1.0:")
        ctx.push_indent()
        ctx.emit(f"{active_var} = False")
        ctx.emit(f"if {from_ch}: ctx.stop_audio({from_ch}, 0.1)")
        ctx.generate_exec_branch(node["id"], "completed", visited)
        ctx.pop_indent()
        ctx.pop_indent()
        
        ctx.generate_exec_branch(node["id"], "", visited)

# ---------- Audio Parameters / Modulation ----------

@register_node("audio_param_pitch", "Audio", "Pitch Parameter",
    "Generate a pitch value with randomization. Can be driven by game state "
    "(speed, HP, combo count, etc.) for dynamic pitch.")
class AudioPitchParamNode(NodeBase):
    properties = {
        "base": PropSpec("base", "number", 1.0, min_val=0.1, max_val=4.0),
        "random": PropSpec("random", "number", 0.0, min_val=0.0, max_val=1.0),
        "speed_factor": PropSpec("speed_factor", "number", 0.0, min_val=0.0, max_val=2.0,
            tooltip="Multiply pitch by character speed / max_speed"),
        "hp_factor": PropSpec("hp_factor", "number", 0.0, min_val=-1.0, max_val=1.0,
            tooltip="Modify pitch based on HP % (negative = lower when hurt)"),
    }
    inputs = [
        PinSpec("target", OBJECT, default=None),
        PinSpec("base", NUMBER, default=1.0),
        PinSpec("random", NUMBER, default=0.0),
        PinSpec("speed_factor", NUMBER, default=0.0),
        PinSpec("hp_factor", NUMBER, default=0.0),
    ]
    outputs = [PinSpec("pitch", NUMBER)]
    pure = True
    
    def generate_output_expr(self, ctx, node, pin_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        
        base = self.input_expr(ctx, node, "base") if ctx.find_input_link(node["id"], "base") else repr(self.prop_value(node, "base", 1.0))
        rand = self.input_expr(ctx, node, "random") if ctx.find_input_link(node["id"], "random") else repr(self.prop_value(node, "random", 0.0))
        speed_f = self.input_expr(ctx, node, "speed_factor") if ctx.find_input_link(node["id"], "speed_factor") else repr(self.prop_value(node, "speed_factor", 0.0))
        hp_f = self.input_expr(ctx, node, "hp_factor") if ctx.find_input_link(node["id"], "hp_factor") else repr(self.prop_value(node, "hp_factor", 0.0))
        
        expr = f"{base}"
        if speed_f != "0.0":
            expr = f"({expr}) * (1 + ({t}[\"vel\"].length() / max(1, {t}.get(\"speed\", 150))) * {speed_f})"
        if hp_f != "0.0":
            expr = f"({expr}) * (1 + ({t}[\"hp\"] / max(1, {t}[\"max_hp\"]) - 0.5) * 2 * {hp_f})"
        if rand != "0.0":
            expr = f"({expr}) * random.uniform(1 - {rand}, 1 + {rand})"
        
        return f"max(0.1, min(4.0, {expr}))"

@register_node("audio_param_volume", "Audio", "Volume Parameter",
    "Generate a volume value with distance attenuation, HP scaling, etc.")
class AudioVolumeParamNode(NodeBase):
    properties = {
        "base": PropSpec("base", "number", 1.0, min_val=0.0, max_val=2.0),
        "distance_attenuation": PropSpec("distance_attenuation", "boolean", True,
            tooltip="Attenuate by distance from camera/player"),
        "hp_factor": PropSpec("hp_factor", "number", 0.0, min_val=-1.0, max_val=1.0,
            tooltip="Louder/quieter based on HP"),
        "combo_factor": PropSpec("combo_factor", "number", 0.0, min_val=0.0, max_val=0.5,
            tooltip="Increase volume per combo hit"),
    }
    inputs = [
        PinSpec("target", OBJECT, default=None),
        PinSpec("listener", OBJECT, default=None, tooltip="Listener for distance (None = camera)"),
        PinSpec("base", NUMBER, default=1.0),
        PinSpec("combo_count", NUMBER, default=1),
    ]
    outputs = [PinSpec("volume", NUMBER)]
    pure = True
    
    def generate_output_expr(self, ctx, node, pin_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        listener = self.object_input_expr(ctx, node, "listener", "None")
        
        base = self.input_expr(ctx, node, "base") if ctx.find_input_link(node["id"], "base") else repr(self.prop_value(node, "base", 1.0))
        hp_f = self.input_expr(ctx, node, "hp_factor") if ctx.find_input_link(node["id"], "hp_factor") else repr(self.prop_value(node, "hp_factor", 0.0))
        combo_f = self.input_expr(ctx, node, "combo_factor") if ctx.find_input_link(node["id"], "combo_factor") else repr(self.prop_value(node, "combo_factor", 0.0))
        combo_count = self.input_expr(ctx, node, "combo_count") if ctx.find_input_link(node["id"], "combo_count") else "1"
        
        expr = f"{base}"
        
        if self.prop_value(node, "distance_attenuation", True):
            if listener != "None":
                expr = f"({expr}) * max(0.1, 1.0 - min(1.0, {t}[\"pos\"].distance_to({listener}[\"pos\"]) / 800.0))"
            else:
                expr = f"({expr}) * max(0.1, 1.0 - min(1.0, {t}[\"pos\"].distance_to(camera[\"pos\"]) / 800.0))"
        
        if hp_f != "0.0":
            expr = f"({expr}) * (1 + ({t}[\"hp\"] / max(1, {t}[\"max_hp\"]) - 0.5) * 2 * {hp_f})"
        
        if combo_f != "0.0":
            expr = f"({expr}) * (1 + ({combo_count} - 1) * {combo_f})"
        
        return f"max(0.0, min(2.0, {expr}))"

# ---------- Audio State Machine ----------

@register_node("audio_state_machine", "Audio", "Audio State Machine",
    "Define audio behavior per character state (idle, attack, hit, death, etc.). "
    "Each state can have its own sound, pitch, volume, and transition rules.")
class AudioStateMachineNode(NodeBase):
    properties = {
        "states": PropSpec("states", "number", 4, min_val=1, max_val=12,
            tooltip="Number of states to define"),
        "default_state": PropSpec("default_state", "string", "idle",
            tooltip="Starting state name"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("state", STRING, default="idle", tooltip="Force state change"),
    ]
    outputs = [
        PinSpec("", EXEC),
        PinSpec("current_state", STRING),
        PinSpec("state_changed", EXEC, tooltip="Fires when state changes"),
    ]
    
    def generate_code(self, ctx, node, visited):
        count = int(self.prop_value(node, "states", 4))
        default = self.prop_value(node, "default_state", "idle")
        t = self.object_input_expr(ctx, node, "target", "me")
        
        state_var = ctx.fresh_var("aud_state")
        prev_var = ctx.fresh_var("prev_state")
        data_var = ctx.fresh_var("state_data")
        
        ctx.emit(f"{data_var} = {{}}")
        for i in range(count):
            name_pin = f"state_{i}_name"
            cue_pin = f"state_{i}_cue"
            vol_pin = f"state_{i}_volume"
            pitch_pin = f"state_{i}_pitch"
            loop_pin = f"state_{i}_loop"
            
            name_link = ctx.find_input_link(node["id"], name_pin)
            name = ctx.get_input_expr(node["id"], name_pin) if name_link else repr(f"state_{i}")
            
            cue_link = ctx.find_input_link(node["id"], cue_pin)
            cue = ctx.get_input_expr(node["id"], cue_pin) if cue_link else '""'
            
            vol = "1.0"
            if ctx.find_input_link(node["id"], vol_pin):
                vol = ctx.get_input_expr(node["id"], vol_pin)
            
            pitch = "1.0"
            if ctx.find_input_link(node["id"], pitch_pin):
                pitch = ctx.get_input_expr(node["id"], pitch_pin)
            
            loop = "False"
            if ctx.find_input_link(node["id"], loop_pin):
                loop = ctx.get_input_expr(node["id"], loop_pin)
            
            ctx.emit(f"{data_var}[{name}] = {{'cue': {cue}, 'volume': {vol}, 'pitch': {pitch}, 'loop': {loop}}}")
        
        ctx.emit(f"{state_var} = getattr({t}, '_audio_state', {default!r})")
        ctx.emit(f"{prev_var} = {state_var}")
        
        state_link = ctx.find_input_link(node["id"], "state")
        if state_link:
            forced = ctx.get_input_expr(node["id"], "state")
            ctx.emit(f"if {forced} and {forced} != {state_var}:")
            ctx.push_indent()
            ctx.emit(f"{prev_var} = {state_var}")
            ctx.emit(f"{state_var} = {forced}")
            ctx.emit(f"{t}._audio_state = {state_var}")
            ctx.generate_exec_branch(node["id"], "state_changed", visited)
            ctx.pop_indent()
        
        ctx.emit(f"if {state_var} in {data_var}:")
        ctx.push_indent()
        ctx.emit(f"sdata = {data_var}[{state_var}]")
        ctx.emit(f"if not getattr({t}, '_audio_channel', None) or {state_var} != {prev_var}:")
        ctx.push_indent()
        ctx.emit(f"if getattr({t}, '_audio_channel', None):")
        ctx.emit(f"    ctx.stop_audio({t}._audio_channel, 0.1)")
        ctx.emit(f"{t}._audio_channel = ctx.play_audio_cue({t}, sdata['cue'], sdata['volume'], sdata['pitch'], sdata['loop'])")
        ctx.emit(f"{t}._audio_state = {state_var}")
        ctx.pop_indent()
        ctx.pop_indent()
        
        ctx.expr_cache[(node["id"], "current_state")] = state_var
        ctx.generate_exec_branch(node["id"], "", visited)

# ---------- Audio Utility ----------

@register_node("audio_get_cue", "Audio", "Get Audio Cue",
    "Resolve an audio cue name from a character's audio_map. Returns the file path.")
class AudioGetCueNode(NodeBase):
    properties = {
        "fallback": PropSpec("fallback", "string", "",
            tooltip="Fallback cue name if primary not found"),
    }
    inputs = [
        PinSpec("target", OBJECT, default=None),
        PinSpec("cue", STRING, default="hit"),
        PinSpec("fallback", STRING, default=""),
    ]
    outputs = [
        PinSpec("path", STRING, tooltip="Resolved file path"),
        PinSpec("found", BOOLEAN, tooltip="Whether cue was found"),
    ]
    pure = True
    
    def generate_output_expr(self, ctx, node, pin_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        cue = self.input_expr(ctx, node, "cue") if ctx.find_input_link(node["id"], "cue") else repr(self.prop_value(node, "cue", "hit"))
        fallback = self.input_expr(ctx, node, "fallback") if ctx.find_input_link(node["id"], "fallback") else repr(self.prop_value(node, "fallback", ""))
        
        if pin_name == "path":
            return f"({t}.get('audio_map', {{}}).get({cue}) or {t}.get('audio_map', {{}}).get({fallback}) or '')"
        else:
            return f"bool({t}.get('audio_map', {{}}).get({cue}) or {t}.get('audio_map', {{}}).get({fallback}))"

@register_node("audio_list_cues", "Audio", "List Audio Cues",
    "Get all available audio cue names for a character. Useful for debugging or dynamic UIs.")
class AudioListCuesNode(NodeBase):
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("cues", OBJECT, tooltip="List of cue names")]
    pure = True
    
    def generate_output_expr(self, ctx, node, pin_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        return f"list({t}.get('audio_map', {{}}).keys())"

@register_node("audio_debug", "Audio", "Audio Debug",
    "Print audio debug info: playing channels, cue mappings, volume levels.")
class AudioDebugNode(NodeBase):
    properties = {
        "show_channels": PropSpec("show_channels", "boolean", True),
        "show_cues": PropSpec("show_cues", "boolean", True),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
    ]
    outputs = [PinSpec("", EXEC)]
    
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        show_ch = self.prop_value(node, "show_channels", True)
        show_cues = self.prop_value(node, "show_cues", True)
        
        ctx.emit(f"ctx.debug_print(f\"=== Audio Debug for {t}[\\\"name\\\"] ===\")")
        if show_cues:
            ctx.emit(f"ctx.debug_print(f\"Cues: {{list({t}.get('audio_map', {{}}).keys())}}\")")
        if show_ch:
            ctx.emit(f"ctx.debug_print(f\"Channel: {{getattr({t}, '_audio_channel', None)}}\")")
            ctx.emit(f"ctx.debug_print(f\"State: {{getattr({t}, '_audio_state', 'none')}}\")")
        
        ctx.generate_exec_branch(node["id"], "", visited)

