@register_node("audio_play_path", "Audio", "Play Audio From Path",
    "Play an audio file directly from a file path (bypasses character audio_map). Great for one-off sounds or when using Audio File Browser.")
class PlayAudioFromPathNode(NodeBase):
    properties = {
        "path": PropSpec("path", "string", "",
            tooltip="Type/paste project-relative path (used unless the path input is wired)"),
        "volume": PropSpec("volume", "number", 1.0, min_val=0.0, max_val=2.0, tooltip="Volume (0-2)"),
        "pitch": PropSpec("pitch", "number", 1.0, min_val=0.25, max_val=4.0, tooltip="Pitch multiplier"),
        "pitch_random": PropSpec("pitch_random", "number", 0.0, min_val=0.0, max_val=1.0,
            tooltip="Random pitch variation +/- this amount (e.g. 0.1 = +/-10%)"),
        "loop": PropSpec("loop", "boolean", False, tooltip="Loop the sound"),
        "spatial": PropSpec("spatial", "boolean", True, tooltip="Use 3D positional audio"),
        "falloff": PropSpec("falloff", "number", 1.0, min_val=0.0, max_val=2.0,
            tooltip="Distance falloff exponent (1=linear, 2=inverse square)"),
        "max_distance": PropSpec("max_distance", "number", 800.0, min_val=50.0, max_val=5000.0,
            tooltip="Max distance for spatial audio"),
        "audio_file": PropSpec("audio_file", "dropdown", "", 
            options=list_imported_audio() if "list_imported_audio" in globals() else [],
            tooltip="Select an audio file from the imported folder (overrides path input)"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("path", STRING, default="", tooltip="Relative path to audio file (e.g. audio/_imported/hit.wav)"),
        PinSpec("audio_file", STRING, default="", tooltip="Selected audio file from dropdown (overrides path)"),
        PinSpec("position", VECTOR, default=None, tooltip="World position (None = use target or camera)"),
        PinSpec("volume", NUMBER, default=1.0, tooltip="Override volume"),
        PinSpec("pitch", NUMBER, default=1.0, tooltip="Override pitch"),
        PinSpec("pitch_random", NUMBER, default=0.0, tooltip="Override pitch randomization"),
    ]
    outputs = [
        PinSpec("", EXEC, tooltip="After sound starts"),
        PinSpec("channel", OBJECT, tooltip="Audio channel handle (for stopping/fading)"),
        PinSpec("actual_pitch", NUMBER, tooltip="The pitch that was actually used"),
    ]
    
    def generate_code(self, ctx, node, visited):
        # Use audio_file dropdown if path input not connected
        if ctx.find_input_link(node["id"], "path"):
            path = self.input_expr(ctx, node, "path")
        else:
            # Check audio_file dropdown (connected or property)
            if ctx.find_input_link(node["id"], "audio_file"):
                path = self.input_expr(ctx, node, "audio_file")
            else:
                # A typed Path is intentionally supported: pins are connection-only
                # in the canvas, so the inspector needs an editable fallback.
                path = repr(self.prop_value(node, "path", "") or self.prop_value(node, "audio_file", ""))
        vol = self.input_expr(ctx, node, "volume") if ctx.find_input_link(node["id"], "volume") else repr(self.prop_value(node, "volume", 1.0))
        pitch = self.input_expr(ctx, node, "pitch") if ctx.find_input_link(node["id"], "pitch") else repr(self.prop_value(node, "pitch", 1.0))
        pitch_rand = self.input_expr(ctx, node, "pitch_random") if ctx.find_input_link(node["id"], "pitch_random") else repr(self.prop_value(node, "pitch_random", 0.0))
        spatial = self.prop_value(node, "spatial", True)
        loop = self.prop_value(node, "loop", False)
        falloff = self.prop_value(node, "falloff", 1.0)
        max_dist = self.prop_value(node, "max_distance", 800.0)
        pos = self.input_expr(ctx, node, "position") if ctx.find_input_link(node["id"], "position") else "None"
        
        channel_var = ctx.fresh_var("chan")
        actual_pitch_var = ctx.fresh_var("pitch")
        
        ctx.emit(f"{actual_pitch_var} = {pitch}")
        ctx.emit(f"if {pitch_rand} > 0:")
        ctx.emit(f"    {actual_pitch_var} *= random.uniform(1 - {pitch_rand}, 1 + {pitch_rand})")
        
        if spatial:
            ctx.emit(f"{channel_var} = ctx.play_audio_from_path({path}, {vol}, {actual_pitch_var}, {loop}, {falloff}, {max_dist}, {pos})")
        else:
            ctx.emit(f"{channel_var} = ctx.play_audio_from_path({path}, {vol}, {actual_pitch_var}, {loop}, 0.0, 0.0, {pos})")
        
        ctx.expr_cache[(node["id"], "channel")] = channel_var
        ctx.expr_cache[(node["id"], "actual_pitch")] = actual_pitch_var
        
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("target_hp_percent", "Targets", "Characters By HP %",
               "Filters or finds targets based on their remaining HP as a percentage of maximum.")
class TargetHPPercentNode(NodeBase):
    properties = {
        "operation": PropSpec("operation", "dropdown", "<", options=["<", "<=", ">", ">=", "=="]),
        "percent": PropSpec("percent", "number", 50, min_val=0, max_val=100),
        "team_filter": PropSpec("team_filter", "dropdown", "enemy", options=["enemy", "ally", "all"]),
    }
    inputs = [PinSpec("center", VECTOR, default=None), PinSpec("radius", NUMBER, default=0), PinSpec("percent", NUMBER, default=50)]
    outputs = [PinSpec("characters", ANY)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        center = self.input_expr(ctx, node, "center") if ctx.find_input_link(node["id"], "center") else "me['pos']"
        radius = self.input_expr(ctx, node, "radius") if ctx.find_input_link(node["id"], "radius") else repr(self.prop_value(node, "radius", 0))
        pct = self.input_expr(ctx, node, "percent") if ctx.find_input_link(node["id"], "percent") else repr(self.prop_value(node, "percent", 50))
        op = self.prop_value(node, "operation", "<")
        team = self.prop_value(node, "team_filter", "enemy")
        return f"[c for c in ctx.characters_in_radius(me, {center}, {radius} if {radius} > 0 else 99999, {team!r}, False) if (c['hp']/max(1,c['max_hp'])*100) {op} {pct}]"

