@register_node("tag_wait_until_set", "Status", "Wait Until Tag Set",
               "Pauses this execution branch until the target gains the specified tag.")
class WaitUntilTagSetNode(NodeBase):
    properties = {"tag": PropSpec("tag", "string", "")}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("tag", STRING)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        tag = self.input_expr(ctx, node, "tag") if ctx.find_input_link(node["id"], "tag") else repr(self.prop_value(node, "tag", ""))
        active = ctx.state_name(node["id"], "active")
        tag_var = ctx.state_name(node["id"], "tag")
        target_var = ctx.state_name(node["id"], "target")
        func = f"_ns_wait_tag_done_{node['id']}"
        ctx.emit(f"{active} = True")
        ctx.emit(f"{tag_var} = str({tag})")
        ctx.emit(f"{target_var} = {t}")
        ctx.needs_time = True
        if func not in ctx.used_helpers:
            ctx.used_helpers.add(func)
            ctx.generate_subgraph_function(node["id"], "", func, [])

