@register_node("gameplay_critical_hit_roll", "Gameplay", "Critical Hit Roll",
               "Rolls for a critical hit based on chance and multiplier, returning a Boolean and the final damage.")
class CriticalHitRollNode(NodeBase):
    properties = {"chance": PropSpec("chance", "number", 0.2), "multiplier": PropSpec("multiplier", "number", 2.0), "base_damage": PropSpec("base_damage", "number", 10)}
    inputs = [PinSpec("chance", NUMBER, default=0.2), PinSpec("multiplier", NUMBER, default=2.0), PinSpec("base_damage", NUMBER, default=10)]
    outputs = [PinSpec("is_crit", BOOLEAN), PinSpec("final_damage", NUMBER)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        chance = self.input_expr(ctx, node, "chance") if ctx.find_input_link(node["id"], "chance") else repr(self.prop_value(node, "chance", 0.2))
        mult = self.input_expr(ctx, node, "multiplier") if ctx.find_input_link(node["id"], "multiplier") else repr(self.prop_value(node, "multiplier", 2.0))
        base = self.input_expr(ctx, node, "base_damage") if ctx.find_input_link(node["id"], "base_damage") else repr(self.prop_value(node, "base_damage", 10))
        v = ctx.fresh_var("roll")
        ctx.expr_cache[(node["id"], "roll")] = v
        ctx.emit(f"{v} = random.random() < {chance}")
        if output_name == "is_crit":
            return v
        return f"({base} * {mult} if {v} else {base})"

