@register_node("terraria_demon_eye_chase", "Terraria", "Demon Eye Chase",
               "Every Frame: Terraria Demon Eye arc movement. Flies toward Target in wobbly arcs. Target can be a character or vector. Put this in Every Frame after Setup.")
class DemonEyeChaseNode(NodeBase):
    properties = {
        "speed": PropSpec("speed", "number", 180, min_val=10, max_val=800, tooltip="Forward chase speed"),
        "arc_amplitude": PropSpec("arc_amplitude", "number", 90, min_val=0, max_val=300, tooltip="How wide the arc wobble is - higher = bigger loops"),
        "arc_frequency": PropSpec("arc_frequency", "number", 2.4, min_val=0.1, max_val=10, tooltip="How fast it wobbles"),
        "agility": PropSpec("agility", "number", 3.5, min_val=0.1, max_val=20, tooltip="How quickly it corrects toward desired arc velocity"),
        "homing": PropSpec("homing", "number", 0.92, min_val=0.0, max_val=1.5, tooltip="Homing lerp strength"),
        "wobble_mode": PropSpec("wobble_mode", "dropdown", "sine", options=["sine", "figure8", "noise"], tooltip="Shape of the arc"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None, tooltip="Character or position to chase - e.g. Nearest Enemy"),
        PinSpec("speed", NUMBER, default=180),
        PinSpec("arc_amplitude", NUMBER, default=90),
        PinSpec("arc_frequency", NUMBER, default=2.4),
        PinSpec("agility", NUMBER, default=3.5),
    ]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.input_expr(ctx, node, "target") if ctx.find_input_link(node["id"], "target") else "None"
        sp = self.input_expr(ctx, node, "speed") if ctx.find_input_link(node["id"], "speed") else repr(self.prop_value(node, "speed", 180))
        amp = self.input_expr(ctx, node, "arc_amplitude") if ctx.find_input_link(node["id"], "arc_amplitude") else repr(self.prop_value(node, "arc_amplitude", 90))
        freq = self.input_expr(ctx, node, "arc_frequency") if ctx.find_input_link(node["id"], "arc_frequency") else repr(self.prop_value(node, "arc_frequency", 2.4))
