        mode = repr(self.prop_value(node, "wobble_mode", "sine"))
        ctx.emit(f"ctx.demon_eye_chase(me, target_pos={t}, speed={sp}, arc_amplitude={amp}, arc_frequency={freq}, agility={ag}, homing={hom}, wobble_mode={mode})")
