@register_node("terraria_demon_eye_spawn_minion", "Terraria", "Spawn Demon Eye Minion",
               "Spawn 1+ Demon Eye minions around this character. They automatically get Demon Eye movement and chase nearest enemy. Attach on spawn or as a summon ability.")
class DemonEyeSpawnMinionNode(NodeBase):
    properties = {
        "character_name": PropSpec("character_name", "string", "", tooltip="Library character name to use for eye - leave empty to clone self"),
        "count": PropSpec("count", "number", 1, min_val=1, max_val=20),
        "radius": PropSpec("radius", "number", 80, min_val=0, max_val=500),
        "speed": PropSpec("speed", "number", 180, min_val=10, max_val=800),
        "arc_amplitude": PropSpec("arc_amplitude", "number", 90, min_val=0, max_val=300),
        "arc_frequency": PropSpec("arc_frequency", "number", 2.4, min_val=0.1, max_val=10),
        "tag": PropSpec("tag", "string", "demon_eye", tooltip="Tag added to spawned eyes for filtering"),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("character_name", STRING, default=""),
        PinSpec("count", NUMBER, default=1),
        PinSpec("radius", NUMBER, default=80),
        PinSpec("speed", NUMBER, default=180),
    ]
    outputs = [PinSpec("", EXEC), PinSpec("spawned", OBJECT, tooltip="First spawned eye, or list if count>1"), PinSpec("spawned_list", ANY, tooltip="List of all spawned eyes")]
    def generate_code(self, ctx, node, visited):
        cn = self.input_expr(ctx, node, "character_name") if ctx.find_input_link(node["id"], "character_name") else repr(self.prop_value(node, "character_name", ""))
        cnt = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(self.prop_value(node, "count", 1))
        rad = self.input_expr(ctx, node, "radius") if ctx.find_input_link(node["id"], "radius") else repr(self.prop_value(node, "radius", 80))
        sp = self.input_expr(ctx, node, "speed") if ctx.find_input_link(node["id"], "speed") else repr(self.prop_value(node, "speed", 180))
        amp = repr(self.prop_value(node, "arc_amplitude", 90))
        freq = repr(self.prop_value(node, "arc_frequency", 2.4))
        tag = repr(self.prop_value(node, "tag", "demon_eye"))
        var_list = ctx.fresh_var("demon_eyes")
        var_first = ctx.fresh_var("demon_eye_first")
        ctx.expr_cache[(node["id"], "spawned_list")] = var_list
        ctx.expr_cache[(node["id"], "spawned")] = var_first
        ctx.emit(f"{var_list} = ctx.demon_eye_spawn_minion(me, character_name={cn}, count={cnt}, radius={rad}, speed={sp}, arc_amplitude={amp}, arc_frequency={freq}, tag={tag})")
        ctx.emit(f"{var_first} = {var_list}[0] if {var_list} else None")
        ctx.generate_exec_branch(node["id"], "", visited)

    def generate_output_expr(self, ctx, node, output_name):
        if output_name == "spawned_list":
            return ctx.expr_cache.get((node["id"], "spawned_list"), "[]")
        return ctx.expr_cache.get((node["id"], "spawned"), "None")

@register_node("movement_set_speed_limits", "Movement", "Set Speed Limits",
               "Sets a per-character minimum and maximum speed cap. "
               "The engine enforces these every frame — no script can push the character faster than max_speed "
               "or slower than min_speed (unless it is completely stopped). "
               "Call on On Spawn to lock a character's speed range permanently, "
               "or at any time to change it mid-fight.")
class SetSpeedLimitsNode(NodeBase):
    properties = {
        "max_speed": PropSpec("max_speed", "number", 300, min_val=0,   max_val=2000),
        "min_speed": PropSpec("min_speed", "number",   0, min_val=0,   max_val=2000),
    }
    inputs = [
        PinSpec("",          EXEC),
        PinSpec("target",    OBJECT, default=None),
        PinSpec("max_speed", NUMBER, default=300),
        PinSpec("min_speed", NUMBER, default=0),
    ]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t    = self.object_input_expr(ctx, node, "target", "me")
        vmax = self.input_expr(ctx, node, "max_speed") if ctx.find_input_link(node["id"], "max_speed") \
               else repr(self.prop_value(node, "max_speed", 300))
        vmin = self.input_expr(ctx, node, "min_speed") if ctx.find_input_link(node["id"], "min_speed") \
               else repr(self.prop_value(node, "min_speed", 0))
        ctx.emit(f"{t}['max_speed'] = max(0, float({vmax}))")
        ctx.emit(f"{t}['min_speed'] = max(0, min(float({vmin}), float({vmax})))")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("movement_get_speed", "Movement", "Get Speed",
               "Returns the character's current movement speed as a number, "
               "plus separate max_speed and min_speed caps. "
               "Use with Compare Number to react when a character is going too fast or too slow.")
class GetSpeedNode(NodeBase):
    inputs  = [PinSpec("target", OBJECT, default=None)]
    outputs = [
        PinSpec("current_speed", NUMBER),
        PinSpec("max_speed",     NUMBER),
        PinSpec("min_speed",     NUMBER),
    ]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        if output_name == "current_speed":
            return f"{t}.get('vel', __import__('pygame').Vector2(0,0)).length()"
        if output_name == "max_speed":
            return f"{t}.get('max_speed', 650)"
        if output_name == "min_speed":
            return f"{t}.get('min_speed', 0)"
        return "0"

@register_node("movement_clamp_position", "Movement", "Clamp Position",
               "Prevents a character from leaving a defined rectangular boundary area.")
class ClampPositionNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("min", VECTOR, default=None), PinSpec("max", VECTOR, default=None)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        min_p = self.input_expr(ctx, node, "min") if ctx.find_input_link(node["id"], "min") else "pygame.Vector2(-9999, -9999)"
        max_p = self.input_expr(ctx, node, "max") if ctx.find_input_link(node["id"], "max") else "pygame.Vector2(9999, 9999)"
        ctx.emit(f"ctx.clamp_position(me, {min_p}, {max_p})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("timing_debounce", "Timing", "Debounce",
               "Ignores retriggers that happen faster than the cooldown -- prevents event flooding.")
class DebounceNode(NodeBase):
    properties = {"duration": PropSpec("duration", "number", 1.0, min_val=0.0, max_val=60.0)}
    inputs = [PinSpec("", EXEC), PinSpec("duration", NUMBER, default=1.0)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        dur = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 1.0))
        end = ctx.state_name(node["id"], "end")
        ctx.emit("_now = time.time()")
        ctx.emit(f"if _now >= {end}:")
        ctx.push_indent()
        ctx.emit(f"{end} = _now + {dur}")
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.pop_indent()

@register_node("timing_random_chance_gate", "Timing", "Random Chance Gate",
               "Splits execution into Success or Failure based on a random percentage roll.")
class RandomChanceGateNode(NodeBase):
    properties = {"chance": PropSpec("chance", "number", 50, min_val=0, max_val=100)}
    inputs = [PinSpec("", EXEC), PinSpec("chance", NUMBER, default=50)]
    outputs = [PinSpec("success", EXEC), PinSpec("failure", EXEC)]
    def generate_code(self, ctx, node, visited):
        c = self.input_expr(ctx, node, "chance") if ctx.find_input_link(node["id"], "chance") else repr(self.prop_value(node, "chance", 50))
        ctx.emit(f"if random.random() * 100 <= {c}:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "success", visited)
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "failure", visited)
        ctx.pop_indent()

@register_node("timing_round_robin_sequence", "Timing", "Round Robin Sequence",
               "Cycles through outputs in order each time triggered -- 1st call fires 0, 2nd fires 1, then loops.")
class RoundRobinSequenceNode(NodeBase):
    properties = {"count": PropSpec("count", "number", 3, min_val=2, max_val=8)}
    inputs = [PinSpec("", EXEC)]
    outputs = [PinSpec(f"{i}", EXEC, tooltip=f"Step {i+1}") for i in range(8)]
    def generate_code(self, ctx, node, visited):
        count = int(self.prop_value(node, "count", 3))
        idx_var = ctx.state_name(node["id"], "index")
        ctx.emit(f"{idx_var} = ({idx_var} + 1) % {count}")
        for i in range(min(count, 8)):
            ctx.emit(f"if {idx_var} == {i}:")
            ctx.push_indent()
            ctx.generate_exec_branch(node["id"], str(i), visited)
            ctx.pop_indent()

@register_node("timing_once", "Timing", "Once",
               "Allows execution once for the character lifetime. For floor touch or any condition that must fire again after release, use Once Per True Cycle instead.")
class OnceNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("reset", EXEC, tooltip="Legacy pin; use Once Per True Cycle for automatic reset behavior")]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        fired = ctx.state_name(node["id"], "fired")
        ctx.emit(f"if not {fired}:")
        ctx.push_indent()
        ctx.emit(f"{fired} = True")
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.pop_indent()
    def generate_exec(self, node_id, visited):
        # We need to handle the 'reset' exec input differently since it just resets the state
        pass # The default generate_exec assumes one incoming EXEC path and processes all linked outputs.
        # It's better to just rely on the main exec path, and intercept reset specifically inside the main generate_code loop
        # Actually, standard visual scripter here doesn't support multiple different EXEC input handlers in `generate_code`.
        # I'll just check if it's accessed via the reset wire, but that's complex. Let's omit Reset for now or just do a simple check.
        # To handle multiple exec inputs properly, we can look at the `generate_exec_branch` logic. 
        # But wait! I can just omit Reset for simplicity if the framework doesn't have an obvious way to distinguish which input pin was executed.
        # Looking at Event nodes, they generate independent roots. For normal nodes, execution flows in.

@register_node("timing_once_per_true_cycle", "Timing", "Once Per True Cycle",
               "Best for floor touch, overlap, range and button states. Feed it every frame plus a boolean. Triggered fires once when False becomes True; it automatically rearms after the value becomes False, so the next touch can fire again.")
class OncePerTrueCycleNode(NodeBase):
    properties={"active":PropSpec("active","boolean",False,tooltip="Boolean state to edge-detect, such as Is On Floor")}
    inputs=[PinSpec("",EXEC),PinSpec("active",BOOLEAN,default=False,tooltip="Connect Is On Floor / Is Touching / In Range")]
    outputs=[PinSpec("triggered",EXEC,tooltip="Fires once on the rising edge"),
             PinSpec("rearmed",EXEC,tooltip="Fires once when the state becomes false again"),
             PinSpec("active",BOOLEAN,tooltip="Current boolean state")]
    def generate_code(self,ctx,node,visited):
        expr=self.input_expr(ctx,node,"active") if ctx.find_input_link(node["id"],"active") else repr(bool(self.prop_value(node,"active",False)))
        prev=ctx.state_name(node["id"],"previous")
        cur=ctx.fresh_var("edge_active")
        ctx.emit(f"{cur} = bool({expr})")
        ctx.expr_cache[(node["id"],"active")]=cur
        ctx.emit(f"if {cur} and not {prev}:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"triggered",visited);ctx.pop_indent()
        ctx.emit(f"elif (not {cur}) and {prev}:")
        ctx.push_indent();ctx.generate_exec_branch(node["id"],"rearmed",visited);ctx.pop_indent()
        ctx.emit(f"{prev} = {cur}")
    def generate_output_expr(self,ctx,node,output_name):
        return ctx.expr_cache.get((node["id"],"active"),"False")

@register_node("target_filter_list", "Targets", "First Match / Filter List",
               "Takes a list of characters and filters it down based on a condition.")
class FilterListNode(NodeBase):
    properties = {
        "property": PropSpec("property", "dropdown", "hp", options=["hp", "max_hp", "distance", "tag"]),
        "operation": PropSpec("operation", "dropdown", "<", options=["<", "<=", ">", ">=", "==", "!=", "has"]),
        "value_num": PropSpec("value_num", "number", 0),
        "value_str": PropSpec("value_str", "string", "")
    }
    inputs = [PinSpec("list", ANY, default=None)]
    outputs = [PinSpec("filtered_list", ANY), PinSpec("first_match", OBJECT)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        lst = self.input_expr(ctx, node, "list") if ctx.find_input_link(node["id"], "list") else "[]"
        prop = self.prop_value(node, "property", "hp")
        op = self.prop_value(node, "operation", "<")
        if prop == "tag":
            val = repr(self.prop_value(node, "value_str", ""))
            cond = f"ctx.has_tag(c, {val})" if op == "has" else f"(not ctx.has_tag(c, {val}))"
        elif prop == "distance":
            val = repr(self.prop_value(node, "value_num", 0))
            cond = f"(c['pos'].distance_to(me['pos']) {op} {val})"
        else:
            val = repr(self.prop_value(node, "value_num", 0))
            cond = f"(c.get('{prop}', 0) {op} {val})"
            
        filtered_expr = f"[c for c in {lst} if {cond}]"
        
        if output_name == "filtered_list":
            return filtered_expr
        elif output_name == "first_match":
            return f"({filtered_expr}[0] if {filtered_expr} else None)"

