@register_node("lifecycle_clone_with_stats", "Gameplay", "Clone With Modified Stats",
               "Duplicates a character but overrides specific stats on the new copy.")
class CloneWithStatsNode(NodeBase):
    properties = {"hp": PropSpec("hp", "number", 0), "damage_min": PropSpec("damage_min", "number", 0), "damage_max": PropSpec("damage_max", "number", 0), "speed": PropSpec("speed", "number", 0), "scale": PropSpec("scale", "number", 0.0)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("hp", NUMBER, default=0), PinSpec("damage_min", NUMBER, default=0), PinSpec("damage_max", NUMBER, default=0), PinSpec("speed", NUMBER, default=0), PinSpec("scale", NUMBER, default=0.0)]
    outputs = [PinSpec("", EXEC), PinSpec("clone", OBJECT)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        hp = self.input_expr(ctx, node, "hp") if ctx.find_input_link(node["id"], "hp") else repr(self.prop_value(node, "hp", 0))
        dmin = self.input_expr(ctx, node, "damage_min") if ctx.find_input_link(node["id"], "damage_min") else repr(self.prop_value(node, "damage_min", 0))
        dmax = self.input_expr(ctx, node, "damage_max") if ctx.find_input_link(node["id"], "damage_max") else repr(self.prop_value(node, "damage_max", 0))
        spd = self.input_expr(ctx, node, "speed") if ctx.find_input_link(node["id"], "speed") else repr(self.prop_value(node, "speed", 0))
        scl = self.input_expr(ctx, node, "scale") if ctx.find_input_link(node["id"], "scale") else repr(self.prop_value(node, "scale", 0.0))
        clone_var = ctx.fresh_var("clone")
        ctx.expr_cache[(node["id"], "clone")] = clone_var
        ctx.emit(f"{clone_var} = ctx.clone_with_stats({t}, {hp} if {hp}>0 else None, {dmin} if {dmin}>0 else None, {dmax} if {dmax}>0 else None, {spd} if {spd}>0 else None, {scl} if {scl}>0.0 else None)")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("lifecycle_spawn_custom", "Gameplay", "Spawn Custom Clone",
               "The universal clone spawner. Clones a character but lets you override EVERYTHING — "
               "pick a script to give the clone a different brain (use Select Script node or wire a filename). "
               "Leave Script empty to create a dumb body with no trait script running. "
               "Tag lets you filter it later with Find By Tag / Get Characters With Tag.")
class SpawnCustomCloneNode(NodeBase):
    properties = {
        "script_file": PropSpec("script_file", "script_file", ""),
        "name":        PropSpec("name",        "string", ""),
        "hp":          PropSpec("hp",          "number", 0),
        "max_hp":      PropSpec("max_hp",      "number", 0),
        "damage_min":  PropSpec("damage_min",  "number", 0),
        "damage_max":  PropSpec("damage_max",  "number", 0),
        "speed":       PropSpec("speed",       "number", 0),
        "scale":       PropSpec("scale",       "number", 0.0),
        "tag":         PropSpec("tag",         "string", ""),
    }
    inputs = [PinSpec("", EXEC), PinSpec("source", OBJECT, default=None),
              PinSpec("script_file", STRING, default=""),
              PinSpec("name",        STRING, default=""),
              PinSpec("hp",          NUMBER, default=0),
              PinSpec("max_hp",      NUMBER, default=0),
              PinSpec("damage_min",  NUMBER, default=0),
              PinSpec("damage_max",  NUMBER, default=0),
              PinSpec("speed",       NUMBER, default=0),
              PinSpec("scale",       NUMBER, default=0.0),
              PinSpec("color",       COLOR, default=[255,255,255]),
              PinSpec("tag",         STRING, default=""),
              PinSpec("position",    VECTOR, default=None)]
    outputs = [PinSpec("", EXEC), PinSpec("clone", OBJECT)]
    def generate_code(self, ctx, node, visited):
        src = self.object_input_expr(ctx, node, "source", "me")
        # Build kwargs only for wired inputs
        kw_parts = []
        _has_script = False
        if ctx.find_input_link(node["id"], "script_file"):
            sf = self.input_expr(ctx, node, "script_file")
            kw_parts.append(f"script_file=str({sf}) if {sf} else None")
            _has_script = True
        elif self.prop_value(node, "script_file", ""):
            _sf_val = str(self.prop_value(node, 'script_file', ''))
            kw_parts.append(f"script_file={repr(_sf_val)}")
            _has_script = True
        # If no script provided, no_script=True automatically
        if not _has_script:
            kw_parts.append("no_script=True")
        if ctx.find_input_link(node["id"], "name"):
            nm = self.input_expr(ctx, node, "name")
            kw_parts.append(f"name=str({nm}) if {nm} else None")
        elif self.prop_value(node, "name", ""):
            kw_parts.append(f"name={repr(str(self.prop_value(node, 'name', '')))}")
        if ctx.find_input_link(node["id"], "hp"):
            kw_parts.append(f"hp=float({self.input_expr(ctx, node, 'hp')})")
        elif self.prop_value(node, "hp", 0):
            kw_parts.append(f"hp={float(self.prop_value(node, 'hp', 0))}")
        if ctx.find_input_link(node["id"], "max_hp"):
            kw_parts.append(f"max_hp=float({self.input_expr(ctx, node, 'max_hp')})")
        elif self.prop_value(node, "max_hp", 0):
            kw_parts.append(f"max_hp={float(self.prop_value(node, 'max_hp', 0))}")
        if ctx.find_input_link(node["id"], "damage_min"):
            kw_parts.append(f"damage_min=int({self.input_expr(ctx, node, 'damage_min')})")
        elif self.prop_value(node, "damage_min", 0):
            kw_parts.append(f"damage_min={int(self.prop_value(node, 'damage_min', 0))}")
        if ctx.find_input_link(node["id"], "damage_max"):
            kw_parts.append(f"damage_max=int({self.input_expr(ctx, node, 'damage_max')})")
        elif self.prop_value(node, "damage_max", 0):
            kw_parts.append(f"damage_max={int(self.prop_value(node, 'damage_max', 0))}")
        if ctx.find_input_link(node["id"], "speed"):
            kw_parts.append(f"speed=float({self.input_expr(ctx, node, 'speed')})")
        elif self.prop_value(node, "speed", 0):
            kw_parts.append(f"speed={float(self.prop_value(node, 'speed', 0))}")
        if ctx.find_input_link(node["id"], "scale"):
            kw_parts.append(f"scale=float({self.input_expr(ctx, node, 'scale')})")
        elif self.prop_value(node, "scale", 0.0):
            kw_parts.append(f"scale={float(self.prop_value(node, 'scale', 0.0))}")
        if ctx.find_input_link(node["id"], "color"):
            kw_parts.append(f"color=tuple({self.input_expr(ctx, node, 'color')}[:3])")
        if ctx.find_input_link(node["id"], "tag"):
            tg = self.input_expr(ctx, node, "tag")
            kw_parts.append(f"tag=str({tg}) if {tg} else None")
        elif self.prop_value(node, "tag", ""):
            kw_parts.append(f"tag={repr(str(self.prop_value(node, 'tag', '')))}")
        if ctx.find_input_link(node["id"], "position"):
            kw_parts.append(f"position=pygame.Vector2({self.input_expr(ctx, node, 'position')})")
        kw_str = ", ".join(kw_parts)
        v = ctx.fresh_var("clone")
        ctx.expr_cache[(node["id"], "clone")] = v
        ctx.emit(f"{v} = ctx.spawn_custom({src}, {kw_str})")
        _ns_emit_target_event_bindings(ctx, node["id"], "clone", v, visited)
        ctx.generate_exec_branch(node["id"], "", visited)

