@register_node("logic_gate", "Logic", "Logic Gate",
               "One gate, every behavior: AND, OR, XOR (odd-parity), NAND, NOR, or MAJORITY over up to four boolean inputs. Only WIRED pins count (unwired pins are ignored, so wire exactly what you need - and/or with 2, 3 or 4 conditions), and you can chain gates for more inputs. count_true/count_wired say exactly how many inputs are hot right now ('at least N' checks are one wire away).")
class LogicGateNode(NodeBase):
    properties = {"mode": PropSpec("mode", "dropdown", "and",
                                   options=["and", "or", "xor", "nand", "nor", "majority"])}
    inputs = [PinSpec("a", BOOLEAN, default=False), PinSpec("b", BOOLEAN, default=False),
              PinSpec("c", BOOLEAN, default=False), PinSpec("d", BOOLEAN, default=False)]
    outputs = [PinSpec("result", BOOLEAN), PinSpec("count_true", NUMBER),
               PinSpec("count_wired", NUMBER)]
    pure = True
    def _gate_terms(self, ctx, node):
        terms = []
        for pin in ("a", "b", "c", "d"):
            if ctx.find_input_link(node["id"], pin):
                terms.append("bool(" + self.input_expr(ctx, node, pin) + ")")
        return terms
    def generate_output_expr(self, ctx, node, output_name):
        terms = self._gate_terms(ctx, node)
        mode = str(self.prop_value(node, "mode", "and")).strip().lower()
        n = len(terms)
        ints = ["(1 if " + t + " else 0)" for t in terms]
        total = " + ".join(ints) if ints else "0"
        if output_name == "count_wired":
            return repr(n)
        if output_name == "count_true":
            return "(" + total + ")"
        if not terms:
            return {"and": "True", "nand": "False", "or": "False",
                    "xor": "False", "majority": "False", "nor": "True"}.get(mode, "True")
        conj = " and ".join(terms)
        disj = " or ".join(terms)
        if mode == "or":
            return "(" + disj + ")"
        if mode == "xor":
            return "(((" + total + ") % 2) == 1)"
        if mode == "nand":
            return "(not (" + conj + "))"
        if mode == "nor":
            return "(not (" + disj + "))"
        if mode == "majority":
            return "((" + total + ") * 2 > " + repr(n) + ")"
        return "(" + conj + ")"

