    inputs = [PinSpec("", EXEC), PinSpec("center", VECTOR, default=None), PinSpec("radius", NUMBER, default=0), PinSpec("event_name", STRING, default="signal"), PinSpec("payload", ANY, default=None)]
    outputs = [PinSpec("", EXEC)]
