@register_node("variable_local_set", "Variables", "Set Local Variable",
               "Stores a private variable on this specific character -- not shared with others.")
class SetLocalVariableNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_var"),
                  "type": PropSpec("type", "dropdown", "number", options=["number", "string", "boolean", "vector", "color", "object"])}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("value", ANY, default=None)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        name = repr(self.prop_value(node, "name", "my_var"))
        if ctx.find_input_link(node["id"], "value"):
            val = self.input_expr(ctx, node, "value")
        else:
            val = ctx.default_to_expr(self.prop_value(node, "type", "number"), None)
        ctx.emit(f"ctx.set_local_var({t}, {name}, {val})")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("variable_local_get", "Variables", "Get Local Variable",
               "Reads a private variable stored on this character. Returns a default if never set.")
class GetLocalVariableNode(NodeBase):
    properties = {"name": PropSpec("name", "string", "my_var"),
                  "type": PropSpec("type", "dropdown", "number", options=["number", "string", "boolean", "vector", "color", "object"]),
                  "default_num": PropSpec("default_num", "number", 0)}
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("value", ANY)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        name = repr(self.prop_value(node, "name", "my_var"))
        vtype = self.prop_value(node, "type", "number")
        # Default for the never-set case respects the declared type — a
        # "string" variable defaults to "" not 0, etc. Number keeps using
        # the tunable default_num field for backward compatibility.
        dflt = repr(self.prop_value(node, "default_num", 0)) if vtype == "number" else ctx.default_to_expr(vtype, None)
        raw = f"ctx.get_local_var({t}, {name}, {dflt})"
        # Coerce whatever actually comes back (e.g. a stale/mismatched value
        # from before the type was set, or a value written by a different
        # node) so a "number" variable always reaches downstream Math nodes
        # as an actual float, instead of silently handing them a string and
        # crashing Subtract/Add/etc. with "could not convert string to float".
        if vtype == "number":
            return f"_ns_to_number({raw}, {dflt})"
        if vtype == "boolean":
            return f"_ns_bool({raw})"
        return raw

@register_node("swarm_spawn_library", "Swarm", "Spawn Swarm From Library",
               "Spawns multiple copies of a named library character nearby.")
class SpawnSwarmLibraryNode(NodeBase):
    properties = {"character": PropSpec("character", "character", ""), "count": PropSpec("count", "number", 5), "radius": PropSpec("radius", "number", 50)}
    inputs = [PinSpec("", EXEC), PinSpec("character", STRING, default=""), PinSpec("count", NUMBER, default=5), PinSpec("radius", NUMBER, default=50)]
    outputs = [PinSpec("", EXEC), PinSpec("spawned", ANY)]
    def generate_code(self, ctx, node, visited):
        char = self.input_expr(ctx, node, "character") if ctx.find_input_link(node["id"], "character") else repr(self.prop_value(node, "character", ""))
        cnt = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(self.prop_value(node, "count", 5))
        rad = self.input_expr(ctx, node, "radius") if ctx.find_input_link(node["id"], "radius") else repr(self.prop_value(node, "radius", 50))
        v = ctx.fresh_var("swarm")
        ctx.expr_cache[(node["id"], "spawned")] = v
        ctx.emit(f"{v} = ctx.spawn_library_character_in_swarm(me, {cnt}, {rad}, {char})")
        ctx.generate_exec_branch(node["id"], "", visited)

