@register_node("math_to_boolean", "Math", "To Boolean",
               "Converts a number or string to True/False. 0, empty string, and \"false\"/\"no\"/\"off\" "
               "all become False; anything else becomes True.")
class ToBooleanNode(NodeBase):
    inputs = [PinSpec("value", ANY, default=None)]
    outputs = [PinSpec("boolean", BOOLEAN)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        v = self.input_expr(ctx, node, "value") if ctx.find_input_link(node["id"], "value") else "False"
        # Plain bool(v) is wrong for strings — bool("False") is True in
        # Python since any non-empty string is truthy. _ns_bool actually
        # reads the text ("true"/"false"/"1"/"0"/etc).
        return f"_ns_bool({v})"

