@register_node("utility_make_color", "Utility", "Make Color",
               "Combines R, G, B numbers (0-255) into a single Color you can wire into any color input.")
class MakeColorNode(NodeBase):
    properties = {"r": PropSpec("r", "number", 255), "g": PropSpec("g", "number", 255), "b": PropSpec("b", "number", 255)}
    inputs  = [PinSpec("r", NUMBER, default=255), PinSpec("g", NUMBER, default=255), PinSpec("b", NUMBER, default=255)]
    outputs = [PinSpec("color", COLOR)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        r = self.input_expr(ctx, node, "r") if ctx.find_input_link(node["id"], "r") else repr(self.prop_value(node, "r", 255))
        g = self.input_expr(ctx, node, "g") if ctx.find_input_link(node["id"], "g") else repr(self.prop_value(node, "g", 255))
        b = self.input_expr(ctx, node, "b") if ctx.find_input_link(node["id"], "b") else repr(self.prop_value(node, "b", 255))
        return f"(int(max(0,min(255,_ns_to_number({r})))), int(max(0,min(255,_ns_to_number({g})))), int(max(0,min(255,_ns_to_number({b})))))"

@register_node("utility_vector_to_string", "Utility", "Vector To String",
               "Turns a Vector2 into readable text, e.g. '(120, 40)'. Useful for debug labels.")
class VectorToStringNode(NodeBase):
    inputs  = [PinSpec("vector", VECTOR, default=None)]
    outputs = [PinSpec("string", STRING)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        v = self.input_expr(ctx, node, "vector") if ctx.find_input_link(node["id"], "vector") else "None"
        return f"(f'({{({v}).x:.1f}}, {{({v}).y:.1f}})' if {v} is not None else '(0, 0)')"

@register_node("utility_string_to_vector", "Utility", "String To Vector",
               "Parses text like '120,40' or '120, 40' into a Vector2. Falls back to (0,0) if it can't be parsed.")
class StringToVectorNode(NodeBase):
    inputs  = [PinSpec("string", STRING, default="0,0")]
    outputs = [PinSpec("vector", VECTOR)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        s = self.input_expr(ctx, node, "string") if ctx.find_input_link(node["id"], "string") else "'0,0'"
        return f"_ns_parse_vector({s})"

@register_node("math_remap", "Math", "Remap",
               "Maps a value from one range [in_min, in_max] to another [out_min, out_max]. Like Godot remap() — e.g. distance 0-300 -> volume 1.0-0.0.")
class RemapNode(NodeBase):
    properties = {"in_min":  PropSpec("in_min",  "number", 0),
                  "in_max":  PropSpec("in_max",  "number", 100),
                  "out_min": PropSpec("out_min", "number", 0),
                  "out_max": PropSpec("out_max", "number", 1)}
    inputs  = [PinSpec("value",   NUMBER, default=0),
               PinSpec("in_min",  NUMBER, default=0),
               PinSpec("in_max",  NUMBER, default=100),
               PinSpec("out_min", NUMBER, default=0),
               PinSpec("out_max", NUMBER, default=1)]
    outputs = [PinSpec("result",  NUMBER)]
    pure    = True
    def generate_output_expr(self, ctx, node, output_name):
        v   = self.input_expr(ctx, node, "value")   if ctx.find_input_link(node["id"], "value")   else repr(self.prop_value(node, "in_min", 0))
        n0  = self.input_expr(ctx, node, "in_min")  if ctx.find_input_link(node["id"], "in_min")  else repr(self.prop_value(node, "in_min",  0))
        n1  = self.input_expr(ctx, node, "in_max")  if ctx.find_input_link(node["id"], "in_max")  else repr(self.prop_value(node, "in_max",  100))
        o0  = self.input_expr(ctx, node, "out_min") if ctx.find_input_link(node["id"], "out_min") else repr(self.prop_value(node, "out_min", 0))
        o1  = self.input_expr(ctx, node, "out_max") if ctx.find_input_link(node["id"], "out_max") else repr(self.prop_value(node, "out_max", 1))
        return f"(({v}) - ({n0})) / max(0.0001, ({n1}) - ({n0})) * (({o1}) - ({o0})) + ({o0})"

@register_node("math_smoothstep", "Math", "Smoothstep",
               "Returns a smooth ease curve between 0 and 1, given an edge0, edge1, and input value. Faster than lerp for natural-feeling transitions.")
class SmoothstepNode(NodeBase):
    properties = {"edge0": PropSpec("edge0", "number", 0), "edge1": PropSpec("edge1", "number", 1)}
    inputs  = [PinSpec("value", NUMBER, default=0.5),
               PinSpec("edge0", NUMBER, default=0),
               PinSpec("edge1", NUMBER, default=1)]
    outputs = [PinSpec("result", NUMBER)]
    pure    = True
    def generate_output_expr(self, ctx, node, output_name):
        v  = self.input_expr(ctx, node, "value") if ctx.find_input_link(node["id"], "value") else "0.5"
        e0 = self.input_expr(ctx, node, "edge0") if ctx.find_input_link(node["id"], "edge0") else repr(self.prop_value(node, "edge0", 0))
        e1 = self.input_expr(ctx, node, "edge1") if ctx.find_input_link(node["id"], "edge1") else repr(self.prop_value(node, "edge1", 1))
        return (f"(lambda _t: _t * _t * (3 - 2 * _t))"
                f"(max(0.0, min(1.0, (({v}) - ({e0})) / max(0.0001, ({e1}) - ({e0})))))")

@register_node("math_lerp_angle", "Math", "Lerp Angle",
               "Interpolates between two angles (degrees) without wrap-around jitter. Always takes the shortest path around the circle.")
class LerpAngleNode(NodeBase):
    inputs  = [PinSpec("from_deg", NUMBER, default=0),
               PinSpec("to_deg",   NUMBER, default=180),
               PinSpec("t",        NUMBER, default=0.5)]
    outputs = [PinSpec("angle", NUMBER)]
    pure    = True
    def generate_output_expr(self, ctx, node, output_name):
        a = self.input_expr(ctx, node, "from_deg") if ctx.find_input_link(node["id"], "from_deg") else "0"
        b = self.input_expr(ctx, node, "to_deg")   if ctx.find_input_link(node["id"], "to_deg")   else "180"
        t = self.input_expr(ctx, node, "t")        if ctx.find_input_link(node["id"], "t")        else "0.5"
        return (f"(lambda _a,_b,_t: _a + ((_b-_a+540)%360-180)*_t)"
                f"(float({a}), float({b}), float({t}))")

@register_node("math_angle_between", "Math", "Angle Between",
               "Returns the angle in degrees from position A to position B. Wire two character positions to get a facing direction as a number.")
class AngleBetweenNode(NodeBase):
    inputs  = [PinSpec("from_pos", VECTOR, default=(0, 0)),
               PinSpec("to_pos",   VECTOR, default=(1, 0))]
    outputs = [PinSpec("degrees", NUMBER)]
    pure    = True
    def generate_output_expr(self, ctx, node, output_name):
        a = self.input_expr(ctx, node, "from_pos") if ctx.find_input_link(node["id"], "from_pos") else "pygame.Vector2(0,0)"
        b = self.input_expr(ctx, node, "to_pos")   if ctx.find_input_link(node["id"], "to_pos")   else "pygame.Vector2(1,0)"
        return (f"(lambda _a,_b: math.degrees(math.atan2(_b.y-_a.y, _b.x-_a.x)))"
                f"(pygame.Vector2({a}), pygame.Vector2({b}))")

@register_node("math_rotate_vector", "Math", "Rotate Vector",
               "Rotates a direction vector by N degrees clockwise. Use to offset aim, create spiral patterns, or rotate a cone direction.")
class RotateVectorNode(NodeBase):
    properties = {"degrees": PropSpec("degrees", "number", 45, min_val=-360, max_val=360)}
    inputs  = [PinSpec("vector",  VECTOR, default=(1, 0)),
               PinSpec("degrees", NUMBER, default=45)]
    outputs = [PinSpec("rotated", VECTOR)]
    pure    = True
    def generate_output_expr(self, ctx, node, output_name):
        v = self.input_expr(ctx, node, "vector")  if ctx.find_input_link(node["id"], "vector")  else "pygame.Vector2(1,0)"
        d = self.input_expr(ctx, node, "degrees") if ctx.find_input_link(node["id"], "degrees") else repr(self.prop_value(node, "degrees", 45))
        return f"pygame.Vector2({v}).rotate(-({d}))"

@register_node("tween_value", "Timing", "Tween Value",
               "Animates a local variable from A to B over a duration using an easing curve. Every frame the variable gets closer to the target — like Godot Tween.tween_property().")
class TweenValueNode(NodeBase):
    properties = {"var_name": PropSpec("var_name", "string", "tween_val"),
                  "duration": PropSpec("duration", "number", 1.0, min_val=0.01, max_val=60.0),
                  "easing":   PropSpec("easing",   "dropdown", "linear",
                                       options=["linear", "ease_in", "ease_out", "ease_in_out", "bounce"])}
    inputs  = [PinSpec("", EXEC),
               PinSpec("target",   OBJECT, default=None),
               PinSpec("from_val", NUMBER, default=0),
               PinSpec("to_val",   NUMBER, default=1),
               PinSpec("duration", NUMBER, default=1.0)]
    outputs = [PinSpec("", EXEC, tooltip="Fires every frame while tweening"),
               PinSpec("value",    NUMBER, tooltip="Current interpolated value"),
               PinSpec("done",     EXEC,   tooltip="Fires once when tween completes")]
    def generate_code(self, ctx, node, visited):
        t      = self.object_input_expr(ctx, node, "target", "me")
        frm    = self.input_expr(ctx, node, "from_val") if ctx.find_input_link(node["id"], "from_val") else repr(self.prop_value(node, "from_val", 0))
        to     = self.input_expr(ctx, node, "to_val")   if ctx.find_input_link(node["id"], "to_val")   else repr(self.prop_value(node, "to_val",   1))
        dur    = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 1.0))
        name   = repr(self.prop_value(node, "var_name", "tween_val"))
        ease   = self.prop_value(node, "easing", "linear")
        tk     = ctx.state_name(node["id"], "t")
        sk     = ctx.state_name(node["id"], "started")
        fk     = ctx.state_name(node["id"], "from")
        dk     = ctx.state_name(node["id"], "dur")
        # Easing lambda
        easing_exprs = {
            "linear":      "_p",
            "ease_in":     "_p*_p",
            "ease_out":    "_p*(2-_p)",
            "ease_in_out": "(2*_p*_p if _p<0.5 else -1+(4-2*_p)*_p)",
            "bounce":      "(abs(math.sin(math.pi*_p*2.5))*max(0,1-_p))",
        }
        ease_expr = easing_exprs.get(ease, "_p")
        v = ctx.fresh_var("tw")
        ctx.expr_cache[(node["id"], "value")] = v
        ctx.emit(f"if not {t}.get('_ns_state',{{}}).get('{sk}'):")
        ctx.push_indent()
        ctx.emit(f"{t}.setdefault('_ns_state',{{}})['{fk}'] = {frm}")
        ctx.emit(f"{t}['_ns_state']['{dk}'] = max(0.001, {dur})")
        ctx.emit(f"{t}['_ns_state']['{tk}'] = 0.0")
        ctx.emit(f"{t}['_ns_state']['{sk}'] = True")
        ctx.pop_indent()
        ctx.emit(f"{t}['_ns_state']['{tk}'] = min({t}['_ns_state'].get('{tk}',0) + dt, {t}['_ns_state'].get('{dk}',1))")
        ctx.emit(f"_p_{node['id']} = {t}['_ns_state'].get('{tk}',0) / {t}['_ns_state'].get('{dk}',1)")
        ctx.emit(f"_p_{node['id']} = max(0.0, min(1.0, _p_{node['id']}))")
        ctx.emit(f"(lambda _p: None)(_p_{node['id']})")  # suppress unused
        ctx.emit(f"{v} = {t}['_ns_state'].get('{fk}',0) + ({to} - {t}['_ns_state'].get('{fk}',0)) * (lambda _p: {ease_expr})(_p_{node['id']})")
        ctx.emit(f"ctx.set_local_var({t}, {name}, {v})")
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.emit(f"if _p_{node['id']} >= 1.0:")
        ctx.push_indent()
        ctx.emit(f"{t}['_ns_state']['{sk}'] = False")
        ctx.generate_exec_branch(node["id"], "done", visited)
        ctx.emit("pass")
        ctx.pop_indent()

@register_node("flow_state_machine", "Utility", "State Machine",
               "A named-state controller. Set the 'state' input to switch between up to 4 states. Each state fires its own exec output every tick. Like AnimationStateMachine or a manual GDScript state machine.")
class StateMachineNode(NodeBase):
    properties = {"state_a": PropSpec("state_a", "string", "idle"),
                  "state_b": PropSpec("state_b", "string", "attack"),
                  "state_c": PropSpec("state_c", "string", "flee"),
                  "state_d": PropSpec("state_d", "string", ""),
                  "var_name": PropSpec("var_name", "string", "sm_state")}
    inputs  = [PinSpec("", EXEC),
               PinSpec("target", OBJECT, default=None),
               PinSpec("set_state", STRING, default="")]
    outputs = [PinSpec("state_a", EXEC), PinSpec("state_b", EXEC),
               PinSpec("state_c", EXEC), PinSpec("state_d", EXEC),
               PinSpec("current_state", STRING)]
    def generate_code(self, ctx, node, visited):
        t       = self.object_input_expr(ctx, node, "target", "me")
        vname   = repr(self.prop_value(node, "var_name", "sm_state"))
        states  = [self.prop_value(node, k, "") for k in ("state_a","state_b","state_c","state_d")]
        set_in  = self.input_expr(ctx, node, "set_state") if ctx.find_input_link(node["id"], "set_state") else '""'
        cs      = ctx.fresh_var("sm_cs")
        ctx.expr_cache[(node["id"], "current_state")] = cs
        ctx.emit(f"if {set_in}: ctx.set_local_var({t}, {vname}, {set_in})")
        ctx.emit(f"{cs} = ctx.get_local_var({t}, {vname}, {repr(states[0])})")
        for i, (pin, state) in enumerate(zip(("state_a","state_b","state_c","state_d"), states)):
            if state:
                ctx.emit(f"if {cs} == {repr(state)}:")
                ctx.push_indent()
                ctx.generate_exec_branch(node["id"], pin, visited)
                ctx.emit("pass")
                ctx.pop_indent()

@register_node("flow_defer", "Utility", "Defer",
               "Queues execution to run at the START of the next on_tick call instead of right now. Prevents mid-frame side effects. Like Godot call_deferred().")
class DeferNode(NodeBase):
    inputs  = [PinSpec("", EXEC)]
    outputs = [PinSpec("next_tick", EXEC)]
    def generate_code(self, ctx, node, visited):
        dk  = ctx.state_name(node["id"], "deferred")
        ctx.emit(f"if me.setdefault('_ns_state',{{}}).get('{dk}'):")
        ctx.push_indent()
        ctx.emit(f"me['_ns_state']['{dk}'] = False")
        ctx.generate_exec_branch(node["id"], "next_tick", visited)
        ctx.emit("pass")
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.emit(f"me['_ns_state']['{dk}'] = True")
        ctx.pop_indent()

@register_node("movement_pathfind_to", "Movement", "Pathfind To",
               "Moves toward a target while avoiding other characters (simple steering: moves toward goal, steers around blockers within avoidance_radius). Not full A* but effective for arena crowds.")
class PathfindToNode(NodeBase):
    properties = {"speed":            PropSpec("speed",            "number", 150, min_val=1, max_val=2000),
                  "avoidance_radius": PropSpec("avoidance_radius", "number", 40,  min_val=0, max_val=300)}
    inputs  = [PinSpec("", EXEC),
               PinSpec("source",           OBJECT, default=None),
               PinSpec("goal",             OBJECT, default=None),
               PinSpec("speed",            NUMBER, default=150),
               PinSpec("avoidance_radius", NUMBER, default=40)]
    outputs = [PinSpec("", EXEC),
               PinSpec("arrived", EXEC, tooltip="Fires when within arrival threshold of goal")]
    def generate_code(self, ctx, node, visited):
        src  = self.object_input_expr(ctx, node, "source", "me")
        goal = self.object_input_expr(ctx, node, "goal",   "me")
        spd  = self.input_expr(ctx, node, "speed")  if ctx.find_input_link(node["id"], "speed")  else repr(self.prop_value(node, "speed", 150))
        arad = self.input_expr(ctx, node, "avoidance_radius") if ctx.find_input_link(node["id"], "avoidance_radius") else repr(self.prop_value(node, "avoidance_radius", 40))
        ctx.emit(f"if isinstance({goal}, dict) and {src} is not None:")
        ctx.push_indent()
        ctx.emit(f"_gpos = {goal}.get('pos') or {goal}")
        ctx.emit(f"_delta = pygame.Vector2(_gpos) - {src}['pos']")
        ctx.emit("_dist  = _delta.length()")
        ctx.emit("if _dist > 4:")
        ctx.push_indent()
        ctx.emit("_dir = _delta.normalize()")
        ctx.emit("_avoid = pygame.Vector2(0, 0)")
        ctx.emit("for _nb in characters:")
        ctx.push_indent()
        ctx.emit(f"if _nb is {src} or _nb.get('hp',0)<=0: continue")
        ctx.emit(f"_off = {src}['pos'] - _nb['pos']")
        ctx.emit("_od  = _off.length()")
        ctx.emit(f"if 0 < _od < {arad}: _avoid += _off.normalize() * ({arad} - _od) / max(1,{arad})")
        ctx.pop_indent()
        ctx.emit("_steer = (_dir + _avoid * 0.5)")
        ctx.emit("if _steer.length_squared() > 0: _steer = _steer.normalize()")
        ctx.emit(f"{src}['vel'] = _steer * {spd}")
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.generate_exec_branch(node["id"], "arrived", visited)
        ctx.emit("pass")
        ctx.pop_indent()
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("vfx_spawn_trail", "Visual Effects", "Spawn Trail",
               "Emits a burst of particles along a line between two world positions — creates a trail, slash, or beam effect.")
class SpawnTrailNode(NodeBase):
    properties = {"count":     PropSpec("count",     "number", 12,  min_val=1,   max_val=200),
                  "width":     PropSpec("width",     "number", 6.0, min_val=0.5, max_val=60.0),
                  "lifetime":  PropSpec("lifetime",  "number", 0.5, min_val=0.1, max_val=4.0),
                  "color":     PropSpec("color",     "color",  [255, 200, 80])}
    inputs  = [PinSpec("", EXEC),
               PinSpec("from_pos", VECTOR, default=(0, 0)),
               PinSpec("to_pos",   VECTOR, default=(100, 0)),
               PinSpec("count",    NUMBER, default=12),
               PinSpec("color",    COLOR,  default=[255, 200, 80])]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        fp  = self.input_expr(ctx, node, "from_pos") if ctx.find_input_link(node["id"], "from_pos") else "me.get('pos', pygame.Vector2(0,0))"
        tp  = self.input_expr(ctx, node, "to_pos")   if ctx.find_input_link(node["id"], "to_pos")   else "me.get('pos', pygame.Vector2(0,0))"
        cnt = self.input_expr(ctx, node, "count")    if ctx.find_input_link(node["id"], "count")    else repr(int(self.prop_value(node, "count", 12)))
        col = self.input_expr(ctx, node, "color")    if ctx.find_input_link(node["id"], "color")    else repr(tuple(int(c) for c in (self.prop_value(node, "color", [255,200,80]) or [255,200,80])))
        w   = repr(float(self.prop_value(node, "width",   6.0)))
        lf  = repr(float(self.prop_value(node, "lifetime",0.5)))
        ctx.emit(f"_fp = pygame.Vector2({fp}); _tp = pygame.Vector2({tp})")
        ctx.emit(f"for _ti in range(int({cnt})):")
        ctx.push_indent()
        ctx.emit(f"_tf = _ti / max(1, int({cnt}) - 1)")
        ctx.emit("_tpos = _fp.lerp(_tp, _tf)")
        ctx.emit("particles.append({{")
        ctx.push_indent()
        ctx.emit(f"'pos': _tpos + pygame.Vector2(random.uniform(-{w},{w}), random.uniform(-{w},{w})),")
        ctx.emit("'vel': pygame.Vector2(random.uniform(-30,30), random.uniform(-30,30)),")
        ctx.emit(f"'life': {lf}, 'max_life': {lf},")
        ctx.emit(f"'color': {col}, 'size': random.uniform(2, {w}),")
        ctx.pop_indent()
        ctx.emit("}})")
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "", visited)

# ─────────────────────────────────────────────────────────────────────────────
# EASING, INTERPOLATION, COLOR LERP, OPACITY
# ─────────────────────────────────────────────────────────────────────────────

# All easing functions operate on t ∈ [0, 1] and return a value in [0, 1]
# (some overshoot slightly, e.g. back/elastic).

@register_node("math_ease", "Math", "Ease",
               "Applies an easing curve to a 0→1 progress value. "
               "Wire a Normalize Range or Tween Value progress into this, "
               "then pipe the result into a Lerp or Color Lerp. "
               "Covers all standard curves: linear, quad, cubic, quart, quint, "
               "sine, expo, circ, back, elastic, bounce — each with in/out/inout variants.")
class EaseNode(NodeBase):
    properties = {
        "curve": PropSpec("curve", "dropdown", "sine_inout", options=_EaseCurveOptions()),
    }
    inputs  = [PinSpec("t", NUMBER, default=0.5)]
    outputs = [PinSpec("eased", NUMBER),
               PinSpec("curve_name", STRING, tooltip="Selected curve name - wire into a Jab/Thrust/Swing Easing pin")]
    pure    = True

    # All formulas as concise lambdas — avoids separate imports in generated code
    _EASE_EXPRS = {
        "linear":        "_t",
        "quad_in":       "_t*_t",
        "quad_out":      "_t*(2-_t)",
        "quad_inout":    "(2*_t*_t if _t<.5 else -1+(4-2*_t)*_t)",
        "cubic_in":      "_t*_t*_t",
        "cubic_out":     "(_t-1)**3+1",
        "cubic_inout":   "(4*_t*_t*_t if _t<.5 else (_t-1)*(2*_t-2)**2+1)",
        "quart_in":      "_t*_t*_t*_t",
        "quart_out":     "1-(_t-1)**4",
        "quart_inout":   "(8*_t**4 if _t<.5 else 1-8*(_t-1)**4)",
        "quint_in":      "_t**5",
        "quint_out":     "1-(_t-1)**5",
        "quint_inout":   "(16*_t**5 if _t<.5 else 1+16*(_t-1)**5)",
        "sine_in":       "1-math.cos(_t*math.pi/2)",
        "sine_out":      "math.sin(_t*math.pi/2)",
        "sine_inout":    "-(math.cos(math.pi*_t)-1)/2",
        "expo_in":       "(0 if _t==0 else 2**(10*_t-10))",
        "expo_out":      "(1 if _t==1 else 1-2**(-10*_t))",
        "expo_inout":    "(0 if _t==0 else 1 if _t==1 else (2**(20*_t-10)/2 if _t<.5 else (2-2**(10-20*_t))/2))",
        "circ_in":       "1-math.sqrt(1-_t*_t)",
        "circ_out":      "math.sqrt(1-((_t-1)**2))",
        "circ_inout":    "((1-math.sqrt(1-4*_t*_t))/2 if _t<.5 else (math.sqrt(1-(2*_t-2)**2)+1)/2)",
        "back_in":       "2.70158*_t**3-1.70158*_t*_t",
        "back_out":      "1+2.70158*(_t-1)**3+1.70158*(_t-1)**2",
        "back_inout":    "((_t*2)**2*(3.59491*(_t*2)-2.59491)/2 if _t<.5 else ((_t*2-2)**2*(3.59491*(_t*2-2)+2.59491)+2)/2)",
        "elastic_in":    "(0 if _t==0 else 1 if _t==1 else -(2**(10*_t-10))*math.sin((_t*10-10.75)*(2*math.pi)/3))",
        "elastic_out":   "(0 if _t==0 else 1 if _t==1 else 2**(-10*_t)*math.sin((_t*10-.75)*(2*math.pi)/3)+1)",
        "elastic_inout": "(0 if _t==0 else 1 if _t==1 else (-(2**(20*_t-10)*math.sin((20*_t-11.125)*(2*math.pi)/4.5))/2 if _t<.5 else (2**(-20*_t+10)*math.sin((20*_t-11.125)*(2*math.pi)/4.5))/2+1))",
        "bounce_in":     "1-(lambda u:( 7.5625*u*u if u<1/2.75 else 7.5625*(u-1.5/2.75)**2+.75 if u<2/2.75 else 7.5625*(u-2.25/2.75)**2+.9375 if u<2.5/2.75 else 7.5625*(u-2.625/2.75)**2+.984375))(1-_t)",
        "bounce_out":    "(lambda u:( 7.5625*u*u if u<1/2.75 else 7.5625*(u-1.5/2.75)**2+.75 if u<2/2.75 else 7.5625*(u-2.25/2.75)**2+.9375 if u<2.5/2.75 else 7.5625*(u-2.625/2.75)**2+.984375))(_t)",
        "bounce_inout":  "((1-(lambda u:(7.5625*u*u if u<1/2.75 else 7.5625*(u-1.5/2.75)**2+.75 if u<2/2.75 else 7.5625*(u-2.25/2.75)**2+.9375 if u<2.5/2.75 else 7.5625*(u-2.625/2.75)**2+.984375))(1-2*_t))/2 if _t<.5 else (1+(lambda u:(7.5625*u*u if u<1/2.75 else 7.5625*(u-1.5/2.75)**2+.75 if u<2/2.75 else 7.5625*(u-2.25/2.75)**2+.9375 if u<2.5/2.75 else 7.5625*(u-2.625/2.75)**2+.984375))(2*_t-1))/2)",
        "discrete":      "float(int(_t*10)/10)",   # snaps to 0.0,0.1,0.2… for stepped/pixelated look
    }

    def generate_output_expr(self, ctx, node, output_name):
        curve = self.prop_value(node, "curve", "sine_inout")
        if output_name == "curve_name":
            return repr(str(curve))
        t_in  = self.input_expr(ctx, node, "t") if ctx.find_input_link(node["id"], "t") else "0.5"
        if _is_custom_curve_name(curve):
            return f"ctx.curve_eval({str(curve)!r}, float({t_in}))"
        expr  = self._EASE_EXPRS.get(curve, "_t")
        return f"(lambda _t: max(0.0, min(1.0, {expr})))(max(0.0, min(1.0, float({t_in}))))"

@register_node("math_interpolate", "Math", "Interpolate",
               "Blends from value A to value B over Duration with an easing curve. "
               "NEEDS PER-FRAME EXECUTION: wire Every Frame (or On Tick) into its white pin — each "
               "pulse advances the animation one step. Triggering it from a one-shot or slow event "
               "(Every X Seconds, On Hit) only advances it a single step, so nothing visibly moves. "
               "From Every Frame it runs 0→1 then STOPS at To (unless Loop/PingPong is on). "
               "For a one-shot effect fired by a slow event, use Fade Opacity or Flicker Opacity "
               "instead — those are fire-and-forget and time themselves. "
               "Wire the 'value' output into anything — speed, damage, opacity, color channels, etc.")
class InterpolateNode(NodeBase):
    properties = {
        "curve": PropSpec("curve", "dropdown", "sine_inout", options=_EaseCurveOptions()),
        "duration": PropSpec("duration", "number", 1.0, min_val=0.01, max_val=60.0),
        "loop":     PropSpec("loop",     "boolean", False),
        "pingpong": PropSpec("pingpong", "boolean", False),
    }
    inputs  = [PinSpec("",         EXEC),
               PinSpec("target",   OBJECT, default=None),
               PinSpec("from_val", NUMBER, default=0.0),
               PinSpec("to_val",   NUMBER, default=1.0),
               PinSpec("duration", NUMBER, default=1.0)]
    outputs = [PinSpec("",       EXEC,   tooltip="Fires every frame while running"),
               PinSpec("value",  NUMBER, tooltip="THE RESULT: the blended number between From and To (already eased). This is the pin you usually want — wire it into speed, scale, damage, etc."),
               PinSpec("progress", NUMBER, tooltip="Raw clock progress 0→1: how far through the Duration we are, on a straight line — the curve has NOT been applied yet. 0 = just started, 1 = finished."),
               PinSpec("eased_progress", NUMBER, tooltip="Progress 0→1 AFTER the easing curve bends it. Same start/end as progress, but follows the curve's shape in between. Feed this into Color Lerp or your own math to ease anything."),
               PinSpec("done",   EXEC,   tooltip="Fires once when finished (non-looping only)"),
               PinSpec("curve_name", STRING, tooltip="The curve picked in this node's dropdown, as text. Wire into a Curve input (Opacity Fade, Ease Value, Jab/Thrust/Swing Easing) so both nodes use the SAME curve.")]
    def generate_code(self, ctx, node, visited):
        t_obj  = self.object_input_expr(ctx, node, "target", "me")
        frm    = self.input_expr(ctx, node, "from_val") if ctx.find_input_link(node["id"], "from_val") else repr(self.prop_value(node, "from_val", 0.0))
        to     = self.input_expr(ctx, node, "to_val")   if ctx.find_input_link(node["id"], "to_val")   else repr(self.prop_value(node, "to_val",   1.0))
        dur    = self.input_expr(ctx, node, "duration")  if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration",  1.0))
        curve  = self.prop_value(node, "curve", "sine_inout")
        loop   = repr(bool(self.prop_value(node, "loop", False)))
        pp     = repr(bool(self.prop_value(node, "pingpong", False)))
        ease_expr = EaseNode._EASE_EXPRS.get(curve, "_t")

        tk  = ctx.state_name(node["id"], "t")
        dk  = ctx.state_name(node["id"], "dur")
        sk  = ctx.state_name(node["id"], "started")
        fk  = ctx.state_name(node["id"], "from")
        ppk = ctx.state_name(node["id"], "pp_dir")

        v    = ctx.fresh_var("interp_val")
        raw_t= ctx.fresh_var("interp_raw")
        ez_t = ctx.fresh_var("interp_ez")

        ctx.expr_cache[(node["id"], "value")]   = v
        ctx.expr_cache[(node["id"], "progress")] = raw_t
        ctx.expr_cache[(node["id"], "eased_progress")] = ez_t
        # Legacy pin names ("t"/"eased_t") — old saved graphs may still have
        # wires attached to them; keep both spellings resolving forever.
        ctx.expr_cache[(node["id"], "t")]        = raw_t
        ctx.expr_cache[(node["id"], "eased_t")]  = ez_t
        ctx.expr_cache[(node["id"], "curve_name")] = repr(str(curve))

        ctx.emit(f"if not {t_obj}.get('_ns_state',{{}}).get('{sk}'):")
        ctx.push_indent()
        ctx.emit(f"{t_obj}.setdefault('_ns_state',{{}})['{fk}'] = {frm}")
        ctx.emit(f"{t_obj}['_ns_state']['{dk}'] = max(0.001, float({dur}))")
        ctx.emit(f"{t_obj}['_ns_state']['{tk}'] = 0.0")
        ctx.emit(f"{t_obj}['_ns_state']['{ppk}'] = 1")
        ctx.emit(f"{t_obj}['_ns_state']['{sk}'] = True")
        ctx.pop_indent()

        ctx.emit(f"{t_obj}['_ns_state']['{tk}'] += dt * {t_obj}['_ns_state'].get('{ppk}', 1)")
        ctx.emit(f"{raw_t} = max(0.0, min(1.0, {t_obj}['_ns_state']['{tk}'] / {t_obj}['_ns_state'].get('{dk}', 1.0)))")
        if _is_custom_curve_name(curve):
            ctx.emit(f"{ez_t}  = ctx.curve_eval({str(curve)!r}, {raw_t})")
        else:
            ctx.emit(f"{ez_t}  = (lambda _t: max(0.0, min(1.0, {ease_expr})))({raw_t})")
        ctx.emit(f"{v}     = {t_obj}['_ns_state'].get('{fk}', {frm}) + ({to} - {t_obj}['_ns_state'].get('{fk}', {frm})) * {ez_t}")
        ctx.generate_exec_branch(node["id"], "", visited)

        # loop / pingpong / done
        ctx.emit(f"if {t_obj}['_ns_state']['{tk}'] >= {t_obj}['_ns_state'].get('{dk}', 1.0):")
        ctx.push_indent()
        ctx.emit(f"if {pp}:")
        ctx.push_indent()
        ctx.emit(f"{t_obj}['_ns_state']['{ppk}'] = -1")
        ctx.pop_indent()
        ctx.emit(f"elif {loop}:")
        ctx.push_indent()
        ctx.emit(f"{t_obj}['_ns_state']['{tk}'] = 0.0")
        ctx.emit(f"{t_obj}['_ns_state']['{fk}'] = {frm}")
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.emit(f"{t_obj}['_ns_state']['{sk}'] = False")
        ctx.generate_exec_branch(node["id"], "done", visited)
        ctx.emit("pass")
        ctx.pop_indent()
        ctx.pop_indent()

        # pingpong reverse
        ctx.emit(f"if {pp} and {t_obj}['_ns_state']['{tk}'] <= 0.0:")
        ctx.push_indent()
        ctx.emit(f"{t_obj}['_ns_state']['{ppk}'] = 1")
        if not self.prop_value(node, "loop", False):
            ctx.emit(f"{t_obj}['_ns_state']['{sk}'] = False")
            ctx.generate_exec_branch(node["id"], "done", visited)
            ctx.emit("pass")
        ctx.pop_indent()

# ══════════════════════════════════════════════════════════════════════════
# PROJECTILE FLIGHT SETTER NODES  (hand-written so their vector pins get real
# defaults instead of snapping toward world origin when left unwired)
# ══════════════════════════════════════════════════════════════════════════
def _flight_set_inputs(extra):
    return ([PinSpec("", EXEC), PinSpec("projectile", OBJECT, default=None),
             PinSpec("name", STRING, default="main")] +
            [PinSpec(n, t, default=d) for (n, t, d) in extra])


def _flight_set_outputs():
    return [PinSpec("", EXEC), PinSpec("projectile", OBJECT), PinSpec("name", STRING)]


def _flight_nm_expr(self, ctx, node):
    return (self.input_expr(ctx, node, "name") if ctx.find_input_link(node["id"], "name")
            else repr(self.prop_value(node, "name", "main")))


class _FlightSetterNode(NodeBase):
    flight_key = ""
    extra = ()           # (name, pin_type, default)
    none_defaults = ()   # fields passed as None when not wired
    inputs = []
    outputs = []

    def generate_code(self, ctx, node, visited):
        obj = self.input_expr(ctx, node, "projectile") if ctx.find_input_link(node["id"], "projectile") else "None"
        nm = _flight_nm_expr(self, ctx, node)
        args = [f"projectile={obj}", f"name={nm}"]
        for (n, t, d) in self.extra:
            if n in self.none_defaults:
                expr = self.input_expr(ctx, node, n) if ctx.find_input_link(node["id"], n) else "None"
            else:
                expr = (self.input_expr(ctx, node, n) if ctx.find_input_link(node["id"], n)
                        else repr(self.prop_value(node, n, d)))
            args.append(f"{n}={expr}")
        ctx.emit(f"ctx.weapon_op({self.flight_key!r}, me, {', '.join(args)})")
        ctx.generate_exec_branch(node["id"], "", visited)

    def generate_output_expr(self, ctx, node, pin_name):
        if pin_name == "projectile":
            obj = self.input_expr(ctx, node, "projectile") if ctx.find_input_link(node["id"], "projectile") else "None"
            nm = _flight_nm_expr(self, ctx, node)
            return f"({obj} if isinstance({obj}, dict) else ctx.weapon_value('rig_projectile_last', me, name={nm}))"
        if pin_name == "name":
            return _flight_nm_expr(self, ctx, node)
        return "None"


@register_node("projectile_flight_curve", "Projectiles", "Set Flight: Curved Arc",
               "Fly along an eased curved arc between the launch point and an End position. "
               "Curvature bulges the arc sideways (banana / underspin shot). Ping-Pong flies out "
               "then back along the same curve; Loop repeats forever; Destroy On Done despawns "
               "when the arc completes. The Easing pin uses the same curve vocabulary as the "
               "Interpolate/Ease nodes, so a flight curve and a value blend can share one curve.")
class FlightCurveNode(_FlightSetterNode):
    flight_key = "rig_projectile_flight_curve"
    extra = (("end", VECTOR, (0.0, 0.0)), ("curvature", NUMBER, 0.0), ("duration", NUMBER, 1.0),
             ("easing", STRING, "smoothstep"), ("pingpong", BOOLEAN, False), ("loop", BOOLEAN, False),
             ("hold_ratio", NUMBER, 0.0), ("destroy_on_done", BOOLEAN, False))
    # end defaults to "straight ahead" (weapon_op falls back to current angle + 140px).
    none_defaults = ("end",)
    inputs = _flight_set_inputs(extra)
    outputs = _flight_set_outputs()
    properties = {
        "name": PropSpec("name", "string", "main"),
        "curvature": PropSpec("curvature", "number", 0.0, min_val=-4000.0, max_val=4000.0),
        "duration": PropSpec("duration", "number", 1.0, min_val=0.01, max_val=60.0),
        "easing": PropSpec("easing", "dropdown", "smoothstep", options=_EaseCurveOptions()),
        "pingpong": PropSpec("pingpong", "boolean", False),
        "loop": PropSpec("loop", "boolean", False),
        "hold_ratio": PropSpec("hold_ratio", "number", 0.0, min_val=0.0, max_val=1.0),
        "destroy_on_done": PropSpec("destroy_on_done", "boolean", False),
    }


