@register_node("projectile_flight_return_speed", "Projectiles", "Set Flight: Return Speed",
               "Change how fast the RETURN / back leg of a return-capable flight (boomerang, out and "
               "back swing) travels, on the fly. Separate from the launch speed, so the projectile can "
               "throw out at one pace and swoop home at another. The Return Easing curve then modulates "
               "this speed along the way (a fast-start curve like ease_out shoots off, a gentle curve "
               "like ease_in starts slower), so pair it with Set Flight: Return Easing for a shaped "
               "comeback. On a tethered (yoyo) projectile with no flight mode it sets the reel-in speed.")
class FlightReturnSpeedNode(_FlightSetterNode):
    flight_key = "rig_projectile_flight_return_speed"
    extra = (("return_speed", NUMBER, 420.0),)
    none_defaults = ()
    inputs = _flight_set_inputs(extra)
    outputs = _flight_set_outputs()
    properties = {
        "name": PropSpec("name", "string", "main"),
        "return_speed": PropSpec("return_speed", "number", 420.0, min_val=10.0, max_val=6000.0,
                                 tooltip="Speed (px/sec) of the return/back leg before the Return Easing curve modulates it. 420 is the default. Higher = a faster, more decisive swing home; lower = a slower, lazier comeback."),
    }


@register_node("projectile_flight_return_arc", "Projectiles", "Set Flight: Return Arc",
               "Bend the RETURN / back leg of a throw-and-return projectile (boomerang, yoyo, "
               "grappling hook) into a visible curved swoop instead of a straight reel home. Positive "
               "bows to one side, negative to the other; 0 (default) = the classic straight comeback. "
               "The bow is zero at both ends so it joins the throw and the catch smoothly. On a "
               "tethered (yoyo) projectile with no flight mode it curves the reel-in; on a flight "
               "boomerang/out-and-back it feeds the return curvature. Pair with Set Flight: Return "
               "Speed / Return Easing to shape how the curve is traversed.")
class FlightReturnArcNode(_FlightSetterNode):
    flight_key = "rig_projectile_flight_return_arc"
    extra = (("return_arc", NUMBER, 0.0),)
    none_defaults = ()
    inputs = _flight_set_inputs(extra)
    outputs = _flight_set_outputs()
    properties = {
        "name": PropSpec("name", "string", "main"),
        "return_arc": PropSpec("return_arc", "number", 0.0, min_val=-600.0, max_val=600.0,
                               tooltip="How far (px) the comeback bows sideways from the straight line home. 0 = straight. Positive bows one way, negative the other. The bow is zero at the start and the catch, so it always reaches the owner."),
    }


@register_node("projectile_flight_waypoints", "Projectiles", "Set Flight: Waypoint Path",
               "Follow a smoothed Catmull-Rom polyline through up to six world route waypoints "
               "over a Duration, eased by the chosen curve. The launch position is always the "
               "first route point. Ping-Pong retraces the route backward; Loop repeats.")
class FlightWaypointsNode(_FlightSetterNode):
    flight_key = "rig_projectile_flight_waypoints"
    extra = (("w1", VECTOR, (0.0, 0.0)), ("w2", VECTOR, (0.0, 0.0)), ("w3", VECTOR, (0.0, 0.0)),
             ("w4", VECTOR, (0.0, 0.0)), ("w5", VECTOR, (0.0, 0.0)), ("w6", VECTOR, (0.0, 0.0)),
             ("duration", NUMBER, 1.0), ("easing", STRING, "smoothstep"),
             ("pingpong", BOOLEAN, False), ("loop", BOOLEAN, False), ("destroy_on_done", BOOLEAN, False))
    inputs = _flight_set_inputs(extra)
    outputs = _flight_set_outputs()
    properties = {
        "name": PropSpec("name", "string", "main"),
        "duration": PropSpec("duration", "number", 1.0, min_val=0.01, max_val=60.0),
        "easing": PropSpec("easing", "dropdown", "smoothstep", options=_EaseCurveOptions()),
        "pingpong": PropSpec("pingpong", "boolean", False),
        "loop": PropSpec("loop", "boolean", False),
        "destroy_on_done": PropSpec("destroy_on_done", "boolean", False),
    }

    def generate_code(self, ctx, node, visited):
        obj = self.input_expr(ctx, node, "projectile") if ctx.find_input_link(node["id"], "projectile") else "None"
        nm = _flight_nm_expr(self, ctx, node)
        pts = []
        for i in range(1, 7):
            if ctx.find_input_link(node["id"], f"w{i}"):
                pts.append(self.input_expr(ctx, node, f"w{i}"))
        if not pts:
            # No waypoints wired: default to a straight line ahead of the
            # owner so the projectile still travels somewhere meaningful.
            pts = ["pygame.Vector2(1,0).rotate(float(me.get('angle',0.0)))*140"]
        args = [f"projectile={obj}", f"name={nm}", "points=[" + ", ".join(pts) + "]"]
        args.append("duration=" + (self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 1.0))))
        args.append("easing=" + (self.input_expr(ctx, node, "easing") if ctx.find_input_link(node["id"], "easing") else repr(self.prop_value(node, "easing", "smoothstep"))))
        args.append("pingpong=" + (self.input_expr(ctx, node, "pingpong") if ctx.find_input_link(node["id"], "pingpong") else repr(self.prop_value(node, "pingpong", False))))
        args.append("loop=" + (self.input_expr(ctx, node, "loop") if ctx.find_input_link(node["id"], "loop") else repr(self.prop_value(node, "loop", False))))
        args.append("destroy_on_done=" + (self.input_expr(ctx, node, "destroy_on_done") if ctx.find_input_link(node["id"], "destroy_on_done") else repr(self.prop_value(node, "destroy_on_done", False))))
        ctx.emit(f"ctx.weapon_op({self.flight_key!r}, me, {', '.join(args)})")
        ctx.generate_exec_branch(node["id"], "", visited)


@register_node("projectile_flight_set_pos", "Projectiles", "Set Flight Position",
               "Move a projectile to a wired Position vector on every exec. Velocity is "
               "auto-derived from the previous position, so knockback / collision and travel "
               "angle still work. The classic way to drive a flight from interpolation nodes: "
               "wire an Interpolate 'eased_progress' into a Get Bezier Point node, then its "
               "'point' output into Position.")
class FlightSetPosNode(_FlightSetterNode):
    flight_key = "rig_projectile_flight_set_pos"
    extra = (("position", VECTOR, (0.0, 0.0)), ("dt", NUMBER, 0.016))
    none_defaults = ("position",)
    inputs = _flight_set_inputs(extra)
    outputs = _flight_set_outputs()
    properties = {
        "name": PropSpec("name", "string", "main"),
        "dt": PropSpec("dt", "number", 0.016, min_val=0.0001, max_val=1.0),
    }


@register_node("math_bezier_point", "Math", "Get Bezier Point",
               "Compute a point on a Bezier curve (returns a Position vector). Wire the output "
               "into Set Flight Position, Spawn Directional Particles, or any Position pin to "
               "trace a curved path. Pass 3 points (start, control, end) for a quadratic curve, "
               "or 4 points for a cubic. The result is eased by t, so drive t from an "
               "Interpolate/Ease node to shape the motion.")
class MathBezierPointNode(NodeBase):
    inputs = [PinSpec("p0", VECTOR, default=(0.0, 0.0)), PinSpec("p1", VECTOR, default=(1.0, 0.0)),
              PinSpec("p2", VECTOR, default=(1.0, 1.0)), PinSpec("p3", VECTOR, default=None),
              PinSpec("t", NUMBER, default=0.5)]
    outputs = [PinSpec("point", VECTOR)]
    properties = {"degree": PropSpec("degree", "dropdown", "quadratic", options=["quadratic", "cubic"])}
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        p0 = self.input_expr(ctx, node, "p0") if ctx.find_input_link(node["id"], "p0") else "(0.0, 0.0)"
        p1 = self.input_expr(ctx, node, "p1") if ctx.find_input_link(node["id"], "p1") else "(1.0, 0.0)"
        p2 = self.input_expr(ctx, node, "p2") if ctx.find_input_link(node["id"], "p2") else "(1.0, 1.0)"
        t = self.input_expr(ctx, node, "t") if ctx.find_input_link(node["id"], "t") else "0.5"
        cubic = bool(ctx.find_input_link(node["id"], "p3")) or str(self.prop_value(node, "degree", "quadratic")) == "cubic"
        if cubic:
            p3 = self.input_expr(ctx, node, "p3") if ctx.find_input_link(node["id"], "p3") else "(1.0, 1.0)"
            return (f"_ns_bezier_point({p0}, {p1}, {p2}, {p3}, {t})")
        return f"_ns_bezier_point({p0}, {p1}, {p2}, None, {t})"


@register_node("math_path_point", "Math", "Get Point Along Path",
               "Compute a smoothed point along a Catmull-Rom waypoint route at a given t, "
               "returning a Position vector. Wire the output into Set Flight Position to fly a "
               "projectile along a custom route driven by an Interpolate/Ease t.")
class MathPathPointNode(NodeBase):
    inputs = [PinSpec("w1", VECTOR, default=(0.0, 0.0)), PinSpec("w2", VECTOR, default=(1.0, 0.0)),
              PinSpec("w3", VECTOR, default=(1.0, 1.0)), PinSpec("w4", VECTOR, default=None),
              PinSpec("w5", VECTOR, default=None), PinSpec("w6", VECTOR, default=None),
              PinSpec("t", NUMBER, default=0.5)]
    outputs = [PinSpec("point", VECTOR)]
    pure = True
    def generate_output_expr(self, ctx, node, output_name):
        pts = []
        for i in range(1, 7):
            if ctx.find_input_link(node["id"], f"w{i}"):
                pts.append(self.input_expr(ctx, node, f"w{i}"))
        if not pts:
            pts = ["(0.0,0.0)", "(1.0,0.0)"]
        t = self.input_expr(ctx, node, "t") if ctx.find_input_link(node["id"], "t") else "0.5"
        return f"_ns_catmull_point([{', '.join(pts)}], {t})"

@register_node("math_ease_value", "Math", "Ease Value",
               "Moves any number from From to To over Duration. Wire Every Frame into it, "
               "send Value into opacity/speed/scale/etc., and connect Done to Destroy. "
               "The Curve input accepts curve_name from an Ease or Interpolate node, so the "
               "fade and Done signal always finish on the same frame.")
class EaseValueNode(NodeBase):
    properties = {
        "from_val": PropSpec("from_val", "number", 1.0),
        "to_val": PropSpec("to_val", "number", 0.0),
        "duration": PropSpec("duration", "number", 1.0, min_val=0.001, max_val=600.0),
        "curve": PropSpec("curve", "dropdown", "sine_inout", options=_EaseCurveOptions()),
    }
    inputs = [
        PinSpec("", EXEC, tooltip="Call every frame (Every Frame / On Tick)"),
        PinSpec("target", OBJECT, default=None,
                tooltip="Optional state owner; wire the projectile here so each projectile gets its own ease"),
        PinSpec("from_val", NUMBER, default=1.0),
        PinSpec("to_val", NUMBER, default=0.0),
        PinSpec("duration", NUMBER, default=1.0),
        PinSpec("curve", STRING, default="sine_inout",
                tooltip="Curve name; accepts curve_name from Ease or Interpolate"),
    ]
    outputs = [
        PinSpec("", EXEC, tooltip="Fires every frame while the value is changing"),
        PinSpec("done", EXEC, tooltip="Fires exactly once, after Value reaches To"),
        PinSpec("value", NUMBER, tooltip="THE RESULT: the blended number between From and To (already eased). Usually the pin you want."),
        PinSpec("progress", NUMBER, tooltip="Raw clock progress 0→1: how far through the Duration we are, before the curve is applied."),
        PinSpec("eased_progress", NUMBER, tooltip="Progress 0→1 AFTER the easing curve bends it — follows the curve's shape between start and end."),
        PinSpec("finished", BOOLEAN, tooltip="True after completion"),
        PinSpec("remaining", NUMBER, tooltip="Seconds remaining"),
        PinSpec("curve_name", STRING, tooltip="The curve this node is using, as text. Wire into another node's Curve input to share the exact same curve."),
    ]

    def generate_code(self, ctx, node, visited):
        target_expr = self.object_input_expr(ctx, node, "target", "me")
        frm = (self.input_expr(ctx, node, "from_val")
               if ctx.find_input_link(node["id"], "from_val")
               else repr(self.prop_value(node, "from_val", 1.0)))
        to = (self.input_expr(ctx, node, "to_val")
              if ctx.find_input_link(node["id"], "to_val")
              else repr(self.prop_value(node, "to_val", 0.0)))
        dur = (self.input_expr(ctx, node, "duration")
               if ctx.find_input_link(node["id"], "duration")
               else repr(self.prop_value(node, "duration", 1.0)))
        curve = (self.input_expr(ctx, node, "curve")
                 if ctx.find_input_link(node["id"], "curve")
                 else repr(str(self.prop_value(node, "curve", "sine_inout"))))

        host = ctx.fresh_var("ease_host")
        state = ctx.fresh_var("ease_state")
        raw = ctx.fresh_var("ease_progress")
        eased = ctx.fresh_var("ease_t")
        value = ctx.fresh_var("ease_value")
        remaining = ctx.fresh_var("ease_remaining")
        curve_var = ctx.fresh_var("ease_curve")
        step_dt = ctx.fresh_var("ease_dt")
        key = f"ease_value_{node['id']}"

        ctx.expr_cache[(node["id"], "value")] = value
        ctx.expr_cache[(node["id"], "progress")] = raw
        ctx.expr_cache[(node["id"], "eased_progress")] = eased
        ctx.expr_cache[(node["id"], "eased_t")] = eased  # legacy pin name — old graphs keep working
        ctx.expr_cache[(node["id"], "remaining")] = remaining
        ctx.expr_cache[(node["id"], "curve_name")] = curve_var
        ctx.expr_cache[(node["id"], "finished")] = f"bool({state}.get('completed', False))"

        ctx.emit(f"{host} = ({target_expr})")
        ctx.emit(f"if not isinstance({host}, dict): {host} = me")
        ctx.emit(f"{state} = {host}.setdefault('_ns_ease_values', {{}}).setdefault({key!r}, {{}})")
        ctx.emit(f"if not {state}.get('initialized', False):")
        ctx.push_indent()
        ctx.emit(f"{state}['from'] = float({frm})")
        ctx.emit(f"{state}['to'] = float({to})")
        ctx.emit(f"{state}['duration'] = max(0.001, float({dur}))")
        ctx.emit(f"{state}['curve'] = str({curve} or 'linear')")
        ctx.emit(f"{state}['elapsed'] = 0.0")
        ctx.emit(f"{state}['active'] = True")
        ctx.emit(f"{state}['completed'] = False")
        ctx.emit(f"{state}['initialized'] = True")
        ctx.pop_indent()

        # `dt` exists on On Tick/Every Frame hooks. The fallback prevents an
        # accidental one-shot event connection from throwing NameError; it
        # advances one frame, while the tooltip explains that recurring input
        # is required for a complete animation.
        ctx.emit(f"{step_dt} = max(0.0, float(locals().get('dt', 1.0 / 60.0)))")
        ctx.emit(f"{raw} = max(0.0, min(1.0, {state}.get('elapsed', 0.0) / {state}.get('duration', 1.0)))")
        ctx.emit(f"{curve_var} = str({state}.get('curve', 'linear'))")
        ctx.emit(f"{eased} = ctx.curve_eval({curve_var}, {raw})")
        ctx.emit(f"{value} = {state}.get('from', 0.0) + ({state}.get('to', 0.0) - {state}.get('from', 0.0)) * {eased}")
        ctx.emit(f"{remaining} = max(0.0, {state}.get('duration', 1.0) - {state}.get('elapsed', 0.0))")

        ctx.emit(f"if {state}.get('active', False):")
        ctx.push_indent()
        ctx.emit(f"{state}['elapsed'] = min({state}.get('duration', 1.0), {state}.get('elapsed', 0.0) + {step_dt})")
        ctx.emit(f"{raw} = max(0.0, min(1.0, {state}['elapsed'] / {state}.get('duration', 1.0)))")
        # Curve may be wired from Ease/Interpolate; read the connected value
        # each active frame so changing the selected style updates immediately.
        ctx.emit(f"{curve_var} = str({curve} or {state}.get('curve', 'linear'))")
        ctx.emit(f"{state}['curve'] = {curve_var}")
        ctx.emit(f"{eased} = ctx.curve_eval({curve_var}, {raw})")
        ctx.emit(f"{value} = {state}.get('from', 0.0) + ({state}.get('to', 0.0) - {state}.get('from', 0.0)) * {eased}")
        ctx.emit(f"{remaining} = max(0.0, {state}.get('duration', 1.0) - {state}['elapsed'])")

        # Update runs first, guaranteeing opacity receives the exact final
        # value (usually 0) before Done destroys the projectile.
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.emit(f"if {state}['elapsed'] >= {state}.get('duration', 1.0) and not {state}.get('completed', False):")
        ctx.push_indent()
        ctx.emit(f"{state}['active'] = False")
        ctx.emit(f"{state}['completed'] = True")
        ctx.generate_exec_branch(node["id"], "done", visited)
        ctx.pop_indent()
        ctx.pop_indent()

    def generate_output_expr(self, ctx, node, output_name):
        if output_name == "finished":
            return ctx.expr_cache.get((node["id"], "finished"), "False")
        if output_name == "curve_name":
            return ctx.expr_cache.get((node["id"], "curve_name"),
                                      repr(str(self.prop_value(node, "curve", "sine_inout"))))
        return ctx.expr_cache.get((node["id"], output_name), "0.0")


@register_node("math_color_lerp", "Math", "Color Lerp",
               "Smoothly blends between two RGB colors based on a 0→1 T value. "
               "Wire an Ease or Interpolate 'eased_t' output here to get smooth color transitions. "
               "The result is a Color you can plug directly into Tint Character, Flash Tint, "
               "Constant Color, particle color, etc.")
class ColorLerpNode(NodeBase):
    properties = {
        "from_color": PropSpec("from_color", "color", [255, 90, 90]),
        "to_color":   PropSpec("to_color",   "color", [90, 90, 255]),
    }
    inputs  = [PinSpec("t",          NUMBER, default=0.5),
               PinSpec("from_color", COLOR,  default=[255, 90, 90]),
               PinSpec("to_color",   COLOR,  default=[90, 90, 255])]
    outputs = [PinSpec("color", COLOR)]
    pure    = True
    def generate_output_expr(self, ctx, node, output_name):
        t  = self.input_expr(ctx, node, "t") if ctx.find_input_link(node["id"], "t") else "0.5"
        fc = self.input_expr(ctx, node, "from_color") if ctx.find_input_link(node["id"], "from_color") \
             else repr(tuple(int(c) for c in (self.prop_value(node, "from_color", [255,90,90]) or [255,90,90])))
        tc = self.input_expr(ctx, node, "to_color") if ctx.find_input_link(node["id"], "to_color") \
             else repr(tuple(int(c) for c in (self.prop_value(node, "to_color", [90,90,255]) or [90,90,255])))
        return (
            f"(lambda _t, _a, _b: ("
            f"int(_a[0]+(_b[0]-_a[0])*_t), "
            f"int(_a[1]+(_b[1]-_a[1])*_t), "
            f"int(_a[2]+(_b[2]-_a[2])*_t)"
            f"))(max(0.0,min(1.0,float({t}))), {fc}, {tc})"
        )

@register_node("vfx_tint_ease", "Visual Effects", "Tint Ease",
               "Applies an eased color tint to a character that fades from one color to another "
               "over a duration using your chosen easing curve. "
               "This is the all-in-one version of: Interpolate → Color Lerp → Tint Character. "
               "Example: on hit, ease from white to transparent over 0.4s with sine_out.")
class TintEaseNode(NodeBase):
    properties = {
        "curve":      PropSpec("curve", "dropdown", "sine_out", options=[
            "linear","quad_in","quad_out","quad_inout",
            "cubic_in","cubic_out","cubic_inout",
            "sine_in","sine_out","sine_inout",
            "expo_in","expo_out","expo_inout",
            "circ_in","circ_out","circ_inout",
            "bounce_out","elastic_out",
        ]),
        "from_color": PropSpec("from_color", "color", [255, 255, 255]),
        "to_color":   PropSpec("to_color",   "color", [0, 0, 0]),
        "duration":   PropSpec("duration",   "number", 0.5, min_val=0.01, max_val=30.0),
    }
    inputs  = [PinSpec("",           EXEC),
               PinSpec("target",     OBJECT, default=None),
               PinSpec("from_color", COLOR,  default=[255, 255, 255]),
               PinSpec("to_color",   COLOR,  default=[0, 0, 0]),
               PinSpec("duration",   NUMBER, default=0.5)]
    outputs = [PinSpec("", EXEC, tooltip="Fires every frame while easing"),
               PinSpec("done", EXEC, tooltip="Fires once when the ease completes")]
    def generate_code(self, ctx, node, visited):
        tgt   = self.object_input_expr(ctx, node, "target", "me")
        dur   = self.input_expr(ctx, node, "duration")   if ctx.find_input_link(node["id"], "duration")   else repr(self.prop_value(node, "duration",   0.5))
        fc    = self.input_expr(ctx, node, "from_color") if ctx.find_input_link(node["id"], "from_color") \
                else repr(tuple(int(c) for c in (self.prop_value(node, "from_color", [255,255,255]) or [255,255,255])))
        tc    = self.input_expr(ctx, node, "to_color")   if ctx.find_input_link(node["id"], "to_color")   \
                else repr(tuple(int(c) for c in (self.prop_value(node, "to_color",   [0,0,0])       or [0,0,0])))
        curve = self.prop_value(node, "curve", "sine_out")
        ease  = EaseNode._EASE_EXPRS.get(curve, "_t")

        tk = ctx.state_name(node["id"], "t")
        sk = ctx.state_name(node["id"], "started")
        dk = ctx.state_name(node["id"], "dur")

        ctx.emit(f"if not {tgt}.get('_ns_state',{{}}).get('{sk}'):")
        ctx.push_indent()
        ctx.emit(f"{tgt}.setdefault('_ns_state',{{}})['{dk}'] = max(0.001, float({dur}))")
        ctx.emit(f"{tgt}['_ns_state']['{tk}'] = 0.0")
        ctx.emit(f"{tgt}['_ns_state']['{sk}'] = True")
        ctx.pop_indent()

        ctx.emit(f"{tgt}['_ns_state']['{tk}'] = min(1.0, {tgt}['_ns_state'].get('{tk}', 0) + dt / {tgt}['_ns_state'].get('{dk}', 1.0))")
        ctx.emit(f"_te_raw = {tgt}['_ns_state']['{tk}']")
        ctx.emit(f"_te_ez  = (lambda _t: max(0.0, min(1.0, {ease})))(_te_raw)")
        ctx.emit(f"_te_fc  = {fc}")
        ctx.emit(f"_te_tc  = {tc}")
        ctx.emit("_te_col = (int(_te_fc[0]+(_te_tc[0]-_te_fc[0])*_te_ez), int(_te_fc[1]+(_te_tc[1]-_te_fc[1])*_te_ez), int(_te_fc[2]+(_te_tc[2]-_te_fc[2])*_te_ez))")
        ctx.emit(f"_ns_set_tint({tgt}, _te_col, dt * 2)  # short duration so tint tracks the lerp")
        ctx.generate_exec_branch(node["id"], "", visited)

        ctx.emit("if _te_raw >= 1.0:")
        ctx.push_indent()
        ctx.emit(f"{tgt}['_ns_state']['{sk}'] = False")
        ctx.generate_exec_branch(node["id"], "done", visited)
        ctx.emit("pass")
        ctx.pop_indent()

@register_node("vfx_opacity_fade", "Visual Effects", "Opacity Fade",
               "Fades a character's REAL transparency from one opacity to another over a "
               "duration with an easing curve: 1.0 = fully solid, 0.0 = fully invisible. "
               "This changes the sprite's actual alpha (not a color tint). "
               "Pick a curve in the dropdown — including your own F8 curves — or wire the "
               "curve_name output of an Interpolate / Ease / Ease Value node into the Curve "
               "input to drive the fade with that node's exact curve. "
               "Use for spawn pop-in, death fade-out, stealth effects, etc.")
class OpacityFadeNode(NodeBase):
    properties = {
        "curve":       PropSpec("curve", "dropdown", "sine_inout", options=_EaseCurveOptions()),
        "from_opacity": PropSpec("from_opacity", "number", 1.0, min_val=0.0, max_val=1.0),
        "to_opacity":   PropSpec("to_opacity",   "number", 0.0, min_val=0.0, max_val=1.0),
        # Legacy: kept so old saved graphs load cleanly. The node used to
        # animate a colour-tint overlay; it now drives true transparency and
        # never touches the colour.
        "color":        PropSpec("color",        "color",  [255, 255, 255],
                                 tooltip="Legacy (unused) — Opacity Fade now changes real transparency, not a tint"),
        "duration":     PropSpec("duration",     "number", 1.0, min_val=0.01, max_val=30.0),
        "loop":         PropSpec("loop",         "boolean", False),
    }
    inputs  = [PinSpec("",             EXEC),
               PinSpec("target",       OBJECT, default=None),
               PinSpec("from_opacity", NUMBER, default=1.0),
               PinSpec("to_opacity",   NUMBER, default=0.0),
               PinSpec("duration",     NUMBER, default=1.0),
               PinSpec("curve",        STRING, default="",
                       tooltip="Optional: wire curve_name from an Interpolate / Ease / Ease Value node. Overrides the dropdown."),
               PinSpec("color",        COLOR,  default=[255, 255, 255],
                       tooltip="Legacy (unused) — kept so old graphs still load")]
    outputs = [PinSpec("",      EXEC,   tooltip="Fires every frame while fading"),
               PinSpec("alpha", NUMBER, tooltip="Current real opacity: 1.0 = solid, 0.0 = invisible"),
               PinSpec("done",  EXEC,   tooltip="Fires once on completion")]
    def generate_code(self, ctx, node, visited):
        tgt   = self.object_input_expr(ctx, node, "target", "me")
        dur   = self.input_expr(ctx, node, "duration")     if ctx.find_input_link(node["id"], "duration")     else repr(self.prop_value(node, "duration",     1.0))
        f_op  = self.input_expr(ctx, node, "from_opacity") if ctx.find_input_link(node["id"], "from_opacity") else repr(self.prop_value(node, "from_opacity",  1.0))
        t_op  = self.input_expr(ctx, node, "to_opacity")   if ctx.find_input_link(node["id"], "to_opacity")   else repr(self.prop_value(node, "to_opacity",    0.0))
        curve = str(self.prop_value(node, "curve", "sine_inout"))
        loop  = repr(bool(self.prop_value(node, "loop", False)))

        tk = ctx.state_name(node["id"], "t")
        sk = ctx.state_name(node["id"], "started")
        dk = ctx.state_name(node["id"], "dur")
        fk = ctx.state_name(node["id"], "from")
        av = ctx.fresh_var("op_alpha")
        ctx.expr_cache[(node["id"], "alpha")] = av

        ctx.emit(f"if not {tgt}.get('_ns_state',{{}}).get('{sk}'):")
        ctx.push_indent()
        ctx.emit(f"{tgt}.setdefault('_ns_state',{{}})['{dk}'] = max(0.001, float({dur}))")
        ctx.emit(f"{tgt}['_ns_state']['{tk}'] = 0.0")
        ctx.emit(f"{tgt}['_ns_state']['{fk}'] = float({f_op})")
        ctx.emit(f"{tgt}['_ns_state']['{sk}'] = True")
        ctx.pop_indent()

        ctx.emit(f"{tgt}['_ns_state']['{tk}'] = min(1.0, {tgt}['_ns_state'].get('{tk}', 0) + dt / {tgt}['_ns_state'].get('{dk}', 1.0))")
        ctx.emit(f"_op_raw = {tgt}['_ns_state']['{tk}']")
        # Curve resolution order: wired curve_name pin > custom F8 curve
        # picked in the dropdown > built-in curve formula.
        if ctx.find_input_link(node["id"], "curve"):
            curve_expr = self.input_expr(ctx, node, "curve")
            ctx.emit(f"_op_ez  = ctx.curve_eval(str({curve_expr} or {curve!r}), _op_raw)")
        elif _is_custom_curve_name(curve):
            ctx.emit(f"_op_ez  = ctx.curve_eval({curve!r}, _op_raw)")
        else:
            ease = EaseNode._EASE_EXPRS.get(curve, "_t")
            ctx.emit(f"_op_ez  = (lambda _t: max(0.0, min(1.0, {ease})))(_op_raw)")
        ctx.emit(f"{av}    = max(0.0, min(1.0, {tgt}['_ns_state'].get('{fk}', {f_op}) + (float({t_op}) - {tgt}['_ns_state'].get('{fk}', {f_op})) * _op_ez))")
        # Drive REAL transparency: the draw path reads c['opacity'] for both
        # sprites and plain circles. Clear any wall-clock _opacity_fade record
        # first so a Set/Fade Opacity started earlier can't fight this node.
        ctx.emit(f"{tgt}.pop('_opacity_fade', None)")
        ctx.emit(f"{tgt}['opacity'] = {av}")
        ctx.generate_exec_branch(node["id"], "", visited)

        ctx.emit("if _op_raw >= 1.0:")
        ctx.push_indent()
        ctx.emit(f"if {loop}:")
        ctx.push_indent()
        ctx.emit(f"{tgt}['_ns_state']['{tk}'] = 0.0")
        ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent()
        ctx.emit(f"{tgt}['_ns_state']['{sk}'] = False")
        ctx.generate_exec_branch(node["id"], "done", visited)
        ctx.emit("pass")
        ctx.pop_indent()
        ctx.pop_indent()

@register_node("loop_repeat_while", "Loops", "Repeat While",
               "A safe While loop capped at 1000 iterations -- repeats until the condition is False.")
class RepeatWhileNode(NodeBase):
    properties = {"max_iterations": PropSpec("max_iterations", "number", 1000)}
    inputs = [PinSpec("", EXEC), PinSpec("condition", BOOLEAN, default=True)]
    outputs = [PinSpec("", EXEC, tooltip="Loop body"), PinSpec("index", NUMBER), PinSpec("completed", EXEC)]
    def generate_code(self, ctx, node, visited):
        cond = self.input_expr(ctx, node, "condition") if ctx.find_input_link(node["id"], "condition") else "True"
        max_iters = int(self.prop_value(node, "max_iterations", 1000))
        idx = ctx.fresh_var("idx")
        ctx.emit(f"{idx} = 0")
        ctx.emit(f"while {cond} and {idx} < {max_iters}:")
        ctx.push_indent()
        ctx.expr_cache[(node["id"], "index")] = idx
        old_depth = ctx.loop_depth
        ctx.loop_depth += 1
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.emit(f"{idx} += 1")
        ctx.loop_depth = old_depth
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "completed", visited)

@register_node("loop_trigger_n_times", "Loops", "Trigger N Times",
               "Fires its execution body exactly N times in a single frame.")
class TriggerNTimesNode(NodeBase):
    properties = {"count": PropSpec("count", "number", 3)}
    inputs = [PinSpec("", EXEC), PinSpec("count", NUMBER, default=3)]
    outputs = [PinSpec("", EXEC, tooltip="Loop body"), PinSpec("index", NUMBER), PinSpec("completed", EXEC)]
    def generate_code(self, ctx, node, visited):
        cnt = self.input_expr(ctx, node, "count") if ctx.find_input_link(node["id"], "count") else repr(self.prop_value(node, "count", 3))
        idx = ctx.fresh_var("idx")
        ctx.emit(f"for {idx} in range(int(max(0, {cnt}))):")
        ctx.push_indent()
        ctx.expr_cache[(node["id"], "index")] = idx
        old_depth = ctx.loop_depth
        ctx.loop_depth += 1
        ctx.generate_exec_branch(node["id"], "", visited)
        ctx.loop_depth = old_depth
        ctx.pop_indent()
        ctx.generate_exec_branch(node["id"], "completed", visited)

