@register_node("debug_all_characters_invulnerable", "Debugging", "Toggle All Characters Invulnerable",
               "Debug master damage switch for every current and future combat character. Toggle flips it each execution; Force On/Off gives deterministic control. While on, no damage source can reduce character HP.")
class DebugAllCharactersInvulnerableNode(NodeBase):
    properties={"mode":PropSpec("mode","dropdown","toggle",options=["toggle","on","off"],tooltip="Toggle each press, or force a known state")}
    inputs=[PinSpec("",EXEC)]
    outputs=[PinSpec("",EXEC),PinSpec("enabled",BOOLEAN)]
