_RIG_T={"number":NUMBER,"string":STRING,"bool":BOOLEAN,"position":VECTOR,"color":COLOR,"target":OBJECT,"animation":STRING,"sprite":STRING}
_RIG_EVENT_OUTPUTS={
 "rig_event_muzzle":[("anchor",STRING),("projectile",OBJECT)],
 "rig_event_attack":[("weapon",STRING),("motion",STRING)],
 "rig_event_projectile_hit":[("target",OBJECT),("projectile",OBJECT)],
 "rig_event_collision":[("target",OBJECT),("collider",OBJECT)],
 "rig_item_pickup_event":[("item",OBJECT)],
 "rig_projectile_spawn":[("projectile",OBJECT),("name",STRING)],
 "rig_projectile_lob_from_position":[("projectile",OBJECT),("name",STRING)],
 "rig_projectile_lob_at_target":[("projectile",OBJECT),("name",STRING)],
 "rig_tether_launch":[("projectile",OBJECT),("name",STRING)],
}
# Extra live-data output pins on ordinary EXEC action nodes (unlike
# _RIG_EVENT_OUTPUTS these keep their exec input). Each entry maps a pin name
# to a weapon_value operation evaluated with the node's `name` when read.
_RIG_LIVE_OUTPUTS={
 "rig_position_aim_target":[("direction",VECTOR,"rig_position_direction"),("angle",NUMBER,"rig_position_angle")],
 "rig_position_aim_nearest":[("direction",VECTOR,"rig_position_direction"),("angle",NUMBER,"rig_position_angle")],
 "rig_position_set_angle":[("direction",VECTOR,"rig_position_direction")],
 "rig_position_rotate":[("direction",VECTOR,"rig_position_direction")],
}
def _rig_fields(*names):
    presets={
      "name":("string","main"),"anchor":("string","main"),
      # Position origins/parents are character/object references, not labels.
      # A missing connection means Self (handled by the runtime fallback).
      "parent":("target",None),"parent_anchor":("string","main"),"source":("string","main"),"origin":("target",None),
      "projectile":("target",None),"center":("target",None),"tag":("string",""),
      "position":("position",(0.0,0.0)),"x":("number",0.0),"y":("number",0.0),"angle":("number",0.0),"scale":("number",1.0),"speed":("number",250.0),"duration":("number",0.25),"upward_force":("number",0.0),"lob_force":("number",220.0),"lob_weight":("number",500.0),"forward_force":("number",140.0),"lob_direction":("position",(1.0,0.0)),"direction":("position",(0.0,-1.0)),
      "distance":("number",35.0),"length":("number",40.0),"radius":("number",12.0),"angle_offset":("number",0.0),"smooth_time":("number",0.18),"progress":("number",1.0),"width":("number",40.0),"height":("number",24.0),
      "damage":("number",0.0),"force":("number",0.0),"gravity":("number",0.0),"weight":("number",0.0),"accuracy":("number",100.0),"spread":("number",15.0),"drag":("number",0.0),"lifetime":("number",3.0),"opacity":("number",255),"drop":("number",0.0),
      "crit_chance":("number",25.0),"crit_percent":("number",150.0),
      "multiplier":("number",1.0),"amount":("number",1),"capacity":("number",10),"enabled":("bool",True),"stack":("bool",False),"keep_upright":("bool",True),"visible":("bool",True),"show_gizmo":("bool",True),"play_visible":("bool",False),"gizmo_size":("number",10),"gizmo_thickness":("number",2),
      "layer":("string","front"),"kind":("string","weapon"),"sprite":("sprite",""),"animation":("animation",""),"animations":("string",""),"color":("color",[255,255,255]),
      "target":("target",None),"filter":("string","enemy"),"tags":("string",""),"afterimage":("bool",True),"pierce":("number",0),"bounces":("number",0),
      "homing":("number",0.0),"value":("number",0.0),"label":("string",""),
      "face_mode":("string","face_center"),"rotation_mode":("string","face_center"),"face_center":("bool",True),"tangent":("bool",False),"spin_with_orbit":("bool",True),"orbit_speed":("number",180.0),
      "double_sided":("bool",False),"follow_flip_x":("bool",False),"follow_flip_y":("bool",False),
      "include_transparent":("bool",False),"pixel_perfect":("bool",True),"threshold":("number",20.0),"padding":("number",0.0),"alpha_threshold":("number",20.0),
      # Constant draw-only art correction for diagonally-drawn textures.
      "sprite_rotation":("number",0.0),
      "hit_cooldown":("number",0.55),"cooldown":("number",0.55),"interval":("number",0.55),"once_per_touch":("bool",True),"single_hit":("bool",True),
      "touch_grace":("number",0.28),"reentry_delay":("number",0.28),
      "spawn_immunity":("number",0.35),
      "global_cooldown":("number",0.12),"restitution":("number",0.65),"floor_friction":("number",5.0),"wall_friction":("number",2.0),"rolling_resistance":("number",1.5),"angular_velocity":("number",0.0),"angular_drag":("number",1.0),"roll_factor":("number",0.35),"max_roll_speed":("number",360.0),"stop_speed":("number",5.0),"settle_on_floor":("bool",True),"align_to_velocity":("bool",True),"roll_enabled":("bool",False),"squash_on_bounce":("bool",True),"squash_amount":("number",0.35),"squash_duration":("number",0.25),
      "hitbox":("string",""),"hitbox_start":("number",0.0),"hitbox_duration":("number",0.0),
      "smooth_speed":("number",12.0),"aim_deadzone":("number",0.15),"discrete":("bool",False),
      "easing":("string","smoothstep"),"extend_ratio":("number",0.38),"hold_ratio":("number",0.14),
      # ── Tether / yoyo / boomerang fields ──────────────────────────────
      "max_distance":("number",260.0),"leash_mode":("string","elastic"),"elasticity":("number",6.0),
      "thickness":("number",2.0),"sag":("number",10.0),"wave":("number",0.0),"segments":("number",12),
      "catch_radius":("number",26.0),"acceleration":("number",0.0),"follow_strength":("number",14.0),
      "keep_offset":("bool",False),"auto_return":("bool",True),"return_on_taut":("bool",False),
      "destroy_on_return":("bool",True),"lock_duration":("number",2.0),"spin_speed":("number",720.0),
      "aim_target":("target",None),"wall_behavior":("string","pass_through"),
      "return_on_wall_hit":("bool",False),
      # ── Tether launch-gate fields ──────────────────────────────────────
      # `gate` chooses WHEN the tether may be (re)launched: off/returned/phase.
      # `require_phase` is the tether phase a `phase` gate must equal.
      # `max_charges` = how many launches before it locks until the gate
      #   releases again (0 = unlimited).  `launch_cooldown` = seconds between
      #   launches (separate name so it defaults to 0, unlike the ammo/collider
      #   `cooldown` which defaults to 0.55).  `reset_charges` refills the budget.
      "gate":("string","off"),"require_phase":("string","caught"),
      "max_charges":("number",0),"launch_cooldown":("number",0.0),
      "reset_charges":("bool",False),
      # ── Projectile FLIGHT PATH fields (curve / bezier / homing / orbit) ──
      "end":("position",(0.0,0.0)),"p0":("position",(0.0,0.0)),"p1":("position",(0.0,0.0)),
      "p2":("position",(0.0,0.0)),"p3":("position",(0.0,0.0)),
      "velocity":("position",(0.0,0.0)),
      "curvature":("number",0.0),"turn_rate":("number",200.0),"delay":("number",0.0),
      "strength":("number",1.0),"ramp_time":("number",0.4),"accel":("number",0.0),
      "hold_ratio":("number",0.0),"orbit_speed":("number",180.0),"dt":("number",0.016),
      "pingpong":("bool",False),"loop":("bool",False),"clockwise":("bool",True),
      "destroy_on_done":("bool",False),"paused":("bool",True),
      "tracking":("string","nearest"),"return_easing":("string","smoothstep"),
      "center":("target",None),
      # ── Boomerang / throw-and-return fields ────────────────────────────
      "out_duration":("number",0.9),"return_duration":("number",0.9),"return_speed":("number",420.0),
      "catch_radius":("number",26.0),"max_distance":("number",0.0),"destroy_on_return":("bool",True),
      "return_on_hit":("bool",False),"return_after":("number",0.0),
      "hold_time":("number",0.0),"hit_hold_time":("number",0.0),"hold_on_hit":("bool",False),
      # `track` is a boolean toggle for the Lock On node: OFF = aim at the
      # target once and never follow it (a thrown projectile that comes home).
      "track":("bool",True),
    }
    return [(n,)+presets[n] for n in names]

def _register_rig_node(key,category,title,desc,fields=(),value_type=None):
    # Every projectile modifier/getter accepts the exact live Projectile object
    # as well as the legacy Name fallback. This lets Spawn/Lob outputs and
    # projectile-contact event outputs wire straight into the next projectile
    # node without name collisions when several copies share one name.
    if ((key.startswith("rig_projectile_") or key.startswith("rig_tether_")) and key not in
            ("rig_projectile_spawn","rig_projectile_lob_from_position","rig_projectile_lob_at_target","rig_tether_launch")
            and not any(f[0]=="projectile" for f in fields)):
        fields=(("projectile","target",None),)+tuple(fields)
    props={};_event_outputs=_RIG_EVENT_OUTPUTS.get(key)
    inputs=[] if (value_type or (_event_outputs and key not in ("rig_projectile_spawn","rig_projectile_lob_from_position","rig_projectile_lob_at_target","rig_tether_launch"))) else [PinSpec("",EXEC)]
    for name,typ,default in fields:
        ptype=_RIG_T[typ];inputs.append(PinSpec(name,ptype,default=default))
        if typ=="animation":props[name]=PropSpec(name,"animation",default)
        elif typ=="sprite":props[name]=PropSpec(name,"sprite",default)
        elif typ=="color":props[name]=PropSpec(name,"color",default)
        elif typ=="bool":props[name]=PropSpec(name,"boolean",default)
        elif typ=="number":
            if name in ("upward_force","lob_force","lob_weight","forward_force"):props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=2400.0,tooltip="Immediate upward velocity added to the projectile")
            elif key in ("rig_projectile_directional_force","rig_projectile_force_angle") and name=="force":props[name]=PropSpec(name,"number",default,min_val=-2400.0,max_val=2400.0)
            elif key=="rig_projectile_force_xy" and name in ("x","y"):props[name]=PropSpec(name,"number",default,min_val=-2400.0,max_val=2400.0)
            elif key=="rig_projectile_force_angle" and name=="angle":props[name]=PropSpec(name,"number",default,min_val=-360.0,max_val=360.0)
            elif name=="sprite_rotation":props[name]=PropSpec(name,"number",default,min_val=-360.0,max_val=360.0,tooltip="Draw-only art correction in degrees. Texture painted diagonally? Enter its tilt (e.g. 45) and it renders straight; velocity, spin and hitboxes are untouched.")
            elif name=="restitution":props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=1.5)
            elif name=="rolling_resistance":props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=30.0,tooltip="How quickly rolling loses horizontal speed. Higher stops sooner; it does not directly set visual spin speed.")
            elif name in ("floor_friction","wall_friction","angular_drag"):props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=30.0)
            elif name=="angular_velocity":props[name]=PropSpec(name,"number",default,min_val=-2160.0,max_val=2160.0,tooltip="Air/free spin in degrees per second. Ground rolling takes control after the projectile settles.")
            elif name=="roll_factor":props[name]=PropSpec(name,"number",default,min_val=-2.0,max_val=2.0,tooltip="Visual rolling amount. 0 = no rolling, 0.35 = natural/slower default, 1 = physical wheel speed, negative reverses direction.")
            elif name=="max_roll_speed":props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=2160.0,tooltip="Hard visual roll-speed limit in degrees per second. 360 = one full turn per second; 0 disables rolling rotation.")
            elif name=="squash_amount":props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=1.0)
            elif name=="squash_duration":props[name]=PropSpec(name,"number",default,min_val=0.02,max_val=2.0)
            elif name=="stop_speed":props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=200.0)
            elif name=="max_charges":props[name]=PropSpec(name,"number",default,min_val=0,max_val=999,tooltip="How many launches are allowed before the gate locks until it releases again. 0 = unlimited (no charge budget).")
            elif name=="launch_cooldown":props[name]=PropSpec(name,"number",default,min_val=0.0,max_val=120.0,tooltip="Minimum seconds between launches (cooldown). 0 = no cooldown.")
            else:props[name]=PropSpec(name,"number",default)
        elif typ in ("target","position"):
            # Object/vector references are wired pins only. Their pin defaults
            # still work when unwired; do not expose a misleading text field.
            pass
        elif name in ("easing","return_easing"):props[name]=PropSpec(name,"dropdown",default,options=_EaseCurveOptions())
        elif name=="leash_mode":props[name]=PropSpec(name,"dropdown",default,options=["elastic","hard"],tooltip="elastic = spring pulls it back inside the limit (stretchy yoyo string). hard = rigid rope, clamps position exactly at max distance.")
        elif name=="wall_behavior":props[name]=PropSpec(name,"dropdown",default,options=["pass_through","bounce","lodge","destroy"],tooltip="How this projectile reacts to arena walls. Tethered projectiles default to pass_through so the leash isn't fighting a wall bounce; pick bounce/lodge/destroy to make walls matter.")
        elif name=="gate":props[name]=PropSpec(name,"dropdown",default,options=["off","returned","phase"],tooltip="When the tether may be (re)launched. off = always. returned = only after the previous one has come back / is no longer out (the 'wait for it to return' gate). phase = only when the tether reaches the chosen phase.")
        elif name=="require_phase":props[name]=PropSpec(name,"dropdown",default,options=["off","fly","return","lock","held","caught"],tooltip="The tether phase a 'phase' gate must equal before it may launch. caught/held/off mean it is home.")
        elif name=="reset_charges":props[name]=PropSpec(name,"boolean",default,tooltip="When this node runs, refill the charge budget back to Max Charges (and clear the cooldown) immediately.")
        else:props[name]=PropSpec(name,"string",default)
    _position_create_output=(key=="rig_position_create_at_position")
    _live_outputs=_RIG_LIVE_OUTPUTS.get(key) or []
    outputs=([PinSpec("value",_RIG_T[value_type])] if value_type else
             ([PinSpec("",EXEC),PinSpec("position_event",OBJECT),PinSpec("name",STRING),PinSpec("position",VECTOR)]
              if _position_create_output else
              [PinSpec("",EXEC)]+[PinSpec(n,t) for n,t in (_event_outputs or [])]
              +[PinSpec(n,t) for n,t,_op in _live_outputs]))
    def _kwargs(self,ctx,node):
        out=[]
        for fname,ftype,default in fields:
            expr=self.input_expr(ctx,node,fname) if ctx.find_input_link(node["id"],fname) else repr(self.prop_value(node,fname,default))
            out.append(f"{fname}={expr}")
        return ", ".join(out)
    if value_type:
        def generate_output_expr(self,ctx,node,pin_name):return f"ctx.weapon_value({key!r}, me, {_kwargs(self,ctx,node)})"
        attrs={"properties":props,"inputs":inputs,"outputs":outputs,"pure":True,"generate_output_expr":generate_output_expr}
    else:
        def generate_code(self,ctx,node,visited):
            args=_kwargs(self,ctx,node);ctx.emit(f"ctx.weapon_op({key!r}, me{', ' if args else ''}{args})");ctx.generate_exec_branch(node["id"],"",visited)
        def generate_output_expr(self,ctx,node,pin_name):
            # Live-data pins (Aim At Target direction/angle, ...): read the
            # anchor's CURRENT state via weapon_value at the moment the pin
            # is consumed downstream — always fresh, even mid-smooth-aim.
            for _ln,_lt,_lop in _live_outputs:
                if pin_name==_ln:
                    name_expr=self.input_expr(ctx,node,"name") if ctx.find_input_link(node["id"],"name") else repr(self.prop_value(node,"name","main"))
                    return f"ctx.weapon_value({_lop!r}, me, name={name_expr})"
            if _position_create_output:
                name_expr=self.input_expr(ctx,node,"name") if ctx.find_input_link(node["id"],"name") else repr(self.prop_value(node,"name","main"))
                if pin_name=="position_event":return f"ctx.weapon_value('rig_position_get', me, name={name_expr})"
                if pin_name=="name":return name_expr
                if pin_name=="position":return f"ctx.weapon_value('rig_position_world', me, name={name_expr})"
            if pin_name == "projectile":
                name_expr = self.input_expr(ctx,node,"name") if ctx.find_input_link(node["id"],"name") else repr(self.prop_value(node,"name","main"))
                if any(f[0]=="projectile" for f in fields) and ctx.find_input_link(node["id"],"projectile"):
                    exact_expr=self.input_expr(ctx,node,"projectile")
                    return f"({exact_expr} if isinstance({exact_expr}, dict) else ctx.weapon_value('rig_projectile_last', me, name={name_expr}))"
                return f"ctx.weapon_value('rig_projectile_last', me, name={name_expr})"
            if pin_name == "name":
                return self.input_expr(ctx,node,"name") if ctx.find_input_link(node["id"],"name") else repr(self.prop_value(node,"name","main"))
            return ctx.event_args.get(pin_name,"None")
        attrs={"properties":props,"inputs":inputs,"outputs":outputs,"generate_code":generate_code}
        if _event_outputs or key.startswith("rig_projectile_") or _position_create_output or _live_outputs:attrs["generate_output_expr"]=generate_output_expr
    cls=type("Rig_"+key.replace("rig_","").title().replace("_",""),(NodeBase,),attrs)
    register_node(key,category,title,desc)(cls)

_RIG_SPECS=[]
def _rs(key,cat,title,desc,fields=(),value=None):_RIG_SPECS.append((key,cat,title,desc,_rig_fields(*fields),value))
