for _spec in _RIG_SPECS:
    if _spec[0] not in NODE_DEFS:_register_rig_node(*_spec)
# ═══════════════════════════════════════════════════════════════════════════
# UNIVERSAL PIPELINE / SQL-STYLE QUERY NODES
# ═══════════════════════════════════════════════════════════════════════════
@register_node("flex_from","Universal","FROM","Start from any value: number, color, vector, object, collection, text, angle, opacity, etc.")
class FlexFromNode(NodeBase):
    inputs=[PinSpec("value",ANY)];outputs=[PinSpec("value",ANY)];pure=True
    def generate_output_expr(self,ctx,node,pin):return self.input_expr(ctx,node,"value")
@register_node("flex_to","Universal","TO","Declare any destination value for a reusable transition pipeline.")
class FlexToNode(FlexFromNode):pass
@register_node("flex_alter","Universal","ALTER","Blend FROM to TO with automatic number/vector/color/angle handling and selectable easing.")
class FlexAlterNode(NodeBase):
    properties={"easing":PropSpec("easing","dropdown","smoothstep",options=["linear","ease_in","ease_out","ease_in_out","smoothstep","smootherstep","bounce"]),"mode":PropSpec("mode","dropdown","auto",options=["auto","number","angle","color","vector","opacity"])}
    inputs=[PinSpec("from_value",ANY),PinSpec("to_value",ANY),PinSpec("t",NUMBER,default=1)];outputs=[PinSpec("result",ANY)];pure=True
