_FLEX_T={"number":NUMBER,"string":STRING,"bool":BOOLEAN,"any":ANY,"target":OBJECT,"position":VECTOR,"color":COLOR}
def _ff(*names):
    d={"source":("any",None),"a":("any",None),"b":("any",None),"target":("target",None),"position":("position",(0,0)),"tag":("string",""),"team":("string",""),"filter":("string","enemy"),"name":("string","main"),"value":("number",0),"count":("number",1),"radius":("number",100),"angle":("number",0),"arc":("number",90),"duration":("number",.3),"strength":("number",6),"frequency":("number",24),"axis":("string","both"),"color":("color",[255,80,80]),"opacity":("number",140),"flash":("bool",False),"enabled":("bool",True),"damage":("number",0),"motion":("string","rig_weapon_swing"),"distance":("number",35),"afterimage":("bool",True),"easing":("string","smoothstep"),"speed":("number",1),"mode":("string","enter"),"cooldown":("number",.35),"only_when_phasing":("bool",True),"respect_ready":("bool",False),"other":("target",None),"seconds":("number",2),"steps":("number",72),"bounces":("number",4),"gravity_multiplier":("number",1),"thickness":("number",2),"show_points":("bool",True),"trail_seconds":("number",2)}
    return [(n,)+d[n] for n in names]
def _reg_flex(key,cat,title,desc,fields=(),value=True,out_type="any"):
    props={};inputs=[] if value else [PinSpec("",EXEC)]
    for n,t,d in fields:
        inputs.append(PinSpec(n,_FLEX_T[t],default=d))
        if n=="easing":
            props[n]=PropSpec(n,"dropdown",d,options=_EaseCurveOptions())
        else:
            props[n]=PropSpec(n,"boolean" if t=="bool" else "color" if t=="color" else "number" if t=="number" else "string",d)
    outputs=[PinSpec("result",_FLEX_T[out_type])] if value else [PinSpec("",EXEC)]
    def args(self,ctx,node):return ", ".join(f"{n}="+(self.input_expr(ctx,node,n) if ctx.find_input_link(node["id"],n) else repr(self.prop_value(node,n,d))) for n,t,d in fields)
    if value:
        def generate_output_expr(self,ctx,node,pin):
            _call = f"ctx.flex_value({key!r},me{', ' if fields else ''}{args(self,ctx,node)})"
            # The composable/SQL-style Target In Range node is generated by
            # this factory rather than the regular Targets classes.  Give it
            # the same live F7 range visualizer, including its custom name.
            # Source Radius and WHERE Distance share that radius visualization.
            if key in ("flex_condition_in_range", "flex_source_radius", "flex_where_distance"):
                _radius = (self.input_expr(ctx,node,"radius") if ctx.find_input_link(node["id"],"radius")
                           else repr(self.prop_value(node,"radius",100)))
                _label = node.get("custom_name") or title
                return f"(ctx.debug_range(me,me['pos'],0,{_radius},{_label!r}) or {_call})"
            return _call
        attrs={"properties":props,"inputs":inputs,"outputs":outputs,"pure":True,"generate_output_expr":generate_output_expr}
    else:
        def generate_code(self,ctx,node,visited):ctx.emit(f"ctx.flex_op({key!r},me{', ' if fields else ''}{args(self,ctx,node)})");ctx.generate_exec_branch(node["id"],"",visited)
        attrs={"properties":props,"inputs":inputs,"outputs":outputs,"generate_code":generate_code}
    register_node(key,cat,title,desc)(type("Flex_"+key.title().replace('_',''),(NodeBase,),attrs))
_FLEX=[]
def _fx(k,c,t,d,f=(),v=True,o="any"):_FLEX.append((k,c,t,d,_ff(*f),v,o))
