    state=True
    def generate_code(self,ctx,node,visited):
        group=repr(self.prop_value(node,"group","Smart Group 1"));ctx.emit(f"_ns_group_flags[{group}] = {self.state!r}");ctx.generate_exec_branch(node["id"],"",visited)
