# ---------- Dummy Controller & Audio Debug Nodes ----------

@register_node("dummy_controller", "Debugging", "Dummy Controller / Event Hook",
               "Hook spawned custom clones, library characters, or swarms to a Dummy Controller to handle on_spawn, on_hit, and on_tick events directly in one visual script.")
class DummyControllerNode(NodeBase):
    properties = {
        "dummy_name": PropSpec("dummy_name", "string", "Dummy", tooltip="Identifier label for this dummy instance"),
        "auto_spin": PropSpec("auto_spin", "number", 0.0, tooltip="Continuous spin speed on spawn (degrees/sec)"),
    }
    inputs = [
        PinSpec("exec_in", EXEC, tooltip="Trigger dummy configuration"),
        PinSpec("spawned", OBJECT, default=None, tooltip="Connected spawned clone / character / swarm member"),
        PinSpec("audio_path", STRING, default="", tooltip="Optional sound effect to play on spawn or hit"),
    ]
    outputs = [
        PinSpec("exec_out", EXEC, tooltip="Continue execution"),
        PinSpec("dummy", OBJECT, tooltip="Output reference to the dummy/spawned character"),
        PinSpec("on_spawn", EXEC, tooltip="Triggered on dummy spawn / spin init"),
        PinSpec("on_hit", EXEC, tooltip="Triggered when dummy hits or takes damage"),
        PinSpec("on_tick", EXEC, tooltip="Triggered every frame for this dummy"),
        PinSpec("on_death", EXEC, tooltip="Triggered when dummy dies"),
        PinSpec("other", OBJECT, tooltip="Target or attacker involved in on_hit"),
        PinSpec("dealt", NUMBER, tooltip="Damage dealt by dummy"),
        PinSpec("taken", NUMBER, tooltip="Damage taken by dummy"),
    ]

    def generate_code(self, ctx, node, visited):
        target_expr = self.object_input_expr(ctx, node, "spawned", "me")
        dummy_var = ctx.fresh_var("dummy_obj")
        ctx.emit(f"{dummy_var} = {target_expr}")
        ctx.expr_cache[(node["id"], "dummy")] = dummy_var
        _ns_emit_target_event_bindings(ctx, node["id"], "dummy", dummy_var, visited)

        auto_spin = float(self.prop_value(node, "auto_spin", 0.0))
        if auto_spin != 0.0:
            ctx.emit(f"if isinstance({dummy_var}, dict):")
            ctx.emit(f"    {dummy_var}['rotation_speed'] = {auto_spin}")

        if ctx.find_input_link(node["id"], "audio_path"):
            apath = self.input_expr(ctx, node, "audio_path")
            ctx.emit(f"if {dummy_var} and {apath}:")
            ctx.emit(f"    ctx.play_audio_from_path({apath}, 1.0, 1.0, False, 1.0, 800.0, {dummy_var}.get('pos'))")

        other_var = ctx.fresh_var("d_other")
        dealt_var = ctx.fresh_var("d_dealt")
        taken_var = ctx.fresh_var("d_taken")

        has_spawn = bool(ctx.output_links(node["id"], "on_spawn"))
        has_hit = bool(ctx.output_links(node["id"], "on_hit"))
        has_tick = bool(ctx.output_links(node["id"], "on_tick"))
        has_death = bool(ctx.output_links(node["id"], "on_death"))

        if has_spawn or has_hit or has_tick or has_death:
            ctx.emit(f"if isinstance({dummy_var}, dict):")
            ctx.push_indent()
            ctx.emit(f"if {dummy_var}.get('script_ns') is None:")
            ctx.push_indent()
            ctx.emit(f"{dummy_var}['script_ns'] = {{}}")
            ctx.pop_indent()
            ctx.emit(f"_d_ns = {dummy_var}['script_ns']")

            if has_spawn:
                ctx.emit_nested_def_with_global(
                    "def _d_on_spawn(_ctx, _me):",
                    lambda: ctx.generate_exec_branch(node["id"], "on_spawn", visited),
                )
                ctx.emit("_d_ns['on_spawn'] = _d_on_spawn")
                ctx.emit(f"_d_on_spawn(ctx, {dummy_var})")

            if has_hit:
                ctx.expr_cache[(node["id"], "other")] = other_var
                ctx.expr_cache[(node["id"], "dealt")] = dealt_var
                ctx.expr_cache[(node["id"], "taken")] = taken_var
                ctx.emit_nested_def_with_global(
                    f"def _d_on_hit(_ctx, _me, {other_var}=None, {dealt_var}=0.0, {taken_var}=0.0, _crit=False):",
                    lambda: ctx.generate_exec_branch(node["id"], "on_hit", visited),
                )
                ctx.emit("_d_ns['on_hit'] = _d_on_hit")

            if has_tick:
                ctx.emit_nested_def_with_global(
                    "def _d_on_tick(_ctx, _me, _dt=0.016):",
                    lambda: ctx.generate_exec_branch(node["id"], "on_tick", visited),
                )
                ctx.emit("_d_ns['on_tick'] = _d_on_tick")

            if has_death:
                ctx.emit_nested_def_with_global(
                    "def _d_on_death(_ctx, _me, _killer=None):",
                    lambda: ctx.generate_exec_branch(node["id"], "on_death", visited),
                )
                ctx.emit("_d_ns['on_death'] = _d_on_death")

            ctx.pop_indent()

        ctx.generate_exec_branch(node["id"], "exec_out", visited)

# =========================================================================
# 50+ SCENE PROP & SCENE DIRECTOR NODES
# =========================================================================


# ===========================================================================
# ITEM / INVENTORY BLUEPRINT SUITE (26 action/data nodes + 4 item events)
# ===========================================================================
def _item_cg_value(owner, ctx, node, pin, default):
    return owner.input_expr(ctx, node, pin) if ctx.find_input_link(node["id"], pin) else repr(owner.prop_value(node, pin, default))


def _item_cg_object(owner, ctx, node, pin="item", fallback="me"):
    return owner.object_input_expr(ctx, node, pin, fallback)


@register_node("item_make", "Items | Setup", "Make Character / Prop An Item",
               "Turns any character or visible prop into a world item with identity, stacks, touch sensing, optional auto-pickup, and selectable physics.")
class ItemMakeNode(NodeBase):
    properties = {
        "item_id": PropSpec("item_id", "string", "item"), "display_name": PropSpec("display_name", "string", ""),
        "category": PropSpec("category", "string", "general"), "max_stack": PropSpec("max_stack", "number", 99, min_val=1, max_val=999999),
        "physics_mode": PropSpec("physics_mode", "dropdown", "static", options=["static", "dynamic", "kinematic"]),
        "auto_pickup": PropSpec("auto_pickup", "boolean", True), "consume_on_pickup": PropSpec("consume_on_pickup", "boolean", True),
        "pickup_radius": PropSpec("pickup_radius", "number", 8.0, min_val=0, max_val=1000),
    }
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("item_id", STRING, default="item")]
    outputs = [PinSpec("", EXEC), PinSpec("item", OBJECT)]
    def generate_code(self, ctx, node, visited):
        target=_item_cg_object(self,ctx,node,"target","me");iid=_item_cg_value(self,ctx,node,"item_id","item");out=ctx.fresh_var("item")
        ctx.emit(f"{out}=ctx.item_op('make',{target},{iid},{self.prop_value(node,'display_name','')!r},{self.prop_value(node,'category','general')!r},{self.prop_value(node,'max_stack',99)!r},{self.prop_value(node,'physics_mode','static')!r},{self.prop_value(node,'auto_pickup',True)!r},{self.prop_value(node,'consume_on_pickup',True)!r},{self.prop_value(node,'pickup_radius',8.0)!r})")
        ctx.expr_cache[(node["id"],"item")]=out;ctx.generate_exec_branch(node["id"],"",visited)


@register_node("item_set_enabled", "Items | Setup", "Set Item Enabled",
               "Enables/respawns an item or hides/disables it. Optional delay automatically respawns a disabled item.")
class ItemSetEnabledNode(NodeBase):
    properties={"enabled":PropSpec("enabled","boolean",True),"respawn_delay":PropSpec("respawn_delay","number",0.0,min_val=0,max_val=3600)}
    inputs=[PinSpec("",EXEC),PinSpec("item",OBJECT,default=None),PinSpec("enabled",BOOLEAN,default=True),PinSpec("respawn_delay",NUMBER,default=0.0)]
    outputs=[PinSpec("",EXEC)]
    def generate_code(self,ctx,node,visited):
        item=_item_cg_object(self,ctx,node);en=_item_cg_value(self,ctx,node,"enabled",True);delay=_item_cg_value(self,ctx,node,"respawn_delay",0.0)
        ctx.emit(f"ctx.item_op('enabled',{item},{en},{delay})");ctx.generate_exec_branch(node["id"],"",visited)


@register_node("item_set_identity", "Items | Setup", "Set Item Identity",
               "Changes item ID, display name, category, and maximum stack size at runtime.")
class ItemSetIdentityNode(NodeBase):
    properties={"item_id":PropSpec("item_id","string","item"),"display_name":PropSpec("display_name","string",""),"category":PropSpec("category","string","general"),"max_stack":PropSpec("max_stack","number",99,min_val=1,max_val=999999)}
    inputs=[PinSpec("",EXEC),PinSpec("item",OBJECT,default=None),PinSpec("item_id",STRING,default="item")]
    outputs=[PinSpec("",EXEC)]
