    def generate_code(self,ctx,node,visited):
        src=_item_cg_object(self,ctx,node,"source","me");dst=_item_cg_object(self,ctx,node,"target","None");iid=_item_cg_value(self,ctx,node,"item_id","item");amt=_item_cg_value(self,ctx,node,"amount",1);out=ctx.fresh_var("moved")
        ctx.emit(f"{out}=ctx.item_op('transfer',{src},{dst},{iid},{amt})");ctx.expr_cache[(node["id"],"amount")]=out;ctx.emit(f"if {out}>0:");ctx.push_indent();ctx.generate_exec_branch(node["id"],"transferred",visited);ctx.pop_indent();ctx.emit("else:");ctx.push_indent();ctx.generate_exec_branch(node["id"],"failed",visited);ctx.pop_indent()


