@register_node("item_respawn_reset", "Items | Physics", "Respawn / Reset Item", "Makes an item available again at its spawn point or a connected position, optionally clearing velocity.")
class ItemRespawnResetNode(NodeBase):
    properties={"use_spawn":PropSpec("use_spawn","boolean",True),"clear_velocity":PropSpec("clear_velocity","boolean",True)};inputs=[PinSpec("",EXEC),PinSpec("item",OBJECT,default=None),PinSpec("position",VECTOR,default=None)];outputs=[PinSpec("",EXEC),PinSpec("item_out",OBJECT)]
    def generate_code(self,ctx,node,visited):
        item=_item_cg_object(self,ctx,node);pos=self.input_expr(ctx,node,"position") if ctx.find_input_link(node["id"],"position") else ("None" if self.prop_value(node,"use_spawn",True) else f"{item}.get('pos')");out=ctx.fresh_var("respawned")
        ctx.emit(f"{out}=ctx.item_op('respawn',{item},{pos},{self.prop_value(node,'clear_velocity',True)!r})");ctx.expr_cache[(node["id"],"item_out")]=out;ctx.generate_exec_branch(node["id"],"",visited)


@register_node("scene_spawn_floating_crit_text", "Scene Director", "Scene Floating Crit Text",
               "Spawns custom animated floating text (e.g., 'CRIT!', 'HEADSHOT!') over a target character's head.")
class SceneSpawnFloatingCritTextNode(NodeBase):
    properties = {
        "text": PropSpec("text", "string", "CRIT!"),
        "scale": PropSpec("scale", "number", 1.5, min_val=0.5, max_val=4.0),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("text", STRING, default="CRIT!"),
        PinSpec("color", COLOR, default=[255, 215, 0]),
    ]
    outputs = [PinSpec("", EXEC)]

    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        txt = self.input_expr(ctx, node, "text") if ctx.find_input_link(node["id"], "text") else repr(self.prop_value(node, "text", "CRIT!"))
        col = self.input_expr(ctx, node, "color") if ctx.find_input_link(node["id"], "color") else repr(self.prop_value(node, "color", [255, 215, 0]))
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.emit(f"    ctx.popup({t}.get('pos', [0,0]), str({txt}), tuple({col})[:3], crit=True, target={t})")
        ctx.generate_exec_branch(node["id"], "", visited)

