@register_node("scene_tint_all_characters", "Scene Director", "Scene Tint All Characters",
               "Flashes or colors every character in the scene simultaneously.")
class SceneTintAllCharactersNode(NodeBase):
    properties = {"duration": PropSpec("duration", "number", 0.5)}
