@register_node("scene_play_spatial_sound", "Scene Audio Director", "Scene Spatial Audio At Target",
               "Plays a sound effect positioned at a specific target character's position.")
class ScenePlaySpatialSoundNode(NodeBase):
    properties = {
        "audio_file": PropSpec("audio_file", "dropdown", "", options=list_imported_audio() if "list_imported_audio" in globals() else []),
        "volume": PropSpec("volume", "number", 1.0),
        "pitch": PropSpec("pitch", "number", 1.0),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("audio_file", STRING, default=""),
        PinSpec("volume", NUMBER, default=1.0),
        PinSpec("pitch", NUMBER, default=1.0),
    ]
    outputs = [PinSpec("", EXEC), PinSpec("channel", OBJECT)]

    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        path = self.input_expr(ctx, node, "audio_file") if ctx.find_input_link(node["id"], "audio_file") else repr(self.prop_value(node, "audio_file", ""))
        vol = self.input_expr(ctx, node, "volume") if ctx.find_input_link(node["id"], "volume") else repr(self.prop_value(node, "volume", 1.0))
        pit = self.input_expr(ctx, node, "pitch") if ctx.find_input_link(node["id"], "pitch") else repr(self.prop_value(node, "pitch", 1.0))
        cvar = ctx.fresh_var("sp_chan")
        ctx.emit(f"if isinstance({t}, dict):")
        ctx.emit(f"    {cvar} = ctx.play_audio_from_path({path}, float({vol}), float({pit}), False, 1.0, 800.0, {t}.get('pos'))")
        ctx.expr_cache[(node["id"], "channel")] = cvar
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("scene_play_global_sound", "Scene Audio Director", "Scene Global Director Audio",
               "Plays non-spatial master audio for background music or global announcements.")
class ScenePlayGlobalSoundNode(NodeBase):
    properties = {
        # Plain text field: paste an imported relative path or an absolute
        # filesystem path directly, while the pin can still receive strings.
        "audio_file": PropSpec("audio_file", "string", ""),
        "volume": PropSpec("volume", "number", 1.0),
        "pitch": PropSpec("pitch", "number", 1.0),
        "loop": PropSpec("loop", "boolean", False),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("audio_file", STRING, default=""),
        PinSpec("volume", NUMBER, default=1.0),
        PinSpec("pitch", NUMBER, default=1.0),
    ]
    outputs = [PinSpec("", EXEC), PinSpec("channel", OBJECT)]

    def generate_code(self, ctx, node, visited):
        path = self.input_expr(ctx, node, "audio_file") if ctx.find_input_link(node["id"], "audio_file") else repr(self.prop_value(node, "audio_file", ""))
        vol = self.input_expr(ctx, node, "volume") if ctx.find_input_link(node["id"], "volume") else repr(self.prop_value(node, "volume", 1.0))
        pit = self.input_expr(ctx, node, "pitch") if ctx.find_input_link(node["id"], "pitch") else repr(self.prop_value(node, "pitch", 1.0))
        loop = self.prop_value(node, "loop", False)
        cvar = ctx.fresh_var("gb_chan")
        ctx.emit(f"{cvar} = ctx.play_audio_from_path({path}, float({vol}), float({pit}), {bool(loop)!r}, 1.0, 800.0, None)")
        ctx.expr_cache[(node["id"], "channel")] = cvar
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("scene_play_random_audio_bag", "Scene Audio Director", "Scene Audio Shuffle Bag",
               "Picks and plays a random audio clip from imported folder.")
class ScenePlayRandomAudioBagNode(NodeBase):
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        ctx.emit(f"_audio_list = ctx.list_scene_audio_files()")
        ctx.emit(f"if _audio_list:")
        ctx.emit(f"    _rnd_clip = random.choice(_audio_list)")
        ctx.emit(f"    _pos = {t}.get('pos') if isinstance({t}, dict) else None")
        ctx.emit(f"    ctx.play_audio_from_path(_rnd_clip, 1.0, 1.0, False, 1.0, 800.0, _pos)")
        ctx.generate_exec_branch(node["id"], "", visited)

