@register_node("scene_knockback_target", "Scene Actions", "Scene Knockback Impulse",
               "Launches a target character along a vector impulse.")
class SceneKnockbackTargetNode(NodeBase):
    properties = {"force": PropSpec("force", "number", 400.0), "duration": PropSpec("duration", "number", 0.25, min_val=0.0), "stack": PropSpec("stack", "bool", False)}
    inputs = [PinSpec("", EXEC), PinSpec("target", OBJECT, default=None), PinSpec("direction", VECTOR, default=None), PinSpec("force", NUMBER, default=400.0), PinSpec("duration", NUMBER, default=0.25), PinSpec("stack", BOOLEAN, default=False)]
    outputs = [PinSpec("", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        dir_v = self.input_expr(ctx, node, "direction") if ctx.find_input_link(node["id"], "direction") else "[1,0]"
        f = self.input_expr(ctx, node, "force") if ctx.find_input_link(node["id"], "force") else repr(self.prop_value(node, "force", 400.0))
        dur = self.input_expr(ctx, node, "duration") if ctx.find_input_link(node["id"], "duration") else repr(self.prop_value(node, "duration", 0.25))
        stack = self.input_expr(ctx, node, "stack") if ctx.find_input_link(node["id"], "stack") else repr(bool(self.prop_value(node, "stack", False)))
        ctx.emit(f"if ctx.is_combat_character({t}): ctx.knockback({t}, {dir_v}, float({f}), float({dur}), bool({stack}))")
        ctx.generate_exec_branch(node["id"], "", visited)

@register_node("scene_is_target_alive", "Scene Conditions", "Scene Is Character Alive?",
               "Branch execution based on whether a target character is currently living.")
class SceneIsTargetAliveNode(NodeBase):
    inputs = [PinSpec("exec_in", EXEC), PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("alive", EXEC), PinSpec("dead", EXEC)]
    def generate_code(self, ctx, node, visited):
        t = self.object_input_expr(ctx, node, "target", "me")
        ctx.emit(f"if ctx.is_combat_character({t}) and not ({t}).get('_despawned'):")
        ctx.push_indent(); ctx.generate_exec_branch(node["id"], "alive", visited); ctx.pop_indent()
        ctx.emit("else:")
        ctx.push_indent(); ctx.generate_exec_branch(node["id"], "dead", visited); ctx.pop_indent()

