@register_node("scene_get_target_hp", "Scene Data", "Scene Get Character HP",
               "Reads target character's current and maximum HP values.")
class SceneGetTargetHPNode(NodeBase):
    inputs = [PinSpec("target", OBJECT, default=None)]
    outputs = [PinSpec("hp", NUMBER), PinSpec("max_hp", NUMBER), PinSpec("hp_percent", NUMBER)]
    def generate_output_expr(self, ctx, node, output_name):
        t = self.object_input_expr(ctx, node, "target", "me")
        if output_name == "hp": return f"float(({t}).get('hp', 0)) if isinstance({t}, dict) else 0.0"
