@register_node("debug_audio_clamp", "Debugging", "Audio Clamp",
               "Clamp onto any audio node or standalone flow to audition audio clips directly in-editor with live audition trigger, volume, pitch, and loop controls.")
class DebugAudioClampNode(NodeBase):
    properties = {
        "clamped_to": PropSpec("clamped_to", "string", ""),
        "audio_file": PropSpec("audio_file", "dropdown", "", options=list_imported_audio() if "list_imported_audio" in globals() else [], tooltip="Audio file path to audition"),
        "volume": PropSpec("volume", "number", 1.0, min_val=0.0, max_val=2.0),
        "pitch": PropSpec("pitch", "number", 1.0, min_val=0.25, max_val=4.0),
        "loop": PropSpec("loop", "boolean", False),
    }
    inputs = [
        PinSpec("exec_in", EXEC),
        PinSpec("path", STRING, default=""),
        PinSpec("volume", NUMBER, default=1.0),
        PinSpec("pitch", NUMBER, default=1.0),
    ]
    outputs = [
        PinSpec("exec_out", EXEC),
        PinSpec("channel", OBJECT),
        PinSpec("actual_pitch", NUMBER),
        PinSpec("actual_volume", NUMBER),
    ]

    def generate_code(self, ctx, node, visited):
        host_id = self.prop_value(node, "clamped_to", "")
        host_node = ctx.nodes.get(host_id) if host_id else None
        if host_node is None and str(host_id).isdigit():
            host_node = ctx.nodes.get(int(host_id))

        # Check path input link or local audio_file prop or clamped host node
        if ctx.find_input_link(node["id"], "path"):
            p_expr = self.input_expr(ctx, node, "path")
        elif self.prop_value(node, "audio_file", ""):
            p_expr = repr(self.prop_value(node, "audio_file", ""))
        elif host_node and ctx.find_input_link(host_node["id"], "path"):
            p_expr = self.input_expr(ctx, host_node, "path")
        elif host_node and ctx.find_input_link(host_node["id"], "audio_file"):
            p_expr = self.input_expr(ctx, host_node, "audio_file")
        elif host_node and host_node.get("props", {}).get("audio_file"):
            p_expr = repr(host_node.get("props", {}).get("audio_file"))
        elif host_node and host_node.get("props", {}).get("path"):
            p_expr = repr(host_node.get("props", {}).get("path"))
        elif host_node and host_node.get("props", {}).get("selected_path"):
            p_expr = repr(host_node.get("props", {}).get("selected_path"))
        elif host_node and host_node.get("props", {}).get("cue"):
            p_expr = repr(host_node.get("props", {}).get("cue"))
        else:
            p_expr = '""'

        if ctx.find_input_link(node["id"], "volume"):
            v_expr = self.input_expr(ctx, node, "volume")
        elif host_node and "volume" in host_node.get("props", {}):
            v_expr = repr(host_node.get("props", {}).get("volume", 1.0))
        else:
            v_expr = repr(self.prop_value(node, "volume", 1.0))

        if ctx.find_input_link(node["id"], "pitch"):
            pit_expr = self.input_expr(ctx, node, "pitch")
        elif host_node and "pitch" in host_node.get("props", {}):
            pit_expr = repr(host_node.get("props", {}).get("pitch", 1.0))
        else:
            pit_expr = repr(self.prop_value(node, "pitch", 1.0))

        loop_val = self.prop_value(node, "loop", False)

        chan_var = ctx.fresh_var("ac_chan")
        ctx.emit(f"if {p_expr}:")
        ctx.push_indent()
        ctx.emit(f"{chan_var} = ctx.play_audio_from_path({p_expr}, {v_expr}, {pit_expr}, {loop_val})")
        ctx.emit(f"_ns_log_audio_event({p_expr}, {v_expr}, {pit_expr}, {chan_var}, node_id={node['id']})")
        ctx.pop_indent()
        ctx.expr_cache[(node["id"], "channel")] = chan_var
        ctx.expr_cache[(node["id"], "actual_pitch")] = pit_expr
        ctx.expr_cache[(node["id"], "actual_volume")] = v_expr
        ctx.generate_exec_branch(node["id"], "exec_out", visited)

