@register_node("debug_sight_path", "Debugging", "Sight Path",
               "Draws a debug line from a character in a given direction, showing what a "
               "directional check (Target Below/Above/Left/Right, etc) is actually looking at. "
               "Thickness represents the width of the detection corridor. Auto-clipped to the "
               "arena box. Toggle visible/vcam_only to control where it shows up.")
class DebugSightPathNode(NodeBase):
    properties = {
        "length":    PropSpec("length", "number", 300, min_val=1, max_val=4000),
        "thickness": PropSpec("thickness", "number", 40, min_val=1, max_val=400),
        "color":     PropSpec("color", "color", [90, 220, 255]),
        "visible":   PropSpec("visible", "boolean", True),
        "vcam_only": PropSpec("vcam_only", "boolean", False),
    }
    inputs = [
        PinSpec("", EXEC),
        PinSpec("target", OBJECT, default=None),
        PinSpec("direction", VECTOR, default=(0, 1)),   # (0,1) = down/"below" in this engine's y-axis
        PinSpec("length", NUMBER, default=300),
        PinSpec("thickness", NUMBER, default=40),
    ]
    outputs = [PinSpec("", EXEC), PinSpec("node", OBJECT)]

    def generate_code(self, ctx, node, visited):
        t   = self.object_input_expr(ctx, node, "target", "me")
        dv  = self.input_expr(ctx, node, "direction") if ctx.find_input_link(node["id"], "direction") else "(0, 1)"
        ln  = self.input_expr(ctx, node, "length") if ctx.find_input_link(node["id"], "length") \
              else repr(self.prop_value(node, "length", 300))
        thk = self.input_expr(ctx, node, "thickness") if ctx.find_input_link(node["id"], "thickness") \
              else repr(self.prop_value(node, "thickness", 40))
        col   = repr(list(self.prop_value(node, "color", [90, 220, 255])))
        vis   = repr(bool(self.prop_value(node, "visible", True)))
        vcamo = repr(bool(self.prop_value(node, "vcam_only", False)))
        tag = repr(f"_sight_path_{node['id']}")
        var = ctx.fresh_var("sight_en")
        ctx.expr_cache[(node["id"], "node")] = var

        # direction + endpoint, clipped to the arena box so it never draws outside it
        ctx.emit(f"_sp_dir = pygame.Vector2({dv})")
        ctx.emit(f"if _sp_dir.length_squared() > 0: _sp_dir = _sp_dir.normalize()")
        ctx.emit(f"_sp_start = {t}.get('pos', pygame.Vector2(0,0))")
        ctx.emit(f"_sp_end = _sp_start + _sp_dir * float({ln})")
        ctx.emit(f"_sp_box = ctx.get_box_rect_world()")
        ctx.emit(f"_sp_clip = _sp_box.clipline(_sp_start.x, _sp_start.y, _sp_end.x, _sp_end.y)")
        ctx.emit(f"_sp_a, _sp_b = (pygame.Vector2(_sp_clip[0]), pygame.Vector2(_sp_clip[1])) if _sp_clip else (_sp_start, _sp_start)")

        # find-or-create the underlying line node, tagged uniquely to this node id
        # (same find-or-create-by-tag pattern the HP bars already use, so no new
        # persistent-state plumbing is needed anywhere else in the file)
        ctx.emit(f"{var} = ctx.en_find_tag_first({tag})")
        ctx.emit(f"if isinstance({var}, list): {var} = next((x for x in {var} if isinstance(x, dict)), None)")
        ctx.emit(f"if {var} is None:")
        ctx.push_indent()
        ctx.emit(f"{var} = ctx.create_ext_node('line', _sp_a.x, _sp_a.y)")
        ctx.emit(f"ctx.add_tag({var}, {tag})")
        ctx.pop_indent()
        ctx.emit(f"{var}['wx'], {var}['wy'] = _sp_a.x, _sp_a.y")
        ctx.emit(f"{var}['wx2'], {var}['wy2'] = _sp_b.x, _sp_b.y")
        ctx.emit(f"{var}['thickness'] = max(1, int({thk}))")
        ctx.emit(f"{var}['color'] = {col}")
        ctx.emit(f"{var}['visible'] = {vis}")
        ctx.emit(f"{var}['vcam_only'] = {vcamo}")
        ctx.emit(f"{var}['draw_layer'] = 'behind'")
        ctx.emit(f"{var}['layer'] = -5")
        ctx.generate_exec_branch(node["id"], "", visited)

