# ═══════════════════════════════════════════════════════════════════════════
# CANVAS STEP-BY-STEP DEBUG SIMULATION ENGINE
# ═══════════════════════════════════════════════════════════════════════════

def make_debug_beep(frequency=440.0, duration=0.1):
    if not AUDIO_AVAILABLE:
        return None
    try:
        import numpy as np
        import pygame.sndarray
        sample_rate = 22050
        n_samples = int(sample_rate * duration)
        t = np.linspace(0, duration, n_samples, False)
        val = np.sin(2 * np.pi * frequency * t) * 32767
        data = val.astype(np.int16)
        if len(data.shape) == 1:
            data = np.column_stack((data, data))
        sound = pygame.sndarray.make_sound(data)
        return sound
    except Exception as e:
        print("Failed to make debug beep:", e)
        return None

_NS_DEBUG_TRACE = []
_NS_DEBUG_EVENTS = []
_NS_DEBUG_WATCHES = {}
_NS_DEBUG_STATS = {
    "steps": 0, "execs": 0, "math": 0, "branches": 0, "values": 0,
    "colors": 0, "errors": 0, "gathers": 0, "events": 0, "damage": 0,
}
_NS_DEBUG_MAX_EVENTS = 4000
_NS_DEBUG_FILTERS_DEFAULT = {
    "exec": True, "value": True, "math": True, "branch": True, "color": True,
    "gather": True, "event": True, "damage": True, "error": True, "info": True, "system": True, "tip": True,
}

def _ns_debug_button_host_id(button_node):
    """Find the node this button controls via a white link or body attachment."""
    bid = button_node.get("id")
    for link in modal.get("ns_links", []):
        if link.get("from") == bid:
            return link.get("to")
    for node in modal.get("ns_nodes", {}).values():
        if bid in (node.get("props", {}).get("_debug_buttons", []) or []):
            return node.get("id")
    return None

def _ns_debug_window_expanders():
    """Return only window expanders that are actually clipped to a node."""
    nodes = modal.get("ns_nodes", {})
    out = []
    for node in nodes.values():
        if node.get("type") == "debug_button" and node.get("props",{}).get("show_in_window",True):
            host_id=_ns_debug_button_host_id(node);target=nodes.get(host_id)
            if target is not None:out.append((node,target))
            continue
        if node.get("type") != "debug_window_expander":
            continue
        target_id = node.get("props", {}).get("clamped_to", "")
        if target_id in (None, ""):
            continue
        target = nodes.get(target_id)
        if target is None:
            try:
                target = nodes.get(int(target_id))
            except (TypeError, ValueError):
                target = None
        if target is not None:
            out.append((node, target))
    return out

def _ns_debug_window_controls():
    """Aggregate all Debug Buttons exposed by every window expander.

    Multiple window expanders intentionally feed one shared control window.
    Buttons are deduplicated so the same action is never shown twice.
    """
    nodes = modal.get("ns_nodes", {})
    controls = []
    seen = set()
    for expander, host in _ns_debug_window_expanders():
        if _ns_node_muted(expander) or _ns_node_muted(host):
            continue
        candidates = []
        if host.get("type") == "debug_button":
            candidates.append(host)
        for button_id in host.get("props", {}).get("_debug_buttons", []) or []:
            button = nodes.get(button_id)
            if button is None:
                try:
                    button = nodes.get(int(button_id))
                except (TypeError, ValueError):
                    button = None
            if button is not None:
                candidates.append(button)
        # Also support a normal graph-linked Debug Button attached to this
        # host, not just the body-drop attachment list.
        for button in nodes.values():
            if button.get("type") == "debug_button" and _ns_debug_button_host_id(button) == host.get("id"):
                candidates.append(button)
        for button in candidates:
            if (button.get("type") != "debug_button" or button.get("id") in seen
                    or _ns_node_muted(button)):
                continue
            seen.add(button.get("id"))
            controls.append((button, _ns_debug_button_host_id(button) or host.get("id"), expander))
    return controls

def _ns_fire_debug_button(button_node, host_id=None):
    """Execute the selected Debug Button action.

    Global debug actions (camera follow, path dimming, reset) work even when
    the button is not attached to a host. Host actions require a target and
    use the connected node as the debug-simulation entry point.
    """
    host = modal.get("ns_nodes", {}).get(host_id) if host_id is not None else None
    if _ns_node_muted(button_node):
        push_toast("This Debug Button is muted.", "warning", 1.8)
        return
    if host is not None and _ns_node_muted(host):
        push_toast("Muted host blocked the Debug Button trigger.", "warning", 2.2)
        _ns_log_debug("Debug Button blocked: host node is muted", kind="system", node_id=host.get("id"))
        return
    action = button_node.get("props", {}).get("action", "Run")
    label = button_node.get("props", {}).get("label", action) or action
    needs_host = action in ("Run", "Step", "Pause / Resume", "Preview", "Toggle", "Force True", "Force False",
                           "Toggle Host Setting", "Set Host Setting True", "Set Host Setting False", "Unclip Host")
    if needs_host and not host:
        push_toast("Attach this Debug Button to a node before using that action.", "warning", 2.5)
        return
    if action == "Run":
        _ns_sim_start(host_id)
    elif action == "Step":
        if not modal.get("ns_sim_active"):
            _ns_sim_start(host_id)
            modal["ns_sim_paused"] = True
        _ns_sim_step()
        modal["ns_sim_paused"] = True
    elif action == "Pause / Resume":
        if not modal.get("ns_sim_active"):
            _ns_sim_start(host_id)
        else:
            modal["ns_sim_paused"] = not modal.get("ns_sim_paused", False)
    elif action == "Reset Debug":
        modal["ns_sim_active"] = False
        modal["ns_sim_steps"] = []
        modal["ns_sim_variables"] = {}
        modal["ns_sim_global_variables"] = {}
        _NS_WIRE_FLOW.clear(); _NS_EXEC_FLASH.clear(); _NS_EXEC_FLASH_COLOR.clear()
        _NS_VALUE_POPUPS.clear(); _ns_debug_reset_session()
    elif action == "Preview":
        _ns_debug_preview(host_id)
        modal["ns_right_tab"] = "debug"
        modal["ns_show_script"] = True
    elif action in ("Toggle Camera Follow", "Toggle Auto-Pan Camera"):
        modal["ns_sim_auto_pan"] = not modal.get("ns_sim_auto_pan", True)
        button_node["_debug_button_pressed"] = modal["ns_sim_auto_pan"]
    elif action == "Toggle Continuous Loop":
        modal["ns_sim_auto_loop"] = not modal.get("ns_sim_auto_loop", False)
        button_node["_debug_button_pressed"] = modal["ns_sim_auto_loop"]
    elif action in ("Toggle Path Dimming", "Toggle Ignore Path Dim"):
        modal["ns_ignore_path_dim"] = not modal.get("ns_ignore_path_dim", False)
        button_node["_debug_button_pressed"] = modal["ns_ignore_path_dim"]
    elif action == "Toggle Values Only":
        modal["ns_debug_values_only"] = not modal.get("ns_debug_values_only", False)
        button_node["_debug_button_pressed"] = modal["ns_debug_values_only"]
    elif action == "Toggle Log Follow":
        modal["ns_debug_follow"] = not modal.get("ns_debug_follow", True)
        modal["ns_debug_user_scroll"] = not modal["ns_debug_follow"]
        button_node["_debug_button_pressed"] = modal["ns_debug_follow"]
    elif action == "Clear Debug Log":
        _ns_debug_reset_session()
        _NS_VALUE_POPUPS.clear()
        button_node["_debug_button_pressed"] = True
    elif action == "Unclip Host":
        host.setdefault("props", {})["clamped_to"] = ""
        host["props"].pop("_debug_buttons", None)
        button_node["_debug_button_pressed"] = True
    elif action in ("Toggle Host Setting", "Cycle Host Setting", "Set Host Setting True", "Set Host Setting False", "Set Host Setting Value"):
        props=host.setdefault("props",{});_setting=str(button_node.get("props",{}).get("setting","active") or "active")
        _hcls=NODE_DEFS.get(host.get("type"),NodeBase);_spec=getattr(_hcls,"properties",{}).get(_setting);_cur=props.get(_setting,getattr(_spec,"default",False))
        if action=="Toggle Host Setting":_new=not bool(_cur)
        elif action=="Set Host Setting True":_new=True
        elif action=="Set Host Setting False":_new=False
        elif action=="Set Host Setting Value":_new=button_node.get("props",{}).get("setting_value",1.0)
        elif _spec and getattr(_spec,"type","")=="dropdown" and getattr(_spec,"options",None):
            _opts=list(_spec.options);_new=_opts[(_opts.index(_cur)+1)%len(_opts)] if _cur in _opts else _opts[0]
        elif isinstance(_cur,bool):_new=not _cur
        elif isinstance(_cur,(int,float)):_new=float(_cur)+float(button_node.get("props",{}).get("setting_step",1.0))
        elif _setting=="layer" or _cur in ("front","behind"):_new="behind" if _cur=="front" else "front"
        else:_new=str(button_node.get("props",{}).get("setting_value",_cur))
        props[_setting]=_new;button_node["_debug_button_pressed"]=bool(_new) if isinstance(_new,bool) else True
        modal["ns_dirty"]=True;push_toast(f"{_setting.replace('_',' ').title()}: {_new}","info",1.5)
    else:
        props = host.setdefault("props", {})
        if action == "Toggle":
            if "force_path" in props:
                props["force_path"] = "Force False" if props.get("force_path") == "Force True" else "Force True"
                button_node["_debug_button_pressed"] = props["force_path"] == "Force True"
            elif "active" in props:
                props["active"] = not bool(props.get("active"))
                button_node["_debug_button_pressed"] = props["active"]
            elif "override_active" in props:
                props["override_active"] = not bool(props.get("override_active"))
                button_node["_debug_button_pressed"] = props["override_active"]
            else:
                host["_debug_button_toggle"] = not bool(host.get("_debug_button_toggle", False))
                button_node["_debug_button_pressed"] = host["_debug_button_toggle"]
        elif action in ("Force True", "Force False"):
            if "force_path" in props:
                props["force_path"] = action
            elif "active" in props:
                props["active"] = action == "Force True"
            elif "override_active" in props:
                props["override_active"] = action == "Force True"
            else:
                host["_debug_button_toggle"] = action == "Force True"
            button_node["_debug_button_pressed"] = action == "Force True"
        _ns_sim_start(host_id)
    _ns_log_debug(f"Debug Button '{label}' → {action}" +
                  (f" on {host.get('type', 'node')}" if host else ""),
                  kind="event", node_id=host_id if host else button_node.get("id"))
    push_toast(f"{label}: {action}", "info", 1.8)

def _ns_fire_utility_button(button_node):
    """Manually press a Utility Button from Canvas Debug."""
    if _ns_node_muted(button_node):
        push_toast("Muted Utility Button cannot trigger.", "warning", 1.8)
        return
    mode = button_node.get("props", {}).get("mode", "Momentary")
    if mode == "Toggle":
        button_node["_utility_active"] = not bool(button_node.get("_utility_active", False))
    else:
        button_node["_utility_active"] = True
    button_node["_utility_pressed_at"] = time.time()
    _ns_sim_start(button_node.get("id"))
    _ns_log_debug(f"Utility Button '{button_node.get('props', {}).get('label', 'Button')}' pressed",
                  kind="event", node_id=button_node.get("id"),
                  value=button_node.get("props", {}).get("default_value", 1.0))
    push_toast("Utility Button pressed", "info", 1.5)

def _ns_debug_reset_session():
    _NS_DEBUG_TRACE.clear()
    _NS_DEBUG_EVENTS.clear()
    _NS_DEBUG_WATCHES.clear()
    for k in list(_NS_DEBUG_STATS.keys()):
        _NS_DEBUG_STATS[k] = 0

def _ns_parse_vector(s, default=(0.0, 0.0)):
    """Parse "(x, y)" / "x,y" / "x y" text into a Vector2; default on failure.
    (This helper was called by vector nodes but never defined - any string fed
    into a vector input raised NameError at sim time.)"""
    try:
        txt = str(s).strip().strip("()[]")
        parts = [p for p in txt.replace(",", " ").split() if p]
        if len(parts) >= 2:
            return pygame.Vector2(float(parts[0]), float(parts[1]))
    except Exception:
        pass
    d = default if isinstance(default, (tuple, list)) and len(default) >= 2 else (0.0, 0.0)
    return pygame.Vector2(float(d[0]), float(d[1]))

def _ns_as_vec2(v, default=(0.0, 0.0)):
    """Coerce any simulator value (Vector2, tuple, list, string, None) into
    a real pygame.Vector2 so every vector node can operate on it safely."""
    try:
        if isinstance(v, pygame.Vector2):
            return pygame.Vector2(v)
        if isinstance(v, (tuple, list)) and len(v) >= 2:
            return pygame.Vector2(float(v[0]), float(v[1]))
        if isinstance(v, str):
            return _ns_parse_vector(v, default)
    except Exception:
        pass
    return pygame.Vector2(default[0], default[1])

def _ns_format_debug_value(v):
    """Render a debug-sim value for popups/logs. Vectors and 2-part
    tuples/lists show as '(x, y)' instead of being silently flattened
    into a single float (which is what caused vectors to display as 0.0)."""
    try:
        if hasattr(v, "x") and hasattr(v, "y"):
            return f"({v.x:g}, {v.y:g})"
        if isinstance(v, (tuple, list)) and len(v) == 2:
            return f"({float(v[0]):g}, {float(v[1]):g})"
        if isinstance(v, (int, float)):
            return f"{v:g}"
        return str(v)
    except Exception:
        return str(v)

def _ns_log_debug(msg, kind="info", node_id=None, value=None, color=None, meta=None):
    """Structured canvas-debug logger for the DEBUG tab + terminals."""
    text_msg = str(msg)
    _NS_DEBUG_TRACE.append(text_msg)
    if len(_NS_DEBUG_TRACE) > _NS_DEBUG_MAX_EVENTS:
        del _NS_DEBUG_TRACE[: len(_NS_DEBUG_TRACE) - _NS_DEBUG_MAX_EVENTS]
    kind = str(kind or "info")
    entry = {
        "t": time.time(), "kind": kind, "msg": text_msg, "node_id": node_id,
        "value": value,
        "color": tuple(int(c) for c in color[:3]) if isinstance(color, (list, tuple)) and len(color) >= 3 else None,
        "meta": meta or {},
    }
    _NS_DEBUG_EVENTS.append(entry)
    if len(_NS_DEBUG_EVENTS) > _NS_DEBUG_MAX_EVENTS:
        del _NS_DEBUG_EVENTS[: len(_NS_DEBUG_EVENTS) - _NS_DEBUG_MAX_EVENTS]
    _NS_DEBUG_STATS["steps"] = _NS_DEBUG_STATS.get("steps", 0) + 1
    if kind in _NS_DEBUG_STATS:
        _NS_DEBUG_STATS[kind] = _NS_DEBUG_STATS.get(kind, 0) + 1
    if kind == "exec":
        _NS_DEBUG_STATS["execs"] = _NS_DEBUG_STATS.get("execs", 0) + 1
    if kind == "error":
        _NS_DEBUG_STATS["errors"] = _NS_DEBUG_STATS.get("errors", 0) + 1
    if node_id is not None and value is not None:
        _NS_DEBUG_WATCHES[node_id] = value
    try:
        print(f"[debug:{kind}] {text_msg}")
    except Exception:
        pass

def _ns_clipboard_copy(text):
    text = str(text).replace("\x00","")
    try:
        if hasattr(pygame.scrap, "put_text"):
            pygame.scrap.put_text(text)
            return True
    except Exception:
        pass
    try:
        import tkinter as _tk
        _root = _tk.Tk()
        _root.withdraw()
        _root.clipboard_clear()
        _root.clipboard_append(text)
        _root.update()
        _root.destroy()
        return True
    except Exception:
        pass
    import subprocess
    for _cmd in (["pbcopy"], ["xclip", "-selection", "clipboard"], ["xsel", "--clipboard", "--input"], ["clip"]):
        try:
            p = subprocess.Popen(_cmd, stdin=subprocess.PIPE)
            p.communicate(text.encode("utf-8"), timeout=2)
            if p.returncode == 0:
                return True
        except Exception:
            continue
    return False

def _ns_find_source_lines_for_node(nid):
    """Given a blueprint node id, return the annotated Python source lines
    (with the invisible `# _ns_node:<id>` markers stripped) that the
    codegen attributed to that node in the currently-generated script.
    Used by the DEBUG tab's 'jump to source line' toggle so a log line can
    be traced back to the exact Python that produced it."""
    try:
        code = vs_build_script_code()
    except Exception:
        code = None
    if not code:
        return []
    import re as _re
    marker_re = _re.compile(r"\s*# _ns_node:(\d+)\s*$")
    out = []
    for line_no, raw in enumerate(code.split("\n"), start=1):
        m = marker_re.search(raw)
        if m and str(m.group(1)) == str(nid):
            clean = marker_re.sub("", raw).rstrip()
            if clean.strip():
                out.append((line_no, clean))
    return out

def _ns_debug_filters():
    f = modal.setdefault("ns_debug_filters", dict(_NS_DEBUG_FILTERS_DEFAULT))
    for k, v in _NS_DEBUG_FILTERS_DEFAULT.items():
        f.setdefault(k, v)
    return f

def _ns_debug_filtered_events():
    filters = _ns_debug_filters()
    values_only = bool(modal.get("ns_debug_values_only", False))
    q = str(modal.get("ns_debug_search", "") or "").strip().lower()
    out = []
    for e in _NS_DEBUG_EVENTS:
        kind = e.get("kind", "info")
        if values_only and kind not in ("value", "math", "branch", "color", "damage"):
            continue
        if not filters.get(kind, True):
            continue
        if q:
            blob = f"{e.get('msg','')} {kind} {e.get('value','')}".lower()
            if q not in blob:
                continue
        out.append(e)
    return out

def _ns_debug_format_event(e, show_time=True, show_kind=True, wrap_w=0):
    kind = e.get("kind", "info")
    msg = str(e.get("msg", ""))
    val = e.get("value", None)
    parts = []
    if show_time:
        ts = e.get("t", time.time())
        t0 = modal.get("ns_debug_session_t0")
        parts.append(f"+{max(0.0, ts - t0):6.2f}s" if t0 else time.strftime("%H:%M:%S", time.localtime(ts)))
    if show_kind:
        parts.append(f"[{kind.upper():6}]")
    line = (" ".join(parts) + " " + msg).strip()
    if val is not None and kind in ("value", "math", "branch", "color", "damage") and str(val) not in msg:
        line = f"{line}  ⇒  {val}"
    if wrap_w and wrap_w > 20:
        return textwrap.wrap(line, width=wrap_w) or [line]
    return [line]

def _ns_debug_kind_color(kind):
    return {
        "exec": (180, 220, 255), "value": (120, 255, 200), "math": (255, 210, 90),
        "branch": (180, 255, 120), "color": (255, 160, 255), "gather": (160, 200, 255),
        "event": (130, 105, 255), "damage": (255, 110, 100), "error": (255, 80, 80),
        "info": (220, 220, 230), "system": (160, 160, 180),
        "tip": (140, 185, 230),
    }.get(kind, (220, 220, 230))

# Nodes that own the structured DEBUG console tab when selected / clamped.
# A Vector Visualizer, Watcher, Math Grapher, etc. has its own inspector
# section and must not accidentally turn the whole right panel into DEBUG.
_NS_DEBUG_PANEL_OWNER_TYPES = frozenset({"debug_expander"})
_NS_DEBUG_CONSOLE_TYPES = frozenset({
    "debug_terminal", "debug_expander", "debug_watcher", "debug_probe",
    "debug_math_graph", "debug_vector_visualizer", "debug_assert",
    "debug_trigger_counter", "debug_breakpoint", "debug_converter",
    "debug_clamp_standard", "debug_clamp_step", "debug_clamp_loop",
    "debug_clamp_duration", "debug_clamp_value_forcer", "debug_clamp_debug_only",
    "debug_event_simulator", "debug_sound_test", "debug_cond_switch",
    "debug_timing_gate", "debug_signal_mux", "debug_dummy_target",
    "debug_mock_fighter", "debug_storage", "debug_get_storage", "debug_signal_gate", "debug_random_gate",
})

def _ns_is_debug_console_type(ntype):
    if not ntype:
        return False
    if ntype in _NS_DEBUG_CONSOLE_TYPES:
        return True
    return str(ntype).startswith("debug_")

def _ns_get_active_debug_node():
    nodes = modal.get("ns_nodes", {})
    selected = nodes.get(modal.get("ns_selected"))
    if not selected:
        return None
    return _ns_attached_expander_host(selected)

def draw_symbol_button(surface, rect, icon_key, hov, active=False, danger=False, tooltip=None, mouse_pos=(0, 0)):
    if danger:
        bg = (56, 24, 28) if hov else (34, 18, 20)
        border = (220, 70, 70)
        col = (255, 120, 120)
    elif active:
        bg = (240, 60, 180) if not hov else (255, 85, 200)
        border = (255, 255, 255)
        col = (255, 255, 255)
    else:
        bg = (28, 26, 42) if hov else (18, 16, 26)
        border = (90, 80, 110) if hov else PANEL_BORDER
        col = (240, 240, 246) if hov else (160, 160, 175)
        
    pygame.draw.rect(surface, bg, rect, border_radius=6)
    pygame.draw.rect(surface, border, rect, width=1, border_radius=6)
    
    icon_enum = IC.get(icon_key)
    if icon_enum:
        sz = max(11, min(16, rect.height - 8))
        surf = get_icon_fs(icon_key, sz, col)
        if surf:
            surface.blit(surf, (rect.centerx - surf.get_width() // 2, rect.centery - surf.get_height() // 2))
    else:
        txt = font_tiny.render(icon_key[:3].upper(), True, col)
        surface.blit(txt, (rect.centerx - txt.get_width() // 2, rect.centery - txt.get_height() // 2))
        
    if tooltip and hov:
        modal.setdefault("_ns_queued_tooltips", []).append((tooltip, mouse_pos))

def _ns_run_custom_dashboard_action(node, action, extra=None):
    nid = node.get("id")
    props = node.setdefault("props", {})
    _sim_vars = modal.setdefault("ns_sim_variables", {})
    
    if action == "delay_dec":
        cur_d = float(modal.get("ns_sim_delay", 0.55))
        modal["ns_sim_delay"] = max(0.0, round(cur_d - 0.05, 2))
        return
    elif action == "delay_inc":
        cur_d = float(modal.get("ns_sim_delay", 0.55))
        modal["ns_sim_delay"] = min(2.0, round(cur_d + 0.05, 2))
        return
    elif action.startswith("delay_preset:"):
        try:
            val = float(action.split(":")[1])
            modal["ns_sim_delay"] = val
        except Exception:
            pass
        return

    if action == "clamp_run":
        _ns_sim_start(nid)
    elif action == "clamp_step":
        if not modal.get("ns_sim_active"):
            _ns_sim_start(nid)
        modal["ns_sim_paused"] = True
        _ns_sim_step()
    elif action == "sim_reset":
        modal["ns_sim_active"] = False
        modal["ns_sim_paused"] = False
        modal["ns_sim_steps"] = []
        modal["ns_sim_variables"] = {}
        _NS_WIRE_FLOW.clear()
        _NS_EXEC_FLASH.clear()
        _NS_EXEC_FLASH_COLOR.clear()
        _NS_VALUE_POPUPS.clear()
        _ns_debug_reset_session()
        push_toast("Simulation reset.", "info")
    elif action == "unclip_host":
        node.setdefault("props", {})["clamped_to"] = ""
        node.setdefault("props", {})["target_group_id"] = ""
        modal["ns_dirty"] = True
        ns_snapshot()
        push_toast("Debugger unclipped from host.", "success")
    elif action == "toggle_loop":
        modal["ns_sim_auto_loop"] = not modal.get("ns_sim_auto_loop", False)
    elif action == "toggle_pan":
        modal["ns_sim_auto_pan"] = not modal.get("ns_sim_auto_pan", True)
    elif action == "toggle_ignore_dim":
        modal["ns_ignore_path_dim"] = not modal.get("ns_ignore_path_dim", False)
    elif action == "clear_raw":
        node["_raw_values"] = []
        push_toast("Raw values cleared.", "info")
    elif action == "copy_raw":
        raws = node.get("_raw_values", [])
        lines = []
        for r in raws:
            lines.append(f"+{r.get('time', 0.0):.2f}s: {r.get('source')} -> {r.get('target')}.{r.get('pin')} = {repr(r.get('value'))}")
        _ns_clipboard_copy("\n".join(lines))
        push_toast("Copied raw values to clipboard.", "success")
    elif action == "freeze_watch":
        node["_debug_frozen"] = not node.get("_debug_frozen", False)
    elif action == "clear_watch":
        modal.get("ns_sim_variables", {}).pop(nid, None)
        _NS_DEBUG_WATCHES.pop(nid, None)
        node["_watch_history"] = []
        push_toast("Watch cleared.", "info")
    elif action == "copy_watch":
        val = _NS_DEBUG_WATCHES.get(nid, modal.get("ns_sim_variables", {}).get(nid))
        _ns_clipboard_copy(repr(val))
        push_toast("Copied watch value.", "success")
    elif action == "clear_graph_history":
        node["_graph_history"] = []
        push_toast("Graph history cleared.", "info")
    elif action == "reset_graph_bounds":
        node.pop("_graph_min", None)
        node.pop("_graph_max", None)
        push_toast("Graph bounds reset.", "info")
    elif action == "zero_vector":
        modal.setdefault("ns_sim_variables", {})[nid] = pygame.Vector2()
        push_toast("Vector set to (0, 0).", "info")
    elif action == "copy_vector":
        val = modal.setdefault("ns_sim_variables", {}).get(nid, pygame.Vector2())
        _ns_clipboard_copy(repr(val))
        push_toast("Copied vector to clipboard.", "success")
    elif action == "track_vector":
        node["_track_input"] = not node.get("_track_input", True)
    elif action == "break_toggle":
        props["active"] = not bool(props.get("active", True))
    elif action == "continue_sim":
        modal["ns_sim_paused"] = False
    elif action == "clear_hits":
        node.pop("_break_hits", None)
        push_toast("Breakpoint hits cleared.", "info")
    elif action == "test_assert":
        _ns_sim_start(nid)
    elif action == "reset_assert":
        node.pop("_ns_assert_state", None)
    elif action == "fire_event":
        _ns_sim_start(nid)
    elif action == "reset_mock":
        props["event_type"] = "On Spawn"
        props["dealt"] = 15.0
        props["crit"] = False
        push_toast("Mock setup reset.", "info")
    elif action == "event_type_cycle":
        opts = ["On Spawn", "On Hit", "On Damage", "On Tick"]
        cur = str(props.get("event_type", "On Spawn"))
        props["event_type"] = opts[(opts.index(cur)+1)%len(opts)] if cur in opts else "On Spawn"
    elif action == "dealt_inc":
        props["dealt"] = float(props.get("dealt", 15.0)) + 5.0
    elif action == "dealt_dec":
        props["dealt"] = max(0.0, float(props.get("dealt", 15.0)) - 5.0)
    elif action == "crit_toggle":
        props["crit"] = not bool(props.get("crit", False))
    elif action == "refresh_dummy":
        props["hp"] = 100.0
        props["shield"] = 0.0
        props["defense"] = 5.0
        props["name"] = "Dummy" if node.get("type") == "debug_dummy_target" else "Mock Fighter"
        push_toast("Attributes reset.", "info")
    elif action == "copy_dummy":
        _ns_clipboard_copy(json.dumps(props, default=str, indent=2))
        push_toast("Copied specs to clipboard.", "success")
    elif action == "stat_inc":
        st_name = extra
        props[st_name] = float(props.get(st_name, 100.0)) + 10.0
    elif action == "stat_dec":
        st_name = extra
        props[st_name] = max(0.0, float(props.get(st_name, 100.0)) - 10.0)
    elif action == "counter_add":
        props["count"] = float(props.get("count", 0.0)) + 1.0
    elif action == "counter_reset":
        props["count"] = 0.0
    elif action == "counter_copy":
        _ns_clipboard_copy(str(props.get("count", 0.0)))
        push_toast("Copied count.", "success")
    elif action == "gate_start":
        node["_gate_started"] = time.time()
        node.pop("_gate_elapsed", None)
    elif action == "gate_stop":
        if node.get("_gate_started"):
            node["_gate_elapsed"] = time.time() - node["_gate_started"]
        else:
            push_toast("Timing gate was never started!", "warning")
    elif action == "gate_reset":
        node.pop("_gate_started", None)
        node.pop("_gate_elapsed", None)
    elif action == "sound_play":
        _process_simulated_node_effects(node, NODE_DEFS.get(node.get("type"), NodeBase))
    elif action == "freq_inc":
        props["frequency"] = min(2000.0, float(props.get("frequency", 440.0)) + 50.0)
    elif action == "freq_dec":
        props["frequency"] = max(100.0, float(props.get("frequency", 440.0)) - 50.0)
    elif action == "vol_inc":
        props["volume"] = min(1.0, float(props.get("volume", 1.0)) + 0.1)
    elif action == "vol_dec":
        props["volume"] = max(0.0, float(props.get("volume", 1.0)) - 0.1)

def _ns_draw_section_header(surface, panel_body, draw_y, title, icon_key, color=(240, 60, 180)):
    pygame.draw.rect(surface, (color[0]//6, color[1]//6, color[2]//6), (panel_body.x+4, draw_y, panel_body.width-8, 30), border_radius=6)
    pygame.draw.rect(surface, color, (panel_body.x+4, draw_y, panel_body.width-8, 30), width=1, border_radius=6)
    
    icon_enum = IC.get(icon_key)
    if icon_enum:
        blit_icon(surface, icon_enum, panel_body.x + 20, draw_y + 15, size=16, color=color)
        
    lbl = font_sm.render(title, True, color)
    surface.blit(lbl, (panel_body.x + 36 if icon_enum else panel_body.x + 12, draw_y + 15 - lbl.get_height() // 2))
    return draw_y + 36

def _ns_draw_description(surface, panel_body, draw_y, text, max_w):
    words = text.split()
    lines = []
    current_line = []
    for word in words:
        current_line.append(word)
        if font_tiny.size(" ".join(current_line))[0] > max_w:
            current_line.pop()
            lines.append(" ".join(current_line))
            current_line = [word]
    if current_line:
        lines.append(" ".join(current_line))
        
    for line in lines:
        lbl = font_tiny.render(line, True, TEXT_DIM)
        surface.blit(lbl, (panel_body.x + 12, draw_y))
        draw_y += 14
    return draw_y + 8

def _ns_draw_digital_display(surface, panel_body, draw_y, text, color=(0, 240, 240)):
    rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 44)
    pygame.draw.rect(surface, (10, 14, 18), rect, border_radius=8)
    pygame.draw.rect(surface, color, rect, width=1, border_radius=8)
    pygame.draw.rect(surface, (color[0]//10, color[1]//10, color[2]//10), rect.inflate(-2, -2), border_radius=7)
    
    lbl = font_sm.render(text, True, color)
    surface.blit(lbl, (rect.centerx - lbl.get_width() // 2, rect.centery - lbl.get_height() // 2))
    return draw_y + 52

def _ns_draw_sparkline(surface, panel_body, draw_y, history, color=(0, 240, 240), title="HISTORY"):
    rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 60)
    pygame.draw.rect(surface, (8, 8, 12), rect, border_radius=8)
    pygame.draw.rect(surface, PANEL_BORDER, rect, width=1, border_radius=8)
    
    tl = font_tiny.render(title, True, TEXT_FAINT)
    surface.blit(tl, (rect.x + 6, rect.y + 4))
    
    if len(history) < 2:
        empty = font_tiny.render("NO DATA YET", True, TEXT_FAINT)
        surface.blit(empty, (rect.centerx - empty.get_width()//2, rect.centery - empty.get_height()//2))
        return draw_y + 68
        
    vals = [float(v) for v in history if isinstance(v, (int, float))]
    if not vals:
        return draw_y + 68
    min_v = min(vals)
    max_v = max(vals)
    rng = max_v - min_v
    if rng == 0:
        rng = 1.0
        
    pts = []
    dx = (rect.width - 16) / max(1, len(vals) - 1)
    for i, v in enumerate(vals):
        px = rect.x + 8 + int(i * dx)
        py = rect.bottom - 6 - int((v - min_v) / rng * (rect.height - 18))
        pts.append((px, py))
        
    if len(pts) > 1:
        pygame.draw.lines(surface, color, False, pts, 2)
        
    lbl_max = font_tiny.render(f"max: {max_v:g}", True, TEXT_FAINT)
    lbl_min = font_tiny.render(f"min: {min_v:g}", True, TEXT_FAINT)
    surface.blit(lbl_max, (rect.right - lbl_max.get_width() - 6, rect.y + 4))
    surface.blit(lbl_min, (rect.right - lbl_min.get_width() - 6, rect.bottom - lbl_min.get_height() - 4))
    
    return draw_y + 68

def _ns_draw_vector_grid(surface, panel_body, draw_y, vec, mouse_pos):
    rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 110)
    pygame.draw.rect(surface, (12, 10, 16), rect, border_radius=8)
    pygame.draw.rect(surface, PANEL_BORDER, rect, width=1, border_radius=8)
    
    cx = rect.x + 60
    cy = rect.centery
    
    for r_sz in (20, 40, 50):
        pygame.draw.circle(surface, (40, 36, 50), (cx, cy), r_sz, 1)
    pygame.draw.line(surface, (50, 45, 60), (cx - 50, cy), (cx + 50, cy), 1)
    pygame.draw.line(surface, (50, 45, 60), (cx, cy - 50), (cx, cy + 50), 1)
    
    if vec and isinstance(vec, pygame.Vector2) and vec.length() > 1e-5:
        l_px = min(48, vec.length() * 0.4)
        v_dir = vec.normalize()
        tx = cx + int(v_dir.x * l_px)
        ty = cy + int(v_dir.y * l_px)
        pygame.draw.line(surface, (240, 60, 180), (cx, cy), (tx, ty), 2)
        pygame.draw.circle(surface, (255, 120, 220), (tx, ty), 4)
        
    hx = rect.x + 124
    hy = rect.y + 10
    
    l_val = vec.length() if vec else 0.0
    ang_val = vec.as_polar()[1] if (vec and vec.length() > 1e-5) else 0.0
    dx_val = vec.x if vec else 0.0
    dy_val = vec.y if vec else 0.0
    
    metrics = [
        ("LENGTH", f"{l_val:.2f}", (0, 240, 240)),
        ("ANGLE", f"{ang_val:.1f}°", GOLD),
        ("X", f"{dx_val:.2f}", TEXT_MAIN),
        ("Y", f"{dy_val:.2f}", TEXT_MAIN),
    ]
    for lbl, val, col in metrics:
        lbl_surf = font_tiny.render(lbl, True, TEXT_FAINT)
        val_surf = font_tiny.render(val, True, col)
        surface.blit(lbl_surf, (hx, hy))
        surface.blit(val_surf, (rect.right - val_surf.get_width() - 10, hy))
        hy += 18
        
    return draw_y + 118

def _ns_draw_debug_dashboard(screen, panel_body, mouse_pos, clip_prev2):
    modal["_ns_custom_debug_btn_rects"] = []
    
    # Retrieve active debug node
    node = _ns_get_active_debug_node()
    if not node or node.get("type") == "debug_terminal":
        # Render general log terminal
        _ns_draw_general_terminal(screen, panel_body, mouse_pos, clip_prev2)
        return
        
    ntype = node.get("type", "")
    cls = NODE_DEFS.get(ntype, NodeBase)
    props = node.setdefault("props", {})
    sim_vars = modal.setdefault("ns_sim_variables", {})
    
    # Render viewports & scroll
    viewport = pygame.Rect(panel_body.x, panel_body.y, panel_body.width, panel_body.height)
    screen.set_clip(viewport)
    scroll = max(0.0, float(modal.setdefault("ns_debug_scroll", 0.0)))
    draw_y = viewport.y - scroll + 6
    max_w = viewport.width - 24
    mxm, mym = mouse_pos
    
    # 1. Custom Node Header & Title
    draw_y = _ns_draw_section_header(screen, panel_body, draw_y, cls.title.upper(), "bug", color=(240, 60, 180))
    draw_y = _ns_draw_description(screen, panel_body, draw_y, getattr(cls, "__doc__", "") or cls.title, max_w)
    

    # 2. Connection Status Indicator
    if ntype != "debug_raw_value_terminal":
        clamped_id = props.get("clamped_to", "")
        nodes_map = modal.get("ns_nodes", {})
        host_node = nodes_map.get(clamped_id)
        if host_node is None and str(clamped_id).isdigit():
            host_node = nodes_map.get(int(clamped_id))
            
        status_rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 32)
        if host_node:
            ui_draw_rect(screen, (15, 35, 25), status_rect, border_radius=6)
            ui_draw_rect(screen, GOOD, status_rect, width=1, border_radius=6)
            lbl_st = font_tiny.render(f"CLIPPED TO: {host_node.get('type','').replace('event_','').upper()} (ID: {host_node['id']})", True, GOOD)
        else:
            ui_draw_rect(screen, (35, 25, 15), status_rect, border_radius=6)
            ui_draw_rect(screen, GOLD, status_rect, width=1, border_radius=6)
            lbl_st = font_tiny.render("DISCONNECTED: DRAG CLIP SOCKET", True, GOLD)
        screen.blit(lbl_st, (status_rect.centerx - lbl_st.get_width()//2, status_rect.centery - lbl_st.get_height()//2))
        draw_y += 40
    
    # 3. Handle Node Specific Visuals and Actions
    if ntype == "debug_audio_visualizer":
        # Full Waveform Oscilloscope + Frequency Spectrum Display in Debug Panel!
        wf_rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 110)
        ui_draw_rect(screen, (8, 12, 22), wf_rect, border_radius=8)
        ui_draw_rect(screen, (60, 180, 240), wf_rect, width=1, border_radius=8)

        # Oscilloscope center axis
        pygame.draw.line(screen, (25, 40, 60), (wf_rect.x, wf_rect.centery), (wf_rect.right, wf_rect.centery), 1)

        # Live sine wavelength curves
        _now_t = time.time()
        _pts_wave = []
        for _wx in range(wf_rect.width):
            _wy = wf_rect.centery + int(math.sin(_wx * 0.12 + _now_t * 9.0) * 28.0 * math.cos(_wx * 0.04 + _now_t * 3.0))
            _pts_wave.append((wf_rect.x + _wx, max(wf_rect.y + 4, min(wf_rect.bottom - 4, _wy))))
        if len(_pts_wave) > 1:
            pygame.draw.lines(screen, (80, 220, 255), False, _pts_wave, 2)

        draw_y += 118

        # 16-bar Spectrum Frequency Analyzer
        spec_rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 65)
        ui_draw_rect(screen, (10, 10, 16), spec_rect, border_radius=6)
        ui_draw_rect(screen, PANEL_BORDER, spec_rect, width=1, border_radius=6)

        num_bars = 16
        bw = (spec_rect.width - 12) // num_bars
        for bi in range(num_bars):
            bar_h = int((math.sin(_now_t * 6.0 + bi * 0.7) * 0.5 + 0.5) * (spec_rect.height - 12))
            bx = spec_rect.x + 6 + bi * bw
            by = spec_rect.bottom - 4 - bar_h
            bcol = (0, 230, 255) if bi < 8 else (240, 60, 180)
            ui_draw_rect(screen, bcol, (bx, by, bw - 2, max(2, bar_h)), border_radius=2)

        draw_y += 75

    elif ntype == "debug_audio_clamp":
        af_path = str(props.get("audio_file", "") or "No audio path set")
        vol_val = float(props.get("volume", 1.0))
        pit_val = float(props.get("pitch", 1.0))

        aud_btn = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 32)
        hov_aud = aud_btn.collidepoint(mxm, mym)
        draw_button(aud_btn, "🔊 AUDITION / HEAR SOUND NOW", hov_aud)
        modal["_ns_custom_debug_btn_rects"].append((aud_btn, "audio_clamp_audition", node["id"], None))
        draw_y += 40

        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"FILE: {af_path[:24]}", color=(0, 230, 255))
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"VOL: {vol_val:.2f}  ·  PITCH: {pit_val:.2f}", color=(240, 120, 220))

    elif ntype == "debug_audio_terminal":
        term_rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 180)
        ui_draw_rect(screen, (12, 8, 20), term_rect, border_radius=8)
        ui_draw_rect(screen, (240, 60, 180), term_rect, width=1, border_radius=8)

        _tf = font_tiny
        _ty = term_rect.y + 6
        _a_events = _NS_AUDIO_LOG_EVENTS[-max(1, (term_rect.height - 12) // 14):]
        if not _a_events:
            screen.blit(_tf.render("NO AUDIO EVENTS LOGGED YET", True, TEXT_DIM), (term_rect.x + 8, _ty))
        else:
            for _ae in _a_events:
                _txt = f"[{_ae['channel']}] {_ae['path'][:24]}  v:{_ae['volume']:.2f} p:{_ae['pitch']:.2f}"
                screen.blit(_tf.render(_txt, True, (255, 200, 250)), (term_rect.x + 8, _ty))
                _ty += 14

        draw_y += 190

    if ntype == "debug_raw_value_terminal":
        # Raw value terminal: Displays values captured during simulation
        raws = node.setdefault("_raw_values", [])
        
        # Dashboard actions (symbols only)
        act_rect1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        act_rect2 = pygame.Rect(act_rect1.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, act_rect1, "copy", act_rect1.collidepoint(mxm, mym), tooltip="Copy Captured Values", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, act_rect2, "delete", act_rect2.collidepoint(mxm, mym), danger=True, tooltip="Clear Captured Values", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((act_rect1, "copy_raw", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((act_rect2, "clear_raw", node["id"], None))
        draw_y += 34
        
        # Display the terminal rows
        term_rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 220)
        ui_draw_rect(screen, (5, 8, 12), term_rect, border_radius=8)
        ui_draw_rect(screen, (40, 200, 180), term_rect, width=1, border_radius=8)
        
        _ry = term_rect.y + 6
        if not raws:
            _empty = font_tiny.render("WAITING FOR SIMULATION VALUES...", True, TEXT_FAINT)
            screen.blit(_empty, (term_rect.centerx - _empty.get_width()//2, term_rect.centery - _empty.get_height()//2))
        else:
            for item in raws[-16:]: # last 16 values
                t_str = f"+{max(0.0, item.get('time', 0.0) - modal.get('ns_debug_session_t0', 0.0)):.2f}s" if modal.get("ns_debug_session_t0") else ""
                prefix = f"[{t_str}] {item.get('pin','value')}: "
                val_repr = repr(item.get("value"))
                full_text = prefix + val_repr
                txt_surf = font_tiny.render(full_text[:38], True, (90, 255, 210))
                screen.blit(txt_surf, (term_rect.x + 8, _ry))
                _ry += 13
                if _ry > term_rect.bottom - 12:
                    break
        draw_y += 230
        
    elif ntype.startswith("debug_clamp_"):
        # Clamp cockpit actions (play, step, reset, disconnect)
        b_sz = 38
        gap = 6
        rx = panel_body.x + 8
        actions_list = [
            ("play", "clamp_run", "Fires the Clamp (triggers simulation)"),
            ("skip_fwd", "clamp_step", "Step Single Simulation Frame"),
            ("refresh", "sim_reset", "Reset Entire Simulation"),
            ("close", "unclip_host", "Disconnect / Unclip Debugger")
        ]
        for icon, act, tooltip in actions_list:
            r = pygame.Rect(rx, draw_y, b_sz, 26)
            is_dg = (act == "unclip_host")
            draw_symbol_button(screen, r, icon, r.collidepoint(mxm, mym), danger=is_dg, tooltip=tooltip, mouse_pos=(mxm, mym))
            modal["_ns_custom_debug_btn_rects"].append((r, act, node["id"], None))
            rx += b_sz + gap
        draw_y += 34
        
        # Checklist option boxes (Continuous Loop, Auto-Pan, Ignore Path Dim)
        opts = [
            ("ns_sim_auto_loop", "Continuous Infinite Loop", "toggle_loop", (240, 60, 180)),
            ("ns_sim_auto_pan", "Auto-Pan Camera Tracker", "toggle_pan", (240, 60, 180)),
            ("ns_ignore_path_dim", "Ignore Path Dim / Disabled Tint", "toggle_ignore_dim", (255, 170, 40))
        ]
        for key, label, action, color in opts:
            on = bool(modal.get(key, True if "auto_pan" in key else False))
            chk = pygame.Rect(panel_body.x + 10, draw_y, 16, 16)
            ui_draw_rect(screen, color if on else PANEL_BORDER, chk, border_radius=4)
            if on:
                ui_draw_rect(screen, (255, 255, 255), chk.inflate(-6, -6), border_radius=2)
            lbl = font_tiny.render(label, True, TEXT_MAIN if on else TEXT_DIM)
            screen.blit(lbl, (chk.right + 8, chk.y + 1))
            modal["_ns_custom_debug_btn_rects"].append((chk, action, node["id"], None))
            draw_y += 22
        draw_y += 8
        
        # Show specific fields for clamping properties
        if ntype == "debug_clamp_standard":
            fv = props.get("force_value", 10.0)
            draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"FORCED VALUE: {fv:g}", color=(240, 60, 180))
        elif ntype == "debug_clamp_value_forcer":
            ov = bool(props.get("override_active", True))
            fn = props.get("forced_number", 0.0)
            fs = props.get("forced_string", "forced")
            status_text = f"ACTIVE OVERRIDE: {fs} ({fn:g})" if ov else "OVERRIDE BYPASSED"
            draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, status_text, color=GOLD if ov else TEXT_DIM)
        elif ntype == "debug_clamp_duration":
            mult = props.get("time_multiplier", 1.0)
            draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"SPEED MULTIPLIER: x{mult:g}", color=(100, 200, 255))
        elif ntype == "debug_clamp_step":
            step = props.get("current_step", 1.0)
            draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"CURRENT STEP: {int(step)}", color=(180, 100, 255))
        elif ntype == "debug_clamp_loop":
            pause_on = bool(props.get("pause_on_each", True))
            status_text = "PAUSE ITERATIONS: ON" if pause_on else "PAUSE ITERATIONS: OFF"
            draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, status_text, color=(180, 100, 255))
            
    elif ntype == "debug_watcher":
        # Capture and display rolling values
        val = sim_vars.get(node["id"])
        if val is None:
            val = _NS_DEBUG_WATCHES.get(node["id"], "None")
            
        # Throttled history capture
        if modal.get("ns_sim_active") and not modal.get("ns_sim_paused"):
            last_t = node.get("_last_history_t", 0)
            now_ms = pygame.time.get_ticks()
            if now_ms - last_t > 150:
                node["_last_history_t"] = now_ms
                history = node.setdefault("_watch_history", [])
                try:
                    history.append(float(val))
                    if len(history) > 40:
                        history.pop(0)
                except Exception:
                    pass
                    
        # Controls
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        r3 = pygame.Rect(r2.right + 6, draw_y, 40, 26)
        frozen = bool(node.get("_debug_frozen"))
        draw_symbol_button(screen, r1, "pause" if frozen else "play", r1.collidepoint(mxm, mym), active=frozen, tooltip="Freeze / Lock Updates", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "delete", r2.collidepoint(mxm, mym), danger=True, tooltip="Clear Watched Value", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r3, "copy", r3.collidepoint(mxm, mym), tooltip="Copy Value to Clipboard", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "freeze_watch", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "clear_watch", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r3, "copy_watch", node["id"], None))
        draw_y += 34
        
        # Digital value readout
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"VALUE: {str(val)}", color=(0, 240, 240))
        
        # Sparkline
        draw_y = _ns_draw_sparkline(screen, panel_body, draw_y, node.get("_watch_history", []), color=(0, 240, 240), title="WATCH HISTORY")
        
    elif ntype == "debug_math_graph":
        # Capture and graph rolling values
        val = 0.0
        for l in modal.get("ns_links", []):
            if l["to"] == node["id"] and l["to_pin"] == "value":
                src = nodes_map.get(l["from"])
                if src:
                    try:
                        val = _ns_eval_node_output(src, pin_name=l.get("from_pin"))
                    except Exception:
                        pass
                break
                
        # History capture
        if modal.get("ns_sim_active") and not modal.get("ns_sim_paused"):
            last_t = node.get("_last_history_t", 0)
            now_ms = pygame.time.get_ticks()
            if now_ms - last_t > 150:
                node["_last_history_t"] = now_ms
                history = node.setdefault("_graph_history", [])
                try:
                    history.append(float(val))
                    if len(history) > 40:
                        history.pop(0)
                except Exception:
                    pass
                    
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "delete", r1.collidepoint(mxm, mym), danger=True, tooltip="Clear Graph History", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "refresh", r2.collidepoint(mxm, mym), tooltip="Reset Waveform Boundaries", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "clear_graph_history", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "reset_graph_bounds", node["id"], None))
        draw_y += 34
        
        # Display large readout
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"CURRENT INPUT: {float(val or 0.0):g}", color=(80, 180, 255))
        # Draw Sparkline
        draw_y = _ns_draw_sparkline(screen, panel_body, draw_y, node.get("_graph_history", []), color=(80, 180, 255), title="WAVEFORM HISTORY")
        
    elif ntype == "debug_vector_visualizer":
        vec = pygame.Vector2(0, 0)
        for l in modal.get("ns_links", []):
            if l["to"] == node["id"] and l["to_pin"] == "vector":
                src = nodes_map.get(l["from"])
                if src:
                    try:
                        vval = _ns_eval_node_output(src, pin_name=l.get("from_pin"))
                        if isinstance(vval, pygame.Vector2):
                            vec = pygame.Vector2(vval)
                        elif isinstance(vval, (tuple, list)) and len(vval) >= 2:
                            vec = pygame.Vector2(float(vval[0]), float(vval[1]))
                    except Exception:
                        pass
                break
                
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "delete", r1.collidepoint(mxm, mym), danger=True, tooltip="Zero / Reset Vector", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "copy", r2.collidepoint(mxm, mym), tooltip="Copy Vector specs", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "zero_vector", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "copy_vector", node["id"], None))
        draw_y += 34
        
        draw_y = _ns_draw_vector_grid(screen, panel_body, draw_y, vec, mouse_pos)
        
    elif ntype == "debug_breakpoint":
        hits = int(node.get("_break_hits", 0))
        act = bool(props.get("active", True))
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        r3 = pygame.Rect(r2.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "check" if act else "close", r1.collidepoint(mxm, mym), active=act, tooltip="Toggle Arm State", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "play", r2.collidepoint(mxm, mym), tooltip="Resume Simulation", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r3, "delete", r3.collidepoint(mxm, mym), danger=True, tooltip="Clear Hit History", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "break_toggle", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "continue_sim", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r3, "clear_hits", node["id"], None))
        draw_y += 34
        
        status_txt = "HALTED AT BREAKPOINT" if (modal.get("ns_sim_paused") and modal.get("ns_sim_start_node") == node["id"]) else ("ARMED & READY" if act else "DISABLED / INACTIVE")
        col = DANGER if "HALTED" in status_txt else (GOLD if act else TEXT_DIM)
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, status_txt, color=col)
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"TOTAL BREAK HITS: {hits}", color=(255, 100, 100))
        
    elif ntype == "debug_assert":
        state = node.get("_ns_assert_state", "None")
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "play", r1.collidepoint(mxm, mym), tooltip="Test Assertion Run", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "refresh", r2.collidepoint(mxm, mym), tooltip="Reset Assertion State", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "test_assert", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "reset_assert", node["id"], None))
        draw_y += 34
        
        color = GOOD if state == "Passed" else (DANGER if state == "Failed" else TEXT_DIM)
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"STATE: {state.upper()}", color=color)
        draw_y = _ns_draw_description(screen, panel_body, draw_y, f"Warning Msg: {props.get('error_message', 'Assertion Failed!')}", max_w)
        
    elif ntype == "debug_event_simulator":
        et = props.get("event_type", "On Spawn")
        dealt = float(props.get("dealt", 15.0))
        crit = bool(props.get("crit", False))
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        r3 = pygame.Rect(r2.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "play", r1.collidepoint(mxm, mym), tooltip="FIRE SIMULATED EVENT", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "refresh", r2.collidepoint(mxm, mym), tooltip="Reset Sim Parameters", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r3, "menu", r3.collidepoint(mxm, mym), tooltip="Cycle Target Event", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "fire_event", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "reset_mock", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r3, "event_type_cycle", node["id"], None))
        draw_y += 34
        
        # Render sliders for Dealt damage
        ch1 = pygame.Rect(panel_body.x + 8, draw_y, 16, 16)
        ui_draw_rect(screen, (240, 60, 180) if crit else PANEL_BORDER, ch1, border_radius=4)
        if crit:
            ui_draw_rect(screen, (255, 255, 255), ch1.inflate(-6, -6), border_radius=2)
        lbl = font_tiny.render("Critical Hit flag (CRIT)", True, TEXT_MAIN if crit else TEXT_DIM)
        screen.blit(lbl, (ch1.right + 8, ch1.y + 1))
        modal["_ns_custom_debug_btn_rects"].append((ch1, "crit_toggle", node["id"], None))
        draw_y += 24
        
        dec_btn = pygame.Rect(panel_body.x + 8, draw_y, 30, 20)
        inc_btn = pygame.Rect(dec_btn.right + 4, draw_y, 30, 20)
        draw_symbol_button(screen, dec_btn, "minus", dec_btn.collidepoint(mxm, mym), tooltip="Decrease Damage", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, inc_btn, "plus", inc_btn.collidepoint(mxm, mym), tooltip="Increase Damage", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((dec_btn, "dealt_dec", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((inc_btn, "dealt_inc", node["id"], None))
        draw_y += 24
        
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"EVENT: {et.upper()}", color=(130, 105, 255))
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"DEALT DMG: {dealt:g}", color=(255, 100, 100))
        
    elif ntype in ("debug_mock_fighter", "debug_dummy_target"):
        hp = float(props.get("hp", 100.0))
        shield = float(props.get("shield", 0.0))
        defense = float(props.get("defense", 5.0))
        name = props.get("name", "Mock Fighter" if ntype == "debug_mock_fighter" else "Dummy")
        team = props.get("team", "Enemies" if ntype == "debug_dummy_target" else "Allies")
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "refresh", r1.collidepoint(mxm, mym), tooltip="Reset Stats", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "copy", r2.collidepoint(mxm, mym), tooltip="Copy Character specifications", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "refresh_dummy", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "copy_dummy", node["id"], None))
        draw_y += 34
        
        # Display Stats HUD
        card_rect = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 120)
        ui_draw_rect(screen, (12, 10, 15), card_rect, border_radius=8)
        ui_draw_rect(screen, PANEL_BORDER, card_rect, width=1, border_radius=8)
        
        # HP bar
        bar_w = card_rect.width - 24
        hp_rect = pygame.Rect(card_rect.x + 12, card_rect.y + 12, bar_w, 16)
        ui_draw_rect(screen, (40, 15, 18), hp_rect, border_radius=4)
        pct = max(0.0, min(1.0, hp / 100.0))
        ui_draw_rect(screen, DANGER, (hp_rect.x, hp_rect.y, int(hp_rect.width * pct), hp_rect.height), border_radius=4)
        hp_lbl = font_tiny.render(f"HEALTH: {hp:.1f} / 100", True, (255, 220, 220))
        screen.blit(hp_lbl, (hp_rect.centerx - hp_lbl.get_width()//2, hp_rect.centery - hp_lbl.get_height()//2))
        
        # Shield bar
        sh_rect = pygame.Rect(card_rect.x + 12, hp_rect.bottom + 8, bar_w, 16)
        ui_draw_rect(screen, (10, 20, 30), sh_rect, border_radius=4)
        spct = max(0.0, min(1.0, shield / 100.0))
        ui_draw_rect(screen, (50, 150, 255), (sh_rect.x, sh_rect.y, int(sh_rect.width * spct), sh_rect.height), border_radius=4)
        sh_lbl = font_tiny.render(f"SHIELD: {shield:.1f}", True, (200, 240, 255))
        screen.blit(sh_lbl, (sh_rect.centerx - sh_lbl.get_width()//2, sh_rect.centery - sh_lbl.get_height()//2))
        
        # Name and alignment
        txt_name = font_tiny.render(f"NAME: {name}", True, TEXT_MAIN)
        txt_team = font_tiny.render(f"ALIGNMENT: {team.upper()}", True, GOOD if team == "Allies" else GOLD)
        txt_def = font_tiny.render(f"DEFENSE: {defense:.1f}", True, TEXT_DIM)
        screen.blit(txt_name, (card_rect.x + 12, sh_rect.bottom + 10))
        screen.blit(txt_team, (card_rect.x + 12, sh_rect.bottom + 26))
        screen.blit(txt_def, (card_rect.right - txt_def.get_width() - 12, sh_rect.bottom + 10))
        draw_y += 130
        
        # Quick adjusting buttons
        y_btns = draw_y
        for st_name, label in [("hp", "Health"), ("shield", "Shield"), ("defense", "Defense")]:
            row_r = pygame.Rect(panel_body.x + 8, y_btns, panel_body.width - 16, 22)
            lbl = font_tiny.render(label, True, TEXT_MAIN)
            screen.blit(lbl, (row_r.x + 4, row_r.y + 3))
            
            b_dec = pygame.Rect(row_r.right - 54, row_r.y, 22, 18)
            b_inc = pygame.Rect(row_r.right - 26, row_r.y, 22, 18)
            draw_symbol_button(screen, b_dec, "minus", b_dec.collidepoint(mxm, mym), tooltip=f"Decrease {label}", mouse_pos=(mxm, mym))
            draw_symbol_button(screen, b_inc, "plus", b_inc.collidepoint(mxm, mym), tooltip=f"Increase {label}", mouse_pos=(mxm, mym))
            modal["_ns_custom_debug_btn_rects"].append((b_dec, "stat_dec", node["id"], st_name))
            modal["_ns_custom_debug_btn_rects"].append((b_inc, "stat_inc", node["id"], st_name))
            y_btns += 26
        draw_y = y_btns + 10
        
    elif ntype == "debug_trigger_counter":
        count = float(props.get("count", 0.0))
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        r3 = pygame.Rect(r2.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "plus", r1.collidepoint(mxm, mym), tooltip="Increment +1", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "refresh", r2.collidepoint(mxm, mym), tooltip="Reset Counter", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r3, "copy", r3.collidepoint(mxm, mym), tooltip="Copy Count", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "counter_add", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "counter_reset", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r3, "counter_copy", node["id"], None))
        draw_y += 34
        
        # retro display
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"[ {int(count):05d} ]", color=(0, 240, 240))
        
    elif ntype == "debug_timing_gate":
        started = node.get("_gate_started")
        elapsed = node.get("_gate_elapsed")
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        r3 = pygame.Rect(r2.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "play", r1.collidepoint(mxm, mym), active=bool(started and not elapsed), tooltip="Trigger stopwatch START", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r2, "stop", r2.collidepoint(mxm, mym), tooltip="Trigger stopwatch STOP", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, r3, "refresh", r3.collidepoint(mxm, mym), tooltip="Reset Stopwatch", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "gate_start", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r2, "gate_stop", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((r3, "gate_reset", node["id"], None))
        draw_y += 34
        
        # running check
        if started and not elapsed:
            display_txt = "RUNNING..."
            col = GOLD
        elif elapsed is not None:
            display_txt = f"{elapsed:.3f}s ({elapsed*1000:.1f}ms)"
            col = (0, 240, 240)
        else:
            display_txt = "0.000s"
            col = TEXT_DIM
            
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, display_txt, color=col)
        
    elif ntype == "debug_sound_test":
        freq = float(props.get("frequency", 440.0))
        vol = float(props.get("volume", 1.0))
        
        r1 = pygame.Rect(panel_body.x + 8, draw_y, 40, 26)
        r2 = pygame.Rect(r1.right + 6, draw_y, 40, 26)
        draw_symbol_button(screen, r1, "play", r1.collidepoint(mxm, mym), tooltip="Play Tone Beep", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((r1, "sound_play", node["id"], None))
        draw_y += 34
        
        # frequency adjusting
        row_fr = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 22)
        screen.blit(font_tiny.render("FREQUENCY", True, TEXT_MAIN), (row_fr.x + 4, row_fr.y + 3))
        b_fdec = pygame.Rect(row_fr.right - 54, row_fr.y, 22, 18)
        b_finc = pygame.Rect(row_fr.right - 26, row_fr.y, 22, 18)
        draw_symbol_button(screen, b_fdec, "minus", b_fdec.collidepoint(mxm, mym), tooltip="Decrease Freq -50Hz", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, b_finc, "plus", b_finc.collidepoint(mxm, mym), tooltip="Increase Freq +50Hz", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((b_fdec, "freq_dec", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((b_finc, "freq_inc", node["id"], None))
        draw_y += 26
        
        # volume adjusting
        row_vl = pygame.Rect(panel_body.x + 8, draw_y, panel_body.width - 16, 22)
        screen.blit(font_tiny.render("VOLUME", True, TEXT_MAIN), (row_vl.x + 4, row_vl.y + 3))
        b_vdec = pygame.Rect(row_vl.right - 54, row_vl.y, 22, 18)
        b_vinc = pygame.Rect(row_vl.right - 26, row_vl.y, 22, 18)
        draw_symbol_button(screen, b_vdec, "minus", b_vdec.collidepoint(mxm, mym), tooltip="Decrease Vol -10%", mouse_pos=(mxm, mym))
        draw_symbol_button(screen, b_vinc, "plus", b_vinc.collidepoint(mxm, mym), tooltip="Increase Vol +10%", mouse_pos=(mxm, mym))
        modal["_ns_custom_debug_btn_rects"].append((b_vdec, "vol_dec", node["id"], None))
        modal["_ns_custom_debug_btn_rects"].append((b_vinc, "vol_inc", node["id"], None))
        draw_y += 32
        
        draw_y = _ns_draw_digital_display(screen, panel_body, draw_y, f"{int(freq)} Hz  ·  {int(vol*100)}%", color=(180, 100, 255))
        
    else:
        # Fallback for any other debug types
        draw_y = _ns_draw_description(screen, panel_body, draw_y, f"Generic debug dashboard for: {ntype}", max_w)
        draw_y += 20
        
    # Calculate scrollbar & limits
    content_h = (draw_y + scroll) - viewport.y
    modal["_ns_debug_max_scroll"] = max(0, content_h - viewport.height)
    modal["ns_debug_scroll"] = min(scroll, modal["_ns_debug_max_scroll"])
    
    screen.set_clip(clip_prev2)
    if modal["_ns_debug_max_scroll"] > 0:
        _sbtr, _sbns = draw_scrollbar(viewport, modal["ns_debug_scroll"], content_h, viewport.height, mouse_pos)
        modal["ns_debug_scroll"] = _sbns
        
    modal["_ns_script_rect"] = viewport
    modal["_ns_debug_log_rect"] = viewport

def _ns_draw_general_terminal(screen, panel_body, mouse_pos, clip_prev2):
    # ── Icon-only structured DEBUG console ────────────────
    modal["_ns_debug_panel_rect"] = panel_body
    clip_prev2 = screen.get_clip(); screen.set_clip(panel_body)
    mxm, mym = mouse_pos

    # Toolbar (icons only — tooltips on hover)
    tb = pygame.Rect(panel_body.x + 4, panel_body.y + 4, panel_body.width - 8, 30)
    ui_draw_rect(screen, (16, 12, 22), tb, border_radius=7)
    ui_draw_rect(screen, (90, 40, 80), tb, width=1, border_radius=7)

    btn = 22
    gap = 4
    x = tb.x + 5
    y = tb.y + 4
    filters = _ns_debug_filters()
    vo_on = bool(modal.get("ns_debug_values_only", False))
    follow_on = bool(modal.get("ns_debug_follow", True))

    # Search field (compact, icon inside)
    search_w = max(70, tb.width - (btn + gap) * 14 - 12)
    search_rect = pygame.Rect(x, y, search_w, btn)
    sfocus = modal.get("focus") == "ns_debug_search"
    ui_draw_rect(screen, FIELD_BG, search_rect, border_radius=5)
    ui_draw_rect(screen, (240, 60, 180) if sfocus else PANEL_BORDER, search_rect, width=1, border_radius=5)
    sic = get_icon_fs("search", 12, TEXT_FAINT) if IC.get("search") else None
    if sic:
        screen.blit(sic, (search_rect.x + 4, search_rect.centery - sic.get_height() // 2))
    q = modal.get("ns_debug_search", "")
    qdisp = q + ("|" if sfocus and int(pygame.time.get_ticks() / 500) % 2 == 0 else "")
    if not q and not sfocus:
        qdisp = "filter"
        qcol = TEXT_FAINT
    else:
        qcol = TEXT_MAIN
    ql = font_tiny.render(qdisp[:28], True, qcol)
    screen.blit(ql, (search_rect.x + (20 if sic else 6), search_rect.centery - ql.get_height() // 2))
    modal["_ns_debug_search_rect"] = search_rect
    x = search_rect.right + gap + 2

    # Values-only (eye)
    vo_rect = pygame.Rect(x, y, btn, btn)
