def draw_asset_creator(mouse_pos):
    global left_click_this_frame
    if modal.get("type")!="asset_creator": return
    screen.set_clip(None); modal_sliders.clear()
    asset_ui_touch()

    proj=modal.setdefault("_ac_project",_ac_project_default())
    zoom=float(modal.get("_ac_zoom",4.0))
    pan=list(modal.get("_ac_pan",[0.0,0.0]))
    tool=modal.get("_ac_tool","move")
    cw=int(proj.get("canvas_w",96)); ch=int(proj.get("canvas_h",96))
    modal["_ac_tooltip"]=""

    # ── Input ──────────────────────────────────────────────────────────────
    keys=pygame.key.get_pressed(); mods=pygame.key.get_mods()
    _kp=modal.setdefault("_ac_kprev",{})
    def _edge(kc):
        n=bool(keys[kc]); w=_kp.get(kc,False); _kp[kc]=n; return n and not w
    _mb=pygame.mouse.get_pressed()
    _lmb,_mmb,_rmb=_mb[0],_mb[1],_mb[2]
    lc=bool(left_click_this_frame)
    rclicked=_rmb and not modal.get("_ac_prev_rmb",False)
    mclicked=_mmb and not modal.get("_ac_prev_mmb",False)
    lmb_held=_lmb; space_held=keys[pygame.K_SPACE]
    _lmb_released=(not _lmb) and bool(modal.get("_ac_prev_lmb"))
    modal["_ac_prev_lmb"]=_lmb; modal["_ac_prev_rmb"]=_rmb; modal["_ac_prev_mmb"]=_mmb
    focus=modal.get("focus")
    # Pixel Lock: the moment any transform drag/slider ends, re-bake locked
    # raster layers so their pixels are stamped once and never drift again.
    if _lmb_released:
        try:_ac_pixel_lock_autobake(proj,_ac_sel_layer(proj))
        except Exception:pass

    # ── Layout ─────────────────────────────────────────────────────────────
    TW=52; LW=230; PW=260; HH=40; SH=26
    header_r=pygame.Rect(0,0,WIDTH,HH)
    toolbar_r=pygame.Rect(0,HH,TW,HEIGHT-HH-SH)
    canvas_area=pygame.Rect(TW,HH,WIDTH-TW-LW-PW,HEIGHT-HH-SH)
    layer_r=pygame.Rect(canvas_area.right,HH,LW,canvas_area.height)
    prop_r=pygame.Rect(layer_r.right,HH,PW,canvas_area.height)
    status_r=pygame.Rect(0,HEIGHT-SH,WIDTH,SH)
    modal["_ac_canvas_area"]=canvas_area
    modal["_ac_layer_panel_rect"]=layer_r.copy()
    modal["_ac_props_panel_rect"]=prop_r.copy()

    # ── Keyboard shortcuts ─────────────────────────────────────────────────
    if focus is None:
        if not (mods&(pygame.KMOD_CTRL|pygame.KMOD_META)):
            for tkey,skey,_,_,_ in AC_TOOLS:
                kc=getattr(pygame,f"K_{skey.lower()}",None)
                if kc and _edge(kc): modal["_ac_tool"]=tkey; tool=tkey; break
        if _edge(pygame.K_z) and (mods&pygame.KMOD_CTRL): _ac_undo()
        elif _edge(pygame.K_y) and (mods&pygame.KMOD_CTRL): _ac_redo()
        elif _edge(pygame.K_a) and (mods&pygame.KMOD_CTRL):
            _m=pygame.mask.Mask((cw,ch),True);modal["_ac_selection_mask"]=_m
        if _edge(pygame.K_EQUALS) or _edge(pygame.K_PLUS): modal["_ac_zoom"]=round(min(64.0,zoom*1.5),2); zoom=float(modal["_ac_zoom"])
        if _edge(pygame.K_MINUS): modal["_ac_zoom"]=round(max(0.05,zoom/1.5),2); zoom=float(modal["_ac_zoom"])
        if _edge(pygame.K_0):
            fit=min((canvas_area.width-40)/max(1,cw),(canvas_area.height-40)/max(1,ch))
            modal["_ac_zoom"]=round(max(0.05,min(64.0,fit)),2); pan=[0.0,0.0]; modal["_ac_pan"]=pan; zoom=float(modal["_ac_zoom"])
        if (_edge(pygame.K_DELETE) or _edge(pygame.K_BACKSPACE)) and not canvas_area.collidepoint(mouse_pos):
            sel=modal.get("_ac_sel_layer")
            if sel: _ac_push_undo(); _ac_remove_layer(proj["layers"],sel); modal["_ac_sel_layer"]=None
        if _edge(pygame.K_d) and (mods&pygame.KMOD_CTRL):
            sl=_ac_sel_layer(proj)
            if sl: _ac_dup_layer(proj,sl)
        if _edge(pygame.K_ESCAPE):
            ctx=modal.get("_ac_ctx_menu")
            if modal.get("_ac_selection_mask") is not None:
                modal["_ac_selection_mask"]=None;modal["_ac_select_drag"]=None;modal["_ac_lasso_points"]=[]
            elif ctx: modal["_ac_ctx_menu"]=None
            elif modal.get("_ac_export_dd"): modal["_ac_export_dd"]=False
            elif tool=="crop" and modal.get("_ac_crop_rect"): modal["_ac_crop_rect"]=None
            else: _ac_close(); return

    # Re-read zoom
    zoom=float(modal.get("_ac_zoom",4.0))

    # ═══════════════════════════════════════════════════════════════════════
    # HEADER
    # ═══════════════════════════════════════════════════════════════════════
    ui_draw_rect(screen,FIELD_FOCUS,header_r)
    pygame.draw.line(screen,DIVIDER,(0,HH-1),(WIDTH,HH-1))
    _hx=8

    def _btn(x,w,label,icon,tip,action,danger=False):
        nonlocal lc
        global left_click_this_frame
        r=pygame.Rect(x,8,w,26); hov=r.collidepoint(mouse_pos)
        bg=(80,30,34) if danger and hov else (FIELD_FOCUS if hov else FIELD_BG)
        brd=DANGER if danger else (ACCENT if hov else PANEL_BORDER)
        ui_draw_rect(screen,bg,r,border_radius=6); ui_draw_rect(screen,brd,r,width=1,border_radius=6)
        ic=get_icon_fs(icon,14,(255,100,100) if danger and hov else (ACCENT if hov else TEXT_MAIN))
        lx=r.x+6
        if ic: screen.blit(ic,(lx,r.centery-ic.get_height()//2)); lx+=ic.get_width()+4
        if label: screen.blit(font_tiny.render(label,True,TEXT_MAIN),(lx,r.centery-5))
        if hov: modal["_ac_tooltip"]=tip
        if hov and lc: action(); lc=False; left_click_this_frame=False
        return r.right

    def _new_proj():
        modal["_ac_project"]=_ac_project_default(); modal["_ac_sel_layer"]=None
        modal["_ac_undo"]=[]; modal["_ac_redo"]=[]; modal["_ac_zoom"]=4.0; modal["_ac_pan"]=[0.0,0.0];modal["_ac_selection_mask"]=None;_AC_RASTER_CACHE.clear()
    _hx=_btn(_hx,58,"New","plus","New project",_new_proj)
    _hx=_btn(_hx,58,"Save","save","Save project",lambda:_ac_save_project(proj))
    _hx=_btn(_hx,68,"Export","export","Export PNG through the Asset Library",lambda:_ac_open_export_library(proj))
    # Open saved project
    _open_r=pygame.Rect(_hx,8,60,26); _open_hov=_open_r.collidepoint(mouse_pos)
    ui_draw_rect(screen,FIELD_FOCUS if _open_hov else FIELD_BG,_open_r,border_radius=6)
    ui_draw_rect(screen,ACCENT if _open_hov else PANEL_BORDER,_open_r,width=1,border_radius=6)
    _ic_o=get_icon_fs("folder",14,ACCENT if _open_hov else TEXT_MAIN); _olx=_open_r.x+6
    if _ic_o: screen.blit(_ic_o,(_olx,_open_r.centery-_ic_o.get_height()//2)); _olx+=_ic_o.get_width()+4
    screen.blit(font_tiny.render("Open",True,TEXT_MAIN),(_olx,_open_r.centery-5))
    if _open_hov: modal["_ac_tooltip"]="Open a saved project"
    if _open_hov and lc:
        if not ASSET_CREATIONS_LOADED: load_asset_creations()
        if ASSET_CREATIONS: modal["_ac_open_dd"]=not modal.get("_ac_open_dd",False)
        else: push_toast("No saved projects yet","info")
        lc=False; left_click_this_frame=False
    _hx=_open_r.right+6
    pygame.draw.line(screen,DIVIDER,(_hx,8),(_hx,32),1); _hx+=8

    # Project name
    _nr=pygame.Rect(_hx,8,140,26); nf=(focus=="_ac_proj_name")
    draw_text_field(_nr,proj.get("name",""),"Project Name",nf)
    if _nr.collidepoint(mouse_pos) and lc:
        modal["focus"]="_ac_proj_name"; _text_editor_begin_mouse("_ac_proj_name",_nr,mouse_pos[0],pygame.key.get_mods())
        lc=False; left_click_this_frame=False
    _hx=_nr.right+12

    # Canvas size + Fit to Content
    _ic_sz=get_icon_fs("grid",14,TEXT_DIM)
    if _ic_sz: screen.blit(_ic_sz,(_hx,13)); _hx+=18
    screen.blit(font_tiny.render(f"{cw}×{ch}",True,TEXT_DIM),(_hx,14)); _hx+=50
    _hx=_btn(_hx,68,"Fit All","maximize","Resize canvas to fit all layers",lambda:_ac_fit_to_content(proj))
    pygame.draw.line(screen,DIVIDER,(_hx,8),(_hx,32),1); _hx+=10

    # Zoom controls
    _hx=_btn(_hx,28,"","minus","Zoom out [− / scroll down]",lambda:(modal.__setitem__("_ac_zoom",round(max(0.05,float(modal.get("_ac_zoom",4.0))/1.5),2)),))
    _zrr=pygame.Rect(_hx,8,52,26)
    ui_draw_rect(screen,FIELD_BG,_zrr,border_radius=5); ui_draw_rect(screen,PANEL_BORDER,_zrr,width=1,border_radius=5)
    screen.blit(font_tiny.render(f"{zoom:.1f}×",True,ACCENT),(_zrr.centerx-12,_zrr.centery-5))
    if _zrr.collidepoint(mouse_pos): modal["_ac_tooltip"]="Scroll wheel to zoom · 0 = fit view"
    _hx=_zrr.right
    _hx=_btn(_hx,28,"","plus","Zoom in [+ / scroll up]",lambda:(modal.__setitem__("_ac_zoom",round(min(64.0,float(modal.get("_ac_zoom",4.0))*1.5),2)),))
    _hx=_btn(_hx,42,"","maximize","Fit canvas to view [0]",lambda:(modal.__setitem__("_ac_zoom",round(max(0.05,min(64.0,min((canvas_area.width-40)/max(1,cw),(canvas_area.height-40)/max(1,ch)))),2)),modal.__setitem__("_ac_pan",[0.0,0.0])))
    _hx+=6

    # View toggles
    for _lbl,_key,_icon in [("Grid","_ac_show_grid","grid"),("Rulers","_ac_show_rulers","list"),("Snap","_ac_snap_pixel","snap")]:
        _on=bool(modal.get(_key,True))
        _tr=pygame.Rect(_hx,8,54,26); _thov=_tr.collidepoint(mouse_pos)
        ui_draw_rect(screen,ACCENT if _on else (FIELD_FOCUS if _thov else FIELD_BG),_tr,border_radius=5)
        ui_draw_rect(screen,ACCENT if _on else (ACCENT if _thov else PANEL_BORDER),_tr,width=1,border_radius=5)
        ic=get_icon_fs(_icon,12,(10,10,14) if _on else (ACCENT if _thov else TEXT_MAIN)); lx=_tr.x+6
        if ic: screen.blit(ic,(lx,_tr.centery-ic.get_height()//2)); lx+=ic.get_width()+3
        screen.blit(font_tiny.render(_lbl,True,(10,10,14) if _on else TEXT_MAIN),(lx,_tr.centery-5))
        if _thov: modal["_ac_tooltip"]=f"Toggle {_lbl}"
        if _thov and lc: modal[_key]=not _on; lc=False; left_click_this_frame=False
        _hx+=60

    # Close
    _hx=_btn(WIDTH-36,28,"","close","Close [Esc]",lambda:_ac_close(),danger=True)

    # ═══════════════════════════════════════════════════════════════════════
    # TOOLBAR
    # ═══════════════════════════════════════════════════════════════════════
    ui_draw_rect(screen,(26,24,38),toolbar_r)
    pygame.draw.line(screen,DIVIDER,(TW-1,HH),(TW-1,HEIGHT-SH))
    _ty=HH+8
    for tkey,skey,icon,label,tip in AC_TOOLS:
        _tr=pygame.Rect(6,_ty,40,34); _act=(tool==tkey); _thov=_tr.collidepoint(mouse_pos)
        bg=ACCENT if _act else (FIELD_FOCUS if _thov else (32,30,44))
        ui_draw_rect(screen,bg,_tr,border_radius=7)
        ui_draw_rect(screen,ACCENT if _act else (ACCENT if _thov else PANEL_BORDER),_tr,width=1,border_radius=7)
        ic=get_icon_fs(icon,18,(10,10,14) if _act else (ACCENT if _thov else TEXT_MAIN))
        if ic: screen.blit(ic,(_tr.centerx-ic.get_width()//2,_tr.centery-ic.get_height()//2-2))
        sk=font_tiny.render(skey,True,(10,10,14) if _act else TEXT_DIM)
        screen.blit(sk,(_tr.centerx-sk.get_width()//2,_tr.bottom-sk.get_height()-2))
        if _thov: modal["_ac_tooltip"]=tip
        if _thov and lc: modal["_ac_tool"]=tkey; tool=tkey; lc=False; left_click_this_frame=False
        _ty+=38
    # ═══════════════════════════════════════════════════════════════════════
    # CANVAS + ZOOM + PAN
    # ═══════════════════════════════════════════════════════════════════════
    # PAN
    want_pan=(tool=="hand" and lmb_held) or (space_held and lmb_held) or _mmb
    if want_pan and not modal.get("_ac_panning"):
        modal["_ac_panning"]=True; modal["_ac_pan_anchor"]=list(mouse_pos); modal["_ac_pan_base"]=list(pan)
    if want_pan and modal.get("_ac_panning"):
        a=modal.get("_ac_pan_anchor",mouse_pos); b=modal.get("_ac_pan_base",[0.0,0.0])
        pan[0]=b[0]+(mouse_pos[0]-a[0]); pan[1]=b[1]+(mouse_pos[1]-a[1]); modal["_ac_pan"]=pan
    if not want_pan: modal["_ac_panning"]=False; modal["_ac_pan_anchor"]=None

    # ZOOM via scroll wheel — handle directly here as backup to _ac_handle_wheel
    # (pygame.mouse.get_pressed with 5 buttons returns scroll as buttons 3/4 on some systems)
    # The main event loop calls _ac_handle_wheel which sets modal["_ac_zoom"]
    zoom=float(modal.get("_ac_zoom",4.0))

    # Cursor
    if space_held or tool=="hand":
        try: pygame.mouse.set_cursor(pygame.SYSTEM_CURSOR_HAND)
        except: pass
    elif canvas_area.collidepoint(mouse_pos):
        try: pygame.mouse.set_cursor(pygame.SYSTEM_CURSOR_CROSSHAIR)
        except: pass
    else:
        try: pygame.mouse.set_cursor(pygame.SYSTEM_CURSOR_ARROW)
        except: pass

    _cc=screen.get_clip(); screen.set_clip(canvas_area)
    _ac_draw_checkerboard(screen,canvas_area)

    tl_x,tl_y=_ac_c2s(0,0,canvas_area,zoom,pan,cw,ch)
    br_x,br_y=_ac_c2s(cw,ch,canvas_area,zoom,pan,cw,ch)
    csr=pygame.Rect(tl_x,tl_y,br_x-tl_x,br_y-tl_y)

    # ── Grid: drawn on a real per-pixel-alpha overlay so transparency actually applies ──
    # (the main `screen` surface has no per-pixel alpha, so alpha colors used to render fully opaque)
    if modal.get("_ac_show_grid"):
        _grid_ovl=pygame.Surface((canvas_area.w,canvas_area.h),pygame.SRCALPHA)
        _ox,_oy=canvas_area.x,canvas_area.y
        if zoom>=3.0:
            for gx in range(0,cw+1,1):
                sx,_=_ac_c2s(gx,0,canvas_area,zoom,pan,cw,ch)
                if tl_x<=sx<=br_x:
                    if gx%16==0: col=(255,255,255,20)
                    elif gx%4==0 and zoom>=6: col=(255,255,255,9)
                    else: continue
                    sy_t=max(canvas_area.top,tl_y); sy_b=min(canvas_area.bottom,br_y)
                    if sy_t<sy_b: pygame.draw.line(_grid_ovl,col,(sx-_ox,sy_t-_oy),(sx-_ox,sy_b-_oy))
            for gy in range(0,ch+1,1):
                _,sy=_ac_c2s(0,gy,canvas_area,zoom,pan,cw,ch)
                if tl_y<=sy<=br_y:
                    if gy%16==0: col=(255,255,255,20)
                    elif gy%4==0 and zoom>=6: col=(255,255,255,9)
                    else: continue
                    sx_l=max(canvas_area.left,tl_x); sx_r=min(canvas_area.right,br_x)
                    if sx_l<sx_r: pygame.draw.line(_grid_ovl,col,(sx_l-_ox,sy-_oy),(sx_r-_ox,sy-_oy))
        else:
            for gx in range(0,cw+1,16):
                sx,_=_ac_c2s(gx,0,canvas_area,zoom,pan,cw,ch)
                if tl_x<=sx<=br_x:
                    sy_t=max(canvas_area.top,tl_y); sy_b=min(canvas_area.bottom,br_y)
                    if sy_t<sy_b: pygame.draw.line(_grid_ovl,(255,255,255,12),(sx-_ox,sy_t-_oy),(sx-_ox,sy_b-_oy))
            for gy in range(0,ch+1,16):
                _,sy=_ac_c2s(0,gy,canvas_area,zoom,pan,cw,ch)
                if tl_y<=sy<=br_y:
                    sx_l=max(canvas_area.left,tl_x); sx_r=min(canvas_area.right,br_x)
                    if sx_l<sx_r: pygame.draw.line(_grid_ovl,(255,255,255,12),(sx_l-_ox,sy-_oy),(sx_r-_ox,sy-_oy))
        screen.blit(_grid_ovl,canvas_area.topleft)

    ui_draw_rect(screen,(80,80,100),csr,width=1)

    # Composite
    composite=_ac_composite_surface(proj,scale=1)
    if composite:
        sw_d=max(1,int(cw*zoom)); sh_d=max(1,int(ch*zoom))
        if sw_d>1 and sh_d>1:
            try: scaled=pygame.transform.scale(composite,(sw_d,sh_d)) if zoom>=1.5 else pygame.transform.smoothscale(composite,(sw_d,sh_d))
            except: scaled=pygame.transform.scale(composite,(sw_d,sh_d))
            screen.blit(scaled,(tl_x,tl_y))

    # Pixel painting, erasing, rectangular/magic/lasso selection.  This runs
    # after the composite so its selection marquee and option strip stay crisp.
    lc=_ac_paint_select_canvas(proj,tool,canvas_area,zoom,pan,mouse_pos,lc,lmb_held)

    # Gizmo
    sel_layer=_ac_sel_layer(proj)
    if sel_layer and tool=="move" and canvas_area.collidepoint(mouse_pos):
        _ac_draw_gizmo(sel_layer,proj,csr,zoom,mouse_pos,lc,lmb_held,modal)

    # Crop
    if tool=="crop": _ac_draw_crop(canvas_area,zoom,pan,cw,ch,mouse_pos,lc,lmb_held,proj)

    # Rulers
    if modal.get("_ac_show_rulers"): _ac_draw_rulers(canvas_area,zoom,pan,cw,ch)

    # Crosshair
    if canvas_area.collidepoint(mouse_pos) and focus is None:
        pygame.draw.line(screen,(255,255,255,20),(mouse_pos[0],canvas_area.top),(mouse_pos[0],canvas_area.bottom),1)
        pygame.draw.line(screen,(255,255,255,20),(canvas_area.left,mouse_pos[1]),(canvas_area.right,mouse_pos[1]),1)

    screen.set_clip(_cc)

    # ═══════════════════════════════════════════════════════════════════════
    # LAYER PANEL
    # ═══════════════════════════════════════════════════════════════════════
    ui_draw_rect(screen,PANEL_BG_ALT,layer_r)
    pygame.draw.line(screen,DIVIDER,(layer_r.right-1,HH),(layer_r.right-1,HEIGHT-SH))
    _ac_draw_layers(proj,mouse_pos,lc,rclicked,focus,layer_r,lmb_held)

    # ═══════════════════════════════════════════════════════════════════════
    # PROPERTIES PANEL
    # ═══════════════════════════════════════════════════════════════════════
    ui_draw_rect(screen,PANEL_BG_ALT,prop_r)
    pygame.draw.line(screen,DIVIDER,(prop_r.x,HH),(prop_r.x,HEIGHT-SH))
    _pt_y=HH+6
    for _i,(_tid,_tic,_tlbl) in enumerate([("properties","info","Properties"),("effects","bolt","FX"),("history","restore","History")]):
        _ptw=(PW-12)//3; _ptr=pygame.Rect(prop_r.x+4+_i*(_ptw+2),_pt_y,_ptw,24)
        _act=(modal.get("_ac_right_panel")==_tid); _phov=_ptr.collidepoint(mouse_pos)
        ui_draw_rect(screen,ACCENT if _act else (FIELD_FOCUS if _phov else FIELD_BG),_ptr,border_radius=5)
        ui_draw_rect(screen,ACCENT if _act else PANEL_BORDER,_ptr,width=1,border_radius=5)
        ic=get_icon_fs(_tic,12,(10,10,14) if _act else (ACCENT if _phov else TEXT_DIM))
        lx=_ptr.centerx-(6+font_tiny.size(_tlbl)[0])//2
        if ic: screen.blit(ic,(lx,_ptr.centery-ic.get_height()//2)); lx+=ic.get_width()+4
        screen.blit(font_tiny.render(_tlbl,True,(10,10,14) if _act else TEXT_MAIN),(lx,_ptr.centery-5))
        if _phov and lc: modal["_ac_right_panel"]=_tid; lc=False; left_click_this_frame=False
    _rp=pygame.Rect(prop_r.x,_pt_y+30,PW,prop_r.bottom-_pt_y-30)
    if modal.get("_ac_right_panel")=="properties": _ac_draw_props(proj,mouse_pos,lc,focus,_rp,lmb_held)
    elif modal.get("_ac_right_panel")=="effects": _ac_draw_fx(proj,mouse_pos,lc,focus,_rp,lmb_held)
    elif modal.get("_ac_right_panel")=="history": _ac_draw_hist(mouse_pos,lc,_rp)

    # ── Context menu ───────────────────────────────────────────────────────
    ctx=modal.get("_ac_ctx_menu")
    if ctx:
        _items=ctx.get("items",[]); _mw=200; _mh=len(_items)*28+8
        _mx=min(ctx.get("x",100),WIDTH-_mw-10); _my=min(ctx.get("y",100),HEIGHT-_mh-10)
        _mr=pygame.Rect(_mx,_my,_mw,_mh)
        ui_draw_rect(screen,(26,24,38),_mr,border_radius=8); ui_draw_rect(screen,ACCENT,_mr,width=1,border_radius=8)
        for _ci,item in enumerate(_items):
            _clbl=item[0]; _cic=item[1] if len(item)>1 and isinstance(item[1],str) else None; _cact=item[-1] if callable(item[-1]) else None
            if _clbl=="---": pygame.draw.line(screen,DIVIDER,(_mx+8,_my+6+_ci*28+14),(_mx+_mw-8,_my+6+_ci*28+14)); continue
            _cr=pygame.Rect(_mx+4,_my+4+_ci*28,_mw-8,24); _chov=_cr.collidepoint(mouse_pos)
            ui_draw_rect(screen,(46,42,66) if _chov else FIELD_BG,_cr,border_radius=4)
            lx=_cr.x+8
            if _cic:
                _icc=get_icon_fs(_cic,13,(255,255,255) if _chov else TEXT_MAIN)
                if _icc: screen.blit(_icc,(lx,_cr.centery-_icc.get_height()//2)); lx+=_icc.get_width()+6
            screen.blit(font_tiny.render(_clbl,True,(255,255,255) if _chov else TEXT_MAIN),(lx,_cr.y+5))
            if _chov and lc and _cact: _cact(); modal["_ac_ctx_menu"]=None; lc=False; left_click_this_frame=False; break
        if lc and not _mr.collidepoint(mouse_pos): modal["_ac_ctx_menu"]=None

    # ── Open project browser (grid) ──────────────────────────────────────────
    if modal.get("_ac_open_dd"):
        if not ASSET_CREATIONS_LOADED: load_asset_creations()
        _names=sorted(ASSET_CREATIONS.keys())
        _ov=pygame.Surface((WIDTH,HEIGHT),pygame.SRCALPHA); _ov.fill((0,0,0,150)); screen.blit(_ov,(0,0))
        _gw,_gh=min(760,WIDTH-80),min(560,HEIGHT-120)
        _gr=pygame.Rect((WIDTH-_gw)//2,(HEIGHT-_gh)//2,_gw,_gh)
        ui_draw_rect(screen,(26,24,38),_gr,border_radius=10)
        ui_draw_rect(screen,ACCENT,_gr,width=1,border_radius=10)
        screen.blit(font_sm.render(f"SAVED PROJECTS ({len(_names)})",True,ACCENT),(_gr.x+16,_gr.y+14))
        _clr=pygame.Rect(_gr.right-32,_gr.y+8,24,24); _clh=_clr.collidepoint(mouse_pos)
        ui_draw_rect(screen,(80,30,34) if _clh else FIELD_BG,_clr,border_radius=6)
        _cic=get_icon_fs("close",13,(255,255,255) if _clh else TEXT_MAIN)
        if _cic: screen.blit(_cic,(_clr.centerx-_cic.get_width()//2,_clr.centery-_cic.get_height()//2))
        if _clh and lc: modal["_ac_open_dd"]=False; lc=False; left_click_this_frame=False
        _cw,_ch2=150,148; _gap=14
        _grid_top=_gr.y+48
        _grid_area=pygame.Rect(_gr.x+16,_grid_top,_gw-32,_gr.bottom-_grid_top-16)
        _cols=max(1,(_grid_area.width+_gap)//(_cw+_gap))
        if _names:
            _oc2=screen.get_clip(); screen.set_clip(_grid_area)
            _scroll=float(modal.get("_ac_proj_grid_scroll",0.0))
            _rows=(len(_names)+_cols-1)//_cols
            _total_h=_rows*(_ch2+_gap)
            _scroll=max(0.0,min(max(0.0,_total_h-_grid_area.height),_scroll))
            for _i,_pname in enumerate(_names):
                _col=_i%_cols; _row=_i//_cols
                _cx=_grid_area.x+_col*(_cw+_gap); _cy=_grid_area.y+_row*(_ch2+_gap)-_scroll
                if _cy+_ch2<_grid_area.y or _cy>_grid_area.bottom: continue
                _card=pygame.Rect(_cx,_cy,_cw,_ch2)
                _chov=_card.collidepoint(mouse_pos) and _grid_area.collidepoint(mouse_pos)
                ui_draw_rect(screen,(46,42,66) if _chov else FIELD_FOCUS,_card,border_radius=8)
                ui_draw_rect(screen,ACCENT if _chov else PANEL_BORDER,_card,width=1,border_radius=8)
                _pdata=ASSET_CREATIONS[_pname]
                _thumb=pygame.Rect(_card.x+8,_card.y+8,_cw-16,_ch2-52)
                _ac_draw_checkerboard(screen,_thumb,tile=6)
                try:
                    _comp=_ac_composite_surface(_pdata,scale=1)
                    if _comp and _comp.get_width()>0 and _comp.get_height()>0:
                        _sc=min(_thumb.width/_comp.get_width(),_thumb.height/_comp.get_height())
                        _tw,_th=max(1,int(_comp.get_width()*_sc)),max(1,int(_comp.get_height()*_sc))
                        _scaled=pygame.transform.scale(_comp,(_tw,_th))
                        screen.blit(_scaled,(_thumb.centerx-_tw//2,_thumb.centery-_th//2))
                except Exception: pass
                ui_draw_rect(screen,PANEL_BORDER,_thumb,width=1)
                screen.blit(font_tiny.render(_pname[:20],True,TEXT_MAIN),(_card.x+8,_card.bottom-40))
                _lyct=len(_ac_all_layers_flat(_pdata.get("layers",[])))
                screen.blit(font_tiny.render(f"{_lyct} layer{'s' if _lyct!=1 else ''}",True,TEXT_DIM),(_card.x+8,_card.bottom-24))
                _delr=pygame.Rect(_card.right-24,_card.y+6,18,18); _delh=_delr.collidepoint(mouse_pos)
                if _chov or _delh:
                    ui_draw_rect(screen,(80,30,34) if _delh else (50,24,28),_delr,border_radius=4)
                    _dic=get_icon_fs("delete",11,(255,255,255) if _delh else DANGER)
                    if _dic: screen.blit(_dic,(_delr.centerx-_dic.get_width()//2,_delr.centery-_dic.get_height()//2))
                if _delh and lc:
                    del ASSET_CREATIONS[_pname]; save_asset_creations()
                    push_toast(f"Deleted: {_pname}","info",1.8)
                    lc=False; left_click_this_frame=False; break
                elif _chov and lc:
                    modal["_ac_project"]=copy.deepcopy(_pdata)
                    modal["_ac_sel_layer"]=None; modal["_ac_undo"]=[]; modal["_ac_redo"]=[]
                    modal["_ac_open_dd"]=False
                    push_toast(f"Opened: {_pname}","success",1.5)
                    lc=False; left_click_this_frame=False; break
            modal["_ac_proj_grid_scroll"]=_scroll
            screen.set_clip(_oc2)
        else:
            screen.blit(font_tiny.render("No saved projects yet",True,TEXT_DIM),(_grid_area.x+4,_grid_area.y+4))
        if lc and not _gr.collidepoint(mouse_pos): modal["_ac_open_dd"]=False

    # ---- Export folder picker: choose WHERE in the asset library it lands ----
    if modal.get("_ac_export_dd"):
        _folders=[""]
        _seen={""}
        try:
            for _fd in list_sprite_folders():
                if _fd and _fd not in _seen: _folders.append(_fd); _seen.add(_fd)
            for _rel in list_sprite_assets():
                _fd=sprite_folder_of(_rel)
                if _fd and _fd not in _seen: _folders.append(_fd); _seen.add(_fd)
        except Exception:
            pass
        _folders[1:]=sorted(_folders[1:])
        _ov=pygame.Surface((WIDTH,HEIGHT),pygame.SRCALPHA); _ov.fill((0,0,0,150)); screen.blit(_ov,(0,0))
        _gw,_gh=400,min(64+30*len(_folders)+16,HEIGHT-140)
        _gr=pygame.Rect((WIDTH-_gw)//2,(HEIGHT-_gh)//2,_gw,_gh)
        ui_draw_rect(screen,(26,24,38),_gr,border_radius=10)
        ui_draw_rect(screen,ACCENT,_gr,width=1,border_radius=10)
        screen.blit(font_sm.render("EXPORT PNG TO...",True,ACCENT),(_gr.x+16,_gr.y+14))
        _clr=pygame.Rect(_gr.right-32,_gr.y+8,24,24); _clh=_clr.collidepoint(mouse_pos)
        ui_draw_rect(screen,(80,30,34) if _clh else FIELD_BG,_clr,border_radius=6)
        _cic=get_icon_fs("close",13,(255,255,255) if _clh else TEXT_MAIN)
        if _cic: screen.blit(_cic,(_clr.centerx-_cic.get_width()//2,_clr.centery-_cic.get_height()//2))
        if _clh and lc: modal["_ac_export_dd"]=False; lc=False; left_click_this_frame=False
        _lst=pygame.Rect(_gr.x+12,_gr.y+44,_gr.width-24,_gr.bottom-(_gr.y+44)-12)
        _oc2=screen.get_clip(); screen.set_clip(_lst)
        _row_h=26; _total_h=_row_h*len(_folders)
        _mx_sc=max(0.0,float(_total_h-_lst.height))
        if _lst.collidepoint(mouse_pos) and _mx_sc>0:
            _scr=float(modal.get("_ac_exp_dd_scroll",0.0))
            modal["_ac_exp_dd_scroll"]=max(0.0,min(_mx_sc,_scr))
        _scr=max(0.0,min(_mx_sc,float(modal.get("_ac_exp_dd_scroll",0.0))))
        _ry=_lst.y-_scr
        for _fd in _folders:
            _rr=pygame.Rect(_lst.x,_ry,_lst.width,_row_h-3); _ry+=_row_h
            if _rr.bottom<_lst.y or _rr.y>_lst.bottom: continue
            _rh=_rr.collidepoint(mouse_pos)
            ui_draw_rect(screen,(46,42,66) if _rh else FIELD_FOCUS,_rr,border_radius=6)
            ui_draw_rect(screen,ACCENT if _rh else PANEL_BORDER,_rr,width=1,border_radius=6)
            _fic=get_icon_fs("folder",13,ACCENT if _rh else TEXT_DIM)
            if _fic: screen.blit(_fic,(_rr.x+8,_rr.centery-_fic.get_height()//2))
            _flbl=("sprites/  (root)" if not _fd else f"sprites/{_fd}/")
            screen.blit(font_sm.render(_flbl,True,TEXT_MAIN),(_rr.x+28,_rr.centery-7))
            if _rh and lc:
                modal["_ac_export_dd"]=False
                _ac_export_png(proj,_fd)
                lc=False; left_click_this_frame=False
        screen.set_clip(_oc2)
        if lc and not _gr.collidepoint(mouse_pos): modal["_ac_export_dd"]=False

    # ── Status bar ─────────────────────────────────────────────────────────
    ui_draw_rect(screen,PANEL_BG_ALT,status_r)
    pygame.draw.line(screen,DIVIDER,(0,status_r.y),(WIDTH,status_r.y))
    if canvas_area.collidepoint(mouse_pos):
        ccx,ccy=_ac_s2c(mouse_pos[0],mouse_pos[1],canvas_area,zoom,pan,cw,ch); ptxt=f"X:{ccx:.1f}  Y:{ccy:.1f}"
    else: ptxt=""
    _si=[tool.upper(),ptxt,f"{cw}×{ch}",f"{zoom:.1f}×",f"{len(_ac_all_layers_flat(proj.get('layers',[])))} layers"]
    screen.blit(font_tiny.render("  │  ".join(s for s in _si if s),True,TEXT_MAIN),(status_r.x+8,status_r.y+5))
    screen.blit(font_tiny.render(f"Undo:{len(modal.get('_ac_undo',[]))}  Redo:{len(modal.get('_ac_redo',[]))}",True,TEXT_DIM),(status_r.right-120,status_r.y+5))

    if modal.get("_ac_tooltip"): _ac_tooltip(modal["_ac_tooltip"],mouse_pos)

# ── Gizmo ─────────────────────────────────────────────────────────────────────
# Sign of (scale_x, scale_y) change per unit of (mouse_dx, mouse_dy) for each handle.
# Layers render centered on their (x,y) anchor, so "away from center" always means
# "bigger" — the sign flips depending on which side of the box the handle sits on.
AC_HANDLE_SIGN={
    "tl":(-1,-1),"tr":(1,-1),"bl":(-1,1),"br":(1,1),
    "t":(0,-1),"b":(0,1),"l":(-1,0),"r":(1,0),
}
AC_HANDLE_CURSOR={
    "tl":"SYSTEM_CURSOR_SIZENWSE","br":"SYSTEM_CURSOR_SIZENWSE",
    "tr":"SYSTEM_CURSOR_SIZENESW","bl":"SYSTEM_CURSOR_SIZENESW",
    "t":"SYSTEM_CURSOR_SIZENS","b":"SYSTEM_CURSOR_SIZENS",
    "l":"SYSTEM_CURSOR_SIZEWE","r":"SYSTEM_CURSOR_SIZEWE",
}

def _ac_draw_gizmo(layer,proj,csr,zoom,mouse_pos,lc,lmb_held,modal):
    b=_ac_layer_bounds(layer,proj)
    if b is None: return
    sx=csr.x+int(b.x*zoom); sy=csr.y+int(b.y*zoom); sw=max(4,int(b.width*zoom)); sh=max(4,int(b.height*zoom))
    giz=pygame.Rect(sx,sy,sw,sh)
    # soft glow outline, then crisp border
    ui_draw_rect(screen,ACCENT,giz.inflate(2,2),width=1,border_radius=2)
    ui_draw_rect(screen,ACCENT,giz,width=2)
    ccx,ccy=sx+sw//2,sy+sh//2

    # corner (uniform-drag) + edge (single-axis) handles
    CH=8; EH_LEN=16; EH_TH=6
    corner_pts={"tl":(sx,sy),"tr":(sx+sw,sy),"bl":(sx,sy+sh),"br":(sx+sw,sy+sh)}
    edge_pts={"t":(ccx,sy),"b":(ccx,sy+sh),"l":(sx,ccy),"r":(sx+sw,ccy)}
    handle_rects={}
    for cn,(cx,cy) in corner_pts.items():
        handle_rects[cn]=pygame.Rect(cx-CH,cy-CH,CH*2,CH*2)
    for cn,(cx,cy) in edge_pts.items():
        if cn in ("t","b"): handle_rects[cn]=pygame.Rect(cx-EH_LEN//2,cy-EH_TH//2,EH_LEN,EH_TH)
        else: handle_rects[cn]=pygame.Rect(cx-EH_TH//2,cy-EH_LEN//2,EH_TH,EH_LEN)

    hovered_handle=None
    for cn,hr in handle_rects.items():
        if hr.collidepoint(mouse_pos): hovered_handle=cn
    for cn,hr in handle_rects.items():
        hov=(cn==hovered_handle)
        is_corner=cn in corner_pts
        col=(255,255,255) if hov else ACCENT
        if is_corner:
            ui_draw_rect(screen,col,hr,border_radius=3)
            ui_draw_rect(screen,(16,16,22),hr,width=1,border_radius=3)
        else:
            ui_draw_rect(screen,col,hr,border_radius=2)
            ui_draw_rect(screen,(16,16,22),hr,width=1,border_radius=2)
        if hov and lmb_held and not modal.get("_ac_drag"):
            _ac_push_undo()
            modal["_ac_drag"]=("scale",cn,mouse_pos,layer.get("scale_x",1.0),layer.get("scale_y",1.0))

    pygame.draw.line(screen,ACCENT,(ccx-10,ccy),(ccx+10,ccy),1)
    pygame.draw.line(screen,ACCENT,(ccx,ccy-10),(ccx,ccy+10),1)
    rr=pygame.Rect(ccx-6,sy-26,12,12); rhov=rr.collidepoint(mouse_pos)
    pygame.draw.line(screen,ACCENT,(ccx,sy),(ccx,sy-14),1)
    pygame.draw.circle(screen,GOOD if rhov else ACCENT,(ccx,sy-20),6)
    pygame.draw.circle(screen,(16,16,22),(ccx,sy-20),6,width=1)
    if rhov and lmb_held and not modal.get("_ac_drag"):
        _ac_push_undo(); modal["_ac_drag"]=("rotate",mouse_pos,layer.get("rotation",0.0))

    # resize cursor when hovering a handle
    if hovered_handle:
        try: pygame.mouse.set_cursor(getattr(pygame,AC_HANDLE_CURSOR[hovered_handle]))
        except Exception: pass
    elif rhov:
        try: pygame.mouse.set_cursor(pygame.SYSTEM_CURSOR_HAND)
        except Exception: pass

    drag=modal.get("_ac_drag")
    mods=pygame.key.get_mods()
    if drag and lmb_held:
        if drag[0]=="move":
            dx=(mouse_pos[0]-drag[1][0])/max(0.01,zoom); dy=(mouse_pos[1]-drag[1][1])/max(0.01,zoom)
            if modal.get("_ac_snap_pixel"): dx=round(dx); dy=round(dy)
            layer["x"]=drag[2]+dx; layer["y"]=drag[3]+dy
            modal["_ac_tooltip"]=f"Δ {dx:+.0f}, {dy:+.0f}"
        elif drag[0]=="scale":
            cn=drag[1]; sxn,syn=AC_HANDLE_SIGN.get(cn,(1,1))
            dx=(mouse_pos[0]-drag[2][0])/max(1,sw); dy=(mouse_pos[1]-drag[2][1])/max(1,sh)
            sx0,sy0=drag[3],drag[4]
            if cn in ("tl","tr","bl","br") and (mods&pygame.KMOD_SHIFT):
                # uniform scale, preserving aspect ratio, driven by whichever axis moved more
                d=dx*sxn if abs(dx)>abs(dy) else dy*syn
                ratio=(sy0/sx0) if sx0 else 1.0
                new_sx=max(0.05,sx0+d*2); new_sy=max(0.05,new_sx*ratio)
                layer["scale_x"]=round(new_sx,2); layer["scale_y"]=round(new_sy,2)
            else:
                if sxn!=0: layer["scale_x"]=round(max(0.05,sx0+dx*sxn*2),2)
                if syn!=0: layer["scale_y"]=round(max(0.05,sy0+dy*syn*2),2)
            modal["_ac_tooltip"]=f"Scale {layer['scale_x']:.2f}×{layer['scale_y']:.2f}"
        elif drag[0]=="rotate":
            angle=math.degrees(math.atan2(mouse_pos[1]-ccy,mouse_pos[0]-ccx))
            layer["rotation"]=round(angle-drag[2],1); modal["_ac_tooltip"]=f"Rotate {layer['rotation']:.0f}°"
    elif not lmb_held and modal.get("_ac_drag"): modal["_ac_drag"]=None
    if giz.collidepoint(mouse_pos) and lc:
        if hovered_handle is None and not rr.collidepoint(mouse_pos):
            _ac_push_undo(); modal["_ac_drag"]=("move",mouse_pos,layer.get("x",0),layer.get("y",0)); left_click_this_frame=False

# ── Crop (now allows INCREASING canvas size) ─────────────────────────────────
def _ac_draw_crop(area,zoom,pan,cw,ch,mouse_pos,lc,lmb_held,proj):
    crop=modal.get("_ac_crop_rect")
    if crop is None:
        tl_x,tl_y=_ac_c2s(0,0,area,zoom,pan,cw,ch); br_x,br_y=_ac_c2s(cw,ch,area,zoom,pan,cw,ch)
        ov=pygame.Surface((area.w,area.h),pygame.SRCALPHA); ov.fill((0,0,0,60)); screen.blit(ov,area.topleft)
        ui_draw_rect(screen,ACCENT,pygame.Rect(tl_x,tl_y,br_x-tl_x,br_y-tl_y),width=2)
        screen.blit(font_sm.render("Drag to crop/expand · Enter=apply · Esc=cancel",True,GOLD),(area.centerx-170,area.bottom-36))
        if area.collidepoint(mouse_pos) and lc: modal["_ac_crop_drag"]=mouse_pos
    else:
        x1,y1,x2,y2=crop
        tl_x,tl_y=_ac_c2s(x1,y1,area,zoom,pan,cw,ch); br_x,br_y=_ac_c2s(x2,y2,area,zoom,pan,cw,ch)
        cs=pygame.Rect(min(tl_x,br_x),min(tl_y,br_y),abs(br_x-tl_x),abs(br_y-tl_y))
        ov=pygame.Surface((area.w,area.h),pygame.SRCALPHA); ov.fill((0,0,0,100))
        _l=cs.move(-area.x,-area.y); pygame.draw.rect(ov,(0,0,0,0),_l); screen.blit(ov,area.topleft)
        ui_draw_rect(screen,ACCENT,cs,width=2)
        for cp in[(cs.x,cs.y),(cs.right,cs.y),(cs.x,cs.bottom),(cs.right,cs.bottom)]: ui_draw_rect(screen,(255,255,255),(cp[0]-4,cp[1]-4,8,8))
        nw=int(abs(x2-x1)); nh=int(abs(y2-y1))
        screen.blit(font_sm.render(f"Crop: {nw}×{nh} · Enter=Apply · Esc=Cancel",True,GOLD),(area.centerx-130,area.bottom-30))
    drag=modal.get("_ac_crop_drag")
    if drag and lmb_held:
        cx1,cy1=_ac_s2c(drag[0],drag[1],area,zoom,pan,cw,ch); cx2,cy2=_ac_s2c(mouse_pos[0],mouse_pos[1],area,zoom,pan,cw,ch)
        # Allow negative coords (expanding beyond canvas)
        modal["_ac_crop_rect"]=(int(round(min(cx1,cx2))),int(round(min(cy1,cy2))),int(round(max(cx1,cx2))),int(round(max(cy1,cy2))))
    elif not lmb_held: modal["_ac_crop_drag"]=None
    if crop and pygame.key.get_pressed()[pygame.K_RETURN]:
        x1,y1,x2,y2=crop; nw=max(8,int(x2-x1)); nh=max(8,int(y2-y1))
        # Calculate offset: where does old canvas center map in new canvas?
        old_cx=cw/2.0; old_cy=ch/2.0
        new_cx=(x1+x2)/2.0; new_cy=(y1+y2)/2.0
        for l in _ac_all_layers_flat(proj.get("layers",[])):
            l["x"]=float(l.get("x",0))+(old_cx-new_cx)
            l["y"]=float(l.get("y",0))+(old_cy-new_cy)
        proj["canvas_w"]=nw; proj["canvas_h"]=nh
        modal["_ac_crop_rect"]=None; modal["_ac_tool"]="move"
        push_toast(f"Canvas resized to {nw}×{nh}","success")

# ── Rulers ────────────────────────────────────────────────────────────────────
def _ac_draw_rulers(area,zoom,pan,cw,ch):
    R=18
    top=pygame.Rect(area.x,area.y,area.w,R); left=pygame.Rect(area.x,area.y+R,R,area.h-R)
    ui_draw_rect(screen,(24,22,34),top); ui_draw_rect(screen,(24,22,34),left)
    step=max(1,int(16/zoom))
    for gx in range(0,cw+1,step):
        sx,_=_ac_c2s(gx,0,area,zoom,pan,cw,ch); sx+=R
        if top.left<=sx<=top.right:
            pygame.draw.line(screen,(50,48,64),(sx,top.bottom-4),(sx,top.bottom))
            if gx%(step*4)==0: screen.blit(font_tiny.render(str(gx),True,TEXT_DIM),(sx+2,top.y+2))
    for gy in range(0,ch+1,step):
        _,sy=_ac_c2s(0,gy,area,zoom,pan,cw,ch); sy+=R
        if left.top<=sy<=left.bottom:
            pygame.draw.line(screen,(50,48,64),(left.right-4,sy),(left.right,sy))
            if gy%(step*4)==0: screen.blit(font_tiny.render(str(gy),True,TEXT_DIM),(left.x+2,sy+2))

# ── Layer Panel ───────────────────────────────────────────────────────────────
def _ac_draw_layers(proj,mouse_pos,lc,rclicked,focus,panel,lmb_held):
    layers=proj.get("layers",[]); screen.blit(font_sm.render("LAYERS",True,ACCENT),(panel.x+8,panel.y+8))
    _ay=panel.y+30
    _btns=[("image_","Add sprite from library",lambda:_ac_add_sprite_layer(proj)),("edit","New paint layer",lambda:(_ac_push_undo(),_ac_new_paint_layer(proj))), ("folder","New group",lambda:_ac_add_group(proj)),("edit","New text layer",lambda:_ac_add_text_layer(proj)),("grid","New shape layer",lambda:_ac_add_shape_layer(proj)),("arrow_up","Move up",lambda:_ac_move_layer_in_list(layers,modal.get("_ac_sel_layer"),-1)),("arrow_down_","Move down",lambda:_ac_move_layer_in_list(layers,modal.get("_ac_sel_layer"),1)),("duplicate","Duplicate layer",lambda:_ac_dup_layer(proj,_ac_sel_layer(proj)) if _ac_sel_layer(proj) else None),("delete","Delete layer",lambda:_ac_delete_selected(proj))]
    _bx=panel.x+4
    for _bic,_btip,_bact in _btns:
        _br=pygame.Rect(_bx,_ay,23,22); _bhov=_br.collidepoint(mouse_pos)
        ui_draw_rect(screen,(44,40,58) if _bhov else FIELD_BG,_br,border_radius=4)
        ui_draw_rect(screen,ACCENT if _bhov else PANEL_BORDER,_br,width=1,border_radius=4)
        ic=get_icon_fs(_bic,13,ACCENT if _bhov else TEXT_MAIN)
        if ic: screen.blit(ic,(_br.centerx-ic.get_width()//2,_br.centery-ic.get_height()//2))
        if _bhov: modal["_ac_tooltip"]=_btip
        if _bhov and lc: _bact(); lc=False; left_click_this_frame=False
        _bx+=25
    _ay+=28; _fw=(panel.width-20)//3
    for _fi3,(_lbl,_ic,_tip,_act) in enumerate([("Flatten","onion","Flatten all layers",lambda:_ac_flatten(proj)),("Merge ↓","merge","Merge selected down",lambda:(_ac_merge_down(proj,modal.get("_ac_sel_layer")) if modal.get("_ac_sel_layer") else None)),("Raster","grid","Rasterize layer: bake rotation/scale/FX into fixed pixels so they never shift again",lambda:_ac_rasterize_layer(proj,_ac_sel_layer(proj)))]):
        _r=pygame.Rect(panel.x+4+_fi3*(_fw+4),_ay,_fw,22); _h=_r.collidepoint(mouse_pos)
        ui_draw_rect(screen,(44,40,58) if _h else FIELD_BG,_r,border_radius=4)
        ui_draw_rect(screen,ACCENT if _h else PANEL_BORDER,_r,width=1,border_radius=4)
        ic=get_icon_fs(_ic,12,ACCENT if _h else TEXT_MAIN); lx=_r.x+4
        if ic: screen.blit(ic,(lx,_r.centery-ic.get_height()//2)); lx+=ic.get_width()+3
        screen.blit(font_tiny.render(_lbl,True,TEXT_MAIN),(lx,_r.centery-5))
        if _h: modal["_ac_tooltip"]=_tip
        if _h and lc: _act(); lc=False; left_click_this_frame=False
    _ay+=28; pygame.draw.line(screen,DIVIDER,(panel.x+4,_ay),(panel.right-4,_ay)); _ay+=4
    lr=pygame.Rect(panel.x+2,_ay,panel.width-4,panel.bottom-_ay-4)
    _oc=screen.get_clip(); screen.set_clip(lr)
    flat=_ac_flat_layers(layers); sel_id=modal.get("_ac_sel_layer")
    scroll=float(modal.get("_ac_scroll",0.0)); RH=36
    total_h=len(flat)*RH+4; scroll=max(0,min(scroll,max(0,total_h-lr.height)))
    drag=modal.get("_ac_layer_drag")
    dragging=bool(drag and drag.get("dragging"))
    drag_id=drag.get("id") if drag else None
    drag_layer=_ac_find_layer(proj["layers"],drag_id) if drag_id else None
    row_info=[]  # (layer,depth,_lr,is_group) for every row, used for drop-target hit testing
    for _i,(layer,depth) in enumerate(flat):
        _ry=lr.y+4+_i*RH-int(scroll)
        if _ry+RH<lr.y or _ry>lr.bottom: continue
        lid=layer["id"]; is_sel=(lid==sel_id); _lr=pygame.Rect(lr.x+depth*14,_ry,lr.width-depth*14,RH-2)
        row_info.append((layer,depth,_lr,layer["type"]=="group"))
        is_being_dragged=dragging and lid==drag_id
        _lhov=_lr.collidepoint(mouse_pos) and not dragging
        if is_being_dragged:
            # leave a faint placeholder where the row used to be
            ui_draw_rect(screen,(26,24,36),_lr,border_radius=5)
            continue
        ui_draw_rect(screen,ACCENT_DIM if is_sel else ((38,35,52) if _lhov else (30,28,42)),_lr,border_radius=5)
        if is_sel: ui_draw_rect(screen,ACCENT,_lr,width=1,border_radius=5)
        vr=pygame.Rect(_lr.x+4,_lr.centery-8,16,16); _von=layer.get("visible",True)
        ic=get_icon_fs("eye" if _von else "eye_off",16,ACCENT if _von else TEXT_DIM)
        if ic: screen.blit(ic,(vr.x,vr.y))
        if vr.collidepoint(mouse_pos) and not dragging: modal["_ac_tooltip"]=f"{'Hide' if _von else 'Show'}"
        if vr.collidepoint(mouse_pos) and lc and not dragging: layer["visible"]=not _von; lc=False; left_click_this_frame=False
        lr2=pygame.Rect(_lr.x+22,_lr.centery-8,16,16); _lon=layer.get("locked",False)
        ic=get_icon_fs("lock" if _lon else "unlock",16,GOLD if _lon else TEXT_DIM)
        if ic: screen.blit(ic,(lr2.x,lr2.y))
        if lr2.collidepoint(mouse_pos) and not dragging: modal["_ac_tooltip"]=f"{'Unlock' if _lon else 'Lock'}"
        if lr2.collidepoint(mouse_pos) and lc and not dragging: layer["locked"]=not _lon; lc=False; left_click_this_frame=False
        lx=_lr.x+42
        _twisty_r=None
        if layer["type"]=="group":
            _twisty_r=pygame.Rect(lx-3,_lr.centery-9,18,18)
            ic=get_icon_fs("arrow_down_" if not layer.get("collapsed") else "forward",12,ACCENT if _twisty_r.collidepoint(mouse_pos) else TEXT_MAIN)
            if ic: screen.blit(ic,(lx,_lr.centery-ic.get_height()//2)); lx+=14
            ic=get_icon_fs("folder",16,ACCENT)
            if ic: screen.blit(ic,(lx,_lr.centery-ic.get_height()//2)); lx+=20
        elif layer["type"]=="text":
            ic=get_icon_fs("edit",16,ACCENT)
            if ic: screen.blit(ic,(lx,_lr.centery-ic.get_height()//2)); lx+=20
        elif layer["type"]=="shape":
            ic=get_icon_fs("grid",16,GOOD)
            if ic: screen.blit(ic,(lx,_lr.centery-ic.get_height()//2)); lx+=20
        elif layer["type"]=="raster":
            ic=get_icon_fs("edit",16,ACCENT)
            if ic: screen.blit(ic,(lx,_lr.centery-ic.get_height()//2)); lx+=20
        else:
            ic=get_icon_fs("image_",16,TEXT_MAIN)
            if ic: screen.blit(ic,(lx,_lr.centery-ic.get_height()//2)); lx+=16
        screen.blit(font_tiny.render(layer["name"][:16],True,(255,255,255) if is_sel else TEXT_MAIN),(lx,_lr.centery-5))
        if layer["type"]=="group":
            _n=len(layer.get("children",[]))
            screen.blit(font_tiny.render(f"{_n}",True,TEXT_DIM),(_lr.right-18,_lr.centery-5))
        op=int(layer.get("opacity",255))
        if op<255: screen.blit(font_tiny.render(f"{op}%",True,TEXT_DIM),(_lr.right-42,_lr.centery-5))
        bm=layer.get("blend_mode","Normal")
        if bm!="Normal": screen.blit(font_tiny.render(bm[:3],True,GOLD),(_lr.right-42,_lr.centery+3))
        # twisty click toggles collapse and eats the click
        if _twisty_r and _twisty_r.collidepoint(mouse_pos) and lc and not dragging:
            layer["collapsed"]=not layer.get("collapsed",False); lc=False; left_click_this_frame=False
        elif _lhov and lc:
            modal["_ac_sel_layer"]=lid; lc=False; left_click_this_frame=False
        if _lhov and rclicked:
            modal["_ac_ctx_menu"]={"x":mouse_pos[0],"y":mouse_pos[1],"items":[
                ("Duplicate","duplicate",lambda l=layer:_ac_dup_layer(proj,l)),
                ("Delete","delete",lambda l=layer:(_ac_push_undo(),_ac_remove_layer(proj["layers"],l["id"]))),
                ("---",None,None),
                ("Move to Top","arrow_up",lambda:_ac_move_to_edge(proj["layers"],lid,"top")),
                ("Move to Bottom","arrow_down_",lambda:_ac_move_to_edge(proj["layers"],lid,"bottom")),
                ("---",None,None),
                ("Rasterize Layer","grid",lambda l=layer:_ac_rasterize_layer(proj,l)),
                ("Merge Down","merge",lambda:_ac_merge_down(proj,lid)),
                ("Flatten All","onion",lambda:_ac_flatten(proj)),
            ]}; left_click_this_frame=False
        if _lhov and lmb_held and not drag and not modal.get("_ac_panning") and not (_twisty_r and _twisty_r.collidepoint(mouse_pos)):
            modal["_ac_layer_drag"]={"id":lid,"anchor":list(mouse_pos),"dragging":False,"name":layer.get("name","Layer"),"kind":layer["type"]}

    # ── drag threshold / drop-target computation / release ──────────────────
    drop_info=None
    if drag:
        moved=abs(mouse_pos[0]-drag["anchor"][0])+abs(mouse_pos[1]-drag["anchor"][1])
        if moved>6: drag["dragging"]=True
        if drag.get("dragging") and lmb_held and drag_layer is not None:
            for layer,depth,_lr,is_group in row_info:
                lid=layer["id"]
                if lid==drag_id or _ac_is_self_or_descendant(drag_layer,lid): continue
                row_top,row_bot=_lr.y,_lr.y+_lr.height
                if row_top<=mouse_pos[1]<=row_bot and lr.collidepoint(mouse_pos[0],max(lr.y,min(lr.bottom-1,mouse_pos[1]))):
                    frac=(mouse_pos[1]-row_top)/max(1,_lr.height)
                    if is_group and 0.28<frac<0.72:
                        drop_info={"mode":"into","target_id":lid,"rect":_lr.copy()}
                    elif frac<0.5:
                        drop_info={"mode":"before","target_id":lid,"depth":depth,"y":row_top,"x":_lr.x}
                    else:
                        drop_info={"mode":"after","target_id":lid,"depth":depth,"y":row_bot,"x":_lr.x}
                    break
        drop_info = drop_info or modal.get("_ac_drop_info")
        if drag.get("dragging") and not lmb_held:
            if drop_info and drag_layer is not None:
                _ac_push_undo()
                src = _ac_find_parent_list(proj["layers"], drag_id)
                if src:
                    slist, sidx = src; moved_layer = slist.pop(sidx)
                    if drop_info.get("mode") == "into":
                        tgt = _ac_find_layer(proj["layers"], drop_info.get("target_id"))
                        if tgt is not None and tgt.get("type") == "group":
                            tgt.setdefault("children", []).insert(0, moved_layer)
                            tgt["collapsed"] = False
                        else:
                            slist.insert(sidx, moved_layer)
                    else:
                        tdst = _ac_find_parent_list(proj["layers"], drop_info.get("target_id"))
                        if tdst:
                            tlist, tidx = tdst
                            tlist.insert(tidx + (1 if drop_info.get("mode") == "after" else 0), moved_layer)
                        else:
                            slist.insert(sidx, moved_layer)
                    modal["_ac_sel_layer"] = drag_id
            modal["_ac_layer_drag"] = None; modal["_ac_drop_info"] = None
        elif not lmb_held:
            modal["_ac_layer_drag"] = None; modal["_ac_drop_info"] = None
    if drag and drag.get("dragging"):
        modal["_ac_drop_info"] = drop_info

    # drop-target indicator, drawn above the rows
    if drop_info:
        if drop_info["mode"]=="into":
            ui_draw_rect(screen,GOOD,drop_info["rect"],width=2,border_radius=6)
        else:
            yy=drop_info["y"]; xx=drop_info["x"]
            pygame.draw.line(screen,GOOD,(xx,yy),(lr.right-4,yy),3)
            pygame.draw.circle(screen,GOOD,(xx,yy),4)

    # floating "popout" ghost card that follows the cursor while dragging
    if dragging and drag_layer is not None:
        gw=min(220,lr.width-4); gh=RH-6
        gx=max(lr.x,min(mouse_pos[0]-18,lr.right-gw)); gy=mouse_pos[1]-gh//2
        ghost=pygame.Surface((gw,gh),pygame.SRCALPHA)
        pygame.draw.rect(ghost,(58,54,78,230),(0,0,gw,gh),border_radius=6)
        pygame.draw.rect(ghost,(*ACCENT,255),(0,0,gw,gh),width=2,border_radius=6)
        _gicon={"group":"folder","text":"edit","shape":"grid"}.get(drag["kind"],"image_")
        gic=get_icon_fs(_gicon,13,ACCENT); gtx=8
        if gic: ghost.blit(gic,(gtx,gh//2-gic.get_height()//2)); gtx+=gic.get_width()+5
        ghost.blit(font_tiny.render(drag.get("name","Layer")[:20],True,(255,255,255)),(gtx,gh//2-5))
        screen.blit(ghost,(gx,gy))
        try: pygame.mouse.set_cursor(pygame.SYSTEM_CURSOR_HAND)
        except Exception: pass

    screen.set_clip(_oc)
    if total_h>lr.height:
        _sbtr, _sbns = draw_scrollbar(lr,scroll,total_h,lr.height,mouse_pos)
        scroll = max(0.0,min(float(_sbns),max(0.0,total_h-lr.height)))
    modal["_ac_scroll"]=scroll
    modal["_ac_layer_scroll_max"]=max(0.0,total_h-lr.height)

# ── Self-contained drag slider ──────────────────────────────────────────────
# The shared modal_sliders/dragging_slider machinery is wired to specific
# panels (external-node inspector, sidebar style tab) and never checked
# modal["type"]=="asset_creator", so those sliders just sat there doing
# nothing. This drives its own drag state directly off the per-frame input
# asset_creator already reads, so it doesn't depend on that machinery at all.
def _ac_slider(key,x,y,w,lo,hi,get,setter,fmt,label,mouse_pos,lc,lmb_held):
    global left_click_this_frame
    value=float(get())
    track=pygame.Rect(x,y,w,3)
    ui_draw_rect(screen,(24,24,30),track,border_radius=2)
    frac=0.0 if hi<=lo else max(0.0,min(1.0,(value-lo)/(hi-lo)))
    fill=pygame.Rect(x,y,int(w*frac),3)
    ui_draw_rect(screen,ACCENT,fill,border_radius=2)
    hx=x+w*frac
    drag=modal.get("_ac_slider_drag")
    active=(drag==key)
    hovered=pygame.Rect(x-4,y-10,w+8,20).collidepoint(mouse_pos)
    if hovered or active:
        glow=pygame.Surface((28,28),pygame.SRCALPHA)
        pygame.draw.circle(glow,(*ACCENT_SOFT,70),(14,14),12)
        screen.blit(glow,(hx-14,y-14))
    pygame.draw.circle(screen,(10,10,13),(int(hx),y),8)
    pygame.draw.circle(screen,ACCENT_HOVER if (hovered or active) else (235,235,242),(int(hx),y),6)
    if label:
        screen.blit(font_sm.render(label,True,TEXT_DIM),(x,y-19))
        vs=font_sm.render(fmt(value),True,TEXT_MAIN)
        screen.blit(vs,(x+w-vs.get_width(),y-19))
    if not active and hovered and lc:
        modal["_ac_slider_drag"]=key; modal["_ac_slider_undone"]=False; active=True
        lc=False; left_click_this_frame=False
    if active:
        if not lmb_held:
            modal["_ac_slider_drag"]=None
        else:
            if not modal.get("_ac_slider_undone"):
                _ac_push_undo(); modal["_ac_slider_undone"]=True
            nf=max(0.0,min(1.0,(mouse_pos[0]-x)/max(1,w)))
            setter(lo+nf*(hi-lo))
    return value

# ── Properties ────────────────────────────────────────────────────────────────
def _ac_draw_props(proj,mouse_pos,lc,focus,panel,lmb_held=False):
    global left_click_this_frame
    sel = _ac_sel_layer(proj)
    if not sel:
        screen.blit(font_tiny.render("Select a layer to edit", True, TEXT_DIM), (panel.x + 12, panel.y + 20))
        return
    _pw = panel.width - 18
    scroll_y = max(0.0, float(modal.get("_ac_props_scroll", 0.0)))
    old_clip = screen.get_clip()
    screen.set_clip(panel)
    _py_start = panel.y + 6
    _py = _py_start - int(scroll_y)
    _fk="_ac_pf_name"; _fr=pygame.Rect(panel.x+8,_py,_pw,24); _ff=(focus==_fk)
    draw_text_field(_fr,sel.get("name","Layer"),"Layer Name",_ff)
    if _fr.collidepoint(mouse_pos) and lc:
        modal["focus"]=_fk; _text_editor_begin_mouse(_fk,_fr,mouse_pos[0],pygame.key.get_mods()); left_click_this_frame=False
    _py+=30
    if sel.get("type")=="sprite":
        _sp=sel.get("sprite","")
        screen.blit(font_tiny.render(f"Sprite: {os.path.basename(_sp) if _sp else '(empty)'}",True,TEXT_DIM),(panel.x+10,_py)); _py+=16
        _cr=pygame.Rect(panel.x+8,_py,_pw,24); _ch=_cr.collidepoint(mouse_pos)
        ui_draw_rect(screen,(44,40,58) if _ch else FIELD_BG,_cr,border_radius=5)
        ui_draw_rect(screen,ACCENT if _ch else PANEL_BORDER,_cr,width=1,border_radius=5)
        ic=get_icon_fs("image_",14,ACCENT if _ch else TEXT_MAIN); lx=_cr.x+6
        if ic: screen.blit(ic,(lx,_cr.centery-ic.get_height()//2)); lx+=ic.get_width()+4
        screen.blit(font_tiny.render("Change Sprite...",True,TEXT_MAIN),(lx,_cr.centery-5))
        if _ch: modal["_ac_tooltip"]="Pick from sprite library"
        if _ch and lc:
            def _pick(rel):
                _ac_push_undo(); sel["sprite"]=rel; sel["name"]=os.path.splitext(os.path.basename(rel))[0]
                modal["type"]="asset_creator"; push_toast(f"Changed: {os.path.basename(rel)}","success",1.5)
            open_asset_library(tab="sprites",pick_callback=_pick,return_to="asset_creator"); left_click_this_frame=False; return
        _py+=30
    if sel.get("type")=="text":
        _tfk="_ac_pf_text"; _tr=pygame.Rect(panel.x+8,_py,_pw,24)
        draw_text_field(_tr,sel.get("text_content",""),"Text Content",focus==_tfk)
        if _tr.collidepoint(mouse_pos) and lc:
            modal["focus"]=_tfk; _text_editor_begin_mouse(_tfk,_tr,mouse_pos[0],pygame.key.get_mods()); left_click_this_frame=False
        _py+=30
    if sel.get("type")=="shape":
        screen.blit(font_tiny.render("SHAPE TYPE",True,ACCENT),(panel.x+10,_py)); _py+=16
        sx=panel.x+8
        for _st,_sl,_sic in [("rect","Rect","grid"),("ellipse","Ellipse","atom"),("line","Line","straight")]:
            _sr=pygame.Rect(sx,_py,74,24); _sa=(sel.get("shape_type")==_st); _sh=_sr.collidepoint(mouse_pos)
            ui_draw_rect(screen,ACCENT if _sa else ((44,40,58) if _sh else FIELD_BG),_sr,border_radius=5)
            ui_draw_rect(screen,ACCENT if _sa else (ACCENT if _sh else PANEL_BORDER),_sr,width=1,border_radius=5)
            ic=get_icon_fs(_sic,14,(10,10,14) if _sa else (ACCENT if _sh else TEXT_MAIN)); lx=_sr.x+6
            if ic: screen.blit(ic,(lx,_sr.centery-ic.get_height()//2)); lx+=ic.get_width()+3
            screen.blit(font_tiny.render(_sl,True,(10,10,14) if _sa else TEXT_MAIN),(lx,_sr.centery-5))
            if _sh and lc: _ac_push_undo(); sel["shape_type"]=_st; left_click_this_frame=False
            sx+=80
        _py+=30

        # Fill Color Picker
        _fill_col = tuple(sel.get("shape_fill", (255, 255, 255, 255)))
        _fr = pygame.Rect(panel.x + 8, _py, _pw, 24); _fh = _fr.collidepoint(mouse_pos)
        ui_draw_rect(screen, FIELD_FOCUS if _fh else FIELD_BG, _fr, border_radius=5)
        ui_draw_rect(screen, ACCENT if _fh else PANEL_BORDER, _fr, width=1, border_radius=5)
        _sb = pygame.Rect(_fr.x + 4, _fr.y + 3, 18, 18)
        ui_draw_rect(screen, _fill_col[:3], _sb, border_radius=3)
        ui_draw_rect(screen, (255, 255, 255), _sb, width=1, border_radius=3)
        screen.blit(font_tiny.render("Shape Fill Color (Pick Wheel...)", True, TEXT_MAIN), (_sb.right + 8, _fr.centery - 5))
        if _fh and lc:
            def _fill_cb(c):
                _ac_push_undo()
                sel["shape_fill"] = list(c)
            open_color_picker(initial_color=_fill_col, callback=_fill_cb, title="Shape Fill Color", return_to="asset_creator")
            left_click_this_frame = False
        _py += 28
    pygame.draw.line(screen,DIVIDER,(panel.x+8,_py),(panel.right-8,_py)); _py+=8
    for _pk,_plbl,_plo,_phi in [("x","Pos X",-500,500),("y","Pos Y",-500,500),("scale_x","Scale X",0.05,8.0),("scale_y","Scale Y",0.05,8.0),("rotation","Rotation",-360,360)]:
        _ac_slider(f"prop:{_pk}",panel.x+8,_py,_pw,_plo,_phi,(lambda k=_pk:float(sel.get(k,0))),(lambda v,k=_pk:sel.__setitem__(k,round(v,2))),(lambda v:f"{v:.1f}" if abs(v)<10 else f"{v:.0f}"),_plbl,mouse_pos,lc,lmb_held)
        _py+=34
    pygame.draw.line(screen,DIVIDER,(panel.x+8,_py),(panel.right-8,_py)); _py+=8
    _ac_slider("prop:opacity",panel.x+8,_py,_pw,0,255,(lambda:float(sel.get("opacity",255))),(lambda v:sel.__setitem__("opacity",int(v))),(lambda v:f"{int(v)}"),"Opacity",mouse_pos,lc,lmb_held)
    _py+=34
    screen.blit(font_tiny.render("BLEND MODE",True,TEXT_DIM),(panel.x+10,_py)); _py+=16
    bm=sel.get("blend_mode","Normal"); bx=panel.x+8
    for m in AC_BLEND_MODES:
        _br=pygame.Rect(bx,_py,38,20); _a=(bm==m); _h=_br.collidepoint(mouse_pos)
        ui_draw_rect(screen,ACCENT if _a else ((44,40,58) if _h else FIELD_BG),_br,border_radius=4)
        screen.blit(font_tiny.render(m[:4],True,(10,10,14) if _a else TEXT_DIM),(_br.x+2,_br.y+3))
        if _h: modal["_ac_tooltip"]=m
        if _h and lc: _ac_push_undo(); sel["blend_mode"]=m; left_click_this_frame=False
        bx+=42
    _py+=26
    for _bk,_bl,_bic in [("flip_x","Flip H","split_v"),("flip_y","Flip V","split_h"),("pixel_snap","Pixel Snap","snap"),("pixel_lock","Pixel Lock (auto-bake)","lock"),("visible","Visible","eye"),("locked","Locked","lock")]:
        _br=pygame.Rect(panel.x+8,_py,_pw,22); _on=bool(sel.get(_bk,True if _bk in ("visible","pixel_snap") else False)); _h=_br.collidepoint(mouse_pos)
        ui_draw_rect(screen,ACCENT_DIM if _on else FIELD_BG,_br,border_radius=4)
        ui_draw_rect(screen,ACCENT if _on else PANEL_BORDER,_br,width=1,border_radius=4)
        ic=get_icon_fs(_bic,12,TEXT_MAIN if _on else TEXT_DIM); lx=_br.x+6
        if ic: screen.blit(ic,(lx,_br.centery-ic.get_height()//2)); lx+=ic.get_width()+4
        screen.blit(font_tiny.render(f"{_bl}: {'ON' if _on else 'off'}",True,TEXT_MAIN if _on else TEXT_DIM),(lx,_br.centery-5))
        if _h: modal["_ac_tooltip"]="Pixel Lock: every rotate/scale is instantly baked into pixels on release — no live resampling, no pixel drift" if _bk=="pixel_lock" else _bl
        if _h and lc:
            _ac_push_undo(); sel[_bk]=not _on; left_click_this_frame=False
            if _bk=="pixel_lock" and not _on:
                # Turning Pixel Lock ON rasterizes right away (any layer type)
                _ac_rasterize_layer(proj,sel,quiet=True,push=False); sel["pixel_lock"]=True
                push_toast("Pixel Lock ON — layer baked; edits re-bake automatically","success",2.2)
        _py+=26
    # ── RECOLOR & HUE SECTION ──
    pygame.draw.line(screen, DIVIDER, (panel.x + 8, _py), (panel.right - 8, _py)); _py += 8
    screen.blit(font_tiny.render("RECOLOR & HUE", True, ACCENT), (panel.x + 10, _py)); _py += 18

    _ac_slider("prop:hue_shift", panel.x + 8, _py, _pw, -180, 180,
               (lambda: float(sel.get("hue_shift", 0.0))),
               (lambda v: (sel.__setitem__("hue_shift", round(v, 1)), sel.pop("_recolor_cache_key", None))),
               (lambda v: f"{v:+.0f}°"), "Hue Shift", mouse_pos, lc, lmb_held)
    _py += 34

    _ac_slider("prop:sat_scale", panel.x + 8, _py, _pw, 0.0, 2.0,
               (lambda: float(sel.get("sat_scale", 1.0))),
               (lambda v: (sel.__setitem__("sat_scale", round(v, 2)), sel.pop("_recolor_cache_key", None))),
               (lambda v: f"{v:.0%}"), "Saturation", mouse_pos, lc, lmb_held)
    _py += 34

    _ac_slider("prop:val_scale", panel.x + 8, _py, _pw, 0.0, 2.0,
               (lambda: float(sel.get("val_scale", 1.0))),
               (lambda v: (sel.__setitem__("val_scale", round(v, 2)), sel.pop("_recolor_cache_key", None))),
               (lambda v: f"{v:.0%}"), "Brightness / Value", mouse_pos, lc, lmb_held)
    _py += 34

    _col_on = bool(sel.get("colorize_on", False))
    _col_r = pygame.Rect(panel.x + 8, _py, _pw, 22); _col_h = _col_r.collidepoint(mouse_pos)
    ui_draw_rect(screen, ACCENT_DIM if _col_on else FIELD_BG, _col_r, border_radius=4)
    ui_draw_rect(screen, ACCENT if _col_on else PANEL_BORDER, _col_r, width=1, border_radius=4)
    ic = get_icon_fs("palette", 12, TEXT_MAIN if _col_on else TEXT_DIM); lx = _col_r.x + 6
    if ic: screen.blit(ic, (lx, _col_r.centery - ic.get_height() // 2)); lx += ic.get_width() + 4
    screen.blit(font_tiny.render(f"Colorize (Recolor Grey Art): {'ON' if _col_on else 'off'}", True, TEXT_MAIN if _col_on else TEXT_DIM), (lx, _col_r.centery - 5))
    if _col_h: modal["_ac_tooltip"] = "Replace hue+saturation (great for grayscale art)"
    if _col_h and lc:
        _ac_push_undo()
        sel["colorize_on"] = not _col_on
        sel.pop("_recolor_cache_key", None)
        left_click_this_frame = False
    _py += 26

    if _col_on:
        _ac_slider("prop:colorize_strength", panel.x + 8, _py, _pw, 0.0, 1.0,
                   (lambda: float(sel.get("colorize_strength", 1.0))),
                   (lambda v: (sel.__setitem__("colorize_strength", round(v, 2)), sel.pop("_recolor_cache_key", None))),
                   (lambda v: f"{v:.0%}"), "Colorize Strength", mouse_pos, lc, lmb_held)
        _py += 34

        _cur_col = tuple(sel.get("colorize_color", [90, 140, 235]))
        _cbr = pygame.Rect(panel.x + 8, _py, _pw, 24); _cbh = _cbr.collidepoint(mouse_pos)
        ui_draw_rect(screen, FIELD_FOCUS if _cbh else FIELD_BG, _cbr, border_radius=5)
        ui_draw_rect(screen, ACCENT if _cbh else PANEL_BORDER, _cbr, width=1, border_radius=5)
        _sw_box = pygame.Rect(_cbr.x + 4, _cbr.y + 3, 18, 18)
