def _ac_draw_hist(mouse_pos,lc,panel):
    _py=panel.y+4; undo=modal.get("_ac_undo",[]); redo=modal.get("_ac_redo",[])
    _cr=pygame.Rect(panel.x+8,_py,panel.width-16,24)
    ui_draw_rect(screen,ACCENT,_cr,border_radius=5)
    ic=get_icon_fs("bolt",12,(10,10,14)); lx=_cr.x+6
    if ic: screen.blit(ic,(lx,_cr.centery-ic.get_height()//2)); lx+=ic.get_width()+4
    screen.blit(font_tiny.render("Current State",True,(10,10,14)),(lx,_cr.centery-5))
    _py+=28
    for _i,_ in enumerate(reversed(redo)):
        _rr=pygame.Rect(panel.x+8,_py,panel.width-16,22); _rh=_rr.collidepoint(mouse_pos)
        ui_draw_rect(screen,(44,40,58) if _rh else FIELD_BG,_rr,border_radius=4)
        screen.blit(font_tiny.render(f"Redo {len(redo)-_i}",True,TEXT_DIM),(_rr.x+8,_rr.y+4))
        if _rh and lc:
            for _ in range(_i+1): _ac_redo()
            left_click_this_frame=False
        _py+=24
    for _i,_ in enumerate(reversed(undo)):
        _ur=pygame.Rect(panel.x+8,_py,panel.width-16,22); _uh=_ur.collidepoint(mouse_pos)
        ui_draw_rect(screen,(44,40,58) if _uh else FIELD_BG,_ur,border_radius=4)
        screen.blit(font_tiny.render(f"State {len(undo)-_i}",True,TEXT_MAIN),(_ur.x+8,_ur.y+4))
        if _uh and lc:
            for _ in range(_i+1): _ac_undo()
            left_click_this_frame=False
        _py+=24
    if not undo and not redo: screen.blit(font_tiny.render("No history yet",True,TEXT_DIM),(panel.x+12,_py+16))

# ── Scroll wheel handler ─────────────────────────────────────────────────────
def _ac_handle_wheel(dy):
    if modal.get("type") != "asset_creator":
        return
    if modal.get("_ac_open_dd"):
        modal["_ac_proj_grid_scroll"] = max(0.0, float(modal.get("_ac_proj_grid_scroll", 0.0)) - dy * 40)
        return
    mpos = pygame.mouse.get_pos()
    # Use the responsive rectangles produced by draw_asset_creator.  The old
    # hard-coded layer rectangle pointed at the LEFT canvas toolbar even though
    # Layers lives on the RIGHT, so wheel events never reached added images.
    prop_rect = modal.get("_ac_props_panel_rect")
    if not isinstance(prop_rect,pygame.Rect):
        prop_rect=pygame.Rect(WIDTH-260,40,260,HEIGHT-66)
    if prop_rect.collidepoint(mpos):
        cur=float(modal.get("_ac_props_scroll",0.0));mx=float(modal.get("_ac_props_scroll_max",1e9))
        modal["_ac_props_scroll"]=max(0.0,min(mx,cur-dy*42))
        return
    layer_rect = modal.get("_ac_layer_panel_rect")
    if not isinstance(layer_rect,pygame.Rect):
        layer_rect=pygame.Rect(WIDTH-260-230,40,230,HEIGHT-66)
    if layer_rect.collidepoint(mpos):
        cur=float(modal.get("_ac_scroll",0.0));mx=float(modal.get("_ac_layer_scroll_max",1e9))
        modal["_ac_scroll"]=max(0.0,min(mx,cur-dy*54))
        return
    zoom = float(modal.get("_ac_zoom", 4.0))
    zoom = max(0.05, min(64.0, zoom * (1.5 ** (1 if dy > 0 else -1))))
    modal["_ac_zoom"] = round(zoom, 2)


# ANIMATION STATE TIMELINE  —  every state of a character at once
# ============================================================
# The old editor showed one state's frames. This shows ALL of them as
# parallel tracks against a shared time ruler (a dope sheet), plus the
# state machine that decides which one plays. Two views:
#   TIMELINE : per-state tracks, frame blocks, drag to retime
#   MACHINE  : state nodes + transition list with conditions

# ============================================================
# ANIMATION TIMELINE  (v2)  —  the one and only animation editor
# ============================================================
# Layout:
#   top-left    : LARGE live preview of the composited state
#   top-right   : compact inspector (collapsible), state + transition props
#   bottom      : the dope sheet — one row per LAYER of the selected state,
#                 plus a state rail on the left to switch states
#
# The old in-character-editor animation tab is deprecated; it now just
# opens this window. Frame sources (GIF / sprite sheet / PNG) are
# reachable from right here, not only from the character editor.

# ============================================================
# SPRITE SHEET EXTRACTOR  —  full-screen UI
# ============================================================
# Left  : the sheet with the slice grid drawn over it (click a cell to
#         toggle it, or click the image to pick the background colour)
# Right : slicing controls, colour key, and the destination picker
#
# This is the same panel used for GIFs (the GIF importer feeds its
# decoded frames in as a virtual sheet), so there is one place to learn.

def open_sheet_extractor(return_to="main", target=None, path=None):
    if not SPRITE_FOLDERS_LOADED:
        load_sprite_folders()
    modal["_shx_return"] = return_to
    modal["_shx_target"] = target or ("sprites", None)
    modal["_shx_cfg"] = _sheet_normalize(modal.get("_shx_cfg"))
    modal["_shx_surface"] = None
    modal["_shx_path"] = ""
    modal["_shx_zoom"] = 1.0
    modal["_shx_pan"] = [0.0, 0.0]
    modal["_shx_pick_color"] = False
    modal["_shx_scale"] = 1.0
    modal["_shx_sel_cell"] = None
    modal["_shx_prev_down"] = True
    modal["_shx_kprev"] = {pygame.K_ESCAPE: True}
    modal["focus"] = None
    modal["type"] = "sheet_extractor"
    if path:
        _shx_load(path)

def _shx_close():
    ret = modal.get("_shx_return", "main")
    modal["_shx_surface"] = None
    modal["_shx_cells"] = None
    modal["focus"] = None
    for k in ("_cb_prev_down", "_ast_prev_down", "_sgm_prev_down"):
        modal[k] = True
    modal["type"] = None if ret == "main" else ret

def _shx_load(path):
    surf = sheet_load_surface(path)
    if surf is None:
        return False
    modal["_shx_surface"] = surf
    modal["_shx_path"] = path
    stem = os.path.splitext(os.path.basename(path))[0]
    modal["_shx_folder"] = "imported/" + stem
    sheet_layout_invalidate()
    _SHX_KEYED_CACHE["sig"] = None
    _SHX_AUTO_CACHE["key"] = None
    modal["_shx_cfg"]["disabled"] = []
    modal["_shx_dirty"] = True
    # A sensible first guess: square-ish cells based on the sheet size.
    cfg = modal["_shx_cfg"]
    if cfg["cell_w"] <= 0 and cfg["cols"] <= 1:
        cfg["cols"], cfg["rows"] = 4, 4
    return True

def _shx_pick_from_library():
    """Open the in-app Asset Library to pick a sprite sheet instead of the OS
    file explorer. The picked sprite loads straight back into this tool."""
    def _pick(rel_path):
        if not rel_path:
            return
        full = os.path.join(SPRITES_DIR, str(rel_path).replace("/", os.sep))
        if not os.path.isfile(full):
            push_toast(f"Image not found: {rel_path}", "error", 3.0)
            return
        _shx_load(full)
    open_asset_library(tab="sprites", pick_callback=_pick, return_to="sheet_extractor")


def _shx_cells(force=False):
    """Cached slice result; recomputed whenever the config changes."""
    surf = modal.get("_shx_surface")
    if surf is None:
        return []
    cfg = modal.get("_shx_cfg", {})
    sig = (id(surf), json.dumps(cfg, sort_keys=True, default=str))
    if not force and modal.get("_shx_sig") == sig and modal.get("_shx_cells") is not None:
        return modal["_shx_cells"]
    cells = sheet_slice(surf, cfg)
    modal["_shx_cells"] = cells
    modal["_shx_sig"] = sig
    return cells

