def open_particle_node_preset_picker(node_id,pname="preset",current="sparks"):
    """Open the real Particle Creator preset shelf for a graph property."""
    key=str(current or "sparks");key=key if key in PE_PRESETS else "sparks"
    temp=pe_default(name="Preset Preview",wx=0.0,wy=0.0);particle_emitters.append(temp)
    pe_apply_preset(temp,key,keep_textures=False);temp["_node_preset_picker_temp"]=True
    modal["_pe_node_pick"]={"node_id":int(node_id),"pname":str(pname),"temp_id":temp["id"],"return_to":"visual_scripter"};modal["_pe_node_pick_candidate"]=key;modal["_pe_node_pick_baseline"]=_pe_picker_authored_state(temp);modal["ns_dropdown_menu"]=None
    open_particle_editor(temp["id"],return_to="visual_scripter")
    modal["_pe_tab"]="presets";modal["_pe_preview_preset"]=key;modal["_pe_preview_em"]=None

def _pe_finish_node_picker(selected=None):
    ctx=modal.get("_pe_node_pick")
    if not isinstance(ctx,dict):return False
    if selected in PE_PRESETS:
        node=modal.get("ns_nodes",{}).get(int(ctx.get("node_id",-1)))
        if isinstance(node,dict):
            node.setdefault("props",{})[str(ctx.get("pname","preset"))]=selected;modal["ns_dirty"]=True
            push_toast(f"Particle preset set to '{pe_preset_label(selected)}'.","success",1.8)
    remove_particle_emitter(ctx.get("temp_id"));modal.pop("_pe_node_pick",None);modal.pop("_pe_node_pick_candidate",None);modal.pop("_pe_node_pick_baseline",None);modal["_pe_preview_preset"]=None;modal["_pe_preview_em"]=None;modal["type"]=ctx.get("return_to","visual_scripter");modal["focus"]=None
    return True

def _pe_picker_authored_state(em):
    identity=set(PE_IDENTITY_KEYS)|{"preset","emitting","binding"}
    return {k:copy.deepcopy(v) for k,v in em.items() if k not in identity and not str(k).startswith("_")}
def _pe_load_picker_for_edit(em,key):
    if key not in PE_PRESETS:return False
    pe_apply_preset(em,key,keep_textures=False);em["preset"]=key;em["name"]=pe_preset_label(key);em["_particles"]=[];em["_accum"]=0.0;em["_age"]=0.0;modal["_pe_node_pick_candidate"]=key;modal["_pe_node_pick_baseline"]=_pe_picker_authored_state(em);modal["_pe_preview_preset"]=None;modal["_pe_preview_em"]=None;modal["_pe_tab"]="emission";push_toast("Preset loaded into the temporary editor. Make changes, then press Use Preset.","info",2.4);return True
def _pe_use_or_apply_preset(em,key,confirm=False):
    if isinstance(modal.get("_pe_node_pick"),dict):
        if not confirm:
            if key in PE_PRESETS:modal["_pe_preview_preset"]=key;modal["_pe_preview_em"]=None;modal["_pe_node_pick_candidate"]=key
            return False
        chosen=key if key in PE_PRESETS else modal.get("_pe_node_pick_candidate","sparks");baseline=modal.get("_pe_node_pick_baseline")
        if isinstance(baseline,dict) and _pe_picker_authored_state(em)!=baseline:
            base=pe_preset_label(chosen)+" Variant";name=base;n=2
            while "custom:"+name in PE_PRESETS:name=f"{base} {n}";n+=1
            saved=save_particle_custom_preset(name,em)
            if saved:chosen=saved;push_toast(f"Saved edited preset as '{name}'.","success",2.0)
        return _pe_finish_node_picker(chosen)
    pe_apply_preset(em,key,keep_textures=False);em["name"]=pe_preset_label(key);modal["_pe_preview_preset"]=None;modal["_pe_preview_em"]=None;push_toast(f"Applied '{em['name']}'.","success",1.4);return False


def open_particle_editor(emitter_id, return_to=None):
    modal["_pe_id"] = int(emitter_id)
    modal["_pe_return"] = return_to
    modal["_pe_tab"] = modal.get("_pe_tab") or "emission"
    modal["_pe_prev_down"] = True
    modal["_pe_kprev"] = {pygame.K_ESCAPE: True}
    modal["_pe_path_mode"] = False
    # Must exist as a str so the generic text-editor fallback picks it up.
    modal.setdefault("_pe_search", "")
    modal.setdefault("_pe_name", "")
    modal["focus"] = None
    modal["type"] = "particle_editor"

def _pe_close():
    if isinstance(modal.get("_pe_node_pick"),dict):
        _pe_finish_node_picker(None);return
    # Keep custom Particle Creator presets synchronized with their edited live
    # emitter. Spawn Pure Particle reads the preset shelf, so closing the editor
    # must commit authored frame holds/lifetime rather than leaving an older copy.
    try:
        _em=get_particle_emitter(modal.get("_pe_id"));_pk=str((_em or {}).get("preset","") or "")
        if _em is not None and _pk.startswith("custom:") and _pk!="custom:":
            save_particle_custom_preset(_pk[7:],_em)
    except Exception:pass
    ret = modal.get("_pe_return")
    modal["type"] = ret
    modal["focus"] = None
    modal["_pe_path_mode"] = False

