    _draw_em = preview_em if preview_em is not None else em
    parts=_draw_em.get("_particles") or []
    _draw_budget=max(48,min(1200,int(SETTINGS.get("pe_editor_preview_budget",480))))
    if len(parts)>_draw_budget:
        _stride=max(1,int(math.ceil(len(parts)/float(_draw_budget))));parts=parts[::_stride][:_draw_budget]
    s0 = float(_draw_em.get("size_start", 6)); s1 = float(_draw_em.get("size_end", 0))
    a0 = float(_draw_em.get("alpha_start", 1)); a1 = float(_draw_em.get("alpha_end", 0))
    _ell_active = (abs(float(_draw_em.get("ellipse_aspect", 1.0)) - 1.0) > 0.005
                   or abs(float(_draw_em.get("ellipse_aspect_end", 1.0)) - 1.0) > 0.005
                   or float(_draw_em.get("ellipse_osc", 0.0)) > 0.005)
    flag = {"add": pygame.BLEND_RGBA_ADD, "multiply": pygame.BLEND_RGBA_MULT,
            "screen": pygame.BLEND_RGBA_ADD}.get(str(_draw_em.get("blend", "normal")), 0)
    _layer_cache=modal.get("_pe_layer_cache")
    if not isinstance(_layer_cache,dict) or _layer_cache.get("size")!=inner.size:
        layer=pygame.Surface(inner.size,pygame.SRCALPHA)
        _layer_cache={"size":inner.size,"surface":layer};modal["_pe_layer_cache"]=_layer_cache
    else:
        layer=_layer_cache["surface"]
    layer.fill((0,0,0,0))
    for p in parts:
        t = p.get("t", 0.0)
        size = max(0.5, (s0 + (s1 - s0) * _pe_curve(t, _draw_em.get("size_curve", "linear"))) * zoom)
        # Match the live renderer: world scale and per-particle multipliers
        # (texture scale / size jitter) belong to the real size too, so the
        # preview shows what the arena will show.
        size *= pe_world_scale(_draw_em)
        if p.get("sz_mul"):
            size *= p["sz_mul"]
        if p.get("tex_scale"):
            size *= p["tex_scale"]
        alpha = max(0, min(255, int(255 * (a0 + (a1 - a0) *
                                          _pe_curve(t, _draw_em.get("alpha_curve", "linear"))))))
        alpha = int(alpha * max(0.0,min(1.0,float(p.get("tex_opacity",1.0)))))
        if alpha <= 0:
            continue
        col = pe_color_at(_draw_em, t)
        sx, sy = _to_scr(p["x"], p["y"])
        lx, ly = sx - inner.x, sy - inner.y
        if lx < -40 or ly < -40 or lx > inner.width + 40 or ly > inner.height + 40:
            continue
        mode = _draw_em.get("render", "circle")
        if mode == "slash":
            mode = "smear"
        # FIX: the preview used to fall through to a circle for sprite mode,
        # so picked sprites were invisible in the editor. Resolve the same
        # image the live renderer resolves (anim frames > per-particle
        # texture > emitter-wide sprite) and draw it.
        _pimg = None
        _aframes = _draw_em.get("anim_frames") or []
        if _aframes:
            # Use the exact same per-frame hold resolver as the live renderer,
            # including 0 = infinite hold / no loop.
            _fi = pe_anim_frame_index(_draw_em, p, time.time())
            _pimg = load_sprite_asset(_aframes[_fi])
        elif p.get("tex"):
            _pimg = load_sprite_asset(p["tex"])
        elif mode == "sprite":
            _pimg = load_sprite_asset(_draw_em.get("sprite"))
        if _pimg is not None:
            k = max(1, int(size * 2))
            img = _pe_scale_sprite(_pimg, k)
            if p.get("rot"):
                img = pygame.transform.rotate(img, p["rot"])
            img = img.copy()
            # Same tint rule as the live renderer: tint only when the
            # particle carries an explicit tint or there is no texture pool
