def draw_anim_state_timeline(mouse_pos):
    if modal.get("type") != "anim_state_timeline":
        return
    f = _UIFrame("_ast")
    machine = modal.setdefault("anim_machine", _anim_machine_default())

    if f.key_edge(pygame.K_ESCAPE):
        if modal.get("focus"):
            modal["focus"] = None
        else:
            _ast_close()
            return
    if f.key_edge(pygame.K_SPACE) and not modal.get("focus"):
        modal["_ast_play"] = not modal.get("_ast_play", False)
        modal["_ast_last"] = time.time()
    if not modal.get("focus"):
        _mods=pygame.key.get_mods();_ctrl=bool(_mods&(pygame.KMOD_CTRL|pygame.KMOD_META));_shift=bool(_mods&pygame.KMOD_SHIFT)
        if _ctrl and f.key_edge(pygame.K_z):_ast_redo() if _shift else _ast_undo()
        elif _ctrl and f.key_edge(pygame.K_y):_ast_redo()
        else:
            _kst=modal.get("_ast_sel_state","idle");_ktr=_ast_selected_track(_kst);_klid=-1 if (_ktr or {}).get("__classic__") else (_ktr or {}).get("id");_kfi=int(modal.get("_ast_sel_frame",0));_kframes=(_ktr or {}).get("frames",[])
            if _ctrl and f.key_edge(pygame.K_d):_ast_duplicate_frame(_kst,_klid,_kfi)
            elif _ctrl and f.key_edge(pygame.K_c):_ast_copy_frame(_kst,_klid,_kfi)
            elif _ctrl and f.key_edge(pygame.K_v):_ast_paste_frame(_kst,_klid,_kfi)
            elif f.key_edge(pygame.K_DELETE) or f.key_edge(pygame.K_BACKSPACE):_ast_remove_frame(_kst,_klid,_kfi)
            elif f.key_edge(pygame.K_HOME) and _kframes:modal["_ast_sel_frame"]=0
            elif f.key_edge(pygame.K_END) and _kframes:modal["_ast_sel_frame"]=len(_kframes)-1
            elif f.key_edge(pygame.K_LEFT) and _kframes:
                if _shift and _kfi>0:_ast_push_undo("Move frame left");_ast_move_frame(_kst,_klid,_kfi,_kfi-1)
                else:modal["_ast_sel_frame"]=max(0,_kfi-1)
            elif f.key_edge(pygame.K_RIGHT) and _kframes:
                if _shift and _kfi<len(_kframes)-1:_ast_push_undo("Move frame right");_ast_move_frame(_kst,_klid,_kfi,_kfi+1)
                else:modal["_ast_sel_frame"]=min(len(_kframes)-1,_kfi+1)

    panel = pygame.Rect(14, 12, WIDTH - 28, HEIGHT - 24)
    draw_panel(panel, alpha=252, radius=12, shadow=False)
    close_r = ui_panel_header(panel, "Animation Editor", "", icon="timeline")
    if ui_close_button(f, close_r):
        _ast_close()
        return

    view = modal.get("_ast_view", "timeline")
    bx = panel.x + 196
    for _i,(_vk,_vl,_vi) in enumerate((("timeline","Timeline","timeline"),("markers","Markers","crosshair"),("collision","Collision","shield"),("machine","Transitions","sitemap"))):
        if ui_button(f,pygame.Rect(bx+_i*88,panel.y+10,84,26),_vl,active=view==_vk,icon=_vi):
            modal["_ast_view"]=view=_vk;modal["_ast_iscroll"]=0.0
            if _vk=="collision" and modal.get("_ast_sel_layer") is not None:modal["_ast_auto_collision_layer"]=modal.get("_ast_sel_layer")

    state = modal.get("_ast_sel_state", "idle")
    if state not in _ast_states():
        state = (_ast_states() or ["idle"])[0]
        modal["_ast_sel_state"] = state

    # Old states (and any track someone never converted) were stuck on the
    # flat classic frame list, which has no gizmo -- only slider offsets.
    # Auto-upgrade to the layer system the moment the editor is open so
    # every keyframe, old or new, gets full move/rotate/scale control.
    if not anim_state_has_layers(state) and _ast_state_frames(state):
        anim_promote_state_to_layers(state)

    # ---- import buttons, always available here ----
    ix = bx + 360
    if ui_button(f, pygame.Rect(ix, panel.y + 10, 96, 26), "Sheet", icon="grid",
                 tooltip="Slice a sprite sheet into frames for this state"):
        _ast_push_undo("Import sprite sheet");modal["_shx_states"] = True
        open_sheet_extractor("anim_state_timeline", target=("anim_state", state))
        return
    if ui_button(f, pygame.Rect(ix + 100, panel.y + 10, 84, 26), "GIF", icon="motion",
                 tooltip="Convert a GIF into frames for this state"):
        _ast_push_undo("Import GIF");open_gif_importer("anim_state_timeline", target=("anim_state", state))
        return
    if ui_button(f, pygame.Rect(ix + 188, panel.y + 10, 84, 26), "PNG", icon="import_",
                 tooltip="Pick a PNG from your asset library for this state (the library's Import button brings in new files)"):
        def _ast_png_pick(rel, _st=state):
            if not rel:
                return
            _ast_push_undo("Import PNG frame")
            sel = _ast_selected_track(_st)
            if sel is not None and not sel.get("__classic__"):
                # A real layer is already selected: drop the image in there.
                sel.setdefault("frames", []).append(rel)
                modal["_ast_sel_layer"] = sel.get("id")
            else:
                # No layer selected (fresh/classic state): promote to the
                # layer system so this image gets full move/scale/rotate
                # gizmo control instead of the old flat, static frame list.
                anim_promote_state_to_layers(_st)
                layer = anim_add_layer(_st, "Layer")
                layer["frames"].append(rel)
                modal["_ast_sel_layer"] = layer["id"]
            modal["_ast_sel_frame"] = 0
            modal.setdefault("_ast_stage_ref_cache", {}).pop(_st, None)
            push_toast(f"Frame added: {os.path.basename(rel)}", "success", 1.8)
        open_asset_library(tab="sprites", pick_callback=_ast_png_pick,
                           return_to="anim_state_timeline")

    insp_on = modal.get("_ast_insp", True)
    if ui_button(f, pygame.Rect(panel.right-250,panel.y+10,28,26),"",icon="undo",disabled=not modal.get("_ast_undo"),tooltip="Undo · Ctrl+Z"):_ast_undo()
    if ui_button(f, pygame.Rect(panel.right-218,panel.y+10,28,26),"",icon="redo",disabled=not modal.get("_ast_redo"),tooltip="Redo · Ctrl+Y"):_ast_redo()
    if ui_button(f,pygame.Rect(panel.right-184,panel.y+10,28,26),"",icon="help",active=modal.get("_ast_help",False),tooltip="Animation Editor upgrades & shortcuts"):modal["_ast_help"]=not modal.get("_ast_help",False)
    if ui_button(f, pygame.Rect(panel.right - 150, panel.y + 10, 96, 26),
                 "Inspector", active=insp_on, icon="settings",
                 tooltip="Show / hide the properties column"):
        modal["_ast_insp"] = not insp_on
        insp_on = modal["_ast_insp"]

    # ---- playback clock ----
    total = max(0.05, _ast_state_length(state))
    if modal.get("_ast_play"):
        now = time.time()
        st_def = machine.get("states", {}).get(state, {})
        speed = max(0.05, float(st_def.get("speed", 1.0)))
        modal["_ast_t"] = float(modal.get("_ast_t", 0.0)) + (now - float(modal.get("_ast_last", now))) * speed
        modal["_ast_last"] = now
        if modal["_ast_t"] > total:
            modal["_ast_t"] = 0.0 if st_def.get("loop", True) else total
    else:
        modal["_ast_last"] = time.time()

    body = pygame.Rect(panel.x + 6, panel.y + 40, panel.width - 12, panel.height - 78)
    side_w = 232 if insp_on else 0
    # Bigger canvas (preview) for positioning art; dope sheet slimmed, inspector
    # narrowed, so the stage -- where you drag/offset frames -- gets the room.
    sheet_h = max(150, int(body.height * 0.28))
    top = pygame.Rect(body.x, body.y, body.width - (side_w + 6 if insp_on else 0),
                      body.height - sheet_h - 6)
    side = pygame.Rect(top.right + 6, body.y, side_w, body.height) if insp_on else None
    sheet = pygame.Rect(body.x, top.bottom + 6,
                        body.width - (side_w + 6 if insp_on else 0), sheet_h)

    if view in ("timeline","markers","collision"):
        _ast_draw_preview(f,top,state,machine);_ast_draw_dope(f,sheet,state,machine)
    else:_ast_draw_machine(f,pygame.Rect(body.x,body.y,top.width,body.height),machine)
    if side is not None:
        _ic_h=1050 if modal.get("_ast_view")=="machine" else 1250;_imax=max(0.0,_ic_h-side.height);_isc=max(0.0,min(_imax,float(modal.get("_ast_iscroll",0.0))));modal["_ast_iscroll"]=_isc;modal["_ast_iscroll_max"]=_imax;modal["_ast_insp_rect"]=side
        ui_draw_rect(screen,PANEL_BG,side,border_radius=10);_old_clip=screen.get_clip();screen.set_clip(side);_shift=pygame.Rect(side.x,side.y-int(_isc),side.width,_ic_h);_ast_draw_inspector(f,_shift,machine);screen.set_clip(_old_clip)
        if _ic_h>side.height:_sb,_isc2=draw_scrollbar(side,_isc,_ic_h,side.height,mouse_pos,_key="ast-inspector");modal["_ast_iscroll"]=_isc2

    # ---- footer ----
    fy = panel.bottom - 38
    if ui_button(f, pygame.Rect(panel.x + 14, fy, 74, 26),
                 "Pause" if modal.get("_ast_play") else "Play",
                 icon="pause" if modal.get("_ast_play") else "play",
                 active=modal.get("_ast_play", False)):
        modal["_ast_play"] = not modal.get("_ast_play", False)
        modal["_ast_last"] = time.time()
    if ui_button(f, pygame.Rect(panel.x + 94, fy, 62, 26), "Rewind", icon="skip_back"):
        modal["_ast_t"] = 0.0
    modal["_ast_zoom"] = ui_slider(
        f, pygame.Rect(panel.x + 176, fy + 13, 150, 11), "ast_zoom", "Zoom",
        float(modal.get("_ast_zoom", 260.0)), 40.0, 1200.0,
        lambda v: modal.__setitem__("_ast_zoom", v), "{:.0f}px/s")
    screen.blit(font_tiny.render(f"{modal.get('_ast_t',0):.2f}s / {total:.2f}s",True,TEXT_DIM),(panel.x+344,fy+8))
    _trk=_ast_selected_track(state);_frs=(_trk or {}).get("frames",[]);_fi=int(modal.get("_ast_sel_frame",0));_fx=panel.x+465
    for _lab,_delta,_tip in (("|<","first","First frame"),("<",-1,"Previous frame"),(">",1,"Next frame"),(">|","last","Last frame")):
        if ui_button(f,pygame.Rect(_fx,fy,34,26),_lab,disabled=not _frs,tooltip=_tip):
            if _delta=="first":modal["_ast_sel_frame"]=0
            elif _delta=="last":modal["_ast_sel_frame"]=max(0,len(_frs)-1)
            else:modal["_ast_sel_frame"]=max(0,min(len(_frs)-1,_fi+_delta))
            modal["_ast_play"]=False
        _fx+=37

    _pick_mode=isinstance(modal.get("_ast_pick_context"),dict)
    if ui_button(f,pygame.Rect(panel.right-150 if _pick_mode else panel.right-118,fy,136 if _pick_mode else 104,26),"Use This State" if _pick_mode else "Done",active=True,icon="check",small=False):
        if _pick_mode:_ast_use_picked_state()
        else:_ast_close()
        return
    if modal.get("_ast_help"):
        ov=pygame.Surface((WIDTH,HEIGHT),pygame.SRCALPHA);ov.fill((0,0,0,175));screen.blit(ov,(0,0));hp=pygame.Rect(max(20,WIDTH//2-430),max(20,HEIGHT//2-280),min(860,WIDTH-40),min(560,HEIGHT-40));draw_panel(hp,alpha=255,radius=14,shadow=False,opaque=True);ui_draw_rect(screen,ACCENT,hp,1,14)
        screen.blit(font_lg.render(f"ANIMATION EDITOR · {len(_AST_UPGRADES)} WORKFLOW UPGRADES",True,TEXT_MAIN),(hp.x+20,hp.y+16));screen.blit(font_tiny.render("Frame ordering, pivots, layered bounds, collision sync, editing and navigation",True,TEXT_DIM),(hp.x+20,hp.y+46))
        closeh=pygame.Rect(hp.right-42,hp.y+14,26,26)
        if ui_button(f,closeh,"×",danger=True):modal["_ast_help"]=False
        cols=3;per=(len(_AST_UPGRADES)+cols-1)//cols;cw=(hp.width-50)//cols
        for i,text in enumerate(_AST_UPGRADES):
            col=i//per;row=i%per;yy=hp.y+76+row*18
            if yy>hp.bottom-20:continue
            num=i+1;screen.blit(font_tiny.render(f"{num:02d}",True,ACCENT),(hp.x+20+col*cw,yy));screen.blit(font_tiny.render(truncate_text_to_width(font_tiny,text,cw-42),True,TEXT_MAIN),(hp.x+48+col*cw,yy))
    _ast_draw_position_ease_picker(f)
    if float(modal.get("_ast_autosave_due",0) or 0)>0 and time.monotonic()>=float(modal.get("_ast_autosave_due",0)):_ast_commit_character_animation_context(True)
    ui_flush_tooltips()

def _ast_selected_track(state):
    lid = modal.get("_ast_sel_layer")
    if lid is None:
        tracks = _ast_tracks(state)
        return tracks[0] if tracks else None
    return anim_layer_by_id(state, lid)

def _ast_draw_preview(f, rect, state, machine):
    """Big composited preview + a state rail so switching states is one click."""
    ui_draw_rect(screen, (11, 11, 15), rect, border_radius=10)
    ui_draw_rect(screen, FIELD_FOCUS, rect, width=1, border_radius=10)

    rail_w = 104
    rail = pygame.Rect(rect.x + 5, rect.y + 5, rail_w, rect.height - 10)
    ui_draw_rect(screen, APP_BG, rail, border_radius=8)
    screen.blit(font_tiny.render("STATES", True, TEXT_FAINT), (rail.x + 8, rail.y + 6))
    if ui_button(f, pygame.Rect(rail.right - 28, rail.y + 3, 22, 19), "",
                 icon="plus", tooltip="New animation state"):
        _ast_prompt_new_state(machine)

    clip_prev = screen.get_clip()
    screen.set_clip(rail)
    ry = rail.y + 24 - int(modal.get("_ast_srail", 0.0))
    for name in _ast_states():
        row = pygame.Rect(rail.x + 4, ry, rail.width - 12, 26)
        if row.bottom > rail.y and row.y < rail.bottom:
            sel = (name == state)
            hov = f.hit(row, rail)
            ui_draw_rect(screen, (32, 28, 52) if sel else ((21, 21, 27) if hov else (13, 13, 17)),
                             row, border_radius=5)
            if sel:
                ui_draw_rect(screen, ACCENT, row, width=1, border_radius=5)
            lbl = truncate_text_to_width(font_sm, name, row.width - 32)
            screen.blit(font_sm.render(lbl, True, TEXT_MAIN if sel else TEXT_DIM),
                        (row.x + 7, row.y + 4))
            if machine.get("entry") == name:
                screen.blit(font_tiny.render("E", True, GOOD), (row.right - 14, row.y + 6))
            nl=len(anim_layers(name));_sprite_only=name in (modal.get("sprite_map",{}) or {}) and not nl and not _ast_state_frames(name)
            if nl:screen.blit(font_tiny.render(str(nl),True,(110,150,220)),(row.right-26,row.y+7))
            elif _sprite_only:screen.blit(font_tiny.render("S",True,(115,255,155)),(row.right-26,row.y+7))
            if f.click(row, rail):
                modal["_ast_sel_state"] = name
                modal["animation_state"] = name
                modal["_ast_sel_layer"] = None
                modal["_ast_t"] = 0.0
        ry += 28
    screen.set_clip(clip_prev)
    ui_scroll_apply(f, "_ast_srail", rail, len(_ast_states()) * 28 + 30, rail.height)

    # -- stage --
    stage = pygame.Rect(rail.right + 6, rect.y + 5, rect.right - rail.right - 11, rect.height - 10)
    ui_draw_rect(screen, (7, 7, 10), stage, border_radius=8)
    screen.set_clip(stage)
    grid = 16
    for gx in range(stage.x, stage.right, grid):
        pygame.draw.line(screen, (15, 15, 20), (gx, stage.y), (gx, stage.bottom), 1)
    for gy in range(stage.y, stage.bottom, grid):
        pygame.draw.line(screen, (15, 15, 20), (stage.x, gy), (stage.right, gy), 1)
    pygame.draw.line(screen, (28, 26, 40), (stage.centerx, stage.y), (stage.centerx, stage.bottom), 1)
    pygame.draw.line(screen, (28, 26, 40), (stage.x, stage.centery), (stage.right, stage.centery), 1)

    _on = bool(modal.get("_ast_onion", False));_pedit=bool(modal.get("_ast_pivot_edit",False));_cprev=bool(modal.get("_ast_collision_preview",True));_sref=bool(modal.get("_ast_sprite_state_onion",False))
    _ref_path=(modal.get("sprite_map",{}) or {}).get(state) or (modal.get("sprite_map",{}) or {}).get("idle")
    if ui_button(f,pygame.Rect(stage.x+8,stage.y+6,104,20),"State Onion",active=_sref,icon="onion",disabled=not _ref_path,tooltip="Overlay the character's static Sprite State at the exact same pixel scale"):
        modal["_ast_sprite_state_onion"]=not _sref
    if modal.get("_ast_view")=="markers" and ui_button(f,pygame.Rect(stage.x+116,stage.y+6,104,20),"+ Position",icon="crosshair",tooltip="Add a manual position event animated per frame"):
        _ast_push_undo("Add animation position event");_ast_add_position_event(state);modal["_ast_play"]=False
    if modal.get("_ast_view")=="collision" and ui_button(f,pygame.Rect(stage.x+116,stage.y+6,112,20),"+ Collision",icon="shield",tooltip="Add an editable collision box on the selected animation frame"):
        _ast_push_undo("Add animation collision frame");_ast_add_collision_box(state,max(0,int(modal.get("_ast_sel_frame",0))));modal["_ast_play"]=False
    _tbx=stage.right-330
    if ui_button(f,pygame.Rect(_tbx,stage.y+6,62,20),"100%",icon="frame",tooltip="Reset preview zoom"):modal["_ast_zoom_lvl"]=1.0
