    if modal.get("_ast_onion",False):
        _ob=max(0,min(8,int(modal.get("_ast_onion_before",2))));_oa=max(0,min(8,int(modal.get("_ast_onion_after",1))));_oo=max(15,min(180,int(modal.get("_ast_onion_alpha",72))));_oy=stage.y+30;_ox=stage.right-330
        screen.blit(font_tiny.render("BLUE PREVIOUS",True,(90,180,255)),(_ox,_oy+5))
        for _lab,_delta in (("−",-1),("+",1)):
            _r=pygame.Rect(_ox+86+(_delta>0)*24,_oy,22,20)
            if ui_button(f,_r,_lab):modal["_ast_onion_before"]=max(0,min(8,_ob+_delta))
        screen.blit(font_tiny.render(str(_ob),True,TEXT_MAIN),(_ox+135,_oy+5));_ox+=158
        screen.blit(font_tiny.render("PINK NEXT",True,(255,110,180)),(_ox,_oy+5))
        for _lab,_delta in (("−",-1),("+",1)):
            _r=pygame.Rect(_ox+68+(_delta>0)*24,_oy,22,20)
            if ui_button(f,_r,_lab):modal["_ast_onion_after"]=max(0,min(8,_oa+_delta))
        screen.blit(font_tiny.render(str(_oa),True,TEXT_MAIN),(_ox+117,_oy+5))

    t = float(modal.get("_ast_t", 0.0))
    img = None
    if anim_state_has_layers(state):
        img = anim_composite_state(state, t)
    else:
        frames = _ast_state_frames(state)
        durs = _ast_state_durations(state)
        if frames:
            total = max(0.02, sum(max(0.02, d) for d in durs))
            lt = t % total
            acc = 0.0
            idx = len(frames) - 1
