def _ast_stage_ref_size(state):
    """A stable 'neutral' footprint for a state's art, ignoring whatever
    the currently selected layer's live scale/offset/rotation happen to
    be, so the stage's fit-to-view never jitters while you edit."""
    cache = modal.setdefault("_ast_stage_ref_cache", {})
    cached = cache.get(state)
    if cached:
        return cached
    w = h = 96
    layers = anim_layers(state) or []
    found = False
    for l in layers:
        for _fi,_path in enumerate(l.get("frames",[])):
            img0=load_sprite_asset(_path)
            if img0:
                w=max(w,img0.get_width());h=max(h,img0.get_height());found=True
    if not found:
        for _path in _ast_state_frames(state):
            img0=load_sprite_asset(_path)
            if img0:w=max(w,img0.get_width());h=max(h,img0.get_height())
    cache[state] = (w, h)
    return (w, h)

def _ast_draw_layer_gizmo(stage, state, fit, t):
    """Move / rotate / scale the selected layer's current frame right on
    the stage -- the same freedom Motion Studio gives motion-clip sprites.
    Drag the body to move, the top handle to rotate, the corner square to
    scale. Only applies to real layers (the auto-promoted PNG track), not
    the legacy flat classic frame list."""
    global left_click_this_frame
    track = _ast_selected_track(state)
    if track is None or track.get("__classic__") or track.get("locked"):
        return
    frames = track.get("frames", [])
    idx = anim_layer_frame_at(state, track, t)
    if idx is None or not (0 <= idx < len(frames)):
        return
    base_img = load_sprite_asset(frames[idx])
    if base_img is None:
        return

    base_off=track.setdefault("offset",[0.0,0.0]);ft=anim_layer_frame_transform(track,idx);frame_off=ft.setdefault("offset",[0.0,0.0]);off=[float(base_off[0])+float(frame_off[0]),float(base_off[1])+float(frame_off[1])]
    base_sc=float(track.get("scale",1.0) or 1.0);frame_sc=float(ft.get("scale",1.0) or 1.0);sc=base_sc*frame_sc
    base_rot=float(track.get("rot",0.0) or 0.0);frame_rot=float(ft.get("rot",0.0) or 0.0);rot=base_rot+frame_rot
    _piv=_ast_state_pivot(state)
    cx = stage.centerx + (off[0]-float(_piv[0])) * fit
    cy = stage.centery + (off[1]-float(_piv[1])) * fit
    hw = max(2.0, base_img.get_width() * sc * fit * 0.5)
    hh = max(2.0, base_img.get_height() * sc * fit * 0.5)
    rad = math.radians(rot)
    cos_r, sin_r = math.cos(rad), math.sin(rad)

    def _pt(dx, dy):
        return (cx + dx * cos_r - dy * sin_r, cy + dx * sin_r + dy * cos_r)

    corners = [_pt(-hw, -hh), _pt(hw, -hh), _pt(hw, hh), _pt(-hw, hh)]
    rot_handle = _pt(0, -hh - 26)
    scale_handle = corners[2]
    drag = modal.get("_ast_gz_drag")
    active_kind = drag["kind"] if drag else None

    # Soft fill + glow so the box reads clearly over busy art.
    _fill = pygame.Surface((stage.width, stage.height), pygame.SRCALPHA)
    _fill_local = [(p[0] - stage.x, p[1] - stage.y) for p in corners]
    pygame.draw.polygon(_fill, (*ACCENT, 26), _fill_local)
    screen.blit(_fill, stage.topleft)
    pygame.draw.polygon(screen, (60, 50, 110), corners, width=4)
    pygame.draw.polygon(screen, (185, 165, 255) if active_kind == "move" else ACCENT, corners, width=2)

    # Corner handles (small filled diamonds) -- only the bottom-right is
    # interactive (scale), the others are visual anchors like Animate's box.
    for i, c in enumerate(corners):
        is_scale = (i == 2)
        col = (255, 210, 120) if (is_scale and active_kind != "rot") else (150, 145, 175)
        r = 6 if is_scale else 4
        pygame.draw.circle(screen, (10, 10, 14), (int(c[0]), int(c[1])), r + 1)
        pygame.draw.circle(screen, col, (int(c[0]), int(c[1])), r)

    # Rotate handle: stem + a ringed knob with a little orbit arc so it
    # reads as "rotate" rather than just another dot.
    stem_top = _pt(0, -hh)
    pygame.draw.line(screen, (90, 80, 130), stem_top, rot_handle, 2)
    _rh = (int(rot_handle[0]), int(rot_handle[1]))
    pygame.draw.circle(screen, (10, 10, 14), _rh, 9)
    pygame.draw.circle(screen, (150, 225, 255) if active_kind != "scale" else (90, 130, 150), _rh, 8)
    _arc_rect = pygame.Rect(_rh[0] - 12, _rh[1] - 12, 24, 24)
    pygame.draw.arc(screen, (10, 10, 14), _arc_rect, 0.6, 2.6, 2)

    # Center cross so "move" has an obvious grab point even on odd shapes.
    pygame.draw.line(screen, (230, 225, 245), (cx - 6, cy), (cx + 6, cy), 1)
    pygame.draw.line(screen, (230, 225, 245), (cx, cy - 6), (cx, cy + 6), 1)

    if active_kind:
        if active_kind == "rot":
            _label = f"frame {frame_rot:.0f}° · total {rot:.0f}°"
        elif active_kind == "scale":
            _label = f"frame {frame_sc:.2f}x · total {sc:.2f}x"
        else:
            _label = f"frame {frame_off[0]:.0f}, {frame_off[1]:.0f}"
        _lb = font_sm.render(_label, True, (10, 10, 14))
        _bg = pygame.Rect(0, 0, _lb.get_width() + 10, _lb.get_height() + 6)
        _bg.center = (int(cx), int(cy - hh - 44))
        ui_draw_rect(screen, (150, 225, 255), _bg, border_radius=5)
        screen.blit(_lb, (_bg.x + 5, _bg.y + 3))

    mouse_pos = pygame.mouse.get_pos()
    lmb = pygame.mouse.get_pressed()[0]

    if not lmb:
        if drag is not None:
            modal["_ast_gz_drag"] = None
        return

    if drag is None:
        if not left_click_this_frame or not stage.collidepoint(mouse_pos):
            return
        if math.hypot(mouse_pos[0] - rot_handle[0], mouse_pos[1] - rot_handle[1]) <= 9:
            _ast_push_undo("Rotate animation keyframe");modal["_ast_gz_drag"] = {
                "kind": "rot", "start_rot": frame_rot,
                "start_mouse_ang": math.degrees(math.atan2(mouse_pos[1] - cy, mouse_pos[0] - cx)),
            }
            left_click_this_frame = False
        elif math.hypot(mouse_pos[0] - scale_handle[0], mouse_pos[1] - scale_handle[1]) <= 9:
            _ast_push_undo("Scale animation keyframe");modal["_ast_gz_drag"] = {"kind": "scale", "start_scale": frame_sc,
                                     "ref_diag": max(1.0, math.hypot(hw, hh))}
            left_click_this_frame = False
        else:
            dx, dy = mouse_pos[0] - cx, mouse_pos[1] - cy
            lx = dx * cos_r + dy * sin_r
            ly = -dx * sin_r + dy * cos_r
            if abs(lx) <= hw and abs(ly) <= hh:
                _ast_push_undo("Move animation keyframe");modal["_ast_gz_drag"] = {"kind": "move", "start_mouse": mouse_pos,
                                         "start_off": [float(frame_off[0]),float(frame_off[1])]}
                left_click_this_frame = False
        return

    if drag["kind"] == "move":
        frame_off[0] = drag["start_off"][0] + (mouse_pos[0] - drag["start_mouse"][0]) / fit
        frame_off[1] = drag["start_off"][1] + (mouse_pos[1] - drag["start_mouse"][1]) / fit
        if modal.get("_ast_snap",True):frame_off[0]=round(frame_off[0]);frame_off[1]=round(frame_off[1])
    elif drag["kind"] == "rot":
        ang = math.degrees(math.atan2(mouse_pos[1] - cy, mouse_pos[0] - cx))
        ft["rot"] = drag["start_rot"] + (ang - drag["start_mouse_ang"])
    elif drag["kind"] == "scale":
        d = math.hypot(mouse_pos[0] - cx, mouse_pos[1] - cy)
        ft["scale"] = max(0.05,min(8.0,drag["start_scale"]*(d/max(1e-6,drag["ref_diag"]))))

def _ast_draw_dope(f, rect, state, machine):
    """Dope sheet: one row per layer of the SELECTED state."""
    ui_draw_rect(screen, (11, 11, 15), rect, border_radius=10)
    ui_draw_rect(screen, FIELD_FOCUS, rect, width=1, border_radius=10)

    hdr = pygame.Rect(rect.x + 8, rect.y + 6, rect.width - 16, 22)
    screen.blit(font_tiny.render(f"LAYERS — {state}", True, TEXT_FAINT), (hdr.x + 4, hdr.y + 5))
    _hdr_track=_ast_selected_track(state);_hdr_lid=-1 if (_hdr_track or {}).get("__classic__") else (_hdr_track or {}).get("id");_hdr_fi=int(modal.get("_ast_sel_frame",0));_hdr_frames=(_hdr_track or {}).get("frames",[])
    if ui_button(f,pygame.Rect(hdr.right-290,hdr.y,92,20),"Delete Frame",icon="delete",danger=True,disabled=not _hdr_frames):_ast_remove_frame(state,_hdr_lid,_hdr_fi)
    if ui_button(f,pygame.Rect(hdr.right-194,hdr.y,102,20),"Delete Layer",icon="delete",danger=True,disabled=_hdr_lid in (-1,None)):
        _ast_push_undo("Delete layer");anim_remove_layer(state,_hdr_lid);modal["_ast_sel_layer"]=None;modal["_ast_sel_frame"]=0
    if ui_button(f, pygame.Rect(hdr.right - 88, hdr.y, 86, 20), "+ Layer", icon="plus",
                 active=True, tooltip="Add another track to this state"):
        if not anim_state_has_layers(state):
            anim_promote_state_to_layers(state)
