def _ast_draw_machine(f, rect, machine):
    ui_draw_rect(screen, (11, 11, 15), rect, border_radius=10)
    ui_draw_rect(screen, FIELD_FOCUS, rect, width=1, border_radius=10)
    screen.blit(font_tiny.render("TRANSITIONS  ·  highest-priority match wins",
                                 True, TEXT_FAINT), (rect.x + 12, rect.y + 8))
    if ui_button(f, pygame.Rect(rect.right - 116, rect.y + 22, 104, 24),
                 "+ Transition", icon="plus", active=True):
        states = _ast_states()
        src = modal.get("_ast_sel_state") or (states[0] if states else "idle")
        dst = next((s for s in states if s != src), src)
        tr = anim_machine_add_transition(machine, src, dst, "always")
        modal["_ast_sel_tr"] = tr["id"]

    hdr = rect.y + 52
    for label, off in (("FROM", 12), ("TO", 130), ("WHEN", 248), ("VALUE", 380)):
        screen.blit(font_tiny.render(label, True, (70, 68, 88)), (rect.x + off, hdr))
    pygame.draw.line(screen, PANEL_BG_ALT, (rect.x + 10, hdr + 15), (rect.right - 10, hdr + 15), 1)

    list_r = pygame.Rect(rect.x + 6, hdr + 20, rect.width - 12, rect.bottom - hdr - 28)
    clip_prev = screen.get_clip()
    screen.set_clip(list_r)
    trs = machine.get("transitions", [])
    y = list_r.y + 2 - int(modal.get("_ast_mscroll", 0.0))
    sel_tr = modal.get("_ast_sel_tr")
    for tr in list(trs):
        row = pygame.Rect(list_r.x + 2, y, list_r.width - 8, 30)
        if row.bottom > list_r.y and row.y < list_r.bottom:
            is_sel = tr.get("id") == sel_tr
            hov = f.hit(row, list_r)
            enabled = tr.get("enabled", True)
            ui_draw_rect(screen, (30, 28, 50) if is_sel else ((22, 22, 28) if hov else (15, 15, 19)),
                             row, border_radius=6)
            if is_sel:
                ui_draw_rect(screen, ACCENT, row, width=1, border_radius=6)
            col = TEXT_MAIN if enabled else (86, 84, 100)
            screen.blit(font_sm.render(truncate_text_to_width(font_sm, str(tr.get("from")), 108),
                                       True, col), (row.x + 8, row.y + 6))
            ar = get_icon_fs("forward", 12, TEXT_FAINT)
            if ar:
                screen.blit(ar, (row.x + 112, row.y + 9))
            screen.blit(font_sm.render(truncate_text_to_width(font_sm, str(tr.get("to")), 108),
                                       True, col), (row.x + 126, row.y + 6))
            cond = ANIM_CONDITION_LABELS.get(str(tr.get("condition")), "Always")
            screen.blit(font_tiny.render(cond, True, GOOD if enabled else (70, 90, 76)),
                        (row.x + 244, row.y + 9))
            val = str(tr.get("value") or "")
            if not val and tr.get("condition") in ("hp_below", "hp_above", "moving", "idle"):
                val = f"{float(tr.get('threshold', 0)):g}"
            if val:
                screen.blit(font_tiny.render(truncate_text_to_width(font_tiny, val, 90),
                                             True, TEXT_DIM), (row.x + 376, row.y + 9))
            if ui_button(f, pygame.Rect(row.right - 52, row.y + 5, 20, 20), "",
                         icon="eye" if enabled else "eye_off", clip=list_r):
                tr["enabled"] = not enabled
            if ui_button(f, pygame.Rect(row.right - 28, row.y + 5, 20, 20), "",
                         icon="delete", danger=True, clip=list_r):
                anim_machine_remove_transition(machine, tr.get("id"))
                if sel_tr == tr.get("id"):
                    modal["_ast_sel_tr"] = None
                break
            if f.click(row.inflate(-60, 0), list_r):
                modal["_ast_sel_tr"] = tr.get("id")
        y += 32
    if not trs:
        screen.set_clip(clip_prev)
        ui_empty_state(list_r, "No transitions yet",
                       "Add one so a state switches on its own —\ne.g. idle → walk 'Is Moving'.",
                       "sitemap")
    screen.set_clip(clip_prev)
    ui_scroll_apply(f, "_ast_mscroll", list_r, len(trs) * 32 + 6, list_r.height)

def _ast_draw_inspector(f, rect, machine):
    ui_draw_rect(screen, PANEL_BG, rect, border_radius=10)
    ui_draw_rect(screen, FIELD_FOCUS, rect, width=1, border_radius=10)

    if modal.get("_ast_view") == "machine" and modal.get("_ast_sel_tr") is not None:
        _ast_inspect_transition(f, rect, machine)
        return

    state = modal.get("_ast_sel_state", "idle")
    st = machine.setdefault("states", {}).setdefault(state, _anim_state_default(state))
    track = _ast_selected_track(state)

    screen.blit(font_tiny.render("STATE", True, TEXT_FAINT), (rect.x + 12, rect.y + 8))
    screen.blit(font_lg.render(truncate_text_to_width(font_lg, str(state), rect.width - 28),
                               True, TEXT_MAIN), (rect.x + 12, rect.y + 19))
    y = rect.y + 50

    if ui_button(f, pygame.Rect(rect.x + 12, y, 68, 22), "Rename", icon="rename"):
        _ast_prompt_rename(machine, state)
    if ui_button(f, pygame.Rect(rect.x + 86, y, 62, 22), "Delete", danger=True, icon="delete",
                 disabled=(len(_ast_states()) <= 1)):
        _ast_push_undo("Delete animation state");anim_machine_remove_state(machine, state)
        modal.get("animation_frames", {}).pop(state, None)
        modal.get("animation_layers", {}).pop(state, None)
        for _map in ("animation_durations","animation_fps","animation_pivots","animation_position_events","animation_collision_frames","animation_anchors","animation_frame_offsets"):
            modal.get(_map,{}).pop(state,None)
        modal["_ast_sel_state"] = (_ast_states() or ["idle"])[0]
        return
    entry = machine.get("entry") == state
    if ui_button(f, pygame.Rect(rect.x + 154, y, 76, 22), "Entry", active=entry,
                 tooltip="Characters start in this state"):
        machine["entry"] = state
    y += 28

    loop = ui_checkbox(f, pygame.Rect(rect.x + 12, y, 84, 18), "Loop", st.get("loop", True))
    st["loop"] = loop
    mir = ui_checkbox(f, pygame.Rect(rect.x + 104, y, 96, 18), "Mirror X", st.get("mirror", False))
    st["mirror"] = mir
    y += 24

    half = (rect.width - 32) // 2
    ui_slider(f, pygame.Rect(rect.x + 12, y + 11, half, 11), "ast_speed", "Speed",
              float(st.get("speed", 1.0)), 0.1, 4.0,
              lambda v: st.__setitem__("speed", v), "{:.2f}x")
    ui_slider(f, pygame.Rect(rect.x + 20 + half, y + 11, half, 11), "ast_fps", "FPS",
              float(modal.setdefault("animation_fps", {}).get(state, 6.0) or 6.0), 0.5, 60.0,
              lambda v: modal.setdefault("animation_fps", {}).__setitem__(state, v), "{:.1f}")
    y += 30
    ui_slider(f, pygame.Rect(rect.x + 12, y + 11, rect.width - 24, 11), "ast_prio",
              "Priority", float(st.get("priority", 0)), -10, 10,
              lambda v: st.__setitem__("priority", int(v)), "{:.0f}", step=1)
    y += 30
    _piv=_ast_state_pivot(state)
    screen.blit(font_tiny.render("ANIMATION PIVOT · aligned to character center",True,TEXT_FAINT),(rect.x+12,y));y+=15
    ui_slider(f,pygame.Rect(rect.x+12,y+11,half,11),"ast_pvx","Pivot X",float(_piv[0]),-512,512,lambda v:_piv.__setitem__(0,round(v)),"{:.0f}px")
    ui_slider(f,pygame.Rect(rect.x+20+half,y+11,half,11),"ast_pvy","Pivot Y",float(_piv[1]),-512,512,lambda v:_piv.__setitem__(1,round(v)),"{:.0f}px");y+=28
    modal["_ast_snap"]=ui_checkbox(f,pygame.Rect(rect.x+12,y,88,18),"Pixel Snap",modal.get("_ast_snap",True))
    if ui_button(f,pygame.Rect(rect.x+108,y-2,118,20),"Edit on Stage",active=modal.get("_ast_pivot_edit",False),icon="crosshair"):modal["_ast_pivot_edit"]=not modal.get("_ast_pivot_edit",False)
    y+=24

    _manager_view=modal.get("_ast_view","timeline")
    if _manager_view=="markers":
        pygame.draw.line(screen,PANEL_BG_ALT,(rect.x+10,y),(rect.right-10,y),1);y+=7
        screen.blit(font_tiny.render("MANUAL POSITION EVENTS",True,TEXT_FAINT),(rect.x+12,y));y+=15
        _events=_ast_position_events(state);_chipx=rect.x+12
        for _event in _events:
            _label=truncate_text_to_width(font_tiny,str(_event.get("name","position")),72);_w=max(48,min(84,font_tiny.size(_label)[0]+16));_r=pygame.Rect(_chipx,y,_w,20)
            if _chipx+_w>rect.right-12:_chipx=rect.x+12;y+=23;_r=pygame.Rect(_chipx,y,_w,20)
            if ui_button(f,_r,_label,active=modal.get("_ast_pos_event")==_event.get("id"),icon="crosshair"):modal["_ast_pos_event"]=_event.get("id")
            _chipx+=_w+4
        if _events:y+=24
        if ui_button(f,pygame.Rect(rect.x+12,y,98,20),"+ Position",icon="plus",active=True):_ast_push_undo("Add animation position event");_ast_add_position_event(state)
