def _sgm_bp_label(node):
    cls = NODE_DEFS.get(node.get("type"))
    title = str(node.get("custom_name") or getattr(cls, "title", node.get("type", "Node")))
    return f"#{node.get('id')}  {title}"

def _sgm_draw_bp_members(f, rect, group, y):
    """Blueprint members of a group, resolved against the open graph."""
    script = _bp_current_script()
    nodes = modal.get("ns_nodes", {}) or {}
    if not nodes:
        ui_empty_state(pygame.Rect(rect.x + 8, y, rect.width - 16, rect.bottom - y - 10),
                       "No blueprint open",
                       "Open a character's blueprint first,\nthen come back to group its nodes.",
                       "blueprint")
        return

    screen.blit(font_tiny.render(
        truncate_text_to_width(font_tiny, f"graph: {script or '(unsaved)'}", rect.width - 24),
        True, TEXT_FAINT), (rect.x + 12, y))
    y += 15

    mine = [m for m in scene_group_bp_members(group) if m["script"] == script]
    mine_ids = {m["id"] for m in mine}
    member_nodes = [nodes[i] for i in mine_ids if i in nodes]

    screen.blit(font_tiny.render(f"MEMBERS ({len(member_nodes)})  ·  click to remove",
                                 True, TEXT_FAINT), (rect.x + 12, y))
    y += 16
    split = (rect.bottom - y - 40) // 2
    mem_r = pygame.Rect(rect.x + 8, y, rect.width - 16, max(40, split))
    _sgm_bp_list(f, mem_r, member_nodes,
                 lambda n: scene_group_remove_bp_nodes(group, [n["id"]]),
                 "No blueprint nodes in this group yet.", inside=True)

    y = mem_r.bottom + 8
    free = [n for n in nodes.values()
            if scene_group_of_bp_node(n.get("id")) is None]
    screen.blit(font_tiny.render(f"UNGROUPED ({len(free)})  ·  click to add",
                                 True, TEXT_FAINT), (rect.x + 12, y))
    y += 16
    add_r = pygame.Rect(rect.x + 8, y, rect.width - 16, max(40, rect.bottom - y - 38))
    _sgm_bp_list(f, add_r, free,
                 lambda n: scene_group_add_bp_nodes(group, [n["id"]]),
                 "Every blueprint node is already grouped.", inside=False)

    by = rect.bottom - 30
    if ui_button(f, pygame.Rect(rect.x + 12, by, 128, 22), "Add Selection",
                 icon="plus", active=True,
                 tooltip="Add everything selected in the blueprint editor"):
        sel = list(ns_selection_ids())
        n = scene_group_add_bp_nodes(group, sel)
        push_toast(f"Added {n} blueprint node(s).", "success", 1.8)
    if ui_button(f, pygame.Rect(rect.x + 146, by, 120, 22), "Select In Graph",
                 icon="search", tooltip="Select this group's nodes on the canvas"):
        modal["ns_multi_selected"] = set(mine_ids)
        modal["ns_selected"] = next(iter(mine_ids)) if mine_ids else None

