def _sgm_prompt_save(group):
    def on_name(name):
        name = " ".join(str(name).strip().split())[:64]
        if not name:
            push_toast("Asset name cannot be empty.", "warning", 2.0)
            modal["type"] = "scene_group_manager"
            modal["_sgm_prev_down"] = True
            modal["focus"] = None
            return

        def on_tags(tags):
            save_scene_group_as_asset(
                group["id"], name,
                [t for t in str(tags or "").split(",") if t.strip()])
            modal["type"] = "scene_group_manager"
            modal["_sgm_prev_down"] = True
            modal["focus"] = None

        modal["type"] = "text_input_modal"
        modal["text_input_title"] = "Group Asset Tags"
        modal["text_input_label"] = "Tags, comma separated (optional):"
        modal["text_input_value"] = ""
        modal["focus"] = "text_input_value"
        modal["text_input_callback"] = on_tags
        modal["text_input_cancel_callback"] = on_tags

    def on_cancel():
        modal["type"] = "scene_group_manager"
        modal["_sgm_prev_down"] = True
        modal["focus"] = None

    modal["type"] = "text_input_modal"
    modal["text_input_title"] = "Save Group Asset"
    modal["text_input_label"] = "Asset name:"
    modal["text_input_value"] = str(group.get("name", "Group Asset"))
    modal["focus"] = "text_input_value"
    modal["text_input_callback"] = on_name
    modal["text_input_cancel_callback"] = on_cancel

def open_anim_editor(return_to="add_character", state=None, library_name=None):
    """Open the full-screen professional animation editor.

    return_to   : "add_character" | "animation_library" | "main"
    state       : animation state name (for character-mode)
    library_name: clip name (for library-mode)
    """
    global modal_scroll
    modal["type"]              = "anim_editor"
    modal["_ae_return"]        = return_to
    modal["_ae_state"]         = state or modal.get("animation_state", "idle")
    modal["_ae_lib_name"]      = library_name
    modal["_ae_sel_frames"]    = set()   # selected frame indices
    modal["_ae_drag_frame"]    = None    # (index, start_x, orig_order) drag state
    modal["_ae_timeline_zoom"] = 1.0     # px-per-second scale
    modal["_ae_tl_scroll"]     = 0.0    # horizontal scroll in seconds
    modal["_ae_play"]          = False
    modal["_ae_play_t"]        = 0.0    # playhead position in seconds
    modal["_ae_play_started"]  = time.time()
    modal["_ae_loop"]          = True
    modal["_ae_onion"]         = False
    modal["_ae_onion_before"]  = 2
    modal["_ae_onion_after"]   = 1
    modal["_ae_snap"]          = True
    modal["_ae_zoom_preset"]   = 1      # 0=fit 1=1x 2=2x 3=4x
    modal["_ae_context_menu"]  = None   # (mx, my, frame_idx)
    modal["_ae_markers"]       = {}     # {seconds: label}
    modal["_ae_interp_filter"] = None   # filter visible by interp type
    modal["_ae_search"]        = ""
    modal["focus"]             = None
    modal_scroll               = 0.0

def _ae_get_frames():
    """Return the list of frame dicts for the current editor context."""
    ae_return = modal.get("_ae_return")
    if ae_return == "animation_library":
        name = modal.get("_ae_lib_name") or modal.get("animation_selected_name")
        defn = ANIMATION_LIBRARY.get(name, {})
        fps  = max(0.1, float(defn.get("fps", 6.0)))
        raw  = defn.get("frames", [])
        return _anim_normalise_frames(raw, fps)
    else:
        st   = modal.get("_ae_state", "idle")
        raw  = modal.setdefault("animation_frames", {}).setdefault(st, [])
        fps  = max(0.1, modal.setdefault("animation_fps", {}).get(st, 6.0))
        return _anim_normalise_frames(raw, fps)

def _ae_set_frames(frames):
    """Write back the frame list to the correct storage location."""
    ae_return = modal.get("_ae_return")
    if ae_return == "animation_library":
        name = modal.get("_ae_lib_name") or modal.get("animation_selected_name")
        if name and name in ANIMATION_LIBRARY:
            ANIMATION_LIBRARY[name]["frames"] = frames
    else:
        st = modal.get("_ae_state", "idle")
        modal.setdefault("animation_frames", {})[st] = [
            f["path"] if isinstance(f, dict) else f for f in frames
        ]
        modal.setdefault("animation_durations", {})[st] = [
            f.get("duration", 1/6) if isinstance(f, dict) else 1/6 for f in frames
        ]

def _ae_total_dur(frames):
    return max(0.02, sum(f.get("duration", 1/6) if isinstance(f, dict) else 1/6
                         for f in frames))

def _ae_playhead_frame(frames, t):
    """Which frame index is active at time t (seconds)?"""
    if not frames:
        return 0
    total = _ae_total_dur(frames)
    t = t % total if modal.get("_ae_loop") else min(t, total - 1e-6)
    acc = 0.0
    for i, f in enumerate(frames):
        dur = f.get("duration", 1/6) if isinstance(f, dict) else 1/6
        acc += dur
        if t < acc:
            return i
    return len(frames) - 1

def open_motion_studio(force_modal=False,clip_name=None,new_clip=True):
    """Open Motion Studio on a clean project unless a clip was explicitly chosen."""
    try:
        if not MOTION_CLIPS_LOADED:load_motion_clips()
    except Exception:pass
    names=motion_clip_names()
    if clip_name in MOTION_CLIPS:
        modal["_ms_clip"]=clip_name
    elif new_clip:
        base="motion_clip";name=base;index=2
        while name in MOTION_CLIPS:name=f"{base}_{index}";index+=1
        MOTION_CLIPS[name]=_motion_clip_default(name);modal["_ms_clip"]=name;save_motion_clips()
    elif modal.get("_ms_clip") not in MOTION_CLIPS:
        if names:modal["_ms_clip"]=names[0]
        else:MOTION_CLIPS["motion_clip"]=_motion_clip_default("motion_clip");modal["_ms_clip"]="motion_clip";save_motion_clips()
    modal["focus"]=None;modal["_ms_frame"]=0.0;modal["_ms_play"]=False;modal["_ms_sel_l"]=0;modal["_ms_sel_k"]=None;modal["_ms_sel_e"]=None;modal["_ms_drag"]=None;modal["_ms_ease_pk"]=None;modal["_ms_undo"]=[];modal["_ms_redo"]=[]
    if not force_modal and popout_settings_on() and _popout_motion_studio():return
    modal["type"]="motion_studio"

