def open_anim_state_timeline_picker(return_to="visual_scripter",target_node=None,target_property=None):
    """Open the real Animation Editor as a state picker."""
    open_anim_state_timeline(return_to)
    modal["_ast_pick_context"]={"return_to":return_to,"target_node":target_node,"target_property":target_property}
    current=None
    if return_to=="visual_scripter" and target_node is not None and target_property:
        current=(modal.get("ns_nodes",{}).get(target_node,{}) or {}).get("props",{}).get(target_property)
    elif return_to=="trait_parameter" and target_property:
        current=modal.get("fields",{}).get(f"param:{target_property}")
    if current in _ast_states():modal["_ast_sel_state"]=current;modal["animation_state"]=current


def _ast_use_picked_state():
    # Commit path/transform metadata only; layered runtime rendering needs no bake.
    for _st,_layers in list((modal.get("animation_layers",{}) or {}).items()):
        for _lay in _layers:anim_layer_frame_transforms(_lay);anim_layer_frame_metadata(_lay)
        if len(_layers)==1 and not _ast_layer_requires_bake(_layers[0]):
            _lay=_layers[0];modal.setdefault("animation_frames",{})[_st]=list(_lay.get("frames",[]));modal.setdefault("animation_durations",{})[_st]=list(anim_layer_durations(_st,_lay))
    ctx=modal.pop("_ast_pick_context",None)
    if not isinstance(ctx,dict):return False
    state=str(modal.get("_ast_sel_state") or "idle");ret=ctx.get("return_to","visual_scripter");prop=ctx.get("target_property")
    if ret=="visual_scripter":
        node=modal.get("ns_nodes",{}).get(ctx.get("target_node"))
        if isinstance(node,dict) and prop:node.setdefault("props",{})[prop]=state;modal["ns_dirty"]=True
    elif ret=="trait_parameter" and prop:modal.setdefault("fields",{})[f"param:{prop}"]=state
    elif ret=="add_character":modal["animation_state"]=state
    modal["type"]="add_character" if ret=="trait_parameter" else (None if ret=="main" else ret);modal["focus"]=None
    push_toast(f"Animation state selected: {state}","success",1.8);return True


