def ns_visible_categories():
    """Category list for the palette chips, scoped to the entity."""
    kind = ns_editing_entity_kind()
    cats = sorted({getattr(c, "category", "") for c in NODE_DEFS.values()})
    if kind != "character":
        return [c for c in cats if c]
    return [c for c in cats if c and c not in NS_SCENE_ONLY_CATEGORIES]

