# ── Node editor visual enhancement state ─────────────────────────────────────
# Execution flash: {node_id: expiry_time}  — node glows briefly after running
_NS_EXEC_FLASH: dict = {}
_NS_EXEC_FLASH_COLOR: dict = {}  # node_id -> (r,g,b) optional override flash color

# Hovered wire: None | (from_id, from_pin, to_id, to_pin)
_ns_hovered_wire = None

# Hovered node id for dependency highlighting
_ns_hovered_node: int | None = None

def _ns_register_exec(node_id: int, duration: float = 0.35, color=None) -> None:
    """Call when a node executes to trigger the flash effect.

    color: optional (r,g,b) — when provided (e.g. Constant Color / VFX),
    the node body flashes that color instead of the category accent.
    """
    _NS_EXEC_FLASH[node_id] = time.time() + duration
    
    # Trigger circular port signal ripple shockwave if enabled!
    try:
        nodes = modal.get("ns_nodes", {})
        n = nodes.get(node_id)
        if n and bool(modal.get("ns_port_ripples_enabled", True)):
            _cx = float(n.get("x", 0)) + 110.0 # centered horizontally
            _cy = float(n.get("y", 0)) + 24.0  # centered vertically
            _col = color if color is not None else (240, 60, 180)
            _NS_PORT_RIPPLES.append({"x": _cx, "y": _cy, "color": _col, "t0": time.time(), "duration": 0.45})
    except Exception:
        pass

    if color is not None:
        try:
            _NS_EXEC_FLASH_COLOR[node_id] = tuple(int(max(0, min(255, c))) for c in color[:3])
        except Exception:
            _NS_EXEC_FLASH_COLOR[node_id] = (255, 255, 255)
    else:
        _NS_EXEC_FLASH_COLOR.pop(node_id, None)

def _ns_resolve_flash_color(node):
    """Best-effort color from node props / wired color inputs / sim vars."""
    if not node:
        return None
    props = node.get("props", {})
    # Direct color props
    for key in ("color", "from_color", "to_color", "fill_color", "tint"):
        c = props.get(key)
        if isinstance(c, (list, tuple)) and len(c) >= 3:
            try:
                return tuple(int(c[i]) for i in range(3))
            except Exception:
                pass
    # RGB components
    if all(k in props for k in ("r", "g", "b")):
        try:
            return (int(props["r"]), int(props["g"]), int(props["b"]))
        except Exception:
            pass
    # sim var cache
    sim = modal.get("ns_sim_variables", {})
    v = sim.get(node["id"])
    if isinstance(v, (list, tuple)) and len(v) >= 3:
        try:
            return tuple(int(v[i]) for i in range(3))
        except Exception:
            pass
    return None

# ── Wire / value-change visual feedback ─────────────────────────────────────
# wire_id -> last execution timestamp (used for flowing dashes + pulse)
_NS_WIRE_PULSE: dict = {}
# node_id / "from:to:pin" -> float  (last time a value traveled the wire)
_NS_WIRE_FLOW:  dict = {}
# node_id -> last numeric value (used to detect +/- changes for popups)
_NS_NODE_LAST_VAL: dict = {}
# Floating value popups: list of dicts drawn over the canvas
_NS_VALUE_POPUPS: list = []
_NS_PORT_RIPPLES: list = []
_NS_PARTICLE_EMBERS: list = []
# Node width override (computed each frame from title text length)
_NS_NODE_W_OVERRIDE: dict = {}
# Node height override (extra rows for long props / extra pins)
_NS_NODE_H_OVERRIDE: dict = {}

def _ns_pulse_wire(wire_key: str, duration: float = 0.55) -> None:
    """Mark a wire as having just carried a pulse (dashed flow + glow)."""
    _NS_WIRE_FLOW[str(wire_key)] = time.time() + duration

def _ns_draw_dotted_line(surface, p0, p1, color, width=2, dash=6, gap=5):
    """Dotted connector path for clip sockets → already-linked hosts."""
    try:
        x0, y0 = float(p0[0]), float(p0[1])
        x1, y1 = float(p1[0]), float(p1[1])
    except Exception:
        return
    dx, dy = x1 - x0, y1 - y0
    dist = math.hypot(dx, dy)
    if dist < 1:
        return
    ux, uy = dx / dist, dy / dist
    # soft underglow
    for t in range(0, int(dist), dash + gap):
        s = t
        e = min(dist, t + dash)
        sx, sy = x0 + ux * s, y0 + uy * s
        ex, ey = x0 + ux * e, y0 + uy * e
        pygame.draw.line(surface, color, (int(sx), int(sy)), (int(ex), int(ey)), max(1, width))

def _ns_spawn_value_popup(x: float, y: float, text: str, color, dur: float = 0.9) -> None:
    """Spawn a fading floating '+1'/'-1'/'3.2s' style popup in canvas space."""
    # Cap active popups for perf
    if len(_NS_VALUE_POPUPS) > 48:
        _NS_VALUE_POPUPS.pop(0)
    _now_popup=time.time()
    _near=[p for p in _NS_VALUE_POPUPS
           if _now_popup-p.get("born",0)<0.45
           and abs(float(p.get("x",0))-float(x))<130
           and abs(float(p.get("y",0))-float(y))<85]
    _used={int(p.get("stack",0)) for p in _near}; _stack=0
    while _stack in _used and _stack<10: _stack+=1
    _NS_VALUE_POPUPS.append({
        "x": float(x), "y": float(y),
        "text": str(text), "stack": _stack,
        "side": -1 if _stack % 2 else 1,
        "color": tuple(color[:3]),
        "born": time.time(),
        "life": float(NS_DEBUG_POPUP_DURATION if abs(float(dur) - 0.9) < 1e-6 else dur),
        "seed": random.random() * 6.28,
    })

def _ns_update_timer_popup(node_id, x, y, text, color=(90,200,255)):
    now=time.time()
    popup=next((p for p in _NS_VALUE_POPUPS if p.get("timer_node")==node_id),None)
    if popup:
        popup.update({"x":float(x),"y":float(y),"text":str(text),"color":tuple(color[:3]),"born":now,"life":max(.75,NS_DEBUG_POPUP_DURATION)})
    else:
        _ns_spawn_value_popup(x,y,text,color,max(.75,NS_DEBUG_POPUP_DURATION));_NS_VALUE_POPUPS[-1]["timer_node"]=node_id

def _ns_tick_popups() -> None:
    """Expire old popups (call once/frame)."""
    now = time.time()
    if _NS_VALUE_POPUPS:
        _NS_VALUE_POPUPS[:] = [p for p in _NS_VALUE_POPUPS if now - p["born"] < p["life"]]
    # also prune old wire pulses periodically (cheap)
    if _NS_WIRE_FLOW:
        _NS_WIRE_FLOW.clear() if len(_NS_WIRE_FLOW) > 400 else None
        expired = [k for k, exp in _NS_WIRE_FLOW.items() if now > exp]
        for k in expired:
            _NS_WIRE_FLOW.pop(k, None)

def _ns_draw_socket(surface, x, y, pin_type, radius, filled=False, zoom=1.0):
    """Draw simple, readable sockets. (Now overalled with glowing interactive halos!)

    The older mixed hollow/crosshatched sockets looked odd at different zooms.
    This version clamps sizes and uses simple filled/outlined symbols so they
    scale predictably.
    """
    try:_pin_scale=max(.55,min(1.8,float(_editor_config.get("ns_pin_scale",1.0))))
    except Exception:_pin_scale=1.0
    r_val = max(3, min(13, int(round(radius*_pin_scale))))
    x_val, y_val = int(x), int(y)
    col_val = PIN_COLORS.get(pin_type, (140, 140, 158))
    _pin_style=str(_editor_config.get("ns_pin_style","type_shapes"))
    try:_glow=max(0.0,min(1.0,float(_editor_config.get("ns_pin_glow",.65))))
    except Exception:_glow=.65
    # Configurable connected-port halo.
    if filled and zoom > 0.4 and _glow>0.01:
        halo_r = r_val + max(2, int((2+4*_glow) * zoom))
        h_surf = pygame.Surface((halo_r*2, halo_r*2), pygame.SRCALPHA)
        pygame.draw.circle(h_surf, (*col_val[:3], int(55*_glow)), (halo_r, halo_r), halo_r)
        pygame.draw.circle(h_surf, (*col_val[:3], int(115*_glow)), (halo_r, halo_r), r_val + 1, 1)
        surface.blit(h_surf, (x_val - halo_r, y_val - halo_r))
    r = r_val
    x, y = x_val, y_val
    col = col_val
    border = tuple(min(255, int(c * 1.15)) for c in col[:3])
    fill = tuple(max(18, int(c * (0.95 if filled else 0.38))) for c in col[:3])
    inner = (12, 13, 18)
    w = max(1, min(2, r // 3))

    if _pin_style == "round":
        pygame.draw.circle(surface,fill,(x,y),r);pygame.draw.circle(surface,border,(x,y),r,w)
        if not filled:pygame.draw.circle(surface,inner,(x,y),max(1,r//3))
        return
    if _pin_style == "square":
        rr=pygame.Rect(x-r,y-r,r*2,r*2);pygame.draw.rect(surface,fill,rr,border_radius=max(1,r//4));pygame.draw.rect(surface,border,rr,w,border_radius=max(1,r//4));return
    if _pin_style == "diamond":
        pts=[(x,y-r),(x+r,y),(x,y+r),(x-r,y)];pygame.draw.polygon(surface,fill,pts);pygame.draw.polygon(surface,border,pts,w);return
    if _pin_style == "minimal":
        pygame.draw.circle(surface,col,(x,y),max(2,r//2));return

    if pin_type == EXEC:
        pts = [(x - r, y - r), (x + r, y), (x - r, y + r)]
        pygame.draw.polygon(surface, fill, pts)
        pygame.draw.polygon(surface, border, pts, w)
        if filled:
            pygame.draw.circle(surface, (255, 255, 255), (x - max(1, r//5), y), max(1, r//4))
        return

    if pin_type == BOOLEAN:
        pts = [(x, y-r), (x+r, y), (x, y+r), (x-r, y)]
        pygame.draw.polygon(surface, fill, pts)
        pygame.draw.polygon(surface, border, pts, w)
        return

    if pin_type == VECTOR:
        pts = [(x-r, y-r//2), (x-r//2, y-r), (x+r//2, y-r), (x+r, y-r//2),
               (x+r, y+r//2), (x+r//2, y+r), (x-r//2, y+r), (x-r, y+r//2)]
        pygame.draw.polygon(surface, fill, pts)
        pygame.draw.polygon(surface, border, pts, w)
        return

    if pin_type == STRING:
        rr = pygame.Rect(x-r, y-r, r*2, r*2)
        pygame.draw.rect(surface, fill, rr, border_radius=max(2, r//2))
        pygame.draw.rect(surface, border, rr, width=w, border_radius=max(2, r//2))
        return

    # Number / Color / Object / Any: simple dot. No hollow rings unless it is
    # genuinely unfilled, and even then it has a tinted center so it doesn't
    # look like a random white/black target.
    pygame.draw.circle(surface, fill, (x, y), r)
    pygame.draw.circle(surface, border, (x, y), r, w)
    if pin_type == COLOR:
        pygame.draw.circle(surface, (255,255,255), (x, y), max(1, r//3))
    elif not filled:
        pygame.draw.circle(surface, inner, (x, y), max(1, r//3))

