# ── Canvas + card visual style helpers ───────────────────────────────────────
def _ns_wire_anim_mode():
    """Wire animation style, including signal-dot visualizers."""
    default = str(_editor_config.get("ns_wire_anim_mode", "flow"))
    mode = str(modal.get("ns_wire_anim_mode", default) or default).lower()
    valid = ("off", "subtle", "flow", "single_dot", "multi_dot", "comet", "spark", "wave", "neon")
    return mode if mode in valid else "flow"

def _ns_set_wire_anim_mode(mode):
    valid = ("off", "subtle", "flow", "single_dot", "multi_dot", "comet", "spark", "wave", "neon")
    if mode not in valid:
        return
    modal["ns_wire_anim_mode"] = mode
    modal["ns_dirty"] = True
    save_ns_editor_setting("ns_wire_anim_mode", mode)
    push_toast(f"Path animation: {mode.replace('_', ' ').title()}", "info", 1.5)

def _ns_cycle_wire_anim_mode():
    order = ["off", "subtle", "flow", "single_dot", "multi_dot", "comet", "spark", "wave", "neon"]
    cur = _ns_wire_anim_mode()
    _ns_set_wire_anim_mode(order[(order.index(cur) + 1) % len(order)])

_ns_canvas_dot_cache = {"size_sig": None, "surface": None, "ref_pan": None, "margin": 0}
_ns_canvas_vignette_cache = {"size_sig": None, "surface": None}

def _ns_category_shape(category):
    """Simple category silhouette only.

    Earlier versions used dramatic polygons (stars, flags, tags, slants). They
    were readable in isolation but looked messy once shadows, headers, tints,
    and selection rings stacked behind them. Keep the actual card shape simple
    and let color + microglyph + header text carry the category identity.
    """
    # A tiny set of calm shapes; most nodes use the same rounded card so the
    # canvas feels clean. No sharp/concave shapes, no extreme cut-outs.
    if category in ("Parameters", "Status"):
        return "soft_capsule"
    if category in ("Clips", "Control"):
        return "soft_tab"
    return "rounded"

def _ns_draw_node_shape(surface, rect, fill, border=None, width=0, radius=10, category="Utility", accent=None, theme=None):
    """Draw the node card body. Theme-aware.

    Returns a dict of layout hints (inner_pad, header_h_extra, body_top_extra,
    text_x_offset) so callers can correctly position header/title/body text
    without each theme needing its own whole draw function, AND so text never
    crowds the color accent (which was causing "big text / low margin / text
    touching" problems).
    """
    shape = _ns_category_shape(category)
    try:
        fill = tuple(max(0, min(255, int(round(c)))) for c in fill[:4])
    except Exception:
        fill = (20, 20, 24)
    if border:
        try:
            border = tuple(max(0, min(255, int(round(c)))) for c in border[:4])
        except Exception:
            border = None
    if accent is None:
        accent = ns_category_color(category)
    try:
        accent = tuple(max(0, min(255, int(round(c)))) for c in accent[:3])
    except Exception:
        accent = (130, 105, 255)
    if theme is None:
        try:
            theme = modal.get("ns_node_theme", NS_NODE_THEME) if isinstance(modal, dict) else NS_NODE_THEME
        except Exception:
            theme = NS_NODE_THEME
    if theme not in NS_NODE_THEMES:
        theme = "current"

    do_fill = not (len(fill) >= 4 and fill[3] == 0)

    # Per-theme geometry
    if theme == "strip":       # Option B: flat body, 4px left strip
        rr = 6
        inner_pad = 16        # 4px strip + 12px margin
        title_x_off = 0
        header_y_off = 0
        header_full_color = False
    elif theme == "block":     # Option C: Unreal-style solid header block
        rr = 4
        inner_pad = 12
        title_x_off = 0
        header_y_off = 0
        header_full_color = True
    elif theme == "topline":   # Option D: 3px line on top
        rr = 7
        inner_pad = 14
        title_x_off = 0
        header_y_off = 0
        header_full_color = False
    elif theme == "dot":       # Option E: minimal dot only
        rr = 10
        inner_pad = 14
        title_x_off = 0
        header_y_off = 0
        header_full_color = False
    elif theme == "underline": # Option F: dark header, colored underline
        rr = 5
        inner_pad = 12
        title_x_off = 0
        header_y_off = 0
        header_full_color = False
    else:                      # current / A: glossy rounded card
        rr = max(6, int(radius))
        if shape == "soft_capsule":
            rr = max(rr, min(rect.height // 3, 18))
        elif shape == "soft_tab":
            rr = max(rr, 12)
        inner_pad = 14
        title_x_off = 0
        header_y_off = 0
        header_full_color = False

    # Body fill
    if do_fill:
        # Flat themes use a flatter fill color
        body_color = fill
        if theme in ("strip", "topline", "dot", "underline") and len(fill) >= 3:
            # Slightly lighter neutral panel for flat themes
            body_color = tuple(min(255, int(c * 1.35 + 8)) if c < 50 else c for c in fill[:3])
        pygame.draw.rect(surface, body_color, rect, border_radius=rr)

        # Left strip (theme B)
        if theme == "strip":
            sw = 4
            # Rounded top/bottom on the strip by drawing a taller rounded rect
            # and covering the right half with body color
            pygame.draw.rect(surface, accent, (rect.x, rect.y, sw + rr, rect.height), border_radius=rr)
            # Square off the right side so strip has a flat edge
            pygame.draw.rect(surface, accent, (rect.x, rect.y + rr, sw, rect.height - rr * 2))
            # Tiny top tab for event/control/clip categories
            if shape == "soft_tab" and rect.width > 40:
                tw = min(rect.width // 3, 64); th = 3
                pygame.draw.rect(surface, accent, (rect.x + rr + 2, rect.y, tw, th), border_radius=th)

        # Top line (theme D)
        if theme == "topline":
            th = 3
            pygame.draw.rect(surface, accent, (rect.x + rr, rect.y, rect.width - rr * 2, th), border_radius=th)
            # rounded ends
            pygame.draw.rect(surface, accent, (rect.x, rect.y, rr + 1, th))
            pygame.draw.rect(surface, accent, (rect.right - rr - 1, rect.y, rr + 1, th))

        # Soft tab hint on current theme (kept from original)
        if theme == "current" and shape == "soft_tab" and rect.width > 40 and rect.height > 24:
            tab_w = min(rect.width // 3, 58)
            tab_h = max(5, min(10, rect.height // 10))
            tint = tuple(min(255, int(c + 8)) for c in fill[:3])
            pygame.draw.rect(surface, tint, (rect.x + rr, rect.y, tab_w, tab_h), border_radius=tab_h // 2)

    if border and width:
        pygame.draw.rect(surface, border, rect, width=width, border_radius=rr)

    return {"inner_pad": inner_pad, "rr": rr, "header_full_color": header_full_color,
            "theme": theme, "accent": accent}

def _ns_draw_category_microglyph(surface, rect, category, color):
    """Small simple category cue in the header; no custom card silhouettes."""
    cx, cy = rect.right - 15, rect.centery
    try:
        if category == "Math":
            pygame.draw.line(surface, color, (cx-6, cy+5), (cx-1, cy-5), 2)
            pygame.draw.line(surface, color, (cx-1, cy-5), (cx+6, cy+5), 2)
        elif category == "Animation":
            pygame.draw.circle(surface, color, (cx-5, cy), 2)
            pygame.draw.circle(surface, color, (cx, cy), 2)
            pygame.draw.circle(surface, color, (cx+5, cy), 2)
        elif category == "Performance":
            pygame.draw.rect(surface, color, (cx-6, cy-5, 12, 10), 1, border_radius=2)
            pygame.draw.line(surface, color, (cx-8, cy), (cx-6, cy), 1)
            pygame.draw.line(surface, color, (cx+6, cy), (cx+8, cy), 1)
        elif category in ("Conditions", "Logic"):
            pygame.draw.polygon(surface, color, [(cx, cy-6), (cx+6, cy), (cx, cy+6), (cx-6, cy)], 1)
        elif category in ("Events", "Input"):
            pygame.draw.circle(surface, color, (cx, cy), 5, 1)
            pygame.draw.circle(surface, color, (cx, cy), 2)
        else:
            pygame.draw.circle(surface, color, (cx, cy), 4, 1)
    except Exception:
        pass

def _ns_node_symbol(node, cls):
    """Text fallback when pytablericons is not installed."""
    ntype = str(node.get("type", "")) if node else ""
    if ntype.startswith("event_"): return "▶"
    if ntype.startswith("math_"): return "Σ"
    if ntype.startswith("condition_"): return "?"
    if ntype.startswith("animation_"): return "A"
    if ntype.startswith("perf_"): return "P"
    if ntype.startswith("variable_"): return "V"
    if ntype.startswith("target_"): return "T"
    if ntype.startswith("debug_"): return "!"
    return (getattr(cls, "category", "Node")[:1] or "•").upper()

def _ns_draw_node_symbol(surface, rect, node, cls, accent, z):
    """Draw a small category symbol badge. Skipped entirely on flat themes
    (the color cue lives on the strip/block/top-line instead) so the header
    stays clean and the category label has more room."""
    try:
        _thm = modal.get("ns_node_theme", NS_NODE_THEME) if isinstance(modal, dict) else NS_NODE_THEME
    except Exception:
        _thm = NS_NODE_THEME
    if _thm in ("strip", "block", "topline", "dot", "underline"):
        return 0
    if z <= 0.42:
        return 0
    size = max(14, min(19, int(16 * max(0.8, min(z, 1.25)))))
    badge = pygame.Rect(rect.x + 8, rect.y + max(4, int(5*z)), size, size)
    bg = tuple(max(0, int(c * 0.25)) for c in accent[:3])
    pygame.draw.rect(surface, bg, badge, border_radius=max(4, size//4))
    pygame.draw.rect(surface, accent, badge, width=1, border_radius=max(4, size//4))
    sym = _ns_node_symbol(node, cls)
    f = ns_scaled_font(9, 1.0, bold=True)
    ts = f.render(sym, True, (245, 248, 255))
    surface.blit(ts, (badge.centerx - ts.get_width()//2, badge.centery - ts.get_height()//2))
    return size + 8

def _ns_wire_style_key(style):
    style = str(style or "bezier")
    return style if style in NS_WIRE_STYLE_LABELS else "bezier"

def _ns_wire_points(p0, p1, style="bezier"):
    """Return an ordered connector path without reverse-link self wrapping."""
    x0, y0 = float(p0[0]), float(p0[1])
    x1, y1 = float(p1[0]), float(p1[1])
    style = _ns_wire_style_key(style)
    dx = x1 - x0
    dy = y1 - y0
    dist = max(1.0, math.hypot(dx, dy))
    if style in ("straight", "direct"):
        return [(x0, y0), (x1, y1)]
    reverse = dx < -8
    if style in ("smart_orthogonal", "orthogonal", "rounded_orthogonal", "circuit", "subway", "loopback"):
        if style == "circuit":
            _lane = max(36.0, min(180.0, abs(dx) * 0.38 + abs(dy) * 0.12))
            if reverse:
                # Route cleanly forward out of x0, down/up through hallway between rows, then left into x1
                mid_y = (y0 + y1) * 0.5 if abs(dy) > 40 else (max(y0, y1) + 48.0 if y0 > y1 else min(y0, y1) - 48.0)
                return [(x0, y0), (x0 + 38, y0), (x0 + 38, mid_y), (x1 - 38, mid_y), (x1 - 38, y1), (x1, y1)]
            bus_x = x0 + max(30.0, dx * 0.42)
            return [(x0, y0), (bus_x, y0), (bus_x, y1), (x1, y1)]
        if style == "subway":
            lane_y = y0 + dy * 0.5
            lane_x0 = x0 + (44 if not reverse else 38)
            lane_x1 = x1 - (44 if not reverse else 38)
            if reverse:
                mid_y = (y0 + y1) * 0.5 if abs(dy) > 45 else (max(y0, y1) + 54.0)
                return [(x0, y0), (lane_x0, y0), (lane_x0, mid_y), (lane_x1, mid_y), (lane_x1, y1), (x1, y1)]
            return [(x0, y0), (lane_x0, y0), (lane_x0, lane_y), (lane_x1, lane_y), (lane_x1, y1), (x1, y1)]
        if style == "loopback" or (reverse and style in ("orthogonal", "rounded_orthogonal", "smart_orthogonal")):
            # Clean hallway routing: step out to right of x0, travel vertically in open lane, step left into x1
            step_out = max(32.0, min(65.0, abs(dx) * 0.35))
            mid_y = (y0 + y1) * 0.5 if abs(dy) > 45 else (y0 + 58.0 if y0 >= y1 else y0 - 58.0)
            return [(x0, y0), (x0 + step_out, y0), (x0 + step_out, mid_y), (x1 - step_out, mid_y), (x1 - step_out, y1), (x1, y1)]
        if abs(dx) >= 34:
            mid_x = x0 + dx * 0.5
            return [(x0, y0), (mid_x, y0), (mid_x, y1), (x1, y1)]
        lane_y = y0 + (dy * 0.5 if abs(dy) > 8 else 34.0)
        return [(x0, y0), (x0, lane_y), (x1, lane_y), (x1, y1)]
    if style == "zigzag":
        steps = max(3, min(9, int(dist / 80)))
        pts = [(x0, y0)]
        amp = max(10.0, min(28.0, dist * 0.06))
        nx, ny = (-dy / dist, dx / dist)
        for i in range(1, steps):
            t = i / steps
            sign = -1 if i % 2 else 1
            pts.append((x0 + dx*t + nx*amp*sign, y0 + dy*t + ny*amp*sign))
        pts.append((x1, y1))
        return pts
    if style == "arc":
        midx, midy = (x0 + x1) * 0.5, (y0 + y1) * 0.5
        lift = max(50.0, min(220.0, dist * 0.28)) * (-1 if y1 >= y0 else 1)
        c1 = (midx, midy + lift)
        c2 = c1
    else:
        if reverse:
            # Fix: NEVER push c2 out to the right when reverse!
            # c1 leaves x0 toward the right, c2 enters x1 from the left!
            handle = max(45.0, abs(dx) * 0.45)
            vo = (dy * 0.25) if abs(dy) > 45 else (-55.0 if y0 < y1 else 55.0)
            c1, c2 = (x0 + handle, y0 + vo), (x1 - handle, y1 - vo)
        else:
            mult = 0.42 if style == "tight_s" else 0.70 if style == "soft_s" else 0.62 if style == "smooth_bezier" else 0.55
            handle = max(34.0, abs(dx) * mult)
            vo = dy * (0.12 if style == "soft_s" else 0.0)
            c1, c2 = (x0 + handle, y0 + vo), (x1 - handle, y1 - vo)
    steps = max(8, min(40, int(dist / 16)))
    points = []
    for i in range(steps + 1):
        t = i / steps
        it = 1.0 - t
        bx = it*it*it*x0 + 3*it*it*t*c1[0] + 3*it*t*t*c2[0] + t*t*t*x1
        by = it*it*it*y0 + 3*it*it*t*c1[1] + 3*it*t*t*c2[1] + t*t*t*y1
        points.append((bx, by))
    return points

def _ns_draw_wire_style_icon(surface, rect, style, color=(210, 210, 220), width=2):
    """Tiny inline preview used by the connector-style dropdown."""
    _style_key = _ns_wire_style_key(style)
    if _style_key == "straight":
        _p0 = (rect.x + 4, rect.centery)
        _p1 = (rect.right - 4, rect.centery)
    else:
        # Give the preview a small vertical delta so curved and stair routes
        # remain visibly different even in a tiny 56px icon.
        _p0 = (rect.x + 4, rect.centery + 6)
        _p1 = (rect.right - 4, rect.centery - 6)
    pts = _ns_wire_points(_p0, _p1, _style_key)
    pts = [(int(x), int(y)) for x, y in pts]
    if len(pts) >= 2:
        pygame.draw.lines(surface, color, False, pts, max(1, width))
    pygame.draw.circle(surface, color, pts[0], 2)
    pygame.draw.circle(surface, color, pts[-1], 2)

def _ns_wire_hit_test(pos, p0, p1, tolerance=10):
    """Return True when a screen point is close to the currently routed wire."""
    pts = _ns_wire_points(p0, p1, modal.get("ns_wire_style", "bezier"))
    px, py = float(pos[0]), float(pos[1])
    tol2 = float(tolerance) ** 2
    for (_x0, _y0), (_x1, _y1) in zip(pts, pts[1:]):
        dx, dy = _x1 - _x0, _y1 - _y0
        length2 = dx * dx + dy * dy
        if length2 <= 1e-9:
            dist2 = (px - _x0) ** 2 + (py - _y0) ** 2
        else:
            t = max(0.0, min(1.0, ((px - _x0) * dx + (py - _y0) * dy) / length2))
            qx, qy = _x0 + t * dx, _y0 + t * dy
            dist2 = (px - qx) ** 2 + (py - qy) ** 2
        if dist2 <= tol2:
            return True
    return False

def _ns_wire_id(link):
    return f"{link.get('from')}:{link.get('to')}:{link.get('from_pin')}->{link.get('to_pin')}"

def ns_delete_selected_wire():
    """Delete the highlighted wire, not a node."""
    selected = modal.get("ns_selected_wire")
    if not selected:
        return False
        
    # Check if this is a virtual debug_button body attachment connection!
    if str(selected).startswith("debug_button_link:"):
        parts = selected.split(":")
        if len(parts) >= 3:
            btn_id, host_id = parts[1], parts[2]
            ns_snapshot()
            nodes = modal.get("ns_nodes", {})
            
            # Resolve int/str ID representation
            host = nodes.get(host_id)
            if host is None and host_id.isdigit():
                host = nodes.get(int(host_id))
            if host:
                _buttons = host.get("props", {}).get("_debug_buttons", [])
                if _buttons:
                    # Remove the button from the host list
                    host["props"]["_debug_buttons"] = [bid for bid in _buttons if str(bid) != str(btn_id)]
                    modal["ns_selected_wire"] = None
                    modal["ns_dirty"] = True
                    push_toast("Debug Button connection uncoupled", "success", 1.8)
                    return True
        modal["ns_selected_wire"] = None
        return False
        
    old_links = modal.get("ns_links", [])
    new_links = [link for link in old_links if _ns_wire_id(link) != selected]
    if len(new_links) == len(old_links):
        modal["ns_selected_wire"] = None
        return False
    ns_snapshot()
    modal["ns_links"] = new_links
    modal["ns_selected_wire"] = None
    modal["ns_dirty"] = True
    push_toast("Connection deleted", "success", 1.8)
    return True

def _ns_draw_wire(surface, p0, p1, color, width=3, animated=False, wire_id=None,
                  hovered=False, exec_wire=False, dashed=False, flow_alpha=1.0):
    canvas = modal.get("_ns_canvas_rect")
    if canvas and not _ns_wire_near_canvas(p0, p1, canvas, pad=140):
        return
    try:width=max(1,int(round(float(width)*max(.5,min(2.5,float(_editor_config.get("ns_wire_width_scale",1.0)))))))
    except Exception:width=max(1,int(width))
    style = _ns_wire_style_key(modal.get("ns_wire_style", "bezier"))
    lod = modal.get("_ns_render_lod", "full")
    pts = _ns_wire_cached_points(p0, p1, style, lod)

    if len(pts) < 2:
        return

    ipts = [(int(p[0]), int(p[1])) for p in pts]
    # Arc length is also used by the pulse-head pass below. Previously it was
    # created only inside show_flow; a debug clamp could pulse a wire while
    # animation mode was Off, leaving `total`/`dists` unbound.
    dists = [0.0]
    for _i in range(1, len(ipts)):
        _dx = ipts[_i][0] - ipts[_i-1][0]
        _dy = ipts[_i][1] - ipts[_i-1][1]
        dists.append(dists[-1] + (_dx*_dx + _dy*_dy) ** 0.5)
    total = dists[-1] if dists[-1] > 0 else 1.0
    if lod in ("tiny", "far"):
        # Ultra-cheap connection rendering: no glow, no animation, no dashes.
        draw_col = tuple(max(0, min(255, int(c * (0.72 if lod == "tiny" else 0.9)))) for c in color[:3])
        pygame.draw.line(surface, draw_col, ipts[0], ipts[-1], max(1, 1 if lod == "tiny" else min(width, 2)))
        return

    # Pulse recently-active wires: widen + glow
    is_pulsing = False
    pulse_frac = 0.0
    if wire_id is not None:
        _exp = _NS_WIRE_FLOW.get(str(wire_id), 0)
        if _exp:
            _age = _exp - time.time()
            if _age > 0:
                is_pulsing = True
                pulse_frac = max(0.0, _age / 0.55)

    # Hover / pulse glow: draw a wider translucent pass underneath (with concentric high-fidelity blur emission ducts!)
    glow_w = width + (8 if hovered else 6 if is_pulsing else 4)
    # Check if ambient glow is enabled
    _wire_glow_on = bool(modal.get("ns_wire_glow_enabled", True))
    glow_a = 95 if hovered else int(85 * pulse_frac) if is_pulsing else (28 if _wire_glow_on else 0)
    if True:
        gcol = (*color[:3], glow_a)
        # small temporary surface clipped to wire bounds only (perf)
        minx = min(i[0] for i in ipts) - glow_w
        miny = min(i[1] for i in ipts) - glow_w
        maxx = max(i[0] for i in ipts) + glow_w
        maxy = max(i[1] for i in ipts) + glow_w
        gw = max(1, maxx - minx); gh = max(1, maxy - miny)
        if gw < 2000 and gh < 2000:
            gsurf = pygame.Surface((gw, gh), pygame.SRCALPHA)
            pygame.draw.lines(gsurf, gcol, False,
                              [(i[0]-minx, i[1]-miny) for i in ipts], glow_w)
            surface.blit(gsurf, (minx, miny))

    # Base wire: brighter/thicker so dim vs active is actually readable.
    mode = _ns_wire_anim_mode()
    width = max(width, 3 if not exec_wire else 4)
    if mode == "neon":
        width += 1
    draw_col = tuple(min(255, int(c * (1.45 if hovered else 1.18))) for c in color[:3])
    base_col = tuple(max(0, int(c * (0.68 if not hovered else 0.82))) for c in draw_col[:3])
    pygame.draw.lines(surface, base_col, False, ipts, max(2, width - 1))
    if style == "rounded_orthogonal" and len(ipts) > 2:
        _jr = max(2, (width + 1) // 2)
        for _joint in ipts[1:-1]:
            pygame.draw.circle(surface, base_col, _joint, _jr)

    # Single/multiple glowing signal dots. Data wires animate only when a
    # value actually pulses; exec wires can continuously indicate direction.
    _signal_active = bool(animated or is_pulsing or dashed or exec_wire)
    if mode in ("single_dot", "multi_dot") and _signal_active and len(ipts) >= 2:
        def _wire_point_at(distance):
            distance = distance % max(1.0, total)
            for _j in range(1, len(dists)):
                if dists[_j] >= distance:
                    _span = max(0.001, dists[_j] - dists[_j-1])
                    _u = (distance - dists[_j-1]) / _span
                    return (ipts[_j-1][0] + (ipts[_j][0]-ipts[_j-1][0]) * _u,
                            ipts[_j-1][1] + (ipts[_j][1]-ipts[_j-1][1]) * _u)
            return ipts[-1]
        _dot_count = 1 if mode == "single_dot" else max(3, min(8, int(total / 90) + 2))
        _dot_speed = (210.0 if exec_wire else 270.0) * NS_WIRE_FLOW_SPEED
        _phase = (time.time() * _dot_speed) % max(1.0, total)
        for _di in range(_dot_count):
            _dist = _phase + total * (_di / _dot_count)
            _dxp, _dyp = _wire_point_at(_dist)
            _dr = max(3, width + (2 if mode == "multi_dot" else 1))
            _glow = pygame.Surface((_dr*6, _dr*6), pygame.SRCALPHA)
            pygame.draw.circle(_glow, (*draw_col[:3], 52), (_dr*3, _dr*3), _dr*3)
            pygame.draw.circle(_glow, (*draw_col[:3], 125), (_dr*3, _dr*3), _dr*2)
            surface.blit(_glow, (int(_dxp)-_dr*3, int(_dyp)-_dr*3))
            pygame.draw.circle(surface, (255,255,255), (int(_dxp), int(_dyp)), _dr)
            pygame.draw.circle(surface, draw_col, (int(_dxp), int(_dyp)), max(1, _dr-2))
            
            # Spawn execution "Comet Dust" particle embers from the pulse head if enabled!
            import random
            if bool(modal.get("ns_wire_particles_enabled", True)) and random.random() < 0.35:
                # Convert screen positions _dxp, _dyp back to world coordinates for stable canvas panning
                view = modal.get("ns_view", {"pan":[0,0],"zoom":1.0}); z_v = float(view.get("zoom",1.0))
                canvas_v = modal.get("_ns_canvas_rect")
                if canvas_v:
                    wx_emb = (float(_dxp) - canvas_v.x - view["pan"][0]) / z_v
                    wy_emb = (float(_dyp) - canvas_v.y - view["pan"][1]) / z_v
                    _NS_PARTICLE_EMBERS.append({
                        "x": wx_emb + random.uniform(-4, 4),
                        "y": wy_emb + random.uniform(-4, 4),
                        "vx": random.uniform(-15.0, 15.0),
                        "vy": -random.uniform(25.0, 48.0), # bubble upward
                        "color": draw_col,
                        "born": time.time(),
                        "life": random.uniform(0.35, 0.55)
                    })

    # Additional continuous path styles.
    if mode in ("comet", "spark", "wave") and _signal_active and len(ipts) >= 2:
        def _style_point(distance):
            distance = distance % max(1.0, total)
            for _j in range(1, len(dists)):
                if dists[_j] >= distance:
                    _span=max(0.001,dists[_j]-dists[_j-1]); _u=(distance-dists[_j-1])/_span
                    return (ipts[_j-1][0]+(ipts[_j][0]-ipts[_j-1][0])*_u,
                            ipts[_j-1][1]+(ipts[_j][1]-ipts[_j-1][1])*_u)
            return ipts[-1]
        _now_style=time.time(); _phase_style=(_now_style*220.0*NS_WIRE_FLOW_SPEED)%max(1.0,total)
        if mode == "comet":
            for _ci in range(7):
                _cx,_cy=_style_point(_phase_style-_ci*9.0)
                _fade=max(0.15,1.0-_ci/7.0); _rr=max(2,int((width+3)*_fade))
                pygame.draw.circle(surface,tuple(int(c*_fade) for c in draw_col),(int(_cx),int(_cy)),_rr)
            _hx,_hy=_style_point(_phase_style); pygame.draw.circle(surface,(255,255,255),(int(_hx),int(_hy)),max(3,width+2))
        elif mode == "spark":
            for _si in range(6):
                _sd=_phase_style+total*(_si/6.0); _sx,_sy=_style_point(_sd)
                _tw=0.45+0.55*abs(math.sin(_now_style*7.0+_si*1.7)); _rr=max(2,int((width+2)*_tw))
                pygame.draw.circle(surface,(255,255,255),(int(_sx),int(_sy)),_rr)
                pygame.draw.line(surface,draw_col,(int(_sx-_rr*2),int(_sy)),(int(_sx+_rr*2),int(_sy)),1)
                pygame.draw.line(surface,draw_col,(int(_sx),int(_sy-_rr*2)),(int(_sx),int(_sy+_rr*2)),1)
        else:  # wave: a travelling chain whose size rises/falls like a signal waveform
            for _wi in range(12):
                _wd=_phase_style+total*(_wi/12.0); _wx,_wy=_style_point(_wd)
                _amp=(math.sin(_now_style*5.0+_wi*0.9)+1.0)*0.5; _rr=max(1,int(1+_amp*(width+1)))
                _wc=tuple(min(255,int(c*(0.55+0.45*_amp))) for c in draw_col)
                pygame.draw.circle(surface,_wc,(int(_wx),int(_wy)),_rr)

    # Animated dashed overlay for the classic flow/neon modes.
    show_flow = (mode not in ("off", "single_dot", "multi_dot", "comet", "spark", "wave")) and _signal_active
    if mode == "subtle" and not is_pulsing:
        show_flow = bool(animated and exec_wire)
    if show_flow and len(ipts) >= 2:
        # `dists`/`total` were computed unconditionally above so pulse
        # rendering remains safe even when animated dashes are disabled.
        # Speed varies: exec wires (loops/always-running) flow constantly;
        # data pulses move faster while fresh then slow.
        _now = time.time()
        if is_pulsing:
            spd = 260.0 * NS_WIRE_FLOW_SPEED
            _offset = (_now * spd) % 40.0
            dash_len = 10.0
            gap_len  = 16.0
            bright   = 0.55 + 0.45 * pulse_frac
        elif exec_wire:
            spd = (240.0 if mode == "neon" else 180.0) * NS_WIRE_FLOW_SPEED
            _offset = (_now * spd) % 32.0
            dash_len = 10.0 if mode == "neon" else 8.0
            gap_len  = 18.0 if mode == "neon" else 22.0
            bright   = 1.0 if mode == "neon" else 0.85
        else:
            spd = (280.0 if mode == "neon" else 220.0) * NS_WIRE_FLOW_SPEED
            _offset = (_now * spd) % 36.0
            dash_len = 7.0
            gap_len  = 20.0
            bright   = 1.0
        dash_col = tuple(min(255, int(c + (255 - c) * bright * 0.55)) for c in draw_col[:3])
        w_eff = max(2, width + (1 if is_pulsing else 0))
        # Walk along the arc drawing dash segments
        d = _offset
        while d < total:
            d_end = min(total, d + dash_len)
            seg_pts = []
            # find indices bracketing d and d_end
            for i in range(len(dists) - 1):
                if dists[i] <= d_end and dists[i+1] >= d:
                    # interpolate
                    if dists[i+1] > dists[i]:
                        ta = (d - dists[i]) / (dists[i+1] - dists[i])
                    else:
                        ta = 0.0
                    sx = ipts[i][0] + (ipts[i+1][0] - ipts[i][0]) * ta
                    sy = ipts[i][1] + (ipts[i+1][1] - ipts[i][1]) * ta
                    if not seg_pts:
                        seg_pts.append((int(sx), int(sy)))
                if dists[i] <= d_end and dists[i+1] >= d_end:
                    if dists[i+1] > dists[i]:
                        tb = (d_end - dists[i]) / (dists[i+1] - dists[i])
                    else:
                        tb = 1.0
                    ex = ipts[i][0] + (ipts[i+1][0] - ipts[i][0]) * tb
                    ey = ipts[i][1] + (ipts[i+1][1] - ipts[i][1]) * tb
                    seg_pts.append((int(ex), int(ey)))
                    break
                if dists[i] >= d and dists[i] <= d_end and len(seg_pts) > 0:
                    seg_pts.append(ipts[i])
            if len(seg_pts) >= 2:
                # For performance on short dashes just draw a single line
                # between the two endpoints rather than an arc segment.
                pygame.draw.line(surface, dash_col, seg_pts[0], seg_pts[-1], w_eff)
                # Lead head glow for pulse
                if is_pulsing and pulse_frac > 0.4:
                    _hr = max(2, w_eff + 1)
                    pygame.draw.circle(surface, (255,255,255), seg_pts[-1], _hr)
            d += dash_len + gap_len

    # Midpoint directional arrow for exec wires
    if exec_wire and len(ipts) >= 4:
        mid = len(ipts) // 2
        mx2, my2 = ipts[mid]
        if mid + 1 < len(ipts):
            nx, ny = ipts[mid+1][0] - ipts[mid][0], ipts[mid+1][1] - ipts[mid][1]
            nl = max(0.001, (nx**2+ny**2)**0.5)
            nx, ny = nx/nl, ny/nl
            _ar = max(4, width + 2)
            _perp = (-ny * _ar * 0.5, nx * _ar * 0.5)
            arrow_pts = [
                (int(mx2 + nx*_ar), int(my2 + ny*_ar)),
                (int(mx2 - nx*_ar + _perp[0]), int(my2 - ny*_ar + _perp[1])),
                (int(mx2 - nx*_ar - _perp[0]), int(my2 - ny*_ar - _perp[1])),
            ]
            pygame.draw.polygon(surface, draw_col, arrow_pts)

    # Canvas-debug signal trace. This is intentionally independent from the
    # selected path animation: whenever debug/data actually fires a wire, a
    # bright dot (or short trail) travels from source to destination.
    if (is_pulsing and pulse_frac > 0.02 and len(ipts) >= 2
            and NS_DEBUG_SIGNAL_DOTS != "off"):
        progress=max(0.0,min(1.0,1.0-pulse_frac))
        count=1 if NS_DEBUG_SIGNAL_DOTS == "single" else 5
        for _di in range(count):
            _p=max(0.0,progress-_di*0.045)
            target=total*_p
            lo,hi=0,len(dists)-1
            while lo<hi:
                mid=(lo+hi)//2
                if dists[mid]<target: lo=mid+1
                else: hi=mid
            _idx=max(1,lo); _span=max(0.001,dists[_idx]-dists[_idx-1])
            _u=(target-dists[_idx-1])/_span
            px=ipts[_idx-1][0]+(ipts[_idx][0]-ipts[_idx-1][0])*_u
            py=ipts[_idx-1][1]+(ipts[_idx][1]-ipts[_idx-1][1])*_u
            fade=max(0.18,1.0-_di/max(1,count)); rr=max(2,int((width+3)*fade))
            glow_r=rr+5; gs=pygame.Surface((glow_r*2,glow_r*2),pygame.SRCALPHA)
            pygame.draw.circle(gs,(*color[:3],int(110*fade)),(glow_r,glow_r),glow_r)
            surface.blit(gs,(int(px)-glow_r,int(py)-glow_r))
            pygame.draw.circle(surface,(255,255,255),(int(px),int(py)),rr)
            if _di>0: pygame.draw.circle(surface,color,(int(px),int(py)),max(1,rr-1))

# scaled with the canvas zoom. That mismatch is what made labels overlap
# or look "broken" when zooming: at low zoom the boxes/rows shrank but
# the text stayed full-size and spilled over; at high zoom the text
# stayed tiny relative to the enlarged nodes. This cache renders node
# text at a size that tracks zoom (clamped to a readable range) instead.
_NS_FONT_CACHE = {}
def ns_scaled_font(base_size, z, bold=False):
    size = max(7, min(30, int(round(base_size * max(0.6, min(z, 1.9))))))
    key = (size, bold)
    f = _NS_FONT_CACHE.get(key)
    if f is None:
        _fam = globals().get("_UI_90S_FONT_FAMILY", "couriernew") if _ui_90s_active() else "segoeui"
        f = pygame.font.SysFont(_fam, size, bold=bold)
        _NS_FONT_CACHE[key] = f
    return f

# Cached text rendering.
# font.render() rasterizes glyphs into a brand-new Surface every call, which
# is one of the most expensive things pygame does. The node canvas redraws
# every visible node's labels each frame, so without caching we were paying
# that cost hundreds of times a frame for text that hadn't changed at all.
# Keyed on the font object's identity (safe because fonts are themselves
# cached/reused -- see ns_scaled_font / _ns_popup_font above) plus the text,
# color, antialias flag, and optional background.
_NS_TEXT_CACHE = {}
_NS_TEXT_CACHE_MAX = 6000

def _ns_text(font, text, antialias=True, color=(255, 255, 255), background=None):
    try:
        if _ui_90s_active():
            antialias = False  # 90s: pixel text on the node canvas
    except Exception:
        pass
    key = (id(font), text, antialias, color, background)
    surf = _NS_TEXT_CACHE.get(key)
    if surf is not None:
        return surf
    surf = font.render(text, antialias, color) if background is None else font.render(text, antialias, color, background)
    if len(_NS_TEXT_CACHE) > _NS_TEXT_CACHE_MAX:
        _NS_TEXT_CACHE.clear()
    _NS_TEXT_CACHE[key] = surf
    return surf

_NS_POPUP_FONT_CACHE = {}
def _ns_popup_font(name, size, bold=True):
    key = (name, size, bold)
    f = _NS_POPUP_FONT_CACHE.get(key)
    if f is None:
        f = pygame.font.SysFont(name, size, bold=bold)
        _NS_POPUP_FONT_CACHE[key] = f
    return f

def ns_world_to_screen(canvas, wx, wy):
    view = modal.get("ns_view", {"pan": [0.0, 0.0], "zoom": 1.0})
    return canvas.x + view["pan"][0] + wx * view["zoom"], canvas.y + view["pan"][1] + wy * view["zoom"]

def ns_screen_to_world(canvas, sx, sy):
    view = modal.get("ns_view", {"pan": [0.0, 0.0], "zoom": 1.0})
    return (sx - canvas.x - view["pan"][0]) / view["zoom"], (sy - canvas.y - view["pan"][1]) / view["zoom"]

# ── Blueprint canvas annotations (non-runtime / non-signal) ───────────────
# Debug paths and free canvas text deliberately live OUTSIDE `ns_nodes` and
# `ns_links`. They are visual documentation only: no pins, no code generation,
# no graph diagnostics side-effects. This gives users real flowchart labels and
# group-to-group pathways without polluting gameplay logic.
_NS_ANNOTATION_COLORS = ((170, 130, 255), (90, 210, 255), (120, 235, 160),
                         (255, 205, 90), (255, 130, 170), (230, 230, 245))

def _ns_annotation_items(kind):
    key = "ns_canvas_texts" if kind == "text" else "ns_debug_paths"
    return modal.setdefault(key, [])

def _ns_annotation_by_id(kind, item_id):
    try:
        item_id = int(item_id)
    except (TypeError, ValueError):
        return None
    return next((item for item in _ns_annotation_items(kind)
                 if int(item.get("id", -1)) == item_id), None)

def _ns_annotation_new_id():
    ids = set()
    for kind in ("text", "path"):
        for item in _ns_annotation_items(kind):
            try: ids.add(int(item.get("id")))
            except (TypeError, ValueError): pass
    candidate = int(time.time() * 1000000) % 1000000000
    while candidate in ids:
        candidate += 1
    return candidate

def _ns_select_annotation(kind, item_id, edit=False):
    item = _ns_annotation_by_id(kind, item_id)
    if item is None:
        return False
    modal["ns_annotation_selected"] = {"kind": kind, "id": int(item["id"])}
    modal["ns_selected"] = None
    modal["ns_multi_selected"] = set()
    modal["ns_selected_groups"] = set()
    if edit:
        modal["focus"] = (f"ns_canvas_text:{int(item['id'])}" if kind == "text"
                          else f"ns_debug_path:{int(item['id'])}")
    return True

def ns_add_canvas_text(wx, wy, text=""):
    ns_snapshot()
    item = {"id": _ns_annotation_new_id(), "x": float(wx), "y": float(wy),
            "text": str(text or ""), "scale": 1.0, "color": [230, 230, 245],
            "align": "left", "locked": False}
    _ns_annotation_items("text").append(item)
    modal["ns_dirty"] = True
    _ns_select_annotation("text", item["id"], edit=True)
    return item

def ns_add_debug_path(from_group=None, to_group=None, from_pos=(0.0, 0.0),
                      to_pos=(0.0, 0.0), label=""):
    ns_snapshot()
    item = {"id": _ns_annotation_new_id(), "from_group": from_group,
            "to_group": to_group, "from_pos": [float(from_pos[0]), float(from_pos[1])],
            "to_pos": [float(to_pos[0]), float(to_pos[1])], "label": str(label or ""),
            "label_scale": 1.0, "color": [170, 130, 255], "arrow": True}
    _ns_annotation_items("path").append(item)
    modal["ns_dirty"] = True
    _ns_select_annotation("path", item["id"], edit=True)
    return item

def _ns_annotation_delete_selected():
    selected = modal.get("ns_annotation_selected") or {}
    kind, item_id = selected.get("kind"), selected.get("id")
    if kind not in ("text", "path") or _ns_annotation_by_id(kind, item_id) is None:
        return False
    ns_snapshot()
    items = _ns_annotation_items(kind)
    items[:] = [item for item in items if int(item.get("id", -1)) != int(item_id)]
    modal["ns_annotation_selected"] = None
    modal["focus"] = None
    modal["ns_dirty"] = True
    push_toast("Canvas text deleted" if kind == "text" else "Debug path deleted", "info", 1.5)
    return True

def _ns_annotation_open_color_picker():
    """Open the full colour picker for the selected canvas text/path label.

    The palette toolbar button used to CYCLE through a handful of preset
    colours (`_NS_ANNOTATION_COLORS`).  That is fine for a rough change but a
    user who wants a specific colour (e.g. a dark shade so a near-white label
    becomes readable) was stuck — it just kept advancing presets instead of
    offering the picker.  This opens the real wheel + palette + hex + RGB and
    writes the result back onto the annotation's `color`, and it works for
    BOTH free canvas text and debug-path labels.
    """
    sel = modal.get("ns_annotation_selected") or {}
    kind, item_id = sel.get("kind"), sel.get("id")
    item = _ns_annotation_by_id(kind, item_id) if kind in ("text", "path") else None
    if item is None:
        return False
    ns_snapshot()
    current = tuple(int(v) for v in list(item.get("color", _NS_ANNOTATION_COLORS[0]))[:3])
    def _apply(c):
        item["color"] = list(c[:3])
        modal["ns_dirty"] = True
    open_color_picker(initial_color=current, callback=_apply,
                      title="Canvas Text Color" if kind == "text" else "Debug Path Label Color")
    return True


def _ns_annotation_adjust_selected(scale_delta=0.0, cycle_color=False):
    selected = modal.get("ns_annotation_selected") or {}
    kind, item_id = selected.get("kind"), selected.get("id")
    item = _ns_annotation_by_id(kind, item_id) if kind in ("text", "path") else None
    if item is None:
        return False
    ns_snapshot()
    scale_key = "scale" if kind == "text" else "label_scale"
    if scale_delta:
        item[scale_key] = max(0.5, min(4.0, float(item.get(scale_key, 1.0)) + float(scale_delta)))
    if cycle_color:
        cur = tuple(item.get("color", _NS_ANNOTATION_COLORS[0])[:3])
        try: idx = _NS_ANNOTATION_COLORS.index(cur)
        except ValueError: idx = -1
        item["color"] = list(_NS_ANNOTATION_COLORS[(idx + 1) % len(_NS_ANNOTATION_COLORS)])
    modal["ns_dirty"] = True
    return True

def _ns_draw_canvas_annotations(canvas, view, mouse_pos):
    """Draw passive documentation paths/text over group plates but under nodes."""
    modal["_ns_canvas_text_hits"] = []
    modal["_ns_debug_path_hits"] = []
    if canvas is None:
        return
    z = max(0.001, float(view.get("zoom", 1.0)))
    selected = modal.get("ns_annotation_selected") or {}

    def world_to_screen(pos):
        return (canvas.x + float(view["pan"][0]) + float(pos[0]) * z,
                canvas.y + float(view["pan"][1]) + float(pos[1]) * z)
    def group_rect(gid):
        g = _ns_group_by_id(gid) if gid is not None else None
        if not g:
            return None
        x, y = world_to_screen((float(g.get("x", 0)), float(g.get("y", 0))))
        return pygame.Rect(int(x), int(y), max(30, int(float(g.get("w", 240))*z)),
                           max(24, int(float(g.get("h", 140))*z)))
    def endpoint(gid, fallback, toward):
        rect = group_rect(gid)
        if rect is None:
            return pygame.Vector2(world_to_screen(fallback))
        center = pygame.Vector2(rect.center)
        delta = pygame.Vector2(toward) - center
        if abs(delta.x) >= abs(delta.y):
            return pygame.Vector2(rect.right if delta.x >= 0 else rect.left, rect.centery)
        return pygame.Vector2(rect.centerx, rect.bottom if delta.y >= 0 else rect.top)

    old_clip = screen.get_clip()
    screen.set_clip(canvas)
    for path in _ns_annotation_items("path"):
        try:
            raw_a = world_to_screen(path.get("from_pos", (0, 0)))
            raw_b = world_to_screen(path.get("to_pos", (0, 0)))
            a = endpoint(path.get("from_group"), path.get("from_pos", (0, 0)), raw_b)
            b = endpoint(path.get("to_group"), path.get("to_pos", (0, 0)), raw_a)
            delta = b - a
            if delta.length_squared() < 4:
                continue
            col = tuple(int(v) for v in list(path.get("color", [170,130,255]))[:3])
            is_selected = selected.get("kind") == "path" and selected.get("id") == path.get("id")
            bend = max(20.0, min(110.0, abs(delta.x) * 0.28))
            sx = 1.0 if delta.x >= 0 else -1.0
            p1 = a + pygame.Vector2(bend * sx, 0)
            p2 = b - pygame.Vector2(bend * sx, 0)
            pts = [(int(a.x), int(a.y)), (int(p1.x), int(p1.y)), (int(p2.x), int(p2.y)), (int(b.x), int(b.y))]
            pygame.draw.lines(screen, (*col, 255), False, pts, max(2, int(2*z)))
            # Dashed cross-ticks make this clearly a documentation path, not a
            # gameplay signal wire.
            for t in (.22, .42, .62, .82):
                q = a.lerp(b, t)
                pygame.draw.circle(screen, (*col, 210), (int(q.x), int(q.y)), max(1, int(2*z)))
            if path.get("arrow", True):
                direction = (b - p2)
                if direction.length_squared() <= 1e-8: direction = delta
                direction = direction.normalize()
                perp = pygame.Vector2(-direction.y, direction.x)
                head = max(6, int(8*z))
                tip = b
                pygame.draw.polygon(screen, (*col, 255), [tip, tip-direction*head+perp*(head*.55), tip-direction*head-perp*(head*.55)])
            mid = a.lerp(b, .5)
            label = str(path.get("label", "") or "")
            if not label and is_selected:
                label = "type path label…"
            if label:
                fnt = ns_scaled_font(max(9, int(11*float(path.get("label_scale", 1.0)))), z, bold=True)
                lines = label.split("\n")
                rendered = [fnt.render(line or " ", True, (255,255,255)) for line in lines]
                w = max(s.get_width() for s in rendered) + 12
                h = sum(s.get_height() for s in rendered) + 8
                lr = pygame.Rect(int(mid.x-w/2), int(mid.y-h/2), w, h)
                bg = pygame.Surface(lr.size, pygame.SRCALPHA)
                pygame.draw.rect(bg, (*col, 230 if is_selected else 205), bg.get_rect(), border_radius=6)
                screen.blit(bg, lr.topleft)
                yy = lr.y + 4
                for surf in rendered:
                    screen.blit(surf, (lr.centerx-surf.get_width()//2, yy)); yy += surf.get_height()
                modal["_ns_debug_path_hits"].append((path.get("id"), lr))
            if is_selected:
                pygame.draw.circle(screen, (255,255,255), (int(a.x),int(a.y)), max(3,int(4*z)), 1)
                pygame.draw.circle(screen, (255,255,255), (int(b.x),int(b.y)), max(3,int(4*z)), 1)
        except Exception:
            pass

    for note in _ns_annotation_items("text"):
        try:
            px, py = world_to_screen((float(note.get("x",0)), float(note.get("y",0))))
            col = tuple(int(v) for v in list(note.get("color", [230,230,245]))[:3])
            is_selected = selected.get("kind") == "text" and selected.get("id") == note.get("id")
            raw = str(note.get("text", "") or "")
            if not raw and is_selected: raw = "Type…"
            if not raw: continue
            fnt = ns_scaled_font(max(10, int(16*float(note.get("scale", 1.0)))), z, bold=False)
            rendered = [fnt.render(line or " ", True, col) for line in raw.split("\n")]
            w = max(s.get_width() for s in rendered)
            h = sum(s.get_height() for s in rendered)
            rect = pygame.Rect(int(px), int(py), max(1,w), max(1,h))
            if note.get("align") == "center": rect.x -= rect.width//2
            elif note.get("align") == "right": rect.x -= rect.width
            if is_selected:
                # Selection highlight.  `ui_draw_rect` draws straight onto the
                # (non-alpha) display surface, where pygame DROPS the alpha
                # channel, so `(*col, 75)` was being rendered as a SOLID box in
                # the text colour.  For the near-white default that is a solid
                # white box with white text on it -> "white box, no text".  Draw
                # the translucent tint + border onto a per-pixel-alpha surface
                # and blit it so the text (drawn full-opacity afterwards) stays
                # readable.
                _hsel = pygame.Surface((rect.w + 10, rect.h + 8), pygame.SRCALPHA)
                pygame.draw.rect(_hsel, (*col, 75), _hsel.get_rect(), border_radius=5)
                pygame.draw.rect(_hsel, col, _hsel.get_rect(), width=1, border_radius=5)
                screen.blit(_hsel, (rect.x - 5, rect.y - 4))
            yy=rect.y
            for surf in rendered:
                x = rect.x if note.get("align") == "left" else rect.centerx-surf.get_width()//2 if note.get("align") == "center" else rect.right-surf.get_width()
                screen.blit(surf,(x,yy)); yy += surf.get_height()
            modal["_ns_canvas_text_hits"].append((note.get("id"), rect.inflate(8,6)))
        except Exception:
            pass
    screen.set_clip(old_clip)

def visual_graph_path(script_file):
    if not script_file:
        return None
    return os.path.join(SCRIPTS_DIR, script_file + ".graph.json")

def _sync_sprite_image_nodes(script_file, tag, rel_path):
    """When an image is assigned to a sprite tag in Character Settings, push that
    path into any Set Sprite Image node(s) in that character's graph using the
    same tag, so the node's image_path field stays in sync with the panel
    instead of silently going stale. Writes straight to the .graph.json on disk
    (so it works even if the node editor isn't currently open for this script),
    and also patches the live in-memory graph if it happens to be the one
    currently loaded in the node editor, so an open editor doesn't clobber this
    with a stale save afterward."""
    if not script_file or not tag:
        return
    path = visual_graph_path(script_file)
    if not path or not os.path.isfile(path):
        return
    try:
        with open(path, "r") as f:
            data = json.load(f)
    except Exception:
        return
    changed = False
    for node in data.get("nodes", {}).values():
        if node.get("type") == "animation_set_sprite_image" and node.get("props", {}).get("sprite_tag") == tag:
            node.setdefault("props", {})["image_path"] = rel_path or ""
            changed = True
    if not changed:
        return
    try:
        with open(path, "w") as f:
            json.dump(data, f, indent=2)
    except Exception:
        return
    if modal.get("ns_loaded_script") == script_file:
        for node in modal.get("ns_nodes", {}).values():
            if node.get("type") == "animation_set_sprite_image" and node.get("props", {}).get("sprite_tag") == tag:
                node.setdefault("props", {})["image_path"] = rel_path or ""

def save_visual_graph_data(script_file):
    path = visual_graph_path(script_file)
    if not path:
        return False
    data = {
        "version": 2,
        "nodes": modal.get("ns_nodes", {}),
        "links": modal.get("ns_links", []),
        "next_id": modal.get("ns_next_id", 1),
        "view": modal.get("ns_view", {"pan": [0, 0], "zoom": 1.0}),
        "wire_style": modal.get("ns_wire_style", "bezier"),
        "sort_mode": modal.get("ns_sort_mode", "topological"),
        "wire_anim_mode": modal.get("ns_wire_anim_mode", "flow"),
        "smart_groups": modal.get("ns_smart_groups", []),
        "canvas_texts": modal.get("ns_canvas_texts", []),
        "debug_paths": modal.get("ns_debug_paths", []),
        "bookmarks": modal.get("ns_bookmarks", []),
        "hide_mode": modal.get("ns_hide_mode", "transparent"),
        "notepad_text": modal.get("ns_notepad_text",""),
        "notepad_search": modal.get("ns_notepad_search",""),
        "notepad_scroll": modal.get("ns_notepad_scroll",0.0),
    }
    try:
        with open(path, "w") as f:
            json.dump(data, f, indent=2)
        modal["ns_dirty"] = False
        modal["ns_source_only"] = False
        modal["ns_loaded_script"] = script_file
        return True
    except Exception as e:
        push_toast(f"Could not save blueprint graph: {e}", "error")
        return False

def set_blueprint_autosave_status(text, kind="info"):
    global blueprint_autosave_status, blueprint_autosave_status_kind, blueprint_autosave_status_time
    blueprint_autosave_status = text
    blueprint_autosave_status_kind = kind
    blueprint_autosave_status_time = time.time()

def save_blueprint_autosave_preferences():
    _editor_config["blueprint_autosave_enabled"] = blueprint_autosave_enabled
    _editor_config["blueprint_autosave_interval"] = blueprint_autosave_interval
    save_editor_config(_editor_config)

def cycle_blueprint_autosave_interval(direction):
    global blueprint_autosave_interval, blueprint_last_autosave
    values = BLUEPRINT_AUTOSAVE_INTERVALS
    try:
        index = values.index(blueprint_autosave_interval)
    except ValueError:
        index = values.index(30)
    blueprint_autosave_interval = values[max(0, min(len(values)-1, index + direction))]
    blueprint_last_autosave = time.time()
    save_blueprint_autosave_preferences()
    set_blueprint_autosave_status(f"Autosave interval: {blueprint_autosave_interval}s")

def autosave_visual_blueprint():
    """Quietly save both generated Python and the editable graph sidecar."""
    global blueprint_last_autosave
    errors = validate_graph(modal.get("ns_nodes", {}), modal.get("ns_links", []))
    if errors:
        blueprint_last_autosave = time.time()
        set_blueprint_autosave_status(f"Autosave skipped · {len(errors)} error(s)", "warning")
        return False
    code = vs_build_script_code()
    if not code:
        blueprint_last_autosave = time.time()
        set_blueprint_autosave_status("Autosave skipped · add an Event", "warning")
        return False
    fname = modal.get("script_file") or sanitize_script_filename(modal.get("ns_save_name"))
    if not fname:
        owner = modal.get("fields", {}).get("Name", "character")
        fname = sanitize_script_filename(f"{owner}_blueprint") or "autosave_blueprint.py"
    try:
        os.makedirs(SCRIPTS_DIR, exist_ok=True)
        compile(code, fname, "exec")
        with open(os.path.join(SCRIPTS_DIR, fname), "w") as f:
            f.write(code)
        if not save_visual_graph_data(fname):
            return False
        modal["script_file"] = fname
        modal["ns_save_name"] = fname[:-3] if fname.endswith(".py") else fname
        blueprint_last_autosave = time.time()
        set_blueprint_autosave_status(f"Autosaved · {time.strftime('%H:%M:%S')}", "success")
        return True
    except Exception as e:
        blueprint_last_autosave = time.time()
        set_blueprint_autosave_status(f"Autosave failed · {e}", "error")
        return False

def maybe_autosave_visual_blueprint():
    if _OBS_RECORDING_ACTIVE or (is_recording and record_mode=="apu") or not blueprint_autosave_enabled or modal.get("type") != "visual_scripter":
        return
    if time.time() - blueprint_last_autosave >= blueprint_autosave_interval:
        autosave_visual_blueprint()

def load_visual_graph_data(script_file):
    path = visual_graph_path(script_file)
    if not path or not os.path.isfile(path):
        return False
    try:
        with open(path, "r") as f:
            data = json.load(f)
        modal["ns_nodes"] = {int(k): v for k, v in data.get("nodes", {}).items()}
        modal["ns_links"] = list(data.get("links", []))
        # Legacy pin renames: Interpolate/Ease Value's "t"/"eased_t" outputs
        # became "progress"/"eased_progress" (the old names read like inputs
        # and confused everyone). Re-point old wires so they draw correctly;
        # codegen accepts both spellings either way.
        _pin_renames = {("math_interpolate", "t"): "progress",
                        ("math_interpolate", "eased_t"): "eased_progress",
                        ("math_ease_value", "eased_t"): "eased_progress"}
        for _lnk in modal["ns_links"]:
            _src = modal["ns_nodes"].get(_lnk.get("from"))
            if isinstance(_src, dict):
                _new = _pin_renames.get((str(_src.get("type", "")), str(_lnk.get("from_pin", ""))))
                if _new:
                    _lnk["from_pin"] = _new
        modal["ns_next_id"] = int(data.get("next_id", 1))
        modal["ns_view"] = data.get("view", {"pan": [0.0, 0.0], "zoom": 1.0})
        modal["ns_wire_style"] = _ns_wire_style_key(data.get("wire_style", "bezier"))
        modal["ns_sort_mode"] = data.get("sort_mode", "topological")
        modal["ns_wire_anim_mode"] = data.get("wire_anim_mode", "flow")
        modal["ns_smart_groups"] = data.get("smart_groups", [])
        modal["ns_canvas_texts"] = [x for x in data.get("canvas_texts", []) if isinstance(x, dict)]
        modal["ns_debug_paths"] = [x for x in data.get("debug_paths", []) if isinstance(x, dict)]
        modal["ns_annotation_selected"] = None
        modal["ns_annotation_tool"] = None
        modal["ns_debug_path_draft"] = None
        modal["ns_bookmarks"] = data.get("bookmarks", [])
        modal["ns_hide_mode"] = data.get("hide_mode", modal.get("ns_hide_mode", "transparent"))
        modal["ns_notepad_text"] = str(data.get("notepad_text","") or "")
        modal["ns_notepad_search"] = str(data.get("notepad_search","") or "")
        modal["ns_notepad_scroll"] = float(data.get("notepad_scroll",0.0) or 0.0)
        modal["ns_notepad_cursor"] = len(modal["ns_notepad_text"])
        modal["ns_notepad_anchor"] = None
        modal["ns_dirty"] = False
        modal["ns_source_only"] = False
        modal["ns_loaded_script"] = script_file
        return True
    except Exception as e:
        push_toast(f"Could not load saved blueprint graph: {e}", "error")
        return False


def init_starter_blueprint_graph(script_file=None):
    """Initializes and saves a clean starter blueprint graph for a new script."""
    if "reset_visual_graph" in globals():
        reset_visual_graph()
    if script_file:
        modal["ns_loaded_script"] = script_file
        modal["script_file"] = script_file
        if "save_visual_graph_data" in globals():
            save_visual_graph_data(script_file)
        try:
            if "vs_build_script_code" in globals() and "SCRIPTS_DIR" in globals():
                code = vs_build_script_code()
                if code:
                    with open(os.path.join(SCRIPTS_DIR, script_file), "w", encoding="utf-8") as f:
                        f.write(code)
        except Exception:
            pass

def reset_visual_graph():
    modal["ns_nodes"] = {1: {"id": 1, "type": "event_on_hit", "x": 40, "y": 140,
                              "props": {}, "ui_scale": 1.0, "ui_width": 1.0, "ui_height": 1.0}}
    modal["ns_links"] = []
    modal["ns_next_id"] = 2
    modal["ns_view"] = {"pan": [0.0, 0.0], "zoom": 1.0}
    modal["ns_wire_style"] = "bezier"
    modal["ns_sort_mode"] = "topological"
    modal["ns_wire_anim_mode"] = "flow"
    modal["ns_smart_groups"] = []
    modal["ns_canvas_texts"] = []
    modal["ns_debug_paths"] = []
    modal["ns_annotation_selected"] = None
    modal["ns_debug_path_draft"] = None
    modal["ns_bookmarks"] = []
    modal["ns_undo"] = []
    modal["ns_redo"] = []
    modal["ns_dirty"] = False
    modal["ns_preserved_params"] = {}
    modal["ns_notepad_text"] = ""
    modal["ns_notepad_search"] = ""
    modal["ns_notepad_scroll"] = 0.0
    modal["ns_notepad_cursor"] = 0
    modal["ns_notepad_anchor"] = None

def auto_generate_graph_from_script(script_file):
    """Best-effort Python -> graph importer.

    Python is more expressive than the node system, so conversion cannot be
    perfectly reversible. This importer recognizes hooks, timers, exposed
    PARAMS, target selection, and the engine ctx.* actions used by bundled
    traits. Unknown bodies receive a visible Comment node instead of silently
    disappearing.
    """
    path = os.path.join(SCRIPTS_DIR, script_file or "")
    try:
        with open(path, "r") as source_file:
            source = source_file.read()
        tree = ast.parse(source, filename=path)
    except Exception as e:
        push_toast(f"Could not parse script into a graph: {e}", "error", 7.0)
        return False

    modal["ns_nodes"] = {}
    modal["ns_links"] = []
    modal["ns_next_id"] = 1
    modal["ns_view"] = {"pan": [20.0, 20.0], "zoom": 0.78}
    modal["ns_undo"] = []
    modal["ns_redo"] = []
    modal["ns_imported_source"] = source
    modal["ns_show_imported_source"] = True
    # Node IDs are being regenerated from scratch below, so any Smart Group
    # left over from the previous graph would reference IDs that no longer
    # exist -- that produced empty/misplaced group plates with the real
    # nodes scattered outside them. Clear them; Generate Graph builds a
    # flat layout and groups can be re-made afterward if wanted.
    modal["ns_smart_groups"] = []
    modal["ns_canvas_texts"] = []
    modal["ns_debug_paths"] = []
    modal["ns_annotation_selected"] = None
    modal["ns_debug_path_draft"] = None
    modal["ns_bookmarks"] = []

    def add_node(node_type, x, y, props=None):
        cls = NODE_DEFS.get(node_type)
        if cls is None:
            return None
        node_id = modal["ns_next_id"]
        modal["ns_next_id"] += 1
        defaults = {name: spec.default for name, spec in cls.properties.items()}
        defaults.update(props or {})
        modal["ns_nodes"][node_id] = {
            "id": node_id, "type": node_type,
            "x": float(x), "y": float(y), "props": defaults,
        }
        return node_id

    def link(source_id, source_pin, target_id, target_pin):
        if source_id and target_id:
            modal["ns_links"].append({
                "from": source_id, "from_pin": source_pin,
                "to": target_id, "to_pin": target_pin,
            })

    params = peek_script_params(script_file)
    hook_to_event = {
        "on_spawn": "event_on_spawn", "on_start": "event_on_start",
        "on_tick": "event_on_tick", "on_hit": "event_on_hit",
        "on_motion_event_hit": "event_on_motion_event_hit",
        "on_motion_clip_end": "event_on_motion_clip_end",
        "on_motion_clip_loop": "event_on_motion_clip_loop",
        "on_motion_event_activate": "event_on_motion_event_activate",
        "on_motion_event_impact": "event_on_motion_event_impact",
        "on_critical_hit": "event_on_critical_hit",
        "on_damage_taken": "event_on_damage_taken",
        "on_damage_dealt": "event_on_damage_dealt", "on_kill": "event_on_kill",
        "on_death": "event_on_death", "on_heal": "event_on_heal",
        "on_collision": "event_on_collision", "on_ally_died": "event_on_ally_died",
        "on_character_touch": "event_on_character_touch",
    }
    functions = [node for node in tree.body
                 if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
                 and node.name in hook_to_event]
    if not functions:
        functions = [None]

    parameter_nodes = {}
    param_y = 80
    for name, default in params.items():
        lower_name = name.lower()
        if isinstance(default, bool):
            node_type = "parameter_boolean"
        elif isinstance(default, (int, float)) and not isinstance(default, bool):
            node_type = "parameter_number"
        elif isinstance(default, str) and any(word in lower_name for word in ("animation", "anim", "clip")):
            node_type = "parameter_animation"
        else:
            node_type = "parameter_text"
        props = {"name": name, "default": default}
        parameter_nodes[name] = add_node(node_type, 930, param_y, props)
        param_y += 95

    lower_full = source.lower()
    recognized_count = 0
    for row, function in enumerate(functions):
        y = 130 + row * 250
        if function is None:
            event_id = add_node("event_on_spawn", 40, y)
            body_text = lower_full
            hook_name = "on_spawn"
        else:
            event_id = add_node(hook_to_event[function.name], 40, y)
            body_text = (ast.get_source_segment(source, function) or "").lower()
            hook_name = function.name

        flow_id = event_id
        flow_pin = ""
        # Recognize timer-accumulator traits and convert them to Every X Seconds.
        if hook_name == "on_tick" and ("_timer" in body_text or "interval" in body_text):
            interval = params.get("interval", 2.0)
            timer_id = add_node("timing_every_x_seconds", 270, y,
                                {"interval": interval, "variation": 0.0})
            link(flow_id, flow_pin, timer_id, "")
            flow_id = timer_id
            flow_pin = ""
            if "interval" in parameter_nodes:
                link(parameter_nodes["interval"], "value", timer_id, "interval")

        # Determine how the script chooses its victim.
        target_id = None
        target_output_pin = "character"
        if function is not None and any(arg.arg == "other" for arg in function.args.args):
            target_id = add_node("target_event_other", 480, y + 145)
        elif "random.choice" in body_text or "characters_in_radius" in body_text or "random_character" in body_text:
            target_id = add_node("target_find_random_opponent", 470, y + 120, {
                "min_distance": params.get("min_distance", 0),
                "max_distance": params.get("max_distance", 0),
                "team_filter": "all",
                "fallback_any": True,
                "include_self": False,
            })
            target_output_pin = "target"
            link(flow_id, flow_pin, target_id, "")
            flow_id = target_id
            flow_pin = "found"
            if "min_distance" in parameter_nodes:
                link(parameter_nodes["min_distance"], "value", target_id, "min_distance")
            if "max_distance" in parameter_nodes:
                link(parameter_nodes["max_distance"], "value", target_id, "max_distance")
            no_target_print = add_node("utility_print", 690, y + 250, {
                "message": "Target search found NO valid target",
                "show_on_screen": True,
            })
            link(target_id, "not_found", no_target_print, "")

        # Bundle common ctx calls into their closest high-level node.
        action_type = None
        props = {}
        if ("chain_lightning" in body_text or "lightning" in body_text
                or ("lightning" in str(script_file).lower()
                    and ("play_animation_at" in body_text
                         or "deal_script_damage" in body_text
                         or "damage_radius" in body_text))):
            action_type = "weather_lightning"
            props = {
                "animation": params.get("animation", "lightning"),
                "damage": params.get("damage", 30),
                "radius": params.get("impact_radius", params.get("radius", 45)),
                "jumps": params.get("chain_jumps", 0),
                "jump_range": params.get("chain_range", 100),
                "decay": params.get("chain_decay", .8),
                "team_filter": "all",
                "allow_self": params.get("allow_self_damage", False),
            }
        elif "spawn_explosion" in body_text:
            action_type = "explosive_spawn"
            props = {"animation": params.get("animation", "explosion"),
                     "damage": params.get("damage", 40), "radius": params.get("radius", 90),
                     "force": params.get("knockback", 300),
                     "allow_self": params.get("allow_self_damage", False),
                     "falloff": params.get("falloff", .5)}
        elif "create_zone" in body_text and ("slow" in body_text or "freeze" in lower_full):
            action_type = "weather_slow_field"
            props = {"animation": params.get("animation", "freeze"),
                     "radius": params.get("radius", 90),
                     "duration": params.get("field_duration", params.get("duration", 4)),
                     "slow": params.get("slow_multiplier", .75)}
        elif "create_zone" in body_text and ("meteor" in lower_full or "warning" in body_text):
            action_type = "weather_meteor"
            props = {"animation": params.get("animation", "meteor"),
                     "radius": params.get("radius", 100), "damage": params.get("damage", 50),
                     "warning_time": params.get("warning_time", 1.5),
                     "allow_self": params.get("allow_self_damage", False)}
        elif "create_zone" in body_text:
            action_type = "weather_fire_zone"
            props = {"animation": params.get("animation", "fire"),
                     "radius": params.get("radius", 80),
                     "duration": params.get("zone_duration", params.get("duration", 5)),
                     "interval": params.get("tick_interval", .5),
                     "damage": params.get("damage_per_tick", params.get("damage", 5)),
                     "allow_self": params.get("allow_self_damage", False)}
        elif "ctx.heal" in body_text:
            action_type = "gameplay_heal"
            props = {"amount": params.get("heal", params.get("amount", 10))}
        elif "remove_collisions" in body_text:
            action_type = "gameplay_collision_toggle"
            props = {"duration": params.get("duration", 1)}
        elif "spawn_library_character_in_swarm" in body_text:
            action_type = "swarm_spawn_library"
            props = {"character": params.get("bee_name", params.get("character", "")),
                     "count": params.get("max_swarm_size", params.get("swarm_size", params.get("count", 3))),
                     "radius": params.get("swarm_radius", params.get("radius", 40))}
        elif "spawn_swarm" in body_text or "spawn_duplicate" in body_text:
            action_type = "swarm_spawn"
            props = {"count": params.get("count", 3), "radius": params.get("radius", 40)}
        elif "play_animation_at" in body_text:
            action_type = "animation_on_target" if "target=" in body_text else "animation_at_position"
            props = {"animation": params.get("animation", ""),
                     "duration": params.get("duration", 0),
                     "scale": params.get("animation_scale", params.get("scale", 1))}
        elif "deal_script_damage" in body_text or "damage_radius" in body_text:
            action_type = "area_damage_radius" if "damage_radius" in body_text else "gameplay_deal_damage"
            props = {"damage": params.get("damage", params.get("amount", 10)),
                     "radius": params.get("radius", params.get("impact_radius", 45)),
                     "allow_self": params.get("allow_self_damage", False)}

        if action_type:
            action_id = add_node(action_type, 740, y, props)
            link(flow_id, flow_pin, action_id, "")
            recognized_count += 1
            if target_id:
                target_cls = NODE_DEFS.get(action_type)
                if target_cls and any(pin.name == "target" for pin in target_cls.inputs):
                    link(target_id, target_output_pin, action_id, "target")
                # Wire the explicit position too, even when the action also
                # accepts a target. This makes the generated graph visually
                # complete and keeps AoE impact centered on the victim.
                if target_cls and any(pin.name == "position" for pin in target_cls.inputs):
                    if target_output_pin == "target":
                        link(target_id, "position", action_id, "position")
                    else:
                        position_id = add_node("target_character_position", 610, y + 145)
                        link(target_id, target_output_pin, position_id, "character")
                        link(position_id, "position", action_id, "position")

            action_cls = NODE_DEFS.get(action_type)
            action_title = action_cls.title if action_cls else action_type
            if action_cls and any(pin.type == EXEC and pin.name == "" for pin in action_cls.outputs):
                if target_id:
                    triggered_print = add_node("utility_print_target", 1010, y, {
                        "prefix": f"{action_title} affected",
                        "show_on_screen": True,
                    })
                    link(action_id, "", triggered_print, "")
                    link(target_id, target_output_pin, triggered_print, "target")
                else:
                    triggered_print = add_node("utility_print", 1010, y, {
                        "message": f"{action_title} triggered",
                        "show_on_screen": True,
                    })
                    link(action_id, "", triggered_print, "")

            # Wire matching exposed parameters whenever the action supports them.
            action_cls = NODE_DEFS.get(action_type)
            action_inputs = {pin.name for pin in action_cls.inputs} if action_cls else set()
            aliases = {
                "impact_radius": "radius", "allow_self_damage": "allow_self",
                "chain_jumps": "jumps", "chain_range": "jump_range",
                "chain_decay": "decay", "damage_per_tick": "damage",
                "zone_duration": "duration", "field_duration": "duration",
                "tick_interval": "interval", "slow_multiplier": "slow",
                "animation_scale": "scale",
            }
            for parameter_name, parameter_id in parameter_nodes.items():
                input_name = aliases.get(parameter_name, parameter_name)
                if input_name in action_inputs:
                    link(parameter_id, "value", action_id, input_name)
        else:
            comment_id = add_node("utility_comment", 330, y,
                                  {"text": f"Imported {hook_name}: logic needs manual node mapping"})
            link(flow_id, "", comment_id, "")

    # Keep unsupported source PARAMS in the generated PARAMS dictionary, but
    # do not clutter the canvas with disconnected value nodes. They were the
    # source of misleading "generated value is not used" warnings.
    linked_sources = {wire.get("from") for wire in modal["ns_links"]}
    unused_parameter_ids = {
        node_id for node_id, node in modal["ns_nodes"].items()
        if str(node.get("type", "")).startswith("parameter_")
        and node_id not in linked_sources
    }
    for node_id in unused_parameter_ids:
        modal["ns_nodes"].pop(node_id, None)

    if not modal["ns_nodes"]:
        reset_visual_graph()
        return False

    modal["ns_dirty"] = True
    modal["ns_source_only"] = False
    modal["ns_loaded_script"] = script_file
    save_visual_graph_data(script_file)
    set_blueprint_autosave_status(
        f"Generated graph · {recognized_count} action(s) recognized",
        "success" if recognized_count else "warning",
    )
    push_toast(
        f"Generated an editable graph from {script_file}: {recognized_count} action(s) recognized. Review warnings before saving.",
        "success" if recognized_count else "info", 8.0,
    )
    return True

def _script_content_hash(script_file):
    """Hash of a script's current source, used to tell whether the user
    has actually edited it since they last dismissed the Generate Graph
    prompt. Returns None if the file can't be read."""
    if not script_file:
        return None
    try:
        with open(os.path.join(SCRIPTS_DIR, script_file), "rb") as f:
            return hashlib.md5(f.read()).hexdigest()
    except Exception:
        return None

def upgrade_prompt_dismissed(script_file):
    """True only if the user dismissed the Generate Graph prompt for this
    exact script content. Editing the .py afterward invalidates the
    dismissal, so the prompt correctly comes back without needing to
    rename the file."""
    dismissed = modal.get("ns_upgrade_dismissed", {})
    if script_file not in dismissed:
        return False
    return dismissed[script_file] == _script_content_hash(script_file)

def graph_is_placeholder_for_script(script_file):
    """Detect the old/default one-event graph beside a real Python trait."""
    if not script_file:
        return False
    nodes = modal.get("ns_nodes", {})
    meaningful_nodes = [
        node for node in nodes.values()
        if not str(node.get("type", "")).startswith("event_")
        and node.get("type") != "utility_comment"
    ]
    if meaningful_nodes:
        return False
    try:
        with open(os.path.join(SCRIPTS_DIR, script_file), "r") as source_file:
            source = source_file.read().lower()
    except Exception:
        return False
    # A hook-only empty script can legitimately have one Event node. A script
    # with engine calls/timers/damage clearly needs action nodes as well.
    markers = (
        "ctx.", "random.choice", "characters_in_radius", "_timer",
        "damage", "heal(", "spawn_", "play_animation", "set_state",
    )
    return any(marker in source for marker in markers)

def script_has_syntax_error(script_file):
    if not script_file:
        return False
    try:
        with open(os.path.join(SCRIPTS_DIR, script_file), "r") as source_file:
            ast.parse(source_file.read(), filename=script_file)
        return False
    except (SyntaxError, OSError):
        return True

def repair_loaded_graph_script(script_file):
    """Regenerate malformed Python from an already loaded valid sidecar."""
    errors = validate_graph(modal.get("ns_nodes", {}), modal.get("ns_links", []))
    if errors:
        return False
    code = vs_build_script_code()
    if not code or code.startswith("# Validation errors"):
        return False
    try:
        compile(code, script_file, "exec")
        with open(os.path.join(SCRIPTS_DIR, script_file), "w") as script_file_handle:
            script_file_handle.write(code)
        push_toast(f"Repaired malformed generated script: {script_file}", "success", 7.0)
        return True
    except Exception as error:
        push_toast(f"Could not repair {script_file}: {error}", "error", 7.0)
        return False

def graph_needs_converter_upgrade():
    nodes = modal.get("ns_nodes", {})
    links = modal.get("ns_links", [])
    linked_sources = {wire.get("from") for wire in links}
    if any(str(node.get("type", "")).startswith("parameter_") and node_id not in linked_sources
           for node_id, node in nodes.items()):
        return True
    if any(node.get("type") == "target_random_in_range" for node in nodes.values()):
        try:
            with open(os.path.join(SCRIPTS_DIR, modal.get("script_file") or ""), "r") as source_file:
                source_text = source_file.read().lower()
            if "random.choice" in source_text or "characters_in_radius" in source_text:
                return True
        except Exception:
            pass
    for node_id, node in nodes.items():
        if node.get("type") != "weather_lightning":
            continue
        has_target = any(wire.get("to") == node_id and wire.get("to_pin") == "target" for wire in links)
        has_position = any(wire.get("to") == node_id and wire.get("to_pin") == "position" for wire in links)
        if has_target and not has_position:
            return True
        script_name = str(modal.get("script_file") or "").lower()
        if "lightning" in script_name:
            target_wires = [wire for wire in links
                            if wire.get("to") == node_id and wire.get("to_pin") == "target"]
            if target_wires:
                source_node = nodes.get(target_wires[0].get("from"), {})
                if source_node.get("type") == "target_random_in_range":
                    return True
        # Converter v1 incorrectly used the entire file name/source to classify
        # every hook as lightning, including a timer-reset-only On Spawn hook.
        spawn_ids = {nid for nid, item in nodes.items() if item.get("type") == "event_on_spawn"}
        if any(wire.get("from") in spawn_ids and wire.get("to") == node_id for wire in links):
            script_file = modal.get("script_file")
            try:
                with open(os.path.join(SCRIPTS_DIR, script_file), "r") as imported_file:
                    imported_source = imported_file.read()
                imported_tree = ast.parse(imported_source)
                spawn_function = next((item for item in imported_tree.body
                                       if isinstance(item, ast.FunctionDef)
                                       and item.name == "on_spawn"), None)
                spawn_text = (ast.get_source_segment(imported_source, spawn_function) or "").lower() if spawn_function else ""
                if spawn_function and not any(marker in spawn_text for marker in
                                               ("play_animation", "damage", "chain_lightning", "spawn_explosion")):
                    return True
            except Exception:
                pass
    return False

def request_graph_generation(script_file, reason="missing"):
    modal["graph_generate_script"] = script_file
    modal["graph_generate_reason"] = reason
    modal["type"] = "graph_generate_confirm"
    modal["focus"] = None

def open_visual_scripter(return_to=None):
    global modal_scroll
    existing = modal.get("script_file")
    if return_to:
        modal["_ns_return_to"] = return_to
    # A source-only choice is not permanent; ask again on the next open so
    # the user can generate a graph later without restarting the app.
    if existing and modal.get("ns_source_only") and not os.path.isfile(visual_graph_path(existing)):
        request_graph_generation(existing)
        return
    if existing and modal.get("ns_loaded_script") == existing:
        if script_has_syntax_error(existing) and os.path.isfile(visual_graph_path(existing)):
            repair_loaded_graph_script(existing)
        if existing and not upgrade_prompt_dismissed(existing):
            if graph_is_placeholder_for_script(existing):
                request_graph_generation(existing, "placeholder")
                return
            if graph_needs_converter_upgrade():
                request_graph_generation(existing, "outdated")
                return
    # Load the graph sidecar belonging to this script. This is what keeps a
    # saved blueprint editable instead of reopening as one On Hit node.
    if modal.get("ns_loaded_script") != existing:
        modal["ns_preserved_params"] = peek_script_params(existing) if existing else {}
        loaded_graph = load_visual_graph_data(existing)
        if not loaded_graph and existing:
            request_graph_generation(existing)
            return
        if not loaded_graph:
            reset_visual_graph()
        elif existing and script_has_syntax_error(existing):
            repair_loaded_graph_script(existing)
        if existing and not upgrade_prompt_dismissed(existing):
            if existing and loaded_graph and graph_is_placeholder_for_script(existing):
                request_graph_generation(existing, "placeholder")
                return
            elif existing and graph_needs_converter_upgrade():
                request_graph_generation(existing, "outdated")
                return
        modal["ns_source_only"] = False
        modal["ns_loaded_script"] = existing
    elif "ns_nodes" not in modal:
        if existing and not load_visual_graph_data(existing):
            request_graph_generation(existing)
            return
        if existing and not upgrade_prompt_dismissed(existing):
            if existing and graph_is_placeholder_for_script(existing):
                request_graph_generation(existing, "placeholder")
                return
            if existing and graph_needs_converter_upgrade():
                request_graph_generation(existing, "outdated")
                return
        if not existing:
            reset_visual_graph()
        modal["ns_source_only"] = False
    modal["type"] = "visual_scripter"
    modal["focus"] = None
    # Never resume a stale debug simulation or camera target just because a
    # blueprint file was opened. Auto-pan starts only after an explicit Run/
    # Step action in this window.
    modal["ns_sim_active"] = False
    modal["ns_sim_paused"] = False
    modal["ns_camera_target_pos"] = None
    modal_scroll = 0.0
    
    # Load all premium overhual settings directly from the permanent config on startup!
    modal["ns_wire_glow_enabled"] = bool(_editor_config.get("ns_wire_glow_enabled", True))
    modal["ns_align_guides_enabled"] = bool(_editor_config.get("ns_align_guides_enabled", True))
    modal["ns_group_glow_enabled"] = bool(_editor_config.get("ns_group_glow_enabled", True))
    modal["ns_port_ripples_enabled"] = bool(_editor_config.get("ns_port_ripples_enabled", True))
    modal["ns_wire_particles_enabled"] = bool(_editor_config.get("ns_wire_particles_enabled", True))
    modal["ns_hotpath_enabled"] = bool(_editor_config.get("ns_hotpath_enabled", True))
    modal["ns_glass_headers_enabled"] = bool(_editor_config.get("ns_glass_headers_enabled", True))
    modal["ns_node_flash_style"] = str(_editor_config.get("ns_node_flash_style", "full"))
    modal["ns_node_shadows"] = bool(_editor_config.get("ns_node_shadows", True))
    modal["ns_tint_overlays"] = bool(_editor_config.get("ns_tint_overlays", True))
    modal["ns_compute_tints"] = bool(_editor_config.get("ns_compute_tints", True))
    modal["ns_node_borders"] = bool(_editor_config.get("ns_node_borders", True))
    modal["ns_node_theme"] = str(_editor_config.get("ns_node_theme", "current"))
    if modal["ns_node_theme"] not in NS_NODE_THEMES:
        modal["ns_node_theme"] = "current"
    modal["ns_sim_delay"] = float(_editor_config.get("ns_sim_delay", 0.55))
    modal.setdefault("ns_selected", None)
    modal.setdefault("ns_multi_selected", set())
    modal.setdefault("ns_selected_groups", set())
    modal.setdefault("ns_drag_node", None)
    modal.setdefault("ns_drag_group", None)
    modal.setdefault("ns_panning", False)
    modal.setdefault("ns_link_drag", None)
    modal.setdefault("ns_lesson_pin_drag", None)
    modal.setdefault("ns_box_select", None)
    modal.setdefault("ns_context_menu", None)
    modal.setdefault("ns_shortcuts_open", False)
    modal.setdefault("ns_shortcuts_scroll", 0.0)
    modal.setdefault("ns_shortcut_capture", None)
    modal.setdefault("ns_dropdown_menu", None)
    modal.setdefault("ns_change_node_menu", None)
    modal.setdefault("ns_wire_style_menu", False)
