def ns_compute_node_tints(nodes, links):
    """Return {node_id: tint_info} for visual overlay effects in the graph.

    When modal['ns_ignore_path_dim'] is True (Ignore Dim toggle), suppress
    dimmed/killed path overlays so you can still see the full graph while debugging.

    Tint rules (applied in priority order, highest wins):
      killed          - downstream of flow_disabled  → near-black
      dead_after_return - downstream of flow_return  → dark amber
      dimmed          - downstream of a Pass OR upstream of a Pass
                        (single Pass at start dims everything after it;
                         single Pass at end dims everything before it;
                         Pass at both ends = everything between is dimmed)
      disabled_self   - the flow_disabled node itself → dark red
      return_self     - the flow_return node itself   → dark magenta
      pass_self       - any connected flow_pass node  → blue badge only
      debug_only      - host with Debug-Only Clip     → amber TEST ONLY (skipped in live game)
      debug_only_clip - the Debug-Only Clip itself    → amber DBG-ONLY badge
    """
    if not nodes:
        return {}

    ignore_dim = bool(modal.get("ns_ignore_path_dim", False))
    # Fast path: fully skip path dimming when ignored
    if ignore_dim:
        # Still mark debug-only hosts lightly so TEST ONLY stays visible,
        # but no pass/disabled path washout.
        tints = {}
        for _oid, _on in nodes.items():
            if _on.get("type") == "debug_clamp_debug_only":
                tints.setdefault(_oid, {"mode": "debug_only_clip", "alpha": 40, "color": (255, 140, 20)})
                hid = _on.get("props", {}).get("clamped_to")
                if hid in nodes:
                    tints[hid] = {"mode": "debug_only", "alpha": 50, "color": (255, 170, 40)}
                else:
                    try:
                        hi = int(hid)
                        if hi in nodes:
                            tints[hi] = {"mode": "debug_only", "alpha": 50, "color": (255, 170, 40)}
                    except (TypeError, ValueError):
                        pass
            if bool(_on.get("props", {}).get("debug_only", False)):
                tints[_oid] = {"mode": "debug_only", "alpha": 50, "color": (255, 170, 40)}
        return tints

    # ── Build exec-only adjacency ─────────────────────────────────────────
    # An exec link is one whose from_pin name is "" (the main flow pin) OR
    # whose corresponding output PinSpec has type == EXEC.
    # Data links (number/string/object wires) are irrelevant for reachability.
    exec_children = {nid: [] for nid in nodes}
    exec_parents  = {nid: [] for nid in nodes}

    for lnk in links:
        f = lnk.get("from")
        t = lnk.get("to")
        if f not in nodes or t not in nodes:
            continue

        from_pin_name = lnk.get("from_pin", "")
        to_pin_name   = lnk.get("to_pin", "")

        # Quick check: both the source output and the destination input must
        # be exec pins.  A pin is exec if its name is "" (the main flow slot)
        # OR if its PinSpec.type == EXEC.
        from_cls = NODE_DEFS.get(nodes[f].get("type"), NodeBase)
        to_cls   = NODE_DEFS.get(nodes[t].get("type"), NodeBase)

        src_pin = next(
            (p for p in from_cls.outputs if p.name == from_pin_name),
            None
        )
        dst_pin = next(
            (p for p in to_cls.inputs if p.name == to_pin_name),
            None
        )

        # Accept the link as an exec link when:
        #   • the source pin is the unnamed ("") flow output, OR
        #   • the source PinSpec is actually typed EXEC, OR
        #   • the destination PinSpec is typed EXEC (named exec inputs like
        #     "open"/"close" on the Gate node)
        is_exec_link = (
            from_pin_name == ""
            or (src_pin is not None and src_pin.type == EXEC)
            or (dst_pin  is not None and dst_pin.type  == EXEC)
        )

        if is_exec_link:
            exec_children[f].append(t)
            exec_parents[t].append(f)

    # ── BFS helpers ───────────────────────────────────────────────────────
    def node_type(nid):
        return nodes[nid].get("type", "")

    def flood_down(start_ids):
        """All nodes reachable downstream (inclusive of start)."""
        seen  = set(start_ids)
        queue = list(start_ids)
        while queue:
            cur = queue.pop()
            for ch in exec_children.get(cur, []):
                if ch not in seen:
                    seen.add(ch)
                    queue.append(ch)
        return seen

    def flood_up(start_ids):
        """All nodes reachable upstream (inclusive of start)."""
        seen  = set(start_ids)
        queue = list(start_ids)
        while queue:
            cur = queue.pop()
            for p in exec_parents.get(cur, []):
                if p not in seen:
                    seen.add(p)
                    queue.append(p)
        return seen

    tints = {}
    SKIP_TYPES = {"flow_pass", "flow_return", "flow_disabled"}

    # ── 1. Disabled → downstream is "killed" (nearly black) ──────────────
    disabled_ids = {nid for nid in nodes if node_type(nid) == "flow_disabled"}
    if not ignore_dim:
        for nid in flood_down(disabled_ids) - disabled_ids:
            tints[nid] = {"mode": "killed", "alpha": 170, "color": (8, 8, 12)}

    # Muted nodes are hard execution blockers just like an unplugged path.
    muted_ids = {nid for nid, node in nodes.items() if _ns_node_muted(node)}
    if not ignore_dim:
        for nid in flood_down(muted_ids) - muted_ids:
            tints[nid] = {"mode": "killed", "alpha": 170, "color": (8, 8, 12)}
    for nid in muted_ids:
        tints[nid] = {"mode": "muted_self", "alpha": 95, "color": (215, 65, 75)}
    for nid, node in nodes.items():
        if _ns_node_bypassed(node):
            tints.setdefault(nid, {"mode": "bypass_self", "alpha": 60, "color": (75, 165, 255)})

    # ── 2. Return → downstream is "dead code" (dark amber) ───────────────
    return_ids = {nid for nid in nodes if node_type(nid) == "flow_return"}
    if not ignore_dim:
        for nid in flood_down(return_ids) - return_ids:
            if nid not in tints:
                tints[nid] = {"mode": "dead_after_return", "alpha": 110, "color": (255, 160, 40)}

    # ── 3. Pass → dim connected neighbours ───────────────────────────────
    # Rules (each Pass acts independently):
    #   • If a Pass has children  → everything downstream of it is dimmed
    #   • If a Pass has parents   → everything upstream of it is dimmed
    # This means:
    #   Pass at start of chain   → dims all nodes after it
    #   Pass at end of chain     → dims all nodes before it
    #   Pass on both ends        → dims everything in between (sandwich)
    pass_ids = {nid for nid in nodes if node_type(nid) == "flow_pass"}
    dimmed   = set()

    for pid in pass_ids:
        children = exec_children.get(pid, [])
        parents  = exec_parents.get(pid, [])

        if children:
            # Dim everything reachable downstream of this Pass
            down = flood_down(set(children))
            dimmed |= down

        if parents:
            # Dim everything reachable upstream of this Pass
            up = flood_up(set(parents))
            dimmed |= up

    # Remove the Pass nodes themselves and any higher-priority tints
    dimmed -= pass_ids
    if not ignore_dim:
        for nid in dimmed:
            if nid not in tints and node_type(nid) not in SKIP_TYPES:
                tints[nid] = {"mode": "dimmed", "alpha": 145, "color": (10, 10, 18)}

    # ── 4. Self-tints for the special nodes themselves ────────────────────
    for nid in disabled_ids:
        tints.setdefault(nid, {"mode": "disabled_self", "alpha": 80, "color": (180, 30, 30)})

    for nid in return_ids:
        tints.setdefault(nid, {"mode": "return_self", "alpha": 60, "color": (200, 80, 200)})

    for nid in pass_ids:
        has_any = bool(exec_children.get(nid)) or bool(exec_parents.get(nid))
        if has_any:
            tints.setdefault(nid, {"mode": "pass_self", "alpha": 55, "color": (80, 120, 200)})

    # ── 5. Debug-Only Clip hosts → amber TEST ONLY tint ────────────────
    debug_only_hosts = set()
    for _oid, _on in nodes.items():
        if _on.get("type") == "debug_clamp_debug_only":
            hid = _on.get("props", {}).get("clamped_to")
            # ids may be int or str depending on load path
            if hid in nodes:
                debug_only_hosts.add(hid)
            else:
                try:
                    hid_i = int(hid)
                    if hid_i in nodes:
                        debug_only_hosts.add(hid_i)
                except (TypeError, ValueError):
                    pass
        if bool(_on.get("props", {}).get("debug_only", False)):
            debug_only_hosts.add(_oid)
    for nid in debug_only_hosts:
        if nid not in tints or tints[nid].get("mode") in ("pass_self",):
            tints[nid] = {"mode": "debug_only", "alpha": 70, "color": (255, 170, 40)}
    for _oid, _on in nodes.items():
        if _on.get("type") == "debug_clamp_debug_only":
            tints.setdefault(_oid, {"mode": "debug_only_clip", "alpha": 50, "color": (255, 140, 20)})

    return tints

def ns_snapshot():
    if modal.get("ns_source_only"):
        modal["ns_source_only"] = False
        push_toast("Started a new graph version. Saving will replace the imported Python with generated graph code.", "info", 6.0)
    modal["ns_dirty"] = True
    modal.setdefault("ns_undo", [])
    snap = {
        "nodes": json.loads(json.dumps(modal.get("ns_nodes", {}))),
        "links": json.loads(json.dumps(modal.get("ns_links", []))),
        "smart_groups": json.loads(json.dumps(modal.get("ns_smart_groups", []))),
        "canvas_texts": json.loads(json.dumps(modal.get("ns_canvas_texts", []))),
        "debug_paths": json.loads(json.dumps(modal.get("ns_debug_paths", []))),
        "bookmarks": json.loads(json.dumps(modal.get("ns_bookmarks", []))),
        "solo_ids": list(modal.get("ns_solo_ids", set()) or []),
        "hide_mode": modal.get("ns_hide_mode", "transparent"),
    }
    modal["ns_undo"].append(snap)
    if len(modal["ns_undo"]) > 60:
        modal["ns_undo"].pop(0)
    modal["ns_redo"] = []

def _ns_current_snap():
    return {
        "nodes": json.loads(json.dumps(modal.get("ns_nodes", {}))),
        "links": json.loads(json.dumps(modal.get("ns_links", []))),
        "smart_groups": json.loads(json.dumps(modal.get("ns_smart_groups", []))),
        "canvas_texts": json.loads(json.dumps(modal.get("ns_canvas_texts", []))),
        "debug_paths": json.loads(json.dumps(modal.get("ns_debug_paths", []))),
        "bookmarks": json.loads(json.dumps(modal.get("ns_bookmarks", []))),
        "solo_ids": list(modal.get("ns_solo_ids", set()) or []),
        "hide_mode": modal.get("ns_hide_mode", "transparent"),
    }

def _ns_restore(snap):
    # Backward compatible: old undo entries were (nodes, links).
    if isinstance(snap, dict):
        nodes = snap.get("nodes", {})
        links = snap.get("links", [])
        modal["ns_smart_groups"] = snap.get("smart_groups", modal.get("ns_smart_groups", []))
        modal["ns_canvas_texts"] = snap.get("canvas_texts", modal.get("ns_canvas_texts", []))
        modal["ns_debug_paths"] = snap.get("debug_paths", modal.get("ns_debug_paths", []))
        modal["ns_annotation_selected"] = None
        modal["ns_debug_path_draft"] = None
        modal["ns_bookmarks"] = snap.get("bookmarks", modal.get("ns_bookmarks", []))
        modal["ns_solo_ids"] = set(snap.get("solo_ids", []))
        modal["ns_hide_mode"] = snap.get("hide_mode", modal.get("ns_hide_mode", "transparent"))
    else:
        nodes, links = snap
    modal["ns_nodes"] = {int(k): v for k, v in nodes.items()}
    modal["ns_links"] = links
    modal["ns_selected"] = None
    modal["ns_multi_selected"] = set()
    modal["ns_selected_groups"] = set()

def ns_undo():
    if modal.get("ns_undo"):
        modal.setdefault("ns_redo", []).append(_ns_current_snap())
        _ns_restore(modal["ns_undo"].pop())

def ns_redo():
    if modal.get("ns_redo"):
        modal.setdefault("ns_undo", []).append(_ns_current_snap())
        _ns_restore(modal["ns_redo"].pop())

def ns_selection_ids():
    ids = set(modal.get("ns_multi_selected", set()))
    if modal.get("ns_selected"):
        ids.add(modal["ns_selected"])
    return {i for i in ids if i in modal.get("ns_nodes", {})}

# ============================================================
# MIXED GROUPS  —  scene (external) nodes AND blueprint nodes
# ============================================================
# A scene group used to hold only external nodes. Blueprint nodes live in
# a completely separate list (modal["ns_nodes"]) belonging to whichever
# script is open, so they need their own member list plus the script name
# to resolve against. A group entry therefore carries:
#
#   node_ids       -> external/scene node ids           (as before)
#   bp_members     -> [{"script": "foo.py", "id": 12}]  (blueprint nodes)
#
# Everything else (nesting, visibility, save-as-asset) works the same for
# both kinds.

def scene_group_bp_members(group):
    out = []
    for m in group.get("bp_members", []) or []:
        if isinstance(m, dict) and m.get("id") is not None:
            out.append({"script": str(m.get("script", "") or ""), "id": int(m["id"])})
    return out

def _bp_current_script():
    """Which blueprint the editor currently has open ('' when none)."""
    return str(modal.get("ns_loaded_script") or modal.get("script_file") or "")

def scene_group_of_bp_node(node_id, script=None):
    script = _bp_current_script() if script is None else str(script)
    for g in reversed(scene_groups):
        for m in scene_group_bp_members(g):
            if m["id"] == int(node_id) and m["script"] == script:
                return g
    return None

def scene_group_add_bp_nodes(group, node_ids, script=None):
    """Attach blueprint nodes to a group (one owner, like scene nodes)."""
    script = _bp_current_script() if script is None else str(script)
    members = group.setdefault("bp_members", [])
    existing = {(m.get("script"), m.get("id")) for m in scene_group_bp_members(group)}
    added = 0
    for nid in node_ids:
        try:
            nid = int(nid)
        except (TypeError, ValueError):
            continue
        for other in scene_groups:
            if other is group:
                continue
            keep = [m for m in scene_group_bp_members(other)
                    if not (m["id"] == nid and m["script"] == script)]
            if len(keep) != len(scene_group_bp_members(other)):
                other["bp_members"] = keep
        if (script, nid) not in existing:
            members.append({"script": script, "id": nid})
            existing.add((script, nid))
            added += 1
    return added

def scene_group_remove_bp_nodes(group, node_ids, script=None):
    script = _bp_current_script() if script is None else str(script)
    want = {int(n) for n in node_ids}
    before = len(scene_group_bp_members(group))
    group["bp_members"] = [m for m in scene_group_bp_members(group)
                           if not (m["id"] in want and m["script"] == script)]
    return before - len(group["bp_members"])

def scene_group_all_bp_members(group, seen=None):
    """Blueprint members of this group and every descendant."""
    seen = set(seen or ())
    gid = group.get("id")
    if gid in seen:
        return []
    seen.add(gid)
    out = list(scene_group_bp_members(group))
    for child in scene_group_children(group):
        out.extend(scene_group_all_bp_members(child, seen))
    return out

def scene_group_bp_live_nodes(group, script=None):
    """Resolve this group's blueprint members against the OPEN graph.
    Returns [] when a different script is loaded."""
    script = _bp_current_script() if script is None else str(script)
    nodes = modal.get("ns_nodes", {}) or {}
    out = []
    for m in scene_group_all_bp_members(group):
        if m["script"] != script:
            continue
        n = nodes.get(m["id"])
        if n is not None:
            out.append(n)
    return out

def scene_group_member_count(group):
    """(scene nodes, blueprint nodes) across the whole subtree."""
    return (len(scene_group_all_node_ids(group)),
            len(scene_group_all_bp_members(group)))

def move_scene_group_bp(group, dx, dy, script=None, moved=None, moved_groups=None):
    """Shift this group's blueprint nodes on the canvas, in world units."""
    script = _bp_current_script() if script is None else str(script)
    moved = moved if moved is not None else set()
    moved_groups = moved_groups if moved_groups is not None else set()
    gid = group.get("id")
    if gid in moved_groups or group.get("locked"):
        return
    moved_groups.add(gid)
    nodes = modal.get("ns_nodes", {}) or {}
    for m in scene_group_bp_members(group):
        if m["script"] != script or m["id"] in moved:
            continue
        n = nodes.get(m["id"])
        if n is None:
            continue
        moved.add(m["id"])
        n["x"] = float(n.get("x", 0)) + dx
        n["y"] = float(n.get("y", 0)) + dy
    for child in scene_group_children(group):
        move_scene_group_bp(child, dx, dy, script, moved, moved_groups)
    modal["ns_dirty"] = True

def group_selected_bp_nodes(name=None):
    """Make a mixed group from the blueprint editor's current selection."""
    ids = list(ns_selection_ids())
    if not ids:
        push_toast("Select blueprint node(s) first.", "warning", 2.2)
        return None
    group = make_scene_group(name=name or f"Blueprint Group {len(scene_groups) + 1}")
    scene_group_add_bp_nodes(group, ids)
    push_toast(f"Grouped {len(ids)} blueprint node(s) as '{group['name']}'.",
               "success", 2.2)
    return group

# ---- keep serialisation aware of the new member list ----

_serialize_scene_groups_v1 = serialize_scene_groups
_restore_scene_groups_v1 = restore_scene_groups

def serialize_scene_groups():                       # noqa: F811
    out = _serialize_scene_groups_v1()
    by_id = {g.get("id"): g for g in scene_groups}
    for entry in out:
        g = by_id.get(entry.get("id"))
        if g is not None:
            entry["bp_members"] = scene_group_bp_members(g)
    return out

def restore_scene_groups(data):                     # noqa: F811
    _restore_scene_groups_v1(data)
    by_id = {g.get("id"): g for g in scene_groups}
    for raw in data or []:
        if not isinstance(raw, dict):
            continue
        try:
            g = by_id.get(int(raw.get("id")))
        except (TypeError, ValueError):
            continue
        if g is not None:
            g["bp_members"] = [
                {"script": str(m.get("script", "")), "id": int(m.get("id"))}
                for m in raw.get("bp_members", []) or []
                if isinstance(m, dict) and str(m.get("id", "")).lstrip("-").isdigit()
            ]

# save_scene_group_as_asset is fully defined at line ~12674 and handles
# external nodes, texts, images, and nested groups in one pass.
# The old v2 blueprint-payload wrapper is intentionally removed to avoid the
# double-call chain that caused TypeError and duplicate-node issues.

# import_scene_group_asset is fully defined at line ~12799 and handles
# external nodes, texts, images, and nested groups in one pass.
# The old v2 blueprint-payload wrapper is intentionally removed.

# ============================================================
# SCENE TEXT / IMAGE GROUPING
# ============================================================
# scene_texts and scene_images are plain lists with no identity of their
# own -- everything referenced them by list index, which breaks the moment
# one is deleted or reordered. Groups need a stable handle, so every text
# and image now gets a persistent "sid" the first time it is seen, and a
# group can hold three member kinds:
#
#   node_ids       -> external nodes            (rects, bars, counters...)
#   text_ids       -> scene text labels
#   image_ids      -> scene images
#
# Existing projects gain ids transparently on load.

_scene_item_next_id = [1]

def _si_new_id():
    sid = _scene_item_next_id[0]
    _scene_item_next_id[0] += 1
    return sid

def ensure_scene_item_ids():
    """Give every text/image a stable id. Cheap, idempotent, safe to call
    every frame."""
    highest = _scene_item_next_id[0] - 1
    for coll in (scene_texts, scene_images):
        for item in coll:
            sid = item.get("sid")
            if not isinstance(sid, int) or sid <= 0:
                item["sid"] = _si_new_id()
            else:
                highest = max(highest, sid)
    if highest >= _scene_item_next_id[0]:
        _scene_item_next_id[0] = highest + 1

# ══════════════════════════════════════════════════════════════════════════
# SCENE UNDO / REDO
# ══════════════════════════════════════════════════════════════════════════
# Until now undo existed only inside the blueprint editor (ns_undo), the
# easing-curve editor and text fields. The *scene* had none at all --
# remove_external_node() was a one-line list filter, so deleting a node was
# permanent with no confirmation and no recovery.
#
# This is a snapshot stack over the five lists that make up a scene:
#     external_nodes, scene_texts, scene_images, scene_groups
#     + the id counters that keep references between them valid
#
# Snapshots are structural copies via _snapshot_value, which deliberately
# shares pygame.Surface objects by reference instead of cloning pixel data --
# so a scene full of images costs kilobytes per undo step, not megabytes.
#
# Usage: call scene_undo_push("Delete node") BEFORE mutating.

SCENE_UNDO_LIMIT = 80

scene_undo_stack = []   # list of (label, snapshot)
scene_redo_stack = []
_scene_undo_suspended = [False]

def _scene_undo_snapshot(include_clear_state=False):
    """Freeze authored Scene Nodes; optionally include every clearable category."""
    emit_snap=[]
    for e in particle_emitters:
        c={k:v for k,v in e.items() if k!="_particles"};emit_snap.append(_snapshot_value(c))
    snap={"external_nodes":_snapshot_value(external_nodes),"scene_texts":_snapshot_value(scene_texts),"scene_images":_snapshot_value(scene_images),"scene_groups":_snapshot_value(scene_groups),"emitters":emit_snap,"ext_next_id":_ext_node_next_id[0],"item_next_id":_scene_item_next_id[0],"group_next_id":_scene_group_next_id[0],"pe_next_id":_pe_next_id[0]}
    if include_clear_state:
        memo={}
        try:target_index=characters.index(camera.get("target")) if camera.get("target") in characters else None
        except Exception:target_index=None
        snap["clear_state"]={
            "characters":_snapshot_value(characters,memo),"weapon_projectiles":_snapshot_value(_WEAPON_PROJECTILES,memo),"particles":_snapshot_value(particles,memo),"particle_emitters":_snapshot_value(particle_emitters,memo),
            "world_effects":_snapshot_value(world_effects,memo),"area_zones":_snapshot_value(area_zones,memo),"popups":_snapshot_value(popups,memo),"pheromone_markers":_snapshot_value(pheromone_markers,memo),
            "scene_blocks":_snapshot_value(scene_blocks,memo),"scene_debug_buttons":_snapshot_value(scene_debug_buttons,memo),"scene_debug_window_positions":_snapshot_value(scene_debug_window_positions,memo),"camera_target_index":target_index,
        }
    return snap

def _scene_undo_restore(snap):
    """Put a snapshot back. Lists are mutated in place (clear + extend) so
    every existing reference to external_nodes / scene_texts / ... keeps
    pointing at the right object -- rebinding them would silently orphan
    the many closures and helpers that captured the original lists."""
    external_nodes[:] = snap["external_nodes"]
    scene_texts[:]    = snap["scene_texts"]
    scene_images[:]   = snap["scene_images"]
    scene_groups[:]   = snap["scene_groups"]
    _live_parts = {e.get("id"): e.get("_particles", []) for e in particle_emitters}
    particle_emitters[:] = snap.get("emitters", [])
    for _e in particle_emitters:
        # Keep whatever particles were already in flight for surviving
        # emitters, so an undo doesn't visibly blink the effect off.
        _e["_particles"] = _live_parts.get(_e.get("id"), [])
    _pe_next_id[0] = snap.get("pe_next_id", _pe_next_id[0])
    _ext_node_next_id[0]    = snap["ext_next_id"]
    _scene_item_next_id[0]  = snap["item_next_id"]
    _scene_group_next_id[0] = snap["group_next_id"]
    clear_state=snap.get("clear_state")
    if isinstance(clear_state,dict):
        characters[:]=clear_state.get("characters",[]);_WEAPON_PROJECTILES[:]=clear_state.get("weapon_projectiles",[]);particles[:]=clear_state.get("particles",[]);particle_emitters[:]=clear_state.get("particle_emitters",particle_emitters)
        world_effects[:]=clear_state.get("world_effects",[]);area_zones[:]=clear_state.get("area_zones",[]);popups[:]=clear_state.get("popups",[]);pheromone_markers[:]=clear_state.get("pheromone_markers",[]);scene_blocks[:]=clear_state.get("scene_blocks",[]);scene_debug_buttons[:]=clear_state.get("scene_debug_buttons",[])
        scene_debug_window_positions.clear();scene_debug_window_positions.update(clear_state.get("scene_debug_window_positions",{}))
        target_index=clear_state.get("camera_target_index");camera["target"]=characters[target_index] if isinstance(target_index,int) and 0<=target_index<len(characters) else None
    # Cached screen rects belong to the frame they were drawn in; drop them
    # so nothing hit-tests or outlines against a restored-but-not-yet-drawn
    # position for one frame.
    for _coll in (external_nodes, scene_texts, scene_images):
        for _it in _coll:
            if isinstance(_it, dict):
                _it["_rect"] = None
    try:
        en_tag_index_rebuild()
    except Exception:
        pass
    # A restored scene may not contain whatever was selected.
    _sel = modal.get("_en_selected_id")
    if _sel is not None and get_external_node(_sel) is None:
        modal["_en_selected_id"] = None
        modal["_sn_sel"] = None
    # Drop multi-selection keys pointing at items the restored scene no
    # longer contains, so bulk actions can't operate on ghosts.
    _msel = modal.get("_scene_multi_sel")
    if _msel:
        modal["_scene_multi_sel"] = {
            _k for _k in _msel if scene_sel_resolve(_k) is not None
        }
    modal["_dragging_ext_node"] = None
    modal["_dragging_scene_group"] = None
    scene_proxy_invalidate();_SPARSE_PRESENT_STATE["full_next"]=True

def scene_undo_push(label="Edit",include_clear_state=False):
    """Record the scene as it is right now, before a change is applied."""
    if _scene_undo_suspended[0]:
        return False
    try:
        scene_undo_stack.append((str(label),_scene_undo_snapshot(include_clear_state=include_clear_state)))
    except Exception:
        return False
    if len(scene_undo_stack) > SCENE_UNDO_LIMIT:
        scene_undo_stack.pop(0)
    # Any new edit invalidates the redo branch.
    scene_redo_stack.clear();return True

def scene_undo_push_once(key, label="Edit"):
    """Push at most one snapshot per continuous interaction.

    Dragging a node fires MOUSEMOTION dozens of times; without this every
    pixel of travel would become its own undo step. The first call for a
    given key snapshots, the rest are ignored until scene_undo_end_gesture()
    clears it on mouse-up.
    """
    if modal.get("_scene_undo_gesture") == key:
        return
    modal["_scene_undo_gesture"] = key
    scene_undo_push(label)

def scene_undo_end_gesture():
    modal["_scene_undo_gesture"] = None

def scene_undo():
    if not scene_undo_stack:
        push_toast("Nothing to undo", "info", 1.6)
        return False
    label, snap = scene_undo_stack.pop()
    scene_redo_stack.append((label,_scene_undo_snapshot(include_clear_state="clear_state" in snap)))
    if len(scene_redo_stack) > SCENE_UNDO_LIMIT:
        scene_redo_stack.pop(0)
    _scene_undo_restore(snap)
    push_toast(f"Undo · {label}", "info", 1.8)
    return True

def scene_redo():
    if not scene_redo_stack:
        push_toast("Nothing to redo", "info", 1.6)
        return False
    label, snap = scene_redo_stack.pop()
    scene_undo_stack.append((label,_scene_undo_snapshot(include_clear_state="clear_state" in snap)))
    if len(scene_undo_stack) > SCENE_UNDO_LIMIT:
        scene_undo_stack.pop(0)
    _scene_undo_restore(snap)
    push_toast(f"Redo · {label}", "info", 1.8)
    return True

def scene_undo_clear():
    """Wipe history -- used when loading/resetting a project so you can't
    undo your way back into a different project's scene."""
    scene_undo_stack.clear()
    scene_redo_stack.clear()
    modal["_scene_undo_gesture"] = None
    # A selection from the previous scene means nothing in the new one.
    modal["_scene_multi_sel"] = set()
    modal["_scene_marquee"] = None

class _SceneUndoSuspend:
    """Context manager: apply a batch of changes as ONE undo step.

        with scene_undo_batch("Load preset"):
            ...many mutations...
    """
    def __init__(self, label):
        self.label = label
    def __enter__(self):
        scene_undo_push(self.label)
        _scene_undo_suspended[0] = True
        return self
    def __exit__(self, *exc):
        _scene_undo_suspended[0] = False
        return False

def scene_undo_batch(label="Edit"):
    return _SceneUndoSuspend(label)

def get_scene_text(sid):
    return next((t for t in scene_texts if t.get("sid") == sid), None)

def get_scene_image(sid):
    return next((i for i in scene_images if i.get("sid") == sid), None)

def scene_item_label(item, kind):
    """Short human label for a text/image row."""
    if kind == "text":
        txt = str(item.get("text", "")).strip() or "(empty)"
        return txt[:26]
    src = item.get("source_path") or item.get("image_path") or ""
    return (os.path.basename(str(src)) or "image")[:26]

# ---------- membership ----------

def scene_group_text_ids(group):
    return [int(x) for x in group.get("text_ids", []) or []]

def scene_group_image_ids(group):
    return [int(x) for x in group.get("image_ids", []) or []]

def scene_group_of_text(sid):
    for g in reversed(scene_groups):
        if int(sid) in scene_group_text_ids(g):
            return g
    return None

def scene_group_of_image(sid):
    for g in reversed(scene_groups):
        if int(sid) in scene_group_image_ids(g):
            return g
    return None

def _sg_add_generic(group, key, sids, resolver):
    added = 0
    members = group.setdefault(key, [])
    for sid in sids:
        try:
            sid = int(sid)
        except (TypeError, ValueError):
            continue
        if resolver(sid) is None:
            continue
        for other in scene_groups:
            if other is not group and sid in (other.get(key) or []):
                other[key].remove(sid)
        if sid not in members:
            members.append(sid)
            added += 1
    return added

def scene_group_add_texts(group, sids):
    return _sg_add_generic(group, "text_ids", sids, get_scene_text)

def scene_group_add_images(group, sids):
    return _sg_add_generic(group, "image_ids", sids, get_scene_image)

def scene_group_remove_texts(group, sids):
    want = {int(s) for s in sids}
    before = len(scene_group_text_ids(group))
    group["text_ids"] = [s for s in scene_group_text_ids(group) if s not in want]
    return before - len(group["text_ids"])

def scene_group_remove_images(group, sids):
    want = {int(s) for s in sids}
    before = len(scene_group_image_ids(group))
    group["image_ids"] = [s for s in scene_group_image_ids(group) if s not in want]
    return before - len(group["image_ids"])

def scene_group_all_text_ids(group, seen=None):
    seen = set(seen or ())
    gid = group.get("id")
    if gid in seen:
        return set()
    seen.add(gid)
    ids = set(scene_group_text_ids(group))
    for child in scene_group_children(group):
        ids |= scene_group_all_text_ids(child, seen)
    return ids

def scene_group_all_image_ids(group, seen=None):
    seen = set(seen or ())
    gid = group.get("id")
    if gid in seen:
        return set()
    seen.add(gid)
    ids = set(scene_group_image_ids(group))
    for child in scene_group_children(group):
        ids |= scene_group_all_image_ids(child, seen)
    return ids

def scene_group_full_count(group):
    """(external nodes, texts, images) across the whole subtree."""
    return (len(scene_group_all_node_ids(group)),
            len(scene_group_all_text_ids(group)),
            len(scene_group_all_image_ids(group)))

# ---------- movement ----------

def _si_move_item(item, dx, dy):
    """Shift one text/image, honouring its own world/screen space mode."""
    if item is None or item.get("locked"):
        return
    world = (item.get("world_space") or item.get("_world_space")) and \
        not item.get("camera_locked", False)
    if world:
        zoom = max(0.001, float(camera.get("zoom", 1.0)))
        item["wx"] = float(item.get("wx", 0.0)) + dx / zoom
        item["wy"] = float(item.get("wy", 0.0)) + dy / zoom
    else:
        frame = ((virtual_camera.get("_preview_frame") or _virtual_camera_display_frame()) if virtual_camera.get("enabled") else None)
        fw = frame.width if frame else WIDTH
        fh = frame.height if frame else HEIGHT
        item["fx"] = max(0.0, min(1.0, float(item.get("fx", 0.5)) + dx / max(1, fw)))
        item["fy"] = max(0.0, min(1.0, float(item.get("fy", 0.5)) + dy / max(1, fh)))

# ══════════════════════════════════════════════════════════════════════════
# SCENE MULTI-SELECT
# ══════════════════════════════════════════════════════════════════════════
# Blueprint nodes already had ns_multi_selected + box select. Scene nodes were
# strictly one-at-a-time (_sn_sel / _en_selected_id), which made every bulk
# edit a repetitive one-node-at-a-time chore and left align/distribute
# impossible to express at all.
#
# A selection is a set of (kind, id) keys:
#     ("en",    node_id)   external node
#     ("text",  sid)       scene text
#     ("image", sid)       scene image
# The same key format the Scene Nodes hierarchy already used for _sn_sel, so
# the list and the arena stay in sync for free.

def scene_sel_get() -> set:
    return modal.setdefault("_scene_multi_sel", set())

def scene_sel_clear():
    modal["_scene_multi_sel"] = set()
    modal["_sn_sel"] = None
    modal["_en_selected_id"] = None

def scene_sel_key_for(item):
    """(kind, id) for any scene item, or None if it has no stable id yet."""
    if not isinstance(item, dict):
        return None
    if "kind" in item and "id" in item:
        return ("en", item["id"])
    sid = item.get("sid")
    if sid is None:
        return None
    if "text" in item:
        return ("text", sid)
    if "image" in item or "image_path" in item:
        return ("image", sid)
    return None

def scene_sel_resolve(key):
    """(kind, id) -> the live dict, or None if it no longer exists."""
    if not key:
        return None
    kind, ident = key
    if kind == "en":
        return get_external_node(ident)
    if kind == "text":
        return get_scene_text(ident)
    if kind == "image":
        return get_scene_image(ident)
    return None

def scene_sel_items():
    """Live dicts for everything selected, skipping stale keys."""
    out = []
    for k in list(scene_sel_get()):
        it = scene_sel_resolve(k)
        if it is None:
            scene_sel_get().discard(k)   # prune deleted items
        else:
            out.append(it)
    return out

def scene_sel_contains(item) -> bool:
    k = scene_sel_key_for(item)
    return bool(k) and k in scene_sel_get()

def scene_sel_set_single(item):
    """Replace the selection with exactly one item (plain click)."""
    k = scene_sel_key_for(item)
    modal["_scene_multi_sel"] = {k} if k else set()
    modal["_sn_sel"] = k
    modal["_en_selected_id"] = k[1] if (k and k[0] == "en") else None
    modal["_scene_canvas_anchor"] = k

def scene_sel_toggle(item):
    """Shift/Ctrl+click: add or remove without disturbing the rest."""
    k = scene_sel_key_for(item)
    if not k:
        return
    sel = scene_sel_get()
    if k in sel:
        sel.discard(k)
        if modal.get("_sn_sel") == k:
            modal["_sn_sel"] = next(iter(sel), None)
    else:
        sel.add(k);modal["_sn_sel"] = k;modal["_scene_canvas_anchor"] = k
    # The single-selection inspector follows the most recent external node so
    # the property panel still has something coherent to show.
    _last = modal.get("_sn_sel")
    modal["_en_selected_id"] = _last[1] if (_last and _last[0] == "en") else None

def scene_sel_add(item, make_primary=False):
    k = scene_sel_key_for(item)
    if k:
        scene_sel_get().add(k)
        if make_primary:
            modal["_sn_sel"] = k
            modal["_en_selected_id"] = k[1] if k[0] == "en" else None


def scene_sel_make_primary(item):
    """Keep a selected item as the inspector/drag anchor without clearing peers."""
    k=scene_sel_key_for(item)
    if not k:return
    scene_sel_get().add(k);modal["_sn_sel"]=k
    modal["_en_selected_id"]=k[1] if k[0]=="en" else None


def scene_item_effectively_locked(item):
    """Direct locks and explicit Scene Group locks; overlapping locked nodes never leak through."""
    if not isinstance(item,dict) or item.get("locked",False):return True
    try:
        sk=scene_sel_key_for(item);group=scene_group_of_node(sk[1]) if sk and sk[0]=="en" else scene_group_of_text(sk[1]) if sk and sk[0]=="text" else scene_group_of_image(sk[1]) if sk else None
        while group is not None:
            if group.get("locked",False):return True
            group=scene_group_parent(group.get("id"))
    except Exception:pass
    return False

def scene_selection_order():
    items=[it for it in scene_hierarchy_all_items() if not _scene_item_hidden(it)]
    return sorted(items,key=lambda it:(0 if scene_hierarchy_effective_plane(it)=="front" else 1,-scene_hierarchy_effective_z(it),str(scene_hierarchy_key_for(it))))


def scene_sel_range_to(item,additive=False):
    ordered=scene_selection_order();anchor_key=modal.get("_scene_canvas_anchor");target_key=scene_sel_key_for(item);keys=[scene_sel_key_for(it) for it in ordered]
    if anchor_key not in keys:anchor_key=target_key
    if not additive:scene_sel_clear()
    try:a,b=keys.index(anchor_key),keys.index(target_key)
    except ValueError:a=b=0
    for candidate in ordered[min(a,b):max(a,b)+1]:
        if not scene_item_effectively_locked(candidate):scene_sel_add(candidate)
    scene_sel_make_primary(item);modal["_scene_canvas_anchor"]=anchor_key;return len(scene_sel_get())


def scene_selected_hit(pos):
    """Hit any visual selection representation before locked overlays above it."""
    candidates=list(scene_sel_items());primary=modal.get("_sn_sel")
    for key in (primary,("en",modal.get("_en_selected_id")) if modal.get("_en_selected_id") is not None else None):
        item=scene_sel_resolve(key) if key else None
        if item is not None and item not in candidates:candidates.append(item)
    hierarchy_item=scene_hierarchy_item(modal.get("_eh_selected"))
    if hierarchy_item is not None and hierarchy_item not in candidates:candidates.append(hierarchy_item)
    selected=[]
    for item in candidates:
        rect=item.get("_rect")
        if isinstance(rect,pygame.Rect) and rect.inflate(8,8).collidepoint(pos) and not scene_item_effectively_locked(item) and not _scene_item_hidden(item):selected.append(item)
    if not selected:return None
    hit=next((it for it in selected if scene_sel_key_for(it)==primary),None)
    return hit or sorted(selected,key=lambda it:-scene_hierarchy_effective_z(it))[0]


def scene_hit_stack(pos):
    hits=[it for it in scene_hierarchy_all_items() if isinstance(it.get("_rect"),pygame.Rect) and it["_rect"].collidepoint(pos) and not _scene_item_hidden(it)]
    return sorted(hits,key=lambda it:(0 if scene_hierarchy_effective_plane(it)=="front" else 1,-scene_hierarchy_effective_z(it),str(scene_hierarchy_key_for(it))))


def scene_top_unlocked_hit(pos):return next((it for it in scene_hit_stack(pos) if not scene_item_effectively_locked(it)),None)


def scene_top_locked_hit(pos):return next((it for it in scene_hit_stack(pos) if scene_item_effectively_locked(it)),None)


def scene_ctrl_drag_begin(item,pos):
    """Arm Ctrl+drag while preserving Ctrl+click toggle semantics."""
    key=scene_sel_key_for(item)
    if not key:return False
    was_selected=key in scene_sel_get()
    if was_selected:scene_sel_make_primary(item)
    else:scene_sel_toggle(item)
    modal["_scene_ctrl_drag"]={"key":key,"start":tuple(pos),"was_selected":was_selected,"moved":False}
    return True


def scene_ctrl_drag_motion_ready(item,pos):
    pending=modal.get("_scene_ctrl_drag")
    if not pending or pending.get("key")!=scene_sel_key_for(item):return True
    if not pending.get("moved"):
        if pygame.Vector2(pos).distance_to(pending.get("start",pos))<=3:return False
        pending["moved"]=True
    return True


def scene_ctrl_drag_finish():
    """A stationary Ctrl+click toggles off; a Ctrl+drag keeps and moves it."""
    pending=modal.pop("_scene_ctrl_drag",None)
    if not pending or pending.get("moved") or not pending.get("was_selected"):return
    item=scene_sel_resolve(pending.get("key"))
    if item is not None:scene_sel_toggle(item)


def scene_ctrl_hover_move_event(event):
    """Move selected bars by hovering one, holding Ctrl, then moving the cursor.

    This deliberately arms only when Ctrl is pressed while the cursor is already
    over a selected Bar/Custom Bar. Ctrl pressed over an unselected node remains
    available for normal additive Ctrl+click selection, so the two workflows do
    not fight each other.
    """
    ctrl_keys={pygame.K_LCTRL,pygame.K_RCTRL}
    for _meta_name in ("K_LGUI","K_RGUI","K_LMETA","K_RMETA"):
        _meta_key=getattr(pygame,_meta_name,None)
        if _meta_key is not None:ctrl_keys.add(_meta_key)
    if event.type==pygame.KEYDOWN and event.key in ctrl_keys:
        if modal.get("type") is not None or _ns_terminal.get("open") or _UI_MODIFY_MODE:return False
        pos=pygame.mouse.get_pos()
        if (ui_visible and not globals().get("_SIDEBAR_HIDDEN", False) and pos[0]<SIDEBAR_W) or point_in_tool_dock(pos):return False
        anchor=next((it for it in reversed(scene_sel_items()) if it.get("kind") in ("progress_bar","custom_progress_bar") and isinstance(it.get("_rect"),pygame.Rect) and it["_rect"].collidepoint(pos) and not it.get("locked")),None)
        if anchor is not None:modal["_scene_ctrl_hover_move"]={"anchor":scene_sel_key_for(anchor),"last":tuple(pos),"moved":False}
        return False
    if event.type==pygame.KEYUP and event.key in ctrl_keys:
        if modal.pop("_scene_ctrl_hover_move",None):scene_undo_end_gesture()
        return False
    state=modal.get("_scene_ctrl_hover_move")
    if event.type==pygame.MOUSEMOTION and state:
        mods=pygame.key.get_mods()
        if modal.get("type") is not None:modal.pop("_scene_ctrl_hover_move",None);return False
        if not (mods&(pygame.KMOD_CTRL|pygame.KMOD_META)) or pygame.mouse.get_pressed()[0]:return False
        if (ui_visible and not globals().get("_SIDEBAR_HIDDEN", False) and event.pos[0]<SIDEBAR_W) or point_in_tool_dock(event.pos):state["last"]=tuple(event.pos);return True
        if state.get("anchor") not in scene_sel_get():modal.pop("_scene_ctrl_hover_move",None);return False
        last=state.get("last",event.pos);dx=event.pos[0]-last[0];dy=event.pos[1]-last[1];state["last"]=tuple(event.pos)
        if dx or dy:
            if not state.get("moved"):
                scene_undo_push_once(("ctrl_hover_move",tuple(sorted(scene_sel_get(),key=str))),"Move selected scene items");state["moved"]=True
            scene_sel_move(dx,dy);scene_proxy_invalidate();_SPARSE_PRESENT_STATE["full_next"]=True
        return True
    return False

def scene_sel_all():
    """Select every visible, unlocked scene item."""
    ensure_scene_item_ids()
    sel = set()
    for n in external_nodes:
        if n.get("visible", True) and not n.get("locked"):
            sel.add(("en", n["id"]))
    for t in scene_texts:
        if not _scene_item_hidden(t) and not t.get("locked") and t.get("sid"):
            sel.add(("text", t["sid"]))
    for im in scene_images:
        if not _scene_item_hidden(im) and not im.get("locked") and im.get("sid"):
            sel.add(("image", im["sid"]))
    modal["_scene_multi_sel"] = sel
    return len(sel)

def scene_hierarchy_key_for(item):
    if not isinstance(item,dict):return None
    if "kind" in item and "id" in item:return f"en:{item.get('id')}"
    if "text" in item:return f"text:{item.get('sid')}"
    if "image" in item or "image_path" in item:return f"image:{item.get('sid')}"
    return None


def scene_hierarchy_all_items():
    ensure_scene_item_ids();return list(external_nodes)+list(scene_texts)+list(scene_images)


def scene_hierarchy_item(key):
    key=str(key or "")
    if not key or ":" not in key:return None
    kind,raw=key.split(":",1)
    try:ident=int(raw)
    except (TypeError,ValueError):return None
    if kind=="en":return get_external_node(ident)
    if kind=="text":return next((item for item in scene_texts if int(item.get("sid",-1))==ident),None)
    if kind=="image":return next((item for item in scene_images if int(item.get("sid",-1))==ident),None)
    return None


def scene_hierarchy_local_z(item):
    try:return int(item.get("z_index",item.get("layer",0) if "kind" in item else item.get("depth",0)))
    except Exception:return 0


def scene_hierarchy_set_local_z(item,value):
    if not isinstance(item,dict):return
    value=max(-10000,min(10000,int(value)));item["z_index"]=value
    if "kind" in item:item["layer"]=value
    else:item["depth"]=value
    scene_proxy_invalidate()


def scene_hierarchy_effective_z(item):
    total=scene_hierarchy_local_z(item);seen={scene_hierarchy_key_for(item)};parent_key=item.get("hierarchy_parent") if isinstance(item,dict) else None
    for _ in range(32):
        if not parent_key or parent_key in seen:break
        seen.add(parent_key);parent=scene_hierarchy_item(parent_key)
        if parent is None:break
        total+=scene_hierarchy_local_z(parent);parent_key=parent.get("hierarchy_parent")
    return total


def scene_hierarchy_effective_plane(item):
    """Root parent controls whether the complete subtree is behind or front."""
    chain=[];probe=item;seen=set()
    while isinstance(probe,dict):
        key=scene_hierarchy_key_for(probe)
        if not key or key in seen:break
        seen.add(key);chain.append(probe);probe=scene_hierarchy_item(probe.get("hierarchy_parent"))
    root=chain[-1] if chain else item
    if "kind" in root:return "back" if str(root.get("draw_layer","front")) in ("back","behind") else "front"
    return "back" if str(root.get("layer","front")) in ("back","behind") else "front"


def scene_hierarchy_parent_hidden(item):
    seen=set();parent_key=item.get("hierarchy_parent") if isinstance(item,dict) else None
    for _ in range(32):
        if not parent_key or parent_key in seen:break
        seen.add(parent_key);parent=scene_hierarchy_item(parent_key)
        if parent is None:break
        if not parent.get("visible",True) or parent.get("_group_hidden"):return True
        parent_key=parent.get("hierarchy_parent")
    return False


def scene_hierarchy_set_parent(item,parent):
    key=scene_hierarchy_key_for(item);parent_key=scene_hierarchy_key_for(parent) if parent else None
    if not key or key==parent_key:return False
    # Reject cycles: a node cannot become a child of one of its descendants.
    probe=parent;seen=set()
    while probe is not None:
        pkey=scene_hierarchy_key_for(probe)
        if pkey==key:return False
        if not pkey or pkey in seen:break
        seen.add(pkey);probe=scene_hierarchy_item(probe.get("hierarchy_parent"))
    item["hierarchy_parent"]=parent_key;scene_proxy_invalidate();return True


def scene_hierarchy_children(parent_key):
    return [item for item in scene_hierarchy_all_items() if item.get("hierarchy_parent")==parent_key]


def scene_hierarchy_reorder(item,target,before=True):
    """Move one subtree using integer Z steps while preserving unrelated values."""
    if item is None or target is None or item is target:return False
    parent_key=target.get("hierarchy_parent");item["hierarchy_parent"]=parent_key
    siblings=[node for node in scene_hierarchy_all_items() if node.get("hierarchy_parent")==parent_key and node is not item]
    siblings.sort(key=lambda node:(-scene_hierarchy_local_z(node),_eh_label(node).lower() if "_eh_label" in globals() else ""))
    idx=siblings.index(target) if target in siblings else len(siblings)
    if not before:idx+=1
    idx=max(0,min(len(siblings),idx));ordered=list(siblings);ordered.insert(idx,item)
    prev_node=ordered[idx-1] if idx>0 else None;next_node=ordered[idx+1] if idx+1<len(ordered) else None
    if prev_node is None and next_node is None:new_z=0
    elif prev_node is None:new_z=scene_hierarchy_local_z(next_node)+1
    elif next_node is None:new_z=scene_hierarchy_local_z(prev_node)-1
    else:
        upper=scene_hierarchy_local_z(prev_node);lower=scene_hierarchy_local_z(next_node)
        if upper-lower>=2:new_z=lower+(upper-lower)//2
        else:
            # Only the nodes at/below the insertion point move; values above and
            # every other parent branch remain untouched.
            for shifted in ordered[idx+1:]:scene_hierarchy_set_local_z(shifted,scene_hierarchy_local_z(shifted)-1)
            new_z=upper-1
    scene_hierarchy_set_local_z(item,new_z);return True


def scene_hierarchy_move_step(item,direction):
    """Move selected item one visible sibling step without drag/drop."""
    if item is None:return False
    parent=item.get("hierarchy_parent");siblings=[node for node in scene_hierarchy_all_items() if node.get("hierarchy_parent")==parent]
    siblings.sort(key=lambda node:(-scene_hierarchy_local_z(node),_eh_label(node).lower() if "_eh_label" in globals() else ""))
    try:index=siblings.index(item)
    except ValueError:return False
    if int(direction)<0:
        if index<=0:return False
        return scene_hierarchy_reorder(item,siblings[index-1],before=True)
    if index>=len(siblings)-1:return False
    return scene_hierarchy_reorder(item,siblings[index+1],before=False)

def scene_z_order_peers(item):
    """Everything sharing this item's draw bucket.

    Depth only matters against nodes drawn in the same pass, so "bring to
    front" means front of the FRONT layer, not in front of things that are
    deliberately behind the characters.
    """
    bucket = str(item.get("draw_layer", "front")) if "kind" in item else \
        str(item.get("layer", "front"))
    out = []
    for en in external_nodes:
        if str(en.get("draw_layer", "front")) == bucket:
            out.append(("layer", en))
    for coll in (scene_texts, scene_images):
        for it in coll:
            if str(it.get("layer", "front")) == ("front" if bucket == "front" else "back"):
                out.append(("depth", it))
    return out

def scene_z_nudge(item,mode):
    """Front/back/up/down using hierarchy-local integer Z values."""
    if item is None:return False
    siblings=[node for node in scene_hierarchy_all_items() if node is not item and node.get("hierarchy_parent")==item.get("hierarchy_parent")]
    siblings.sort(key=lambda node:(-scene_hierarchy_local_z(node),_eh_label(node).lower() if "_eh_label" in globals() else ""))
    scene_undo_push("Change draw order")
    if not siblings:return False
    if mode=="front":scene_hierarchy_set_local_z(item,max(scene_hierarchy_local_z(node) for node in siblings)+1);return True
    if mode=="back":scene_hierarchy_set_local_z(item,min(scene_hierarchy_local_z(node) for node in siblings)-1);return True
    ordered=sorted(siblings+[item],key=lambda node:(-scene_hierarchy_local_z(node),_eh_label(node).lower() if "_eh_label" in globals() else ""));index=ordered.index(item)
    if mode=="up" and index>0:return scene_hierarchy_reorder(item,ordered[index-1],True)
    if mode=="down" and index<len(ordered)-1:return scene_hierarchy_reorder(item,ordered[index+1],False)
    return False

def scene_hierarchy_descendants(item):
    root=scene_hierarchy_key_for(item);out=[];queue=[root];seen={root}
    while queue:
        parent=queue.pop(0)
        for child in scene_hierarchy_children(parent):
            key=scene_hierarchy_key_for(child)
            if key and key not in seen:seen.add(key);out.append(child);queue.append(key)
    return out


def _scene_move_item_force(item,dx,dy):
    """Move a hierarchy follower even when the child itself is locked."""
    if "kind" in item:
        if item.get("camera_locked"):
            frame=((virtual_camera.get("_preview_frame") or _virtual_camera_display_frame()) if virtual_camera.get("enabled") else None);fw=frame.width if frame else WIDTH;fh=frame.height if frame else HEIGHT;item["fx"]=max(0,min(1,float(item.get("fx",.5))+dx/max(1,fw)));item["fy"]=max(0,min(1,float(item.get("fy",.5))+dy/max(1,fh)))
        else:
            zoom=max(.001,float(camera.get("zoom",1)));item["wx"]=float(item.get("wx",0))+dx/zoom;item["wy"]=float(item.get("wy",0))+dy/zoom
            if item.get("kind") in ("wall","line"):item["wx2"]=float(item.get("wx2",0))+dx/zoom;item["wy2"]=float(item.get("wy2",0))+dy/zoom
    else:
        world=(item.get("world_space") or item.get("_world_space")) and not item.get("camera_locked",False)
        if world:
            zoom=max(.001,float(camera.get("zoom",1)));item["wx"]=float(item.get("wx",0))+dx/zoom;item["wy"]=float(item.get("wy",0))+dy/zoom
        else:
            frame=((virtual_camera.get("_preview_frame") or _virtual_camera_display_frame()) if virtual_camera.get("enabled") else None);fw=frame.width if frame else WIDTH;fh=frame.height if frame else HEIGHT;item["fx"]=max(0,min(1,float(item.get("fx",.5))+dx/max(1,fw)));item["fy"]=max(0,min(1,float(item.get("fy",.5))+dy/max(1,fh)))


def scene_hierarchy_move_subtree(item,dx,dy,include_root=True):
    if item is None:return 0
    nodes=([item] if include_root else [])+scene_hierarchy_descendants(item)
    for node in nodes:_scene_move_item_force(node,dx,dy)
    scene_proxy_invalidate();return len(nodes)


def _scene_selected_has_ancestor(item,selected_keys):
    parent=item.get("hierarchy_parent");seen=set()
    while parent and parent not in seen:
        if parent in selected_keys:return True
        seen.add(parent);p=scene_hierarchy_item(parent);parent=p.get("hierarchy_parent") if p else None
    return False


def scene_sel_move(dx, dy):
    """Move selected hierarchy roots; descendants follow even when locked."""
    moved_groups=set();selected=scene_sel_items();selected_hkeys={scene_hierarchy_key_for(it) for it in selected}
    for it in selected:
        if scene_item_effectively_locked(it) or _scene_selected_has_ancestor(it,selected_hkeys):continue
        if scene_hierarchy_children(scene_hierarchy_key_for(it)):
            scene_hierarchy_move_subtree(it,dx,dy,True);continue
        key=scene_sel_key_for(it);grp=scene_group_of_node(key[1]) if key and key[0]=="en" else scene_group_of_text(key[1]) if key and key[0]=="text" else scene_group_of_image(key[1]) if key else None
        if grp is not None:
            root=scene_group_root(grp.get("id")) or grp;gid=root.get("id")
            if gid in moved_groups or root.get("locked"):continue
            moved_groups.add(gid);move_scene_group(root,dx,dy);continue
        if key and key[0]=="en":_en_move_by(it,dx,dy)
        else:_si_move_item(it,dx,dy)
    scene_proxy_invalidate()

def _en_move_by(node, dx, dy):
    """Shift one external node by a screen delta, honouring its space."""
    if node is None or node.get("locked"):
        return
    if node.get("camera_locked"):
        frame = ((virtual_camera.get("_preview_frame") or _virtual_camera_display_frame()) if virtual_camera.get("enabled") else None)
        fw = frame.width if frame else WIDTH
        fh = frame.height if frame else HEIGHT
        node["fx"] = max(0.0, min(1.0, float(node.get("fx", 0.5)) + dx / max(1, fw)))
        node["fy"] = max(0.0, min(1.0, float(node.get("fy", 0.5)) + dy / max(1, fh)))
    else:
        zoom = max(0.001, float(camera.get("zoom", 1.0)))
        node["wx"] = float(node.get("wx", 0.0)) + dx / zoom
        node["wy"] = float(node.get("wy", 0.0)) + dy / zoom
        if node.get("kind") in ("wall", "line"):
            node["wx2"] = float(node.get("wx2", 0.0)) + dx / zoom
            node["wy2"] = float(node.get("wy2", 0.0)) + dy / zoom

def scene_sel_marquee(rect, additive=False):
    """Select everything whose drawn rect intersects the marquee.

    Uses each item's cached "_rect" -- the on-screen box from the last draw --
    so hit testing matches exactly what the user can see, including rotation
    and scale, without re-deriving any geometry.
    """
    if not additive:
        modal["_scene_multi_sel"] = set()
    sel = scene_sel_get()
    n = 0
    for coll, kind in ((external_nodes, "en"), (scene_texts, "text"), (scene_images, "image")):
        for it in coll:
            if it.get("locked") or _scene_item_hidden(it):
                continue
            r = it.get("_rect")
            if r is None or not rect.colliderect(r):
                continue
            k = scene_sel_key_for(it)
            if k:
                sel.add(k)
                n += 1
    _last = next(iter(sel), None) if sel else None
    modal["_sn_sel"] = _last
    modal["_en_selected_id"] = _last[1] if (_last and _last[0] == "en") else None
    return n

# ══════════════════════════════════════════════════════════════════════════
# ALIGN / DISTRIBUTE / MATCH SIZE
# ══════════════════════════════════════════════════════════════════════════
# All of these operate on the cached screen rects ("_rect") and then apply the
# resulting screen-space delta through the same movers used by dragging, so a
# mixed selection of world-space and camera-locked items aligns correctly
# without any per-kind special casing at the call site.

def _scene_sel_rects():
    """[(item, rect)] for selected items that were actually drawn."""
    out = []
    for it in scene_sel_items():
        r = it.get("_rect")
        if r is not None and not it.get("locked"):
            out.append((it, r))
    return out

def scene_align(mode):
    """mode: left|right|center_x|top|bottom|center_y"""
    pairs = _scene_sel_rects()
    if len(pairs) < 2:
        push_toast("Select 2 or more items to align", "warning", 2.2)
        return 0
    rects = [r for _, r in pairs]
    if mode == "left":
        target = min(r.left for r in rects)
        delta = lambda r: (target - r.left, 0)
    elif mode == "right":
        target = max(r.right for r in rects)
        delta = lambda r: (target - r.right, 0)
    elif mode == "center_x":
        target = sum(r.centerx for r in rects) / len(rects)
        delta = lambda r: (target - r.centerx, 0)
    elif mode == "top":
        target = min(r.top for r in rects)
        delta = lambda r: (0, target - r.top)
    elif mode == "bottom":
        target = max(r.bottom for r in rects)
        delta = lambda r: (0, target - r.bottom)
    elif mode == "center_y":
        target = sum(r.centery for r in rects) / len(rects)
        delta = lambda r: (0, target - r.centery)
    else:
        return 0
    scene_undo_push(f"Align {mode.replace('_', ' ')}")
    for it, r in pairs:
        dx, dy = delta(r)
        if abs(dx) > 0.01 or abs(dy) > 0.01:
            _scene_move_one(it, dx, dy)
    return len(pairs)

def _scene_move_one(item, dx, dy):
    """Move a single item by a screen delta, ignoring group membership.

    Align/distribute deliberately bypasses the "grouped members move as one"
    rule: the whole point is to reposition items relative to each other, and
    dragging the group would defeat that.
    """
    k = scene_sel_key_for(item)
    if k and k[0] == "en":
        _en_move_by(item, dx, dy)
    else:
        _si_move_item(item, dx, dy)

def scene_distribute(axis):
    """Even spacing between item centres. axis: 'h' or 'v'."""
    pairs = _scene_sel_rects()
    if len(pairs) < 3:
        push_toast("Select 3 or more items to distribute", "warning", 2.2)
        return 0
    horiz = (axis == "h")
    pairs.sort(key=lambda p: p[1].centerx if horiz else p[1].centery)
    first = pairs[0][1]
    last = pairs[-1][1]
    lo = first.centerx if horiz else first.centery
    hi = last.centerx if horiz else last.centery
    step = (hi - lo) / (len(pairs) - 1)
    scene_undo_push("Distribute " + ("horizontally" if horiz else "vertically"))
    # Endpoints stay put; everything between them is respaced.
    for i, (it, r) in enumerate(pairs[1:-1], start=1):
        want = lo + step * i
        cur = r.centerx if horiz else r.centery
        d = want - cur
        if abs(d) > 0.01:
            _scene_move_one(it, d if horiz else 0, 0 if horiz else d)
    return len(pairs)

def scene_match_size(axis):
    """Scale every selected item so its drawn size matches the largest.

    Scene items don't share a width/height field -- text has a font size,
    images and nodes have a scale multiplier, shapes have w/h -- so this works
    on the ratio between drawn rects and nudges each item's own size field by
    that ratio. axis: 'w' | 'h'
    """
    pairs = _scene_sel_rects()
    if len(pairs) < 2:
        push_toast("Select 2 or more items to match size", "warning", 2.2)
        return 0
    target = max((r.width if axis == "w" else r.height) for _, r in pairs)
    if target <= 0:
        return 0
    scene_undo_push("Match " + ("width" if axis == "w" else "height"))
    n = 0
    for it, r in pairs:
        cur = r.width if axis == "w" else r.height
        if cur <= 0:
            continue
        ratio = target / float(cur)
        if abs(ratio - 1.0) < 0.005:
            continue
        k = scene_sel_key_for(it)
        if k and k[0] == "en" and it.get("kind") == "rect_box":
            # Rect boxes have explicit dimensions -- resize the real field so
            # the change survives a zoom change, instead of faking it with scale.
            if axis == "w":
                it["w"] = max(4.0, float(it.get("w", 100)) * ratio)
            else:
                it["h"] = max(4.0, float(it.get("h", 60)) * ratio)
        elif k and k[0] == "text":
            it["size"] = max(8, int(round(float(it.get("size", 28)) * ratio)))
        else:
            it["scale"] = max(0.02, float(it.get("scale", 1.0)) * ratio)
        n += 1
    return n

def move_scene_group_items(group, dx, dy, moved=None, moved_groups=None):
    """Move a group's texts and images (external nodes are handled by
    move_scene_group)."""
    moved = moved if moved is not None else set()
    moved_groups = moved_groups if moved_groups is not None else set()
    gid = group.get("id")
    if gid in moved_groups or group.get("locked"):
        return
    moved_groups.add(gid)
    for sid in scene_group_text_ids(group):
        key = ("t", sid)
        if key in moved:
            continue
        moved.add(key)
        _si_move_item(get_scene_text(sid), dx, dy)
    for sid in scene_group_image_ids(group):
        key = ("i", sid)
        if key in moved:
            continue
        moved.add(key)
        _si_move_item(get_scene_image(sid), dx, dy)
    for child in scene_group_children(group):
        move_scene_group_items(child, dx, dy, moved, moved_groups)

def set_scene_group_items_visible(group, visible, seen=None):
    """Texts/images have no 'visible' flag; hide them via alpha/vcam instead.
    We use a dedicated key so unhiding restores the author's value."""
    seen = seen if seen is not None else set()
    if group.get("id") in seen:
        return
    seen.add(group.get("id"))
    for sid in scene_group_text_ids(group):
        t = get_scene_text(sid)
        if t is not None:
            t["_group_hidden"] = not bool(visible)
    for sid in scene_group_image_ids(group):
        im = get_scene_image(sid)
        if im is not None:
            im["_group_hidden"] = not bool(visible)
    for child in scene_group_children(group):
        set_scene_group_items_visible(child, visible, seen)

def set_scene_group_items_locked(group, locked, seen=None):
    seen = seen if seen is not None else set()
    if group.get("id") in seen:
        return
    seen.add(group.get("id"))
    for sid in scene_group_text_ids(group):
        t = get_scene_text(sid)
        if t is not None:
            t["locked"] = bool(locked)
    for sid in scene_group_image_ids(group):
        im = get_scene_image(sid)
        if im is not None:
            im["locked"] = bool(locked)
    for child in scene_group_children(group):
        set_scene_group_items_locked(child, locked, seen)

# ---------- wrap the group primitives so all three kinds travel together ----

_move_scene_group_nodes_only = move_scene_group
_set_group_visible_nodes_only = set_scene_group_visible
_set_group_locked_nodes_only = set_scene_group_locked
_scene_group_bounds_nodes_only = scene_group_bounds
_ungroup_scene_group_nodes_only = ungroup_scene_group

def move_scene_group(group, dx, dy, moved=None, moved_groups=None):      # noqa: F811
    _move_scene_group_nodes_only(group, dx, dy, moved, moved_groups)
    # Separate visit-set: node ids and (kind, sid) keys never collide, but
    # the group-visit set must not be shared or the second pass is skipped.
    move_scene_group_items(group, dx, dy)

def set_scene_group_visible(group, visible, seen=None):                  # noqa: F811
    _set_group_visible_nodes_only(group, visible, seen)
    set_scene_group_items_visible(group, visible)

def set_scene_group_locked(group, locked, seen=None):                    # noqa: F811
    _set_group_locked_nodes_only(group, locked, seen)
    set_scene_group_items_locked(group, locked)

def scene_group_bounds(group):                                           # noqa: F811
    """Outline covers external nodes, texts and images alike.

    Hidden members contribute nothing. A group whose members are all hidden
    has no bounds at all, which is what makes draw_scene_group_outlines skip
    it -- otherwise the frame and its drag handle stayed on screen wrapped
    around empty space.
    """
    rects = []
    base = _scene_group_bounds_nodes_only(group)
    if base is not None:
        # Undo the padding the node-only version already added.
        rects.append(pygame.Rect(base.x + 10, base.y + 10,
                                 max(1, base.width - 20), max(1, base.height - 20)))
    for sid in scene_group_all_text_ids(group):
        t = get_scene_text(sid)
        if t is not None and t.get("_rect") is not None and not _scene_item_hidden(t):
            rects.append(t["_rect"])
    for sid in scene_group_all_image_ids(group):
        im = get_scene_image(sid)
        if im is not None and im.get("_rect") is not None and not _scene_item_hidden(im):
            rects.append(im["_rect"])
    if not rects:
        return None
    left = min(r.left for r in rects)
    top = min(r.top for r in rects)
    right = max(r.right for r in rects)
    bottom = max(r.bottom for r in rects)
    return pygame.Rect(left - 10, top - 10, right - left + 20, bottom - top + 20)

def ungroup_scene_group(group_id, delete_nodes=False):                   # noqa: F811
    scene_undo_push("Delete group" if delete_nodes else "Ungroup")
    group = get_scene_group(group_id)
    if group is not None and delete_nodes:
        # Delete member texts/images too, deepest-first so indices stay valid.
        doomed_t = scene_group_all_text_ids(group)
        doomed_i = scene_group_all_image_ids(group)
        if doomed_t:
            scene_texts[:] = [t for t in scene_texts if t.get("sid") not in doomed_t]
        if doomed_i:
            scene_images[:] = [im for im in scene_images if im.get("sid") not in doomed_i]
    return _ungroup_scene_group_nodes_only(group_id, delete_nodes)

# ---------- serialisation ----------

_serialize_scene_groups_items_v = serialize_scene_groups
_restore_scene_groups_items_v = restore_scene_groups

def serialize_scene_groups():                                            # noqa: F811
    out = _serialize_scene_groups_items_v()
    by_id = {g.get("id"): g for g in scene_groups}
    for entry in out:
        g = by_id.get(entry.get("id"))
        if g is not None:
            entry["text_ids"] = scene_group_text_ids(g)
            entry["image_ids"] = scene_group_image_ids(g)
    return out

def restore_scene_groups(data):                                          # noqa: F811
    _restore_scene_groups_items_v(data)
    by_id = {g.get("id"): g for g in scene_groups}
    for raw in data or []:
        if not isinstance(raw, dict):
            continue
        try:
            g = by_id.get(int(raw.get("id")))
        except (TypeError, ValueError):
            continue
        if g is None:
            continue
        g["text_ids"] = [int(x) for x in raw.get("text_ids", []) or []
                         if str(x).lstrip("-").isdigit()]
        g["image_ids"] = [int(x) for x in raw.get("image_ids", []) or []
                          if str(x).lstrip("-").isdigit()]

def group_selected_scene_items(text_ids=(), image_ids=(), name=None):
    """Create a group straight from picked texts/images."""
    if not text_ids and not image_ids:
        push_toast("Select a text or image first.", "warning", 2.2)
        return None
    group = make_scene_group(name=name)
    n = scene_group_add_texts(group, text_ids) + scene_group_add_images(group, image_ids)
    push_toast(f"Created '{group['name']}' with {n} item(s).", "success", 2.2)
    return group

