# User-editable shortcuts for the node action menu.  Keeping these in the
# editor config (rather than in a graph) means the same muscle memory works in
# every blueprint.  Existing conventional shortcuts are shown by default;
# every other action starts unassigned until the user chooses a chord.
NS_DEFAULT_ACTION_KEYBINDS = {
    "duplicate": "ctrl+d",
    "copy": "ctrl+c",
    "delete": "delete",
    "toggle_minimap": "m",
}

def _ns_normalize_chord(chord):
    if not chord:
        return ""
    parts = [p.strip().lower().replace(" ", "_") for p in str(chord).split("+") if p.strip()]
    aliases = {"control": "ctrl", "left_ctrl": "ctrl", "right_ctrl": "ctrl",
               "left_shift": "shift", "right_shift": "shift",
               "left_alt": "alt", "right_alt": "alt", "meta": "super"}
    parts = [aliases.get(p, p) for p in parts]
    ordered = [m for m in ("ctrl", "alt", "shift", "super") if m in parts]
    base = [p for p in parts if p not in ("ctrl", "alt", "shift", "super")]
    return "+".join(ordered + base[-1:])

def _ns_load_action_keybinds():
    valid = {action[1] for action in NS_NODE_ACTIONS}
    raw = _editor_config.get("visual_scripter_action_keybinds")
    if not isinstance(raw, dict):
        raw = dict(NS_DEFAULT_ACTION_KEYBINDS)
    return {key: _ns_normalize_chord(value) for key, value in raw.items()
            if key in valid and _ns_normalize_chord(value)}

NS_ACTION_KEYBINDS = _ns_load_action_keybinds()

def _ns_save_action_keybinds():
    _editor_config["visual_scripter_action_keybinds"] = dict(NS_ACTION_KEYBINDS)
    save_editor_config(_editor_config)

def _ns_event_chord(event):
    """Return a stable Ctrl/Alt/Shift+key string for a Pygame KEYDOWN."""
    modifier_keys = {
        pygame.K_LCTRL, pygame.K_RCTRL, pygame.K_LSHIFT, pygame.K_RSHIFT,
        pygame.K_LALT, pygame.K_RALT,
    }
    if event.key in modifier_keys:
        return ""
    mods = getattr(event, "mod", pygame.key.get_mods())
    parts = []
    if mods & pygame.KMOD_CTRL: parts.append("ctrl")
    if mods & pygame.KMOD_ALT: parts.append("alt")
    if mods & pygame.KMOD_SHIFT: parts.append("shift")
    if mods & (getattr(pygame, "KMOD_META", 0) | getattr(pygame, "KMOD_GUI", 0)):
        parts.append("super")
    try:
        base = pygame.key.name(event.key).lower().replace(" ", "_")
    except Exception:
        base = ""
    # Keypad and punctuation names stay stable; modifiers remain separate so
    # Shift+2 is not collapsed into the resulting '@' character.
    aliases={"kp_0":"keypad_0","kp_1":"keypad_1","kp_2":"keypad_2","kp_3":"keypad_3",
             "kp_4":"keypad_4","kp_5":"keypad_5","kp_6":"keypad_6","kp_7":"keypad_7",
             "kp_8":"keypad_8","kp_9":"keypad_9"}
    base=aliases.get(base,base)
    return _ns_normalize_chord("+".join(parts + ([base] if base else [])))

def _ns_chord_label(chord):
    if not chord:
        return "Unassigned"
    nice = {"ctrl": "Ctrl", "alt": "Alt", "shift": "Shift", "super": "Super",
            "delete": "Delete", "backspace": "Backspace", "space": "Space",
            "return": "Enter"}
    return "+".join(nice.get(part, part.replace("_", " ").title())
                    for part in chord.split("+"))

