    ("Tools","asset_creator","Open / Close Asset Creator","image_",["f1"],"press"),("Tools","anim_states","Open / Close Animation States","timeline",["f2"],"press"),("Tools","node_groups","Open / Close Node Groups","hierarchy",["f3"],"press"),("Tools","gif_import","Import GIF Frames","image",["f4"],"press"),("Tools","sheet_extract","Sprite Sheet Extractor","grid",["ctrl+f4"],"press"),("Tools","tileset_extract","Tileset 3×3","grid",["ctrl+f3"],"press"),("Tools","char_vault","Character Vault","bookmark",["ctrl+f1"],"press"),("Tools","easing_editor","Easing Editor","curve",["f8"],"press"),("Tools","motion_studio","Motion Studio","motion",["f9"],"press"),("Tools","asset_library","Asset Library","folder",["f10"],"press"),
