def _skb_rows_for_workspace(ws=None):
    """Id-registry filter: 3D keybinds show camera + terminal; 2D hides 3D-only camera binds."""
    ws = ws or modal.get("_skb_workspace") or "arena2d"
    if ws == "env3d":
        return [row for row in SCENE_KEYBIND_ACTIONS if row[1] in _ENV3D_KEYBIND_KEYS]
    return [row for row in SCENE_KEYBIND_ACTIONS if row[1] not in _ENV3D_ONLY_KEYS]


def _scene_binding_obj(value,kind="press"):
    if isinstance(value,dict):token=_ns_normalize_chord(value.get("input",""));return {"input":token,"delay":max(0.0,min(2.0,float(value.get("delay",0.0)))) ,"repeat":max(.02,min(2.0,float(value.get("repeat",.08))))}
    return {"input":_ns_normalize_chord(value),"delay":0.0,"repeat":.08}


def _load_scene_keybinds():
    raw=_editor_config.get("scene_keybinds",{});legacy=_editor_config.get("scene_shortcuts",{});out={}
    for _cat,key,_title,_icon,defaults,kind in SCENE_KEYBIND_ACTIONS:
        source=raw.get(key,None) if isinstance(raw,dict) else None
        if source is None and key in legacy:source=[legacy.get(key)]
        if source is None:source=defaults
        if not isinstance(source,(list,tuple)):source=[source]
        bindings=[]
        for value in source:
            obj=_scene_binding_obj(value,kind)
            if obj["input"] and obj["input"] not in [b["input"] for b in bindings]:bindings.append(obj)
        out[key]=bindings
    return out


SCENE_KEYBINDS=_load_scene_keybinds()
SCENE_SHORTCUTS={key:(vals[0]["input"] if vals else "") for key,vals in SCENE_KEYBINDS.items()}
_SCENE_INPUT_DOWN=set();_SCENE_INPUT_STARTED={};_SCENE_CAMERA_DRAG={"active":False,"last":None}


def _save_scene_shortcuts():
    _editor_config["scene_keybinds"]={key:[dict(binding) for binding in values] for key,values in SCENE_KEYBINDS.items()};_editor_config["scene_shortcuts"]={key:(values[0]["input"] if values else "") for key,values in SCENE_KEYBINDS.items()};save_editor_config(_editor_config)
    SCENE_SHORTCUTS.clear();SCENE_SHORTCUTS.update({key:(vals[0]["input"] if vals else "") for key,vals in SCENE_KEYBINDS.items()})


def _scene_input_token(event):
    mods=getattr(event,"mod",pygame.key.get_mods());parts=[]
    if mods&pygame.KMOD_CTRL:parts.append("ctrl")
    if mods&pygame.KMOD_ALT:parts.append("alt")
    if mods&pygame.KMOD_SHIFT:parts.append("shift")
    if mods&(getattr(pygame,"KMOD_META",0)|getattr(pygame,"KMOD_GUI",0)):parts.append("super")
    base=""
    if event.type in (pygame.KEYDOWN,pygame.KEYUP):
        try:base=pygame.key.name(event.key).lower().replace(" ","_")
        except Exception:base=""
        if base in ("left_ctrl","right_ctrl","left_shift","right_shift","left_alt","right_alt","left_gui","right_gui"):return ""
    elif event.type in (pygame.MOUSEBUTTONDOWN,pygame.MOUSEBUTTONUP):base={1:"mouse_left",2:"mouse_middle",3:"mouse_right",4:"wheel_up",5:"wheel_down"}.get(getattr(event,"button",0),"")
    elif event.type==pygame.MOUSEWHEEL:base="wheel_up" if event.y>0 else "wheel_down" if event.y<0 else ""
    return _ns_normalize_chord("+".join(parts+([base] if base else [])))


def _scene_input_label(token):
    mouse={"mouse_left":"Mouse Left","mouse_middle":"Mouse Middle","mouse_right":"Mouse Right","wheel_up":"Wheel Up","wheel_down":"Wheel Down"};parts=str(token).split("+");return "+".join(mouse.get(p,{"ctrl":"Ctrl","alt":"Alt","shift":"Shift","super":"Super"}.get(p,p.replace("_"," ").title())) for p in parts) if token else "Unassigned"


def _scene_shortcut_label(action):
    vals=SCENE_KEYBINDS.get(action,[])
    if not vals:return "Unassigned"
    labels=[_scene_input_label(v["input"]) for v in vals[:2]]
    return " / ".join(labels)+(f" +{len(vals)-2}" if len(vals)>2 else "")


def _scene_binding_matches(action,token):return bool(token and any(b.get("input")==token for b in SCENE_KEYBINDS.get(action,[])))

def _scene_mod_held(action, fallback_mod=None):
    """True when a hold-style modifier binding for `action` is down."""
    mods = pygame.key.get_mods()
    binds = SCENE_KEYBINDS.get(action) or []
    names = []
    for b in binds:
        inp = str((b or {}).get("input") or "")
        if inp:
            names.append(inp.split("+")[0] if inp.split("+")[0] in ("ctrl", "shift", "alt", "super") else inp)
    if not names:
        if fallback_mod is None:
            fallback_mod = pygame.KMOD_CTRL
        return bool(mods & fallback_mod)
    for inp in names:
        if inp == "ctrl" and (mods & pygame.KMOD_CTRL):
            return True
        if inp == "shift" and (mods & pygame.KMOD_SHIFT):
            return True
        if inp == "alt" and (mods & pygame.KMOD_ALT):
            return True
        if inp == "super" and (mods & (getattr(pygame, "KMOD_META", 0) | getattr(pygame, "KMOD_GUI", 0))):
            return True
    return False


def _scene_action_event(event,action):return bool(event.type==pygame.KEYDOWN and _scene_binding_matches(action,_scene_input_token(event)))


def _assign_scene_shortcut(action,chord):
    token=_ns_normalize_chord(chord);SCENE_KEYBINDS[action]=([{"input":token,"delay":0.0,"repeat":.08}] if token else []);_save_scene_shortcuts()


def _handle_scene_shortcut_capture(event):return False


def _scene_bind_note_event(event):
    token=_scene_input_token(event);now=time.monotonic()
    if event.type in (pygame.KEYDOWN,pygame.MOUSEBUTTONDOWN):
        if token and token.split("+")[-1] not in ("wheel_up","wheel_down"):_SCENE_INPUT_DOWN.add(token);_SCENE_INPUT_STARTED.setdefault(token,now)
    elif event.type in (pygame.KEYUP,pygame.MOUSEBUTTONUP):
        if event.type==pygame.KEYUP:
            try:base=pygame.key.name(event.key).lower().replace(" ","_")
            except Exception:base=""
        else:base={1:"mouse_left",2:"mouse_middle",3:"mouse_right",4:"wheel_up",5:"wheel_down"}.get(getattr(event,"button",0),"")
        for down in list(_SCENE_INPUT_DOWN):
            if down.split("+")[-1]==base:_SCENE_INPUT_DOWN.discard(down);_SCENE_INPUT_STARTED.pop(down,None)


def _scene_binding_active(action):
    now=time.monotonic()
    for binding in SCENE_KEYBINDS.get(action,[]):
        token=binding.get("input","")
        if token in _SCENE_INPUT_DOWN and now-float(_SCENE_INPUT_STARTED.get(token,now))>=float(binding.get("delay",0)):return True
    return False


def _scene_camera_pan_vector():
    x=float(_scene_binding_active("camera_pan_right"))-float(_scene_binding_active("camera_pan_left"));y=float(_scene_binding_active("camera_pan_down"))-float(_scene_binding_active("camera_pan_up"));return pygame.Vector2(x,y)


def _scene_selection_role(event):
    token=_scene_input_token(event)
    # Most specific selection gesture wins; shared controls remain legal.
    for action,role in (("select_range","range"),("select_add","add"),("select_primary","primary")):
        if _scene_binding_matches(action,token):return role
    return None


def _scene_event_is_selection(event):return event.type==pygame.MOUSEBUTTONDOWN and _scene_selection_role(event) is not None


def _scene_context_event(event):return event.type==pygame.MOUSEBUTTONDOWN and _scene_binding_matches("context_menu",_scene_input_token(event))


def _handle_scene_camera_drag_event(event):
    if modal.get("type") is not None or _ns_terminal.get("open") or _UI_MODIFY_MODE:return False
    if event.type==pygame.MOUSEBUTTONDOWN and _scene_binding_matches("camera_drag",_scene_input_token(event)):
        vc_frame=virtual_camera.get("_preview_frame") if virtual_camera.get("preview") else virtual_camera.get("_scene_frame_rect")
        if (ui_visible and not globals().get("_SIDEBAR_HIDDEN", False) and event.pos[0]<SIDEBAR_W) or point_in_tool_dock(event.pos) or (virtual_camera.get("enabled") and vc_frame and vc_frame.collidepoint(event.pos)):return False
        _SCENE_CAMERA_DRAG.update({"active":True,"last":tuple(event.pos)});camera["target"]=None;return True
    if event.type==pygame.MOUSEMOTION and _SCENE_CAMERA_DRAG.get("active"):
        rel=pygame.Vector2(event.rel)/max(.001,float(camera.get("zoom",1.0)));camera["pos"]-=rel;camera["vel"]=pygame.Vector2(0,0);_SCENE_CAMERA_DRAG["last"]=tuple(event.pos);return True
    if event.type==pygame.MOUSEBUTTONUP and _SCENE_CAMERA_DRAG.get("active"):_SCENE_CAMERA_DRAG.update({"active":False,"last":None});return True
    return False


def open_scene_keybinds(workspace=None):
    ws = workspace or "arena2d"
    rows = _skb_rows_for_workspace(ws)
    cat = rows[0][0] if rows else "Navigation"
    sel = rows[0][1] if rows else "camera_pan_up"
    modal.update({"type":"scene_keybinds","focus":None,"_skb_workspace":ws,"_skb_category":cat,"_skb_selected":sel,"_skb_capture":None,"_skb_test":False,"_skb_scroll":0.0,"_skb_test_input":"","_skb_test_popups":[],"_skb_hits":{},"_skb_return_env3d":ws=="env3d"})


def close_scene_keybinds():
    global _TOOL_MODAL_CLOSE_UNTIL,left_click_this_frame
    _ret=bool(modal.get("_skb_return_env3d"))
    _save_scene_shortcuts();_TOOL_MODAL_CLOSE_UNTIL=time.monotonic()+.28;left_click_this_frame=False
    for _k in ("_skb_workspace","_skb_return_env3d","_skb_category","_skb_selected","_skb_capture","_skb_test","_skb_scroll","_skb_test_input","_skb_test_popups","_skb_hits"):
        modal.pop(_k, None)
    modal["type"]="env3d_embedded" if _ret else None;modal["focus"]=None


def _skb_test_trigger(token):
    matches=[meta["title"] for key,meta in _SCENE_ACTION_META.items() if _scene_binding_matches(key,token)];label=" + ".join(matches[:3]) if matches else "No action bound";modal["_skb_test_input"]=token;modal.setdefault("_skb_test_popups",[]).append({"text":label,"input":token,"time":time.monotonic()});modal["_skb_test_popups"]=modal["_skb_test_popups"][-5:]


def handle_scene_keybinds_event(event):
    if modal.get("type")!="scene_keybinds":return False
    if event.type==pygame.KEYDOWN and event.key==pygame.K_ESCAPE:
        if modal.get("_skb_capture"):modal["_skb_capture"]=None
        elif modal.get("_skb_test"):modal["_skb_test"]=False;_SCENE_INPUT_DOWN.clear()
        else:close_scene_keybinds()
        return True
    hits=modal.get("_skb_hits",{})
    if modal.get("_skb_test") and event.type==pygame.MOUSEBUTTONDOWN and event.button==1:
        if hits.get("test") and hits["test"].collidepoint(event.pos):modal["_skb_test"]=False;_SCENE_INPUT_DOWN.clear();return True
        if hits.get("close") and hits["close"].collidepoint(event.pos):close_scene_keybinds();_SCENE_INPUT_DOWN.clear();return True
    capture=modal.get("_skb_capture")
    if capture and event.type in (pygame.KEYDOWN,pygame.MOUSEBUTTONDOWN,pygame.MOUSEWHEEL):
        if event.type==pygame.KEYDOWN and event.key in (pygame.K_BACKSPACE,pygame.K_DELETE):SCENE_KEYBINDS[capture["action"]]=[];modal["_skb_capture"]=None;_save_scene_shortcuts();return True
        token=_scene_input_token(event);bind_kind=_SCENE_ACTION_META.get(capture["action"],{}).get("kind","press")
        valid=(bind_kind=="press" and event.type==pygame.KEYDOWN) or (bind_kind in ("mouse","drag") and event.type==pygame.MOUSEBUTTONDOWN and getattr(event,"button",0) in (1,2,3)) or (bind_kind=="hold" and event.type in (pygame.KEYDOWN,pygame.MOUSEBUTTONDOWN) and not (event.type==pygame.MOUSEBUTTONDOWN and getattr(event,"button",0) in (4,5)))
        if token and not valid:push_toast("That input does not fit this action type","warning",2);return True
        if token:
            vals=SCENE_KEYBINDS.setdefault(capture["action"],[])
            if token not in [v["input"] for v in vals]:
                if len(vals)>=4:push_toast("Each action supports up to four inputs","warning",2)
                else:vals.append({"input":token,"delay":0.0,"repeat":.08})
            modal["_skb_capture"]=None;_save_scene_shortcuts();push_toast(f"Bound {_scene_input_label(token)}","success",1.8)
        return True
    if modal.get("_skb_test") and event.type==pygame.MOUSEMOTION:
        modal["_skb_pointer_motion_until"]=time.monotonic()+.20;modal["_skb_pointer_pos"]=tuple(event.pos);return True
    if modal.get("_skb_test") and event.type in (pygame.KEYDOWN,pygame.KEYUP,pygame.MOUSEBUTTONDOWN,pygame.MOUSEBUTTONUP,pygame.MOUSEWHEEL):
        _scene_bind_note_event(event);token=_scene_input_token(event)
        if event.type in (pygame.KEYDOWN,pygame.MOUSEBUTTONDOWN,pygame.MOUSEWHEEL) and token:_skb_test_trigger(token)
        return True
    if event.type==pygame.MOUSEWHEEL:modal["_skb_scroll"]=max(0.0,float(modal.get("_skb_scroll",0))-event.y*38);return True
    if event.type==pygame.MOUSEBUTTONDOWN and event.button==1:
        pos=event.pos
        if hits.get("close") and hits["close"].collidepoint(pos):close_scene_keybinds();return True
        if hits.get("test") and hits["test"].collidepoint(pos):modal["_skb_test"]=not modal.get("_skb_test");_SCENE_INPUT_DOWN.clear();return True
        if hits.get("reset") and hits["reset"].collidepoint(pos):
            for _cat,key,_title,_icon,defaults,kind in _skb_rows_for_workspace(modal.get("_skb_workspace") or "arena2d"):SCENE_KEYBINDS[key]=[_scene_binding_obj(v,kind) for v in defaults]
            _save_scene_shortcuts();push_toast("Scene keybind defaults restored","success",2);return True
        for cat,rect in hits.get("categories",[]):
            if rect.collidepoint(pos):modal["_skb_category"]=cat;modal["_skb_selected"]=next((key for c,key,*_ in SCENE_KEYBIND_ACTIONS if c==cat),None);modal["_skb_scroll"]=0.0;return True
        for action,rect in hits.get("actions",[]):
            if rect.collidepoint(pos):modal["_skb_selected"]=action;return True
        if hits.get("add") and hits["add"].collidepoint(pos):modal["_skb_capture"]={"action":modal.get("_skb_selected")};return True
        for action,index,rect in hits.get("remove",[]):
            if rect.collidepoint(pos):
                vals=SCENE_KEYBINDS.get(action,[])
                if 0<=index<len(vals):vals.pop(index);_save_scene_shortcuts()
                return True
        for action,index,delta,field,rect in hits.get("adjust",[]):
            if rect.collidepoint(pos):
                vals=SCENE_KEYBINDS.get(action,[])
                if 0<=index<len(vals):vals[index][field]=max(0.0 if field=="delay" else .02,min(2.0,float(vals[index].get(field,0))+delta));_save_scene_shortcuts()
                return True
    return event.type in (pygame.MOUSEBUTTONDOWN,pygame.MOUSEBUTTONUP,pygame.MOUSEMOTION)


