def _ns_shortcuts_text_focus_active():
    if modal.get("ns_change_node_menu") or modal.get("ns_context_menu") or modal.get("ns_dropdown_menu"):
        return True
    focus = modal.get("focus") or ""
    if focus in ("ns_search", "ns_scene_search", "ns_palette_search", "ns_save_name", "ns_debug_search", "ns_context_search",
                 "ns_dropdown_search", "ns_change_node_search", "text_input_value"):
        return True
    return focus.startswith(("ns_prop:", "ns_prop_number:", "ns_prop_hex:",
                             "ns_node_name:", "ns_fuse_name:", "en_"))

def _ns_assign_action_keybind(action_key, chord):
    chord = _ns_normalize_chord(chord)
    # One chord should do one predictable thing. Reassigning it automatically
    # clears its previous owner instead of leaving an invisible conflict.
    for old_action, old_chord in list(NS_ACTION_KEYBINDS.items()):
        if old_chord == chord and old_action != action_key:
            NS_ACTION_KEYBINDS.pop(old_action, None)
    if chord:
        NS_ACTION_KEYBINDS[action_key] = chord
    else:
        NS_ACTION_KEYBINDS.pop(action_key, None)
    _ns_save_action_keybinds()

def _ns_handle_action_shortcut(event):
    """Capture/edit a shortcut, or run it on the currently selected node."""
    if modal.get("type") != "visual_scripter":
        return False
    capture = modal.get("ns_shortcut_capture")
    if capture:
        if event.key == pygame.K_ESCAPE:
            modal["ns_shortcut_capture"] = None
            push_toast("Shortcut capture cancelled", "info", 1.2)
            return True
        if event.key in (pygame.K_BACKSPACE, pygame.K_DELETE):
            _ns_assign_action_keybind(capture, "")
            modal["ns_shortcut_capture"] = None
            push_toast("Shortcut cleared", "info", 1.3)
            return True
        chord = _ns_event_chord(event)
        if chord:
            _ns_assign_action_keybind(capture, chord)
            modal["ns_shortcut_capture"] = None
            action = next((a for a in NS_NODE_ACTIONS if a[1] == capture), None)
            push_toast(f"{action[2] if action else capture}: {_ns_chord_label(chord)}", "success", 2.0)
        return True
    if _ns_shortcuts_text_focus_active():
        return False
    chord = _ns_event_chord(event)
    action_key = next((key for key, value in NS_ACTION_KEYBINDS.items()
                       if value == chord), None)
    if not action_key:
        if modal.get("ns_shortcuts_open") and event.key == pygame.K_ESCAPE:
            modal["ns_shortcuts_open"] = False
            return True
        return False
    # Preserve the editor's useful Delete behavior when a wire (rather than a
    # node) is selected, even if Delete is managed through this shortcut map.
    if action_key == "delete" and modal.get("ns_selected_wire"):
        ns_delete_selected_wire()
        return True
    if not _ns_perform_node_action(action_key, modal.get("ns_selected")):
        push_toast("Select a node before using that shortcut", "warning", 1.8)
    return True

def _ns_draw_shortcuts_panel(panel_rect, mouse_pos, anchor_rect):
    """Tabbed Visual Scripter settings: shortcuts, canvas, debug UI, audio."""
    if not modal.get("ns_shortcuts_open"):
        modal["_ns_shortcuts_panel_rect"] = None
        modal["_ns_shortcut_bind_rects"] = []
        modal["_ns_shortcut_clear_rects"] = []
        modal["_ns_settings_tab_rects"] = []
        modal["_ns_setting_action_rects"] = []
        return
    panel_w = min(500, max(390, panel_rect.width - 24))
    panel_h = min(540, max(360, panel_rect.bottom - anchor_rect.bottom - 40))
    x = min(max(panel_rect.x + 8, anchor_rect.x-panel_w+anchor_rect.width), panel_rect.right-panel_w-8)
