    def row(y,label,value,action=None,options=None):
        rr=pygame.Rect(body.x,int(y),body.width-4,34)
        ui_draw_rect(screen,PANEL_BG_ALT if rr.collidepoint(mouse_pos) else FIELD_BG,rr,border_radius=7)
        screen.blit(font_sm.render(label,True,TEXT_MAIN),(rr.x+10,rr.y+7))
        if options:
            bx=rr.right-8
            for payload,text in reversed(options):
                bw=max(42,font_tiny.size(text)[0]+14); bx-=bw
