def _ns_action_label(action, node=None):
    """Dynamic labels so the menu reads like professional software."""
    if not node:
        return action[2]
    key = action[1]
    toggles = {
        "lock": ("Unlock Position", "Lock Position", node.get("ui_locked")),
        "mini": ("Exit Mini Node", "Mini Node", node.get("ui_mini")),
        "presentation": ("Exit Presentation Mode", "Presentation Mode", node.get("ui_presentation")),
        "pin": ("Use Normal Visibility", "Keep Visible", node.get("ui_pinned")),
        "hide": ("Unhide Node", "Hide Temporarily", node.get("ui_hidden")),
        "watch": ("Unwatch Node", "Watch Node", node.get("ui_watch")),
        "breakpoint": ("Remove Breakpoint", "Breakpoint", node.get("ui_breakpoint")),
        "show_values": ("Hide Live Values", "Show Live Values", node.get("ui_show_values")),
        "mute": ("Unmute Node", "Mute Node", node.get("ui_muted")),
        "bypass": ("Disable Bypass", "Bypass Node", node.get("ui_bypass")),
        "note": ("Close Node Note", "Node Note", node.get("ui_note_open")),
        "tag_important": ("Unmark Important", "Mark Important", node.get("ui_important")),
        "heatmark": ("Stop Profiling Count", "Profile Execution Count", node.get("ui_hot_path")),
    }
    if key in toggles:
        on_label, off_label, state = toggles[key]
        return on_label if state else off_label
    if key == "toggle_group_collapse":
        g = _ns_group_for_node(node.get("id"))
        return "Expand Smart Group" if g and g.get("collapsed") else "Collapse Smart Group"
    if key == "freeze_group":
        g = _ns_group_for_node(node.get("id"))
        return "Unfreeze Group" if g and g.get("frozen") else "Freeze Group"
    if key == "detach_paint":
        if node and node.get("type") == "clip_paint_bucket":
            gid = node.get("props", {}).get("target_group_id")
            cid = node.get("props", {}).get("clamped_to")
            if gid:
                grp = _ns_group_by_id(gid)
                gname = grp.get("name", "group") if grp else str(gid)
                return f'Detach from Group "{gname}"'
            elif cid:
                tgt = modal.get("ns_nodes", {}).get(cid)
                tname = (tgt.get("custom_name") or NODE_DEFS.get(tgt.get("type"), NodeBase).title) if tgt else str(cid)
                return f'Detach from "{tname}"'
            return "Detach Paint (not connected)"
        return "Detach Paint Bucket"
    return action[2]

def _ns_toggle_node_flag(node, key):
    node[key] = not bool(node.get(key, False))
    modal["ns_dirty"] = True
    return node[key]

def _ns_reveal_all_nodes(snapshot=True):
    nodes = modal.get("ns_nodes", {})
    if snapshot:
        ns_snapshot()
    for n in nodes.values():
        n["ui_hidden"] = False
    modal["ns_solo_ids"] = set()
    modal["ns_dirty"] = True
    push_toast("Revealed all hidden/solo nodes", "info", 1.4)

def _ns_cycle_hide_mode():
    modal["ns_hide_mode"] = "invisible" if modal.get("ns_hide_mode", "transparent") == "transparent" else "transparent"
    push_toast("Hidden nodes: " + ("Invisible" if modal["ns_hide_mode"] == "invisible" else "Transparent/selectable"), "info", 1.8)

