def _ns_connected_ids(start_id, direction="both"):
    nodes = modal.get("ns_nodes", {})
    links = modal.get("ns_links", [])
    out_adj = {}; in_adj = {}
    for l in links:
        out_adj.setdefault(l.get("from"), set()).add(l.get("to"))
        in_adj.setdefault(l.get("to"), set()).add(l.get("from"))
    adjs = []
    if direction in ("down", "both"):
        adjs.append(out_adj)
    if direction in ("up", "both"):
        adjs.append(in_adj)
    seen = {start_id}; stack = [start_id]
    while stack:
        cur = stack.pop()
        for adj in adjs:
            for nxt in adj.get(cur, ()):
                if nxt in nodes and nxt not in seen:
                    seen.add(nxt); stack.append(nxt)
    return seen

def _ns_focus_node_id(nid):
    canvas = modal.get("_ns_canvas_rect")
    node = modal.get("ns_nodes", {}).get(nid)
    if not canvas or not node:
        return
    view = modal.setdefault("ns_view", {"pan": [0, 0], "zoom": 1.0})
    z = max(0.001, view.get("zoom", 1.0))
    nx = float(node.get("x", 0)) + float(NS_NODE_W) * 0.5
    ny = float(node.get("y", 0)) + float(NS_NODE_H_BASE) * 0.5
    view["pan"][0] = canvas.width * 0.5 - nx * z
    view["pan"][1] = canvas.height * 0.5 - ny * z

def _ns_create_smart_group_from_selection(anchor_id=None, anchor_group_id=None):
    nodes = modal.get("ns_nodes", {})
    ids = set(ns_selection_ids())
    if anchor_id in nodes:
        ids.add(anchor_id)
    # Fused/clamped companions are visual units and must remain inside the frame.
    if ids:
        ids = set(_ns_expand_selection_with_fusion(ids, nodes))

    selected_groups = set(modal.get("ns_selected_groups", set()) or set())
    if anchor_group_id is not None and _ns_group_by_id(anchor_group_id):
        selected_groups.add(anchor_group_id)
    children = [_ns_group_by_id(gid) for gid in selected_groups]
    children = [g for g in children if g is not None]
    # Do not add a group and one of its descendants as siblings.
    descendant_ids = set()
    for child in children:
        descendant_ids.update(child.get("child_group_ids", []) or [])
    children = [g for g in children if g.get("id") not in descendant_ids]

    if len(children) > 5:
        push_toast("A group can contain at most 5 direct child groups.", "warning", 3.0)
        return False
    depth = 1 + max((_ns_group_nesting_depth(g) for g in children), default=0)
    if depth > 5:
        push_toast("Smart Group nesting is limited to 5 levels.", "warning", 3.0)
        return False

    # Nodes already represented by a selected child stay owned by that child,
    # not duplicated as direct members of the new parent.
    child_nodes = set()
    for child in children:
        child_nodes.update(_ns_group_all_node_ids(child))
    ids = {nid for nid in ids if nid in nodes and nid not in child_nodes}
    if not ids and not children:
        push_toast("Select node(s), group(s), or both first.", "warning", 2.2)
        return False

    ns_snapshot()
    existing = modal.get("ns_smart_groups", [])
    used_group_ids = {g.get("id") for g in existing}
    gid = int(time.time() * 1000) % 100000000
    while gid in used_group_ids:
        gid = (gid + 1) % 100000000
    group = {
        "id": gid, "name": f"Smart Group {len(existing) + 1}",
        "node_ids": sorted(ids),
        "child_group_ids": [g.get("id") for g in children],
        "collapsed": False, "frozen": False, "color": [90, 160, 255],
        "icon": "folder", "description": "", "tags": [], "padding_scale": 1.0,
        "x": 0, "y": 0, "w": 260, "h": 160,
    }
    # A child group can have only one parent. Re-parent selected children.
    child_ids = set(group["child_group_ids"])
    for old_parent in existing:
        if old_parent.get("id") not in child_ids:
            old_parent["child_group_ids"] = [cid for cid in old_parent.get("child_group_ids", [])
                                               if cid not in child_ids]
    existing.append(group)
    _ns_sync_smart_group_bounds(group)
    modal["ns_selected_groups"] = {gid}
    modal["ns_multi_selected"] = set()
    modal["ns_selected"] = None
    modal["ns_dirty"] = True
    summary = []
    if ids: summary.append(f"{len(ids)} node(s)")
    if children: summary.append(f"{len(children)} nested group(s)")
    push_toast(f"Created {group['name']} with " + " + ".join(summary), "success", 2.5)
    return True

def _ns_perform_node_action(action_key, node_id=None):
    nodes = modal.get("ns_nodes", {})
    node = nodes.get(node_id or modal.get("ns_selected"))
    if action_key == "toggle_radar_arrows":
        modal["ns_show_radar_arrows"] = not modal.get("ns_show_radar_arrows", True)
        if "save_ns_editor_setting" in globals():
            save_ns_editor_setting("ns_show_radar_arrows", modal["ns_show_radar_arrows"])
        push_toast(f"Search Radar Arrows: {'ON' if modal['ns_show_radar_arrows'] else 'OFF'}", "info", 1.8)
        return True
    if action_key == "toggle_minimap":
        modal["ns_show_minimap"] = not modal.get("ns_show_minimap", True)
        if "save_ns_editor_setting" in globals():
            save_ns_editor_setting("ns_show_minimap", modal["ns_show_minimap"])
        push_toast(f"Canvas Minimap Preview: {'ON' if modal['ns_show_minimap'] else 'OFF'}", "info", 1.8)
        return True
    if action_key in ("reveal_all", "health"):
        if action_key == "reveal_all":
            _ns_reveal_all_nodes(snapshot=True)
        else:
            modal["ns_right_tab"] = "issues"
            push_toast("Graph Health opened", "info", 1.4)
        return True
    if not node:
        return False
    _mutating_actions = {"lock", "mini", "presentation", "pin", "hide", "watch", "breakpoint", "show_values", "mute", "bypass", "note", "tag_important", "heatmark", "fit_content", "solo", "select_upstream", "select_downstream", "select_connected", "bookmark", "toggle_group_collapse", "freeze_group", "macro_candidate", "references", "detach_paint"}
    if action_key in _mutating_actions:
        ns_snapshot()
    if action_key in ("lock", "mini", "presentation", "pin", "hide", "watch", "breakpoint", "show_values", "mute", "bypass", "note", "tag_important", "heatmark"):
        flag = {
            "lock":"ui_locked", "mini":"ui_mini", "presentation":"ui_presentation", "pin":"ui_pinned",
            "hide":"ui_hidden", "watch":"ui_watch", "breakpoint":"ui_breakpoint", "show_values":"ui_show_values",
            "mute":"ui_muted", "bypass":"ui_bypass", "note":"ui_note_open", "tag_important":"ui_important",
            "heatmark":"ui_hot_path",
        }[action_key]
        state = _ns_toggle_node_flag(node, flag)
        if action_key == "mute" and state:
            node["ui_bypass"] = False
            # Remove already-queued debug work so a mid-simulation mute is immediate.
            modal["ns_sim_steps"] = [st for st in modal.get("ns_sim_steps", [])
                                     if st.get("node_id") != node.get("id") and st.get("src_id") != node.get("id")]
        elif action_key == "bypass" and state:
            node["ui_muted"] = False
        elif action_key == "watch" and state:
            node["ui_show_values"] = True
        elif action_key == "mini" and state:
            node["ui_presentation"] = False
        elif action_key == "presentation" and state:
            node["ui_mini"] = False
        elif action_key == "heatmark" and state:
            node["_ui_exec_count"] = 0
        if action_key == "mute":
            msg = "Muted: all triggers and downstream flow blocked" if state else "Node unmuted"
        elif action_key == "bypass":
            msg = "Bypass ON: action skipped, primary flow continues" if state else "Bypass disabled"
        elif action_key == "breakpoint":
            msg = "Breakpoint enabled" if state else "Breakpoint removed"
        else:
            msg = f"{action_key.replace('_', ' ').title()}: {'ON' if state else 'OFF'}"
        push_toast(msg, "warning" if action_key == "mute" and state else "info", 2.0)
        return True
    if action_key == "fit_content":
        node["ui_scale"] = 1.0; node["ui_width"] = 1.0; node["ui_height"] = 1.0; modal["ns_dirty"] = True
        return True
    if action_key == "focus":
        _ns_focus_node_id(node["id"]); return True
    if action_key == "solo":
        modal["ns_solo_ids"] = _ns_connected_ids(node["id"], "both"); return True
    if action_key == "select_upstream":
        modal["ns_selected"] = node["id"]; modal["ns_multi_selected"] = _ns_connected_ids(node["id"], "up"); return True
    if action_key == "select_downstream":
        modal["ns_selected"] = node["id"]; modal["ns_multi_selected"] = _ns_connected_ids(node["id"], "down"); return True
    if action_key == "select_connected":
        modal["ns_selected"] = node["id"]; modal["ns_multi_selected"] = _ns_connected_ids(node["id"], "both"); return True
    if action_key == "bookmark":
        modal.setdefault("ns_bookmarks", []).append({"name": node.get("custom_name") or str(node.get("type")), "node_id": node["id"], "x": node.get("x",0), "y": node.get("y",0), "zoom": modal.get("ns_view",{}).get("zoom",1.0)})
        push_toast("Bookmark added", "success", 1.4); return True
    if action_key == "save_cluster":
        return ns_save_selection_as_cluster(anchor_node_id=node["id"])
    if action_key == "smart_group":
        return _ns_create_smart_group_from_selection(node["id"])
    if action_key in ("toggle_group_collapse", "freeze_group"):
        g = _ns_group_for_node(node["id"])
        if not g:
            _ns_create_smart_group_from_selection(node["id"])
            g = _ns_group_for_node(node["id"])
        if g:
            key = "collapsed" if action_key == "toggle_group_collapse" else "frozen"
            g[key] = not bool(g.get(key, False))
            modal["ns_dirty"] = True
            push_toast(f"{g.get('name','Smart Group')} {key}: {'ON' if g[key] else 'OFF'}", "info", 1.6)
            return True
        return False
    if action_key == "macro_candidate":
        for nid in ns_selection_ids() or {node["id"]}:
            if nid in nodes: nodes[nid]["ui_macro_candidate"] = True
        modal["ns_dirty"] = True; push_toast("Marked macro candidate", "info", 1.4); return True
    if action_key == "references":
        modal["ns_right_tab"] = "tools"; node["ui_reference_focus"] = True; return True
    if action_key == "duplicate":
        ns_duplicate_selected(); return True
    if action_key == "copy":
        ns_copy_selected(); return True
    if action_key == "delete":
        ns_delete_selected(); return True
    if action_key == "detach_paint":
        if node and node.get("type") == "clip_paint_bucket":
            ns_snapshot()
            props = node.setdefault("props", {})
            gid = props.get("target_group_id", "")
            cid = props.get("clamped_to", "")
            props["target_group_id"] = ""
            props["clamped_to"] = ""
            modal["ns_dirty"] = True
            if gid:
                grp = _ns_group_by_id(gid)
                gname = grp.get("name", "group") if grp else str(gid)
                push_toast(f'Paint Bucket detached from group "{gname}"', "success", 2.0)
            elif cid:
                tgt = modal.get("ns_nodes", {}).get(cid)
                tname = (tgt.get("custom_name") or NODE_DEFS.get(tgt.get("type"), NodeBase).title) if tgt else str(cid)
                push_toast(f'Paint Bucket detached from "{tname}"', "success", 2.0)
            else:
                push_toast("Paint Bucket detached (was not connected)", "info", 1.5)
            return True
        return False
    return False

def _ns_prompt_group_name(group_id):
    group = _ns_group_by_id(group_id)
    if not group:
        return False
        
    def on_confirm(value):
        value = " ".join(str(value).strip().split())[:64]
        if not value:
            push_toast("Group name cannot be empty.", "warning", 1.8)
            return
        ns_snapshot()
        group["name"] = value
        modal["ns_dirty"] = True
        push_toast(f"Renamed group to {value}", "success", 1.8)
        modal["type"] = "visual_scripter"
        modal["focus"] = None
        
    def on_cancel():
        modal["type"] = "visual_scripter"
        modal["focus"] = None
        
    modal["type"] = "text_input_modal"
    modal["text_input_title"] = "Rename Smart Group"
    modal["text_input_label"] = "Group name:"
    modal["text_input_value"] = str(group.get("name", "Smart Group"))
    modal["focus"] = "text_input_value"
    modal["text_input_callback"] = on_confirm
    modal["text_input_cancel_callback"] = on_cancel
    return True

def _ns_perform_group_action(action_key, group_id):
    group = next((g for g in modal.get("ns_smart_groups", [])
                  if g.get("id") == group_id), None)
    if not group:
        return False
    if action_key == "teach_lesson":
        cluster_id = group.get("lesson_cluster_id")
        cluster = modal.get("ns_nodes", {}).get(cluster_id)
        if not cluster:
            push_toast("This group isn't pinned to a Node Cluster Formation node.", "warning", 3.0)
            return False
        modal["ns_selected"] = cluster_id
        modal["ns_multi_selected"] = set()
        modal["ns_selected_groups"] = {group_id}
        if not str(cluster.get("props", {}).get("idea", "") or "").strip():
            push_toast("Type an idea on the cluster node first, then Teach This Idea.", "warning", 4.0)
            return True
        return teach_cluster_lesson(cluster_id)
    if action_key == "delete_group_contents":
        ns_snapshot()
        nodes_map = modal.setdefault("ns_nodes", {})
        
        # 1. Gather all nodes inside this group and any nested descendant groups recursively
        child_nodes = list(_ns_group_all_node_ids(group))
        all_groups_to_delete = {group_id}
        
        q = [group_id]
        while q:
            curr = q.pop(0)
            curr_g = _ns_group_by_id(curr)
            if curr_g:
                for cid in curr_g.get("child_group_ids", []):
                    if cid not in all_groups_to_delete:
                        all_groups_to_delete.add(cid)
                        q.append(cid)
                        
        # 2. Delete all gathered nodes
        for nid in child_nodes:
            nodes_map.pop(nid, None)
            
        # 3. Delete any broken links connected to these deleted nodes
        old_links = modal.get("ns_links", [])
        modal["ns_links"] = [l for l in old_links if l.get("from") not in child_nodes and l.get("to") not in child_nodes]
        
        # 4. Delete the group boxes themselves
        modal["ns_smart_groups"] = [g for g in modal.get("ns_smart_groups", []) if g.get("id") not in all_groups_to_delete]
        
        # 5. Clean up parent/child group arrays of remaining groups
        for parent in modal.get("ns_smart_groups", []):
            parent["child_group_ids"] = [cid for cid in parent.get("child_group_ids", []) if cid not in all_groups_to_delete]
            
        modal["ns_selected_groups"] = set()
        modal["ns_selected"] = None
        modal["ns_multi_selected"] = set()
        modal["ns_dirty"] = True
        
        push_toast(f"Deleted group '{group.get('name')}' and all {len(child_nodes)} node(s) inside (Press Ctrl+Z to Undo)", "success", 2.5)
        return True

    if action_key == "add_sel_nodes":
        ns_snapshot()
        ids = set(ns_selection_ids())
        nodes_map = modal.get("ns_nodes", {})
        if ids:
            ids = set(_ns_expand_selection_with_fusion(ids, nodes_map))
        # Exclude the cluster node itself
        ids.discard(group.get("lesson_cluster_id"))
        added = 0
        for nid in ids:
            if nid in nodes_map and nid not in group["node_ids"]:
                group["node_ids"].append(nid)
                added += 1
        _ns_sync_smart_group_bounds(group)
        modal["ns_dirty"] = True
        push_toast(f"Added {added} node(s) to group '{group.get('name')}'", "success", 2.2)
        return True
    if action_key == "remove_sel_nodes":
        ns_snapshot()
        ids = set(ns_selection_ids())
        removed = 0
        for nid in ids:
            if nid in group["node_ids"]:
                group["node_ids"].remove(nid)
                removed += 1
        _ns_sync_smart_group_bounds(group)
        modal["ns_dirty"] = True
        push_toast(f"Removed {removed} node(s) from group '{group.get('name')}'", "success", 2.2)
        return True

    if action_key == "save_cluster":
        return ns_save_selection_as_cluster(anchor_group_id=group_id)
    if action_key == "rename_group":
        return _ns_prompt_group_name(group_id)
    if action_key in ("scale_down", "scale_up", "scale_reset"):
        ns_snapshot()
        current = float(group.get("padding_scale", 1.0))
        group["padding_scale"] = (1.0 if action_key == "scale_reset" else
                                    max(0.5, current - 0.2) if action_key == "scale_down" else
                                    min(3.0, current + 0.2))
        _ns_sync_smart_group_bounds(group)
        modal["ns_dirty"] = True
        push_toast(f"Group scale: {group['padding_scale']:.1f}x", "info", 1.5)
        return True
    if action_key == "wrap_group":
        modal.setdefault("ns_selected_groups", set()).add(group_id)
        return _ns_create_smart_group_from_selection(anchor_group_id=group_id)
    if action_key == "duplicate_group":
        return _ns_duplicate_smart_groups({group_id})
    if action_key == "toggle_collapse":
        ns_snapshot()
        group["collapsed"] = not bool(group.get("collapsed", False))
        if group["collapsed"]:
            group["frozen"] = False
        modal["ns_dirty"] = True
        push_toast(("Collapsed " if group["collapsed"] else "Expanded ") +
                   group.get("name", "Smart Group"), "success", 1.5)
        return True
    if action_key == "toggle_freeze":
        ns_snapshot()
        group["frozen"] = not bool(group.get("frozen", False))
        modal["ns_dirty"] = True
        push_toast(("Frozen " if group["frozen"] else "Unfrozen ") +
                   group.get("name", "Smart Group"), "info", 1.5)
        return True
    if action_key == "select_members":
        ids = {nid for nid in group.get("node_ids", []) if nid in modal.get("ns_nodes", {})}
        modal["ns_multi_selected"] = ids
        modal["ns_selected"] = next(iter(ids)) if ids else None
        modal["ns_selected_groups"] = {group_id}
        return True
    if action_key == "focus_group":
        ids = [nid for nid in group.get("node_ids", []) if nid in modal.get("ns_nodes", {})]
        if ids:
            _ns_focus_node_id(ids[0])
        return True
    if action_key == "ungroup":
        ns_snapshot()
        modal["ns_smart_groups"] = [g for g in modal.get("ns_smart_groups", [])
                                    if g.get("id") != group_id]
        for parent in modal.get("ns_smart_groups", []):
            parent["child_group_ids"] = [cid for cid in parent.get("child_group_ids", [])
                                           if cid != group_id]
        modal.setdefault("ns_selected_groups", set()).discard(group_id)
        modal["ns_dirty"] = True
        push_toast(f"Ungrouped '{group.get('name')}' (Press Ctrl+Z to Undo)", "info", 2.4)
        push_toast("Smart Group removed; nodes were kept", "info", 1.8)
        return True
    if action_key == "remove_paint_bucket":
        paint = _ns_group_paint_clip(group_id)
        if paint:
            ns_snapshot()
            props = paint.setdefault("props", {})
            props["target_group_id"] = ""
            props["clamped_to"] = ""
            modal["ns_dirty"] = True
            push_toast(f'Paint Bucket removed from "{group.get("name", "group")}"', "success", 2.0)
            return True
        push_toast("No Paint Bucket attached to this group", "warning", 1.5)
        return False
    return False

def _ns_record_recent_action(action_key):
    recent = modal.setdefault("ns_recent_node_actions", [])
    if action_key in recent:
        recent.remove(action_key)
    recent.insert(0, action_key)
    del recent[6:]

def ns_apply_hex_buffer(pname):
    """Parse the in-progress hex string for `pname` and, if it's a full valid
    hex color, write it into the selected node's props (r/g/b for Constant
    Color, or a single color list for other color properties)."""
    sel = modal.get("ns_nodes", {}).get(modal.get("ns_selected"))
    if not sel:
        return
    buf = modal.get("_ns_hex_buf", {}).get(pname, "")
    hexpart = buf[1:] if buf.startswith("#") else buf
    if len(hexpart) != 6 or not all(c in "0123456789abcdefABCDEF" for c in hexpart):
        return
    r = int(hexpart[0:2], 16); g = int(hexpart[2:4], 16); b = int(hexpart[4:6], 16)
    if pname == "rgb_hex" and sel.get("type") == "utility_constant_color":
        sel.setdefault("props", {})["r"] = r
        sel.setdefault("props", {})["g"] = g
        sel.setdefault("props", {})["b"] = b
    else:
        sel.setdefault("props", {})[pname] = [r, g, b]

def ns_apply_number_buffer(pname):
    sel = modal.get("ns_nodes", {}).get(modal.get("ns_selected"))
    if not sel:
        return False
    cls = NODE_DEFS.get(sel.get("type"))
    spec = cls.properties.get(pname) if cls else None
    text = modal.get("_ns_number_buf", {}).get(pname, "").strip()
    try:
        value = float(text)
    except ValueError:
        return False
    if spec:
        if spec.min is not None:
            value = max(spec.min, value)
        if spec.max is not None:
            value = min(spec.max, value)
        if isinstance(spec.default, int) and not isinstance(spec.default, bool) and value.is_integer():
            value = int(value)
    sel.setdefault("props", {})[pname] = value
    modal["ns_dirty"] = True
    return True

def ns_delete_selected():
    ids = ns_selection_ids()
    selected_groups = modal.get("ns_selected_groups", set())
    if not ids and not selected_groups:
        return
    ns_snapshot()
    if ids:
        for nid in ids:
            modal["ns_nodes"].pop(nid, None)
        # Remove body-dropped Debug Button attachments when their button node is
        # deleted, so a host never keeps a dead control ID.
        for _host in modal.get("ns_nodes", {}).values():
            _old_buttons = _host.get("props", {}).get("_debug_buttons", [])
            if _old_buttons:
                _host["props"]["_debug_buttons"] = [bid for bid in _old_buttons if bid not in ids]
        modal["ns_links"] = [l for l in modal.get("ns_links", []) if l["from"] not in ids and l["to"] not in ids]
        modal["ns_selected"] = None
        modal["ns_multi_selected"] = set()

    if selected_groups:
        try:
            import tkinter as tk
            root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
            group_names = []
            for gid in selected_groups:
                g = next((x for x in modal.get("ns_smart_groups", []) if x.get("id") == gid), None)
                if g:
                    group_names.append(g.get("name", "Smart Group"))
            _names_str = ", ".join(group_names)
            # Bypass lagging messagebox dialogue confirmation completely!
            confirm = True
        except Exception:
            confirm = True
        if confirm:
            ns_snapshot()
            modal["ns_smart_groups"] = [g for g in modal.get("ns_smart_groups", [])
                                        if g.get("id") not in selected_groups]
            for parent in modal.get("ns_smart_groups", []):
                parent["child_group_ids"] = [cid for cid in parent.get("child_group_ids", [])
                                               if cid not in selected_groups]
            push_toast("Smart Group(s) removed; nodes were kept (Press Ctrl+Z to Undo)", "info", 2.4)
            modal["ns_dirty"] = True
        modal["ns_selected_groups"] = set()

def ns_snap_pos(x, y):
    """Snap world-space coordinates to the node grid (NS_GRID)."""
    g = NS_GRID
    return round(x / g) * g, round(y / g) * g

def _ns_node_layout_scale(n):
    """Read the user-facing visual scale for a graph node."""
    try:
        return max(0.45, min(3.5, float(n.get("ui_scale", 1.0))))
    except (TypeError, ValueError):
        return 1.0

def _ns_node_width_stretch(n):
    try:
        return max(0.55, min(3.5, float(n.get("ui_width", 1.0))))
    except (TypeError, ValueError):
        return 1.0

def _ns_node_height_stretch(n):
    try:
        return max(0.55, min(3.5, float(n.get("ui_height", 1.0))))
    except (TypeError, ValueError):
        return 1.0

def _ns_layout_target_nodes(n):
    """Return every host in the selected node's connected clip component."""
    if not n:
        return []
    hosts, clips, ids = _ns_clip_component_nodes(n.get("id"), modal.get("ns_nodes", {}))
    if clips and len(hosts) >= 2 and all(c.get("props", {}).get("_clip_fused") for c in clips if c):
        return hosts
    return [n]

def _ns_set_node_layout(n, key, value):
    """Set a visual size control, keeping both halves of a fused block equal."""
    targets = _ns_layout_target_nodes(n)
    for target in targets:
        target[key] = round(float(value), 2)
    if targets:
        modal["ns_dirty"] = True
        clip = _ns_find_clip_for_node(targets[0].get("id"), modal.get("ns_nodes", {}))
        if clip:
            _ns_layout_clip_group(clip)

def _ns_get_node_world_width(n):
    """Approximate the node's world width for collision-free auto-layout."""
    props = n.get("props", {})
    if props.get("_fuse_cell_w"):
        return float(props["_fuse_cell_w"])
    natural = 340.0 if n.get("type") in ("debug_terminal","debug_raw_value_terminal") else float(NS_NODE_W)
    factor = 0.72 * 0.82 if n.get("ui_mini") else 1.22 * 1.20 if n.get("ui_presentation") else 1.0
    return natural * _ns_node_layout_scale(n) * _ns_node_width_stretch(n) * factor

def _ns_get_node_world_height(n):
    cls = NODE_DEFS.get(n.get("type"), NodeBase)
    _ins, _outs = cls.get_inputs(n), cls.get_outputs(n)
    exec_in_n  = len([p for p in _ins  if p.type == EXEC])
    exec_out_n = len([p for p in _outs if p.type == EXEC])
    data_in_n  = len([p for p in _ins  if p.type != EXEC])
    data_out_n = len([p for p in _outs if p.type != EXEC])
    left_rows  = max(1, exec_in_n) + data_in_n
    right_rows = max(1, exec_out_n) + data_out_n
    rows       = max(left_rows, right_rows)
    factor = 0.72 * 0.66 if n.get("ui_mini") else 1.22 * 1.12 if n.get("ui_presentation") else 1.0
    if n.get("type") in ("debug_terminal","debug_raw_value_terminal"):
        _sock_scale = _ns_node_layout_scale(n)
        hdr_h = max(18.0, 26.0 * _sock_scale)
        term_h = max(80.0, 100.0 * _sock_scale)
        spacing = max(20.0, 15.0 * _sock_scale)
        padding = max(8.0, 12.0 * _sock_scale)
        needed_h = hdr_h + spacing + term_h + padding
        return needed_h * _ns_node_height_stretch(n) * factor
    base_h = 40 + rows * 18 + len(cls.get_properties(n)) * 15
    # Do not read the cached fused cell here: clip relayout uses this value
    # to recompute that cell after a scale/stretch slider changes.
    return base_h * _ns_node_layout_scale(n) * _ns_node_height_stretch(n) * factor

def _ns_build_graph_adj(nodes, links):
    children = {nid: [] for nid in nodes}
    parents  = {nid: [] for nid in nodes}
    for lnk in links:
        f, t = lnk.get("from"), lnk.get("to")
        if f in children and t in children:
            children[f].append(t)
            parents[t].append(f)
    return children, parents

def _ns_topo_columns(nodes, links):
    children, parents = _ns_build_graph_adj(nodes, links)
    col = {}
    queue = [nid for nid in nodes if not parents[nid]]
    if not queue and nodes:
        queue = [next(iter(nodes))]
    for nid in queue:
        col[nid] = 0
    bfs = list(queue)
    visited_bfs = set(queue)
    while bfs:
        nxt = []
        for nid in bfs:
            for cid in children[nid]:
                new_col = col[nid] + 1
                if col.get(cid, -1) < new_col:
                    col[cid] = new_col
                if cid not in visited_bfs:
                    visited_bfs.add(cid)
                    nxt.append(cid)
        bfs = nxt
    for nid in nodes:
        if nid not in col:
            col[nid] = 0
    return col, children, parents

def _ns_place_columns(nodes, columns, col_x_gap=None, row_gap=60, origin_x=0, origin_y=0, center=True):
    if col_x_gap is None:
        col_x_gap = NS_NODE_W + 100
    # Keep enlarged / stretched cards from overlapping the next column.
    widest = max((_ns_get_node_world_width(n) for n in nodes.values()), default=NS_NODE_W)
    col_x_gap = max(float(col_x_gap), widest + 100)
    for c in columns:
        columns[c].sort(key=lambda nid: nodes[nid].get("y", 0))
    for c in sorted(columns):
        group = columns[c]
        heights = [_ns_get_node_world_height(nodes[nid]) for nid in group]
        total_h = sum(heights) + row_gap * max(0, len(group) - 1)
        start_y = origin_y - (total_h // 2 if center else 0)
        cur_y = start_y
        for i, nid in enumerate(group):
            sx, sy = ns_snap_pos(origin_x + c * col_x_gap, cur_y)
            nodes[nid]["x"] = sx
            nodes[nid]["y"] = sy
            cur_y += heights[i] + row_gap

def ns_auto_layout(mode=None):
    """Auto-sort the graph. mode cycles / selects a layout strategy.

    Modes:
      topological  – left→right by exec/data depth (default)
      hierarchical – events as roots, tree layers
      category     – group by node category in rows
      grid         – neat rectangular grid by selection order / id
      compact      – pack connected components tightly
      radial       – place around graph centroid by depth rings
      align_row    – selected (or all) nodes on one horizontal row
      align_col    – selected (or all) nodes on one vertical column
    """
    nodes = modal.get("ns_nodes", {})
    links = modal.get("ns_links", [])
    if not nodes:
        return

    modes = ["topological", "hierarchical", "category", "grid", "compact", "radial", "align_row", "align_col"]
    if mode is None:
        # cycle
        cur = modal.get("ns_sort_mode", "topological")
        try:
            idx = (modes.index(cur) + 1) % len(modes)
        except ValueError:
            idx = 0
        mode = modes[idx]
    modal["ns_sort_mode"] = mode

    ns_snapshot()
    from collections import defaultdict

    sel = list(ns_selection_ids()) if "ns_selection_ids" in dir() else []
    try:
        sel = list(ns_selection_ids())
    except Exception:
        sel = []
    _explicit_sel = list(sel)  # remember whether the user actually selected something
    if not sel:
        sel = list(nodes.keys())

    # Skip pure layout clip markers from placement? still place them via relayout after
    placeable = {nid: n for nid, n in nodes.items() if not _ns_is_layout_clip(n)}
    if _explicit_sel:
        # Shift-selected a subset? Only arrange that subset — everything else
        # on the canvas stays exactly where it is.
        _sel_set = set(_explicit_sel)
        placeable = {nid: n for nid, n in placeable.items() if nid in _sel_set}
        if not placeable:
            push_toast("Nothing placeable in the current selection.", "warning")
            return

    _scope_note = " (selected only)" if _explicit_sel else ""

    if mode == "topological":
        col, _, _ = _ns_topo_columns(placeable, links)
        columns = defaultdict(list)
        for nid, c in col.items():
            columns[c].append(nid)
        _ns_place_columns(nodes, columns)
        push_toast("Sort: Topological (left → right flow)" + _scope_note, "success", 3.5)

    elif mode == "hierarchical":
        # Prefer event nodes as roots
        children, parents = _ns_build_graph_adj(placeable, links)
        roots = [nid for nid, n in placeable.items()
                 if n.get("type", "").startswith("event_") or not parents.get(nid)]
        if not roots:
            roots = [next(iter(placeable))]
        col = {r: 0 for r in roots}
        bfs = list(roots)
        seen = set(roots)
        while bfs:
            nxt = []
            for nid in bfs:
                for cid in children.get(nid, []):
                    col[cid] = max(col.get(cid, 0), col[nid] + 1)
                    if cid not in seen:
                        seen.add(cid)
                        nxt.append(cid)
            bfs = nxt
        for nid in placeable:
            col.setdefault(nid, 0)
        columns = defaultdict(list)
        for nid, c in col.items():
            columns[c].append(nid)
        # within column sort by category then title
        for c in columns:
            columns[c].sort(key=lambda nid: (
                NODE_DEFS.get(placeable[nid].get("type"), NodeBase).category,
                NODE_DEFS.get(placeable[nid].get("type"), NodeBase).title,
            ))
        _ns_place_columns(nodes, columns, col_x_gap=NS_NODE_W + 120, row_gap=70)
        push_toast("Sort: Hierarchical (events → children)" + _scope_note, "success", 3.5)

    elif mode == "category":
        cats = defaultdict(list)
        for nid, n in placeable.items():
            cat = NODE_DEFS.get(n.get("type"), NodeBase).category or "Other"
            cats[cat].append(nid)
        y = 0
        for ci, cat in enumerate(sorted(cats.keys())):
            group = cats[cat]
            group.sort(key=lambda nid: NODE_DEFS.get(placeable[nid].get("type"), NodeBase).title)
            x = 0
            max_h = 0
            for nid in group:
                h = _ns_get_node_world_height(nodes[nid])
                max_h = max(max_h, h)
                sx, sy = ns_snap_pos(x, y)
                nodes[nid]["x"] = sx
                nodes[nid]["y"] = sy
                x += _ns_get_node_world_width(nodes[nid]) + 40
            y += max_h + 80
        push_toast("Sort: By Category (rows)" + _scope_note, "success", 3.5)

    elif mode == "grid":
        ids = sorted(placeable.keys(), key=lambda nid: (nodes[nid].get("y", 0), nodes[nid].get("x", 0)))
        n = max(1, len(ids))
        cols = max(1, int(math.ceil(math.sqrt(n))))
        gap_x = max(NS_NODE_W + 50, max((_ns_get_node_world_width(nodes[nid]) for nid in ids), default=NS_NODE_W) + 50)
        gap_y = max(120, max((_ns_get_node_world_height(nodes[nid]) for nid in ids), default=80) + 40)
        for i, nid in enumerate(ids):
            r, c = divmod(i, cols)
            # wait: i//cols is row, i%cols is col
            row, col = i // cols, i % cols
            h = _ns_get_node_world_height(nodes[nid])
            sx, sy = ns_snap_pos(col * gap_x, row * gap_y)
            nodes[nid]["x"] = sx
            nodes[nid]["y"] = sy
        push_toast("Sort: Grid" + _scope_note, "success", 3.5)

    elif mode == "compact":
        # connected components packed side by side, each topo-sorted
        children, parents = _ns_build_graph_adj(placeable, links)
        seen = set()
        components = []
        for nid in placeable:
            if nid in seen:
                continue
            stack = [nid]
            comp = []
            seen.add(nid)
            while stack:
                cur = stack.pop()
                comp.append(cur)
                for nb in children.get(cur, []) + parents.get(cur, []):
                    if nb not in seen and nb in placeable:
                        seen.add(nb)
                        stack.append(nb)
            components.append(comp)
        cur_x = 0
        for comp in components:
            sub = {nid: placeable[nid] for nid in comp}
            sub_links = [l for l in links if l.get("from") in sub and l.get("to") in sub]
            col, _, _ = _ns_topo_columns(sub, sub_links)
            columns = defaultdict(list)
            for nid, c in col.items():
                columns[c].append(nid)
            # place relative then offset
            _ns_place_columns(nodes, columns, origin_x=cur_x, center=True)
            # measure width
            xs = [nodes[nid]["x"] for nid in comp]
            cur_x = (max(xs) if xs else cur_x) + max((_ns_get_node_world_width(nodes[nid]) for nid in comp), default=NS_NODE_W) + 160
        push_toast("Sort: Compact components" + _scope_note, "success", 3.5)

    elif mode == "radial":
        col, _, _ = _ns_topo_columns(placeable, links)
        rings = defaultdict(list)
        for nid, c in col.items():
            rings[c].append(nid)
        cx, cy = 0, 0
        for depth in sorted(rings):
            group = rings[depth]
            group.sort(key=lambda nid: nodes[nid].get("y", 0))
            radius = 40 + depth * (NS_NODE_W + 70)
            n = len(group)
            for i, nid in enumerate(group):
                ang = (2 * math.pi * i / max(1, n)) - math.pi / 2
                sx, sy = ns_snap_pos(cx + math.cos(ang) * radius, cy + math.sin(ang) * radius)
                nodes[nid]["x"] = sx
                nodes[nid]["y"] = sy
        push_toast("Sort: Radial rings" + _scope_note, "success", 3.5)

    elif mode == "align_row":
        ids = [nid for nid in sel if nid in placeable] or list(placeable.keys())
        ids.sort(key=lambda nid: nodes[nid].get("x", 0))
        # average y
        ay = sum(nodes[nid].get("y", 0) for nid in ids) / max(1, len(ids))
        x = min(nodes[nid].get("x", 0) for nid in ids)
        for nid in ids:
            sx, sy = ns_snap_pos(x, ay)
            nodes[nid]["x"] = sx
            nodes[nid]["y"] = sy
            x += _ns_get_node_world_width(nodes[nid]) + 50
        push_toast("Sort: Align row" + _scope_note, "success", 3.5)

    elif mode == "align_col":
        ids = [nid for nid in sel if nid in placeable] or list(placeable.keys())
        ids.sort(key=lambda nid: nodes[nid].get("y", 0))
        ax = sum(nodes[nid].get("x", 0) for nid in ids) / max(1, len(ids))
        y = min(nodes[nid].get("y", 0) for nid in ids)
        for nid in ids:
            h = _ns_get_node_world_height(nodes[nid])
            sx, sy = ns_snap_pos(ax, y)
            nodes[nid]["x"] = sx
            nodes[nid]["y"] = sy
            y += h + 40
        push_toast("Sort: Align column" + _scope_note, "success", 3.5)

    else:
        push_toast(f"Unknown sort mode: {mode}", "warning")
        return

    # Re-fuse any clip groups after moving hosts
    _ns_relayout_all_clips()

def ns_duplicate_selected():
    # Smart Groups take precedence: Ctrl+D / toolbar Duplicate should duplicate
    # the selected group *and its contents*, not silently duplicate only a
    # leftover node selection from before the group was selected.
    selected_groups = set(modal.get("ns_selected_groups", set()) or set())
    if selected_groups:
        return _ns_duplicate_smart_groups(selected_groups)
    # UPGRADED: allow ALL nodes to be duplicated, including Events (user request)
    # Previously Event nodes were excluded - now we allow them, but still keep one copy of each unique event if needed
    ids = set(ns_selection_ids())
    if not ids:
        return
    # Bring along any fused/clamped partner so a connected pair is never
    # split — duplicating one half used to silently drop the connection.
    ids = _ns_expand_selection_with_fusion(ids, modal["ns_nodes"])
    ns_snapshot()
    id_map = {}
    for old_id in ids:
        nid = modal["ns_next_id"]
        modal["ns_next_id"] += 1
        n = modal["ns_nodes"][old_id]
        new_node = json.loads(json.dumps(n))
        new_node["id"] = nid
        new_node["x"] = n["x"] + 30
        new_node["y"] = n["y"] + 30
        modal["ns_nodes"][nid] = new_node
        id_map[old_id] = nid
    for nid in id_map.values():
        _ns_remap_fusion_refs(modal["ns_nodes"][nid], id_map)
    for l in list(modal["ns_links"]):
        if l["from"] in id_map and l["to"] in id_map:
            modal["ns_links"].append({"from": id_map[l["from"]], "from_pin": l["from_pin"],
                                      "to": id_map[l["to"]], "to_pin": l["to_pin"]})
    modal["ns_multi_selected"] = set(id_map.values())
    modal["ns_selected"] = list(id_map.values())[-1] if id_map else None

def _ns_fresh_smart_group_id(used=None):
    """Create a collision-free persisted Smart Group id."""
    used = set(used or ())
    gid = int(time.time() * 1000) % 100000000
    while gid in used:
        gid = (gid + 1) % 100000000
    return gid

def _ns_duplicate_smart_groups(selected_group_ids, offset=(48.0, 48.0)):
    """Deep-duplicate selected Smart Group roots and everything inside them.

    Membership, nested hierarchy, node positions, internal links, clip/fusion
    refs, debug-button lists, and Paint Bucket `target_group_id` refs all get
    remapped. External links deliberately stay external, matching regular node
    duplicate behavior.
    """
    groups = modal.get("ns_smart_groups", []) or []
    by_id = {g.get("id"): g for g in groups}
    selected = {gid for gid in set(selected_group_ids or ()) if gid in by_id}
    if not selected:
        return False

    # Keep only selected roots. Selecting a parent and its child should yield
    # one copied hierarchy, never two overlapping copies of the child.
    roots = []
    for gid in selected:
        parent = _ns_group_parent(gid)
        has_selected_parent = False
        seen = set()
        while parent and parent.get("id") not in seen:
            seen.add(parent.get("id"))
            if parent.get("id") in selected:
                has_selected_parent = True
                break
            parent = _ns_group_parent(parent.get("id"))
        if not has_selected_parent:
            roots.append(by_id[gid])
    if not roots:
        return False

    ordered_groups, seen_groups = [], set()
    def _collect(group):
        gid = group.get("id")
        if gid in seen_groups:
            return
        seen_groups.add(gid)
        ordered_groups.append(group)
        for child in _ns_group_children(group):
            _collect(child)
    for root in roots:
        _collect(root)

    source_group_ids = {g.get("id") for g in ordered_groups}
    source_node_ids = set()
    for group in roots:
        source_node_ids.update(_ns_group_all_node_ids(group))
    source_node_ids = {nid for nid in source_node_ids if nid in modal.get("ns_nodes", {})}
    if not source_node_ids and not source_group_ids:
        return False

    ns_snapshot()
    nodes = modal["ns_nodes"]
    id_map = {}
    dx, dy = float(offset[0]), float(offset[1])
    for old_id in sorted(source_node_ids):
        nid = modal["ns_next_id"]
        modal["ns_next_id"] += 1
        clone = json.loads(json.dumps(nodes[old_id]))
        clone["id"] = nid
        clone["x"] = float(clone.get("x", 0.0)) + dx
        clone["y"] = float(clone.get("y", 0.0)) + dy
        nodes[nid] = clone
        id_map[old_id] = nid
    for nid in id_map.values():
        _ns_remap_fusion_refs(nodes[nid], id_map)
    for link in list(modal.get("ns_links", [])):
        if link.get("from") in id_map and link.get("to") in id_map:
            modal["ns_links"].append({"from": id_map[link["from"]], "from_pin": link.get("from_pin", ""),
                                      "to": id_map[link["to"]], "to_pin": link.get("to_pin", "")})

    used_gids = {g.get("id") for g in groups}
    group_map = {}
    for original in ordered_groups:
        new_gid = _ns_fresh_smart_group_id(used_gids | set(group_map.values()))
        group_map[original.get("id")] = new_gid

    existing_names = {str(g.get("name", "")).strip().lower() for g in groups}
    clones = []
    for original in ordered_groups:
        clone = json.loads(json.dumps(original))
        old_gid = original.get("id")
        clone["id"] = group_map[old_gid]
        base_name = (str(original.get("name", "Smart Group")).strip() or "Smart Group") + " Copy"
        name = base_name
        suffix = 2
        while name.lower() in existing_names:
            name = f"{base_name} {suffix}"; suffix += 1
        existing_names.add(name.lower())
        clone["name"] = name
        clone["node_ids"] = [id_map[nid] for nid in original.get("node_ids", []) if nid in id_map]
        clone["child_group_ids"] = [group_map[cid] for cid in original.get("child_group_ids", []) if cid in group_map]
        # A duplicate should be immediately usable and visible, even when the
        # original was a frozen/collapsed organizational reference.
        clone["frozen"] = False
        clone["collapsed"] = False
        if original.get("lesson_cluster_id") in id_map:
            clone["lesson_cluster_id"] = id_map[original.get("lesson_cluster_id")]
        elif "lesson_cluster_id" in clone:
            clone["lesson_cluster_id"] = None
        clones.append(clone)

    # Group-targeted Paint Buckets and lesson references are not ordinary node
    # links, so remap them after both maps have been created.
    for nid in id_map.values():
        props = nodes[nid].setdefault("props", {})
        for key in ("target_group_id", "lesson_group_id"):
            old_ref = props.get(key)
            if old_ref in group_map:
                props[key] = group_map[old_ref]
            else:
                try:
                    old_ref_i = int(old_ref)
                    if old_ref_i in group_map:
                        props[key] = group_map[old_ref_i]
                except (TypeError, ValueError):
                    pass

    groups.extend(clones)
    _ns_sync_all_smart_groups()
    new_root_ids = {group_map[g.get("id")] for g in roots}
    modal["ns_selected_groups"] = new_root_ids
    modal["ns_multi_selected"] = set(id_map.values())
    modal["ns_selected"] = next(iter(id_map.values()), None)
    modal["ns_dirty"] = True
    push_toast(f"Duplicated {len(roots)} Smart Group(s), {len(id_map)} node(s) · Ctrl+Z to undo", "success", 2.8)
    return True

def ns_insert_example(ex):
    ns_snapshot()
    id_map = {}
    _base_x, _base_y = 0, 0
    view = modal.get("ns_view", {"pan": [0,0], "zoom": 1.0})
    z = view["zoom"]
    cx, cy = -view["pan"][0]/z + (WIDTH/2 - 100)/z, -view["pan"][1]/z + HEIGHT/2/z
    
    # Calculate offset
    min_x = min([n.get("x", 0) for n in ex["nodes"].values()]) if ex["nodes"] else 0
    min_y = min([n.get("y", 0) for n in ex["nodes"].values()]) if ex["nodes"] else 0
    
    for old_id, n in ex["nodes"].items():
        nid = modal["ns_next_id"]
        modal["ns_next_id"] += 1
        id_map[str(old_id)] = nid
        # Offset to center of screen
        nx = cx + (n.get("x", 0) - min_x)
        ny = cy + (n.get("y", 0) - min_y)
        modal["ns_nodes"][nid] = {
            "id": nid, "type": n["type"], "x": nx, "y": ny, "props": dict(n.get("props", {}))
        }
        
    for l in ex["links"]:
        if str(l["from"]) in id_map and str(l["to"]) in id_map:
            modal["ns_links"].append({
                "from": id_map[str(l["from"])], "from_pin": l["from_pin"],
                "to": id_map[str(l["to"])], "to_pin": l["to_pin"]
            })
            
    modal["ns_multi_selected"] = set(id_map.values())
    modal["ns_selected"] = list(id_map.values())[0] if id_map else None
    modal["ns_dirty"] = True
    push_toast(f"Inserted example '{ex['title']}'", "success")

def ns_open_example_new(ex):
    reset_visual_graph()
    modal["ns_loaded_script"] = None
    modal["script_file"] = None
    modal["ns_save_name"] = "example_" + ex["title"].lower().replace(" ", "_")
    
    id_map = {}
    for old_id, n in ex["nodes"].items():
        nid = modal["ns_next_id"]
        modal["ns_next_id"] += 1
        id_map[str(old_id)] = nid
        modal["ns_nodes"][nid] = {
            "id": nid, "type": n["type"], "x": n.get("x", 0), "y": n.get("y", 0), "props": dict(n.get("props", {}))
        }
        
    for l in ex["links"]:
        if str(l["from"]) in id_map and str(l["to"]) in id_map:
            modal["ns_links"].append({
                "from": id_map[str(l["from"])], "from_pin": l["from_pin"],
                "to": id_map[str(l["to"])], "to_pin": l["to_pin"]
            })
            
    modal["ns_dirty"] = True
    push_toast(f"Opened example '{ex['title']}' as new script.", "success")

def ns_add_node(node_type, world_pos):
    cls = NODE_DEFS.get(node_type)
    if cls is None:
        return None

    # Check if this is a Scene Observer / Director node on a normal character
    is_scene_node = node_type.startswith("event_on_scene_") or (node_type.startswith("scene_") and "Scene" in getattr(cls, "category", ""))
    _editing_tmpl = modal.get("editing")
    is_normal_char = True
    if isinstance(_editing_tmpl, dict) and _editing_tmpl.get("is_scene_prop", False):
        is_normal_char = False
    elif modal.get("is_scene_prop", False):
        is_normal_char = False

    session_dismissed = bool(globals().get("_SESSION_DISMISSED_SCENE_EVENT_WARNING", False) or modal.get("_ns_dismissed_scene_event_warning", False))

    if is_scene_node and is_normal_char and not session_dismissed and modal.get("type") == "visual_scripter":
        modal["_pending_scene_node"] = {"type": node_type, "pos": world_pos}
        modal["type"] = "scene_event_warning_confirm"
        return None
    ns_snapshot()
    nid = modal["ns_next_id"]
    modal["ns_next_id"] += 1
    props = {}
    for k, spec in cls.properties.items():
        props[k] = spec.default
    wx, wy = world_pos[0], world_pos[1]
    # Snap placement to grid when snap is enabled
    if modal.get("ns_snap_enabled", False):
        wx, wy = ns_snap_pos(wx, wy)
    modal["ns_nodes"][nid] = {
        "id": nid, "type": node_type, "x": wx, "y": wy, "props": props,
        "ui_scale": 1.0, "ui_width": 1.0, "ui_height": 1.0,
    }
    modal["ns_selected"] = nid
    modal["ns_multi_selected"] = set()
    return nid

def _cluster_add_raw(node_type, x, y, props=None):
    """Add a graph node without taking one undo snapshot per generated node."""
    cls = NODE_DEFS.get(node_type)
    if cls is None:
        return None
    nid = modal["ns_next_id"]
    modal["ns_next_id"] += 1
    node_props = {name: spec.default for name, spec in cls.properties.items()}
    if props:
        node_props.update(props)
    modal["ns_nodes"][nid] = {
        "id": nid, "type": node_type, "x": float(x), "y": float(y),
        "props": node_props, "ui_scale": 1.0, "ui_width": 1.0, "ui_height": 1.0,
    }
    return nid

def _cluster_link(source_id, source_pin, target_id, target_pin):
    if source_id is None or target_id is None:
        return
    modal["ns_links"].append({
        "from": source_id, "from_pin": source_pin,
        "to": target_id, "to_pin": target_pin,
    })

