# Written-out number words -> digits, used so "an integer of three" or
# "reduce hits by eleven" resolve to real numeric constants.
_CLUSTER_WORD_NUMBERS = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
    "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14, "fifteen": 15,
    "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19, "twenty": 20,
    "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70,
    "eighty": 80, "ninety": 90, "hundred": 100,
}

# Keywords that route a "spawn ..." statement to the right spawn node even
# when the exact node title isn't quoted back verbatim.
_CLUSTER_SPAWN_KEYWORDS = [
    ("pure directional particle", "particle_pure_directional_at"),
    ("pure particle", "particle_pure_spawn_at"),
    ("swarm", "swarm_spawn"),
    ("particle", "vfx_spawn_particle"),
    ("trail", "vfx_spawn_trail"),
    ("explo", "explosive_spawn"),
    ("projectile", "rig_projectile_spawn"),
    ("bullet", "rig_projectile_spawn"),
    ("object", "gameplay_spawn_object"),
    ("item", "gameplay_spawn_object"),
    ("prop", "gameplay_spawn_object"),
    ("character", "gameplay_spawn_library_character"),
    ("enemy", "gameplay_spawn_library_character"),
    ("fighter", "gameplay_spawn_library_character"),
]

def _cluster_word_to_number(text):
    """Convert a written-out number ('three', 'twenty one') to a numeric string, else None."""
    words = re.findall(r"[a-z]+", str(text or "").lower())
    if not words or any(w not in _CLUSTER_WORD_NUMBERS for w in words):
        return None
    total = 0
    for w in words:
        total += _CLUSTER_WORD_NUMBERS[w]
    return str(total)

def _node_recognition_aliases(key, cls=None):
    """Build searchable phrases for every registered node automatically."""
    cls = cls or NODE_DEFS.get(key)
    if cls is None:
        return []
    title = str(getattr(cls, "title", "") or "").lower()
    key_text = str(key or "").replace("_", " ").lower()
    aliases = set(_CLUSTER_RECOGNITION_ALIASES.get(key, []))
    aliases.update(NODE_CUSTOM_TERMINOLOGY.get(str(key), []))
    if title:
        aliases.add(title)
    if key_text:
        aliases.add(key_text)
    # Include meaningful title tokens and category + title so every node has
    # at least several discoverable words even when no hand alias exists.
    words = [w for w in re.findall(r"[a-z0-9]+", title) if len(w) > 2]
    aliases.update(words)
    category = str(getattr(cls, "category", "") or "").lower()
    if category and title:
        aliases.add(f"{category} {title}")
    return sorted(aliases, key=lambda value: (len(value), value))

def node_recognition_catalog():
    """Return every node and its natural-language recognition phrases."""
    return [(key, cls.title, _node_recognition_aliases(key, cls))
            for key, cls in sorted(NODE_DEFS.items(), key=lambda item: (item[1].category, item[1].title))]

def find_node_recognition_matches(query, limit=6):
    """Conservative recognizer: exact/base phrases first, then full-token matches."""
    query=" ".join(str(query or "").strip().lower().replace('_',' ').split());scored=[];qtokens=re.findall(r"[a-z0-9]+",query)
    for key,title,aliases in node_recognition_catalog():
        cls=NODE_DEFS.get(key);title_n=" ".join(str(title).lower().split());key_n=key.replace('_',' ').lower();score=1 if not query else 0
        normalized=[" ".join(str(a).lower().split()) for a in aliases]
        if query:
            if query in (title_n,key_n):score=4000
            for alias in normalized:
                if query==alias:score=max(score,3500+len(alias))
                elif len(alias)>=5 and len(alias.split())>=2 and alias in query:score=max(score,1500+len(alias))
                elif query in alias and len(query)>=4:score=max(score,900+len(query))
                elif alias.startswith(query) and len(query)>=3:score=max(score,850+len(query))
            blob=" ".join([key_n,title_n,str(getattr(cls,'description','') or ''),*normalized])
            covered=sum(1 for token in qtokens if token in blob)
            if qtokens and covered==len(qtokens):score=max(score,700+100*covered)
        if score:scored.append((score,key,title,aliases))
    scored.sort(key=lambda item:(-item[0],item[2].lower()));return scored[:max(1,int(limit))]

_CLUSTER_CONJUNCTIONS = {
    "if", "then", "else", "when", "whenever", "and", "or", "not", "on", "do",
    "to", "by", "of", "a", "an", "the", "is", "are", "than", "each", "at",
    "with", "from", "into", "as", "get", "local", "global", "variable",
}

def _cluster_classify_word(word, blob_cache=[None]):
    """Classify one word for live syntax coloring:
    'conj' (grammar glue), 'value' (number/quoted literal), 'known'
    (matches a recognized node/action keyword), or 'unknown'."""
    core = re.sub(r"[^\w']+", "", word).lower()
    if not core:
        return "conj"
    if core in _CLUSTER_CONJUNCTIONS:
        return "conj"
    if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", core) or core in _CLUSTER_WORD_NUMBERS:
        return "value"
    if (word.startswith('"') or word.startswith("'")):
        return "value"
    if blob_cache[0] is None:
        words = set()
        for key, title, aliases in node_recognition_catalog():
            for alias in aliases:
                words.update(re.findall(r"[a-z0-9]+", str(alias).lower()))
        blob_cache[0] = words
    if core in blob_cache[0] and len(core) > 2:
        return "known"
    return "unknown"

def _cluster_classify_text(text):
    """Split text into (word, category) pairs, preserving separators for display."""
    pieces = re.findall(r"\S+|\s+", str(text or ""))
    result = []
    for piece in pieces:
        if piece.isspace():
            result.append((piece, "conj"))
        else:
            result.append((piece, _cluster_classify_word(piece)))
    return result

def _cluster_unrecognized_node(node_id, text, suggestions=()):
    node = modal.get("ns_nodes", {}).get(node_id)
    if not node:
        return
    suggestion_text = ", ".join(title for _, _, title, _ in suggestions[:3]) or "search the Recognition Helper"
    node.setdefault("props", {})["_cluster_unrecognized"] = True
    node["props"]["_cluster_note"] = f"Unrecognized phrase: {text}. Suggestions: {suggestion_text}"
    node["custom_name"] = "Needs review"
    push_toast(f"I couldn't fully recognize '{str(text)[:70]}'. Try: {suggestion_text}", "warning", 5.0)

def _cluster_clean_token(text):
    text = str(text or "").strip().strip(".,;:!?()[]{}")
    # Unwrap phrasing like "a integer of three" / "an int of 3" / "a number of 5"
    # down to just the value itself before any other cleanup runs.
    wrapped = re.match(
        r"^(?:an?\s+)?(?:number|num|numeric|integer|int|float|decimal)\s+of\s+(.+)$",
        text, flags=re.IGNORECASE)
    if wrapped:
        text = wrapped.group(1).strip()
    text = re.sub(r"^(?:constant|value|literal)\s+", "", text, flags=re.IGNORECASE)
    text = re.sub(r"^(?:an?\s+)?(?:number|num|numeric|integer|int|float|decimal)\s*[:=]?\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+(?:as a number|as number)$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+variable$", "", text, flags=re.IGNORECASE)
    if len(text) >= 2 and text[0] == text[-1] and text[0] in "\"'":
        text = text[1:-1]
    text = text.strip()
    # Written-out numbers ("three", "twenty one") become real digits so they
    # can flow into numeric constants/comparisons.
    word_value = _cluster_word_to_number(text)
    if word_value is not None:
        text = word_value
    return text

def _cluster_constant(token, x, y):
    """Create the most useful constant type for a word/number token."""
    raw = _cluster_clean_token(token)
    low = raw.lower()
    if low in ("true", "false", "on", "off"):
        value = low in ("true", "on")
        return _cluster_add_raw("utility_constant_boolean", x, y, {"value": value}), "value"
    try:
        if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", raw):
            value = float(raw) if "." in raw else int(raw)
            return _cluster_add_raw("utility_constant_number", x, y, {"value": value}), "value"
    except (TypeError, ValueError):
        pass
    return _cluster_add_raw("utility_constant_string", x, y, {"value": raw}), "value"

def _cluster_atomic_condition(expression, x, y):
    """Build one comparison condition and return (node_id, output_pin)."""
    import re as _re_cluster
    expr = str(expression or "").strip().strip(".?!")
    operators = [
        (r"doesn['’]t\s+equal|does\s+not\s+equal|isn['’]t\s+equal\s+to|is\s+not\s+equal\s+to|not\s+equal\s+to|!=", "!="),
        (r"is\s+greater\s+than\s+or\s+equal(?:\s+to)?|greater\s+than\s+or\s+equal(?:\s+to)?|at\s+least|>=", ">="),
        (r"is\s+less\s+than\s+or\s+equal(?:\s+to)?|less\s+than\s+or\s+equal(?:\s+to)?|at\s+most|<=", "<="),
        (r"is\s+greater\s+than|greater\s+than|more\s+than|above", ">"),
        (r"is\s+less\s+than|less\s+than|fewer\s+than|below", "<"),
        (r"contains", "contains"),
        (r"starts\s+with", "starts with"),
        (r"ends\s+with", "ends with"),
        (r"equals|equal\s+to|is\s+equal\s+to|==", "=="),
        (r"\s>\s|>", ">"),
        (r"\s<\s|<", "<"),
        (r"\bis\b|\bare\b", "=="),
    ]
    found = None
    for pattern, operation in operators:
        match = _re_cluster.search(pattern, expr, flags=_re_cluster.IGNORECASE)
        if match:
            found = (match, operation)
            break
    if not found:
        bool_value = expr.lower() in ("true", "yes", "on", "valid", "alive")
        node_id = _cluster_add_raw("utility_constant_boolean", x, y, {"value": bool_value})
        _cluster_unrecognized_node(node_id, expr, find_node_recognition_matches(expr))
        return node_id, "value"
    match, operation = found
    left = expr[:match.start()].strip()
    right = expr[match.end():].strip()
    # Strip conversational glue around operands.
    left = _re_cluster.sub(r"^(?:if|when|whether)\s+", "", left, flags=_re_cluster.IGNORECASE)
    right = _re_cluster.sub(r"^(?:to|than)\s+", "", right, flags=_re_cluster.IGNORECASE)
    left_raw = _cluster_clean_token(left)
    right_raw = _cluster_clean_token(right)
    numeric = bool(_re_cluster.fullmatch(r"[-+]?\d+(?:\.\d+)?", left_raw)) and bool(
        _re_cluster.fullmatch(r"[-+]?\d+(?:\.\d+)?", right_raw))
    compare_type = "condition_compare_number" if numeric else "condition_compare_text"
    left_id, left_pin = _cluster_constant(left_raw, x, y)
    right_id, right_pin = _cluster_constant(right_raw, x, y + 84)
    compare_id = _cluster_add_raw(compare_type, x + 250, y, {"operation": operation})
    _cluster_link(left_id, left_pin, compare_id, "a")
    _cluster_link(right_id, right_pin, compare_id, "b")
    return compare_id, "result"

def _cluster_condition(expression, x, y):
    """Build compound AND/OR/NOT conditions from a plain-language phrase."""
    import re as _re_cluster
    expr = str(expression or "").strip()
    # Split only at conversational boolean operators, preserving comparisons.
    pieces = _re_cluster.split(r"\s+(and|or)\s+", expr, flags=_re_cluster.IGNORECASE)
    if len(pieces) >= 3:
        gate_type = "gate_and" if pieces[1].lower() == "and" else "gate_or"
        left_id, left_pin = _cluster_condition(pieces[0], x, y)
        right_id, right_pin = _cluster_condition(" ".join(pieces[2:]), x, y + 130)
        gate_id = _cluster_add_raw(gate_type, x + 500, y + 55)
        _cluster_link(left_id, left_pin, gate_id, "A")
        _cluster_link(right_id, right_pin, gate_id, "B")
        return gate_id, "Out"
    if expr.lower().startswith("not "):
        source_id, source_pin = _cluster_condition(expr[4:], x, y)
        gate_id = _cluster_add_raw("gate_not", x + 500, y)
        _cluster_link(source_id, source_pin, gate_id, "In")
        return gate_id, "Out"
    return _cluster_atomic_condition(expr, x, y)

def _cluster_extract_if(statement):
    import re as _re_cluster
    text = str(statement or "").strip().strip(".;")
    if not _re_cluster.match(r"^(if|when|whenever)\b", text, flags=_re_cluster.IGNORECASE):
        return None
    rest = _re_cluster.sub(r"^(if|when|whenever)\s+", "", text, count=1, flags=_re_cluster.IGNORECASE)
    false_text = ""
    else_match = _re_cluster.search(r"\s+else\s+", rest, flags=_re_cluster.IGNORECASE)
    if else_match:
        false_text = rest[else_match.end():].strip()
        rest = rest[:else_match.start()].strip()
    then_match = _re_cluster.search(r"\s+(?:then|do)\s+", rest, flags=_re_cluster.IGNORECASE)
    if then_match:
        condition = rest[:then_match.start()].strip()
        true_text = rest[then_match.end():].strip()
        return condition, true_text, false_text
    # Also understand: "if A does not equal B print this" without the word then.
    action_match = _re_cluster.search(
        r"\b(print|log|say|output|damage|deal\s+damage|heal|set|get|increment|decrement|reduce|lower|"
        r"decrease|drop|increase|raise|boost|toggle|spawn|summon|release|despawn|play|enable|disable)\b",
        rest, flags=_re_cluster.IGNORECASE)
    if action_match:
        return rest[:action_match.start()].strip(), rest[action_match.start():].strip(), false_text
    return rest, "", false_text

def _cluster_props_from_text(node_key,text):
    cls=NODE_DEFS.get(node_key);props={};low=str(text).lower()
    if not cls:return props
    patterns={"damage":r"damage\s*(?:=|of|to)?\s*([-+]?\d+(?:\.\d+)?)","speed":r"speed\s*(?:=|of|to)?\s*([-+]?\d+(?:\.\d+)?)","radius":r"radius\s*(?:=|of|to)?\s*([-+]?\d+(?:\.\d+)?)","duration":r"(?:duration|for)\s*(?:=|of|to)?\s*([-+]?\d+(?:\.\d+)?)","angle":r"angle\s*(?:=|of|to)?\s*([-+]?\d+(?:\.\d+)?)","distance":r"distance\s*(?:=|of|to)?\s*([-+]?\d+(?:\.\d+)?)","x":r"\bx\s*(?:=|to)?\s*([-+]?\d+(?:\.\d+)?)","y":r"\by\s*(?:=|to)?\s*([-+]?\d+(?:\.\d+)?)"}
    for name,pattern in patterns.items():
        if name in cls.properties:
            m=re.search(pattern,low)
            if m:
                value=float(m.group(1));props[name]=int(value) if value.is_integer() else value
    for name in ("tag","name","anchor","layer","sprite","animation"):
        if name not in cls.properties:continue
        quoted=re.search(rf"{name}\s*(?:=|as|to)?\s*[\"']([^\"']+)[\"']",text,re.I)
        plain=re.search(rf"{name}\s*(?:=|as|to)\s*([a-zA-Z0-9_ -]+?)(?=\s+(?:speed|damage|radius|duration|angle|distance|x|y)\b|$)",text,re.I)
        if quoted:props[name]=quoted.group(1).strip()
        elif plain:props[name]=plain.group(1).strip()
    if "afterimage" in cls.properties and ("afterimage" in low or "ghost" in low):props["afterimage"]=True
    return props

def _cluster_lesson_entry_node(generated_ids):
    """Pick the node in a just-instantiated taught subgraph that should be
    wired to the incoming exec flow: the one with an exec input that has no
    incoming link from another node in the same subgraph."""
    id_set = set(generated_ids)
    has_incoming = {nid: False for nid in generated_ids}
    for l in modal.get("ns_links", []):
        if l["to"] in id_set and l["from"] in id_set:
            has_incoming[l["to"]] = True
    for nid in generated_ids:
        n = modal.get("ns_nodes", {}).get(nid)
        cls = NODE_DEFS.get(n.get("type")) if n else None
        if cls and any(p.type == EXEC for p in cls.inputs) and not has_incoming[nid]:
            return nid
    return None

def _cluster_action(statement, x, y):
    """Build a practical action node, or a visible Comment for unknown text."""
    import re as _re_cluster
    text = str(statement or "").strip().strip(".;")
    low = text.lower()
    if not text:
        return _cluster_add_raw("utility_comment", x, y, {"text": "No action specified"})
    # Taught clause-level lessons take priority over the generic pattern
    # rules below — if you corrected this exact kind of phrase before, reuse
    # that correction instead of guessing again.
    _clause_hits = find_similar_cluster_lessons(text, limit=1, max_tokens=10)
    if _clause_hits and _clause_hits[0][0] >= 0.6:
        _score, _lesson = _clause_hits[0]
        _generated = _cluster_apply_lesson(_lesson, x, y)
        if _generated:
            return _cluster_lesson_entry_node(_generated) or _generated[0]
    print_match = _re_cluster.match(r"(?:print|log|say|output)\s*(.*)", text, flags=_re_cluster.IGNORECASE)
    if print_match:
        message = print_match.group(1).strip() or "Triggered"
        message = _re_cluster.sub(r"^(?:that|this|message)\s+", "", message, flags=_re_cluster.IGNORECASE)
        return _cluster_add_raw("utility_print", x, y, {"message": message, "show_on_screen": True})
    if "deal damage" in low or low.startswith("damage"):
        amount_match = _re_cluster.search(r"[-+]?\d+(?:\.\d+)?", text)
        amount = float(amount_match.group()) if amount_match else 10
        return _cluster_add_raw("gameplay_deal_damage", x, y, {"amount": amount})
    if low.startswith("heal") or " heal " in low:
        amount_match = _re_cluster.search(r"[-+]?\d+(?:\.\d+)?", text)
        amount = float(amount_match.group()) if amount_match else 10
        return _cluster_add_raw("gameplay_heal", x, y, {"amount": amount})
    # "get (local/global) variable X" is a declaration, not a flow action —
    # surface it as a floating Get Variable node instead of a red comment.
    get_match = _re_cluster.match(
        r"(?:get|read|load)\s+(?:the\s+)?(?:local\s+|global\s+)?variable\s+([\w ]+)$",
        text, flags=_re_cluster.IGNORECASE)
    if get_match:
        name = _cluster_clean_token(get_match.group(1)).replace(" ", "_")
        return _cluster_add_raw("variable_get", x, y, {"name": name})
    var_match = _re_cluster.match(r"set\s+(?:variable\s+)?([\w ]+?)\s+(?:to|=)\s+(.+)", text, flags=_re_cluster.IGNORECASE)
    if var_match:
        name = _cluster_clean_token(var_match.group(1)).replace(" ", "_")
        raw_value = _cluster_clean_token(var_match.group(2))
        value_id, value_pin = _cluster_constant(raw_value, x - 230, y + 75)
        value_type = "number" if _re_cluster.fullmatch(r"[-+]?\d+(?:\.\d+)?", raw_value) else "string"
        node_id = _cluster_add_raw("variable_set", x, y, {"name": name, "type": value_type})
        _cluster_link(value_id, value_pin, node_id, "value")
        return node_id
    # Increment/decrement, plus everyday synonyms: reduce/lower/decrease/drop
    # all mean decrement; increase/raise/boost/add-to all mean increment.
    inc_match = _re_cluster.match(
        r"(increment|decrement|reduce|lower|decrease|drop|increase|raise|boost)\s+(?:the\s+)?([\w ]+?)"
        r"(?:\s+by\s+(.+?))?$",
        text, flags=_re_cluster.IGNORECASE)
    if inc_match:
        verb = inc_match.group(1).lower()
        action = "variable_increment" if verb in ("increment", "increase", "raise", "boost") else "variable_decrement"
        name = _cluster_clean_token(inc_match.group(2)).replace(" ", "_")
        amount_raw = _cluster_clean_token(inc_match.group(3)) if inc_match.group(3) else "1"
        amount_match = _re_cluster.fullmatch(r"[-+]?\d+(?:\.\d+)?", amount_raw)
        amount = float(amount_match.group()) if amount_match else 1
        return _cluster_add_raw(action, x, y, {"name": name, "amount": amount})
    # "spawn <thing>" routes to whichever spawn node best matches the noun.
    if low.startswith("spawn") or low.startswith("summon") or low.startswith("release"):
        for keyword, node_key in _CLUSTER_SPAWN_KEYWORDS:
            if keyword in low and node_key in NODE_DEFS:
                return _cluster_add_raw(node_key, x, y, _cluster_props_from_text(node_key, text))
    if "toggle auto-pan" in low or "toggle autopan" in low:
        return _cluster_add_raw("debug_button", x, y, {"label": "Toggle Auto Pan", "action": "Toggle Auto-Pan Camera"})
    if low.startswith("toggle"):
        return _cluster_add_raw("variable_toggle", x, y, {"name": text[6:].strip().replace(" ", "_") or "my_flag"})

    # If the phrase contains an exact known node alias, place that node as a
    # suggested starting point but mark it for review. Otherwise place a red
    # blinking Comment node so no part of the request disappears silently.
    matches=find_node_recognition_matches(text,limit=12)
    chosen=next((m for m in matches if m[0]>=1000 and any(p.type==EXEC for p in NODE_DEFS.get(m[1],NodeBase).inputs)),None)
    if chosen:
        score,suggested_key,_,_=chosen;suggested_id=_cluster_add_raw(suggested_key,x,y,_cluster_props_from_text(suggested_key,text))
        if score<1400:_cluster_unrecognized_node(suggested_id,text,matches)
        return suggested_id
    comment_id = _cluster_add_raw("utility_comment", x, y, {"text": f"UNRECOGNIZED: {text}"})
    _cluster_unrecognized_node(comment_id, text, matches)
    return comment_id

# Ordered so more specific phrases (e.g. "each hit") are checked before the
# generic ones. Each entry: (regex for the trigger phrase, event node type).
_CLUSTER_EVENT_TRIGGERS = [
    (r"on\s+(?:each\s+)?spawn|when\s+spawned|at\s+spawn|on\s+start", "event_on_spawn"),
    (r"on\s+(?:my\s+)?projectile\s+hit|when\s+(?:my\s+)?(?:projectile|bullet|grenade)\s+hits", "event_on_projectile_hit_character"),
    (r"on\s+(?:being\s+)?hit\s+by\s+(?:a\s+)?(?:projectile|bullet|grenade)", "event_on_hit_by_projectile"),
    (r"on\s+(?:each\s+)?tick|every\s+frame|on\s+update", "event_on_tick"),
    (r"on\s+(?:each\s+)?hit(?!\s+point)|when\s+hit|on\s+being\s+hit", "event_on_hit"),
    (r"on\s+critical\s+hit|on\s+crit", "event_on_critical_hit"),
    (r"on\s+damage(?:\s+taken)?|when\s+damaged|on\s+taking\s+damage", "event_on_damage_taken"),
    (r"on\s+(?:dealing\s+)?damage\s+dealt|on\s+dealing\s+damage", "event_on_damage_dealt"),
    (r"on\s+kill|when\s+killed\s+(?:an\s+)?(?:enemy|target)", "event_on_kill"),
    (r"on\s+death|when\s+(?:it\s+)?dies|on\s+dying", "event_on_death"),
    (r"on\s+heal(?:ed)?|when\s+healed", "event_on_heal"),
    (r"on\s+collision|when\s+colliding|on\s+collide", "event_on_collision"),
]

def _cluster_extract_trigger(text):
    """If `text` starts with an 'on X' style trigger phrase, split it off and
    return (event_node_type, remaining_text); else (None, text)."""
    stripped = str(text or "").strip()
    for pattern, event_type in _CLUSTER_EVENT_TRIGGERS:
        m = re.match(r"^(?:" + pattern + r")\s*(?:then|do|:|,)?\s*", stripped, flags=re.IGNORECASE)
        if m and event_type in NODE_DEFS:
            return event_type, stripped[m.end():].strip()
    return None, stripped

def _cluster_idea_tokens(text):
    return set(w for w in re.findall(r"[a-z0-9]+", str(text or "").lower()) if len(w) > 1)

def _cluster_lesson_similarity(tokens_a, tokens_b):
    if not tokens_a or not tokens_b:
        return 0.0
    inter = len(tokens_a & tokens_b)
    union = len(tokens_a | tokens_b)
    return inter / union if union else 0.0

def find_similar_cluster_lessons(idea_text, limit=5, max_tokens=None):
    """Return [(score, lesson_dict), ...] sorted best-first.
    max_tokens restricts to lessons taught from short (single-clause) ideas,
    so a whole multi-step lesson doesn't get misapplied to one small phrase."""
    q_tokens = _cluster_idea_tokens(idea_text)
    scored = []
    for lesson in NODE_CLUSTER_LESSONS:
        l_tokens = set(lesson.get("tokens", []))
        if max_tokens is not None and len(l_tokens) > max_tokens:
            continue
        score = _cluster_lesson_similarity(q_tokens, l_tokens)
        if score > 0:
            scored.append((score, lesson))
    scored.sort(key=lambda item: -item[0])
    return scored[:max(1, int(limit))]

def _cluster_capture_subgraph(node_ids):
    """Serialize a set of graph nodes + the links between them, positions
    made relative to their own bounding box so the lesson can be replayed
    anywhere later."""
    nodes = modal.get("ns_nodes", {})
    ids = [nid for nid in node_ids if nid in nodes]
    if not ids:
        return None
    min_x = min(float(nodes[nid].get("x", 0)) for nid in ids)
    min_y = min(float(nodes[nid].get("y", 0)) for nid in ids)
    saved_nodes = []
    for nid in ids:
        n = nodes[nid]
        saved_nodes.append({
            "ref": nid, "type": n.get("type"),
            "x": float(n.get("x", 0)) - min_x, "y": float(n.get("y", 0)) - min_y,
            "props": dict(n.get("props", {})),
        })
    id_set = set(ids)
    saved_links = [
        {"from": l["from"], "from_pin": l["from_pin"], "to": l["to"], "to_pin": l["to_pin"]}
        for l in modal.get("ns_links", [])
        if l["from"] in id_set and l["to"] in id_set
    ]
    return {"nodes": saved_nodes, "links": saved_links}

def make_empty_lesson_group(world_x=0.0, world_y=0.0):
    """Create a brand-new, empty Lesson Group at a canvas position, with
    no nodes required up front. Nodes can be dragged into it afterward
    (or built inside it), then a Node Cluster Formation node can be
    pinned to it just like a selection-built group."""
    existing_groups = modal.get("ns_smart_groups", [])
    used_ids = {g.get("id") for g in existing_groups}
    gid = int(time.time() * 1000) % 100000000
    while gid in used_ids:
        gid = (gid + 1) % 100000000
    group = {
        "id": gid,
        "name": "Lesson Group",
        "node_ids": [],
        "child_group_ids": [],
        "collapsed": False,
        "frozen": False,
        "color": [255, 190, 80],
        "icon": "folder",
        "description": "Pin a Node Cluster Formation node to this group to teach lessons from it.",
        "tags": ["lesson"],
        "padding_scale": 1.0,
        "x": float(world_x) - 130.0, "y": float(world_y) - 80.0, "w": 260, "h": 160,
        "kind": "lesson",
        "lesson_cluster_id": None,
    }
    existing_groups.append(group)
    modal["ns_selected_groups"] = {gid}
    modal["ns_dirty"] = True
    push_toast("Empty Lesson Group created · drag nodes into it, then pin a Node Cluster Formation node to it.", "success", 4.0)
    return group

def _ns_cluster_lesson_group(cluster_node_id):
    """The Lesson Group linked to this cluster node, if any."""
    cluster = modal.get("ns_nodes", {}).get(cluster_node_id)
    if not cluster:
        return None
    gid = cluster.get("props", {}).get("lesson_group_id")
    if gid in (None, ""):
        return None
    group = _ns_group_by_id(gid)
    return group if group and group.get("kind") == "lesson" else None

def list_available_lesson_groups(exclude_cluster_id=None):
    """Lesson Groups on the canvas that aren't already pinned by another
    cluster node, or are pinned to this one. Returns a list of
    (group_id, group_dict) tuples so the inspector dropdown can show
    them in a stable order."""
    out = []
    for g in modal.get("ns_smart_groups", []):
        if g.get("kind") != "lesson":
            continue
        pinned_to = g.get("lesson_cluster_id")
        if pinned_to not in (None, "", exclude_cluster_id):
            continue
        out.append((g.get("id"), g))
    out.sort(key=lambda kv: (kv[1].get("name") or "").lower())
    return out

def pin_cluster_to_lesson_group(cluster_node_id, group_id):
    """Attach the cluster node to a Lesson Group. The pin is stored on
    the cluster as props.lesson_group_id, and the group remembers which
    cluster node owns it (lesson_cluster_id) so a second cluster can't
    grab it by accident."""
    cluster = modal.get("ns_nodes", {}).get(cluster_node_id)
    if not cluster:
        return False
    if group_id in (None, ""):
        # Unpin.
        prev = _ns_cluster_lesson_group(cluster_node_id)
        if prev:
            prev["lesson_cluster_id"] = None
        cluster.setdefault("props", {})["lesson_group_id"] = ""
        modal["ns_dirty"] = True
        push_toast("Unpinned from the lesson group.", "info", 2.0)
        return True
    target = _ns_group_by_id(group_id)
    if not target or target.get("kind") != "lesson":
        push_toast("That's not a Lesson Group.", "warning", 2.5)
        return False
    # Steal ownership: if another cluster had this group pinned, clear it.
    prev_pinner = target.get("lesson_cluster_id")
    if prev_pinner and prev_pinner != cluster_node_id:
        prev_cluster = modal.get("ns_nodes", {}).get(prev_pinner)
        if prev_cluster and prev_cluster.get("props", {}).get("lesson_group_id") == group_id:
            prev_cluster["props"]["lesson_group_id"] = ""
    # Detach from any previous group this cluster was pinned to.
    prev = _ns_cluster_lesson_group(cluster_node_id)
    if prev and prev.get("id") != group_id:
        prev["lesson_cluster_id"] = None
    cluster.setdefault("props", {})["lesson_group_id"] = group_id
    target["lesson_cluster_id"] = cluster_node_id
    modal["ns_dirty"] = True
    member_count = len(_ns_group_all_node_ids(target))
    push_toast(f"Pinned to '{target.get('name', 'Lesson Group')}' · {member_count} node(s). "
               f"Type an idea and hit Teach This Idea to save it as a lesson.", "success", 3.5)
    return True

def unpin_cluster_lesson_group(cluster_node_id):
    return pin_cluster_to_lesson_group(cluster_node_id, "")

def teach_cluster_lesson(cluster_node_id):
    """Save the user's manually-corrected graph as a lesson tied to the
    current idea text, so future similar ideas can reuse it directly.

    Nodes come from this cluster's pinned Lesson Group. The cluster node
    can ONLY be connected to a lesson group via its pin -- if no group
    is pinned, teach is blocked and the user is told to pin or build
    one (the latter is done from the Node Docker right-click menu)."""
    global NODE_CLUSTER_LESSONS
    cluster = modal.get("ns_nodes", {}).get(cluster_node_id)
    if not cluster:
        return False
    idea = str(cluster.get("props", {}).get("idea", "") or "").strip()
    if not idea:
        push_toast("Type an idea before teaching a lesson for it.", "warning", 3.0)
        return False
    lesson_group = _ns_cluster_lesson_group(cluster_node_id)
    if not lesson_group:
        push_toast("Pin a Lesson Group to this node first (Node Docker → Make Lesson Group).", "warning", 4.5)
        return False
    node_ids = _ns_group_all_node_ids(lesson_group)
    node_ids.discard(cluster_node_id)
    if not node_ids:
        push_toast("That Lesson Group is empty -- add nodes to it before teaching.", "warning", 4.0)
        return False
    subgraph = _cluster_capture_subgraph(node_ids)
    if not subgraph or not subgraph["nodes"]:
        push_toast("Nothing to teach — the lesson group was empty.", "warning", 3.0)
        return False
    tokens = sorted(_cluster_idea_tokens(idea))
    editing_id = cluster.get("props", {}).get("_editing_lesson_id")
    existing = cluster_lesson_by_id(editing_id) if editing_id else None
    if not existing:
        existing = next((l for l in NODE_CLUSTER_LESSONS
                          if l.get("idea", "").strip().lower() == idea.lower()), None)
    lesson_id = existing.get("id") if existing else hashlib.sha1(f"{idea}{time.time()}".encode()).hexdigest()[:12]
    lesson_name = existing.get("name") if existing else idea[:60]
    lesson = {"id": lesson_id, "name": lesson_name, "idea": idea, "tokens": tokens,
              "nodes": subgraph["nodes"], "links": subgraph["links"], "ts": time.time()}
    NODE_CLUSTER_LESSONS = [l for l in NODE_CLUSTER_LESSONS if l.get("id") != lesson_id]
    NODE_CLUSTER_LESSONS.append(lesson)
    save_node_cluster_lessons()
    cluster.setdefault("props", {})["_editing_lesson_id"] = lesson_id
    push_toast(f"Learned this idea from {len(node_ids)} node(s). I'll reuse it for similar ideas.", "success", 5.0)
    return True

def edit_cluster_lesson_on_canvas(cluster_node_id, lesson_id):
    """Bring a previously-taught lesson's nodes back onto the canvas next
    to the cluster node, re-linked to a fresh Lesson Group, so editing and
    re-teaching updates the same lesson instead of creating a duplicate."""
    cluster = modal.get("ns_nodes", {}).get(cluster_node_id)
    lesson = cluster_lesson_by_id(lesson_id)
    if not cluster or not lesson:
        return False
    base_x = float(cluster.get("x", 0)) + 260
    base_y = float(cluster.get("y", 0))
    generated = _cluster_apply_lesson(lesson, base_x, base_y)
    if not generated:
        push_toast("This lesson has no nodes to edit.", "warning", 3.0)
        return False
    # Detach whatever Lesson Group this cluster was previously pinned to --
    # otherwise it's left behind still marked as claimed by this cluster
    # (lesson_cluster_id set) with nothing actually pointing back at it,
    # so it can never be pinned again by anyone.
    _prev_group = _ns_cluster_lesson_group(cluster_node_id)
    if _prev_group:
        _prev_group["lesson_cluster_id"] = None
    existing_groups = modal.get("ns_smart_groups", [])
    gid = int(time.time() * 1000) % 100000000
    used = {g.get("id") for g in existing_groups}
    while gid in used:
        gid = (gid + 1) % 100000000
    group = {
        "id": gid, "name": f"Lesson: {lesson.get('name', 'Untitled')[:32]}", "node_ids": sorted(generated),
        "child_group_ids": [], "collapsed": False, "frozen": False,
        "color": [255, 190, 80], "icon": "folder", "description": "",
        "tags": ["lesson"], "padding_scale": 1.0, "x": 0, "y": 0, "w": 260, "h": 160,
        "kind": "lesson", "lesson_cluster_id": cluster_node_id,
    }
    existing_groups.append(group)
    _ns_sync_smart_group_bounds(group)
    cluster.setdefault("props", {})["lesson_group_id"] = gid
    cluster["props"]["_editing_lesson_id"] = lesson_id
    cluster["props"]["idea"] = lesson.get("idea", cluster["props"].get("idea", ""))
    modal["ns_selected_groups"] = {gid}
    modal["ns_multi_selected"] = set(generated)
    modal["ns_selected"] = cluster_node_id
    modal["ns_dirty"] = True
    push_toast(f"Lesson '{lesson.get('name','Untitled')}' loaded for editing · {len(generated)} node(s).",
               "info", 3.5)
    return True

def _cluster_apply_lesson(lesson, base_x, base_y):
    """Instantiate a taught lesson's nodes/links at the given anchor point.
    Returns the list of newly created node ids."""
    id_map = {}
    generated = []
    for saved in lesson.get("nodes", []):
        node_type = saved.get("type")
        if node_type not in NODE_DEFS:
            continue
        nid = _cluster_add_raw(node_type, base_x + saved.get("x", 0), base_y + saved.get("y", 0),
                                dict(saved.get("props", {})))
        if nid is not None:
            id_map[saved.get("ref")] = nid
            generated.append(nid)
    for link in lesson.get("links", []):
        src, dst = id_map.get(link.get("from")), id_map.get(link.get("to"))
        if src is not None and dst is not None:
            _cluster_link(src, link.get("from_pin", ""), dst, link.get("to_pin", ""))
    return generated

_CLUSTER_IDEA_TEMPLATES = [
    ("Damage on hit", "on hit deal 10 damage, if target health is 0 then despawn"),
    ("Cooldown timer", "on spawn set cooldown to 0, on tick increment cooldown by 1, if cooldown is greater than 60 then set cooldown to 0"),
    ("Hit counter to swarm", "on spawn set hits taken to 0, on each hit increment hits taken by 1, if hits taken is 5 then spawn swarm"),
    ("Heal over time", "on tick if health is less than 100 then heal 2"),
    ("Toggle shield on hit", "on hit toggle shield_active"),
    ("Print debug on spawn", "on spawn print hello world"),
]

def build_node_cluster_from_idea(cluster_node_id):
    """Turn the formation node's idea into an editable, best-effort graph.

    This is deliberately a mockup generator rather than a hidden code model:
    every recognized phrase becomes ordinary graph nodes/wires, and anything
    not recognized remains visible as a Comment node for manual completion.
    """
    cluster = modal.get("ns_nodes", {}).get(cluster_node_id)
    if not cluster:
        return False
    idea = str(cluster.get("props", {}).get("idea", "") or "").strip()
    if not idea:
        push_toast("Type an idea into Node Cluster Formation first.", "warning", 3.0)
        return False
    import re as _re_cluster
    ns_snapshot()
    base_x = float(cluster.get("x", 0))
    base_y = float(cluster.get("y", 0)) + 220

    # If a taught lesson closely matches this idea, replay it directly —
    # it's a real human-corrected example, so it takes priority over the
    # generic keyword parser below.
    best = find_similar_cluster_lessons(idea, limit=1)
    if best and best[0][0] >= 0.72:
        score, lesson = best[0]
        generated = _cluster_apply_lesson(lesson, base_x, base_y)
        if generated:
            modal["ns_selected"] = cluster_node_id
            modal["ns_multi_selected"] = set(generated)
            modal["ns_dirty"] = True
            modal["ns_right_tab"] = "issues"
            push_toast(f"Built from a taught example ({int(score * 100)}% match). Review and adjust.",
                       "success", 5.0)
            return True

    # Split on statement separators: semicolons, newlines, commas, and
    # "then"/"and then" — but never split inside an "if ... then ..." clause,
    # since that "then" belongs to the conditional, not to sequencing.
    _raw_statements = [part.strip() for part in _re_cluster.split(r"[;\n,]+", idea) if part.strip()]
    statements = []
    for part in _raw_statements:
        # A trailing conditional embedded mid-sentence, e.g. "reduce hits by
        # 11 if hits is 0 then spawn swarm" — split the lead-in action off
        # from the "if ... then ..." clause so both parse correctly.
        mid_if = _re_cluster.match(
            r"^(?!\s*(?:if|when|whenever)\b)(?P<pre>.+?)\s+\bif\b\s+(?P<rest>.+\bthen\b.+)$",
            part, flags=_re_cluster.IGNORECASE)
        if mid_if:
            statements.append(mid_if.group("pre").strip())
            statements.append(("if " + mid_if.group("rest")).strip())
        elif _re_cluster.match(r"^(if|when|whenever)\b", part, flags=_re_cluster.IGNORECASE):
            statements.append(part)
        else:
            statements.extend(
                x.strip() for x in _re_cluster.split(r"\s+then\s+|\s+and then\s+", part, flags=_re_cluster.IGNORECASE)
                if x.strip())
    if not statements:
        statements = [idea]

    # Route each statement to the right event trigger. Any statement that
    # opens with an "on X" / "when X" phrase starts a fresh event chain;
    # everything else continues under whichever trigger came before it
    # (defaulting to On Spawn if the idea never names one).
    event_nodes = {}   # event_type -> node id, reused if the same trigger repeats
    generated = []

    def _event_root(event_type, col):
        if event_type not in event_nodes:
            ev_y = base_y + len(event_nodes) * 40
            ev_id = _cluster_add_raw(event_type, base_x, ev_y)
            event_nodes[event_type] = ev_id
            generated.append(ev_id)
        return event_nodes[event_type]

    current_event_type = "event_on_spawn"
    flow_sources = [(_event_root(current_event_type, 0), "")]
    row_index = 0
    for statement in statements:
        trigger_type, remainder = _cluster_extract_trigger(statement)
        if trigger_type:
            current_event_type = trigger_type
            flow_sources = [(_event_root(current_event_type, 0), "")]
            statement = remainder
        if not statement:
            continue
        row_index += 1
        row_y = base_y + row_index * 260
        parsed_if = _cluster_extract_if(statement)
        if parsed_if:
            condition_text, true_text, false_text = parsed_if
            cond_id, cond_pin = _cluster_condition(condition_text, base_x + 30, row_y + 20)
            branch_id = _cluster_add_raw("condition_branch", base_x + 560, row_y + 30)
            generated.extend([cond_id, branch_id])
            _cluster_link(cond_id, cond_pin, branch_id, "condition")
            for source_id, source_pin in flow_sources:
                _cluster_link(source_id, source_pin, branch_id, "")
            true_id = _cluster_action(true_text or "TODO: true branch", base_x + 850, row_y)
            false_id = _cluster_action(false_text or "TODO: false branch", base_x + 850, row_y + 120)
            generated.extend([true_id, false_id])
            _cluster_link(branch_id, "true", true_id, "")
            _cluster_link(branch_id, "false", false_id, "")
            flow_sources = [(true_id, ""), (false_id, "")]
        else:
            action_id = _cluster_action(statement, base_x + 560, row_y)
            generated.append(action_id)
            # variable_get is a pure/data node (no exec pins) — it's a
            # declaration, so don't wire it into the exec chain.
            cls = NODE_DEFS.get(modal.get("ns_nodes", {}).get(action_id, {}).get("type"))
            has_exec_in = cls and any(p.type == EXEC for p in cls.inputs)
            if has_exec_in:
                for source_id, source_pin in flow_sources:
                    _cluster_link(source_id, source_pin, action_id, "")
                flow_sources = [(action_id, "")]
            # else: leave flow_sources pointing at the previous exec node.
    modal["ns_selected"] = cluster_node_id
    modal["ns_multi_selected"] = set(generated)
    modal["ns_dirty"] = True
    modal["ns_right_tab"] = "issues"
    push_toast(f"Built an editable mockup cluster with {len(generated)} node(s). Review and adjust it.", "success", 5.0)
    return True

# ── Node editor performance/index systems ────────────────────────────────────
_NS_NODE_LIBRARY_CACHE = {"sig": None, "categories": [], "rows": [], "tokens": {}}
_NS_DIAGNOSTIC_CACHE = {"sig": None, "issues": []}
_NS_GRAPH_STATS_CACHE = {"sig": None, "stats": {}}
_NS_WIRE_PATH_CACHE = {}          # rounded endpoint/style/lod -> point list
_NS_TEXT_LAYOUT_CACHE = {}         # future text layout cache hook
_NS_MAX_WIRE_CACHE = 50000

def _ns_lod_level(zoom, stats=None):
    """Return tiny/far/medium/full based on zoom and graph scale."""
    stats = stats or {}
    n = int(stats.get("nodes", 0) or 0)
    l = int(stats.get("links", 0) or 0)
    pressure = (1 if n > 1500 or l > 4000 else 0) + (1 if n > 5000 or l > 15000 else 0)
    z = float(zoom or 1.0)
    if z < 0.05 or pressure >= 2:
        return "tiny"
    if z < 0.12 or pressure >= 1:
        return "far"
    if z < 0.35:
        return "medium"
    return "full"

def _ns_view_world_rect(canvas, view, pad=240):
    z = max(0.001, float(view.get("zoom", 1.0)))
    return (
        (canvas.x - pad - canvas.x - view["pan"][0]) / z,
        (canvas.y - pad - canvas.y - view["pan"][1]) / z,
        (canvas.right + pad - canvas.x - view["pan"][0]) / z,
        (canvas.bottom + pad - canvas.y - view["pan"][1]) / z,
    )

def _ns_node_world_visible_fast(n, wrect, pad=80):
    """Cheap cull before building fonts/surfaces/rects."""
    x = float(n.get("x", 0)); y = float(n.get("y", 0))
    # Over-estimate node size so we never pop nodes at viewport edges.
    return not (x > wrect[2] + pad or y > wrect[3] + pad or x + NS_NODE_W * 3 < wrect[0] - pad or y + NS_NODE_H_BASE * 5 < wrect[1] - pad)

def _ns_wire_cached_points(p0, p1, style, lod):
    """Connection-path cache. Low LOD deliberately collapses to straight."""
    if lod in ("tiny", "far"):
        return [(float(p0[0]), float(p0[1])), (float(p1[0]), float(p1[1]))]
    key = (round(float(p0[0]), 1), round(float(p0[1]), 1), round(float(p1[0]), 1), round(float(p1[1]), 1), style, lod)
    pts = _NS_WIRE_PATH_CACHE.get(key)
    if pts is None:
        if len(_NS_WIRE_PATH_CACHE) > _NS_MAX_WIRE_CACHE:
            _NS_WIRE_PATH_CACHE.clear()
        pts = _ns_wire_points(p0, p1, style)
        if lod == "medium" and len(pts) > 12:
            step = max(1, len(pts) // 12)
            pts = pts[::step] + ([pts[-1]] if pts[-1] != pts[::step][-1] else [])
        _NS_WIRE_PATH_CACHE[key] = pts
    return pts

def _ns_group_by_id(group_id):
    return next((g for g in modal.get("ns_smart_groups", []) or []
                 if g.get("id") == group_id), None)

def _ns_group_for_node(nid):
    """Return the nearest/direct Smart Group containing a node."""
    for g in reversed(modal.get("ns_smart_groups", []) or []):
        if nid in set(g.get("node_ids", [])):
            return g
    return None

def _ns_group_children(group):
    groups = {g.get("id"): g for g in modal.get("ns_smart_groups", []) or []}
    return [groups[gid] for gid in group.get("child_group_ids", []) or [] if gid in groups]

def _ns_group_all_node_ids(group, seen=None):
    seen = set(seen or ())
    gid = group.get("id")
    if gid in seen:
        return set()
    seen.add(gid)
    ids = {nid for nid in group.get("node_ids", []) if nid in modal.get("ns_nodes", {})}
    for child in _ns_group_children(group):
        ids.update(_ns_group_all_node_ids(child, seen))
    return ids

def _ns_group_nesting_depth(group, seen=None):
    """Number of group levels in this subtree, including this group."""
    seen = set(seen or ())
    gid = group.get("id")
    if gid in seen:
        return 99
    seen.add(gid)
    children = _ns_group_children(group)
    return 1 if not children else 1 + max(_ns_group_nesting_depth(c, seen) for c in children)

def _ns_group_parent(group_id):
    return next((g for g in modal.get("ns_smart_groups", []) or []
                 if group_id in (g.get("child_group_ids", []) or [])), None)

def _ns_group_has_collapsed_ancestor(group_id):
    seen = set()
    parent = _ns_group_parent(group_id)
    while parent and parent.get("id") not in seen:
        seen.add(parent.get("id"))
        # Frozen only locks movement. It must never hide a child group or
        # its nodes — collapse is the sole visibility/virtualization state.
        if parent.get("collapsed"):
            return True
        parent = _ns_group_parent(parent.get("id"))
    return False

def _ns_node_group_world_bounds(node, nodes):
    """Conservative visual bounds, including long titles and clamp decks."""
    x = float(node.get("x", 0)); y = float(node.get("y", 0))
    title = str(node.get("custom_name") or
                getattr(NODE_DEFS.get(node.get("type"), NodeBase), "title", node.get("type", "Node")))
    width = max(_ns_get_node_world_width(node), min(520.0, 44.0 + len(title) * 9.0))
    height = _ns_get_node_world_height(node)
    clamped = [other for other in nodes.values()
               if str(other.get("props", {}).get("clamped_to", "")) == str(node.get("id"))]
    if clamped:
        # Host cards are shifted upward by one deck per attached clamp.
        deck_extra = 36.0 * len(clamped)
        y -= deck_extra
        height += deck_extra
        width = max(width, max((_ns_get_node_world_width(c) for c in clamped), default=width))
    return x, y, x + width, y + height

def _ns_sync_smart_group_bounds(group, side_pad=52.0, top_pad=70.0,
                                bottom_pad=48.0, seen=None):
    """Fit a group around direct nodes plus nested child groups."""
    seen = set(seen or ())
    gid = group.get("id")
    if gid in seen:
        return False
    seen.add(gid)
    _padding_scale = max(0.5, min(3.0, float(group.get("padding_scale", 1.0))))
    side_pad *= _padding_scale; top_pad *= _padding_scale; bottom_pad *= _padding_scale
    nodes = modal.get("ns_nodes", {})
    ids = [nid for nid in group.get("node_ids", []) if nid in nodes]
    group["node_ids"] = ids
    child_groups = _ns_group_children(group)[:5]
    group["child_group_ids"] = [g.get("id") for g in child_groups]
    boxes = []
    for nid in ids:
        boxes.append(_ns_node_group_world_bounds(nodes[nid], nodes))
    for child in child_groups:
        _ns_sync_smart_group_bounds(child, side_pad, top_pad, bottom_pad, seen)
        boxes.append((float(child.get("x", 0)), float(child.get("y", 0)),
                      float(child.get("x", 0)) + float(child.get("w", 180)),
                      float(child.get("y", 0)) + float(child.get("h", 120))))
    if not boxes:
        return False
    left = min(b[0] for b in boxes); top = min(b[1] for b in boxes)
    right = max(b[2] for b in boxes); bottom = max(b[3] for b in boxes)
    group["x"] = left - side_pad
    group["y"] = top - top_pad
    group["w"] = max(150.0, right - left + side_pad * 2)
    group["h"] = max(110.0, bottom - top + top_pad + bottom_pad)
    return True

def _ns_sync_all_smart_groups():
    # Children first, then parents. Parents therefore consume final child bounds.
    groups = modal.get("ns_smart_groups", []) or []
    for group in sorted(groups, key=lambda g: _ns_group_nesting_depth(g)):
        _ns_sync_smart_group_bounds(group)
    for group in sorted(groups, key=lambda g: _ns_group_nesting_depth(g), reverse=True):
        _ns_sync_smart_group_bounds(group)

def _ns_refit_groups_from_rendered_nodes(canvas):
    """Use actual card rectangles to eliminate title/clamp leakage next frame."""
    if not canvas:
        return
    rects = {nid: rect for nid, rect in modal.get("_ns_node_rects_canvas", [])}
    view = modal.get("ns_view", {"pan": [0,0], "zoom": 1.0})
    z = max(0.001, float(view.get("zoom", 1.0)))
    if z < 0.55:
        # World-space fitting already scales correctly. Screen minimums at
        # distant zoom levels would otherwise make groups inflate visually.
        return
    def world_box(rect):
        return ((rect.left-canvas.x-view["pan"][0])/z,
                (rect.top-canvas.y-view["pan"][1])/z,
                (rect.right-canvas.x-view["pan"][0])/z,
                (rect.bottom-canvas.y-view["pan"][1])/z)
    groups = modal.get("ns_smart_groups", []) or []
    for group in sorted(groups, key=lambda g: _ns_group_nesting_depth(g)):
        if group.get("collapsed"):
            continue
        boxes = [world_box(rects[nid]) for nid in group.get("node_ids", []) if nid in rects]
        boxes += [(c.get("x",0), c.get("y",0), c.get("x",0)+c.get("w",0), c.get("y",0)+c.get("h",0))
                  for c in _ns_group_children(group)]
        if not boxes:
            continue
        scale = max(0.5, min(3.0, float(group.get("padding_scale",1.0))))
        sp, tp, bp = 52*scale, 70*scale, 48*scale
        left=min(b[0] for b in boxes); top=min(b[1] for b in boxes)
        right=max(b[2] for b in boxes); bottom=max(b[3] for b in boxes)
        group["x"], group["y"] = left-sp, top-tp
        group["w"], group["h"] = right-left+sp*2, bottom-top+tp+bp

def _ns_move_smart_group(group, dx, dy, moved_nodes=None, moved_groups=None):
    """Move a group, every descendant group, and every member exactly once."""
    nodes = modal.get("ns_nodes", {})
    moved_nodes = moved_nodes if moved_nodes is not None else set()
    moved_groups = moved_groups if moved_groups is not None else set()
    gid = group.get("id")
    if gid in moved_groups:
        return
    moved_groups.add(gid)
    for nid in group.get("node_ids", []) or []:
        node = nodes.get(nid)
        if node is not None and nid not in moved_nodes:
            moved_nodes.add(nid)
            node["x"] = float(node.get("x", 0)) + dx
            node["y"] = float(node.get("y", 0)) + dy
    for child in _ns_group_children(group):
        _ns_move_smart_group(child, dx, dy, moved_nodes, moved_groups)
    for paint in nodes.values():
        if (paint.get("type") == "clip_paint_bucket" and
                str(paint.get("props",{}).get("target_group_id","")) == str(gid) and
                paint.get("id") not in moved_nodes):
            moved_nodes.add(paint.get("id"))
            paint["x"] = float(paint.get("x",0)) + dx
            paint["y"] = float(paint.get("y",0)) + dy
    group["x"] = float(group.get("x", 0)) + dx
    group["y"] = float(group.get("y", 0)) + dy
    modal["ns_dirty"] = True

def _ns_defs_signature():
    """Cheap invalidation key for node-library search/sort caches."""
    return (len(NODE_DEFS), tuple(sorted(NODE_DEFS.keys())))

def _ns_rebuild_node_library_cache():
    sig = _ns_defs_signature()
    if _NS_NODE_LIBRARY_CACHE.get("sig") == sig:
        return
    rows = []
    tokens = {}
    for key, cls in NODE_DEFS.items():
        hay = " ".join((cls.title, cls.key, cls.category, cls.description,
                        " ".join(getattr(p, "name", "") for p in getattr(cls, "inputs", [])),
                        " ".join(getattr(p, "name", "") for p in getattr(cls, "outputs", [])),
                        " ".join(getattr(p, "name", "") for p in getattr(cls, "properties", {}).values()))).lower()
        rows.append((key, cls, hay))
        tokens[key] = set(hay.replace("_", " ").replace("/", " ").split())
    rows.sort(key=lambda x: (x[1].category, x[1].title))
    _NS_NODE_LIBRARY_CACHE.update({
        "sig": sig,
        "categories": sorted(NODE_CATEGORIES.keys()),
        "rows": rows,
        "tokens": tokens,
    })

def ns_sorted_categories():
    _ns_rebuild_node_library_cache()
    return list(_NS_NODE_LIBRARY_CACHE["categories"])

def _ns_search_score(query, key, cls, hay):
    if not query:
        return 0
    q = query.lower().strip()
    if not q:
        return 0
    score = 0
    title = cls.title.lower()
    cat = getattr(cls, "category", "").lower()
    
    # Priority boost for Event nodes so they always show at the very top of search!
    is_event = (key.startswith("event_") or key in globals().get("EVENT_TO_HOOK", {}) 
                or title.startswith("on ") or "event" in cat)
    if is_event:
        score += 800

    if title == q:
        score += 1000
    if title.startswith(q):
        score += 350
    if key.lower().startswith(q):
        score += 250
    if q in title:
        score += 160
    if q in key.lower():
        score += 130
    for token in q.split():
        if token not in hay:
            return None
        score += 35
        if token in _NS_NODE_LIBRARY_CACHE.get("tokens", {}).get(key, set()):
            score += 20
    return score

DEFAULT_PALETTE_NODES = [
    "event_on_spawn", "event_on_despawn", "event_on_death", "event_on_hit", "event_on_tick",
    "event_on_damage_taken", "event_on_damage_dealt", "event_on_kill",
    "scene_duplicate_bar_for_character", "scene_clone_node", "scene_delete_linked_nodes",
    "audio_play_path", "gameplay_spawn_custom_clone", "dummy_controller",
    "gameplay_deal_damage", "gameplay_heal", "condition_branch", "timing_delay",
    "gameplay_spin", "gameplay_teleport", "utility_comment", "utility_print"
]

# Categories that only make sense on a scene entity (prop / director), not
# on a fighter. Showing them everywhere was the source of the "why can my
# character reach scene nodes" confusion.
NS_SCENE_ONLY_CATEGORIES = frozenset({
    "Scene", "Scene Actions", "Scene Audio Director", "Scene Communication",
    "Scene Conditions", "Scene Data", "Scene Director", "Scene Math",
    "Scene Physics", "Scene Prop Controls", "Scene Text", "Scene Animation",
    "Scene Utilities", "Particles", "Weather",
})

def ns_editing_entity_kind():
    """What kind of entity the blueprint editor is currently attached to.

    Returns "character", "prop" or "director". Directors are props with
    their visuals off, and they are the scene's logic brain -- so they get
    BOTH the scene nodes and the ordinary character nodes.
    """
    tmpl = modal.get("editing")
    is_prop = False
    is_dir = False
    if isinstance(tmpl, dict) and tmpl.get("is_scene_prop"):
        is_prop = True
        is_dir = bool(tmpl.get("scene_director"))
    elif modal.get("is_scene_prop"):
        is_prop = True
        is_dir = bool(modal.get("scene_director"))
    if is_dir:
        return "director"
    return "prop" if is_prop else "character"

CHARACTER_ALLOWED_SCENE_NODES = frozenset({
    "character_get_instance_id", "character_set_instance_id", "utility_format_id_tag", "utility_generate_unique_id",
    "scene_set_identifier_tooltip", "scene_remove_identifier_tooltip",
    "vfx_wiggle_target", "vfx_stop_wiggle", "rig_projectile_squash_stretch",
    "rig_projectile_wall_behavior", "rig_projectile_lodge_wall", "rig_projectile_bounce_wall",
    "event_on_projectile_wall_hit", "event_on_projectile_wall_touch",
    "scene_clone_node", "ext_clone_node", "scene_duplicate_bar_for_character",
    "scene_set_node_tag", "scene_set_node_name", "scene_delete_node",
    "scene_delete_by_tag", "scene_delete_linked_nodes", "scene_link_node_to_character",
    "scene_find_node_by_tag", "ext_get_node", "ext_find_tag", "ext_track_char",
    "ext_set_value", "ext_set_text", "ext_set_visible", "ext_set_color", "ext_set_prop",
    "ext_set_bar_max", "ext_set_bar_label", "ext_set_bar_size", "ext_configure_bar",
    "event_on_despawn", "event_on_death", "event_on_spawn"
})

def ns_node_allowed(key, cls, kind=None):
    """Is this node offered for the entity being edited?"""
    kind = kind or ns_editing_entity_kind()
    cat = getattr(cls, "category", "")
    if key in CHARACTER_ALLOWED_SCENE_NODES:
        return True
    scene_ish = (cat in NS_SCENE_ONLY_CATEGORIES
                 or str(key).startswith("event_on_scene_")
                 or str(key).startswith("scene_")
                 or str(key).startswith("pe_")
                 or str(key).startswith("ext_"))
    if kind == "character":
        # Plain fighters get everything EXCEPT the scene-authoring nodes.
        return not scene_ish
    # Props get scene nodes; directors get scene nodes plus everything a
    # character can do, since they drive the whole match.
    return True

def ns_filtered_nodes(search="", category=None):
    _ns_rebuild_node_library_cache()
    q = (search or "").strip().lower()
    _kind = ns_editing_entity_kind()

    # Fast default palette when search is empty: show popular starter nodes to eliminate 600+ node render lag
    if not q and not category:
        res = []
        for key in DEFAULT_PALETTE_NODES:
            cls = NODE_DEFS.get(key)
            if cls and ns_node_allowed(key, cls, _kind):
                res.append((key, cls))
        return res

    out = []
    for key, cls, hay in _NS_NODE_LIBRARY_CACHE["rows"]:
        if category and cls.category != category:
            continue
        if not ns_node_allowed(key, cls, _kind):
            continue
        score = _ns_search_score(q, key, cls, hay) if q else 100
        if score is not None:
            out.append((score, key, cls))

    if q:
        out.sort(key=lambda x: (-x[0], not (x[1].startswith("event_") or x[1] in globals().get("EVENT_TO_HOOK", {}) or x[2].title.lower().startswith("on ")), x[2].category, x[2].title))
        return [(key, cls) for _, key, cls in out[:35]]
    else:
        out.sort(key=lambda x: (not (x[1].startswith("event_") or x[1] in globals().get("EVENT_TO_HOOK", {}) or x[2].title.lower().startswith("on ")), x[2].category, x[2].title))
        return [(key, cls) for _, key, cls in out[:45]]

def _ns_graph_signature(nodes=None, links=None):
    nodes = nodes if nodes is not None else modal.get("ns_nodes", {})
    links = links if links is not None else modal.get("ns_links", [])
    try:
        node_sig = tuple(sorted((int(nid), n.get("type"), round(float(n.get("x", 0)), 2),
                                round(float(n.get("y", 0)), 2),
                                str(n.get("custom_name", "")),
                                bool(n.get("ui_muted")), bool(n.get("ui_bypass")),
                                bool(n.get("ui_breakpoint")), bool(n.get("ui_pinned")),
                                tuple(sorted((n.get("props") or {}).items(), key=lambda kv: str(kv[0]))))
                               for nid, n in nodes.items()))
    except Exception:
        node_sig = tuple(sorted((str(k), str(v)) for k, v in nodes.items()))
    try:
        link_sig = tuple(sorted((l.get("from"), l.get("from_pin"), l.get("to"), l.get("to_pin")) for l in links))
    except Exception:
        link_sig = tuple(map(str, links))
    return (node_sig, link_sig)

def _ns_cached_graph_diagnostics(nodes, links):
    sig = _ns_graph_signature(nodes, links)
    if _NS_DIAGNOSTIC_CACHE.get("sig") != sig:
        _NS_DIAGNOSTIC_CACHE["sig"] = sig
        _NS_DIAGNOSTIC_CACHE["issues"] = graph_diagnostics(nodes, links)
    # Return copies because runtime errors/source-only warnings are inserted per frame.
    return [dict(issue) for issue in _NS_DIAGNOSTIC_CACHE.get("issues", [])]

def _ns_graph_stats(nodes=None, links=None):
    """Cached graph metrics used by UI, minimap, profiling, and future tools."""
    nodes = nodes if nodes is not None else modal.get("ns_nodes", {})
    links = links if links is not None else modal.get("ns_links", [])
    sig = _ns_graph_signature(nodes, links)
    if _NS_GRAPH_STATS_CACHE.get("sig") == sig:
        return dict(_NS_GRAPH_STATS_CACHE.get("stats", {}))
    by_cat, by_type = {}, {}
    incoming = {nid: 0 for nid in nodes}
    outgoing = {nid: 0 for nid in nodes}
    exec_links = data_links = broken_links = 0
    for nid, n in nodes.items():
        cls = NODE_DEFS.get(n.get("type"), NodeBase)
        by_cat[cls.category] = by_cat.get(cls.category, 0) + 1
        by_type[n.get("type")] = by_type.get(n.get("type"), 0) + 1
    for l in links:
        f, t = l.get("from"), l.get("to")
        if f in outgoing: outgoing[f] += 1
        if t in incoming: incoming[t] += 1
        a = nodes.get(f); cls_a = NODE_DEFS.get(a.get("type"), NodeBase) if a else NodeBase
        pin_a = next((p for p in cls_a.outputs if p.name == l.get("from_pin")), None)
        if pin_a is None:
            broken_links += 1
        elif pin_a.type == EXEC:
            exec_links += 1
        else:
            data_links += 1
    orphan_nodes = [nid for nid in nodes if incoming.get(nid, 0) == 0 and outgoing.get(nid, 0) == 0]
    stats = {
        "nodes": len(nodes), "links": len(links), "exec_links": exec_links, "data_links": data_links,
        "broken_links": broken_links, "orphan_nodes": len(orphan_nodes), "by_category": by_cat,
        "by_type": by_type, "fanout_max": max(outgoing.values(), default=0),
        "fanin_max": max(incoming.values(), default=0),
        "density": round(len(links) / max(1, len(nodes)), 3),
    }
    _NS_GRAPH_STATS_CACHE.update({"sig": sig, "stats": stats})
    return dict(stats)

def _ns_rect_near_canvas(rect, canvas, pad=600):
    return rect.colliderect(canvas.inflate(pad, pad))

def _ns_wire_near_canvas(p0, p1, canvas, pad=360):
    minx = min(p0[0], p1[0]) - pad; maxx = max(p0[0], p1[0]) + pad
    miny = min(p0[1], p1[1]) - pad; maxy = max(p0[1], p1[1]) + pad
    return pygame.Rect(int(minx), int(miny), max(1, int(maxx-minx)), max(1, int(maxy-miny))).colliderect(canvas)

