def vs_build_script_code():
    nodes = modal.get("ns_nodes", {})
    links = modal.get("ns_links", [])
    if not nodes:
        return None
    errors = validate_graph(nodes, links)
    if errors:
        return "# Validation errors:\n# " + "\n# ".join(errors)

    # Identify target-bound event nodes (wired to spawned clones/dummies) vs top-level host hooks
    hook_events = {}
    target_bound_events = []
    for n in nodes.values():
        hook = EVENT_TO_HOOK.get(n.get("type"))
        if hook:
            is_target_bound = any(l.get("to") == n["id"] and l.get("to_pin") == "target" for l in links)
            if is_target_bound:
                target_bound_events.append(n)
            else:
                hook_events.setdefault(hook, []).append(n)

    # If there are target-bound event nodes, ensure on_spawn exists so setup bindings run at spawn time
    if target_bound_events or not hook_events:
        hook_events.setdefault("on_spawn", [])

    parts = []
    parts.append('"""Generated by Blueprint Visual Scripter.\n')
    parts.append('This file is regenerated from the node graph; edit the graph instead.\n"""\n')
    parts.append('import random\nimport math\nimport pygame\nimport time\n')
    # Preserve parameters already declared by an imported/source script, then
    # let explicit graph Parameter nodes add or override entries. This keeps
    # Traits-panel settings from disappearing after the first graph save.
    # But only use preserved params that belong to the CURRENTLY loaded script —
    # stale params from a previous character's script must not leak in.
    _preserved = modal.get("ns_preserved_params", {})
    _current_script = modal.get("script_file") or modal.get("ns_loaded_script")
    if _current_script:
        # Re-peek to ensure the preserved set matches the actual script
        _fresh_params = peek_script_params(_current_script)
        if _fresh_params:
            _preserved = {k: v for k, v in _preserved.items() if k in _fresh_params}
        else:
            _preserved = {}
    exposed_params = dict(_preserved)
    for parameter_node in nodes.values():
        if _ns_node_muted(parameter_node) or _ns_node_bypassed(parameter_node):
            continue
        node_type = parameter_node.get("type")
        props = parameter_node.get("props", {})
        if node_type == "parameter_number":
            exposed_params[str(props.get("name", "amount"))] = props.get("default", 10)
        elif node_type == "parameter_boolean":
            exposed_params[str(props.get("name", "enabled"))] = bool(props.get("default", True))
        elif node_type == "parameter_text":
            exposed_params[str(props.get("name", "text"))] = str(props.get("default", ""))
        elif node_type == "parameter_animation":
            exposed_params[str(props.get("name", "animation"))] = str(props.get("default", ""))
        elif node_type == "parameter_color":
            # Kept in generated code for graph use; list-valued parameters are
            # not currently shown as plain text fields in the Traits panel.
            exposed_params[str(props.get("name", "color"))] = list(props.get("color", [255,255,255]))
    parts.append(f"\nPARAMS = {exposed_params!r}\n")

    # Auto-declare any custom sprite tags used by Set Sprite Image nodes so the
    # character editor's Sprites panel automatically shows a new row for them
    # (see _read_script_sprite_tags / BUILTIN_SPRITE_TAGS) -- no manual editing
    # of the generated file needed, and no separate sync step: both the panel
    # and the node read/write the same me["sprites"][tag] dict, so swapping the
    # image in the panel is picked up by the node (and vice versa) automatically.
    _declared_sprite_tags = []
    # Regenerating a script must never LOSE sprite tags the old file already
    # declared. Custom states added in the character editor are persisted into
    # the script's SPRITE_TAGS line (persist_custom_sprite_tags_to_script);
    # rebuilding from the graph without carrying them forward silently deleted
    # the user's custom sprite states on every blueprint save/autosave.
    _regen_target = modal.get("script_file") or modal.get("ns_loaded_script")
    if _regen_target:
        try:
            for _prev_tag in peek_script_sprite_tags(_regen_target):
                _prev_tag = str(_prev_tag).strip()
                if _prev_tag and _prev_tag not in _declared_sprite_tags:
                    _declared_sprite_tags.append(_prev_tag)
        except Exception:
            pass
    for _sprite_node in nodes.values():
        if _ns_node_muted(_sprite_node) or _ns_node_bypassed(_sprite_node):
            continue
        if _sprite_node.get("type") == "animation_set_sprite_image":
            _tag_val = str(_sprite_node.get("props", {}).get("sprite_tag", "")).strip()
            if _tag_val and _tag_val not in _declared_sprite_tags:
                _declared_sprite_tags.append(_tag_val)
    if _declared_sprite_tags:
        parts.append(f"\nSPRITE_TAGS = {_declared_sprite_tags!r}\n")

    parts.append(NS_RUNTIME_HELPERS)
    parts.append('\n_ns_variables = {}\n')
    # Generated scripts run in their own isolated exec() namespace (see
    # build_script_ns), so the editor's module-level _NS_GLOBAL_VARS isn't
    # visible to them. Without this, any graph using Set/Get Global Variable
    # would crash with NameError the moment that hook ran. Declare a
    # per-script global dict here so Set/Get Global Variable nodes always
    # have something to write to and read from.
    parts.append('_NS_GLOBAL_VARS = {}\n')
    _group_defaults = {str(g.get("name","Smart Group")): True for g in modal.get("ns_smart_groups", [])}
    parts.append(f"_ns_group_flags = {_group_defaults!r}\n")

    def _tag(line, nid):
        """Append an inline node-id marker comment to generated source."""
        if nid is None or line is None:
            return line
        tagged = str(line).rstrip("\n\n")
        if not tagged.strip() or "# _ns_node:" in tagged:
            return tagged
        return tagged + f"  # _ns_node:{nid}"

    # state var declarations
    state_lines = []   # list of (line_text, node_id_or_None)
    timing_nodes_exist = False
    for n in nodes.values():
        cls = NODE_DEFS.get(n.get("type"))
        if cls is None or _ns_node_muted(n) or _ns_node_bypassed(n):
            continue
        _stid = n["id"]
        if n.get("type") in ("timing_delay", "timing_fuse"):
            # One queue entry per trigger; unlike the former active/timer pair,
            # overlapping projectile events cannot overwrite/block each other.
            state_lines.append((f"_ns_state_{_stid}_queue = []", _stid))
            timing_nodes_exist = True
        elif n.get("type") in ("timing_countdown", "timing_timeline"):
            state_lines.append((f"_ns_state_{_stid}_active = False", _stid))
            state_lines.append((f"_ns_state_{_stid}_timer = 0.0", _stid))
            timing_nodes_exist = True
        elif n.get("type") == "timing_cooldown":
            state_lines.append((f"_ns_state_{_stid}_end = 0.0", _stid))
        elif n.get("type") == "timing_every_second":
            state_lines.append((f"_ns_state_{_stid}_timer = 0.0", _stid))
            timing_nodes_exist = True
        elif n.get("type") == "timing_every_x_seconds":
            state_lines.append((f"_ns_state_{_stid}_timer = 0.0", _stid))
            timing_nodes_exist = True
        elif n.get("type") == "timing_every_x_triggered":
            state_lines.append((f"_ns_state_{_stid}_count = 0", _stid))
        elif n.get("type") == "timing_repeat_for_duration":
            state_lines.append((f"_ns_state_{_stid}_active = False", _stid))
            state_lines.append((f"_ns_state_{_stid}_timer = 0.0", _stid))
            state_lines.append((f"_ns_state_{_stid}_remaining = 0.0", _stid))
            state_lines.append((f"_ns_state_{_stid}_interval = 0.0", _stid))
            timing_nodes_exist = True
        elif n.get("type") in ("tag_wait_until_set", "tag_wait_until_removed"):
            state_lines.append((f"_ns_state_{_stid}_active = False", _stid))
            state_lines.append((f"_ns_state_{_stid}_tag = ''", _stid))
            state_lines.append((f"_ns_state_{_stid}_target = None", _stid))
            timing_nodes_exist = True
        elif n.get("type") == "timing_round_robin_sequence":
            state_lines.append((f"_ns_state_{_stid}_index = -1", _stid))
        elif n.get("type") == "timing_once":
            state_lines.append((f"_ns_state_{_stid}_fired = False", _stid))
        elif n.get("type") == "timing_once_per_true_cycle":
            # Rising-edge memory must exist at module scope before on_tick's
            # first call; state_name() only adds the hook's global declaration.
            state_lines.append((f"_ns_state_{_stid}_previous = False", _stid))
        elif n.get("type") == "timing_stopwatch":
            state_lines.append((f"_ns_state_{_stid}_running = False", _stid))
            state_lines.append((f"_ns_state_{_stid}_elapsed = 0.0", _stid))
            timing_nodes_exist = True
    # Any timer-driven node (timing_fuse, timing_delay, timing_countdown, etc.)
    # needs _ns_update_timers() called every frame, which only happens inside
    # an on_tick hook. Previously this required the graph to have an explicit
    # "Event On Tick" node, so graphs that only used delay/fuse timers (with
    # no visible tick node) silently never advanced their timers. Now the
    # on_tick hook is generated automatically whenever timing nodes are
    # present, even with zero event_on_tick nodes wired in.
    if timing_nodes_exist:
        hook_events.setdefault("on_tick", [])
    state_names = [entry[0].split("=", 1)[0].strip() for entry in state_lines]
    if state_lines:
        parts.append('\n# persistent node state\n')
        for _sl, _snid in state_lines:
            parts.append(_tag(_sl, _snid) + '\n')

    # generate hook functions (line tagging helper is declared above state emission)
    def _ctx_annotated_out(ctx):
        """Return a list of annotated lines (text, nid) from a ctx, using
        its sub.out lists for any pending_funcs the ctx enqueued."""
        out = []
        for raw, nid in ctx.annotated_lines():
            out.append((raw, nid))
        return out

    all_pending_funcs = []
    pending_ctxs = []   # parallel list of sub-contexts for pending funcs
    for hook, event_nodes in hook_events.items():
        event_args = {}
        for arg in EVENT_HOOK_ARGS.get(hook, []):
            event_args[arg] = arg
        ctx = CodegenContext(nodes, links, hook, event_args)
        for ev in event_nodes:
            ctx.generate_exec(ev["id"], set())
        if hook == "on_spawn" and target_bound_events:
            for tb_ev in target_bound_events:
                ctx.generate_exec(tb_ev["id"], set())
        # Collect the sub-contexts BEFORE we consume pending_funcs
        for pfunc_ctx in getattr(ctx, "_pending_ctxs", []):
            pending_ctxs.append(pfunc_ctx)
        all_pending_funcs.extend(ctx.pending_funcs)

        args = ["ctx", "me"] + EVENT_HOOK_ARGS.get(hook, [])
        parts.append(f"\ndef {hook}({', '.join(args)}):\n")
        if ctx.state_vars:
            parts.append("    global " + ", ".join(sorted(ctx.state_vars.keys())) + "\n")
        if timing_nodes_exist and hook != "on_tick":
            # Event hooks such as on_damage_taken(ctx, me, other, taken, crit)
            # do not receive a dt argument. Timing nodes can still be used to
            # start persistent timer state from an event, so provide a safe
            # single-frame delta instead of generating NameError: dt.
            parts.append("    dt = 1.0 / 60.0\n")
        if hook == "on_tick" and timing_nodes_exist:
            parts.append("    _ns_update_timers(ctx, me, dt)\n")
        if ctx.out:
            for raw, nid in _ctx_annotated_out(ctx):
                parts.append(_tag(raw, nid) + "\n")
        else:
            parts.append("    pass\n")

    # timer update function (if any delay/countdown/timeline nodes exist)
    if timing_nodes_exist:
        parts.append("\ndef _ns_update_timers(ctx, me, dt):\n")
        if state_names:
            parts.append("    global " + ", ".join(state_names) + "\n")
        for n in nodes.values():
            if _ns_node_muted(n) or _ns_node_bypassed(n):
                continue
            t = n.get("type")
            nid = n["id"]
            if t in ("timing_delay", "timing_fuse"):
                queue = f"_ns_state_{n['id']}_queue"
                func = f"_ns_delay_done_{n['id']}"
                pending = f"_ns_delay_pending_{n['id']}"
                task = f"_ns_delay_task_{n['id']}"
                # Detach the current batch first. A callback may trigger this
                # same Delay again; that new item stays in queue for the next
                # frame instead of being lost during iteration.
                parts.append(_tag(f"    if {queue}:", nid) + "\n")
                parts.append(_tag(f"        {pending} = list({queue})", nid) + "\n")
                parts.append(_tag(f"        {queue}[:] = []", nid) + "\n")
                parts.append(_tag(f"        for {task} in {pending}:", nid) + "\n")
                parts.append(_tag(f"            {task}[0] -= dt", nid) + "\n")
                parts.append(_tag(f"            if {task}[0] <= 0:", nid) + "\n")
                parts.append(_tag(f"                {func}(ctx, me, *{task}[1])", nid) + "\n")
                parts.append(_tag(f"            else:", nid) + "\n")
                parts.append(_tag(f"                {queue}.append({task})", nid) + "\n")
            elif t == "timing_countdown":
                active = f"_ns_state_{n['id']}_active"
                timer = f"_ns_state_{n['id']}_timer"
                func = f"_ns_countdown_done_{n['id']}"
                parts.append(_tag(f"    if {active}:", nid) + "\n")
                parts.append(_tag(f"        {timer} -= dt", nid) + "\n")
                parts.append(_tag(f"        if {timer} <= 0:", nid) + "\n")
                parts.append(_tag(f"            {active} = False", nid) + "\n")
                parts.append(_tag(f"            {func}(ctx, me)", nid) + "\n")
            elif t == "timing_timeline":
                active = f"_ns_state_{n['id']}_active"
                timer = f"_ns_state_{n['id']}_timer"
                func = f"_ns_timeline_done_{n['id']}"
                parts.append(_tag(f"    if {active}:", nid) + "\n")
                parts.append(_tag(f"        {timer} += dt", nid) + "\n")
                parts.append(_tag(f"        if {timer} >= {n.get('props',{}).get('duration',2.0)}:", nid) + "\n")
                parts.append(_tag(f"            {active} = False", nid) + "\n")
                parts.append(_tag(f"            {func}(ctx, me)", nid) + "\n")
            elif t in ("tag_wait_until_set", "tag_wait_until_removed"):
                active = f"_ns_state_{n['id']}_active"
                tag_var = f"_ns_state_{n['id']}_tag"
                target_var = f"_ns_state_{n['id']}_target"
                func = f"_ns_wait_tag_done_{n['id']}"
                parts.append(_tag(f"    if {active} and {target_var}:", nid) + "\n")
                op = "in" if t == "tag_wait_until_set" else "not in"
                parts.append(_tag(f"        if {tag_var} {op} {target_var}.get('tags', set()):", nid) + "\n")
                parts.append(_tag(f"            {active} = False", nid) + "\n")
                parts.append(_tag(f"            {func}(ctx, me)", nid) + "\n")
            elif t == "timing_repeat_for_duration":
                active = f"_ns_state_{n['id']}_active"
                timer = f"_ns_state_{n['id']}_timer"
                remaining = f"_ns_state_{n['id']}_remaining"
                ivstate = f"_ns_state_{n['id']}_interval"
                tick_func = f"_ns_repeatdur_tick_{n['id']}"
                done_func = f"_ns_repeatdur_done_{n['id']}"
                parts.append(_tag(f"    if {active}:", nid) + "\n")
                parts.append(_tag(f"        {remaining} -= dt", nid) + "\n")
                parts.append(_tag(f"        {timer} -= dt", nid) + "\n")
                parts.append(_tag(f"        if {timer} <= 0:", nid) + "\n")
                parts.append(_tag(f"            {timer} += max(0.05, {ivstate})", nid) + "\n")
                parts.append(_tag(f"            {tick_func}(ctx, me)", nid) + "\n")
                parts.append(_tag(f"        if {remaining} <= 0:", nid) + "\n")
                parts.append(_tag(f"            {active} = False", nid) + "\n")
                parts.append(_tag(f"            {done_func}(ctx, me)", nid) + "\n")

    # delayed callback functions (place after hooks)
    # Rather than emitting the raw text from `pending_funcs` (which has no
    # attribution), we re-emit every sub-context with markers.
    if pending_ctxs or all_pending_funcs:
        parts.append("\n# delayed / subgraph callbacks\n")
        # Use pending_ctxs if available; otherwise fall back to raw lines
        seen_funcs = set()
        for sub in pending_ctxs:
            # sub stores its metadata: pull function header/args/body
            fn_name = getattr(sub, "_pending_func_name", None)
            if fn_name is None:
                continue
            if fn_name in seen_funcs:
                continue
            seen_funcs.add(fn_name)
            args = ["ctx", "me"] + list(getattr(sub, "_pending_func_extra_args", []))
            parts.append(f"def {fn_name}({', '.join(args)}):\n")
            if state_names:
                parts.append("    global " + ", ".join(state_names) + "\n")
            body_lines = list(sub.annotated_lines())
            if not body_lines:
                parts.append("    pass\n")
            else:
                for raw, nid in body_lines:
                    if not raw.strip():
                        parts.append(raw + "\n")
                    else:
                        parts.append(_tag(raw, nid) + "\n")
            parts.append("\n")
        # Fallback: emit any pending_funcs that didn't come with a ctx
        # (shouldn't happen now, but keeps old code paths safe).
        # We must skip the ENTIRE function (def + body), not just the def
        # line.  Previously only the "def ..." line was skipped when a
        # function had already been emitted via pending_ctxs, which left
        # the (double-indented) body lines orphaned at module scope and
        # caused IndentationError.
        _skip_func_body = False
        for line in all_pending_funcs:
            if isinstance(line, str) and line.strip().startswith("def ") and any(
                line.strip().startswith(f"def {fn}(") for fn in seen_funcs
            ):
                _skip_func_body = True
                continue
            if _skip_func_body:
                # Blank line marks the end of a function body in the
                # pending_funcs list (each function is terminated by "").
                if not line.strip():
                    _skip_func_body = False
                continue
            parts.append(line + "\n" if not line.endswith("\n") else line)

    return "".join(parts)

def sanitize_script_filename(name):
    name = (name or "").strip()
    if not name:
        return None
    if name.endswith(".py"):
        name = name[:-3]
    safe = "".join(ch if (ch.isalnum() or ch in ("_", "-")) else "_" for ch in name)
    safe = safe.strip("_") or None
    return (safe + ".py") if safe else None

# ── Reusable Node Cluster Library ───────────────────────────────────────────
def _ns_cluster_selected_ids(anchor_node_id=None, anchor_group_id=None):
    ids=set(ns_selection_ids())
    if anchor_node_id in modal.get("ns_nodes",{}):ids.add(anchor_node_id)
    group_ids=set(modal.get("ns_selected_groups",set()) or set())
    if anchor_group_id is not None:group_ids.add(anchor_group_id)
    for gid in group_ids:
        group=_ns_group_by_id(gid)
        if group:ids.update(_ns_group_all_node_ids(group))
    return _ns_expand_selection_with_fusion(ids,modal.get("ns_nodes",{})) if ids else set()

def ns_save_selection_as_cluster(anchor_node_id=None,anchor_group_id=None):
    ids=set(_ns_cluster_selected_ids(anchor_node_id,anchor_group_id));nodes=modal.get("ns_nodes",{})
    if not ids:push_toast("Select nodes or a Smart Group first.","warning",2.2);return False
    
    default_name = f"Node Cluster {len(NODE_CLUSTER_LIBRARY)+1}"
    
    def on_name_confirm(name):
        name = " ".join(str(name).strip().split())[:80]
        if not name:
            push_toast("Cluster name cannot be empty.", "warning")
            return
            
        # Chain second in-built text modal for tags!
        def on_tags_confirm(tags):
            tag_list = []
            for tag in str(tags or "").split(','):
                tag = tag.strip().lower()
                if tag and tag not in tag_list:
                    tag_list.append(tag[:32])
                    
            import copy
            saved_nodes = {str(nid): copy.deepcopy(nodes[nid]) for nid in ids if nid in nodes}
            saved_links = [copy.deepcopy(link) for link in modal.get("ns_links", []) if link.get("from") in ids and link.get("to") in ids]
            saved_groups = []
            for group in modal.get("ns_smart_groups", []):
                members = _ns_group_all_node_ids(group)
                # Save any group with at least one member in the selection so
                # event/trigger nodes grouped with internal nodes are all captured.
                if members and members.intersection(ids):
                    grp_copy = copy.deepcopy(group)
                    grp_copy["node_ids"] = [nid for nid in grp_copy.get("node_ids", []) if nid in ids]
                    saved_groups.append(grp_copy)
            xs=[float(n.get("x",0)) for n in saved_nodes.values()];ys=[float(n.get("y",0)) for n in saved_nodes.values()]
            center=[(min(xs)+max(xs))/2 if xs else 0,(min(ys)+max(ys))/2 if ys else 0]
            entry={"id":hashlib.sha1((name+str(time.time())).encode()).hexdigest()[:12],"name":name,"tags":tag_list,
                   "nodes":saved_nodes,"links":saved_links,"groups":saved_groups,"center":center,
                   "created":time.time(),"node_count":len(saved_nodes),"link_count":len(saved_links)}
            # Same-name save updates the old card instead of silently duplicating it.
            old=next((i for i,c in enumerate(NODE_CLUSTER_LIBRARY) if c.get("name","").lower()==name.lower()),None)
            if old is None:NODE_CLUSTER_LIBRARY.append(entry)
            else:entry["id"]=NODE_CLUSTER_LIBRARY[old].get("id",entry["id"]);NODE_CLUSTER_LIBRARY[old]=entry
            save_node_cluster_library();push_toast(f"Saved cluster '{name}' · {len(saved_nodes)} node(s).","success",2.2)
            modal["type"] = "visual_scripter"
            modal["focus"] = None
            
        modal["type"] = "text_input_modal"
        modal["text_input_title"] = "Save Cluster Tags"
        modal["text_input_label"] = "Tags separated by commas (optional):"
        modal["text_input_value"] = ""
        modal["focus"] = "text_input_value"
        modal["text_input_callback"] = on_tags_confirm
        
    def on_cancel():
        modal["type"] = "visual_scripter"
        modal["focus"] = None
        
    modal["type"] = "text_input_modal"
    modal["text_input_title"] = "Save Node Cluster"
    modal["text_input_label"] = "Cluster name:"
    modal["text_input_value"] = default_name
    modal["focus"] = "text_input_value"
    modal["text_input_callback"] = on_name_confirm
    modal["text_input_cancel_callback"] = on_cancel
    return True

def ns_import_cluster(entry):
    if not entry:return False
    import copy
    nodes=modal.get("ns_nodes",{});canvas=modal.get("_ns_canvas_rect");view=modal.get("ns_view",{"pan":[0,0],"zoom":1})
    z=max(.01,float(view.get("zoom",1)))
    cx=(canvas.width/2-view["pan"][0])/z if canvas else 0;cy=(canvas.height/2-view["pan"][1])/z if canvas else 0
    old_center=entry.get("center",[0,0]);id_map={};new_ids=[];ns_snapshot()
    for old_id,raw in entry.get("nodes",{}).items():
        nid=modal["ns_next_id"];modal["ns_next_id"]+=1;node=copy.deepcopy(raw);node["id"]=nid
        node["x"]=float(node.get("x",0))-float(old_center[0])+cx;node["y"]=float(node.get("y",0))-float(old_center[1])+cy
        nodes[nid]=node;id_map[int(old_id) if str(old_id).isdigit() else old_id]=nid;new_ids.append(nid)
    for nid in new_ids:_ns_remap_fusion_refs(nodes[nid],id_map)
    for link in entry.get("links",[]):
        f=id_map.get(link.get("from"));t=id_map.get(link.get("to"))
        if f is not None and t is not None:
            nl=copy.deepcopy(link);nl["from"]=f;nl["to"]=t;modal["ns_links"].append(nl)
    # Recreate fully-contained Smart Groups, including nested group references.
    group_map={};pending=[]
    for raw in entry.get("groups",[]):
        ng=copy.deepcopy(raw);old_gid=ng.get("id");new_gid=int(time.time()*1000000)%100000000
        while _ns_group_by_id(new_gid) or new_gid in group_map.values():new_gid=(new_gid+1)%100000000
        group_map[old_gid]=new_gid;ng["id"]=new_gid;ng["node_ids"]=[id_map[x] for x in ng.get("node_ids",[]) if x in id_map];pending.append(ng)
    for ng in pending:
        ng["child_group_ids"]=[group_map[x] for x in ng.get("child_group_ids",[]) if x in group_map]
        modal.setdefault("ns_smart_groups",[]).append(ng)
    modal["ns_multi_selected"]=set(new_ids);modal["ns_selected"]=new_ids[-1] if new_ids else None;modal["ns_selected_groups"]=set(group_map.values())
    modal["ns_dirty"]=True;_ns_sync_all_smart_groups();push_toast(f"Imported '{entry.get('name','Cluster')}' · {len(new_ids)} nodes","success",2.5);return True

def open_node_cluster_library():
    global modal_scroll
    load_node_cluster_library();modal["type"]="cluster_library";modal["cluster_library_search"]="";modal["cluster_library_tag"]="all";modal["focus"]=None;modal_scroll=0.0

def open_cluster_lesson_manager(owner_node_id=None):
    global modal_scroll
    load_node_cluster_lessons()
    modal["type"] = "cluster_lesson_manager"
    modal["cluster_lesson_manager_owner"] = owner_node_id
    modal["cluster_lesson_manager_search"] = ""
    modal["focus"] = None
    modal_scroll = 0.0

def delete_node_cluster(cluster_id):
    NODE_CLUSTER_LIBRARY[:]=[c for c in NODE_CLUSTER_LIBRARY if c.get("id")!=cluster_id];save_node_cluster_library()

# ── Cross-graph node clipboard ──────────────────────────────────────────────
# Stored at module level so Ctrl+C in one graph, Ctrl+V in another works.
_NS_NODE_CLIPBOARD = None   # None | {"nodes": {...}, "links": [...]}

def ns_copy_selected():
    """Copy selected nodes + their internal links to the cross-graph clipboard."""
    ids = ns_selection_ids()
    if not ids:
        push_toast("Nothing selected to copy.", "info", 2.0)
        return
    # A node that's fused/clamped to a partner must bring that partner
    # along, or the copy silently drops the connection between them.
    ids = _ns_expand_selection_with_fusion(ids, modal.get("ns_nodes", {}))
    import copy
    copied_nodes = {nid: copy.deepcopy(modal["ns_nodes"][nid]) for nid in ids if nid in modal.get("ns_nodes", {})}
    copied_links = [
        dict(lnk) for lnk in modal.get("ns_links", [])
        if lnk.get("from") in ids and lnk.get("to") in ids
    ]
    global _NS_NODE_CLIPBOARD
    _NS_NODE_CLIPBOARD = {"nodes": copied_nodes, "links": copied_links}
    push_toast(f"Copied {len(copied_nodes)} node(s) to clipboard.", "success", 2.5)

def ns_paste_clipboard(canvas=None):
    """Paste the clipboard into the current graph, re-mapping IDs and
    offsetting positions so the paste doesn't land exactly on top of the
    originals. Works even when the source graph was a different blueprint."""
    if not _NS_NODE_CLIPBOARD or not _NS_NODE_CLIPBOARD.get("nodes"):
        push_toast("Clipboard is empty — copy some nodes first (Ctrl+C).", "info", 2.5)
        return
    import json
    ns_snapshot()

    # Place pasted nodes in the centre of the current canvas view
    view = modal.get("ns_view", {"pan": [0, 0], "zoom": 1.0})
    z    = view.get("zoom", 1.0)
    if canvas:
        cx = (canvas.width  / 2 - view["pan"][0]) / max(0.01, z)
        cy = (canvas.height / 2 - view["pan"][1]) / max(0.01, z)
    else:
        cx, cy = 0.0, 0.0

    src_nodes = _NS_NODE_CLIPBOARD["nodes"]
    src_links = _NS_NODE_CLIPBOARD["links"]

    # Find bounding box centre of the copied nodes
    xs = [n["x"] for n in src_nodes.values()]
    ys = [n["y"] for n in src_nodes.values()]
    src_cx = (min(xs) + max(xs)) / 2 if xs else 0
    src_cy = (min(ys) + max(ys)) / 2 if ys else 0

    dx = cx - src_cx
    dy = cy - src_cy

    id_map = {}
    new_ids = []
    for old_id, n in src_nodes.items():
        new_id = modal["ns_next_id"]
        modal["ns_next_id"] += 1
        new_node = json.loads(json.dumps(n))
        new_node["id"] = new_id
        new_node["x"]  = n["x"] + dx
        new_node["y"]  = n["y"] + dy
        if modal.get("ns_snap_enabled", False):
            new_node["x"], new_node["y"] = ns_snap_pos(new_node["x"], new_node["y"])
        modal["ns_nodes"][new_id] = new_node
        id_map[old_id] = new_id
        new_ids.append(new_id)

    for lnk in src_links:
        f = id_map.get(lnk.get("from"))
        t = id_map.get(lnk.get("to"))
        if f and t:
            modal["ns_links"].append({
                "from": f, "from_pin": lnk.get("from_pin", ""),
                "to":   t, "to_pin":   lnk.get("to_pin",   ""),
            })

    # Fused/clamped cross-references (clip <-> host, clamp <-> host) were
    # deep-copied verbatim and still point at the OLD ids — repoint them
    # at the freshly pasted ids, or drop them if the partner wasn't part
    # of this paste, so a pasted node never ends up silently wired to an
    # unrelated node in the destination graph.
    for new_id in new_ids:
        _ns_remap_fusion_refs(modal["ns_nodes"][new_id], id_map)

    # Select the pasted nodes
    modal["ns_multi_selected"] = set(new_ids)
    modal["ns_selected"] = new_ids[-1] if new_ids else None
    push_toast(f"Pasted {len(new_ids)} node(s).", "success", 2.5)

def ns_export_graph_to_file():
    """Export the current graph sidecar JSON to any location the user picks."""
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
        path = filedialog.asksaveasfilename(
            title="Export Blueprint Graph",
            defaultextension=".graph.json",
            filetypes=[("Blueprint Graph", "*.graph.json"), ("JSON", "*.json"), ("All files", "*.*")],
            initialfile=(modal.get("script_file") or "blueprint") + ".graph.json",
        )
        root.destroy()
    except Exception as e:
        push_toast(f"File picker failed: {e}", "error"); return
    if not path:
        return
    data = {
        "version": 1,
        "nodes":   modal.get("ns_nodes", {}),
        "links":   modal.get("ns_links", []),
        "next_id": modal.get("ns_next_id", 1),
        "view":    modal.get("ns_view", {"pan": [0, 0], "zoom": 1.0}),
        "wire_style": modal.get("ns_wire_style", "bezier"),
        "wire_anim_mode": modal.get("ns_wire_anim_mode", "flow"),
        "sort_mode": modal.get("ns_sort_mode", "topological"),
        "smart_groups": modal.get("ns_smart_groups", []),
        "bookmarks": modal.get("ns_bookmarks", []),
        "hide_mode": modal.get("ns_hide_mode", "transparent"),
        "script_name": modal.get("script_file") or modal.get("ns_save_name") or "",
    }
    try:
        with open(path, "w") as f:
            json.dump(data, f, indent=2)
        push_toast(f"Graph exported to {os.path.basename(path)}", "success", 4.0)
    except Exception as e:
        push_toast(f"Export failed: {e}", "error")

def ns_export_script_to_file():
    """Export the GENERATED Blueprint script (the Python that vs_build_script_code
    produces) anywhere the user picks, with a choice of file format.

    Unlike Save Blueprint (which writes into the in-app scripts/ folder so the
    game still sees it), this is a pure export: the user chooses the path and the
    extension (.py, .txt, .json, or any other extension via All files), so they
    can drop the generated code into any project or paste it elsewhere.
    """
    nodes = modal.get("ns_nodes", {})
    if not nodes:
        push_toast("Nothing to export — add and connect an Event node first.", "warning")
        return
    errors = validate_graph(nodes, modal.get("ns_links", []))
    if errors:
        modal["ns_show_script"] = True
        modal["ns_right_tab"] = "issues"
        modal["ns_diag_scroll"] = 0
        push_toast(f"Cannot export script: fix {len(errors)} error(s) in the Issues tab.", "error")
        return
    code = vs_build_script_code()
    if code is None:
        push_toast("Cannot export script: add and connect an Event node first.", "error")
        return
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
        _stem = (modal.get("script_file") or "")
        if _stem.lower().endswith(".py"):
            _stem = _stem[:-3]
        _stem = _stem or modal.get("ns_save_name") or "blueprint_script"
        path = filedialog.asksaveasfilename(
            title="Export Generated Script",
            defaultextension=".py",
            initialfile=_stem + ".py",
            filetypes=[
                ("Python script", "*.py"),
                ("Text", "*.txt"),
                ("JSON (source text)", "*.json"),
                ("Markdown", "*.md"),
                ("All files", "*.*"),
            ],
        )
        root.destroy()
    except Exception as e:
        push_toast(f"File picker failed: {e}", "error"); return
    if not path:
        return
    try:
        with open(path, "w", encoding="utf-8") as f:
            f.write(code)
        push_toast(f"Script exported to {os.path.basename(path)}", "success", 4.0)
    except Exception as e:
        push_toast(f"Export failed: {e}", "error")

def ns_import_graph_from_file(merge=False):
    """Import a .graph.json file.
    merge=False  → replaces the current graph entirely (asks to save first)
    merge=True   → merges nodes into the current graph at the canvas centre
    """
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk(); root.withdraw(); root.attributes("-topmost", True)
        path = filedialog.askopenfilename(
            title="Import Blueprint Graph",
            filetypes=[("Blueprint Graph", "*.graph.json"), ("JSON", "*.json"), ("All files", "*.*")],
        )
        root.destroy()
    except Exception as e:
        push_toast(f"File picker failed: {e}", "error"); return
    if not path:
        return
    try:
        with open(path, "r") as f:
            data = json.load(f)
    except Exception as e:
        push_toast(f"Could not read file: {e}", "error"); return

    raw_nodes = {int(k): v for k, v in data.get("nodes", {}).items()}
    raw_links = list(data.get("links", []))

    if not raw_nodes:
        push_toast("That file contains no nodes.", "error"); return

    if merge:
        # Merge: paste the imported nodes into the current graph centre
        global _NS_NODE_CLIPBOARD
        _NS_NODE_CLIPBOARD = {"nodes": raw_nodes, "links": raw_links}
        ns_paste_clipboard(modal.get("_ns_canvas_rect"))
        push_toast(f"Merged {len(raw_nodes)} node(s) from {os.path.basename(path)}", "success", 4.0)
    else:
        # Replace: load as a fresh graph
        ns_snapshot()
        modal["ns_nodes"]   = raw_nodes
        modal["ns_links"]   = raw_links
        modal["ns_next_id"] = int(data.get("next_id", max(raw_nodes.keys(), default=0) + 1))
        modal["ns_view"]    = data.get("view", {"pan": [0.0, 0.0], "zoom": 1.0})
        modal["ns_wire_style"] = _ns_wire_style_key(data.get("wire_style", "bezier"))
        modal["ns_wire_anim_mode"] = data.get("wire_anim_mode", "flow")
        modal["ns_sort_mode"] = data.get("sort_mode", "topological")
        modal["ns_smart_groups"] = data.get("smart_groups", [])
        modal["ns_bookmarks"] = data.get("bookmarks", [])
        modal["ns_hide_mode"] = data.get("hide_mode", modal.get("ns_hide_mode", "transparent"))
        modal["ns_dirty"]   = True
        modal["ns_selected"] = None
        modal["ns_multi_selected"] = set()
        # Suggest the original script name
        suggested = data.get("script_name", "")
        if suggested:
            modal["ns_save_name"] = suggested.replace(".py", "")
        push_toast(f"Imported {len(raw_nodes)} node(s) from {os.path.basename(path)}", "success", 4.0)

def ns_save_as_new_name():
    """Save the current blueprint under a brand-new name (Save As)."""
    name = modal.get("ns_save_name", "").strip()
    if not name:
        push_toast("Type a name in the Save As field first.", "error", 3.0)
        return
    fname = sanitize_script_filename(name)
    if not fname:
        push_toast("Invalid name — use letters, numbers and underscores only.", "error", 3.0)
        return
    existing_path = os.path.join(SCRIPTS_DIR, fname)
    if os.path.isfile(existing_path) and fname != modal.get("script_file"):
        # Already exists under a different script — ask via toast then proceed
        push_toast(f"{fname} already exists — saving will overwrite it.", "info", 4.0)
    result = create_visual_graph_script(name)
    if result:
        modal["script_file"] = result
        modal["ns_save_name"] = result[:-3]
        push_toast(f"Saved as {result}", "success", 4.0)

def create_visual_graph_script(desired_name=None):
    errors = validate_graph(modal.get("ns_nodes", {}), modal.get("ns_links", []))
    if errors:
        modal["ns_show_script"] = True
        modal["ns_right_tab"] = "issues"
        modal["ns_diag_scroll"] = 0
        push_toast(f"Cannot save blueprint: fix {len(errors)} error(s) in the Issues tab.", "error")
        return None
    code = vs_build_script_code()
    if code is None:
        push_toast("Cannot save blueprint: add and connect an Event node first.", "error")
        return None
    os.makedirs(SCRIPTS_DIR, exist_ok=True)
    fname = sanitize_script_filename(desired_name) or f"blueprint_graph_{int(time.time())}.py"
    try:
        compile(code, fname, "exec")
        # Auto-backup the previous version before overwriting
        if os.path.isfile(os.path.join(SCRIPTS_DIR, fname)):
            create_backup(fname)
        with open(os.path.join(SCRIPTS_DIR, fname), "w") as f:
            f.write(code)
        if not save_visual_graph_data(fname):
            return None
        modal["script_file"] = fname
        modal["ns_save_name"] = fname[:-3]
        modal["ns_show_imported_source"] = False
        if current_project_name:
            save_project(current_project_name)
        # Keep character importer in sync: if this script is already assigned
        # to the character being edited, update its param UI so changes show
        if modal.get("_ns_return_to") == "add_character" or modal.get("script_file") == fname:
            if "set_script_params_ui" in dir():
                set_script_params_ui(fname)
        push_toast(f"Saved {fname} (backup created).", "success", 3.0)
        return fname
    except Exception as e:
        print("Visual graph export failed:", e)
        if isinstance(e, SyntaxError):
            try:
                _bad_line_no = int(e.lineno or 0)
                _code_lines = code.splitlines()
                _lo = max(0, _bad_line_no - 3)
                _hi = min(len(_code_lines), _bad_line_no + 2)
                print("Generated source near the error:")
                for _li in range(_lo, _hi):
                    print(f"  {_li + 1:04d}: {_code_lines[_li]}")
                _bad_line = _code_lines[_bad_line_no - 1] if 0 < _bad_line_no <= len(_code_lines) else ""
                _node_match = re.search(r"# _ns_node:(\d+)", _bad_line)
                if _node_match:
                    _bad_node = int(_node_match.group(1))
                    modal["ns_selected"] = _bad_node
                    modal["ns_multi_selected"] = {_bad_node}
                    modal["ns_right_tab"] = "issues"
                    modal["ns_show_script"] = True
                    push_toast(f"Generated syntax error at node {_bad_node}, line {_bad_line_no}. Node selected.", "error", 7.0)
                else:
                    push_toast(f"Generated syntax error at line {_bad_line_no}: {e.msg}", "error", 7.0)
            except Exception:
                push_toast(f"Generated syntax error: {e}", "error", 7.0)
        else:
            push_toast(f"Save failed: {e}", "error", 5.0)
        return None

def request_blueprint_exit(action="return"):
    """Ask whether to save before leaving the graph or closing the app."""
    modal["blueprint_exit_action"] = action  # "return" or "quit"
    modal["type"] = "blueprint_exit_confirm"
    modal["focus"] = None

def finish_blueprint_exit(save_changes):
    global quit_after_project_save
    action = modal.get("blueprint_exit_action")
    if save_changes:
        if not create_visual_graph_script(modal.get("ns_save_name")):
            return
    else:
        # Load from disk over unsaved changes, or clear it if brand new.
        if modal.get("ns_loaded_script"):
            load_visual_graph_data(modal["ns_loaded_script"])
        else:
            reset_visual_graph()
    modal["ns_dirty"] = False

    if action == "quit":
        quit_after_project_save = True
        close_modal()
        request_app_exit()
    else:
        if modal.get("_ns_return_to") == "script_manager":
            modal["type"]   = "script_manager"
            modal["_ns_return_to"] = None
        else:
            _ensure_add_character_fields()
            modal["type"] = "add_character"
        modal["focus"] = None
    modal["blueprint_exit_action"] = "return"

def _ensure_add_character_fields():
    """Hydrate every character field, even when the modal was only partial."""
    fields = modal.setdefault("fields", {})
    # Hydration repairs MISSING keys only. An intentionally blank Name is a
    # valid in-progress edit and must not regenerate the previous/random name.
    name_missing="Name" not in fields
    for _key,_default in FIELD_DEFAULTS.items():fields.setdefault(_key,_default)
    if name_missing and modal.get("editing") is None:fields["Name"]=f"Fighter{random.randint(1,99)}"
    if not modal.get("color") or len(modal.get("color", [])) < 3:
        modal["color"] = list(PALETTE[random.randint(0, len(PALETTE)-1)])

def close_browser():
    global modal_scroll
    modal["type"] = modal.get("_browse_return")
    modal_scroll = 0.0

def close_modal():
    modal.pop("_pm_return_env3d",None);modal.pop("_return_env3d",None);modal.pop("_pm_workspace",None);modal["type"]=None
    modal["focus"] = None
    modal["editing"] = None
    modal["editing_text_index"] = None
    modal["editing_image_index"] = None
    modal.pop("_eh_inspector_modal_key", None)
    modal.pop("_e3d_uv_tool", None)

PROJECTS_DIR = os.path.join(BASE_DIR, "projects")
PROJ_THUMBS_DIR = os.path.join(PROJECTS_DIR, "_thumbs")
os.makedirs(PROJECTS_DIR, exist_ok=True)
os.makedirs(PROJ_THUMBS_DIR, exist_ok=True)

def _project_workspace_key():
    """Arena Studio is 2D-only."""
    return "arena2d"

def projects_dir(ws=None):
    ws = ws or _project_workspace_key()
    d = PROJECTS_DIR
    os.makedirs(d, exist_ok=True)
    return d

def proj_thumbs_dir(ws=None):
    d = os.path.join(projects_dir(ws), "_thumbs")
    os.makedirs(d, exist_ok=True)
    return d

current_project_name = None          # name of currently loaded project
quit_after_project_save = False
recent_projects = []                 # list of recently opened project names
project_rows = []                    # project manager hit targets

_proj_thumb_cache = {}               # name → pygame.Surface or None
_last_auto_thumb_time = 0.0          # epoch of last auto-screenshot
_AUTO_THUMB_INTERVAL = 120.0         # seconds between auto-captures

def get_project_path(name, ws=None):
    return os.path.join(projects_dir(ws), f"{name}.json")

def get_project_thumb_path(name, ws=None):
    """PNG thumbnail path for a project."""
    safe = "".join(c if (c.isalnum() or c in "-_ ") else "_" for c in name)
    return os.path.join(proj_thumbs_dir(ws), f"{safe}.png")

def capture_project_thumbnail(name=None):
    """Screenshot the arena canvas and save as project thumbnail.
    Uses current_project_name if name is None."""
    global _proj_thumb_cache
    tgt = name or current_project_name
    if not tgt:
        return
    try:
        snap = screen.copy()
        # Scale down to 400×225 (16:9) for a compact thumbnail
        thumb = pygame.transform.smoothscale(snap, (400, 225))
        path = get_project_thumb_path(tgt)
        pygame.image.save(thumb, path)
        _proj_thumb_cache[_project_workspace_key() + "::" + tgt] = thumb
    except Exception:
        pass

def load_project_thumbnail(name):
    """Load (and cache) the thumbnail surface for a project, or return None."""
    key = _project_workspace_key() + "::" + str(name)
    if key in _proj_thumb_cache:
        return _proj_thumb_cache[key]
    path = get_project_thumb_path(name)
    surf = None
    if os.path.isfile(path):
        try:
            surf = pygame.image.load(path).convert()
        except Exception:
            surf = None
    _proj_thumb_cache[key] = surf
    return surf

def list_projects():
    """Returns list of (name, mtime) tuples sorted by most recent.
    Scoped to the active workspace so 2D and 3D shelves never mix."""
    projects = []
    root = projects_dir()
    if not os.path.isdir(root):
        return projects
    skip = {"model_library"}
    for f in os.listdir(root):
        if not f.endswith(".json"):
            continue
        name = f[:-5]
        if name.startswith("_") or name.lower() in skip:
            continue
        try:
            mtime = os.path.getmtime(get_project_path(name))
            projects.append((name, mtime))
        except Exception:
            pass
    projects.sort(key=lambda x: x[1], reverse=True)
    return projects

def load_recent_projects():
    global recent_projects
    recent_projects = [p[0] for p in list_projects()[:8]]

def sanitize_project_name(name):
    """File-system safe project name with the visible name preserved enough for the UI."""
    name = (name or "").strip()
    keep = []
    for ch in name:
        keep.append(ch if ch.isalnum() or ch in (" ", "-", "_") else "_")
    cleaned = "".join(keep).strip(" ._")
    return cleaned[:60] or "Untitled Project"

def get_project_asset_dir(name):
    return os.path.join(projects_dir(), "_assets", sanitize_project_name(name))

def rel_to_base(path):
    try:
        return os.path.relpath(path, BASE_DIR).replace(os.sep, "/")
    except Exception:
        return path

def abs_from_base(path):
    if not path:
        return None
    if os.path.isabs(path):
        return path
    return os.path.join(BASE_DIR, path.replace("/", os.sep))

# Startup prune: the audio library registry is loaded before abs_from_base
# exists (import order), so stale entries are cleaned here once, at runtime.
try:
    _prune_audio_library()
except Exception:
    pass

def _character_center_value(source):
    """Return a safe normalized [x,y] sprite pivot."""
    try:
        raw=(source.get("character_center") if isinstance(source,dict) else source) or [0.5,0.5]
        return [max(0.0,min(1.0,float(raw[0]))),max(0.0,min(1.0,float(raw[1])))]
    except Exception:
        return [0.5,0.5]

