def ensure_scene_image_asset(img, project_name, index):
    """Copy or export a scene image into projects/_assets/<project>/ and return a BASE_DIR-relative path."""
    asset_dir = get_project_asset_dir(project_name)
    os.makedirs(asset_dir, exist_ok=True)
    src = img.get("source_path") or img.get("image_path")
    src_abs = abs_from_base(src) if src else None
    ext = os.path.splitext(src_abs or "")[1].lower() if src_abs else ".png"
    if ext not in (".png", ".jpg", ".jpeg", ".bmp", ".gif"):
        ext = ".png"
    dest = os.path.join(asset_dir, f"scene_image_{index}{ext}")
    try:
        if src_abs and os.path.isfile(src_abs):
            if os.path.abspath(src_abs) != os.path.abspath(dest):
                shutil.copyfile(src_abs, dest)
        elif img.get("image"):
            # Fall back to exporting the already-loaded surface as a PNG.
            dest = os.path.join(asset_dir, f"scene_image_{index}.png")
            pygame.image.save(img["image"], dest)
        else:
            return None
        return rel_to_base(dest)
    except Exception as e:
        print("Could not persist scene image:", e)
        return rel_to_base(src_abs) if src_abs else None

def scene_image_from_data(data):
    path = data.get("image_path") or data.get("source_path")
    full = abs_from_base(path)
    surf = None
    if full and os.path.isfile(full):
        try:
            surf = pygame.image.load(full).convert_alpha()
        except Exception as e:
            print("Could not load scene image:", e)
    if surf is None:
        return None
    return {
        "image": surf,
        "source_path": full,
        "image_path": path,
        "fx": data.get("fx", 0.5), "fy": data.get("fy", 0.5),
        "wx": data.get("wx"), "wy": data.get("wy"),
        "scale": data.get("scale", 1.0),
        "alpha": data.get("alpha", 255),
        "pixel_perfect": bool(data.get("pixel_perfect", False)),
        "layer": data.get("layer", "front"),
        "depth": data.get("depth", 0),
        "z_index": int(data.get("z_index",data.get("depth",0)) or 0),
        "hierarchy_parent": data.get("hierarchy_parent"),
        "visible": bool(data.get("visible",True)),
        "rotation": data.get("rotation", 0),
        "flip_x": bool(data.get("flip_x", False)),
        "flip_y": bool(data.get("flip_y", False)),
        "world_space": data.get("world_space", False),
        "camera_locked": data.get("camera_locked", False),
        "scale_with_zoom": data.get("scale_with_zoom", False),
        "scale_with_frame": data.get("scale_with_frame", False),
        "anchor_x": data.get("anchor_x", 0.5),
        "anchor_y": data.get("anchor_y", 0.5),
        "locked": bool(data.get("locked", False)),
        "vcam_only": bool(data.get("vcam_only", False)),
        "opacity": data.get("opacity", 255),
        "parallax_x": float(data.get("parallax_x", 1.0)),
        "parallax_y": float(data.get("parallax_y", 1.0)),
        "arena_clip": data.get("arena_clip", None),
        "blend": data.get("blend", "normal"),
        "splice": data.get("splice") or {"enabled": False, "axis": "v", "pos": 0.5, "keep": "start"},
        "shadow": data.get("shadow") or {"enabled": False, "offset_x": 6, "offset_y": 6, "color": [0, 0, 0],
                                          "alpha": 160, "use_main_splice": True,
                                          "splice": {"enabled": False, "axis": "v", "pos": 0.5, "keep": "start"}},
        "_rect": None,
    }

_ASSET_DEP_EXTS={".png",".jpg",".jpeg",".webp",".gif",".bmp",".wav",".ogg",".mp3",".flac",".aac",".m4a",".opus",".mp4",".webm",".ttf",".otf",".py"}
_ASSET_DEP_SKIP_KEYS={"script_ns","image","_surface","_surf","_cache","_particles","_audio_channel","_channel"}


def _ad_kind(path):
    ext=os.path.splitext(str(path).lower())[1]
    if ext in (".png",".jpg",".jpeg",".webp",".gif",".bmp"):return "Image"
    if ext in (".wav",".ogg",".mp3",".flac",".aac",".m4a",".opus"):return "Audio"
    if ext in (".mp4",".webm"):return "Video"
    if ext in (".ttf",".otf"):return "Font"
    if ext==".py":return "Script"
    return "Asset"


def _ad_is_asset_value(value):
    if not isinstance(value,str) or not value or len(value)>1200 or value.startswith(("http://","https://","data:")):return False
    clean=value.split("?",1)[0].split("#",1)[0]
    return os.path.splitext(clean)[1].lower() in _ASSET_DEP_EXTS


def _ad_resolve(raw,base_dir=None):
    raw=os.path.expandvars(os.path.expanduser(str(raw).strip().strip('"')));norm=raw.replace("\\","/");candidates=[]
    if os.path.isabs(raw):candidates.append(raw)
    if base_dir:candidates.append(os.path.join(base_dir,raw))
    candidates.extend((os.path.join(BASE_DIR,raw),os.path.join(SPRITES_DIR,raw),os.path.join(AUDIO_DIR,raw),os.path.join(SCRIPTS_DIR,raw)))
    if norm.startswith("sprites/"):candidates.insert(0,os.path.join(BASE_DIR,*norm.split("/")))
    elif norm.startswith("audio/"):candidates.insert(0,os.path.join(BASE_DIR,*norm.split("/")))
    elif norm.startswith("scripts/"):candidates.insert(0,os.path.join(BASE_DIR,*norm.split("/")))
    for candidate in candidates:
        full=os.path.abspath(candidate)
        if os.path.isfile(full):return full
    return os.path.abspath(candidates[0] if candidates else raw)


def _ad_inside_base(path):
    try:return os.path.commonpath((os.path.abspath(path),os.path.abspath(BASE_DIR)))==os.path.abspath(BASE_DIR)
    except Exception:return False


def _ad_add_ref(index,raw,scope,container,key,trail,base_dir=None,project_file=None):
    full=_ad_resolve(raw,base_dir);canon=os.path.normcase(os.path.abspath(full));entry=index.setdefault(canon,{"key":canon,"path":full,"raw":str(raw),"kind":_ad_kind(raw),"refs":[],"exists":os.path.isfile(full),"size":0,"mtime":0.0,"duplicate":None,"inventory":False})
    entry["refs"].append({"scope":scope,"container":container,"key":key,"trail":trail,"project":project_file,"original":str(raw)})


def _ad_walk(value,scope,index,trail="",base_dir=None,project_file=None,seen=None,depth=0):
    if depth>14:return
    if seen is None:seen=set()
    if isinstance(value,(dict,list)):
        ident=id(value)
        if ident in seen:return
        seen.add(ident)
    if isinstance(value,dict):
        for key,item in value.items():
            if str(key) in _ASSET_DEP_SKIP_KEYS:continue
            sub=f"{trail}.{key}" if trail else str(key)
            if _ad_is_asset_value(item):_ad_add_ref(index,item,scope,value,key,sub,base_dir,project_file)
            elif isinstance(item,(dict,list,tuple)):_ad_walk(item,scope,index,sub,base_dir,project_file,seen,depth+1)
    elif isinstance(value,(list,tuple)):
        for i,item in enumerate(value):
            sub=f"{trail}[{i}]"
            if _ad_is_asset_value(item):_ad_add_ref(index,item,scope,value,i,sub,base_dir,project_file)
            elif isinstance(item,(dict,list,tuple)):_ad_walk(item,scope,index,sub,base_dir,project_file,seen,depth+1)


def _ad_file_sha1(path):
    h=hashlib.sha1()
    try:
        with open(path,"rb") as f:
            while True:
                chunk=f.read(1024*1024)
                if not chunk:break
                h.update(chunk)
        return h.hexdigest()
    except Exception:return None


def scan_asset_dependencies(show_toast=False):
    index={};docs={}
    live_roots=(("Current Scene",external_nodes),("Scene Text",scene_texts),("Scene Images",scene_images),("Characters",characters),("Particle Emitters",particle_emitters),("Entity Library",LIBRARY),("Character Vault",CHAR_VAULT),("Motion Clips",MOTION_CLIPS),("Animations",ANIMATION_LIBRARY),("Audio Library",AUDIO_LIBRARY))
    for scope,root in live_roots:_ad_walk(root,scope,index)
    try:
        for fn in os.listdir(PROJECTS_DIR):
            if not fn.lower().endswith(".json"):continue
            path=os.path.join(PROJECTS_DIR,fn)
            try:
                with open(path,"r",encoding="utf-8") as f:data=json.load(f)
                docs[path]=data;_ad_walk(data,f"Project · {fn[:-5]}",index,base_dir=os.path.dirname(path),project_file=path)
            except Exception:continue
    except Exception:pass
    roots=[]
    for root in (SPRITES_DIR,AUDIO_DIR,SCRIPTS_DIR,os.path.join(PROJECTS_DIR,"_assets"),os.path.join(BASE_DIR,"fonts")):
        if os.path.isdir(root) and root not in roots:roots.append(root)
    for root in roots:
        for dirpath,dirs,files in os.walk(root):
            dirs[:]=[d for d in dirs if d not in ("__pycache__","_ui_cache","_icon_cache")]
            for fn in files:
                full=os.path.abspath(os.path.join(dirpath,fn))
                if os.path.splitext(fn)[1].lower() not in _ASSET_DEP_EXTS:continue
                canon=os.path.normcase(full);entry=index.setdefault(canon,{"key":canon,"path":full,"raw":rel_to_base(full),"kind":_ad_kind(full),"refs":[],"exists":True,"size":0,"mtime":0.0,"duplicate":None,"inventory":True});entry["inventory"]=True
    for entry in index.values():
        entry["exists"]=os.path.isfile(entry["path"])
        if entry["exists"]:
            try:entry["size"]=os.path.getsize(entry["path"]);entry["mtime"]=os.path.getmtime(entry["path"])
            except Exception:pass
        entry["external"]=bool(entry["exists"] and not _ad_inside_base(entry["path"]));entry["unused"]=bool(entry["inventory"] and not entry["refs"])
    by_size={}
    for entry in index.values():
        if entry["exists"] and entry["size"]>0:by_size.setdefault(entry["size"],[]).append(entry)
    for size_group in by_size.values():
        if len(size_group)<2:continue
        by_hash={}
        for entry in size_group:
            digest=_ad_file_sha1(entry["path"])
            if digest:by_hash.setdefault(digest,[]).append(entry)
        for digest,group in by_hash.items():
            if len(group)>1:
                for entry in group:entry["duplicate"]=digest
    assets=sorted(index.values(),key=lambda e:(0 if not e["exists"] else 1,0 if e["refs"] else 1,e["kind"],os.path.basename(e["path"]).lower()))
    modal["_ad_assets"]=assets;modal["_ad_docs"]=docs;modal["_ad_scan_time"]=time.time();modal["_ad_scroll"]=0.0;modal["_ad_usage_scroll"]=0.0
    if modal.get("_ad_selected") not in {e["key"] for e in assets}:modal["_ad_selected"]=assets[0]["key"] if assets else None
    if show_toast:
        missing=sum(not e["exists"] for e in assets);unused=sum(e["unused"] for e in assets);push_toast(f"Dependency scan complete · {len(assets)} assets · {missing} missing · {unused} unused","success",3.5)
    return assets


def _ad_reference_value(new_abs,original):
    original=str(original);base=None
    ext=os.path.splitext(new_abs)[1].lower()
    if "/" not in original.replace("\\","/"):
        if ext==".py":base=SCRIPTS_DIR
        elif ext in (".wav",".ogg",".mp3",".flac",".aac",".m4a",".opus"):base=AUDIO_DIR
        else:base=SPRITES_DIR
    try:
        if base and os.path.commonpath((new_abs,base))==os.path.abspath(base):return os.path.relpath(new_abs,base).replace(os.sep,"/")
    except Exception:pass
    return rel_to_base(new_abs) if _ad_inside_base(new_abs) else os.path.abspath(new_abs)


def _ad_flush_changes(changed_projects):
    for path in changed_projects:
        data=modal.get("_ad_docs",{}).get(path)
        if data is None:continue
        try:
            tmp=path+".tmp"
            with open(tmp,"w",encoding="utf-8") as f:f.write(json.dumps(data,indent=2))
            os.replace(tmp,path)
        except Exception as exc:push_toast(f"Could not update {os.path.basename(path)} · {exc}","error",5)
    for fn in (save_motion_clips,save_animation_library,save_library,save_character_vault,save_audio_library):
        try:fn()
        except Exception:pass
    try:en_tag_index_rebuild();scene_proxy_invalidate();invalidate_sprite_asset_cache()
    except Exception:pass


def _ad_replace_entry(entry,new_abs,flush=True):
    changed=set();count=0
    for ref in list(entry.get("refs",[])):
        try:ref["container"][ref["key"]]=_ad_reference_value(new_abs,ref.get("original",""));count+=1
        except Exception:continue
        if ref.get("project"):changed.add(ref["project"])
    if flush:_ad_flush_changes(changed);scan_asset_dependencies(False)
    return count,changed


def _ad_pick_replacement():
    entry=next((e for e in modal.get("_ad_assets",[]) if e["key"]==modal.get("_ad_selected")),None)
    if not entry:return
    try:
        import tkinter as tk
        from tkinter import filedialog
        root=tk.Tk();root.withdraw();root.attributes("-topmost",True);picked=filedialog.askopenfilename(title=f"Replace {os.path.basename(entry['path'])}");root.destroy()
    except Exception as exc:picked="";push_toast(f"File picker failed · {exc}","error")
    if picked:
        count,_=_ad_replace_entry(entry,os.path.abspath(picked),True);push_toast(f"Replaced {count} reference(s)","success",3)


def _ad_relink_missing_folder():
    try:
        import tkinter as tk
        from tkinter import filedialog
        root=tk.Tk();root.withdraw();root.attributes("-topmost",True);folder=filedialog.askdirectory(title="Search folder for missing assets");root.destroy()
    except Exception as exc:folder="";push_toast(f"Folder picker failed · {exc}","error")
    if not folder:return
    names={}
    for dp,_ds,files in os.walk(folder):
        for fn in files:names.setdefault(fn.lower(),[]).append(os.path.join(dp,fn))
    total=0;projects=set()
    for entry in list(modal.get("_ad_assets",[])):
        if entry["exists"]:continue
        hits=names.get(os.path.basename(entry["path"]).lower(),[])
        if len(hits)==1:
            count,changed=_ad_replace_entry(entry,os.path.abspath(hits[0]),False);total+=count;projects|=changed
    _ad_flush_changes(projects);scan_asset_dependencies(False);push_toast(f"Relinked {total} missing reference(s)","success" if total else "warning",4)


def _ad_pack_external():
    targets=[e for e in modal.get("_ad_assets",[]) if e.get("external") and e.get("refs")]
    if not targets:push_toast("No referenced external assets to pack","info",2);return
    dest=os.path.join(get_project_asset_dir(current_project_name or "Untitled Project"),"dependencies");os.makedirs(dest,exist_ok=True);projects=set();total=0
    for entry in targets:
        base=os.path.basename(entry["path"]);out=os.path.join(dest,base);stem,ext=os.path.splitext(base);n=2
        while os.path.exists(out) and os.path.normcase(out)!=os.path.normcase(entry["path"]):out=os.path.join(dest,f"{stem}_{n}{ext}");n+=1
        try:shutil.copy2(entry["path"],out)
        except Exception:continue
        count,changed=_ad_replace_entry(entry,out,False);total+=count;projects|=changed
    _ad_flush_changes(projects);scan_asset_dependencies(False);push_toast(f"Packed {len(targets)} asset(s) · rewired {total} reference(s)","success",4)


def _ad_consolidate_duplicate():
    entry=next((e for e in modal.get("_ad_assets",[]) if e["key"]==modal.get("_ad_selected")),None)
    if not entry or not entry.get("duplicate"):return
    group=[e for e in modal.get("_ad_assets",[]) if e.get("duplicate")==entry["duplicate"] and e["key"]!=entry["key"]]
    if not group:return
    target=max(group,key=lambda e:len(e.get("refs",[])));count,_=_ad_replace_entry(entry,target["path"],True);push_toast(f"Consolidated {count} reference(s) into {os.path.basename(target['path'])}","success",4)


def _ad_reveal_selected():
    entry=next((e for e in modal.get("_ad_assets",[]) if e["key"]==modal.get("_ad_selected")),None)
    if not entry:return
    path=entry["path"]
    try:
        if sys.platform.startswith("win"):subprocess.Popen(["explorer","/select,",os.path.normpath(path)])
        elif sys.platform=="darwin":subprocess.Popen(["open","-R",path])
        else:subprocess.Popen(["xdg-open",os.path.dirname(path)])
    except Exception as exc:push_toast(f"Reveal failed · {exc}","error")


def _ad_filtered_assets():
    query=str(modal.get("_ad_search","") or "").strip().lower();flt=str(modal.get("_ad_filter","all"));out=[]
    for e in modal.get("_ad_assets",[]):
        if query and query not in e["path"].lower() and not any(query in r["scope"].lower() or query in r["trail"].lower() for r in e["refs"]):continue
        if flt=="missing" and e["exists"]:continue
        if flt=="unused" and not e["unused"]:continue
        if flt=="duplicates" and not e.get("duplicate"):continue
        if flt=="external" and not e.get("external"):continue
        out.append(e)
    return out


