def _scene_clear_counts():
    return {
        "characters":sum(1 for c in characters if not c.get("is_scene_prop")),
        "props":sum(1 for c in characters if c.get("is_scene_prop") and not c.get("scene_director")),
        "directors":sum(1 for c in characters if c.get("scene_director")),
        "projectiles":len(_WEAPON_PROJECTILES),"particles":len(particle_emitters)+len(particles),
        "scene_nodes":len(external_nodes)+len(scene_texts)+len(scene_images)+len(scene_groups),
        "effects":len(world_effects)+len(area_zones)+len(popups)+len(pheromone_markers),
        "scene_painter":len(scene_blocks),"debug":len(scene_debug_buttons),
    }


def open_clear_scene_menu():
    if not any(_scene_clear_counts().values()):push_toast("The scene is already empty","info",1.8);return
    modal["type"]="clear_scene_menu";modal["focus"]=None;modal["_clear_scene_rects"]=[]


def open_clear_scene_confirm(category):
    category=str(category);counts=_scene_clear_counts();count=sum(counts.values()) if category=="all" else counts.get(category,0)
    if count<=0:push_toast("That category is already empty","info",1.8);return False
    modal["type"]="clear_scene_confirm";modal["focus"]=None;modal["_clear_scene_pending"]=category;modal["_clear_scene_pending_count"]=count
    return True


def clear_scene_category(category):
    global simulation_started,game_over,winner
    category=str(category);counts=_scene_clear_counts();expected=sum(counts.values()) if category=="all" else counts.get(category,0);removed=0
    if expected<=0:return 0
    if is_recording:stop_recording()
    if not scene_undo_push(f"Clear {category.replace('_',' ').title()}",include_clear_state=True):
        push_toast("Clear canceled because an undo snapshot could not be created","error",5.0);return 0
    if category in ("all","characters"):
        before=len(characters);characters[:]=[c for c in characters if c.get("is_scene_prop")] if category!="all" else [];removed+=before-len(characters)
    if category=="props":
        before=len(characters);characters[:]=[c for c in characters if not (c.get("is_scene_prop") and not c.get("scene_director"))];removed+=before-len(characters)
    if category=="directors":
        before=len(characters);characters[:]=[c for c in characters if not c.get("scene_director")];removed+=before-len(characters)
    if category in ("all","projectiles"):removed+=len(_WEAPON_PROJECTILES);clear_weapon_projectiles()
    if category in ("all","particles"):
        removed+=len(particle_emitters)+len(particles);particle_emitters.clear();particles.clear()
    if category in ("all","scene_nodes"):
        removed+=len(external_nodes)+len(scene_texts)+len(scene_images)+len(scene_groups);external_nodes.clear();scene_texts.clear();scene_images.clear();scene_groups.clear();modal["_eh_selected"]=None;scene_proxy_invalidate()
    if category in ("all","effects"):
        removed+=len(world_effects)+len(area_zones)+len(popups)+len(pheromone_markers);world_effects.clear();area_zones.clear();popups.clear();pheromone_markers.clear()
    if category in ("all","scene_painter"):removed+=len(scene_blocks);scene_blocks.clear()
    if category in ("all","debug"):removed+=len(scene_debug_buttons);scene_debug_buttons.clear();scene_debug_window_positions.clear()
    if camera.get("target") not in characters:camera["target"]=None
    if category in ("all","characters"):simulation_started=False;game_over=False;winner=None
    try:en_tag_index_rebuild()
    except Exception:pass
    push_toast(f"Cleared {category.replace('_',' ')} · {removed} item(s) · Ctrl+Z to undo","success",4.0);return removed


