def rewrite_project_asset_refs(project_name, old_name):
    """After copy/rename, make scene-image JSON point at the new asset folder."""
    path = get_project_path(project_name)
    try:
        with open(path, "r") as f:
            data = json.load(f)
        old_rel = rel_to_base(get_project_asset_dir(old_name)).rstrip("/") + "/"
        new_rel = rel_to_base(get_project_asset_dir(project_name)).rstrip("/") + "/"
        changed = False
        for img in data.get("scene_images", []):
            for key in ("image_path", "source_path"):
                val = img.get(key)
                if isinstance(val, str) and val.startswith(old_rel):
                    img[key] = new_rel + val[len(old_rel):]
                    changed = True
        if changed:
            with open(path, "w") as f:
                json.dump(data, f, indent=2)
    except Exception as e:
        print("Could not rewrite copied project asset paths:", e)

def delete_project(name):
    global current_project_name
    path = get_project_path(name)
    try:
        if os.path.isfile(path):
            os.remove(path)
        asset_dir = get_project_asset_dir(name)
        if os.path.isdir(asset_dir):
            shutil.rmtree(asset_dir, ignore_errors=True)
        if current_project_name == name:
            current_project_name = None
        load_recent_projects()
        return True
    except Exception as e:
        print("Delete project failed:", e)
        return False

def duplicate_project(src_name, dst_name):
    dst_name = sanitize_project_name(dst_name)
    src = get_project_path(src_name)
    dst = get_project_path(dst_name)
    if not os.path.isfile(src):
        return False
    if os.path.exists(dst):
        stem = dst_name
        n = 2
        while os.path.exists(get_project_path(f"{stem} {n}")):
            n += 1
        dst_name = f"{stem} {n}"
        dst = get_project_path(dst_name)
    try:
        shutil.copyfile(src, dst)
        src_assets = get_project_asset_dir(src_name)
        dst_assets = get_project_asset_dir(dst_name)
        if os.path.isdir(src_assets):
            if os.path.isdir(dst_assets):
                shutil.rmtree(dst_assets, ignore_errors=True)
            shutil.copytree(src_assets, dst_assets)
        rewrite_project_asset_refs(dst_name, src_name)
        load_recent_projects()
        return True
    except Exception as e:
        print("Copy project failed:", e)
        return False

def rename_project(old_name, new_name):
    global current_project_name
    new_name = sanitize_project_name(new_name)
    old = get_project_path(old_name)
    new = get_project_path(new_name)
    if not os.path.isfile(old) or old_name == new_name:
        return False
    if os.path.exists(new):
        print("Rename failed: target already exists")
        return False
    try:
        os.rename(old, new)
        old_assets = get_project_asset_dir(old_name)
        new_assets = get_project_asset_dir(new_name)
        if os.path.isdir(old_assets):
            os.makedirs(os.path.dirname(new_assets), exist_ok=True)
            if os.path.isdir(new_assets):
                shutil.rmtree(new_assets, ignore_errors=True)
            os.rename(old_assets, new_assets)
        rewrite_project_asset_refs(new_name, old_name)
        if current_project_name == old_name:
            current_project_name = new_name
        load_recent_projects()
        return True
    except Exception as e:
        print("Rename project failed:", e)
        return False

