def _json_clean_data(obj):
    """Recursively converts Pygame objects (Vector2, Rect, Color), tuples, sets,
    and numpy types into JSON-serializable primitives, skipping callables and Surfaces."""
    if obj is None or isinstance(obj, (int, float, str, bool)):
        return obj
    if hasattr(obj, "x") and hasattr(obj, "y") and not isinstance(obj, dict):
        try:
            return [float(obj.x), float(obj.y)]
        except Exception:
            pass
    if hasattr(obj, "r") and hasattr(obj, "g") and hasattr(obj, "b"):
        try:
            return [int(obj.r), int(obj.g), int(obj.b), int(getattr(obj, "a", 255))]
        except Exception:
            pass
    if isinstance(obj, (list, tuple, set)):
        return [_json_clean_data(v) for v in obj if not callable(v) and "Surface" not in type(v).__name__]
    if isinstance(obj, dict):
        res = {}
        for k, v in obj.items():
            if callable(v) or "Surface" in type(v).__name__:
                continue
            if isinstance(k, (tuple, list)):
                sk = ",".join(str(x) for x in k)
            else:
                sk = str(k)
            if sk in ("_rect", "_surface", "_cached_surf", "_cached_rect", "_text_surf"):
                continue
            res[sk] = _json_clean_data(v)
        return res
    # NumPy arrays expose both item() and tolist(). item() only works for a
    # scalar/size-1 array, so arrays from live rigging state must use tolist()
    # first or project saves fail with "can only convert an array of size 1".
    if hasattr(obj, "tolist"):
        try:return _json_clean_data(obj.tolist())
        except Exception:pass
    if hasattr(obj, "item"):
        try:return _json_clean_data(obj.item())
        except Exception:pass
    return str(obj)

def _build_project_payload(name):
    """Serialize the entire live project to a plain dict.

    Split out of save_project() so the autosave path can produce a byte-for-byte
    identical payload without inheriting any of save_project()'s user-facing
    side effects (naming dialog, toasts, thumbnail invalidation, recent list).
    A recovery file is therefore a real, fully-loadable project rather than a
    reduced snapshot that only mostly restores.
    """
    # Round 15: a project save must capture the F9 studio + F8 easing work too.
    # Load the sidecar stores first so an unsaved session never snapshots empty.
    try:
        if not MOTION_CLIPS_LOADED:
            load_motion_clips()
        if not CUSTOM_EASE_LOADED:
            load_easing_curves()
        if not SPRITE_FOLDERS_LOADED:
            load_sprite_folders()
    except Exception:
        pass


    ensure_scene_item_ids()
    data = {
        "version": 4,
        "characters": [serialize_character(c) for c in characters],
        "library": [serialize_template(t) for t in LIBRARY],
        "scene_texts": [],
        "scene_images": [],
        "scene_hierarchy": {},
        "scene_hierarchy_collapsed": sorted(str(k) for k in modal.get("_eh_collapsed",set())),
        "settings": SETTINGS.copy(),
        "camera": {"pos": list(camera["pos"]), "zoom": camera["zoom"], "zoom_target": camera["zoom_target"],
                   "smart_follow": bool(camera.get("smart_follow", False)),
                   "smart_follow_mode": camera.get("smart_follow_mode", "centroid"),
                   "smart_follow_scope": camera.get("smart_follow_scope", "combat"),
                   "smart_follow_include_dead": bool(camera.get("smart_follow_include_dead", False)),
                   "smart_follow_padding": float(camera.get("smart_follow_padding", 0.12)),
                   "smart_follow_min_zoom": float(camera.get("smart_follow_min_zoom", 0.4)),
                   "smart_follow_max_zoom": float(camera.get("smart_follow_max_zoom", 2.5)),
                   "smart_follow_target": camera.get("smart_follow_target"),
                   "smart_follow_auto_zoom": bool(camera.get("smart_follow_auto_zoom", False))},
        "camera_bounds": {"enabled":bool(CAMERA_BOUNDS.get("enabled",False)),"rect":list(CAMERA_BOUNDS.get("rect",[-600,-340,600,340])),"mode":str(CAMERA_BOUNDS.get("mode","both")),"ease_distance":float(CAMERA_BOUNDS.get("ease_distance",180.0)),"ease_strength":float(CAMERA_BOUNDS.get("ease_strength",1.0)),"show_gizmo":bool(CAMERA_BOUNDS.get("show_gizmo",True))},
        "bg_color": list(bg_color),
        "box_scale": box_scale,
        "box_thickness": box_thickness,
        "show_shadows": show_shadows,
        "movement_smoothing": movement_smoothing,
        "win_condition": win_condition,
        "time_limit": time_limit,
        "kill_limit": kill_limit,
        "record_enabled": record_enabled,
        "record_name": record_name,
        "record_width": record_width,
        "record_height": record_height,
        "record_fps": record_fps,
        "record_gpu_output_profile": record_gpu_output_profile,
        "record_gpu_source_profile": record_gpu_source_profile,
        "record_gpu_source_profile_version": 3,
        "record_mode": record_mode,
        "record_png_mode": record_png_mode,
        "record_auto_render_interpolated": record_auto_render_interpolated,
        "record_countdown_visible": record_countdown_visible,
        "countdown_duration": countdown_duration,
        "global_audio_map": dict(GLOBAL_AUDIO_MAP),
        "global_audio_volume_map": dict(GLOBAL_AUDIO_VOLUME_MAP),
        "virtual_camera": {
            "enabled": bool(virtual_camera.get("enabled", False)),
            "preview": bool(virtual_camera.get("preview", False)),
            "aspect": virtual_camera.get("aspect", "16:9"),
            "pos": list(virtual_camera.get("pos", pygame.Vector2(0,0))),
            "zoom": float(virtual_camera.get("zoom", 1.0)),
            "follow_name": virtual_camera.get("follow_name"),
            "follow_live_camera": bool(virtual_camera.get("follow_live_camera", virtual_camera.get("follow_name") is None)),
            "pan_offset": list(virtual_camera.get("pan_offset", pygame.Vector2(0, 0))),
            "show_frame": bool(virtual_camera.get("show_frame", True)),
            "follow_smoothing": float(virtual_camera.get("follow_smoothing", 1.0)),
            "swap_on_death": bool(virtual_camera.get("swap_on_death", True)),
            "show_safe_area": bool(virtual_camera.get("show_safe_area", True)),
            "speed": float(virtual_camera.get("speed", 4.0)),
            "drag": float(virtual_camera.get("drag", 3.0)),
            "smart_follow": bool(virtual_camera.get("smart_follow", False)),
            "smart_follow_mode": virtual_camera.get("smart_follow_mode", "centroid"),
            "smart_follow_scope": virtual_camera.get("smart_follow_scope", "combat"),
            "smart_follow_include_dead": bool(virtual_camera.get("smart_follow_include_dead", False)),
            "smart_follow_padding": float(virtual_camera.get("smart_follow_padding", 0.12)),
            "smart_follow_min_zoom": float(virtual_camera.get("smart_follow_min_zoom", 0.4)),
            "smart_follow_max_zoom": float(virtual_camera.get("smart_follow_max_zoom", 2.5)),
            "smart_follow_target": virtual_camera.get("smart_follow_target"),
            "smart_follow_auto_zoom": bool(virtual_camera.get("smart_follow_auto_zoom", False)),
        },
        # Project snapshots also include the animation library and UI/editor
        # preferences, not just the playable arena.
        "animation_library": json.loads(json.dumps(ANIMATION_LIBRARY)),
        # Round 15: motion clips, custom easing curves, and sprite folder
        # organization travel INSIDE the project file now.
        "motion_clips": json.loads(json.dumps(MOTION_CLIPS)),
        "easing_curves": json.loads(json.dumps(CUSTOM_EASE_CURVES)),
        "sprite_folders": dict(SPRITE_FOLDERS),
        "ui_preferences": _project_ui_snapshot(),
    }

    for t in scene_texts:
        data["scene_texts"].append({
            "text": t.get("text", ""), "size": t.get("size", 28), "color": list(t.get("color", (255,255,255))),
                        "outline": t.get("outline", True), "layer": t.get("layer", "front"),
            "depth": t.get("depth", 0),
            "z_index": scene_hierarchy_local_z(t),
            "hierarchy_parent": t.get("hierarchy_parent"),
            "visible": bool(t.get("visible",True)),
            "fx": t.get("fx", 0.5), "fy": t.get("fy", 0.5),
            "world_space": t.get("world_space", False),
            "camera_locked": t.get("camera_locked", False),
            "wx": t.get("wx"), "wy": t.get("wy"),
            "shake_level": t.get("shake_level", 0.0),
            "shake_freq": t.get("shake_freq", 1.0),
            "per_letter_shake": t.get("per_letter_shake", False),
            "scale_with_zoom": t.get("scale_with_zoom", False),
            "scale_with_frame": t.get("scale_with_frame", False),
            "font_name": t.get("font_name", "segoeui"),
            "locked": t.get("locked", False),   # ← was missing
            "vcam_only": t.get("vcam_only", False),
            "rotation": t.get("rotation", 0),
            "outline_width": t.get("outline_width", 1),
            "opacity": t.get("opacity", 255),
            "parallax_x": t.get("parallax_x", 1.0),
            "parallax_y": t.get("parallax_y", 1.0),
            "arena_clip": t.get("arena_clip", None),
            "blend": t.get("blend", "normal"),
            # Stable id so node groups can still find this text after a reload.
            "sid": t.get("sid"),
        })

    for i, img in enumerate(scene_images):
        image_path = ensure_scene_image_asset(img, name, i)
        if image_path:
            img["image_path"] = image_path
        data["scene_images"].append({
            "sid": img.get("sid"),
            "image_path": image_path,
            "source_path": image_path,
            "fx": img.get("fx", 0.5), "fy": img.get("fy", 0.5),
            "wx": img.get("wx"), "wy": img.get("wy"),
            "scale": img.get("scale", 1.0),
            "alpha": img.get("alpha", 255),
            "pixel_perfect": bool(img.get("pixel_perfect", False)),
            "layer": img.get("layer", "front"),
            "depth": img.get("depth", 0),
            "z_index": scene_hierarchy_local_z(img),
            "hierarchy_parent": img.get("hierarchy_parent"),
            "visible": bool(img.get("visible",True)),
            "rotation": img.get("rotation", 0),
            "flip_x": bool(img.get("flip_x", False)),
            "flip_y": bool(img.get("flip_y", False)),
            "world_space": img.get("world_space", False),
            "camera_locked": img.get("camera_locked", False),
            "scale_with_zoom": img.get("scale_with_zoom", False),
            "scale_with_frame": img.get("scale_with_frame", False),
            "anchor_x": img.get("anchor_x", 0.5),
            "anchor_y": img.get("anchor_y", 0.5),
            "locked": img.get("locked", False),
            "vcam_only": img.get("vcam_only", False),
            "opacity": img.get("opacity", 255),
            "parallax_x": img.get("parallax_x", 1.0),
            "parallax_y": img.get("parallax_y", 1.0),
            "arena_clip": img.get("arena_clip", None),
            "blend": img.get("blend", "normal"),
            "splice": img.get("splice") or {"enabled": False, "axis": "v", "pos": 0.5, "keep": "start"},
            "shadow": img.get("shadow") or {"enabled": False, "offset_x": 6, "offset_y": 6, "color": [0, 0, 0],
                                             "alpha": 160, "use_main_splice": True,
                                             "splice": {"enabled": False, "axis": "v", "pos": 0.5, "keep": "start"}},
        })

    # Save scene debug buttons
    data["scene_debug_buttons"] = []
    for btn in scene_debug_buttons:
        data["scene_debug_buttons"].append({
            "id": btn.get("id"),
            "label": btn.get("label"),
            "window_title": btn.get("window_title"),
            "color": list(btn.get("color",[130,105,255])),
            "action_type": btn.get("action_type","custom_event"),
            "target_type": btn.get("target_type","all"),
            "target_name": btn.get("target_name",""),
            "amount": btn.get("amount",0),
            "tag": btn.get("tag",""),
            "enabled": btn.get("enabled",True),
        })
    data["scene_debug_mode"] = bool(scene_debug_mode)
    data["scene_debug_window_positions"] = {k: list(v) for k,v in scene_debug_window_positions.items()}
    data["scene_debug_next_id"] = scene_debug_next_id

    # Save external nodes (strip non-serialisable runtime state)
    _SKIP_EN_KEYS={"_rect","_surface","_bar_fade_alpha","_bar_fade_t","_bar_fade_ver"}
    data["external_nodes"] = []
    for en in external_nodes:
        _en_save = {k: v for k, v in en.items()
                    if k not in _SKIP_EN_KEYS
                    and not callable(v)}
        # fill_data keys are tuples — convert to list-of-list for JSON
        if "fill_data" in _en_save:
            _en_save["fill_data"] = {
                f"{k[0]},{k[1]}": v
                for k, v in _en_save["fill_data"].items()
                if isinstance(k, (list, tuple)) and len(k) == 2
            }
        data["external_nodes"].append(_en_save)

    # Canonical hierarchy state. Parent keys use stable en:/text:/image: IDs;
    # the map is restored only after every collection has loaded.
    for _hier_item in scene_hierarchy_all_items():
        _hier_key=scene_hierarchy_key_for(_hier_item)
        if not _hier_key:continue
        data["scene_hierarchy"][_hier_key]={
            "parent":_hier_item.get("hierarchy_parent"),
            "z_index":scene_hierarchy_local_z(_hier_item),
            "visible":bool(_hier_item.get("visible",True)),
            "locked":bool(_hier_item.get("locked",False)),
            "plane":scene_hierarchy_effective_plane(_hier_item) if not _hier_item.get("hierarchy_parent") else None,
            "name":_eh_identity_name(_hier_item),"tags":list(_hier_item.get("tags",[])),
            "scale_with_frame":bool(_hier_item.get("scale_with_frame",False)),"scale_with_zoom":bool(_hier_item.get("scale_with_zoom",False)),
        }

    # Scene node groups (grouping of external nodes, movable as one).
    data["scene_groups"] = serialize_scene_groups()

    # Particle emitters. "_particles" is live simulation state and is never
    # written -- an emitter reconstructs its look from its settings alone.
    data["particle_emitters"] = [
        {k: v for k, v in e.items() if not k.startswith("_")}
        for e in particle_emitters
    ]
    data["pe_next_id"] = _pe_next_id[0]

    # Scene Painter block layers travel with the project.
    data["scene_blocks"] = json.loads(json.dumps(scene_blocks))

    return data

def _write_project_file(path, name, mark_recovery=False):
    """Build the payload and write it to an arbitrary path.

    Writes to a temp file then os.replace()s it into position, so a crash
    partway through can never leave a truncated recovery file that fails to
    parse at the exact moment you need it.
    """
    try:
        data = _build_project_payload(name)
        clean = _json_clean_data(data)
        if mark_recovery:
            clean["_recovery"] = True
            clean["_recovery_time"] = time.time()
            clean["_recovery_of"] = name or ""
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w") as f:
            json.dump(clean, f, indent=2)
        os.replace(tmp, path)
        return True
    except Exception as e:
        print("Project write failed:", e)
        return False

def save_project(name=None, ask_name=False):
    """Saves the full current project: arena state, scene text/images, settings and the project-local character library."""
    global current_project_name

    if ask_name or not name:
        show_save_as_dialog(current_project_name or "My Project")
        return False

    name = sanitize_project_name(name)
    current_project_name = name
    path = get_project_path(name)

    data = _build_project_payload(name)

    try:
        _arena_palette_save(force=True)
    except Exception:
        pass
    try:
        os.makedirs(projects_dir(), exist_ok=True)
        clean_data = _json_clean_data(data)
        with open(path, "w") as f:
            json.dump(clean_data, f, indent=2)
        # A real save supersedes any recovery file for this project.
        try:
            discard_recovery(name)
        except Exception:
            pass
        load_recent_projects()
        # Update the thumbnail cache so PM shows fresh thumb immediately
        _proj_thumb_cache.pop(_project_workspace_key() + "::" + name, None)
        try:
            if modal.get("type") is None:
                capture_project_thumbnail(name)
        except Exception:
            pass
        if "push_toast" in globals():
            push_toast(f"Saved project: {name}", "success", 3.0)
        print(f"Project saved as: {name}")
        if modal.get("_save_reminder_open"):
            try:_save_reminder_delay(int(_editor_config.get("save_reminder_interval",300) or 300))
            except Exception:modal["_save_reminder_open"]=False
        return True
    except Exception as e:
        print("Save failed:", e)
        import traceback
        traceback.print_exc()
        if "push_toast" in globals():
            push_toast(f"Save failed: {e}", "error", 5.0)
        return False

# ══════════════════════════════════════════════════════════════════════════
# PROJECT AUTOSAVE + CRASH RECOVERY
# ══════════════════════════════════════════════════════════════════════════
RECOVERY_DIR = os.path.join(PROJECTS_DIR, "_recovery")

def _recovery_dir():
    d = os.path.join(projects_dir(), "_recovery")
    os.makedirs(d, exist_ok=True)
    return d

def _recovery_path(name=None):
    name = sanitize_project_name(name or current_project_name or "untitled")
    return os.path.join(_recovery_dir(), f"{name}.autosave.json")

def save_project_autosave():
    """Write the live project to its recovery slot.

    Deliberately quiet: no toast, no recent-projects update, no thumbnail
    invalidation. It reuses the exact payload builder save_project() uses by
    calling it against a redirected path, so the recovery file is a real,
    fully-loadable project -- not a partial snapshot that only mostly works.
    """
    global project_last_autosave, project_autosave_status, project_autosave_status_time
    project_last_autosave = time.time()
    try:
        _prev = current_project_name or "untitled"
        path = _recovery_path()
        ok = _write_project_file(path, _prev, mark_recovery=True)
        if ok:
            project_autosave_status = f"Autosaved {time.strftime('%H:%M:%S')}"
        else:
            project_autosave_status = "Autosave failed"
        project_autosave_status_time = time.time()
        return ok
    except Exception as e:
        project_autosave_status = f"Autosave failed · {e}"
        project_autosave_status_time = time.time()
        return False

def maybe_autosave_project():
    """Called once per frame from the main loop."""
    global project_last_autosave
    if not project_autosave_enabled:
        return
    # Never autosave mid-match or mid-recording: the point of recovery is to
    # restore what you were *building*, and a match mutates character state
    # constantly, which would make every slot differ for no useful reason.
    if simulation_started or is_recording or _OBS_RECORDING_ACTIVE or export_render_job is not None or (isinstance(_gpu_finalize_job,dict) and not _gpu_finalize_job.get("done")):
        return
    if time.time() - project_last_autosave < project_autosave_interval:
        return
    # Nothing worth saving yet.
    if _project_workspace_key() != "env3d" and not (characters or external_nodes or scene_texts or scene_images):
        project_last_autosave = time.time()
        return
    save_project_autosave()

def find_recovery_candidates():
    """Recovery files that represent work the saved project doesn't have.

    A successful save_project() deletes the matching recovery file outright,
    so anything still sitting in RECOVERY_DIR is by definition an autosave
    that was never followed by a real save -- i.e. the session ended badly.

    Deliberately NOT timestamp-based: mtime comparison is unreliable because
    a save and an autosave in the same second are indistinguishable, and
    filesystems vary in mtime granularity. Presence is the signal.
    """
    out = []
    rdir = _recovery_dir()
    if not os.path.isdir(rdir):
        return out
    for fn in os.listdir(rdir):
        if not fn.endswith(".autosave.json"):
            continue
        rpath = os.path.join(rdir, fn)
        try:
            rtime = os.path.getmtime(rpath)
            if os.path.getsize(rpath) <= 2:
                continue  # empty/garbage slot
        except Exception:
            continue
        pname = fn[:-len(".autosave.json")]
        ppath = get_project_path(pname)
        out.append({"name": pname, "path": rpath,
                    "when": rtime, "age": max(0.0, time.time() - rtime),
                    "had_project": os.path.isfile(ppath)})
    out.sort(key=lambda d: -d["when"])
    return out

def discard_recovery(name=None):
    try:
        p = _recovery_path(name)
        if os.path.isfile(p):
            os.remove(p)
            return True
    except Exception:
        pass
    return False

def load_project(name_or_path):
    """Loads a project by name or full path, restoring the exact saved scene rather than a default arena."""
    global current_project_name, LIBRARY, active_tab
    global sidebar_scroll, library_scroll, style_scroll
    global bg_color, box_scale, box_thickness, win_condition, show_shadows, movement_smoothing
    global time_limit, kill_limit, record_enabled, record_name, record_width, record_height, record_fps, record_gpu_output_profile, record_gpu_source_profile, record_mode, record_png_mode, record_auto_render_interpolated, record_countdown_visible, countdown_duration
    global simulation_started, game_over, winner, paused, end_fade_alpha, end_fade_complete, end_fade_timer
    global MOTION_CLIPS_LOADED, MOTION_CLIPS_VERSION, CUSTOM_EASE_LOADED, CUSTOM_EASE_VERSION, SPRITE_FOLDERS_LOADED
    global motion_debug_shapes, node_range_debug_shapes, all_node_gizmos_enabled
    global scene_debug_buttons, scene_debug_mode, scene_debug_window_positions, scene_debug_next_id
    global scene_blocks

    if os.path.isfile(name_or_path):
        path = name_or_path
        name = os.path.basename(name_or_path)[:-5]
    else:
        name = name_or_path
        path = get_project_path(name)

    try:
        with open(path, "r") as f:
            data = json.load(f)
    except Exception as e:
        print("Load failed:", e)
        return False

    if not isinstance(data, dict):
        push_toast("That file isn't a project save (skipped library/data JSON).", "error", 3.2)
        return False


    if "scene_undo_clear" in globals():
        scene_undo_clear()
    particle_emitters.clear()
    clear_weapon_projectiles()
    characters.clear(); scene_texts.clear(); scene_images.clear(); popups.clear(); external_nodes.clear()
    scene_death_history.clear()
    camera["target"] = None
    simulation_started = False
    game_over = False
    winner = None
    paused = True
    kill_counts.clear()
    end_fade_alpha = 0.0
    end_fade_complete = False
    end_fade_timer = 0.0
    GLOBAL_AUDIO_MAP.clear()
    GLOBAL_AUDIO_MAP.update(dict(data.get("global_audio_map", {})))
    GLOBAL_AUDIO_VOLUME_MAP.clear(); GLOBAL_AUDIO_VOLUME_MAP.update({"game_end": 1.0, "background_music": 0.7}); GLOBAL_AUDIO_VOLUME_MAP.update(dict(data.get("global_audio_volume_map", {})))
    _saved_vcam = data.get("virtual_camera", {}) or {}
    if _saved_vcam:
        virtual_camera["enabled"] = bool(_saved_vcam.get("enabled", False))
        virtual_camera["preview"] = bool(_saved_vcam.get("preview", False))
        virtual_camera["aspect"] = _saved_vcam.get("aspect", "16:9")
        virtual_camera["pos"] = pygame.Vector2(_saved_vcam.get("pos", [0,0]))
        virtual_camera["zoom"] = float(_saved_vcam.get("zoom", 1.0))
        virtual_camera["follow_name"] = _saved_vcam.get("follow_name")
        virtual_camera["follow_live_camera"] = bool(_saved_vcam.get(
            "follow_live_camera", virtual_camera["follow_name"] is None))
        virtual_camera["pan_offset"] = pygame.Vector2(_saved_vcam.get("pan_offset", [0, 0]))
        virtual_camera["show_frame"] = bool(_saved_vcam.get("show_frame", True))
        virtual_camera["_follow_last_index"] = None
        virtual_camera["_pan_dragging"] = False
        virtual_camera["_preview_frame"] = None
        virtual_camera["_pan_vel"] = pygame.Vector2(0, 0)
        virtual_camera["follow_smoothing"] = float(_saved_vcam.get("follow_smoothing", 1.0))
        virtual_camera["swap_on_death"] = bool(_saved_vcam.get("swap_on_death", True))
        virtual_camera["show_safe_area"] = bool(_saved_vcam.get("show_safe_area", True))
        virtual_camera["speed"] = float(_saved_vcam.get("speed", 4.0))
        virtual_camera["drag"] = float(_saved_vcam.get("drag", 3.0))
        virtual_camera["smart_follow"] = bool(_saved_vcam.get("smart_follow", False))
        virtual_camera["smart_follow_mode"] = _saved_vcam.get("smart_follow_mode", "centroid")
        virtual_camera["smart_follow_scope"] = _saved_vcam.get("smart_follow_scope", "combat")
        virtual_camera["smart_follow_include_dead"] = bool(_saved_vcam.get("smart_follow_include_dead", False))
        virtual_camera["smart_follow_padding"] = float(_saved_vcam.get("smart_follow_padding", 0.12))
        virtual_camera["smart_follow_min_zoom"] = float(_saved_vcam.get("smart_follow_min_zoom", 0.4))
        virtual_camera["smart_follow_max_zoom"] = float(_saved_vcam.get("smart_follow_max_zoom", 2.5))
        virtual_camera["smart_follow_target"] = _saved_vcam.get("smart_follow_target")
        virtual_camera["smart_follow_auto_zoom"] = bool(_saved_vcam.get("smart_follow_auto_zoom", False))

    # Arena look (background/box colors, box scale, shadows, smoothing) is a
    # GLOBAL preference now — loading a project must not revert it. These
    # project fields are kept in the save file for backwards compatibility
    # but are deliberately ignored on load.
    win_condition = data.get("win_condition", win_condition)
    time_limit = data.get("time_limit", time_limit)
    kill_limit = data.get("kill_limit", kill_limit)
    record_enabled = data.get("record_enabled", record_enabled)
    record_name = str(data.get("record_name", record_name) or "")
    record_width = data.get("record_width", record_width)
    record_height = data.get("record_height", record_height)
    record_fps = max(1, int(data.get("record_fps", record_fps)))
    _saved_gpu_profile=data.get("record_gpu_output_profile")
    record_gpu_output_profile=(_gpu_output_profile(_saved_gpu_profile) if _saved_gpu_profile is not None
                               else _gpu_output_profile_from_legacy(record_width,record_height))
    _saved_source_profile=_gpu_source_profile(data.get("record_gpu_source_profile","window"))
    # v1 could persist Monitor Max from the short-lived fullscreen build. Reset
    # that once so existing projects receive the smooth bounded-window fix.
    if int(data.get("record_gpu_source_profile_version",1) or 1)<3 and _saved_source_profile != "window":
        _saved_source_profile="window"
    record_gpu_source_profile=_saved_source_profile
    record_mode=str(data.get("record_mode",record_mode))
    if record_mode in ("interpolated","faux"):record_mode="stream"
    if record_mode not in ("manual","stream","apu"):record_mode="manual"
    record_png_mode = str(data.get("record_png_mode", record_png_mode))
    if record_png_mode not in ("fast", "compact"):
        record_png_mode = "fast"
    record_auto_render_interpolated = bool(data.get("record_auto_render_interpolated", record_auto_render_interpolated))
    record_countdown_visible = data.get("record_countdown_visible", record_countdown_visible)
    countdown_duration = data.get("countdown_duration", countdown_duration)

    # Restore project-local animation/editor state. Older projects simply use
    # the current defaults when these keys are absent.
    if isinstance(data.get("animation_library"), dict):
        ANIMATION_LIBRARY.clear()
        ANIMATION_LIBRARY.update(data.get("animation_library", {}))
    # Round 15: restore motion clips / easing curves / sprite folders embedded
    # at save time, and mirror them to their sidecar jsons so the F9 studio,
    # F8 editor, and F10 library immediately see the project's versions.
    if isinstance(data.get("motion_clips"), dict):
        try:
            MOTION_CLIPS.clear()
            for _mcn, _mcv in data.get("motion_clips", {}).items():
                if isinstance(_mcv, dict):
                    MOTION_CLIPS[str(_mcn)] = _motion_clip_normalize(_mcv)
            MOTION_CLIPS_LOADED = True
            MOTION_CLIPS_VERSION += 1
            save_motion_clips()
        except Exception:
            pass
    if isinstance(data.get("easing_curves"), dict):
        try:
            CUSTOM_EASE_CURVES.clear()
            for _ecn3, _ecv3 in data.get("easing_curves", {}).items():
                if isinstance(_ecv3, (list, dict)):
                    CUSTOM_EASE_CURVES[str(_ecn3)] = _curve_normalize(_ecv3)
            CUSTOM_EASE_LOADED = True
            CUSTOM_EASE_VERSION += 1
            save_easing_curves()
        except Exception:
            pass
    if isinstance(data.get("sprite_folders"), dict):
        try:
            SPRITE_FOLDERS.clear()
            for _sfk, _sfv in data.get("sprite_folders", {}).items():
                SPRITE_FOLDERS[str(_sfk)] = str(_sfv)[:48]
            SPRITE_FOLDERS_LOADED = True
            save_sprite_folders()
        except Exception:
            pass
    _ui_saved = data.get("ui_preferences", {}) or {}
    # Restore the debug display switches and keybinds saved with this project.
    # Keep validation shallow and tolerant so old projects remain loadable.
    motion_debug_shapes = bool(_ui_saved.get("motion_hitbox_gizmos", motion_debug_shapes))
    node_range_debug_shapes = bool(_ui_saved.get("node_range_gizmos", node_range_debug_shapes))
    all_node_gizmos_enabled = bool(_ui_saved.get("all_node_gizmos_enabled", all_node_gizmos_enabled))
    if "scene_debug_mode" in _ui_saved:
        scene_debug_mode = bool(_ui_saved.get("scene_debug_mode"))
    _project_shortcuts = _ui_saved.get("scene_shortcuts")
    if isinstance(_project_shortcuts, dict):
        SCENE_SHORTCUTS.clear()
        SCENE_SHORTCUTS.update({str(k): str(v) for k, v in _project_shortcuts.items()})
        _save_scene_shortcuts()
    _project_keybinds = _ui_saved.get("visual_scripter_action_keybinds")
    if isinstance(_project_keybinds, dict):
        NS_ACTION_KEYBINDS.clear()
        NS_ACTION_KEYBINDS.update({str(k): str(v) for k, v in _project_keybinds.items()})
        _ns_save_action_keybinds()
    if _ui_saved.get("active_tab") in ("arena", "library", "style"):
        active_tab = _ui_saved.get("active_tab")
    sidebar_scroll = max(0.0, float(_ui_saved.get("arena_scroll", sidebar_scroll) or 0.0))
    library_scroll = max(0.0, float(_ui_saved.get("library_scroll", library_scroll) or 0.0))
    style_scroll = max(0.0, float(_ui_saved.get("style_scroll", style_scroll) or 0.0))
    modal["script_manager_sort"] = _ui_saved.get("script_manager_sort", modal.get("script_manager_sort", "name_asc"))
    modal["_sm_search"] = _ui_saved.get("script_manager_search", modal.get("_sm_search", ""))
    modal["_sm_filter"] = _ui_saved.get("script_manager_filter", modal.get("_sm_filter", "all"))
    modal["ns_search"] = _ui_saved.get("blueprint_search", modal.get("ns_search", ""))
    modal["ns_category_filter"] = _ui_saved.get("blueprint_category", modal.get("ns_category_filter"))
    modal["ns_snap_enabled"] = bool(_ui_saved.get("blueprint_snap", modal.get("ns_snap_enabled", False)))
    modal["ns_sim_auto_pan"] = bool(_ui_saved.get("blueprint_auto_pan", modal.get("ns_sim_auto_pan", True)))
    modal["ns_ignore_path_dim"] = bool(_ui_saved.get("blueprint_ignore_path_dim", modal.get("ns_ignore_path_dim", False)))
    modal["ns_show_palette"] = bool(_ui_saved.get("blueprint_show_palette", modal.get("ns_show_palette", True)))
    modal["ns_show_script"] = bool(_ui_saved.get("blueprint_show_script", modal.get("ns_show_script", False)))
    modal["ns_show_inspector"] = bool(_ui_saved.get("blueprint_show_inspector", modal.get("ns_show_inspector", True)))
    modal["ns_inspector_width"] = float(_ui_saved.get("blueprint_inspector_width", modal.get("ns_inspector_width", 250)))
    modal["ns_script_width"] = float(_ui_saved.get("blueprint_script_width", modal.get("ns_script_width", 360)))
    modal["ns_wire_anim_mode"] = _ui_saved.get("blueprint_wire_anim_mode", modal.get("ns_wire_anim_mode", "flow"))
    _saved_visual = _ui_saved.get("visual_blueprint")
    if isinstance(_saved_visual, dict) and _saved_visual.get("nodes"):
        modal["ns_nodes"] = {int(k): v for k, v in _saved_visual.get("nodes", {}).items()}
        modal["ns_links"] = list(_saved_visual.get("links", []))
        modal["ns_next_id"] = int(_saved_visual.get("next_id", max(modal["ns_nodes"], default=0) + 1))
        modal["ns_view"] = _saved_visual.get("view", {"pan": [0, 0], "zoom": 1.0})
        modal["ns_wire_style"] = _ns_wire_style_key(_saved_visual.get("wire_style", "bezier"))
        modal["ns_wire_anim_mode"] = _saved_visual.get("wire_anim_mode", modal.get("ns_wire_anim_mode", "flow"))
        modal["ns_sort_mode"] = _saved_visual.get("sort_mode", "topological")
        modal["ns_smart_groups"] = _saved_visual.get("smart_groups", [])
        modal["ns_bookmarks"] = _saved_visual.get("bookmarks", [])
        modal["ns_hide_mode"] = _saved_visual.get("hide_mode", modal.get("ns_hide_mode", "transparent"))
        modal["script_file"] = _saved_visual.get("script_file")
        # Restore per-graph notepad
        modal["ns_notepad_text"] = str(_saved_visual.get("notepad_text","") or "")
        modal["ns_notepad_search"] = str(_saved_visual.get("notepad_search","") or "")
        modal["ns_notepad_scroll"] = float(_saved_visual.get("notepad_scroll",0.0) or 0.0)
        modal["ns_notepad_cursor"] = len(modal["ns_notepad_text"])
        modal["ns_notepad_anchor"] = None
        modal["ns_notepad_last_jump_node"] = None
        modal["ns_notepad_jump_idx"] = -1
        modal["ns_dirty"] = False

    for k, v in data.get("settings", {}).items():
        if k not in SETTINGS:
            continue
        # Only UI / theme preferences are global. Everything else --
        # including damage-number behaviour (rise, shrink, shake, colours),
        # hp bars and combat tuning -- belongs to the project it was saved
        # with and is restored here.
        if str(k).startswith(("ui_", "panel_", "button_", "pe_editor_", "pe_max_",
                              "svg_", "arena_outer_")):
            continue
        if str(k) in ("save_dir", "vsync", "fps_cap", "cache_size", "nerd_stats",
                      "nerd_stats_detail", "frame_costs", "spike_logging",
                      "ui_render_fps", "scene_font_scale", "box_color",
                      "pe_show_help", "pe_large_text", "pe_auto_throttle"):
            continue
        SETTINGS[k] = v

    # Project-local character library. Older projects without this key intentionally start empty
    # instead of leaking characters from another project.
    LIBRARY = [serialize_template(t) for t in data.get("library", [])]

    cam = data.get("camera", {})
    camera["pos"] = pygame.Vector2(cam.get("pos", [0, 0]))
    camera["vel"] = pygame.Vector2(0, 0)
    camera["zoom"] = cam.get("zoom", 1.0)
    camera["zoom_target"] = cam.get("zoom_target", camera["zoom"])
    camera["smart_follow"] = bool(cam.get("smart_follow", camera.get("smart_follow", False)))
    camera["smart_follow_mode"] = cam.get("smart_follow_mode", camera.get("smart_follow_mode", "centroid"))
    camera["smart_follow_scope"] = cam.get("smart_follow_scope", camera.get("smart_follow_scope", "combat"))
    camera["smart_follow_include_dead"] = bool(cam.get("smart_follow_include_dead", camera.get("smart_follow_include_dead", False)))
    camera["smart_follow_padding"] = float(cam.get("smart_follow_padding", camera.get("smart_follow_padding", 0.12)))
    camera["smart_follow_min_zoom"] = float(cam.get("smart_follow_min_zoom", camera.get("smart_follow_min_zoom", 0.4)))
    camera["smart_follow_max_zoom"] = float(cam.get("smart_follow_max_zoom", camera.get("smart_follow_max_zoom", 2.5)))
    camera["smart_follow_target"] = cam.get("smart_follow_target", camera.get("smart_follow_target"))
    camera["smart_follow_auto_zoom"] = bool(cam.get("smart_follow_auto_zoom", camera.get("smart_follow_auto_zoom", False)))
    _cb_saved=data.get("camera_bounds") or {}
    if isinstance(_cb_saved,dict):
        CAMERA_BOUNDS.update({"enabled":bool(_cb_saved.get("enabled",False)),"rect":list(_cb_saved.get("rect",[-600,-340,600,340])),"mode":str(_cb_saved.get("mode","both")),"ease_distance":max(0.0,float(_cb_saved.get("ease_distance",180.0))),"ease_strength":max(0.0,min(1.0,float(_cb_saved.get("ease_strength",1.0)))),"show_gizmo":bool(_cb_saved.get("show_gizmo",True))})

    for cdata in data.get("characters", []):
        template = serialize_template(cdata)
        template["instance_id"] = str(cdata.get("instance_id", "") or generate_character_instance_id())
        template["hp"] = cdata.get("hp", template["max_hp"])
        inst = spawn_instance(template)
        inst["pos"] = pygame.Vector2(cdata.get("pos", [0, 0]))
        if "vel" in cdata:
            inst["vel"] = pygame.Vector2(cdata.get("vel", [template.get("speed", 150), 0]))
            inst["_smooth_vel"] = pygame.Vector2(inst["vel"])
        characters.append(inst)

    for t in data.get("scene_texts", []):
        scene_texts.append({
            "text": t.get("text", ""), "size": t.get("size", 28), "color": tuple(t.get("color", [255,255,255])),
            "outline": t.get("outline", True), "layer": t.get("layer", "front"),
            "depth": t.get("depth", 0),
            "z_index": int(t.get("z_index",t.get("depth",0)) or 0),
            "hierarchy_parent": t.get("hierarchy_parent"),
            "visible": bool(t.get("visible",True)),
            "fx": t.get("fx", 0.5), "fy": t.get("fy", 0.5),
            "world_space": t.get("world_space", False),
            "camera_locked": t.get("camera_locked", False),
            "wx": t.get("wx"), "wy": t.get("wy"),
            "shake_level": t.get("shake_level", 0.0),
            "shake_freq": t.get("shake_freq", 1.0),
            "per_letter_shake": t.get("per_letter_shake", False),
            "scale_with_zoom": t.get("scale_with_zoom", False),
            "scale_with_frame": t.get("scale_with_frame", False),
            "font_name": t.get("font_name", "segoeui"),
            "locked": t.get("locked", False),
            "vcam_only": t.get("vcam_only", False),
            "rotation": t.get("rotation", 0),
            "outline_width": t.get("outline_width", 1),
            "opacity": t.get("opacity", 255),
            "parallax_x": float(t.get("parallax_x", 1.0)),
            "parallax_y": float(t.get("parallax_y", 1.0)),
            "arena_clip": t.get("arena_clip", None),
            "blend": t.get("blend", "normal"),
            "sid": t.get("sid"),
            "_rect": None,
        })

    for idata in data.get("scene_images", []):
        img = scene_image_from_data(idata)
        if img:
            if idata.get("sid") is not None:
                img["sid"] = idata.get("sid")
            img["locked"] = idata.get("locked", False)
            img["vcam_only"] = idata.get("vcam_only", False)
            img["pixel_perfect"] = bool(idata.get("pixel_perfect", False))
            # ensure any extra fields from data that scene_image_from_data might have missed are restored
            if "pixel_perfect" in idata:
                img["pixel_perfect"] = bool(idata["pixel_perfect"])
            scene_images.append(img)

    # Load particle emitters
    particle_emitters.clear()
    _pe_hi = 0
    for _ed in data.get("particle_emitters", []):
        if not isinstance(_ed, dict):
            continue
        _em = pe_default()
        for _k, _v in _ed.items():
            if not str(_k).startswith("_"):
                _em[_k] = _v
        _em["_particles"] = []
        _em["_age"] = 0.0
        _em["_accum"] = 0.0
        _em["_emit_count"] = 0
        _em["_tex_sched"] = None
        _em.pop("_fired", None)
        pe_normalize(_em)
        try:
            _em["id"] = int(_ed.get("id", _em["id"]))
        except Exception:
            pass
        _pe_hi = max(_pe_hi, int(_em["id"]))
        particle_emitters.append(_em)
    _pe_next_id[0] = max(int(data.get("pe_next_id", 1)), _pe_hi + 1)

    # Load Scene Painter block layers
    scene_blocks.clear()
    for _sbl in data.get("scene_blocks", []):
        if isinstance(_sbl, dict):
            _sbl.setdefault("tiles", {})
            _sbl.setdefault("visible", True)
            _sbl.setdefault("solid", True)
            _sbl.setdefault("tile_size", 32)
            _sbl.setdefault("opacity", 255)
            scene_blocks.append(_sbl)

    # Load external nodes
    external_nodes.clear()
    _ext_node_next_id[0] = 1
    for en_data in data.get("external_nodes", []):
        en = dict(en_data)
        en["_rect"] = None
        if "offset" in en and isinstance(en["offset"], list) and len(en["offset"]) == 2:
            try:
                en["offset"] = pygame.Vector2(en["offset"][0], en["offset"][1])
            except Exception:
                pass
        if "fill_data" in en and isinstance(en["fill_data"], dict):
            en["fill_data"] = {
                tuple(int(x) for x in str(k).split(",")): v
                for k, v in en["fill_data"].items()
                if "," in str(k)
            }
        if en.get("kind")=="timer":_normalize_scene_timer_runtime(en,False)
        if en.get("id", 0) >= _ext_node_next_id[0]:
            _ext_node_next_id[0] = en["id"] + 1
        external_nodes.append(en)
    en_tag_index_rebuild()
    # Groups are restored after nodes so every member id resolves.
    restore_scene_groups(data.get("scene_groups", []))
    # Texts/images may carry ids from the save file; make sure newly created
    # ones never collide with them.
    ensure_scene_item_ids()

    # Restore complete hierarchy only after all key targets resolve.
    _hier_saved=data.get("scene_hierarchy",{}) or {}
    if isinstance(_hier_saved,dict):
        # Local properties first, then relationships (cycle-safe second pass).
        for _hier_key,_hier_state in _hier_saved.items():
            _hier_item=scene_hierarchy_item(_hier_key)
            if _hier_item is None or not isinstance(_hier_state,dict):continue
            scene_hierarchy_set_local_z(_hier_item,_hier_state.get("z_index",scene_hierarchy_local_z(_hier_item)))
            _hier_item["visible"]=bool(_hier_state.get("visible",_hier_item.get("visible",True)))
            _hier_item["locked"]=bool(_hier_state.get("locked",_hier_item.get("locked",False)))
            if _hier_state.get("name"):_eh_set_identity_name(_hier_item,_hier_state.get("name"))
            if "tags" in _hier_state:_eh_set_tags_text(_hier_item,",".join(str(tag) for tag in (_hier_state.get("tags") or [])))
            if "scale_with_frame" in _hier_state:_hier_item["scale_with_frame"]=bool(_hier_state.get("scale_with_frame"))
            if "scale_with_zoom" in _hier_state:_hier_item["scale_with_zoom"]=bool(_hier_state.get("scale_with_zoom"))
            _plane=_hier_state.get("plane")
            if _plane in ("front","back"):_eh_set_plane(_hier_item,_plane)
            _hier_item["hierarchy_parent"]=None
        for _hier_key,_hier_state in _hier_saved.items():
            _hier_item=scene_hierarchy_item(_hier_key)
            if _hier_item is None or not isinstance(_hier_state,dict):continue
            _parent=scene_hierarchy_item(_hier_state.get("parent"))
            if _parent is not None:scene_hierarchy_set_parent(_hier_item,_parent)
    # Old schema fallback fields remain supported and invalid parent references
    # are normalized instead of poisoning the tree.
    for _hier_item in scene_hierarchy_all_items():
        _hier_item.setdefault("z_index",scene_hierarchy_local_z(_hier_item))
        _pk=_hier_item.get("hierarchy_parent")
        if _pk and scene_hierarchy_item(_pk) is None:_hier_item["hierarchy_parent"]=None
    _saved_collapsed=set(str(k) for k in (data.get("scene_hierarchy_collapsed",[]) or []))
    modal["_eh_collapsed"]={k for k in _saved_collapsed if scene_hierarchy_item(k) is not None}
    modal["_eh_selected"]=None;modal["_eh_drag"]=None;scene_proxy_invalidate()

    # Load scene debug buttons
    scene_debug_buttons.clear()
    for bdata in data.get("scene_debug_buttons", []):
        try:
            btn = {
                "id": int(bdata.get("id",0)),
                "label": str(bdata.get("label","Debug"))[:40],
                "window_title": str(bdata.get("window_title","Debug Controls"))[:40],
                "color": list(bdata.get("color",[130,105,255])),
                "action_type": str(bdata.get("action_type","custom_event")),
                "target_type": str(bdata.get("target_type","all")),
                "target_name": str(bdata.get("target_name",""))[:40],
                "amount": float(bdata.get("amount",0) or 0),
                "tag": str(bdata.get("tag",""))[:40],
                "enabled": bool(bdata.get("enabled",True)),
            }
            scene_debug_buttons.append(btn)
        except Exception as e:
            print("Failed to load debug button", e)
    scene_debug_mode = bool(data.get("scene_debug_mode", False))
    scene_debug_window_positions.clear()
    for k,v in (data.get("scene_debug_window_positions", {}) or {}).items():
        try:
            scene_debug_window_positions[str(k)] = [float(v[0]), float(v[1])] if isinstance(v,(list,tuple)) and len(v)>=2 else [SIDEBAR_W+20, 80]
        except:
            scene_debug_window_positions[str(k)] = [SIDEBAR_W+20, 80]
    scene_debug_next_id = int(data.get("scene_debug_next_id", 0) or 0)
    if scene_debug_next_id == 0:
        scene_debug_next_id = max([b.get("id",0) for b in scene_debug_buttons], default=0) + 1
    if scene_debug_next_id < 1:
        scene_debug_next_id = 1

    current_project_name = name
    load_recent_projects()
    print(f"Loaded project: {name}")
    return True

# Simple Save As / Rename / Copy dialog using a modal text field
def show_save_as_dialog(default_name="My Project"):
    return show_project_name_dialog("save_as", default_name)

def open_rename_project_modal(name):
    return show_project_name_dialog("rename_project", name, source_project=name)

def open_copy_project_modal(name):
    return show_project_name_dialog("copy_project", f"{name} Copy", source_project=name)

def request_app_exit():
    if isinstance(export_render_job,dict) and export_render_job.get("apu"):
        push_toast("APU frame rebuild is active · cancel it from the progress window before exiting.","warning",7);return
    if _apu_compile_process is not None and _apu_compile_process.poll() is None:
        push_toast("APU video is still compiling · wait until validation finishes before exiting.","warning",7);return
    if isinstance(_gpu_finalize_job,dict) and _gpu_finalize_job.get("process") is not None and _gpu_finalize_job["process"].poll() is None:
        push_toast("GPU video is still compiling · wait for the progress window to finish before exiting.", "warning", 6.0)
        return
    modal["type"] = "app_exit_confirm"
    modal["focus"] = None

def finish_app_exit(save_changes):
    global running, quit_after_project_save
    if not save_changes:
        if is_recording:
            stop_recording()
        running = False
        modal["type"] = None
        return
    if current_project_name:
        if save_project(current_project_name):
            if is_recording:
                stop_recording()
            running = False
            modal["type"] = None
    else:
        quit_after_project_save = True
        show_save_as_dialog("My Project")

def confirm_save_as():
    global running, quit_after_project_save
    name = sanitize_project_name(modal["fields"].get("Project Name", "").strip())
    mode = modal.get("save_mode", "save_as")
    src = modal.get("source_project")
    saved = False
    if name:
        if mode == "rename_project" and src:
            saved = rename_project(src, name)
        elif mode == "copy_project" and src:
            saved = duplicate_project(src, name)
        else:
            saved = save_project(name)
    close_modal()
    if quit_after_project_save and saved:
        quit_after_project_save = False
        if is_recording:
            stop_recording()
        running = False

