    rec_text="There is no universal best mode. Choose from your hardware, clip length, storage speed, and whether live FPS or fast completion matters most."
    rr=pygame.Rect(panel.x+18,panel.y+80,panel.width-36,44);ui_draw_rect(screen,_eh_mix(PANEL_BG_ALT,INFO,.10),rr,border_radius=9);ui_draw_rect(screen,INFO,rr,1,9)
    ric=get_icon_fs("info",17,INFO)
