def dismiss_end_screen():
    global game_over, winner, simulation_started, paused, end_fade_alpha, end_fade_complete, end_fade_timer
    game_over = False
    winner = None
    simulation_started = False
    paused = True
    end_fade_alpha = 0.0
    end_fade_complete = False
    end_fade_timer = 0.0
    camera["target"] = None
    kill_counts.clear()

def safe_int(s, default):
    try:
        return int(float(s))
    except Exception:
        return default

def safe_float(s, default):
    try:
        return float(s)
    except Exception:
        return default

def _apply_template_to_live_character(character, template):
    """Apply editor fields/PARAMS to exactly one already-spawned instance."""
    if not isinstance(character, dict) or not any(character is c for c in characters):
        return False
    _ensure_char_instance_id(character)
    old_pos = pygame.Vector2(character.get("pos", (0, 0)))
    old_vel = pygame.Vector2(character.get("vel", (0, 0)))
    old_smooth = pygame.Vector2(character.get("_smooth_vel", old_vel))
    old_max = max(1.0, float(character.get("max_hp", 1)))
    old_ratio = max(0.0, min(1.0, float(character.get("hp", old_max)) / old_max))

    character["name"] = str(template.get("name", character.get("name", "Fighter")))
    character["color"] = tuple(template.get("color", character.get("color", (190, 190, 200))))
    character["character_center"] = _character_center_value(template)
    character["max_hp"] = int(template.get("max_hp", character.get("max_hp", 100)))
    character["hp"] = max(0, min(character["max_hp"], int(round(character["max_hp"] * old_ratio))))
    for key in ("dmg_min", "dmg_max", "crit_chance", "crit_mult", "speed", "scale", "radius",
                "friendly_fire", "contact_trait", "collision_source", "collision_shape",
                "collision_radius", "collision_radius_x", "collision_radius_y",
                "collision_box_w", "collision_box_h", "collision_offset_x", "collision_offset_y"):
        if key in template:
            character[key] = copy.deepcopy(template[key])
    character["_contact_traits"] = list(template.get("contact_traits", character.get("_contact_traits", [])))
    character["collision_debug_color"] = list(template.get("collision_debug_color", [110, 195, 255]))
    character["collision_debug_editor_visible"] = bool(template.get("collision_debug_editor_visible", True))
    character["collision_debug_play_visible"] = bool(template.get("collision_debug_play_visible", True))
    character["collision_debug_fill"] = bool(template.get("collision_debug_fill", True))
    character["is_scene_prop"] = bool(template.get("is_scene_prop", False))
    _visible = bool(template.get("is_visible", True))
    character["scene_director"] = bool(character["is_scene_prop"] and (template.get("scene_director", False) or not _visible))
    character["is_visible"] = False if character["scene_director"] else _visible
    character["_prop_has_collision"] = bool(template.get("has_collision", True)) if character["is_scene_prop"] else False
    character["has_collision"] = False if character["scene_director"] else bool(template.get("has_collision", True))
    character["body_type"] = "static" if character["is_scene_prop"] else "dynamic"
    character["manual_input_enabled"] = not character["is_scene_prop"]

    character["script_file"] = template.get("script_file")
    character["script_params"] = dict(template.get("script_params", {}))
    character["sprite_folder"] = template.get("sprite_folder")
    character["sprite_map"] = dict(template.get("sprite_map", {}))
    character["custom_sprite_tags"] = [str(t) for t in (template.get("custom_sprite_tags") or []) if isinstance(t, str) and t]
    character["audio_map"] = dict(template.get("audio_map", {}))
    character["audio_volume_map"] = dict(template.get("audio_volume_map", {}))
    character["animation_sources"] = dict(template.get("animation_sources", {}))
    character["rig"] = copy.deepcopy(_rig_normalize(template.get("rig")))
    character["anim_machine"] = copy.deepcopy(_anim_machine_normalize(
        template.get("anim_machine"), known_states=list(dict.fromkeys(list(template.get("animations",{}).keys())+list(template.get("sprite_map",{}).keys())+list((template.get("animation_layers",{}) or {}).keys())))))

    # Fresh namespace = per-instance PARAMS. Reusing cached executed globals
    # made one copy's parameter edits leak into every same-script character.
    new_ns = load_script_ns_from_file(character.get("script_file")) or {}
    apply_script_params(new_ns, character["script_params"])
    character["script_ns"] = new_ns

    sprites = dict(load_sprites(character.get("sprite_folder", ""))) if character.get("sprite_folder") else {}
    for tag, rel_path in character["sprite_map"].items():
        image = load_sprite_asset(rel_path)
        if image is not None:
            sprites[tag] = image
    character["sprites"] = sprites

    anim_defs = {}
    anim_fps = {}
    anim_durations = {}
    # Character-authored animations only; reusable global clips load on demand.
    for key, value in dict(template.get("animations", {})).items():
        anim_defs[str(key)] = list(value)
    anim_fps.update({str(k): float(v) for k, v in dict(template.get("animation_fps", {})).items()})
    for key, value in dict(template.get("animation_durations", {})).items():
        anim_durations[str(key)] = [max(0.02, float(x)) for x in value]
    character["animation_paths"] = anim_defs
    character["animation_fps"] = anim_fps
    character["animation_durations"] = anim_durations
    character["animation_anchors"] = {
        str(k): tuple(v) for k, v in dict(template.get("animation_anchors", {})).items()
    }
    character["animation_pivots"]={str(k):list(v) for k,v in dict(template.get("animation_pivots",{})).items()}
    character["animation_position_events"]=copy.deepcopy(dict(template.get("animation_position_events",{})))
    character["animation_collision_frames"]=copy.deepcopy(dict(template.get("animation_collision_frames",{})))
    character["animation_layers"]=copy.deepcopy(dict(template.get("animation_layers",{})))
    character["animations"] = {
        state: [img for img in (load_sprite_asset(path) for path in paths) if img is not None]
        for state, paths in anim_defs.items()
    }
    character["animation_total_durations"] = {k: sum(v) for k, v in anim_durations.items()}

    # Reapply graph-driven presentation immediately. Newer scripts can define a
    # dedicated hook; older graphs fall back to on_spawn so PARAM -> Set Name,
    # Set Scale, etc. visibly update as soon as Apply is clicked.
    if new_ns.get("on_parameters_changed"):
        call_hook(character, "on_parameters_changed", CTX, character)
    else:
        call_hook(character, "on_spawn", CTX, character)

    # Editing must not teleport an existing scene instance. Velocity is kept
    # unless its reapply hook deliberately changed it.
    character["pos"] = old_pos
    if pygame.Vector2(character.get("vel", old_vel)) == pygame.Vector2(0, 0) and old_vel.length_squared() > 0:
        character["vel"] = old_vel
        character["_smooth_vel"] = old_smooth
    _ensure_char_instance_id(character)
    return True


def confirm_add_character():
    if modal.get("_mesh_preview_path") or modal.get("_mesh_library_id"):
        f = modal.get("fields") or {}
        name = str(f.get("Name", "") or "").strip() or modal.get("_mesh_preview_name") or "Mesh"
        eid = modal.get("_mesh_library_id")
        load_model_library()
        entry = next((e for e in MODEL_LIBRARY if e.get("id") == eid), None)
        if entry is None:
            entry = {"id": eid or f"mesh_{int(time.time()*1000)}", "path": modal.get("_mesh_preview_path"), "format": "glb", "created": time.time()}
            MODEL_LIBRARY.append(entry)
        entry["name"] = name
        entry["color"] = list(modal.get("color") or [120, 180, 255])
        entry["texture"] = modal.get("_mesh_texture") or ""
        save_model_library()
        # Live-update already-placed instances that came from this library entry.
        try:
            ws = _ENV3D.get("workspace")
            if ws is not None:
                for o in list(getattr(ws, "objects", None) or []):
                    if o.get("library_id") == entry.get("id"):
                        o["texture"] = entry.get("texture") or ""
                        o["name"] = name
        except Exception:
            pass
        push_toast(f"Saved to Model Library: {name}", "success", 2.4)
        close_modal()
        return
    f = modal["fields"]
    script_params = {}
    for key in modal.get("param_order", []):
        raw = f.get(f"param:{key}", "")
        ptype = modal["param_types"].get(key, "str")
        if ptype == "int":
            script_params[key] = safe_int(raw, 0)
        elif ptype in ("float", "number"):
            script_params[key] = safe_float(raw, 0.0)
        elif ptype in ("bool", "boolean"):
            script_params[key] = str(raw).strip().lower() in ("1", "true", "yes", "y", "on")
        else:
            script_params[key] = raw

    is_prop = bool(modal.get("is_scene_prop", False))

    # ── Custom sprite tags ────────────────────────────────────────────
    # `modal["sprite_tags"]` is the resolved list (built-ins + script-
    # declared + user-added). Figure out which ones are USER-added (not
    # built-in, not declared by the script) and persist them in two
    # places so they survive closing the editor and reloading the
    # library:
    #   1. The character template (loaded from / saved to library.json)
    #   2. The script's top-level SPRITE_TAGS = [...] declaration so
    #      the visual scripter + other systems see them too.
    _script_declared = set(peek_script_sprite_tags(modal.get("script_file")))
    _custom_tags = []
    # User-added tags stay "custom" FOREVER, even after they have been
    # persisted into the script's SPRITE_TAGS line. Previously a tag that
    # made it into the script got reclassified as "script-declared" here,
    # so the template saved custom_sprite_tags = [] — and the next
    # blueprint regeneration (which rebuilds the script from the graph and
    # drops the SPRITE_TAGS line) erased the state from BOTH homes. That
    # was the "my custom sprite state keeps getting deleted" bug.
    for _t in modal.get("custom_sprite_tags", []) or []:
        _t = normalize_sprite_tag(_t)
        if _t and _t not in BUILTIN_SPRITE_TAGS and _t not in _custom_tags:
            _custom_tags.append(_t)
    # Legacy sweep: tags present in the resolved list that neither the
    # engine nor the script declares must be user-added ones from before
    # custom_sprite_tags tracking existed. Keep treating them as custom.
    for _t in modal.get("sprite_tags", []) or []:
        _t = normalize_sprite_tag(_t)
        if not _t or _t in BUILTIN_SPRITE_TAGS or _t in _script_declared or _t in _custom_tags:
            continue
        _custom_tags.append(_t)
    modal["custom_sprite_tags"] = list(_custom_tags)
    if _custom_tags:
        persist_custom_sprite_tags_to_script(modal.get("script_file"), _custom_tags)

    template = {
        "is_scene_prop": is_prop,
        "has_collision": bool(modal.get("has_collision", True)),
        "is_visible": bool(modal.get("is_visible", True)),
        "name": f.get("Name", "").strip() or ("Scene Prop" if is_prop else "Fighter"),
        "library_source_name": str(modal.get("_editing_original_name") or f.get("Name","").strip() or ("Scene Prop" if is_prop else "Fighter")),
        "max_hp": 999999 if is_prop else max(1, safe_int(f.get("Max HP", "100"), 100)),
        "dmg_min": 0 if is_prop else max(0, safe_int(f.get("Min Damage", "5"), 5)),
        "dmg_max": 0 if is_prop else max(1, safe_int(f.get("Max Damage", "15"), 15)),
        "crit_chance": 0.0 if is_prop else min(100, max(0, safe_float(f.get("Crit Chance %", "10"), 10))) / 100,
        "crit_mult": 1.0 if is_prop else max(1.0, safe_float(f.get("Crit Multiplier", "1.5"), 1.5)),
        "speed": 0.0 if is_prop else max(10, safe_float(f.get("Speed", "180"), 180)),
        "scale": max(0.3, min(3.0, safe_float(f.get("Scale", "1.0"), 1.0))),
        "character_center": _character_center_value(modal.get("character_center",[0.5,0.5])),
        "radius": float(modal.get("visual_radius", 16.0)),
        "contact_trait": str(modal.get("contact_trait", "normal")),
        "contact_traits": [],
        "color": list(modal["color"]),
        "script_file": modal["script_file"],
        "sprite_folder": modal["sprite_folder"],
        "sprite_map": dict(modal.get("sprite_map", {})),
        "custom_sprite_tags": list(_custom_tags),
        "script_params": script_params,
        "audio_map": dict(modal.get("audio_map", {})),
        "audio_volume_map": dict(modal.get("audio_volume_map", {})),
        "animations": {k: list(v) for k, v in modal.get("animation_frames", {}).items()},
        "animation_fps": dict(modal.get("animation_fps", {})),
        "animation_durations": {k: list(v) for k, v in modal.get("animation_durations", {}).items()},
        "animation_frame_offsets": {k: [list(x) for x in v] for k, v in (modal.get("animation_frame_offsets") or {}).items()},
        "animation_sources": dict(modal.get("animation_sources", {})),
        "animation_anchors": {k: list(v) for k, v in modal.get("animation_anchors", {}).items()},
        "animation_pivots": {k: list(v) for k, v in modal.get("animation_pivots", {}).items()},
        "animation_position_events": copy.deepcopy(modal.get("animation_position_events",{})),
        "animation_collision_frames": copy.deepcopy(modal.get("animation_collision_frames",{})),
        "friendly_fire": modal.get("friendly_fire", True),
        "collision_source": modal.get("collision_source", "custom"),
        "collision_debug_color": list(modal.get("collision_debug_color", [110, 195, 255])),
        "collision_debug_editor_visible": bool(modal.get("collision_debug_editor_visible", True)),
        "collision_debug_play_visible": bool(modal.get("collision_debug_play_visible", True)),
        "collision_debug_fill": bool(modal.get("collision_debug_fill", True)),
        "collision_shape": modal.get("collision_shape", "sphere"),
        "collision_radius": float(modal.get("collision_radius", 16)),
        "collision_radius_x": float(modal.get("collision_radius_x", modal.get("collision_radius", 16))),
        "collision_radius_y": float(modal.get("collision_radius_y", modal.get("collision_radius_x", modal.get("collision_radius", 16)))),
        "collision_box_w": float(modal.get("collision_box_w", 32)),
        "collision_box_h": float(modal.get("collision_box_h", 32)),
        "collision_offset_x": float(modal.get("collision_offset_x", 0.0)),
        "collision_offset_y": float(modal.get("collision_offset_y", 0.0)),
        "rig": _rig_normalize(modal.get("char_rig")),
        "anim_machine": _anim_machine_normalize(
            modal.get("anim_machine"),
            known_states=list(dict.fromkeys(list(modal.get("animation_frames",{}).keys())+list(modal.get("sprite_map",{}).keys())+list((modal.get("animation_layers",{}) or {}).keys())))),
        "animation_layers": anim_serialize_layers(),
    }

    editing = modal.get("editing")
    if editing is not None and any(editing is c for c in characters):
        _source_name=str(editing.get("library_source_name") or modal.get("_editing_original_name") or editing.get("name","") or "")
        if _apply_template_to_live_character(editing, template):
            push_toast(f"Updated live instance [{editing.get('instance_id', '')}] with new parameters.", "success", 4.0)
        if modal.get("_apply_live_to_library"):
            _library_entry=next((entry for entry in LIBRARY if str(entry.get("name",""))==_source_name),None)
            if _library_entry is None:_library_entry=next((entry for entry in LIBRARY if str(entry.get("name",""))==str(template.get("name",""))),None)
            _saved=copy.deepcopy(template);_saved["library_source_name"]=str(template.get("name","Fighter"))
            if _library_entry is None:LIBRARY.append(_saved)
            else:_library_entry.clear();_library_entry.update(_saved)
            editing["library_source_name"]=str(template.get("name","Fighter"));save_library()
            push_toast(f"Applied live character to Library: {template.get('name','Fighter')} · audio, script, sprites, animations and rig saved.","success",5.0)
        close_modal()
        return
    if editing is not None and editing in LIBRARY:
        editing.clear()
        editing.update(template)
        save_library()
        # ── Push changes to every live character that was spawned from
        # this library entry (matched by name).  We update stats, script,
        # sprites and animations in-place so the character keeps its
        # current HP / position / velocity — only its template data changes.
        updated = 0
        for c in characters:
            if c.get("name") != template["name"]:
                continue
            # Object role / authoring flags.  This is deliberately updated
            # in-place so toggling "Visible in Arena" immediately repairs an
            # already-spawned prop without making the user respawn the scene.
            c["is_scene_prop"] = bool(template.get("is_scene_prop", False))
            _live_prop_visible = bool(template.get("is_visible", True))
            c["scene_director"] = bool(c["is_scene_prop"] and (template.get("scene_director", False) or not _live_prop_visible))
            c["is_visible"] = _live_prop_visible if c["is_scene_prop"] and not c["scene_director"] else (False if c["scene_director"] else True)
            c["_prop_has_collision"] = bool(template.get("has_collision", True)) if c["is_scene_prop"] else False
            c["has_collision"] = bool(template.get("has_collision", True)) if not c["scene_director"] else False
            c["body_type"] = "static" if c["is_scene_prop"] else "dynamic"
            c["manual_input_enabled"] = not c["is_scene_prop"]
            c["show_hp_bar"] = False if c["is_scene_prop"] else None
            c["show_name"] = True if c["is_scene_prop"] else None
            if c["is_scene_prop"]:
                c["vel"] = pygame.Vector2()
                c["_smooth_vel"] = pygame.Vector2()
            # Stats
            c["max_hp"]      = template["max_hp"]
            c["dmg_min"]     = template["dmg_min"]
            c["dmg_max"]     = template["dmg_max"]
            c["crit_chance"] = template["crit_chance"]
            c["crit_mult"]   = template["crit_mult"]
            c["speed"]       = template["speed"]
            c["scale"]       = template.get("scale", 1.0)
            c["character_center"] = _character_center_value(template)
            c["color"]       = tuple(template["color"])
            c["radius"]      = float(template.get("radius", c.get("radius", 16)))
            c["contact_trait"] = str(template.get("contact_trait", c.get("contact_trait", "normal")))
            c["_contact_traits"] = list(template.get("contact_traits", c.get("_contact_traits", [])))
            c["collision_source"] = str(template.get("collision_source", "custom"))
            c["collision_debug_color"] = list(template.get("collision_debug_color", [110, 195, 255]))
            c["collision_debug_editor_visible"] = bool(template.get("collision_debug_editor_visible", template.get("collision_debug_visible", True)))
            c["collision_debug_play_visible"] = bool(template.get("collision_debug_play_visible", template.get("collision_debug_visible", True)))
            c["collision_debug_fill"] = bool(template.get("collision_debug_fill", True))
            c["collision_shape"] = str(template.get("collision_shape", "sphere"))
            c["collision_radius"] = float(template.get("collision_radius", c.get("radius", 16)))
            c["collision_radius_x"] = float(template.get("collision_radius_x", template.get("collision_radius", c.get("radius", 16))))
            c["collision_radius_y"] = float(template.get("collision_radius_y", template.get("collision_radius_x", template.get("collision_radius", c.get("radius", 16)))))
            c["collision_box_w"] = float(template.get("collision_box_w", 32))
            c["collision_box_h"] = float(template.get("collision_box_h", 32))
            c["collision_offset_x"] = float(template.get("collision_offset_x", 0.0))
            c["collision_offset_y"] = float(template.get("collision_offset_y", 0.0))
            c["friendly_fire"] = template.get("friendly_fire", True)
            c["audio_map"]         = dict(template.get("audio_map", {}))
            c["audio_volume_map"]  = dict(template.get("audio_volume_map", {}))
            c["sprite_map"]        = dict(template.get("sprite_map", {}))
            c["custom_sprite_tags"] = [str(t) for t in (template.get("custom_sprite_tags") or []) if isinstance(t, str) and t]
            c["script_file"]       = template.get("script_file")
            c["script_params"]     = dict(template.get("script_params", {}))

            # Reload script namespace with fresh params
            new_ns = load_script_ns_from_file(c["script_file"])
            apply_script_params(new_ns, c["script_params"])
            c["script_ns"] = new_ns

            # Reload sprites
            new_sprites = dict(load_sprites(template.get("sprite_folder", ""))) if template.get("sprite_folder") else {}
            for tag, rel_path in c["sprite_map"].items():
                img = load_sprite_asset(rel_path)
                if img is not None:
                    new_sprites[tag] = img
            c["sprites"] = new_sprites

            # Reload animations
            anim_defs = {}; anim_fps = {}; anim_dur = {}; anim_anchors = {}
            # Do not inject unrelated global clips into this character.
            for k, v in template.get("animations", {}).items():
                anim_defs[str(k)] = list(v)
            for k, v in template.get("animation_fps", {}).items():
                anim_fps[str(k)] = float(v)
            for k, v in template.get("animation_durations", {}).items():
                anim_dur[str(k)] = [max(0.02, float(x)) for x in v]
            for k, v in template.get("animation_anchors", {}).items():
                try: anim_anchors[str(k)] = (float(v[0]), float(v[1]))
                except: pass

            anim_surfaces = {}
            for state, paths in anim_defs.items():
                frames = [img for img in (load_sprite_asset(p) for p in paths) if img]
                if frames:
                    anim_surfaces[state] = frames
            c["animations"]        = anim_surfaces
            c["animation_fps"]     = anim_fps
            c["animation_durations"] = anim_dur
            c["animation_anchors"] = anim_anchors
            c["animation_pivots"]={str(k):list(v) for k,v in dict(template.get("animation_pivots",{})).items()}
            c["animation_position_events"]=copy.deepcopy(dict(template.get("animation_position_events",{})))
            c["animation_collision_frames"]=copy.deepcopy(dict(template.get("animation_collision_frames",{})))
            c["animation_layers"]=copy.deepcopy(dict(template.get("animation_layers",{})))
            c["animation_total_durations"] = {k: sum(v) for k, v in anim_dur.items()}
            c["animation_paths"]   = anim_defs
            updated += 1

        if updated:
            push_toast(f"Updated {updated} live '{template['name']}' instance(s) in scene.", "success", 4.0)
    else:
        LIBRARY.append(template)
        save_library()
        inst = spawn_instance(template)
        play_audio_cue(inst, "spawn")
        characters.append(inst)
    close_modal()

def _apply_modal_hex_color():
    """If the user typed into the HEX field of a colour-picker modal, parse it
    into modal['color'] before the change is committed."""
    hx = modal.get("_hex_input", "")
    if isinstance(hx, str):
        hx = hx.lstrip("#").strip()
        if len(hx) == 6 and all(ch in "0123456789abcdefABCDEF" for ch in hx):
            try:
                modal["color"] = (int(hx[0:2], 16), int(hx[2:4], 16), int(hx[4:6], 16))
            except Exception:
                pass

