# ============================================================
# PYGAME-CE MIGRATION + LOADING SCREEN SYSTEM
# ============================================================
# Detect pygame-ce
try:
    _ver_str = getattr(pygame.version, "ver", "") or getattr(pygame, "__version__", "")
    IS_CE = bool(getattr(pygame, "IS_CE", False)) or ("ce" in _ver_str.lower())
except Exception:
    IS_CE = False

# Flags to defer per-frame heavy work until needed
HEAVY_PER_FRAME_ENABLED = False
# User-controlled preload acceleration. Work remains on the main thread because
# pygame surfaces/caches are not thread-safe; acceleration increases the safe
# time-slice, never launches an unbounded thread storm.
_PRELOAD_FORCE_ACTIVE=bool(_editor_config.get("preload_force_active",False))
_PRELOAD_SPEED_MODE=str(_editor_config.get("preload_speed_mode","x2"))
if _PRELOAD_SPEED_MODE not in ("x2","x4","max"):_PRELOAD_SPEED_MODE="x2"
_PRELOAD_MAX_DYNAMIC=0.035
_PRELOAD_LAST_FRAME=0.0
_PRELOAD_CONTROL_RECTS={}
_BACKGROUND_PRELOAD_COLLAPSED=bool(_editor_config.get("background_preload_collapsed",False))
_BACKGROUND_PRELOAD_POS=tuple(_editor_config.get("background_preload_pos",())) if isinstance(_editor_config.get("background_preload_pos"),list) and len(_editor_config.get("background_preload_pos"))==2 else None
_BACKGROUND_PRELOAD_PANEL_RECT=None
_BACKGROUND_PRELOAD_DRAG=None


def _preload_cpu_ceiling():
    cores=max(1,int(os.cpu_count() or 2))
    # 2-core laptops retain a tighter UI heartbeat; larger systems may spend
    # more of each frame on load work, capped at 85 ms for responsiveness.
    return max(.025,min(.085,.018+cores*.006))


def _preload_work_budget(base_budget,force=False):
    base=max(.001,float(base_budget))
    if not (_PRELOAD_FORCE_ACTIVE or force):return base
    if _PRELOAD_SPEED_MODE=="x2":return min(.045,base*2.0)
    if _PRELOAD_SPEED_MODE=="x4":return min(.070,base*4.0)
    return max(.012,min(_preload_cpu_ceiling(),float(_PRELOAD_MAX_DYNAMIC)))


def _preload_adapt_max(frame_duration):
    global _PRELOAD_MAX_DYNAMIC,_PRELOAD_LAST_FRAME
    _PRELOAD_LAST_FRAME=max(0.0,float(frame_duration))
    if not _PRELOAD_FORCE_ACTIVE or _PRELOAD_SPEED_MODE!="max":return
    ceiling=_preload_cpu_ceiling()
    # Back off quickly after a long/unresponsive frame; climb slowly while the
    # UI heartbeat is healthy. This avoids thermal/CPU runaway and bottlenecks.
    if frame_duration>.110:_PRELOAD_MAX_DYNAMIC=max(.012,_PRELOAD_MAX_DYNAMIC*.68)
    elif frame_duration>.075:_PRELOAD_MAX_DYNAMIC=max(.014,_PRELOAD_MAX_DYNAMIC*.84)
    elif frame_duration<.045:_PRELOAD_MAX_DYNAMIC=min(ceiling,_PRELOAD_MAX_DYNAMIC*1.07+.001)


def _set_preload_force(enabled=None,mode=None):
    global _PRELOAD_FORCE_ACTIVE,_PRELOAD_SPEED_MODE,_PRELOAD_MAX_DYNAMIC
    if mode in ("x2","x4","max"):_PRELOAD_SPEED_MODE=mode;_PRELOAD_FORCE_ACTIVE=True
    elif enabled is not None:_PRELOAD_FORCE_ACTIVE=bool(enabled)
    _PRELOAD_MAX_DYNAMIC=min(_preload_cpu_ceiling(),max(.025,_PRELOAD_MAX_DYNAMIC))
    _editor_config["preload_force_active"]=_PRELOAD_FORCE_ACTIVE
    _editor_config["preload_speed_mode"]=_PRELOAD_SPEED_MODE
    save_editor_config(_editor_config)


def _preload_control_layout(sw,sh):
    # Dedicated footer row: controls can never overlap the status text/bar.
    y=max(70,int(sh)-36);x=10
    force=pygame.Rect(x,y,112,26);x=force.right+7
    x2=pygame.Rect(x,y,45,26);x=x2.right+5
    x4=pygame.Rect(x,y,45,26);x=x4.right+5
    maximum=pygame.Rect(x,y,58,26)
    return {"force":force,"x2":x2,"x4":x4,"max":maximum}


def _handle_preload_control_click(pos):
    global _BACKGROUND_PRELOAD_COLLAPSED
    rects=_PRELOAD_CONTROL_RECTS
    if rects.get("collapse") and rects["collapse"].collidepoint(pos):
        _BACKGROUND_PRELOAD_COLLAPSED=not _BACKGROUND_PRELOAD_COLLAPSED
        _editor_config["background_preload_collapsed"]=_BACKGROUND_PRELOAD_COLLAPSED
        save_editor_config(_editor_config);return True
    if rects.get("force") and rects["force"].collidepoint(pos):_set_preload_force(not _PRELOAD_FORCE_ACTIVE);return True
    for mode in ("x2","x4","max"):
        if rects.get(mode) and rects[mode].collidepoint(pos):_set_preload_force(mode=mode);return True
    return False


BACKGROUND_PRELOAD_DONE = True
_BACKGROUND_PRELOAD_SECTIONS = []
_BACKGROUND_PRELOAD_INDEX = 0
_BACKGROUND_PRELOAD_GEN = None
_BACKGROUND_PRELOAD_LABEL = ""
_BACKGROUND_PRELOAD_DETAIL = ""
_BACKGROUND_PRELOAD_FRAC = 0.0
_BACKGROUND_PRELOAD_DONE_AT = 0.0


def queue_background_preloads(sections, skipped_keys):
    """Continue genuinely skipped splash work incrementally after the splash."""
    global BACKGROUND_PRELOAD_DONE, _BACKGROUND_PRELOAD_SECTIONS
    global _BACKGROUND_PRELOAD_INDEX, _BACKGROUND_PRELOAD_GEN
    global _BACKGROUND_PRELOAD_LABEL, _BACKGROUND_PRELOAD_DETAIL
    global _BACKGROUND_PRELOAD_FRAC, _BACKGROUND_PRELOAD_DONE_AT
    wanted = set(skipped_keys or ())
    _BACKGROUND_PRELOAD_SECTIONS = [
        (key, label, factory) for key, label, factory, _skippable in sections
        if key in wanted
    ]
    _BACKGROUND_PRELOAD_INDEX = 0
    _BACKGROUND_PRELOAD_GEN = None
    _BACKGROUND_PRELOAD_LABEL = ""
    _BACKGROUND_PRELOAD_DETAIL = ""
    _BACKGROUND_PRELOAD_FRAC = 0.0
    _BACKGROUND_PRELOAD_DONE_AT = 0.0
    BACKGROUND_PRELOAD_DONE = not bool(_BACKGROUND_PRELOAD_SECTIONS)


def background_preload_progress():
    total = len(_BACKGROUND_PRELOAD_SECTIONS)
    if total <= 0:
        return 1.0
    return max(0.0, min(1.0,
        (_BACKGROUND_PRELOAD_INDEX + _BACKGROUND_PRELOAD_FRAC) / total))


def background_preload_status_text():
    pct = int(round(background_preload_progress() * 100))
    if BACKGROUND_PRELOAD_DONE:
        return "Background loading complete · 100%"
    detail = (" · " + _BACKGROUND_PRELOAD_DETAIL) if _BACKGROUND_PRELOAD_DETAIL else ""
    return f"Background loading {pct}% · {_BACKGROUND_PRELOAD_LABEL}{detail}"


def run_next_background_task(force=False):
    """Advance skipped preload generators without freezing the main UI."""
    global BACKGROUND_PRELOAD_DONE, _BACKGROUND_PRELOAD_INDEX
    global _BACKGROUND_PRELOAD_GEN, _BACKGROUND_PRELOAD_LABEL
    global _BACKGROUND_PRELOAD_DETAIL, _BACKGROUND_PRELOAD_FRAC
    global _BACKGROUND_PRELOAD_DONE_AT
    if BACKGROUND_PRELOAD_DONE:
        return 1.0
    base_budget=0.010 if force else 0.003
    deadline=time.perf_counter()+_preload_work_budget(base_budget,force=force)
    advanced_once = False
    while time.perf_counter() < deadline or not advanced_once:
        if _BACKGROUND_PRELOAD_INDEX >= len(_BACKGROUND_PRELOAD_SECTIONS):
            BACKGROUND_PRELOAD_DONE = True
            _BACKGROUND_PRELOAD_FRAC = 0.0
            _BACKGROUND_PRELOAD_DETAIL = ""
            _BACKGROUND_PRELOAD_DONE_AT = time.time()
            break
        key, label, factory = _BACKGROUND_PRELOAD_SECTIONS[_BACKGROUND_PRELOAD_INDEX]
        _BACKGROUND_PRELOAD_LABEL = label
        if _BACKGROUND_PRELOAD_GEN is None:
            try:
                _BACKGROUND_PRELOAD_GEN = factory()
            except Exception as exc:
                print(f"background preload {key} factory failed:", exc)
                _BACKGROUND_PRELOAD_INDEX += 1
                continue
        try:
            info = next(_BACKGROUND_PRELOAD_GEN)
            advanced_once = True
            if isinstance(info, tuple):
                if len(info) >= 1:
                    _BACKGROUND_PRELOAD_LABEL = str(info[0])
                if len(info) >= 3:
                    cur, total = int(info[1]), max(1, int(info[2]))
                    _BACKGROUND_PRELOAD_FRAC = max(0.0, min(1.0, cur / total))
                    _BACKGROUND_PRELOAD_DETAIL = f"{cur}/{total}"
                else:
                    _BACKGROUND_PRELOAD_DETAIL = ""
            if not force:
                break
        except StopIteration:
            _BACKGROUND_PRELOAD_GEN = None
            _BACKGROUND_PRELOAD_INDEX += 1
            _BACKGROUND_PRELOAD_FRAC = 0.0
            _BACKGROUND_PRELOAD_DETAIL = ""
        except Exception as exc:
            print(f"background preload {key} failed:", exc)
            _BACKGROUND_PRELOAD_GEN = None
            _BACKGROUND_PRELOAD_INDEX += 1
            _BACKGROUND_PRELOAD_FRAC = 0.0
    return background_preload_progress()


def handle_background_preload_drag_event(event):
    """Drag the loader by its header, exactly like Nerd Stats/Frame Costs."""
    global _BACKGROUND_PRELOAD_DRAG,_BACKGROUND_PRELOAD_POS
    rect=globals().get("_BACKGROUND_PRELOAD_PANEL_RECT")
    if event.type==pygame.MOUSEBUTTONDOWN and event.button==1 and isinstance(rect,pygame.Rect):
        collapse=(_PRELOAD_CONTROL_RECTS or {}).get("collapse")
        header=pygame.Rect(rect.x,rect.y,rect.width,min(24,rect.height))
        if header.collidepoint(event.pos) and not (collapse and collapse.collidepoint(event.pos)):
            _BACKGROUND_PRELOAD_DRAG={"dx":event.pos[0]-rect.x,"dy":event.pos[1]-rect.y};return True
    if event.type==pygame.MOUSEMOTION and _BACKGROUND_PRELOAD_DRAG and isinstance(rect,pygame.Rect):
        nx=max(4,min(max(4,WIDTH-rect.width-4),event.pos[0]-_BACKGROUND_PRELOAD_DRAG["dx"]));ny=max(4,min(max(4,HEIGHT-rect.height-4),event.pos[1]-_BACKGROUND_PRELOAD_DRAG["dy"]));_BACKGROUND_PRELOAD_POS=(nx,ny);return True
    if event.type==pygame.MOUSEBUTTONUP and event.button==1 and _BACKGROUND_PRELOAD_DRAG:
        _BACKGROUND_PRELOAD_DRAG=None
        if _BACKGROUND_PRELOAD_POS is not None:
            _editor_config["background_preload_pos"]=[int(_BACKGROUND_PRELOAD_POS[0]),int(_BACKGROUND_PRELOAD_POS[1])];save_editor_config(_editor_config)
        return True
    return False


def draw_background_preload_status():
    """Collapsible background-loader panel using the Performance/Frame Costs shell."""
    global _PRELOAD_CONTROL_RECTS,_BACKGROUND_PRELOAD_PANEL_RECT
    if _UI_KILLED or is_recording or _OBS_RECORDING_ACTIVE or modal.get("type")=="env3d_embedded":_PRELOAD_CONTROL_RECTS={};_BACKGROUND_PRELOAD_PANEL_RECT=None;return
    if not _BACKGROUND_PRELOAD_SECTIONS:_BACKGROUND_PRELOAD_PANEL_RECT=None;return
    if BACKGROUND_PRELOAD_DONE and time.time()-_BACKGROUND_PRELOAD_DONE_AT>3.0:_BACKGROUND_PRELOAD_PANEL_RECT=None;return
    try:
        collapsed=bool(_BACKGROUND_PRELOAD_COLLAPSED);wid=min(430,max(330,WIDTH-28));hei=24 if collapsed else 108
        if _BACKGROUND_PRELOAD_POS is None: px,py=WIDTH//2-wid//2,42
        else: px=max(4,min(WIDTH-wid-4,int(_BACKGROUND_PRELOAD_POS[0])));py=max(4,min(HEIGHT-hei-4,int(_BACKGROUND_PRELOAD_POS[1])))
        panel=pygame.Rect(px,py,wid,hei);_BACKGROUND_PRELOAD_PANEL_RECT=panel.copy()
        shell=pygame.Surface(panel.size,pygame.SRCALPHA);shell.fill((8,8,12,232));screen.blit(shell,panel.topleft)
        ui_draw_rect(screen,(60,58,78),panel,width=1,border_radius=5)
        header=pygame.Rect(panel.x,panel.y,panel.width,24)
        ui_draw_rect(screen,PANEL_BG_ALT,header,border_top_left_radius=5,border_top_right_radius=5)
        pygame.draw.line(screen,DIVIDER,(header.x,header.bottom-1),(header.right,header.bottom-1),1)
        _icol=GOOD if BACKGROUND_PRELOAD_DONE else ACCENT
        hic=get_icon_fs("download",13,_icol) or get_icon_fs("arrow_down_",13,_icol)
        if hic:screen.blit(hic,(header.x+8,header.centery-hic.get_height()//2))
        else:
            # Built-in vector fallback: icon remains visible even if an icon pack is incomplete.
            pygame.draw.line(screen,_icol,(header.x+14,header.y+5),(header.x+14,header.y+14),2)
            pygame.draw.polygon(screen,_icol,[(header.x+10,header.y+11),(header.x+18,header.y+11),(header.x+14,header.y+16)])
            pygame.draw.line(screen,_icol,(header.x+9,header.y+18),(header.x+19,header.y+18),2)
        pct=int(round(background_preload_progress()*100));title=f"BACKGROUND LOADING  ·  {pct}%  ·  DRAG"
        screen.blit(font_tiny.render(title,True,TEXT_DIM),(header.x+27,header.y+6))
        cr=pygame.Rect(header.right-25,header.y+3,20,18);_PRELOAD_CONTROL_RECTS={"collapse":cr}
        ui_draw_rect(screen,FIELD_BG if not cr.collidepoint(pygame.mouse.get_pos()) else FIELD_FOCUS,cr,border_radius=4)
        # Explicit vector chevron — never depends on PyTabler/font glyph coverage.
        if collapsed: pygame.draw.polygon(screen,ACCENT,[(cr.centerx-4,cr.centery-5),(cr.centerx+5,cr.centery),(cr.centerx-4,cr.centery+5)])
        else: pygame.draw.polygon(screen,ACCENT,[(cr.centerx-5,cr.centery-3),(cr.centerx+5,cr.centery-3),(cr.centerx,cr.centery+5)])
        if collapsed:return
        detail=(_BACKGROUND_PRELOAD_LABEL or "Preparing assets") + (("  ·  "+_BACKGROUND_PRELOAD_DETAIL) if _BACKGROUND_PRELOAD_DETAIL else "")
        detail=truncate_text_to_width(font_tiny,detail,panel.width-20)
        screen.blit(font_tiny.render(detail,True,TEXT_MAIN),(panel.x+10,panel.y+31))
        bar=pygame.Rect(panel.x+10,panel.y+49,panel.width-20,10);ui_draw_rect(screen,FIELD_BG,bar,border_radius=5)
        fill=bar.copy();fill.width=max(0,int(bar.width*background_preload_progress()))
        if fill.width:ui_draw_rect(screen,GOOD if BACKGROUND_PRELOAD_DONE else ACCENT,fill,border_radius=5)
        ui_draw_rect(screen,PANEL_BORDER,bar,width=1,border_radius=5)
        local=_preload_control_layout(panel.width,panel.height)
        for key,rect in local.items():rect.move_ip(panel.x,panel.y);_PRELOAD_CONTROL_RECTS[key]=rect
        mouse=pygame.mouse.get_pos();defs=(("force","FORCE ON" if _PRELOAD_FORCE_ACTIVE else "FORCE LOAD"),("x2","×2"),("x4","×4"),("max","MAX"))
        for key,label in defs:
            r=_PRELOAD_CONTROL_RECTS[key];active=_PRELOAD_FORCE_ACTIVE and (key=="force" or key==_PRELOAD_SPEED_MODE)
            ui_draw_rect(screen,ACCENT if active else FIELD_BG,r,border_radius=5);ui_draw_rect(screen,ACCENT_HOVER if r.collidepoint(mouse) else PANEL_BORDER,r,width=1,border_radius=5)
            ts=font_tiny.render(label,True,(10,10,14) if active else TEXT_DIM);screen.blit(ts,(r.centerx-ts.get_width()//2,r.centery-ts.get_height()//2))
    except Exception:pass


def _scene_editor_runtime_state():
    """Return live authoring systems that must keep ticking/presenting.

    Scene authoring is not the same thing as a running match: character-follow
    constraints, a manually played particle emitter, bar easing, and explicit
    scene tweens are expected to preview while the match is stopped.  The old
    optimization treated all of them as idle and left their last pixels frozen.
    """
    follow=False;smooth=False;tweens=False;emitters=False
    try:
        for en in external_nodes:
            if not isinstance(en,dict):continue
            if en.get("char_follow_enabled",False):follow=True
            if en.get("_tweens"):tweens=True
            if en.get("kind") in ("progress_bar","custom_progress_bar") and en.get("smooth",True) and float(en.get("smooth_speed",4.0) or 0)>0:
                try:
                    target=float(en.get("value",0.0));current=en.get("_smooth_val")
                    smooth=smooth or current is None or abs(target-float(current))>.001 or abs(float(en.get("_smooth_shake",0.0) or 0.0))>.001
                except (TypeError,ValueError):pass
        if not tweens:
            tweens=any(isinstance(it,dict) and it.get("_tweens") for coll in (scene_texts,scene_images) for it in coll)
        if not SETTINGS.get("freeze_particles",False):
            emitters=any(isinstance(em,dict) and em.get("enabled",True) and (em.get("emitting",False) or bool(em.get("_particles"))) for em in particle_emitters)
    except Exception:
        # Correctness wins if a malformed authoring object enters the list.
        follow=smooth=tweens=emitters=True
    return {"follow":bool(follow),"smooth":bool(smooth),"tweens":bool(tweens),"emitters":bool(emitters)}


def should_do_heavy_tick():
    # Only tick heavy systems when we actually need them
    try:
        if simulation_started:
            return True
        if characters:
            return True
        if modal.get("type") == "visual_scripter":
            return True
        if world_effects or particles or area_zones:
            return True
        if external_nodes:
            # only if any visible
            return any(en.get("visible", True) for en in external_nodes)
        return False
    except:
        return True

# Show project manager on startup
def _preload_all_media_assets():
    """Preload all imported sprites and audio files into memory at startup."""
    try:
        sprites = list_sprite_assets(force=True)
        if isinstance(sprites, (list, tuple)):
            for rel in sprites:
                try:
                    load_sprite_asset(rel)
                except Exception:
                    pass
        audios = list_imported_audio()
        if isinstance(audios, (list, tuple)):
            for rel in audios:
                try:
                    register_audio_asset(os.path.join(BASE_DIR, rel))
                except Exception:
                    pass
    except Exception as e:
        print("Media preloading complete:", e)

def show_project_manager():
    global modal_scroll
    from_3d=False
    # Snapshot the live canvas so the tile view has a fresh thumb.
    capture_project_thumbnail()
    modal["_pm_return_env3d"] = bool(from_3d)
    modal["_pm_workspace"]="arena2d"
    modal["type"] = "project_manager"
    modal["focus"] = None
    modal["_ui_window_id"] = "project_manager"
    modal_scroll = 0.0

