# ============================================================
# icon.* controls only the OS window/taskbar icon. logo.* is a separate,
# explicit opt-in image for the loading screen/sidebar branding. mainfont.*
# controls splash typography. All assets fall back gracefully when absent.
_CUSTOM_LOGO_SURF = None
_CUSTOM_SPLASH_FONT_TITLE = None
_CUSTOM_SPLASH_FONT_STEP = None
_CUSTOM_SPLASH_FONT_SMALL = None
_APP_LOGO_PATH = None

def _load_custom_app_assets():
    """Look for logo/icon and mainfont next to this script and preload them."""
    global _CUSTOM_LOGO_SURF, _CUSTOM_SPLASH_FONT_TITLE
    global _CUSTOM_SPLASH_FONT_STEP, _CUSTOM_SPLASH_FONT_SMALL, _APP_LOGO_PATH
    _asset_roots=tuple(dict.fromkeys((RESOURCE_DIR,BASE_DIR)))
    _CUSTOM_LOGO_SURF=None;_APP_LOGO_PATH=None
    for fname in ("logo.png","logo.ico","Logo.png","Logo.ico"):
        for _root in _asset_roots:
            p=os.path.join(_root,fname)
            if not os.path.isfile(p):continue
            surf=_load_image_surface(p)
            if surf is None:continue
            try:
                try:surf=surf.convert_alpha()
                except Exception:
                    try:surf=surf.convert()
                    except Exception:pass
            except Exception:pass
            _CUSTOM_LOGO_SURF=surf;_APP_LOGO_PATH=p;break
        if _CUSTOM_LOGO_SURF is not None:break
    # Re-assert the OS icon after display recreation, without promoting it to a
    # logo. Only an explicit logo.* is allowed inside loading/sidebar UI.
    _window_icon=globals().get("_EARLY_APP_ICON_SURF") or _CUSTOM_LOGO_SURF
    if _window_icon is not None:
        try:pygame.display.set_icon(_window_icon)
        except Exception:pass
    _CUSTOM_SPLASH_FONT_TITLE=None;_CUSTOM_SPLASH_FONT_STEP=None;_CUSTOM_SPLASH_FONT_SMALL=None
    for fname in ("mainfont.ttf","mainfont.otf","MainFont.ttf","MainFont.otf"):
        _font_loaded=False
        for _root in _asset_roots:
            p=os.path.join(_root,fname)
            if not os.path.isfile(p):continue
            try:
                _CUSTOM_SPLASH_FONT_TITLE=pygame.font.Font(p,48);_CUSTOM_SPLASH_FONT_STEP=pygame.font.Font(p,14);_CUSTOM_SPLASH_FONT_SMALL=pygame.font.Font(p,12);_font_loaded=True;break
            except Exception as e:print("mainfont load failed:",e)
        if _font_loaded:break

