def _preload_blueprints_iter():
    yield ("Blueprint Core", 0, 6)
    try:
        if 'NODE_DEFS' in globals() and isinstance(NODE_DEFS, dict):
            _ = len(NODE_DEFS)
            # Touch every node def's category/color so first-canvas-paint has them
            _cats = set()
            for _nd in NODE_DEFS.values():
                if isinstance(_nd, dict):
                    c = _nd.get("category")
                    if c: _cats.add(c)
            yield ("Blueprint Core", 1, 6)
            if 'ns_category_color' in globals():
                for _cat in sorted(_cats) or ["Events","Math","Logic","Variables","Animation","Audio","Debugging","Control","Flow","Comparison"]:
                    try: ns_category_color(_cat)
                    except Exception: pass
            yield ("Blueprint Core", 2, 6)
            # Pre-render a handful of common node-title glyphs/fonts so text cache is warm
            _sizes = [11,12,13,14]
            _faces = ["segoeui"]
            for _sz in _sizes:
                for _face in _faces:
                    for _bold in (False, True):
                        try:
                            if 'get_dmg_font' in globals(): get_dmg_font(_sz, _face, bold=_bold)
                        except Exception: pass
            yield ("Blueprint Core", 3, 6)
            # Touch node-icon surface cache for a few common kinds
            for _ic in ("event","var","number","string","bool","branch","loop","print","add","sub"):
                try:
                    if 'get_icon_fs' in globals(): get_icon_fs(_ic, 12, (255,255,255))
                except Exception: pass
            yield ("Blueprint Core", 4, 6)
        else:
            yield ("Blueprint Core", 4, 6)
    except Exception:
        yield ("Blueprint Core", 4, 6)
    # Build default script-ns cache entry so first node compile isn't cold
    try:
        if 'ensure_script_namespace' in globals():
            try: ensure_script_namespace("__startup_preload__")
            except Exception: pass
    except Exception: pass
    yield ("Blueprint Core", 5, 6)
    yield ("Blueprint Ready", 6, 6)

def _preload_ui_iter():
    yield ("UI Warmup", 0, 7)
    yield ("UI Warmup", 1, 7)
    try:
        if 'get_dmg_font' in globals():
            for _sz in (10,11,12,13,14,16,18,22):
                for _bold in (False, True):
                    try: get_dmg_font(_sz, "segoeui", bold=_bold)
                    except Exception: pass
        yield ("UI Warmup", 2, 7)
    except Exception:
        yield ("UI Warmup", 2, 7)
    try:
        if 'get_icon_fs' in globals():
            _icns = ["play","pause","stop","plus","x","search","save","folder",
                     "edit","copy","delete","undo","redo","import_","export",
                     "close","home","refresh","settings","star","heart"]
            for _i, _ic in enumerate(_icns):
                try: get_icon_fs(_ic, 14, (255,255,255))
                except Exception: pass
                if _i % 5 == 0:
                    yield ("UI Warmup", 3 + min(3,_i//5), 7)
        yield ("UI Warmup", 6, 7)
    except Exception:
        yield ("UI Warmup", 6, 7)
    # Pre-render a handful of common button/label sizes
    try:
        _fnt_test = None
        if 'get_dmg_font' in globals():
            _fnt_test = get_dmg_font(13,"segoeui",bold=False)
        if _fnt_test is not None:
            for _txt in ["Play","Pause","Stop","New","Save","Load","Cancel","OK","Add","Remove"]:
                try: _fnt_test.render(_txt, True, (255,255,255))
                except Exception: pass
    except Exception: pass
    yield ("UI Ready", 7, 7)

def _preload_logic_pause_iter():
    yield ("Logic Prep", 0, 4)
    # Warm up math/easing/timer helpers so first tick isn't stalling
    try:
        import math as _lm
        for _x in (0.0, 0.25, 0.5, 0.75, 1.0):
            _lm.sin(_x*3.14159); _lm.cos(_x*3.14159); _lm.sqrt(max(0.0,_x))
        yield ("Logic Prep", 1, 4)
    except Exception:
        yield ("Logic Prep", 1, 4)
    # Touch the particle/timer pools once
    try:
        if 'particle_emitters_tick' in globals():
            yield ("Logic Prep", 2, 4)
        else:
            yield ("Logic Prep", 2, 4)
    except Exception:
        yield ("Logic Prep", 2, 4)
    # Pre-touch the scene-proxy cache dict(s) so first render doesn't allocate
    try:
        for _cname in ("_SCENE_IMG_CACHE","_SCENE_TEXT_CACHE","_SCENE_CHAR_CACHE","_SCENE_PROXY_Q"):
            if _cname in globals() and isinstance(globals()[_cname], dict):
                pass
        yield ("Logic Prep", 3, 4)
    except Exception:
        yield ("Logic Prep", 3, 4)
    yield ("Ready", 4, 4)

