def _splash_pump_events(section_hit=None, all_hit=None):
    """Pump one frame of splash input. `section_hit` / `all_hit` are the live
    hit-rects of the two skip buttons, or None when that button is currently
    hidden/disabled - a hidden button can never be clicked (this was the bug
    where clicking where the button *used* to be still fired). Returns:
      'section'  - skip the current section
      'all'      - skip everything (2-step confirmed)
      'arm_all'  - first SKIP ALL click: arms the confirm state
      None       - nothing
    ESC always = immediate skip-all."""
    global _skip_all_confirm_t, _skip_cooldown_until
    res = None
    now = time.time()
    if _skip_cooldown_until > now:
        # still pump events (keep the window responsive) but ignore clicks
        for _ev in pygame.event.get():
            if _ev.type == pygame.QUIT: pygame.quit(); sys.exit(0)
        return None
    for _ev in pygame.event.get():
        if _ev.type == pygame.QUIT: pygame.quit(); sys.exit(0)
        if _ev.type == pygame.KEYDOWN and _ev.key == pygame.K_ESCAPE:
            res = "all"
        if _ev.type == pygame.MOUSEBUTTONDOWN and _ev.button == 1:
            if _handle_preload_control_click(_ev.pos):
                res="preload_control"
            elif section_hit is not None and section_hit.collidepoint(_ev.pos):
                res = "section"
            elif all_hit is not None and all_hit.collidepoint(_ev.pos):
                # two-step confirmation: first click arms, second confirms
                if now - _skip_all_confirm_t < 3.0:
                    res = "all"
                    _skip_all_confirm_t = 0.0
                else:
                    _skip_all_confirm_t = now
                    res = "arm_all"
    return res

# First paint -- force black screen immediately so the OS never sees an
# unpainted/stalled window ("Not Responding").
try:
    screen.fill((0,0,0)); pygame.display.flip()
    pygame.event.pump()
except Exception: pass
_splash_skip_section_rect = pygame.Rect(0,0,102,30)  # placeholder, recomputed each frame
_splash_skip_all_rect     = pygame.Rect(0,0,102,30)

done = bool(_APU_WORKER_BOOT)
_converge_start = None
_white_start = None
# Always animate: paint every frame regardless of whether work happened.
while not done:
    frame_start = time.time(); now = time.time()

    # Recompute button rects based on current screen size (safe if resized during splash)
    sw, sh = screen.get_size()
    _splash_skip_section_rect = pygame.Rect(sw-240, sh-50, 108, 30)
    _splash_skip_all_rect     = pygame.Rect(sw-124, sh-50, 110, 30)

    # End conditions first
    if _sec_idx >= _TOTAL_SECTIONS and _converge_start is None:
        _converge_start = now
    if _converge_start is not None and _white_start is None:
        ct = (now - _converge_start)/0.45  # a touch longer for merge
        if ct >= 1.0:
            _white_start = now; ct = 1.0
        # show buttons/hide warning during converge
        _draw_loading_screen(1.0, "Ready!", "", phase="converge", converge_t=ct,
                             skip_section_rect=None, skip_all_rect=None,
                             skip_all_warning=False)
        pygame.event.pump()
        # throttle to ~60fps
        _rem = (1.0/TARGET_FRAMERATE) - (time.time()-frame_start)
        if _rem > 0: time.sleep(_rem)
        continue
    if _white_start is not None:
        wt = (now - _white_start)/0.25
        if wt >= 1.0: done = True; break
        for _ev in pygame.event.get():
            if _ev.type == pygame.QUIT: pygame.quit(); sys.exit(0)
        _draw_loading_screen(1.0, "Ready!", "", phase="white", converge_t=wt,
                             skip_section_rect=None, skip_all_rect=None)
        _rem = (1.0/TARGET_FRAMERATE) - (time.time()-frame_start)
        if _rem > 0: time.sleep(_rem)
        continue

    # ── Do work for one budget window ──
    frame_deadline=frame_start+_preload_work_budget(_splash_budget)
    did_work = False
    cur_key = None; cur_skippable = False
    while time.time() < frame_deadline:
        if _sec_idx >= _TOTAL_SECTIONS: break
        did_work = True
        key, label, factory, skippable = _SECTIONS[_sec_idx]
        cur_key, cur_skippable = key, skippable
        _active_label = label
        if key in _skipped_sections:
            _sec_idx += 1; _active_gen = None; _sub_label = "skipped"; continue
        if _active_gen is None:
            try: _active_gen = factory()
            except Exception as e:
                print(f"splash section {key} factory failed:", e)
                _active_gen = None; _sec_idx += 1; continue
        advanced = False
        try:
            info = next(_active_gen); advanced = True
            if isinstance(info, tuple) and len(info) >= 1:
                _active_label = str(info[0])
                if len(info) >= 3:
                    c, tot = int(info[1]), max(1, int(info[2]))
                    _sub_label = f"{c} / {tot}"
                else: _sub_label = ""
        except StopIteration:
            _active_gen = None; _sub_label = ""; _sec_idx += 1
        except Exception as e:
            print(f"splash section {key} error:", e)
            _active_gen = None; _sec_idx += 1

        if not advanced: continue

    # Compute progress
    frac = 0.0
    if _sec_idx < _TOTAL_SECTIONS and _active_gen is not None and _sub_label:
        try:
            parts = _sub_label.replace(" ","").split("/")
            if len(parts) == 2:
                c, tot = int(parts[0]), max(1, int(parts[1]))
                frac = max(0.0, min(1.0, c/tot))
        except Exception: frac = 0.0
    overall = (_sec_idx + frac)/_TOTAL_SECTIONS

    # Determine button state (button is only active while its section is
    # skippable and not already skipped; cur_key is None if nothing ran this
    # frame, in which case there is no "current section" to skip).
    section_enabled = (cur_key is not None and cur_skippable
                       and _sec_idx < _TOTAL_SECTIONS
                       and cur_key not in _skipped_sections)
    all_enabled = _sec_idx < _TOTAL_SECTIONS
    warning_show = (time.time() - _skip_all_confirm_t) < 3.0 and _skip_all_confirm_t > 0
    cd = max(0.0, _skip_cooldown_until - time.time())

    # Handle this frame's input ONCE. Only the buttons that are actually
    # visible can be hit, and the section skip uses the section that was
    # really being processed this frame (no stale key/skippable races).
    try:
        click = _splash_pump_events(
            _splash_skip_section_rect if section_enabled else None,
            _splash_skip_all_rect if all_enabled else None)
        if click == "section":
            if cur_key is not None and cur_skippable and _sec_idx < _TOTAL_SECTIONS:
                _skipped_sections.add(cur_key)
                _active_gen = None; _sec_idx += 1; _sub_label = "skipped"
                _skip_cooldown_until = time.time() + 0.35
        elif click == "all":
            # mark every remaining skippable section as skipped;
            # non-skippable ones still run, they just finish quickly.
            for sk_i in range(_sec_idx, _TOTAL_SECTIONS):
                kk, _, _, skk = _SECTIONS[sk_i]
                if skk: _skipped_sections.add(kk)
            _skip_cooldown_until = time.time() + 0.45
            _skip_all_confirm_t = 0.0
    except Exception: pygame.event.pump()

    # Draw (always -- keeps blobs animating smoothly)
    _draw_loading_screen(overall, _active_label or "Loading", _sub_label,
                         phase="loading", converge_t=0.0,
                         skip_section_rect=_splash_skip_section_rect if section_enabled else None,
                         skip_all_rect=_splash_skip_all_rect if all_enabled else None,
                         skip_section_enabled=section_enabled,
                         skip_all_enabled=all_enabled,
                         skip_all_warning=warning_show,
                         skip_cooldown=cd)

    # Adaptive budget tuning
    frame_dur=time.time()-frame_start;_preload_adapt_max(frame_dur)
    if frame_dur > _LONG_FRAME:
        _slow_streak += 1; _splash_budget = max(BUDGET_MIN, _splash_budget*0.5)
    elif frame_dur < 0.018 and _slow_streak == 0:
        _splash_budget = min(BUDGET_MAX, _splash_budget*1.12 + 0.0005)
    else:
        _splash_budget = _splash_budget*0.85 + BUDGET_START*0.15
    if _slow_streak > 2: _splash_budget = BUDGET_MIN; _slow_streak = 0

    # If done but MIN_SPLASH_TIME not reached, idle a bit painting animation
    if (_sec_idx >= _TOTAL_SECTIONS and _converge_start is None) and (now - _splash_t0) < MIN_SPLASH_TIME:
        time.sleep(0.005)
    if not did_work and not (_sec_idx >= _TOTAL_SECTIONS):
        # still sleep tiny bit but only when no generator advanced (e.g. first tick)
        pass

    # Throttle to ~60fps regardless of work, so blobs move smoothly
    _rem = (1.0/TARGET_FRAMERATE) - (time.time()-frame_start)
    if _rem > 0: time.sleep(_rem)

# Anything the user skipped now resumes incrementally in the main loop; the
