def _eh_label(item):
    if isinstance(item,dict) and str(item.get("hierarchy_name","")).strip():return str(item.get("hierarchy_name")).strip()
    if "kind" in item:return str(item.get("name") or item.get("kind","node").replace("_"," "))
    if "text" in item:return str(item.get("text") or "Text")[:48]
    if "image" in item or "image_path" in item:return os.path.basename(str(item.get("image_path") or item.get("source_path") or "Image"))
    return str(item.get("name") or "Entity")


def _eh_type(item):
    if "kind" in item:return str(item.get("kind","node")).replace("_"," ").title()
    if "text" in item:return "Scene Text"
    if "image" in item or "image_path" in item:return "Scene Image"
    return "Entity"


def _eh_scene_flatten():
    items=scene_hierarchy_all_items();by_parent={}
    for item in items:by_parent.setdefault(item.get("hierarchy_parent"),[]).append(item)
    # Front/highest Z is deliberately listed first, matching layer panels in
    # professional editors and the user's visual expectation.
    for vals in by_parent.values():vals.sort(key=lambda x:(-scene_hierarchy_local_z(x),_eh_label(x).lower()))
    out=[];seen=set();collapsed=modal.setdefault("_eh_collapsed",set());valid_keys={scene_hierarchy_key_for(item) for item in items}
    def walk(item,depth):
        key=scene_hierarchy_key_for(item)
        if not key or key in seen:return
        seen.add(key);out.append((item,depth))
        if key not in collapsed:
            for child in by_parent.get(key,[]):walk(child,depth+1)
    for root in by_parent.get(None,[]):walk(root,0)
    # Only recover genuinely orphaned/cyclic records. Descendants skipped by a
    # collapsed ancestor are intentional and must never reappear as root rows at
    # the bottom of the stack.
    def hidden_by_collapse(item):
        parent_key=item.get("hierarchy_parent");trail=set()
        while parent_key and parent_key not in trail:
            if parent_key in collapsed:return True
            trail.add(parent_key);parent=scene_hierarchy_item(parent_key)
            if parent is None:return False
            parent_key=parent.get("hierarchy_parent")
        return False
    for item in items:
        key=scene_hierarchy_key_for(item);parent_key=item.get("hierarchy_parent")
        if key not in seen and (not parent_key or parent_key not in valid_keys):walk(item,0)
    for item in items:
        if scene_hierarchy_key_for(item) not in seen and not hidden_by_collapse(item):walk(item,0)
    return out


def _eh_selected_item():return scene_hierarchy_item(modal.get("_eh_selected"))


def _eh_select_row(key,mods=0):
    """Hierarchy selection: plain=single, Ctrl=toggle, Shift=visible range."""
    item=scene_hierarchy_item(key)
