def _eh_duplicate_selected():
    """Duplicate a node or complete hierarchy subtree as one undoable action."""
    root=_eh_selected_item()
    if root is None:return None
    originals=[root]+scene_hierarchy_descendants(root);scene_undo_push(f"Duplicate {_eh_label(root)} subtree")
    made=[];key_map={}
    for old in originals:
        clone=_snapshot_value(old);clone["_rect"]=None
        for transient in ("_screen_rect","_surface","_surf","_particles","_tweens","_bar_fade_t","_bar_fade_ver"):clone.pop(transient,None)
        if "kind" in old:clone["id"]=_en_new_id();external_nodes.append(clone)
        elif "text" in old:clone["sid"]=_si_new_id();scene_texts.append(clone)
        else:clone["sid"]=_si_new_id();scene_images.append(clone)
        key_map[scene_hierarchy_key_for(old)]=scene_hierarchy_key_for(clone);made.append((old,clone))
    for old,clone in made:
        old_parent=old.get("hierarchy_parent");clone["hierarchy_parent"]=key_map.get(old_parent,old_parent);_scene_move_item_force(clone,20,20)
    new_root=made[0][1];scene_hierarchy_set_local_z(new_root,scene_hierarchy_local_z(root)+1)
    if "kind" in new_root:new_root["name"]=(str(root.get("name") or root.get("kind") or "Node")+" Copy")[:80]
    else:new_root["hierarchy_name"]=(str(root.get("hierarchy_name") or _eh_label(root))+" Copy")[:80]
    modal["_eh_selected"]=scene_hierarchy_key_for(new_root);modal["_eh_selection_anchor"]=modal["_eh_selected"];scene_sel_set_single(new_root);modal["focus"]=None;scene_proxy_invalidate();_SPARSE_PRESENT_STATE["full_next"]=True;push_toast(f"Duplicated {len(made)} hierarchy item(s) · Ctrl+Z to undo","success",3)
    return new_root


def _eh_clear_drag_state(snap=True):
    """Release every hierarchy drag visual/input latch in one place."""
    modal["_eh_drag"]=None;modal["_eh_static_rows"]=[];modal["_eh_drop_preview_state"]=(None,None,None,None);modal["_text_drag_field"]=None
    if snap:modal["_eh_row_y_anim"]={};modal["_eh_row_settle_until"]=0.0


def open_scene_node_delete_confirm(item=None):
    """Use Arena's own validation popup; never open a Tk/OS message box."""
