def _eh_parent_valid(source,target):
    if source is None or target is None or source is target:return False
    source_key=scene_hierarchy_key_for(source);probe=target;seen=set()
    while isinstance(probe,dict):
        key=scene_hierarchy_key_for(probe)
        if not key or key in seen:break
        if key==source_key:return False
        seen.add(key);probe=scene_hierarchy_item(probe.get("hierarchy_parent"))
    return True


def _eh_drop_preview(pos,rows=None):
    root_zone=modal.get("_eh_root_drop_rect")
    if root_zone and root_zone.collidepoint(pos):return "root",None,None
    tree=modal.get("_eh_tree_rect")
    if tree and not tree.collidepoint(pos):return "cancel",None,None
    rows=modal.get("_eh_rows",[]) if rows is None else rows
    row=next((r for r in rows if r["rect"].collidepoint(pos)),None)
    # Empty tree space cancels. Rooting is deliberate via the labeled root tray.
    if row is None:return "cancel",None,None
    rr=row["rect"];edge=max(8,min(12,int(rr.height*.31)))
    if pos[1]<=rr.top+edge:return "reorder",row,"before"
    if pos[1]>=rr.bottom-edge:return "reorder",row,"after"
    return "parent",row,None


def _eh_lively_button(rect,label,icon_key,mouse_pos,color=ACCENT,danger=False,muted=False):
    """High-contrast identity/stack action button with themed icon accents."""
    ui_cursor_hint(rect,"hand",30)
