    if danger:bg=(82,29,36) if hov else (42,23,29);border=(255,99,112) if hov else (132,62,73);icol=(255,244,246) if hov else (242,151,162);tcol=(255,247,248) if hov else (245,224,228)
    elif muted:bg=(22,22,29);border=PANEL_BORDER;icol=TEXT_DIM;tcol=TEXT_DIM
    else:bg=color if hov else (29,28,40);border=(245,248,255) if hov else color;icol=ui_contrast_text(bg,TEXT_MAIN) if hov else color;tcol=ui_contrast_text(bg,TEXT_MAIN) if hov else TEXT_MAIN
    ui_draw_rect(screen,bg,rect,border_radius=7);ui_draw_rect(screen,border,rect,2 if hov else 1,7)
    ic=get_icon_fs(icon_key,15,icol) if icon_key else None
    safe_label=truncate_text_to_width(font_tiny,str(label),max(20,rect.width-(ic.get_width()+22 if ic else 14)))
    txt=font_tiny.render(safe_label,True,tcol);total=txt.get_width()+(ic.get_width()+7 if ic else 0);xx=rect.centerx-total//2
