def _scene_item_world_position(item):
    try:
        if "kind" in item and not item.get("camera_locked"):return _en_resolve_pos(item)
        if (item.get("world_space") or item.get("_world_space")) and not item.get("camera_locked"):return pygame.Vector2(float(item.get("wx",0)),float(item.get("wy",0)))
        rect=item.get("_rect")
        if isinstance(rect,pygame.Rect):return screen_to_world(rect.center)
        return pygame.Vector2(float(item.get("wx",0)),float(item.get("wy",0)))
    except Exception:return pygame.Vector2(0,0)


