def _settings_launcher_dispatch(spec, from_env3d=False):
    act = (spec or {}).get("action")
    if act == "ui_custom":
        if from_env3d:
            modal["_uct_return_env3d"] = True
        open_ui_customization_tool()
    elif act == "keybinds":
        open_scene_keybinds(workspace="env3d" if from_env3d else "arena2d")


def draw_settings_launcher(spec, x, y, cw, mouse_pos, clip_rect=None, handle_clicks=False, from_env3d=False):
    """Draw one 2D Settings launcher card. Returns (y, button_rect)."""
    global left_click_this_frame
    kind = spec.get("kind")
    pygame.draw.line(screen, DIVIDER, (x, y), (x + cw, y), 1); y += 12
    draw_section_label(str(spec.get("section") or ""), (x, y)); y += 20
    btn = None
    if kind == "ui_custom_card":
        _cur_theme_label = _UI_CUSTOM_THEME_LABELS.get(_CURRENT_THEME, _CURRENT_THEME.split("::", 1)[-1])
        _cust_card = pygame.Rect(x, y, cw, 62)
        ui_draw_rect(screen, PANEL_BG_ALT, _cust_card, border_radius=9)
        ui_draw_rect(screen, PANEL_BORDER, _cust_card, 1, 9)
        ui_draw_rect(screen, ACCENT, pygame.Rect(_cust_card.x + 9, _cust_card.y + 9, 36, 36), border_radius=7)
        screen.blit(font_sm.render(str(_cur_theme_label)[:30], True, TEXT_MAIN), (_cust_card.x + 56, _cust_card.y + 9))
        screen.blit(font_tiny.render(str(spec.get("subtitle") or ""), True, TEXT_FAINT), (_cust_card.x + 56, _cust_card.y + 31))
        y += 70
        btn = pygame.Rect(x, y, cw, 32)
        draw_button(btn, str(spec.get("button") or "Open"), btn.collidepoint(mouse_pos), small=True, variant="purple")
        y += 40
        hint = str(spec.get("hint") or "")
        if hint:
            screen.blit(font_tiny.render(hint, True, TEXT_DIM), (x, y)); y += 24
    elif kind == "keybind_card":
        _skb_card = pygame.Rect(x, y, cw, 94)
        ui_draw_rect(screen, PANEL_BG_ALT, _skb_card, border_radius=9)
        ui_draw_rect(screen, PANEL_BORDER, _skb_card, 1, 9)
        _skic = _skb_icon_surface(str(spec.get("icon") or "keyboard"), 20, ACCENT)
        if _skic:
            screen.blit(_skic, (_skb_card.x + 12, _skb_card.y + 11))
        screen.blit(font_sm.render(str(spec.get("title") or ""), True, TEXT_MAIN), (_skb_card.x + 42, _skb_card.y + 8))
        screen.blit(font_tiny.render(str(spec.get("subtitle") or ""), True, TEXT_FAINT), (_skb_card.x + 42, _skb_card.y + 28))
        btn = pygame.Rect(_skb_card.x + 12, _skb_card.y + 51, 142, 30)
        draw_button(btn, str(spec.get("button") or "Open"), btn.collidepoint(mouse_pos), small=True, variant="purple")
        if from_env3d:
            _skb_status = "Current · WASD move · " + _scene_shortcut_label("env3d_camera_pan") + " pan"
        else:
            _skb_status = "Current · " + _scene_shortcut_label("camera_pan_up") + " pan · " + _scene_shortcut_label("select_primary") + " select"
        _skbs = font_tiny.render(truncate_text_to_width(font_tiny, _skb_status, max(80, cw - 174)), True, TEXT_DIM)
        screen.blit(_skbs, (btn.right + 10, btn.centery - _skbs.get_height() // 2))
        y += 106
    if handle_clicks and btn is not None and clip_rect is not None:
        if clip_hit(btn, clip_rect, mouse_pos) and left_click_this_frame:
            _settings_launcher_dispatch(spec, from_env3d=from_env3d)
            left_click_this_frame = False
    return y, btn


def draw_settings_launchers(x, y, cw, mouse_pos, clip_rect=None, handle_clicks=False, from_env3d=False):
    hits = []
    for spec in SETTINGS_LAUNCHER_REGISTRY:
        y, btn = draw_settings_launcher(spec, x, y, cw, mouse_pos, clip_rect, handle_clicks, from_env3d)
        if btn is not None:
            hits.append((spec.get("id"), btn, spec))
    return y, hits


