    id_map=globals().get("SCENE_BUTTON_ID_MAP",{}) or {};styles=globals().get("SCENE_BUTTON_STYLE_REGISTRY",{}) or {};spec=id_map.get(str(button_id or ""),{}) if isinstance(id_map,dict) else {};style=styles.get(spec.get("style"),styles.get("tool",{})) if isinstance(styles,dict) else {}
    label=str(label if label is not None else spec.get("label") or button_id or "Button");icon=str(icon or spec.get("icon") or "settings");color=color or style.get("color") or ACCENT;danger=spec.get("style")=="danger"
    draw_button(rect,"",rect.collidepoint(mouse_pos),small=True,muted=muted,danger=danger,variant=style.get("variant"))
    ic=get_icon_fs(icon,14,GOOD if on else color);left=rect.x+8
    if ic is not None:screen.blit(ic,(left,rect.centery-ic.get_height()//2));left+=20
    reserve=20 if on else 7;text=truncate_text_to_width(font_tiny,label,max(12,rect.right-left-reserve));lab=font_tiny.render(text,True,TEXT_DIM if muted else TEXT_MAIN);screen.blit(lab,(left,rect.centery-lab.get_height()//2))
    if on:
        mark=get_icon_fs("check",12,GOOD)
        if mark is not None:screen.blit(mark,(rect.right-mark.get_width()-7,rect.centery-mark.get_height()//2))
    if rect.collidepoint(mouse_pos):
        tip=str(hint or spec.get("hint") or spec.get("label") or label).strip()
        if tip:globals().setdefault("_deferred_tooltips",[]).append((tip,rect,rect.x,max(rect.w,220)))

