def _ui_window_items(spec):
    src = spec.get("items")
    if src == "workspaces":
        return list(_PROJECT_WORKSPACES)
    if isinstance(src, (list, tuple)):
        return list(src)
    return []

def _ui_window_run(action):
    act = str(action or "")
    if act.startswith("pick:"):
        _project_chooser_pick(act.split(":", 1)[1])
        return True
    return False

def open_ui_window(window_id):
    spec = UI_WINDOW_REGISTRY.get(window_id)
    if not spec:
        return False
    opener = spec.get("open")
    if opener == "show_project_manager":
        show_project_manager()
        return True
    if opener == "open_add_character_modal":
        open_add_character_modal()
        return True
    if opener == "open_env3d_uv_tool":
        open_env3d_uv_tool(blank=True)
        return True
    modal["type"] = spec.get("id") or window_id
    modal["focus"] = None
    modal["_ui_window_id"] = window_id
    modal.pop("_pc_hover", None)
    return True

def open_project_chooser():
    """Show the workspace picker (startup + Workspaces toolbar button)."""
    open_ui_window("project_chooser")

_CSHARP_3D_PROCESS=[None]

def _find_csharp_3d_project():
    candidates=[os.path.join(_ARENA_INSTALL_DIR,"ArenaEngine","ArenaEngine.csproj"),os.path.join(os.path.dirname(_ARENA_INSTALL_DIR),"ArenaEngine","ArenaEngine.csproj")]
    return next((os.path.abspath(x) for x in candidates if os.path.isfile(x)),"")

def _restore_python_window_after_csharp():
    try:
        if os.name=="nt":
            import ctypes
            hwnd=pygame.display.get_wm_info().get("window")
            if hwnd:ctypes.windll.user32.ShowWindow(hwnd,9);ctypes.windll.user32.SetForegroundWindow(hwnd)
    except Exception:pass

def _launch_csharp_3d_workspace():
    running=_CSHARP_3D_PROCESS[0]
    if running is not None and running.poll() is None:
        push_toast("Arena 3D is already running.","info",2.0);return True
    project=_find_csharp_3d_project()
    if not project:
        push_toast("ArenaEngine/ArenaEngine.csproj was not found beside Box Game.","error",5.0);return False
    folder=os.path.dirname(project);name=os.path.splitext(os.path.basename(project))[0];exe_candidates=[os.path.join(folder,"bin","Release","net10.0",name+".exe"),os.path.join(folder,"bin","Debug","net10.0",name+".exe")];exe=next((x for x in exe_candidates if os.path.isfile(x)),"")
    cmd=[exe] if exe else ["dotnet","run","--project",project,"-c","Release"]
    try:
        flags=getattr(subprocess,"CREATE_NEW_PROCESS_GROUP",0);proc=subprocess.Popen(cmd,cwd=folder,creationflags=flags);_CSHARP_3D_PROCESS[0]=proc
        modal["type"]=None;modal["focus"]=None
        try:pygame.display.iconify()
        except Exception:pass
        def wait_engine():
            try:proc.wait()
            finally:_CSHARP_3D_PROCESS[0]=None;_restore_python_window_after_csharp()
        threading.Thread(target=wait_engine,daemon=True,name="ArenaEngineMonitor").start();return True
    except FileNotFoundError:
        push_toast("dotnet was not found. Check the .NET SDK installation.","error",5.0)
    except Exception as exc:push_toast(f"Could not launch Arena 3D: {exc}","error",5.0)
    return False

def _project_chooser_pick(key):
    """Switch workspaces, loading a skipped system only when first requested."""
    global _ARENA2D_WORKSPACE_LOADED, _ACTIVE_WORKSPACE
    if key == "arena2d":
        pygame.event.set_grab(False);pygame.mouse.set_visible(True)
        if not _ARENA2D_WORKSPACE_LOADED:
            modal["type"]=None;modal["focus"]=None
            _soft_reload_to_splash("loading 2D Arena workspace...",False)
            _load_all_data_stores();_ARENA2D_WORKSPACE_LOADED=True
        # Keep the 3D GPU scene parked. Releasing it made 2D→3D round trips
        # look like a brand-new workspace (empty cube, 3D projects gone).
        _ACTIVE_WORKSPACE = "arena2d"
        modal["type"] = None
        modal["focus"] = None
        modal.pop("_pc_hover", None)
        try:
            load_recent_projects()
        except Exception:
            pass
        push_toast("2D Arena Sim workspace", "success", 1.4)
    elif key=="csharp3d":
        _ACTIVE_WORKSPACE="csharp3d";_launch_csharp_3d_workspace()
    elif key == "cinematics":
        push_toast("2D Cinematics is in development \u2014 coming soon.", "info", 2.6)
    elif key == "env3d":
        modal["type"] = None; modal["focus"] = None; modal.pop("_pc_hover", None)
        _enter_env3d_workspace()

def draw_project_chooser(mouse_pos):
    """Id-based workspace picker — thin wrapper over the window registry."""
    draw_ui_window("project_chooser", mouse_pos)

def draw_ui_window(window_id, mouse_pos):
    spec = UI_WINDOW_REGISTRY.get(window_id)
    if not spec:
        return
    if modal.get("type") != spec.get("id", window_id):
        return
    if spec.get("layout") == "workspace_cards":
        _draw_workspace_cards_window(spec, mouse_pos)

def _draw_workspace_cards_window(spec, mouse_pos):
    """Themed card chooser driven by a window-registry spec + item ids."""
    screen.set_clip(None)
    f = _UIFrame("_pc")
    if f.key_edge(pygame.K_ESCAPE):
        _ui_window_run(spec.get("esc", "pick:arena2d"))
        return
    # Use the screen surface's actual current size rather than the WIDTH/HEIGHT
    # globals. Those globals only get resynced on a VIDEORESIZE event (or the
    # fullscreen-toggle code path) later in the main loop, so on the very
    # first frames after a resize/fullscreen switch -- which is exactly when
    # this startup picker tends to be showing -- they can still hold a stale
    # size, leaving the panel with a visible gap instead of sitting flush.
    _pc_sw, _pc_sh = screen.get_size()
    panel = pygame.Rect(0, 0, _pc_sw, _pc_sh)
    draw_panel(panel, alpha=255, radius=0, shadow=False, opaque=True)
    title = str(spec.get("title") or "ARENA STUDIO")
    subtitle = f"v{APP_VERSION} \u00b7 choose a workspace"
    close_r = ui_panel_header(panel, title, subtitle, icon=spec.get("icon") or "home")
    if ui_close_button(f, close_r):
        _ui_window_run(spec.get("close", "pick:arena2d"))
        return
    banner = str(spec.get("banner") or "")
    if banner:
        screen.blit(font_tiny.render(banner, True, TEXT_FAINT), (panel.x + 320, panel.y + 18))

    body = pygame.Rect(panel.x + 12, panel.y + 52, panel.width - 24, panel.height - 60)
    ui_draw_rect(screen, PANEL_BG_ALT, body, border_radius=9)
    ui_draw_rect(screen, PANEL_BORDER, body, width=1, border_radius=9)

    cards = _ui_window_items(spec)
    n = max(1, len(cards))
    _gap = 18
    _card_w = min(340, (body.width - 48 - _gap * max(0, n - 1)) // n)
    _card_h = min(300, body.height - 96)
    _total = _card_w * n + _gap * max(0, n - 1)
    _x0 = body.centerx - _total // 2
    _y0 = body.y + 34
    for _i, _ws in enumerate(cards):
        _r = pygame.Rect(_x0 + _i * (_card_w + _gap), _y0, _card_w, _card_h)
        _hov = f.hit(_r)
        _avail = bool(_ws.get("available"))
        if _avail:
            ui_draw_rect(screen, ACCENT_HOVER if _hov else FIELD_BG, _r, border_radius=12)
            ui_draw_rect(screen, ACCENT if _hov else PANEL_BORDER, _r, width=2 if _hov else 1, border_radius=12)
        else:
            ui_draw_rect(screen, PANEL_BG_ALT if _hov else FIELD_BG, _r, border_radius=12)
            ui_draw_rect(screen, PANEL_BORDER, _r, width=1, border_radius=12)
        _ic = get_icon_fs(str(_ws.get("icon", "")), 44, GOLD if _avail else TEXT_FAINT)
        if _ic:
            screen.blit(_ic, (_r.centerx - _ic.get_width() // 2, _r.y + 34))
        _tag = str(_ws.get("tag", ""))
        _tag_fg = ui_contrast_text(ACCENT, TEXT_MAIN) if _avail else TEXT_DIM
        _ts = font_tiny.render(_tag, True, _tag_fg)
        _tw = _ts.get_width() + 16
        _tr = pygame.Rect(0, 0, _tw, 18)
        _tr.centerx = _r.centerx
        _tr.top = _r.y + _r.height - 32
        ui_draw_rect(screen, ACCENT if _avail else FIELD_FOCUS, _tr, border_radius=9)
        screen.blit(_ts, (_tr.centerx - _ts.get_width() // 2, _tr.centery - _ts.get_height() // 2))
        _ls = font_sm.render(str(_ws.get("label", "")), True, TEXT_MAIN if _avail else TEXT_DIM)
        screen.blit(_ls, (_r.centerx - _ls.get_width() // 2, _r.y + 92))
        _dy = _r.y + 122
        for _line in textwrap.wrap(str(_ws.get("desc", "")), 30):
            _ds = font_tiny.render(_line, True, TEXT_FAINT)
            screen.blit(_ds, (_r.centerx - _ds.get_width() // 2, _dy))
            _dy += 15
        if _avail:
            _cta = font_tiny.render("\u25b6  Enter workspace", True, ACCENT)
            screen.blit(_cta, (_r.centerx - _cta.get_width() // 2, _tr.top - 26))
        if f.click(_r):
            _project_chooser_pick(str(_ws.get("key", "")))
    _foot = font_tiny.render(str(spec.get("footer") or ""), True, TEXT_FAINT)
    if spec.get("footer"):
        screen.blit(_foot, (body.centerx - _foot.get_width() // 2, body.bottom - 26))
