def _env3d_operate():
    v = str(modal.get("_e3d_operate") or "item")
    return v if v in ("item", "form", "rig") else "item"

def _e3d_mesh_elems():
    """Form-mode element toggles. Multi-select; at least one stays on."""
    raw = modal.get("_e3d_mesh_elems")
    if raw is None:
        raw = ["verts", "edges", "faces"]
    if isinstance(raw, str):
        raw = [raw]
    out = [x for x in list(raw or []) if x in ("verts", "edges", "faces")]
    return out or ["verts", "edges", "faces"]

def _chrome_sidebar_w():
    """3D Form mode uses a thin icon rail; everything else keeps SIDEBAR_W."""
    try:
        if modal.get("type") == "env3d_embedded" and _env3d_operate() == "form":
            return 76
    except Exception:
        pass
    try:
        if mobile_layout_active():return int(mobile_sidebar_w())
    except Exception:
        pass
    return int(SIDEBAR_W)

def _toolbar_workspace_key():
    return "env3d" if modal.get("type") == "env3d_embedded" else "arena2d"

def _toolbar_buttons_for_workspace():
    """Filter TOOLBAR_BUTTON_REGISTRY by the active workspace id."""
    ws = _toolbar_workspace_key()
    out = []
    for b in TOOLBAR_BUTTON_REGISTRY:
        allowed = b.get("workspaces")
        if allowed and ws not in allowed:
            continue
        out.append(b)
    return out

def _toolbar_button_label(bid):
    """State-dependent label for a registry id. Kept separate from the
    registry itself so the registry stays pure layout/style data."""
    if bid == "aw_start":
        return "Pause" if not paused else ("Resume" if simulation_started else "Start")
    return {
        "aw_stop": "Stop", "aw_gizmos": "Gizmos", "aw_reload": "Reload",
        "aw_setup": "Setup", "aw_workspaces": "Workspaces",
    }[bid]

