def _subbar_items_for_workspace():
    """Filter WORKSPACE_SUBBAR_REGISTRY by the bar spec + per-item workspace."""
    spec = WORKSPACE_SUBBAR_SPEC
    ws = _toolbar_workspace_key()
    allowed = spec.get("workspaces")
    if allowed and ws not in allowed:
        return []
    out = []
    op = _env3d_operate() if ws == "env3d" else "item"
    for item in WORKSPACE_SUBBAR_REGISTRY:
        item_ws = item.get("workspaces")
        if item_ws and ws not in item_ws:
            continue
        need = item.get("operate")
        if need and op not in need:
            continue
        if op in ("form", "rig") and item.get("id") in ("sb_transform", "sb_pivot"):
            continue
        out.append(item)
    return out

def workspace_subbar_visible():
    return bool(ui_visible and _subbar_items_for_workspace())

def workspace_chrome_height():
    """Main top bar + optional thin subbar. Used to offset the 3D viewport."""
    if not ui_visible:
        return 0
    try:h = int(mobile_topbar_h() if mobile_layout_active() else WORKSPACE_TOPBAR_H)
    except Exception:h = int(WORKSPACE_TOPBAR_H)
    if workspace_subbar_visible():
        h += int(WORKSPACE_SUBBAR_SPEC.get("height") or WORKSPACE_SUBBAR_H)
    return h

def _subbar_current_value(spec):
    key = spec.get("value_key") or ("_subbar_" + str(spec.get("id") or "value"))
    default = spec.get("default")
    if spec.get("kind") == "dropdown":
        opts = spec.get("options") or []
        if default is None and opts:
            default = opts[0].get("id")
    val = modal.get(key, default)
    if spec.get("kind") == "dropdown":
        ids = {o.get("id") for o in (spec.get("options") or [])}
        if val not in ids:
            val = default
    elif spec.get("kind") == "toggle_row":
        ids = {o.get("id") for o in (spec.get("options") or [])}
        if isinstance(val, str):
            val = [val]
        val = [x for x in list(val or []) if x in ids]
        if not val:
            if isinstance(default, (list, tuple)):
                val = [x for x in default if x in ids]
            elif default in ids:
                val = [default]
    return val

def _subbar_current_option(spec):
    val = _subbar_current_value(spec)
    for opt in spec.get("options") or []:
        if opt.get("id") == val:
            return opt
    opts = spec.get("options") or []
    return opts[0] if opts else {}

def _subbar_set_value(spec, value):
    key = spec.get("value_key") or ("_subbar_" + str(spec.get("id") or "value"))
    modal[key] = value
    if key == "_e3d_operate" and value == "form":
        ws = _ENV3D.get("workspace")
        if ws is not None and ws._sel_obj() is not None:ws.selected = True
        modal.setdefault("_e3d_mesh_elems", ["verts", "edges", "faces"])
    if key == "_e3d_operate" and value == "rig":
        modal["_e3d_pose_joint"]=None;modal["_e3d_pose_drag"]=None
        # Pose is a scene mode, not the isolated construction workspace.
        # Leaving dedicated Rigging also restores the normal right bar.
        if modal.get("_e3d_rigging"):_env3d_exit_rigging()
        ws=_ENV3D.get("workspace");obj=ws._sel_obj() if ws is not None else None
        if obj is None or not isinstance(obj.get("armature"),dict):push_toast("Pose Mode needs a selected rigged model","info",2.2)
        else:
            ws._set_object_selection({obj.get("id")},obj.get("id"));ws.rig_enforce_rotation_pose(obj);arm=ws.ensure_armature(obj)
            # Entering Pose mode must never re-solve or cumulatively alter IK.
            bone=ws._rig_bone_by_id(arm,arm.get("active_bone")) or ((arm.get("bones") or [None])[0])
            if bone is not None:modal["_e3d_pose_joint"]={"oid":obj.get("id"),"joint_id":str(bone.get("tail_joint")),"bone_id":str(bone.get("id"))}
            push_toast("Pose Mode · rotate Point controls or drag an IK Circle target","info",2.6)
    if key == "_e3d_operate" and value != "rig":
        modal["_e3d_pose_hits"]=[];modal["_e3d_pose_gizmo_hits"]=[];modal["_e3d_pose_drag"]=None

def handle_workspace_subbar_click(pos):
    """Id-keyed dispatch for the thin subbar + its open dropdown."""
    menu = modal.get("_subbar_menu")
    if menu:
        for oid, rect, opt in modal.get("_subbar_menu_hits") or []:
            if rect.collidepoint(pos):
                spec = next((s for s in WORKSPACE_SUBBAR_REGISTRY if s.get("id") == menu.get("id")), None)
                if spec is not None:
                    _subbar_set_value(spec, oid)
                modal["_subbar_menu"] = None
                return True
        mrect = modal.get("_subbar_menu_rect")
        if mrect is not None and mrect.collidepoint(pos):
            return True
        closed_id = menu.get("id")
        modal["_subbar_menu"] = None
        for eid, rect, spec in modal.get("_subbar_hits") or []:
            if rect.collidepoint(pos) and eid == closed_id:
                return True
        # outside the menu: swallow this click so it only closes the dropdown
        return True
    for eid, rect, spec in modal.get("_subbar_hits") or []:
        if not rect.collidepoint(pos):
            continue
        if spec.get("kind") == "dropdown":
            modal["_subbar_menu"] = {"id": eid}
        elif spec.get("kind") == "toggle_row" or spec.get("toggle"):
            cid = spec.get("choice") or eid
            cur = list(_subbar_current_value(spec) or [])
            if cid in cur:
                if len(cur) > 1:
                    cur = [x for x in cur if x != cid]
            else:
                cur = cur + [cid]
            _subbar_set_value(spec, cur)
        elif spec.get("kind") == "choice_row" or spec.get("choice"):
            val = spec.get("choice") or eid
            _subbar_set_value(spec, val)
        else:
            act = spec.get("action")
            if act and act not in ("noop", None):
                try:
                    _subbar_set_value(spec, act)
                except Exception:
                    pass
        return True
    srect = modal.get("_subbar_rect")
    if srect is not None and srect.collidepoint(pos):
        return True
    return False

def draw_workspace_subbar(mouse_pos):
    """Thin registry strip under the main top bar. Theme tokens only."""
    modal["_subbar_hits"] = []
    items = _subbar_items_for_workspace()
    if not items or not ui_visible:
        modal["_subbar_rect"] = None
        return None
    dock_w = max(0, dock_reserved_width())
    x0 = _chrome_sidebar_w()
    h = int(WORKSPACE_SUBBAR_SPEC.get("height") or WORKSPACE_SUBBAR_H)
    try:_mtbh = int(mobile_topbar_h() if mobile_layout_active() else WORKSPACE_TOPBAR_H)
    except Exception:_mtbh = int(WORKSPACE_TOPBAR_H)
    bar = pygame.Rect(x0, _mtbh, max(1, WIDTH - x0 - dock_w), h)
    modal["_subbar_rect"] = bar.copy()
    try:
        _modify_register_element("panel", bar, "Workspace Subbar", key="panel:workspace_subbar")
    except Exception:
        pass
    try:
        bg = _palette_mix(PANEL_BG, FIELD_BG, 0.28)
    except Exception:
        bg = PANEL_BG
    ui_draw_rect(screen, bg, bar)
    pygame.draw.line(screen, PANEL_BORDER, (bar.x, bar.bottom - 1), (bar.right, bar.bottom - 1), 1)
    hits = []

    def _draw_choice_row(spec, x, y, h, right=False):
        opts = list(spec.get("options") or [])
        cur = _subbar_current_value(spec)
        gap = 3
        parts = []
        total = 0
        for opt in opts:
            lab_s = font_tiny.render(str(opt.get("label") or opt.get("id") or ""), True, TEXT_MAIN)
            bw = 8 + 14 + 6 + lab_s.get_width() + 8
            parts.append((opt, max(52, bw), lab_s))
            total += max(52, bw)
        if parts:
            total += gap * (len(parts) - 1)
        x0 = x - total if right else x
        xx = x0
        for opt, bw, lab_s in parts:
            br = pygame.Rect(xx, y, bw, h)
            hov = br.collidepoint(mouse_pos)
            if isinstance(cur, (list, tuple, set)):
                on = opt.get("id") in cur
            else:
                on = opt.get("id") == cur
            ui_draw_rect(screen, ACCENT if on else (PANEL_BG_ALT if hov else FIELD_BG), br, border_radius=6)
            ui_draw_rect(screen, ACCENT if (on or hov) else PANEL_BORDER, br, 1, 6)
            fg = ui_contrast_text(ACCENT, TEXT_MAIN) if on else TEXT_MAIN
            icx = br.x + 8
            ic = get_icon_fs(str(opt.get("icon") or ""), 13, fg)
            if ic:
                screen.blit(ic, (icx, br.centery - ic.get_height() // 2))
                icx += 16
            ls = font_tiny.render(str(opt.get("label") or opt.get("id") or ""), True, fg)
            screen.blit(ls, (icx, br.centery - ls.get_height() // 2))
            ui_cursor_hint(br, "hand", 40)
            hit_spec = dict(spec)
            hit_spec["choice"] = opt.get("id")
            hits.append((opt.get("id"), br, hit_spec))
            xx += bw + gap
        return total

    def _draw_dropdown(spec, x, y, h):
        cur = _subbar_current_option(spec)
        label = str((cur or {}).get("label") or spec.get("label") or "")
        icon = str((cur or {}).get("icon") or spec.get("icon") or "")
        lab_s = font_tiny.render(label, True, TEXT_MAIN)
        bw = 8 + 14 + 6 + lab_s.get_width() + 18 + 8
        br = pygame.Rect(x, y, max(72, bw), h)
        hov = br.collidepoint(mouse_pos)
        open_ = (modal.get("_subbar_menu") or {}).get("id") == spec.get("id")
        bgb = PANEL_BG_ALT if (hov or open_) else FIELD_BG
        bdr = ACCENT if (open_ or hov) else PANEL_BORDER
        fg = ACCENT if open_ else TEXT_MAIN
        ui_draw_rect(screen, bgb, br, border_radius=6)
        ui_draw_rect(screen, bdr, br, 1, 6)
        xx = br.x + 8
        ic = get_icon_fs(icon, 13, fg)
        if ic:
            screen.blit(ic, (xx, br.centery - ic.get_height() // 2))
            xx += 16
        screen.blit(lab_s, (xx, br.centery - lab_s.get_height() // 2))
        ch = get_icon_fs("chevron_down", 12, TEXT_FAINT)
        if ch:
            screen.blit(ch, (br.right - 16, br.centery - ch.get_height() // 2))
        ui_cursor_hint(br, "hand", 40)
        hits.append((spec.get("id"), br, spec))
        return br.width

    def _draw_button(spec, x, y, h):
        label = str(spec.get("label") or spec.get("id") or "")
        icon = str(spec.get("icon") or "")
        lab_s = font_tiny.render(label, True, TEXT_MAIN)
        bw = 8 + (14 if icon else 0) + (6 if icon else 0) + lab_s.get_width() + 8
        br = pygame.Rect(x, y, max(48, bw), h)
        hov = br.collidepoint(mouse_pos)
        on = spec.get("id") and spec.get("id") == modal.get("_e3d_form_tool")
        ui_draw_rect(screen, ACCENT if on else (PANEL_BG_ALT if hov else FIELD_BG), br, border_radius=6)
        ui_draw_rect(screen, ACCENT if (on or hov) else PANEL_BORDER, br, 1, 6)
        xx = br.x + 8
        ic = get_icon_fs(icon, 13, ui_contrast_text(ACCENT, TEXT_MAIN) if on else (ACCENT if hov else TEXT_MAIN))
        if ic:
            screen.blit(ic, (xx, br.centery - ic.get_height() // 2))
            xx += 16
        screen.blit(lab_s, (xx, br.centery - lab_s.get_height() // 2))
        ui_cursor_hint(br, "hand", 40)
        hits.append((spec.get("id"), br, spec))
        return br.width

    left_items = [s for s in items if s.get("align") != "right"]
    right_items = [s for s in items if s.get("align") == "right"]
    iy, ih = bar.y + 3, bar.height - 6
    tx = bar.x + 8
    for spec in left_items:
        kind = spec.get("kind") or "button"
        if kind == "dropdown":
            tx += _draw_dropdown(spec, tx, iy, ih) + 6
        elif kind in ("choice_row", "toggle_row"):
            tx += _draw_choice_row(spec, tx, iy, ih, right=False) + 6
        else:
            tx += _draw_button(spec, tx, iy, ih) + 6
    rx = bar.right - 8
    for spec in reversed(right_items):
        kind = spec.get("kind") or "button"
        if kind in ("choice_row", "toggle_row"):
            w = _draw_choice_row(spec, rx, iy, ih, right=True)
            rx -= w + 6
        elif kind == "dropdown":
            # measure via draw at temp - dropdown doesn't support right easily; skip
            w = _draw_dropdown(spec, rx - 120, iy, ih)
            rx -= w + 6
        else:
            w = _draw_button(spec, rx - 80, iy, ih)
            rx -= w + 6
    modal["_subbar_hits"] = hits
    return bar

def draw_workspace_subbar_menu(mouse_pos):
    """Dropdown overlay for subbar dropdown controls. Drawn last so it stacks."""
    menu = modal.get("_subbar_menu")
    modal["_subbar_menu_hits"] = []
    modal["_subbar_menu_rect"] = None
    if not menu:
        return None
    spec = next((s for s in WORKSPACE_SUBBAR_REGISTRY if s.get("id") == menu.get("id")), None)
    if spec is None or spec.get("kind") != "dropdown":
        modal["_subbar_menu"] = None
        return None
    btn = None
    for eid, rect, _s in modal.get("_subbar_hits") or []:
        if eid == spec.get("id"):
            btn = rect
            break
    if btn is None:
        modal["_subbar_menu"] = None
        return None
    opts = list(spec.get("options") or [])
    row_h = 24
    w = max(int(btn.width), 132)
    h = 6 + len(opts) * row_h + 6
    panel = pygame.Rect(btn.x, btn.bottom + 3, w, h)
    if panel.right > WIDTH - 4:
        panel.x = max(4, WIDTH - panel.width - 4)
    if panel.bottom > HEIGHT - 4:
        panel.y = max(4, btn.y - h - 3)
    ui_draw_rect(screen, PANEL_BG, panel, border_radius=7)
    ui_draw_rect(screen, PANEL_BORDER, panel, 1, 7)
    cur = _subbar_current_value(spec)
    hits = []
    y = panel.y + 6
    for opt in opts:
        r = pygame.Rect(panel.x + 4, y, panel.width - 8, row_h)
        hov = r.collidepoint(mouse_pos)
        on = opt.get("id") == cur
        if on:
            ui_draw_rect(screen, ACCENT, r, border_radius=5)
            fg = ui_contrast_text(ACCENT, TEXT_MAIN)
        elif hov:
            ui_draw_rect(screen, PANEL_BG_ALT, r, border_radius=5)
            fg = TEXT_MAIN
        else:
            fg = TEXT_DIM
        xx = r.x + 8
        ic = get_icon_fs(str(opt.get("icon") or ""), 13, fg)
        if ic:
            screen.blit(ic, (xx, r.centery - ic.get_height() // 2))
            xx += 18
        ls = font_tiny.render(str(opt.get("label") or opt.get("id") or ""), True, fg)
        screen.blit(ls, (xx, r.centery - ls.get_height() // 2))
        ui_cursor_hint(r, "hand", 50)
        hits.append((opt.get("id"), r, opt))
        y += row_h
    modal["_subbar_menu_hits"] = hits
    modal["_subbar_menu_rect"] = panel.copy()
    return panel


