# ── Sidebar footer shortcut hint ──────────────────────────────────────────
# The bottom hint ("H hide UI | SPACE pause | ...") lives inside the sidebar,
# but it used to be painted ONLY on sidebar-repaint frames while the cached
# sidebar stored just the first SIDEBAR_W pixels. The hint text is ~700px
# wide -- far wider than the sidebar -- so the ~350px that spilled into the
# arena flickered visible/invisible with the sidebar's capped repaint rate
# and made the sidebar's right border glitch next to the text. The hint is
# now wrapped to fit inside the sidebar and drawn EVERY frame, clipped to
# the sidebar, so it can never flicker or bleed into the arena.
_SIDEBAR_FOOTER_HINT_LINES = {"w": 0, "lines": None}

def _sidebar_footer_hint_text():
    return (f"H hide UI | SPACE pause | {_scene_shortcut_label('asset_creator')} asset creator | "
            f"{_scene_shortcut_label('anim_states')} anim states | {_scene_shortcut_label('node_groups')} groups | "
            f"{_scene_shortcut_label('gif_import')} gif | {_scene_shortcut_label('easing_editor')} easing | "
            f"{_scene_shortcut_label('motion_studio')} motion | {_scene_shortcut_label('fullscreen')} fullscreen | "
            f"WASD pan | ESC unfollow")

def _sidebar_footer_hint_lines():
    """Wrap the shortcut hint into lines that fit inside the sidebar width
    (breaks on ' | ' segment boundaries, so keys never split mid-word)."""
    try:
        max_w = max(120, SIDEBAR_W - 30)
        hit = _SIDEBAR_FOOTER_HINT_LINES
        if hit["lines"] is not None and hit["w"] == max_w:
            return hit["lines"]
        segs = _sidebar_footer_hint_text().split(" | ")
        lines = []
        cur = ""
        for s in segs:
            trial = s if not cur else cur + " | " + s
            if font_tiny.size(trial)[0] <= max_w:
                cur = trial
            else:
                if cur:
                    lines.append(cur)
                cur = s
        if cur:
            lines.append(cur)
        if not lines:
            lines = ["H hide UI | SPACE pause"]
        hit["lines"] = lines
        hit["w"] = max_w
        return lines
    except Exception:
        return ["H hide UI | SPACE pause"]

def _sidebar_footer_hint_reserve():
    """How much vertical space (px) the wrapped footer hint needs at the
    bottom of the sidebar, so each tab's scrollable list stops above it."""
    try:
        n = len(_sidebar_footer_hint_lines()) + 1  # one tiny version/channel line
        return max(30, n * (font_tiny.get_height() + 1) + 10)
    except Exception:
        return 46

def _draw_sidebar_footer_hint():
    """Paint the wrapped hint at the bottom of the sidebar, clipped to the
    sidebar region so nothing spills into the arena. Called every frame, so
    cache hits can never blank it out."""
    try:
        lines = _sidebar_footer_hint_lines()
        lh = font_tiny.get_height() + 1
        y = HEIGHT - 8 - (len(lines) + 1) * lh
        try:
            _ox = _sb_x_offset
        except Exception:
            _ox = 0
        _clip = screen.get_clip()
        screen.set_clip(pygame.Rect(0, 0, SIDEBAR_W, HEIGHT))
        try:
            _oa = _sb_anim_alpha
        except Exception:
            _oa = 255
        for ln in lines:
            hs = font_tiny.render(ln, True, TEXT_FAINT)
            if _oa < 255:
                hs = hs.copy();hs.set_alpha(max(0, _oa))
            screen.blit(hs, (14 + _ox, y));y += lh
        # Persistent tiny version plus release type/channel at the very bottom.
        _ver=font_tiny.render(app_version_display_label(),True,_palette_mix(TEXT_FAINT,ACCENT,.35))
        if _oa < 255:_ver=_ver.copy();_ver.set_alpha(max(0,_oa))
        screen.blit(_ver,(14+_ox,y));screen.set_clip(_clip)
    except Exception:
        pass

