# ── In-game dev terminal ────────────────────────────────────────────────
# Double-tap "/" on the main scene to open, ESC to close. Runs real shell
# commands (PowerShell on Windows, bash elsewhere) plus a couple of
# built-ins ($env:X=Y / export X=Y / set X=Y / clear), so you can flip
# things like NS_DEBUG_HOOKS without leaving the game.
# ── Notes Manager + safe calculator terminal tools ──────────────────────────
_NOTES_PATH=_cfg_path("notes","notes_manager.json")
_NOTES_BACKUP_DIR=_cfg_path("notes","backups")
_NOTES_DATA={"version":1,"notes":[]};_NOTES_LOADED=False;_NOTES_DIRTY=False

def _notes_now():return time.strftime("%Y-%m-%d %H:%M:%S")
def _notes_id():return int(time.time()*1000000)+random.randint(0,999)
def load_notes_manager():
    global _NOTES_LOADED,_NOTES_DATA
    if _NOTES_LOADED:return
    _NOTES_LOADED=True
    try:
        data,src=_data_store_read_safe(_NOTES_PATH,"Arena Notes","dict")
        if isinstance(data,dict):_NOTES_DATA=data
    except Exception:pass
    _NOTES_DATA.setdefault("version",1);_NOTES_DATA.setdefault("notes",[])
    for n in _NOTES_DATA["notes"]:
        n.setdefault("id",_notes_id());n.setdefault("title","Untitled Note");n.setdefault("body","");n.setdefault("category","General");n.setdefault("pinned",False);n.setdefault("archived",False);n.setdefault("checklist",[]);n.setdefault("created",_notes_now());n.setdefault("updated",n["created"])

def save_notes_manager(show=False):
    global _NOTES_DIRTY
    load_notes_manager()
    try:
        _data_store_write_safe(_NOTES_PATH,_NOTES_DATA,"Arena Notes",True);_NOTES_DIRTY=False
        if show:push_toast("Notes saved","success",1.5)
        return True
    except Exception as e:push_toast(f"Notes save failed: {e}","error",3);return False

def backup_notes_manager(show=True):
    load_notes_manager();save_notes_manager(False)
    try:
        os.makedirs(_NOTES_BACKUP_DIR,exist_ok=True);stamp=time.strftime("%Y%m%d_%H%M%S");path=os.path.join(_NOTES_BACKUP_DIR,f"notes_{stamp}.json")
        with open(path,"w",encoding="utf-8") as f:json.dump(_NOTES_DATA,f,indent=2,ensure_ascii=False)
        files=sorted(glob.glob(os.path.join(_NOTES_BACKUP_DIR,"notes_*.json")))
        for old in files[:-30]:
            try:os.remove(old)
            except Exception:pass
        if show:push_toast(f"Notes backup created · {stamp}","success",2)
        return path
    except Exception as e:push_toast(f"Backup failed: {e}","error",3);return None

def _notes_restore_latest():
    global _NOTES_DATA,_NOTES_DIRTY
    files=sorted(glob.glob(os.path.join(_NOTES_BACKUP_DIR,"notes_*.json")))
    if not files:push_toast("No notes backups found","warning",2);return
    try:
        backup_notes_manager(False)
        with open(files[-1],"r",encoding="utf-8") as f:data=json.load(f)
        if not isinstance(data,dict) or not isinstance(data.get("notes"),list):raise ValueError("invalid backup")
        _NOTES_DATA=data;_NOTES_DIRTY=True;save_notes_manager(False);modal["_notes_selected"]=None;push_toast("Latest notes backup restored","success",2.5)
    except Exception as e:push_toast(f"Restore failed: {e}","error",3)

def _notes_selected():
    load_notes_manager();sid=modal.get("_notes_selected")
    return next((n for n in _NOTES_DATA["notes"] if n.get("id")==sid),None)

def _notes_touch(note=None):
    global _NOTES_DIRTY
    _NOTES_DIRTY=True
    if note is not None:note["updated"]=_notes_now()

def _notes_new(matchup=False,title=None):
    load_notes_manager();now=_notes_now();name=title or ("Matchup: Fighter A vs Fighter B" if matchup else "Untitled Note")
    n={"id":_notes_id(),"title":name,"body":"" if not matchup else "Match setup, observations, and result:","category":"Matchups" if matchup else "General","pinned":False,"archived":False,"created":now,"updated":now,"checklist":[]}
    if matchup:n["checklist"]=[{"id":_notes_id(),"text":"Match completed","done":False},{"id":_notes_id(),"text":"Result recorded","done":False},{"id":_notes_id(),"text":"Replay/export reviewed","done":False}]
    _NOTES_DATA["notes"].insert(0,n);modal["_notes_selected"]=n["id"];_notes_touch(n);save_notes_manager(False);return n

def open_notes_manager():
    load_notes_manager();_ns_terminal["open"]=False;modal.update({"type":"notes_manager","focus":None,"_notes_filter":modal.get("_notes_filter","all"),"_notes_search":modal.get("_notes_search",""),"_notes_scroll":0.0,"_notes_body_scroll":0.0})
    if _notes_selected() is None and _NOTES_DATA["notes"]:modal["_notes_selected"]=_NOTES_DATA["notes"][0]["id"]

def close_notes_manager():
    if _NOTES_DIRTY:save_notes_manager(False)
    modal["type"]=None;modal["focus"]=None;modal["_text_drag_field"]=None

