def _notes_export_txt():
    load_notes_manager()
    try:
        outdir=_cfg_path("notes","exports");os.makedirs(outdir,exist_ok=True);path=os.path.join(outdir,f"arena_notes_{time.strftime('%Y%m%d_%H%M%S')}.txt")
        lines=["ARENA STUDIO NOTES", "="*50,""]
        for n in _NOTES_DATA["notes"]:
            if n.get("archived"):continue
            lines += [f"[{n.get('category','General')}] {n.get('title','Untitled')}",f"Updated: {n.get('updated','')}",str(n.get("body","")).rstrip()]
            lines += [("[x] " if c.get("done") else "[ ] ")+str(c.get("text","")) for c in n.get("checklist",[])]
            lines += ["","-"*50,""]
        with open(path,"w",encoding="utf-8") as f:f.write("\n".join(lines))
        push_toast(f"Notes exported: {os.path.basename(path)}","success",3)
    except Exception as e:push_toast(f"Export failed: {e}","error",3)

def _notes_filtered():
    load_notes_manager();q=str(modal.get("_notes_search","")).strip().lower();flt=modal.get("_notes_filter","all")
    out=[]
    for n in _NOTES_DATA["notes"]:
        archived=bool(n.get("archived"));checks=n.get("checklist",[])
        if flt=="trash" and not archived:continue
        if flt!="trash" and archived:continue
        if flt=="pinned" and not n.get("pinned"):continue
        if flt=="matchups" and n.get("category")!="Matchups":continue
        if flt=="open" and checks and all(c.get("done") for c in checks):continue
        hay=(str(n.get("title",""))+" "+str(n.get("body",""))+" "+str(n.get("category",""))+" "+" ".join(str(c.get("text","")) for c in checks)).lower()
        if q and q not in hay:continue
        out.append(n)
    return sorted(out,key=lambda n:(not n.get("pinned",False),str(n.get("updated",""))),reverse=False)

def handle_notes_manager_event(event):
    if modal.get("type")!="notes_manager":return False
    if event.type==pygame.KEYDOWN:
        mods=getattr(event,"mod",pygame.key.get_mods())
        if event.key==pygame.K_ESCAPE:
            if modal.get("focus") in ("_notes_title","_notes_body","_notes_search"):
                modal["focus"]=None;modal["_text_drag_field"]=None;return True
            close_notes_manager();return True
        if event.key==pygame.K_s and mods&(pygame.KMOD_CTRL|pygame.KMOD_META):save_notes_manager(True);return True
        if event.key==pygame.K_n and mods&(pygame.KMOD_CTRL|pygame.KMOD_META):_notes_new(False);return True
        return False
    if event.type==pygame.MOUSEWHEEL:
        pos=pygame.mouse.get_pos();lr=modal.get("_notes_list_rect");br=modal.get("_notes_body_rect")
        if lr and lr.collidepoint(pos):modal["_notes_scroll"]=max(0,float(modal.get("_notes_scroll",0))-event.y*48)
        elif br and br.collidepoint(pos):modal["_notes_body_scroll"]=max(0,float(modal.get("_notes_body_scroll",0))-event.y*34)
        return True
    if event.type==pygame.MOUSEBUTTONDOWN and event.button==1:
        pos=event.pos
        for r,action,payload in reversed(modal.get("_notes_controls",[])):
            if not r.collidepoint(pos):continue
            note=_notes_selected()
            if action=="close":close_notes_manager()
            elif action=="new":_notes_new(False)
            elif action=="matchup":
                _notes_prompt("New Simulation Matchup","Matchup title:","Matchup: Fighter A vs Fighter B",lambda v:_notes_new(True,str(v).strip() or None))
            elif action=="save":save_notes_manager(True)
            elif action=="backup":backup_notes_manager(True)
            elif action=="restore":_notes_restore_latest()
            elif action=="export":_notes_export_txt()
            elif action=="filter":modal["_notes_filter"]=payload;modal["_notes_scroll"]=0
            elif action=="select":modal["_notes_selected"]=payload;modal["_notes_body_scroll"]=0;modal["focus"]=None
            elif action=="pin" and note:note["pinned"]=not note.get("pinned");_notes_touch(note)
            elif action=="archive" and note:note["archived"]=not note.get("archived");_notes_touch(note);save_notes_manager(False)
            elif action=="duplicate" and note:
                cp=copy.deepcopy(note);cp["id"]=_notes_id();cp["title"]+= " Copy";cp["created"]=cp["updated"]=_notes_now();_NOTES_DATA["notes"].insert(0,cp);modal["_notes_selected"]=cp["id"];_notes_touch(cp)
            elif action=="category" and note:_notes_prompt("Note Category","Category:",note.get("category","General"),lambda v:(note.__setitem__("category",str(v).strip() or "General"),_notes_touch(note)))
            elif action=="add_check" and note:_notes_prompt("Add Checklist Item","Task:","",lambda v:(note.setdefault("checklist",[]).append({"id":_notes_id(),"text":str(v).strip() or "New task","done":False}),_notes_touch(note)))
            elif action=="toggle_check" and note:
                c=next((c for c in note.get("checklist",[]) if c.get("id")==payload),None)
                if c:c["done"]=not c.get("done");_notes_touch(note)
            elif action=="edit_check" and note:
                c=next((c for c in note.get("checklist",[]) if c.get("id")==payload),None)
                if c:_notes_prompt("Edit Checklist Item","Task:",c.get("text",""),lambda v:(c.__setitem__("text",str(v).strip() or "Task"),_notes_touch(note)))
            elif action=="delete_check" and note:note["checklist"]=[c for c in note.get("checklist",[]) if c.get("id")!=payload];_notes_touch(note)
            elif action=="clear_done" and note:note["checklist"]=[c for c in note.get("checklist",[]) if not c.get("done")];_notes_touch(note)
            elif action=="title" and note:
                modal["focus"]="_notes_title";modal["_text_active_focus"]=("notes_manager","_notes_title");modal["_text_cursor"]=len(str(note.get("title","")));modal["_text_anchor"]=None
            elif action=="body" and note:
                modal["focus"]="_notes_body";modal["_text_active_focus"]=("notes_manager","_notes_body");modal["_text_cursor"]=len(str(note.get("body","")));modal["_text_anchor"]=None
            elif action=="search":modal["focus"]="_notes_search";_text_editor_begin_mouse("_notes_search",r,pos[0],pygame.key.get_mods())
            return True
        return True
    return event.type in (pygame.MOUSEBUTTONUP,pygame.MOUSEMOTION)

def _notes_wrap(text,font,width):
    lines=[]
    for para in str(text).split("\n"):
        words=para.split(" ");cur=""
        for word in words:
            trial=word if not cur else cur+" "+word
            if font.size(trial)[0]<=width:cur=trial
            else:
                if cur:lines.append(cur)
                cur=word
        lines.append(cur)
    return lines or [""]

