_ns_terminal = {
    "open": False,
    "input": "",
    "output": [],          # list of (text, color)
    "history": [],         # submitted command strings
    "hist_idx": None,
    "running": False,
    "_out_queue": queue.Queue(),
    # --- v6.9 terminal upgrade ---
    "scroll": 0,           # lines scrolled up from the bottom (wheel/PageUpDown)
    "live": False,         # $live: mirror real stdout/stderr in here
    "_real_streams": None, # (stdout, stderr) saved when $live turns on
    "_stream_bufs": {"out": "", "err": ""},
    "_scheduled": [],      # $wait: {"time": float, "cmd": str, "delay": float}
    "_watches": [],        # $watch: {"expr": str, "last": float, "value": obj, "interval": float}
    "_aliases": {},        # $alias name -> command template
    "_exec_ns": None,      # lazy python namespace for $py/$eval/$watch
    "_alias_depth": 0,     # alias-expansion recursion guard
    "_paused": [],         # names movement-locked by $pause
}

def _terminal_log(text, color=(220, 220, 220)):
    for line in str(text).split("\n"):
        _ns_terminal["output"].append((line, color))
    if len(_ns_terminal["output"]) > 500:
        _ns_terminal["output"] = _ns_terminal["output"][-500:]

# ══════════════════════════════════════════════════════════════════════════
# DEV TERMINAL COMMAND SYSTEM
# Every built-in runs IN-PROCESS (instant). Anything unknown that also fails a
# fast PATH lookup reports "not a command" IMMEDIATELY - no more waiting on a
# PowerShell/bash cold start. Real shell commands still work (streamed live,
# cmd/bash by line) via plain typing or an explicit $shell prefix.
# ══════════════════════════════════════════════════════════════════════════
_TC_GOOD = (120, 230, 140)
_TC_WARN = (255, 200, 110)
_TC_ERR = (255, 130, 120)
_TC_DIM = (160, 160, 172)
_TC_ACC = (140, 220, 255)
_TC_GOLD = (255, 210, 130)
_TC_OUT = (205, 205, 212)
_TC_STDERR = (255, 150, 140)

_CMD_REGISTRY = []     # dicts: name, aliases, cat, usage, desc, fn
_CMD_BY_NAME = {}

def terminal_command(name, category, usage, desc, aliases=()):
    """Decorator: register one instant in-process terminal command."""
    def deco(fn):
        entry = {"name": name.lstrip("$"), "aliases": tuple(a.lstrip("$") for a in aliases),
                 "cat": category, "usage": usage, "desc": desc, "fn": fn}
        _CMD_REGISTRY.append(entry)
        for n in (entry["name"],) + entry["aliases"]:
            _CMD_BY_NAME[n.lower()] = entry
        return fn
    return deco

def _t_args(raw):
    try:
        import shlex as _shx
        return _shx.split(raw)
    except Exception:
        return str(raw).split()

def _t_num(tok, cast=float, label="number"):
    try:
        return cast(tok)
    except (TypeError, ValueError):
        raise ValueError(f"'{tok}' is not a valid {label}.")

def _t_bool(tok, default=None):
    s = str(tok).strip().lower()
    if s in ("1", "true", "yes", "on", "y"): return True
    if s in ("0", "false", "no", "off", "n"): return False
    if default is not None: return default
    raise ValueError(f"'{tok}' is not on/off.")

def _t_value(tok):
    """Parse bool/int/float/[r,g,b]/(x,y)/bare-string for $set/$config."""
    s = str(tok).strip()
    if s.lower() in ("true", "on", "yes"): return True
    if s.lower() in ("false", "off", "no"): return False
    try:
        return ast.literal_eval(s)
    except Exception:
        pass
    for cast in (int, float):
        try:
            return cast(s)
        except (TypeError, ValueError):
            pass
    return s

def _t_color(color_name):
    _NAMED = {"red": (235, 80, 80), "green": (90, 220, 130), "blue": (90, 150, 255),
              "yellow": (255, 220, 90), "gold": (255, 210, 130), "white": (240, 240, 245),
              "black": (8, 8, 10), "purple": (190, 120, 255), "pink": (255, 130, 200),
              "orange": (255, 160, 70), "cyan": (90, 220, 230), "grey": (140, 140, 150),
              "gray": (140, 140, 150)}
    toks = str(color_name).replace(",", " ").split()
    if len(toks) == 1:
        t = toks[0].lower()
        if t in _NAMED:
            return _NAMED[t]
        if t.startswith("#") and len(t) == 7:
            return (int(t[1:3], 16), int(t[3:5], 16), int(t[5:7], 16))
        raise ValueError(f"unknown color '{color_name}' (use r g b, #rrggbb, or a name)")
    if len(toks) == 3:
        return tuple(max(0, min(255, _t_num(x, int, "color channel"))) for x in toks)
    raise ValueError("color needs r g b, #rrggbb, or a name like red")

def _term_char(token, complain=True):
    """Exact name, else unique case-insensitive substring."""
    if token is None:
        return None
    for c in list(characters):
        if str(c.get("name", "")) == token:
            return c
    low = str(token).lower()
    subs = [c for c in list(characters) if low in str(c.get("name", "")).lower()]
    if len(subs) == 1:
        return subs[0]
    if complain:
        if not subs:
            _terminal_log(f"No character named/matching '{token}'. ($list to see all)", _TC_ERR)
        else:
            _terminal_log(f"'{token}' matches {len(subs)}: " +
                          ", ".join(str(c.get("name")) for c in subs[:6]) + (" ..." if len(subs) > 6 else ""), _TC_WARN)
    return None

def _term_chars(token):
    """'all'/'fighters' => every non-prop; otherwise one resolved character."""
    if str(token).strip().lower() in ("all", "everyone", "fighters", "*"):
        out = [c for c in list(characters) if not c.get("is_scene_prop")]
        if not out:
            _terminal_log("No fighter characters in the arena.", _TC_WARN)
        return out
    c = _term_char(token)
    return [c] if c is not None else []

def _term_exec_ns():
    ns = _ns_terminal.get("_exec_ns")
    if ns is None:
        ns = {"characters": characters, "SETTINGS": SETTINGS, "camera": camera,
              "CTX": CTX, "ctx": CTX, "pygame": pygame, "math": math, "random": random,
              "os": os, "sys": sys, "time": time, "screen": screen, "modal": modal,
              "call_hook": call_hook, "push_toast": push_toast,
              "WIDTH": WIDTH, "HEIGHT": HEIGHT}
        _ns_terminal["_exec_ns"] = ns
    return ns

def _term_kill_char(c):
    """Same death flow the scene debug Kill button uses."""
    if c.get("hp", 0) > 0:
        c["hp"] = 0
        try:
            call_hook(c, "on_death", CTX, c, None)
        except Exception:
            pass

# ────────────────────────── TERMINAL ──────────────────────────
@terminal_command("$ide","terminal","$ide [folder|file]","Open Arena Lite IDE: project explorer, multi-tab editor, line numbers, Python/C# syntax colors, undo/redo, find/replace, save-all, Python run, dotnet run/build, stop process, and output console.",aliases=("editor","code"))
def _tc_ide(argstr,args):
    target=os.path.abspath(os.path.expanduser(argstr.strip().strip('"') or _ARENA_INSTALL_DIR))
    if not os.path.exists(target):
        _terminal_log(f"IDE path does not exist: {target}",_TC_ERR);return
    if getattr(sys,"frozen",False):cmd=[sys.executable,"--arena-lite-ide",target]
    else:cmd=[sys.executable,os.path.abspath(__file__),"--arena-lite-ide",target]
    flags=getattr(subprocess,"CREATE_NEW_PROCESS_GROUP",0)
    try:
        subprocess.Popen(cmd,cwd=os.path.dirname(target) if os.path.isfile(target) else target,creationflags=flags)
        _terminal_log(f"Arena Lite IDE opened: {target}",_TC_GOOD)
    except Exception as exc:_terminal_log(f"Could not open IDE: {exc}",_TC_ERR)

@terminal_command("$help", "terminal", "$help [command|category]", "List every built-in command (this list), grouped by category. '$help <command>' = details, '$help <category>' = one group. Scroll with the mouse wheel.")
def _tc_help(argstr, args):
    _terminal_show_help(argstr.strip() or None)
    return None

def _terminal_show_help(query=None):
    cats = {}
    for e in _CMD_REGISTRY:
        cats.setdefault(e["cat"], []).append(e)
    if not query:
        n = len(_CMD_REGISTRY)
        _terminal_log(f"DEV TERMINAL - {n} built-in commands (mouse wheel / PgUp / PgDn to scroll)", _TC_GOLD)
        for cat in sorted(cats):
            _terminal_log(f"  [{cat.upper()}]", _TC_ACC)
            for e in cats[cat]:
                _terminal_log(f"    ${e['name']:<11} {e['usage']}", _TC_OUT)
        _terminal_log("Type $help <command> for full details. Unknown commands run as shell (instant check).", _TC_DIM)
        _terminal_log("Tip: $live on mirrors the game's own python output here in real time.", _TC_DIM)
        return
    qlow = query.strip().lstrip("$").lower()
    if qlow in cats:
        _terminal_log(f"[{qlow.upper()}] commands:", _TC_GOLD)
        for e in cats[qlow]:
            _terminal_log(f"  ${e['name']:<11} {e['usage']}", _TC_OUT)
        return
    hits = [e for e in _CMD_REGISTRY if qlow == e["name"].lower() or qlow in e["aliases"]]
    if not hits:
        hits = [e for e in _CMD_REGISTRY if qlow in e["name"].lower() or qlow in e["usage"].lower()]
    if hits:
        for e in hits[:4]:
            _terminal_log(f"${e['name']}  [{e['cat']}]", _TC_GOLD)
            _terminal_log(f"  usage: {e['usage']}", _TC_OUT)
            _terminal_log(f"  {e['desc']}", _TC_DIM)
            if e["aliases"]:
                _terminal_log("  aliases: " + ", ".join("$" + a for a in e["aliases"]), _TC_DIM)
    else:
        _terminal_log(f"No command matching '{query}'. Type $help for all {len(_CMD_REGISTRY)} commands.", _TC_ERR)

@terminal_command("$live", "terminal", "$live [on|off]", "LIVE OUTPUT: mirror the game's real stdout/stderr here, line by line, exactly like the python terminal it was launched from (prints, tracebacks, hook errors). $live with no args shows status.", aliases=("livelog",))
def _tc_live(argstr, args):
    want = None
    if args:
        want = _t_bool(args[0])
    cur = bool(_ns_terminal["live"])
    if want is None or want == cur:
        _terminal_log(f"live output: {'ON' if cur else 'OFF'}", _TC_ACC if cur else _TC_DIM)
        return None
    if want:
        _ns_terminal["_real_streams"] = (sys.stdout, sys.stderr)
        sys.stdout = _TerminalMirror(sys.stdout, "out")
        sys.stderr = _TerminalMirror(sys.stderr, "err")
        _ns_terminal["live"] = True
        _terminal_log("live output ON - prints/tracebacks now stream here (and still to the real console).", _TC_GOOD)
    else:
        real = _ns_terminal.get("_real_streams")
        if real:
            sys.stdout.flush() if hasattr(sys.stdout, "flush") else None
            sys.stdout, sys.stderr = real
        _ns_terminal["_real_streams"] = None
        _ns_terminal["live"] = False
        _terminal_log("live output OFF.", _TC_DIM)
    return None

class _TerminalMirror:
    """File-like tee: passes through to the real stream AND queues completed
    lines into the in-game terminal, so $live shows true python output."""
    def __init__(self, stream, kind):
        self._stream = stream
        self._kind = kind  # "out" | "err"
    def write(self, s):
        try:
            self._stream.write(s)
        except Exception:
            pass
        try:
            buf = _ns_terminal["_stream_bufs"].get(self._kind, "") + str(s)
            while "\n" in buf:
                line, buf = buf.split("\n", 1)
                if line.strip():
                    _ns_terminal["_out_queue"].put((line, _TC_OUT if self._kind == "out" else _TC_STDERR))
            _ns_terminal["_stream_bufs"][self._kind] = buf
        except Exception:
            pass
        return len(s)
    def flush(self):
        try:
            self._stream.flush()
        except Exception:
            pass
    def __getattr__(self, name):
        return getattr(self._stream, name)

