@terminal_command("$convert","utility","$convert clone txt",
                  "Choose any file and clone its exact contents beside it with a .txt extension.")
def _tc_convert(argstr,args):
    action=[str(a).strip().lower() for a in args]
    if action!=["clone","txt"]:raise ValueError("usage: $convert clone txt")
    root=None
    try:
        import tkinter as tk
        from tkinter import filedialog
        root=tk.Tk();root.withdraw();root.attributes("-topmost",True)
        source=filedialog.askopenfilename(title="Choose any file to clone as TXT",parent=root)
    finally:
        if root is not None:
            try:root.destroy()
            except Exception:pass
    if not source:_terminal_log("convert clone txt cancelled",_TC_WARN);return None
    source=os.path.abspath(source);folder=os.path.dirname(source);stem,ext=os.path.splitext(os.path.basename(source));base=(stem+"_clone" if ext.lower()==".txt" else stem);dest=os.path.join(folder,base+".txt");n=2
    while os.path.exists(dest):dest=os.path.join(folder,f"{base}_{n}.txt");n+=1
    shutil.copy2(source,dest);_terminal_log(f"cloned as TXT: {dest}",_TC_GOOD);push_toast(f"Created {os.path.basename(dest)}","success",2.5);return dest


