@terminal_command("$copy", "terminal", "$copy [all|last|<count>]", "Copy terminal output lines directly to system clipboard.", aliases=("pbcopy", "clip"))
def _cmd_terminal_copy(argstr, args):
    out = _ns_terminal.get("output", [])
    if not out:
        _terminal_log("[copy] No terminal output to copy.", _TC_WARN)
        return
    sub = args[0].lower() if args else "all"
    if sub == "last":
        # Copy output of the last command
        last_lines = []
        for text_l, col in reversed(out):
            last_lines.insert(0, str(text_l))
            if str(text_l).startswith("> "):
                break
        copy_text = "\n".join(last_lines)
    elif sub.isdigit():
        n_lines = int(sub)
        copy_text = "\n".join(str(t) for t, c in out[-n_lines:])
    else:
        copy_text = "\n".join(str(t) for t, c in out)
        
    ok = _copy_to_system_clipboard(copy_text)
    if ok:
        _terminal_log(f"[copy] ✓ Copied {len(copy_text.splitlines())} line(s) to system clipboard.", _TC_GOOD)
        try: push_toast(f"Copied {len(copy_text.splitlines())} terminal lines to clipboard", "success", 2.0)
        except Exception: pass
    else:
        _terminal_log("[copy] Failed to copy automatically to clipboard.", _TC_ERR)


@terminal_command("$export-arda", "system", "$export-arda [filename.arda]", "Export all software data into a single portable .arda archive.", aliases=("$export_arda", "$export-data", "$backup-data"))
def _cmd_export_arda(argstr, args):
    fn = argstr.strip() or f"arena_data_{int(time.time())}.arda"
    out_f = os.path.join(_get_app_root_dir(), fn)
    try:
        res_p, mf = export_arda_package(out_f)
        _terminal_log(f"[arda] ✓ Successfully exported .arda archive to: {res_p}", _TC_GOOD)
        push_toast(f"Exported .arda package to {os.path.basename(res_p)}", "success", 4.0)
    except Exception as e:
        _terminal_log(f"[arda error] Export failed: {e}", _TC_ERR)

@terminal_command("$import-arda", "system", "$import-arda <file.arda> [append|overwrite|fresh]", "Import software data from a .arda archive.", aliases=("$import_arda", "$import-data", "$restore-data"))
def _cmd_import_arda(argstr, args):
    if not args:
        _terminal_log("usage: $import-arda <path/to/file.arda> [append|overwrite|fresh]", _TC_WARN)
        return
    fpath = args[0]
    if not os.path.isabs(fpath):
        fpath = os.path.join(_get_app_root_dir(), fpath)
    mode = args[1].lower() if len(args) > 1 else "append"
    if not os.path.isfile(fpath):
        _terminal_log(f"[arda error] File not found: {fpath}", _TC_ERR)
        return
    ok, msg = import_arda_package(fpath, mode=mode)
    if ok:
        _terminal_log(f"[arda] ✓ {msg}", _TC_GOOD)
        push_toast(msg, "success", 4.0)
    else:
        _terminal_log(f"[arda error] {msg}", _TC_ERR)

