# ────────────────────────── CHARACTERS ──────────────────────────
@terminal_command("$list", "characters", "$list [filter|props]", "List characters with hp/pos/team. $list props = only scene props, $list heroes = name filter.", aliases=("chars", "$chars", "ls"))
def _tc_list(argstr, args):
    rows = list(characters)
    if args:
        f = args[0].lower()
        if f in ("props", "prop"):
            rows = [c for c in rows if c.get("is_scene_prop")]
        elif f in ("fighters", "chars", "characters"):
            rows = [c for c in rows if not c.get("is_scene_prop")]
        else:
            rows = [c for c in rows if f in str(c.get("name", "")).lower()]
    if not rows:
        _terminal_log("no matches.", _TC_WARN)
        return None
    _terminal_log(f"{len(rows)} character(s):", _TC_GOLD)
    for c in rows[:40]:
        p = c.get("pos")
        kind = "prop" if c.get("is_scene_prop") else ("kin" if c.get("body_type") == "kinematic" else "dyn")
        dead = " DEAD" if c.get("hp", 1) <= 0 else ""
        _terminal_log(f"  {str(c.get('name','?'))[:18]:<18} hp {c.get('hp',0):>6.0f}/{c.get('max_hp',0):>6.0f} pos({p.x:6.0f},{p.y:6.0f}) {kind} {str(c.get('team','-'))[:10]}{dead}", _TC_OUT)
    if len(rows) > 40:
        _terminal_log(f"  ... +{len(rows) - 40} more (use a filter)", _TC_DIM)
    return None

@terminal_command("$info", "characters", "$info <name>", "Detailed dump: body, physics, flags, script, sprite state.")
def _tc_info(argstr, args):
    c = _term_char(args[0] if args else None)
    if not c:
        return None
    p, v = c.get("pos"), c.get("vel")
    _terminal_log(f"-- {c.get('name')} --", _TC_GOLD)
    _terminal_log(f"  hp {c.get('hp')}/{c.get('max_hp')} team {c.get('team')} body {c.get('body_type')} shape {c.get('collision_shape')}", _TC_OUT)
    _terminal_log(f"  pos({p.x:.1f},{p.y:.1f}) vel({v.x:.1f},{v.y:.1f}) speed {c.get('speed')} max {c.get('max_speed')}", _TC_OUT)
    _terminal_log(f"  gravity {c.get('gravity')} {'ON' if c.get('gravity_enabled') else 'off'} grounded {c.get('gravity_grounded')} bounce {c.get('bounce')}", _TC_OUT)
    _terminal_log(f"  walls: {sorted(c.get('_wall_contacts') or [])} | last touch {c.get('_last_wall_touch_dir')} last bounce {c.get('_last_bounce_dir')}", _TC_OUT)
    _terminal_log(f"  locks: move={bool(c.get('movement_locked'))} sleep={bool(c.get('sleeping'))} frozen_x={bool(c.get('freeze_x'))} y={bool(c.get('freeze_y'))}", _TC_OUT)
    _terminal_log(f"  anim {c.get('visual_state')} | script {c.get('script_file')} | scale {c.get('scale')} angle {c.get('angle', 0)}", _TC_OUT)
    return None

@terminal_command("$find", "characters", "$find <text>", "Names matching text (fast fuzzy search incl. teams and scripts).")
def _tc_find(argstr, args):
    if not args:
        _terminal_log("usage: $find <text>", _TC_WARN)
