    if len(args) >= 2:
        v = max(1.0, _t_num(args[1]))
        c["max_hp"] = v
        c["hp"] = min(float(c.get("hp", v)), v)
        _terminal_log(f"{c.get('name')} max_hp = {v:g}", _TC_GOOD)
