# ────────────────────────── DEBUG / SETTINGS / PYTHON ──────────────────────────
@terminal_command("$config", "settings", "$config [key] [value]", "Read/write SETTINGS. $config = dump all, $config key = show, $config key value = set (auto-parsed: bool/number/[r,g,b]/text).", aliases=("cfg",))
def _tc_config(argstr, args):
    if not args:
        keys = sorted(SETTINGS.keys())
        _terminal_log(f"SETTINGS ({len(keys)} keys, first 60):", _TC_GOLD)
        for i in range(0, min(len(keys), 60), 2):
            _terminal_log("  " + "  ".join(f"{k[:24]}={str(SETTINGS[k])[:18]:<18}" for k in keys[i:i + 2]), _TC_OUT)
        return None
    key = args[0]
    if key not in SETTINGS:
        near = [k for k in SETTINGS if key.lower() in str(k).lower()][:8]
        _terminal_log(f"no SETTINGS key '{key}'." + (f" similar: {', '.join(near)}" if near else ""), _TC_WARN)
        return None
    if len(args) == 1:
        _terminal_log(f"{key} = {SETTINGS[key]!r}", _TC_OUT)
        return None
    val = _t_value(" ".join(args[1:]))
    old = SETTINGS.get(key)
    if isinstance(old, bool):
        val = _t_bool(val, default=bool(old))
    SETTINGS[key] = val
    try:
        _settings_saver = globals().get("save_settings")
        if callable(_settings_saver):
            _settings_saver()
    except Exception:
        pass
    _terminal_log(f"{key} = {SETTINGS[key]!r} (was {old!r})", _TC_GOOD)
    return None

@terminal_command("$volume", "settings", "$volume [0-100]", "Get or set master volume.", aliases=("vol",))
def _tc_volume(argstr, args):
    global MASTER_VOLUME
    if not args:
        _terminal_log(f"master volume: {int(MASTER_VOLUME * 100)}%", _TC_OUT)
        return None
    MASTER_VOLUME = max(0.0, min(1.0, _t_num(args[0]) / 100.0))
    try:
        pygame.mixer.music.set_volume(MASTER_VOLUME)
    except Exception:
        pass
    _terminal_log(f"master volume = {int(MASTER_VOLUME * 100)}%", _TC_GOOD)
    return None

@terminal_command("$hooks", "settings", "$hooks [on|off]", "Toggle NS_DEBUG_HOOKS (dumps which scripts/hooks load) without touching the env from a shell.")
def _tc_hooks(argstr, args):
    cur = os.environ.get("NS_DEBUG_HOOKS", "")
    want = _t_bool(args[0]) if args else not cur
    if want:
        os.environ["NS_DEBUG_HOOKS"] = "1"
    else:
        os.environ.pop("NS_DEBUG_HOOKS", None)
    _terminal_log(f"NS_DEBUG_HOOKS {'on' if want else 'off'} (needs $live on to see dumps here).", _TC_GOOD)
    return None

@terminal_command("$py", "settings", "$py <python code>", "Run python against live engine state (characters, SETTINGS, camera, CTX, screen...). Output prints right here.", aliases=("python",))
def _tc_py(argstr, args):
    if not argstr.strip():
        _terminal_log("usage: $py <code>", _TC_WARN)
        return None
    import contextlib as _cl
    buf_out, buf_err = io.StringIO(), io.StringIO()
    try:
        with _cl.redirect_stdout(buf_out), _cl.redirect_stderr(buf_err):
            exec(argstr, _term_exec_ns())
    except Exception:
        buf_err.write(traceback.format_exc())
    if buf_out.getvalue():
        _terminal_log(buf_out.getvalue().rstrip("\n"), _TC_OUT)
    if buf_err.getvalue():
        _terminal_log(buf_err.getvalue().rstrip("\n"), _TC_STDERR)
    return None

@terminal_command("$eval", "settings", "$eval <expression>", "Evaluate one python expression and print the result.", aliases=("=",))
def _tc_eval(argstr, args):
    if not argstr.strip():
        _terminal_log("usage: $eval <expression>", _TC_WARN)
        return None
    try:
        result = eval(argstr, _term_exec_ns())
        _terminal_log(repr(result), _TC_OUT)
    except Exception:
        _terminal_log(traceback.format_exc(limit=2).rstrip("\n"), _TC_STDERR)
    return None

@terminal_command("$watch", "settings", "$watch <expression>", "Re-evaluate an expression twice a second; prints when the value CHANGES (e.g. $watch len(characters)). $unwatch <n|all> removes, $watchlist shows.")
def _tc_watch(argstr, args):
    if not argstr.strip():
        _terminal_log("usage: $watch <expression>", _TC_WARN)
        return None
    if len(_ns_terminal["_watches"]) >= 10:
        _terminal_log("max 10 watches - $unwatch something first.", _TC_WARN)
        return None
    _ns_terminal["_watches"].append({"expr": argstr.strip(), "last": 0.0, "value": object(), "interval": 0.5})
    _terminal_log(f"watching: {argstr.strip()}", _TC_GOOD)
    return None

@terminal_command("$unwatch", "settings", "$unwatch <n|all>", "Remove watch #n (see $watchlist) or all watches.")
def _tc_unwatch(argstr, args):
    w = _ns_terminal["_watches"]
    if args and args[0].lower() == "all":
        w.clear()
        _terminal_log("all watches removed.", _TC_GOOD)
        return None
    idx = _t_num(args[0], int, "watch number") if args else 0
    if 1 <= idx <= len(w):
        gone = w.pop(idx - 1)
        _terminal_log(f"unwatched: {gone['expr']}", _TC_GOOD)
    else:
        _terminal_log("no such watch (see $watchlist).", _TC_WARN)
    return None

@terminal_command("$watchlist", "settings", "$watchlist", "List active watches and their latest values.")
def _tc_watchlist(argstr, args):
    w = _ns_terminal["_watches"]
    if not w:
        _terminal_log("no watches.", _TC_DIM)
        return None
    for i, it in enumerate(w, 1):
        _terminal_log(f"  {i}. {it['expr']} = {it.get('value')!r}", _TC_OUT)
    return None

@terminal_command("$broadcast", "settings", "$broadcast <event> [payload]", "Fire a broadcast to every script's On Broadcast hook (test your graphs instantly).", aliases=("emit",))
def _tc_broadcast(argstr, args):
    if not args:
        _terminal_log("usage: $broadcast <event> [payload]", _TC_WARN)
        return None
    payload = " ".join(args[1:]) if len(args) > 1 else None
    try:
        payload = _t_value(payload) if payload is not None else None
    except Exception:
        pass
    CTX.broadcast_scene_event(None, str(args[0]), payload)
    _terminal_log(f"broadcast '{args[0]}' payload={payload!r}", _TC_GOOD)
    return None

# ══════════════════════════════════════════════════════════════════════════
# DISPATCH
# ══════════════════════════════════════════════════════════════════════════
_SHELL_BUILTINS = {"dir", "type", "echo", "copy", "del", "erase", "ren", "rename",
                   "move", "md", "mkdir", "rd", "rmdir", "where", "cls", "ver", "vol"}

def _terminal_env_assign(cmd):
    m = re.match(r'^\$env:([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', cmd)
    if not m:
        m = re.match(r'^(?:export|set)\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)$', cmd, re.IGNORECASE)
    if not m:
        return False
    name, val = m.group(1), m.group(2).strip().strip('"').strip("'")
    os.environ[name] = val
    _terminal_log(f"{name} = {val}", _TC_GOOD)
    return True

def _terminal_spawn_shell(cmd):
    """Run a real shell command with LIVE line streaming (no more waiting for
    the whole process before output appears)."""
    try:
        first = _t_args(cmd)[0]
    except Exception:
        first = cmd.split()[0] if cmd.split() else ""
    if not first:
        return
    prog = first.lstrip("./\\")
    if prog.lower() not in _SHELL_BUILTINS and shutil.which(first) is None:
        _terminal_log(f"'{first}' is not a recognized command (instant PATH check).", _TC_ERR)
        _terminal_log("Built-ins: $help - shell builtins like dir/cd work, or prefix with $shell.", _TC_DIM)
        return
    _ns_terminal["running"] = True

    def _worker():
        proc = None
        try:
            if sys.platform.startswith("win"):
                shell_cmd = ["cmd", "/c", cmd]   # cmd cold-starts ~10x faster than powershell
            else:
                shell_cmd = ["/bin/bash", "-c", cmd]
            proc = subprocess.Popen(shell_cmd, stdout=subprocess.PIPE,
                                    stderr=subprocess.STDOUT, text=True, bufsize=1)
            timed_out = [False]

            def _watchdog():
                try:
                    proc.wait(timeout=30)
                except Exception:
                    timed_out[0] = True
                    try:
                        proc.kill()
                    except Exception:
                        pass
            threading.Thread(target=_watchdog, daemon=True).start()
            for line in proc.stdout:
                _ns_terminal["_out_queue"].put((line.rstrip("\n").rstrip("\r"), _TC_OUT))
            proc.wait()
            if timed_out[0]:
                _ns_terminal["_out_queue"].put(("[killed: 30s timeout]", _TC_ERR))
            elif proc.returncode:
                _ns_terminal["_out_queue"].put((f"(exit code {proc.returncode})", _TC_DIM))
        except Exception as e:
            _ns_terminal["_out_queue"].put((f"[shell error] {e}", _TC_ERR))
        finally:
            _ns_terminal["_out_queue"].put(None)  # sentinel: command finished

    threading.Thread(target=_worker, daemon=True).start()

