@terminal_command("$fullscreen", "settings", "$fullscreen [on|off]",
                  "Toggle the game window fullscreen (same as F11): $fullscreen on forces fullscreen, $fullscreen off forces windowed, no argument toggles.",
                  aliases=("fs", "fscreen"))
def _tc_fullscreen(argstr, args):
    want = str(args[0]).lower() if args else ""
    if want in ("on", "1", "true", "yes", "y"):
        if not is_fullscreen:
            toggle_fullscreen()
    elif want in ("off", "0", "false", "no", "n"):
        if is_fullscreen:
            toggle_fullscreen()
    elif want:
        raise ValueError("usage: $fullscreen [on|off]")
    else:
        toggle_fullscreen()
    _terminal_log(f"fullscreen: {'ON' if is_fullscreen else 'OFF'}  (window {WIDTH}x{HEIGHT})", _TC_GOOD)
    return None

