    _terminal_log("── SCENE NODES ──", _TC_ACC)
    _terminal_log(f"  external nodes  : {snap['external_nodes']}  (visible {snap['external_visible']})", _TC_OUT)
    _terminal_log(f"  scene texts     : {snap['scene_texts']}", _TC_OUT)
    _terminal_log(f"  scene images    : {snap['scene_images']}", _TC_OUT)
