                                    # 1) drag-gizmo pickup for whatever is selected (layer wins)
                                    if _sel_layer in ("bg", "fill", "frame", "text") and not modal.get(f"spe_{_sel_layer}_lock", False):
                                        if _gz.get("center") and _gz["center"].collidepoint(mx, my):
                                            modal["_spe_dragging_layer"] = {"id": _sel_layer, "kind": "free", "start_mx": mx, "start_my": my, "start_x": float(modal.get(f"spe_{_sel_layer}_off_x", 0)), "start_y": float(modal.get(f"spe_{_sel_layer}_off_y", 0))}
                                            _spe_consumed = True
                                        elif _gz.get("x") and _gz["x"].collidepoint(mx, my):
                                            modal["_spe_dragging_layer"] = {"id": _sel_layer, "kind": "x", "start_mx": mx, "start_my": my, "start_x": float(modal.get(f"spe_{_sel_layer}_off_x", 0)), "start_y": float(modal.get(f"spe_{_sel_layer}_off_y", 0))}
