                                            modal["_spe_dragging_aes"] = {"idx": _sel_idx, "kind": "free", "start_mx": mx, "start_my": my, "start_x": float(_aes_list[_sel_idx].get("x", 0)), "start_y": float(_aes_list[_sel_idx].get("y", 0))}
                                            _spe_consumed = True
