                                    _src_debug_button.setdefault("props",{}).setdefault("show_in_window",True)
                                    modal["ns_show_script"]=True;modal["ns_right_tab"]="tools";modal["ns_tools_scroll"]=0
                                    _host_title=getattr(NODE_DEFS.get(_host.get("type"),NodeBase),"title",_host.get("type","Node"))
