                            if _best_wy is not None:
                                wy = _best_wy; align_y = _guide_gy

                            modal["_ns_align_guide_x"] = align_x
                            modal["_ns_align_guide_y"] = align_y

                            dx = wx - n["x"]; dy = wy - n["y"]
                            n["x"] = wx; n["y"] = wy
                            # Also drag any clamped nodes attached to this node
                            for other_id, other_node in modal["ns_nodes"].items():
                                if other_node.get("props", {}).get("clamped_to") == nid:
                                    other_node["x"] += dx
                                    other_node["y"] += dy
                            # Fused clip groups move as one.  Do not move their
