                            ("Copy Folder Path", lambda f=_folder_target: (_ns_clipboard_copy("audio/_imported" + (("/" + f) if f else "")), push_toast("Folder path copied.", "success"))),
                            ("Refresh Folder", lambda: refresh_audio_library_files()),
