            characters[:] = [c for c in characters if not c.get("_despawned")]
            dead = [c for c in characters if c["hp"] <= 0]
            for c in dead:
                play_audio_cue(c, "death")
                killer_name = c.get("_last_hit_by")
                killer = next((x for x in characters if x["name"] == killer_name and x is not c), None)
                _scene_debug_archive_death(c,killer)
                call_hook(c, "on_death", CTX, c, killer)
                for _sp in list(characters):
                    call_hook(_sp, "on_scene_death", CTX, c, killer)
                dead_team = c.get("team", c.get("name"))
