            for mod in mods:
                stat = mod["stat"]
                if not mod.get("applied"):
                    old = character.get(stat, 0)
                    mod["old"] = old
                    character[stat] = old * mod["amount"] if mod.get("multiply") else old + mod["amount"]
                    mod["applied"] = True
                if now_mod >= mod["end"] and mod.get("applied"):
                    character[stat] = mod.get("old", character.get(stat,0))
                    mod["expired"] = True
            character["_timed_modifiers"] = [m for m in mods if not m.get("expired")]

