            _fb=(float(_follow_node.get("wx",0.0) or 0.0),float(_follow_node.get("wy",0.0) or 0.0),bool(_follow_node.get("visible",True)))
            _en_tick_char_follow(_follow_node)
            _fa=(float(_follow_node.get("wx",0.0) or 0.0),float(_follow_node.get("wy",0.0) or 0.0),bool(_follow_node.get("visible",True)))
            if _fa!=_fb:_scene_constraint_changed=True

