        _idle_authoring_state=_scene_editor_runtime_state()
        _idle_scene_static=not (particles or world_effects or area_zones or popups or pheromone_markers or _WEAPON_PROJECTILES or _idle_authoring_state["emitters"] or _idle_authoring_state["tweens"] or _idle_authoring_state["smooth"] or _scene_constraint_changed)
        _idle_jobs=bool(is_recording or _OBS_RECORDING_ACTIVE or export_render_job or (isinstance(_gpu_finalize_job,dict) and not _gpu_finalize_job.get("done")) or (isinstance(_apu_compile_job,dict) and not _apu_compile_job.get("done")))
        _idle_mouse=pygame.mouse.get_pos();_idle_mouse_pressed=any(pygame.mouse.get_pressed())
        _idle_mouse_over_ui=bool(ui_visible and ((_idle_mouse[0]<SIDEBAR_W and not globals().get("_SIDEBAR_HIDDEN", False)) or point_in_tool_dock(_idle_mouse)))
        _idle_mouse_over_item=False
        if not _idle_mouse_over_ui:
            try:
                _idle_mouse_over_item=any(isinstance(obj.get("_rect"),pygame.Rect) and obj["_rect"].inflate(8,8).collidepoint(_idle_mouse) for obj in list(external_nodes)+list(scene_texts)+list(scene_images))
                if not _idle_mouse_over_item:_idle_mouse_over_item=any(isinstance(c.get("_screen_rect"),pygame.Rect) and c["_screen_rect"].inflate(8,8).collidepoint(_idle_mouse) for c in characters)
            except Exception:_idle_mouse_over_item=False
        _idle_press_animation=any(float(until)>time.time() for until in _UI_ELEMENT_PRESSED_UNTIL.values()) or any(float(st.get("until",0))>time.time() for st in _ui_press_btns.values())
        _idle_scroll_or_drag=bool(globals().get("dragging_slider") is not None or globals().get("_SCROLLBAR_DRAG") is not None or modal.get("_uct_scroll_drag") or _APU_PROGRESS_DRAGGING)
        # Keep rendering briefly after wheel/key/click input so inertial scroll,
