                # now: grid + folder tree + inspector actions.

                # ── Audio Asset Browser workspace ────────────────────────────
                # The sidebar remains only as the application navigator. Actual
                # audio work happens in this three-pane content browser.
                ws = pygame.Rect(SIDEBAR_W + 14, 62, max(320, WIDTH-SIDEBAR_W-28), max(260, HEIGHT-76))
                draw_panel(ws, alpha=253, radius=14, color=APP_BG)
                wx, wy, ww = ws.x+16, ws.y+14, ws.width-32
                title = font_lg.render("Audio Assets", True, TEXT_MAIN)
                screen.blit(title, (wx, wy))
                subtitle = font_tiny.render("PROJECT CONTENT BROWSER  ·  import, organize, preview, and assign sound", True, TEXT_FAINT)
                screen.blit(subtitle, (wx, wy+27))
                toolbar_y=wy+52
                search_rect=pygame.Rect(wx,toolbar_y,min(330,ww//2),32)
                draw_text_field(search_rect, modal.get("audio_asset_search",""), "Search assets, folders, tags", modal.get("focus")=="audio_asset_search")
                modal["_audio_asset_search_rect"]=search_rect
                tbuttons=[]
                for label, icon in (("Import","import_"),("Scan","refresh"),("New Folder","folder")):
                    bw=84 if label!="New Folder" else 106
