                _afnf = pygame.Rect(left.right-28, left.y+6, 20, 20)
                _afnf_hov = _afnf.collidepoint(mouse_pos)
                ui_draw_rect(screen, ACCENT if _afnf_hov else (20,20,26), _afnf, border_radius=5)
                ui_draw_rect(screen, ACCENT if _afnf_hov else PANEL_BORDER, _afnf, width=1, border_radius=5)
                blit_icon(screen, IC.get("plus"), _afnf.centerx, _afnf.centery, 12, ACCENT_HOVER if _afnf_hov else TEXT_DIM)
                modal["_audio_folder_new_btn"] = _afnf
                # Nested folders are shown as an indented tree (depth = number of
