                # Folder tree: collapsible branches (twisty on any folder that
                # contains subfolders) with per-folder asset counts. The tree
                # mirrors audio/_imported on disk; counts reflect only files
                # that actually exist (registry is pruned on every scan).
                folders=[("", "All Audio")] + [(f, f.split("/")[-1]) for f in globals()["_cached_audio_folders"] if f]
                modal.setdefault("audio_asset_folder", "")
                modal.setdefault("audio_show_assets", False)
                modal.setdefault("_audio_folder_collapsed", set())
                modal["_audio_asset_folder_rows"]=[]
                modal["_audio_folder_twisty_rows"]=[]
                folder_list_rect=pygame.Rect(left.x,left.y+30,left.width,left.height-_sidebar_footer_hint_reserve())
                modal["_audio_folder_list_rect"]=folder_list_rect
                folder_row_h=31
                _fkids={}
                for _fk,_fl in folders[1:]:
                    _fparent=_fk.rsplit("/",1)[0] if "/" in _fk else ""
                    _fkids.setdefault(_fparent,[]).append(_fk)
                _collapsed=modal["_audio_folder_collapsed"]
                _tree_rows=[("","All Audio",0,False)]
                def _walk_folders(_parent,_depth):
                    for _ch in _fkids.get(_parent,[]):
                        _has_kids=bool(_fkids.get(_ch))
                        _tree_rows.append((_ch,_ch.split("/")[-1],_depth,_has_kids))
                        if _has_kids and _ch not in _collapsed:
                            _walk_folders(_ch,_depth+1)
                _walk_folders("",0)
                folder_content_h=len(_tree_rows)*folder_row_h+8
