                folder_scroll=max(0.0, min(modal.get("_audio_folder_scroll",0.0), folder_max_scroll))
                modal["_audio_folder_scroll"]=folder_scroll
                _folder_clip_backup=screen.get_clip(); screen.set_clip(folder_list_rect)
                fy=folder_list_rect.y+5-folder_scroll
