                            if folder_key in _collapsed:
                                pygame.draw.polygon(screen,_twc,[(_tw.x+5,_tw.y+3),(_tw.x+5,_tw.y+11),(_tw.x+11,_tw.y+7)])
                            else:
                                pygame.draw.polygon(screen,_twc,[(_tw.x+3,_tw.y+4),(_tw.x+11,_tw.y+4),(_tw.x+7,_tw.y+11)])
                            modal["_audio_folder_twisty_rows"].append((folder_key,_tw))
