                grid_list_rect=pygame.Rect(grid.x,grid.y+30,grid.width,grid.height-34)
                modal["_audio_grid_list_rect"]=grid_list_rect
                rows_needed=(len(assets)+cols-1)//cols
                grid_content_h=rows_needed*(card_h+8)+12
                grid_max_scroll=max(0.0, grid_content_h-grid_list_rect.height)
                modal["_audio_grid_max_scroll"]=grid_max_scroll
                grid_scroll=max(0.0, min(modal.get("_audio_grid_scroll",0.0), grid_max_scroll))
                modal["_audio_grid_scroll"]=grid_scroll
                _grid_clip_backup=screen.get_clip(); screen.set_clip(grid_list_rect)
                for idx,asset in enumerate(assets):
                    cx=grid.x+11+(idx%cols)*(card_w+8);cy=grid.y+34-grid_scroll+(idx//cols)*(card_h+8);card=pygame.Rect(cx,cy,card_w,card_h)
                    if card.bottom<grid_list_rect.y or card.y>grid_list_rect.bottom: continue
                    sel=modal.get("audio_asset_selected")==asset.get("id")
                    ui_draw_rect(screen,(29,25,44) if sel else (19,19,25) if card.collidepoint(mouse_pos) else (16,16,21),card,border_radius=8)
                    ui_draw_rect(screen,ACCENT if sel else PANEL_BORDER,card,width=2 if sel else 1,border_radius=8)
                    thumb=pygame.Rect(card.x+8,card.y+8,card.width-16,55);ui_draw_rect(screen,(25,23,32),thumb,border_radius=6)
                    blit_icon(screen,IC.get("audio"),thumb.centerx,thumb.centery,28,ACCENT_HOVER)
                    name=truncate_text_to_width(font_sm,str(asset.get("name","Audio")),card.width-16);screen.blit(name and font_sm.render(name,True,TEXT_MAIN),(card.x+8,card.y+70))
                    meta=font_tiny.render(os.path.splitext(str(asset.get("path","")))[1].upper().replace(".","") or "AUDIO",True,TEXT_FAINT);screen.blit(meta,(card.x+8,card.y+90))
                    modal["_audio_asset_grid_cards"].append((asset,card))
                # If no library results but disk search found files anywhere, show them as importable
