                if selected:
                    blit_icon(screen,IC.get("audio"),right.centerx,right.y+65,38,ACCENT_HOVER)
                    nm=truncate_text_to_width(font_md,str(selected.get("name","Audio")),right.width-24);screen.blit(font_md.render(nm,True,TEXT_MAIN),(right.x+12,right.y+100))
                    details=[("PATH",selected.get("path","")),("FOLDER",selected.get("folder") or "audio/_imported"),("TAGS",", ".join(selected.get("tags",[])) or "No tags")]
                    dy=right.y+138
                    for k,v in details:
                        screen.blit(font_tiny.render(k,True,TEXT_FAINT),(right.x+12,dy));dy+=14
                        for line in textwrap.wrap(str(v),width=23)[:2]:screen.blit(font_tiny.render(line,True,TEXT_DIM),(right.x+12,dy));dy+=13
                        dy+=8
                    # Quick actions: Move / Rename / Remove — always visible so
