                _status_text = f"{len(modal.get('ns_nodes', {}))} nodes  ·  {len(modal.get('ns_links', []))} links  ·  {int(z*100)}%"
                if _sel_count: _status_text += f"  ·  {_sel_count} selected"
                _status_s = font_tiny.render(_status_text, True, TEXT_DIM)
                _status_r = pygame.Rect(canvas.x + 9, canvas.bottom - 25, _status_s.get_width()+18, 18)
                _status_bg = pygame.Surface((_status_r.width, _status_r.height), pygame.SRCALPHA)
                pygame.draw.rect(_status_bg, (10,10,15,210), _status_bg.get_rect(), border_radius=7)
