                    draw_button(_insp_toggle, _arr, _tghov, small=True, muted=True)
                    # Handle click on toggle: pin/lock
                    if _tghov and left_click_this_frame:
                        modal["ns_inspector_locked"] = not _insp_locked
                        # If locking closed while open, set show_inspector False style? We
                        # keep show_inspector True but locked=False is auto-hide.
                        # Actually treat "lock" as "stay open at full width", unlock as hover-only.
                        left_click_this_frame = False
                    if insp_w > _insp_w_icon + 20:
                        modal["_ns_insp_rect"] = insp
                        # Floating expander overlay intentionally disabled.
                        modal["_ns_expander_rect"] = None
                        modal["_ns_expander_close_btn"] = None
                        modal["_ns_pending_expander"] = None

                        sel = nodes.get(modal.get("ns_selected"))
                        insp_scroll = modal.get("ns_insp_scroll", 0.0)
                        # When easing open, pad content in a bit so it doesn't poke through
                        _clip = insp.inflate(-8,-8)
                        _old_clip = screen.get_clip()
                        screen.set_clip(_clip)
                        iy = insp.y + 34 - insp_scroll
                        insp_content_top = insp.y + 34
                    else:
                        # Inspector is collapsed to its icon strip: nothing to
                        # select or draw into it this frame. Without this,
                        # `sel` (checked just below) was left undefined and
                        # crashed the very next time the collapsed state was
                        # reached with a node selected.
                        sel = None
                        # No clip was set in this branch (see the `if` above),
                        # so there's nothing to restore. Without this, the
                        # unconditional screen.set_clip(_old_clip) below
                        # crashed with NameError the first time this branch ran.
                        _old_clip = None
                        # Same story for these three: the code after this
                        # if/else block (content-height/scroll-limit calc)
                        # reads them unconditionally, so the collapsed branch
                        # needs harmless defaults too instead of leaving them
                        # undefined.
                        insp_scroll = modal.get("ns_insp_scroll", 0.0)
                        insp_content_top = insp.y + 34
                        iy = insp_content_top
                    modal_sliders = []
                    modal["_ns_prop_rects"] = {}
                    modal["_ns_prop_number_rects"] = {}
                    modal["_ns_prop_animation_rects"] = {}
                    modal["_ns_prop_sprite_rects"] = {}
                    modal["_ns_prop_character_rects"] = {}
                    modal["_ns_prop_color_rects"] = {}
                    modal["_ns_prop_hex_rects"] = {}
                    modal["_ns_prop_script_file_rects"] = {}
                    modal["_ns_debug_host_setting_rects"] = []
                    modal["_ns_layout_reset_btn"] = None
                    modal["_ns_cluster_build_btn"] = None
                    modal["_ns_cluster_helper_btn"] = None
                    modal["_ns_cluster_teach_btn"] = None
                    modal["_ns_idea_autocomplete_rects"] = []
                    modal["_ns_idea_template_btn"] = None
                    insp_clip_prev = screen.get_clip()
                    screen.set_clip(insp)
                    if sel:
                        cls = NODE_DEFS.get(sel.get("type"), NodeBase)
                        screen.blit(_ns_text(font_sm, cls.title, True, TEXT_MAIN), (insp.x + 12, iy))
                        iy += 22
                        screen.blit(_ns_text(font_tiny, cls.key, True, TEXT_FAINT), (insp.x + 12, iy))
                        iy += 20
                        # ── Change Node Type button ──
                        _chg_btn = pygame.Rect(insp.x + 12, iy, insp.width - 24, 24)
