                                screen.blit(_ns_text(font_tiny, "Auto-Pan Camera Tracker", True, TEXT_MAIN), (insp.x + 34, card_y + 25))
                                modal["_ns_dbg_pan_checkbox"] = pan_checkbox

                                ignore_checkbox = pygame.Rect(insp.x + 12, card_y + 48, 16, 16)
