                            if linked_input:
                                source = nodes.get(linked_input.get("from"))
                                source_cls = NODE_DEFS.get(source.get("type")) if source else None
                                source_name = source_cls.title if source_cls else "wired value"
                                connected_rect = pygame.Rect(insp.x + 12, iy, insp.width - 24, 28)
                                ui_draw_rect(screen, (24, 34, 38), connected_rect, border_radius=6)
