                    _tiles_per_row = max(1, pw // (260 + _tile_gap))
                    _tile_w = (pw - _tile_gap * (_tiles_per_row - 1)) // _tiles_per_row
                    _thumb_h = int(_tile_w * 9 / 16)   # 16:9 preview
                    _info_h  = 62                        # name(18) + meta(14) + gap + buttons(22) + padding
                    _tile_h  = _thumb_h + _info_h

                    _content_h = ((len(projects) + _tiles_per_row - 1) // _tiles_per_row) * (_tile_h + _tile_gap)
                    modal_max_scroll = max(0.0, _content_h - body_rect.height)
                    modal_scroll = max(0.0, min(modal_scroll, modal_max_scroll))

                    for _pi, (proj_name, mtime) in enumerate(projects):
                        _tc = _pi % _tiles_per_row
                        _tr = _pi // _tiles_per_row
                        _tx = px + _tc * (_tile_w + _tile_gap)
                        _ty = content_y + _tr * (_tile_h + _tile_gap) - modal_scroll

                        if _ty + _tile_h < content_y or _ty > body_rect.bottom:
                            _fake = pygame.Rect(0,0,0,0)
                            modal["_project_rows"].append((proj_name, _fake, _fake, _fake, _fake))
                            continue

                        tile = pygame.Rect(_tx, _ty, _tile_w, _tile_h)
                        _is_cur = proj_name == current_project_name
                        _tile_hov = tile.collidepoint(mouse_pos)
                        _tile_bg = (26,22,46) if _is_cur else (PANEL_BG_ALT if _tile_hov else (18,17,26))
