                        ui_draw_rect(screen, ACCENT if _is_cur else (ACCENT_DIM if _tile_hov else PANEL_BORDER),
                                         tile, width=2 if _is_cur else 1, border_radius=10)

                        # ── Thumbnail area (top, 16:9) ────────────────
                        # Clip thumb strictly within both body_rect and thumb_rect
                        _thumb_rect = pygame.Rect(_tx + 1, _ty + 1, _tile_w - 2, _thumb_h)
