                        _thumb_surf = load_project_thumbnail(proj_name)
                        if _thumb_surf and _thumb_clip.width > 0 and _thumb_clip.height > 0:
                            _ts_w, _ts_h = _thumb_surf.get_size()
                            _scale = max(_thumb_rect.width / max(1, _ts_w), _thumb_rect.height / max(1, _ts_h))
                            _sw = max(1, int(_ts_w * _scale)); _sh = max(1, int(_ts_h * _scale))
                            _scaled = ui_thumb(_thumb_surf, _sw, _sh)
                            _cx2 = (_sw - _thumb_rect.width) // 2
                            _cy2 = (_sh - _thumb_rect.height) // 2
