                        screen.blit(_nm, (_tx + 8, _name_y))

                        try: _fsize = os.path.getsize(get_project_path(proj_name))
                        except: _fsize = 0
                        _fsize_str = f"{_fsize//1024}KB" if _fsize < 1024*1024 else f"{_fsize//1048576}MB"
                        _dt_str = time.strftime("%b %d  %H:%M", time.localtime(mtime))
                        _meta = font_tiny.render(f"{_dt_str}  ·  {_fsize_str}", True, TEXT_FAINT)
                        screen.blit(_meta, (_tx + 8, _name_y + 18))

                        # Action buttons row
                        _btn_y2 = _info_y + _info_h - 26
                        _bw3 = (_tile_w - 36) // 3
                        _open_r  = pygame.Rect(_tx + 6,                _btn_y2, _bw3, 20)
                        _copy_r  = pygame.Rect(_open_r.right + 3,      _btn_y2, _bw3, 20)
                        _ren_r   = pygame.Rect(_copy_r.right + 3,      _btn_y2, _bw3, 20)
