                        modal["_spe_cards"] = []

                        # ----- shared live state for the composite preview -----
                        _snap_on = bool(modal.get("spe_snap", False))
                        _snap_source = modal.get("spe_snap_source", "bg")
                        _prog_val = float(modal.get("spe_prog", 0.75))
                        _spe_max_hp = max(1.0, float(modal.get("spe_test_max_hp", 100)))
                        _pv_hp = _prog_val * _spe_max_hp
                        _lc = int(modal.get("spe_left_cap", 12))
                        _rc = int(modal.get("spe_right_cap", 12))
                        _discrete_on = bool(modal.get("spe_discrete", False))

                        # defensive mirrors (cover modals opened before this build)
                        for _mk2, _dv2 in (("spe_fill_dir", _node.get("fill_direction", "")),
                                           ("spe_bg_path", _node.get("bg_path", "")),
                                           ("spe_frame_path", _node.get("frame_path", "")),
                                           ("spe_fill_path", _node.get("fill_path", "")),
                                           ("spe_bg_mode", _node.get("bg_mode", "auto")),
                                           ("spe_frame_mode", _node.get("frame_mode", "auto")),
                                           ("spe_fill_tex_mode", _node.get("fill_tex_mode", "auto")),
                                           ("spe_bg_off_x", int(_node.get("bg_off_x", 0) or 0)),
                                           ("spe_bg_off_y", int(_node.get("bg_off_y", 0) or 0)),
                                           ("spe_fill_off_x", int(_node.get("fill_off_x", 0) or 0)),
                                           ("spe_fill_off_y", int(_node.get("fill_off_y", 0) or 0)),
                                           ("spe_frame_off_x", int(_node.get("frame_off_x", 0) or 0)),
                                           ("spe_frame_off_y", int(_node.get("frame_off_y", 0) or 0)),
                                           ("spe_bg_lock", bool(_node.get("bg_lock", False))),
                                           ("spe_fill_lock", bool(_node.get("fill_lock", False))),
                                           ("spe_frame_lock", bool(_node.get("frame_lock", False))),
                                           ("spe_show_bg_ph", bool(_node.get("show_bg_placeholder", True))),
                                           ("spe_show_fill_ph", bool(_node.get("show_fill_placeholder", True))),
                                           ("spe_show_frame_outline_ph", bool(_node.get("show_frame_outline", True))),
                                           ("spe_tile_textures", bool(_node.get("tile_textures", True))),
                                           ("spe_pixel_perfect", bool(_node.get("pixel_perfect", True))),
                                           ("spe_fill_above", bool(_node.get("fill_above_frame", False))),
                                           ("spe_tint_on", bool(_node.get("fill_tint_enabled", False))),
                                           ("spe_tint_stops", copy.deepcopy(_node.get("fill_tint_stops") or [])),
                                           ("spe_bg_scale", float(_node.get("bg_scale", 1.0) or 1.0)),
                                           ("spe_fill_scale", float(_node.get("fill_scale", 1.0) or 1.0)),
                                           ("spe_frame_scale", float(_node.get("frame_scale", 1.0) or 1.0)),
                                           ("spe_text_on", bool(_node.get("show_text_value", False))),
                                           ("spe_text_format", str(_node.get("text_format", "current_max"))),
                                           ("spe_text_prefix", str(_node.get("text_prefix", ""))),
                                           ("spe_text_suffix", str(_node.get("text_suffix", ""))),
                                           ("spe_text_align", str(_node.get("text_align", "center"))),
                                           ("spe_text_size", int(_node.get("text_font_size", 12))),
                                           ("spe_text_off_x", int(_node.get("text_offset_x", 0))),
                                           ("spe_text_off_y", int(_node.get("text_offset_y", 0))),
                                           ("spe_text_color", list(_node.get("text_color", [255, 255, 255]))[:3]),
                                           ("spe_text_outline", bool(_node.get("text_outline", True))),
                                           ("spe_text_outline_color", list(_node.get("text_outline_color", [0, 0, 0]))[:3]),
                                           ("spe_text_outline_thickness", int(_node.get("text_outline_thickness", 1))),
                                           ("spe_text_font", str(_node.get("text_font_name", _node.get("font_name", "segoeui")))),
                                           ("spe_text_stops_on", bool(_node.get("text_color_stops_enabled", False))),
                                           ("spe_text_stops", copy.deepcopy(_node.get("text_color_stops") or [])),
                                           ("spe_text_ostops_on", bool(_node.get("text_outline_stops_enabled", False))),
                                           ("spe_text_ostops", copy.deepcopy(_node.get("text_outline_stops") or []))):
                            modal.setdefault(_mk2, _dv2)

                        _bg_l = load_sprite_asset(modal.get("spe_bg_l", "")) if modal.get("spe_bg_l") else None
                        _bg_m = load_sprite_asset(modal.get("spe_bg_m", "")) if modal.get("spe_bg_m") else None
                        _bg_r = load_sprite_asset(modal.get("spe_bg_r", "")) if modal.get("spe_bg_r") else None
                        _f_m  = load_sprite_asset(modal.get("spe_fill_m", "")) if modal.get("spe_fill_m") else None
                        if _bg_l: _bg_l = pygame.transform.flip(_bg_l, bool(modal.get("spe_bg_l_fh")), bool(modal.get("spe_bg_l_fv")))
                        if _bg_m: _bg_m = pygame.transform.flip(_bg_m, bool(modal.get("spe_bg_m_fh")), bool(modal.get("spe_bg_m_fv")))
                        if _bg_r: _bg_r = pygame.transform.flip(_bg_r, bool(modal.get("spe_bg_r_fh")), bool(modal.get("spe_bg_r_fv")))
                        if _f_m:  _f_m  = pygame.transform.flip(_f_m,  bool(modal.get("spe_fill_m_fh")), bool(modal.get("spe_fill_m_fv")))
                        # Fill Tint by % — live preview follows the Smart Preview HP
                        # slider through the exact same evaluator the arena uses.
                        _pv_tint = _bar_fill_tint_params(
                            {"fill_tint_enabled": bool(modal.get("spe_tint_on", False)),
                             "fill_tint_stops": modal.get("spe_tint_stops") or []},
                            float(modal.get("spe_prog", 0.75)))
                        if _pv_tint is not None and _f_m is not None:
                            _f_m = _bar_tint_surface(_f_m, *_pv_tint)

                        _pre_w = int(modal.setdefault("spe_w", 300))
                        _snap_tile_img = _f_m if _snap_source == "hp" else _bg_m
                        _active_w = _pre_w
                        if _snap_on and _snap_tile_img:
                            _tile_w = max(1, _snap_tile_img.get_width())
                            _active_w = _lc + _rc + max(0, int(round((_pre_w - _lc - _rc) / float(_tile_w))) * _tile_w)

                        def _scale_layer_local(img, size):
                            return pygame.transform.scale(img, size) if bool(modal.get("spe_pixel_perfect", True)) else pygame.transform.smoothscale(img, size)

                        def _draw_3_slice_preview(target_surf, dest_rect, left_c, right_c, tex_left, tex_mid, tex_right, mode=None):
                            # mode honors the same vocabulary as the arena renderer
                            # ("tile"/"stretch"); None derives it from the Tile
                            # Textures flag. Previously this ALWAYS tiled, so the
                            # Tile/Stretch chips visibly did nothing in the preview.
                            if mode is None:
                                mode = "tile" if bool(modal.get("spe_tile_textures", True)) else "stretch"
                            x, y, w, h = dest_rect.x, dest_rect.y, dest_rect.width, dest_rect.height
                            if left_c + right_c > w:
                                ratio = w / float(left_c + right_c)
                                left_c = int(left_c * ratio)
                                right_c = int(right_c * ratio)
                            if left_c > 0 and tex_left:
                                target_surf.blit(_scale_layer_local(tex_left, (left_c, h)), (x, y))
                            if right_c > 0 and tex_right:
                                target_surf.blit(_scale_layer_local(tex_right, (right_c, h)), (x + w - right_c, y))
                            mid_w = w - left_c - right_c
                            if mid_w > 0 and tex_mid:
                                mid_x = x + left_c
                                if str(mode).lower() == "stretch":
                                    target_surf.blit(_scale_layer_local(tex_mid, (mid_w, h)), (mid_x, y))
                                    return
                                # Aspect-correct the tile to the bar height - identical math
                                # to the in-game 3-slice renderer, so the texture is never
                                # squashed and preview == arena pixel for pixel.
                                tile_w = max(1, int(tex_mid.get_width() * (h / float(max(1, tex_mid.get_height())))))
                                tile_scaled = _scale_layer_local(tex_mid, (tile_w, h))
                                for _ti in range(mid_w // tile_w):
                                    target_surf.blit(tile_scaled, (mid_x + _ti * tile_w, y))
                                _rem = mid_w % tile_w
                                if _rem > 0:
                                    target_surf.blit(tile_scaled.subsurface(pygame.Rect(0, 0, _rem, h)), (mid_x + (mid_w // tile_w) * tile_w, y))

                        # ===== RIGHT COLUMN: pinned live preview =====
                        def _rby(_o):
                            return _body_y + _o

                        _roff = 0.0
                        _pv_zoom = max(0.25, min(8.0, float(modal.get("spe_pv_zoom", 1.0))))
                        _pv_pan_x = float(modal.get("spe_pv_pan_x", 0.0))
                        _pv_pan_y = float(modal.get("spe_pv_pan_y", 0.0))
                        draw_section_label("LIVE PREVIEW - PINNED", (_rp_x, _rby(_roff)))
                        _zm_btn_w = 26
                        _zm_in_r = pygame.Rect(_rp_x + _rp_w - _zm_btn_w, _rby(_roff - 2), _zm_btn_w, 20)
                        _zm_rst_w = 118
                        _zm_rst_r = pygame.Rect(_zm_in_r.x - _zm_rst_w - 4, _rby(_roff - 2), _zm_rst_w, 20)
                        _zm_out_r = pygame.Rect(_zm_rst_r.x - _zm_btn_w - 4, _rby(_roff - 2), _zm_btn_w, 20)
                        for _zr, _zlbl, _zid in ((_zm_out_r, "-", "out"), (_zm_rst_r, f"{int(_pv_zoom*100)}% (Reset)", "reset"), (_zm_in_r, "+", "in")):
                            _zhov = _zr.collidepoint(mouse_pos)
                            ui_draw_rect(screen, ACCENT if _zhov else FIELD_FOCUS, _zr, border_radius=4)
                            ui_draw_rect(screen, PANEL_BORDER, _zr, width=1, border_radius=4)
                            _ztxt = font_tiny.render(_zlbl, True, (10, 10, 14) if _zhov else (255, 255, 255))
                            screen.blit(_ztxt, (_zr.centerx - _ztxt.get_width()//2, _zr.centery - _ztxt.get_height()//2))
                        modal["_spe_zoom_in_rect"] = _zm_in_r
                        modal["_spe_zoom_out_rect"] = _zm_out_r
                        modal["_spe_zoom_reset_rect"] = _zm_rst_r
                        _roff += 22

                        # preview frame sized so every chip row below fits without overlap
                        _chip_rows_h = 6 * 26 + 18
                        _stats_h = 22
                        _pv_h = max(140, min(320, _band_h - 22 - _stats_h - _chip_rows_h))
                        _pv_rect = pygame.Rect(_rp_x, _rby(_roff), _rp_w, _pv_h)
                        modal["_spe_pv_rect"] = _pv_rect
                        ui_draw_rect(screen, (14, 14, 18), _pv_rect, border_radius=10)
                        _ck = 10
                        for _cy2 in range(_pv_rect.y, _pv_rect.bottom, _ck):
                            for _cx2 in range(_pv_rect.x, _pv_rect.right, _ck):
                                if ((_cx2 - _pv_rect.x)//_ck + (_cy2 - _pv_rect.y)//_ck) % 2 == 0:
                                    _cr2 = pygame.Rect(_cx2, _cy2, _ck, _ck).clip(_pv_rect)
                                    if _cr2.width > 0 and _cr2.height > 0:
                                        ui_draw_rect(screen, (22, 20, 28), _cr2)
                        ui_draw_rect(screen, PANEL_BORDER, _pv_rect, width=1, border_radius=10)
                        _pv_clip = screen.get_clip()
                        screen.set_clip(_pv_rect)

                        _scaled_bar_w = max(4, int(round(_active_w * _pv_zoom)))
                        _bar_h = max(4, int(modal.get("spe_h", 32)))
                        _scaled_bar_h = max(4, int(round(_bar_h * _pv_zoom)))
                        _draw_x = int(round(_pv_rect.centerx + _pv_pan_x - _scaled_bar_w // 2))
                        _draw_y = int(round(_pv_rect.centery + _pv_pan_y - _scaled_bar_h // 2))
                        _dest = pygame.Rect(_draw_x, _draw_y, _scaled_bar_w, _scaled_bar_h)
                        _lc_z = int(round(_lc * _pv_zoom))
                        _rc_z = int(round(_rc * _pv_zoom))
                        _bg_oxz = int(round(float(modal.get("spe_bg_off_x", 0)) * _pv_zoom))
                        _bg_oyz = int(round(float(modal.get("spe_bg_off_y", 0)) * _pv_zoom))
                        _fill_oxz = int(round(float(modal.get("spe_fill_off_x", 0)) * _pv_zoom))
                        _fill_oyz = int(round(float(modal.get("spe_fill_off_y", 0)) * _pv_zoom))
                        _frm_oxz = int(round(float(modal.get("spe_frame_off_x", 0)) * _pv_zoom))
                        _frm_oyz = int(round(float(modal.get("spe_frame_off_y", 0)) * _pv_zoom))
                        _layer_rects = {}

                        # ---------- background layer (offset + mode + placeholder) ----------
                        def _pv_scaled_rect(_r5, _s5):
                            try: _s5 = float(_s5)
                            except (TypeError, ValueError): _s5 = 1.0
                            if abs(_s5 - 1.0) < 0.001: return _r5
                            _nw5 = max(1, int(round(_r5.width * _s5)))
                            _nh5 = max(1, int(round(_r5.height * _s5)))
                            return pygame.Rect(_r5.centerx - _nw5 // 2, _r5.centery - _nh5 // 2, _nw5, _nh5)
                        _dest_bg = _pv_scaled_rect(_dest.move(_bg_oxz, _bg_oyz), modal.get("spe_bg_scale", 1.0))
                        _layer_rects["bg"] = _dest_bg
                        _bg_single_path = str(modal.get("spe_bg_path", "") or "")
                        _bg_single_img = load_sprite_asset(_bg_single_path) if _bg_single_path else None
                        if _bg_l or _bg_m or _bg_r:
                            _draw_3_slice_preview(screen, _dest_bg, _lc_z, _rc_z, _bg_l, _bg_m, _bg_r)
                        elif _bg_single_img:
                            _bgm_pv = str(modal.get("spe_bg_mode", "auto")).lower()
                            if _bgm_pv == "native":
                                _nw = max(1, int(round(_bg_single_img.get_width() * _pv_zoom)))
                                _nh = max(1, int(round(_bg_single_img.get_height() * _pv_zoom)))
                                _nimg = _scale_layer_local(_bg_single_img, (_nw, _nh))
                                _nx2 = _dest_bg.centerx - _nw // 2
                                _ny2 = _dest_bg.centery - _nh // 2
                                screen.blit(_nimg, (_nx2, _ny2))
                                _layer_rects["bg"] = pygame.Rect(_nx2, _ny2, _nw, _nh)
                            elif _bgm_pv == "stretch" or (_bgm_pv in ("auto", "", "none") and not bool(modal.get("spe_tile_textures", True))):
                                screen.blit(_scale_layer_local(_bg_single_img, (max(1, _dest_bg.width), max(1, _dest_bg.height))), (_dest_bg.x, _dest_bg.y))
                            else:
                                _draw_3_slice_preview(screen, _dest_bg, 0, 0, None, _bg_single_img, None, mode="tile")
                        elif bool(modal.get("spe_show_bg_ph", True)):
                            ui_draw_rect(screen, (30, 30, 40), _dest_bg, border_radius=4)

                        _aes_list = modal.get("spe_aesthetic_sprites", [])
                        _sel_aes_idx = modal.get("spe_selected_aesthetic")
                        _spe_aes_rects = {}
                        modal["_spe_aes_rects"] = _spe_aes_rects

                        def _draw_aes_preview_pass(above_flag):
                            for _ai, _aitem in enumerate(_aes_list):
                                if not isinstance(_aitem, dict):
                                    continue
                                if bool(_aitem.get("above_frame", True)) != above_flag:
                                    continue
                                # HP reactions: visibility rule, blink rule, state swap.
                                _spe_aes_norm(_aitem)
                                _vis, _alpha = _spe_aes_react(_aitem, _prog_val, _pv_hp, _spe_max_hp, time.time())
                                if not _vis:
                                    # keep the selected sprite as a ghost so it stays
                                    # clickable while its rules hide it at this HP
                                    if _ai != _sel_aes_idx:
                                        continue
                                    _alpha = 40
                                _apath = _spe_aes_state_path(_aitem, _prog_val)
                                if not _apath:
                                    continue
                                _aimg = load_sprite_asset(_apath)
                                if not _aimg:
                                    continue
                                _aimg = pygame.transform.flip(_aimg, bool(_aitem.get("flip_h", False)), bool(_aitem.get("flip_v", False)))
                                _asc = float(_aitem.get("scale", 1.0) or 1.0)
                                _combined_sc = _asc * _pv_zoom
                                if abs(_combined_sc - 1.0) > 0.001:
                                    _new_w = max(1, int(round(_aimg.get_width() * _combined_sc)))
                                    _new_h = max(1, int(round(_aimg.get_height() * _combined_sc)))
                                    _aimg = _scale_layer_local(_aimg, (_new_w, _new_h))
                                if _alpha < 255:
                                    _aimg = _aimg.copy()
                                    _aimg.set_alpha(max(0, min(255, int(_alpha))))
                                _aanchor = str(_aitem.get("anchor", "left")).lower()
                                _ax_z = float(_aitem.get("x", 0)) * _pv_zoom
                                _ay_z = float(_aitem.get("y", 0)) * _pv_zoom
                                if _aanchor == "right":
                                    _as_scr_x = int(round(_draw_x + _scaled_bar_w + _ax_z))
                                elif _aanchor == "center":
                                    _as_scr_x = int(round(_draw_x + _scaled_bar_w // 2 + _ax_z))
                                else:  # "left"
                                    _as_scr_x = int(round(_draw_x + _ax_z))
                                _as_scr_y = int(round(_draw_y + _ay_z))
                                screen.blit(_aimg, (_as_scr_x, _as_scr_y))
                                _sr = pygame.Rect(_as_scr_x, _as_scr_y, _aimg.get_width(), _aimg.get_height())
                                _spe_aes_rects[_ai] = {"rect": _sr, "anchor": _aanchor, "img_w": _aimg.get_width(), "img_h": _aimg.get_height()}

                        _draw_aes_preview_pass(False)

                        # ---------- fill + frame layer rects ----------
                        _mt = int(round(modal.get("spe_margin_t", 2) * _pv_zoom))
                        _mb = int(round(modal.get("spe_margin_b", 2) * _pv_zoom))
                        _ml = int(round(modal.get("spe_margin_l", 4) * _pv_zoom))
                        _mr = int(round(modal.get("spe_margin_r", 4) * _pv_zoom))
                        _pv_dir = str(modal.get("spe_fill_dir", "") or "").lower()
                        if _pv_dir not in ("left_to_right", "right_to_left", "bottom_to_top", "top_to_bottom"):
                            _pv_dir = "left_to_right"
                        _pv_axis_v = _pv_dir in ("bottom_to_top", "top_to_bottom")
                        _pv_rev = _pv_dir in ("right_to_left", "top_to_bottom")
                        _frgn_w = _scaled_bar_w - _lc_z - _rc_z - _ml - _mr
                        _frgn_h = _scaled_bar_h - _mt - _mb
                        _frgn = _pv_scaled_rect(pygame.Rect(_draw_x + _lc_z + _ml + _fill_oxz, _draw_y + _mt + _fill_oyz, max(0, _frgn_w), max(0, _frgn_h)), modal.get("spe_fill_scale", 1.0))
                        _frgn_w, _frgn_h = _frgn.width, _frgn.height
                        _layer_rects["fill"] = _frgn
                        _dest_fr = _pv_scaled_rect(_dest.move(_frm_oxz, _frm_oyz), modal.get("spe_frame_scale", 1.0))
                        _layer_rects["frame"] = _dest_fr
                        _single_fill_path = str(modal.get("spe_fill_path", "") or "")
                        _single_fill_img = load_sprite_asset(_single_fill_path) if _single_fill_path else None
                        if _single_fill_img is not None and _pv_tint is not None:
                            _single_fill_img = _bar_tint_surface(_single_fill_img, *_pv_tint)
                        _frame_path_pv = str(modal.get("spe_frame_path", "") or "")
                        _frame_img_pv = load_sprite_asset(_frame_path_pv) if _frame_path_pv else None

                        def _pv_draw_fill():
                            if _frgn_w <= 0 or _frgn_h <= 0 or _prog_val <= 0.001:
                                return
                            if _f_m:
                                if _discrete_on:
                                    if not _pv_axis_v:
                                        _th2 = max(1, _frgn_h)
                                        _tw2 = max(1, int(round(_f_m.get_width() * (_th2 / float(max(1, _f_m.get_height()))))))
                                        _tile_scaled = _scale_layer_local(_f_m, (_tw2, _th2))
                                        _max_tiles = _frgn_w // _tw2
                                        _active_tiles = int(round(_prog_val * _max_tiles)) if _max_tiles > 0 else 0
                                        _start_x = (_frgn.x + _frgn_w - _active_tiles * _tw2) if _pv_rev else _frgn.x
                                        for _ti2 in range(_active_tiles):
                                            screen.blit(_tile_scaled, (_start_x + _ti2 * _tw2, _frgn.y))
                                    else:
                                        _tw2 = max(1, _frgn_w)
                                        _th2 = max(1, int(round(_f_m.get_height() * (_tw2 / float(max(1, _f_m.get_width()))))))
                                        _tile_scaled = _scale_layer_local(_f_m, (_tw2, _th2))
                                        _max_tiles = _frgn_h // _th2
                                        _active_tiles = int(round(_prog_val * _max_tiles)) if _max_tiles > 0 else 0
                                        _start_y = _frgn.y if _pv_rev else (_frgn.y + _frgn_h - _active_tiles * _th2)
                                        for _ti2 in range(_active_tiles):
                                            screen.blit(_tile_scaled, (_frgn.x, _start_y + _ti2 * _th2))
                                else:
                                    _fill_temp = pygame.Surface((max(1, _frgn_w), max(1, _frgn_h)), pygame.SRCALPHA)
                                    _draw_3_slice_preview(_fill_temp, pygame.Rect(0, 0, max(1, _frgn_w), max(1, _frgn_h)), 0, 0, None, _f_m, None)
                                    if not _pv_axis_v:
                                        _fw = int(round(_prog_val * _frgn_w))
                                        if _fw > 0:
                                            if _pv_rev:
                                                screen.blit(_fill_temp, (_frgn.x + _frgn_w - _fw, _frgn.y), area=pygame.Rect(_frgn_w - _fw, 0, _fw, _frgn_h))
                                            else:
                                                screen.blit(_fill_temp, (_frgn.x, _frgn.y), area=pygame.Rect(0, 0, _fw, _frgn_h))
                                    else:
                                        _fh2 = int(round(_prog_val * _frgn_h))
                                        if _fh2 > 0:
                                            if _pv_rev:
                                                screen.blit(_fill_temp, (_frgn.x, _frgn.y), area=pygame.Rect(0, 0, _frgn_w, _fh2))
                                            else:
                                                screen.blit(_fill_temp, (_frgn.x, _frgn.y + _frgn_h - _fh2), area=pygame.Rect(0, _frgn_h - _fh2, _frgn_w, _fh2))
                            elif _single_fill_img:
                                if str(modal.get("spe_fill_tex_mode", "auto")).lower() == "native":
                                    _fw_n = max(1, int(round(_single_fill_img.get_width() * _pv_zoom)))
                                    _fh_n = max(1, int(round(_single_fill_img.get_height() * _pv_zoom)))
                                    _nfill = _scale_layer_local(_single_fill_img, (_fw_n, _fh_n))
                                    if not _pv_axis_v:
                                        _wvis = int(round(_prog_val * _fw_n))
                                        if _wvis > 0:
                                            if _pv_rev:
                                                screen.blit(_nfill, (_frgn.centerx + _fw_n // 2 - _wvis, _frgn.centery - _fh_n // 2), area=pygame.Rect(_fw_n - _wvis, 0, _wvis, _fh_n))
                                            else:
                                                screen.blit(_nfill, (_frgn.centerx - _fw_n // 2, _frgn.centery - _fh_n // 2), area=pygame.Rect(0, 0, _wvis, _fh_n))
                                    else:
                                        _hvis = int(round(_prog_val * _fh_n))
                                        if _hvis > 0:
                                            if _pv_rev:
                                                screen.blit(_nfill, (_frgn.centerx - _fw_n // 2, _frgn.centery - _fh_n // 2), area=pygame.Rect(0, 0, _fw_n, _hvis))
                                            else:
                                                screen.blit(_nfill, (_frgn.centerx - _fw_n // 2, _frgn.centery + _fh_n // 2 - _hvis), area=pygame.Rect(0, _fh_n - _hvis, _fw_n, _hvis))
                                else:
                                    _fill_scaled = _scale_layer_local(_single_fill_img, (max(1, _frgn_w), max(1, _frgn_h)))
                                    if not _pv_axis_v:
                                        _fw = int(round(_prog_val * _frgn_w))
                                        if _fw > 0:
                                            if _pv_rev:
                                                screen.blit(_fill_scaled, (_frgn.x + _frgn_w - _fw, _frgn.y), area=pygame.Rect(_frgn_w - _fw, 0, _fw, _frgn_h))
                                            else:
                                                screen.blit(_fill_scaled, (_frgn.x, _frgn.y), area=pygame.Rect(0, 0, _fw, _frgn_h))
                                    else:
                                        _fh2 = int(round(_prog_val * _frgn_h))
                                        if _fh2 > 0:
                                            if _pv_rev:
                                                screen.blit(_fill_scaled, (_frgn.x, _frgn.y), area=pygame.Rect(0, 0, _frgn_w, _fh2))
                                            else:
                                                screen.blit(_fill_scaled, (_frgn.x, _frgn.y + _frgn_h - _fh2), area=pygame.Rect(0, _frgn_h - _fh2, _frgn_w, _fh2))
                            elif bool(modal.get("spe_show_fill_ph", True)):
                                _pv_ph_col = (78, 210, 138)
                                if _pv_tint is not None:
                                    _tc4, _ts4, _tb4 = _pv_tint
                                    _pv_ph_col = _blend_rgb(_pv_ph_col, _tc4, _ts4)
                                    if _tb4 > 0:
                                        _pv_ph_col = _blend_rgb(_pv_ph_col, (255, 255, 255), _tb4)
                                    elif _tb4 < 0:
                                        _pv_ph_col = _blend_rgb(_pv_ph_col, (0, 0, 0), -_tb4)
                                if not _pv_axis_v:
                                    _fw = int(round(_prog_val * _frgn_w))
                                    if _fw > 0:
                                        _dx2 = (_frgn.x + _frgn_w - _fw) if _pv_rev else _frgn.x
                                        ui_draw_rect(screen, _pv_ph_col, pygame.Rect(_dx2, _frgn.y, _fw, _frgn_h), border_radius=max(1, int(round(4 * _pv_zoom))))
                                else:
                                    _fh2 = int(round(_prog_val * _frgn_h))
                                    if _fh2 > 0:
                                        _dy2 = _frgn.y if _pv_rev else (_frgn.y + _frgn_h - _fh2)
                                        ui_draw_rect(screen, _pv_ph_col, pygame.Rect(_frgn.x, _dy2, _frgn_w, _fh2), border_radius=max(1, int(round(4 * _pv_zoom))))

                        def _pv_draw_frame():
                            if _frame_img_pv:
                                _fmm_pv = str(modal.get("spe_frame_mode", "auto")).lower()
                                if _fmm_pv == "native":
                                    _nw3 = max(1, int(round(_frame_img_pv.get_width() * _pv_zoom)))
                                    _nh3 = max(1, int(round(_frame_img_pv.get_height() * _pv_zoom)))
                                    _nimg3 = _scale_layer_local(_frame_img_pv, (_nw3, _nh3))
                                    _nx3 = _dest_fr.centerx - _nw3 // 2
                                    _ny3 = _dest_fr.centery - _nh3 // 2
                                    screen.blit(_nimg3, (_nx3, _ny3))
                                    _layer_rects["frame"] = pygame.Rect(_nx3, _ny3, _nw3, _nh3)
                                elif _fmm_pv == "stretch" or (_fmm_pv in ("auto", "", "none") and not bool(modal.get("spe_tile_textures", True))):
                                    screen.blit(_scale_layer_local(_frame_img_pv, (max(1, _dest_fr.width), max(1, _dest_fr.height))), (_dest_fr.x, _dest_fr.y))
                                else:
                                    _draw_3_slice_preview(screen, _dest_fr, 0, 0, None, _frame_img_pv, None)
                            elif bool(modal.get("spe_show_frame_outline_ph", True)) and not (_bg_l or _bg_m or _bg_r or _bg_single_img):
                                ui_draw_rect(screen, (50, 50, 60), _dest_fr, width=1, border_radius=max(1, int(round(4 * _pv_zoom))))

                        if bool(modal.get("spe_fill_above", False)):
                            _pv_draw_frame()
                            _pv_draw_fill()
                        else:
                            _pv_draw_fill()
                            _pv_draw_frame()
                        _draw_aes_preview_pass(True)

                        # ---------- text value overlay (draggable layer) ----------
                        if bool(modal.get("spe_text_on", False)):
                            _pvt_fmt = str(modal.get("spe_text_format", "current_max")).lower()
                            if _pvt_fmt == "current_only":
                                _pvt_txt = f"{int(round(_pv_hp))}"
                            elif _pvt_fmt == "percentage":
                                _pvt_txt = f"{int(_prog_val * 100)}%"
                            else:
                                _pvt_txt = f"{int(round(_pv_hp))} / {int(_spe_max_hp)}"
                            _pvt_txt = f"{modal.get('spe_text_prefix','')}{_pvt_txt}{modal.get('spe_text_suffix','')}"
                            _pvt_col = tuple(modal.get("spe_text_color", [255, 255, 255])[:3])
                            # color-by-% stops (same shared evaluator as the arena)
                            if bool(modal.get("spe_text_stops_on", False)) and modal.get("spe_text_stops"):
                                _pvt_col = _bar_text_stops_color(modal["spe_text_stops"], _prog_val, _pvt_col)
                            _pvt_ocol = tuple(modal.get("spe_text_outline_color", [0, 0, 0])[:3])
                            if bool(modal.get("spe_text_ostops_on", False)) and modal.get("spe_text_ostops"):
                                _pvt_ocol = _bar_text_stops_color(modal["spe_text_ostops"], _prog_val, _pvt_ocol)
                            _pvt_sz = max(8, int(round(int(modal.get("spe_text_size", 12)) * _pv_zoom)))
                            _pvt_font_name = str(modal.get("spe_text_font", "segoeui")).strip() or "segoeui"
                            if not _pvt_font_name.lower().endswith((".ttf", ".otf")):
                                _pvt_font_name = _pvt_font_name.lower()
                            try:
                                _pvt_font = get_dmg_font(_pvt_sz, _pvt_font_name, bold=True)
                            except Exception:
                                _pvt_font = font_tiny
                            _pvt_ot = max(0, min(8, int(modal.get("spe_text_outline_thickness", 1)))) if bool(modal.get("spe_text_outline", True)) else 0
                            _pvt_surf = _en_cached_text_render(_pvt_font, _pvt_txt, _pvt_col, _pvt_ocol, _pvt_ot)
                            _pvt_w, _pvt_h = _pvt_surf.get_size()
                            _pvt_align = str(modal.get("spe_text_align", "center")).lower()
                            _pvt_ox = int(round(int(modal.get("spe_text_off_x", 0)) * _pv_zoom))
                            _pvt_oy = int(round(int(modal.get("spe_text_off_y", 0)) * _pv_zoom))
                            if _pvt_align == "top":
                                _pvt_x = _draw_x + (_scaled_bar_w - _pvt_w) // 2 + _pvt_ox
                                _pvt_y = _draw_y - _pvt_h - 2 + _pvt_oy
                            elif _pvt_align == "bottom":
                                _pvt_x = _draw_x + (_scaled_bar_w - _pvt_w) // 2 + _pvt_ox
                                _pvt_y = _draw_y + _scaled_bar_h + 2 + _pvt_oy
                            elif _pvt_align == "left":
                                _pvt_x = _draw_x + 6 + _pvt_ox
                                _pvt_y = _draw_y + (_scaled_bar_h - _pvt_h) // 2 + _pvt_oy
                            elif _pvt_align == "right":
                                _pvt_x = _draw_x + _scaled_bar_w - _pvt_w - 6 + _pvt_ox
                                _pvt_y = _draw_y + (_scaled_bar_h - _pvt_h) // 2 + _pvt_oy
                            else:
                                _pvt_x = _draw_x + (_scaled_bar_w - _pvt_w) // 2 + _pvt_ox
                                _pvt_y = _draw_y + (_scaled_bar_h - _pvt_h) // 2 + _pvt_oy
                            screen.blit(_pvt_surf, (_pvt_x, _pvt_y))
                            _layer_rects["text"] = pygame.Rect(_pvt_x, _pvt_y, _pvt_w, _pvt_h)

                        # ===== selection model: layers + aesthetic sprites =====
                        modal["_spe_layer_rects"] = _layer_rects
                        _pv_items = []
                        if "text" in _layer_rects:
                            _pv_items.append(("layer", "text", _layer_rects["text"], "TEXT"))
                        for _ai2 in sorted([k for k in _spe_aes_rects.keys() if k < len(_aes_list)], reverse=True):
                            if bool(_aes_list[_ai2].get("above_frame", True)):
                                _pv_items.append(("aes", _ai2, _spe_aes_rects[_ai2]["rect"], f"Sprite #{_ai2+1}"))
                        if bool(modal.get("spe_fill_above", False)):
                            _pv_items.append(("layer", "fill", _layer_rects["fill"], "HP FILL"))
                            _pv_items.append(("layer", "frame", _layer_rects["frame"], "FRAME"))
                        else:
                            _pv_items.append(("layer", "frame", _layer_rects["frame"], "FRAME"))
                            _pv_items.append(("layer", "fill", _layer_rects["fill"], "HP FILL"))
                        _pv_items.append(("layer", "bg", _layer_rects["bg"], "BACKGROUND"))
                        for _ai2 in sorted([k for k in _spe_aes_rects.keys() if k < len(_aes_list)], reverse=True):
                            if not bool(_aes_list[_ai2].get("above_frame", True)):
                                _pv_items.append(("aes", _ai2, _spe_aes_rects[_ai2]["rect"], f"Sprite #{_ai2+1}"))
                        modal["_spe_preview_items"] = _pv_items

                        # ===== gizmos (shared widget: layer or aesthetic) =====
                        modal["_spe_aes_gizmos"] = {}

                        def _spe_draw_sel_gizmo(_srect, _label, _is_locked):
                            ui_draw_rect(screen, (0, 235, 255), _srect.inflate(6, 6), width=1, border_radius=4)
                            _lab = font_tiny.render(_label, True, (255, 255, 255))
                            _lab_bg = pygame.Rect(_srect.x, _srect.y - 18, _lab.get_width() + 8, 15)
                            ui_draw_rect(screen, (24, 24, 32), _lab_bg, border_radius=3)
                            ui_draw_rect(screen, (0, 235, 255), _lab_bg, width=1, border_radius=3)
                            screen.blit(_lab, (_lab_bg.x + 4, _lab_bg.y + 1))
                            if _is_locked:
                                _lk_r = pygame.Rect(0, 0, 22, 22)
                                _lk_r.center = _srect.center
                                ui_draw_rect(screen, GOLD, _lk_r, border_radius=5)
                                ui_draw_rect(screen, PANEL_BG_ALT, _lk_r, width=1, border_radius=5)
                                _lk_t = font_tiny.render("\U0001f512", True, (10, 10, 14))
                                screen.blit(_lk_t, (_lk_r.centerx - _lk_t.get_width() // 2, _lk_r.centery - _lk_t.get_height() // 2))
                                _lk_lbl = font_tiny.render("LOCKED", True, GOLD)
                                screen.blit(_lk_lbl, (_srect.centerx - _lk_lbl.get_width() // 2, _srect.bottom + 4))
                                modal["_spe_aes_gizmos"] = {"center": None, "x": None, "y": None, "body": _srect}
                            else:
                                _gz_center = pygame.Rect(0, 0, 14, 14)
                                _gz_center.center = _srect.center
                                ui_draw_rect(screen, (255, 215, 0), _gz_center, border_radius=3)
                                ui_draw_rect(screen, PANEL_BG_ALT, _gz_center, width=1, border_radius=3)
                                _gz_x = pygame.Rect(_srect.right + 6, _srect.centery - 7, 18, 14)
                                ui_draw_rect(screen, (255, 70, 70), _gz_x, border_radius=3)
                                ui_draw_rect(screen, PANEL_BG_ALT, _gz_x, width=1, border_radius=3)
                                _xtxt = font_tiny.render("X", True, (255, 255, 255))
                                screen.blit(_xtxt, (_gz_x.centerx - _xtxt.get_width()//2, _gz_x.centery - _xtxt.get_height()//2))
                                _gz_y = pygame.Rect(_srect.centerx - 7, _srect.top - 22, 14, 18)
                                ui_draw_rect(screen, (70, 225, 70), _gz_y, border_radius=3)
                                ui_draw_rect(screen, PANEL_BG_ALT, _gz_y, width=1, border_radius=3)
                                _ytxt = font_tiny.render("Y", True, PANEL_BG_ALT)
                                screen.blit(_ytxt, (_gz_y.centerx - _ytxt.get_width()//2, _gz_y.centery - _ytxt.get_height()//2))
                                modal["_spe_aes_gizmos"] = {"center": _gz_center, "x": _gz_x, "y": _gz_y, "body": _srect}

                        _sel_layer = modal.get("spe_selected_layer")
                        if _sel_layer in ("bg", "fill", "frame", "text") and _sel_layer in _layer_rects:
                            _lay_lbl = {"bg": "BACKGROUND", "fill": "HP FILL", "frame": "FRAME", "text": "TEXT"}[_sel_layer]
                            _spe_draw_sel_gizmo(_layer_rects[_sel_layer], _lay_lbl, bool(modal.get(f"spe_{_sel_layer}_lock", False)))
                        elif _sel_aes_idx is not None and _sel_aes_idx in _spe_aes_rects:
                            _sel_info = _spe_aes_rects[_sel_aes_idx]
                            _srect = _sel_info["rect"]
                            _sanchor = _sel_info["anchor"]
                            _bar_edge_x = _draw_x if _sanchor == "left" else (_draw_x + _scaled_bar_w if _sanchor == "right" else _draw_x + _scaled_bar_w // 2)
                            _line_col = (0, 235, 255) if _sanchor == "left" else ((255, 180, 50) if _sanchor == "right" else (180, 100, 255))
                            pygame.draw.line(screen, _line_col, (_bar_edge_x, _srect.centery), (_srect.centerx, _srect.centery), 1)
                            pygame.draw.circle(screen, _line_col, (_bar_edge_x, _srect.centery), 3)
                            _is_locked = False
                            try:
                                _is_locked = str(_aes_list[_sel_aes_idx].get("lock", "auto")) != "auto"
                            except Exception:
                                pass
                            _spe_draw_sel_gizmo(_srect, f"ANCHOR: {_sanchor.upper()}", _is_locked)

                        screen.set_clip(_pv_clip)
                        _roff += _pv_h + 6

                        # ---------- stats row ----------
                        _dupc = ((_active_w - _lc - _rc) // _bg_m.get_width()) if _bg_m else 0
                        _stat_txt = f"W:{_active_w}px H:{_bar_h}px Fill:{int(_prog_val*100)}% HP:{int(round(_pv_hp))}/{int(_spe_max_hp)} Caps:{_lc}/{_rc} Zoom:{int(_pv_zoom*100)}%"
                        screen.blit(font_tiny.render(truncate_text_to_width(font_tiny, _stat_txt, _rp_w), True, GOLD), (_rp_x + 2, _rby(_roff)))
                        _roff += _stats_h

                        # ---------- control chips (fixed rail) ----------
                        def _spe_chip(_r, _text, _on, _act, _val=None, _enabled=True):
                            _hov = _r.collidepoint(mouse_pos) and _enabled
                            ui_draw_rect(screen, ACCENT if _on else (FIELD_FOCUS if _hov else FIELD_BG), _r, border_radius=5)
                            ui_draw_rect(screen, ACCENT if _on else PANEL_BORDER, _r, width=1, border_radius=5)
                            _tc = (10, 10, 14) if _on else (TEXT_MAIN if _enabled else TEXT_FAINT)
                            _t = font_tiny.render(truncate_text_to_width(font_tiny, _text, max(10, _r.width - 8)), True, _tc)
                            screen.blit(_t, (_r.centerx - _t.get_width()//2, _r.centery - _t.get_height()//2))
                            modal["_spe_ctrl_chips"].append((_r, _act, _val))

                        _row_h = 22
                        _cw4 = (_rp_w - 12) // 4
                        _cw3 = (_rp_w - 8) // 3
                        _r_cy = _rby(_roff)
                        _spe_chip(pygame.Rect(_rp_x, _r_cy, _cw4, _row_h), "Background", _sel_layer == "bg", "layer", "bg")
                        _spe_chip(pygame.Rect(_rp_x + _cw4 + 4, _r_cy, _cw4, _row_h), "HP Fill", _sel_layer == "fill", "layer", "fill")
                        _spe_chip(pygame.Rect(_rp_x + 2*(_cw4 + 4), _r_cy, _cw4, _row_h), "Frame", _sel_layer == "frame", "layer", "frame")
                        _spe_chip(pygame.Rect(_rp_x + 3*(_cw4 + 4), _r_cy, _rp_w - 3*(_cw4 + 4), _row_h), "Text", _sel_layer == "text", "layer", "text",
                                  _enabled=bool(modal.get("spe_text_on", False)))
                        _roff += _row_h + 4

                        _lay_sel_ok = _sel_layer in ("bg", "fill", "frame", "text")
                        _lay_locked = bool(modal.get(f"spe_{_sel_layer}_lock", False)) if _lay_sel_ok else False
                        _r_cy = _rby(_roff)
                        _cw2 = (_rp_w - 4) // 2
                        _spe_chip(pygame.Rect(_rp_x, _r_cy, _cw2, _row_h), ("Unlock Layer" if _lay_locked else "Lock Layer") if _lay_sel_ok else "Lock (pick a layer)",
                                  _lay_locked, "lock", None, _enabled=_lay_sel_ok)
                        _spe_chip(pygame.Rect(_rp_x + _cw2 + 4, _r_cy, _rp_w - _cw2 - 4, _row_h), "Reset Position", False, "reset", None, _enabled=_lay_sel_ok)
                        _roff += _row_h + 4

                        _r_cy = _rby(_roff)
                        _dir_lbl_w = 44
                        screen.blit(font_tiny.render("Fill Flow:", True, TEXT_DIM), (_rp_x + 2, _r_cy + 5))
                        _dw = (_rp_w - _dir_lbl_w - 12) // 4
                        for _di2, (_dlbl2, _dval2) in enumerate((("L->R", "left_to_right"), ("R->L", "right_to_left"), ("B->T", "bottom_to_top"), ("T->B", "top_to_bottom"))):
                            _spe_chip(pygame.Rect(_rp_x + _dir_lbl_w + _di2 * (_dw + 4), _r_cy, _dw, _row_h), _dlbl2, _pv_dir == _dval2, "dir", _dval2)
                        _roff += _row_h + 4

                        _r_cy = _rby(_roff)
                        _mode_names = {"auto": "Auto", "tile": "Tile", "stretch": "Stretch", "native": "Native"}
                        _spe_chip(pygame.Rect(_rp_x, _r_cy, _cw3, _row_h), "BG: " + _mode_names.get(str(modal.get("spe_bg_mode", "auto")), "Auto"),
                                  False, "bgmode", None, _enabled=bool(_bg_single_img))
                        _spe_chip(pygame.Rect(_rp_x + _cw3 + 4, _r_cy, _cw3, _row_h), "Frame: " + _mode_names.get(str(modal.get("spe_frame_mode", "auto")), "Auto"),
                                  False, "framemode", None, _enabled=bool(_frame_img_pv))
                        _ftx_on = str(modal.get("spe_fill_tex_mode", "auto")).lower() == "native"
                        _spe_chip(pygame.Rect(_rp_x + 2*(_cw3 + 4), _r_cy, _rp_w - 2*(_cw3 + 4), _row_h), "Fill: " + ("Native" if _ftx_on else "Scaled"),
                                  _ftx_on, "filltex", None, _enabled=bool(_single_fill_img))
                        _roff += _row_h + 4

                        _r_cy = _rby(_roff)
                        _spe_chip(pygame.Rect(_rp_x, _r_cy, _cw3, _row_h), "BG Backing", bool(modal.get("spe_show_bg_ph", True)), "phbg")
                        _spe_chip(pygame.Rect(_rp_x + _cw3 + 4, _r_cy, _cw3, _row_h), "Fill Color", bool(modal.get("spe_show_fill_ph", True)), "phfill")
                        _spe_chip(pygame.Rect(_rp_x + 2*(_cw3 + 4), _r_cy, _rp_w - 2*(_cw3 + 4), _row_h), "Outline", bool(modal.get("spe_show_frame_outline_ph", True)), "phoutline")
                        _roff += _row_h + 2
                        screen.blit(font_tiny.render(truncate_text_to_width(font_tiny, "click selects - click stack again to cycle - drag gizmos - wheel zoom - RMB/MMB pan", _rp_w), True, TEXT_FAINT), (_rp_x + 2, _rby(_roff)))

                        # ---------- LEFT COLUMN: scrollable settings ----------
                        _clip_prev = screen.get_clip()
                        screen.set_clip(body_rect)

                        def _spe_by(o):
                            return body_rect.y - modal_scroll + o

                        off = 0.0

                        pw = _left_w  # every section below sizes itself to the left column

                        # ===== 2. test drivers (44px slider pitch keeps labels clear) =====
                        _sl_gap = 14
                        _sl_w = (pw - _sl_gap) // 2
                        _s1 = make_slider("Preview Width (smart stretch)", px, _spe_by(off + 22), _sl_w, 50, 600,
                            lambda: float(modal.get("spe_w", 300)),
                            lambda v: modal.__setitem__("spe_w", int(v)),
                            lambda v: f"{int(v)}px")
                        draw_slider(_s1, mouse_pos); modal_sliders.append(_s1)
                        _s2 = make_slider("Fill Tester (health / progress)", px + _sl_w + _sl_gap, _spe_by(off + 22), _sl_w, 0.0, 1.0,
                            lambda: float(modal.get("spe_prog", 0.75)),
                            lambda v: modal.__setitem__("spe_prog", round(v, 2)),
                            lambda v: f"{int(v*100)}%")
                        draw_slider(_s2, mouse_pos); modal_sliders.append(_s2)
                        # ── HP test row: drives the HP-reactive aesthetics ──
                        _s3 = make_slider("Test Max HP  (what ABS rules compare against)", px, _spe_by(off + 48), pw, 1, 1000,
                            lambda: float(modal.get("spe_test_max_hp", 100)),
                            lambda v: modal.__setitem__("spe_test_max_hp", max(1, int(v))),
                            lambda v: f"{int(v)} hp")
                        draw_slider(_s3, mouse_pos); modal_sliders.append(_s3)
                        _hp_row_y = off + 68
                        _hp_txt = font_md.render(f"HP: {int(round(_pv_hp))} / {int(_spe_max_hp)}   ({int(_prog_val*100)}%)",
                                                 True, (0, 235, 255) if _prog_val > 0.001 else (255, 120, 90))
                        screen.blit(_hp_txt, (px + 12, _spe_by(_hp_row_y)))
                        _tchips = []
                        _tch_x = px + 12 + _hp_txt.get_width() + 18
                        for _tci, _tcf in enumerate((0.0, 0.25, 0.5, 0.75, 1.0)):
                            _tcr = pygame.Rect(_tch_x + _tci * 50, _spe_by(_hp_row_y), 44, 22)
                            _tchov = _tcr.collidepoint(mouse_pos)
                            _tcon = abs(_prog_val - _tcf) < 0.001
                            ui_draw_rect(screen, ACCENT if _tcon else ((52, 54, 72) if _tchov else FIELD_FOCUS), _tcr, border_radius=5)
                            ui_draw_rect(screen, ACCENT if _tcon else PANEL_BORDER, _tcr, width=2 if _tcon else 1, border_radius=5)
                            _tcl = font_tiny.render(f"{int(_tcf*100)}%", True, (10, 10, 14) if _tcon else TEXT_MAIN)
                            screen.blit(_tcl, (_tcr.centerx - _tcl.get_width()//2, _tcr.centery - _tcl.get_height()//2))
                            _tchips.append((_tcr, "test_chip", None, _tcf))
