                                        draw_slider(_sp_s, mouse_pos); modal_sliders.append(_sp_s)
                                        _styl = str(_br.get("style", "fade"))
                                        _fade_r = pygame.Rect(px + 12 + (pw - 36) // 2 + 12, _spe_by(off + (_ly - _cy_base) + 16), 78, 26)
                                        _hard_r = pygame.Rect(_fade_r.right + 8, _spe_by(off + (_ly - _cy_base) + 16), 78, 26)
