                        screen.blit(font_tiny.render(f"Force Pixel-Perfect Snapping to Tile Width{_inc_txt}: {'ENABLED' if _snap_on else 'DISABLED'}", True, (10, 10, 14) if _snap_on else TEXT_DIM), (_snap_r.x + 8, _snap_r.y + 6))
                        modal["_spe_snap_rect"] = _snap_r
                        off += 32

