                        screen.blit(font_tiny.render(f"Discrete / Segmented HP Fill (removes whole tiles): {'ENABLED' if _discrete_on else 'DISABLED (Smooth)'}", True, (10, 10, 14) if _discrete_on else TEXT_DIM), (_disc_r.x + 8, _disc_r.y + 6))
                        modal["_spe_discrete_rect"] = _disc_r
                        off += 38

                        # ══ FILL TINT BY % ══════════════════════════════════
                        # Recolor / darken the fill artwork as HP crosses stops
