                            screen.blit(font_tiny.render(f"Tint Fill By Percentage: {'ENABLED' if _tint_on else 'DISABLED'}  (recolors the fill texture as the bar drains)", True, (10, 10, 14) if _tint_on else TEXT_DIM), (_tint_r.x + 8, _tint_r.y + 6))
                            modal["_spe_tint_toggle_rect"] = _tint_r
