                    hy = panel_rect.y + 20
                    screen.blit(title, (px, hy)); hy+=32
                    pygame.draw.line(screen, DIVIDER, (px, hy), (px+pw, hy),1); hy+=10
                    footer_h=68
                    footer_top = panel_rect.bottom - footer_h
