                    draw_button(cancel_btn, "Cancel", cancel_btn.collidepoint(mouse_pos), danger=True)
                    modal["_confirm_btn"]=confirm_btn
                    modal["_cancel_btn"]=cancel_btn
                    body_rect = pygame.Rect(px, hy, pw, footer_top-14-hy)
                    modal_body_rect=body_rect
                    clip_prev=screen.get_clip()
                    screen.set_clip(body_rect)
                    def by(local_off):
                        return body_rect.y - modal_scroll + local_off
                    off=0.0
                    field_rects={}
                    modal["_swatches"]=[]

                    draw_section_label("BUTTON", (px, by(off))); off+=18
