                ui_draw_rect(screen,GOLD,pygame.Rect(panel.x,panel.y,4,panel.height),border_top_left_radius=8,border_bottom_left_radius=8);main_ic=get_icon_fs("save",18,GOLD)
                if main_ic:screen.blit(main_ic,(panel.x+14,panel.y+13))
