                actions_x=panel.x+190 if not compact else panel.x+12;actions_y=panel.y+13 if not compact else panel.y+56;gap=5;available=panel.right-actions_x-12;save_w=94;dont_w=108;step_w=24;duration_w=52;snooze_w=max(70,available-save_w-dont_w-step_w*2-duration_w-gap*5)
                save_r=pygame.Rect(actions_x,actions_y,save_w,32);dont_r=pygame.Rect(save_r.right+gap,actions_y,dont_w,32);minus=pygame.Rect(dont_r.right+gap,actions_y,step_w,32);duration=pygame.Rect(minus.right+gap,actions_y,duration_w,32);plus=pygame.Rect(duration.right+gap,actions_y,step_w,32);snooze=pygame.Rect(plus.right+gap,actions_y,snooze_w,32)
                draw_button(save_r,"   Save",save_r.collidepoint(mouse_pos),variant="save",small=True);draw_button(dont_r,"   Don't Save",dont_r.collidepoint(mouse_pos),muted=True,small=True);draw_button(minus,"−",minus.collidepoint(mouse_pos),small=True,muted=True);draw_button(plus,"+",plus.collidepoint(mouse_pos),small=True,muted=True)
